static bool PopContextMenuForMouseDownIfNeeded(NSView *view, NSEvent *event)
{
    if (!view || !event) return false;
    const bool contextClick = [event type] == NSEventTypeRightMouseDown ||
        [event buttonNumber] == 1 ||
        (([event modifierFlags] & NSEventModifierFlagControl) != 0);
    if (!contextClick) return false;
    NSMenu *menu = [view menuForEvent:event];
    if (menu) [NSMenu popUpContextMenu:menu withEvent:event forView:view];
    return true;
}

typedef void (^LinkEDASearchSelectionHandler)(NSArray<NSString *> *values);
typedef NSMenu * (^LinkEDASearchContextMenuHandler)(NSString *value);

@interface LinkEDASearchableAddController : NSWindowController
    <NSWindowDelegate, NSTableViewDataSource, NSTableViewDelegate,
     NSSearchFieldDelegate, NSMenuDelegate>
@property(nonatomic, retain) NSArray<NSString *> *choices;
@property(nonatomic, retain) NSMutableArray<NSString *> *filtered;
@property(nonatomic, retain) NSSearchField *searchField;
@property(nonatomic, retain) NSTableView *tableView;
@property(nonatomic, retain) NSTextField *emptyLabel;
@property(nonatomic, retain) NSButton *addButton;
@property(nonatomic, copy) LinkEDASearchSelectionHandler selectionHandler;
@property(nonatomic, copy) LinkEDASearchContextMenuHandler contextMenuHandler;
@property(nonatomic, retain) NSMenu *contextMenu;
@property(nonatomic, assign) NSWindow *ownerWindow;
- (instancetype)initWithOwner:(NSWindow *)owner title:(NSString *)title
                       choices:(NSArray<NSString *> *)choices
                       handler:(LinkEDASearchSelectionHandler)handler
                   contextMenu:(LinkEDASearchContextMenuHandler)contextMenu;
- (void)presentRelativeToView:(NSView *)view;
- (void)rebuild;
- (void)addSelected:(id)sender;
@end

static NSMutableSet<LinkEDASearchableAddController *> *g_searchableAddControllers;

@implementation LinkEDASearchableAddController
- (instancetype)initWithOwner:(NSWindow *)owner title:(NSString *)title
                       choices:(NSArray<NSString *> *)choices
                       handler:(LinkEDASearchSelectionHandler)handler
                   contextMenu:(LinkEDASearchContextMenuHandler)contextMenu
{
    NSPanel *panel = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, 370, 365)
        styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                   NSWindowStyleMaskUtilityWindow)
        backing:NSBackingStoreBuffered defer:NO];
    self = [super initWithWindow:panel];
    [panel release];
    if (self) {
        self.ownerWindow = owner;
        self.choices = [[NSOrderedSet orderedSetWithArray:choices ?: @[]] array];
        self.filtered = [NSMutableArray array];
        self.selectionHandler = handler;
        self.contextMenuHandler = contextMenu;
        panel.title = title ?: @"Add variables";
        panel.releasedWhenClosed = NO;
        panel.hidesOnDeactivate = NO;
        panel.delegate = self;
        NSView *content = panel.contentView;
        self.searchField = [[[NSSearchField alloc] initWithFrame:
            NSMakeRect(14, 321, 342, 28)] autorelease];
        self.searchField.placeholderString = @"Search variables or terms";
        self.searchField.sendsSearchStringImmediately = YES;
        self.searchField.delegate = self;
        [content addSubview:self.searchField];
        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(14, 50, 342, 263)];
        scroll.hasVerticalScroller = YES; scroll.borderType = NSBezelBorder;
        self.tableView = [[[NSTableView alloc] initWithFrame:scroll.bounds] autorelease];
        NSTableColumn *column = [[NSTableColumn alloc] initWithIdentifier:@"SearchableAddChoice"];
        column.width = 318; [self.tableView addTableColumn:column];
        [column release];
        self.tableView.headerView = nil; self.tableView.rowHeight = 25;
        self.tableView.allowsEmptySelection = YES;
        self.tableView.allowsMultipleSelection = YES;
        self.tableView.allowsTypeSelect = YES;
        self.tableView.dataSource = self; self.tableView.delegate = self;
        self.tableView.target = self; self.tableView.doubleAction = @selector(addSelected:);
        if (self.contextMenuHandler) {
            self.contextMenu = [[[NSMenu alloc] initWithTitle:@"Term actions"] autorelease];
            self.contextMenu.delegate = self;
            self.tableView.menu = self.contextMenu;
        }
        scroll.documentView = self.tableView; [content addSubview:scroll]; [scroll release];
        self.emptyLabel = [[[NSTextField alloc] initWithFrame:
            NSMakeRect(18, 15, 205, 20)] autorelease];
        self.emptyLabel.bezeled = NO; self.emptyLabel.drawsBackground = NO;
        self.emptyLabel.editable = NO; self.emptyLabel.selectable = NO;
        self.emptyLabel.font = [NSFont systemFontOfSize:11];
        self.emptyLabel.textColor = NSColor.secondaryLabelColor;
        self.emptyLabel.stringValue = @"Shift-click: range · Command-click: individual";
        [content addSubview:self.emptyLabel];
        self.addButton = [[[NSButton alloc] initWithFrame:
            NSMakeRect(238, 9, 118, 30)] autorelease];
        self.addButton.title = @"Add selected";
        self.addButton.bezelStyle = NSBezelStyleRounded;
        self.addButton.target = self; self.addButton.action = @selector(addSelected:);
        [content addSubview:self.addButton];
        [self rebuild];
    }
    return self;
}
- (void)dealloc
{
    self.tableView.delegate = nil; self.tableView.dataSource = nil;
    self.window.delegate = nil;
    [_choices release]; [_filtered release]; [_searchField release];
    [_tableView release]; [_emptyLabel release]; [_addButton release];
    [_selectionHandler release]; [_contextMenuHandler release]; [_contextMenu release];
    [super dealloc];
}
- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{ (void)tableView; return (NSInteger)self.filtered.count; }
- (NSView *)tableView:(NSTableView *)tableView viewForTableColumn:(NSTableColumn *)column row:(NSInteger)row
{
    (void)column; NSString *identifier = @"SearchableAddCell";
    NSTableCellView *cell = [tableView makeViewWithIdentifier:identifier owner:self];
    if (!cell) {
        cell = [[[NSTableCellView alloc] initWithFrame:
            NSMakeRect(0, 0, 310, 25)] autorelease];
        cell.identifier = identifier;
        NSTextField *label = [[NSTextField alloc] initWithFrame:NSMakeRect(7, 3, 296, 19)];
        label.bezeled = NO; label.drawsBackground = NO; label.editable = NO;
        label.selectable = NO; label.font = [NSFont systemFontOfSize:12];
        label.autoresizingMask = NSViewWidthSizable;
        cell.textField = label; [cell addSubview:label];
        [label release];
    }
    cell.textField.stringValue = row >= 0 && row < (NSInteger)self.filtered.count
        ? self.filtered[(NSUInteger)row] : @"";
    return cell;
}
- (void)controlTextDidChange:(NSNotification *)notification
{ if (notification.object == self.searchField) [self rebuild]; }
- (void)tableViewSelectionDidChange:(NSNotification *)notification
{
    if (notification.object != self.tableView) return;
    NSUInteger count = self.tableView.selectedRowIndexes.count;
    self.addButton.enabled = count > 0;
    self.addButton.title = count > 1
        ? [NSString stringWithFormat:@"Add %lu", (unsigned long)count] : @"Add selected";
}
- (void)menuNeedsUpdate:(NSMenu *)menu
{
    [menu removeAllItems];
    NSInteger row = self.tableView.clickedRow;
    if (row < 0) row = self.tableView.selectedRow;
    if (row < 0 || row >= (NSInteger)self.filtered.count || !self.contextMenuHandler)
        return;
    [self.tableView selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row]
                byExtendingSelection:NO];
    NSMenu *source = self.contextMenuHandler(self.filtered[(NSUInteger)row]);
    for (NSMenuItem *item in source.itemArray)
        [menu addItem:[[item copy] autorelease]];
}
- (void)rebuild
{
    NSString *query = self.searchField.stringValue ?: @"";
    [self.filtered removeAllObjects];
    for (NSString *choice in self.choices)
        if (query.length == 0 || [choice rangeOfString:query
            options:NSCaseInsensitiveSearch].location != NSNotFound)
            [self.filtered addObject:choice];
    [self.tableView reloadData];
    self.emptyLabel.stringValue = self.filtered.count == 0
        ? @"No variables or terms available"
        : @"Shift-click: range · Command-click: individual";
    self.addButton.enabled = self.filtered.count > 0;
    if (self.filtered.count > 0)
        [self.tableView selectRowIndexes:[NSIndexSet indexSetWithIndex:0]
                    byExtendingSelection:NO];
}
- (void)addSelected:(id)sender
{
    (void)sender; NSIndexSet *rows = self.tableView.selectedRowIndexes;
    if (rows.count == 0 && self.filtered.count > 0)
        rows = [NSIndexSet indexSetWithIndex:0];
    NSMutableArray<NSString *> *values = [NSMutableArray array];
    [rows enumerateIndexesUsingBlock:^(NSUInteger index, BOOL *stop) {
        (void)stop; if (index < self.filtered.count) [values addObject:self.filtered[index]];
    }];
    if (values.count == 0) return;
    LinkEDASearchSelectionHandler handler = [self.selectionHandler copy];
    [self close];
    if (handler) handler(values);
    [handler release];
}
- (void)presentRelativeToView:(NSView *)view
{
    self.searchField.stringValue = @""; [self rebuild];
    NSRect anchor = view ? [view convertRect:view.bounds toView:nil] : NSZeroRect;
    if (view.window) anchor = [view.window convertRectToScreen:anchor];
    NSRect frame = self.window.frame;
    frame.origin = NSMakePoint(NSMinX(anchor), NSMinY(anchor) - NSHeight(frame) - 6.0);
    NSScreen *screen = self.ownerWindow.screen ?: NSScreen.mainScreen;
    if (screen) {
        NSRect visible = screen.visibleFrame;
        frame.origin.x = std::clamp(frame.origin.x, NSMinX(visible),
            std::max(NSMinX(visible), NSMaxX(visible) - NSWidth(frame)));
        frame.origin.y = std::clamp(frame.origin.y, NSMinY(visible),
            std::max(NSMinY(visible), NSMaxY(visible) - NSHeight(frame)));
    }
    [self.window setFrame:frame display:NO];
    if (self.ownerWindow) [self.ownerWindow addChildWindow:self.window ordered:NSWindowAbove];
    [self.window makeKeyAndOrderFront:nil];
    [self.window makeFirstResponder:self.searchField];
}
- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    if (self.window.parentWindow) [self.window.parentWindow removeChildWindow:self.window];
    dispatch_async(dispatch_get_main_queue(), ^{ [g_searchableAddControllers removeObject:self]; });
}
@end

static void ShowSearchableAddSelector(NSWindow *owner, NSView *anchor,
    NSString *title, const std::vector<std::string> &choices,
    LinkEDASearchSelectionHandler handler,
    LinkEDASearchContextMenuHandler contextMenu = nil)
{
    NSMutableArray<NSString *> *labels = [NSMutableArray arrayWithCapacity:choices.size()];
    for (const std::string &choice : choices) if (!choice.empty())
        [labels addObject:[NSString stringWithUTF8String:choice.c_str()]];
    if (!g_searchableAddControllers)
        g_searchableAddControllers = [[NSMutableSet alloc] init];
    LinkEDASearchableAddController *controller = [[LinkEDASearchableAddController alloc]
        initWithOwner:owner title:title choices:labels handler:handler contextMenu:contextMenu];
    [g_searchableAddControllers addObject:controller];
    [controller presentRelativeToView:anchor];
    [controller release];
}

@interface LinkEDASecondaryActionButton : NSButton
@property(nonatomic, copy) void (^secondaryAction)(void);
@end

@implementation LinkEDASecondaryActionButton
- (void)mouseDown:(NSEvent *)event
{
    if ((event.modifierFlags & NSEventModifierFlagControl) != 0 && self.secondaryAction) {
        self.secondaryAction(); return;
    }
    [super mouseDown:event];
}
- (void)rightMouseDown:(NSEvent *)event
{ (void)event; if (self.secondaryAction) self.secondaryAction(); else [super rightMouseDown:event]; }
- (void)dealloc
{ [_secondaryAction release]; [super dealloc]; }
@end

