static void CaptureActiveAnalysisScopeUnlocked(const std::string &group,
                                               rlispstat::core::AnalysisScope &scope,
                                               bool &captured)
{
    scope = MacCommandDispatcher().applicationState().activeAnalysisScope(group);
    captured = true;
}

static std::vector<int> RowsForCapturedAnalysisScope(const rlispstat::core::AnalysisScope &scope,
                                                     bool captured)
{
    if (!captured || scope.kind == rlispstat::core::AnalysisScopeKind::AllObservations) return {};
    return rlispstat::core::ResolveAnalysisScopeRowIds(scope, scope.totalDatasetRows);
}

static std::string OriginalRowsAnalysisModelSpec(
    const rlispstat::core::AnalysisScope &scope,
    bool captured)
{
    std::vector<std::string> rows;
    for (const int row : RowsForCapturedAnalysisScope(scope, captured)) {
        rows.push_back(std::to_string(row));
    }
    return JoinStrings(rows, "\t");
}

static std::string ScopeForCapturedAnalysisScope(const rlispstat::core::AnalysisScope &scope,
                                                 bool captured,
                                                 const std::string &fallback = "all")
{
    if (!captured) return fallback;
    return scope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds ? "selected" : "all";
}

static std::vector<rlispstat::core::AnalysisScopeChoice>
AnalysisScopeChoicesForGroup(const std::string &group, bool includeUnselected)
{
    std::size_t selectedCount = 0;
    std::vector<rlispstat::core::SavedSelection> saved;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto selected = g_groupSelections.find(group);
        if (selected != g_groupSelections.end()) selectedCount = selected->second.size();
        saved = MacCommandDispatcher().applicationState().savedSelections(group);
    }
    return rlispstat::core::BuildAnalysisScopeChoices(
        selectedCount, saved, includeUnselected);
}

static NSHashTable *g_scopeSummaryViews = nil;
@interface GlobalAnalysisScopeSummary : NSPopUpButton
@property(nonatomic, copy) NSString *scopeDataset;
@property(nonatomic, copy) NSString *computedScopeText;
- (void)refreshGlobalScopeText;
+ (void)refreshRegisteredScopeViews;
@end
@implementation GlobalAnalysisScopeSummary
- (void)setEnabled:(BOOL)value { (void)value; [super setEnabled:NO]; }
- (BOOL)acceptsFirstResponder { return NO; }
- (void)viewDidMoveToWindow {
    [super viewDidMoveToWindow];
    if (!g_scopeSummaryViews) {
        g_scopeSummaryViews = [[NSHashTable weakObjectsHashTable] retain];
        [NSTimer scheduledTimerWithTimeInterval:0.5 target:[GlobalAnalysisScopeSummary class]
            selector:@selector(refreshRegisteredScopeViews) userInfo:nil repeats:YES];
    }
    if ([self window]) [g_scopeSummaryViews addObject:self];
    else [g_scopeSummaryViews removeObject:self];
}
+ (void)refreshRegisteredScopeViews {
    for (GlobalAnalysisScopeSummary *view in [g_scopeSummaryViews allObjects]) [view refreshGlobalScopeText];
}
- (void)refreshGlobalScopeText {
    if (![self.scopeDataset length]) return;
    const auto scope = MacCommandDispatcher().applicationState().activeAnalysisScope([self.scopeDataset UTF8String]);
    const std::string label=rlispstat::core::AnalysisScopeCompactSummary(scope,scope.totalDatasetRows);
    if ([self numberOfItems]) [[self itemAtIndex:0] setTitle:[NSString stringWithUTF8String:label.c_str()]];
    [[self cell] setLineBreakMode:NSLineBreakByTruncatingTail];
    std::string help="Global analysis scope: "+rlispstat::core::AnalysisScopeSummary(scope,scope.totalDatasetRows,false)+
        "\nChange it in the central Analysis Scope menu. Recalculating uses the current global scope.";
    if([self.computedScopeText length])help+="\n"+std::string([self.computedScopeText UTF8String]);
    [self setToolTip:[NSString stringWithUTF8String:help.c_str()]];

}
- (void)dealloc { [_scopeDataset release]; [_computedScopeText release]; [super dealloc]; }
@end

static void PopulateAnalysisScopePopup(
    NSPopUpButton *popup,
    const std::string &group,
    const std::string &fallbackScope,
    const rlispstat::core::AnalysisScope &capturedScope,
    bool captured,
    bool includeUnselected)
{
    if (!popup) return;
    if ([popup isKindOfClass:[GlobalAnalysisScopeSummary class]])
        [(GlobalAnalysisScopeSummary *)popup setScopeDataset:[NSString stringWithUTF8String:group.c_str()]];
    (void)fallbackScope; (void)includeUnselected;
    const auto current = MacCommandDispatcher().applicationState().activeAnalysisScope(group);
    const auto label = rlispstat::core::AnalysisScopeSummary(current, current.totalDatasetRows, false);
    [popup removeAllItems];
    [popup addItemWithTitle:[NSString stringWithUTF8String:label.c_str()]];
    [[popup lastItem] setRepresentedObject:current.kind == rlispstat::core::AnalysisScopeKind::AllObservations ? @"all" : @"selected"];
    [popup setEnabled:NO];
    [popup setBordered:NO];
    [[popup cell] setArrowPosition:NSPopUpNoArrow];
    std::string help = "Global analysis scope: " + label +
        "\nChange it in the central Analysis Scope menu. Recalculating uses the current global scope.";
    if (captured) help += "\n" + rlispstat::core::AnalysisScopeWindowSummary(capturedScope, capturedScope.totalDatasetRows);
    [popup setToolTip:[NSString stringWithUTF8String:help.c_str()]];
    if ([popup isKindOfClass:[GlobalAnalysisScopeSummary class]]) {
        auto *summary=(GlobalAnalysisScopeSummary *)popup;
        [summary setComputedScopeText:captured ? [NSString stringWithUTF8String:rlispstat::core::AnalysisScopeWindowSummary(capturedScope,capturedScope.totalDatasetRows).c_str()] : nil];
        [summary refreshGlobalScopeText];
    }
}

static std::string SelectedAnalysisScopeChoice(NSPopUpButton *popup)
{
    if (!popup || ![popup selectedItem]) return "all";
    id represented = [[popup selectedItem] representedObject];
    return [represented isKindOfClass:[NSString class]]
        ? std::string([(NSString *)represented UTF8String]) : "all";
}

