// Model-local Selected/Unselected scopes follow the live linked selection
// unless the analysis was opened from an explicit immutable global subset.
// Callers hold g_mutex while taking this snapshot.
static std::vector<int> RowsForModelSpecificationUnlocked(
    const std::string &group,
    const rlispstat::core::ModelSpecification &specification)
{
    std::vector<int> selectedRows;
    const auto selected = g_groupSelections.find(group);
    if (selected != g_groupSelections.end()) {
        selectedRows.assign(selected->second.begin(), selected->second.end());
    }
    return rlispstat::core::ModelSpecificationSelectionRows(
        specification, selectedRows);
}

static std::string ScopeForModelSpecification(
    const rlispstat::core::ModelSpecification &specification)
{
    const std::string scope =
        rlispstat::core::ModelSpecificationFitScope(specification);
    return scope == "compare_selected_all" ? "all" : scope;
}

static void ComputeScatterRangesIncludingAllImputations(
    PlotModel *plot, const DataFrameModel &df);

static void ApplyCapturedAnalysisScopeToPlotUnlocked(PlotModel &model)
{
    const DataFrameModel *dataset = MacCommandDispatcher().applicationState().datasets().find(model.group);
    if (!dataset) return;
    const std::size_t totalRows = static_cast<std::size_t>(std::max(0, dataset->rows));
    rlispstat::core::ApplyAnalysisScopeToPlot(model, model.dataScope, totalRows);
    if (model.kind == "scatter" && !rlispstat::core::PlotIsDerivedAnalysisView(model))
        ComputeScatterRangesIncludingAllImputations(&model, *dataset);
}

static bool AttachPlotModelUnlocked(PlotModel *model)
{
    if (!model) return false;
    const DataFrameModel *dataset = MacCommandDispatcher().applicationState().datasets().find(model->group);
    const std::size_t totalRows = dataset
        ? static_cast<std::size_t>(std::max(0, dataset->rows)) : 0;
    if (model->isDatasetSeed) {
        model->dataScope = rlispstat::core::AllObservationsAnalysisScope(model->group, totalRows);
        // Copies made from the seed should capture the then-active scope.
        model->dataScopeCaptured = false;
    } else {
        if (!model->dataScopeCaptured) {
            model->dataScope = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
            model->dataScopeCaptured = true;
        }
        // A derived workflow may already have frozen its source analysis
        // scope before registration.  Captured must not mean "already
        // filtered": always enforce that immutable scope on the row-backed
        // geometry at the single attachment boundary.
        ApplyCapturedAnalysisScopeToPlotUnlocked(*model);
    }
    const bool accepted = MacPlotCoordinator().attachPlot(*model).accepted;
    if (accepted && !model->isDatasetSeed) {
        model->rExportTheme = MacCommandDispatcher().plotTheme();
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
    }
    return accepted;
}

