static bool QueueDimensionalityScoreSaveMainRTask(
    const MainRDimensionalityScoreSaveTask &task)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const std::string source = task.sourceKind + "|" + task.analysisId;
        if (g_pendingDimensionalityScoreSaveSources.count(source)) return false;
        if (!g_pendingDimensionalityScoreSaveRequests.insert(task.requestId).second)
            return false;
        g_pendingDimensionalityScoreSaveSources.insert(source);
        g_pendingDimensionalityScoreSaveTasks.push_back(task);
    }
    NotifyMainRTaskAvailable();
    return true;
}

