static NSColor *ColorFromPlotRGBA(const rlispstat::core::PlotRGBA &color)
{
    return [NSColor colorWithCalibratedRed:(CGFloat)color.r
                                     green:(CGFloat)color.g
                                      blue:(CGFloat)color.b
                                     alpha:(CGFloat)color.a];
}

// Resolve transparency against the panel once, not against earlier cases.
static NSColor *ScatterMarkColor(NSColor *color, const PlotThemeStyle &theme, bool shadeOverlap)
{
    if (shadeOverlap) return color;
    NSColor *foreground = [color colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    NSColor *panel = [theme.panel colorUsingColorSpace:[NSColorSpace genericRGBColorSpace]];
    return ColorFromPlotRGBA(rlispstat::core::PlotMarkColor(
        {[foreground redComponent], [foreground greenComponent], [foreground blueComponent], [foreground alphaComponent]},
        {[panel redComponent], [panel greenComponent], [panel blueComponent], 1.0}, false));
}

static PlotThemeStyle PlotThemeStyleFromSpec(const rlispstat::core::PlotThemeStyleSpec &spec)
{
    return {
        ColorFromPlotRGBA(spec.background),
        ColorFromPlotRGBA(spec.panel),
        ColorFromPlotRGBA(spec.minorGrid),
        ColorFromPlotRGBA(spec.majorGrid),
        ColorFromPlotRGBA(spec.axis),
        ColorFromPlotRGBA(spec.text),
        ColorFromPlotRGBA(spec.mutedText),
        ColorFromPlotRGBA(spec.geomFill),
        ColorFromPlotRGBA(spec.geomStroke),
        ColorFromPlotRGBA(spec.accent),
        ColorFromPlotRGBA(spec.accent2),
        ColorFromPlotRGBA(spec.markFill),
        ColorFromPlotRGBA(spec.markStroke),
        ColorFromPlotRGBA(spec.selectedMarkFill),
        ColorFromPlotRGBA(spec.selectedMarkStroke),
        ColorFromPlotRGBA(spec.auxiliary),
        ColorFromPlotRGBA(spec.reference),
        ColorFromPlotRGBA(spec.smooth),
        spec.showMinorGrid,
        spec.showPanelBorder,
        spec.coordinatedMarks,
        spec.hollowUnselectedMarks,
        spec.crossUnselectedMarks,
        spec.squareSelectedMarks,
        spec.selectedMarkScale,
        spec.selectedMarkStrokeWidth,
        spec.showAxisTickMarks
    };
}

static PlotThemeStyle CurrentPlotThemeStyle()
{
    extern thread_local std::optional<std::string> g_plotThemeNameOverride;
    return PlotThemeStyleFromSpec(
        rlispstat::core::PlotThemeStyleForName(
            g_plotThemeNameOverride.value_or(MacCommandDispatcher().plotTheme())));
}

