static NSColor *BarplotAutomaticColor(size_t index, CGFloat alpha = 1.0)
{
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    if (theme.coordinatedMarks) {
        NSColor *base = index % 3 == 0 ? theme.geomFill : (index % 3 == 1 ? theme.auxiliary : theme.markFill);
        return [base colorWithAlphaComponent:(index % 3 == 1 ? alpha * 0.62 : alpha)];
    }
    return [NSColor colorWithCalibratedWhite:1.0 alpha:alpha];
}

