static NSColor *BarplotSegmentFillColor(const std::string &colorKey, size_t index, CGFloat alpha = 1.0)
{
    if (colorKey.empty()) {
        return BarplotAutomaticColor(index, alpha);
    }
    if (BarplotLevelIsMissing(colorKey)) {
        return [NSColor colorWithCalibratedWhite:0.78 alpha:alpha];
    }
    return ColorForNameOrHex(colorKey, alpha);
}

