static NSBezierPath *PathForCorePoints(
    const std::vector<rlispstat::core::Point> &points,
    BOOL closePath);

static void DrawScatterplotRenderPlanInPanel(
    const rlispstat::core::ScatterplotRenderPlan &plan,
    const NSRect plotRect,
    const PlotThemeStyle &theme,
    double pointSizeScale)
{
    pointSizeScale = rlispstat::core::ClampPointSizeScale(pointSizeScale);
    NSGraphicsContext *context = [NSGraphicsContext currentContext];
    [context saveGraphicsState];
    [[NSBezierPath bezierPathWithRect:plotRect] addClip];
    for (const rlispstat::core::ScatterplotSmoothCurveDrawItem &item : plan.smoothCurves) {
        if (item.confidencePolygon.size() < 3) continue;
        NSColor *color = item.colorName.empty()
            ? theme.smooth
            : ColorForName(item.colorName, 1.0);
        [[color colorWithAlphaComponent:(CGFloat)item.confidenceAlpha] setFill];
        [PathForCorePoints(item.confidencePolygon, YES) fill];
    }
    for (const rlispstat::core::ScatterplotOverlayDrawItem &item : plan.overlayLines) {
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:rlispstat::platform::macos::ToNSPoint(item.start)];
        [line lineToPoint:rlispstat::platform::macos::ToNSPoint(item.end)];
        if (item.dashed) { CGFloat dash[] = {7.0, 4.0}; [line setLineDash:dash count:2 phase:0.0]; }
        [line setLineWidth:(CGFloat)item.lineWidth];
        [(item.useDefaultDarkColor ? theme.smooth : ColorForName(item.colorName, (CGFloat)item.alpha)) setStroke];
        [line stroke];
    }
    for (const rlispstat::core::ScatterplotSmoothCurveDrawItem &item : plan.smoothCurves) {
        if (item.points.size() < 2) continue;
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:rlispstat::platform::macos::ToNSPoint(item.points.front())];
        for (std::size_t index = 1; index < item.points.size(); ++index) {
            [line lineToPoint:rlispstat::platform::macos::ToNSPoint(item.points[index])];
        }
        if (item.dashed) { CGFloat dash[] = {8.0, 5.0}; [line setLineDash:dash count:2 phase:0.0]; }
        [line setLineWidth:(CGFloat)item.lineWidth];
        [(item.colorName.empty() ? theme.smooth : ColorForName(item.colorName, (CGFloat)item.alpha)) setStroke];
        [line stroke];
    }
    NSDictionary *labelAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    for (const rlispstat::core::ScatterplotPointDrawItem &item : plan.points) {
        if (item.hasImputationGlyph) continue;
        const NSPoint point = rlispstat::platform::macos::ToNSPoint(item.point);
        CGFloat radius = (CGFloat)(item.radius * pointSizeScale);
        if (item.selected) DrawPointSelectionRing(theme, point, radius,
            item.hasExplicitColor ? ColorForName(item.colorName, 1.0) : theme.selectedMarkFill);
        NSColor *fill = nil;
        if (theme.coordinatedMarks && !item.hasExplicitColor) {
            fill = item.selected ? theme.selectedMarkFill :
                (theme.hollowUnselectedMarks ? theme.panel : theme.markFill);
        } else {
            fill = ColorForName(item.colorName.empty() ? "black" : item.colorName,
                                (CGFloat)item.fillAlpha);
        }
        if (theme.coordinatedMarks && !item.hasExplicitColor && item.shadeOverlap && !item.selected)
            fill = [fill colorWithAlphaComponent:item.fillAlpha];
        [ScatterMarkColor(fill, theme, item.shadeOverlap) setFill];
        NSBezierPath *mark = PlotThemeMarkPath(theme, point, radius, item.selected);
        [mark fill];
        NSColor *stroke = theme.coordinatedMarks
            ? (item.selected ? theme.selectedMarkStroke :
               (item.hasExplicitColor ? ColorForName(item.colorName, (CGFloat)item.strokeAlpha) : theme.markStroke))
            : ColorForName(item.colorName.empty() ? "black" : item.colorName, (CGFloat)item.strokeAlpha);
        if (theme.coordinatedMarks && item.shadeOverlap && !item.selected)
            stroke = [stroke colorWithAlphaComponent:item.strokeAlpha];
        [ScatterMarkColor(stroke, theme, item.shadeOverlap) setStroke];
        [mark setLineWidth:(theme.coordinatedMarks && item.selected)
            ? (CGFloat)theme.selectedMarkStrokeWidth : (CGFloat)item.strokeWidth];
        [mark stroke];
        if (item.showLabel) {
            NSString *label = ToNSString(item.label);
            NSSize size = [label sizeWithAttributes:labelAttributes];
            CGFloat x = std::min(std::max(point.x + 6.0, NSMinX(plotRect) + 2.0),
                                 NSMaxX(plotRect) - size.width - 6.0);
            CGFloat y = std::min(std::max(point.y - size.height - 4.0, NSMinY(plotRect) + 2.0),
                                 NSMaxY(plotRect) - size.height - 4.0);
            NSRect background = NSMakeRect(x - 3.0, y - 2.0, size.width + 6.0, size.height + 4.0);
            [[theme.panel colorWithAlphaComponent:0.88] setFill];
            [[NSBezierPath bezierPathWithRoundedRect:background xRadius:3.0 yRadius:3.0] fill];
            [label drawAtPoint:NSMakePoint(x, y) withAttributes:labelAttributes];
        }
    }
    [context restoreGraphicsState];
}

static void DrawHistogramRenderPlanInPanel(
    const rlispstat::core::HistogramRenderPlan &plan,
    const NSRect plotRect,
    const PlotThemeStyle &theme,
    const std::string &group,
    const std::set<int> &selection)
{
    NSGraphicsContext *context = [NSGraphicsContext currentContext];
    [context saveGraphicsState];
    [[NSBezierPath bezierPathWithRect:plotRect] addClip];
    for (const rlispstat::core::HistogramBarRenderItem &bar : plan.bars) {
        NSRect rect = NSIntersectionRect(rlispstat::platform::macos::ToNSRect(bar.rect), plotRect);
        if (NSIsEmptyRect(rect)) continue;
        [theme.geomFill setFill]; NSRectFillUsingOperation(rect, NSCompositingOperationSourceOver);
        for (const rlispstat::core::HistogramBarSegment &segment : bar.colorSegments) {
            NSRect segmentRect = NSIntersectionRect(rlispstat::platform::macos::ToNSRect(segment.rect), plotRect);
            NSColor *color = BarplotDataSheetToneColor(
                segment.colorName, false, (CGFloat)segment.alpha);
            [color setFill];
            NSRectFillUsingOperation(segmentRect, NSCompositingOperationSourceOver);
        }
        for (const rlispstat::core::HistogramBarSegment &segment : bar.selectedSegments) {
            NSRect segmentRect = NSIntersectionRect(
                rlispstat::platform::macos::ToNSRect(segment.rect), plotRect);
            NSColor *fill = BarplotDataSheetToneColor(
                segment.colorName, true, (CGFloat)segment.alpha);
            [fill setFill];
            NSRectFillUsingOperation(segmentRect, NSCompositingOperationSourceOver);
        }
        // Keep the bin boundary above selection and explicit case-colour
        // layers. Black outlines describe histogram structure on both native
        // platforms; fills continue to describe colour and linked selection.
        [[NSColor blackColor] setStroke];
        NSBezierPath *binOutline = [NSBezierPath bezierPathWithRect:NSInsetRect(rect, 0.5, 0.5)];
        [binOutline setLineWidth:1.0];
        [binOutline stroke];
        if (bar.showCount && !bar.countLabel.empty()) {
            NSDictionary *attributes = @{
                NSFontAttributeName: [NSFont systemFontOfSize:10],
                NSForegroundColorAttributeName: theme.mutedText
            };
            NSString *label = ToNSString(bar.countLabel);
            NSSize size = [label sizeWithAttributes:attributes];
            [label drawAtPoint:NSMakePoint(NSMidX(rect) - size.width / 2.0,
                                           NSMinY(rect) + 3.0)
                withAttributes:attributes];
        }
    }
    for (const rlispstat::core::HistogramDensityRenderItem &curve : plan.density.curves) {
        if (curve.fillPolygon.size() >= 3) {
            NSBezierPath *fillPath = [NSBezierPath bezierPath];
            [fillPath moveToPoint:rlispstat::platform::macos::ToNSPoint(curve.fillPolygon.front())];
            for (std::size_t index = 1; index < curve.fillPolygon.size(); ++index) {
                [fillPath lineToPoint:rlispstat::platform::macos::ToNSPoint(curve.fillPolygon[index])];
            }
            [fillPath closePath];
            NSColor *fillColor = curve.kind == "color_group"
                ? ColorForName(curve.colorName, 0.34)
                : (curve.kind == "selected"
                    ? (theme.coordinatedMarks ? [theme.selectedMarkFill colorWithAlphaComponent:0.30]
                                              : [NSColor colorWithCalibratedWhite:0.06 alpha:0.30])
                    : (theme.coordinatedMarks ? [theme.markFill colorWithAlphaComponent:0.26]
                                              : [NSColor colorWithCalibratedWhite:0.16 alpha:0.26]));
            [fillColor setFill];
            [fillPath fill];
        }
    }
    for (const rlispstat::core::HistogramDensityOverlapRenderItem &overlap : plan.density.overlaps) {
        [MixedColorForNames(overlap.firstColorName, overlap.secondColorName, 0.52) setFill];
        [PathForCorePoints(overlap.fillPolygon, YES) fill];
    }
    for (const rlispstat::core::HistogramDensityRenderItem &curve : plan.density.curves) {
        if (curve.linePoints.size() >= 2) {
            NSBezierPath *line = PathForCorePoints(curve.linePoints, NO);
            [(theme.coordinatedMarks ? [theme.panel colorWithAlphaComponent:0.82]
                                     : [NSColor colorWithCalibratedWhite:1.0 alpha:0.82]) setStroke];
            [line setLineWidth:5.4]; [line stroke];
            if (curve.kind == "color_group") {
                [ColorForName(curve.colorName, 1.0) setStroke];
                [line setLineWidth:3.0];
            } else if (curve.kind == "selected") {
                [(theme.coordinatedMarks ? theme.selectedMarkFill
                    : [NSColor colorWithCalibratedWhite:0.02 alpha:1.0]) setStroke];
                [line setLineWidth:3.2];
            } else {
                [(theme.coordinatedMarks ? theme.smooth
                    : [NSColor colorWithCalibratedWhite:0.10 alpha:0.96]) setStroke];
                [line setLineWidth:3.0];
            }
            [line stroke];
        }
    }
    for (const rlispstat::core::HistogramRugRenderItem &rug : plan.rugs) {
        const std::string explicitColor = PointColorForRow(group, rug.caseId);
        NSColor *rugColor = !theme.coordinatedMarks || !explicitColor.empty()
            ? ColorForName(explicitColor.empty() ? DisplayColorForPoint(group, rug.caseId) : explicitColor, 0.55)
            : (selection.count(rug.caseId) ? theme.selectedMarkFill : theme.markStroke);
        [rugColor setStroke];
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:rlispstat::platform::macos::ToNSPoint(rug.start)];
        [line lineToPoint:rlispstat::platform::macos::ToNSPoint(rug.end)];
        [line stroke];
    }
    [context restoreGraphicsState];
}

static void DrawBoxplotRenderPlanInPanel(
    const rlispstat::core::TrellisPanelRenderPlan &plan,
    const PlotModel *model,
    const PlotThemeStyle &theme,
    const std::map<int, std::string> &rowColors)
{
    NSRect plotRect = rlispstat::platform::macos::ToNSRect(plan.context.plotRect);
    NSGraphicsContext *context = [NSGraphicsContext currentContext];
    [context saveGraphicsState];
    [[NSBezierPath bezierPathWithRect:plotRect] addClip];
    for (const BoxplotStatsRenderItem &stats : plan.boxplotStats) {
        if (model->boxplotShowWhiskers) {
            NSBezierPath *whiskers = [NSBezierPath bezierPath];
            [whiskers setLineWidth:1.3];
            for (const auto &segment : std::vector<std::pair<rlispstat::core::Point, rlispstat::core::Point>>{
                     {stats.upperWhiskerStart, stats.upperWhiskerEnd}, {stats.lowerWhiskerStart, stats.lowerWhiskerEnd},
                     {stats.upperCapStart, stats.upperCapEnd}, {stats.lowerCapStart, stats.lowerCapEnd}}) {
                [whiskers moveToPoint:rlispstat::platform::macos::ToNSPoint(segment.first)];
                [whiskers lineToPoint:rlispstat::platform::macos::ToNSPoint(segment.second)];
            }
            [theme.geomStroke setStroke]; [whiskers stroke];
        }
        if (model->boxplotShowBox) {
            NSRect box = NSIntersectionRect(rlispstat::platform::macos::ToNSRect(stats.boxRect), plotRect);
            [theme.geomFill setFill]; NSRectFillUsingOperation(box, NSCompositingOperationSourceOver);
            [theme.geomStroke setStroke]; NSFrameRectWithWidth(box, 1.4);
            NSBezierPath *median = [NSBezierPath bezierPath];
            [median moveToPoint:rlispstat::platform::macos::ToNSPoint(stats.medianStart)];
            [median lineToPoint:rlispstat::platform::macos::ToNSPoint(stats.medianEnd)];
            [median setLineWidth:2.0]; [theme.accent setStroke]; [median stroke];
        }
    }
    if (model->boxplotShowPoints) {
        for (const BoxplotPointDrawItem &item : plan.boxplotPoints) {
            NSPoint point = rlispstat::platform::macos::ToNSPoint(item.point);
            const auto color = rowColors.find(item.caseId);
            const bool explicitColor = color != rowColors.end() && !color->second.empty();
            CGFloat radius = 3.2 * (CGFloat)
                rlispstat::core::ClampPointSizeScale(model->pointSizeScale);
            if (item.selected) DrawPointSelectionRing(theme, point, radius,
                explicitColor ? ColorForName(color->second, 1.0) : theme.selectedMarkFill);
            NSBezierPath *mark = PlotThemeMarkPath(theme, point, radius, item.selected);
            [(item.selected ? theme.selectedMarkFill :
                (explicitColor ? ColorForName(color->second, item.dimmed ? 0.24 : 0.72) :
                 (theme.hollowUnselectedMarks ? theme.panel : theme.markFill))) setFill];
            [mark fill];
            [(item.selected ? theme.selectedMarkStroke :
                (explicitColor ? ColorForName(color->second, 0.90) : theme.markStroke)) setStroke];
            [mark setLineWidth:item.selected ? (CGFloat)theme.selectedMarkStrokeWidth : 1.0];
            [mark stroke];
        }
    }
    [context restoreGraphicsState];
}

struct DataSheetRowStyle {
    bool customBackground = false;
    NSColor *background = nil;
    NSColor *textColor = nil;
};

static DataSheetRowStyle DataSheetDisplayStyle(const std::string &name, bool selected, bool hasExplicitColor)
{
    DataSheetRowStyle style;
    style.customBackground = true;
    if (!hasExplicitColor) {
        style.background = selected ? DataSheetSelectedFallbackColor() : WorkbenchSurfaceColor();
        style.textColor = [NSColor blackColor];
        return style;
    }
    auto color = rlispstat::core::FindPaletteColor(name);
    if (!color) {
        style.background = selected ? DataSheetSelectedFallbackColor() : WorkbenchSurfaceColor();
        style.textColor = [NSColor blackColor];
        return style;
    }
    style.background = selected
        ? [NSColor colorWithCalibratedRed:color->selectedR green:color->selectedG blue:color->selectedB alpha:1.0]
        : [NSColor colorWithCalibratedRed:color->lightR green:color->lightG blue:color->lightB alpha:1.0];
    style.textColor = (selected && color->selectedTextWhite) ? [NSColor whiteColor] : [NSColor blackColor];
    return style;
}

static DataSheetRowStyle DataSheetStyleForRow(const std::string &group, int row, bool nativeSelected = false)
{
    DataSheetRowStyle style;
    std::string colorName = PointColorForRow(group, row);
    bool selected = nativeSelected;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(group);
        selected = selected || (it != g_groupSelections.end() && it->second.find(row) != it->second.end());
    }
    style = DataSheetDisplayStyle(colorName, selected, !colorName.empty());
    return style;
}

static NumericVariable *FindVariable(PlotModel *model, const std::string &name)
{
    return model ? rlispstat::core::FindNumericVariable(*model, name) : nullptr;
}

static const VariableMeta *FindVariableMeta(PlotModel *model, const std::string &name)
{
    return model ? rlispstat::core::FindVariableMeta(*model, name) : nullptr;
}

static const DataColumn *FindDataColumnForModel(PlotModel *model, const std::string &name)
{
    if (!model) return nullptr;
    const DataFrameModel *df = FindDataFrameUnlockedConst(model->group);
    return df ? FindDataColumnInDataFrame(*df, name) : nullptr;
}

static bool VariableExistsForModel(PlotModel *model, const std::string &name)
{
    if (!model || name.empty()) return false;
    const DataFrameModel *df = FindDataFrameUnlockedConst(model->group);
    return rlispstat::core::AvailableVariableExists(*model, name, df);
}

static std::vector<std::string> VariableNamesForModel(PlotModel *model)
{
    if (!model) return {};
    const DataFrameModel *df = FindDataFrameUnlockedConst(model->group);
    return rlispstat::core::AvailableVariableNames(*model, df);
}

static bool ModelTermExistsForModel(PlotModel *model, const std::string &term, const std::string &response = "")
{
    return rlispstat::core::ModelTermExistsForVariables(VariableNamesForModel(model), term, response);
}

static std::vector<std::string> FilterModelTermsForResponse(PlotModel *model,
                                                            const std::vector<std::string> &terms,
                                                            const std::string &response)
{
    return rlispstat::core::FilterModelTermsForResponse(VariableNamesForModel(model), terms, response);
}

static std::vector<std::string> BaseVariablesFromModelTerms(PlotModel *model,
                                                            const std::string &response,
                                                            const std::vector<std::string> &modelTerms)
{
    return rlispstat::core::BaseVariablesFromModelTerms(VariableNamesForModel(model), response, modelTerms);
}

static std::vector<std::string> InteractionCandidateTermsForModel(PlotModel *model,
                                                                  const std::string &response,
                                                                  const std::vector<std::string> &modelTerms,
                                                                  const std::vector<std::string> &existingTerms,
                                                                  const std::string &baseTerm = "")
{
    return rlispstat::core::InteractionCandidateTermsForModel(
        VariableNamesForModel(model), response, modelTerms, existingTerms, baseTerm);
}

static std::vector<std::string> HierarchicalTermsForModelTerm(PlotModel *model,
                                                              const std::string &response,
                                                              const std::string &term)
{
    return rlispstat::core::HierarchicalTermsForModelTerm(VariableNamesForModel(model), response, term);
}

static bool AddHierarchicalTermsToVector(PlotModel *model,
                                         const std::string &response,
                                         std::vector<std::string> &terms,
                                         const std::string &term)
{
    return rlispstat::core::AddHierarchicalTermsToVector(
        VariableNamesForModel(model), response, terms, term);
}

@interface LinkEDAPolynomialDegreePromptTarget : NSObject
+ (instancetype)sharedTarget;
- (void)promptForDegree:(id)sender;
@end

@implementation LinkEDAPolynomialDegreePromptTarget
+ (instancetype)sharedTarget
{
    static LinkEDAPolynomialDegreePromptTarget *target = nil;
    if (!target) target = [[LinkEDAPolynomialDegreePromptTarget alloc] init];
    return target;
}
- (void)promptForDegree:(id)sender
{
    NSDictionary *info = [sender representedObject];
    if (![info isKindOfClass:[NSDictionary class]]) return;
    id target = [[info objectForKey:@"target"] nonretainedObjectValue];
    SEL action = NSSelectorFromString([info objectForKey:@"action"] ?: @"");
    NSString *variable = [info objectForKey:@"variable"] ?: @"";
    NSArray<NSString *> *terms = [info objectForKey:@"terms"];
    if (!target || !action || ![target respondsToSelector:action] || terms.count == 0) return;

    NSMutableArray<NSNumber *> *degrees = [NSMutableArray array];
    for (NSString *termLabel in terms) {
        std::string parsedVariable; int degree = 0;
        if (rlispstat::core::ParsePolynomialTerm(termLabel.UTF8String,
                parsedVariable, degree))
            [degrees addObject:@(degree)];
    }
    if (degrees.count == 0) return;
    NSString *validationMessage = nil;
    while (true) {
        NSAlert *alert = [[[NSAlert alloc] init] autorelease];
        alert.messageText = [NSString stringWithFormat:@"Polynomial term: %@", variable];
        NSMutableArray<NSString *> *labels = [NSMutableArray array];
        for (NSNumber *degree in degrees) [labels addObject:degree.stringValue];
        NSString *available = [labels componentsJoinedByString:@", "];
        alert.informativeText = validationMessage ?: [NSString stringWithFormat:
            @"Enter the polynomial degree. Available degrees: %@.", available];
        NSTextField *input = [[[NSTextField alloc] initWithFrame:
            NSMakeRect(0, 0, 220, 24)] autorelease];
        input.placeholderString = @"Degree";
        input.stringValue = degrees.firstObject.stringValue;
        alert.accessoryView = input;
        [alert addButtonWithTitle:@"Add"];
        [alert addButtonWithTitle:@"Cancel"];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
        NSString *requested = [input.stringValue stringByTrimmingCharactersInSet:
            NSCharacterSet.whitespaceAndNewlineCharacterSet];
        NSScanner *scanner = [NSScanner scannerWithString:requested];
        NSInteger degree = 0;
        const bool validInteger = [scanner scanInteger:&degree] && scanner.isAtEnd;
        NSUInteger index = validInteger
            ? [degrees indexOfObject:@(degree)] : NSNotFound;
        if (index == NSNotFound) {
            validationMessage = [NSString stringWithFormat:
                @"Enter one of the available integer degrees: %@.", available];
            continue;
        }
        NSMenuItem *selection = [[[NSMenuItem alloc] initWithTitle:terms[index]
            action:nil keyEquivalent:@""] autorelease];
        selection.representedObject = terms[index];
        [target performSelector:action withObject:selection];
        return;
    }
}
@end

static bool AddPolynomialChoices(NSMenu *menu, id target, SEL action,
    const std::vector<std::string> &numeric, const std::string &response,
    const std::vector<std::string> &terms, const std::string &baseTerm = "",
    const std::map<std::string, int> &maximumDegreeByVariable = {})
{
    const auto groups = rlispstat::core::PolynomialMenuTerms(
        numeric, response, terms, baseTerm, maximumDegreeByVariable);
    if (groups.empty()) return false;
    if (!baseTerm.empty()) {
        const auto &group = *groups.begin();
        NSMutableArray<NSString *> *availableTerms = [NSMutableArray array];
        for (const auto &term : group.second)
            [availableTerms addObject:ToNSString(term)];
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:@"Add polynomial term…"
            action:@selector(promptForDegree:) keyEquivalent:@""];
        item.target = [LinkEDAPolynomialDegreePromptTarget sharedTarget];
        item.representedObject = @{
            @"target": [NSValue valueWithNonretainedObject:target],
            @"action": NSStringFromSelector(action),
            @"variable": ToNSString(group.first),
            @"terms": availableTerms
        };
        [menu addItem:item]; [item release];
        return true;
    }
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Add polynomial term" action:nil keyEquivalent:@""];
    NSMenu *polynomials = [[NSMenu alloc] initWithTitle:@"Add polynomial term"];
    for (const auto &group : groups) {
        NSMenu *choices = baseTerm.empty() ? [[NSMenu alloc] initWithTitle:ToNSString(group.first)] : polynomials;
        for (const auto &term : group.second) {
            std::string variable; int degree = 0; rlispstat::core::ParsePolynomialTerm(term, variable, degree);
            NSString *label = degree == 2 ? @"Quadratic (degree 2)" : degree == 3 ? @"Cubic (degree 3)" :
                [NSString stringWithFormat:@"Degree %d", degree];
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:label action:action keyEquivalent:@""];
            [item setTarget:target]; [item setRepresentedObject:ToNSString(term)]; [choices addItem:item];
        }
        if (baseTerm.empty()) {
            NSMenuItem *variable = [[NSMenuItem alloc] initWithTitle:ToNSString(group.first) action:nil keyEquivalent:@""];
            [variable setSubmenu:choices]; [polynomials addItem:variable];
        }
    }
    [root setSubmenu:polynomials]; [menu addItem:root]; return true;
}

static bool AddPolynomialMenuItems(NSMenu *menu, id target, SEL action, PlotModel *model,
    const std::string &response, const std::vector<std::string> &terms, const std::string &baseTerm = "",
    const std::map<std::string, std::string> &effectiveTypes = {})
{
    std::vector<std::string> numeric;
    std::map<std::string, int> maximumDegreeByVariable;
    const DataFrameModel *dataframe = model ? FindDataFrameUnlockedConst(model->group) : nullptr;
    for (const auto &variable : VariableNamesForModel(model))
        if (rlispstat::core::DefaultTermType(model, variable) == "numeric" &&
            (effectiveTypes.find(variable) == effectiveTypes.end() || effectiveTypes.at(variable) == "numeric")) {
            const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
                *model, dataframe, variable);
            if (metadata.observedCount > 0) {
                maximumDegreeByVariable[variable] = static_cast<int>(
                    std::min<std::size_t>(5, metadata.uniqueCount > 0 ? metadata.uniqueCount - 1 : 0));
            }
            numeric.push_back(variable);
        }
    return AddPolynomialChoices(menu, target, action, numeric, response, terms,
                                baseTerm, maximumDegreeByVariable);
}

static bool AddModelTermMenuItems(NSMenu *menu,
                                    id target,
                                    SEL action,
                                    PlotModel *model,
                                    const std::string &response,
                                    const std::vector<std::string> &existingTerms,
                                    const std::string &baseTerm = "",
    const std::map<std::string, std::string> &effectiveTypes = {})
{
    const bool addedPolynomial = AddPolynomialMenuItems(menu, target, action, model, response, existingTerms, baseTerm, effectiveTypes);
    std::vector<std::string> candidates = InteractionCandidateTermsForModel(model, response, existingTerms, existingTerms, baseTerm);
    if (candidates.empty()) return addedPolynomial;
    const auto groups = rlispstat::core::BuildInteractionMenuGroups(candidates, baseTerm);
    if (groups.empty()) return addedPolynomial;
    NSMenuItem *interactionsItem = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::GLMInteractionsMenuTitle()) action:nil keyEquivalent:@""];
    NSMenu *interactionsMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMInteractionsMenuTitle())];
    if (!baseTerm.empty()) {
        const auto &group = groups.front();
        const std::size_t directOrder =
            rlispstat::core::UniqueBaseVariablesForTerm(baseTerm).size() + 1;
        bool addedDirectChoice = false;
        for (const auto &order : group.orders) {
            if (order.order != directOrder) continue;
            for (const auto &choice : order.choices) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(choice.displayLabel) action:action keyEquivalent:@""];
                [item setTarget:target];
                [item setRepresentedObject:ToNSString(choice.term)];
                [interactionsMenu addItem:item];
                addedDirectChoice = true;
            }
        }
        bool addedHigherOrder = false;
        for (const auto &order : group.orders) {
            if (order.order <= directOrder) continue;
            if (addedDirectChoice && !addedHigherOrder) {
                [interactionsMenu addItem:[NSMenuItem separatorItem]];
            }
            const std::string orderTitle = std::to_string(order.order) + " terms";
            NSMenuItem *orderItem = [[NSMenuItem alloc] initWithTitle:ToNSString(orderTitle) action:nil keyEquivalent:@""];
            NSMenu *orderMenu = [[NSMenu alloc] initWithTitle:ToNSString(orderTitle)];
            for (const auto &choice : order.choices) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(choice.displayLabel) action:action keyEquivalent:@""];
                [item setTarget:target];
                [item setRepresentedObject:ToNSString(choice.term)];
                [orderMenu addItem:item];
            }
            [interactionsMenu setSubmenu:orderMenu forItem:orderItem];
            [interactionsMenu addItem:orderItem];
            addedHigherOrder = true;
        }
        [menu setSubmenu:interactionsMenu forItem:interactionsItem];
        [menu addItem:interactionsItem];
        return addedDirectChoice || addedHigherOrder;
    }
    for (const auto &group : groups) {
        NSMenuItem *predictorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(group.predictor) action:nil keyEquivalent:@""];
        NSMenu *predictorMenu = [[NSMenu alloc] initWithTitle:ToNSString(group.predictor)];
        for (const auto &order : group.orders) {
            const std::string orderTitle = std::to_string(order.order) + " terms";
            NSMenuItem *orderItem = [[NSMenuItem alloc] initWithTitle:ToNSString(orderTitle) action:nil keyEquivalent:@""];
            NSMenu *orderMenu = [[NSMenu alloc] initWithTitle:ToNSString(orderTitle)];
            for (const auto &choice : order.choices) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(choice.displayLabel) action:action keyEquivalent:@""];
                [item setTarget:target];
                [item setRepresentedObject:ToNSString(choice.term)];
                [orderMenu addItem:item];
            }
            [predictorMenu setSubmenu:orderMenu forItem:orderItem];
            [predictorMenu addItem:orderItem];
        }
        [interactionsMenu setSubmenu:predictorMenu forItem:predictorItem];
        [interactionsMenu addItem:predictorItem];
    }
    [menu setSubmenu:interactionsMenu forItem:interactionsItem];
    [menu addItem:interactionsItem];
    return true;
}

static bool AddComparisonModelTermMenuItems(
    NSMenu *menu,
    id target,
    SEL action,
    PlotModel *model,
    const std::string &response,
    const std::vector<std::vector<std::string>> &comparisonModelTerms,
    const std::vector<std::string> &activeModelTerms,
    const std::string &baseTerm = "")
{
    const bool addedPolynomial = AddPolynomialMenuItems(menu, target, action, model, response, activeModelTerms, baseTerm);
    std::vector<std::string> candidates = rlispstat::core::InteractionCandidateTermsForComparison(
        VariableNamesForModel(model), response, comparisonModelTerms, activeModelTerms, baseTerm);
    if (candidates.empty()) return addedPolynomial;
    const auto groups = rlispstat::core::BuildInteractionMenuGroups(candidates, baseTerm);
    if (groups.empty()) return addedPolynomial;
    NSMenuItem *interactionsItem = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::GLMInteractionsMenuTitle())
               action:nil
        keyEquivalent:@""];
    NSMenu *interactionsMenu = [[NSMenu alloc]
        initWithTitle:ToNSString(rlispstat::core::GLMInteractionsMenuTitle())];
    if (!baseTerm.empty()) {
        const auto &group = groups.front();
        const std::size_t directOrder =
            rlispstat::core::UniqueBaseVariablesForTerm(baseTerm).size() + 1;
        bool addedDirectChoice = false;
        for (const auto &order : group.orders) {
            if (order.order != directOrder) continue;
            for (const auto &choice : order.choices) {
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:ToNSString(choice.displayLabel)
                           action:action
                    keyEquivalent:@""];
                [item setTarget:target];
                [item setRepresentedObject:ToNSString(choice.term)];
                [interactionsMenu addItem:item];
                addedDirectChoice = true;
            }
        }
        bool addedHigherOrder = false;
        for (const auto &order : group.orders) {
            if (order.order <= directOrder) continue;
            if (addedDirectChoice && !addedHigherOrder) {
                [interactionsMenu addItem:[NSMenuItem separatorItem]];
            }
            const std::string orderTitle = std::to_string(order.order) + " terms";
            NSMenuItem *orderItem = [[NSMenuItem alloc]
                initWithTitle:ToNSString(orderTitle)
                       action:nil
                keyEquivalent:@""];
            NSMenu *orderMenu = [[NSMenu alloc] initWithTitle:ToNSString(orderTitle)];
            for (const auto &choice : order.choices) {
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:ToNSString(choice.displayLabel)
                           action:action
                    keyEquivalent:@""];
                [item setTarget:target];
                [item setRepresentedObject:ToNSString(choice.term)];
                [orderMenu addItem:item];
            }
            [interactionsMenu setSubmenu:orderMenu forItem:orderItem];
            [interactionsMenu addItem:orderItem];
            addedHigherOrder = true;
        }
        [menu setSubmenu:interactionsMenu forItem:interactionsItem];
        [menu addItem:interactionsItem];
        return addedDirectChoice || addedHigherOrder;
    }
    for (const auto &group : groups) {
        NSMenuItem *predictorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(group.predictor) action:nil keyEquivalent:@""];
        NSMenu *predictorMenu = [[NSMenu alloc] initWithTitle:ToNSString(group.predictor)];
        for (const auto &order : group.orders) {
            const std::string orderTitle = std::to_string(order.order) + " terms";
            NSMenuItem *orderItem = [[NSMenuItem alloc] initWithTitle:ToNSString(orderTitle) action:nil keyEquivalent:@""];
            NSMenu *orderMenu = [[NSMenu alloc] initWithTitle:ToNSString(orderTitle)];
            for (const auto &choice : order.choices) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(choice.displayLabel) action:action keyEquivalent:@""];
                [item setTarget:target];
                [item setRepresentedObject:ToNSString(choice.term)];
                [orderMenu addItem:item];
            }
            [predictorMenu setSubmenu:orderMenu forItem:orderItem];
            [predictorMenu addItem:orderItem];
        }
        [interactionsMenu setSubmenu:predictorMenu forItem:predictorItem];
        [interactionsMenu addItem:predictorItem];
    }
    [menu setSubmenu:interactionsMenu forItem:interactionsItem];
    [menu addItem:interactionsItem];
    return true;
}

static std::vector<std::string> SearchableModelTermChoices(
    PlotModel *model, const std::string &response,
    const std::vector<std::string> &existingTerms,
    const std::map<std::string, std::string> &effectiveTypes = {})
{
    (void)existingTerms;
    (void)effectiveTypes;
    std::vector<std::string> choices;
    const auto variables = VariableNamesForModel(model);
    for (const std::string &name : variables)
        if (name != response)
            choices.push_back(name);
    std::vector<std::string> unique;
    for (auto &choice : choices)
        if (!choice.empty() && std::find(unique.begin(), unique.end(), choice) == unique.end())
            unique.push_back(std::move(choice));
    return unique;
}

static std::vector<std::string> SearchableComparisonTermChoices(
    PlotModel *model, const std::string &response,
    const std::vector<std::vector<std::string>> &comparisonTerms,
    const std::vector<std::string> &activeTerms)
{
    (void)comparisonTerms;
    return SearchableModelTermChoices(model, response, activeTerms);
}

static std::vector<std::string> SearchableTermsIncludingBase(
    PlotModel *model, const std::string &response,
    std::vector<std::string> terms, const std::string &baseTerm)
{
    rlispstat::core::AddHierarchicalTermsToVector(
        VariableNamesForModel(model), response, terms, baseTerm);
    return terms;
}

static NSMenu *SearchableModelTermContextMenu(
    NSString *label, id target, SEL action, PlotModel *model,
    const std::string &response, const std::vector<std::string> &currentTerms,
    const std::map<std::string, std::string> &effectiveTypes = {})
{
    const std::string baseTerm = label ? std::string(label.UTF8String) : std::string();
    NSMenu *menu = [[[NSMenu alloc] initWithTitle:@"Term actions"] autorelease];
    NSMenuItem *heading = [[[NSMenuItem alloc] initWithTitle:label ?: @""
        action:nil keyEquivalent:@""] autorelease];
    heading.enabled = NO; [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *root = [[[NSMenuItem alloc] initWithTitle:@"Model terms"
        action:nil keyEquivalent:@""] autorelease];
    NSMenu *termsMenu = [[[NSMenu alloc] initWithTitle:@"Model terms"] autorelease];
    const auto termsWithBase = SearchableTermsIncludingBase(
        model, response, currentTerms, baseTerm);
    if (!AddModelTermMenuItems(termsMenu, target, action, model, response,
            termsWithBase, baseTerm, effectiveTypes)) {
        NSMenuItem *empty = [[[NSMenuItem alloc]
            initWithTitle:@"No polynomial or interaction terms available"
            action:nil keyEquivalent:@""] autorelease];
        empty.enabled = NO; [termsMenu addItem:empty];
    }
    root.submenu = termsMenu; [menu addItem:root];
    return menu;
}

static NSMenu *SearchableComparisonTermContextMenu(
    NSString *label, id target, SEL action, PlotModel *model,
    const std::string &response,
    std::vector<std::vector<std::string>> comparisonTerms,
    const std::vector<std::string> &activeTerms, std::size_t activeModel)
{
    const std::string baseTerm = label ? std::string(label.UTF8String) : std::string();
    NSMenu *menu = [[[NSMenu alloc] initWithTitle:@"Term actions"] autorelease];
    NSMenuItem *heading = [[[NSMenuItem alloc] initWithTitle:label ?: @""
        action:nil keyEquivalent:@""] autorelease];
    heading.enabled = NO; [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *root = [[[NSMenuItem alloc] initWithTitle:@"Model terms"
        action:nil keyEquivalent:@""] autorelease];
    NSMenu *termsMenu = [[[NSMenu alloc] initWithTitle:@"Model terms"] autorelease];
    const auto termsWithBase = SearchableTermsIncludingBase(
        model, response, activeTerms, baseTerm);
    if (activeModel < comparisonTerms.size()) comparisonTerms[activeModel] = termsWithBase;
    if (!AddComparisonModelTermMenuItems(termsMenu, target, action, model,
            response, comparisonTerms, activeTerms, baseTerm)) {
        NSMenuItem *empty = [[[NSMenuItem alloc]
            initWithTitle:@"No polynomial or interaction terms available"
            action:nil keyEquivalent:@""] autorelease];
        empty.enabled = NO; [termsMenu addItem:empty];
    }
    root.submenu = termsMenu; [menu addItem:root];
    return menu;
}

static const DataColumn *FindDataColumnUnlockedConst(const std::string &group, const std::string &variable);
static DataFrameModel DataFrameMenuSnapshot(const DataFrameModel &source)
{
    // Menus need the active values and semantic metadata, not every stored
    // imputation or the opaque mids serialization.  Copying the complete
    // object here made a right click scale with the number of imputations.
    DataFrameModel snapshot;
    snapshot.group = source.group;
    snapshot.rows = source.rows;
    snapshot.datasetType = source.datasetType;
    snapshot.imputationId = source.imputationId;
    snapshot.sourceDatasetId = source.sourceDatasetId;
    snapshot.imputationCount = source.imputationCount;
    snapshot.activeImputationVersion = source.activeImputationVersion;
    snapshot.imputationDisplayMode = source.imputationDisplayMode;
    snapshot.dataVersion = source.dataVersion;
    snapshot.columns.reserve(source.columns.size());
    for (const DataColumn &sourceColumn : source.columns) {
        DataColumn column;
        column.name = sourceColumn.name;
        column.type = sourceColumn.type;
        column.displayName = sourceColumn.displayName;
        column.description = sourceColumn.description;
        column.decimals = sourceColumn.decimals;
        column.values = sourceColumn.values;
        column.displayValues = sourceColumn.displayValues;
        column.definedLevels = sourceColumn.definedLevels;
        column.reversibleFactorLevels = sourceColumn.reversibleFactorLevels;
        column.storageType = sourceColumn.storageType;
        column.numericMapping = sourceColumn.numericMapping;
        column.reversibleCategoryType = sourceColumn.reversibleCategoryType;
        column.binary = sourceColumn.binary;
        snapshot.columns.push_back(std::move(column));
    }
    return snapshot;
}

static std::vector<std::string> BarplotAvailableVariablesForModel(const PlotModel *model)
{
    if (!model) return {};
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *df = FindDataFrameUnlockedConst(model->group);
    return df ? rlispstat::core::BarplotAvailableVariables(*df) : std::vector<std::string>();
}

static bool RebuildBarplotFromModelVariables(PlotModel *model, std::string *message = nullptr)
{
    if (!model) {
        if (message) *message = rlispstat::core::BarplotNotAvailableStatus();
        return false;
    }
    DataFrameModel df;
    bool foundData = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(model->group);
        if (found) {
            df = *found;
            foundData = true;
        }
    }
    if (!foundData) {
        if (message) *message = rlispstat::core::DatasetNotAvailableStatus();
        return false;
    }
    const bool rebuilt = rlispstat::core::RebuildBarplotFromDataFrame(*model, df, message);
    if (rebuilt) {
        std::lock_guard<std::mutex> lock(g_mutex);
        ApplyCapturedAnalysisScopeToPlotUnlocked(*model);
    }
    return rebuilt;
}

static void ComputeScatterRangesIncludingAllImputations(PlotModel *plot, const DataFrameModel &df)
{
    if (!plot || !DataFrameShowsAllImputations(df)) {
        ComputeRanges(plot);
        return;
    }
    const DataColumn *xCol = FindDataColumnInDataFrame(df, plot->xLabel);
    const DataColumn *yCol = FindDataColumnInDataFrame(df, plot->yLabel);
    if (!xCol || !yCol) {
        ComputeRanges(plot);
        return;
    }

    std::vector<rlispstat::core::ScatterplotPointValue> pointValues;
    pointValues.reserve(plot->points.size());
    for (const DataPoint &p : plot->points) {
        pointValues.push_back(rlispstat::core::ScatterplotPointValue{p.row, p.x, p.y});
    }
    std::optional<rlispstat::core::DataViewport> viewport =
        rlispstat::core::ScatterplotViewportIncludingImputations(
            df,
            *xCol,
            *yCol,
            pointValues,
            plot->scatterImputationUncertainty);
    if (!viewport.has_value()) {
        ComputeRanges(plot);
        return;
    }
    plot->dataXmin = viewport->xmin;
    plot->dataXmax = viewport->xmax;
    plot->dataYmin = viewport->ymin;
    plot->dataYmax = viewport->ymax;
    plot->xmin = plot->dataXmin;
    plot->xmax = plot->dataXmax;
    plot->ymin = plot->dataYmin;
    plot->ymax = plot->dataYmax;
}

// Called while g_mutex is held.  Return one exact point cloud per completed
// dataset for both ordinary MI scatterplots and MI regression diagnostics.
static std::vector<rlispstat::core::ScatterplotImputationPointSet>
ImputationPointSetsForSmoothUnlocked(const PlotModel &plot)
{
    if (plot.isGLMDiagnostic) {
        return rlispstat::core::BuildRegressionDiagnosticSmoothPointSets(plot);
    }
    rlispstat::core::ScatterplotRenderInput input;
    input.points.reserve(plot.points.size());
    for (const DataPoint &point : plot.points) {
        input.points.push_back({point.row, point.x, point.y});
    }
    if (plot.kind == "scatter") {
        const DataFrameModel *dataframe = FindDataFrameUnlockedConst(plot.group);
        if (dataframe && DataFrameShowsAllImputations(*dataframe)) {
            input.imputationDataFrame = dataframe;
            input.xColumn = FindDataColumnInDataFrame(*dataframe, plot.xLabel);
            input.yColumn = FindDataColumnInDataFrame(*dataframe, plot.yLabel);
        }
    }
    return rlispstat::core::BuildScatterplotImputationPointSets(input);
}

static std::string CurrentLabelColumnForGroupUnlocked(const std::string &group)
{
    const std::string column = MacCommandDispatcher().applicationState().labelColumn(group);
    return FindDataColumnUnlockedConst(group, column) ? column : "";
}

static std::map<int, std::string> LabelMapForGroup(const std::string &group)
{
    std::map<int, std::string> labels;
    std::lock_guard<std::mutex> lock(g_mutex);
    std::string column = CurrentLabelColumnForGroupUnlocked(group);
    if (column.empty()) {
        return labels;
    }
    const DataColumn *col = FindDataColumnUnlockedConst(group, column);
    if (!col) {
        return labels;
    }
    return rlispstat::core::RowLabelMapForColumn(*col);
}

static std::string LabelColumnForGroup(const std::string &group)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return CurrentLabelColumnForGroupUnlocked(group);
}

static std::map<int, std::string> RowColorsForPlot(const PlotModel *model)
{
    if (!model) return {};
    if (model->frozenAppearanceCaptured) return model->frozenRowColors;
    std::lock_guard<std::mutex> lock(g_mutex);
    std::map<int, std::string> result;
    for (const auto &entry :
         MacCommandDispatcher().applicationState().displayPointColors(model->group))
        result[entry.first] = entry.second;
    return result;
}

static std::map<int, std::string> RowLabelsForPlot(const PlotModel *model)
{
    if (!model) return {};
    auto labels = model->frozenAppearanceCaptured ? model->frozenRowLabels
                                                  : LabelMapForGroup(model->group);
    // A biplot always has real source case IDs, even before a label variable
    // is chosen. Use those IDs rather than silently drawing no labels.
    if (labels.empty() && model->kind == "pca_biplot")
        for (const auto &point : model->points)
            if (point.row > 0) labels[point.row] = std::to_string(point.row);
    return labels;
}

static std::string RowColorForPlot(const PlotModel *model, int row)
{
    if (!model || !model->frozenAppearanceCaptured)
        return model ? PointColorForRow(model->group, row) : std::string();
    auto found = model->frozenRowColors.find(row);
    return found == model->frozenRowColors.end() ? std::string() : found->second;
}

static bool SetGroupLabelColumn(const std::string &group, const std::string &column, std::string *message = nullptr)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!DatasetExistsUnlocked(group)) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        if (!MacCommandDispatcher().applicationState().setLabelColumn(group, column)) {
            if (message) *message = rlispstat::core::DatasetColumnNotFoundStatus(column, group);
            return false;
        }
    }
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
    if (message) {
        *message = column.empty() ? rlispstat::core::DatasetPointLabelsResetStatus() : rlispstat::core::DatasetPointLabelColumnSetStatus(column);
    }
    return true;
}

static PlotModel *FirstPlotForGroupUnlocked(const std::string &group)
{
    PlotModel *seed = nullptr;
    for (const auto &entry : g_plots) {
        if (entry.second && entry.second->group == group && !entry.second->isGLMDiagnostic) {
            if (!entry.second->isDatasetSeed) {
                return entry.second;
            }
            seed = entry.second;
        }
    }
    return seed;
}

static GroupModelState &EnsureGroupModelUnlocked(const std::string &group, PlotModel *seed = nullptr)
{
    GroupModelState &state = rlispstat::core::EnsureGroupModelState(g_groupModels, group, seed);
    // Independent model windows use an ID such as linear_model:Alien:1.
    // Their dataset remains state.group; looking up the model ID here skips
    // type synchronization and silently treats categorical terms as numeric.
    if (const DataFrameModel *dataframe = FindDataFrameUnlockedConst(state.group)) {
        state.multipleImputation = GroupIsMultipleImputationUnlocked(state.group);
        state.imputationCount = state.multipleImputation ? std::max(1, dataframe->imputationCount) : 0;
        if (rlispstat::core::SynchronizeGroupModelTermTypes(state, *dataframe)) {
            rlispstat::core::MarkGroupModelChanged(state);
        }
    }
    return state;
}

static rlispstat::core::AnalysisVariableRoles
DeclaredVariableRolesSnapshot(const std::string &group)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return rlispstat::core::DefaultVariableRolesForAnalysisInitialization(
        MacCommandDispatcher().applicationState().variableRoles(group));
}

// The shared experimental gate currently returns no defaults. If the feature
// is enabled later, the returned map remains a value copy: model-local terms,
// interactions and term properties never travel back into dataset metadata.
static rlispstat::core::AnalysisVariableRoles
FreshRegressionVariableRolesSnapshot(const std::string &group)
{
    return rlispstat::core::FreshRegressionAnalysisVariableRoles(
        DeclaredVariableRolesSnapshot(group));
}

static rlispstat::core::InitialAnalysisSpecification
ResolveInitialAnalysisForGroup(const DataFrameModel &dataframe,
                               rlispstat::core::SharedAnalysisKind kind,
                               const rlispstat::core::AnalysisSpecification *existing = nullptr)
{
    return rlispstat::core::ResolveInitialAnalysisSpecification(
        dataframe, rlispstat::core::SharedAnalysisDefinition(kind),
        DeclaredVariableRolesSnapshot(dataframe.group), existing);
}

static bool DataFrameSnapshotForGroup(const std::string &group,
                                      DataFrameModel &dataframe)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *found = FindDataFrameUnlockedConst(group);
    if (!found) return false;
    dataframe = *found;
    return true;
}

static void DrawPointSelectionRing(const PlotThemeStyle &theme,
                                   NSPoint point,
                                   CGFloat pointRadius,
                                   NSColor *color)
{
    (void)theme;
    const CGFloat ringRadius = pointRadius + 1.8;
    NSBezierPath *ring = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(
        point.x - ringRadius, point.y - ringRadius,
        ringRadius * 2.0, ringRadius * 2.0)];
    [[color colorWithAlphaComponent:0.28] setFill];
    [ring fill];
}

static PlotModel *EnsureDatasetSeedPlotUnlocked(const std::string &group)
{
    for (const auto &entry : g_plots) {
        if (entry.second && entry.second->group == group && entry.second->isDatasetSeed) {
            return entry.second;
        }
    }
    const DataFrameModel *found = FindDataFrameUnlockedConst(group);
    if (!found) {
        return FirstPlotForGroupUnlocked(group);
    }
    const DataFrameModel &df = *found;
    PlotModel *seed = new PlotModel();
    rlispstat::core::PopulateDatasetSeedPlot(*seed, df, group);
    (void)AttachPlotModelUnlocked(seed);
    EnsureGroupModelUnlocked(group, seed);
    return seed;
}

static std::string ActiveDatasetGroupUnlocked()
{
    std::string fallbackGroup;
    auto activePlot = g_plots.find(g_activePlotId);
    if (activePlot != g_plots.end() && activePlot->second) {
        fallbackGroup = activePlot->second->group;
    }
    return MacCommandDispatcher().applicationState().datasets().activeDatasetGroup(fallbackGroup);
}

static PlotModel *ActiveDatasetSeedPlotUnlocked()
{
    std::string group = ActiveDatasetGroupUnlocked();
    if (group.empty()) {
        return nullptr;
    }
    return EnsureDatasetSeedPlotUnlocked(group);
}

static void MarkActiveDatasetGroupUnlocked(const std::string &group)
{
    MacCommandDispatcher().applicationState().datasets().rememberActiveDatasetGroup(group);
}

static void SetActiveDatasetUnlocked(const std::string &group)
{
    if (!MacCommandDispatcher().applicationState().datasets().setActiveDataset(group)) {
        return;
    }
    PlotModel *seed = EnsureDatasetSeedPlotUnlocked(group);
    if (seed) {
        (void)MacPlotCoordinator().activatePlot(seed->id);
    }
}

// Dataset defaults are metadata, not a projection of the currently open
// linear model. Call while holding g_mutex when sharing state with background
// analysis work.
static std::string DefaultVariableRoleForGroupUnlocked(
    const std::string &group, const std::string &name)
{
    const auto roles = MacCommandDispatcher().applicationState().variableRoles(group);
    const auto found = roles.find(name);
    return found == roles.end() ? "none" : found->second;
}

static bool SetDefaultVariableRoleOnMac(
    const std::string &group, const std::string &variable,
    const std::string &role, std::string *message = nullptr)
{
    const std::string reply = MacCommandDispatcher().dispatch(
        {"SET_DEFAULT_VARIABLE_ROLE", group, variable, role});
    const bool ok = reply.rfind("OK", 0) == 0;
    if (message) {
        *message = reply.rfind("OK\t", 0) == 0 ? reply.substr(3)
            : reply.rfind("ERR ", 0) == 0 ? reply.substr(4) : reply;
    }
    return ok;
}



struct ScatterPointDrawCache {
