// The selection outline lives in its own view so pointer movement does not
// repaint every point, smoother and imputation glyph in the plot underneath.
@interface PlotGestureOverlayView : NSView
@property(nonatomic) NSRect gestureRect;
@end

@implementation PlotGestureOverlayView
- (BOOL)isFlipped { return YES; }
- (BOOL)isOpaque { return NO; }
- (NSView *)hitTest:(NSPoint)point { (void)point; return nil; }
- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    if (NSIsEmptyRect(self.gestureRect)) return;
    [[NSColor colorWithCalibratedRed:0.125 green:0.445 blue:0.705 alpha:0.10] setFill];
    NSRectFillUsingOperation(self.gestureRect, NSCompositingOperationSourceOver);
    NSBezierPath *outline = [NSBezierPath bezierPathWithRect:self.gestureRect];
    CGFloat dash[] = {5.0, 4.0};
    [outline setLineDash:dash count:2 phase:0.0];
    [outline setLineWidth:1.5];
    [[NSColor colorWithCalibratedRed:0.050 green:0.310 blue:0.520 alpha:0.95] setStroke];
    [outline stroke];
}
@end

