@end

@implementation AssociatedDataSheetButtonTarget
- (void)showAssociatedDataSheet:(id)sender
{
    (void)sender;
    if ([self.group length]) ShowDataSheetOnMain(std::string([self.group UTF8String]));
}
@end

static char kAssociatedDataSheetButtonTargetKey;
static char kAssociatedDataSheetButtonAccessoryKey;
static char kWindowDatasetGroupKey;

static void AssociateWindowWithDataset(NSWindow *window, const std::string &group)
{
    if (window && !group.empty())
        objc_setAssociatedObject(window, &kWindowDatasetGroupKey,
                                 ToNSString(group), OBJC_ASSOCIATION_COPY_NONATOMIC);
}

static void SetWindowDataSheetGroupOnMac(NSWindow *window,
                                         const std::string &group)
{
    if (!window || group.empty()) return;
    AssociateWindowWithDataset(window, group);
    AssociatedDataSheetButtonTarget *target =
        (AssociatedDataSheetButtonTarget *)objc_getAssociatedObject(
            window, &kAssociatedDataSheetButtonTargetKey);
    if (!target) {
        target = [[AssociatedDataSheetButtonTarget alloc] init];
        NSButton *button = [[NSButton alloc] initWithFrame:NSMakeRect(0, 0, 32, 24)];
        NSImage *image = [NSImage imageWithSystemSymbolName:@"tablecells"
                                  accessibilityDescription:@"Show associated data"];
        if (image) {
            [button setImage:image];
            [button setImagePosition:NSImageOnly];
        } else {
            [button setTitle:@"▦"];
        }
        [button setBezelStyle:NSBezelStyleTexturedRounded];
        [button setTarget:target];
        [button setAction:@selector(showAssociatedDataSheet:)];
        [button setToolTip:@"Show associated data sheet"];
        [button setAccessibilityLabel:@"Show associated data sheet"];

        NSTitlebarAccessoryViewController *accessory =
            [[NSTitlebarAccessoryViewController alloc] init];
        [accessory setView:button];
        [accessory setLayoutAttribute:NSLayoutAttributeRight];
        [window addTitlebarAccessoryViewController:accessory];
        objc_setAssociatedObject(window, &kAssociatedDataSheetButtonTargetKey,
                                 target, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(window, &kAssociatedDataSheetButtonAccessoryKey,
                                 accessory, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    [target setGroup:ToNSString(group)];
}

using SpreadPlotMessage = rlispstat::core::SpreadPlotMessage;
static void PublishSpreadPlotEventOnMac(const SpreadPlotMessage &message);

static void RedrawGroupViewsNow(const std::string &group, bool forceDisplay = false)
{
    std::vector<ScatterView *> scatterViews;
    std::vector<BoxplotView *> boxplotViews;
    std::vector<HistogramView *> histogramViews;
    std::vector<BarplotView *> barplotViews;
    std::vector<id<GLMPairwiseComparisonPlotRefreshing>> pairwiseComparisonPlotViews;
    std::vector<id<GLMPairwiseResultsRefreshing>> pairwiseResultsControllers;
    std::vector<Table1ReportView *> table1Views;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (ScatterView *view : g_views) {
            if (view.model && view.model->group == group) {
                scatterViews.push_back(view);
            }
        }
        for (BoxplotView *view : g_boxplotViews) {
            if (view.model && view.model->group == group) {
                boxplotViews.push_back(view);
            }
        }
        for (HistogramView *view : g_histogramViews) {
            if (view.model && view.model->group == group) {
                histogramViews.push_back(view);
            }
        }
        for (BarplotView *view : g_barplotViews) {
            if (view.model && view.model->group == group) {
                barplotViews.push_back(view);
            }
        }
        for (id<GLMPairwiseComparisonPlotRefreshing> view : g_pairwiseComparisonPlotViews) {
            const std::string &viewGroup = [view pairwisePlotGroup];
            if (viewGroup == group) {
                pairwiseComparisonPlotViews.push_back(view);
            }
        }
        for (id<GLMPairwiseResultsRefreshing> controller : g_pairwiseResultsControllers) {
            const std::string &controllerGroup = [controller pairwiseResultsGroup];
            if (controllerGroup == group) pairwiseResultsControllers.push_back(controller);
        }
        for (const Table1ViewEntry &entry : g_table1Views) {
            if (entry.group == group) {
                table1Views.push_back(static_cast<Table1ReportView *>(entry.view));
            }
        }
    }
    for (ScatterView *view : scatterViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (BoxplotView *view : boxplotViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (HistogramView *view : histogramViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (BarplotView *view : barplotViews) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (id<GLMPairwiseComparisonPlotRefreshing> view : pairwiseComparisonPlotViews) {
        [view refreshPairwisePlotSelection];
        if (forceDisplay) [view displayIfNeeded];
    }
    for (id<GLMPairwiseResultsRefreshing> controller : pairwiseResultsControllers) {
        [controller refreshPairwiseResultsSelection];
    }
    for (Table1ReportView *view : table1Views) {
        [view setNeedsDisplay:YES];
        if (forceDisplay) [view displayIfNeeded];
    }
}

