static void PublishSpreadPlotEventOnMac(const SpreadPlotMessage &message)
{
    if (message.groupId.empty()) return;
    if (message.type == "ANALYSIS_SCOPE_CHANGED") {
        const std::string group = message.groupId;
        // Scope changes can be published while the dataset mutex is held.
        // Invalidate fits later on the UI queue, before redrawing their windows.
        dispatch_async(dispatch_get_main_queue(), ^{
            [GlobalAnalysisScopeSummary refreshRegisteredScopeViews];
            RefreshOpenPlotsForGlobalScopeOnMain(group, false);
            RefitOpenAnalysesForScopeOnMain(group, false);
            RefreshDataDeskWindowsOnMain(group);
            RedrawGroupViewsOnMain(group);
            RefreshRegressionComparisonWindowsOnMain(group, false);
            RefreshGeneralizedComparisonWindowsOnMain(group, false);
            UpdateAnalysisScopeStatusOnMain();
            UpdatePanelOnMain();
        });
        return;
    }
    if (message.type == "GLM_SPEC_CHANGED" ||
        message.type == "GLM_DEPENDENT_CHANGED" ||
        message.type == "GLM_PREDICTOR_ADDED" ||
        message.type == "GLM_PREDICTOR_REMOVED" ||
        message.type == "GLM_PREDICTOR_REPLACED" ||
        message.type == "GLM_TERM_TYPE_CHANGED" ||
        message.type == "GLM_SCOPE_CHANGED") {
        RefreshGLMDiagnosticPlotsOnMain(message.groupId);
        RefreshDataDeskWindowsOnMain(message.groupId);
        return;
    }
    if (message.type == "GLM_REFIT_COMPLETED" ||
        message.type == "GLM_DIAGNOSTICS_UPDATED") {
        RefreshGLMDiagnosticPlotsOnMain(message.groupId);
        RedrawGroupViewsOnMain(message.groupId);
        return;
    }
	    if (message.type == "ROW_SELECTION_CHANGED") {
        { std::lock_guard<std::mutex> lock(g_mutex);
          if (g_liveBrushGroups.count(message.groupId)) return; }
	        [GlobalAnalysisScopeSummary refreshRegisteredScopeViews];
	        UpdateAnalysisScopeStatusOnMain();
	        RefreshOpenPlotsForGlobalScopeOnMain(message.groupId, true);
	        RefitOpenAnalysesForScopeOnMain(message.groupId, true);
	        RefreshGLMOnMain(message.groupId);
	        RefreshGLMDiagnosticPlotsOnMain(message.groupId);
	        RedrawGroupViewsOnMain(message.groupId);
        RefreshDendrogramWindowsOnMain(message.groupId);
        RefreshDataDeskWindowsOnMain(message.groupId);
        RefreshRegressionComparisonWindowsOnMain(message.groupId, true);
        RefreshGeneralizedComparisonWindowsOnMain(message.groupId, true);
        return;
    }
    if (message.type == "ROW_COLORS_CHANGED" || message.type == "VIEW_NEEDS_REDRAW") {
        RefreshGLMDiagnosticPlotsOnMain(message.groupId);
        RedrawGroupViewsOnMain(message.groupId);
        RefreshDendrogramWindowsOnMain(message.groupId);
        RefreshDataDeskWindowsOnMain(message.groupId);
        RefreshRegressionComparisonWindowsOnMain(message.groupId, false);
        RefreshGeneralizedComparisonWindowsOnMain(message.groupId, false);
        return;
    }
    if (message.type == "DIAGNOSTIC_PLOT_OPENED") {
        RedrawGroupViewsOnMain(message.groupId);
    }
}

static void PublishSpreadPlotMessage(const std::string &type, const std::string &group,
                                     const std::string &senderId,
                                     const std::string &modelId,
                                     const std::vector<int> &rowIds,
                                     int selectionVersion)
{
    SpreadPlotMessage message;
    message.type = type;
    message.groupId = group;
    message.senderId = senderId;
    message.modelId = modelId;
    message.rowIds = rowIds;
    message.selectionVersion = selectionVersion;
    if (type == "ROW_SELECTION_CHANGED" && message.selectionVersion == 0) {
        std::lock_guard<std::mutex> lock(g_mutex);
        message.selectionVersion = g_groupSelectionVersions[group];
    }
    PublishSpreadPlotEventOnMac(message);
}

