        (flags & NSEventModifierFlagOption) != 0,
        (flags & NSEventModifierFlagCommand) != 0,
        (flags & NSEventModifierFlagControl) != 0,
        (flags & NSEventModifierFlagShift) != 0,
        model ? model->selectionMode : "replace");
}

static bool RequestSmoothRecomputeForGroupUnlocked(const std::string &group,
                                                   rlispstat::core::SmoothCurveScope scope)
{
    bool requested = false;
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (!plot || plot->group != group) {
            continue;
        }
        if (plot->kind == "scatter_matrix") {
            const std::string source = scope == SmoothCurveScope::Selection ? "selected" :
                scope == SmoothCurveScope::ColorGroup ? "color" : "all";
            if (rlispstat::core::HasOverlaySource(*plot, source)) {
                rlispstat::core::InvalidateScatterMatrixFits(*plot);
                requested = true;
            }
            continue;
        }
        requested = rlispstat::core::MarkSmoothCurveScopePendingIfPresent(plot->smoothCurves, scope) || requested;
    }
    return requested;
}

static void RequestColorSmoothRecomputeForGroupUnlocked(const std::string &group)
{
    if (RequestSmoothRecomputeForGroupUnlocked(group, rlispstat::core::SmoothCurveScope::ColorGroup)) {
        NotifyMainRTaskAvailable();
    }
}

static bool RequestSmoothRecomputeForPlotUnlocked(PlotModel *plot)
{
    if (!plot) {
        return false;
    }
    if (plot->kind == "scatter_matrix") {
        rlispstat::core::InvalidateScatterMatrixFits(*plot);
        return plot->scatterMatrixFitsPending;
    }
    return rlispstat::core::MarkExistingSmoothCurvesPending(plot->smoothCurves);
}

static void MarkSelectionScopedModelsStaleUnlocked(const std::string &group)
{
    const auto active = MacCommandDispatcher().applicationState().activeAnalysisScope(group);
    if (!rlispstat::core::AnalysisScopeTracksCurrentSelection(active) &&
        active.sourceKind != rlispstat::core::AnalysisScopeSourceKind::CurrentUnselection) return;
    for (auto &entry : g_groupModels) {
        GroupModelState &state = entry.second;
        if (state.group != group) continue;
        // A disabled Auto-refit freezes both the fitted result and its row
        // snapshot. The later scope notification only adds an explanatory
        // note; it must not capture the new selection or invalidate this fit.
        if (!state.autoRefit) {
            state.frozenScopeNotice = state.dataScopeCaptured
                ? rlispstat::core::FrozenAnalysisScopeNotice(state.dataScope, active)
                : std::string{};
            continue;
        }
        if (MacCommandDispatcher().applicationState().captureAnalysisScope(
                group, state.dataScope, state.dataScopeCaptured, &state.scope))
            rlispstat::core::MarkGroupModelChanged(state);
    }
}

static bool CompleteCoordinatedSelectionUnlocked(
    const rlispstat::core::PlotCoordinationResult &coordination,
    int *selectionVersion)
{
    if (!coordination.accepted) return false;
    if (selectionVersion) {
        *selectionVersion = coordination.event.selectionVersion;
    }
    if (!coordination.changed) return false;
    if (g_liveBrushGroups.count(coordination.event.group)) return true;
    MarkSelectionScopedModelsStaleUnlocked(coordination.event.group);
    if (RequestSmoothRecomputeForGroupUnlocked(
            coordination.event.group,
            rlispstat::core::SmoothCurveScope::Selection)) {
        NotifyMainRTaskAvailable();
    }
    return true;
}

static bool SetGroupSelectionUnlocked(const std::string &group,
                                      const std::set<int> &rows,
                                      int *selectionVersion = nullptr)
{
    // Existing interactive views create a group on first use. The portable
    // coordinator owns normalization, versioning and linked plot membership.
    MacCommandDispatcher().applicationState().ensureSelectionGroup(group);
    return CompleteCoordinatedSelectionUnlocked(
        MacPlotCoordinator().replaceSelection(group, rows),
        selectionVersion);
}

static void NotifyPortableSelectionChanged(const std::string &group,
                                           const std::set<int> &rows,
                                           int selectionVersion,
                                           bool redraw)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkSelectionScopedModelsStaleUnlocked(group);
        if (RequestSmoothRecomputeForGroupUnlocked(
                group, rlispstat::core::SmoothCurveScope::Selection)) {
            NotifyMainRTaskAvailable();
        }
    }
    PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", group, "backend", "",
                             std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    // ROW_SELECTION_CHANGED already refreshes every linked view. Publishing a
    // second VIEW_NEEDS_REDRAW repeated the expensive diagnostic and analysis
    // window refresh for every click or brush gesture.
    (void)redraw;
    dispatch_async(dispatch_get_main_queue(), ^{
        std::vector<ModelTrellisWindowController *> controllers;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            for (const auto &entry : g_modelTrellisControllers) {
                auto state = g_modelTrellises.find(entry.first);
                if (state != g_modelTrellises.end() && state->second.specification.baseModel.group == group) {
                    controllers.push_back(entry.second);
                }
            }
        }
        for (ModelTrellisWindowController *controller : controllers) [(id)controller performSelector:@selector(refresh)];
    });
}

