static bool SavePlotViewToPathOnMain(const std::string &plotId, NSString *path, const std::string &format)
{
    __block BOOL ok = NO;
    void (^saveBlock)(void) = ^{
      NSView *view = nil;
      PlotModel *model = nullptr;
      std::string originalTitle;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          view = PlotViewForPlotUnlocked(plotId);
          auto found = g_plots.find(plotId);
          if (found != g_plots.end() && found->second) {
              model = found->second;
              originalTitle = model->title;
              if (model->dataScopeCaptured) {
                  const std::string baseTitle = originalTitle.empty()
                      ? rlispstat::core::TitleForPlot(*model) : originalTitle;
                  model->title = baseTitle + " — " +
                      rlispstat::core::AnalysisScopeWindowSummary(
                          model->dataScope, model->dataScope.totalDatasetRows);
              }
          }
      }
      if (view) {
          [view setNeedsDisplay:YES];
          [view displayIfNeeded];
      }
      ok = SaveViewToPath(view, path, format);
      if (model) {
          model->title = originalTitle;
          [view setNeedsDisplay:YES];
      }
    };
    if ([NSThread isMainThread]) {
        saveBlock();
    } else {
        dispatch_sync(dispatch_get_main_queue(), saveBlock);
    }
    return ok;
}

static bool CopyPlotViewToPasteboardOnMain(const std::string &plotId, const std::string &format)
{
    __block BOOL ok = NO;
    void (^copyBlock)(void) = ^{
      NSView *view = nil;
      PlotModel *model = nullptr;
      std::string originalTitle;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          view = PlotViewForPlotUnlocked(plotId);
          auto found = g_plots.find(plotId);
          if (found != g_plots.end() && found->second) {
              model = found->second;
              originalTitle = model->title;
              if (model->dataScopeCaptured) {
                  const std::string baseTitle = originalTitle.empty()
                      ? rlispstat::core::TitleForPlot(*model) : originalTitle;
                  model->title = baseTitle + " — " +
                      rlispstat::core::AnalysisScopeWindowSummary(
                          model->dataScope, model->dataScope.totalDatasetRows);
              }
          }
      }
      if (!view) {
          if (model) model->title = originalTitle;
          return;
      }
      [view setNeedsDisplay:YES];
      [view displayIfNeeded];
      NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
      [pasteboard clearContents];
      if (format == "PDF") {
          NSData *data = VisualExportDataForView(view, @"PDF");
          ok = [pasteboard setData:data forType:NSPasteboardTypePDF];
      } else {
          NSData *data = VisualExportDataForView(view, @"PNG");
          ok = [pasteboard setData:data forType:NSPasteboardTypePNG];
      }
      if (model) {
          model->title = originalTitle;
          [view setNeedsDisplay:YES];
      }
    };
    if ([NSThread isMainThread]) {
        copyBlock();
    } else {
        dispatch_sync(dispatch_get_main_queue(), copyBlock);
    }
    return ok;
}

static bool QueuePlotSvgExportOnMain(const std::string &plotId,
                                     NSString *path,
                                     const std::string &operation)
{
    if (!path || [path length] == 0) return false;
    NSView *view = nil;
    PlotModel snapshot;
    bool hasModel = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        view = PlotViewForPlotUnlocked(plotId);
        auto found = g_plots.find(plotId);
        if (found != g_plots.end() && found->second) {
            snapshot = *found->second;
            hasModel = true;
        }
    }
    if (!view || !hasModel) return false;
    const NSSize size = [view bounds].size;
    const bool hasPortableEffectRenderer = snapshot.kind == "glm_interaction" ||
        snapshot.kind == "interaction_plot";
    if (hasPortableEffectRenderer) {
        // The estimates and confidence limits in this immutable snapshot were
        // computed by R.  Render those exact values directly so SVG export
        // cannot substitute a generic R plot with a different palette or
        // geometry merely because the requested output is vectorial.
        const std::string title = snapshot.title.empty()
            ? rlispstat::core::TitleForPlot(snapshot) : snapshot.title;
        const rlispstat::core::SvgTableDocument document =
            rlispstat::core::BuildSvgPlotSnapshotDocument(
                snapshot, MacCommandDispatcher().plotTheme(), title,
                static_cast<double>(size.width), static_cast<double>(size.height));
        const std::string source = ComposeSvgExportForView(view, document.svg);
        if (source.empty()) return false;
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        if (!data) return false;
        if (operation == "copy") {
            NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
            [pasteboard clearContents];
            const BOOL copied = [pasteboard setData:data forType:@"public.svg-image"];
            if (copied) {
                [pasteboard setString:ToNSString(source)
                              forType:NSPasteboardTypeString];
            }
            return copied == YES;
        }
        NSError *error = nil;
        return [data writeToFile:path options:NSDataWritingAtomic error:&error] == YES;
    }
    if (g_mainRNotifyPath.empty()) return false;
    const std::string requestId = "export_" +
        std::to_string(static_cast<long long>(time(nullptr))) + "_" +
        std::to_string(std::rand() % 1000000);
    MainRPlotExportTask task;
    task.requestId = requestId;
    task.plotId = plotId;
    task.path = std::string([path UTF8String]);
    task.format = "svg";
    task.operation = operation;
    task.widthInches = std::max(1.0, static_cast<double>(size.width) / 72.0);
    task.heightInches = std::max(1.0, static_cast<double>(size.height) / 72.0);
    task.group = snapshot.group;
    task.plotKind = snapshot.kind;
    task.xVariable = snapshot.xLabel;
    task.yVariable = snapshot.yLabel;
    task.title = snapshot.title;
    task.options.push_back({"theme", MacCommandDispatcher().plotTheme()});
    if (snapshot.dataScopeCaptured) {
        task.options.push_back({"analysis_scope",
            rlispstat::core::AnalysisScopeWindowSummary(
                snapshot.dataScope, snapshot.dataScope.totalDatasetRows)});
    }
    // Vector export intentionally excludes the transient linked selection.  It
    // does preserve analysis layers that describe the full displayed sample.
    task.options.push_back({"selection", "excluded"});
    task.options.push_back({"shade_overlap", snapshot.scatterShadeOverlap ? "TRUE" : "FALSE"});
    task.options.push_back({"size_by_overlap", snapshot.scatterSizeByOverlap ? "TRUE" : "FALSE"});
    const bool needsExactNativeGeometry = snapshot.kind == "pca_scree" ||
        snapshot.kind == "pca_biplot" || snapshot.kind == "glm_interaction" ||
        snapshot.kind == "interaction_plot" || snapshot.isGLMDiagnostic;
    auto exportNumber = [](double value) {
        std::ostringstream stream;
        stream << std::setprecision(17) << value;
        return stream.str();
    };
    if (needsExactNativeGeometry) {
        for (const DataPoint &point : snapshot.points) {
            task.options.push_back({"point", exportNumber(point.x) + "\x1f" +
                exportNumber(point.y) + "\x1f" + std::to_string(point.row)});
        }
        if (snapshot.points.empty()) {
            for (const HistogramPoint &point : snapshot.histogramPoints) {
                task.options.push_back({"point", exportNumber(point.x) + "\x1f" +
                    "0" + "\x1f" + std::to_string(point.row)});
            }
        }
        for (const DataPoint &point : snapshot.screeParallelPoints) {
            task.options.push_back({"parallel_point", exportNumber(point.x) + "\x1f" +
                exportNumber(point.y)});
        }
        for (const InteractionPlotLine &line : snapshot.interactionPlotLines) {
            for (const DataPoint &point : line.points) {
                task.options.push_back({"line_point", line.label + "\x1f" + line.colorKey +
                    "\x1f" + exportNumber(point.x) + "\x1f" + exportNumber(point.y)});
            }
        }
        if (snapshot.glmDiagnosticKind == "roc_curve") {
            for (const DataPoint &point : snapshot.rocStepPoints) {
                task.options.push_back({"line_point", std::string("ROC") + "\x1f" +
                    "black" + "\x1f" +
                    exportNumber(point.x) + "\x1f" + exportNumber(point.y)});
            }
        }
        for (const auto &tick : snapshot.interactionXTicks) {
            task.options.push_back({"x_tick", exportNumber(tick.first) + "\x1f" + tick.second});
        }
        if (snapshot.isGLMDiagnostic) {
            task.options.push_back({"diagnostic_kind", snapshot.glmDiagnosticKind});
        }
        for (const BiplotLoading &loading : snapshot.biplotLoadings) {
            task.options.push_back({"loading", loading.variable + "\x1f" +
                exportNumber(loading.x) + "\x1f" + exportNumber(loading.y)});
        }
    }
    const bool hasOverallLm = std::any_of(snapshot.overlays.begin(), snapshot.overlays.end(),
        [](const Overlay &overlay) {
            return overlay.visible && overlay.type == "lm" && overlay.source == "all";
        });
    if (hasOverallLm) task.options.push_back({"lm", "TRUE"});
    const bool hasOverallSmooth = std::any_of(snapshot.smoothCurves.begin(), snapshot.smoothCurves.end(),
        [](const SmoothCurveData &curve) {
            return curve.ok && curve.scope == SmoothCurveScope::Overall &&
                curve.x.size() >= 2 && curve.x.size() == curve.y.size();
        });
    if (hasOverallSmooth) {
        std::ostringstream span;
        span << std::setprecision(17) << snapshot.smoothSpan;
        task.options.push_back({"smooth", "TRUE"});
        task.options.push_back({"smooth_span", span.str()});
    }
    if (snapshot.kind == "scatter_matrix") {
        for (const std::string &variable : snapshot.scatterMatrixVariables) {
            task.options.push_back({"variable", variable});
        }
    }
    if (snapshot.kind == "time_series") {
        task.options.push_back({"series", snapshot.timeSeriesGroupVariable});
        task.options.push_back({"time_type", snapshot.timeSeriesTimeType});
        task.options.push_back({"identification", snapshot.timeSeriesIdentification});
        task.options.push_back({"legend_position", snapshot.timeSeriesLegendPosition});
    }
    if (snapshot.kind == "boxplot") {
        for (const std::string &variable : snapshot.boxplotVariables) {
            task.options.push_back({"variable", variable});
        }
        task.options.push_back({"standardize", snapshot.boxplotStandardizeVariables ? "TRUE" : "FALSE"});
        task.options.push_back({"connect_rows", snapshot.boxplotConnectRows ? "TRUE" : "FALSE"});
    }
    if (snapshot.kind == "barplot") {
        for (const std::string &variable : snapshot.barplotXVariables) {
            task.options.push_back({"variable", variable});
        }
        task.options.push_back({"split", snapshot.barplotSplitVariable});
        task.options.push_back({"bar_mode", snapshot.barplotMode});
        task.options.push_back({"bar_width", snapshot.barplotWidthMode});
    }
    if (snapshot.kind == "histogram") {
        for (std::size_t i = 0; i < snapshot.histogramBins.size(); ++i) {
            if (i == 0) {
                std::ostringstream lower;
                lower << std::setprecision(17) << snapshot.histogramBins[i].lower;
                task.options.push_back({"histogram_break", lower.str()});
            }
            std::ostringstream upper;
            upper << std::setprecision(17) << snapshot.histogramBins[i].upper;
            task.options.push_back({"histogram_break", upper.str()});
        }
        task.options.push_back({"histogram_bins", std::to_string(snapshot.histogramBins.size())});
        task.options.push_back({"show_density", snapshot.histogramShowDensity ? "TRUE" : "FALSE"});
        task.options.push_back({"density_mode", snapshot.histogramDensityMode});
        std::ostringstream bandwidth;
        std::ostringstream adjust;
        bandwidth << std::setprecision(17) << snapshot.histogramDensityBw;
        adjust << std::setprecision(17) << snapshot.histogramDensityAdjust;
        task.options.push_back({"density_bw", bandwidth.str()});
        task.options.push_back({"density_adjust", adjust.str()});
        task.options.push_back({"show_rug", snapshot.histogramShowRug ? "TRUE" : "FALSE"});
    }
    if (snapshot.kind == "trellis_scatterplot" && snapshot.trellisSpecificationInitialized) {
        task.options.push_back({"plot_type", rlispstat::core::TrellisPlotTypeName(snapshot.trellisSpecification.plotType)});
        task.options.push_back({"layout", snapshot.trellisSpecification.layoutMode});
        task.options.push_back({"scale_mode", snapshot.trellisSpecification.scaleMode});
        task.options.push_back({"grouping", snapshot.trellisSpecification.groupingVariableId});
        task.options.push_back({"split", snapshot.trellisSpecification.splitVariableId});
        task.options.push_back({"bar_measure", snapshot.trellisSpecification.barMeasure});
        task.options.push_back({"histogram_measure", snapshot.trellisSpecification.histogramMeasure});
        task.options.push_back({"histogram_bins", std::to_string(snapshot.trellisSpecification.histogramBinCount)});
        bool hasPanelSmooth = false;
        for (const auto &panel : snapshot.trellisPanelSmoothCurves) {
            hasPanelSmooth = hasPanelSmooth || std::any_of(panel.second.begin(), panel.second.end(),
                [](const SmoothCurveData &curve) {
                    return curve.ok && curve.scope == SmoothCurveScope::Overall &&
                        curve.x.size() >= 2 && curve.x.size() == curve.y.size();
                });
        }
        if (hasPanelSmooth) {
            std::ostringstream span;
            span << std::setprecision(17) << snapshot.smoothSpan;
            task.options.push_back({"smooth", "TRUE"});
            task.options.push_back({"smooth_span", span.str()});
        }
        for (const auto &condition : snapshot.trellisSpecification.conditioningVariables) {
            const std::string kind = condition.kind == TrellisConditioningVariableKind::ContinuousBinned
                ? "continuous" : "categorical";
            const std::string dimension = condition.dimension == TrellisDimension::Rows
                ? "rows" : (condition.dimension == TrellisDimension::Columns ? "columns" : "nested");
            std::string method = "equal_width";
            std::string bins = "4";
            if (condition.binning.has_value()) {
                method = condition.binning->method == TrellisContinuousBinningMethod::EqualCount
                    ? "equal_count" : "equal_width";
                bins = std::to_string(condition.binning->binCount);
            }
            task.options.push_back({"condition", condition.variableId + "\x1f" + kind + "\x1f" +
                dimension + "\x1f" + method + "\x1f" + bins});
        }
    }
    WindowNotesContainer *notes = WindowNotesContainerForView(view);
    if (notes) {
        const rlispstat::core::WindowExportComposition composition =
            rlispstat::core::BuildWindowExportComposition([notes noteSnapshot]);
        if (composition.note.has_value()) {
            std::lock_guard<std::mutex> lock(g_mutex);
            g_pendingPlotExportNotes[requestId] = *composition.note;
        }
    }
    QueuePlotExportMainRTask(task);
    return true;
}

static void SetSavePanelExtensionCompat(NSSavePanel *panel, NSString *extension)
{
    if (!panel || !extension) return;
    if (@available(macOS 11.0, *)) {
        UTType *type = [UTType typeWithFilenameExtension:extension];
        if (type) [panel setAllowedContentTypes:@[type]];
    } else {
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
        [panel setAllowedFileTypes:@[extension]];
#pragma clang diagnostic pop
    }
}

static bool QueuePlotSvgCopyOnMain(const std::string &plotId)
{
    NSString *filename = [NSString stringWithFormat:@"LinkEDA-%lld-%u.svg",
        static_cast<long long>(time(nullptr)), arc4random_uniform(1000000)];
    NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:filename];
    return QueuePlotSvgExportOnMain(plotId, path, "copy");
}

@interface MacTabularExportView : NSView
- (instancetype)initWithTitle:(NSString *)title tabDelimited:(NSString *)tabDelimited;
@end

@implementation MacTabularExportView {
    rlispstat::core::VectorTableLayout _layout;
}

- (instancetype)initWithTitle:(NSString *)title tabDelimited:(NSString *)tabDelimited
{
    const std::string titleText = title ? std::string([title UTF8String]) : std::string();
    const std::string tableText = tabDelimited ? std::string([tabDelimited UTF8String]) : std::string();
    const rlispstat::core::VectorTableLayout layout =
        rlispstat::core::BuildVectorTableLayout(titleText, tableText);
    self = [super initWithFrame:NSMakeRect(0, 0, layout.dimensions.widthPoints,
                                           layout.dimensions.heightPoints)];
    if (!self) return nil;
    _layout = layout;
    // This view is intentionally detached from a window. Keeping it
    // non-layer-backed makes dataWithPDFInsideRect: and bitmap export invoke
    // drawRect: reliably instead of capturing an uncommitted empty layer.
    [self setWantsLayer:NO];
    return self;
}

- (BOOL)isFlipped { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor whiteColor] setFill]; NSRectFill([self bounds]);
    const CGFloat logicalWidth = _layout.dimensions.widthPoints;
    const CGFloat logicalHeight = _layout.dimensions.heightPoints;
    const CGFloat scale = std::min(NSWidth([self bounds]) / logicalWidth,
                                   NSHeight([self bounds]) / logicalHeight);
    const CGFloat offsetX = (NSWidth([self bounds]) - logicalWidth * scale) * 0.5;
    const CGFloat offsetY = (NSHeight([self bounds]) - logicalHeight * scale) * 0.5;
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *transform = [NSAffineTransform transform];
    [transform translateXBy:offsetX yBy:offsetY];
    [transform scaleBy:scale];
    [transform concat];
    const CGFloat margin = _layout.margin;
    CGFloat y = margin;
    if (!_layout.title.empty()) {
        [ToNSString(_layout.title) drawAtPoint:NSMakePoint(margin, y)
            withAttributes:@{NSFontAttributeName: [NSFont systemFontOfSize:16 weight:NSFontWeightSemibold],
                             NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.08 alpha:1]}];
    }
    y = _layout.tableTop;
    const CGFloat available = logicalWidth - 2.0 * margin;
    [[NSColor colorWithCalibratedWhite:0.55 alpha:1] setStroke];
    NSBezierPath *topRule = [NSBezierPath bezierPath];
    [topRule moveToPoint:NSMakePoint(margin, y)];
    [topRule lineToPoint:NSMakePoint(logicalWidth - margin, y)];
    [topRule setLineWidth:0.8];
    [topRule stroke];
    for (std::size_t rowIndex = 0; rowIndex < _layout.rows.size(); ++rowIndex) {
        if (rowIndex == 0) {
            [[NSColor colorWithCalibratedWhite:0.95 alpha:1] setFill];
            NSRectFill(NSMakeRect(margin, y, available, _layout.rowHeight));
        }
        for (std::size_t column = 0; column < _layout.columnWidths.size(); ++column) {
            const CGFloat x = _layout.columnStarts[column];
            const CGFloat width = _layout.columnWidths[column];
            NSString *value = column < _layout.rows[rowIndex].size()
                ? ToNSString(_layout.rows[rowIndex][column]) : @"";
            NSMutableParagraphStyle *paragraph = [[NSMutableParagraphStyle alloc] init];
            [paragraph setLineBreakMode:NSLineBreakByTruncatingTail];
            [value drawInRect:NSMakeRect(x + 6.0, y + 5.0, std::max((CGFloat)0, width - 12.0), 16.0)
                withAttributes:@{NSFontAttributeName: [NSFont systemFontOfSize:11 weight:rowIndex == 0 ? NSFontWeightSemibold : NSFontWeightRegular],
                                 NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.10 alpha:1],
                                 NSParagraphStyleAttributeName: paragraph}];
        }
        if (rowIndex == 0 || rowIndex + 1 == _layout.rows.size()) {
            [[NSColor colorWithCalibratedWhite:0.55 alpha:1] setStroke];
            NSBezierPath *rule = [NSBezierPath bezierPath];
            [rule moveToPoint:NSMakePoint(margin, y + _layout.rowHeight)];
            [rule lineToPoint:NSMakePoint(logicalWidth - margin, y + 24.0)];
            [rule setLineWidth:0.8]; [rule stroke];
        }
        y += _layout.rowHeight;
    }
    [NSGraphicsContext restoreGraphicsState];
}
@end

// The platform only transports the frozen shared publication specification.
static NSData *PublicationTablePDFData(const rlispstat::core::PublicationTableSpec &table);
static NSData *PublicationTablesPDFData(const std::vector<rlispstat::core::PublicationTableSpec> &tables,
    const rlispstat::core::LatexPublicationOptions &options);

@interface MacVisualTableExportTarget : NSObject
- (instancetype)initWithView:(NSView *)view
                       title:(NSString *)title
                    baseName:(NSString *)baseName
                tabDelimited:(NSString *)tabDelimited;
- (void)setPublicationTable:(const rlispstat::core::PublicationTableSpec &)table;
- (void)setReportTables:(const std::vector<rlispstat::core::PublicationTableSpec> &)tables;
- (void)setAlternateReportTables:(const std::vector<rlispstat::core::PublicationTableSpec> &)tables;
- (void)setSeparateReportTables:(const std::vector<rlispstat::core::PublicationTableSpec> &)tables;
- (BOOL)requestAPADetails:(rlispstat::core::LatexPublicationOptions &)options
            useAlternate:(bool &)useAlternate
            separateFiles:(bool &)separateFiles
       allowSeparateFiles:(BOOL)allowSeparateFiles;
- (void)copyOfficeTable:(id)sender;
- (void)copyAPAOfficeTable:(id)sender;
- (void)saveAPAPDF:(id)sender;
- (void)copyVisualExport:(id)sender;
- (void)saveVisualExport:(id)sender;
@end

@implementation MacVisualTableExportTarget {
    std::optional<rlispstat::core::PublicationTableSpec> _publicationTable;
    std::vector<rlispstat::core::PublicationTableSpec> _reportTables;
    std::vector<rlispstat::core::PublicationTableSpec> _alternateReportTables;
    std::vector<rlispstat::core::PublicationTableSpec> _separateReportTables;
    NSView *_exportView;
    NSString *_exportTitle;
    NSString *_exportBaseName;
    NSString *_tabDelimited;
    WindowNotesContainer *_notesContainer;
}

- (instancetype)initWithView:(NSView *)view
                       title:(NSString *)title
                    baseName:(NSString *)baseName
                tabDelimited:(NSString *)tabDelimited
{
    self = [super init];
    if (!self) return nil;
    _exportView = [view retain];
    _exportTitle = [title copy] ?: @"Results";
    const std::string safe = rlispstat::core::SafeExportBaseName(
        baseName ? std::string([baseName UTF8String]) : std::string(), "LinkEDA-results");
    _exportBaseName = [ToNSString(safe) copy];
    _tabDelimited = [tabDelimited copy] ?: @"";
    _notesContainer = [ActiveWindowNotesContainer() retain];
    return self;
}

- (void)dealloc
{
    [_exportView release];
    [_exportTitle release];
    [_exportBaseName release];
    [_tabDelimited release];
    [_notesContainer release];
    [super dealloc];
}

- (void)setPublicationTable:(const rlispstat::core::PublicationTableSpec &)table
{
    _publicationTable = table;
}

- (void)setReportTables:(const std::vector<rlispstat::core::PublicationTableSpec> &)tables
{
    _reportTables = tables;
}

- (void)setAlternateReportTables:(const std::vector<rlispstat::core::PublicationTableSpec> &)tables
{
    _alternateReportTables = tables;
}

- (void)setSeparateReportTables:(const std::vector<rlispstat::core::PublicationTableSpec> &)tables
{
    _separateReportTables = tables;
}

- (NSData *)pdfData
{
    if (!_reportTables.empty()) {
        auto tables = _reportTables;
        if (_notesContainer) {
            const auto notes = rlispstat::core::BuildWindowExportComposition([_notesContainer noteSnapshot]);
            if (notes.note) tables.back().footnotes.push_back(notes.note->plain_text);
        }
        rlispstat::core::LatexPublicationOptions options; options.reportHeadings = true;
        return PublicationTablesPDFData(tables,options);
    }
    if (!_publicationTable)
        return VisualExportDataForViewWithNotes(_exportView, @"PDF", _notesContainer);
    auto table = *_publicationTable;
    if (_notesContainer) {
        const auto composition = rlispstat::core::BuildWindowExportComposition([_notesContainer noteSnapshot]);
        if (composition.note) table.footnotes.push_back(composition.note->plain_text);
    }
    return PublicationTablePDFData(table);
}

- (NSData *)pngData
{
    if (_reportTables.empty())
        return VisualExportDataForViewWithNotes(_exportView, @"PNG", _notesContainer);
    // Copy/save PNG follows the same compact report as the PDF clipboard.
    // The PDF is produced by the shared LaTeX renderer before rasterization.
    NSData *pdf = [self pdfData];
    if (!pdf) return nil;
    NSImage *image = [[[NSImage alloc] initWithData:pdf] autorelease];
    const NSSize size = [image size];
    if (size.width <= 0 || size.height <= 0) return nil;
    NSBitmapImageRep *bitmap = [[[NSBitmapImageRep alloc]
        initWithBitmapDataPlanes:NULL pixelsWide:(NSInteger)std::ceil(size.width * 2)
        pixelsHigh:(NSInteger)std::ceil(size.height * 2) bitsPerSample:8 samplesPerPixel:4
        hasAlpha:YES isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:0 bitsPerPixel:0] autorelease];
    if (!bitmap) return nil;
    [bitmap setSize:size];
    [NSGraphicsContext saveGraphicsState];
    [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithBitmapImageRep:bitmap]];
    [[NSColor whiteColor] setFill]; NSRectFill(NSMakeRect(0,0,size.width,size.height));
    [image drawInRect:NSMakeRect(0,0,size.width,size.height)];
    [NSGraphicsContext restoreGraphicsState];
    return [bitmap representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
}

- (NSData *)svgData
{
    const rlispstat::core::SvgTableDocument document = rlispstat::core::BuildSvgTableDocument(
        std::string([_exportTitle UTF8String]), std::string([_tabDelimited UTF8String]));
    if (document.svg.empty()) return nil;
    std::string source = ComposeSvgExportForView(_exportView, document.svg);
    if (!WindowNotesContainerForView(_exportView) && _notesContainer) {
        const auto composition = rlispstat::core::BuildWindowExportComposition([_notesContainer noteSnapshot]);
        if (composition.note.has_value()) source =
            rlispstat::core::ComposeSvgDocumentWithWindowNote(source, *composition.note);
    }
    return [NSData dataWithBytes:source.data() length:source.size()];
}

- (void)copyVisualExport:(id)sender
{
    const NSInteger tag = [sender tag];
    NSData *data = nil;
    NSPasteboardType type = nil;
    if (tag == 0) {
        data = [self pdfData];
        type = NSPasteboardTypePDF;
    } else if (tag == 1) {
        data = [self svgData];
        type = @"public.svg-image";
    } else if (tag == 2) {
        data = [self pngData];
        type = NSPasteboardTypePNG;
    }
    if (!data || !type) return;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setData:data forType:type];
}

- (BOOL)requestAPADetails:(rlispstat::core::LatexPublicationOptions &)options
            useAlternate:(bool &)useAlternate
            separateFiles:(bool &)separateFiles
       allowSeparateFiles:(BOOL)allowSeparateFiles
{
    if (!_publicationTable && _reportTables.empty()) return NO;
    NSAlert *details = [[NSAlert alloc] init];
    [details setMessageText:@"APA 7 table details"];
    [details setInformativeText:@"Enter the table number and title."];
    const bool offersSeparate = allowSeparateFiles && _separateReportTables.size() == 2;
    const CGFloat fieldHeight = 112 + (_alternateReportTables.empty() ? 0 : 60) +
        (offersSeparate ? 82 : 0);
    NSStackView *fields = [[NSStackView alloc] initWithFrame:NSMakeRect(0,0,420,fieldHeight)];
    fields.orientation = NSUserInterfaceLayoutOrientationVertical; fields.alignment = NSLayoutAttributeLeading;
    NSTextField *number = [NSTextField textFieldWithString:@"1"];
    NSTextField *title = [NSTextField textFieldWithString:ToNSString(
        rlispstat::core::PublicationTitleWithoutTableLabel([_exportTitle UTF8String]))];
    [number setFrameSize:NSMakeSize(420,24)]; [title setFrameSize:NSMakeSize(420,24)];
    for (NSView *field in @[[NSTextField labelWithString:@"Table number"],number,
                           [NSTextField labelWithString:@"Table title"],title]) [fields addArrangedSubview:field];
    NSPopUpButton *globalLayout = nil;
    if (!_alternateReportTables.empty()) {
        [fields addArrangedSubview:[NSTextField labelWithString:@"Scale-level results"]];
        globalLayout = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0,0,420,26) pullsDown:NO];
        [globalLayout addItemsWithTitles:@[@"Compact table above item results",
            @"Note below item results"]];
        [fields addArrangedSubview:globalLayout];
    }
    NSPopUpButton *dimensionalityLayout = nil;
    if (offersSeparate) {
        [fields addArrangedSubview:[NSTextField labelWithString:@"Dimensionality tables"]];
        dimensionalityLayout = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0,0,420,26) pullsDown:NO];
        [dimensionalityLayout addItemsWithTitles:@[@"One combined table in one PDF",
            @"Two tables in two PDF files"]];
        [fields addArrangedSubview:dimensionalityLayout];
        [fields addArrangedSubview:[NSTextField labelWithString:
            @"With two files, this is the first table number; the second follows it."]];
    }
    [details setAccessoryView:fields]; [details addButtonWithTitle:@"Export"]; [details addButtonWithTitle:@"Cancel"];
    if ([details runModal] != NSAlertFirstButtonReturn) return NO;
    options.apa7 = true;
    options.tableNumber = [[number stringValue] UTF8String]; options.title = [[title stringValue] UTF8String];
    useAlternate = globalLayout && [globalLayout indexOfSelectedItem] == 1;
    separateFiles = dimensionalityLayout && [dimensionalityLayout indexOfSelectedItem] == 1;
    return YES;
}

- (void)copyOfficeTable:(id)sender
{
    (void)sender;
    std::string html = "<html><head><meta charset=\"utf-8\"></head><body>";
    std::string plain;
    const auto append = [&](const rlispstat::core::PublicationTableSpec &table) {
        std::string fragment = rlispstat::core::BuildPublicationTableHtml(table);
        const std::size_t begin = fragment.find("<body>");
        const std::size_t end = fragment.rfind("</body>");
        html += begin == std::string::npos || end == std::string::npos
            ? fragment : fragment.substr(begin + 6, end - begin - 6);
        if (!plain.empty()) plain += "\n";
        if (!table.title.empty()) plain += table.title + "\n";
        plain += rlispstat::core::BuildPublicationTableTsv(table);
    };
    if (!_reportTables.empty()) for (const auto &table : _reportTables) append(table);
    else if (_publicationTable) append(*_publicationTable);
    else plain = std::string([_tabDelimited UTF8String]);
    html += "</body></html>";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString(plain) forType:NSPasteboardTypeString];
    [pasteboard setString:ToNSString(plain) forType:@"public.utf8-tab-separated-values-text"];
    if (!_reportTables.empty() || _publicationTable)
        [pasteboard setString:ToNSString(html) forType:NSPasteboardTypeHTML];
}

- (void)copyAPAOfficeTable:(id)sender
{
    (void)sender;
    rlispstat::core::LatexPublicationOptions options;
    bool useAlternate = false;
    bool separateFiles = false;
    if (![self requestAPADetails:options useAlternate:useAlternate
        separateFiles:separateFiles allowSeparateFiles:NO]) return;
    std::vector<rlispstat::core::PublicationTableSpec> tables =
        useAlternate ? _alternateReportTables : (!_reportTables.empty()
            ? _reportTables : (_publicationTable
                ? std::vector<rlispstat::core::PublicationTableSpec>{*_publicationTable}
                : std::vector<rlispstat::core::PublicationTableSpec>{}));
    std::string html = "<html><head><meta charset=\"utf-8\"></head><body>";
    std::string plain = "Table " + options.tableNumber + "\n" + options.title + "\n";
    for (std::size_t i = 0; i < tables.size(); ++i) {
        auto table = tables[i];
        if (_reportTables.empty() && _publicationTable) {
            table.title.clear();
            if (!table.subtitle.empty()) {
                table.footnotes.insert(table.footnotes.begin(), table.subtitle);
                table.subtitle.clear();
            }
        }
        const std::string fragment = rlispstat::core::BuildPublicationTableHtml(
            table, i == 0, options.tableNumber, options.title);
        const std::size_t begin = fragment.find("<body>");
        const std::size_t end = fragment.rfind("</body>");
        html += begin == std::string::npos || end == std::string::npos
            ? fragment : fragment.substr(begin + 6, end - begin - 6);
        if (i) plain += "\n";
        if (!table.title.empty()) plain += table.title + "\n";
        plain += rlispstat::core::BuildPublicationTableTsv(table);
        if (!table.footnotes.empty()) {
            plain += "Note. ";
            for (std::size_t j = 0; j < table.footnotes.size(); ++j) {
                if (j) plain += " ";
                plain += table.footnotes[j];
            }
            plain += "\n";
        }
    }
    html += "</body></html>";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString(plain) forType:NSPasteboardTypeString];
    [pasteboard setString:ToNSString(plain) forType:@"public.utf8-tab-separated-values-text"];
    [pasteboard setString:ToNSString(html) forType:NSPasteboardTypeHTML];
}

- (void)saveAPAPDF:(id)sender
{
    (void)sender;
    rlispstat::core::LatexPublicationOptions options;
    bool useAlternate = false;
    bool separateFiles = false;
    if (![self requestAPADetails:options useAlternate:useAlternate
        separateFiles:separateFiles allowSeparateFiles:YES]) return;
    if (separateFiles) {
        NSSavePanel *firstPanel = [NSSavePanel savePanel]; SetSavePanelExtensionCompat(firstPanel,@"pdf");
        NSString *firstSuffix = [NSString stringWithFormat:@"-%@_APA7.pdf",
            ToNSString(_separateReportTables[0].title)];
        [firstPanel setNameFieldStringValue:[_exportBaseName stringByAppendingString:firstSuffix]];
        if ([firstPanel runModal] != NSModalResponseOK) return;
        NSURL *firstURL = [[[firstPanel URL] copy] autorelease];
        NSSavePanel *secondPanel = [NSSavePanel savePanel]; SetSavePanelExtensionCompat(secondPanel,@"pdf");
        NSString *secondSuffix = [NSString stringWithFormat:@"-%@_APA7.pdf",
            ToNSString(_separateReportTables[1].title)];
        [secondPanel setNameFieldStringValue:[_exportBaseName stringByAppendingString:secondSuffix]];
        if ([secondPanel runModal] != NSModalResponseOK) return;
        NSURL *secondURL = [[[secondPanel URL] copy] autorelease];
        if ([[firstURL path] caseInsensitiveCompare:[secondURL path]] == NSOrderedSame) {
            ShowWorkbenchMessageOnMain(@"Export PDF", @"Choose two different PDF files for the dimensionality tables.");
            return;
        }
        auto firstTable = _separateReportTables[0];
        auto secondTable = _separateReportTables[1];
        if (_notesContainer) {
            const auto notes = rlispstat::core::BuildWindowExportComposition([_notesContainer noteSnapshot]);
            if (notes.note) {
                firstTable.footnotes.push_back(notes.note->plain_text);
                secondTable.footnotes.push_back(notes.note->plain_text);
            }
        }
        const auto followingNumber = [](const std::string &number) {
            if (!number.empty() && std::all_of(number.begin(), number.end(),
                [](unsigned char c) { return std::isdigit(c); })) {
                try { return std::to_string(std::stoull(number) + 1); } catch (...) {}
            }
            return number + "b";
        };
        const auto sectionTitle = [](const std::string &base,
                                     const rlispstat::core::PublicationTableSpec &table) {
            if (base.empty()) return table.title;
            if (table.title.empty()) return base;
            return base + ": " + table.title;
        };
        auto firstOptions = options;
        firstOptions.title = sectionTitle(options.title, firstTable);
        auto secondOptions = options;
        secondOptions.tableNumber = followingNumber(options.tableNumber);
        secondOptions.title = sectionTitle(options.title, secondTable);
        firstTable.title.clear();
        secondTable.title.clear();
        NSData *firstData = PublicationTablesPDFData({firstTable}, firstOptions);
        NSData *secondData = PublicationTablesPDFData({secondTable}, secondOptions);
        if (!firstData || !secondData) {
            ShowWorkbenchMessageOnMain(@"Export PDF", @"The two APA 7 PDFs could not be compiled.");
            return;
        }
        NSError *firstError = nil;
        NSError *secondError = nil;
        const BOOL firstWritten = [firstData writeToURL:firstURL options:NSDataWritingAtomic error:&firstError];
        const BOOL secondWritten = firstWritten &&
            [secondData writeToURL:secondURL options:NSDataWritingAtomic error:&secondError];
        if (!firstWritten || !secondWritten)
            ShowWorkbenchMessageOnMain(@"Export PDF", firstError ? [firstError localizedDescription] :
                (secondError ? [secondError localizedDescription] : @"The two PDFs could not both be written."));
        return;
    }
    NSSavePanel *panel = [NSSavePanel savePanel]; SetSavePanelExtensionCompat(panel,@"pdf");
    [panel setNameFieldStringValue:[_exportBaseName stringByAppendingString:@"_APA7.pdf"]];
    if ([panel runModal] != NSModalResponseOK) return;
    std::vector<rlispstat::core::PublicationTableSpec> tables =
        useAlternate ? _alternateReportTables : (!_reportTables.empty()
            ? _reportTables : (_publicationTable
                ? std::vector<rlispstat::core::PublicationTableSpec>{*_publicationTable}
                : std::vector<rlispstat::core::PublicationTableSpec>{}));
    if (_reportTables.empty() && _publicationTable) {
        tables.front().title.clear();
        if (!tables.front().subtitle.empty()) {
            tables.front().footnotes.insert(tables.front().footnotes.begin(), tables.front().subtitle);
            tables.front().subtitle.clear();
        }
    }
    if (_notesContainer) {
        const auto notes = rlispstat::core::BuildWindowExportComposition([_notesContainer noteSnapshot]);
        if (notes.note) tables.back().footnotes.push_back(notes.note->plain_text);
    }
    // APA uses the semantic publication table; ordinary report sections
    // belong only to the compact, as-displayed export.
    NSData *data = PublicationTablesPDFData(tables,options);
    NSError *error = nil;
    if (!data || ![data writeToURL:[panel URL] options:NSDataWritingAtomic error:&error])
        ShowWorkbenchMessageOnMain(@"Export PDF",error ? [error localizedDescription] : @"The PDF could not be written.");
}

- (void)saveVisualExport:(id)sender
{
    const NSInteger tag = [sender tag];
    NSString *extension = tag == 3 ? @"svg" : (tag == 4 ? @"pdf" : @"png");
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, extension);
    [panel setNameFieldStringValue:[_exportBaseName stringByAppendingPathExtension:extension]];
    if ([panel runModal] != NSModalResponseOK) return;
    NSData *data = tag == 3 ? [self svgData] :
        (tag == 4 ? [self pdfData] :
                    [self pngData]);
    NSError *error = nil;
    if (!data || ![data writeToURL:[panel URL] options:NSDataWritingAtomic error:&error]) {
        ShowWorkbenchMessageOnMain(@"Export", error ? [error localizedDescription] : @"The file could not be written.");
    }
}

@end

static void AddHistogramBinningMenuItems(NSMenu *menu, PlotModel *model)
{
    if (!model) return;
    const bool trellis = model->kind == "trellis_scatterplot";
    const std::size_t count = trellis ? model->trellisSpecification.histogramBinCount : model->histogramBins.size();
    auto add = [&](NSMenu *parent, const rlispstat::core::HistogramMenuOption &option) {
        const std::string command = trellis
            ? "TRELLIS_SCATTERPLOT_SET_HISTOGRAM_BINS" + (option.value.empty() ? "" : "|" + option.value)
            : option.command;
        NSMenuItem *item = PlotCommandMenuItem(ToNSString(option.title), ToNSString(command));
        [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
        [parent addItem:item];
    };
    NSMenuItem *rulesRoot = [[NSMenuItem alloc] initWithTitle:@"Automatic binning rule" action:nil keyEquivalent:@""];
    NSMenu *rules = [[NSMenu alloc] initWithTitle:@"Automatic binning rule"];
    for (const auto &option : rlispstat::core::HistogramBinningRuleMenuOptions()) add(rules, option);
    [rulesRoot setSubmenu:rules]; [menu addItem:rulesRoot];
    NSMenuItem *countsRoot = [[NSMenuItem alloc] initWithTitle:@"Number of bins" action:nil keyEquivalent:@""];
    NSMenu *counts = [[NSMenu alloc] initWithTitle:@"Number of bins"];
    for (const auto &option : rlispstat::core::HistogramBinCountMenuOptions(count)) add(counts, option);
    [counts addItem:[NSMenuItem separatorItem]];
    add(counts, {"Custom…", "", "HIST_SET_BINS"});
    [countsRoot setSubmenu:counts]; [menu addItem:countsRoot];
}

// Keep export actions in the same three places across report and plot windows.
// Existing menu items retain their targets, represented objects and actions.
static void OrganizeExportMenu(NSMenu *menu)
{
    if (!menu || [menu numberOfItems] == 0) return;
    NSMenu *copyMenu = [[[NSMenu alloc] initWithTitle:@"Copy"] autorelease];
    NSMenu *saveMenu = [[[NSMenu alloc] initWithTitle:@"Save"] autorelease];
    NSMenuItem *rCodeItem = nil;
    NSArray<NSMenuItem *> *items = [[menu itemArray] copy];
    [menu removeAllItems];
    for (NSMenuItem *item in items) {
        if ([item isSeparatorItem]) continue;
        NSString *title = [item title] ?: @"";
        if ([title isEqualToString:@"R Code"] && [item submenu]) {
            rCodeItem = item;
            continue;
        }
        NSString *actionName = [item action] ? NSStringFromSelector([item action]) : @"";
        NSMenu *destination = ([title hasPrefix:@"Copy"] ||
            [title containsString:@"— Copy"] ||
            [[actionName lowercaseString] hasPrefix:@"copy"])
            ? copyMenu : saveMenu;
        if (([title isEqualToString:@"Copy"] || [title isEqualToString:@"Save"]) &&
            [item submenu]) {
            NSMenu *source = [item submenu];
            NSArray<NSMenuItem *> *children = [[source itemArray] copy];
            for (NSMenuItem *child in children) {
                [source removeItem:child];
                if (![child isSeparatorItem]) [destination addItem:child];
            }
            [children release];
            continue;
        }
        if ([title isEqualToString:@"Copy PDF image"] ||
            [title isEqualToString:@"Copy as PDF"]) {
            [item setTitle:@"PDF image (vector)"];
            [item setToolTip:@"Copies the current appearance as a vector PDF image."];
        } else if ([title isEqualToString:@"PDF — As displayed…"]) {
            [item setTitle:@"PDF (as shown)…"];
            [item setToolTip:@"Saves the current window appearance as a PDF."];
        } else if ([title isEqualToString:@"PDF — APA 7 style…"]) {
            [item setTitle:@"PDF (APA 7 table)…"];
            [item setToolTip:@"Creates a publication table PDF using APA 7 formatting."];
        }
        [destination addItem:item];
    }
    if ([copyMenu numberOfItems]) {
        NSMenuItem *root = [[[NSMenuItem alloc] initWithTitle:@"Copy" action:nil keyEquivalent:@""] autorelease];
        [root setSubmenu:copyMenu];
        [menu addItem:root];
    }
    if ([saveMenu numberOfItems]) {
        NSMenuItem *root = [[[NSMenuItem alloc] initWithTitle:@"Save" action:nil keyEquivalent:@""] autorelease];
        [root setSubmenu:saveMenu];
        [menu addItem:root];
    }
    if (rCodeItem) [menu addItem:rCodeItem];
    [items release];
}

static void AddStandardTableVisualExportItems(NSMenu *menu,
                                              NSView *view,
                                              NSString *title,
                                              NSString *baseName,
                                              NSString *tabDelimited,
                                              const rlispstat::core::PublicationTableSpec *publicationTable = nullptr,
                                              const std::vector<rlispstat::core::PublicationTableSpec> *reportTables = nullptr,
                                              bool includePdfSave = true,
                                              bool includeApaPdf = true,
                                              const std::vector<rlispstat::core::PublicationTableSpec> *alternateReportTables = nullptr,
                                              const std::vector<rlispstat::core::PublicationTableSpec> *separateReportTables = nullptr)
{
    if (!menu || !tabDelimited) return;
    WindowNotesContainer *notes = ActiveWindowNotesContainer();
    if (notes) {
        NSMenuItem *includeNotes = PlotCommandMenuItem(@"Include Notes", @"NOTES_INCLUDE_EXPORT");
        [includeNotes setEnabled:[notes hasNotes]];
        [includeNotes setState:[notes includeNotes]
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:includeNotes];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    if (!view) view = [[[MacTabularExportView alloc] initWithTitle:title tabDelimited:tabDelimited] autorelease];
    MacVisualTableExportTarget *target = [[MacVisualTableExportTarget alloc]
        initWithView:view title:title baseName:baseName tabDelimited:tabDelimited];
    if (publicationTable) [target setPublicationTable:*publicationTable];
    if (reportTables) [target setReportTables:*reportTables];
    if (alternateReportTables) [target setAlternateReportTables:*alternateReportTables];
    if (separateReportTables) [target setSeparateReportTables:*separateReportTables];
    if (publicationTable || (reportTables && !reportTables->empty())) {
        NSMenuItem *copyTable = [[NSMenuItem alloc] initWithTitle:@"Copy formatted table"
            action:@selector(copyOfficeTable:) keyEquivalent:@""];
        [copyTable setToolTip:@"Copies the table as formatted HTML and tab-delimited cells for documents and spreadsheets."];
        [copyTable setTarget:target]; [copyTable setRepresentedObject:target]; [menu addItem:copyTable];
    }
    if (publicationTable || (reportTables && !reportTables->empty())) {
        NSMenuItem *copyAPA = [[NSMenuItem alloc] initWithTitle:@"Copy APA 7 table…"
            action:@selector(copyAPAOfficeTable:) keyEquivalent:@""];
        [copyAPA setToolTip:@"Asks for the table number and title, then copies the APA 7 table."];
        [copyAPA setTarget:target]; [copyAPA setRepresentedObject:target]; [menu addItem:copyAPA];
    }
    if (publicationTable || (reportTables && !reportTables->empty()))
        [menu addItem:[NSMenuItem separatorItem]];
    const auto actions = rlispstat::core::BuildExportMenuActions(
        rlispstat::core::StandardVisualExportCapabilities(rlispstat::core::ExportPlatform::MacOS),
        rlispstat::core::ExportPlatform::MacOS);
    for (const auto &action : actions) {
        if (action.separatorBefore) [menu addItem:[NSMenuItem separatorItem]];
        const bool copy = action.capability == rlispstat::core::ExportCapability::CopyPdf ||
            action.capability == rlispstat::core::ExportCapability::CopySvg ||
            action.capability == rlispstat::core::ExportCapability::CopyPng;
        NSInteger tag = -1;
        if (action.capability == rlispstat::core::ExportCapability::CopyPdf) tag = 0;
        else if (action.capability == rlispstat::core::ExportCapability::CopySvg) tag = 1;
        else if (action.capability == rlispstat::core::ExportCapability::CopyPng) tag = 2;
        else if (action.capability == rlispstat::core::ExportCapability::SaveSvg) tag = 3;
        else if (action.capability == rlispstat::core::ExportCapability::SavePdf) tag = 4;
        else if (action.capability == rlispstat::core::ExportCapability::SavePng) tag = 5;
        if (tag < 0 || (tag == 4 && !includePdfSave)) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(action.title)
            action:(copy ? @selector(copyVisualExport:) : @selector(saveVisualExport:)) keyEquivalent:@""];
        if ((publicationTable || reportTables) &&
            action.capability == rlispstat::core::ExportCapability::SavePdf)
            [item setTitle:@"PDF — As displayed…"];
        if (action.capability == rlispstat::core::ExportCapability::CopyPdf)
            [item setTitle:@"Copy PDF image"];
        [item setTarget:target];
        [item setTag:tag];
        // NSMenuItem retains representedObject even though its target is non-owning.
        [item setRepresentedObject:target];
        [menu addItem:item];
    }
    if (includeApaPdf && (publicationTable || (reportTables && !reportTables->empty()))) {
        NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(saveAPAPDF:) keyEquivalent:@""];
        [apa setTarget:target]; [apa setRepresentedObject:target]; [menu addItem:apa];
    }
    [target release];
    OrganizeExportMenu(menu);
}

static void AddRCodeExportItems(NSMenu *exportMenu,
                                const std::string &objectKind,
                                const std::string &objectId,
                                bool hasPublicationCode,
                                const std::string &column = {})
{
    if (!exportMenu || objectId.empty()) return;
    const auto actions = rlispstat::core::BuildRCodeExportMenuActions(
        true, hasPublicationCode);
    if (actions.empty()) return;
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"R Code"
        action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:@"R Code"];
    for (const auto &action : actions) {
        std::string command = action.command;
        if (action.capability == rlispstat::core::ExportCapability::ShowRCode) {
            command += "|" + objectKind + "|" + objectId;
            if (!column.empty()) command += "|" + column;
        } else {
            command += "|" + objectId;
        }
        [submenu addItem:PlotCommandMenuItem(
            ToNSString(action.title), ToNSString(command))];
    }
    [root setSubmenu:submenu];
    if ([exportMenu numberOfItems] > 0) [exportMenu addItem:[NSMenuItem separatorItem]];
    [exportMenu addItem:root];
    OrganizeExportMenu(exportMenu);
}

// Result tables use one shared entry point for the common visual and R-code
// export surface. Some older analyses do not yet publish an output-code
// reference; keeping the command visible is intentional in that case because
// the central dispatcher reports the limitation explicitly instead of making
// the R Code category disappear from otherwise equivalent result tables.
static void AddStandardResultTableExportMenu(NSMenu *menu,
                                             NSView *view,
                                             NSString *title,
                                             NSString *baseName,
                                             NSString *tabDelimited,
                                             const std::string &outputId,
                                             bool hasPublicationCode = true)
{
    if (!menu) return;
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export"
        action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(
        exportMenu, view, title, baseName, tabDelimited ?: @"");
    AddRCodeExportItems(
        exportMenu, "output", outputId, hasPublicationCode);
    [root setSubmenu:exportMenu];
    [menu addItem:root];
}

static void ShowPlotExportSavePanelOnMain(const std::string &plotId, const std::string &format)
{
    std::string plotIdCopy = plotId;
    std::string formatCopy = format;
    void (^showPanel)(void) = ^{
      NSString *extension = ToNSString(rlispstat::core::PlotExportFileExtension(formatCopy));
      NSSavePanel *panel = [NSSavePanel savePanel];
      [panel setTitle:ToNSString(rlispstat::core::PlotExportPanelTitle(formatCopy))];
      [panel setNameFieldStringValue:ToNSString(rlispstat::core::PlotExportFilename(plotIdCopy, formatCopy))];
      SetSavePanelExtensionCompat(panel, extension);
      [NSApp activateIgnoringOtherApps:YES];
      if ([panel runModal] != NSModalResponseOK) return;
      if (formatCopy == "SVG") {
          if (!QueuePlotSvgExportOnMain(plotIdCopy, [panel URL].path, "save")) {
              ShowWorkbenchMessageOnMain(ToNSString(PlotExportFailedTitle()),
                                         @"The SVG could not be generated from the current plot.");
          }
          return;
      }
      if (!SavePlotViewToPathOnMain(plotIdCopy, [panel URL].path, formatCopy)) {
          ShowWorkbenchMessageOnMain(ToNSString(PlotExportFailedTitle()),
                                     ToNSString(PlotExportFailedStatus()));
      }
    };
    // Menu actions already run on AppKit's main thread.  Show the panel there
    // immediately: deferring a modal panel through the GCD main queue can
    // leave embedded R/AppKit event loops with no visible response.
    if ([NSThread isMainThread]) showPanel();
    else dispatch_async(dispatch_get_main_queue(), showPanel);
}

static PlotModel *ActivePlot()
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto it = g_plots.find(g_activePlotId);
    if (it != g_plots.end()) {
        return it->second;
    }
    PlotModel *datasetSeed = ActiveDatasetSeedPlotUnlocked();
    if (datasetSeed) {
        return datasetSeed;
    }
    if (!g_plots.empty()) {
        return g_plots.begin()->second;
    }
    return nullptr;
}

static PlotModel *ActiveDatasetCommandModel(PlotModel *fallback)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    PlotModel *seed = ActiveDatasetSeedPlotUnlocked();
    return seed ? seed : fallback;
}

static std::string PlotWindowTitleWithAnalysisScope(const PlotModel &model)
{
    std::string title = rlispstat::core::TitleForPlot(model);
    if (model.dataScopeCaptured) {
        title += " — " + rlispstat::core::AnalysisScopeWindowSummary(
            model.dataScope, model.dataScope.totalDatasetRows);
    }
    if (model.analysisScopeFrozen) title += " — Frozen";
    return title;
}

static void UpdateWindowTitleOnMain(PlotModel *model)
{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!model) {
          return;
      }
      std::lock_guard<std::mutex> lock(g_mutex);
      const std::string title = PlotWindowTitleWithAnalysisScope(*model);
      SetPlotWindowTitleUnlocked(model->id, title);
    });
}

static void UpdateWindowTitleForPlotOnMain(const std::string &plotId)
{
    std::string plotIdCopy = plotId;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::lock_guard<std::mutex> lock(g_mutex);
      auto modelIt = g_plots.find(plotIdCopy);
      if (modelIt == g_plots.end() || !modelIt->second) {
          return;
      }
      PlotModel *model = modelIt->second;
      const std::string title = PlotWindowTitleWithAnalysisScope(*model);
      SetPlotWindowTitleUnlocked(plotIdCopy, title);
    });
}

static void SetActivePlotOnMain(PlotModel *model)
{
    if (!model) {
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)MacPlotCoordinator().activatePlot(model->id);
        MarkActiveDatasetGroupUnlocked(
            MacCommandDispatcher().applicationState().dataSheetGroupForPlotGroup(model->group));
    }
    UpdateActiveDatasetMenuOnMain();
    UpdatePanelOnMain();
}

static std::vector<NSWindow *> VisibleResultTabBarRepresentatives()
{
    std::vector<NSWindow *> result;
    NSMutableSet *seenGroups = [NSMutableSet set];
    for (NSWindow *window in [NSApp orderedWindows]) {
        if (![window isVisible] ||
            ![[window tabbingIdentifier] isEqualToString:@"LinkEDA.Results"]) continue;
        NSWindowTabGroup *group = [window tabGroup];
        if (group && [seenGroups containsObject:group]) continue;
        if (group) [seenGroups addObject:group];
        result.push_back(window);
    }
    return result;
}

static void RemoveNativeSingleWindowTabBarItem(NSMenu *menu)
{
    if (!menu) return;
    for (NSInteger index = [menu numberOfItems] - 1; index >= 0; --index) {
        NSMenuItem *item = [menu itemAtIndex:index];
        if ([item action] == @selector(toggleTabBar:)) [menu removeItemAtIndex:index];
    }
}

@interface CommandTarget : NSObject <NSMenuDelegate>
- (void)runCommand:(id)sender;
- (BOOL)validateMenuItem:(NSMenuItem *)menuItem;
@end

@implementation CommandTarget
- (void)runCommand:(id)sender
{
    NSString *command = nil;
    if ([sender respondsToSelector:@selector(representedObject)]) {
        command = [sender representedObject];
    }
    if (!command && [sender respondsToSelector:@selector(identifier)]) {
        command = [sender identifier];
    }
    if (!command) {
        return;
    }
    if ([command isEqualToString:@"FILE_IMPORT_DATA"]) {
        // This command must work even before a plot or dataset exists.
        ShowImportChooserOnMain();
        return;
    }
    if ([command isEqualToString:@"FILE_EXPORT_DATA"]) {
        ShowExportDataChooserOnMain();
        return;
    }
    if ([command isEqualToString:@"FILE_CLOSE_DATASET"]) {
        std::string group;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
        }
        CloseDatasetAndAnalysesOnMain(group);
        return;
    }
    if ([command isEqualToString:@"WELCOME_SHOW"]) {
        ShowWelcomeOnMain();
        return;
    }
    if ([command isEqualToString:@"WELCOME_DOCUMENTATION"]) {
        OpenWelcomeDocumentationOnMain();
        return;
    }
    if ([command isEqualToString:@"WELCOME_ABOUT"]) {
        ShowAboutLinkEDAOnMain();
        return;
    }
    if ([command isEqualToString:@"NOTES_TOGGLE"]) {
        [ActiveWindowNotesContainer() toggleNotes];
        return;
    }
    if ([command isEqualToString:@"NOTES_CLEAR"]) {
        [ActiveWindowNotesContainer() clearNotesWithConfirmation];
        return;
    }
    if ([command isEqualToString:@"NOTES_INCLUDE_EXPORT"]) {
        [ActiveWindowNotesContainer() toggleIncludeNotes];
        return;
    }
    if ([command isEqualToString:@"NOTES_ADD_STICKY"]) {
        [ActiveWindowNotesContainer() addStickyNote];
        return;
    }
    if ([command isEqualToString:@"SHOW_ANALYSIS_SCOPE_PANEL"]) {
        ShowAnalysisScopePanelOnMain();
        return;
    }
    if ([command isEqualToString:@"SNAPSHOT_ALBUM_SHOW"]) {
        ShowSnapshotAlbumOnMain();
        return;
    }
    if ([command isEqualToString:@"SNAPSHOT_ALBUM_ADD_ACTIVE"]) {
        AddActiveWindowToSnapshotAlbumOnMain();
        return;
    }
    if ([command isEqualToString:@"WINDOW_TOGGLE_ALL_TAB_BARS"]) {
        std::vector<NSWindow *> windows = VisibleResultTabBarRepresentatives();
        const BOOL shouldShow = std::any_of(windows.begin(), windows.end(), [](NSWindow *window) {
            return [window tabbedWindows] == nil;
        });
        for (NSWindow *window : windows) {
            const BOOL visible = [window tabbedWindows] != nil;
            if (shouldShow == visible) continue;
            if (shouldShow) [window setTabbingMode:NSWindowTabbingModeAutomatic];
            [window toggleTabBar:sender];
        }
        return;
    }
    if ([command isEqualToString:@"WINDOW_MERGE_ALL"]) {
        NSWindow *window = [NSApp keyWindow];
        if (!window || ![[window tabbingIdentifier] isEqualToString:@"LinkEDA.Results"]) return;
        for (NSWindow *candidate in [NSApp windows]) {
            if ([candidate isVisible] &&
                [[candidate tabbingIdentifier] isEqualToString:@"LinkEDA.Results"])
                [candidate setTabbingMode:NSWindowTabbingModeAutomatic];
        }
        [window mergeAllWindows:sender];
        return;
    }
    PlotModel *model = ActivePlot();
    DispatchCommand(model, std::string([command UTF8String]));
}

- (void)menuNeedsUpdate:(NSMenu *)menu
{
    RemoveNativeSingleWindowTabBarItem(menu);
}

- (BOOL)validateMenuItem:(NSMenuItem *)menuItem
{
    NSString *command = [menuItem representedObject];
    if ([command isKindOfClass:[NSString class]] &&
        ([command hasPrefix:@"DATA_IMPUTATION_DIAGNOSTICS"] || [command isEqualToString:@"DATA_MISSING_DATA_OVERVIEW"] ||
         [command isEqualToString:@"DATA_MISSINGNESS_MODELS"] || [command isEqualToString:@"ANALYZE_MISSING_DATA_IMPUTATION"])) {
        std::lock_guard<std::mutex> lock(g_mutex);
        NSArray* parts=[command componentsSeparatedByString:@"|"];
        const auto group=[parts count]>1?std::string([parts[1] UTF8String]):ActiveDatasetGroupUnlocked();
        const auto* data=FindDataFrameUnlockedConst(group);if(!data)return NO;
        const auto c=rlispstat::core::MissingDataCapabilitiesFor(*data);
        if([command hasPrefix:@"DATA_IMPUTATION_DIAGNOSTICS"])return c.diagnostics;
        if([command isEqualToString:@"DATA_MISSINGNESS_MODELS"]) {
            [menuItem setToolTip:c.models ? nil : ToNSString(c.modelsUnavailableReason)];
            return c.models;
        }
        if([command isEqualToString:@"ANALYZE_MISSING_DATA_IMPUTATION"])return c.imputation;
        return c.overview;
    }
    if ([command isEqualToString:@"NOTES_TOGGLE"]) {
        WindowNotesContainer *notes = ActiveWindowNotesContainer();
        const BOOL visible = notes && [notes notesVisible];
        NSString *title = visible ? @"Hide Notes" :
            ((notes && [notes hasPanelNote]) ? @"Show Notes •" : @"Show Notes");
        [menuItem setTitle:title];
        [menuItem setState:visible ? NSControlStateValueOn : NSControlStateValueOff];
        return notes != nil;
    }
    if ([command isEqualToString:@"NOTES_CLEAR"]) {
        WindowNotesContainer *notes = ActiveWindowNotesContainer();
        return notes != nil && [notes hasPanelNote];
    }
    if ([command isEqualToString:@"NOTES_INCLUDE_EXPORT"]) {
        WindowNotesContainer *notes = ActiveWindowNotesContainer();
        [menuItem setState:(notes && [notes includeNotes])
            ? NSControlStateValueOn : NSControlStateValueOff];
        return notes != nil && [notes hasNotes];
    }
    if ([command isEqualToString:@"NOTES_ADD_STICKY"]) {
        return ActiveWindowNotesContainer() != nil;
    }
    if ([command isEqualToString:@"SNAPSHOT_ALBUM_SHOW"]) {
        [menuItem setState:SnapshotAlbumIsVisible()
            ? NSControlStateValueOn : NSControlStateValueOff];
        return YES;
    }
    if ([command isEqualToString:@"FILE_EXPORT_DATA"] ||
        [command isEqualToString:@"FILE_CLOSE_DATASET"]) {
        std::lock_guard<std::mutex> lock(g_mutex);
        const std::string group = ActiveDatasetGroupUnlocked();
        return !group.empty() && FindDataFrameUnlockedConst(group) != nullptr;
    }
    if ([command isEqualToString:@"SNAPSHOT_ALBUM_ADD_ACTIVE"])
        // Keep the fallback action available; capture itself validates the
        // current window and explains unsupported result types.  The primary
        // interaction remains dragging from the window tab.
        return YES;
    if ([command isEqualToString:@"WINDOW_TOGGLE_ALL_TAB_BARS"]) {
        std::vector<NSWindow *> windows = VisibleResultTabBarRepresentatives();
        const BOOL shouldShow = std::any_of(windows.begin(), windows.end(), [](NSWindow *window) {
            return [window tabbedWindows] == nil;
        });
        [menuItem setTitle:shouldShow ? @"Show Tab Bars" : @"Hide Tab Bars"];
        return !windows.empty();
    }
    if ([command isEqualToString:@"WINDOW_MERGE_ALL"]) {
        NSWindow *window = [NSApp keyWindow];
        if (!window || ![[window tabbingIdentifier] isEqualToString:@"LinkEDA.Results"])
            return NO;
        for (NSWindow *candidate in [NSApp orderedWindows]) {
            if (candidate != window && [candidate isVisible] &&
                [[candidate tabbingIdentifier] isEqualToString:@"LinkEDA.Results"])
                return YES;
        }
        return NO;
    }
    if ([command hasPrefix:@"PLOT_THEME|"]) {
        NSString *selectedTheme = [command substringFromIndex:[@"PLOT_THEME|" length]];
        [menuItem setState:[selectedTheme isEqualToString:ToNSString(MacCommandDispatcher().plotTheme())]
            ? NSControlStateValueOn : NSControlStateValueOff];
        return YES;
    }
    if ([command isEqualToString:@"SET_ANALYSIS_SCOPE_FROM_SELECTION"] ||
        [command isEqualToString:@"SET_ANALYSIS_SCOPE_ALL"]) {
        std::lock_guard<std::mutex> lock(g_mutex);
        const std::string group = ActiveDatasetGroupUnlocked();
        if (group.empty()) return NO;
        const rlispstat::core::AnalysisScope scope =
            MacCommandDispatcher().applicationState().activeAnalysisScope(group);
        [menuItem setState:([command isEqualToString:@"SET_ANALYSIS_SCOPE_ALL"] &&
                            scope.kind == rlispstat::core::AnalysisScopeKind::AllObservations)
            ? NSControlStateValueOn : NSControlStateValueOff];
        if ([command isEqualToString:@"SET_ANALYSIS_SCOPE_FROM_SELECTION"]) {
            auto selected = g_groupSelections.find(group);
            return selected != g_groupSelections.end() && !selected->second.empty();
        }
        return YES;
    }
    if ([command isEqualToString:@"FILE_OPEN_DATA_FROM_R"]) {
        return !g_mainRNotifyPath.empty();
    }
    if (![command hasPrefix:@"FILE_RETURN_"] &&
        ![command isEqualToString:@"FILE_CANCEL_DATA_RETURN"]) {
        return YES;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const std::string group = ActiveDatasetGroupUnlocked();
    const bool editSession = !group.empty() &&
        g_rEditSessionsByGroup.find(group) != g_rEditSessionsByGroup.end();
    if ([command isEqualToString:@"FILE_CANCEL_DATA_RETURN"]) return editSession;
    return !group.empty() && (editSession || !g_mainRNotifyPath.empty());
}
@end

static NSMenuItem *ApplicationMenuItem(NSString *title, NSString *command, NSString *key, NSEventModifierFlags modifiers)
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:key];
    [item setTarget:g_commandTarget];
    [item setRepresentedObject:command];
    if ([key length] > 0) {
        [item setKeyEquivalentModifierMask:modifiers];
    }
    return item;
}

static NSMenuItem *PlotCommandMenuItem(NSString *title, NSString *command)
{
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:@""];
    [item setTarget:g_commandTarget];
    [item setRepresentedObject:command];
    return item;
}

static NSMenuItem *ImputationDiagnosticsMenuItem(const std::string &group)
{
    NSMenuItem *root=[[NSMenuItem alloc] initWithTitle:@"Imputation diagnostics" action:nil keyEquivalent:@""];
    NSMenu *menu=[[NSMenu alloc] initWithTitle:@"Imputation diagnostics"];
    for (const auto &section : std::vector<std::pair<std::string,std::string>>{
        {"summary","Missingness summary"},{"variables","Missingness by variable"},{"patterns","Missing-data patterns"},
        {"patterns_all","Show all patterns"},{"model","Imputation model"},{"events","Logged events"},
        {"convergence","Convergence summary"}})
        [menu addItem:PlotCommandMenuItem(ToNSString(section.second),ToNSString("DATA_IMPUTATION_DIAGNOSTICS|"+group+"|"+section.first))];
    DataFrameModel dataframe;
    {std::lock_guard<std::mutex> lock(g_mutex);const auto* source=FindDataFrameUnlockedConst(group);if(source)dataframe=*source;}
    for (const auto &section : std::vector<std::pair<std::string,std::string>>{{"chain_mean","Chain means"},{"chain_variance","Chain variances"},{"distributions","Observed vs imputed"}}) {
        NSMenuItem *item=[[NSMenuItem alloc] initWithTitle:ToNSString(section.second) action:nil keyEquivalent:@""];
        NSMenu *variables=[[NSMenu alloc] initWithTitle:ToNSString(section.second)];
        for (const auto& column:dataframe.columns) [variables addItem:PlotCommandMenuItem(ToNSString(column.name),ToNSString("DATA_IMPUTATION_DIAGNOSTICS|"+group+"|"+section.first+"|"+column.name))];
        [item setSubmenu:variables];[menu addItem:item];
    }
    [root setSubmenu:menu];return root;
}
static void AddMissingInformationMenu(NSMenu *menu, const std::string &id)
{
    if (!menu) return;
    NSMenuItem *previous = [menu itemWithTitle:@"Multiple imputation"];
    if (previous) [menu removeItem:previous];
    const auto* output=MacCommandDispatcher().applicationState().outputCodeReference(id);
    if(!output || output->provenance.missingInformationRows.empty())return;
    NSMenuItem *root=[[NSMenuItem alloc] initWithTitle:@"Multiple imputation" action:nil keyEquivalent:@""];
    NSMenu *options=[[NSMenu alloc] initWithTitle:@"Multiple imputation"];
    [options addItem:PlotCommandMenuItem(@"Show missing-information diagnostics",ToNSString("SHOW_MISSING_INFORMATION|"+id))];
    [root setSubmenu:options];[menu addItem:root];
}

static NSMenuItem *ColorByVariableMenuItem(PlotModel *model)
{
    if (!model) return nil;
    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(model->group);
        if (!found) return nil;
        dataframe = *found;
    }
    const auto activeOverride =
        MacCommandDispatcher().applicationState().colorOverride(model->group);
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Colors" action:nil keyEquivalent:@""];
    NSMenu *colors = [[NSMenu alloc] initWithTitle:@"Colors"];
    NSMenuItem *status = [[NSMenuItem alloc]
        initWithTitle:activeOverride
            ? [NSString stringWithFormat:@"Colors: Override by %s", activeOverride->variable.c_str()]
            : @"Colors: Persistent case colors"
        action:nil keyEquivalent:@""];
    [status setEnabled:NO];
    [colors addItem:status];
    [colors addItem:[NSMenuItem separatorItem]];
    NSMenuItem *overrideRoot = [[NSMenuItem alloc] initWithTitle:@"Override colors by" action:nil keyEquivalent:@""];
    NSMenu *choices = [[NSMenu alloc] initWithTitle:@"Override colors by"];
    NSMenuItem *none = PlotCommandMenuItem(@"Cancel color override", @"PLOT_COLOR_BY|.");
    [none setState:!activeOverride
        ? NSControlStateValueOn : NSControlStateValueOff];
    [choices addItem:none];
    [choices addItem:[NSMenuItem separatorItem]];
    for (const DataColumn &column : dataframe.columns) {
        const bool displayed = column.name == model->xLabel || column.name == model->yLabel ||
            std::find(model->scatterMatrixVariables.begin(), model->scatterMatrixVariables.end(),
                column.name) != model->scatterMatrixVariables.end() ||
            std::find(model->boxplotVariables.begin(), model->boxplotVariables.end(),
                column.name) != model->boxplotVariables.end() ||
            std::find(model->barplotXVariables.begin(), model->barplotXVariables.end(),
                column.name) != model->barplotXVariables.end() ||
            column.name == model->barplotSplitVariable;
        if (displayed || !rlispstat::core::TrellisConditionColumnIsValid(column, dataframe.rows)) continue;
        NSMenuItem *item = PlotCommandMenuItem(ToNSString(column.name),
            ToNSString("PLOT_COLOR_BY|" + column.name));
        [item setState:activeOverride && activeOverride->variable == column.name
            ? NSControlStateValueOn : NSControlStateValueOff];
        [choices addItem:item];
    }
    [overrideRoot setSubmenu:choices];
    [colors addItem:overrideRoot];
    [colors addItem:[NSMenuItem separatorItem]];
    [colors addItem:PlotCommandMenuItem(@"Save current colors as scheme…", @"SAVE_COLOR_SCHEME")];
    const auto schemes = MacCommandDispatcher().applicationState().colorSchemes(model->group);
    NSMenuItem *applyRoot = [[NSMenuItem alloc] initWithTitle:@"Apply color scheme" action:nil keyEquivalent:@""];
    NSMenu *applyMenu = [[NSMenu alloc] initWithTitle:@"Apply color scheme"];
    if (schemes.empty()) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:@"No saved schemes" action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [applyMenu addItem:empty];
    } else {
        for (const auto &scheme : schemes)
            [applyMenu addItem:PlotCommandMenuItem(ToNSString(scheme.name),
                ToNSString("APPLY_COLOR_SCHEME|" + scheme.name))];
    }
    [applyRoot setSubmenu:applyMenu];
    [colors addItem:applyRoot];
    [root setSubmenu:colors];
    return root;
}

