             {"top_left", @"Top left"}, {"top_right", @"Top right"},
             {"bottom_left", @"Bottom left"}, {"bottom_right", @"Bottom right"}}) {
        [menu addItem:PlotCommandMenuItem(position.second,
            ToNSString("PLOT_COLOR_LEGEND_POSITION|" + position.first))];
    }
    [root setSubmenu:menu];
    return root;
}

static void AddMenuGroupWithoutRedundantSingleLevel(NSMenu *parent,
                                                     NSMenuItem *group,
                                                     NSMenu *contents)
{
    const NSInteger count = [contents numberOfItems];
    if (count == 0) return;
    if (count == 1) {
        NSMenuItem *onlyItem = [contents itemAtIndex:0];
        [onlyItem retain];
        [contents removeItem:onlyItem];
        [parent addItem:onlyItem];
        [onlyItem release];
        return;
    }
    [group setSubmenu:contents];
    [parent addItem:group];
}

static NSMenuItem *ConditioningVariablesMenuItem(PlotModel *model)
{
    if (!model) return nil;
    const bool supported = model->kind == "scatter" || model->kind == "time_series" ||
        model->kind == "histogram" ||
        (model->kind == "barplot" && model->barplotXVariables.size() <= 1) ||
        (model->kind == "boxplot" && !BoxplotUsesVariableAxes(model));
    if (!supported) return nil;
    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(model->group);
        if (!found) return nil;
        dataframe = *found;
    }
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Conditioning variables"
        action:nil keyEquivalent:@""];
    NSMenu *conditions = [[NSMenu alloc] initWithTitle:@"Conditioning variables"];
    NSMenuItem *addRoot = [[NSMenuItem alloc] initWithTitle:@"Add conditioning variable"
        action:nil keyEquivalent:@""];
    NSMenu *add = [[NSMenu alloc] initWithTitle:@"Add conditioning variable"];
    NSMenuItem *categoricalRoot = [[NSMenuItem alloc] initWithTitle:@"Categorical"
        action:nil keyEquivalent:@""];
    NSMenu *categorical = [[NSMenu alloc] initWithTitle:@"Categorical"];
    NSMenuItem *numericRoot = [[NSMenuItem alloc] initWithTitle:@"Numeric"
        action:nil keyEquivalent:@""];
    NSMenu *numeric = [[NSMenu alloc] initWithTitle:@"Numeric"];
    for (const DataColumn &column : dataframe.columns) {
        const bool displayed = column.name == model->xLabel || column.name == model->yLabel ||
            column.name == model->barplotSplitVariable ||
            std::find(model->barplotXVariables.begin(), model->barplotXVariables.end(),
                column.name) != model->barplotXVariables.end() ||
            std::find(model->boxplotGroupingVariables.begin(), model->boxplotGroupingVariables.end(),
                column.name) != model->boxplotGroupingVariables.end();
        if (displayed) continue;
        if (NormalizeVariableType(column.type) == "numeric" && DataColumnAllowsNumeric(column)) {
            NSMenuItem *variableRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name)
                action:nil keyEquivalent:@""];
            NSMenu *methods = [[NSMenu alloc] initWithTitle:ToNSString(column.name)];
            [methods addItem:PlotCommandMenuItem(@"Categorical", ToNSString(
                "PLOT_CONDITION_CATEGORICAL|" + column.name))];
            [methods addItem:PlotCommandMenuItem(@"Ordinal", ToNSString(
                "PLOT_CONDITION_ORDERED|" + column.name))];
            [methods addItem:[NSMenuItem separatorItem]];
            [methods addItem:PlotCommandMenuItem(@"Equal-width intervals", ToNSString(
                "PLOT_CONDITION_EQUAL_WIDTH|" + column.name))];
            [methods addItem:PlotCommandMenuItem(@"Equal-count intervals", ToNSString(
                "PLOT_CONDITION_EQUAL_COUNT|" + column.name))];
            [variableRoot setSubmenu:methods]; [numeric addItem:variableRoot];
        } else if (DataColumnLooksGroupingCandidate(column, dataframe.rows)) {
            [categorical addItem:PlotCommandMenuItem(ToNSString(column.name), ToNSString(
                "PLOT_CONDITION_CATEGORICAL|" + column.name))];
        }
    }
    AddMenuGroupWithoutRedundantSingleLevel(add, categoricalRoot, categorical);
    AddMenuGroupWithoutRedundantSingleLevel(add, numericRoot, numeric);
    if ([add numberOfItems] == 0) return nil;
    [addRoot setSubmenu:add];
    if ([conditions numberOfItems] == 0) return addRoot;
    [conditions addItem:addRoot];
    [root setSubmenu:conditions];
    return root;
}

static NSMenu *PlotThemeMenu(NSView *owner)
{
    const rlispstat::core::PlotContextMenuTitles titles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenu *themeMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.theme)];
    for (const std::string &theme : PlotThemeNames()) {
        NSString *displayName = ToNSString(rlispstat::core::PlotThemeDisplayName(theme));
        NSMenuItem *item = owner
            ? [[NSMenuItem alloc] initWithTitle:displayName action:@selector(changeLocalPlotTheme:) keyEquivalent:@""]
            : PlotCommandMenuItem(displayName, ToNSString("PLOT_THEME|" + theme));
        if (owner) {
            [item setTarget:owner];
            [item setRepresentedObject:ToNSString(theme)];
        }
        if ([ToNSString(theme) isEqualToString:PlotEffectiveThemeName(owner)]) {
            [item setState:NSControlStateValueOn];
        }
        [themeMenu addItem:item];
    }
    return themeMenu;
}

static void AddPlotThemeSubmenu(NSMenu *menu, NSView *owner = nil)
{
    const rlispstat::core::PlotContextMenuTitles titles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenuItem *themeItem = [[NSMenuItem alloc] initWithTitle:
        (owner ? ToNSString(titles.theme) : @"Global theme") action:nil keyEquivalent:@""];
    [menu setSubmenu:PlotThemeMenu(owner) forItem:themeItem];
    [menu addItem:themeItem];
}

static NSMenuItem *ImputationDisplaySubmenuItemForPlot(PlotModel *model)
{
    if (!model || rlispstat::core::IsPooledRegressionEffectPlot(*model)) return nil;
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe) ||
        dataframe.datasetType != "multiple_imputation" ||
        dataframe.imputationCount <= 0) {
        return nil;
    }
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:ToNSString(
        rlispstat::core::ScatterplotImputationDisplayMenuTitle(
            dataframe.imputationCount,
            dataframe.activeImputationVersion,
            dataframe.imputationDisplayMode)) action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:[root title]];
    const auto options = rlispstat::core::ScatterplotImputationDisplayMenuOptions(
        dataframe.imputationCount,
        dataframe.activeImputationVersion,
        dataframe.imputationDisplayMode);
    for (std::size_t index = 0; index < options.size(); ++index) {
        if (index == static_cast<std::size_t>(dataframe.imputationCount))
            [submenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *item = PlotCommandMenuItem(
            ToNSString(options[index].title), ToNSString(options[index].command));
        [item setEnabled:options[index].enabled];
        [item setState:options[index].checked
            ? NSControlStateValueOn : NSControlStateValueOff];
        [submenu addItem:item];
    }
    [root setSubmenu:submenu];
    return root;
}

static void DrawPlotImputationDisplayStatus(PlotModel *model,
                                            bool summarizesAllImputations,
                                            NSRect rect,
                                            CGFloat y)
{
    if (!model) return;
    const auto diagnosticStatus=rlispstat::core::ImputationDiagnosticDisplayStatus(*model);
    if(!diagnosticStatus.empty()) {
        [ToNSString(diagnosticStatus) drawInRect:NSMakeRect(rect.origin.x,y,rect.size.width,18)
            withAttributes:@{NSFontAttributeName:[NSFont systemFontOfSize:9.5],NSForegroundColorAttributeName:[NSColor secondaryLabelColor]}];
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    std::string status = rlispstat::core::IsPooledRegressionEffectPlot(*model)
        ? rlispstat::core::PooledEffectPlotImputationStatus(dataframe)
        : rlispstat::core::PlotImputationDisplayStatus(
            dataframe, summarizesAllImputations);
    if (model->isGLMDiagnostic && model->diagnosticImputationCount > 0 &&
        !model->diagnosticShowImputationUncertainty) {
        status = "Showing imputation " + std::to_string(model->diagnosticImputationIndex) +
            " of " + std::to_string(model->diagnosticImputationCount) + " (not pooled).";
    }
    if (model->kind == "time_series" && dataframe.rows > 0 &&
        model->points.size() != static_cast<std::size_t>(dataframe.rows)) {
        if (!status.empty()) status += " ";
        status += std::to_string(model->points.size()) + " plotted cases of " +
            std::to_string(dataframe.rows) + " dataset rows.";
    }
    if (!model->diagnosticSummary.empty()) {
        NSDictionary *noteAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:9.5],
            NSForegroundColorAttributeName:[NSColor secondaryLabelColor]};
        [ToNSString(model->diagnosticSummary) drawInRect:
            NSMakeRect(rect.origin.x, rect.origin.y+rect.size.height+44, rect.size.width, 26)
            withAttributes:noteAttrs];
    }
    if (status.empty()) return;
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:NSTextAlignmentCenter];
    [style setLineBreakMode:NSLineBreakByTruncatingTail];
    NSDictionary *attributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:9.5],
        NSForegroundColorAttributeName: [NSColor secondaryLabelColor],
        NSParagraphStyleAttributeName: style
    };
    [ToNSString(status) drawInRect:NSMakeRect(rect.origin.x, y, rect.size.width, 16.0)
                     withAttributes:attributes];
}

static void AddStandardPlotExportItems(NSMenu *menu, BOOL includeSelectedRows)
{
    WindowNotesContainer *notes = ActiveWindowNotesContainer();
    if (notes) {
        NSMenuItem *includeNotes = PlotCommandMenuItem(@"Include Notes", @"NOTES_INCLUDE_EXPORT");
        [includeNotes setEnabled:[notes hasNotes]];
        [includeNotes setState:[notes includeNotes]
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:includeNotes];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    std::vector<std::vector<rlispstat::core::LinkedPlotCommandOption>> groups =
        rlispstat::core::PlotExportCommandOptionGroups(includeSelectedRows);
    for (std::size_t groupIndex = 0; groupIndex < groups.size(); ++groupIndex) {
        if (groupIndex > 0) {
            [menu addItem:[NSMenuItem separatorItem]];
        }
        for (const rlispstat::core::LinkedPlotCommandOption &option : groups[groupIndex]) {
            [menu addItem:PlotCommandMenuItem(ToNSString(option.title), ToNSString(option.command))];
        }
    }
    OrganizeExportMenu(menu);
}

static NSImage *PaletteMenuSwatch(const PaletteColor &color)
{
    NSImage *image = [[NSImage alloc] initWithSize:NSMakeSize(18, 12)];
    [image lockFocus];
    [[NSColor colorWithCalibratedRed:color.baseR green:color.baseG blue:color.baseB alpha:1.0] setFill];
    NSRectFill(NSMakeRect(0, 0, 18, 12));
    [[NSColor colorWithCalibratedWhite:0.25 alpha:0.55] setStroke];
    NSFrameRect(NSMakeRect(0, 0, 18, 12));
    [image unlockFocus];
    return image;
}

static NSImage *DefaultColorMenuSwatch()
{
    NSImage *image = [[NSImage alloc] initWithSize:NSMakeSize(18, 12)];
    [image lockFocus];
    [[NSColor blackColor] setFill];
    NSRectFill(NSMakeRect(0, 0, 9, 12));
    [[NSColor whiteColor] setFill];
    NSRectFill(NSMakeRect(9, 0, 9, 12));
    [[NSColor colorWithCalibratedWhite:0.25 alpha:0.55] setStroke];
    NSFrameRect(NSMakeRect(0, 0, 18, 12));
    [image unlockFocus];
    return image;
}

