static NSMenuItem *AddDataColumnSubmenuItemForGroup(const std::string &group)
{
    const rlispstat::core::PlotContextMenuTitles titles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenuItem *dataItem = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.addDataColumn) action:nil keyEquivalent:@""];
    NSMenu *dataMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addDataColumn)];
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::DataColumnCommandOptions(group)) {
        [dataMenu addItem:PlotCommandMenuItem(ToNSString(option.title), ToNSString(option.command))];
    }
    [dataItem setSubmenu:dataMenu];
    return dataItem;
}

static NSMenuItem *AddDataColumnSubmenuItem()
{
    return AddDataColumnSubmenuItemForGroup("");
}

static std::string AnalysisScopeRowsCommand(const std::string &group,
                                            const std::vector<int> &rows,
                                            const std::string &sourceKind,
                                            const std::string &description,
                                            const std::string &viewId = "",
                                            const std::string &elementId = "")
{
    std::ostringstream command;
    command << "SET_ANALYSIS_SCOPE_FROM_ROWS|" << group << "|" << rows.size();
    for (int row : rows) command << "|" << row;
    command << "|" << sourceKind << "|" << description
            << "|" << viewId << "|" << elementId;
    return command.str();
}

static std::optional<std::string> PromptForSavedAnalysisScopeName(
    std::size_t observationCount)
{
    std::string previousValue;
    while (true) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Save Current Selection as Scope"];
        [alert setInformativeText:[NSString stringWithFormat:
            @"Save the current %lu selected observations for later use and make the new named scope active.",
            (unsigned long)observationCount]];
        [alert addButtonWithTitle:@"Save"];
        [alert addButtonWithTitle:@"Cancel"];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 320, 24)];
        [field setStringValue:ToNSString(previousValue)];
        [field setPlaceholderString:@"For example: High mileage cars"];
        [field setAccessibilityLabel:@"Selection name"];
        [alert setAccessoryView:field];
        [[alert window] setInitialFirstResponder:field];
        NSModalResponse response = [alert runModal];
        previousValue = [[field stringValue] UTF8String];
        [field release];
        [alert release];
        if (response != NSAlertFirstButtonReturn) return std::nullopt;

        std::string error;
        if (rlispstat::core::ValidateAnalysisScopeSelectionName(previousValue, &error)) {
            return rlispstat::core::NormalizeAnalysisScopeSelectionName(previousValue);
        }
        NSAlert *errorAlert = [[NSAlert alloc] init];
        [errorAlert setMessageText:@"Name selected observations"];
        [errorAlert setInformativeText:ToNSString(error)];
        [errorAlert addButtonWithTitle:@"OK"];
        [errorAlert runModal];
        [errorAlert release];
    }
}

static std::optional<std::string> PromptForColorSchemeName(std::size_t observationCount)
{
    std::string previousValue;
    while (true) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Save Current Colors as Scheme"];
        [alert setInformativeText:[NSString stringWithFormat:
            @"Save persistent case colors for the %lu observations in the current analysis scope.",
            (unsigned long)observationCount]];
        [alert addButtonWithTitle:@"Save"];
        [alert addButtonWithTitle:@"Cancel"];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 320, 24)];
        [field setStringValue:ToNSString(previousValue)];
        [field setPlaceholderString:@"For example: Outlier groups"];
        [field setAccessibilityLabel:@"Color scheme name"];
        [alert setAccessoryView:field];
        [[alert window] setInitialFirstResponder:field];
        const NSModalResponse response = [alert runModal];
        previousValue = [[field stringValue] UTF8String];
        [field release];
        [alert release];
        if (response != NSAlertFirstButtonReturn) return std::nullopt;
        std::string error;
        if (rlispstat::core::ValidateAnalysisScopeSelectionName(previousValue, &error))
            return rlispstat::core::NormalizeAnalysisScopeSelectionName(previousValue);
        NSAlert *errorAlert = [[NSAlert alloc] init];
        [errorAlert setMessageText:@"Save Color Scheme"];
        [errorAlert setInformativeText:ToNSString(error)];
        [errorAlert addButtonWithTitle:@"OK"];
        [errorAlert runModal];
        [errorAlert release];
    }
}

static void AddSavedSelectionItemsToScopeMenu(
    NSMenu *menu,
    const std::string &group,
    const std::vector<rlispstat::core::SavedSelection> &savedSelections,
    const rlispstat::core::AnalysisScope &activeScope)
{
    if (!menu || savedSelections.empty()) return;
    const std::optional<std::string> activeName =
        rlispstat::core::AnalysisScopeSelectionName(activeScope);
    for (const rlispstat::core::SavedSelection &selection : savedSelections) {
        NSString *title = [NSString stringWithFormat:@"Saved: %s (%lu)", selection.name.c_str(),
            (unsigned long)selection.originalRowIds.size()];
        NSMenuItem *useItem = ApplicationMenuItem(
            title,
            ToNSString("USE_SAVED_ANALYSIS_SCOPE|" + group + "|" + selection.name),
            @"", 0);
        [useItem setState:activeName.has_value() && *activeName == selection.name
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:useItem];
    }
}

static NSMenuItem *AnalysisScopeSubmenuItemForPlot(PlotModel *model,
                                                   const std::vector<int> &contextRows = {},
                                                   const std::string &contextSourceKind = "",
                                                   const std::string &contextDescription = "",
                                                   const std::string &contextElementId = "")
{
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:ToNSString(
        rlispstat::core::PlotAnalysisScopeMenuTitle()) action:nil keyEquivalent:@""];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(
        rlispstat::core::PlotAnalysisScopeMenuTitle())];
    if (!model) {
        [root setEnabled:NO];
        return root;
    }
    std::vector<int> selectedRows;
    std::size_t totalRows = model->dataScope.totalDatasetRows;
    std::size_t excludedCount = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)MacPlotCoordinator().activatePlot(model->id);
        const DataFrameModel *dataset = FindDataFrameUnlockedConst(model->group);
        if (dataset) totalRows = static_cast<std::size_t>(std::max(0, dataset->rows));
        excludedCount = MacCommandDispatcher().applicationState()
            .excludedRows(model->group).size();
        auto selected = g_groupSelections.find(model->group);
        if (selected != g_groupSelections.end()) {
            selectedRows.assign(selected->second.begin(), selected->second.end());
        }
        if (contextSourceKind == "trellis_panel") {
            g_analysisScopePanelMenuContext.group = model->group;
            g_analysisScopePanelMenuContext.plotId = model->id;
            g_analysisScopePanelMenuContext.panelId = contextElementId;
            g_analysisScopePanelMenuContext.description = contextDescription;
            g_analysisScopePanelMenuContext.rows = contextRows;
        } else if (g_analysisScopePanelMenuContext.plotId != model->id) {
            g_analysisScopePanelMenuContext = {};
        }
    }
    UpdateAnalysisScopeStatusOnMain();
    const std::size_t selected = selectedRows.size();
    NSString *selectedTitle = [NSString stringWithFormat:@"Current Selection (live; %lu)", (unsigned long)selected];
    const std::string selectionSource =
        (model->kind == "scatter" || model->kind == "scatter_matrix" ||
         model->kind == "time_series" || model->kind == "dotplot")
        ? "scatterplot_selection" : "current_selection";
    NSMenuItem *selectionItem = PlotCommandMenuItem(
        selectedTitle,
        ToNSString(AnalysisScopeRowsCommand(
            model->group, selectedRows, selectionSource,
            "Current selection", model->id)));
    [selectionItem setEnabled:selected > 0];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto active = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
        [selectionItem setState:rlispstat::core::AnalysisScopeTracksCurrentSelection(active)
            ? NSControlStateValueOn : NSControlStateValueOff];
    }
    [menu addItem:selectionItem];
    NSMenuItem *saveSelectionItem = PlotCommandMenuItem(
        @"Save Current Selection as Scope\u2026",
        ToNSString("SAVE_ANALYSIS_SCOPE_FROM_SELECTION|" + model->group + "||" + model->id));
    [saveSelectionItem setEnabled:selected > 0];
    [menu addItem:saveSelectionItem];

    if (!contextRows.empty()) {
        std::string contextNoun = "Subset";
        if (contextSourceKind == "trellis_panel") contextNoun = "Panel";
        else if (contextSourceKind == "boxplot_group") contextNoun = "Group";
        else if (contextSourceKind == "histogram_bin") contextNoun = "Bin";
        else if (contextSourceKind == "bar_segment") {
            contextNoun = contextDescription.rfind("Bar segment", 0) == 0 ? "Segment" : "Bar";
        }
        else if (contextSourceKind == "bar_category") contextNoun = "Bar";
        NSString *contextTitle = [NSString stringWithFormat:@"%s (%lu)",
            contextNoun.c_str(), (unsigned long)contextRows.size()];
        NSMenuItem *contextItem = PlotCommandMenuItem(contextTitle, ToNSString(AnalysisScopeRowsCommand(
            model->group, contextRows,
            contextSourceKind.empty() ? "other_explicit_subset" : contextSourceKind,
            contextDescription.empty() ? "Context subset" : contextDescription,
            model->id, contextElementId)));
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const auto active = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
            [contextItem setState:!rlispstat::core::AnalysisScopeSelectionName(active).has_value() &&
                rlispstat::core::AnalysisScopeMatchesRows(active, contextRows)
                ? NSControlStateValueOn : NSControlStateValueOff];
        }
        [menu addItem:contextItem];
    }

    std::set<int> visible = VisibleRowsForModel(model);
    if (!visible.empty()) {
        const std::vector<int> rows(visible.begin(), visible.end());
        NSString *visibleTitle = [NSString stringWithFormat:@"Plot (%lu)", (unsigned long)rows.size()];
        NSMenuItem *visibleItem = PlotCommandMenuItem(visibleTitle, ToNSString(AnalysisScopeRowsCommand(
            model->group, rows, "visible_observations",
            "Observations visible in plot", model->id)));
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const auto active = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
            [visibleItem setState:!rlispstat::core::AnalysisScopeSelectionName(active).has_value() &&
                active.sourceKind == rlispstat::core::AnalysisScopeSourceKind::VisibleObservations &&
                rlispstat::core::AnalysisScopeMatchesRows(active, rows)
                ? NSControlStateValueOn : NSControlStateValueOff];
        }
        [menu addItem:visibleItem];
    }
    NSMenuItem *allItem = PlotCommandMenuItem(
        [NSString stringWithFormat:@"Included (%lu)",
            (unsigned long)(totalRows - excludedCount)],
        ToNSString("SET_ANALYSIS_SCOPE_ALL|" + model->group));
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto scope = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
        [allItem setState:(scope.kind == rlispstat::core::AnalysisScopeKind::AllObservations ||
            scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::IncludedObservations)
            ? NSControlStateValueOn : NSControlStateValueOff];
    }
    [menu addItem:allItem];
    if (rlispstat::core::PlotSupportsCaseExclusion(*model)) {
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *excludeCases = PlotCommandMenuItem(
            @"Exclude selected cases from all analyses",
            ToNSString("EXCLUDE_SELECTED_CASES|" + model->group));
        [excludeCases setEnabled:selected > 0];
        [menu addItem:excludeCases];
        [menu addItem:PlotCommandMenuItem(@"Include selected cases again",
            ToNSString("INCLUDE_SELECTED_CASES|" + model->group))];
        [menu addItem:PlotCommandMenuItem(@"Include all cases again",
            ToNSString("INCLUDE_ALL_CASES|" + model->group))];
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto active = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
        const auto saved = MacCommandDispatcher().applicationState().savedSelections(model->group);
        AddSavedSelectionItemsToScopeMenu(menu, model->group, saved, active);
    }
    if (!rlispstat::core::PlotIsDerivedAnalysisView(*model) && !model->isDatasetSeed) {
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *liveItem = PlotCommandMenuItem(
            @"Freeze This Plot at Current Scope", @"PLOT_TOGGLE_SCOPE_FREEZE");
        [liveItem setState:model->analysisScopeFrozen
            ? NSControlStateValueOn : NSControlStateValueOff];
        [liveItem setToolTip:model->analysisScopeFrozen
            ? @"Turn this off to reconnect the plot and rebuild it from the current global scope."
            : @"Keep this plot at its currently displayed observations when the global scope changes."];
        [menu addItem:liveItem];
    }
    if (kShowExperimentalFeatures) {
        const bool canClone = !model->isDatasetSeed && !model->isGLMDiagnostic &&
            model->kind != "pca_biplot" && model->kind != "pca_scree" &&
            model->kind != "interaction_plot";
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *openActive = PlotCommandMenuItem(
            @"Experimental — Open equivalent with active scope",
            @"OPEN_EQUIVALENT_WITH_ACTIVE_SCOPE");
        [openActive setEnabled:canClone];
        [menu addItem:openActive];
        NSMenuItem *openAll = PlotCommandMenuItem(
            @"Experimental — Open equivalent with all cases",
            @"OPEN_EQUIVALENT_WITH_ALL_ROWS");
        [openAll setEnabled:canClone];
        [menu addItem:openAll];
    }
    [root setSubmenu:menu];
    return root;
}

static void AddApplicationMenuOptions(NSMenu *menu, const std::vector<rlispstat::core::LinkedPlotCommandOption> &options)
{
    for (const rlispstat::core::LinkedPlotCommandOption &option : options) {
        [menu addItem:ApplicationMenuItem(ToNSString(option.title), ToNSString(option.command), @"", 0)];
    }
}

static NSEventModifierFlags ApplicationMenuOptionModifiers(const rlispstat::core::ApplicationMenuCommandOption &option)
{
    NSEventModifierFlags modifiers = 0;
    if (option.commandModifier) {
        modifiers |= NSEventModifierFlagCommand;
    }
    if (option.shiftModifier) {
        modifiers |= NSEventModifierFlagShift;
    }
    return modifiers;
}

static NSMenuItem *ApplicationMenuItemForOption(const rlispstat::core::ApplicationMenuCommandOption &option)
{
    std::string title = option.title;
    if (option.experimental) title += " (Experimental)";
    return ApplicationMenuItem(ToNSString(title),
                               ToNSString(option.command),
                               ToNSString(option.keyEquivalent),
                               ApplicationMenuOptionModifiers(option));
}

static void AddApplicationMenuOptions(NSMenu *menu, const std::vector<rlispstat::core::ApplicationMenuCommandOption> &options)
{
    for (const rlispstat::core::ApplicationMenuCommandOption &option : options) {
        if (option.experimental && !kShowExperimentalFeatures) continue;
        // A command requested from an already filtered menu may be absent
        // (for example Linear Model Trellis when experimental features are
        // hidden).  Do not turn that missing command into a blank menu row.
        if (option.command.empty() || option.title.empty()) continue;
        [menu addItem:ApplicationMenuItemForOption(option)];
    }
}

static void AddPlotApplicationMenuOptions(NSMenu *menu)
{
    for (const rlispstat::core::ApplicationMenuCommandOption &option : rlispstat::core::PlotCommandOptions()) {
        if (option.command == "PLOT_NEW_TRELLIS_SCATTERPLOT") {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""];
            NSMenu *submenu = [[NSMenu alloc] initWithTitle:ToNSString(option.title)];
            AddApplicationMenuOptions(submenu, rlispstat::core::TrellisPlotStartCommandOptions());
            [menu setSubmenu:submenu forItem:item];
            [menu addItem:item];
        } else {
            [menu addItem:ApplicationMenuItemForOption(option)];
        }
    }
}

static void AddApplicationMenuOptionGroups(NSMenu *menu, const std::vector<std::vector<rlispstat::core::ApplicationMenuCommandOption>> &groups)
{
    for (std::size_t groupIndex = 0; groupIndex < groups.size(); ++groupIndex) {
        if (groupIndex > 0) {
            [menu addItem:[NSMenuItem separatorItem]];
        }
        AddApplicationMenuOptions(menu, groups[groupIndex]);
    }
}

static void AddApplicationSubmenus(NSMenu *menu, const std::vector<rlispstat::core::ApplicationMenuCommandGroup> &groups)
{
    for (const rlispstat::core::ApplicationMenuCommandGroup &group : groups) {
        NSMenuItem *item = nil;
        NSMenu *submenu = menu;
        if (!group.title.empty()) {
            item = [[NSMenuItem alloc] initWithTitle:ToNSString(group.title) action:nil keyEquivalent:@""];
            submenu = [[NSMenu alloc] initWithTitle:ToNSString(group.title)];
        }
        NSMenu *optionMenu = submenu;
        std::string currentSubgroup;
        for (const auto &option : group.options) {
            if (option.experimental && !kShowExperimentalFeatures) continue;
            if (option.command.empty() || option.title.empty()) continue;
            if (!option.subgroupTitle.empty()) {
                if (currentSubgroup != option.subgroupTitle) {
                    currentSubgroup = option.subgroupTitle;
                    NSMenuItem *subgroupItem = [[NSMenuItem alloc]
                        initWithTitle:ToNSString(currentSubgroup) action:nil keyEquivalent:@""];
                    optionMenu = [[NSMenu alloc] initWithTitle:ToNSString(currentSubgroup)];
                    [submenu setSubmenu:optionMenu forItem:subgroupItem];
                    [submenu addItem:subgroupItem];
                }
            } else {
                currentSubgroup.clear();
                optionMenu = submenu;
            }
            [optionMenu addItem:ApplicationMenuItemForOption(option)];
        }
        if (item) {
            [menu setSubmenu:submenu forItem:item];
            [menu addItem:item];
        }
    }
}

static void AddModelTermTypeMenuItems(NSMenu *menu, id target, SEL action, const std::string &currentType)
{
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::ModelTermTypeOptions()) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:action
                                               keyEquivalent:@""];
        [item setTarget:target];
        [item setRepresentedObject:ToNSString(option.value)];
        [item setState:currentType == option.value ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
}

static void AddModelDiagnosticPlotMenuItems(NSMenu *menu, id target, SEL action,
                                            bool includeExtended,
                                            bool discreteResponse = false)
{
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::ModelDiagnosticPlotOptions(includeExtended)) {
        if (discreteResponse &&
            (option.value == "scale_location" ||
             option.value == "residuals_leverage" ||
             option.value == "cooks_distance")) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:action
                                               keyEquivalent:@""];
        [item setTarget:target];
        [item setRepresentedObject:ToNSString(option.value)];
        [menu addItem:item];
    }
}

static NSMenuItem *ModelDiagnosticPlotsMenuItem(id target, SEL action,
                                                bool includeBinary,
                                                bool includeDistribution = false,
                                                bool discreteResponse = false)
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenuItem *root = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.openDiagnostics) action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc]
        initWithTitle:ToNSString(titles.openDiagnostics)];
    AddModelDiagnosticPlotMenuItems(
        submenu, target, action, true, discreteResponse || includeBinary);
    if (includeBinary) {
        for (NSArray *spec in @[@[@"ROC curve", @"roc_curve"],
                                @[@"Calibration plot", @"calibration_plot"]]) {
            NSMenuItem *item = [[NSMenuItem alloc]
                initWithTitle:spec[0] action:action keyEquivalent:@""];
            [item setTarget:target];
            [item setRepresentedObject:spec[1]];
            [submenu addItem:item];
        }
    }
    if (includeDistribution || includeBinary) {
        NSMenuItem *item = [[NSMenuItem alloc]
            initWithTitle:@"Observed vs predicted distribution"
                   action:action keyEquivalent:@""];
        [item setTarget:target];
        [item setRepresentedObject:@"observed_predicted_score_distribution"];
        [submenu addItem:item];
        NSMenuItem *boundary = [[NSMenuItem alloc]
            initWithTitle:@"Boundary / zero fit"
                   action:action keyEquivalent:@""];
        [boundary setTarget:target];
        [boundary setRepresentedObject:@"boundary_zero_fit"];
        [submenu addItem:boundary];
    }
    [root setSubmenu:submenu];
    return root;
}

static void UpdateActiveDatasetMenuOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!g_activeDatasetMenu) {
          return;
      }
      [g_activeDatasetMenu removeAllItems];
      std::vector<std::string> groups;
      std::string active;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          active = ActiveDatasetGroupUnlocked();
          groups = DatasetGroupsUnlocked();
      }
      if (groups.empty()) {
          NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::NoRegisteredDatasetsTitle()) action:nil keyEquivalent:@""];
          [empty setEnabled:NO];
          [g_activeDatasetMenu addItem:empty];
          return;
      }
      for (const rlispstat::core::ApplicationMenuCommandOption &option : rlispstat::core::ActiveDatasetCommandOptions(groups)) {
          NSMenuItem *item = ApplicationMenuItemForOption(option);
          [item setState:(option.value == active) ? NSControlStateValueOn : NSControlStateValueOff];
          [g_activeDatasetMenu addItem:item];
      }
    });
    UpdateAnalysisScopeStatusOnMain();
}

static void RefreshAnalysisScopePanel(
    NSString *summary,
    const std::string &group,
    const rlispstat::core::AnalysisScope &scope,
    std::size_t totalRows,
    std::size_t selectedCount,
    const std::vector<rlispstat::core::SavedSelection> &savedSelections)
{
    if (!g_analysisScopePanel || !g_analysisScopePanelOptions ||
        !g_analysisScopePanelScroll || !g_analysisScopePanelSave ||
        !g_analysisScopePanelIncludeAll) return;
    (void)selectedCount;
    [g_analysisScopePanelStatus setStringValue:summary ?: @"No active dataset"];
    NSArray<NSView *> *oldScopeRows = [[g_analysisScopePanelOptions subviews] copy];
    for (NSView *view in oldScopeRows) [view removeFromSuperview];
    [oldScopeRows release];

    struct ScopePanelRow {
        NSString *label;
        NSString *command;
        std::size_t count;
        bool enabled;
        bool checked;
    };
    std::set<int> excluded;
    std::set<int> selected;
    if (!group.empty()) {
        std::lock_guard<std::mutex> lock(g_mutex);
        excluded = MacCommandDispatcher().applicationState().excludedRows(group);
        auto found = g_groupSelections.find(group);
        if (found != g_groupSelections.end()) selected = found->second;
    }
    const std::size_t includedCount = totalRows - excluded.size();
    const std::size_t selectedIncluded = static_cast<std::size_t>(
        std::count_if(selected.begin(), selected.end(),
            [&excluded](int row) { return excluded.count(row) == 0; }));
    std::vector<ScopePanelRow> rows;
    if (!group.empty()) {
        rows.push_back({@"Included cases",
            ToNSString("SET_ANALYSIS_SCOPE_ALL|" + group), includedCount, true,
            scope.kind == rlispstat::core::AnalysisScopeKind::AllObservations ||
            scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::IncludedObservations});
        rows.push_back({@"Current selection (live)",
            ToNSString("SET_ANALYSIS_SCOPE_FROM_SELECTION|" + group +
                       "|Current selection|global_scope_indicator"),
            selectedIncluded, selectedIncluded > 0,
            rlispstat::core::AnalysisScopeTracksCurrentSelection(scope)});
        rows.push_back({@"Unselected included cases", ToNSString(
            "SET_ANALYSIS_SCOPE_UNSELECTED|" + group),
            includedCount - selectedIncluded, true,
            scope.sourceKind == rlispstat::core::AnalysisScopeSourceKind::CurrentUnselection});
        const auto activeName = rlispstat::core::AnalysisScopeSelectionName(scope);
        for (const auto &saved : savedSelections) {
            rows.push_back({ToNSString(saved.name), ToNSString(
                "USE_SAVED_ANALYSIS_SCOPE|" + group + "|" + saved.name),
                static_cast<std::size_t>(std::count_if(
                    saved.originalRowIds.begin(), saved.originalRowIds.end(),
                    [&excluded](int row) { return excluded.count(row) == 0; })), true,
                activeName && *activeName == saved.name});
        }
    }

    const CGFloat rowHeight = 21.0;
    const CGFloat width = 230.0;
    const CGFloat documentHeight = std::max((CGFloat)1.0,
        rowHeight * static_cast<CGFloat>(rows.size()));
    [g_analysisScopePanelOptions setFrame:NSMakeRect(0, 0, width, documentHeight)];
    for (std::size_t index = 0; index < rows.size(); ++index) {
        const ScopePanelRow &row = rows[index];
        const CGFloat y = documentHeight - rowHeight * static_cast<CGFloat>(index + 1);
        NSButton *button = [[NSButton alloc]
            initWithFrame:NSMakeRect(0, y, width - 42.0, rowHeight)];
        [button setButtonType:NSButtonTypeRadio];
        [button setTitle:row.label];
        [button setFont:[NSFont systemFontOfSize:11.0]];
        [button setTarget:g_commandTarget];
        [button setAction:@selector(runCommand:)];
        [button setIdentifier:row.command];
        [button setEnabled:row.enabled];
        [button setState:row.checked ? NSControlStateValueOn : NSControlStateValueOff];
        [button setAccessibilityLabel:row.label];
        [g_analysisScopePanelOptions addSubview:button];

        NSTextField *count = [[NSTextField alloc]
            initWithFrame:NSMakeRect(width - 40.0, y + 2.0, 34.0, rowHeight - 3.0)];
        [count setStringValue:[NSString stringWithFormat:@"%lu", (unsigned long)row.count]];
        [count setAlignment:NSTextAlignmentRight];
        [count setFont:[NSFont monospacedDigitSystemFontOfSize:10.5
                                                       weight:NSFontWeightRegular]];
        [count setTextColor:[NSColor secondaryLabelColor]];
        [count setEditable:NO]; [count setBordered:NO]; [count setDrawsBackground:NO];
        [g_analysisScopePanelOptions addSubview:count];
    }
    [g_analysisScopePanelScroll setHasVerticalScroller:rows.size() > 7];
    [g_analysisScopePanelScroll setHidden:rows.empty()];
    [g_analysisScopePanelSave setIdentifier:ToNSString(
        "SAVE_ANALYSIS_SCOPE_FROM_SELECTION|" + group + "||global_scope_indicator")];
    [g_analysisScopePanelSave setEnabled:!group.empty() && selectedCount > 0];
    [g_analysisScopePanelIncludeAll setIdentifier:ToNSString(
        "INCLUDE_ALL_CASES|" + group)];
    [g_analysisScopePanelIncludeAll setEnabled:!group.empty() && !excluded.empty()];

    const CGFloat listHeight = rows.empty() ? 0.0 :
        std::min((CGFloat)147.0, documentHeight);
    [g_analysisScopePanelScroll setFrame:NSMakeRect(10, 34, width, listHeight)];
    [g_analysisScopePanelStatus setFrame:NSMakeRect(10, 39 + listHeight, width, 20)];
    [g_analysisScopePanelSave setFrame:NSMakeRect(10, 6, 124, 23)];
    [g_analysisScopePanelIncludeAll setFrame:NSMakeRect(144, 6, 96, 23)];
    [g_analysisScopePanel setContentSize:NSMakeSize(250, 65 + listHeight)];
}

