        [g_analysisScopePanelStatus setEditable:NO];
        [g_analysisScopePanelStatus setBordered:NO];
        [g_analysisScopePanelStatus setDrawsBackground:NO];
        [g_analysisScopePanelStatus setLineBreakMode:NSLineBreakByTruncatingTail];
        [g_analysisScopePanelStatus setUsesSingleLineMode:YES];
        [g_analysisScopePanelStatus setFont:[NSFont systemFontOfSize:11.5 weight:NSFontWeightSemibold]];
        [content addSubview:g_analysisScopePanelStatus];
        g_analysisScopePanelOptions = [[NSView alloc]
            initWithFrame:NSMakeRect(0, 0, 230, 63)];
        g_analysisScopePanelScroll = [[NSScrollView alloc]
            initWithFrame:NSMakeRect(10, 34, 230, 63)];
        [g_analysisScopePanelScroll setBorderType:NSNoBorder];
        [g_analysisScopePanelScroll setDrawsBackground:NO];
        [g_analysisScopePanelScroll setAutohidesScrollers:YES];
        [g_analysisScopePanelScroll setDocumentView:g_analysisScopePanelOptions];
