@implementation WelcomeBrandView

- (BOOL)isOpaque { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    NSRect bounds = [self bounds];
    NSColor *base = [NSColor controlBackgroundColor];
    NSColor *blueWash = [base blendedColorWithFraction:0.14
                                               ofColor:[NSColor systemBlueColor]];
    NSGradient *gradient = [[NSGradient alloc] initWithStartingColor:base
                                                        endingColor:blueWash];
    [gradient drawInRect:bounds angle:90.0];
    [gradient release];

    // Subtle waves echo the visual language of the reference without turning
    // this functional Welcome window into a splash screen.
    for (NSInteger wave = 0; wave < 3; ++wave) {
        CGFloat y = 22.0 + wave * 17.0;
        NSBezierPath *path = [NSBezierPath bezierPath];
        [path moveToPoint:NSMakePoint(0, y)];
        [path curveToPoint:NSMakePoint(bounds.size.width, y + 5)
             controlPoint1:NSMakePoint(bounds.size.width * 0.28, y + 42)
             controlPoint2:NSMakePoint(bounds.size.width * 0.68, y - 28)];
        [path lineToPoint:NSMakePoint(bounds.size.width, 0)];
        [path lineToPoint:NSMakePoint(0, 0)];
        [path closePath];
        [[[NSColor systemBlueColor] colorWithAlphaComponent:0.055 + wave * 0.025] setFill];
        [path fill];
    }

    const CGFloat panelY = 164.0;
    const CGFloat panelW = 91.0;
    const CGFloat panelH = 88.0;
    const CGFloat starts[] = {22.0, 126.0, 230.0};
    NSColor *axis = [[NSColor secondaryLabelColor] colorWithAlphaComponent:0.34];
    NSColor *blue = [NSColor systemBlueColor];
    NSColor *green = [NSColor systemGreenColor];
    NSColor *orange = [NSColor systemOrangeColor];
    for (NSInteger i = 0; i < 3; ++i) {
        NSRect card = NSMakeRect(starts[i], panelY, panelW, panelH);
        NSBezierPath *cardPath = [NSBezierPath bezierPathWithRoundedRect:card xRadius:10 yRadius:10];
        [[[NSColor windowBackgroundColor] colorWithAlphaComponent:0.72] setFill];
        [cardPath fill];
        [[axis colorWithAlphaComponent:0.28] setStroke];
        [cardPath setLineWidth:0.7];
        [cardPath stroke];
        NSBezierPath *axes = [NSBezierPath bezierPath];
        [axes moveToPoint:NSMakePoint(NSMinX(card) + 12, NSMinY(card) + 13)];
        [axes lineToPoint:NSMakePoint(NSMinX(card) + 12, NSMaxY(card) - 11)];
        [axes moveToPoint:NSMakePoint(NSMinX(card) + 12, NSMinY(card) + 13)];
        [axes lineToPoint:NSMakePoint(NSMaxX(card) - 9, NSMinY(card) + 13)];
        [axis setStroke];
        [axes setLineWidth:1.0];
        [axes stroke];
    }

    // Scatterplot.
    const NSPoint dots[] = {{40,190},{48,204},{57,194},{62,217},{70,210},
                            {76,226},{84,218},{91,235},{99,229},{105,242}};
    for (const NSPoint &point : dots) {
        [blue setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(point.x - 2.8, point.y - 2.8, 5.6, 5.6)] fill];
    }

    // Histogram and smooth curve.
    const CGFloat heights[] = {20, 37, 55, 47, 31, 16};
    for (NSInteger i = 0; i < 6; ++i) {
        NSRect bar = NSMakeRect(143 + i * 11, panelY + 14, 9, heights[i]);
        [[[NSColor systemGreenColor] colorWithAlphaComponent:0.46] setFill];
        NSRectFill(bar);
    }
    NSBezierPath *curve = [NSBezierPath bezierPath];
    [curve moveToPoint:NSMakePoint(139, 183)];
    [curve curveToPoint:NSMakePoint(205, 187)
          controlPoint1:NSMakePoint(157, 249)
          controlPoint2:NSMakePoint(181, 249)];
    [blue setStroke];
    [curve setLineWidth:1.8];
    [curve stroke];

    // Three compact boxplots.
    NSColor *fills[] = {blue, green, orange};
    const CGFloat centers[] = {252, 276, 300};
    const CGFloat lower[] = {187, 180, 192};
    const CGFloat upper[] = {239, 230, 246};
    for (NSInteger i = 0; i < 3; ++i) {
        NSBezierPath *whisker = [NSBezierPath bezierPath];
        [whisker moveToPoint:NSMakePoint(centers[i], lower[i])];
        [whisker lineToPoint:NSMakePoint(centers[i], upper[i])];
        [[NSColor secondaryLabelColor] setStroke];
        [whisker setLineWidth:1.1];
        [whisker stroke];
        NSRect box = NSMakeRect(centers[i] - 7, lower[i] + 12, 14, 25);
        [[[fills[i] colorWithAlphaComponent:0.55] colorUsingColorSpace:[NSColorSpace sRGBColorSpace]] setFill];
        NSRectFill(box);
        NSBezierPath *boxPath = [NSBezierPath bezierPathWithRect:box];
        [fills[i] setStroke];
        [boxPath setLineWidth:1.0];
        [boxPath stroke];
        NSBezierPath *median = [NSBezierPath bezierPath];
        [median moveToPoint:NSMakePoint(NSMinX(box), NSMidY(box))];
        [median lineToPoint:NSMakePoint(NSMaxX(box), NSMidY(box))];
        [fills[i] setStroke];
        [median stroke];
    }
}

@end

static NSButton *WelcomeActionButton(NSString *title, NSString *symbolName,
                                     id target, SEL action, NSRect frame,
                                     BOOL primary)
{
    NSButton *button = [NSButton buttonWithTitle:title target:target action:action];
    [button setFrame:frame];
    [button setBezelStyle:NSBezelStyleRounded];
    [button setControlSize:NSControlSizeLarge];
    [button setFont:[NSFont systemFontOfSize:14 weight:NSFontWeightMedium]];
    [button setAlignment:NSTextAlignmentLeft];
    [button setImagePosition:NSImageLeft];
    NSImage *symbol = [NSImage imageWithSystemSymbolName:symbolName
                                accessibilityDescription:title];
    if (symbol) [button setImage:symbol];
    [button setAccessibilityLabel:title];
    if (primary) {
        [button setBezelColor:[NSColor systemBlueColor]];
        [button setContentTintColor:[NSColor whiteColor]];
    }
    return button;
}

@implementation WelcomeWindowController

- (instancetype)initWithVersion:(const std::string &)version
{
    self = [super init];
    if (!self) return nil;
    _version = version;
    const auto model = rlispstat::core::DefaultWelcomeWindowModel(
        version, !g_mainRNotifyPath.empty(), NativeWelcomeRecentItems());
    _window = [[NSWindow alloc]
        initWithContentRect:NSMakeRect(0, 0, 860, 560)
                  styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                             NSWindowStyleMaskMiniaturizable)
                    backing:NSBackingStoreBuffered defer:NO];
    [_window setTitle:ToNSString(model.strings.windowTitle)];
    [_window setReleasedWhenClosed:NO];
    [_window setDelegate:self];
    [_window setAccessibilityLabel:ToNSString(model.strings.windowTitle)];
    NSVisualEffectView *content = [[NSVisualEffectView alloc]
