// The import preview keeps its selection independently from the filtered
// rows. Searching never drops variables that were selected before they became
// hidden, and native Shift/Command selection continues to work for visible rows.
@interface NativeImportColumnSelectionTarget : NSObject
    <NSTableViewDataSource, NSTableViewDelegate, NSSearchFieldDelegate>
{
    std::vector<std::string> _variables;
    std::vector<std::string> _filteredVariables;
    std::set<std::string> _selectedVariables;
    NSTableView *_table;
    NSSearchField *_searchField;
    NSTextField *_summaryField;
    BOOL _rebuilding;
}
- (instancetype)initWithTable:(NSTableView *)table
                   searchField:(NSSearchField *)searchField
                  summaryField:(NSTextField *)summaryField
                     variables:(const std::vector<std::string> &)variables;
- (void)rebuild;
- (std::vector<std::string>)selectedVariables;
- (void)selectAllVariables:(id)sender;
- (void)deselectAllVariables:(id)sender;
@end

@implementation NativeImportColumnSelectionTarget
- (instancetype)initWithTable:(NSTableView *)table
                   searchField:(NSSearchField *)searchField
                  summaryField:(NSTextField *)summaryField
                     variables:(const std::vector<std::string> &)variables
{
    self = [super init];
    if (self) {
        _table = table;
        _searchField = searchField;
        _summaryField = summaryField;
        _variables = variables;
        _selectedVariables.insert(variables.begin(), variables.end());
        _rebuilding = NO;
    }
    return self;
}
- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{ (void)tableView; return static_cast<NSInteger>(_filteredVariables.size()); }
- (id)tableView:(NSTableView *)tableView
 objectValueForTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    (void)tableView; (void)tableColumn;
    if (row < 0 || static_cast<std::size_t>(row) >= _filteredVariables.size()) return @"";
    return ToNSString(_filteredVariables[static_cast<std::size_t>(row)]);
}
- (void)updateSummary
{
    NSString *summary = [NSString stringWithFormat:@"%lu of %lu variables selected",
        (unsigned long)_selectedVariables.size(), (unsigned long)_variables.size()];
    if (_filteredVariables.size() != _variables.size())
        summary = [summary stringByAppendingFormat:@" · %lu shown",
            (unsigned long)_filteredVariables.size()];
    [_summaryField setStringValue:summary];
}
- (void)syncVisibleSelection
{
    if (_rebuilding) return;
    NSIndexSet *selectedRows = [_table selectedRowIndexes];
    for (std::size_t index = 0; index < _filteredVariables.size(); ++index) {
        const std::string &name = _filteredVariables[index];
        if ([selectedRows containsIndex:(NSUInteger)index]) _selectedVariables.insert(name);
        else _selectedVariables.erase(name);
    }
    [self updateSummary];
}
- (void)tableViewSelectionDidChange:(NSNotification *)notification
{ if ([notification object] == _table) [self syncVisibleSelection]; }
- (void)controlTextDidChange:(NSNotification *)notification
{ if ([notification object] == _searchField) [self rebuild]; }
- (void)rebuild
{
    [self syncVisibleSelection];
    NSString *query = [_searchField stringValue] ?: @"";
    _filteredVariables.clear();
    for (const std::string &name : _variables) {
        NSString *label = ToNSString(name);
        if ([query length] == 0 || [label rangeOfString:query
            options:NSCaseInsensitiveSearch].location != NSNotFound)
            _filteredVariables.push_back(name);
    }
    _rebuilding = YES;
    [_table reloadData];
    NSMutableIndexSet *selectedRows = [NSMutableIndexSet indexSet];
    for (std::size_t index = 0; index < _filteredVariables.size(); ++index)
        if (_selectedVariables.find(_filteredVariables[index]) != _selectedVariables.end())
            [selectedRows addIndex:(NSUInteger)index];
    [_table selectRowIndexes:selectedRows byExtendingSelection:NO];
    _rebuilding = NO;
    [self updateSummary];
}
- (std::vector<std::string>)selectedVariables
{
    [self syncVisibleSelection];
    std::vector<std::string> selected;
    for (const std::string &name : _variables)
        if (_selectedVariables.find(name) != _selectedVariables.end())
            selected.push_back(name);
    return selected;
}
- (void)selectAllVariables:(id)sender
{
    (void)sender;
    _rebuilding = YES;
    _selectedVariables.clear();
    _selectedVariables.insert(_variables.begin(), _variables.end());
    [self rebuild];
    [[_table window] makeFirstResponder:_table];
}
- (void)deselectAllVariables:(id)sender
{
    (void)sender;
    _rebuilding = YES;
    _selectedVariables.clear();
    [self rebuild];
    [[_table window] makeFirstResponder:_table];
}
@end

struct PreparedNativeImportFile {
    bool ok = false;
    std::string path;
    std::string sourcePath;
    std::string temporaryDirectory;
    std::string message;
};

static bool NativeImportURLNeedsStaging(NSURL *url)
{
    NSString *path = [url path];
    if ([path rangeOfString:@"/Library/CloudStorage/"].location != NSNotFound) return true;
    struct stat metadata;
    if (stat([path fileSystemRepresentation], &metadata) != 0) return false;
#ifdef SF_DATALESS
    if ((metadata.st_flags & SF_DATALESS) != 0) return true;
#endif
    return false;
}

static PreparedNativeImportFile PrepareNativeImportFile(NSURL *selectedURL)
{
    PreparedNativeImportFile prepared;
    if (!selectedURL || ![selectedURL isFileURL]) {
        prepared.message = "The selected item is not a readable file URL.";
        return prepared;
    }
    NSString *originalPath = [selectedURL path];
    prepared.path = [originalPath UTF8String];
    prepared.sourcePath = prepared.path;
    const BOOL scoped = [selectedURL startAccessingSecurityScopedResource];
    const bool stage = scoped || NativeImportURLNeedsStaging(selectedURL);
    if (!stage) {
        prepared.ok = true;
        return prepared;
    }

    NSString *directory = [NSTemporaryDirectory() stringByAppendingPathComponent:
        [NSString stringWithFormat:@"rlispstat-import-%@", [[NSUUID UUID] UUIDString]]];
    NSError *directoryError = nil;
    if (![[NSFileManager defaultManager] createDirectoryAtPath:directory
                                  withIntermediateDirectories:YES
                                                   attributes:nil
                                                        error:&directoryError]) {
        if (scoped) [selectedURL stopAccessingSecurityScopedResource];
        prepared.message = directoryError ? [[directoryError localizedDescription] UTF8String] :
            "Could not create a temporary directory for the selected file.";
        return prepared;
    }

    NSURL *destination = [NSURL fileURLWithPath:
        [directory stringByAppendingPathComponent:[selectedURL lastPathComponent]]];
    __block NSError *copyError = nil;
    NSError *coordinationError = nil;
    NSFileCoordinator *coordinator = [[NSFileCoordinator alloc] initWithFilePresenter:nil];
    [coordinator coordinateReadingItemAtURL:selectedURL options:0 error:&coordinationError
                                 byAccessor:^(NSURL *coordinatedURL) {
        if (![[NSFileManager defaultManager] copyItemAtURL:coordinatedURL
                                                    toURL:destination
                                                    error:&copyError]) return;
    }];
    if (scoped) [selectedURL stopAccessingSecurityScopedResource];
    NSError *error = coordinationError ?: copyError;
    if (error || ![[NSFileManager defaultManager] fileExistsAtPath:[destination path]]) {
        [[NSFileManager defaultManager] removeItemAtPath:directory error:nil];
        prepared.message = error ? [[error localizedDescription] UTF8String] :
            "The selected cloud file could not be made available for import.";
        return prepared;
    }
    prepared.ok = true;
    prepared.path = [[destination path] UTF8String];
    prepared.temporaryDirectory = [directory UTF8String];
    return prepared;
}

static void OpenWelcomeDataFileAtURLOnMain(NSURL *selectedURL)
{
    if (!selectedURL) return;
    NSURL *urlCopy = [selectedURL copy];
    std::thread importer([urlCopy]() {
        PreparedNativeImportFile prepared = PrepareNativeImportFile(urlCopy);
        if (!prepared.ok) {
            ShowWorkbenchMessageOnMain(ToNSString(NativeImportFailedTitle()),
                                       ToNSString(prepared.message));
            return;
        }
        if (!g_mainRNotifyPath.empty()) {
            QueueImportDataMainRTask({prepared.path, prepared.sourcePath,
                !prepared.temporaryDirectory.empty()});
            return;
        }
        std::string message;
        std::string importedGroup;
        bool ok = ImportDataFileIntoBackend(prepared.path, &message, &importedGroup);
        if (!prepared.temporaryDirectory.empty()) {
            [[NSFileManager defaultManager]
                removeItemAtPath:ToNSString(prepared.temporaryDirectory) error:nil];
        }
        if (ok && !importedGroup.empty()) {
            NoteWelcomeRecentPathOnMain(prepared.sourcePath.empty()
                ? prepared.path : prepared.sourcePath);
            UpdateActiveDatasetMenuOnMain();
            ShowDataSheetOnMain(importedGroup);
            UpdatePanelOnMain();
            CloseWelcomeOnMain();
        }
        ShowWorkbenchMessageOnMain(
            ToNSString(ok ? NativeImportDialogTitle() : NativeImportFailedTitle()),
            ToNSString(message));
    });
    importer.detach();
}

static void ShowImportChooserOnMain()
{
    if (![NSThread isMainThread]) {
        dispatch_async(dispatch_get_main_queue(), ^{ ShowImportChooserOnMain(); });
        return;
    }

    NSOpenPanel *panel = [NSOpenPanel openPanel];
    [panel setTitle:ToNSString(NativeImportDialogTitle())];
    [panel setPrompt:@"Import"];
    [panel setCanChooseFiles:YES];
    [panel setCanChooseDirectories:NO];
    [panel setAllowsMultipleSelection:NO];
    const std::vector<rlispstat::core::NativeImportFileFilter> filters =
        rlispstat::core::NativeImportFileFilters();
    if (!filters.empty()) SetNativeImportPanelExtensions(panel, filters.front().extensions);
    NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 410, 50)];
    NSTextField *filterLabel = [NSTextField labelWithString:@"Data format"];
    [filterLabel setFrame:NSMakeRect(0, 29, 360, 18)];
    NSPopUpButton *filterPopup = [[NSPopUpButton alloc]
        initWithFrame:NSMakeRect(0, 0, 360, 27) pullsDown:NO];
    for (const auto &filter : filters) [filterPopup addItemWithTitle:ToNSString(filter.title)];
    NativeImportFilterTarget *filterTarget = [[NativeImportFilterTarget alloc]
        initWithPanel:panel filters:filters];
    [filterPopup setTarget:filterTarget];
    [filterPopup setAction:@selector(filterChanged:)];
    [accessory addSubview:filterLabel];
    [accessory addSubview:filterPopup];
    [panel setAccessoryView:accessory];
    [NSApp activateIgnoringOtherApps:YES];

    const NSModalResponse result = [panel runModal];
    (void)filterTarget;
    if (result != NSModalResponseOK || [[panel URLs] count] == 0) {
        if (g_welcomeController) [g_welcomeController refresh];
        return;
    }
    OpenWelcomeDataFileAtURLOnMain([[panel URLs] objectAtIndex:0]);
}

static void ShowExportDataChooserOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      DataFrameModel dataframe;
      bool hasDataframe = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          const std::string group = ActiveDatasetGroupUnlocked();
          const DataFrameModel *found = group.empty()
              ? nullptr : FindDataFrameUnlockedConst(group);
          if (found) {
              dataframe = *found;
              hasDataframe = true;
          }
      }
      if (!hasDataframe) {
          ShowWorkbenchMessageOnMain(@"Export Data",
              @"No active dataset is available to export.");
          return;
      }

      NSSavePanel *panel = [NSSavePanel savePanel];
      [panel setTitle:@"Export Data"];
      [panel setPrompt:@"Export"];
      const std::string baseName = rlispstat::core::SafeExportBaseName(
          dataframe.group, "LinkEDA-data");
      const std::vector<rlispstat::core::NativeDataExportFileFilter> filters =
          rlispstat::core::NativeDataExportFileFilters();
      SetSavePanelExtensionCompat(panel, ToNSString(filters.front().extension));
      [panel setAllowsOtherFileTypes:NO];
      [panel setExtensionHidden:NO];
      [panel setNameFieldStringValue:[ToNSString(baseName)
          stringByAppendingPathExtension:ToNSString(filters.front().extension)]];

      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 410, 50)];
      NSTextField *formatLabel = [NSTextField labelWithString:@"Data format"];
      [formatLabel setFrame:NSMakeRect(0, 29, 360, 18)];
      NSPopUpButton *formatPopup = [[NSPopUpButton alloc]
          initWithFrame:NSMakeRect(0, 0, 360, 27) pullsDown:NO];
      for (const auto &filter : filters) [formatPopup addItemWithTitle:ToNSString(filter.title)];
      NativeDataExportFilterTarget *filterTarget = [[NativeDataExportFilterTarget alloc]
          initWithPanel:panel filters:filters baseName:ToNSString(baseName)];
      [formatPopup setTarget:filterTarget];
      [formatPopup setAction:@selector(filterChanged:)];
      [accessory addSubview:formatLabel];
      [accessory addSubview:formatPopup];
      [panel setAccessoryView:accessory];
      if ([panel runModal] != NSModalResponseOK) return;
      const NSInteger selectedIndex = [filterTarget selectedIndex];
      const std::size_t formatIndex = selectedIndex >= 0 &&
          (std::size_t)selectedIndex < filters.size()
          ? (std::size_t)selectedIndex : 0;
      const std::string format = filters[formatIndex].identifier;
      NSString *destination = [[panel URL] path];
      DataFrameModel exportFrame = dataframe;
      dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        std::string failure;
        bool exported = false;
        if (format == "csv") {
            std::ostringstream csv;
            exported = rlispstat::core::WriteDataExportCSV(csv, exportFrame);
            const std::string bytes = csv.str();
            NSData *data = exported
                ? [NSData dataWithBytes:bytes.data() length:bytes.size()] : nil;
            NSError *error = nil;
            exported = data && [data writeToFile:destination
                                         options:NSDataWritingAtomic error:&error];
            if (!exported && error) failure = [[error localizedDescription] UTF8String];
        } else {
            NSString *token = [[NSUUID UUID] UUIDString];
            NSString *tmp = NSTemporaryDirectory();
            NSString *scriptPath = [tmp stringByAppendingPathComponent:
                [NSString stringWithFormat:@"linkeda-export-%@.R", token]];
            NSString *inputPath = [tmp stringByAppendingPathComponent:
                [NSString stringWithFormat:@"linkeda-export-%@.csv", token]];
            NSString *metadataPath = [tmp stringByAppendingPathComponent:
                [NSString stringWithFormat:@"linkeda-export-%@-metadata.csv", token]];
            std::ostringstream csv;
            const bool generated = rlispstat::core::WriteDataExportCSV(csv, exportFrame);
            const std::string input = csv.str();
            NSData *inputData = generated
                ? [NSData dataWithBytes:input.data() length:input.size()] : nil;
            std::ostringstream metadataCsv;
            const bool metadataGenerated =
                rlispstat::core::WriteDataExportMetadataCSV(metadataCsv, exportFrame);
            const std::string metadata = metadataCsv.str();
            NSData *metadataData = metadataGenerated
                ? [NSData dataWithBytes:metadata.data() length:metadata.size()] : nil;
            NSString *script = ToNSString(rlispstat::core::NativeDataExportRScript());
            if (!inputData || ![inputData writeToFile:inputPath atomically:YES] ||
                !metadataData || ![metadataData writeToFile:metadataPath atomically:YES] ||
                ![script writeToFile:scriptPath atomically:YES
                             encoding:NSUTF8StringEncoding error:nil]) {
                failure = rlispstat::core::NativeDataExportTemporaryFileFailedStatus();
            } else {
                exported = RunRscriptTask(
                    @[scriptPath, inputPath, metadataPath, destination, ToNSString(format)],
                    rlispstat::core::NativeDataExportRscriptLaunchFailedStatus(),
                    rlispstat::core::NativeDataExportRscriptFailedStatus(),
                    &failure);
            }
            RemoveTemporaryFiles(@[scriptPath, inputPath, metadataPath]);
        }
        const bool multipleImputation = exportFrame.datasetType == "multiple_imputation" &&
            exportFrame.imputationCount > 0;
        ShowWorkbenchMessageOnMain(exported ? @"Data Exported" : @"Export Data Failed",
            ToNSString(exported
                ? rlispstat::core::NativeDataExportSuccessStatus(format, multipleImputation)
                : (failure.empty() ? rlispstat::core::NativeDataExportRscriptFailedStatus()
                                   : failure)));
      });
    });
}

static void ShowImportColumnChooserOnMain(
    const std::string &stagedDataset,
    const std::string &information,
    const std::vector<std::string> &variables)
{
    if (stagedDataset.empty() || variables.empty()) return;
    const std::string stagedDatasetCopy = stagedDataset;
    const std::string informationCopy = information;
    const std::vector<std::string> variablesCopy = variables;
    dispatch_async(dispatch_get_main_queue(), ^{
      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:@"Choose variables to import"];
      [alert setInformativeText:ToNSString(informationCopy +
          " All variables are selected initially.")];
      [alert addButtonWithTitle:@"Import selected"];
      [alert addButtonWithTitle:@"Cancel"];

      const CGFloat visibleHeight = std::min<CGFloat>(350.0,
          std::max<CGFloat>(110.0, (CGFloat)variablesCopy.size() * 23.0 + 4.0));
      const CGFloat accessoryHeight = visibleHeight + 104.0;
      NSView *accessory = [[NSView alloc]
          initWithFrame:NSMakeRect(0, 0, 430, accessoryHeight)];

      NSSearchField *searchField = [[NSSearchField alloc]
          initWithFrame:NSMakeRect(0, visibleHeight + 74.0, 430, 28)];
      [searchField setPlaceholderString:@"Search variables"];
      [searchField setSendsSearchStringImmediately:YES];
      [accessory addSubview:searchField];

      const CGFloat tableContentHeight = std::max<CGFloat>(
          visibleHeight, (CGFloat)variablesCopy.size() * 22.0);
      NSTableView *table = [[NSTableView alloc]
          initWithFrame:NSMakeRect(0, 0, 408, tableContentHeight)];
      NSTableColumn *column = [[NSTableColumn alloc] initWithIdentifier:@"variable"];
      [column setWidth:404.0];
      [column setMinWidth:260.0];
      [[column headerCell] setStringValue:@"Variable"];
      [table addTableColumn:column];
      [table setHeaderView:nil];
      [table setAllowsMultipleSelection:YES];
      [table setAllowsEmptySelection:YES];
      [table setAllowsTypeSelect:YES];
      [table setRowHeight:22.0];
      [table setSelectionHighlightStyle:NSTableViewSelectionHighlightStyleRegular];

      NSScrollView *scroll = [[NSScrollView alloc]
          initWithFrame:NSMakeRect(0, 0, 430, visibleHeight)];
      [scroll setHasVerticalScroller:YES];
      [scroll setBorderType:NSBezelBorder];
      [scroll setDocumentView:table];
      [accessory addSubview:scroll];

      NSTextField *selectionSummary = [NSTextField labelWithString:@""];
      [selectionSummary setFrame:NSMakeRect(236, visibleHeight + 42.0, 192, 20)];
      [selectionSummary setAlignment:NSTextAlignmentRight];
      [selectionSummary setFont:[NSFont systemFontOfSize:11.0]];
      [selectionSummary setTextColor:[NSColor secondaryLabelColor]];
      [accessory addSubview:selectionSummary];

      NativeImportColumnSelectionTarget *selectionTarget =
          [[NativeImportColumnSelectionTarget alloc]
              initWithTable:table searchField:searchField
              summaryField:selectionSummary variables:variablesCopy];
      [table setDataSource:selectionTarget];
      [table setDelegate:selectionTarget];
      [searchField setDelegate:selectionTarget];
      [selectionTarget rebuild];
      NSButton *selectAll = [[NSButton alloc]
          initWithFrame:NSMakeRect(0, visibleHeight + 36.0, 104, 28)];
      [selectAll setTitle:@"Select all"];
      [selectAll setBezelStyle:NSBezelStyleRounded];
      [selectAll setTarget:selectionTarget];
      [selectAll setAction:@selector(selectAllVariables:)];
      [selectAll setKeyEquivalent:@"a"];
      [selectAll setKeyEquivalentModifierMask:NSEventModifierFlagCommand];
      [accessory addSubview:selectAll];

      NSButton *deselectAll = [[NSButton alloc]
          initWithFrame:NSMakeRect(112, visibleHeight + 36.0, 112, 28)];
      [deselectAll setTitle:@"Deselect all"];
      [deselectAll setBezelStyle:NSBezelStyleRounded];
      [deselectAll setTarget:selectionTarget];
      [deselectAll setAction:@selector(deselectAllVariables:)];
      [deselectAll setKeyEquivalent:@"a"];
      [deselectAll setKeyEquivalentModifierMask:
          NSEventModifierFlagCommand | NSEventModifierFlagShift];
      [accessory addSubview:deselectAll];

      NSTextField *selectionHint = [NSTextField labelWithString:
          @"Shift-click selects a range; Command-click toggles separate variables.  "
           "\u2318A selects all; \u21E7\u2318A deselects all."];
      [selectionHint setFrame:NSMakeRect(2, visibleHeight + 4.0, 426, 30)];
      [selectionHint setFont:[NSFont systemFontOfSize:11.0]];
      [selectionHint setTextColor:[NSColor secondaryLabelColor]];
      [selectionHint setLineBreakMode:NSLineBreakByWordWrapping];
      [selectionHint setMaximumNumberOfLines:2];
      [accessory addSubview:selectionHint];

      [alert setAccessoryView:accessory];
      [[alert window] makeFirstResponder:searchField];

      MainRImportDataTask task;
      task.stagedDataset = stagedDatasetCopy;
      for (;;) {
          if ([alert runModal] != NSAlertFirstButtonReturn) {
              task.cancelStagedImport = true;
              QueueImportDataMainRTask(task);
              if (g_welcomeController) [g_welcomeController refresh];
              [table setDataSource:nil]; [table setDelegate:nil];
              [searchField setDelegate:nil]; [selectionTarget release];
              return;
          }
          task.selectedVariables = [selectionTarget selectedVariables];
          if (!task.selectedVariables.empty()) break;

          NSBeep();
          NSAlert *selectionRequired = [[NSAlert alloc] init];
          [selectionRequired setMessageText:@"Choose variables to import"];
          [selectionRequired setInformativeText:@"Select at least one variable before importing."];
          [selectionRequired addButtonWithTitle:@"OK"];
          [selectionRequired runModal];
          [selectionRequired release];
          [[alert window] makeFirstResponder:searchField];
      }
      QueueImportDataMainRTask(task);
      [table setDataSource:nil]; [table setDelegate:nil];
      [searchField setDelegate:nil]; [selectionTarget release];
    });
}

static std::string UniqueNativeDatasetNameFromBase(const std::string &baseName)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return MacCommandDispatcher().applicationState().datasets().uniqueDatasetName(baseName);
}

static bool WriteNativeDataFramePayloadForR(const DataFrameModel &df, NSString *path, std::string *message,
                                            bool includeImputation = false)
{
    std::ofstream out([path fileSystemRepresentation], std::ios::out | std::ios::trunc);
    if (!out) {
        if (message) *message = NativeRDataPayloadTemporaryFileFailedStatus();
        return false;
    }
    rlispstat::core::WriteDataFramePayloadForR(out, df, includeImputation);
    return true;
}

static bool QueueNativeDatasetSyncToR(const DataFrameModel &df)
{
    NSString *folder = [NSTemporaryDirectory() stringByAppendingPathComponent:
        [NSString stringWithFormat:@"rlispstat-sync-%@", [[NSUUID UUID] UUIDString]]];
    if (![[NSFileManager defaultManager] createDirectoryAtPath:folder
            withIntermediateDirectories:YES attributes:nil error:nil]) {
        return false;
    }
    NSString *payloadPath = [folder stringByAppendingPathComponent:@"dataset.txt"];
    std::string ignored;
    if (!WriteNativeDataFramePayloadForR(df, payloadPath, &ignored, true)) {
        [[NSFileManager defaultManager] removeItemAtPath:folder error:nil];
        return false;
    }
    QueueDatasetSyncMainRTask({
        std::string([[[NSUUID UUID] UUIDString] UTF8String]),
        df.group,
        std::string([payloadPath fileSystemRepresentation])
    });
    return true;
}

