static bool RunNativeMiceImputation(const DataFrameModel &df,
                                    const std::string &outputGroup,
                                    const std::string &imputeVariables,
                                    const std::string &predictorVariables,
                                    const std::string &methodSpec,
                                    int m,
                                    int maxit,
                                    const std::string &seed,
                                    bool openDataSheet,
                                    std::string *message)
{
    NSString *uuid = [[NSUUID UUID] UUIDString];
    NSString *tmp = NSTemporaryDirectory();
    NSString *scriptPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-mice-%@.R", uuid]];
    NSString *inputPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-mice-%@.input", uuid]];
    NSString *payloadPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-mice-%@.payload", uuid]];
    std::string miceScript = NativeMiceImputationRScript();
    NSString *script = [NSString stringWithUTF8String:miceScript.c_str()];
    if (![script writeToFile:scriptPath atomically:YES encoding:NSUTF8StringEncoding error:nil]) {
        if (message) *message = NativeMiceTemporaryScriptFailedStatus();
        return false;
    }
    if (!WriteNativeDataFramePayloadForR(df, inputPath, message)) {
        RemoveTemporaryFiles(@[scriptPath]);
        return false;
    }

    NSArray *args = @[scriptPath, inputPath, payloadPath, ToNSString(outputGroup),
                      ToNSString(imputeVariables), ToNSString(predictorVariables),
                      ToNSString(methodSpec),
                      ToNSString(std::to_string(std::max(1, m))),
                      ToNSString(std::to_string(std::max(0, maxit))),
                      ToNSString(seed)];
    if (!RunRscriptTask(args,
                        NativeMiceRscriptLaunchFailedStatus(),
                        NativeMiceRscriptFailedStatus(),
                        message)) {
        RemoveTemporaryFiles(@[scriptPath, inputPath, payloadPath]);
        return false;
    }

    NSString *payload = [NSString stringWithContentsOfFile:payloadPath encoding:NSUTF8StringEncoding error:nil];
    RemoveTemporaryFiles(@[scriptPath, inputPath, payloadPath]);
    if (!payload || [payload length] == 0) {
        if (message) *message = NativeMicePayloadMissingStatus();
        return false;
    }

    std::vector<std::string> lines = SplitLines(std::string([payload UTF8String]));
    if (!openDataSheet && !lines.empty() && lines[0] == "REGISTER_DATASET") {
        lines[0] = "REGISTER_DATASET_SILENT";
    }
    std::string reply = AppendMainRTasks(HandleCommandLines(lines));
    if (reply.rfind("ERR ", 0) == 0) {
        if (message) *message = reply.substr(4);
        return false;
    }
    DataFrameModel registered;
    bool foundRegistered = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(outputGroup);
        if (found) {
            registered = *found;
            foundRegistered = true;
        }
    }
    if (!foundRegistered || !QueueNativeDatasetSyncToR(registered)) {
        if (message) {
            *message = "The imputed dataset was created, but it could not be synchronized "
                "with the connected R session.";
        }
        return false;
    }
    if (message) {
        *message = NativeMiceCreatedDatasetStatus(outputGroup, m);
    }
    return true;
}

static bool RunRBackedMultipleImputationAnalysis(const DataFrameModel &df,
                                                 const std::string &mode,
                                                 const std::string &analysisId,
                                                 const std::vector<std::string> &variables,
                                                 const std::string &groupVariable,
                                                 const std::string &response,
                                                 const std::vector<std::string> &terms,
                                                 const std::string &scope,
                                                 std::string *message,
                                                 const std::string &modelSpec = "",
                                                 std::vector<std::string> *rawPayload = nullptr,
                                                 int timeoutSeconds = 120)
{
    NSString *uuid = [[NSUUID UUID] UUIDString];
    NSString *tmp = NSTemporaryDirectory();
    NSString *scriptPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-analysis-%@.R", uuid]];
    NSString *inputPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-analysis-%@.input", uuid]];
    NSString *payloadPath = [tmp stringByAppendingPathComponent:[NSString stringWithFormat:@"rlispstat-analysis-%@.payload", uuid]];
    std::string analysisScript = NativePooledAnalysisRScript();
    NSString *script = [NSString stringWithUTF8String:analysisScript.c_str()];
    if (![script writeToFile:scriptPath atomically:YES encoding:NSUTF8StringEncoding error:nil]) {
        if (message) *message = NativePooledAnalysisTemporaryScriptFailedStatus();
        return false;
    }
    if (!WriteNativeDataFramePayloadForR(df, inputPath, message, true)) {
        RemoveTemporaryFiles(@[scriptPath]);
        return false;
    }

    NSArray *args = @[scriptPath, inputPath, payloadPath,
                      ToNSString(mode),
                      ToNSString(analysisId),
                      ToNSString(JoinStrings(variables, "\t")),
                      ToNSString(groupVariable),
                      ToNSString(response),
                      ToNSString(JoinStrings(terms, "\t")),
                      ToNSString(scope),
                      ToNSString(modelSpec)];
    if (!RunRscriptTask(args,
                        NativePooledAnalysisRscriptLaunchFailedStatus(),
                        NativePooledAnalysisRscriptFailedStatus(),
                        message,
                        timeoutSeconds)) {
        RemoveTemporaryFiles(@[scriptPath, inputPath, payloadPath]);
        return false;
    }

    NSString *payload = [NSString stringWithContentsOfFile:payloadPath encoding:NSUTF8StringEncoding error:nil];
    RemoveTemporaryFiles(@[scriptPath, inputPath, payloadPath]);
    if (!payload || [payload length] == 0) {
        if (message) *message = NativePooledAnalysisPayloadMissingStatus();
        return false;
    }

    std::vector<std::string> lines = SplitLines(std::string([payload UTF8String]));
    if (rawPayload) {
        *rawPayload = std::move(lines);
        if (message) *message = NativePooledAnalysisOpenedStatus();
        return true;
    }
    std::string reply = AppendMainRTasks(HandleCommandLines(lines));
    if (reply.rfind("ERR ", 0) == 0) {
        if (message) *message = reply.substr(4);
        return false;
    }
    if (message) *message = NativePooledAnalysisOpenedStatus();
    return true;
}

static bool RunRBackedMIPairwiseComparisons(
    const DataFrameModel &df,
    const std::string &mode,
    const std::string &analysisId,
    const std::string &response,
    const std::vector<std::string> &terms,
    const std::string &scope,
    const std::string &modelSpec,
    const std::string &term,
    rlispstat::core::GLMPairwiseComparisonResult *result,
    std::string *message)
{
    if (!result) return false;
    std::vector<std::string> lines;
    if (!RunRBackedMultipleImputationAnalysis(
            df, mode, analysisId, std::vector<std::string>(), term,
            response, terms, scope, message, modelSpec, &lines)) {
        return false;
    }
    result->term = term;
    if (!rlispstat::core::ParseGLMPairwiseComparisonsRResult(lines, *result)) {
        if (message) *message = result->message.empty()
            ? "R could not calculate pooled multiple-imputation pairwise comparisons."
            : result->message;
        return false;
    }
    return true;
}

static bool RunRBackedMIInteractionReport(
    const DataFrameModel &df,
    const std::string &mode,
    const std::string &analysisId,
    const std::string &response,
    const std::vector<std::string> &terms,
    const std::string &scope,
    const std::string &modelSpec,
    const std::string &term,
    std::string *body,
    std::string *message,
    double emmTestReference = std::numeric_limits<double>::quiet_NaN(),
    const RegressionInteractionDerivedLink &effectOptions = {})
{
    if (!body) return false;
    std::vector<std::string> lines;
    std::vector<std::string> options;
    options.push_back(std::isfinite(emmTestReference)
        ? "emm_reference=" + FormatDouble(emmTestReference, 15)
        : "emm_reference=none");
    if (!effectOptions.reportFocal.empty())
        options.push_back("report_focal=" + effectOptions.reportFocal);
    if (!effectOptions.reportGroup.empty())
        options.push_back("report_group=" + effectOptions.reportGroup);
    options.push_back("effect_quantity=" + effectOptions.effectQuantity);
    options.push_back("effect_adjustment=" + effectOptions.effectAdjustment);
    options.push_back("effect_presentation=" + effectOptions.effectPresentation);
    options.push_back("effect_confidence=" +
        FormatDouble(effectOptions.confidenceLevel, 15));
    if (!RunRBackedMultipleImputationAnalysis(
            df, mode, analysisId, options, term,
            response, terms, scope, message, modelSpec, &lines, 300)) {
        return false;
    }
    *body = JoinStrings(lines, "\n");
    if (body->empty()) {
        if (message) *message = "R returned no pooled multiple-imputation interaction report.";
        return false;
    }
    return true;
}

static bool RunRBackedInteractionPlot(
    const DataFrameModel &df,
    const std::string &mode,
    const std::string &analysisId,
    const std::string &response,
    const std::vector<std::string> &terms,
    const std::string &scope,
    const std::string &modelSpec,
    const std::string &term,
    rlispstat::core::RegressionInteractionPlotResult *result,
    std::string *message,
    const std::string &focal = std::string(),
    const RegressionInteractionDerivedLink &effectOptions = {})
{
    if (!result) return false;
    std::vector<std::string> lines;
    std::vector<std::string> options;
    if (!focal.empty()) options.push_back("plot_focal=" + focal);
    options.push_back("effect_quantity=" + effectOptions.effectQuantity);
    options.push_back("effect_adjustment=" + effectOptions.effectAdjustment);
    options.push_back("effect_presentation=" + effectOptions.effectPresentation);
    options.push_back("effect_confidence=" +
        FormatDouble(effectOptions.confidenceLevel, 15));
    if (!RunRBackedMultipleImputationAnalysis(
            df, mode, analysisId, options, term,
            response, terms, scope, message, modelSpec, &lines, 300)) {
        return false;
    }
    if (!rlispstat::core::ParseRegressionInteractionPlotRResult(lines, *result)) {
        if (message) *message = result->message.empty()
            ? "R could not calculate the pooled effect plot."
            : result->message;
        return false;
    }
    return true;
}

static bool RunRBackedPartialRegressionPlot(
    const DataFrameModel &df,
    const std::string &mode,
    const std::string &analysisId,
    const std::string &response,
    const std::vector<std::string> &terms,
    const std::string &scope,
    const std::string &modelSpec,
    const std::string &term,
    const std::string &residualType,
    rlispstat::core::RegressionPartialPlotResult *result,
    std::string *message)
{
    if (!result) return false;
    std::vector<std::string> lines;
    const std::vector<std::string> options{
        residualType.empty() ? std::string("default") : residualType
    };
    if (!RunRBackedMultipleImputationAnalysis(
            df, mode, analysisId, options, term,
            response, terms, scope, message, modelSpec, &lines)) {
        return false;
    }
    if (!rlispstat::core::ParseRegressionPartialPlotRResult(lines, *result)) {
        if (message) *message = result->message.empty()
            ? "R could not calculate the partial regression plot."
            : result->message;
        return false;
    }
    return true;
}

static std::string ApplyRBackedInteractionPlotResult(
    const DataFrameModel &df,
    const std::string &analysisId,
    const std::string &response,
    const std::string &term,
    rlispstat::core::RegressionInteractionPlotResult pooled,
    std::string *message,
    const RegressionInteractionDerivedLink &derivedLink = {})
{
    const bool simpleEffect = !IsInteractionTerm(term);
    rlispstat::core::PopulateRegressionInteractionLegendRows(pooled, df);
    PlotModel *plot = nullptr;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!derivedLink.sourceModelId.empty()) {
            for (const auto &entry : g_plots) {
                PlotModel *candidate = entry.second;
                bool hasOpenView = false;
                if (candidate) {
                    for (ScatterView *view : g_views) {
                        NSWindow *window = view ? [view window] : nil;
                        if (view && view.model == candidate && window && [window isVisible]) {
                            hasOpenView = true;
                            break;
                        }
                    }
                }
                if (candidate && candidate->isRegressionDerivedPlot &&
                    candidate->regressionDerivedKind == (simpleEffect ? "effect_plot" : "interaction_plot") &&
                    candidate->regressionDerivedSourceModelId == derivedLink.sourceModelId &&
                    candidate->regressionDerivedTerm == term && hasOpenView) {
                    plot = candidate;
                    break;
                }
            }
        }
    }
    const bool isNewPlot = plot == nullptr;
    const bool preservedConnectEstimates = plot
        ? plot->regressionConnectEstimates : true;
    const bool preservedIntervalsVisible = plot
        ? plot->regressionConfidenceIntervalsVisible : false;
    const bool preservedLevelVisible = plot
        ? plot->regressionConfidenceLevelVisible : true;
    const std::string preservedLegendPosition = plot
        ? plot->interactionLegendPosition : "right";
    const bool preservedCustomLegendPosition = plot
        ? plot->interactionLegendUsesCustomPosition : false;
    const double preservedLegendX = plot ? plot->interactionLegendX : 0.72;
    const double preservedLegendY = plot ? plot->interactionLegendY : 0.10;
    const std::string preservedLegendTitleOverride = plot
        ? plot->interactionLegendTitleOverride : std::string();
    const bool preservedLegendTitleVisible = plot
        ? plot->interactionLegendTitleVisible : true;
    if (isNewPlot) {
        plot = new PlotModel();
        rlispstat::core::PopulateDatasetSeedPlot(*plot, df, df.group);
        plot->id = (simpleEffect ? "pooled_effect_" : "pooled_interaction_") + df.group + "_" +
            std::to_string((long long)time(nullptr)) + "_" +
            std::to_string(std::rand() % 1000000);
    }
    plot->kind = "glm_interaction";
    plot->isDatasetSeed = false;
    plot->isGLMDiagnostic = false;
    plot->isGLMInteractionPlot = true;
    plot->glmModelId = analysisId;
    plot->glmInteractionTerm = term;
    plot->isRegressionDerivedPlot = !derivedLink.sourceModelId.empty();
    plot->regressionDerivedKind = plot->isRegressionDerivedPlot
        ? (simpleEffect ? "effect_plot" : "interaction_plot") : std::string();
    plot->regressionDerivedSourceKind = derivedLink.sourceModelKind;
    plot->regressionDerivedSourceModelId = derivedLink.sourceModelId;
    plot->regressionDerivedSourceRevision = derivedLink.sourceModelRevision;
    plot->regressionDerivedSourceFitVersion = derivedLink.sourceFitVersion;
    plot->regressionDerivedTerm = term;
    plot->group = df.group;
    plot->points.clear();
    plot->interactionPlotLines = pooled.lines;
    plot->interactionXTicks = pooled.xTicks;
    plot->interactionXTickRows = pooled.xTickCaseIds;
    plot->interactionLegendTitleOverride = preservedLegendTitleOverride;
    plot->interactionLegendTitleVisible = preservedLegendTitleVisible;
    rlispstat::core::ApplyRegressionInteractionPresentation(*plot, pooled, response);
    rlispstat::core::ApplyRegressionInteractionVariableLabels(
        *plot, pooled, df, response);
    plot->rExportTheme = MacCommandDispatcher().plotTheme();
    plot->regressionConnectEstimates = preservedConnectEstimates;
    plot->regressionConfidenceIntervalsVisible = preservedIntervalsVisible;
    plot->regressionConfidenceLevelVisible = preservedLevelVisible;
    plot->interactionLegendPosition = preservedLegendPosition;
    plot->interactionLegendUsesCustomPosition = preservedCustomLegendPosition;
    plot->interactionLegendX = preservedLegendX;
    plot->interactionLegendY = preservedLegendY;
    plot->overlays.clear();
    for (const InteractionPlotLine &line : plot->interactionPlotLines) {
        plot->points.insert(plot->points.end(), line.points.begin(), line.points.end());
    }
    if (plot->points.empty()) {
        if (isNewPlot) delete plot;
        if (message) *message = "R returned no finite pooled fitted values for the effect plot.";
        return "";
    }
    ComputeRanges(plot);
    rlispstat::core::ApplyRegressionInteractionAxisRange(*plot);
    const auto &applicationState = MacCommandDispatcher().applicationState();
    const auto *source = derivedLink.sourceModelId.empty()
        ? applicationState.outputCodeReference(analysisId)
        : applicationState.regressionSourceOutputCodeReference(
            derivedLink.sourceModelKind, derivedLink.sourceModelId);
    if (source) {
        plot->codeReference = rlispstat::core::RegressionInteractionPlotCodeReference(
            *plot, pooled, *source);
        MacCommandDispatcher().applicationState().registerOutputCodeReference(
            plot->codeReference);
    }
    if (isNewPlot) {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(plot)) {
            delete plot;
            if (message) *message = "Could not register the pooled effect plot.";
            return "";
        }
    }
    if (isNewPlot) {
        PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", plot->group, plot->id, analysisId);
        AddPlotOnMain(plot);
    } else {
        // Drawing consults linked-selection state protected by g_mutex.  Never
        // force AppKit to draw while that mutex is held: drawRect: would try to
        // acquire it again and permanently deadlock the application.
        std::vector<ScatterView *> views;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            for (ScatterView *view : g_views) {
                if (view.model == plot) views.push_back(view);
            }
        }
        for (ScatterView *view : views) {
            [view setNeedsDisplay:YES];
            [view displayIfNeeded];
        }
    }
    return plot->id;
}

static std::string OpenRBackedInteractionPlot(
    const DataFrameModel &df,
    const std::string &mode,
    const std::string &analysisId,
    const std::string &response,
    const std::vector<std::string> &terms,
    const std::string &scope,
    const std::string &modelSpec,
    const std::string &term,
    std::string *message,
    const RegressionInteractionDerivedLink &derivedLink = {})
{
    rlispstat::core::RegressionInteractionPlotResult pooled;
    if (!RunRBackedInteractionPlot(df, mode, analysisId, response, terms,
                                   scope, modelSpec, term, &pooled, message,
                                   std::string(), derivedLink)) {
        return "";
    }
    return ApplyRBackedInteractionPlotResult(
        df, analysisId, response, term, std::move(pooled), message, derivedLink);
}

