- (NSView *)accessoryView
{
    return _view;
}

- (void)datasetChanged:(id)sender
{
    (void)sender;
    NSString *title = [_datasetPopup titleOfSelectedItem];
    _selectedGroup = title ? std::string([title UTF8String]) : "";
    [self reloadVariableRows];
}

- (void)reloadVariableRows
{
    const MissingDataImputationDialogState dialogState = BuildMissingDataImputationDialogState();
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_selectedGroup);
        if (current) {
            df = *current;
            found = true;
        }
    }
    [_imputeButtons removeAllObjects];
    [_methodPopups removeAllObjects];
    [_predictorButtons removeAllObjects];
    _rowNames.clear();

    size_t rowCount = found ? df.columns.size() : 0;
    CGFloat rowHeight = 28.0;
    CGFloat docHeight = std::max<CGFloat>(248.0, 34.0 + rowHeight * (CGFloat)rowCount + 8.0);
    NSView *rowsView = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 620, docHeight)];
    CGFloat headerY = docHeight - 24.0;
    [rowsView addSubview:GLMLabel(ToNSString(dialogState.imputeColumnTitle), NSMakeRect(8, headerY, 190, 18), 11, NSFontWeightSemibold)];
    [rowsView addSubview:GLMLabel(ToNSString(dialogState.typeMissingColumnTitle), NSMakeRect(220, headerY, 120, 18), 11, NSFontWeightSemibold)];
    [rowsView addSubview:GLMLabel(ToNSString(dialogState.methodColumnTitle), NSMakeRect(350, headerY, 92, 18), 11, NSFontWeightSemibold)];
    [rowsView addSubview:GLMLabel(ToNSString(dialogState.predictorColumnTitle), NSMakeRect(468, headerY, 120, 18), 11, NSFontWeightSemibold)];

    if (!found) {
        NSTextField *empty = GLMLabel(ToNSString(dialogState.unavailableDatasetRowText), NSMakeRect(8, headerY - 34.0, 560, 22), 12, NSFontWeightRegular);
        [empty setTextColor:[NSColor colorWithCalibratedWhite:0.4 alpha:1.0]];
        [rowsView addSubview:empty];
        [_summaryField setStringValue:ToNSString(dialogState.unavailableDatasetRowText)];
        [_deselectAllButton setEnabled:NO];
        [_deselectPredictorsButton setEnabled:NO];
        [_scrollView setDocumentView:rowsView];
        return;
    }
    [_deselectAllButton setEnabled:YES];
    [_deselectPredictorsButton setEnabled:YES];

    int defaultImputeCount = 0;
    int missingColumnCount = 0;
    for (size_t i = 0; i < df.columns.size(); ++i) {
        const DataColumn &col = df.columns[i];
        bool supported = DataColumnSupportedForMice(col);
        bool allMissing = DataColumnAllMissing(col);
        bool idLike = DataColumnLooksLikeId(col);
        int missing = DataColumnMissingCount(col);
        if (missing > 0) ++missingColumnCount;
        bool canImpute = supported && missing > 0 && !allMissing;
        bool defaultImpute = canImpute && !idLike;
        bool canPredict = supported && !allMissing && !idLike;
        bool defaultPredict = canPredict && !idLike;
        if (defaultImpute) ++defaultImputeCount;
        CGFloat y = headerY - 30.0 - (CGFloat)i * rowHeight;

        _rowNames.push_back(col.name);
        NSButton *impute = [[NSButton alloc] initWithFrame:NSMakeRect(4, y - 2.0, 206, 24)];
        [impute setButtonType:NSButtonTypeSwitch];
        [impute setTitle:ToNSString(col.name)];
        [impute setState:defaultImpute ? NSControlStateValueOn : NSControlStateValueOff];
        [impute setEnabled:canImpute];
        [rowsView addSubview:impute];
        [_imputeButtons addObject:impute];

        std::string status = MiceVariableStatusText(col, df.rows);
        NSTextField *statusField = GLMLabel(ToNSString(status), NSMakeRect(220, y, 122, 20), 11, NSFontWeightRegular);
        [statusField setTextColor:[NSColor colorWithCalibratedWhite:0.38 alpha:1.0]];
        [rowsView addSubview:statusField];

        NSPopUpButton *method = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(348, y - 3.0, 96, 25)];
        std::vector<std::string> methodOptions = MiceMethodOptions(col);
        if (methodOptions.empty()) {
            [method addItemWithTitle:ToNSString(dialogState.unsupportedMethodTitle)];
        } else {
            for (const std::string &option : methodOptions) [method addItemWithTitle:ToNSString(option)];
            std::string defaultMethod = DefaultMiceMethod(col);
            if (!defaultMethod.empty()) [method selectItemWithTitle:ToNSString(defaultMethod)];
        }
        [method setEnabled:canImpute];
        [rowsView addSubview:method];
        [_methodPopups addObject:method];

        NSButton *predictor = [[NSButton alloc] initWithFrame:NSMakeRect(464, y - 2.0, 124, 24)];
        [predictor setButtonType:NSButtonTypeSwitch];
        [predictor setTitle:ToNSString(dialogState.predictorUseTitle)];
        [predictor setState:defaultPredict ? NSControlStateValueOn : NSControlStateValueOff];
        [predictor setEnabled:canPredict];
        [rowsView addSubview:predictor];
        [_predictorButtons addObject:predictor];
    }
    [_scrollView setDocumentView:rowsView];
    [_summaryField setStringValue:ToNSString(MiceDatasetSummaryText(df, missingColumnCount, defaultImputeCount))];
}

- (void)updateSelectionSummary
{
    NSUInteger imputeCount = 0;
    NSUInteger predictorCount = 0;
    for (NSButton *button in _imputeButtons) {
        if ([button state] == NSControlStateValueOn) ++imputeCount;
    }
    for (NSButton *button in _predictorButtons) {
        if ([button state] == NSControlStateValueOn) ++predictorCount;
    }
    [_summaryField setStringValue:ToNSString(MiceSelectionSummaryText(imputeCount, predictorCount))];
}

- (void)deselectAllVariables:(id)sender
{
    (void)sender;
    for (NSButton *button in _imputeButtons) {
        if ([button isEnabled]) [button setState:NSControlStateValueOff];
    }
    for (NSButton *button in _predictorButtons) {
        if ([button isEnabled]) [button setState:NSControlStateValueOff];
    }
    [self updateSelectionSummary];
}

- (void)deselectPredictorVariables:(id)sender
{
    (void)sender;
    for (NSButton *button in _predictorButtons) {
        if ([button isEnabled]) [button setState:NSControlStateValueOff];
    }
    [self updateSelectionSummary];
}

- (std::string)selectedGroup
{
    return _selectedGroup;
}

- (std::string)imputeText
{
    std::vector<std::string> selected;
    for (NSUInteger i = 0; i < [_imputeButtons count] && i < _rowNames.size(); ++i) {
        NSButton *button = [_imputeButtons objectAtIndex:i];
        if ([button state] == NSControlStateValueOn) selected.push_back(_rowNames[(size_t)i]);
    }
    return JoinStrings(selected, "\t");
}

- (std::string)predictorText
{
    std::vector<std::string> selected;
    for (NSUInteger i = 0; i < [_predictorButtons count] && i < _rowNames.size(); ++i) {
        NSButton *button = [_predictorButtons objectAtIndex:i];
        if ([button state] == NSControlStateValueOn) selected.push_back(_rowNames[(size_t)i]);
    }
    return JoinStrings(selected, "\t");
}

- (std::string)methodText
{
    const MissingDataImputationDialogState dialogState = BuildMissingDataImputationDialogState();
    std::vector<std::string> selected;
    for (NSUInteger i = 0; i < [_imputeButtons count] && i < [_methodPopups count] && i < _rowNames.size(); ++i) {
        NSButton *button = [_imputeButtons objectAtIndex:i];
        if ([button state] != NSControlStateValueOn) continue;
        NSPopUpButton *popup = [_methodPopups objectAtIndex:i];
        NSString *method = [popup titleOfSelectedItem];
        if (!method || std::string([method UTF8String]) == dialogState.unsupportedMethodTitle) continue;
        selected.push_back(_rowNames[(size_t)i] + "=" + std::string([method UTF8String]));
    }
    return JoinStrings(selected, "\t");
}

- (int)imputationCount
{
    return std::max(1, [[_mField stringValue] intValue]);
}

- (int)iterationCount
{
    return std::max(0, [[_maxitField stringValue] intValue]);
}

- (std::string)seedText
{
    NSString *seed = [_seedField stringValue];
    return seed ? std::string([seed UTF8String]) : "";
}

- (bool)openDataSheet
{
    return [_openSheetButton state] == NSControlStateValueOn;
}

@end

static void ShowMissingDataImputationDialogOnMain(PlotModel *model)
{
    const MissingDataImputationDialogState dialogState = BuildMissingDataImputationDialogState();
    std::string selectedGroup;
    std::vector<std::string> groups;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        selectedGroup = model ? model->group : ActiveDatasetGroupUnlocked();
        groups = DatasetGroupsUnlocked();
    }
    std::string selectedGroupCopy = selectedGroup;
    std::vector<std::string> groupsCopy = groups;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::string dialogSelectedGroup = selectedGroupCopy;
      std::vector<std::string> dialogGroups = groupsCopy;
      if (dialogGroups.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
                                     ToNSString(NoActiveDatasetImportOrRegisterStatus()));
          return;
      }
      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.runButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];

      MissingDataImputationDialogController *dialog =
          [[MissingDataImputationDialogController alloc] initWithGroups:dialogGroups selectedGroup:dialogSelectedGroup];
      [alert setAccessoryView:[dialog accessoryView]];
      if ([alert runModal] != NSAlertFirstButtonReturn) return;

      std::string group = [dialog selectedGroup];
      std::string impute = [dialog imputeText];
      std::string predictors = [dialog predictorText];
      std::string methods = [dialog methodText];
      int m = [dialog imputationCount];
      int maxit = [dialog iterationCount];
      std::string seed = [dialog seedText];
      bool openDataSheet = [dialog openDataSheet];
      if (impute.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
                                     ToNSString(dialogState.noImputeVariablesStatus));
          return;
      }
      if (predictors.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
                                     ToNSString(dialogState.noPredictorVariablesStatus));
          return;
      }
      DataFrameModel df;
      std::string outputGroup;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          const DataFrameModel *current = FindDataFrameUnlockedConst(group);
          if (!current) {
              ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
                                         ToNSString(dialogState.datasetUnavailableStatus));
              return;
          }
          const auto scope = MacCommandDispatcher().applicationState().activeAnalysisScope(group);
          const auto rows = rlispstat::core::ResolveAnalysisScopeRowIds(scope, current->rows);
          if (rows.empty()) {
              ShowWorkbenchMessageOnMain(@"Multiple Imputation", @"The global analysis scope contains no observations.");
              return;
          }
          df = rlispstat::core::SubsetDataFrame(*current, rows, current->group);
      }
      outputGroup = UniqueNativeDatasetNameFromBase(group + " imputed");
      std::thread worker([df, outputGroup, impute, predictors, methods, m, maxit, seed, openDataSheet]() {
          std::string message;
          const MissingDataImputationDialogState workerDialogState = BuildMissingDataImputationDialogState();
          bool ok = RunNativeMiceImputation(df, outputGroup, impute, predictors, methods, m, maxit, seed, openDataSheet, &message);
          ShowWorkbenchMessageOnMain(ToNSString(ok ? workerDialogState.title : workerDialogState.failedTitle),
                                     ToNSString(message));
      });
      worker.detach();
    });
}

static void ShowMissingDataPatternsDialogOnMain(const std::string &group, bool models)
{
    DataFrameModel df;
    rlispstat::core::AnalysisScope scope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto* source=FindDataFrameUnlockedConst(group); if(!source)return;
        df=*source; scope=MacCommandDispatcher().applicationState().activeAnalysisScope(group);
    }
    dispatch_async(dispatch_get_main_queue(), ^{
        const auto capabilities=rlispstat::core::MissingDataCapabilitiesFor(df);
        if(models && !capabilities.models) {
            ShowWorkbenchMessageOnMain(@"Missingness Models",ToNSString(capabilities.modelsUnavailableReason));
            return;
        }
        NSAlert* alert=[[NSAlert alloc] init];
        [alert setMessageText:models?@"Missingness Models":@"Missing Data Overview"];
        [alert setInformativeText:models?
            @"Model whether a variable is missing using observed predictors. This investigates associations with missingness; it does not establish MAR. Rows with missing predictors are excluded.":
            @"Choose variables for the missingness table. You can add or remove variables, open descriptives, request Little’s test, and save derived columns from the results window."];
        [alert addButtonWithTitle:models?@"Fit model":@"Analyze"];
        [alert addButtonWithTitle:@"Cancel"];
        NSView* view=[[NSView alloc] initWithFrame:NSMakeRect(0,0,660,430)];
        auto label=[&](NSString* text,CGFloat x,CGFloat y,CGFloat width){NSTextField* f=[NSTextField labelWithString:text];[f setFrame:NSMakeRect(x,y,width,24)];[view addSubview:f];};
        label(@"Data source",0,402,90);
        NSPopUpButton* source=[[NSPopUpButton alloc] initWithFrame:NSMakeRect(100,400,340,26) pullsDown:NO];
        if(capabilities.original)[source addItemWithTitle:@"Original data before imputation"];
        [source addItemWithTitle:@"Current/active data"];[view addSubview:source];
        NSPopUpButton* target=[[NSPopUpButton alloc] initWithFrame:NSMakeRect(100,367,530,26) pullsDown:NO];
        if(models) {label(@"Target",0,369,90);for(const auto& c:capabilities.targets)[target addItemWithTitle:ToNSString(c)];[view addSubview:target];}
        label(ToNSString(rlispstat::core::AnalysisScopeSummary(scope,scope.totalDatasetRows)),0,338,650);
        label(models?@"Predictors":@"Variables",0,310,310);

        std::vector<NSButton*> first,second;
        auto list=[&](CGFloat x,std::vector<NSButton*>& buttons,bool descriptions){
            NSScrollView* scroll=[[NSScrollView alloc] initWithFrame:NSMakeRect(x,112,650,194)];
            [scroll setHasVerticalScroller:YES];[scroll setBorderType:NSBezelBorder];
            NSView* content=[[NSView alloc] initWithFrame:NSMakeRect(0,0,630,df.columns.size()*25)];
            for(size_t i=0;i<df.columns.size();++i){const auto& c=df.columns[i];
                NSButton* b=[[NSButton alloc] initWithFrame:NSMakeRect(6,(df.columns.size()-i-1)*25,615,24)];
                [b setButtonType:NSButtonTypeSwitch];[b setTitle:ToNSString(c.name+" ("+c.type+")")];
                const bool supported=c.type!="character" && c.type!="text";
                [b setEnabled:!descriptions || supported];
                [b setState:(!models && (!descriptions || supported))?NSControlStateValueOn:NSControlStateValueOff];
                [content addSubview:b];buttons.push_back(b);
            }
            [scroll setDocumentView:content];[view addSubview:scroll];
        };
        list(0,first,models);
        if(models)label(@"Save to data (optional)",0,81,650);
        const std::vector<std::pair<std::string,std::string>> choices=models?
            std::vector<std::pair<std::string,std::string>>{{"indicator","Missingness indicator"},{"probability","Predicted probability"}}:
            std::vector<std::pair<std::string,std::string>>{{"pattern","Missingness pattern"},{"n_missing","Number missing"},{"pct_missing","Percent missing"},{"indicators","Variable indicators"}};
        std::vector<NSButton*> save;
        for(size_t i=0;models && i<choices.size();++i){NSButton* b=[[NSButton alloc] initWithFrame:NSMakeRect((i%2)*330,52-(i/2)*26,325,24)];[b setButtonType:NSButtonTypeSwitch];[b setTitle:ToNSString(choices[i].second)];[view addSubview:b];save.push_back(b);}
        [alert setAccessoryView:view];if([alert runModal]!=NSAlertFirstButtonReturn)return;
        std::vector<std::string> variables,descriptions,saved;
        const std::string selectedTarget=models?std::string([[[target selectedItem] title] UTF8String]):"";
        for(size_t i=0;i<first.size();++i)if([first[i] state]==NSControlStateValueOn && df.columns[i].name!=selectedTarget)variables.push_back(df.columns[i].name);
        for(size_t i=0;i<second.size();++i)if([second[i] state]==NSControlStateValueOn)descriptions.push_back(df.columns[i].name);
        for(size_t i=0;i<save.size();++i)if([save[i] state]==NSControlStateValueOn)saved.push_back(choices[i].first);
        auto task=rlispstat::core::MissingDataWorkflowTask(df,models,
            capabilities.original && [source indexOfSelectedItem]==0?"original":"active",
            selectedTarget,variables,descriptions,saved,scope);
        {std::lock_guard<std::mutex> lock(g_mutex);g_pendingMissingDataTasks.push_back(task);}
        NotifyMainRTaskAvailable();
    });
}

static void ShowNewLinkedScatterplotDialogOnMain(PlotModel *model)
{
    const ScatterplotCreationDialogState dialogState = BuildScatterplotCreationDialogState();
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(NoActiveDatasetTitle()), ToNSString(dialogState.noActiveDatasetStatus));
        return;
    }

    dispatch_async(dispatch_get_main_queue(), ^{
      PlotModel seed;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          seed = *model;
      }
      DataFrameModel dataframe;
      if (!DataFrameSnapshotForGroup(seed.group, dataframe)) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), @"The active dataset is not available.");
          return;
      }
      const auto initial = ResolveInitialAnalysisForGroup(
          dataframe, rlispstat::core::SharedAnalysisKind::Scatterplot);
      const std::string initialX =
          rlispstat::core::InitialAnalysisVariable(initial, "x");
      const std::string initialY =
          rlispstat::core::InitialAnalysisVariable(initial, "y");
      if (seed.variables.size() < 2) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.needsTwoNumericVariablesStatus));
          return;
      }

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.createButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];

      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 360, 118)];
      NSTextField *dataset = GLMLabel(ToNSString(DatasetDialogLabel(seed.group)), NSMakeRect(0, 92, 340, 20), 12, NSFontWeightMedium);
      [accessory addSubview:dataset];
      NSTextField *xLabel = GLMLabel(ToNSString(rlispstat::core::ScatterplotXFieldLabel()), NSMakeRect(0, 62, 30, 22), 12, NSFontWeightRegular);
      NSTextField *yLabel = GLMLabel(ToNSString(rlispstat::core::ScatterplotYFieldLabel()), NSMakeRect(0, 32, 30, 22), 12, NSFontWeightRegular);
      [accessory addSubview:xLabel];
      [accessory addSubview:yLabel];

      NSPopUpButton *xPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(34, 58, 150, 28)];
      NSPopUpButton *yPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(34, 28, 150, 28)];
      [xPopup addItemWithTitle:@"Choose..."];
      [yPopup addItemWithTitle:@"Choose..."];
      for (const NumericVariable &var : seed.variables) {
          [xPopup addItemWithTitle:ToNSString(var.name)];
          [yPopup addItemWithTitle:ToNSString(var.name)];
      }
      if (!initialX.empty()) [xPopup selectItemWithTitle:ToNSString(initialX)];
      if (!initialY.empty()) [yPopup selectItemWithTitle:ToNSString(initialY)];
      [accessory addSubview:xPopup];
      [accessory addSubview:yPopup];

      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(194, 32, 156, 24)];
      [titleField setStringValue:@""];
      [titleField setPlaceholderString:ToNSString(dialogState.optionalTitlePlaceholder)];
      [accessory addSubview:titleField];
      [alert setAccessoryView:accessory];

      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::string x = [[xPopup titleOfSelectedItem] UTF8String];
      std::string y = [[yPopup titleOfSelectedItem] UTF8String];
      if (x == "Choose..." || y == "Choose..." || x == y) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
              @"Choose two different numeric variables.");
          return;
      }
      std::string title = [[titleField stringValue] UTF8String];
      if (title.empty()) {
          title = ScatterplotDefaultTitle(x, y);
      }

	      PlotModel *created = new PlotModel(seed);
	      created->kind = "scatter";
	      created->isDatasetSeed = false;
	      created->isGLMDiagnostic = false;
	      created->id = "plot_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
      created->xLabel = x;
      created->yLabel = y;
      created->title = title;
      created->overlays.clear();
      created->nextOverlayId = 1;
      created->interactionMode = "select";
      created->selectionMode = "replace";
      RebuildPointsForCurrentVariables(created);
      ComputeRanges(created);
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
          EnsureGroupModelUnlocked(created->group, created);
      }
      AddPlotOnMain(created);
    });
}

static void ShowNewTimeSeriesDialogOnMain(PlotModel *model)
{
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Time Series", @"Open or activate a dataset first.");
        return;
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      PlotModel seed;
      DataFrameModel dataframe;
      bool hasDataframe = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          seed = *model;
          const DataFrameModel *current = FindDataFrameUnlockedConst(seed.group);
          if (current) {
              dataframe = *current;
              hasDataframe = true;
          }
      }
      if (!hasDataframe || seed.variables.empty()) {
          ShowWorkbenchMessageOnMain(@"Time Series", @"The active dataset needs a numeric value variable and a numeric or date/time variable.");
          return;
      }
      const auto initial = ResolveInitialAnalysisForGroup(
          dataframe, rlispstat::core::SharedAnalysisKind::TimeSeries);
      const std::string initialTime =
          rlispstat::core::InitialAnalysisVariable(initial, "x");
      const std::string initialValue =
          rlispstat::core::InitialAnalysisVariable(initial, "y");
      const std::vector<std::string> initialSeries =
          rlispstat::core::InitialAnalysisVariables(initial, "conditioning");

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:@"Time Series"];
      [alert setInformativeText:@"Choose a time variable, a numeric value, and optionally a variable identifying the series."];
      [alert addButtonWithTitle:@"Create"];
      [alert addButtonWithTitle:@"Cancel"];
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 410, 158)];
      [accessory addSubview:GLMLabel(ToNSString(DatasetDialogLabel(seed.group)),
                                     NSMakeRect(0, 132, 390, 20), 12, NSFontWeightMedium)];
      [accessory addSubview:GLMLabel(@"Time", NSMakeRect(0, 98, 74, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(@"Value", NSMakeRect(0, 66, 74, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(@"Series", NSMakeRect(0, 34, 74, 22), 12, NSFontWeightRegular)];

      NSPopUpButton *timePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(76, 94, 160, 28)];
      NSPopUpButton *valuePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(76, 62, 160, 28)];
      [timePopup addItemWithTitle:@"Choose..."];
      [valuePopup addItemWithTitle:@"Choose..."];
      for (const DataColumn &column : dataframe.columns) {
          if (rlispstat::core::AnalysisVariableIsCompatible(
                  column, rlispstat::core::AnalysisVariableType::DateTimeOrNumeric)) {
              [timePopup addItemWithTitle:ToNSString(column.name)];
          }
      }
      for (const NumericVariable &variable : seed.variables) {
          [valuePopup addItemWithTitle:ToNSString(variable.name)];
      }
      if (!initialTime.empty()) [timePopup selectItemWithTitle:ToNSString(initialTime)];
      if (!initialValue.empty()) [valuePopup selectItemWithTitle:ToNSString(initialValue)];
      [accessory addSubview:timePopup];
      [accessory addSubview:valuePopup];

      NSPopUpButton *seriesPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(76, 30, 160, 28)];
      [seriesPopup addItemWithTitle:@"(none)"];
      for (const DataColumn &column : dataframe.columns) {
          if (rlispstat::core::AnalysisVariableIsCompatible(
                  column, rlispstat::core::AnalysisVariableType::Categorical))
              [seriesPopup addItemWithTitle:ToNSString(column.name)];
      }
      if (initialSeries.size() == 1)
          [seriesPopup selectItemWithTitle:ToNSString(initialSeries.front())];
      [accessory addSubview:seriesPopup];
      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(250, 62, 154, 24)];
      [titleField setPlaceholderString:@"Optional title"];
      [accessory addSubview:titleField];
      NSTextField *hint = GLMLabel(@"Rows are ordered by time within each series.",
                                   NSMakeRect(0, 2, 400, 20), 11, NSFontWeightRegular);
      [hint setTextColor:[NSColor secondaryLabelColor]];
      [accessory addSubview:hint];
      [alert setAccessoryView:accessory];
      if ([alert runModal] != NSAlertFirstButtonReturn) return;

      const std::string timeVariable = [[timePopup titleOfSelectedItem] UTF8String];
      const std::string valueVariable = [[valuePopup titleOfSelectedItem] UTF8String];
      if (timeVariable == "Choose..." || valueVariable == "Choose..." ||
          timeVariable == valueVariable) {
          ShowWorkbenchMessageOnMain(@"Time Series",
              @"Choose different compatible time and value variables.");
          return;
      }
      NSString *seriesSelection = [seriesPopup titleOfSelectedItem];
      const std::string seriesVariable = [seriesSelection isEqualToString:@"(none)"]
          ? std::string() : std::string([seriesSelection UTF8String]);
      std::string timeType = "numeric";
      const DataColumn *selectedTimeColumn = FindDataColumnInDataFrame(dataframe, timeVariable);
      if (selectedTimeColumn) {
          timeType = rlispstat::core::InferTimeSeriesTimeType(*selectedTimeColumn);
      }

      PlotModel *created = new PlotModel(seed);
      created->kind = "time_series";
      created->isDatasetSeed = false;
      created->isGLMDiagnostic = false;
      created->id = "timeseries_" + std::to_string((long long)time(nullptr)) + "_" +
          std::to_string(std::rand() % 1000000);
      created->xLabel = timeVariable;
      created->yLabel = valueVariable;
      created->timeSeriesGroupVariable = seriesVariable;
      created->timeSeriesTimeType = timeType;
      created->title = [[titleField stringValue] length] > 0
          ? std::string([[titleField stringValue] UTF8String])
          : valueVariable + " over " + timeVariable;
      created->overlays.clear();
      created->smoothCurves.clear();
      created->interactionMode = "select";
      created->selectionMode = "replace";
      std::string error;
      if (!rlispstat::core::RebuildTimeSeriesFromDataFrame(*created, dataframe, &error)) {
          delete created;
          ShowWorkbenchMessageOnMain(@"Time Series", ToNSString(error));
          return;
      }
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
          EnsureGroupModelUnlocked(created->group, created);
      }
      AddPlotOnMain(created);
    });
}

@interface TrellisScatterplotDialogValidator : NSObject
@property(nonatomic, assign) NSPopUpButton *xPopup;
@property(nonatomic, assign) NSPopUpButton *yPopup;
@property(nonatomic, assign) NSPopUpButton *conditionPopup;
@property(nonatomic, assign) NSButton *createButton;
@property(nonatomic, assign) BOOL requiresY;
@property(nonatomic, assign) BOOL requiresDifferentXY;
- (void)updateCreateButton:(id)sender;
@end

@implementation TrellisScatterplotDialogValidator
- (void)updateCreateButton:(id)sender
{
    (void)sender;
    NSString *x = [self.xPopup titleOfSelectedItem];
    NSString *y = [self.yPopup titleOfSelectedItem];
    BOOL yOK = !self.requiresY || y.length > 0;
    BOOL distinctOK = !self.requiresDifferentXY || ![x isEqualToString:y];
    [self.createButton setEnabled:x.length > 0 && yOK && distinctOK &&
        self.conditionPopup.titleOfSelectedItem.length > 0];
}
@end

static void ShowNewTrellisScatterplotDialogOnMain(PlotModel *model,
                                                  const std::string &initialType)
{
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Trellis Plots", @"Open or activate a dataset first.");
        return;
    }
    const TrellisPlotType plotType =
        rlispstat::core::ParseTrellisPlotType(initialType).value_or(TrellisPlotType::Scatter);
    dispatch_async(dispatch_get_main_queue(), ^{
      PlotModel seed;
      DataFrameModel dataframe;
      bool found = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          seed = *model;
          const DataFrameModel *current = FindDataFrameUnlockedConst(seed.group);
          if (current) { dataframe = *current; found = true; }
      }
      std::vector<std::string> numeric;
      std::vector<std::string> timeVariables;
      std::vector<std::string> categorical;
      std::vector<std::string> conditioning;
      std::vector<std::string> seriesVariables;
      if (found) {
          for (const DataColumn &column : dataframe.columns) {
              if (NormalizeVariableType(column.type) == "numeric" && DataColumnAllowsNumeric(column)) {
                  numeric.push_back(column.name);
                  timeVariables.push_back(column.name);
              } else if (NormalizeVariableType(column.type) == "datetime") {
                  timeVariables.push_back(column.name);
              }
              if (rlispstat::core::TrellisConditionColumnIsValid(column, dataframe.rows)) {
                  categorical.push_back(column.name);
                  conditioning.push_back(column.name);
              }
              if (VariableTypeIsFactorLike(column.type)) {
                  seriesVariables.push_back(column.name);
              }
          }
      }
      const bool requiresY = plotType == TrellisPlotType::Scatter ||
          plotType == TrellisPlotType::TimeSeries || plotType == TrellisPlotType::Boxplot;
      const bool requiresDifferentXY = plotType == TrellisPlotType::Scatter ||
          plotType == TrellisPlotType::TimeSeries;
      const std::vector<std::string> &xVariables =
          plotType == TrellisPlotType::TimeSeries ? timeVariables :
          (plotType == TrellisPlotType::Boxplot || plotType == TrellisPlotType::Bar)
              ? categorical : numeric;
      const auto sharedKind = plotType == TrellisPlotType::TimeSeries
          ? rlispstat::core::SharedAnalysisKind::TimeSeries
          : plotType == TrellisPlotType::Boxplot
              ? rlispstat::core::SharedAnalysisKind::Boxplot
              : plotType == TrellisPlotType::Bar
                  ? rlispstat::core::SharedAnalysisKind::BarChart
                  : plotType == TrellisPlotType::Histogram
                      ? rlispstat::core::SharedAnalysisKind::Histogram
                      : rlispstat::core::SharedAnalysisKind::TrellisPlot;
      const auto initial = ResolveInitialAnalysisForGroup(dataframe, sharedKind);
      const std::string initialX =
          rlispstat::core::InitialAnalysisVariable(initial, "x");
      const std::string initialY =
          rlispstat::core::InitialAnalysisVariable(initial, "y");
      const auto initialConditions =
          rlispstat::core::InitialAnalysisVariables(initial, "conditioning");
      NSString *plotName = plotType == TrellisPlotType::Scatter ? @"Scatterplot" :
          plotType == TrellisPlotType::TimeSeries ? @"Time Series" :
          plotType == TrellisPlotType::Boxplot ? @"Boxplot" :
          plotType == TrellisPlotType::Bar ? @"Bar Chart" : @"Histogram";
      if (xVariables.empty() || (requiresY && numeric.empty()) ||
          (requiresDifferentXY && xVariables.size() == 1 && numeric.size() == 1 &&
           xVariables.front() == numeric.front())) {
          ShowWorkbenchMessageOnMain(@"Trellis Plots",
              [NSString stringWithFormat:@"The active dataset does not contain suitable variables for a trellis %@.", plotName]);
          return;
      }
      if (conditioning.empty()) {
          ShowWorkbenchMessageOnMain(@"Trellis Plots", @"The active dataset has no suitable categorical or discrete numeric conditioning variable.");
          return;
      }

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:[NSString stringWithFormat:@"Trellis Plots — %@", plotName]];
      [alert setInformativeText:@"Choose the variables for the initial plot and a conditioning variable. The plot type can still be changed later from its context menu."];
      [alert addButtonWithTitle:@"Create"];
      [alert addButtonWithTitle:@"Cancel"];
      const BOOL isTimeSeries = plotType == TrellisPlotType::TimeSeries;
      const CGFloat extraHeight = isTimeSeries ? 32.0 : 0.0;
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 440, 170 + extraHeight)];
      [accessory addSubview:GLMLabel(ToNSString(DatasetDialogLabel(seed.group)), NSMakeRect(0, 144 + extraHeight, 420, 20), 12, NSFontWeightMedium)];
      [accessory addSubview:GLMLabel(@"X", NSMakeRect(0, 108 + extraHeight, 86, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(@"Y", NSMakeRect(0, 76 + extraHeight, 86, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(@"Condition on", NSMakeRect(0, 44 + extraHeight, 86, 22), 12, NSFontWeightRegular)];
      NSPopUpButton *xPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(90, 104 + extraHeight, 174, 28)];
      NSPopUpButton *yPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(90, 72 + extraHeight, 174, 28)];
      [xPopup addItemWithTitle:@""];
      [yPopup addItemWithTitle:@""];
      for (const std::string &name : xVariables) [xPopup addItemWithTitle:ToNSString(name)];
      for (const std::string &name : numeric) [yPopup addItemWithTitle:ToNSString(name)];
      if (!requiresY) {
          [yPopup removeAllItems];
          [yPopup addItemWithTitle:@"—"];
          [yPopup setEnabled:NO];
      }
      if (!initialX.empty()) [xPopup selectItemWithTitle:ToNSString(initialX)];
      if (requiresY && !initialY.empty())
          [yPopup selectItemWithTitle:ToNSString(initialY)];
      NSPopUpButton *conditionPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(90, 40 + extraHeight, 174, 28)];
      [conditionPopup addItemWithTitle:@""];
      for (const std::string &name : conditioning) [conditionPopup addItemWithTitle:ToNSString(name)];
      if (initialConditions.size() == 1)
          [conditionPopup selectItemWithTitle:ToNSString(initialConditions.front())];
      NSPopUpButton *seriesPopup = nil;
      if (isTimeSeries) {
          [accessory addSubview:GLMLabel(@"Series", NSMakeRect(0, 44, 86, 22), 12, NSFontWeightRegular)];
          seriesPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(90, 40, 174, 28)];
          [seriesPopup addItemWithTitle:@"(none)"];
          for (const std::string &name : seriesVariables)
              [seriesPopup addItemWithTitle:ToNSString(name)];
          [accessory addSubview:seriesPopup];
      }
      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(278, 42 + extraHeight, 156, 24)];
      [titleField setPlaceholderString:@"Optional title"];
      [accessory addSubview:xPopup];
      [accessory addSubview:yPopup];
      [accessory addSubview:conditionPopup];
      [accessory addSubview:titleField];
      NSTextField *hint = GLMLabel(isTimeSeries
                                   ? @"Condition on creates panels; Series draws separate trajectories."
                                   : requiresDifferentXY
                                       ? @"X and Y must be different; conditioning is required."
                                       : @"A conditioning variable is required.",
                                   NSMakeRect(0, 7, 430, 20), 11, NSFontWeightRegular);
      [hint setTextColor:[NSColor secondaryLabelColor]];
      [accessory addSubview:hint];
      [alert setAccessoryView:accessory];
      TrellisScatterplotDialogValidator *validator = [[TrellisScatterplotDialogValidator alloc] init];
      validator.xPopup = xPopup;
      validator.yPopup = yPopup;
      validator.conditionPopup = conditionPopup;
      validator.createButton = alert.buttons.firstObject;
      validator.requiresY = requiresY;
      validator.requiresDifferentXY = requiresDifferentXY;
      [xPopup setTarget:validator]; [xPopup setAction:@selector(updateCreateButton:)];
      [yPopup setTarget:validator]; [yPopup setAction:@selector(updateCreateButton:)];
      [conditionPopup setTarget:validator]; [conditionPopup setAction:@selector(updateCreateButton:)];
      [validator updateCreateButton:nil];
      if ([alert runModal] != NSAlertFirstButtonReturn) return;

      const std::string xVariable = [[xPopup titleOfSelectedItem] UTF8String];
      const std::string yVariable = requiresY ? std::string([[yPopup titleOfSelectedItem] UTF8String]) : "";
      const std::string condition = [[conditionPopup titleOfSelectedItem] UTF8String];
      const std::string seriesVariable = isTimeSeries &&
          ![[seriesPopup titleOfSelectedItem] isEqualToString:@"(none)"]
          ? std::string([[seriesPopup titleOfSelectedItem] UTF8String]) : std::string();
      PlotModel *created = new PlotModel(seed);
      created->kind = "trellis_scatterplot";
      created->isDatasetSeed = false;
      created->isGLMDiagnostic = false;
      created->id = "trellis_scatterplot_" + std::to_string((long long)time(nullptr)) + "_" +
          std::to_string(std::rand() % 1000000);
      created->xLabel = xVariable;
      created->yLabel = yVariable;
      created->trellisConditionVariable = condition;
      created->trellisSpecification = TrellisPlotSpecification{};
      created->trellisSpecification.plotType = plotType;
      created->trellisSpecification.xVariableId = xVariable;
      created->trellisSpecification.yVariableId = yVariable;
      created->trellisSpecification.groupingVariableId = seriesVariable;
      created->timeSeriesGroupVariable = seriesVariable;
      TrellisConditioningVariable initialCondition;
      initialCondition.variableId = condition;
      initialCondition.variableLabel = condition;
      const DataColumn *conditionColumn = FindDataColumnInDataFrame(dataframe, condition);
      initialCondition.kind = conditionColumn
          ? rlispstat::core::TrellisConditioningKindForColumn(*conditionColumn)
          : TrellisConditioningVariableKind::Categorical;
      if (initialCondition.kind == TrellisConditioningVariableKind::ContinuousBinned) {
          TrellisContinuousBinningSpecification binning;
          binning.method = TrellisContinuousBinningMethod::EqualWidth;
          binning.binCount = 4;
          initialCondition.binning = std::move(binning);
      }
      initialCondition.dimension = TrellisDimension::Columns;
      created->trellisSpecification.conditioningVariables.push_back(initialCondition);
      created->trellisSpecificationInitialized = true;
      created->overlays.clear();
      created->smoothCurves.clear();
      created->interactionMode = "select";
      created->selectionMode = "replace";
      std::string error;
      if (!rlispstat::core::RebuildTrellisPlotFromDataFrame(*created, dataframe, &error)) {
          delete created;
          ShowWorkbenchMessageOnMain(@"Trellis Plots", ToNSString(error));
          return;
      }
      if ([[titleField stringValue] length] > 0) {
          created->trellisSpecification.hasCustomTitle = true;
          created->trellisSpecification.customTitle = [[titleField stringValue] UTF8String];
          created->title = created->trellisSpecification.customTitle;
      }
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
          EnsureGroupModelUnlocked(created->group, created);
      }
      AddPlotOnMain(created);
    });
}

@interface LinearModelTrellisDialogValidator : NSObject
@property(nonatomic, assign) NSPopUpButton *responsePopup;
@property(nonatomic, assign) NSPopUpButton *rowPopup;
@property(nonatomic, assign) NSPopUpButton *columnPopup;
@property(nonatomic, assign) NSButton *createButton;
- (void)updateCreateButton:(id)sender;
@end

@implementation LinearModelTrellisDialogValidator
- (void)updateCreateButton:(id)sender
{
    (void)sender;
    NSString *response=[[[self.responsePopup selectedItem] representedObject] description];
    NSString *row=[[[self.rowPopup selectedItem] representedObject] description];
    NSString *column=[[[self.columnPopup selectedItem] representedObject] description];
    BOOL conditioned=row.length>0||column.length>0;
    BOOL distinct=row.length==0||column.length==0||![row isEqualToString:column];
    [self.createButton setEnabled:response.length>0&&conditioned&&distinct];
}
@end

static void ShowNewLinearModelTrellisDialogOnMain(PlotModel *model)
{
    if(!model){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",@"Open or activate a dataset first.");return;}
    dispatch_async(dispatch_get_main_queue(),^{
      PlotModel seed;DataFrameModel data;bool found=false;{std::lock_guard<std::mutex>lock(g_mutex);seed=*model;const DataFrameModel*d=FindDataFrameUnlockedConst(seed.group);if(d){data=*d;found=true;}}
      if(!found){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",@"The active dataset is not available.");return;}
      std::vector<std::string>numeric;for(const auto&column:data.columns)if(NormalizeVariableType(column.type)=="numeric"&&DataColumnAllowsNumeric(column))numeric.push_back(column.name);
      if(numeric.empty()){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",@"The active dataset has no numeric variable suitable as a response.");return;}
      const auto initial=ResolveInitialAnalysisForGroup(
          data,rlispstat::core::SharedAnalysisKind::LinearModelTrellis);
      const std::string initialResponse=rlispstat::core::InitialAnalysisVariable(initial,"y");
