      NSPopUpButton*response=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(132,122,190,28)];[response addItemWithTitle:@"Choose..."];[[response lastItem]setRepresentedObject:@""];for(const auto&name:numeric){[response addItemWithTitle:ToNSString(name)];[[response lastItem]setRepresentedObject:ToNSString(name)];}if(!initialResponse.empty())[response selectItemWithTitle:ToNSString(initialResponse)];
      auto conditionPopup=^NSPopUpButton*(CGFloat y){NSPopUpButton*p=[[NSPopUpButton alloc]initWithFrame:NSMakeRect(132,y,190,28)];[p addItemWithTitle:@"None"];[[p lastItem]setRepresentedObject:@""];for(const auto&name:categorical){[p addItemWithTitle:ToNSString(name)];[[p lastItem]setRepresentedObject:ToNSString(name)];}return p;};
      NSPopUpButton*rows=conditionPopup(90);NSPopUpButton*columns=conditionPopup(58);bool assignedRow=false;for(const auto&term:initialConditions){auto found=std::find(categorical.begin(),categorical.end(),term);if(found==categorical.end())continue;NSInteger index=(NSInteger)std::distance(categorical.begin(),found)+1;if(!assignedRow){[rows selectItemAtIndex:index];assignedRow=true;}else{[columns selectItemAtIndex:index];break;}}
      NSPopUpButton*scope=[[GlobalAnalysisScopeSummary alloc]initWithFrame:NSMakeRect(132,26,190,28)];
      PopulateAnalysisScopePopup(scope,seed.group,"all",{},false,true);
      for(NSView*v in @[response,rows,columns,scope])[accessory addSubview:v];NSTextField*hint=GLMLabel(@"Conditioning variables cannot be repeated or used as predictors.",NSMakeRect(0,0,430,18),11,NSFontWeightRegular);[hint setTextColor:[NSColor secondaryLabelColor]];[accessory addSubview:hint];[alert setAccessoryView:accessory];
      LinearModelTrellisDialogValidator*validator=[[LinearModelTrellisDialogValidator alloc]init];validator.responsePopup=response;validator.rowPopup=rows;validator.columnPopup=columns;validator.createButton=alert.buttons.firstObject;[response setTarget:validator];[response setAction:@selector(updateCreateButton:)];[rows setTarget:validator];[rows setAction:@selector(updateCreateButton:)];[columns setTarget:validator];[columns setAction:@selector(updateCreateButton:)];[validator updateCreateButton:nil];
      if([alert runModal]!=NSAlertFirstButtonReturn)return;

      ModelTrellisState state;state.id="model_trellis:"+seed.group+":"+std::to_string((long long)time(nullptr))+":"+std::to_string(std::rand()%1000000);state.sourceModelGroup=seed.group;state.specification.baseModel.group=seed.group;state.specification.baseModel.response=[[[response selectedItem]representedObject]UTF8String];state.specification.baseModel.scope=SelectedAnalysisScopeChoice(scope);state.specification.panelContent=ModelTrellisPanelContent::CompactSummary;
      NSString*row=[[[rows selectedItem]representedObject]description];NSString*column=[[[columns selectedItem]representedObject]description];std::string error;if(row.length&&!rlispstat::core::SetModelTrellisConditioningVariable(state.specification,ModelTrellisDimension::Rows,std::string([row UTF8String]),data,&error)){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",ToNSString(error));return;}if(column.length&&!rlispstat::core::SetModelTrellisConditioningVariable(state.specification,ModelTrellisDimension::Columns,std::string([column UTF8String]),data,&error)){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",ToNSString(error));return;}for(const auto&term:initialPredictors){if(term==state.specification.baseModel.response||term==std::string([row UTF8String])||term==std::string([column UTF8String])||!FindDataColumnInDataFrame(data,term))continue;if(!rlispstat::core::AddModelTrellisIndependentVariable(state.specification,term,data,&error)){ShowWorkbenchMessageOnMain(@"Linear Model Trellis",ToNSString(error));return;}}
      std::set<int>selection;
      if(rlispstat::core::SavedAnalysisScopeNameFromChoiceValue(state.specification.baseModel.scope)){
          if(!ResolveSavedAnalysisScopeChoiceForGroup(seed.group,state.specification.baseModel.scope,state.dataScope,&error)){
              ShowWorkbenchMessageOnMain(@"Linear Model Trellis",ToNSString(error));return;
          }
