static void ShowNewLinkedBoxplotDialogOnMain(PlotModel *model)
{
    const BoxplotCreationDialogState dialogState = BuildBoxplotCreationDialogState();
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(NoActiveDatasetTitle()), ToNSString(dialogState.noActiveDatasetStatus));
        return;
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      PlotModel seed;
      DataFrameModel df;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          seed = *model;
          const DataFrameModel *found = FindDataFrameUnlockedConst(seed.group);
          if (found) {
              df = *found;
          }
      }
      if (seed.variables.empty() || df.columns.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.needsNumericDataStatus));
          return;
      }
      const auto initial = ResolveInitialAnalysisForGroup(
          df, rlispstat::core::SharedAnalysisKind::Boxplot);
      const std::string initialY =
          rlispstat::core::InitialAnalysisVariable(initial, "y");
      const std::string initialX =
          rlispstat::core::InitialAnalysisVariable(initial, "x");

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.createButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 380, 126)];
      [accessory addSubview:GLMLabel(ToNSString(DatasetDialogLabel(seed.group)), NSMakeRect(0, 98, 360, 20), 12, NSFontWeightMedium)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::ScatterplotYFieldLabel()), NSMakeRect(0, 64, 34, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::ScatterplotGroupFieldLabel()), NSMakeRect(0, 34, 50, 22), 12, NSFontWeightRegular)];
      NSPopUpButton *yPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(58, 60, 160, 28)];
      [yPopup addItemWithTitle:@"Choose..."];
      for (const NumericVariable &var : seed.variables) {
          [yPopup addItemWithTitle:ToNSString(var.name)];
      }
      if (!initialY.empty()) [yPopup selectItemWithTitle:ToNSString(initialY)];
      NSPopUpButton *xPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(58, 30, 160, 28)];
      [xPopup addItemWithTitle:ToNSString(NoVariableOptionTitle())];
      for (const DataColumn &col : df.columns) {
          if (rlispstat::core::AnalysisVariableIsCompatible(
                  col, rlispstat::core::AnalysisVariableType::Categorical))
              [xPopup addItemWithTitle:ToNSString(col.name)];
      }
      if (!initialX.empty()) [xPopup selectItemWithTitle:ToNSString(initialX)];
      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(230, 32, 140, 24)];
      [titleField setPlaceholderString:ToNSString(dialogState.optionalTitlePlaceholder)];
      [accessory addSubview:yPopup];
      [accessory addSubview:xPopup];
      [accessory addSubview:titleField];
      [alert setAccessoryView:accessory];
      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::string yName = [[yPopup titleOfSelectedItem] UTF8String];
      std::string xName = [[xPopup titleOfSelectedItem] UTF8String];
      if (yName == "Choose...") {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
              @"Choose a numeric response variable.");
          return;
      }
      if (xName == NoVariableOptionTitle()) xName = "";
      std::string title = [[titleField stringValue] UTF8String];
      if (title.empty()) title = BoxplotDefaultTitle(yName, xName);

      const DataColumn *yCol = nullptr;
      const DataColumn *xCol = nullptr;
      for (const DataColumn &col : df.columns) {
          if (col.name == yName) yCol = &col;
          if (!xName.empty() && col.name == xName) xCol = &col;
      }
      if (!yCol) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.selectedYMissingStatus));
          return;
      }

      PlotModel *created = new PlotModel();
      created->kind = "boxplot";
      created->id = "boxplot_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
      created->group = seed.group;
      created->xLabel = xName;
      created->yLabel = yName;
      created->title = title;
      created->variables = seed.variables;
      created->variableMeta = seed.variableMeta;
      if (xName.empty()) {
          created->boxplotVariables.push_back(yName);
      }
      for (size_t i = 0; i < yCol->values.size(); ++i) {
          char *endptr = nullptr;
          double y = std::strtod(yCol->values[i].c_str(), &endptr);
          if (endptr == yCol->values[i].c_str() || !std::isfinite(y)) {
              continue;
          }
          std::string cat = xCol ? xCol->values[i] : yName;
          if (cat.empty()) cat = "NA";
          created->boxplotPoints.push_back(BoxplotPoint{y, cat, (int)i + 1});
      }
      EnsureParallelBoxplotState(created);
      if (created->boxplotCategories.empty()) {
          created->boxplotCategories = CategoriesForPlot(*created);
      }
      created->boxplotDefinedCategories = created->boxplotCategories;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
      }
      AddPlotOnMain(created);
    });
}

