          return;
      }
      const auto initial = ResolveInitialAnalysisForGroup(
          dataframe, rlispstat::core::SharedAnalysisKind::Histogram);
      const std::string initialX =
          rlispstat::core::InitialAnalysisVariable(initial, "x");
      if (seed.variables.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.needsNumericVariableStatus));
          return;
      }

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.createButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 380, 126)];
      [accessory addSubview:GLMLabel(ToNSString(DatasetDialogLabel(seed.group)), NSMakeRect(0, 98, 360, 20), 12, NSFontWeightMedium)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::HistogramXFieldLabel()), NSMakeRect(0, 64, 34, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::HistogramBinsFieldLabel()), NSMakeRect(0, 34, 50, 22), 12, NSFontWeightRegular)];
      NSPopUpButton *xPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(58, 60, 160, 28)];
      [xPopup addItemWithTitle:@"Choose..."];
      for (const NumericVariable &var : seed.variables) {
          [xPopup addItemWithTitle:ToNSString(var.name)];
      }
      if (!initialX.empty()) [xPopup selectItemWithTitle:ToNSString(initialX)];
      NSTextField *binsField = [[NSTextField alloc] initWithFrame:NSMakeRect(58, 32, 70, 24)];
      [binsField setPlaceholderString:ToNSString(dialogState.binsPlaceholder)];
      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(230, 32, 140, 24)];
      [titleField setPlaceholderString:ToNSString(dialogState.optionalTitlePlaceholder)];
      [accessory addSubview:xPopup];
      [accessory addSubview:binsField];
      [accessory addSubview:titleField];
      [alert setAccessoryView:accessory];
      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::string xName = [[xPopup titleOfSelectedItem] UTF8String];
      if (xName == "Choose...") {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
              @"Choose a numeric variable.");
          return;
      }
      const NumericVariable *xVar = nullptr;
      for (const NumericVariable &var : seed.variables) {
          if (var.name == xName) {
              xVar = &var;
              break;
          }
      }
      if (!xVar) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.selectedXMissingStatus));
          return;
      }
      std::string title = [[titleField stringValue] UTF8String];
      if (title.empty()) title = HistogramDefaultTitle(xName);

      PlotModel *created = new PlotModel();
      created->kind = "histogram";
      created->id = "histogram_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
      created->group = seed.group;
      created->xLabel = xName;
      created->yLabel = "";
      created->title = title;
      created->variables = seed.variables;
      created->variableMeta = seed.variableMeta;
      for (size_t i = 0; i < xVar->values.size(); ++i) {
          double x = xVar->values[i];
          if (std::isfinite(x)) {
              created->histogramPoints.push_back(HistogramPoint{x, (int)i + 1, 0});
          }
      }
      if (created->histogramPoints.empty()) {
    delete created;
           ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::HistogramWindowTitle()), ToNSString(rlispstat::core::HistogramNoFiniteValuesStatus()));
          return;
      }
      int bins = std::atoi([[binsField stringValue] UTF8String]);
      if (bins <= 0) {
          RebinHistogramByRule(created, "sturges");
      } else {
          RebinHistogram(created, bins);
      }
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
          EnsureGroupModelUnlocked(created->group, created);
      }
      AddPlotOnMain(created);
    });
}

static void ShowNewLinkedBarplotDialogOnMain(PlotModel *model)
{
    const BarplotCreationDialogState dialogState = BuildBarplotCreationDialogState();
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(NoActiveDatasetTitle()), ToNSString(dialogState.noActiveDatasetStatus));
        return;
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      PlotModel seed;
      DataFrameModel df;
      bool found = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          seed = *model;
          const DataFrameModel *current = FindDataFrameUnlockedConst(seed.group);
          if (current) {
              df = *current;
              found = true;
          }
      }
      if (!found || df.columns.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.needsBackendDataStatus));
          return;
      }
      const auto initial = ResolveInitialAnalysisForGroup(
          df, rlispstat::core::SharedAnalysisKind::BarChart);
      const std::string initialX =
          rlispstat::core::InitialAnalysisVariable(initial, "x");
      const std::vector<std::string> initialConditioning =
          rlispstat::core::InitialAnalysisVariables(initial, "conditioning");

      std::vector<std::string> candidates;
      for (const DataColumn &col : df.columns) {
          if (!DataColumnLooksLikeId(col) &&
              rlispstat::core::AnalysisVariableIsCompatible(
                  col, rlispstat::core::AnalysisVariableType::Categorical)) {
              candidates.push_back(col.name);
          }
      }
      if (candidates.empty()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
              @"The active dataset has no categorical variable suitable for a bar chart.");
          return;
      }

      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.createButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];
      NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 430, 156)];
      [accessory addSubview:GLMLabel(ToNSString(DatasetDialogLabel(seed.group)), NSMakeRect(0, 128, 390, 20), 12, NSFontWeightMedium)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotXVariableFieldLabel()), NSMakeRect(0, 94, 76, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotAddXFieldLabel()), NSMakeRect(0, 64, 76, 22), 12, NSFontWeightRegular)];
      [accessory addSubview:GLMLabel(ToNSString(rlispstat::core::BoxplotSplitByFieldLabel()), NSMakeRect(0, 34, 76, 22), 12, NSFontWeightRegular)];
      NSPopUpButton *xPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(82, 90, 150, 28)];
      [xPopup addItemWithTitle:@"Choose..."];
      for (const std::string &name : candidates) {
          [xPopup addItemWithTitle:ToNSString(name)];
      }
      if (!initialX.empty()) [xPopup selectItemWithTitle:ToNSString(initialX)];
      NSPopUpButton *addXPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(82, 60, 150, 28)];
      [addXPopup addItemWithTitle:ToNSString(NoVariableOptionTitle())];
      for (const std::string &name : candidates) {
          [addXPopup addItemWithTitle:ToNSString(name)];
      }
      NSPopUpButton *splitPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(82, 30, 150, 28)];
      [splitPopup addItemWithTitle:ToNSString(NoVariableOptionTitle())];
      for (const std::string &name : candidates) {
          [splitPopup addItemWithTitle:ToNSString(name)];
      }
      if (initialConditioning.size() == 1)
          [splitPopup selectItemWithTitle:ToNSString(initialConditioning.front())];
      NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(248, 32, 160, 24)];
      [titleField setPlaceholderString:ToNSString(dialogState.optionalTitlePlaceholder)];
      [accessory addSubview:xPopup];
      [accessory addSubview:addXPopup];
      [accessory addSubview:splitPopup];
      [accessory addSubview:titleField];
      [alert setAccessoryView:accessory];
      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::string xName = [[xPopup titleOfSelectedItem] UTF8String];
      if (xName == "Choose...") {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
              @"Choose a categorical variable.");
          return;
      }
      std::string addXName = [[addXPopup titleOfSelectedItem] UTF8String];
      std::vector<std::string> xNames;
      xNames.push_back(xName);
      if (addXName != NoVariableOptionTitle() && addXName != xName) {
          xNames.push_back(addXName);
      }
      std::string splitName = [[splitPopup titleOfSelectedItem] UTF8String];
      if (splitName == NoVariableOptionTitle() || std::find(xNames.begin(), xNames.end(), splitName) != xNames.end()) splitName.clear();
      std::vector<const DataColumn *> xCols;
      const DataColumn *splitCol = nullptr;
      for (const std::string &name : xNames) {
          const DataColumn *xCol = nullptr;
          for (const DataColumn &col : df.columns) {
              if (col.name == name) {
                  xCol = &col;
                  break;
              }
          }
          if (xCol) xCols.push_back(xCol);
      }
      for (const DataColumn &col : df.columns) {
          if (!splitName.empty() && col.name == splitName) {
              splitCol = &col;
          }
      }
      if (xCols.size() != xNames.size()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.selectedVariableMissingStatus));
          return;
      }
      if (!splitName.empty() && !splitCol) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title), ToNSString(dialogState.selectedSplitVariableMissingStatus));
          return;
      }
      std::string xLabel = JoinStrings(xNames, " + ");
      std::string title = [[titleField stringValue] UTF8String];
      if (title.empty()) title = BarplotDefaultTitle(xLabel, splitName);

      PlotModel *created = new PlotModel();
      created->kind = "barplot";
      created->id = "barplot_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
      created->group = seed.group;
      created->xLabel = xLabel;
      created->yLabel = "";
      created->title = title;
      created->variables = seed.variables;
      created->variableMeta = seed.variableMeta;
      created->barplotXVariables = xNames;
      created->barplotSplitVariable = splitName;
      created->barplotRowColorDisplay = "hide";
      created->barplotShowConditionalPercent = !splitName.empty();

      rlispstat::core::RebuildBarplotBinsForColumns(*created, xCols, splitCol);
      NormalizeBarplotVisualState(created);
      if (created->barplotBins.empty()) {
    delete created;
           ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::BarplotWindowTitle()), ToNSString(rlispstat::core::BarplotNoValuesToPlotStatus()));
          return;
      }
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          (void)AttachPlotModelUnlocked(created);
          EnsureGroupModelUnlocked(created->group, created);
      }
      AddPlotOnMain(created);
    });
}

static void ShowBarplotSplitStrokeWidthDialogOnMain(PlotModel *model)
{
    if (!model || model->kind != "barplot") {
        return;
    }
    std::string plotId = model->id;
    dispatch_async(dispatch_get_main_queue(), ^{
      double currentWidth = 3.0;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto it = g_plots.find(plotId);
          if (it == g_plots.end() || !it->second || it->second->kind != "barplot") {
              return;
          }
          currentWidth = ClampBarplotSplitStrokeWidth(it->second->barplotSplitStrokeWidth);
      }

      BarplotSplitStrokeWidthDialogState dialogState =
          BuildBarplotSplitStrokeWidthDialogState(currentWidth);
      NSAlert *alert = [[NSAlert alloc] init];
      [alert setMessageText:ToNSString(dialogState.title)];
      [alert setInformativeText:ToNSString(dialogState.informativeText)];
      [alert addButtonWithTitle:ToNSString(dialogState.applyButtonTitle)];
      [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];

      NSTextField *widthField = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 180, 24)];
      [widthField setStringValue:ToNSString(dialogState.currentValueText)];
      [alert setAccessoryView:widthField];

      if ([alert runModal] != NSAlertFirstButtonReturn) {
          return;
      }

      std::string text = [[widthField stringValue] UTF8String];
      std::optional<double> parsedValue = rlispstat::core::ParseBarplotSplitStrokeWidthCommandValue(text);
      if (!parsedValue.has_value()) {
          ShowWorkbenchMessageOnMain(ToNSString(dialogState.title),
                                     ToNSString(dialogState.invalidNumberStatus));
          return;
      }
      double value = *parsedValue;

      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto it = g_plots.find(plotId);
          if (it == g_plots.end() || !it->second || it->second->kind != "barplot") {
              return;
          }
          it->second->barplotSplitStrokeWidth = value;
      }
      RedrawPlotOnMain(plotId);
    });
}

