static NSButton *PanelButton(NSView *content, const std::string &title, const std::string &command, NSRect frame)
{
    NSButton *button = [[NSButton alloc] initWithFrame:frame];
    [button setTitle:ToNSString(title)];
    [button setButtonType:NSButtonTypeToggle];
    [button setBezelStyle:NSBezelStyleRounded];
    [button setFont:[NSFont systemFontOfSize:11]];
    [button setTarget:g_commandTarget];
    [button setAction:@selector(runCommand:)];
    [button setIdentifier:ToNSString(command)];
    [content addSubview:button];
    g_panelButtons[command] = button;
    return button;
}

static void EnsurePanelOnMain()
{
    if (g_panel) {
        return;
    }
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }

    g_panel = [[NSPanel alloc]
        initWithContentRect:NSMakeRect(80, 520, 350, 230)
                  styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskUtilityWindow)
                    backing:NSBackingStoreBuffered
                      defer:NO];
    [g_panel setTitle:@"LinkEDA tools"];
    [g_panel setFloatingPanel:YES];
    [g_panel setHidesOnDeactivate:NO];

    NSView *content = [g_panel contentView];
    g_panelStatus = [[NSTextField alloc] initWithFrame:NSMakeRect(12, 194, 326, 22)];
    [g_panelStatus setEditable:NO];
    [g_panelStatus setBordered:NO];
    [g_panelStatus setDrawsBackground:NO];
    [g_panelStatus setFont:[NSFont systemFontOfSize:11]];
    [content addSubview:g_panelStatus];


    PanelButton(content, "Replace", "SET_SELECTION_REPLACE", NSMakeRect(12, 150, 70, 26));
    PanelButton(content, "Add", "SET_SELECTION_ADD", NSMakeRect(86, 150, 54, 26));
    PanelButton(content, "Subtract", "SET_SELECTION_SUBTRACT", NSMakeRect(144, 150, 82, 26));
    PanelButton(content, "Toggle", "SET_SELECTION_TOGGLE", NSMakeRect(230, 150, 68, 26));

    PanelButton(content, "Clear", "CLEAR_SELECTION", NSMakeRect(12, 110, 64, 26));
    PanelButton(content, "Invert", "INVERT_SELECTION", NSMakeRect(80, 110, 64, 26));
    PanelButton(content, "All", "SELECT_ALL_VISIBLE", NSMakeRect(148, 110, 50, 26));
    PanelButton(content, "Copy", "COPY_SELECTED", NSMakeRect(202, 110, 58, 26));
    PanelButton(content, "Palette", "OPEN_COLOR_PALETTE", NSMakeRect(260, 110, 72, 26));


    // Export belongs to the plot's contextual Export submenu; the utility
    // palette is reserved for interaction and selection controls.
    PanelButton(content, "Close", "CLOSE_PLOT", NSMakeRect(12, 30, 74, 26));
}

static void UpdatePanelOnMain()
{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!g_panel) {
          return;
      }
      PlotModel *model = ActivePlot();
      for (auto &entry : g_panelButtons) {
          [entry.second setState:NSControlStateValueOff];
          [entry.second setEnabled:model &&
              (entry.first == "CLOSE_PLOT" ||
               rlispstat::core::PlotLinksToDataRows(*model))];
      }
      if (!model) {
          [g_panelStatus setStringValue:ToNSString(rlispstat::core::PlotNoActiveStatus())];
          return;
      }
      std::string modeCommand = "SET_MODE_" + model->interactionMode;
      std::transform(modeCommand.begin(), modeCommand.end(), modeCommand.begin(), ::toupper);
      auto modeButton = g_panelButtons.find(modeCommand);
      if (modeButton != g_panelButtons.end()) {
          [modeButton->second setState:NSControlStateValueOn];
      }
      std::string selCommand = "SET_SELECTION_" + model->selectionMode;
      std::transform(selCommand.begin(), selCommand.end(), selCommand.begin(), ::toupper);
      auto selButton = g_panelButtons.find(selCommand);
      if (selButton != g_panelButtons.end()) {
          [selButton->second setState:NSControlStateValueOn];
      }
      std::ostringstream status;
      rlispstat::core::AnalysisScope analysisScope;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          analysisScope = MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
      }
      status << "Plot: " << model->yLabel << " vs " << model->xLabel
             << " | Selected: " << SelectionCount(model->group)
             << " | Color: " << SelectedColorForGroup(model->group)
             << " | " << rlispstat::core::AnalysisScopeSummary(
                    analysisScope, analysisScope.totalDatasetRows);
      [g_panelStatus setStringValue:ToNSString(status.str())];
    });
}

static void ShowPanelOnMain(bool show)
{
    dispatch_async(dispatch_get_main_queue(), ^{
      EnsurePanelOnMain();
      if (show) {
          [g_panel orderFront:nil];
          UpdatePanelOnMain();
      } else {
          [g_panel orderOut:nil];
      }
    });
}

static void ApplyColorToGroupSelection(PlotModel *model, const std::string &colorName)
{
    if (!model || !rlispstat::core::FindPaletteColor(colorName)) {
        return;
    }
    std::string group = model->group;
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_groupSelectedColors[group] = colorName;
        auto it = g_groupSelections.find(group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    if (selection.empty()) { UpdatePanelOnMain(); return; }
    auto prepared = PreparePersistentColorsForManualEdit(group);
    if (!prepared) return;
    std::set<int> changedRows(prepared->begin(), prepared->end());
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (int row : selection) {
            g_groupPointColors[group][row] = colorName;
            changedRows.insert(row);
        }
        if (!selection.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", group, "palette", "", std::vector<int>(changedRows.begin(), changedRows.end()));
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
}

static void ApplyColorToGroupSelection(const std::string &group, const std::string &colorName)
{
    if (group.empty() || !rlispstat::core::FindPaletteColor(colorName)) {
        return;
    }
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_groupSelectedColors[group] = colorName;
        auto it = g_groupSelections.find(group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    if (selection.empty()) { UpdatePanelOnMain(); return; }
    auto prepared = PreparePersistentColorsForManualEdit(group);
    if (!prepared) return;
    std::set<int> changedRows(prepared->begin(), prepared->end());
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (int row : selection) {
            g_groupPointColors[group][row] = colorName;
            changedRows.insert(row);
        }
        if (!selection.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", group, "palette", "", std::vector<int>(changedRows.begin(), changedRows.end()));
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
}

static void ResetColorForGroupSelection(PlotModel *model)
{
    if (!model) {
        return;
    }
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_groupSelectedColors[model->group] = "black";
        auto it = g_groupSelections.find(model->group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    if (selection.empty()) { UpdatePanelOnMain(); return; }
    auto prepared = PreparePersistentColorsForManualEdit(model->group);
    if (!prepared) return;
    std::set<int> changedRows(prepared->begin(), prepared->end());
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto colors = g_groupPointColors.find(model->group);
        if (colors != g_groupPointColors.end()) {
            for (int row : selection) {
                colors->second.erase(row);
                changedRows.insert(row);
            }
        }
        if (!selection.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(model->group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", model->group, "palette", "", std::vector<int>(changedRows.begin(), changedRows.end()));
    RedrawGroupViewsSynchronouslyOnMain(model->group, true);
    UpdatePanelOnMain();
}

