static void EnsurePaletteOnMain()
{
    if (g_palettePanel) {
        return;
    }
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }
    const auto &paletteColors = rlispstat::core::PaletteColors();
    const int colorCount = (int)paletteColors.size();
    const int paletteColumns = 3;
    const int paletteRows = std::max(1, (colorCount + 1 + paletteColumns - 1) / paletteColumns);
    const CGFloat panelWidth = 28.0 + 36.0 + (paletteColumns - 1) * 52.0;
    const CGFloat panelHeight = 24.0 + 30.0 + (paletteRows - 1) * 42.0;
    g_palettePanel = [[NSPanel alloc]
        initWithContentRect:NSMakeRect(400, 520, panelWidth, panelHeight)
                  styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskUtilityWindow)
                    backing:NSBackingStoreBuffered
                      defer:NO];
    [g_palettePanel setTitle:@"LinkEDA palette"];
    [g_palettePanel setFloatingPanel:YES];
    [g_palettePanel setHidesOnDeactivate:NO];

    NSView *content = [g_palettePanel contentView];
    const CGFloat firstRowY = panelHeight - 12.0 - 30.0;
    for (int i = 0; i < colorCount; ++i) {
        const PaletteColor &color = paletteColors[i];
        int row = i / paletteColumns;
        int col = i % paletteColumns;
        NSButton *button = [[NSButton alloc] initWithFrame:NSMakeRect(14 + col * 52, firstRowY - row * 42, 36, 30)];
        [button setTitle:@""];
        [button setButtonType:NSButtonTypeMomentaryPushIn];
        [button setBezelStyle:NSBezelStyleTexturedRounded];
        [button setWantsLayer:YES];
        [[button layer] setBackgroundColor:[[NSColor colorWithCalibratedRed:color.baseR green:color.baseG blue:color.baseB alpha:1.0] CGColor]];
        [[button layer] setCornerRadius:6.0];
        [[button layer] setBorderWidth:1.0];
        [[button layer] setBorderColor:[[NSColor colorWithCalibratedWhite:0.25 alpha:0.45] CGColor]];
        [button setToolTip:ToNSString(color.name)];
        [button setTarget:g_commandTarget];
        [button setAction:@selector(runCommand:)];
        [button setIdentifier:ToNSString(std::string("SET_SELECTED_COLOR|") + color.name)];
        [content addSubview:button];
    }
    int resetIndex = colorCount;
    int resetRow = resetIndex / paletteColumns;
    int resetCol = resetIndex % paletteColumns;
    NSButton *reset = [[NSButton alloc] initWithFrame:NSMakeRect(14 + resetCol * 52, firstRowY - resetRow * 42, 36, 30)];
    [reset setTitle:@""];
    [reset setButtonType:NSButtonTypeMomentaryPushIn];
    [reset setBezelStyle:NSBezelStyleTexturedRounded];
    [reset setImagePosition:NSImageOnly];
    NSImage *resetImage = [[NSImage alloc] initWithSize:NSMakeSize(30, 24)];
    [resetImage lockFocus];
    [[NSColor blackColor] setFill];
    NSRectFill(NSMakeRect(0, 0, 15, 24));
    [[NSColor whiteColor] setFill];
    NSRectFill(NSMakeRect(15, 0, 15, 24));
    [[NSColor colorWithCalibratedWhite:0.25 alpha:0.60] setStroke];
    NSFrameRect(NSMakeRect(0, 0, 30, 24));
    [resetImage unlockFocus];
    [reset setImage:resetImage];
    [reset setToolTip:ToNSString(rlispstat::core::FormatResetRowColorTooltip())];
    [reset setTarget:g_commandTarget];
    [reset setAction:@selector(runCommand:)];
    [reset setIdentifier:@"RESET_SELECTED_COLOR"];
    [content addSubview:reset];
}

static void ShowPaletteOnMain(bool show)
{
    dispatch_async(dispatch_get_main_queue(), ^{
      EnsurePaletteOnMain();
      if (show) {
          [g_palettePanel orderFront:nil];
      } else {
          [g_palettePanel orderOut:nil];
      }
    });
}


