static void SaveRecordingRScriptOnMain()
{
    std::string script = rlispstat::core::RenderRecordingRScript(RecordingSnapshot());
    dispatch_async(dispatch_get_main_queue(), ^{
      NSSavePanel *panel = [NSSavePanel savePanel];
      [panel setTitle:ToNSString(RecordingSavePanelTitle())];
      [panel setNameFieldStringValue:ToNSString(RecordingSaveDefaultFilename())];
      SetSavePanelExtensionCompat(panel, ToNSString(rlispstat::core::RFileExtension()));
      if ([panel runModal] != NSModalResponseOK) return;
      NSError *error = nil;
      BOOL ok = [ToNSString(script) writeToURL:[panel URL]
                                    atomically:YES
                                      encoding:NSUTF8StringEncoding
                                         error:&error];
      if (!ok) {
          ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()),
                                     error ? [error localizedDescription] : ToNSString(RecordingSaveFailedStatus()));
      }
    });
}

static void ReplayRecordingOnMain()
{
    std::vector<RecordingEntry> entries = RecordingSnapshot();
    int replayed = 0;
    g_recordingReplaying = true;
    for (const RecordingEntry &entry : entries) {
        if (!entry.replayable) {
            continue;
        }
        std::vector<std::string> parts = SplitTabs(entry.internalCommand);
        if (parts.empty()) {
            continue;
        }
        if (parts[0] == "API") {
            std::vector<std::string> lines = DecodeRecordingAPICommand(entry.internalCommand);
            if (!lines.empty()) {
                HandleCommandLines(lines);
                ++replayed;
            }
        } else if (parts[0] == "DISPATCH" && parts.size() >= 3) {
            std::string plotId = DecodeCommandField(parts[1]);
            std::string command = DecodeCommandField(parts[2]);
            PlotModel *target = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_plots.find(plotId);
                if (it != g_plots.end()) {
                    target = it->second;
                } else if (!entry.group.empty()) {
                    target = EnsureDatasetSeedPlotUnlocked(entry.group);
                } else {
                    target = ActiveDatasetSeedPlotUnlocked();
                }
            }
            DispatchCommand(target, command);
            ++replayed;
        }
    }
    g_recordingReplaying = false;
    ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingReplayedStatus(replayed)));
}

static bool HandleRecordingCommand(const std::string &command)
{
    if (command.rfind("RECORD_", 0) != 0) {
        return false;
    }
    if (command == "RECORD_START") {
        {
            std::lock_guard<std::mutex> lock(g_recordingMutex);
            g_recordingActive = true;
        }
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingStartedStatus()));
        return true;
    }
    if (command == "RECORD_STOP") {
        {
            std::lock_guard<std::mutex> lock(g_recordingMutex);
            g_recordingActive = false;
        }
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingStoppedStatus()));
        return true;
    }
    if (command == "RECORD_CLEAR") {
        {
            std::lock_guard<std::mutex> lock(g_recordingMutex);
            g_recordingEntries.clear();
        }
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingClearedStatus()));
        return true;
    }
    if (command == "RECORD_SHOW") {
        ShowRecordingOnMain();
        return true;
    }
    if (command == "RECORD_COPY_R") {
        CopyTextToPasteboardOnMain(ToNSString(rlispstat::core::RenderRecordingRScript(RecordingSnapshot())));
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingRScriptCopiedStatus()));
        return true;
    }
    if (command == "RECORD_COPY_INTERNAL") {
        CopyTextToPasteboardOnMain(ToNSString(rlispstat::core::RenderRecordingInternalCommands(RecordingSnapshot())));
        ShowWorkbenchMessageOnMain(ToNSString(RecordingMessageTitle()), ToNSString(RecordingInternalCommandsCopiedStatus()));
        return true;
    }
    if (command == "RECORD_SAVE_R") {
        SaveRecordingRScriptOnMain();
        return true;
    }
    if (command == "RECORD_REPLAY") {
        ReplayRecordingOnMain();
        return true;
    }
    return true;
}

using rlispstat::core::TempPath;

static bool WriteDataFrameCSV(const std::string &group, const std::string &path,
                              const std::vector<int> &includeRows, std::string *message)
{
    const DataFrameModel *found = FindDataFrameUnlockedConst(group);
    if (!found) {
        if (message) *message = rlispstat::core::NoRegisteredDatasetGroupStatus();
        return false;
    }
    const DataFrameModel &df = *found;
    std::ofstream out(path);
    if (!out) {
        if (message) *message = rlispstat::core::DatasetTemporaryDataWriteFailedStatus();
        return false;
    }
    return rlispstat::core::WriteDataFrameCSV(out, df, includeRows);
}

// The native window owns only the short-lived Rscript transport.  R performs
// the GLS/emmeans calculation and the portable core validates and parses its
// tabular reply.
static bool RunRBackedGLMPairwiseComparisons(const DataFrameModel &dataframe,
                                             PlotModel *model,
                                             const std::string &dependent,
                                             const std::vector<std::string> &terms,
                                             const std::map<std::string, std::string> &termTypes,
                                             const GLMFitSummary &fit,
                                             const rlispstat::core::GLMPairwiseComparisonRequest &request,
                                             rlispstat::core::GLMPairwiseComparisonResult *result,
                                             std::string *message)
{
    if (!model || !result) {
        if (message) *message = "The current model is unavailable.";
        return false;
    }
    const std::string csvPath = TempPath("rlispstat_glm_pairwise_data", ".csv");
    const std::string scriptPath = TempPath("rlispstat_glm_pairwise", ".R");
    {
        std::ofstream csv(csvPath);
        if (!csv || !rlispstat::core::WriteDataFrameCSV(csv, dataframe, fit.rowsUsed)) {
            if (message) *message = "Could not write the current fitted data for R.";
            unlink(csvPath.c_str());
            return false;
        }
    }
    {
        std::ofstream script(scriptPath);
        script << rlispstat::core::GLMPairwiseComparisonsRScript();
        if (!script) {
            if (message) *message = "Could not write the R script for pairwise comparisons.";
            unlink(csvPath.c_str());
            unlink(scriptPath.c_str());
            return false;
        }
    }
    const std::vector<std::string> variables = BaseVariablesFromModelTerms(model, dependent, terms);
    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " +
        ShellQuoteSingle(scriptPath) + " " + ShellQuoteSingle(csvPath) + " " +
        ShellQuoteSingle(dependent) + " " + ShellQuoteSingle(request.term) + " " +
        ShellQuoteSingle(std::to_string(request.confidenceLevel)) + " " +
        ShellQuoteSingle(std::to_string(static_cast<long long>(terms.size())));
    for (const std::string &term : terms) command += " " + ShellQuoteSingle(term);
    command += " " + ShellQuoteSingle(std::to_string(static_cast<long long>(variables.size())));
    for (const std::string &variable : variables) command += " " + ShellQuoteSingle(variable);
    for (const std::string &variable : variables) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(model, variable, termTypes));
    }
    command += " " + ShellQuoteSingle(request.adjustment.empty() ? "auto" : request.adjustment);
    command += " 2>&1";
    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        if (message) *message = "Could not run Rscript for pairwise comparisons.";
        unlink(csvPath.c_str());
        unlink(scriptPath.c_str());
        return false;
    }
    std::string output;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), pipe)) output += buffer;
    const int rc = pclose(pipe);
    unlink(csvPath.c_str());
    unlink(scriptPath.c_str());
    const std::vector<std::string> lines = SplitLines(output);
    if (rc != 0 || !rlispstat::core::ParseGLMPairwiseComparisonsRResult(lines, *result)) {
        if (message) *message = output.empty() ? "R could not calculate pairwise comparisons." : output;
        return false;
    }
    return true;
}

static bool RunRBackedBinaryPairwiseComparisons(const DataFrameModel &dataframe,
                                                const GeneralizedGLMState &state,
                                                const std::string &term,
                                                rlispstat::core::GLMPairwiseComparisonResult *result,
                                                std::string *message)
{
    if (!result) return false;
    if (state.multipleImputation) {
        const auto task=GeneralizedGLMTaskForState(state,0);
        return RunRBackedMIPairwiseComparisons(dataframe,"gglm_pairwise",
            "pairwise_"+state.id,state.response,state.terms,state.scope,
            EncodeStandaloneGeneralizedMISpec(task),term,result,message);
    }

    const std::string csvPath = TempPath("rlispstat_binary_pairwise_data", ".csv");
    const std::string scriptPath = TempPath("rlispstat_binary_pairwise", ".R");
    {
        std::ofstream csv(csvPath);
        if (!csv || !rlispstat::core::WriteDataFrameCSV(csv, dataframe, state.rowsUsed)) {
            if (message) *message = "Could not write the fitted binary-regression rows for R.";
            unlink(csvPath.c_str());
            return false;
        }
    }
    {
        std::ofstream script(scriptPath);
        script << rlispstat::core::BinaryPairwiseComparisonsRScript();
        if (!script) {
            if (message) *message = "Could not prepare the R pairwise-comparison script.";
            unlink(csvPath.c_str()); unlink(scriptPath.c_str());
            return false;
        }
    }
    const std::vector<std::string> variables = BaseVariablesFromModelTerms(
        const_cast<PlotModel *>(&state.seed), state.response, state.terms);
    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " + ShellQuoteSingle(scriptPath) +
        " " + ShellQuoteSingle(csvPath) + " " + ShellQuoteSingle(state.response) +
        " " + ShellQuoteSingle(state.responseCoding.eventValue) + " " + ShellQuoteSingle(state.link) +
        " " + ShellQuoteSingle(term) + " " + ShellQuoteSingle("0.95") +
        " " + ShellQuoteSingle(std::to_string((long long)state.terms.size()));
    for (const std::string &modelTerm : state.terms) command += " " + ShellQuoteSingle(modelTerm);
    command += " " + ShellQuoteSingle(std::to_string((long long)variables.size()));
    for (const std::string &variable : variables) command += " " + ShellQuoteSingle(variable);
    for (const std::string &variable : variables) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(&state.seed, variable, state.termTypes));
    }
    command += " 2>&1";
    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        if (message) *message = "Could not run Rscript for binary pairwise comparisons.";
        unlink(csvPath.c_str()); unlink(scriptPath.c_str());
        return false;
    }
    std::string output;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), pipe)) output += buffer;
    int rc = pclose(pipe);
    unlink(csvPath.c_str()); unlink(scriptPath.c_str());
    result->term = term;
    if (rc != 0 || !rlispstat::core::ParseGLMPairwiseComparisonsRResult(SplitLines(output), *result)) {
        if (message) *message = output.empty() ? "R could not calculate binary pairwise comparisons." : output;
        return false;
    }
    return true;
}

static std::vector<int> RowsForGeneralizedScope(const GeneralizedGLMState &state)
{
    int rowCount = 0;
    const DataFrameModel *df = FindDataFrameUnlockedConst(state.group);
    if (df) rowCount = df->rows;
    const std::vector<int> capturedRows = RowsForCapturedAnalysisScope(
        state.dataScope, state.dataScopeCaptured);
    if (!capturedRows.empty() ||
        (state.dataScopeCaptured &&
         state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds)) {
        return capturedRows;
    }
    std::set<int> selected;
    auto selIt = g_groupSelections.find(state.group);
    if (selIt != g_groupSelections.end()) selected = selIt->second;
    return rlispstat::core::RowsForScope(rowCount, selected, state.scope);
}

static bool RefitGeneralizedGLMState(GeneralizedGLMState &state)
{
    MacCommandDispatcher().applicationState().captureAnalysisScope(state.group, state.dataScope, state.dataScopeCaptured, &state.scope);
    state.rows.clear();
    state.diagnostics.clear();
    state.rowsUsed.clear();
    state.rowsExcluded.clear();
    state.ok = false;
    if (state.response.empty()) {
        state.status = rlispstat::core::GLMChooseResponseVariableStatus();
        return false;
    }
    if (!IsValidGeneralizedFamily(state.family)) {
        state.status = rlispstat::core::GLMInvalidFamilyStatus();
        return false;
    }
    if (!IsValidGeneralizedLink(state.family, state.link)) {
        state.status = rlispstat::core::GLMInvalidLinkForFamilyStatus();
        return false;
    }

    std::string csvPath = TempPath("rlispstat_gglm_data", ".csv");
    std::string scriptPath = TempPath("rlispstat_gglm_fit", ".R");
    std::string message;
    std::vector<int> includeRows = RowsForGeneralizedScope(state);
    if (state.scope != "all" && includeRows.empty()) {
        state.status = rlispstat::core::GLMNoRowsForScopeStatus();
        return false;
    }
    if (!WriteDataFrameCSV(state.group, csvPath, includeRows, &message)) {
        state.status = message;
        return false;
    }
    {
        std::ofstream script(scriptPath);
        script << GeneralizedGLMRScript();
    }

    std::string command = ShellQuoteSingle(g_rscriptPath) + " --vanilla " + ShellQuoteSingle(scriptPath) + " " +
        ShellQuoteSingle(csvPath) + " " + ShellQuoteSingle(state.response) + " " + ShellQuoteSingle(state.family) + " " +
        ShellQuoteSingle(state.link) + " " + ShellQuoteSingle(std::to_string((long long)state.terms.size()));
    for (const std::string &term : state.terms) {
        command += " " + ShellQuoteSingle(term);
    }
    for (const std::string &term : state.terms) {
        command += " " + ShellQuoteSingle(rlispstat::core::ModelTermDisplayType(&state.seed, term, state.termTypes));
    }
    command += " 2>&1";

    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        state.status = GeneralizedGLMRscriptLaunchFailedStatus();
        unlink(csvPath.c_str());
        unlink(scriptPath.c_str());
        return false;
    }
    std::string output;
    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), pipe)) {
        output += buffer;
    }
    int rc = pclose(pipe);
    unlink(csvPath.c_str());
    unlink(scriptPath.c_str());
    std::vector<std::string> lines = SplitLines(output);
    if (lines.empty() || lines[0] != "OK" || rc != 0) {
        state.status = output.empty() ? rlispstat::core::GeneralizedGLMFitFailedStatus() : output;
        return false;
    }
    for (size_t i = 1; i < lines.size(); ++i) {
        std::vector<std::string> parts = SplitTabs(lines[i]);
        if (parts.empty()) continue;
        if (parts[0] == "FIT" && parts.size() >= 11) {
            state.n = std::atoi(parts[1].c_str());
            state.excluded = std::atoi(parts[2].c_str());
            state.nullDeviance = parts[3] == "NA" ? NAN : std::strtod(parts[3].c_str(), nullptr);
            state.residualDeviance = parts[4] == "NA" ? NAN : std::strtod(parts[4].c_str(), nullptr);
            state.dfResidual = std::atoi(parts[5].c_str());
            state.aic = parts[6] == "NA" ? NAN : std::strtod(parts[6].c_str(), nullptr);
            state.bic = parts[7] == "NA" ? NAN : std::strtod(parts[7].c_str(), nullptr);
            state.dispersion = parts[8] == "NA" ? NAN : std::strtod(parts[8].c_str(), nullptr);
            state.logLik = parts[9] == "NA" ? NAN : std::strtod(parts[9].c_str(), nullptr);
            state.statisticName = parts[10];
        } else if (parts[0] == "META" && parts.size() >= 7) {
            state.converged = parts[1] == "TRUE";
            state.iterations = parts[2] == "NA" ? 0 : std::atoi(parts[2].c_str());
            state.boundary = parts[3] == "TRUE";
            state.rank = parts[4] == "NA" ? 0 : std::atoi(parts[4].c_str());
            state.parameterCount = parts[5] == "NA" ? 0 : std::atoi(parts[5].c_str());
            state.rankDeficient = parts[6] == "TRUE";
        } else if (parts[0] == "ROW" && parts.size() >= 13) {
            GeneralizedGLMRow row;
            row.rowType = parts[1];
            row.term = parts[2];
            row.displayLabel = parts[3];
            row.sourceTerm = parts[4];
            row.factorLevel = parts[5];
            row.referenceLevel = parts[6];
            row.termType = parts[7];
            row.estimate = parts[8] == "NA" ? NAN : std::strtod(parts[8].c_str(), nullptr);
            row.stdError = parts[9] == "NA" ? NAN : std::strtod(parts[9].c_str(), nullptr);
            row.statisticName = parts[10];
            row.statistic = parts[11] == "NA" ? NAN : std::strtod(parts[11].c_str(), nullptr);
            row.pValue = parts[12] == "NA" ? NAN : std::strtod(parts[12].c_str(), nullptr);
            if (parts.size() >= 15) {
                row.ciLower = parts[13] == "NA" ? NAN : std::strtod(parts[13].c_str(), nullptr);
                row.ciUpper = parts[14] == "NA" ? NAN : std::strtod(parts[14].c_str(), nullptr);
            }
            state.rows.push_back(row);
        } else if (parts[0] == "DIAG" && parts.size() >= 9) {
            GeneralizedGLMDiagnosticRow diag;
            diag.row = std::atoi(parts[1].c_str());
            diag.observed = parts[2] == "NA" ? NAN : std::strtod(parts[2].c_str(), nullptr);
            diag.fitted = parts[3] == "NA" ? NAN : std::strtod(parts[3].c_str(), nullptr);
            diag.devianceResidual = parts[4] == "NA" ? NAN : std::strtod(parts[4].c_str(), nullptr);
            diag.pearsonResidual = parts[5] == "NA" ? NAN : std::strtod(parts[5].c_str(), nullptr);
            diag.workingResidual = parts[6] == "NA" ? NAN : std::strtod(parts[6].c_str(), nullptr);
            diag.leverage = parts[7] == "NA" ? NAN : std::strtod(parts[7].c_str(), nullptr);
            diag.cooksDistance = parts[8] == "NA" ? NAN : std::strtod(parts[8].c_str(), nullptr);
            if (diag.row > 0) {
                state.diagnostics.push_back(diag);
                state.rowsUsed.push_back(diag.row);
            }
        }
    }
    std::set<int> used(state.rowsUsed.begin(), state.rowsUsed.end());
    std::vector<int> candidateRows = includeRows;
    if (candidateRows.empty()) {
        const DataFrameModel *df = FindDataFrameUnlockedConst(state.group);
        int totalRows = df ? df->rows : state.n + state.excluded;
        for (int row = 1; row <= totalRows; ++row) candidateRows.push_back(row);
    }
    for (int row : candidateRows) {
        if (used.find(row) == used.end()) state.rowsExcluded.push_back(row);
    }
    state.ok = true;
    state.fitVersion += 1;
    state.diagnosticsVersion += 1;
    state.status = "GLM fitted on " + std::to_string(state.n) + " rows.";
    return true;
}

static void ArmGeneralizedGLMFitWatchdog(const std::string &analysisId,
                                         std::uint64_t generation,
                                         const std::string &signature,
                                         bool multipleImputation)
{
    // An MI request can contain many independent fits and remains observable
    // through GGLM_PROGRESS heartbeats and the task's Cancel button.  The
    // short single-model deadline would incorrectly dismiss a valid MI run.
    const int pendingLimitSeconds = multipleImputation ? 3600 : 120;
    std::thread watchdog([analysisId, generation, signature, pendingLimitSeconds]() {
        const auto deadline = std::chrono::steady_clock::now() +
            std::chrono::seconds(pendingLimitSeconds);
        while (std::chrono::steady_clock::now() < deadline) {
            std::this_thread::sleep_for(std::chrono::milliseconds(250));
            std::lock_guard<std::mutex> lock(g_mutex);
            auto it = g_generalizedGLMs.find(analysisId);
            if (it == g_generalizedGLMs.end() || !it->second.rFitPending ||
                it->second.rFitGeneration != generation ||
                it->second.lastRFitSignature != signature) {
                return;
            }
        }
        bool expired = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto it = g_generalizedGLMs.find(analysisId);
            if (it != g_generalizedGLMs.end() && it->second.rFitPending &&
                it->second.rFitGeneration == generation &&
                it->second.lastRFitSignature == signature) {
                it->second.rFitPending = false;
                it->second.status =
                    "The R fit did not return within " +
                    std::to_string(pendingLimitSeconds) +
                    " seconds. The pending request was cancelled.";
                expired = true;
            }
        }
        if (expired) RefreshGeneralizedGLMOnMain(analysisId);
    });
    watchdog.detach();
}

static void RequestGeneralizedGLMFitInMainR(GeneralizedGLMState &state)
{
    state.frozenScopeNotice.clear();
    MacCommandDispatcher().applicationState().captureAnalysisScope(state.group, state.dataScope, state.dataScopeCaptured, &state.scope);
    if (state.precomputed && !state.multipleImputation) {
        return;
    }
    if (state.countRegression &&
        state.countDistribution == rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling) {
        rlispstat::core::ClearGeneralizedGLMFitResults(state);
        const std::string sourceModelId = state.id;
        // RequestGeneralizedGLMFitInMainR can be entered while application
        // state is locked.  Defer invalidating dependent plots/reports until
        // the current event has released that lock, so no previous hurdle fit
        // remains visible while the replacement is pending or fails.
        dispatch_async(dispatch_get_main_queue(), ^{
            RefreshModelDiagnosticsForModelNow(sourceModelId);
        });
    }
    if (state.countRegression &&
        rlispstat::core::CountDistributionUsesTrials(state.countDistribution) &&
        (state.trialsVariable.empty() &&
         (!std::isfinite(state.trialsConstant) || state.trialsConstant <= 0.0 ||
          std::floor(state.trialsConstant) != state.trialsConstant))) {
        state.rFitPending = false;
        state.ok = false;
        state.status = "Enter Trials as a fixed positive integer before fitting this bounded-count model.";
        return;
    }
    // The visible type label may be derived from dataset metadata, but the fit
    // identity and wire payload must come from the owned ModelSpecification.
    // Materialize those defaults before computing either one. In particular,
    // this keeps a factor added after the window was opened from falling
    // through EffectiveModelSpecificationTermTypes() to its numeric fallback.
    DataFrameModel specificationDataframe;
    if (DataFrameSnapshotForGroup(state.group, specificationDataframe)) {
        rlispstat::core::SynchronizeGeneralizedGLMFitSpecification(
            state, specificationDataframe);
    }
    if (state.response.empty()) {
        state.rFitPending = false;
        state.ok = false;
        state.status = rlispstat::core::GLMChooseResponseVariableStatus();
        return;
    }
    if (state.terms.empty() && !state.binaryRegression && !state.countRegression) {
        state.rFitPending = false;
        state.ok = false;
        state.status = rlispstat::core::GLMAddPredictorBeforeTableStatus();
        return;
    }
    if (rlispstat::core::GeneralizedFamilyRequiresResponseBounds(state.family) &&
        (!state.responseBoundsConfigured || !std::isfinite(state.responseLower) ||
         !std::isfinite(state.responseUpper) || state.responseLower >= state.responseUpper)) {
        state.rFitPending = false;
        state.ok = false;
        state.status = "Enter finite response bounds with lower < upper before fitting.";
        return;
    }
    std::string effectiveDistribution = state.countRegression
        ? rlispstat::core::CountDistributionId(state.countDistribution)
        : state.family;
    if (state.modelType != rlispstat::core::StatisticalModelType::LegacyGeneralized &&
        !rlispstat::core::DistributionIsAvailableForModel(
            state.modelType, effectiveDistribution)) {
        state.rFitPending = false;
        state.ok = false;
        state.status = "The selected distribution is not available for " +
            rlispstat::core::StatisticalModelTypeLabel(state.modelType) + ".";
        return;
    }
    if (state.dataScopeCaptured &&
        state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds &&
        state.dataScope.originalRowIds.empty()) {
        state.rFitPending = false;
        state.ok = false;
        state.status = "The analysis scope contains no rows.";
        return;
    }
    if (!specificationDataframe.group.empty()) {
        const DataColumn *responseColumn = FindDataColumnInDataFrame(
            specificationDataframe, state.response);
        std::set<int> validationRows;
        if (state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
            validationRows.insert(state.dataScope.originalRowIds.begin(),
                                  state.dataScope.originalRowIds.end());
        }
        rlispstat::core::ResponseDomainValidation validation;
        if (responseColumn && state.modelType == rlispstat::core::StatisticalModelType::Count) {
            const auto count = rlispstat::core::InspectCountResponse(*responseColumn, validationRows);
            validation.ok = count.ok;
            validation.status = count.status;
        } else if (responseColumn &&
                   state.modelType == rlispstat::core::StatisticalModelType::Binary) {
            validation = rlispstat::core::InspectResponseDomain(
                *responseColumn, rlispstat::core::ResponseDomain::Binary,
                validationRows);
        } else if (responseColumn &&
                   state.modelType == rlispstat::core::StatisticalModelType::PositiveContinuous) {
            const auto *distribution =
                rlispstat::core::FindDistributionSpecification(state.family);
            validation = rlispstat::core::InspectResponseDomain(
                *responseColumn,
                distribution ? distribution->responseDomain
                             : rlispstat::core::ResponseDomain::Continuous,
                validationRows);
        } else if (responseColumn &&
                   state.modelType == rlispstat::core::StatisticalModelType::Proportion) {
            validation = rlispstat::core::InspectResponseDomain(
                *responseColumn,
                state.family == "beta"
                    ? rlispstat::core::ResponseDomain::OpenUnitInterval
                    : rlispstat::core::ResponseDomain::OpenClosedUnitInterval,
                validationRows);
        } else {
            validation.ok = responseColumn != nullptr;
        }
        if (!validation.ok) {
            state.rFitPending = false;
            state.ok = false;
            state.status = validation.status.empty()
                ? "The response is not compatible with the selected model."
                : validation.status;
            return;
        }
        if (state.countRegression && !state.exposure.empty()) {
            const DataColumn *exposureColumn = FindDataColumnInDataFrame(
                specificationDataframe, state.exposure);
            const auto exposureValidation = exposureColumn
                ? rlispstat::core::InspectCountExposure(*exposureColumn, validationRows)
                : rlispstat::core::CountExposureValidation{};
            if (!exposureColumn || !exposureValidation.ok) {
                state.rFitPending = false;
                state.ok = false;
                state.status = exposureColumn && !exposureValidation.status.empty()
                    ? exposureValidation.status
                    : "The exposure variable was not found in the analysis dataset.";
                return;
            }
        }
        if (!state.offsetVariable.empty()) {
            if (state.countRegression && state.offsetVariable == state.exposure) {
                state.rFitPending = false;
                state.ok = false;
                state.status =
                    "The same variable cannot be both Exposure and Link-scale offset. "
                    "Exposure is transformed with log(); Link-scale offset is used as stored.";
                return;
            }
            const DataColumn *offsetColumn = FindDataColumnInDataFrame(
                specificationDataframe, state.offsetVariable);
            const auto offsetValidation = offsetColumn
                ? rlispstat::core::InspectLinkOffset(*offsetColumn, validationRows)
                : rlispstat::core::LinkOffsetValidation{};
            if (!offsetColumn || !offsetValidation.ok) {
                state.rFitPending = false;
                state.ok = false;
                state.status = offsetColumn && !offsetValidation.status.empty()
                    ? offsetValidation.status
                    : "The link-scale offset variable was not found in the analysis dataset.";
                return;
            }
        }
    }
    std::string signature = rlispstat::core::GeneralizedGLMFitSignature(state);
    if (state.rFitPending && state.lastRFitSignature == signature) {
        return;
    }
    state.rFitPending = true;
    state.lastRFitSignature = signature;
    const std::uint64_t generation = ++state.rFitGeneration;
    state.status = "Fitting " +
        rlispstat::core::StatisticalModelTypeLabel(state.modelType) +
        " in the main R session...";
    ArmGeneralizedGLMFitWatchdog(state.id, generation, signature,
                                state.multipleImputation);
    if (state.multipleImputation) {
        // A connected R session already owns the canonical MI dataset record
        // and the shared mice fitting functions.  Reuse that function-level
        // backend through the normal task queue; launching a second R process
        // here loses Count/Binary semantics and makes result delivery depend
        // on a second, synchronous UI hop.
        if (!g_mainRNotifyPath.empty()) {
            QueueGeneralizedGLMMainRTask(state, generation);
            return;
        }
        DataFrameModel df;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *found = FindDataFrameUnlockedConst(state.group);
            if (found) df = *found;
        }
        if (df.group.empty()) {
            state.rFitPending = false;
            state.status = rlispstat::core::GLMImputedDatasetNotAvailableStatus();
            return;
        }
        const std::string analysisId = state.id;
        const std::string response = state.response;
        const std::vector<std::string> terms = state.terms;
        const std::string scope = state.scope;
        const std::string modelSpec = EncodeStandaloneGeneralizedMISpec(
            GeneralizedGLMTaskForState(state, generation));
        std::thread worker([df, analysisId, response, terms, scope, modelSpec, signature, generation]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                df, "gglm", analysisId, std::vector<std::string>(), "",
                response, terms, scope, &message, modelSpec);
            if (!ok) {
                bool appliedToCurrentRequest = false;
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_generalizedGLMs.find(analysisId);
                    if (it != g_generalizedGLMs.end() &&
                        it->second.rFitGeneration == generation &&
                        it->second.rFitPending &&
                        it->second.lastRFitSignature == signature) {
                        it->second.rFitPending = false;
                        it->second.status = message;
                        appliedToCurrentRequest = true;
                    }
                }
                if (appliedToCurrentRequest) {
                    RefreshGeneralizedGLMOnMain(analysisId);
                    ShowWorkbenchMessageOnMain(
                        ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(message));
                }
            }
        });
        worker.detach();
        return;
    }
    QueueGeneralizedGLMMainRTask(state, generation);
}

static bool AddHierarchicalGeneralizedComparisonTerm(GeneralizedComparisonState &state,
                                                     GeneralizedComparisonModel &model,
                                                     const std::string &term)
{
    bool changed = false;
    std::string response = model.response.empty() ? state.response : model.response;
    for (const std::string &candidate : HierarchicalTermsForModelTerm(&state.seed, response, term)) {
        rlispstat::core::AddGeneralizedComparisonTermRow(state, candidate);
        if (!rlispstat::core::GeneralizedModelIncludesTerm(model, candidate)) {
            model.terms.push_back(candidate);
            changed = true;
        }
    }
    return changed;
}

static void ApplyGeneralizedComparisonTermTypes(GeneralizedComparisonState &state, GeneralizedGLMState &fit)
{
    for (const std::string &term : fit.terms) {
         std::string type = rlispstat::core::ModelTermDisplayType(&state.seed, term, state.termTypes);
         rlispstat::core::SetVariableMetaType(fit.seed.variableMeta, term, type);
    }
}

static void ArmGeneralizedComparisonFitWatchdog(const std::string &comparisonId,
                                                int generation,
                                                const std::string &signature,
                                                const MainRGeneralizedComparisonTask &request)
{
    constexpr int kPendingLimitSeconds = 120;
    std::thread watchdog([comparisonId, generation, signature, request,
                          kPendingLimitSeconds]() mutable {
        const auto started = std::chrono::steady_clock::now();
        const auto deadline = started +
            std::chrono::seconds(kPendingLimitSeconds);
        const std::array<int, 6> retrySeconds{{2, 5, 10, 20, 40, 80}};
        std::size_t nextRetry = 0;
        while (std::chrono::steady_clock::now() < deadline) {
            std::this_thread::sleep_for(std::chrono::milliseconds(250));
            bool retryCurrentRequest = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_generalizedComparisons.find(comparisonId);
                if (it == g_generalizedComparisons.end() || !it->second.rFitPending ||
                    it->second.rFitGeneration != generation ||
                    it->second.lastRFitSignature != signature) {
                    return;
                }
                if (nextRetry < retrySeconds.size() &&
                    std::chrono::steady_clock::now() >=
                        started + std::chrono::seconds(retrySeconds[nextRetry])) {
                    retryCurrentRequest = true;
                    ++nextRetry;
                }
            }
            if (retryCurrentRequest) {
                // Main-R task transport is deliberately at-least-once.  The
                // immutable generation/revision/fingerprint gates make a
                // duplicate harmless, while retrying prevents an unacknowledged
                // FIFO delivery from leaving the window pending forever.
                QueueGeneralizedComparisonMainRTask(request);
            }
        }
        bool expired = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto it = g_generalizedComparisons.find(comparisonId);
            if (it != g_generalizedComparisons.end() && it->second.rFitPending &&
                it->second.rFitGeneration == generation &&
                it->second.lastRFitSignature == signature) {
                it->second.rFitPending = false;
                const std::string status =
                    "The R comparison fit did not return within 120 seconds. "
                    "The pending request was cancelled.";
                for (GeneralizedComparisonModel &model : it->second.models) {
                    model.isStale = false;
                    model.fit.ok = false;
                    model.fit.status = status;
                    model.fitState =
                        rlispstat::core::RegressionComparisonFitState::Error;
                }
                RefreshGeneralizedTermRowsFromFits(it->second);
                for (GeneralizedComparisonModel &model : it->second.models) {
                    model.fitState =
                        rlispstat::core::RegressionComparisonFitState::Error;
                }
                expired = true;
            }
        }
        if (expired) {
            AcknowledgeGeneralizedComparisonMainRTask(comparisonId, generation);
            ShowGeneralizedComparisonOnMain(comparisonId);
        }
    });
    watchdog.detach();
}

static void RequestGeneralizedComparisonFitInMainR(GeneralizedComparisonState &state)
{
    state.frozenScopeNotice.clear();
    MacCommandDispatcher().applicationState().captureAnalysisScope(state.group, state.dataScope, state.dataScopeCaptured, &state.scope);
    if (state.response.empty() || state.models.empty()) {
        state.rFitPending = false;
        for (GeneralizedComparisonModel &model : state.models) {
            model.fit = GeneralizedGLMState();
            model.fitState = rlispstat::core::RegressionComparisonFitState::NotFitted;
            model.isStale = false;
        }
        RefreshGeneralizedTermRowsFromFits(state);
        return;
    }

    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state.group, dataframe)) {
        state.rFitPending = false;
        for (GeneralizedComparisonModel &model : state.models) {
            rlispstat::core::InvalidateGeneralizedComparisonModel(state, model);
        }
        RefreshGeneralizedTermRowsFromFits(state);
        return;
    }
    const bool datasetIdentityChanged =
        rlispstat::core::SynchronizeGeneralizedComparisonDatasetIdentity(state, dataframe);
    for (GeneralizedComparisonModel &model : state.models) {
        const bool specificationChanged =
            rlispstat::core::SynchronizeModelSpecificationTermTypes(model, dataframe);
        if (datasetIdentityChanged || specificationChanged) {
            rlispstat::core::InvalidateGeneralizedComparisonModel(state, model);
        }
    }

    MainRGeneralizedComparisonTask task;
    task.id = state.id;
    task.group = state.group;
    task.response = state.response;
    task.family = state.family;
    task.link = state.link;
    task.scope = state.scope;
    task.binaryComparison = state.binaryComparison;
    task.countComparison = state.countComparison;
    task.modelType = rlispstat::core::StatisticalModelTypeId(state.modelType);
    task.eventValue = state.responseCoding.eventValue.empty()
        ? state.responseCoding.eventLabel : state.responseCoding.eventValue;
    task.referenceValue = state.responseCoding.referenceValue.empty()
        ? state.responseCoding.referenceLabel : state.responseCoding.referenceValue;
    task.datasetType = state.datasetType;
    task.imputationSetId = state.imputationSetId;
    task.sourceDatasetId = state.sourceDatasetId;
    task.imputationCount = state.imputationCount;
    task.termTypes = state.termTypes;
    task.generation = ++state.rFitGeneration;
    task.autoRefit = state.autoRefit;

    for (GeneralizedComparisonModel &model : state.models) {
        if (model.modelVersion <= 0) model.modelVersion = 1;
        const auto specification =
            rlispstat::core::EffectiveGeneralizedComparisonModelSpecification(state, model);
        MainRGeneralizedComparisonModelTask item;
        item.id = model.id;
        item.label = model.label;
        item.response = specification.response;
        item.family = model.family.empty() ? state.family : model.family;
        item.link = model.link.empty() ? state.link : model.link;
        item.scope = specification.scope.empty() ? state.scope : specification.scope;
        item.responseBoundsConfigured = model.responseBoundsConfigured;
        item.responseLower = model.responseLower;
        item.responseUpper = model.responseUpper;
        item.countRegression = state.countComparison;
        item.countDistribution = rlispstat::core::CountDistributionId(model.countDistribution);
        item.exposure = model.exposure;
        item.offsetVariable = model.offsetVariable;
        item.trialsVariable = model.trialsVariable;
        item.trialsConstant = model.trialsConstant;
        item.terms = specification.terms;
        item.termTypes = rlispstat::core::GeneralizedComparisonModelTermTypes(state, model);
        item.centeredPredictors.assign(specification.centeredPredictors.begin(),
                                       specification.centeredPredictors.end());
        item.factorReferenceLevels = specification.factorReferenceLevels;
        item.specificationRevision = model.modelVersion;
        item.specificationFingerprint =
            rlispstat::core::GeneralizedComparisonModelSpecificationFingerprint(state, model);
        task.models.push_back(std::move(item));
        model.requestedSpecificationRevision = model.modelVersion;
        model.requestedSpecificationFingerprint =
            rlispstat::core::GeneralizedComparisonModelSpecificationFingerprint(state, model);
        model.isStale = true;
        model.fitState = rlispstat::core::RegressionComparisonFitState::Pending;
    }
    if (state.dataScopeCaptured &&
        state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
        task.rows = state.dataScope.originalRowIds;
    }
    state.lastRFitSignature =
        rlispstat::core::GeneralizedComparisonFitSignature(state);
    RefreshGeneralizedTermRowsFromFits(state);
    state.rFitPending = true;
    ArmGeneralizedComparisonFitWatchdog(
        state.id, task.generation, state.lastRFitSignature, task);
    QueueGeneralizedComparisonMainRTask(std::move(task));
}

static void RefitGeneralizedComparisonModel(GeneralizedComparisonState &state, GeneralizedComparisonModel &model)
{
    model.isStale = true;
    model.fitState = rlispstat::core::RegressionComparisonFitState::Pending;
    RequestGeneralizedComparisonFitInMainR(state);
}

static void RefitGeneralizedComparisonModels(GeneralizedComparisonState &state, bool forceAll = false)
{
    if (state.response.empty() || state.models.empty()) {
        for (GeneralizedComparisonModel &model : state.models) {
            model.fit = GeneralizedGLMState();
            model.fitState = rlispstat::core::RegressionComparisonFitState::NotFitted;
            model.isStale = false;
        }
        RefreshGeneralizedTermRowsFromFits(state);
        return;
    }
    bool refitNeeded = forceAll;
    for (GeneralizedComparisonModel &model : state.models) {
        if (model.isStale || model.fitVersion == 0) refitNeeded = true;
    }
    if (!refitNeeded || (state.rFitPending && !forceAll)) return;
    RequestGeneralizedComparisonFitInMainR(state);
}

static bool FindGeneralizedComparisonModelById(const std::string &modelId,
                                               GeneralizedComparisonState **stateOut = nullptr,
                                               GeneralizedComparisonModel **modelOut = nullptr)
{
    for (auto &entry : g_generalizedComparisons) {
        GeneralizedComparisonState &state = entry.second;
        GeneralizedComparisonModel *model =
            rlispstat::core::GeneralizedComparisonModelById(state, modelId);
        if (!model) continue;
        if (stateOut) *stateOut = &state;
        if (modelOut) *modelOut = model;
        return true;
    }
    return false;
}


static bool AddHierarchicalRegressionComparisonTerm(RegressionComparisonState &state,
                                                     RegressionComparisonModel &model,
                                                     const std::string &term)
{
    bool changed = false;
    std::string response = model.response.empty() ? state.response : model.response;
    for (const std::string &candidate : HierarchicalTermsForModelTerm(&state.seed, response, term)) {
        rlispstat::core::AddRegressionTermRow(state, candidate);
        if (!rlispstat::core::ModelIncludesTerm(model, candidate)) {
            model.terms.push_back(candidate);
            changed = true;
        }
    }
    return changed;
}

static void RequestRegressionComparisonFitInMainR(RegressionComparisonState &state)
{
    state.frozenScopeNotice.clear();
    MacCommandDispatcher().applicationState().captureAnalysisScope(state.group, state.dataScope, state.dataScopeCaptured, &state.scope);
    if (state.response.empty() || state.models.empty()) {
        state.rFitPending = false;
        state.lastRFitSignature.clear();
        for (RegressionComparisonModel &model : state.models) {
            model.fit = GLMFitSummary();
            model.isStale = true;
            model.fitState = rlispstat::core::RegressionComparisonFitState::NotFitted;
        }
        return;
    }
    DataFrameModel dataframe;
    if (DataFrameSnapshotForGroup(state.group, dataframe)) {
        const bool datasetIdentityChanged =
            rlispstat::core::SynchronizeRegressionComparisonDatasetIdentity(state, dataframe);
        const bool specificationChanged =
            rlispstat::core::SynchronizeRegressionComparisonTermTypes(state, dataframe);
        if (datasetIdentityChanged || specificationChanged) {
            for (RegressionComparisonModel &model : state.models) {
                rlispstat::core::InvalidateRegressionComparisonModel(state, model);
            }
        }
    }
    std::string signature = rlispstat::core::RegressionComparisonFitSignature(state);
    if (state.rFitPending && state.lastRFitSignature == signature) {
        return;
    }
    state.rFitPending = true;
    state.lastRFitSignature = signature;
    MainRRegressionComparisonTask task;
    task.id = state.id;
    task.generation = ++state.rFitGeneration;
    task.group = state.group;
    task.response = state.response;
    task.scope = state.scope == "compare_selected_all" ? "all" : state.scope;
    task.autoRefit = state.autoRefit;
    task.datasetType = state.datasetType;
    task.imputationSetId = state.imputationSetId;
    task.sourceDatasetId = state.sourceDatasetId;
    task.imputationCount = state.imputationCount;
    task.termRows = state.termRows;
    task.termTypes = state.termTypes;
    task.rows = RowsForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured);
    task.models.reserve(state.models.size());
    for (RegressionComparisonModel &model : state.models) {
        model.fitState = rlispstat::core::RegressionComparisonFitState::Pending;
        model.isStale = true;
        const rlispstat::core::ModelSpecification specification =
            rlispstat::core::EffectiveRegressionComparisonModelSpecification(state, model);
        MainRRegressionComparisonModelTask item;
        item.id = model.id;
        item.label = model.label;
        item.response = specification.response;
        item.terms = specification.terms;
        item.termTypes = specification.termTypes;
        item.centeredPredictors.assign(specification.centeredPredictors.begin(),
                                       specification.centeredPredictors.end());
        item.factorReferenceLevels = specification.factorReferenceLevels;
        task.models.push_back(std::move(item));
    }
    QueueRegressionComparisonMainRTask(task);
}


static void RefitRegressionComparisonModel(RegressionComparisonState &state, RegressionComparisonModel &model)
{
    if (state.precomputed) {
        model.isStale = false;
        model.fitState = model.fit.ok
            ? rlispstat::core::RegressionComparisonFitState::Valid
            : rlispstat::core::RegressionComparisonFitState::Error;
        return;
    }
    model.isStale = true;
    if (const DataFrameModel *dataframe = FindDataFrameUnlockedConst(state.group)) {
        rlispstat::core::SynchronizeRegressionComparisonTermTypes(state, *dataframe);
    }
    RequestRegressionComparisonFitInMainR(state);
}


static void RefitRegressionComparisonModels(RegressionComparisonState &state, bool forceAll = false)
{
    if (state.precomputed) {
        RefreshRegressionTermRowsFromFits(state);
        rlispstat::core::PruneRegressionComparisonRowsForCurrentTypes(state);
        return;
    }
    bool needsRefit = forceAll;
    for (RegressionComparisonModel &model : state.models) {
        if (forceAll) {
            model.isStale = true;
        }
        if (model.isStale || model.fitVersion == 0) {
            needsRefit = true;
        }
    }
    if (needsRefit) {
        RequestRegressionComparisonFitInMainR(state);
    } else {
        RefreshRegressionTermRowsFromFits(state);
        rlispstat::core::PruneRegressionComparisonRowsForCurrentTypes(state);
    }
}

