        *dataframe, specification, additionalVariables);
}

// Convert the semantic diagnostic result to the native plot representation in
// one place. A histogram is not a scatterplot with y = 0: HistogramView
// consumes histogramPoints and histogramBins exclusively.
static bool ApplyDiagnosticPlotData(
    PlotModel *diag,
    const rlispstat::core::DiagnosticPlotData &data)
{
    if (!diag || !data.ok) return false;

    const int previousBinCount = static_cast<int>(diag->histogramBins.size());
    diag->kind = data.kind;
    diag->glmDiagnosticKind = data.diagnosticKind;
    diag->title = data.title;
    if (diag->diagnosticImputationCount > 0 &&
        !diag->diagnosticShowImputationUncertainty) {
        diag->title += " — Showing imputation " +
            std::to_string(diag->diagnosticImputationIndex) + " of " +
            std::to_string(diag->diagnosticImputationCount) + " (not pooled)";
    }
    diag->xLabel = data.xLabel;
    diag->yLabel = data.yLabel;
    diag->diagnosticShowIdentityLine = data.showIdentityLine;
    diag->points.clear();
    diag->histogramPoints.clear();
    diag->histogramBins.clear();
    diag->rocStepPoints.clear();
    diag->rocThresholds.clear();
    diag->interactionPlotLines = data.lines;
    diag->diagnosticImputationValues = data.imputationValues;

    if (data.kind == "histogram") {
        diag->histogramPoints.reserve(data.points.size());
        for (const rlispstat::core::DiagnosticPlotPoint &point : data.points) {
            diag->histogramPoints.push_back(HistogramPoint{point.x, point.row, 0});
        }
        if (previousBinCount > 0) rlispstat::core::RebinHistogram(*diag, previousBinCount);
        else RebinHistogramByRule(diag, "sturges");
    } else {
        diag->points.reserve(data.points.size());
        for (const rlispstat::core::DiagnosticPlotPoint &point : data.points) {
            diag->points.push_back(DataPoint{point.x, point.y, point.row});
        }
        diag->rocStepPoints.reserve(data.visualPoints.size());
        for (const rlispstat::core::DiagnosticPlotPoint &point : data.visualPoints) {
            diag->rocStepPoints.push_back(DataPoint{point.x, point.y, 0});
        }
        diag->rocThresholds.reserve(data.rocThresholds.size());
        for (const rlispstat::core::DiagnosticROCThreshold &threshold : data.rocThresholds) {
            rlispstat::core::ROCThresholdLink link;
            link.point = DataPoint{threshold.falsePositiveRate, threshold.truePositiveRate, 0};
            link.threshold = threshold.threshold;
            link.truePositive = threshold.truePositive;
            link.falsePositive = threshold.falsePositive;
            link.trueNegative = threshold.trueNegative;
            link.falseNegative = threshold.falseNegative;
            link.crossingRows = threshold.crossingRows;
            link.falsePositiveRows = threshold.falsePositiveRows;
            link.falseNegativeRows = threshold.falseNegativeRows;
            diag->rocThresholds.push_back(std::move(link));
        }
        ComputeRanges(diag);
        if (!diag->diagnosticImputationValues.empty()) {
            std::vector<rlispstat::core::ScatterplotPointValue> points;
            points.reserve(diag->points.size());
            for (const DataPoint &point : diag->points) {
                points.push_back({point.row, point.x, point.y});
            }
            const auto viewport = rlispstat::core::ScatterplotViewportIncludingPointImputations(
                points, diag->diagnosticImputationValues,
                diag->scatterImputationUncertainty);
            if (viewport.has_value()) {
                diag->xmin = viewport->xmin; diag->xmax = viewport->xmax;
                diag->ymin = viewport->ymin; diag->ymax = viewport->ymax;
            }
        }
        rlispstat::core::ApplyDiagnosticIdentityRange(*diag);
    }

    diag->displayedFitVersion = data.fitVersion;
    diag->displayedDiagnosticsVersion = data.diagnosticsVersion;
    diag->displayedDiagnosticOptionsVersion = data.diagnosticOptionsVersion;
    diag->displayedResidualType = data.residualType;
    return true;
}

static void InvalidateModelDiagnosticPlot(PlotModel *diag)
{
    if (!diag || !diag->isGLMDiagnostic) return;
    // Never leave observations from an earlier specification on screen while
    // its replacement is fitting, or after that fit has failed.
    diag->points.clear();
    diag->histogramPoints.clear();
    diag->histogramBins.clear();
    diag->rocStepPoints.clear();
    diag->rocThresholds.clear();
    diag->interactionPlotLines.clear();
    diag->diagnosticImputationValues.clear();
    diag->diagnosticAllImputationValues.clear();
    diag->displayedFitVersion = 0;
    diag->displayedDiagnosticsVersion = 0;
    diag->displayedDiagnosticOptionsVersion = 0;
    diag->diagnosticSummary = "No current model fit is available for this diagnostic.";
    const std::string suffix = " — waiting for current model fit";
    if (diag->title.size() < suffix.size() ||
        diag->title.compare(diag->title.size() - suffix.size(), suffix.size(), suffix) != 0) {
        diag->title += suffix;
    }
}

static void RegisterPartialRegressionCodeReference(
    PlotModel *plot, const rlispstat::core::RegressionPartialPlotResult &result)
{
    auto &application = MacCommandDispatcher().applicationState();
    const auto *source = application.regressionSourceOutputCodeReference(
        plot->regressionDerivedSourceKind, plot->regressionDerivedSourceModelId);
    if (source) {
        plot->codeReference = rlispstat::core::RegressionPartialPlotCodeReference(
            *plot, result, *source);
        application.registerOutputCodeReference(plot->codeReference);
    }
}

static std::string OpenRBackedPartialRegressionPlot(
    const DataFrameModel &df,
    const std::string &mode,
    const std::string &analysisId,
    const std::string &response,
    const std::vector<std::string> &terms,
    const std::string &scope,
    const std::string &modelSpec,
    const std::string &term,
    const std::string &residualType,
    std::string *message,
    const RegressionInteractionDerivedLink &derivedLink = {})
{
    rlispstat::core::RegressionPartialPlotResult result;
    if (!RunRBackedPartialRegressionPlot(
            df, mode, analysisId, response, terms, scope, modelSpec,
            term, residualType, &result, message)) {
        return "";
    }
    PlotModel *plot = nullptr;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!derivedLink.sourceModelId.empty()) {
            for (const auto &entry : g_plots) {
                PlotModel *candidate = entry.second;
                if (candidate && candidate->isRegressionDerivedPlot &&
                    candidate->regressionDerivedKind == "partial_regression_plot" &&
                    candidate->regressionDerivedSourceModelId == derivedLink.sourceModelId &&
                    candidate->regressionDerivedTerm == term) {
                    plot = candidate;
                    break;
                }
            }
        }
    }
    const bool isNewPlot = plot == nullptr;
    if (isNewPlot) {
        plot = new PlotModel();
        rlispstat::core::PopulateDatasetSeedPlot(*plot, df, df.group);
        plot->id = "partial_regression_" + df.group + "_" +
            std::to_string((long long)time(nullptr)) + "_" +
            std::to_string(std::rand() % 1000000);
    }
    plot->kind = "scatter";
    plot->isDatasetSeed = false;
    plot->isGLMDiagnostic = true;
    plot->glmModelId = derivedLink.sourceModelId.empty()
        ? analysisId : derivedLink.sourceModelId;
    plot->glmDiagnosticKind = "partial_regression";
    plot->isRegressionDerivedPlot = !derivedLink.sourceModelId.empty();
    plot->regressionDerivedKind = plot->isRegressionDerivedPlot
        ? "partial_regression_plot" : std::string();
    plot->regressionDerivedSourceKind = derivedLink.sourceModelKind;
    plot->regressionDerivedSourceModelId = derivedLink.sourceModelId;
    plot->regressionDerivedSourceRevision = derivedLink.sourceModelRevision;
    plot->regressionDerivedSourceFitVersion = derivedLink.sourceFitVersion;
    plot->regressionDerivedTerm = term;
    plot->generalizedDiagnosticResiduals =
        derivedLink.sourceModelKind.rfind("generalized", 0) == 0;
    plot->group = df.group;
    plot->diagnosticImputationCount = std::max(1, result.imputationCount);
    plot->diagnosticImputationIndex = std::clamp(
        plot->diagnosticImputationIndex, 1, plot->diagnosticImputationCount);
    if (isNewPlot) {
        plot->diagnosticShowImputationUncertainty =
            rlispstat::core::DiagnosticImputationUncertaintyShouldBeDefault(
                df, "partial_regression");
        plot->diagnosticImputationUncertaintyScope = "all";
    }
    plot->regressionPartialPointsByImputation = result.pointsByImputation;
    plot->regressionPartialResidualType = result.residualType;
    plot->regressionPartialContributionScale = result.contributionScale;
    plot->regressionPartialAvailableTerms = result.availableTerms;
    plot->displayedResidualType = result.residualType;
    plot->diagnosticAvailableResidualTypes = result.availableResidualTypes;
    rlispstat::core::ModelSpecification specification;
    specification.response = response;
    specification.terms = terms;
    plot->diagnosticRowsWithImputedModelInputs =
        rlispstat::core::RowsWithImputedModelInputs(df, specification);
    const rlispstat::core::DiagnosticPlotData data =
        rlispstat::core::BuildRegressionPartialPlotData(
            result, plot->diagnosticImputationIndex,
            plot->diagnosticShowImputationUncertainty);
    if (!ApplyDiagnosticPlotData(plot, data)) {
        if (isNewPlot) delete plot;
        if (message && message->empty()) *message = data.message;
        return "";
    }
    RegisterPartialRegressionCodeReference(plot, result);
    plot->displayedFitVersion = derivedLink.sourceFitVersion;
    plot->displayedDiagnosticsVersion = derivedLink.sourceFitVersion;
    if (isNewPlot) {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(plot)) {
            delete plot;
            if (message) *message = "Could not register the partial regression plot.";
            return "";
        }
    }
    if (isNewPlot) {
        PublishSpreadPlotMessage(
            "DIAGNOSTIC_PLOT_OPENED", plot->group, plot->id, analysisId);
        AddPlotOnMain(plot);
    } else {
        for (ScatterView *view : g_views) {
            if (view.model == plot) {
                [view setNeedsDisplay:YES];
                [view displayIfNeeded];
            }
        }
    }
    return plot->id;
}

static bool PopulateDiagnosticPlotFromFit(PlotModel *diag, const GLMFitSummary &fit,
                                          int fitVersion, int diagnosticsVersion,
                                          const std::set<int> &rowsWithImputedModelInputs)
{
    diag->diagnosticSummary.clear();
    // Keep the provenance classification with the exact diagnostic
    // presentation that was built from it.  The renderer runs after this
    // function returns, so retaining the set only as a local filtering input
    // makes every uncertainty glyph look like fitted-value propagation.
    diag->diagnosticRowsWithImputedModelInputs = rowsWithImputedModelInputs;
    const std::vector<GLMDiagnosticRow> *diagnostics = &fit.diagnostics;
    diag->diagnosticImputationCount = static_cast<int>(fit.diagnosticsByImputation.size());
    if (!fit.diagnosticsByImputation.empty()) {
        diag->diagnosticImputationIndex = std::clamp(
            diag->diagnosticImputationIndex, 1,
            static_cast<int>(fit.diagnosticsByImputation.size()));
        diagnostics = &fit.diagnosticsByImputation[
            static_cast<std::size_t>(diag->diagnosticImputationIndex - 1)];
    } else {
        diag->diagnosticImputationIndex = 1;
    }
    rlispstat::core::DiagnosticPlotData data;
    if (diag->diagnosticShowImputationUncertainty &&
        fit.diagnosticsByImputation.size() > 1) {
        std::vector<rlispstat::core::DiagnosticPlotData> perImputation;
        perImputation.reserve(fit.diagnosticsByImputation.size());
        for (const auto &imputationDiagnostics : fit.diagnosticsByImputation) {
            perImputation.push_back(rlispstat::core::BuildLinearDiagnosticPlotData(
                diag->glmDiagnosticKind,
                diag->displayedResidualType.empty() ? "raw" : diag->displayedResidualType,
                imputationDiagnostics,
                fitVersion, diagnosticsVersion));
        }
        const rlispstat::core::DiagnosticPlotData allImputations =
            rlispstat::core::BuildDiagnosticPlotDataAcrossImputations(perImputation);
        diag->diagnosticAllImputationValues = allImputations.imputationValues;
        data = diag->diagnosticImputationUncertaintyScope == "all"
            ? allImputations
            : rlispstat::core::BuildDiagnosticPlotDataAcrossImputations(
                perImputation, rowsWithImputedModelInputs);
    } else {
        // The current fit may be a transient single-imputation result while a
        // new pooled MI fit is pending.  Preserve the user's presentation
        // choice so the accepted fit can restore the uncertainty view.
        diag->diagnosticAllImputationValues.clear();
        data = rlispstat::core::BuildLinearDiagnosticPlotData(
            diag->glmDiagnosticKind,
            diag->displayedResidualType.empty() ? "raw" : diag->displayedResidualType,
            *diagnostics, fitVersion, diagnosticsVersion);
    }
    return ApplyDiagnosticPlotData(diag, data);
}

static void RefreshModelDiagnosticsForModelNow(const std::string &modelId)
{
    for (const auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (plot && plot->isGLMDiagnostic && plot->glmModelId == modelId) {
            if (!UpdateGLMDiagnosticPlot(plot)) InvalidateModelDiagnosticPlot(plot);
            UpdateWindowTitleOnMain(plot);
        }
    }
    for (ScatterView *view : g_views) {
        if (view.model && view.model->isGLMDiagnostic && view.model->glmModelId == modelId) {
            [view setNeedsDisplay:YES];
            [view displayIfNeeded];
        }
    }
    for (HistogramView *view : g_histogramViews) {
        if (view.model && view.model->isGLMDiagnostic &&
            view.model->glmModelId == modelId) {
            [view setNeedsDisplay:YES];
            [view displayIfNeeded];
        }
    }
    RefreshPairwiseDerivedOutputsForModelNow(modelId);
    RefreshInteractionDerivedOutputsForModelNow(modelId);
}

static bool PopulateGeneralizedDiagnosticPlot(PlotModel *diag, GeneralizedGLMState &state,
                                              std::string *message = nullptr,
                                              const rlispstat::core::DiagnosticOptions *optionsOverride = nullptr)
{
    if (!diag || !state.ok) {
        if (message) *message = rlispstat::core::GLMNoDiagnosticRowsStatus();
        return false;
    }
    const std::string diagnosticKind =
        rlispstat::core::NormalizeGeneralizedDiagnosticKind(diag->glmDiagnosticKind);
    if (diagnosticKind == "observed_predicted_score_distribution" ||
        diagnosticKind == "boundary_zero_fit") {
        diag->diagnosticImputationCount = static_cast<int>(
            state.boundedCountDistributionsByImputation.size());
        const std::vector<rlispstat::core::BoundedCountDistributionPoint> *distribution =
            &state.boundedCountDistribution;
        if (!state.boundedCountDistributionsByImputation.empty()) {
            diag->diagnosticImputationIndex = std::clamp(
                diag->diagnosticImputationIndex, 1,
                static_cast<int>(state.boundedCountDistributionsByImputation.size()));
            distribution = &state.boundedCountDistributionsByImputation[
                static_cast<std::size_t>(diag->diagnosticImputationIndex - 1)];
        }
        const bool includeCeiling = state.countRegression &&
            rlispstat::core::CountDistributionUsesTrials(state.countDistribution) &&
            state.countDistribution != rlispstat::core::CountDistribution::PerfectScore;
        const auto data = diagnosticKind == "boundary_zero_fit"
            ? rlispstat::core::BuildDiscreteBoundaryDiagnosticPlotData(
                *distribution, includeCeiling,
                state.fitVersion, state.diagnosticsVersion)
            : rlispstat::core::BuildBoundedCountDistributionDiagnosticPlotData(
                *distribution, state.fitVersion, state.diagnosticsVersion);
        if (!data.ok) {
            if (message) *message = data.message;
            return false;
        }
        return ApplyDiagnosticPlotData(diag, data);
    }
    const std::vector<GeneralizedGLMDiagnosticRow> *diagnostics = &state.diagnostics;
    diag->diagnosticImputationCount = static_cast<int>(state.diagnosticsByImputation.size());
    if (!state.diagnosticsByImputation.empty()) {
        diag->diagnosticImputationIndex = std::clamp(
            diag->diagnosticImputationIndex, 1,
            static_cast<int>(state.diagnosticsByImputation.size()));
        diagnostics = &state.diagnosticsByImputation[
            static_cast<std::size_t>(diag->diagnosticImputationIndex - 1)];
    } else {
        diag->diagnosticImputationIndex = 1;
    }
    if (diagnostics->empty()) {
        if (message) *message = rlispstat::core::GLMNoDiagnosticRowsStatus();
        return false;
    }
    // Residual representation is a property of this diagnostic window.  It
    // must not mutate (or be overwritten by) the model's fitting options.
    rlispstat::core::DiagnosticOptions options =
        optionsOverride ? *optionsOverride : state.diagnosticOptions;
    if (!diag->displayedResidualType.empty() &&
        rlispstat::core::IsGeneralizedResidualTypeAvailable(
            state, diag->displayedResidualType)) {
        options.residualType = diag->displayedResidualType;
    }
    const std::set<int> rowsWithImputedModelInputs =
        ImputedModelInputRowsForMac(
            state.group, state,
            state.exposure.empty()
                ? std::vector<std::string>{}
                : std::vector<std::string>{state.exposure});
    // Persist the provenance used by the semantic diagnostic result.  AppKit
    // consumes this field later when assigning red/black uncertainty glyphs.
    diag->diagnosticRowsWithImputedModelInputs = rowsWithImputedModelInputs;
    rlispstat::core::DiagnosticPlotData data;
    if (diag->diagnosticShowImputationUncertainty &&
        state.diagnosticsByImputation.size() > 1) {
        std::vector<rlispstat::core::DiagnosticPlotData> perImputation;
        perImputation.reserve(state.diagnosticsByImputation.size());
        for (const auto &imputationDiagnostics : state.diagnosticsByImputation) {
            perImputation.push_back(rlispstat::core::BuildGeneralizedDiagnosticPlotData(
                diag->glmDiagnosticKind, options, imputationDiagnostics,
                state.fitVersion, state.diagnosticsVersion));
        }
        const rlispstat::core::DiagnosticPlotData allImputations =
            rlispstat::core::BuildDiagnosticPlotDataAcrossImputations(perImputation);
        diag->diagnosticAllImputationValues = allImputations.imputationValues;
        data = diag->diagnosticImputationUncertaintyScope == "all"
            ? allImputations
            : rlispstat::core::BuildDiagnosticPlotDataAcrossImputations(
                perImputation, rowsWithImputedModelInputs);
    } else {
        // Presentation state belongs to the plot, not to whichever fit result
        // happened to arrive most recently.  In particular, never downgrade
        // an MI uncertainty plot while its replacement fit is pending.
        diag->diagnosticAllImputationValues.clear();
        data = rlispstat::core::BuildGeneralizedDiagnosticPlotData(
            diag->glmDiagnosticKind, options, *diagnostics,
            state.fitVersion, state.diagnosticsVersion);
    }
    if (!data.ok) {
        if (message) *message = data.message;
        return false;
    }
    const std::size_t noteIndex = static_cast<std::size_t>(std::max(1,diag->diagnosticImputationIndex)-1);
    diag->diagnosticSummary = noteIndex < state.diagnosticNotesByImputation.size()
        ? state.diagnosticNotesByImputation[noteIndex] : std::string{};
    return ApplyDiagnosticPlotData(diag, data);
}

using GLMNumericSummary = rlispstat::core::NumericSummary;

using GLMPostEstimate = rlispstat::core::LinearFunctionEstimate;
using GLMInteractionReport = rlispstat::core::GLMInteractionReport;

using rlispstat::core::GLMRowIncluded;
using rlispstat::core::GLMLevelIndex;
using rlispstat::core::GLMRowsUsedSet;

static GLMNumericSummary GLMNumericSummaryForVariable(PlotModel *model, const std::string &variable,
                                                       const GLMFitSummary &fit)
{
    if (!model) return rlispstat::core::SummarizeFiniteValues({});
    return rlispstat::core::GLMNumericSummaryForVariable(
        FindDataColumnForModel(model, variable),
        model->variables,
        variable,
        GLMRowsUsedSet(fit));
}

static std::vector<std::string> GLMFactorLevelsForVariable(PlotModel *model, const std::string &variable,
                                                           const GLMFitSummary &fit)
{
    if (const rlispstat::core::GLMFactorCoding *coding =
            rlispstat::core::FactorCodingForVariable(fit, variable)) {
        if (!coding->levels.empty()) return coding->levels;
    }
    std::vector<std::string> levels;
    std::set<std::string> seen;
    if (!model) return levels;
    const std::set<int> rows = GLMRowsUsedSet(fit);
    if (const DataColumn *col = FindDataColumnForModel(model, variable)) {
        for (size_t i = 0; i < col->values.size(); ++i) {
            if (!GLMRowIncluded(rows, (int)i + 1)) continue;
            const std::string &value = col->values[i];
            if (DataCellIsMissing(value)) continue;
            if (seen.insert(value).second) levels.push_back(value);
        }
    } else if (NumericVariable *var = FindVariable(model, variable)) {
        for (size_t i = 0; i < var->values.size(); ++i) {
            if (!GLMRowIncluded(rows, (int)i + 1)) continue;
            double value = var->values[i];
            if (!std::isfinite(value)) continue;
            std::string label = FormatFactorLabel(value);
            if (seen.insert(label).second) levels.push_back(label);
        }
    }
    return levels;
}

static rlispstat::core::ScenarioDesignInput GLMScenarioDesignInputForModel(
    PlotModel *model,
    const std::vector<std::string> &terms,
    const std::map<std::string, std::string> &termTypes,
    const GLMFitSummary &fit,
    const std::map<std::string, double> &numericValues,
    const std::map<std::string, std::string> &factorValues)
{
    rlispstat::core::ScenarioDesignInput input;
    input.terms = terms;
    input.termTypes = termTypes;
    input.numericValues = numericValues;
    input.factorValues = factorValues;
    input.expectedSize = fit.beta.size();
    for (const std::string &variable : BaseVariablesFromModelTerms(model, "", terms)) {
        rlispstat::core::ScenarioVariableInfo info;
        info.type = rlispstat::core::GLMBaseVariableType(model, variable, termTypes);
        if (info.type == "factor") {
            if (!rlispstat::core::ApplyFittedFactorCoding(fit, variable, info)) {
                info.factorLevels = GLMFactorLevelsForVariable(model, variable, fit);
            }
        } else {
            GLMNumericSummary summary = GLMNumericSummaryForVariable(model, variable, fit);
            info.numericDefault = summary.ok ? summary.mean : 0.0;
        }
        input.variables[variable] = info;
    }
    return input;
}

static bool GLMScenarioAt(PlotModel *model,
                          const std::vector<std::string> &terms,
                          const std::map<std::string, std::string> &termTypes,
                          const GLMFitSummary &fit,
                          std::map<std::string, double> numericValues,
                          std::map<std::string, std::string> factorValues,
                          std::vector<double> &out)
{
    rlispstat::core::ScenarioDesignInput input = GLMScenarioDesignInputForModel(
        model, terms, termTypes, fit, numericValues, factorValues);
    return rlispstat::core::BuildScenarioDesignVector(input, out);
}

static GLMPostEstimate GLMEstimateLinearFunction(const GLMFitSummary &fit,
                                                 const std::vector<double> &contrast,
                                                 const std::string &label,
                                                 double confidenceLevel)
{
    return rlispstat::core::EstimateLinearFunction(fit.beta, fit.covariance, contrast, label, confidenceLevel);
}

static GLMPostEstimate GLMPredictionEstimate(PlotModel *model,
                                             const std::vector<std::string> &terms,
                                             const std::map<std::string, std::string> &termTypes,
                                             const GLMFitSummary &fit,
                                             const std::map<std::string, double> &numericValues,
                                             const std::map<std::string, std::string> &factorValues,
                                             const std::string &label,
                                             double confidenceLevel)
{
    std::vector<double> design;
    if (!GLMScenarioAt(model, terms, termTypes, fit, numericValues, factorValues, design)) {
        GLMPostEstimate missing;
        missing.label = label;
        return missing;
    }
    return GLMEstimateLinearFunction(fit, design, label, confidenceLevel);
}

static bool GLMDifferenceContrast(PlotModel *model,
                                  const std::vector<std::string> &terms,
                                  const std::map<std::string, std::string> &termTypes,
                                  const GLMFitSummary &fit,
                                  const std::map<std::string, double> &numericA,
                                  const std::map<std::string, std::string> &factorA,
                                  const std::map<std::string, double> &numericB,
                                  const std::map<std::string, std::string> &factorB,
                                  std::vector<double> &contrast)
{
    std::vector<double> a;
    std::vector<double> b;
    if (!GLMScenarioAt(model, terms, termTypes, fit, numericA, factorA, a)) return false;
    if (!GLMScenarioAt(model, terms, termTypes, fit, numericB, factorB, b)) return false;
    contrast = SubtractVectors(a, b);
    return !contrast.empty();
}

static void GLMAddContinuousByCategoricalReport(PlotModel *model,
                                                const std::vector<std::string> &terms,
                                                const std::map<std::string, std::string> &termTypes,
                                                const GLMFitSummary &fit,
                                                const std::string &x,
                                                const std::string &g,
                                                double confidenceLevel,
                                                GLMInteractionReport &report)
{
    GLMNumericSummary xSummary = GLMNumericSummaryForVariable(model, x, fit);
    std::vector<std::string> levels = GLMFactorLevelsForVariable(model, g, fit);
    if (!xSummary.ok || levels.empty()) {
        report.message = "The interaction could not be interpreted because one component has no fitted values.";
        return;
    }
    std::vector<GLMPostEstimate> slopes;
    std::vector<std::vector<double>> slopeContrasts;
    for (const std::string &level : levels) {
        std::map<std::string, double> low{{x, xSummary.mean}};
        std::map<std::string, double> high{{x, xSummary.mean + 1.0}};
        std::map<std::string, std::string> factor{{g, level}};
        std::vector<double> contrast;
        if (!GLMDifferenceContrast(model, terms, termTypes, fit, high, factor, low, factor, contrast)) continue;
        slopeContrasts.push_back(contrast);
        slopes.push_back(GLMEstimateLinearFunction(fit, contrast, "Slope of " + x + " when " + g + " = " + level, confidenceLevel));
    }
    report.sections.push_back({"Simple slopes", slopes,
        rlispstat::core::GLMInteractionSectionInference::Test});

    std::vector<GLMPostEstimate> comparisons;
    for (size_t i = 0; i < slopeContrasts.size(); ++i) {
        for (size_t j = i + 1; j < slopeContrasts.size(); ++j) {
            std::vector<double> contrast = SubtractVectors(slopeContrasts[i], slopeContrasts[j]);
            if (contrast.empty()) continue;
            comparisons.push_back(GLMEstimateLinearFunction(fit, contrast, levels[i] + " - " + levels[j] + " slope difference", confidenceLevel));
        }
    }
    ApplyHolmAdjustedPValues(comparisons);
    report.sections.push_back({"Pairwise slope comparisons (Holm)", comparisons,
        rlispstat::core::GLMInteractionSectionInference::AdjustedComparison});

    std::vector<GLMPostEstimate> predictions;
    std::vector<std::pair<std::string, double>> xValues;
    if (std::isfinite(xSummary.sd) && xSummary.sd > 0.0) {
        xValues.push_back(std::make_pair("M - SD", xSummary.mean - xSummary.sd));
        xValues.push_back(std::make_pair("M", xSummary.mean));
        xValues.push_back(std::make_pair("M + SD", xSummary.mean + xSummary.sd));
    } else {
        xValues.push_back(std::make_pair("M", xSummary.mean));
    }
    for (const std::string &level : levels) {
        for (const auto &xValue : xValues) {
            predictions.push_back(GLMPredictionEstimate(model, terms, termTypes, fit,
                                                        {{x, xValue.second}}, {{g, level}},
                                                        g + " = " + level + ", " + x + " = " + xValue.first,
                                                        confidenceLevel));
        }
    }
    report.sections.push_back({"Predicted means", predictions,
        rlispstat::core::GLMInteractionSectionInference::EstimateOnly});
}

static void GLMAddCategoricalByCategoricalReport(PlotModel *model,
                                                 const std::vector<std::string> &terms,
                                                 const std::map<std::string, std::string> &termTypes,
                                                 const GLMFitSummary &fit,
                                                 const std::string &a,
                                                 const std::string &b,
                                                 double confidenceLevel,
                                                 GLMInteractionReport &report)
{
    std::vector<std::string> aLevels = GLMFactorLevelsForVariable(model, a, fit);
    std::vector<std::string> bLevels = GLMFactorLevelsForVariable(model, b, fit);
    if (aLevels.empty() || bLevels.empty()) {
        report.message = "The interaction could not be interpreted because one categorical predictor has no fitted categories.";
        return;
    }
    report.interpretation = "Estimated marginal means for " + a +
        " at each category of " + b + ", followed by Holm-adjusted pairwise "
        "comparisons of " + a + " within each " + b +
        ". The reverse comparison direction is reported separately below.";
    std::vector<GLMPostEstimate> predictions;
    std::vector<std::vector<std::string>> predictionIdentities;
    for (const std::string &aLevel : aLevels) {
        for (const std::string &bLevel : bLevels) {
            predictions.push_back(GLMPredictionEstimate(model, terms, termTypes, fit, {}, {{a, aLevel}, {b, bLevel}},
                                                        a + " = " + aLevel + ", " + b + " = " + bLevel,
                                                        confidenceLevel));
            predictionIdentities.push_back({aLevel, bLevel});
        }
    }
    report.sections.push_back({"Estimated marginal means", predictions,
        rlispstat::core::GLMInteractionSectionInference::EstimateOnly});
    report.sections.back().identityHeaders = {a, b};
    report.sections.back().identityRows = std::move(predictionIdentities);

    std::vector<GLMPostEstimate> effectsA;
    std::vector<std::vector<std::string>> effectsAIdentities;
    for (const std::string &bLevel : bLevels) {
        for (size_t i = 0; i < aLevels.size(); ++i) {
            for (size_t j = i + 1; j < aLevels.size(); ++j) {
                std::vector<double> contrast;
                if (!GLMDifferenceContrast(model, terms, termTypes, fit, {}, {{a, aLevels[i]}, {b, bLevel}},
                                           {}, {{a, aLevels[j]}, {b, bLevel}}, contrast)) continue;
                const std::string comparison = aLevels[i] + " - " + aLevels[j];
                effectsA.push_back(GLMEstimateLinearFunction(
                    fit, contrast, comparison + " within " + b + " = " + bLevel,
                    confidenceLevel));
                effectsAIdentities.push_back({bLevel, comparison});
            }
        }
    }
    ApplyHolmAdjustedPValues(effectsA);
    report.sections.push_back({"Pairwise comparisons of " + a + " within " + b + " (Holm)", effectsA,
        rlispstat::core::GLMInteractionSectionInference::AdjustedComparison});
    report.sections.back().identityHeaders = {b, "Comparison"};
    report.sections.back().identityRows = std::move(effectsAIdentities);

    std::vector<GLMPostEstimate> effectsB;
    std::vector<std::vector<std::string>> effectsBIdentities;
    for (const std::string &aLevel : aLevels) {
        for (size_t i = 0; i < bLevels.size(); ++i) {
            for (size_t j = i + 1; j < bLevels.size(); ++j) {
                std::vector<double> contrast;
                if (!GLMDifferenceContrast(model, terms, termTypes, fit, {}, {{a, aLevel}, {b, bLevels[i]}},
                                           {}, {{a, aLevel}, {b, bLevels[j]}}, contrast)) continue;
                const std::string comparison = bLevels[i] + " - " + bLevels[j];
                effectsB.push_back(GLMEstimateLinearFunction(
                    fit, contrast, comparison + " within " + a + " = " + aLevel,
                    confidenceLevel));
                effectsBIdentities.push_back({aLevel, comparison});
            }
        }
    }
    ApplyHolmAdjustedPValues(effectsB);
    report.sections.push_back({"Pairwise comparisons of " + b + " within " + a + " (Holm)", effectsB,
        rlispstat::core::GLMInteractionSectionInference::AdjustedComparison});
    report.sections.back().identityHeaders = {a, "Comparison"};
    report.sections.back().identityRows = std::move(effectsBIdentities);
}

static void GLMAddContinuousByContinuousReport(PlotModel *model,
                                               const std::vector<std::string> &terms,
                                               const std::map<std::string, std::string> &termTypes,
                                               const GLMFitSummary &fit,
                                               const std::string &x,
                                               const std::string &z,
                                               double confidenceLevel,
                                               GLMInteractionReport &report)
{
    GLMNumericSummary xSummary = GLMNumericSummaryForVariable(model, x, fit);
    GLMNumericSummary zSummary = GLMNumericSummaryForVariable(model, z, fit);
    if (!xSummary.ok || !zSummary.ok) {
        report.message = "The interaction could not be interpreted because one component has no fitted values.";
        return;
    }
    std::vector<std::pair<std::string, double>> zValues;
    if (std::isfinite(zSummary.sd) && zSummary.sd > 0.0) {
        zValues.push_back(std::make_pair("M - SD", zSummary.mean - zSummary.sd));
        zValues.push_back(std::make_pair("M", zSummary.mean));
        zValues.push_back(std::make_pair("M + SD", zSummary.mean + zSummary.sd));
    } else {
        zValues.push_back(std::make_pair("M", zSummary.mean));
    }
    std::vector<GLMPostEstimate> slopesX;
    for (const auto &zValue : zValues) {
        std::vector<double> contrast;
        if (!GLMDifferenceContrast(model, terms, termTypes, fit,
                                   {{x, xSummary.mean + 1.0}, {z, zValue.second}}, {},
                                   {{x, xSummary.mean}, {z, zValue.second}}, {}, contrast)) continue;
        slopesX.push_back(GLMEstimateLinearFunction(fit, contrast,
                                                    "Slope of " + x + " when " + z + " = " + zValue.first,
                                                    confidenceLevel));
    }
    report.sections.push_back({"Conditional slopes of " + x, slopesX,
        rlispstat::core::GLMInteractionSectionInference::Test});

    std::vector<std::pair<std::string, double>> xValues;
    if (std::isfinite(xSummary.sd) && xSummary.sd > 0.0) {
        xValues.push_back(std::make_pair("M - SD", xSummary.mean - xSummary.sd));
        xValues.push_back(std::make_pair("M", xSummary.mean));
        xValues.push_back(std::make_pair("M + SD", xSummary.mean + xSummary.sd));
    } else {
        xValues.push_back(std::make_pair("M", xSummary.mean));
    }
    std::vector<GLMPostEstimate> slopesZ;
    for (const auto &xValue : xValues) {
        std::vector<double> contrast;
        if (!GLMDifferenceContrast(model, terms, termTypes, fit,
                                   {{x, xValue.second}, {z, zSummary.mean + 1.0}}, {},
                                   {{x, xValue.second}, {z, zSummary.mean}}, {}, contrast)) continue;
        slopesZ.push_back(GLMEstimateLinearFunction(fit, contrast,
                                                    "Slope of " + z + " when " + x + " = " + xValue.first,
                                                    confidenceLevel));
    }
    report.sections.push_back({"Conditional slopes of " + z, slopesZ,
        rlispstat::core::GLMInteractionSectionInference::Test});

    std::vector<GLMPostEstimate> predictions;
    for (const auto &xValue : xValues) {
        for (const auto &zValue : zValues) {
            predictions.push_back(GLMPredictionEstimate(model, terms, termTypes, fit,
                                                        {{x, xValue.second}, {z, zValue.second}}, {},
                                                        x + " = " + xValue.first + ", " + z + " = " + zValue.first,
                                                        confidenceLevel));
        }
    }
    report.sections.push_back({"Predicted means", predictions,
        rlispstat::core::GLMInteractionSectionInference::EstimateOnly});
}

static GLMInteractionReport BuildGLMInteractionReportPortableMac(
    const PlotModel *model,
    const std::string &term,
    const std::vector<std::string> &terms,
    const std::map<std::string, std::string> &termTypes,
    const GLMFitSummary &fit)
{
    if (!model) {
        return rlispstat::core::BuildGLMInteractionReport(
            PlotModel{}, nullptr, term, terms, termTypes, fit);
    }
    DataFrameModel dataframe;
    bool hasDataframe = false;
    std::set<std::string> centeredPredictors;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
        GroupModelState &state = EnsureGroupModelUnlocked(model->group, nullptr);
        centeredPredictors = state.centeredPredictors;
    }
    return rlispstat::core::BuildGLMInteractionReport(
        *model, hasDataframe ? &dataframe : nullptr, term, terms, termTypes, fit,
        0.95, centeredPredictors);
}

@interface GLMInteractionReportView : NSView
@property(nonatomic, copy) NSString *body;
- (instancetype)initWithBody:(NSString *)body frame:(NSRect)frame;
- (NSMenuItem *)explanationItemForSection:(NSString *)section statistic:(NSString *)statistic;
@end

@implementation GLMInteractionReportView

- (NSString *)snapshotTabDelimitedText
{
    return _body ?: @"";
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    (void)event;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Interaction Report"];
    std::string outputId;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (const GLMInteractionReportWindowEntry &entry :
             g_interactionReportWindows) {
            if (entry.window != [self window]) continue;
            outputId = "interaction-report:" + entry.link.sourceModelId +
                ":" + entry.link.term;
            break;
        }
    }
    std::vector<std::string> reportLines;
    std::istringstream input{std::string([[self snapshotTabDelimitedText] UTF8String])};
    for(std::string line;std::getline(input,line);) reportLines.push_back(line);
    rlispstat::core::GLMInteractionReport report;
    rlispstat::core::ParseGLMInteractionReportText(reportLines,report);
    if (!report.sections.empty()) {
        NSMenuItem *explainRoot = [[[NSMenuItem alloc]
            initWithTitle:@"Explain statistic" action:nil keyEquivalent:@""] autorelease];
        NSMenu *sections = [[[NSMenu alloc] initWithTitle:@"Explain statistic"] autorelease];
        for (const auto &section : report.sections) {
            NSMenuItem *sectionRoot = [[[NSMenuItem alloc]
                initWithTitle:ToNSString(section.first) action:nil keyEquivalent:@""] autorelease];
            NSMenu *statistics = [[[NSMenu alloc] initWithTitle:ToNSString(section.first)] autorelease];
            std::vector<std::string> headings = {section.estimateHeader, "SE"};
            if (section.showDegreesOfFreedom) headings.push_back("df");
            if (section.inference != rlispstat::core::GLMInteractionSectionInference::EstimateOnly) {
                headings.push_back("Statistic");
                headings.push_back(section.inference ==
                    rlispstat::core::GLMInteractionSectionInference::AdjustedComparison
                    ? "Adjusted p" : "p");
            }
            headings.push_back(section.lowerHeader);
            headings.push_back(section.upperHeader);
            for (const auto &heading : headings)
                [statistics addItem:[self explanationItemForSection:ToNSString(section.first)
                    statistic:ToNSString(heading)]];
            [sectionRoot setSubmenu:statistics];
            [sections addItem:sectionRoot];
        }
        [explainRoot setSubmenu:sections];
        [menu addItem:explainRoot];
    }
    const auto tables=rlispstat::core::InteractionScalePublicationTables(report);
    NSMenu *exports=[[[NSMenu alloc]initWithTitle:@"Export"]autorelease];
    NSMenuItem *root=[[[NSMenuItem alloc]initWithTitle:@"Export" action:nil keyEquivalent:@""]autorelease];
    AddStandardTableVisualExportItems(exports,self,[[self window]title] ?: @"Interaction Report",
        @"interaction-report",[self snapshotTabDelimitedText],nullptr,tables.empty()?nullptr:&tables);
    AddRCodeExportItems(exports,"output",outputId,true);
    AddSnapshotAlbumContextItems(menu);
    [root setSubmenu:exports];[menu addItem:root];
    return menu;
}

- (NSMenuItem *)explanationItemForSection:(NSString *)section statistic:(NSString *)statistic
{
    NSMenuItem *item = [[[NSMenuItem alloc] initWithTitle:statistic ?: @"Statistic"
        action:@selector(explainInteractionStatistic:) keyEquivalent:@""] autorelease];
    [item setTarget:self];
    [item setRepresentedObject:@{@"section":section ?: @"", @"statistic":statistic ?: @""}];
    return item;
}

- (void)explainInteractionStatistic:(id)sender
{
    NSDictionary *selection = [sender representedObject];
    if (![selection isKindOfClass:[NSDictionary class]]) return;
    NSString *sectionName = selection[@"section"];
    NSString *statistic = selection[@"statistic"];
    if (![sectionName isKindOfClass:[NSString class]] ||
        ![statistic isKindOfClass:[NSString class]]) return;
    rlispstat::core::GLMInteractionReport report;
    if (!rlispstat::core::ParseGLMInteractionReportText(
            SplitLines(std::string([[self snapshotTabDelimitedText] UTF8String])), report)) return;
    for (const auto &section : report.sections) {
        if (section.first != std::string([sectionName UTF8String])) continue;
        const auto context = rlispstat::core::InteractionReportStatisticContext(
            report, section, std::string([statistic UTF8String]));
        ShowWorkbenchMessageOnMain(
            [@"Explain statistic: " stringByAppendingString:statistic],
            ToNSString(rlispstat::core::ExplainModelStatistic(context)));
        return;
    }
}

