@implementation InteractionReportLineField
- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSMenu *reportMenu = [[self superview] menuForEvent:event];
    NSMenu *cellMenu = [self menu];
    if (!cellMenu || [cellMenu numberOfItems] == 0) return reportMenu;
    NSMenu *combined = [[[NSMenu alloc] initWithTitle:@"Interaction Report"] autorelease];
    for (NSMenuItem *item in [cellMenu itemArray])
        [combined addItem:[[item copy] autorelease]];
    if (reportMenu && [reportMenu numberOfItems] > 0) {
        [combined addItem:[NSMenuItem separatorItem]];
        for (NSMenuItem *item in [reportMenu itemArray])
            [combined addItem:[[item copy] autorelease]];
    }
    return combined;
}
