static void RegisterPairwiseDiagnostics(
    const rlispstat::core::GLMPairwiseComparisonResult &result,
    const GLMPairwiseComparisonPlotLink &link)
{
    auto reference=rlispstat::core::PairwiseDiagnosticsCodeReference(
        "pairwise:"+link.sourceModelId+":"+result.term,result);
    if(reference.outputId.empty())return;
    const auto* source=MacCommandDispatcher().applicationState().regressionSourceOutputCodeReference(
        link.sourceModelKind,link.sourceModelId);
    if(source)reference.provenance.scope=source->provenance.scope;
    if(link.sourceModelKind=="mean_comparison") {
        const std::size_t separator=link.sourceModelId.find('\x1f');
        if(separator!=std::string::npos) {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto meanSource=g_meanComparisonAcceptedStates.find(link.sourceModelId.substr(0,separator));
            if(meanSource!=g_meanComparisonAcceptedStates.end()) {
                reference.provenance.dataVersion=meanSource->second.provenance.dataVersion;
                reference.provenance.scope=meanSource->second.provenance.scope;
            }
        }
    }
    MacCommandDispatcher().applicationState().registerOutputCodeReference(reference);
}

@implementation GLMPairwiseResultsWindowController
{
    NSWindow *_window;
}

- (instancetype)initWithTerm:(const std::string &)term
                      result:(const rlispstat::core::GLMPairwiseComparisonResult &)result
                    plotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    self = [super init];
    if (!self) return nil;
    _term = term;
    _method = result.method;
    _adjustment = result.adjustment;
    _rows = result.comparisons;
    _scaleResult = result;
    _plotLink = plotLink;
    RegisterPairwiseDiagnostics(result,plotLink);
    const bool gamesHowell = result.adjustment == "Games-Howell";
    const bool binaryRegression = plotLink.binaryRegression;
    const CGFloat noteHeight = result.scaleReport.ok ? 130.0 : (gamesHowell ? 18.0 : 34.0);
    const CGFloat verticalChromeHeight = 84.0 + noteHeight;
    const CGFloat availableScreenHeight = NSHeight([[NSScreen mainScreen] visibleFrame]);
    const CGFloat maximumInitialContentHeight = std::max((CGFloat)320.0, availableScreenHeight - 120.0);
    const CGFloat horizontalScrollerHeight = result.scaleReport.ok ? 18.0 : 0.0;
    const CGFloat desiredTableHeight = std::max((CGFloat)96.0,
        (CGFloat)_rows.size() * 22.0 + 32.0 + horizontalScrollerHeight);
    const CGFloat tableHeight = std::min(desiredTableHeight,
        std::max((CGFloat)96.0, maximumInitialContentHeight - verticalChromeHeight));
    const CGFloat contentHeight = std::max((CGFloat)240.0,
        std::min(maximumInitialContentHeight, tableHeight + verticalChromeHeight));
    _window = [[NSWindow alloc] initWithContentRect:NSMakeRect(180, 180, 930, contentHeight)
                                           styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                                             backing:NSBackingStoreBuffered
                                               defer:NO];
    [_window setTitle:[NSString stringWithFormat:@"Pairwise comparisons — %@", SafeNSStringFromUTF8(term)]];
    [_window setReleasedWhenClosed:NO];
    [_window setContentMinSize:NSMakeSize(820.0, 240.0)];

    NSView *content = [_window contentView];
    [content setWantsLayer:YES];
    [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];
    const CGFloat horizontalMargin = 14.0;
    const CGFloat innerWidth = NSWidth([content bounds]) - 2.0 * horizontalMargin;
    const CGFloat titleY = contentHeight - 32.0;
    const CGFloat subtitleY = titleY - 20.0;
    const CGFloat topRuleY = subtitleY - 7.0;
    const CGFloat scrollTop = topRuleY - 5.0;
    const CGFloat noteY = 10.0;
    const CGFloat bottomRuleY = noteY + noteHeight + 6.0;
    const CGFloat scrollBottom = bottomRuleY + 5.0;

    NSTextField *title = [NSTextField labelWithString:[NSString stringWithFormat:@"Pairwise comparisons — %@", SafeNSStringFromUTF8(term)]];
    [title setFrame:NSMakeRect(horizontalMargin, titleY, innerWidth, 20.0)];
    [title setAutoresizingMask:NSViewWidthSizable | NSViewMinYMargin];
    [title setFont:[NSFont systemFontOfSize:16.0 weight:NSFontWeightSemibold]];
    [title setTextColor:[NSColor colorWithCalibratedWhite:0.18 alpha:1.0]];
    [content addSubview:title];
    NSString *subtitleText = binaryRegression
        ? SafeNSStringFromUTF8(result.method)
        : (plotLink.multipleImputation
            ? [NSString stringWithFormat:@"Estimated marginal means · %@ · %@ adjustment",
                SafeNSStringFromUTF8(result.method.empty() ? "Rubin-combined multiple imputation" : result.method),
                SafeNSStringFromUTF8(result.adjustment.empty() ? "Tukey" : result.adjustment)]
            : (gamesHowell ? @"Games–Howell pairwise comparisons"
                           : @"Estimated marginal means · Heteroscedastic GLS · Tukey adjustment"));
    _subtitleField = [NSTextField labelWithString:subtitleText];
    [_subtitleField setFrame:NSMakeRect(horizontalMargin, subtitleY, innerWidth, 16.0)];
    [_subtitleField setAutoresizingMask:NSViewWidthSizable | NSViewMinYMargin];
    [_subtitleField setFont:[NSFont systemFontOfSize:12.0 weight:NSFontWeightRegular]];
    [_subtitleField setTextColor:[NSColor colorWithCalibratedWhite:0.48 alpha:1.0]];
    [content addSubview:_subtitleField];

    NSBox *topRule = [[NSBox alloc] initWithFrame:NSMakeRect(horizontalMargin, topRuleY, innerWidth, 1.0)];
    [topRule setAutoresizingMask:NSViewWidthSizable | NSViewMinYMargin];
    [topRule setBoxType:NSBoxSeparator];
    [content addSubview:topRule];

    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(
        horizontalMargin, scrollBottom, innerWidth, std::max((CGFloat)44.0, scrollTop - scrollBottom))];
    [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [scroll setBorderType:NSNoBorder];
    [scroll setFocusRingType:NSFocusRingTypeNone];
    [scroll setHasVerticalScroller:desiredTableHeight > tableHeight];
    [scroll setHasHorizontalScroller:YES];
    [scroll setAutohidesScrollers:!result.scaleReport.ok];
    if (result.scaleReport.ok) [scroll setScrollerStyle:NSScrollerStyleLegacy];
    [scroll setDrawsBackground:NO];
    const CGFloat documentHeight = std::max((CGFloat)44.0, (CGFloat)_rows.size() * 22.0);
    _table = [[GLMPairwiseResultsTableView alloc] initWithFrame:NSMakeRect(0, 0, innerWidth, documentHeight)];
    [_table setDataSource:self];
    [_table setDelegate:self];
    [_table setPairwiseCopyDelegate:self];
    [_table setAllowsMultipleSelection:YES];
    [_table setAllowsEmptySelection:YES];
    [_table setAllowsColumnSelection:NO];
    [_table setSelectionHighlightStyle:NSTableViewSelectionHighlightStyleNone];
    [_table setFocusRingType:NSFocusRingTypeNone];
    [_table setUsesAlternatingRowBackgroundColors:NO];
    [_table setGridStyleMask:NSTableViewGridNone];
    [_table setBackgroundColor:WorkbenchSurfaceColor()];
    [_table setAutoresizingMask:NSViewHeightSizable];
    [_table setRowHeight:22.0];
    [_table setIntercellSpacing:NSMakeSize(3.0, 0.0)];
    [_table setHeaderView:[[GLMPairwiseResultsHeaderView alloc] initWithFrame:NSMakeRect(0,0,innerWidth,24)]];
    [_table setColumnAutoresizingStyle:NSTableViewNoColumnAutoresizing];
    struct ColumnSpec { const char *identifier; const char *title; CGFloat width; NSTextAlignment alignment; };
    const ColumnSpec columns[] = {
        {"comparison", "Comparison", 230.0, NSTextAlignmentLeft},
        {"estimate", "Estimate", 84.0, NSTextAlignmentRight},
        {"se", "SE", 68.0, NSTextAlignmentRight},
        {"df", "df", 64.0, NSTextAlignmentRight},
        {"t", "t", 62.0, NSTextAlignmentRight},
        {"p", "Adjusted p", 86.0, NSTextAlignmentRight},
        {"lower", "Lower 95%", 88.0, NSTextAlignmentRight},
        {"upper", "Upper 95%", 88.0, NSTextAlignmentRight}
    };
    for (const ColumnSpec &spec : columns) {
        NSTableColumn *column = [[NSTableColumn alloc] initWithIdentifier:ToNSString(spec.identifier)];
        NSString *columnTitle = ToNSString(spec.title);
        if (binaryRegression && spec.identifier == std::string("estimate")) {
            columnTitle = plotLink.binaryOddsRatio ? @"OR" : @"Probability difference";
        } else if (binaryRegression && spec.identifier == std::string("t")) {
            columnTitle = @"z";
        }
        [[column headerCell] setStringValue:columnTitle];
        const CGFloat effectiveWidth = binaryRegression && !plotLink.binaryOddsRatio && spec.identifier == std::string("estimate")
            ? 132.0 : spec.width;
        [column setWidth:effectiveWidth];
        [column setMinWidth:spec.identifier == std::string("comparison") ? 180.0 : effectiveWidth];
        [column setResizingMask:spec.identifier == std::string("comparison") ? NSTableColumnAutoresizingMask : NSTableColumnNoResizing];
        NSTextFieldCell *cell = [[NSTextFieldCell alloc] initTextCell:@""];
        [cell setAlignment:spec.alignment];
        [cell setFont:[NSFont systemFontOfSize:12.0 weight:NSFontWeightRegular]];
        [cell setLineBreakMode:NSLineBreakByTruncatingTail];
        [column setDataCell:cell];
        [_table addTableColumn:column];
    }
    [self configureScaleColumns];
    const CGFloat tableWidth = SizeNativeResultTableColumnsToContents(_table, innerWidth);
    [scroll setDocumentView:_table];
    [content addSubview:scroll];

    NSString *noteText = plotLink.multipleImputation
        ? [NSString stringWithFormat:
            @"The model was fitted across all imputations. Estimated marginal means and pairwise contrasts use %@; multiplicity uses %@ adjustment.",
            SafeNSStringFromUTF8(result.method.empty() ? "Rubin's rules" : result.method),
            SafeNSStringFromUTF8(result.adjustment.empty() ? "Tukey" : result.adjustment)]
        : (binaryRegression
        ? (plotLink.binaryOddsRatio
            ? @"The binary model was fitted in R with stats::glm. Tukey-adjusted odds-ratio comparisons were calculated with emmeans."
            : @"The binary-link model was fitted in R with stats::glm. Tukey-adjusted probability differences were calculated with emmeans; odds ratios are reported only for a logit link.")
        : (gamesHowell
            ? @"For a one-factor model, pairwise comparisons were calculated in R using the Games–Howell procedure."
            : @"The model was fitted in R using nlme::gls with a separate residual variance for each category of the selected categorical predictor. Estimated marginal means and Tukey-adjusted pairwise comparisons were obtained with emmeans."));
    _noteField = [NSTextField wrappingLabelWithString:noteText];
    NSBox *bottomRule = [[NSBox alloc] initWithFrame:NSMakeRect(horizontalMargin, bottomRuleY, innerWidth, 1.0)];
    [bottomRule setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
    [bottomRule setBoxType:NSBoxSeparator];
    [content addSubview:bottomRule];
    [_noteField setFrame:NSMakeRect(horizontalMargin, noteY, innerWidth, noteHeight)];
    [_noteField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
    [_noteField setFont:[NSFont systemFontOfSize:12.0 weight:NSFontWeightRegular]];
    [_noteField setTextColor:[NSColor colorWithCalibratedWhite:0.48 alpha:1.0]];
    [_noteField setLineBreakMode:NSLineBreakByWordWrapping];
    [_noteField setPreferredMaxLayoutWidth:innerWidth];
    [content addSubview:_noteField];
    if (_scaleResult.scaleReport.ok) [_noteField setStringValue:ToNSString(JoinStrings(_scaleResult.scaleReport.notes," "))];
    const CGFloat preferredWidth = std::min((CGFloat)1400.0,
        std::max((CGFloat)930.0, tableWidth + 2.0 * horizontalMargin + 16.0));
    FitResultTableWindowToContent(
        _window, NSMakeSize(preferredWidth, contentHeight), NSMakeSize(820.0, 240.0));
    [[scroll contentView] scrollToPoint:NSZeroPoint];
    [scroll reflectScrolledClipView:[scroll contentView]];
    [_table scrollRowToVisible:0];
    [_window makeFirstResponder:_table];
    return self;
}

- (NSWindow *)window
{
    return _window;
}

- (void)refreshPairwiseDerivedResult
{
    if (_plotLink.sourceModelId.empty()) return;
    RefreshPairwiseResultsControllerFromSource(self);
}

- (void)markDerivedPending:(const std::string &)message
{
    [_subtitleField setStringValue:ToNSString(message)];
}

- (GLMPairwiseComparisonPlotLink)derivedPlotLink
{
    return _plotLink;
}

- (void)applyDerivedResult:(const rlispstat::core::GLMPairwiseComparisonResult &)result
                  plotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    _method = result.method;
    _adjustment = result.adjustment;
    _rows = result.comparisons;
    _scaleResult = result;
    _plotLink = plotLink;
    RegisterPairwiseDiagnostics(result,plotLink);
    const bool gamesHowell = result.adjustment == "Games-Howell";
    NSString *subtitle = _plotLink.binaryRegression
        ? SafeNSStringFromUTF8(result.method)
        : (_plotLink.multipleImputation
            ? [NSString stringWithFormat:@"Estimated marginal means · %@ · %@ adjustment",
                SafeNSStringFromUTF8(result.method.empty() ? "Rubin-combined multiple imputation" : result.method),
                SafeNSStringFromUTF8(result.adjustment.empty() ? "Tukey" : result.adjustment)]
            : (gamesHowell ? @"Games–Howell pairwise comparisons"
                           : @"Estimated marginal means · Heteroscedastic GLS · Tukey adjustment"));
    [_subtitleField setStringValue:subtitle ?: @""];
    if (_plotLink.multipleImputation) {
        [_noteField setStringValue:[NSString stringWithFormat:
            @"The current fitted model was re-evaluated across all imputations. Estimates and uncertainty use %@; multiplicity uses %@ adjustment.",
            SafeNSStringFromUTF8(result.method.empty() ? "Rubin's rules" : result.method),
            SafeNSStringFromUTF8(result.adjustment.empty() ? "Tukey" : result.adjustment)]];
    }
    [self configureScaleColumns];
    [_table reloadData];
    NSView *document = [[_table enclosingScrollView] documentView];
    if (document) {
        NSRect frame = [document frame];
        frame.size.height = std::max((CGFloat)44.0, (CGFloat)_rows.size() * 22.0);
        [document setFrame:frame];
    }
    NSScrollView *scroll = [_table enclosingScrollView];
    SizeNativeResultTableColumnsToContents(_table, NSWidth([[scroll contentView] bounds]));
    [[scroll contentView] scrollToPoint:NSZeroPoint];
    [scroll reflectScrolledClipView:[scroll contentView]];
    [self refreshPairwiseResultsSelection];
}

- (void)applyDerivedFailure:(const std::string &)message
{
    _rows.clear();
    _plotLink.rowsByComparison.clear();
    [_subtitleField setStringValue:SafeNSStringFromUTF8(
        message.empty() ? "The source model no longer supports this derived comparison." : message)];
    [_noteField setStringValue:@"The previous values were removed because they belonged to an older model specification."];
    [self configureScaleColumns];
    [_table reloadData];
}

- (NSMenu *)pairwiseTableMenuForTableView:(NSTableView *)table event:(NSEvent *)event
{
    (void)event;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Pairwise comparisons"];
    const BOOL hasRows = [table numberOfSelectedRows] > 0;
    NSMenuItem *select = [[NSMenuItem alloc] initWithTitle:@"Select observations from both categories"
                                                     action:@selector(selectComparison:)
                                              keyEquivalent:@""];
    [select setTarget:self];
    [select setEnabled:hasRows];
    [menu addItem:select];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:@"Clear selection"
                                                    action:@selector(clearPairwiseSelection:)
                                             keyEquivalent:@""];
    [clear setTarget:self];
    [clear setEnabled:!_plotLink.group.empty() && SelectionCount(_plotLink.group) > 0];
    [menu addItem:clear];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *forestPlot = [[NSMenuItem alloc] initWithTitle:@"Show pairwise differences plot"
                                                       action:@selector(openPairwiseForestPlot:)
                                                keyEquivalent:@""];
    [forestPlot setTarget:self];
    [forestPlot setEnabled:!_rows.empty()];
    [menu addItem:forestPlot];
    NSMenuItem *boxplot = [[NSMenuItem alloc] initWithTitle:@"Show boxplot of observed data"
                                                     action:@selector(openPairwiseBoxplot:)
                                              keyEquivalent:@""];
    [boxplot setTarget:self];
    [boxplot setEnabled:!_plotLink.observations.empty()];
    [menu addItem:boxplot];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *explainRoot = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
        action:nil keyEquivalent:@""];
    NSMenu *explainMenu = [[NSMenu alloc] initWithTitle:[explainRoot title]];
    NSString *estimateStatistic = _plotLink.binaryRegression
        ? (_plotLink.binaryOddsRatio ? @"Odds ratio" : @"Probability difference")
        : @"Estimate";
    for (NSString *statistic in @[ estimateStatistic, @"SE", @"df", @"t / z",
                                    @"Adjusted p", @"Lower 95%", @"Upper 95%" ]) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:statistic
            action:@selector(explainPairwiseStatistic:) keyEquivalent:@""];
        [item setTarget:self]; [item setRepresentedObject:statistic];
        [explainMenu addItem:item];
    }
    [explainRoot setSubmenu:explainMenu];
    [menu addItem:explainRoot];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    auto scaleTable=rlispstat::core::PairwiseScalePublicationTable(_scaleResult);
    if (!_scaleResult.scaleReport.ok) {
        scaleTable.title = "Pairwise comparisons — " + _term;
        scaleTable.stubColumns = {0};
        for (NSTableColumn *column in [_table tableColumns]) {
            const std::string label = [[[column headerCell] stringValue] UTF8String];
            scaleTable.columns.push_back({label, label, "", -1, false});
        }
        for (NSInteger row = 0; row < [_table numberOfRows]; ++row) {
            std::vector<rlispstat::core::PublicationValue> cells;
            for (NSTableColumn *column in [_table tableColumns]) {
                rlispstat::core::PublicationValue value;
                value.kind = rlispstat::core::PublicationValueKind::Text;
                value.text = [[self tableView:_table objectValueForTableColumn:column row:row] UTF8String];
                cells.push_back(std::move(value));
            }
            scaleTable.rows.push_back(std::move(cells));
        }
        const NSString *note = [_noteField stringValue];
        if ([note length]) scaleTable.footnotes.push_back([note UTF8String]);
    }
    const std::vector<rlispstat::core::PublicationTableSpec> scaleTables={scaleTable};
    AddStandardTableVisualExportItems(exportMenu, _table,
        [@"Pairwise comparisons — " stringByAppendingString:ToNSString(_term)],
        @"pairwise-comparisons", [self pairwiseCopyTextForRows:[self allRows]],
        &scaleTable, &scaleTables);
    const std::string pairwiseOutputId = "pairwise:" +
        _plotLink.sourceModelId + ":" + _term;
    AddMissingInformationMenu(menu,pairwiseOutputId);
    AddRCodeExportItems(exportMenu, "output", pairwiseOutputId, true);
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copySelected = [[NSMenuItem alloc] initWithTitle:@"Copy selected rows"
                                                            action:@selector(copy:)
                                                     keyEquivalent:@""];
    [copySelected setTarget:_table];
    [copySelected setEnabled:hasRows];
    [exportMenu addItem:copySelected];
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:@"Export table as CSV…"
                                                  action:@selector(exportCSV:)
                                           keyEquivalent:@""];
    [csv setTarget:self];
    [exportMenu addItem:csv];
    AddSnapshotAlbumContextItems(menu);
    [exportRoot setSubmenu:exportMenu];
    [menu addItem:exportRoot];
    return menu;
}

- (void)explainPairwiseStatistic:(id)sender
{
    NSString *represented = [sender representedObject];
    if (![represented isKindOfClass:[NSString class]]) return;
    ShowAnalysisStatisticExplanationOnMain(
        std::string([represented UTF8String]), "pairwise comparisons", _method,
        _adjustment.empty() ? std::string() : _adjustment + " adjustment",
        _plotLink.multipleImputation, _plotLink.poolingMethod);
}

- (NSIndexSet *)allRows
{
    return _rows.empty() ? [NSIndexSet indexSet] :
        [NSIndexSet indexSetWithIndexesInRange:NSMakeRange(0, _rows.size())];
}

