- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    (void)tableView;
    return static_cast<NSInteger>(_rows.size());
}

- (id)tableView:(NSTableView *)tableView objectValueForTableColumn:(NSTableColumn *)column row:(NSInteger)row
{
    (void)tableView;
    if (row < 0 || static_cast<std::size_t>(row) >= _rows.size()) return @"";
    const rlispstat::core::LinearFunctionEstimate &value = _rows[static_cast<std::size_t>(row)];
    NSString *identifier = [column identifier];
    if ([identifier hasPrefix:@"scale_"]) {
        const NSInteger index=[[identifier substringFromIndex:6] integerValue];
        if(static_cast<std::size_t>(row)<_scaleResult.scaleRows.size() && index>=0 &&
            static_cast<std::size_t>(index)<_scaleResult.scaleRows[row].size())
            return ToNSString(_scaleResult.scaleRows[row][index]);
        return @"";
    }
    if ([identifier isEqualToString:@"comparison"]) {
        return [SafeNSStringFromUTF8(value.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "];
    }
    if ([identifier isEqualToString:@"estimate"]) return PairwiseNumberText(value.estimate, 4);
    if ([identifier isEqualToString:@"se"]) return PairwiseNumberText(value.stdError, 4);
    if ([identifier isEqualToString:@"df"]) return PairwiseNumberText(value.degreesOfFreedom, 1);
    if ([identifier isEqualToString:@"t"]) return PairwiseNumberText(value.statistic, 3);
    if ([identifier isEqualToString:@"p"]) return PairwisePValueText(value.adjustedPValue);
    if ([identifier isEqualToString:@"lower"]) return PairwiseNumberText(value.ciLower, 4);
    if ([identifier isEqualToString:@"upper"]) return PairwiseNumberText(value.ciUpper, 4);
    return @"";
}

- (NSString *)pairwiseCopyTextForRows:(NSIndexSet *)rows
{
    if (!rows || [rows count] == 0) return @"";
    NSMutableArray<NSString *> *lines = [NSMutableArray array];
    NSMutableArray<NSString *> *headers = [NSMutableArray array];
    for (NSTableColumn *column in [_table tableColumns]) {
        [headers addObject:[[column headerCell] stringValue]];
    }
    [lines addObject:[headers componentsJoinedByString:@"\t"]];
    NSUInteger index = [rows firstIndex];
    while (index != NSNotFound) {
        NSMutableArray<NSString *> *cells = [NSMutableArray array];
        for (NSTableColumn *column in [_table tableColumns]) {
            [cells addObject:[self tableView:_table objectValueForTableColumn:column row:(NSInteger)index]];
        }
        [lines addObject:[cells componentsJoinedByString:@"\t"]];
        index = [rows indexGreaterThanIndex:index];
    }
    return [lines componentsJoinedByString:@"\n"];
}

- (NSString *)pairwiseSnapshotText
{
    return [self pairwiseCopyTextForRows:[self allRows]];
}
- (void)configureScaleColumns
{
    if (!_scaleResult.scaleReport.ok || !_table) return;
    for (NSTableColumn *column in [[[_table tableColumns] copy] autorelease]) [_table removeTableColumn:column];
    const auto comparison = std::find(_scaleResult.scaleHeaders.begin(),
        _scaleResult.scaleHeaders.end(), "Comparison");
    const std::size_t comparisonIndex = comparison == _scaleResult.scaleHeaders.end()
        ? 0 : static_cast<std::size_t>(comparison - _scaleResult.scaleHeaders.begin());
    for(std::size_t i=0;i<_scaleResult.scaleHeaders.size();++i) {
        NSTableColumn *column=[[[NSTableColumn alloc]initWithIdentifier:
            ToNSString("scale_"+std::to_string(i))]autorelease];
        [[column headerCell]setStringValue:ToNSString(_scaleResult.scaleHeaders[i])];
        const BOOL isLabel = i <= comparisonIndex;
        [column setWidth:isLabel ? 220.0 : 140.0];
        [column setMinWidth:isLabel ? 180.0 : 90.0];
        NSTextFieldCell *cell = [[NSTextFieldCell alloc] initTextCell:@""];
        [cell setAlignment:isLabel ? NSTextAlignmentLeft : NSTextAlignmentRight];
        [cell setFont:[NSFont systemFontOfSize:12.0 weight:NSFontWeightRegular]];
        [cell setLineBreakMode:NSLineBreakByTruncatingTail];
        [column setDataCell:cell];
        [_table addTableColumn:column];
    }
    [_subtitleField setStringValue:@"Estimated marginal means: response scale · Statistical contrasts: link scale (identity: response)"];
    [_noteField setStringValue:ToNSString(JoinStrings(_scaleResult.scaleReport.notes," "))];
}

@end

static void DrawPairwisePDFText(const NSString *text, NSRect rect, NSDictionary *attributes)
{
    if (!text || NSIsEmptyRect(rect)) return;
    [text drawInRect:rect withAttributes:attributes];
}

static std::string PairwisePDFFileStem(const GLMPairwiseComparisonPlotLink &link, bool apa)
{
    std::string stem = "pairwise_" + link.response + "_by_" + link.factor + (apa ? "_APA7" : "_table");
    for (char &ch : stem) if (!std::isalnum(static_cast<unsigned char>(ch)) && ch != '_' && ch != '-') ch = '_';
    return stem;
}

static void ExportGLMPairwiseComparisonTablePDF(
    const std::vector<rlispstat::core::LinearFunctionEstimate> &rows,
    const GLMPairwiseComparisonPlotLink &link,
    bool apaStyle)
{
    NSString *tableNumber = @"1";
    NSString *title = SafeNSStringFromUTF8(apaStyle
        ? ("Pairwise Comparisons of " + link.response + " Across " + link.factor + " Groups")
        : ("Pairwise comparisons of " + link.response + " by " + link.factor));
    if (apaStyle) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"APA 7 table details"];
        [alert setInformativeText:@"Enter the table number and title to print above the APA 7 table."];
        NSTextField *numberField = [NSTextField textFieldWithString:tableNumber];
        NSTextField *titleField = [NSTextField textFieldWithString:title];
        [numberField setPlaceholderString:@"1"];
        [titleField setPlaceholderString:@"Pairwise comparisons"];
        NSStackView *accessory = [[NSStackView alloc] initWithFrame:NSMakeRect(0, 0, 420, 104)];
        [accessory setOrientation:NSUserInterfaceLayoutOrientationVertical];
        [accessory setAlignment:NSLayoutAttributeLeading];
        [accessory setSpacing:5.0];
        [accessory addArrangedSubview:[NSTextField labelWithString:@"Table number"]];
        [accessory addArrangedSubview:numberField];
        [accessory addArrangedSubview:[NSTextField labelWithString:@"Table title"]];
        [accessory addArrangedSubview:titleField];
        [[numberField widthAnchor] constraintEqualToConstant:420.0].active = YES;
        [[titleField widthAnchor] constraintEqualToConstant:420.0].active = YES;
        [numberField setNextKeyView:titleField];
        [alert setAccessoryView:accessory];
        [alert addButtonWithTitle:@"Continue"];
        [alert addButtonWithTitle:@"Cancel"];
        [[alert window] setInitialFirstResponder:numberField];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
        if ([[numberField stringValue] length] > 0) tableNumber = [numberField stringValue];
        if ([[titleField stringValue] length] > 0) title = [titleField stringValue];
    }
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, @"pdf");
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"%@.pdf", SafeNSStringFromUTF8(PairwisePDFFileStem(link, apaStyle))]];
    if ([panel runModal] != NSModalResponseOK) return;

    const CGFloat pageWidth = apaStyle ? 595.0 : 842.0;
    const CGFloat pageHeight = apaStyle ? 842.0 : 595.0;
    CGRect mediaBox = CGRectMake(0.0, 0.0, pageWidth, pageHeight);
    CGContextRef context = CGPDFContextCreateWithURL((__bridge CFURLRef)[panel URL], &mediaBox, nullptr);
    if (!context) return;
    const CGFloat margin = 42.0;
    NSString *estimateHeader = link.binaryRegression
        ? (link.binaryOddsRatio ? @"OR" : @"Probability difference")
        : @"Estimate";
    NSString *statisticHeader = link.binaryRegression ? @"z" : @"t";
    const NSArray<NSString *> *headers = apaStyle
        ? @[ @"Comparison", estimateHeader, @"SE", @"df", statisticHeader, @"p", @"95% CI" ]
        : @[ @"Comparison", estimateHeader, @"SE", @"df", statisticHeader, @"Adjusted p", @"Lower 95%", @"Upper 95%" ];
    const std::vector<CGFloat> widths = apaStyle
        ? std::vector<CGFloat>{145, 62, 48, 45, 45, 50, 108}
        : std::vector<CGFloat>{184, 76, 60, 54, 54, 78, 82, 82};
    NSDictionary *titleAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:(apaStyle ? 13.0 : 16.0) weight:NSFontWeightSemibold], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSDictionary *bodyAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:10.0], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSDictionary *headerAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:10.0 weight:NSFontWeightSemibold], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSDictionary *noteAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:9.5], NSForegroundColorAttributeName: [NSColor blackColor] };
    NSInteger page = 0;
    CGFloat y = 0.0;
    auto endPage = [&]() {
        if (page <= 0) return;
        DrawPairwisePDFText([NSString stringWithFormat:@"Page %ld", (long)page],
                            NSMakeRect(pageWidth - margin - 55.0, pageHeight - margin + 7.0, 55.0, 12.0), noteAttrs);
        [NSGraphicsContext setCurrentContext:nil];
        CGContextRestoreGState(context);
        CGContextEndPage(context);
    };
    auto beginPage = [&](bool firstPage) {
        if (page > 0) {
            endPage();
        }
        ++page;
        CGContextBeginPage(context, nullptr);
        CGContextSaveGState(context);
        CGContextTranslateCTM(context, 0.0, pageHeight);
        CGContextScaleCTM(context, 1.0, -1.0);
        [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:context flipped:YES]];
        y = margin;
        if (apaStyle && firstPage) {
            DrawPairwisePDFText([NSString stringWithFormat:@"Table %@", tableNumber], NSMakeRect(margin, y, pageWidth - 2 * margin, 18), headerAttrs);
            y += 20.0;
        }
        DrawPairwisePDFText(firstPage ? title : [NSString stringWithFormat:@"%@ (continued)", title], NSMakeRect(margin, y, pageWidth - 2 * margin, 22), titleAttrs);
        y += 28.0;
        if (firstPage && !apaStyle) {
            NSString *method = link.binaryRegression ? SafeNSStringFromUTF8(link.method) :
                (link.gamesHowell ? @"Method: Games–Howell pairwise comparisons" : @"Model: Heteroscedastic generalized least squares; pairwise comparisons of estimated marginal means (Tukey adjustment)");
            DrawPairwisePDFText(method, NSMakeRect(margin, y, pageWidth - 2 * margin, 15), bodyAttrs); y += 16.0;
            DrawPairwisePDFText([NSString stringWithFormat:@"Confidence level: %.0f%%    Cases analysed: %d    Cases excluded: %d", link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded], NSMakeRect(margin, y, pageWidth - 2 * margin, 15), bodyAttrs); y += 22.0;
        }
        NSBezierPath *topRule = [NSBezierPath bezierPath]; [topRule moveToPoint:NSMakePoint(margin, y)]; [topRule lineToPoint:NSMakePoint(pageWidth - margin, y)]; [topRule setLineWidth:1.0]; [[NSColor blackColor] setStroke]; [topRule stroke];
        y += 4.0;
        CGFloat x = margin;
        for (NSUInteger index = 0; index < [headers count]; ++index) {
            NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init]; [style setAlignment:index == 0 ? NSTextAlignmentLeft : NSTextAlignmentRight];
            NSMutableDictionary *attrs = [headerAttrs mutableCopy]; attrs[NSParagraphStyleAttributeName] = style;
            DrawPairwisePDFText(headers[index], NSMakeRect(x, y, widths[index] - 3.0, 16.0), attrs); x += widths[index];
        }
        y += 18.0;
        NSBezierPath *headerRule = [NSBezierPath bezierPath]; [headerRule moveToPoint:NSMakePoint(margin, y)]; [headerRule lineToPoint:NSMakePoint(pageWidth - margin, y)]; [headerRule setLineWidth:0.8]; [headerRule stroke]; y += 4.0;
    };
    beginPage(true);
    for (const rlispstat::core::LinearFunctionEstimate &row : rows) {
        NSString *comparison = [SafeNSStringFromUTF8(row.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "];
        const CGFloat comparisonHeight = std::max((CGFloat)18.0, [comparison boundingRectWithSize:NSMakeSize(widths[0] - 3.0, 100.0) options:NSStringDrawingUsesLineFragmentOrigin attributes:bodyAttrs].size.height + 3.0);
        const CGFloat rowHeight = std::max((CGFloat)20.0, comparisonHeight);
        if (y + rowHeight > pageHeight - margin - 70.0) beginPage(false);
        NSArray<NSString *> *cells = apaStyle
            ? @[ comparison, PairwiseNumberText(row.estimate, 4), PairwiseNumberText(row.stdError, 4), PairwiseNumberText(row.degreesOfFreedom, 1), PairwiseNumberText(row.statistic, 3), PairwisePValueText(row.adjustedPValue), [NSString stringWithFormat:@"[%@, %@]", PairwiseNumberText(row.ciLower, 4), PairwiseNumberText(row.ciUpper, 4)] ]
            : @[ comparison, PairwiseNumberText(row.estimate, 4), PairwiseNumberText(row.stdError, 4), PairwiseNumberText(row.degreesOfFreedom, 1), PairwiseNumberText(row.statistic, 3), PairwisePValueText(row.adjustedPValue), PairwiseNumberText(row.ciLower, 4), PairwiseNumberText(row.ciUpper, 4) ];
        CGFloat x = margin;
        for (NSUInteger index = 0; index < [cells count]; ++index) {
            NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init]; [style setAlignment:index == 0 ? NSTextAlignmentLeft : NSTextAlignmentRight];
            NSMutableDictionary *attrs = [bodyAttrs mutableCopy]; attrs[NSParagraphStyleAttributeName] = style;
            DrawPairwisePDFText(cells[index], NSMakeRect(x, y, widths[index] - 3.0, rowHeight), attrs); x += widths[index];
        }
        y += rowHeight;
    }
    const NSString *note = link.binaryRegression
        ? [NSString stringWithFormat:@"Note. The binary model and Tukey-adjusted comparisons were calculated in R using stats::glm and emmeans. %@ The confidence level was %.0f%%. The analysis included %d observations%@.", link.binaryOddsRatio ? @"Odds ratios are reported." : @"Probability differences are reported; odds ratios are available only for a logit link.", link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded > 0 ? [NSString stringWithFormat:@"; %d observations were excluded", link.casesExcluded] : @""]
        : (link.gamesHowell
            ? [NSString stringWithFormat:@"Note. Pairwise comparisons were calculated using the Games–Howell procedure. The confidence level was %.0f%%. Adjusted p values are reported. The analysis included %d observations%@.", link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded > 0 ? [NSString stringWithFormat:@"; %d observations were excluded", link.casesExcluded] : @""]
            : [NSString stringWithFormat:@"Note. Estimated marginal means were obtained from a heteroscedastic generalized least-squares model with separate residual variances for the categories of %@. Pairwise p values were adjusted using the Tukey method. The confidence level was %.0f%%. The analysis included %d observations%@.", SafeNSStringFromUTF8(link.factor), link.confidenceLevel * 100.0, link.casesAnalysed, link.casesExcluded > 0 ? [NSString stringWithFormat:@"; %d observations were excluded", link.casesExcluded] : @""]);
    const CGFloat noteHeight = [note boundingRectWithSize:NSMakeSize(pageWidth - 2 * margin, 100.0) options:NSStringDrawingUsesLineFragmentOrigin attributes:noteAttrs].size.height + 4.0;
    if (y + noteHeight + 20.0 > pageHeight - margin) beginPage(false);
    NSBezierPath *bottomRule = [NSBezierPath bezierPath]; [bottomRule moveToPoint:NSMakePoint(margin, y)]; [bottomRule lineToPoint:NSMakePoint(pageWidth - margin, y)]; [bottomRule setLineWidth:1.0]; [[NSColor blackColor] setStroke]; [bottomRule stroke]; y += 8.0;
    DrawPairwisePDFText(note, NSMakeRect(margin, y, pageWidth - 2 * margin, noteHeight), noteAttrs);
    endPage();
    CGContextRelease(context);
}

static void ExportBinaryRegressionAsDisplayedPDF(const GeneralizedGLMState &state,
                                                 bool showModelDetails)
{
    NSString *title = [NSString stringWithFormat:@"Binary Model Predicting %@", SafeNSStringFromUTF8(state.response)];
    BOOL landscape = YES;
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, @"pdf");
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"binary_regression_%@.pdf",
                                    SafeNSStringFromUTF8(state.response)]];
    if ([panel runModal] != NSModalResponseOK) return;

    const CGFloat pageWidth = landscape ? 842.0 : 595.0;
    const CGFloat pageHeight = landscape ? 595.0 : 842.0;
    CGRect mediaBox = CGRectMake(0, 0, pageWidth, pageHeight);
    CGContextRef context = CGPDFContextCreateWithURL((__bridge CFURLRef)[panel URL], &mediaBox, nullptr);
    if (!context) return;
    const CGFloat margin = 42.0;
    NSDictionary *titleAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:14 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *sectionAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:10.5 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *bodyAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:9.2], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *noteAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:8.8], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSInteger page = 0;
    CGFloat y = margin;
    auto endPage = [&]() {
        if (page == 0) return;
        DrawPairwisePDFText([NSString stringWithFormat:@"Page %ld", (long)page], NSMakeRect(pageWidth - margin - 50, pageHeight - margin + 6, 50, 12), noteAttrs);
        [NSGraphicsContext setCurrentContext:nil];
        CGContextRestoreGState(context);
        CGContextEndPage(context);
    };
    auto beginPage = [&](NSString *continued) {
        if (page > 0) endPage();
        ++page;
        CGContextBeginPage(context, nullptr);
        CGContextSaveGState(context);
        CGContextTranslateCTM(context, 0, pageHeight);
        CGContextScaleCTM(context, 1, -1);
        [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:context flipped:YES]];
        y = margin;
        DrawPairwisePDFText(continued ?: title, NSMakeRect(margin, y, pageWidth - 2 * margin, 22), titleAttrs);
        y += 28;
        NSString *coding = [NSString stringWithFormat:@"Response: %@    Event: %@ (%d)    Reference: %@ (%d)    Link: %@    N = %d",
            SafeNSStringFromUTF8(state.response), SafeNSStringFromUTF8(state.responseCoding.eventLabel), state.responseCoding.eventCount,
            SafeNSStringFromUTF8(state.responseCoding.referenceLabel), state.responseCoding.referenceCount,
            SafeNSStringFromUTF8(state.link), state.n];
        DrawPairwisePDFText(coding, NSMakeRect(margin, y, pageWidth - 2 * margin, 16), bodyAttrs); y += 19;
    };
    auto rule = [&]() {
        NSBezierPath *path = [NSBezierPath bezierPath];
        [path moveToPoint:NSMakePoint(margin, y)]; [path lineToPoint:NSMakePoint(pageWidth - margin, y)];
        [path setLineWidth:0.8]; [[NSColor blackColor] setStroke]; [path stroke]; y += 4;
    };
    beginPage(nil);
    DrawPairwisePDFText(@"Global fit", NSMakeRect(margin, y, 120, 16), sectionAttrs); y += 18;
    NSString *fit = [NSString stringWithFormat:@"LR χ²(%d) = %@, p = %@; Nagelkerke pseudo-R² = %@",
        state.dfModel, SafeNSStringFromUTF8(FormatModelNumberOrDash(state.globalLR)), PairwisePValueText(state.globalP),
        SafeNSStringFromUTF8(FormatModelNumberOrDash(state.nagelkerkeR2))];
    DrawPairwisePDFText(fit, NSMakeRect(margin, y, pageWidth - 2 * margin, 18), bodyAttrs); y += 24;

    if (showModelDetails) {
        DrawPairwisePDFText(@"Model details", NSMakeRect(margin, y, 180, 16), sectionAttrs); y += 18;
        NSArray<NSString *> *details = @[
            [NSString stringWithFormat:@"Log likelihood: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.logLik))],
            [NSString stringWithFormat:@"Residual deviance: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.residualDeviance))],
            [NSString stringWithFormat:@"Null deviance: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.nullDeviance))],
            [NSString stringWithFormat:@"df residual: %d", state.dfResidual],
            [NSString stringWithFormat:@"AIC: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.aic))],
            [NSString stringWithFormat:@"BIC: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.bic))],
            [NSString stringWithFormat:@"McFadden R²: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.mcfaddenR2))],
            [NSString stringWithFormat:@"Cox–Snell R²: %@", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.coxSnellR2))],
            [NSString stringWithFormat:@"Apparent AUC: %@¹", SafeNSStringFromUTF8(FormatModelNumberOrDash(state.auc))],
            [NSString stringWithFormat:@"Converged: %@", state.converged ? @"yes" : @"no"],
            [NSString stringWithFormat:@"Iterations: %d", state.iterations],
            [NSString stringWithFormat:@"Rank: %d/%d", state.rank, state.parameterCount]
        ];
        const CGFloat detailWidth = (pageWidth - 2 * margin) / 4.0;
        for (NSUInteger index = 0; index < details.count; ++index) {
            const NSUInteger row = index / 4;
            const NSUInteger column = index % 4;
            DrawPairwisePDFText(details[index], NSMakeRect(margin + column * detailWidth,
                y + row * 17.0, detailWidth - 5.0, 16), bodyAttrs);
        }
        y += 54.0;
        DrawPairwisePDFText(@"¹ Calculated on the observations used to fit the model; not out-of-sample validation.",
            NSMakeRect(margin, y, pageWidth - 2 * margin, 16), noteAttrs);
        y += 22.0;
    }

    DrawPairwisePDFText(@"Terms and coefficients", NSMakeRect(margin, y, 180, 16), sectionAttrs); y += 18; rule();
    const bool exponentiatedEffect =
        rlispstat::core::GeneralizedModelHasExponentiatedEffect(state);
    NSString *effectHeader = exponentiatedEffect
        ? [NSString stringWithFormat:@"%@ / 95%% CI",
            SafeNSStringFromUTF8(rlispstat::core::GeneralizedExponentiatedEffectLabel(state))]
        : @"95% CI for B";
    NSArray<NSString *> *coefHeaders = @[@"Variable / category", @"B", @"SE", @"z", @"p",
        effectHeader];
    const CGFloat available = pageWidth - 2 * margin;
    NSArray<NSNumber *> *coefWidths = @[@0.32, @0.09, @0.09, @0.08, @0.08, @0.34];
    CGFloat x = margin;
    for (NSUInteger index = 0; index < coefHeaders.count; ++index) {
        CGFloat width = available * [coefWidths[index] doubleValue];
        DrawPairwisePDFText(coefHeaders[index], NSMakeRect(x, y, width - 2, 15), sectionAttrs); x += width;
    }
    y += 17; rule();
    for (const auto &row : state.rows) {
        if (y + 18 > pageHeight - margin - 55) {
            beginPage([title stringByAppendingString:@" (continued)"]);
            DrawPairwisePDFText(@"Terms and coefficients (continued)", NSMakeRect(margin, y, 240, 16), sectionAttrs); y += 18; rule();
            x = margin;
            for (NSUInteger index = 0; index < coefHeaders.count; ++index) {
                CGFloat width = available * [coefWidths[index] doubleValue];
                DrawPairwisePDFText(coefHeaders[index], NSMakeRect(x, y, width - 2, 15), sectionAttrs); x += width;
            }
            y += 17; rule();
        }
        if (row.rowType == "section_header") {
            const std::string displayLabel = row.displayLabel.empty()
                ? row.term : row.displayLabel;
            DrawPairwisePDFText(SafeNSStringFromUTF8(displayLabel),
                NSMakeRect(margin, y, available, 16), sectionAttrs);
            y += 17;
            continue;
        }
        const bool parent = row.rowType == "factor_parent" || row.rowType == "term_parent";
        const bool structural = parent || row.rowType == "reference";
        const rlispstat::core::GlobalTermTestRow *test =
            rlispstat::core::GeneralizedGlobalTermTestForPresentationRow(state, row);
        NSString *dash = @"—";
        std::string displayLabel = row.displayLabel.empty() ? row.term : row.displayLabel;
        if (row.rowType == "reference" && displayLabel.find("reference") == std::string::npos) displayLabel += " (reference)";
        NSMutableArray<NSString *> *cells = [NSMutableArray arrayWithObject:SafeNSStringFromUTF8(displayLabel)];
        [cells addObject:parent ? @"" : structural ? dash : SafeNSStringFromUTF8(FormatModelNumberOrDash(row.estimate))];
        [cells addObject:parent ? @"" : structural ? dash : SafeNSStringFromUTF8(FormatModelNumberOrDash(row.stdError))];
        [cells addObject:parent
            ? (test ? SafeNSStringFromUTF8(FormatDoubleOrDash(test->statistic, 3)) : dash)
            : (row.rowType == "reference" ? dash : SafeNSStringFromUTF8(FormatModelNumberOrDash(row.statistic)))];
        [cells addObject:parent
            ? (test ? PairwisePValueText(test->pValue) : dash)
            : (row.rowType == "reference" ? dash : PairwisePValueText(row.pValue))];
        NSString *effect = parent ? @"" : dash;
        if (!structural) effect = exponentiatedEffect
            ? [NSString stringWithFormat:@"%@ [%@, %@]", SafeNSStringFromUTF8(FormatModelNumberOrDash(row.exponentiatedEstimate)), SafeNSStringFromUTF8(FormatModelNumberOrDash(row.exponentiatedLower)), SafeNSStringFromUTF8(FormatModelNumberOrDash(row.exponentiatedUpper))]
            : [NSString stringWithFormat:@"[%@, %@]", SafeNSStringFromUTF8(FormatModelNumberOrDash(row.ciLower)), SafeNSStringFromUTF8(FormatModelNumberOrDash(row.ciUpper))];
        [cells addObject:effect];
        x = margin;
        for (NSUInteger index = 0; index < cells.count; ++index) {
            CGFloat width = available * [coefWidths[index] doubleValue];
            DrawPairwisePDFText(cells[index], NSMakeRect(x, y, width - 2, 16), bodyAttrs); x += width;
        }
        y += 17;
    }
    y += 3; rule();
    NSMutableString *note = [NSMutableString stringWithString:(exponentiatedEffect
        ? [NSString stringWithFormat:@"Note. The model used a binomial distribution with a %@ link. The event modelled was %@; %@ was the reference outcome. Exponentiated coefficients are %@s. Confidence intervals are 95%% Wald intervals. Calculations were performed in R using stats::glm.", SafeNSStringFromUTF8(rlispstat::core::BinaryLinkLabel(state.binaryLink)), SafeNSStringFromUTF8(state.responseCoding.eventLabel), SafeNSStringFromUTF8(state.responseCoding.referenceLabel), SafeNSStringFromUTF8(rlispstat::core::GeneralizedExponentiatedEffectLabel(state))]
        : [NSString stringWithFormat:@"Note. The model used a binomial distribution with a %@ link. The event modelled was %@; %@ was the reference outcome. Coefficients and confidence intervals are reported on the link scale. Confidence intervals are 95%% Wald intervals. Calculations were performed in R using stats::glm.", SafeNSStringFromUTF8(rlispstat::core::BinaryLinkLabel(state.binaryLink)), SafeNSStringFromUTF8(state.responseCoding.eventLabel), SafeNSStringFromUTF8(state.responseCoding.referenceLabel)])];
    const std::string methodNote =
        rlispstat::core::GeneralizedGlobalTermTestMethodNote(state);
    if (!methodNote.empty()) {
        [note appendFormat:@" %@", SafeNSStringFromUTF8(methodNote)];
    }
    const std::string hierarchyNote =
        rlispstat::core::GeneralizedGlobalTermTestHierarchyNote(state);
    if (!hierarchyNote.empty()) {
        [note appendFormat:@" %@", SafeNSStringFromUTF8(hierarchyNote)];
    }
    CGFloat noteHeight = [note boundingRectWithSize:NSMakeSize(pageWidth - 2 * margin, 140) options:NSStringDrawingUsesLineFragmentOrigin attributes:noteAttrs].size.height + 4;
    if (y + noteHeight > pageHeight - margin) beginPage([title stringByAppendingString:@" (continued)"]);
    DrawPairwisePDFText(note, NSMakeRect(margin, y, pageWidth - 2 * margin, noteHeight), noteAttrs); y += noteHeight + 6;
    for (const std::string &warning : state.warnings) {
        DrawPairwisePDFText(SafeNSStringFromUTF8("Warning. " + warning), NSMakeRect(margin, y, pageWidth - 2 * margin, 18), noteAttrs); y += 18;
    }
    endPage();
    CGPDFContextClose(context);
    CGContextRelease(context);
}

static void ExportBinaryRegressionPDF(const GeneralizedGLMState &state, bool apaStyle,
                                      bool showModelDetails = false)
{
    if (apaStyle) rlispstat::platform::macos::ShowBinaryRegressionAPAExportPanel(state);
    else ExportBinaryRegressionAsDisplayedPDF(state, showModelDetails);
}

static void ExportBinaryComparisonPDFNative(const GeneralizedComparisonState &state, bool apaStyle)
{
    NSString *tableNumber = @"1";
    NSString *title = [NSString stringWithFormat:@"Comparison of Binary Models Predicting %@", SafeNSStringFromUTF8(state.response)];
    if (apaStyle) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"APA 7 table details"];
        [alert setInformativeText:@"Enter the table number and title."];
        NSTextField *numberField = [NSTextField textFieldWithString:tableNumber];
        NSTextField *titleField = [NSTextField textFieldWithString:title];
        NSStackView *accessory = [[NSStackView alloc] initWithFrame:NSMakeRect(0, 0, 420, 104)];
        [accessory setOrientation:NSUserInterfaceLayoutOrientationVertical]; [accessory setSpacing:5];
        for (NSView *view in @[[NSTextField labelWithString:@"Table number"], numberField,
                               [NSTextField labelWithString:@"Table title"], titleField]) [accessory addArrangedSubview:view];
        [[numberField widthAnchor] constraintEqualToConstant:420].active = YES;
        [[titleField widthAnchor] constraintEqualToConstant:420].active = YES;
        [alert setAccessoryView:accessory]; [alert addButtonWithTitle:@"Continue"]; [alert addButtonWithTitle:@"Cancel"];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
        if ([[numberField stringValue] length]) tableNumber = [numberField stringValue];
        if ([[titleField stringValue] length]) title = [titleField stringValue];
    }
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, @"pdf");
    [panel setNameFieldStringValue:apaStyle ? @"binary_model_comparison_APA7.pdf" : @"binary_model_comparison.pdf"];
    if ([panel runModal] != NSModalResponseOK) return;
    const CGFloat pageWidth = 842, pageHeight = 595, margin = 38;
    CGRect mediaBox = CGRectMake(0, 0, pageWidth, pageHeight);
    CGContextRef context = CGPDFContextCreateWithURL((__bridge CFURLRef)[panel URL], &mediaBox, nullptr);
    if (!context) return;
    CGContextBeginPage(context, nullptr); CGContextSaveGState(context);
    CGContextTranslateCTM(context, 0, pageHeight); CGContextScaleCTM(context, 1, -1);
    [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:context flipped:YES]];
    NSDictionary *titleAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:14 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *headerAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:9 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor blackColor]};
    NSDictionary *bodyAttrs = @{NSFontAttributeName:[NSFont systemFontOfSize:8.8], NSForegroundColorAttributeName:[NSColor blackColor]};
    CGFloat y = margin;
    if (apaStyle) { DrawPairwisePDFText([NSString stringWithFormat:@"Table %@", tableNumber], NSMakeRect(margin, y, 200, 16), headerAttrs); y += 19; }
    DrawPairwisePDFText(title, NSMakeRect(margin, y, pageWidth - 2 * margin, 22), titleAttrs); y += 28;
    NSString *coding = [NSString stringWithFormat:@"Response: %@    Event: %@    Reference: %@    Link: %@    Common rows: %lu",
        SafeNSStringFromUTF8(state.response), SafeNSStringFromUTF8(state.responseCoding.eventLabel),
        SafeNSStringFromUTF8(state.responseCoding.referenceLabel), SafeNSStringFromUTF8(state.link), (unsigned long)state.commonRows.size()];
    DrawPairwisePDFText(coding, NSMakeRect(margin, y, pageWidth - 2 * margin, 16), bodyAttrs); y += 22;
    NSArray<NSString *> *headers = @[@"Reduced model", @"Full model", @"LR χ²", @"df", @"p", @"ΔDeviance"];
    std::vector<CGFloat> widths = {170, 170, 100, 55, 90, 110};
    NSBezierPath *path = [NSBezierPath bezierPath]; [path moveToPoint:NSMakePoint(margin, y)]; [path lineToPoint:NSMakePoint(pageWidth-margin, y)]; [[NSColor blackColor] setStroke]; [path stroke]; y += 4;
    CGFloat x = margin;
    for (NSUInteger i = 0; i < headers.count; ++i) { DrawPairwisePDFText(headers[i], NSMakeRect(x, y, widths[i]-2, 16), headerAttrs); x += widths[i]; }
    y += 18; path = [NSBezierPath bezierPath]; [path moveToPoint:NSMakePoint(margin, y)]; [path lineToPoint:NSMakePoint(pageWidth-margin, y)]; [path stroke]; y += 4;
    for (std::size_t index = 1; index < state.models.size(); ++index) {
        const auto &reduced = state.models[index - 1];
        const auto &full = state.models[index];
        NSArray<NSString *> *cells = @[SafeNSStringFromUTF8(reduced.label), SafeNSStringFromUTF8(full.label),
            full.comparisonOk ? PairwiseNumberText(full.comparisonStatistic, 3) : @"—",
            full.comparisonOk ? [NSString stringWithFormat:@"%d", full.comparisonDf] : @"—",
            full.comparisonOk ? PairwisePValueText(full.comparisonP) : @"—",
            full.comparisonOk ? PairwiseNumberText(full.comparisonDelta, 3) : @"—"];
        x=margin; for(NSUInteger i=0;i<cells.count;++i){DrawPairwisePDFText(cells[i],NSMakeRect(x,y,widths[i]-2,18),bodyAttrs);x+=widths[i];} y+=19;
    }
    path=[NSBezierPath bezierPath];[path moveToPoint:NSMakePoint(margin,y)];[path lineToPoint:NSMakePoint(pageWidth-margin,y)];[path stroke];y+=8;
    if (!apaStyle && state.showInformationCriteria) {
        y += 8;
        DrawPairwisePDFText(@"Information criteria", NSMakeRect(margin, y, 200, 16), headerAttrs); y += 19;
        NSArray<NSString *> *icHeaders = @[@"Model", @"AIC", @"BIC", @"ΔAIC", @"ΔBIC"];
        std::vector<CGFloat> icWidths = {200, 100, 100, 100, 100};
        double minAIC = INFINITY, minBIC = INFINITY;
        for (const auto &candidate : state.models) {
            if (candidate.fit.ok && std::isfinite(candidate.fit.aic)) minAIC = std::min(minAIC, candidate.fit.aic);
            if (candidate.fit.ok && std::isfinite(candidate.fit.bic)) minBIC = std::min(minBIC, candidate.fit.bic);
        }
        x = margin;
        for (NSUInteger i = 0; i < icHeaders.count; ++i) { DrawPairwisePDFText(icHeaders[i], NSMakeRect(x, y, icWidths[i]-2, 16), headerAttrs); x += icWidths[i]; }
        y += 18;
        for (const auto &candidate : state.models) {
            NSArray<NSString *> *cells = @[SafeNSStringFromUTF8(candidate.label), PairwiseNumberText(candidate.fit.aic, 2),
                PairwiseNumberText(candidate.fit.bic, 2), PairwiseNumberText(candidate.fit.aic - minAIC, 2),
                PairwiseNumberText(candidate.fit.bic - minBIC, 2)];
            x = margin;
            for (NSUInteger i = 0; i < cells.count; ++i) { DrawPairwisePDFText(cells[i], NSMakeRect(x, y, icWidths[i]-2, 18), bodyAttrs); x += icWidths[i]; }
            y += 19;
        }
    }
    NSString *note=[NSString stringWithFormat:@"Note. All models were fitted in R using stats::glm with a binomial distribution and %@ link on the same analysis rows. Likelihood-ratio tests compare each model with the preceding model when the models are nested.",SafeNSStringFromUTF8(state.link)];
    DrawPairwisePDFText(note,NSMakeRect(margin,y,pageWidth-2*margin,40),bodyAttrs);
    [NSGraphicsContext setCurrentContext:nil]; CGContextRestoreGState(context); CGContextEndPage(context); CGContextRelease(context);
}

@implementation GLMPairwiseComparisonPlotView

- (NSString *)snapshotTabDelimitedText
{
    std::ostringstream text;
    text << (_pairedMeanDifferences ? "Paired mean differences" : "Pairwise differences")
         << " — " << _term
         << "\nComparison\tEstimate\tCI lower\tCI upper\tp";
    for (const rlispstat::core::LinearFunctionEstimate &row : _rows) {
        text << '\n' << row.label << '\t' << row.estimate << '\t'
             << row.ciLower << '\t' << row.ciUpper << '\t' << row.adjustedPValue;
    }
    return ToNSString(text.str());
}

- (BOOL)isFlipped
{
    return YES;
}

- (instancetype)initWithTerm:(const std::string &)term
                        rows:(const std::vector<rlispstat::core::LinearFunctionEstimate> &)rows
                    plotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    const CGFloat height = std::max((CGFloat)220.0, 100.0 + (CGFloat)rows.size() * 32.0);
    self = [super initWithFrame:NSMakeRect(0.0, 0.0, 820.0, height)];
    if (!self) return nil;
    _term = term;
    _group = plotLink.group;
    _sourceModelId = plotLink.sourceModelId;
    _plotLink = plotLink;
    _rows = rows;
    _rowsByComparison = plotLink.rowsByComparison;
    _gamesHowell = plotLink.gamesHowell;
    _binaryRegression = plotLink.binaryRegression;
    _binaryOddsRatio = plotLink.binaryOddsRatio;
    _pairedMeanDifferences = plotLink.pairedMeanDifferences;
    [self setWantsLayer:YES];
    [self setAutoresizingMask:NSViewWidthSizable];
    return self;
}

- (const std::string &)pairwisePlotGroup
{
    return _group;
}

- (const std::string &)pairwiseSourceModelId
{
    return _sourceModelId;
}

- (const std::string &)pairwiseSourceTerm
{
    return _plotLink.factor;
}

- (GLMPairwiseComparisonPlotLink)derivedPlotLink
{
    return _plotLink;
}

- (void)refreshPairwisePlotSelection
{
    [self setNeedsDisplay:YES];
}

- (void)applyDerivedResult:(const rlispstat::core::GLMPairwiseComparisonResult &)result
                  plotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    if (!_plotLink.factor.empty() && _plotLink.factor != result.term) return;
    if (_plotLink.sourceModelKind != "mean_comparison") _term = result.term;
    _group = plotLink.group;
    _sourceModelId = plotLink.sourceModelId;
    _plotLink = plotLink;
    _rows = result.comparisons;
    _rowsByComparison = plotLink.rowsByComparison;
    _gamesHowell = plotLink.gamesHowell;
    _binaryRegression = plotLink.binaryRegression;
    _binaryOddsRatio = plotLink.binaryOddsRatio;
    _pairedMeanDifferences = plotLink.pairedMeanDifferences;
    NSRect frame = [self frame];
    frame.size.height = std::max((CGFloat)220.0, 100.0 + (CGFloat)_rows.size() * 32.0);
    [self setFrame:frame];
    [self setNeedsDisplay:YES];
    [self displayIfNeeded];
}

- (void)clearDerivedResult
{
    _rows.clear();
    _rowsByComparison.clear();
    _plotLink.rowsByComparison.clear();
    NSRect frame = [self frame];
    frame.size.height = 220.0;
    [self setFrame:frame];
    [self setNeedsDisplay:YES];
    [self displayIfNeeded];
}

- (NSInteger)comparisonAtPoint:(NSPoint)point
{
    const CGFloat top = 38.0;
    const CGFloat rowHeight = 32.0;
    NSInteger row = (NSInteger)std::floor((point.y - top) / rowHeight);
    return row >= 0 && (std::size_t)row < _rows.size() ? row : -1;
}

- (void)mouseDown:(NSEvent *)event
{
    const NSInteger row = [self comparisonAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    if (row < 0 || (std::size_t)row >= _rowsByComparison.size() ||
        _rowsByComparison[(std::size_t)row].empty() || _group.empty()) return;
    const NSEventModifierFlags flags = [event modifierFlags];
    const std::string mode = rlispstat::core::EffectiveSelectionModeName(
        (flags & NSEventModifierFlagOption) != 0,
        (flags & NSEventModifierFlagCommand) != 0,
        (flags & NSEventModifierFlagControl) != 0,
        (flags & NSEventModifierFlagShift) != 0,
        "replace");
    int selectionVersion = 0;
    if (MergeSelection(_group, _rowsByComparison[(std::size_t)row], mode, &selectionVersion)) {
        const std::set<int> &selected = _rowsByComparison[(std::size_t)row];
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group,
                                 _pairedMeanDifferences ? "compare-means" : "glm-pairwise", "",
                                 std::vector<int>(selected.begin(), selected.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
}

- (void)selectForestComparison:(id)sender
{
    const NSInteger row = [[sender representedObject] integerValue];
    if (row < 0 || static_cast<std::size_t>(row) >= _rowsByComparison.size()) return;
    const std::set<int> &rows = _rowsByComparison[static_cast<std::size_t>(row)];
    if (rows.empty()) return;
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = SetGroupSelectionUnlocked(_group, rows, &selectionVersion);
    }
    if (changed) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group,
                                 _pairedMeanDifferences ? "compare-means" : "glm-pairwise", "",
                                 std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
}

- (void)copyForestPlot:(id)sender
{
    NSString *format = [sender representedObject] ?: @"PDF";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    if ([format isEqualToString:@"SVG"]) {
        const std::string source = ComposeSvgExportForView(self, [self forestSvgDocument]);
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        [pasteboard setData:data forType:@"public.svg-image"];
        [pasteboard setString:ToNSString(source) forType:NSPasteboardTypeString];
    } else if ([format isEqualToString:@"PNG"]) {
        [pasteboard setData:VisualExportDataForView(self, @"PNG") forType:NSPasteboardTypePNG];
    } else {
        [pasteboard setData:VisualExportDataForView(self, @"PDF") forType:NSPasteboardTypePDF];
    }
}

- (void)saveForestPlot:(id)sender
{
    NSString *format = [sender representedObject];
    NSSavePanel *panel = [NSSavePanel savePanel];
    NSString *extension = [format lowercaseString];
    SetSavePanelExtensionCompat(panel, extension);
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"%@.%@",
        _pairedMeanDifferences ? @"paired-mean-differences" : @"pairwise-differences", extension]];
    if ([panel runModal] != NSModalResponseOK) return;
    if ([format isEqualToString:@"SVG"]) {
        const std::string source = ComposeSvgExportForView(self, [self forestSvgDocument]);
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        [data writeToURL:[panel URL] atomically:YES];
    } else {
        SaveViewToPath(self, [panel URL].path, format ? [format UTF8String] : "PDF");
    }
}

- (std::string)forestSvgDocument
{
    const NSRect bounds = [self bounds];
    rlispstat::core::SvgWriter svg({bounds.size.width, bounds.size.height, 2.0});
    const auto style = rlispstat::core::PlotThemeStyleForName(
        std::string([PlotEffectiveThemeName(self) UTF8String]));
    auto hex = [](const rlispstat::core::PlotRGBA &color) {
        char buffer[16];
        std::snprintf(buffer, sizeof(buffer), "#%02X%02X%02X",
            (int)std::llround(std::max(0.0, std::min(1.0, color.r)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.g)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.b)) * 255.0));
        return std::string(buffer);
    };
    svg.rectangle(0, 0, bounds.size.width, bounds.size.height,
                  {hex(style.background), "none", 0, 1, {}});
    if (_rows.empty()) return svg.finish();
    const CGFloat labelWidth = 220.0;
    const CGFloat top = 38.0;
    const CGFloat rowHeight = 32.0;
    const NSRect plotRect = NSMakeRect(labelWidth + 14.0, top,
        std::max((CGFloat)80.0, bounds.size.width - labelWidth - 42.0),
        std::max((CGFloat)24.0, (CGFloat)_rows.size() * rowHeight));
    svg.rectangle(plotRect.origin.x, plotRect.origin.y, plotRect.size.width, plotRect.size.height,
                  {hex(style.panel), "none", 0, 1, {}});
    double minimum = _binaryOddsRatio ? 1.0 : 0.0;
    double maximum = minimum;
    for (const auto &row : _rows) {
        minimum = std::min(minimum, std::min(row.estimate, row.ciLower));
        maximum = std::max(maximum, std::max(row.estimate, row.ciUpper));
    }
    if (!std::isfinite(minimum) || !std::isfinite(maximum) || maximum <= minimum) {
        minimum = -1.0; maximum = 1.0;
    }
    const double padding = std::max(0.1, (maximum - minimum) * 0.08);
    minimum -= padding; maximum += padding;
    auto xForValue = [&](double value) {
        return plotRect.origin.x + (value - minimum) / (maximum - minimum) * plotRect.size.width;
    };
    rlispstat::core::SvgTextStyle titleText{hex(style.text), "Arial, Helvetica, sans-serif", 15, 600, false, "start"};
    rlispstat::core::SvgTextStyle labelText{hex(style.text), "Arial, Helvetica, sans-serif", 12, 500, false, "start"};
    rlispstat::core::SvgTextStyle tickText{hex(style.mutedText), "Arial, Helvetica, sans-serif", 10, 400, false, "middle"};
    svg.text(14, 25, (_pairedMeanDifferences ? "Paired mean differences — " : "Pairwise differences — ") + _term, titleText);
    for (int tick = 0; tick <= 5; ++tick) {
        const double x = plotRect.origin.x + plotRect.size.width * tick / 5.0;
        svg.line(x, plotRect.origin.y, x, NSMaxY(plotRect),
                 {"none", hex(style.majorGrid), 1, 1, {}});
        const double value = minimum + (maximum - minimum) * tick / 5.0;
        std::ostringstream label; label << std::setprecision(3) << value;
        svg.text(x, NSMaxY(plotRect) + 17, label.str(), tickText);
    }
    svg.line(plotRect.origin.x, NSMaxY(plotRect), NSMaxX(plotRect), NSMaxY(plotRect),
             {"none", hex(style.axis), 1.2, 1, {}});
    const double reference = _binaryOddsRatio ? 1.0 : 0.0;
    svg.line(xForValue(reference), plotRect.origin.y, xForValue(reference), NSMaxY(plotRect),
             {"none", hex(style.axis), 1.2, 1, {4, 3}});
    svg.beginClipRect(plotRect.origin.x, plotRect.origin.y, plotRect.size.width, plotRect.size.height);
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        const auto &row = _rows[index];
        const double y = top + rowHeight * index + rowHeight / 2.0;
        svg.line(xForValue(row.ciLower), y, xForValue(row.ciUpper), y,
                 {"none", hex(style.geomStroke), 1.4, 1, {}});
        svg.line(xForValue(row.ciLower), y - 4, xForValue(row.ciLower), y + 4,
                 {"none", hex(style.geomStroke), 1.4, 1, {}});
        svg.line(xForValue(row.ciUpper), y - 4, xForValue(row.ciUpper), y + 4,
                 {"none", hex(style.geomStroke), 1.4, 1, {}});
        svg.ellipse(xForValue(row.estimate), y, 4, 4,
                    {hex(style.geomFill), hex(style.geomStroke), 1, 1, {}});
    }
    svg.endClip();
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        std::string label = _rows[index].label;
        std::size_t found = 0;
        while ((found = label.find(" - ", found)) != std::string::npos) {
            label.replace(found, 3, " − "); found += 3;
        }
        svg.text(14, top + rowHeight * index + rowHeight / 2.0 + 4, label, labelText);
    }
    return svg.finish();
}

- (void)copyForestComparisonValues:(id)sender
{
    const NSInteger row = [[sender representedObject] integerValue];
    if (row < 0 || static_cast<std::size_t>(row) >= _rows.size()) return;
    const rlispstat::core::LinearFunctionEstimate &value = _rows[static_cast<std::size_t>(row)];
    NSString *text = [NSString stringWithFormat:@"%@\nEstimate: %@\n95%% CI: [%@, %@]\n%@: %@",
        [SafeNSStringFromUTF8(value.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "],
        PairwiseNumberText(value.estimate, 4), PairwiseNumberText(value.ciLower, 4),
        PairwiseNumberText(value.ciUpper, 4), _pairedMeanDifferences ? @"p" : @"Adjusted p",
        PairwisePValueText(value.adjustedPValue)];
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
}

- (void)clearForestSelection:(id)sender
{
    (void)sender;
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = ClearGroupSelectionUnlocked(_group, &selectionVersion);
    }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _group,
        _pairedMeanDifferences ? "compare-means" : "glm-pairwise", "", {}, selectionVersion);
}

- (void)rightMouseDown:(NSEvent *)event
{
    const NSInteger row = [self comparisonAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:_pairedMeanDifferences ? @"Paired comparison" : @"Pairwise comparison"];
    const BOOL hasComparison = row >= 0;
    NSMenuItem *select = [[NSMenuItem alloc] initWithTitle:_pairedMeanDifferences ? @"Select paired observations" : @"Select comparison" action:@selector(selectForestComparison:) keyEquivalent:@""];
    [select setRepresentedObject:@(row)]; [select setTarget:self]; [select setEnabled:hasComparison]; [menu addItem:select];
    NSMenuItem *selectRows = [[NSMenuItem alloc] initWithTitle:_pairedMeanDifferences ? @"Select observations used by this pair" : @"Select observations from both categories" action:@selector(selectForestComparison:) keyEquivalent:@""];
    [selectRows setRepresentedObject:@(row)]; [selectRows setTarget:self]; [selectRows setEnabled:hasComparison]; [menu addItem:selectRows];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:@"Clear selection" action:@selector(clearForestSelection:) keyEquivalent:@""];
    [clear setTarget:self]; [clear setEnabled:SelectionCount(_group) > 0]; [menu addItem:clear];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    WindowNotesContainer *notes = WindowNotesContainerForView(self);
    if (notes) {
        NSMenuItem *includeNotes = PlotCommandMenuItem(@"Include Notes", @"NOTES_INCLUDE_EXPORT");
        [includeNotes setEnabled:[notes hasNotes]];
        [includeNotes setState:[notes includeNotes] ? NSControlStateValueOn : NSControlStateValueOff];
        [exportMenu addItem:includeNotes];
        [exportMenu addItem:[NSMenuItem separatorItem]];
    }
    const auto actions = rlispstat::core::BuildExportMenuActions(
        rlispstat::core::StandardVisualExportCapabilities(rlispstat::core::ExportPlatform::MacOS),
        rlispstat::core::ExportPlatform::MacOS);
    for (const auto &action : actions) {
        if (action.separatorBefore) [exportMenu addItem:[NSMenuItem separatorItem]];
        const bool copy = action.identifier.rfind("copy_", 0) == 0;
        NSString *format = action.capability == rlispstat::core::ExportCapability::CopySvg ||
            action.capability == rlispstat::core::ExportCapability::SaveSvg ? @"SVG" :
            (action.capability == rlispstat::core::ExportCapability::CopyPng ||
             action.capability == rlispstat::core::ExportCapability::SavePng ? @"PNG" : @"PDF");
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(action.title)
            action:(copy ? @selector(copyForestPlot:) : @selector(saveForestPlot:)) keyEquivalent:@""];
        [item setRepresentedObject:format]; [item setTarget:self]; [exportMenu addItem:item];
    }
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copyValues = [[NSMenuItem alloc] initWithTitle:@"Copy comparison values" action:@selector(copyForestComparisonValues:) keyEquivalent:@""];
    [copyValues setRepresentedObject:@(row)]; [copyValues setTarget:self]; [copyValues setEnabled:hasComparison]; [exportMenu addItem:copyValues];
    OrganizeExportMenu(exportMenu);
    [exportRoot setSubmenu:exportMenu]; [menu addItem:exportRoot];
    [menu addItem:[NSMenuItem separatorItem]];
    AddPlotThemeSubmenu(menu, self);
    AddSnapshotAlbumContextItems(menu);
    [NSMenu popUpContextMenu:FinalizeGraphContextMenu(menu) withEvent:event forView:self];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeOverrideScope localTheme(PlotLocalThemeName(self));
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);
    if (_rows.empty()) return;

    NSDictionary *labelAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12.0 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    CGFloat widestLabel = 0.0;
    for (const rlispstat::core::LinearFunctionEstimate &row : _rows) {
        NSSize labelSize = [SafeNSStringFromUTF8(row.label) sizeWithAttributes:labelAttributes];
        widestLabel = std::max(widestLabel, labelSize.width);
    }
    const CGFloat labelWidth = std::min((CGFloat)300.0, std::max((CGFloat)150.0, widestLabel + 22.0));
    const CGFloat top = 38.0;
    const CGFloat rowHeight = 32.0;
    const NSRect plotRect = NSMakeRect(labelWidth + 14.0, top,
                                       std::max((CGFloat)80.0, NSWidth([self bounds]) - labelWidth - 42.0),
                                       std::max((CGFloat)24.0, (CGFloat)_rows.size() * rowHeight));
    [theme.panel setFill];
    NSRectFill(plotRect);

    const double referenceValue = _binaryOddsRatio ? 1.0 : 0.0;
    double minimum = referenceValue;
    double maximum = referenceValue;
    for (const rlispstat::core::LinearFunctionEstimate &row : _rows) {
        minimum = std::min(minimum, std::min(row.estimate, row.ciLower));
        maximum = std::max(maximum, std::max(row.estimate, row.ciUpper));
    }
    if (!std::isfinite(minimum) || !std::isfinite(maximum) || maximum <= minimum) {
        minimum = -1.0;
        maximum = 1.0;
    }
    const double padding = std::max(0.1, (maximum - minimum) * 0.08);
    minimum -= padding;
    maximum += padding;
    const auto xForValue = [&](double value) {
        return plotRect.origin.x + (CGFloat)((value - minimum) / (maximum - minimum) * plotRect.size.width);
    };

    NSDictionary *titleAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:15.0 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *tickAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10.0],
        NSForegroundColorAttributeName: theme.mutedText
    };
    [SafeNSStringFromUTF8((_pairedMeanDifferences ? "Paired mean differences — " : "Pairwise differences — ") + _term)
        drawAtPoint:NSMakePoint(14.0, 14.0) withAttributes:titleAttributes];

    NSBezierPath *grid = [NSBezierPath bezierPath];
    for (int tick = 0; tick <= 5; ++tick) {
        const CGFloat x = plotRect.origin.x + plotRect.size.width * tick / 5.0;
        [grid moveToPoint:NSMakePoint(x, plotRect.origin.y)];
        [grid lineToPoint:NSMakePoint(x, NSMaxY(plotRect))];
        const double value = minimum + (maximum - minimum) * tick / 5.0;
        NSString *text = [NSString stringWithFormat:@"%.3g", value];
        NSSize size = [text sizeWithAttributes:tickAttributes];
        [text drawAtPoint:NSMakePoint(x - size.width / 2.0, NSMaxY(plotRect) + 7.0) withAttributes:tickAttributes];
    }
    [theme.majorGrid setStroke];
    [grid setLineWidth:1.0];
    [grid stroke];
    NSBezierPath *axis = [NSBezierPath bezierPath];
    [axis moveToPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect))];
    [axis lineToPoint:NSMakePoint(NSMaxX(plotRect), NSMaxY(plotRect))];
    [theme.axis setStroke];
    [axis setLineWidth:1.2];
    [axis stroke];

    const CGFloat zeroX = xForValue(referenceValue);
    if (zeroX >= plotRect.origin.x && zeroX <= NSMaxX(plotRect)) {
        NSBezierPath *zero = [NSBezierPath bezierPath];
        [zero moveToPoint:NSMakePoint(zeroX, plotRect.origin.y)];
        [zero lineToPoint:NSMakePoint(zeroX, NSMaxY(plotRect))];
        CGFloat dashes[] = {4.0, 3.0};
        [zero setLineDash:dashes count:2 phase:0.0];
        [(theme.coordinatedMarks ? theme.reference : theme.axis) setStroke];
        [zero setLineWidth:1.2];
        [zero stroke];
    }

    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(_group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        const rlispstat::core::LinearFunctionEstimate &row = _rows[index];
        const CGFloat y = top + rowHeight * index + rowHeight / 2.0;
        const bool selected = index < _rowsByComparison.size() && !_rowsByComparison[index].empty() &&
            _rowsByComparison[index] == selection;
        if (selected) {
            [(theme.coordinatedMarks ? [theme.selectedMarkFill colorWithAlphaComponent:0.12] :
                [NSColor colorWithCalibratedWhite:0.93 alpha:1.0]) setFill];
            NSRectFill(NSMakeRect(0.0, top + rowHeight * index, NSWidth([self bounds]), rowHeight));
        }
        NSString *label = [SafeNSStringFromUTF8(row.label) stringByReplacingOccurrencesOfString:@" - " withString:@" − "];
        [label drawInRect:NSMakeRect(14.0, y - 8.0, labelWidth - 12.0, 17.0) withAttributes:labelAttributes];
        const CGFloat low = xForValue(row.ciLower);
        const CGFloat high = xForValue(row.ciUpper);
        NSColor *color = selected && theme.coordinatedMarks ? theme.selectedMarkFill :
            (selected ? theme.accent : theme.geomStroke);
        [color setStroke];
        NSBezierPath *interval = [NSBezierPath bezierPath];
        [interval moveToPoint:NSMakePoint(low, y)];
        [interval lineToPoint:NSMakePoint(high, y)];
        [interval moveToPoint:NSMakePoint(low, y - 4.0)];
        [interval lineToPoint:NSMakePoint(low, y + 4.0)];
        [interval moveToPoint:NSMakePoint(high, y - 4.0)];
        [interval lineToPoint:NSMakePoint(high, y + 4.0)];
        [interval setLineWidth:selected ? 2.2 : 1.4];
        [interval stroke];
        [(selected && theme.coordinatedMarks ? theme.selectedMarkFill :
            (selected ? theme.accent : theme.geomFill)) setFill];
        const CGFloat radius = selected ? 5.0 : 4.0;
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(xForValue(row.estimate) - radius, y - radius, radius * 2.0, radius * 2.0)] fill];
    }
    [(_pairedMeanDifferences
        ? @"Mean difference (first variable − second variable)"
        : (_binaryRegression
        ? (_binaryOddsRatio ? @"Odds ratio (first category / second category)" : @"Probability difference (first category − second category)")
        : (_gamesHowell ? @"Mean difference (first category − second category)" : @"Estimated marginal mean difference (first category − second category)")))
        drawAtPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect) + 25.0)
                                               withAttributes:tickAttributes];
    [(_pairedMeanDifferences
        ? @"Click a pair to select its complete observations. Command-click combines selections."
        : @"Click a comparison to select observations from both categories. Command-click combines selections.")
        drawAtPoint:NSMakePoint(14.0, NSMaxY(plotRect) + 44.0) withAttributes:tickAttributes];
}
@end

@implementation GLMPairwiseObservedBoxplotView
- (BOOL)isFlipped
{
    return YES;
}

- (instancetype)initWithPlotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    self = [super initWithFrame:NSMakeRect(0.0, 0.0, 460.0, 260.0)];
    if (!self) return nil;
    _plotLink = plotLink;
    [self setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    return self;
}

- (const std::string &)pairwisePlotGroup
{
    return _plotLink.group;
}

- (const std::string &)pairwiseSourceModelId
{
    return _plotLink.sourceModelId;
}

- (const std::string &)pairwiseSourceTerm
{
    return _plotLink.factor;
}

- (GLMPairwiseComparisonPlotLink)derivedPlotLink
{
    return _plotLink;
}

- (void)refreshPairwisePlotSelection
{
    [self setNeedsDisplay:YES];
}

- (void)applyDerivedPlotLink:(const GLMPairwiseComparisonPlotLink &)plotLink
{
    _plotLink = plotLink;
    [self setNeedsDisplay:YES];
    [self displayIfNeeded];
}

- (void)clearDerivedResult
{
    _plotLink.levels.clear();
    _plotLink.observations.clear();
    _plotLink.rowsByLevel.clear();
    _plotLink.rowsByComparison.clear();
    [self setNeedsDisplay:YES];
    [self displayIfNeeded];
}

- (NSInteger)levelAtPoint:(NSPoint)point
{
    const CGFloat left = 54.0, right = 18.0;
    const CGFloat width = NSWidth([self bounds]) - left - right;
    if (_plotLink.levels.empty() || point.x < left || point.x > left + width) return -1;
    const CGFloat slot = width / _plotLink.levels.size();
    const NSInteger level = static_cast<NSInteger>((point.x - left) / slot);
    return level >= 0 && static_cast<std::size_t>(level) < _plotLink.levels.size() ? level : -1;
}

- (void)selectLevel:(id)sender
{
    const NSInteger index = [[sender representedObject] integerValue];
    if (index < 0 || static_cast<std::size_t>(index) >= _plotLink.levels.size()) return;
    const std::set<int> &rows = _plotLink.rowsByLevel[_plotLink.levels[static_cast<std::size_t>(index)]];
    if (rows.empty()) return;
    const NSEventModifierFlags flags = [[NSApp currentEvent] modifierFlags];
    const std::string mode = rlispstat::core::EffectiveSelectionModeName(
        (flags & NSEventModifierFlagOption) != 0, (flags & NSEventModifierFlagCommand) != 0,
        (flags & NSEventModifierFlagControl) != 0, (flags & NSEventModifierFlagShift) != 0, "replace");
    int selectionVersion = 0;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = (mode == "replace")
            ? SetGroupSelectionUnlocked(_plotLink.group, rows, &selectionVersion)
            : MergeGroupSelectionUnlocked(_plotLink.group, rows, mode, &selectionVersion);
    }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _plotLink.group, "glm-pairwise", "",
                                           std::vector<int>(rows.begin(), rows.end()), selectionVersion);
}

- (void)clearBoxplotSelection:(id)sender
{
    (void)sender;
    int selectionVersion = 0;
    bool changed = false;
    { std::lock_guard<std::mutex> lock(g_mutex); changed = ClearGroupSelectionUnlocked(_plotLink.group, &selectionVersion); }
    if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", _plotLink.group, "glm-pairwise", "", {}, selectionVersion);
}

- (void)copyBoxplot:(id)sender
{
    (void)sender;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setData:VisualExportDataForView(self, @"PDF") forType:NSPasteboardTypePDF];
}

- (void)saveBoxplot:(id)sender
{
    NSString *format = [sender representedObject];
    NSString *extension = [format isEqualToString:@"PNG"] ? @"png" : @"pdf";
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, extension);
    [panel setNameFieldStringValue:[NSString stringWithFormat:@"distribution-by-%@.%@", SafeNSStringFromUTF8(_plotLink.factor), extension]];
    if ([panel runModal] == NSModalResponseOK) SaveViewToPath(self, [panel URL].path, format ? [format UTF8String] : "PDF");
}

- (void)mouseDown:(NSEvent *)event
{
    const NSInteger level = [self levelAtPoint:[self convertPoint:[event locationInWindow] fromView:nil]];
    if (level < 0) return;
    NSMenuItem *item = [[NSMenuItem alloc] init];
    [item setRepresentedObject:@(level)];
    [self selectLevel:item];
}

- (void)rightMouseDown:(NSEvent *)event
{
    // This legacy view is no longer instantiated. Observed pairwise data are
    // opened as the standard linked BoxplotView, whose Export submenu is built
    // by AddStandardPlotExportItems and includes SVG/PDF/PNG consistently.
    [super rightMouseDown:event];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill]; NSRectFill([self bounds]);
    if (_plotLink.levels.empty() || _plotLink.observations.empty()) return;
    const CGFloat left = 54.0, right = 18.0, top = 38.0, bottom = 50.0;
    const NSRect plot = NSMakeRect(left, top, std::max((CGFloat)80.0, NSWidth([self bounds]) - left - right),
                                   std::max((CGFloat)80.0, NSHeight([self bounds]) - top - bottom));
    [theme.panel setFill]; NSRectFill(plot);
    double ymin = INFINITY, ymax = -INFINITY;
    std::map<std::string, std::vector<double>> values;
    for (const auto &observation : _plotLink.observations) {
        values[observation.level].push_back(observation.response);
        ymin = std::min(ymin, observation.response); ymax = std::max(ymax, observation.response);
    }
    if (!(ymax > ymin)) { ymin -= 1.0; ymax += 1.0; }
    const double pad = (ymax - ymin) * 0.07; ymin -= pad; ymax += pad;
    const auto yFor = [&](double value) { return plot.origin.y + (CGFloat)((ymax - value) / (ymax - ymin) * plot.size.height); };
    NSDictionary *titleAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:13 weight:NSFontWeightSemibold], NSForegroundColorAttributeName: theme.text };
    NSDictionary *labelAttrs = @{ NSFontAttributeName: [NSFont systemFontOfSize:10], NSForegroundColorAttributeName: theme.mutedText };
    [SafeNSStringFromUTF8("Distribution of " + _plotLink.response + " by " + _plotLink.factor) drawAtPoint:NSMakePoint(14, 14) withAttributes:titleAttrs];
    for (int tick = 0; tick <= 4; ++tick) {
        const double value = ymin + (ymax - ymin) * tick / 4.0;
        const CGFloat y = yFor(value);
        NSBezierPath *line = [NSBezierPath bezierPath]; [line moveToPoint:NSMakePoint(NSMinX(plot), y)]; [line lineToPoint:NSMakePoint(NSMaxX(plot), y)];
        [theme.majorGrid setStroke]; [line setLineWidth:0.8]; [line stroke];
        NSString *label = [NSString stringWithFormat:@"%.3g", value]; NSSize size = [label sizeWithAttributes:labelAttrs];
        [label drawAtPoint:NSMakePoint(left - size.width - 6.0, y - size.height / 2.0) withAttributes:labelAttrs];
    }
    std::set<int> selection;
    { std::lock_guard<std::mutex> lock(g_mutex); auto it = g_groupSelections.find(_plotLink.group); if (it != g_groupSelections.end()) selection = it->second; }
    const CGFloat slot = plot.size.width / _plotLink.levels.size();
    for (std::size_t index = 0; index < _plotLink.levels.size(); ++index) {
        const std::string &level = _plotLink.levels[index];
        std::vector<double> sorted = values[level];
        if (sorted.empty()) continue;
        std::sort(sorted.begin(), sorted.end());
        const double q1 = BoxplotQuantileSorted(sorted, 0.25), med = BoxplotQuantileSorted(sorted, 0.5), q3 = BoxplotQuantileSorted(sorted, 0.75);
        const double fenceLow = q1 - 1.5 * (q3 - q1), fenceHigh = q3 + 1.5 * (q3 - q1);
        double low = sorted.front(), high = sorted.back();
        for (double value : sorted) if (value >= fenceLow) { low = value; break; }
        for (auto it = sorted.rbegin(); it != sorted.rend(); ++it) if (*it <= fenceHigh) { high = *it; break; }
        const CGFloat cx = plot.origin.x + slot * ((CGFloat)index + 0.5), width = std::min((CGFloat)64.0, slot * 0.52);
        const std::set<int> &levelRows = _plotLink.rowsByLevel[level];
        const bool active = !levelRows.empty() && std::any_of(levelRows.begin(), levelRows.end(), [&](int row) { return selection.count(row) != 0; });
        const CGFloat alpha = selection.empty() || active ? 0.36 : 0.12;
        [[theme.geomFill colorWithAlphaComponent:alpha] setFill];
        NSRect box = NSMakeRect(cx - width / 2.0, yFor(q3), width, std::max((CGFloat)1.0, yFor(q1) - yFor(q3))); NSRectFill(box);
        [(active ? theme.accent : theme.geomStroke) setStroke]; NSFrameRectWithWidth(box, active ? 2.0 : 1.0);
        NSBezierPath *whisker = [NSBezierPath bezierPath];
        [whisker moveToPoint:NSMakePoint(cx, yFor(high))]; [whisker lineToPoint:NSMakePoint(cx, yFor(q3))];
        [whisker moveToPoint:NSMakePoint(cx, yFor(q1))]; [whisker lineToPoint:NSMakePoint(cx, yFor(low))];
        [whisker moveToPoint:NSMakePoint(cx - width * .25, yFor(high))]; [whisker lineToPoint:NSMakePoint(cx + width * .25, yFor(high))];
        [whisker moveToPoint:NSMakePoint(cx - width * .25, yFor(low))]; [whisker lineToPoint:NSMakePoint(cx + width * .25, yFor(low))];
        [whisker setLineWidth:active ? 1.8 : 1.2]; [whisker stroke];
        NSBezierPath *median = [NSBezierPath bezierPath]; [median moveToPoint:NSMakePoint(cx - width / 2.0, yFor(med))]; [median lineToPoint:NSMakePoint(cx + width / 2.0, yFor(med))]; [theme.accent setStroke]; [median setLineWidth:1.8]; [median stroke];
        for (const auto &observation : _plotLink.observations) if (observation.level == level) {
            const CGFloat jitter = ((observation.row * 37) % 17 - 8) * 0.55;
            const bool rowSelected = selection.count(observation.row) != 0;
            [(rowSelected ? theme.accent : theme.geomStroke) setFill];
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx + jitter - (rowSelected ? 3.0 : 2.0), yFor(observation.response) - (rowSelected ? 3.0 : 2.0), rowSelected ? 6.0 : 4.0, rowSelected ? 6.0 : 4.0)] fill];
        }
        for (double value : sorted) if (value < low || value > high) {
            [theme.accent2 setStroke]; [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(cx - 3.0, yFor(value) - 3.0, 6.0, 6.0)] stroke];
        }
        NSString *category = SafeNSStringFromUTF8(level); NSSize categorySize = [category sizeWithAttributes:labelAttrs];
        [category drawAtPoint:NSMakePoint(cx - categorySize.width / 2.0, NSMaxY(plot) + 8.0) withAttributes:labelAttrs];
    }
    [SafeNSStringFromUTF8(_plotLink.response) drawAtPoint:NSMakePoint(5.0, top + 4.0) withAttributes:labelAttrs];
}
@end

static void ShowGLMPairwiseObservedBoxplotOnMain(const GLMPairwiseComparisonPlotLink &plotLink)
{
    const GLMPairwiseComparisonPlotLink linkCopy = plotLink;
    dispatch_async(dispatch_get_main_queue(), ^{
        if (linkCopy.observations.empty()) return;
        PlotModel *created = new PlotModel();
        created->kind = "boxplot";
        created->id = "boxplot_pairwise_" + std::to_string((long long)time(nullptr)) +
            "_" + std::to_string(std::rand() % 1000000);
        created->group = linkCopy.group;
        created->xLabel = linkCopy.factor;
        created->yLabel = linkCopy.response;
        created->title = "Distribution of " + linkCopy.response + " by " + linkCopy.factor;
        created->interactionMode = "select";
        created->selectionMode = "replace";
        created->isRegressionDerivedPlot = !linkCopy.sourceModelId.empty();
        created->regressionDerivedKind = "pairwise_observed_boxplot";
        created->regressionDerivedSourceKind = linkCopy.sourceModelKind;
        created->regressionDerivedSourceModelId = linkCopy.sourceModelId;
        created->regressionDerivedTerm = linkCopy.factor;
        created->regressionDerivedSourceRevision = linkCopy.sourceModelRevision;
        created->regressionDerivedSourceFitVersion = linkCopy.sourceFitVersion;
        created->boxplotCategories = linkCopy.levels;
        created->boxplotDefinedCategories = created->boxplotCategories;
        for (const GLMPairwiseComparisonPlotLink::Observation &observation : linkCopy.observations) {
            if (observation.row > 0 && std::isfinite(observation.response)) {
                created->boxplotPoints.push_back(
                    BoxplotPoint{observation.response, observation.level, observation.row});
            }
        }
        if (created->boxplotPoints.empty()) {
            delete created;
            return;
        }
        EnsureParallelBoxplotState(created);
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            for (const auto &entry : g_plots) {
                PlotModel *source = entry.second;
                if (source && source->group == linkCopy.group) {
                    created->variables = source->variables;
                    created->variableMeta = source->variableMeta;
                    break;
                }
            }
            if (!AttachPlotModelUnlocked(created)) {
                delete created;
                return;
            }
        }
        AddPlotOnMain(created);
    });
}

static void ShowGLMPairwiseComparisonPlotOnMain(
    const std::string &term,
    const std::vector<rlispstat::core::LinearFunctionEstimate> &rows,
    const GLMPairwiseComparisonPlotLink &plotLink)
{
    const std::string termCopy = term;
    const std::vector<rlispstat::core::LinearFunctionEstimate> rowsCopy = rows;
    const GLMPairwiseComparisonPlotLink linkCopy = plotLink;
    dispatch_async(dispatch_get_main_queue(), ^{
        static NSMutableArray *retainedPairwisePlotWindows = nil;
        if (!retainedPairwisePlotWindows) retainedPairwisePlotWindows = [[NSMutableArray alloc] init];
        const CGFloat visibleHeight = std::min((CGFloat)620.0,
            std::max((CGFloat)260.0, 110.0 + (CGFloat)rowsCopy.size() * 32.0));
        NSWindow *window = [[NSWindow alloc] initWithContentRect:NextWindowFrameOnMain(820.0, visibleHeight)
                                                       styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                                                         backing:NSBackingStoreBuffered
                                                           defer:NO];
        [window setTitle:SafeNSStringFromUTF8(
            (linkCopy.pairedMeanDifferences ? "Paired mean differences — " : "Pairwise comparison plot — ") + termCopy)];
        [window setReleasedWhenClosed:NO];
        [window setContentMinSize:NSMakeSize(620.0, 260.0)];
        [window setContentMaxSize:NSMakeSize(1280.0, 760.0)];
        GLMPairwiseComparisonPlotView *plot = [[GLMPairwiseComparisonPlotView alloc]
            initWithTerm:termCopy rows:rowsCopy plotLink:linkCopy];
        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:[[window contentView] bounds]];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [scroll setBorderType:NSNoBorder];
        [scroll setDrawsBackground:NO];
        [scroll setHasVerticalScroller:YES];
        [scroll setAutohidesScrollers:YES];
        [scroll setDocumentView:plot];
        [window setContentView:scroll];
        [retainedPairwisePlotWindows addObject:window];
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            g_pairwiseComparisonPlotViews.push_back(plot);
        }
        [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowWillCloseNotification
                                                          object:window
                                                           queue:[NSOperationQueue mainQueue]
                                                      usingBlock:^(NSNotification *note) {
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pairwiseComparisonPlotViews.erase(
                    std::remove(g_pairwiseComparisonPlotViews.begin(), g_pairwiseComparisonPlotViews.end(), plot),
                    g_pairwiseComparisonPlotViews.end());
            }
            [retainedPairwisePlotWindows removeObject:window];
            (void)note;
        }];
        [NSApp activateIgnoringOtherApps:YES];
        EnableNotesForWindow(window, "", @"this comparison graph", linkCopy.group);
        [window makeKeyAndOrderFront:nil];
        [window makeFirstResponder:plot];
    });
}

static GLMPairwiseComparisonPlotLink BuildGLMPairwiseComparisonPlotLink(
    const std::string &group,
    const DataFrameModel &dataframe,
    const std::string &response,
    const std::string &term,
    const std::vector<int> &rowsUsed,
    const rlispstat::core::GLMPairwiseComparisonResult &result)
{
    GLMPairwiseComparisonPlotLink link;
    link.group = group;
    link.response = response;
    link.factor = term;
    link.method = result.method;
    link.gamesHowell = result.adjustment == "Games-Howell";
    link.casesAnalysed = static_cast<int>(rowsUsed.size());
    link.casesExcluded = std::max(0, dataframe.rows - link.casesAnalysed);
    link.levels = result.levels;
    link.rowsByComparison.resize(result.comparisons.size());
    const DataColumn *factorColumn = FindDataColumnInDataFrame(dataframe, term);
    const DataColumn *responseColumn = FindDataColumnInDataFrame(dataframe, response);
    if (!factorColumn || !responseColumn) return link;

    // Model and ApplicationState case identifiers are 1-based.  Preserve that
    // identity instead of treating them as indices into DataColumn::values.
    for (int caseId : rowsUsed) {
        if (caseId <= 0) continue;
        const std::size_t index = static_cast<std::size_t>(caseId - 1);
        if (index >= factorColumn->values.size() || index >= responseColumn->values.size()) continue;
        const std::string &level = factorColumn->values[index];
        double value = NAN;
        if (DataCellIsMissing(level) || !ParseDataCellDouble(responseColumn->values[index], value) || !std::isfinite(value)) continue;
        link.rowsByLevel[level].insert(caseId);
        link.observations.push_back({caseId, level, value});
    }

    for (std::size_t comparisonIndex = 0; comparisonIndex < result.comparisons.size(); ++comparisonIndex) {
        const rlispstat::core::LinearFunctionEstimate &comparison = result.comparisons[comparisonIndex];
        auto first = link.rowsByLevel.find(comparison.firstLevel);
        auto second = link.rowsByLevel.find(comparison.secondLevel);
        if (first != link.rowsByLevel.end()) {
            link.rowsByComparison[comparisonIndex].insert(first->second.begin(), first->second.end());
        }
        if (second != link.rowsByLevel.end()) {
            link.rowsByComparison[comparisonIndex].insert(second->second.begin(), second->second.end());
        }
    }
    return link;
}

struct PairwiseDerivedRefreshSnapshot {
    std::string sourceKind;
    std::string sourceModelId;
    int sourceRevision = 0;
    int sourceFitVersion = 0;
    std::string term;
    std::string group;
    DataFrameModel dataframe;
    PlotModel seed;
    std::string response;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::set<std::string> centeredPredictors;
    std::string scope;
    std::string modelSpec;
    GLMFitSummary linearFit;
    GeneralizedGLMState generalizedFit;
    bool multipleImputation = false;
    bool binaryRegression = false;
    std::string pairwiseAdjustment;
    double confidenceLevel = 0.95;
};

static bool BuildPairwiseDerivedRefreshSnapshot(
    const GLMPairwiseComparisonPlotLink &link,
    PairwiseDerivedRefreshSnapshot &snapshot,
    std::string &message)
{
    snapshot.sourceKind = link.sourceModelKind;
    snapshot.sourceModelId = link.sourceModelId;
    snapshot.term = link.factor;
    snapshot.group = link.group;
    if (snapshot.sourceModelId.empty() || snapshot.term.empty()) {
        message = "This pairwise result is not attached to a live regression model.";
        return false;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *dataframe = FindDataFrameUnlockedConst(link.group);
    if (!dataframe) {
        message = "The source dataset is no longer available.";
        return false;
    }
    snapshot.dataframe = *dataframe;
    if (snapshot.sourceKind == "mean_comparison") {
        const std::size_t separator = snapshot.sourceModelId.find('\x1f');
        if (separator == std::string::npos) {
            message = "The source ANOVA is no longer available.";
            return false;
        }
        const std::string comparisonId = snapshot.sourceModelId.substr(0, separator);
        const std::string response = snapshot.sourceModelId.substr(separator + 1);
        auto source = g_meanComparisonAcceptedStates.find(comparisonId);
        PlotModel *seed = FirstPlotForGroupUnlocked(link.group);
        if (source == g_meanComparisonAcceptedStates.end() || !seed) {
            message = "The source ANOVA is no longer available.";
            return false;
        }
        const MeanComparisonState *state = &source->second;
        if (!state || state->analysisType != "one_way_anova" ||
            state->groupVariable != snapshot.term) {
            message = "The source ANOVA no longer contains this grouping variable.";
            return false;
        }
        if (state->specification.method ==
            rlispstat::core::MeanComparisonMethod::KruskalWallis) {
            message = "Kruskal-Wallis requires rank-based post-hoc comparisons.";
            return false;
        }
        const MeanComparisonRow *omnibus = nullptr;
        for (const auto &table : state->tables) {
            if (table.tableId != "omnibus") continue;
            for (const auto &row : table.rows)
                if (row.variable == response) { omnibus = &row; break; }
        }
        if (!omnibus || omnibus->originalRowIndices.empty()) {
            message = "The source ANOVA has no fitted observations for this response.";
            return false;
        }
        snapshot.sourceRevision = g_meanComparisonResultVersions[comparisonId];
        snapshot.sourceFitVersion = snapshot.sourceRevision;
        snapshot.seed = *seed;
        snapshot.response = response;
        snapshot.terms = {snapshot.term};
        snapshot.termTypes = {{snapshot.term, "factor"}};
        snapshot.scope = ScopeForCapturedAnalysisScope(
            state->dataScope, state->dataScopeCaptured, "all");
        snapshot.linearFit.ok = true;
        snapshot.linearFit.beta = {0.0};
        snapshot.linearFit.covariance = {{1.0}};
        snapshot.linearFit.rowsUsed = omnibus->originalRowIndices;
        snapshot.multipleImputation = state->multipleImputation;
        snapshot.pairwiseAdjustment = state->method.find("Classical") != std::string::npos
            ? "classical-tukey" : "games-howell";
        snapshot.confidenceLevel = state->confidenceLevel;
        snapshot.modelSpec = EncodeStandaloneLinearMISpec(
            snapshot.termTypes, {}, {}, omnibus->originalRowIndices);
    } else if (snapshot.sourceKind == "linear_single") {
        auto stateIt = g_groupModels.find(snapshot.sourceModelId);
        auto fitIt = g_precomputedLinearModelFits.find(snapshot.sourceModelId);
        PlotModel *seed = FirstPlotForGroupUnlocked(link.group);
        if (stateIt == g_groupModels.end() || fitIt == g_precomputedLinearModelFits.end() ||
            !fitIt->second.ok || !seed) {
            message = "The source linear model has no accepted fit.";
            return false;
        }
        const GroupModelState &state = stateIt->second;
        snapshot.sourceRevision = state.modelVersion;
        snapshot.sourceFitVersion = state.fitVersion;
        snapshot.seed = *seed;
        snapshot.response = state.response;
        snapshot.terms = state.terms;
        snapshot.termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        snapshot.centeredPredictors = state.centeredPredictors;
        snapshot.scope = ScopeForModelSpecification(state);
        snapshot.modelSpec = EncodeStandaloneLinearMISpec(
            snapshot.termTypes, state.centeredPredictors,
            state.factorReferenceLevels,
            RowsForModelSpecificationUnlocked(link.group, state));
        snapshot.linearFit = fitIt->second;
        snapshot.multipleImputation = state.multipleImputation;
    } else if (snapshot.sourceKind == "generalized_single") {
        auto stateIt = g_generalizedGLMs.find(snapshot.sourceModelId);
        if (stateIt == g_generalizedGLMs.end() || !stateIt->second.ok) {
            message = "The source generalized model has no accepted fit.";
            return false;
        }
        const GeneralizedGLMState &state = stateIt->second;
        snapshot.sourceRevision = state.modelVersion;
        snapshot.sourceFitVersion = state.fitVersion;
        snapshot.seed = state.seed;
        snapshot.response = state.response;
        snapshot.terms = state.terms;
        snapshot.termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        snapshot.scope = ScopeForCapturedAnalysisScope(
            state.dataScope, state.dataScopeCaptured, state.scope);
        snapshot.modelSpec = EncodeStandaloneGeneralizedMISpec(
            GeneralizedGLMTaskForState(state, state.rFitGeneration));
        snapshot.generalizedFit = state;
        snapshot.multipleImputation = state.multipleImputation;
        snapshot.binaryRegression = state.binaryRegression;
    } else if (snapshot.sourceKind == "linear_comparison") {
        RegressionComparisonState *state = nullptr;
        RegressionComparisonModel *model = nullptr;
        if (!FindRegressionComparisonModelById(snapshot.sourceModelId, &state, &model) ||
            !state || !model || !model->fit.ok) {
            message = "The source comparison model has no accepted fit.";
            return false;
        }
        const rlispstat::core::ModelSpecification specification =
            rlispstat::core::EffectiveRegressionComparisonModelSpecification(*state, *model);
        snapshot.sourceRevision = model->modelVersion;
        snapshot.sourceFitVersion = model->fitVersion;
        snapshot.seed = state->seed;
        snapshot.response = specification.response.empty() ? state->response : specification.response;
        snapshot.terms = specification.terms;
        snapshot.termTypes = specification.termTypes;
        snapshot.centeredPredictors = specification.centeredPredictors;
        snapshot.scope = specification.scope.empty() ? state->scope : specification.scope;
        snapshot.modelSpec = EncodeStandaloneLinearMISpec(
            specification.termTypes, specification.centeredPredictors,
            specification.factorReferenceLevels,
            RowsForCapturedAnalysisScope(state->dataScope, state->dataScopeCaptured));
        snapshot.linearFit = model->fit;
        snapshot.multipleImputation = state->multipleImputation;
    } else if (snapshot.sourceKind == "generalized_comparison") {
        GeneralizedComparisonState *state = nullptr;
        GeneralizedComparisonModel *model = nullptr;
        if (!FindGeneralizedComparisonModelById(snapshot.sourceModelId, &state, &model) ||
            !state || !model || !model->fit.ok) {
            message = "The source generalized-comparison model has no accepted fit.";
            return false;
        }
        const MainRGeneralizedGLMTask task =
            GeneralizedGLMTaskForComparisonModel(*state, *model);
        snapshot.sourceRevision = model->modelVersion;
        snapshot.sourceFitVersion = model->fitVersion;
        snapshot.seed = state->seed;
        snapshot.response = task.response;
        snapshot.terms = task.terms;
        snapshot.termTypes = task.termTypes;
        snapshot.scope = task.scope;
        snapshot.modelSpec = EncodeStandaloneGeneralizedMISpec(task);
        snapshot.generalizedFit = model->fit;
        snapshot.multipleImputation = state->multipleImputation;
        snapshot.binaryRegression = state->binaryComparison;
    } else {
        message = "The source regression type is not registered for live derived output.";
        return false;
    }
    const auto type = snapshot.termTypes.find(snapshot.term);
    if (std::find(snapshot.terms.begin(), snapshot.terms.end(), snapshot.term) == snapshot.terms.end() ||
        type == snapshot.termTypes.end() ||
        (type->second != "factor" && type->second != "ordered") ||
        IsInteractionTerm(snapshot.term)) {
        message = "The source model no longer contains this categorical term.";
        return false;
    }
    return true;
}

static bool PairwiseDerivedSnapshotIsCurrent(
    const PairwiseDerivedRefreshSnapshot &snapshot)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    if (snapshot.sourceKind == "mean_comparison") {
        const std::size_t separator = snapshot.sourceModelId.find('\x1f');
        if (separator == std::string::npos) return false;
        auto current = g_meanComparisonResultVersions.find(snapshot.sourceModelId.substr(0, separator));
        return current != g_meanComparisonResultVersions.end() &&
            current->second == snapshot.sourceRevision;
    }
    if (snapshot.sourceKind == "linear_single") {
        auto it = g_groupModels.find(snapshot.sourceModelId);
        return it != g_groupModels.end() && !it->second.isStale &&
            it->second.modelVersion == snapshot.sourceRevision &&
            it->second.fitVersion == snapshot.sourceFitVersion;
    }
    if (snapshot.sourceKind == "generalized_single") {
        auto it = g_generalizedGLMs.find(snapshot.sourceModelId);
        return it != g_generalizedGLMs.end() && it->second.ok && !it->second.rFitPending &&
            it->second.modelVersion == snapshot.sourceRevision &&
            it->second.fitVersion == snapshot.sourceFitVersion;
    }
    if (snapshot.sourceKind == "linear_comparison") {
        RegressionComparisonState *state = nullptr;
        RegressionComparisonModel *model = nullptr;
        return FindRegressionComparisonModelById(snapshot.sourceModelId, &state, &model) &&
            model && !model->isStale && model->fit.ok &&
            model->modelVersion == snapshot.sourceRevision &&
            model->fitVersion == snapshot.sourceFitVersion;
    }
    if (snapshot.sourceKind == "generalized_comparison") {
        GeneralizedComparisonState *state = nullptr;
        GeneralizedComparisonModel *model = nullptr;
        return FindGeneralizedComparisonModelById(snapshot.sourceModelId, &state, &model) &&
            model && !model->isStale && model->fit.ok &&
            model->modelVersion == snapshot.sourceRevision &&
            model->fitVersion == snapshot.sourceFitVersion;
    }
    return false;
}

static bool ExecutePairwiseDerivedRefresh(
    const PairwiseDerivedRefreshSnapshot &snapshot,
    rlispstat::core::GLMPairwiseComparisonResult &result,
    GLMPairwiseComparisonPlotLink &link,
    std::string &message)
{
    result.term = snapshot.term;
    bool ok = false;
    if (snapshot.binaryRegression) {
        ok = RunRBackedBinaryPairwiseComparisons(
            snapshot.dataframe, snapshot.generalizedFit,
            snapshot.term, &result, &message);
    } else if (snapshot.multipleImputation) {
        const std::string mode = snapshot.sourceKind.rfind("generalized", 0) == 0
            ? "gglm_pairwise" : "glm_pairwise";
        ok = RunRBackedMIPairwiseComparisons(
            snapshot.dataframe, mode,
            mode + "_derived_" + snapshot.sourceModelId,
            snapshot.response, snapshot.terms, snapshot.scope,
            snapshot.modelSpec, snapshot.term, &result, &message);
    } else if (snapshot.sourceKind == "mean_comparison") {
        rlispstat::core::GLMPairwiseComparisonRequest request;
        request.term = snapshot.term;
        request.confidenceLevel = snapshot.confidenceLevel;
        request.adjustment = snapshot.pairwiseAdjustment;
        ok = RunRBackedGLMPairwiseComparisons(
            snapshot.dataframe, const_cast<PlotModel *>(&snapshot.seed), snapshot.response,
            snapshot.terms, snapshot.termTypes, snapshot.linearFit,
            request, &result, &message);
    } else if (snapshot.sourceKind == "linear_single" ||
               snapshot.sourceKind == "linear_comparison") {
        rlispstat::core::GLMPairwiseComparisonRequest request;
        request.term = snapshot.term;
        ok = RunRBackedGLMPairwiseComparisons(
            snapshot.dataframe, const_cast<PlotModel *>(&snapshot.seed), snapshot.response,
            snapshot.terms, snapshot.termTypes, snapshot.linearFit,
            request, &result, &message);
    } else {
        message = "Live pairwise refresh is unavailable for this generalized model.";
        return false;
    }
    if (!ok) return false;
    const std::vector<int> &rowsUsed = snapshot.binaryRegression
        ? snapshot.generalizedFit.rowsUsed
        : (snapshot.sourceKind.rfind("generalized", 0) == 0
            ? snapshot.generalizedFit.rowsUsed : snapshot.linearFit.rowsUsed);
    link = BuildGLMPairwiseComparisonPlotLink(
        snapshot.group, snapshot.dataframe, snapshot.response,
        snapshot.term, rowsUsed, result);
    link.sourceModelKind = snapshot.sourceKind;
    link.sourceModelId = snapshot.sourceModelId;
    link.sourceModelRevision = snapshot.sourceRevision;
    link.sourceFitVersion = snapshot.sourceFitVersion;
    link.multipleImputation = snapshot.multipleImputation;
    link.poolingMethod = snapshot.multipleImputation ? result.method : std::string();
    link.binaryRegression = snapshot.binaryRegression;
    if (snapshot.binaryRegression) {
        link.binaryOddsRatio = snapshot.generalizedFit.binaryLink ==
            rlispstat::core::BinaryLink::Logit;
        link.rowsByComparison.assign(result.comparisons.size(), {});
        link.observations.clear();
        link.rowsByLevel.clear();
        const DataColumn *factor = FindDataColumnInDataFrame(snapshot.dataframe, snapshot.term);
        const DataColumn *response = FindDataColumnInDataFrame(snapshot.dataframe, snapshot.response);
        if (factor && response) {
            for (int row : rowsUsed) {
                if (row <= 0) continue;
                const std::size_t index = static_cast<std::size_t>(row - 1);
                if (index >= factor->values.size() || index >= response->values.size()) continue;
                const std::string &level = factor->values[index];
                const std::string &observed = response->values[index];
                if (DataCellIsMissing(level) || DataCellIsMissing(observed)) continue;
                const double binary = observed == snapshot.generalizedFit.responseCoding.eventValue ? 1.0 : 0.0;
                link.rowsByLevel[level].insert(row);
                link.observations.push_back({row, level, binary});
            }
            for (std::size_t index = 0; index < result.comparisons.size(); ++index) {
                for (const std::string &level : {result.comparisons[index].firstLevel,
                                                 result.comparisons[index].secondLevel}) {
                    auto found = link.rowsByLevel.find(level);
                    if (found != link.rowsByLevel.end())
                        link.rowsByComparison[index].insert(found->second.begin(), found->second.end());
                }
            }
        }
    }
    return true;
}

static void ApplyPairwiseDerivedRefreshOnMain(
    const PairwiseDerivedRefreshSnapshot &snapshot,
    const rlispstat::core::GLMPairwiseComparisonResult &result,
    const GLMPairwiseComparisonPlotLink &link)
{
    std::vector<id<GLMPairwiseComparisonPlotRefreshing>> views;
    std::vector<id<GLMPairwiseResultsRefreshing>> controllers;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        views = g_pairwiseComparisonPlotViews;
        controllers = g_pairwiseResultsControllers;
    }
    for (id<GLMPairwiseResultsRefreshing> item : controllers) {
        if ([item pairwiseSourceModelId] == snapshot.sourceModelId &&
            [item pairwiseSourceTerm] == snapshot.term) {
            [(GLMPairwiseResultsWindowController *)item applyDerivedResult:result plotLink:link];
        }
    }
    for (id<GLMPairwiseComparisonPlotRefreshing> item : views) {
        if ([item pairwiseSourceModelId] != snapshot.sourceModelId ||
            [item pairwiseSourceTerm] != snapshot.term) continue;
        if ([item isKindOfClass:[GLMPairwiseComparisonPlotView class]]) {
            [(GLMPairwiseComparisonPlotView *)item applyDerivedResult:result plotLink:link];
        } else if ([item isKindOfClass:[GLMPairwiseObservedBoxplotView class]]) {
            [(GLMPairwiseObservedBoxplotView *)item applyDerivedPlotLink:link];
        }
    }
    std::vector<BoxplotView *> boxplotViews;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (auto &entry : g_plots) {
            PlotModel *plot = entry.second;
            if (!plot || !plot->isRegressionDerivedPlot ||
                plot->regressionDerivedKind != "pairwise_observed_boxplot" ||
                plot->regressionDerivedSourceModelId != snapshot.sourceModelId ||
                plot->regressionDerivedTerm != snapshot.term) continue;
            plot->group = link.group;
            plot->xLabel = link.factor;
            plot->yLabel = link.response;
            plot->title = "Distribution of " + link.response + " by " + link.factor;
            plot->boxplotCategories = link.levels;
            plot->boxplotDefinedCategories = link.levels;
            plot->boxplotPoints.clear();
            for (const GLMPairwiseComparisonPlotLink::Observation &observation : link.observations) {
                if (observation.row > 0 && std::isfinite(observation.response)) {
                    plot->boxplotPoints.push_back(
                        BoxplotPoint{observation.response, observation.level, observation.row});
                }
            }
            plot->regressionDerivedSourceKind = link.sourceModelKind;
            plot->regressionDerivedSourceRevision = link.sourceModelRevision;
            plot->regressionDerivedSourceFitVersion = link.sourceFitVersion;
            if (BoxplotView *view = BoxplotViewForPlotUnlocked(plot->id))
                boxplotViews.push_back(view);
        }
    }
    for (BoxplotView *view : boxplotViews) {
        [view setNeedsDisplay:YES];
        [view displayIfNeeded];
    }
}

static void ClearPairwiseDerivedOutputsOnMain(
    const std::string &sourceModelId,
    const std::string &term,
    const std::string &message)
{
    std::vector<id<GLMPairwiseComparisonPlotRefreshing>> views;
    std::vector<id<GLMPairwiseResultsRefreshing>> controllers;
    std::vector<BoxplotView *> boxplotViews;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        views = g_pairwiseComparisonPlotViews;
        controllers = g_pairwiseResultsControllers;
        for (auto &entry : g_plots) {
            PlotModel *plot = entry.second;
            if (!plot || !plot->isRegressionDerivedPlot ||
                plot->regressionDerivedKind != "pairwise_observed_boxplot" ||
                plot->regressionDerivedSourceModelId != sourceModelId ||
                plot->regressionDerivedTerm != term) continue;
            plot->boxplotPoints.clear();
            plot->boxplotCategories.clear();
            plot->boxplotDefinedCategories.clear();
            if (BoxplotView *view = BoxplotViewForPlotUnlocked(plot->id))
                boxplotViews.push_back(view);
        }
    }
    for (id<GLMPairwiseResultsRefreshing> item : controllers) {
        if ([item pairwiseSourceModelId] == sourceModelId &&
            [item pairwiseSourceTerm] == term)
            [(GLMPairwiseResultsWindowController *)item applyDerivedFailure:message];
    }
    for (id<GLMPairwiseComparisonPlotRefreshing> item : views) {
        if ([item pairwiseSourceModelId] != sourceModelId ||
            [item pairwiseSourceTerm] != term) continue;
        if ([item isKindOfClass:[GLMPairwiseComparisonPlotView class]])
            [(GLMPairwiseComparisonPlotView *)item clearDerivedResult];
        else if ([item isKindOfClass:[GLMPairwiseObservedBoxplotView class]])
            [(GLMPairwiseObservedBoxplotView *)item clearDerivedResult];
    }
    for (BoxplotView *view : boxplotViews) {
        [view setNeedsDisplay:YES];
        [view displayIfNeeded];
    }
}

static void MarkPairwiseDerivedResultsPendingOnMain(
    const std::string &sourceModelId, const std::string &message)
{
    std::vector<id<GLMPairwiseResultsRefreshing>> controllers;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        controllers = g_pairwiseResultsControllers;
    }
    for (id<GLMPairwiseResultsRefreshing> item : controllers)
        if ([item pairwiseSourceModelId] == sourceModelId)
            [(GLMPairwiseResultsWindowController *)item markDerivedPending:message];
}

static void RefreshPairwiseResultsControllerFromSource(
    GLMPairwiseResultsWindowController *controller)
{
    if (!controller) return;
    RefreshPairwiseDerivedLinkFromSource([controller derivedPlotLink]);
}

static void RefreshPairwiseDerivedLinkFromSource(
    const GLMPairwiseComparisonPlotLink &oldLink)
{
    PairwiseDerivedRefreshSnapshot snapshot;
    std::string message;
    if (!BuildPairwiseDerivedRefreshSnapshot(oldLink, snapshot, message)) {
        ClearPairwiseDerivedOutputsOnMain(
            oldLink.sourceModelId, oldLink.factor, message);
        return;
    }
    if (snapshot.sourceKind == "mean_comparison")
        MarkPairwiseDerivedResultsPendingOnMain(
            snapshot.sourceModelId,
            "Updating for the current scope; previous comparison results remain visible.");
    else ClearPairwiseDerivedOutputsOnMain(
        snapshot.sourceModelId, snapshot.term,
        "Recalculating from the updated source model…");
    std::thread([snapshot]() mutable {
        rlispstat::core::GLMPairwiseComparisonResult result;
        GLMPairwiseComparisonPlotLink link;
        std::string message;
        const bool ok = ExecutePairwiseDerivedRefresh(snapshot, result, link, message);
        dispatch_async(dispatch_get_main_queue(), ^{
            if (!PairwiseDerivedSnapshotIsCurrent(snapshot)) return;
            if (!ok) {
                if (snapshot.sourceKind == "mean_comparison")
                    MarkPairwiseDerivedResultsPendingOnMain(
                        snapshot.sourceModelId,
                        "Update failed: " + message + " Previous results remain visible.");
                else ClearPairwiseDerivedOutputsOnMain(
                    snapshot.sourceModelId, snapshot.term, message);
                return;
            }
            ApplyPairwiseDerivedRefreshOnMain(snapshot, result, link);
        });
    }).detach();
}

static void RefreshPairwiseDerivedOutputsForModelNow(const std::string &modelId)
{
    if (modelId.empty()) return;
    std::vector<id<GLMPairwiseResultsRefreshing>> controllers;
    std::vector<id<GLMPairwiseComparisonPlotRefreshing>> views;
    std::vector<GLMPairwiseComparisonPlotLink> links;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        controllers = g_pairwiseResultsControllers;
        views = g_pairwiseComparisonPlotViews;
        for (const auto &entry : g_plots) {
            const PlotModel *plot = entry.second;
            if (!plot || !plot->isRegressionDerivedPlot ||
                plot->regressionDerivedKind != "pairwise_observed_boxplot" ||
                plot->regressionDerivedSourceModelId != modelId) continue;
            GLMPairwiseComparisonPlotLink link;
            link.sourceModelKind = plot->regressionDerivedSourceKind;
            link.sourceModelId = plot->regressionDerivedSourceModelId;
            link.sourceModelRevision = plot->regressionDerivedSourceRevision;
            link.sourceFitVersion = plot->regressionDerivedSourceFitVersion;
            link.group = plot->group;
            link.factor = plot->regressionDerivedTerm;
            links.push_back(link);
        }
    }
    // One dependency launches the shared recalculation for every table and
    // graph with the same source-model/term identity.  A table need not remain
    // open: a surviving derived graph is sufficient to keep the live link.
    std::set<std::string> refreshedTerms;
    for (id<GLMPairwiseResultsRefreshing> item : controllers) {
        if ([item pairwiseSourceModelId] != modelId) continue;
        const std::string term = [item pairwiseSourceTerm];
        if (refreshedTerms.insert(term).second) {
            RefreshPairwiseDerivedLinkFromSource(
                [(GLMPairwiseResultsWindowController *)item derivedPlotLink]);
        }
    }
    for (id<GLMPairwiseComparisonPlotRefreshing> item : views) {
        if ([item pairwiseSourceModelId] != modelId) continue;
        const std::string term = [item pairwiseSourceTerm];
        if (!refreshedTerms.insert(term).second) continue;
        if ([item isKindOfClass:[GLMPairwiseComparisonPlotView class]]) {
            RefreshPairwiseDerivedLinkFromSource(
                [(GLMPairwiseComparisonPlotView *)item derivedPlotLink]);
        } else if ([item isKindOfClass:[GLMPairwiseObservedBoxplotView class]]) {
            RefreshPairwiseDerivedLinkFromSource(
                [(GLMPairwiseObservedBoxplotView *)item derivedPlotLink]);
        }
    }
    for (const GLMPairwiseComparisonPlotLink &link : links) {
        if (refreshedTerms.insert(link.factor).second)
            RefreshPairwiseDerivedLinkFromSource(link);
    }
}

struct InteractionDerivedRefreshSnapshot {
    RegressionInteractionDerivedLink link;
    DataFrameModel dataframe;
    PlotModel seed;
    std::string response;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    std::set<std::string> centeredPredictors;
    std::string scope;
    std::string modelSpec;
    GLMFitSummary linearFit;
    bool rBacked = false;
    bool hasReport = false;
    bool hasPlot = false;
    std::string plotFocal;
};

static bool BuildInteractionDerivedRefreshSnapshot(
    const RegressionInteractionDerivedLink &oldLink,
    InteractionDerivedRefreshSnapshot &snapshot,
    std::string &message,
    bool requireInteraction = true)
{
    snapshot.link = oldLink;
    if (oldLink.sourceModelId.empty() || oldLink.term.empty()) {
        message = "This interaction result is not attached to a live regression model.";
        return false;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *dataframe = FindDataFrameUnlockedConst(oldLink.group);
    if (!dataframe) {
        message = "The source dataset is no longer available.";
        return false;
    }
    snapshot.dataframe = *dataframe;
    if (oldLink.sourceModelKind == "linear_single") {
        auto stateIt = g_groupModels.find(oldLink.sourceModelId);
        auto fitIt = g_precomputedLinearModelFits.find(oldLink.sourceModelId);
        PlotModel *seed = FirstPlotForGroupUnlocked(oldLink.group);
        if (stateIt == g_groupModels.end() || fitIt == g_precomputedLinearModelFits.end() ||
            !fitIt->second.ok || stateIt->second.isStale || !seed) {
            message = "The source linear model has no accepted fit.";
            return false;
        }
        const GroupModelState &state = stateIt->second;
        snapshot.link.sourceModelRevision = state.modelVersion;
        snapshot.link.sourceFitVersion = state.fitVersion;
        snapshot.seed = *seed;
        snapshot.response = state.response;
        snapshot.terms = state.terms;
        snapshot.termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        snapshot.centeredPredictors = state.centeredPredictors;
        snapshot.scope = ScopeForModelSpecification(state);
        snapshot.modelSpec = EncodeStandaloneLinearMISpec(
            snapshot.termTypes, state.centeredPredictors,
            state.factorReferenceLevels,
            RowsForModelSpecificationUnlocked(oldLink.group, state));
        snapshot.linearFit = fitIt->second;
        // Interaction output uses the shared R post-estimation route for both
        // ordinary and multiply-imputed linear models.  Besides keeping the
        // presentation identical across platforms, this route supports exact
        // three-way specifications; the legacy portable renderer is limited
        // to two components.
        snapshot.rBacked = true;
    } else if (oldLink.sourceModelKind == "generalized_single") {
        auto stateIt = g_generalizedGLMs.find(oldLink.sourceModelId);
        if (stateIt == g_generalizedGLMs.end() || !stateIt->second.ok ||
            stateIt->second.rFitPending ||
            stateIt->second.fitVersion < stateIt->second.modelVersion) {
            message = "The source generalized model has no accepted fit.";
            return false;
        }
        const GeneralizedGLMState &state = stateIt->second;
        snapshot.link.sourceModelRevision = state.modelVersion;
        snapshot.link.sourceFitVersion = state.fitVersion;
        snapshot.seed = state.seed;
        snapshot.response = state.response;
        snapshot.terms = state.terms;
        snapshot.termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        snapshot.scope = ScopeForCapturedAnalysisScope(
            state.dataScope, state.dataScopeCaptured, state.scope);
        snapshot.modelSpec = EncodeStandaloneGeneralizedMISpec(
            GeneralizedGLMTaskForState(state, state.rFitGeneration));
        snapshot.rBacked = true;
    } else if (oldLink.sourceModelKind == "linear_comparison") {
        RegressionComparisonState *state = nullptr;
        RegressionComparisonModel *model = nullptr;
        if (!FindRegressionComparisonModelById(oldLink.sourceModelId, &state, &model) ||
            !state || !model || model->isStale || !model->fit.ok) {
            message = "The source comparison model has no accepted fit.";
            return false;
        }
        const rlispstat::core::ModelSpecification specification =
            rlispstat::core::EffectiveRegressionComparisonModelSpecification(*state, *model);
        snapshot.link.sourceModelRevision = model->modelVersion;
        snapshot.link.sourceFitVersion = model->fitVersion;
        snapshot.seed = state->seed;
        snapshot.response = specification.response.empty() ? state->response : specification.response;
        snapshot.terms = specification.terms;
        snapshot.termTypes = specification.termTypes;
        snapshot.centeredPredictors = specification.centeredPredictors;
        snapshot.scope = specification.scope.empty() ? state->scope : specification.scope;
        snapshot.modelSpec = EncodeStandaloneLinearMISpec(
            specification.termTypes, specification.centeredPredictors,
            specification.factorReferenceLevels,
            RowsForCapturedAnalysisScope(state->dataScope, state->dataScopeCaptured));
        snapshot.linearFit = model->fit;
        snapshot.rBacked = true;
    } else if (oldLink.sourceModelKind == "generalized_comparison") {
        GeneralizedComparisonState *state = nullptr;
        GeneralizedComparisonModel *model = nullptr;
        if (!FindGeneralizedComparisonModelById(oldLink.sourceModelId, &state, &model) ||
            !state || !model || model->isStale || !model->fit.ok) {
            message = "The source generalized-comparison model has no accepted fit.";
            return false;
        }
        const MainRGeneralizedGLMTask task =
            GeneralizedGLMTaskForComparisonModel(*state, *model);
        snapshot.link.sourceModelRevision = model->modelVersion;
        snapshot.link.sourceFitVersion = model->fitVersion;
        snapshot.seed = state->seed;
        snapshot.response = task.response;
        snapshot.terms = task.terms;
        snapshot.termTypes = task.termTypes;
        snapshot.scope = task.scope;
        snapshot.modelSpec = EncodeStandaloneGeneralizedMISpec(task);
        snapshot.rBacked = true;
    } else {
        message = "The source regression type is not registered for live interaction output.";
        return false;
    }
    if ((requireInteraction && !IsInteractionTerm(oldLink.term)) ||
        std::find(snapshot.terms.begin(), snapshot.terms.end(), oldLink.term) ==
            snapshot.terms.end()) {
        message = requireInteraction
            ? "The source model no longer contains this interaction."
            : "The source model no longer contains this predictor.";
        return false;
    }
    return true;
}

static bool InteractionDerivedSnapshotIsCurrent(
    const InteractionDerivedRefreshSnapshot &snapshot)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const RegressionInteractionDerivedLink &link = snapshot.link;
    bool sourceCurrent = false;
    if (link.sourceModelKind == "linear_single") {
        auto it = g_groupModels.find(link.sourceModelId);
        sourceCurrent = it != g_groupModels.end() && !it->second.isStale &&
            it->second.modelVersion == link.sourceModelRevision &&
            it->second.fitVersion == link.sourceFitVersion;
    } else if (link.sourceModelKind == "generalized_single") {
        auto it = g_generalizedGLMs.find(link.sourceModelId);
        sourceCurrent = it != g_generalizedGLMs.end() && it->second.ok &&
            !it->second.rFitPending &&
            it->second.modelVersion == link.sourceModelRevision &&
            it->second.fitVersion == link.sourceFitVersion;
    } else if (link.sourceModelKind == "linear_comparison") {
        RegressionComparisonState *state = nullptr;
        RegressionComparisonModel *model = nullptr;
        sourceCurrent = FindRegressionComparisonModelById(link.sourceModelId, &state, &model) &&
            model && !model->isStale && model->fit.ok &&
            model->modelVersion == link.sourceModelRevision &&
            model->fitVersion == link.sourceFitVersion;
    } else if (link.sourceModelKind == "generalized_comparison") {
        GeneralizedComparisonState *state = nullptr;
        GeneralizedComparisonModel *model = nullptr;
        sourceCurrent = FindGeneralizedComparisonModelById(link.sourceModelId, &state, &model) &&
            model && !model->isStale && model->fit.ok &&
            model->modelVersion == link.sourceModelRevision &&
            model->fitVersion == link.sourceFitVersion;
    }
    if (!sourceCurrent || !snapshot.hasReport) return sourceCurrent;
    return std::any_of(g_interactionReportWindows.begin(),
                       g_interactionReportWindows.end(),
        [&](const GLMInteractionReportWindowEntry &entry) {
            return entry.link.sourceModelId == link.sourceModelId &&
                entry.link.term == link.term &&
                entry.link.optionGeneration == link.optionGeneration;
        });
}

static bool ApplyStoredPartialRegressionPlot(PlotModel *plot)
{
    if (!plot || plot->regressionPartialPointsByImputation.empty()) return false;
    rlispstat::core::RegressionPartialPlotResult result;
    result.ok = true;
    result.term = plot->regressionDerivedTerm;
    result.residualType = plot->regressionPartialResidualType;
    result.contributionScale = plot->regressionPartialContributionScale;
    result.imputationCount = static_cast<int>(
        plot->regressionPartialPointsByImputation.size());
    result.pointsByImputation = plot->regressionPartialPointsByImputation;
    plot->diagnosticImputationCount = result.imputationCount;
    return ApplyDiagnosticPlotData(
        plot, rlispstat::core::BuildRegressionPartialPlotData(
            result, plot->diagnosticImputationIndex,
            plot->diagnosticShowImputationUncertainty));
}

static bool RefreshPartialRegressionPlotFromSource(PlotModel *plot,
                                                    std::string *error = nullptr)
{
    if (!plot || !plot->isRegressionDerivedPlot ||
        plot->regressionDerivedKind != "partial_regression_plot") return false;
    RegressionInteractionDerivedLink oldLink;
    oldLink.sourceModelKind = plot->regressionDerivedSourceKind;
    oldLink.sourceModelId = plot->regressionDerivedSourceModelId;
    oldLink.sourceModelRevision = plot->regressionDerivedSourceRevision;
    oldLink.sourceFitVersion = plot->regressionDerivedSourceFitVersion;
    oldLink.group = plot->group;
    oldLink.term = plot->regressionDerivedTerm;
    oldLink.title = plot->title;
    InteractionDerivedRefreshSnapshot snapshot;
    std::string message;
    if (!BuildInteractionDerivedRefreshSnapshot(
            oldLink, snapshot, message, false)) {
        if (error) *error = message;
        return false;
    }
    const bool generalized =
        snapshot.link.sourceModelKind.rfind("generalized", 0) == 0;
    rlispstat::core::RegressionPartialPlotResult result;
    const std::string requestedResidual = plot->displayedResidualType.empty()
        ? (generalized ? "working" : "raw") : plot->displayedResidualType;
    const bool ok = RunRBackedPartialRegressionPlot(
        snapshot.dataframe,
        generalized ? "gglm_partial_plot" : "glm_partial_plot",
        (generalized ? "gglm_partial_derived_" : "glm_partial_derived_") +
            snapshot.link.sourceModelId,
        snapshot.response, snapshot.terms, snapshot.scope, snapshot.modelSpec,
        snapshot.link.term, requestedResidual, &result, &message);
    if (!ok || !InteractionDerivedSnapshotIsCurrent(snapshot)) {
        if (error) *error = ok
            ? "The source model changed while the partial plot was being calculated."
            : message;
        return false;
    }
    plot->regressionPartialPointsByImputation = result.pointsByImputation;
    plot->regressionPartialResidualType = result.residualType;
    plot->regressionPartialContributionScale = result.contributionScale;
    plot->regressionPartialAvailableTerms = result.availableTerms;
    plot->displayedResidualType = result.residualType;
    plot->diagnosticAvailableResidualTypes = result.availableResidualTypes;
    plot->regressionDerivedSourceRevision = snapshot.link.sourceModelRevision;
    plot->regressionDerivedSourceFitVersion = snapshot.link.sourceFitVersion;
    plot->displayedFitVersion = snapshot.link.sourceFitVersion;
    plot->displayedDiagnosticsVersion = snapshot.link.sourceFitVersion;
    plot->diagnosticImputationCount = std::max(1, result.imputationCount);
    rlispstat::core::ModelSpecification specification;
    specification.response = snapshot.response;
    specification.terms = snapshot.terms;
    plot->diagnosticRowsWithImputedModelInputs =
        rlispstat::core::RowsWithImputedModelInputs(
            snapshot.dataframe, specification);
    if (!ApplyStoredPartialRegressionPlot(plot)) return false;
    RegisterPartialRegressionCodeReference(plot, result);
    return true;
}

static void ClearInteractionDerivedOutputsOnMain(
    const std::string &modelId,
    const std::string &term,
    const std::string &message,
    bool clearPlots = true)
{
    std::vector<GLMInteractionReportWindowEntry> reports;
    std::vector<ScatterView *> views;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        reports = g_interactionReportWindows;
        for (const auto &entry : g_plots) {
            PlotModel *plot = entry.second;
            if (!clearPlots || !plot || !plot->isRegressionDerivedPlot ||
                !rlispstat::core::IsPooledRegressionEffectPlot(*plot) ||
                plot->regressionDerivedSourceModelId != modelId ||
                plot->regressionDerivedTerm != term) continue;
            plot->points.clear();
            plot->interactionPlotLines.clear();
            plot->interactionXTicks.clear();
            plot->interactionXTickRows.clear();
            plot->title = "Effect: " + term + " — unavailable";
            for (ScatterView *view : g_views) if (view.model == plot) views.push_back(view);
        }
    }
    for (const GLMInteractionReportWindowEntry &entry : reports) {
        if (entry.link.sourceModelId == modelId && entry.link.term == term)
            ReplaceGLMInteractionReportBody(entry.scroll, message);
    }
    for (ScatterView *view : views) {
        [view setNeedsDisplay:YES];
        [view displayIfNeeded];
    }
}

static void RegisterInteractionReportCodeReference(
    const RegressionInteractionDerivedLink &link, const std::string &body)
{
    auto &application = MacCommandDispatcher().applicationState();
    const auto *source = application.regressionSourceOutputCodeReference(
        link.sourceModelKind, link.sourceModelId);
    if (!source) return;
    rlispstat::core::GLMInteractionReport report;
    if (!rlispstat::core::ParseGLMInteractionReportText(SplitLines(body), report)) return;
    auto reference = rlispstat::core::RegressionInteractionReportCodeReference(
        "interaction-report:" + link.sourceModelId + ":" + link.term, report, *source);
    if (!reference.outputId.empty()) application.registerOutputCodeReference(reference);
}

static void ApplyInteractionDerivedRefreshOnMain(
    const InteractionDerivedRefreshSnapshot &snapshot,
    const std::string &body,
    const rlispstat::core::RegressionInteractionPlotResult *plotResult)
{
    std::vector<GLMInteractionReportWindowEntry> reports;
    std::vector<ScatterView *> views;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        reports = g_interactionReportWindows;
        if (plotResult) {
            for (const auto &entry : g_plots) {
                PlotModel *plot = entry.second;
                if (!plot || !plot->isRegressionDerivedPlot ||
                    !rlispstat::core::IsPooledRegressionEffectPlot(*plot) ||
                    plot->regressionDerivedSourceModelId != snapshot.link.sourceModelId ||
                    plot->regressionDerivedTerm != snapshot.link.term) continue;
                rlispstat::core::RegressionInteractionPlotResult resolved = *plotResult;
                rlispstat::core::PopulateRegressionInteractionLegendRows(resolved, snapshot.dataframe);
                plot->group = snapshot.link.group;
                plot->points.clear();
                plot->interactionPlotLines = resolved.lines;
                plot->interactionXTicks = resolved.xTicks;
                plot->interactionXTickRows = resolved.xTickCaseIds;
                rlispstat::core::ApplyRegressionInteractionPresentation(
                    *plot, resolved, snapshot.response);
                rlispstat::core::ApplyRegressionInteractionVariableLabels(
                    *plot, resolved, snapshot.dataframe, snapshot.response);
                plot->rExportTheme = MacCommandDispatcher().plotTheme();
                // A source refit must not discard display choices made in the
                // effect-plot window.
                plot->overlays.clear();
                for (const InteractionPlotLine &line : plot->interactionPlotLines)
                    plot->points.insert(plot->points.end(), line.points.begin(), line.points.end());
                plot->displayedFitVersion = snapshot.link.sourceFitVersion;
                plot->regressionDerivedSourceRevision = snapshot.link.sourceModelRevision;
                plot->regressionDerivedSourceFitVersion = snapshot.link.sourceFitVersion;
                if (const auto *source = MacCommandDispatcher().applicationState()
                        .regressionSourceOutputCodeReference(
                            snapshot.link.sourceModelKind,
                            snapshot.link.sourceModelId)) {
                    plot->codeReference =
                        rlispstat::core::RegressionInteractionPlotCodeReference(
                            *plot, resolved, *source);
                    MacCommandDispatcher().applicationState()
                        .registerOutputCodeReference(plot->codeReference);
                }
                ComputeRanges(plot);
                rlispstat::core::ApplyRegressionInteractionAxisRange(*plot);
                for (ScatterView *view : g_views) if (view.model == plot) views.push_back(view);
            }
        }
    }
    if (!body.empty()) {
        RegisterInteractionReportCodeReference(snapshot.link, body);
        for (GLMInteractionReportWindowEntry &entry : reports) {
            if (entry.link.sourceModelId != snapshot.link.sourceModelId ||
                entry.link.term != snapshot.link.term) continue;
            [entry.window setTitle:SafeNSStringFromUTF8(entry.link.title)];
            ReplaceGLMInteractionReportBody(entry.scroll, body);
        }
        std::lock_guard<std::mutex> lock(g_mutex);
        for (GLMInteractionReportWindowEntry &entry : g_interactionReportWindows) {
            if (entry.link.sourceModelId == snapshot.link.sourceModelId &&
                entry.link.term == snapshot.link.term) {
                const std::string title = entry.link.title;
                entry.link = snapshot.link;
                if (!title.empty()) entry.link.title = title;
            }
        }
    }
    for (ScatterView *view : views) {
        [view setNeedsDisplay:YES];
        [view displayIfNeeded];
    }
}

static void RefreshInteractionDerivedLinkFromSource(
    const RegressionInteractionDerivedLink &oldLink,
    bool hasReport,
    bool hasPlot,
    const std::string &plotFocal = std::string())
{
    InteractionDerivedRefreshSnapshot snapshot;
    std::string message;
    // The same R-backed window is used for a main-effect plot and for an
    // interaction plot.  Requiring a colon here rejects valid simple effects
    // (for example a bounded-count probability by gender) before R can
    // recalculate them, leaving the window indefinitely in its pending state.
    if (!BuildInteractionDerivedRefreshSnapshot(
            oldLink, snapshot, message, false)) {
        ClearInteractionDerivedOutputsOnMain(oldLink.sourceModelId, oldLink.term, message);
        return;
    }
    snapshot.hasReport = hasReport;
    snapshot.hasPlot = hasPlot;
    snapshot.plotFocal = plotFocal;
    ClearInteractionDerivedOutputsOnMain(
        oldLink.sourceModelId, oldLink.term,
        "Recalculating from the updated source model…", hasPlot);
    std::thread([snapshot]() mutable {
        std::string body;
        std::string message;
        rlispstat::core::RegressionInteractionPlotResult plotResult;
        bool ok = true;
        if (snapshot.hasReport) {
            if (snapshot.rBacked) {
                const std::string mode = snapshot.link.sourceModelKind.rfind("generalized", 0) == 0
                    ? "gglm_interaction" : "glm_interaction";
                ok = RunRBackedMIInteractionReport(
                    snapshot.dataframe, mode,
                    mode + "_derived_" + snapshot.link.sourceModelId,
                    snapshot.response, snapshot.terms, snapshot.scope,
                    snapshot.modelSpec, snapshot.link.term, &body, &message,
                    snapshot.link.emmReferenceTestEnabled
                        ? snapshot.link.emmTestReference
                        : std::numeric_limits<double>::quiet_NaN(),
                    snapshot.link);
            } else {
                const GLMInteractionReport report = rlispstat::core::BuildGLMInteractionReport(
                    snapshot.seed, &snapshot.dataframe, snapshot.link.term,
                    snapshot.terms, snapshot.termTypes, snapshot.linearFit,
                    0.95, snapshot.centeredPredictors,
                    snapshot.link.emmReferenceTestEnabled
                        ? snapshot.link.emmTestReference
                        : std::numeric_limits<double>::quiet_NaN());
                body = GLMInteractionReportText(report);
                ok = !body.empty();
                if (!ok) message = report.message;
            }
        }
        if (ok && snapshot.hasPlot) {
            const std::string mode = snapshot.link.sourceModelKind.rfind("generalized", 0) == 0
                ? "gglm_interaction_plot" : "glm_interaction_plot";
            ok = RunRBackedInteractionPlot(
                snapshot.dataframe, mode,
                mode + "_derived_" + snapshot.link.sourceModelId,
                snapshot.response, snapshot.terms, snapshot.scope,
                snapshot.modelSpec, snapshot.link.term, &plotResult, &message,
                snapshot.plotFocal, snapshot.link);
        }
        dispatch_async(dispatch_get_main_queue(), ^{
            if (!InteractionDerivedSnapshotIsCurrent(snapshot)) return;
            if (!ok) {
                ClearInteractionDerivedOutputsOnMain(
                    snapshot.link.sourceModelId, snapshot.link.term, message);
                return;
            }
            ApplyInteractionDerivedRefreshOnMain(
                snapshot, body, snapshot.hasPlot ? &plotResult : nullptr);
        });
    }).detach();
}

static void RefreshInteractionDerivedOutputsForModelNow(const std::string &modelId)
{
    if (modelId.empty()) return;
    struct Dependency {
        RegressionInteractionDerivedLink link;
        bool hasReport = false;
        bool hasPlot = false;
        std::string plotFocal;
    };
    std::map<std::string, Dependency> dependencies;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        for (const GLMInteractionReportWindowEntry &entry : g_interactionReportWindows) {
            if (entry.link.sourceModelId != modelId) continue;
            Dependency &dependency = dependencies[entry.link.term];
            dependency.link = entry.link;
            dependency.hasReport = true;
        }
        for (const auto &entry : g_plots) {
            const PlotModel *plot = entry.second;
            if (!plot || !plot->isRegressionDerivedPlot ||
                !rlispstat::core::IsPooledRegressionEffectPlot(*plot) ||
                plot->regressionDerivedSourceModelId != modelId) continue;
            bool hasOpenView = false;
            for (ScatterView *view : g_views) {
                NSWindow *window = view ? [view window] : nil;
                if (view && view.model == plot && window && [window isVisible]) {
                    hasOpenView = true;
                    break;
                }
            }
            if (!hasOpenView) continue;
            Dependency &dependency = dependencies[plot->regressionDerivedTerm];
            dependency.link.sourceModelKind = plot->regressionDerivedSourceKind;
            dependency.link.sourceModelId = plot->regressionDerivedSourceModelId;
            dependency.link.sourceModelRevision = plot->regressionDerivedSourceRevision;
            dependency.link.sourceFitVersion = plot->regressionDerivedSourceFitVersion;
            dependency.link.group = plot->group;
            dependency.link.term = plot->regressionDerivedTerm;
            dependency.link.binaryEffect = plot->regressionBinaryProbability;
            dependency.link.boundedCountEffect = plot->regressionBoundedCount;
            dependency.link.effectQuantity = plot->regressionEffectQuantity;
            dependency.link.effectAdjustment = plot->regressionEffectAdjustment;
            dependency.link.effectPresentation = plot->regressionEffectPresentation;
            dependency.link.confidenceLevel = plot->regressionConfidenceLevel;
            dependency.hasPlot = true;
            dependency.plotFocal = plot->xLabel;
        }
    }
    for (const auto &entry : dependencies) {
        RefreshInteractionDerivedLinkFromSource(
            entry.second.link, entry.second.hasReport, entry.second.hasPlot,
            entry.second.plotFocal);
    }
}

static void SetRegressionEffectXAxisOnMain(PlotModel *plot,
                                           const std::string &focal)
{
    if (!plot || plot->kind != "glm_interaction" || focal.empty() ||
        focal == plot->xLabel) return;
    const std::vector<std::string> variables =
        SplitInteractionTerm(plot->glmInteractionTerm);
    if (std::find(variables.begin(), variables.end(), focal) == variables.end()) {
        ShowWorkbenchMessageOnMain(@"Effect Plot",
            @"The requested horizontal-axis variable is not part of this effect.");
        return;
    }
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = plot->regressionDerivedSourceKind;
    link.sourceModelId = plot->regressionDerivedSourceModelId;
    link.sourceModelRevision = plot->regressionDerivedSourceRevision;
    link.sourceFitVersion = plot->regressionDerivedSourceFitVersion;
    link.group = plot->group;
    link.term = plot->regressionDerivedTerm.empty()
        ? plot->glmInteractionTerm : plot->regressionDerivedTerm;
    link.binaryEffect = plot->regressionBinaryProbability;
    link.boundedCountEffect = plot->regressionBoundedCount;
    link.effectQuantity = plot->regressionEffectQuantity;
    link.effectAdjustment = plot->regressionEffectAdjustment;
    link.effectPresentation = plot->regressionEffectPresentation;
    link.confidenceLevel = plot->regressionConfidenceLevel;
    InteractionDerivedRefreshSnapshot snapshot;
    std::string message;
    if (!BuildInteractionDerivedRefreshSnapshot(link, snapshot, message)) {
        ShowWorkbenchMessageOnMain(@"Effect Plot", ToNSString(message));
        return;
    }
    const std::string plotId = plot->id;
    const std::string analysisId = plot->glmModelId;
    const std::uint64_t generation = ++plot->regressionEffectRequestGeneration;
    plot->title = "Effect: " + link.term + " — recalculating for " + focal + " on X…";
    RedrawPlotOnMain(plotId);
    std::thread([snapshot, focal, plotId, analysisId, generation]() mutable {
        const bool generalized =
            snapshot.link.sourceModelKind.rfind("generalized", 0) == 0;
        const std::string mode = generalized
            ? "gglm_interaction_plot" : "glm_interaction_plot";
        rlispstat::core::RegressionInteractionPlotResult result;
        std::string error;
        const bool ok = RunRBackedInteractionPlot(
            snapshot.dataframe, mode, analysisId,
            snapshot.response, snapshot.terms, snapshot.scope,
            snapshot.modelSpec, snapshot.link.term, &result, &error, focal,
            snapshot.link);
        dispatch_async(dispatch_get_main_queue(), ^{
            PlotModel *current = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_plots.find(plotId);
                if (found != g_plots.end()) current = found->second;
            }
            if (!current || current->regressionEffectRequestGeneration != generation ||
                !InteractionDerivedSnapshotIsCurrent(snapshot)) return;
            if (!ok) {
                current->title = "Effect: " + snapshot.link.term + " — unavailable";
                RedrawPlotOnMain(plotId);
                ShowWorkbenchMessageOnMain(@"Effect Plot", ToNSString(error));
                return;
            }
            std::string applyMessage;
            if (ApplyRBackedInteractionPlotResult(
                    snapshot.dataframe, analysisId, snapshot.response,
                    snapshot.link.term, std::move(result), &applyMessage,
                    snapshot.link).empty()) {
                ShowWorkbenchMessageOnMain(@"Effect Plot", ToNSString(applyMessage));
            }
        });
    }).detach();
}

static void SetRegressionEffectOptionOnMain(
    PlotModel *plot,
    CommandAction action,
    const std::string &value)
{
    if (!plot || plot->kind != "glm_interaction" ||
        (!plot->regressionBinaryProbability && !plot->regressionBoundedCount) ||
        value.empty()) return;
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = plot->regressionDerivedSourceKind;
    link.sourceModelId = plot->regressionDerivedSourceModelId;
    link.sourceModelRevision = plot->regressionDerivedSourceRevision;
    link.sourceFitVersion = plot->regressionDerivedSourceFitVersion;
    link.group = plot->group;
    link.term = plot->regressionDerivedTerm.empty()
        ? plot->glmInteractionTerm : plot->regressionDerivedTerm;
    link.binaryEffect = plot->regressionBinaryProbability;
    link.boundedCountEffect = plot->regressionBoundedCount;
    link.effectQuantity = plot->regressionEffectQuantity;
    link.effectAdjustment = plot->regressionEffectAdjustment;
    link.effectPresentation = plot->regressionEffectPresentation;
    link.confidenceLevel = plot->regressionConfidenceLevel;
    if (action == CommandAction::SetRegressionEffectQuantity) {
        if (plot->regressionBoundedCount) {
            if (plot->regressionCeilingHurdle) {
                if (value != "overall_expected_score" &&
                    value != "perfect_score_probability" &&
                    value != "conditional_expected_score") return;
            } else if (value != "predicted_probability" &&
                       value != "expected_count") return;
        } else if (value != "predicted_probability" &&
                   value != "probability_difference") return;
        link.effectQuantity = value;
    } else if (action == CommandAction::SetRegressionEffectAdjustment) {
        if (value != "average_sample" && value != "reference_profile") return;
        link.effectAdjustment = value;
    } else if (action == CommandAction::SetRegressionEffectPresentation) {
        if (value != "percentage" && value != "probability") return;
        link.effectPresentation = value;
    } else if (action == CommandAction::SetRegressionEffectConfidence) {
        char *end = nullptr;
        const double level = std::strtod(value.c_str(), &end);
        if (end == value.c_str() || (end && *end) || !std::isfinite(level) ||
            level <= 0.0 || level >= 1.0) return;
        link.confidenceLevel = level;
    } else return;
    link.optionGeneration = ++g_nextInteractionReportOptionGeneration;
    bool hasReport = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        hasReport = std::any_of(g_interactionReportWindows.begin(),
            g_interactionReportWindows.end(), [&](const auto &entry) {
                return entry.link.sourceModelId == link.sourceModelId &&
                    entry.link.term == link.term;
            });
        for (auto &entry : g_interactionReportWindows) {
            if (entry.link.sourceModelId != link.sourceModelId ||
                entry.link.term != link.term) continue;
            entry.link.effectQuantity = link.effectQuantity;
            entry.link.effectAdjustment = link.effectAdjustment;
            entry.link.effectPresentation = link.effectPresentation;
            entry.link.confidenceLevel = link.confidenceLevel;
            entry.link.optionGeneration = link.optionGeneration;
        }
    }
    plot->title = "Effect: " + link.term + " — recalculating in R…";
    RedrawPlotOnMain(plot->id);
    RefreshInteractionDerivedLinkFromSource(
        link, hasReport, true, plot->xLabel);
}

static void ShowGLMPairwiseResultsWindowOnMain(const std::string &term,
                                                const rlispstat::core::GLMPairwiseComparisonResult &result,
                                                const GLMPairwiseComparisonPlotLink &plotLink)
{
    const std::string termCopy = term;
    const rlispstat::core::GLMPairwiseComparisonResult resultCopy = result;
    const GLMPairwiseComparisonPlotLink plotLinkCopy = plotLink;
    void (^presentWindow)(void) = ^{
        static NSMutableArray *retainedPairwiseWindows = nil;
        if (!retainedPairwiseWindows) retainedPairwiseWindows = [[NSMutableArray alloc] init];
        GLMPairwiseResultsWindowController *controller =
            [[GLMPairwiseResultsWindowController alloc] initWithTerm:termCopy result:resultCopy plotLink:plotLinkCopy];
        NSWindow *window = [controller window];
        [retainedPairwiseWindows addObject:controller];
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            g_pairwiseResultsControllers.push_back(controller);
        }
        [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowWillCloseNotification
                                                          object:window
                                                           queue:[NSOperationQueue mainQueue]
                                                      usingBlock:^(NSNotification *note) {
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pairwiseResultsControllers.erase(
                    std::remove(g_pairwiseResultsControllers.begin(), g_pairwiseResultsControllers.end(), controller),
                    g_pairwiseResultsControllers.end());
            }
            [retainedPairwiseWindows removeObject:controller];
            (void)note;
        }];
        [window center];
        EnableNotesForWindow(window, "", @"this pairwise comparison", plotLinkCopy.group);
        // R may have returned while another result window or application has
        // focus. Present the completed table just like the other model results.
        [NSApp activateIgnoringOtherApps:YES];
        [window makeKeyAndOrderFront:nil];
        [window orderFrontRegardless];
        [window displayIfNeeded];
    };
    // Menu actions already run on the UI thread: show the result before the
    // caller announces completion, rather than leaving presentation queued.
    if ([NSThread isMainThread]) presentWindow();
    else dispatch_async(dispatch_get_main_queue(), presentWindow);
}

static GLMInteractionReportView *BuildGLMInteractionReportDocumentView(
    NSString *bodyString)
{
    if (!bodyString || [bodyString length] == 0) {
        bodyString = ToNSString(rlispstat::core::GLMNoInteractionReportTextStatus());
    }
    NSArray<NSString *> *lines = [bodyString componentsSeparatedByCharactersInSet:
        [NSCharacterSet newlineCharacterSet]];
    CGFloat documentWidth = 1080.0;
    // Measure each table before laying out labels so every scale stays visible.
    for (NSString *line in lines) {
        NSArray *cells = [line componentsSeparatedByString:@"\t"];
        if ([cells indexOfObject:@"SE"] == NSNotFound) continue;
        CGFloat width = 32.0;
        for (NSString *cell in cells) width += std::max((CGFloat)130.0,
            [cell sizeWithAttributes:@{NSFontAttributeName:[NSFont systemFontOfSize:11.5 weight:NSFontWeightSemibold]}].width + 20.0);
        documentWidth = std::max(documentWidth, width + 140.0);
    }
    CGFloat documentHeight = 560.0;
    GLMInteractionReportView *reportView =
        [[GLMInteractionReportView alloc] initWithBody:bodyString
                                                 frame:NSMakeRect(0, 0, documentWidth, documentHeight)];
    CGFloat y = 16.0;
    auto addLabel = [&](NSString *text,
                        CGFloat x,
                        CGFloat width,
                        CGFloat height,
                        CGFloat fontSize,
                        NSFontWeight weight,
                        NSTextAlignment alignment) {
        NSTextField *label = InteractionReportLineLabel(text,
                                                        NSMakeRect(x, y, width, height),
                                                        fontSize,
                                                        weight,
                                                        alignment);
        [reportView addSubview:label];
        return label;
    };
    auto addMetadata = [&](NSString *line) {
        NSRange colon = [line rangeOfString:@":"];
        if (colon.location == NSNotFound) {
            addLabel(line, 16.0, documentWidth - 32.0, 22.0, 12.0,
                     NSFontWeightRegular, NSTextAlignmentLeft);
            y += 22.0;
            return;
        }
        NSString *key = [line substringToIndex:colon.location + 1];
        NSString *value = [[line substringFromIndex:colon.location + 1]
            stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
        addLabel(key, 16.0, 210.0, 20.0, 12.0, NSFontWeightSemibold, NSTextAlignmentLeft);
        addLabel(value, 230.0, documentWidth - 246.0, 20.0, 12.0,
                 NSFontWeightRegular, NSTextAlignmentLeft);
        y += 22.0;
    };
    NSInteger activeIdentityColumns = 1;
    std::vector<CGFloat> activeColumnWidths;
    std::vector<std::string> activeColumnHeaders;
    std::string activeSectionName;
    for (NSString *line in lines) {
        if ([line length] == 0) {
            y += 8.0;
            continue;
        }
        if ([line hasPrefix:ToNSString(rlispstat::core::GLMReportInteractionTermPrefix())]) {
            NSString *term = [[line substringFromIndex:
                [ToNSString(rlispstat::core::GLMReportInteractionTermPrefix()) length]]
                stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
            addLabel(term, 16.0, documentWidth - 32.0, 24.0, 16.0,
                     NSFontWeightSemibold, NSTextAlignmentLeft);
            y += 30.0;
            continue;
        }
        if ([line hasPrefix:ToNSString(rlispstat::core::GLMReportTypePrefix())] ||
            [line hasPrefix:ToNSString(rlispstat::core::GLMReportConfidenceLevelPrefix())] ||
            [line hasPrefix:ToNSString(rlispstat::core::GLMReportMultipleComparisonsPrefix())] ||
            [line hasPrefix:@"Imputations:"] ||
            [line hasPrefix:@"Pooling:"] ||
            [line hasPrefix:@"EMM reference test:"] ||
            [line hasPrefix:@"Interaction contrasts:"] ||
            [line hasPrefix:@"Estimated marginal means:"] ||
            [line hasPrefix:@"Statistical contrasts:"] ||
            [line hasPrefix:@"Transformed contrast:"]) {
            addMetadata(line);
            continue;
        }
        if ([line hasPrefix:@"Interpretation:"]) {
            NSString *value = [[line substringFromIndex:[@"Interpretation:" length]]
                stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
            addLabel(value, 16.0, documentWidth - 32.0, 42.0, 12.0,
                     NSFontWeightRegular, NSTextAlignmentLeft);
            y += 48.0;
            continue;
        }
        if ([line hasPrefix:ToNSString(rlispstat::core::GLMReportNotePrefix())]) {
            y += 8.0;
            addLabel(line, 16.0, documentWidth - 32.0, 36.0, 11.0,
                     NSFontWeightRegular, NSTextAlignmentLeft);
            y += 42.0;
            continue;
        }
        NSArray<NSString *> *parts = [line componentsSeparatedByString:@"\t"];
        if ([parts count] > 1) {
            NSUInteger seIndex = [parts indexOfObject:@"SE"];
            NSUInteger estimateIndex = seIndex != NSNotFound && seIndex > 1 ? seIndex - 1 : NSNotFound;
            BOOL header = estimateIndex != NSNotFound &&
                [parts indexOfObject:@"SE"] != NSNotFound && estimateIndex > 0;
            const NSInteger columnCount = (NSInteger)[parts count];
            if (header) {
                activeIdentityColumns = (NSInteger)estimateIndex;
                activeColumnWidths.clear();
                activeColumnHeaders.clear();
                for (NSInteger i = 0; i < columnCount; ++i) {
                    NSString *heading = parts[(NSUInteger)i];
                    activeColumnHeaders.push_back(std::string([heading UTF8String]));
                    CGFloat width = std::max((CGFloat)130.0,
                        [heading sizeWithAttributes:@{NSFontAttributeName:[NSFont systemFontOfSize:11.5 weight:NSFontWeightSemibold]}].width + 20.0);
                    if (i == 0 || [heading isEqualToString:@"Comparison"]) width += 70.0;
                    activeColumnWidths.push_back(width);
                }
            }
            if ((NSInteger)activeColumnWidths.size() != columnCount) {
                activeIdentityColumns = 1;
                activeColumnWidths.assign((std::size_t)columnCount,
                    (documentWidth - 32.0) / (CGFloat)columnCount);
                activeColumnWidths.front() = 360.0;
            }
            CGFloat x = 16.0;
            for (NSInteger i = 0; i < columnCount; ++i) {
                NSString *cell = parts[(NSUInteger)i];
                const CGFloat width = activeColumnWidths[(std::size_t)i];
                NSTextField *cellLabel = addLabel(cell, x, width, 18.0, 11.5,
                         header ? NSFontWeightSemibold : NSFontWeightRegular,
                         i < activeIdentityColumns
                            ? NSTextAlignmentLeft : NSTextAlignmentRight);
                if (i >= activeIdentityColumns &&
                    (std::size_t)i < activeColumnHeaders.size() &&
                    !activeSectionName.empty()) {
                    NSMenu *helpMenu = [[[NSMenu alloc] initWithTitle:@"Statistic"] autorelease];
                    [helpMenu addItem:[reportView explanationItemForSection:
                        ToNSString(activeSectionName)
                        statistic:ToNSString(activeColumnHeaders[(std::size_t)i])]];
                    [cellLabel setMenu:helpMenu];
                }
                x += width;
            }
            y += 20.0;
            if (header) {
                [reportView addSubview:InteractionReportRule(
                    16.0, y - 1.0, documentWidth - 32.0)];
                y += 6.0;
            }
            continue;
        }
        y += 8.0;
        activeSectionName = std::string([line UTF8String]);
        addLabel(line, 16.0, documentWidth - 32.0, 20.0, 12.5,
                 NSFontWeightSemibold, NSTextAlignmentLeft);
        y += 22.0;
    }
    documentHeight = std::max((CGFloat)560.0, y + 24.0);
    [reportView setFrameSize:NSMakeSize(documentWidth, documentHeight)];
    return reportView;
}

static void ReplaceGLMInteractionReportBody(NSScrollView *scroll,
                                             const std::string &body)
{
    if (!scroll) return;
    // The provenance trailer is transport metadata for R-code export, not
    // report content. Keep the original body for provenance registration and
    // pass only the visible report to rendering and table export.
    std::string visibleBody;
    std::istringstream input(body);
    for (std::string line; std::getline(input, line);) {
        if (line == "ANALYSIS_PROVENANCE_V2" || line == "ANALYSIS_PROVENANCE_V1" ||
            line == "ANALYSIS_PROVENANCE_V2\r" || line == "ANALYSIS_PROVENANCE_V1\r")
            break;
        visibleBody += line;
        visibleBody += '\n';
    }
    GLMInteractionReportView *reportView = BuildGLMInteractionReportDocumentView(
        SafeNSStringFromUTF8(visibleBody));
    [scroll setDocumentView:reportView];
    [[scroll contentView] scrollToPoint:NSMakePoint(0.0, 0.0)];
    [scroll reflectScrolledClipView:[scroll contentView]];
}

@interface EMMReferenceControlTarget : NSObject
@property(nonatomic, copy) void (^changeHandler)(NSPopUpButton *sender);
- (void)referenceChanged:(NSPopUpButton *)sender;
@end

@implementation EMMReferenceControlTarget
- (void)referenceChanged:(NSPopUpButton *)sender
{
    if (self.changeHandler) self.changeHandler(sender);
}
@end

static void ConfigureEMMReferenceSelector(
    NSPopUpButton *selector,
    const RegressionInteractionDerivedLink &link)
{
    if (!selector) return;
    if (!link.emmReferenceTestEnabled || !std::isfinite(link.emmTestReference)) {
        [selector selectItemAtIndex:0];
        return;
    }
    if (std::fabs(link.emmTestReference) < 1e-15) {
        [selector selectItemAtIndex:1];
        return;
    }
    NSString *title = [NSString stringWithFormat:@"Custom: %@",
        SafeNSStringFromUTF8(FormatDouble(link.emmTestReference, 8))];
    [[selector itemAtIndex:2] setTitle:title];
    [selector selectItemAtIndex:2];
}

static void ShowGLMInteractionReportWindowOnMain(
    const std::string &title,
    const std::string &body,
    const RegressionInteractionDerivedLink &derivedLink = {})
{
    std::string titleCopy = title;
    std::string bodyCopy = body;
    RegressionInteractionDerivedLink linkCopy = derivedLink;
    if (linkCopy.optionGeneration == 0)
        linkCopy.optionGeneration = ++g_nextInteractionReportOptionGeneration;
    dispatch_async(dispatch_get_main_queue(), ^{
        static NSMutableArray *retainedInteractionWindows = nil;
        if (!retainedInteractionWindows) {
            retainedInteractionWindows = [[NSMutableArray alloc] init];
        }
        NSRect frame = NSMakeRect(180, 180, 980, 620);
        NSWindow *window = [[NSWindow alloc] initWithContentRect:frame
                                                       styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                                                         backing:NSBackingStoreBuffered
                                                           defer:NO];
        [window setTitle:SafeNSStringFromUTF8(titleCopy)];
        [window setReleasedWhenClosed:NO];
        NSView *content = [window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[[NSColor whiteColor] CGColor]];

        rlispstat::core::GLMInteractionReport parsedReport;
        std::vector<std::string> reportLines;
        std::istringstream reportStream(bodyCopy);
        for (std::string line; std::getline(reportStream, line);) reportLines.push_back(line);
        rlispstat::core::ParseGLMInteractionReportText(reportLines, parsedReport);
        std::map<std::string, std::string> fittedTermTypes;
        if (parsedReport.kind == "three_way_with_numeric") {
            InteractionDerivedRefreshSnapshot source;
            std::string sourceMessage;
            if (BuildInteractionDerivedRefreshSnapshot(
                    linkCopy, source, sourceMessage)) {
                fittedTermTypes = source.termTypes;
            } else {
                DataFrameModel dataset;
                if (DataFrameSnapshotForGroup(linkCopy.group, dataset)) {
                    for (const auto &variable :
                         rlispstat::core::UniqueBaseVariablesForTerm(parsedReport.term)) {
                        const DataColumn *column = FindDataColumnInDataFrame(dataset, variable);
                        if (column) fittedTermTypes[variable] = column->type;
                    }
                }
            }
        }
        auto groupingFactors = rlispstat::core::GLMInteractionGroupingFactors(
            parsedReport, fittedTermTypes);
        std::vector<std::string> comparisonVariables = groupingFactors;
        if (parsedReport.kind == "three_way_with_numeric" &&
            groupingFactors.size() >= 2)
            comparisonVariables =
                rlispstat::core::UniqueBaseVariablesForTerm(parsedReport.term);
        const std::string initialFocal = !linkCopy.reportFocal.empty()
            ? linkCopy.reportFocal
            : (comparisonVariables.size() > groupingFactors.size()
                ? *std::find_if(comparisonVariables.begin(), comparisonVariables.end(),
                    [&](const std::string &variable) {
                        return std::find(groupingFactors.begin(), groupingFactors.end(), variable) ==
                            groupingFactors.end();
                    })
                : (groupingFactors.empty() ? std::string() : groupingFactors.front()));
        const std::string initialGroup = !linkCopy.reportGroup.empty() &&
            linkCopy.reportGroup != initialFocal
            ? linkCopy.reportGroup
            : (groupingFactors.empty() ? std::string()
                : (*std::find_if(groupingFactors.begin(), groupingFactors.end(),
                    [&](const std::string &variable) { return variable != initialFocal; })));
        const CGFloat controlHeight = groupingFactors.empty() ? 46.0 : 82.0;
        NSView *controlBar = [[NSView alloc] initWithFrame:NSMakeRect(
            0.0, NSHeight([content bounds]) - controlHeight,
            NSWidth([content bounds]), controlHeight)];
        [controlBar setAutoresizingMask:NSViewWidthSizable | NSViewMinYMargin];
        NSTextField *referenceLabel = [NSTextField labelWithString:
            @"Test estimated means against:"];
        [referenceLabel setFrame:NSMakeRect(16.0, 12.0, 210.0, 22.0)];
        [controlBar addSubview:referenceLabel];
        NSPopUpButton *referenceSelector = [[NSPopUpButton alloc]
            initWithFrame:NSMakeRect(228.0, 8.0, 170.0, 28.0) pullsDown:NO];
        [referenceSelector addItemsWithTitles:@[@"None", @"0", @"Custom…"]];
        [referenceSelector setEnabled:!linkCopy.sourceModelId.empty()];
        [controlBar addSubview:referenceSelector];
        NSPopUpButton *quantitySelector = nil;
        NSPopUpButton *adjustmentSelector = nil;
        NSPopUpButton *presentationSelector = nil;
        NSPopUpButton *confidenceSelector = nil;
        if (linkCopy.binaryEffect) {
            [referenceLabel setStringValue:@"Quantity:"];
            [referenceLabel setFrame:NSMakeRect(16.0, 12.0, 64.0, 22.0)];
            quantitySelector = referenceSelector;
            [quantitySelector removeAllItems];
            [quantitySelector addItemsWithTitles:@[
                @"Predicted probability", @"Probability difference"]];
            [quantitySelector setFrame:NSMakeRect(80.0, 8.0, 180.0, 28.0)];
            [quantitySelector selectItemAtIndex:
                linkCopy.effectQuantity == "probability_difference" ? 1 : 0];

            NSTextField *adjustmentLabel = [NSTextField labelWithString:@"Adjustment:"];
            [adjustmentLabel setFrame:NSMakeRect(274.0, 12.0, 86.0, 22.0)];
            [controlBar addSubview:adjustmentLabel];
            adjustmentSelector = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(360.0, 8.0, 220.0, 28.0) pullsDown:NO];
            [adjustmentSelector addItemsWithTitles:@[
                @"Average over analysis sample", @"Reference profile"]];
            [adjustmentSelector selectItemAtIndex:
                linkCopy.effectAdjustment == "reference_profile" ? 1 : 0];
            [adjustmentSelector setEnabled:!linkCopy.sourceModelId.empty()];
            [controlBar addSubview:adjustmentSelector];

            NSTextField *presentationLabel = [NSTextField labelWithString:@"Display:"];
            [presentationLabel setFrame:NSMakeRect(594.0, 12.0, 60.0, 22.0)];
            [controlBar addSubview:presentationLabel];
            presentationSelector = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(652.0, 8.0, 126.0, 28.0) pullsDown:NO];
            [presentationSelector addItemsWithTitles:@[@"Percentage", @"0–1"]];
            [presentationSelector selectItemAtIndex:
                linkCopy.effectPresentation == "probability" ? 1 : 0];
            [presentationSelector setEnabled:!linkCopy.sourceModelId.empty()];
            [controlBar addSubview:presentationSelector];

            NSTextField *confidenceLabel = [NSTextField labelWithString:@"CI:"];
            [confidenceLabel setFrame:NSMakeRect(790.0, 12.0, 26.0, 22.0)];
            [controlBar addSubview:confidenceLabel];
            confidenceSelector = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(816.0, 8.0, 92.0, 28.0) pullsDown:NO];
            [confidenceSelector addItemsWithTitles:@[@"90%", @"95%", @"99%"]];
            [confidenceSelector selectItemAtIndex:
                std::fabs(linkCopy.confidenceLevel - 0.90) < 0.001 ? 0 :
                (std::fabs(linkCopy.confidenceLevel - 0.99) < 0.001 ? 2 : 1)];
            [confidenceSelector setEnabled:!linkCopy.sourceModelId.empty()];
            [controlBar addSubview:confidenceSelector];
        }
        NSPopUpButton *groupingSelector = nil;
        NSPopUpButton *comparisonSelector = nil;
        NSTextField *stratumLabel = nil;
        if (!groupingFactors.empty()) {
            if (comparisonVariables.size() > 2) {
                NSTextField *compareLabel = [NSTextField labelWithString:@"Compare:"];
                [compareLabel setFrame:NSMakeRect(16.0, 48.0, 80.0, 22.0)];
                [controlBar addSubview:compareLabel];
                comparisonSelector = [[NSPopUpButton alloc]
                    initWithFrame:NSMakeRect(100.0, 44.0, 230.0, 28.0) pullsDown:NO];
                for (const auto &factor : comparisonVariables)
                    [comparisonSelector addItemWithTitle:SafeNSStringFromUTF8(factor)];
                [comparisonSelector selectItemWithTitle:SafeNSStringFromUTF8(initialFocal)];
                [comparisonSelector setEnabled:!linkCopy.sourceModelId.empty()];
                [comparisonSelector setToolTip:@"Compare this factor within each combination of the other factors."];
                [controlBar addSubview:comparisonSelector];
            }
            NSTextField *groupLabel = [NSTextField labelWithString:@"Group by:"];
            [groupLabel setFrame:NSMakeRect(comparisonVariables.size() > 2 ? 348.0 : 16.0,
                48.0, 80.0, 22.0)];
            [controlBar addSubview:groupLabel];
            groupingSelector = [[NSPopUpButton alloc]
                initWithFrame:NSMakeRect(comparisonVariables.size() > 2 ? 432.0 : 100.0,
                    44.0, 230.0, 28.0) pullsDown:NO];
            for (const auto &factor : groupingFactors)
                [groupingSelector addItemWithTitle:SafeNSStringFromUTF8(factor)];
            [groupingSelector selectItemWithTitle:SafeNSStringFromUTF8(initialGroup)];
            [groupingSelector setEnabled:!linkCopy.sourceModelId.empty()];
            [groupingSelector setToolTip:comparisonVariables.size() == 2
                ? @"Compare the other factor within each category of this variable."
                : @"Group comparisons by this factor; the remaining factor defines strata."];
            [controlBar addSubview:groupingSelector];
            if (comparisonVariables.size() > 2) {
                auto remaining = comparisonVariables;
                remaining.erase(std::remove(remaining.begin(), remaining.end(), initialFocal), remaining.end());
                remaining.erase(std::remove(remaining.begin(), remaining.end(), initialGroup), remaining.end());
                stratumLabel = [NSTextField labelWithString:[NSString stringWithFormat:
                    @"Within: %@", SafeNSStringFromUTF8(remaining.empty() ? "" : remaining.front())]];
                [stratumLabel setFrame:NSMakeRect(680.0, 48.0, 278.0, 22.0)];
                [controlBar addSubview:stratumLabel];
            }
        }
        [content addSubview:controlBar];

        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(
            0.0, 0.0, NSWidth([content bounds]),
            NSHeight([content bounds]) - controlHeight)];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [scroll setBorderType:NSNoBorder];
        [scroll setDrawsBackground:YES];
        [scroll setBackgroundColor:[NSColor whiteColor]];
        [scroll setHasVerticalScroller:YES];
        [scroll setHasHorizontalScroller:YES];

        ReplaceGLMInteractionReportBody(scroll, bodyCopy);
        RegisterInteractionReportCodeReference(linkCopy, bodyCopy);
        [content addSubview:scroll];
        [retainedInteractionWindows addObject:window];
        if (!linkCopy.binaryEffect)
            ConfigureEMMReferenceSelector(referenceSelector, linkCopy);
        EMMReferenceControlTarget *referenceTarget = [[EMMReferenceControlTarget alloc] init];
        referenceTarget.changeHandler = ^(NSPopUpButton *sender) {
            RegressionInteractionDerivedLink current;
            bool found = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                for (const GLMInteractionReportWindowEntry &entry : g_interactionReportWindows) {
                    if (entry.window == window) {
                        current = entry.link;
                        found = true;
                        break;
                    }
                }
            }
            if (!found) return;
            if (sender == groupingSelector || sender == comparisonSelector) {
                if ([sender indexOfSelectedItem] < 0) return;
                const std::string previousFocal = current.reportFocal.empty()
                    ? initialFocal : current.reportFocal;
                const std::string previousGroup = current.reportGroup.empty()
                    ? initialGroup : current.reportGroup;
                std::string focal = previousFocal;
                std::string group = previousGroup;
                if (sender == groupingSelector) {
                    group = [[sender titleOfSelectedItem] UTF8String];
                    if (group == focal) focal = previousGroup;
                } else {
                    focal = [[sender titleOfSelectedItem] UTF8String];
                    if (focal == group) group = previousFocal;
                }
                if (focal.empty() || group.empty() || focal == group) return;
                current.reportFocal = focal;
                current.reportGroup = group;
                current.optionGeneration = ++g_nextInteractionReportOptionGeneration;
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    for (auto &entry : g_interactionReportWindows) {
                        if (entry.link.sourceModelId != current.sourceModelId ||
                            entry.link.term != current.term) continue;
                        entry.link.reportFocal = current.reportFocal;
                        entry.link.reportGroup = current.reportGroup;
                        entry.link.optionGeneration = current.optionGeneration;
                        [entry.groupingSelector selectItemWithTitle:
                            SafeNSStringFromUTF8(group)];
                        [entry.comparisonSelector selectItemWithTitle:
                            SafeNSStringFromUTF8(focal)];
                        if (entry.stratumLabel) {
                            auto remaining = comparisonVariables;
                            remaining.erase(std::remove(remaining.begin(), remaining.end(), focal), remaining.end());
                            remaining.erase(std::remove(remaining.begin(), remaining.end(), group), remaining.end());
                            [entry.stratumLabel setStringValue:[NSString stringWithFormat:
                                @"Within: %@", SafeNSStringFromUTF8(remaining.empty() ? "" : remaining.front())]];
                        }
                    }
                }
                RefreshInteractionDerivedLinkFromSource(current, true, false);
                return;
            }
            if (current.binaryEffect) {
                if (sender == quantitySelector) {
                    current.effectQuantity = [sender indexOfSelectedItem] == 1
                        ? "probability_difference" : "predicted_probability";
                } else if (sender == adjustmentSelector) {
                    current.effectAdjustment = [sender indexOfSelectedItem] == 1
                        ? "reference_profile" : "average_sample";
                } else if (sender == presentationSelector) {
                    current.effectPresentation = [sender indexOfSelectedItem] == 1
                        ? "probability" : "percentage";
                } else if (sender == confidenceSelector) {
                    current.confidenceLevel = [sender indexOfSelectedItem] == 0
                        ? 0.90 : ([sender indexOfSelectedItem] == 2 ? 0.99 : 0.95);
                }
                current.optionGeneration = ++g_nextInteractionReportOptionGeneration;
                bool hasPlot = false;
                std::string plotFocal;
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    for (GLMInteractionReportWindowEntry &entry : g_interactionReportWindows) {
                        if (entry.link.sourceModelId != current.sourceModelId ||
                            entry.link.term != current.term) continue;
                        entry.link.effectQuantity = current.effectQuantity;
                        entry.link.effectAdjustment = current.effectAdjustment;
                        entry.link.effectPresentation = current.effectPresentation;
                        entry.link.confidenceLevel = current.confidenceLevel;
                        entry.link.optionGeneration = current.optionGeneration;
                        if (entry.quantitySelector) [entry.quantitySelector selectItemAtIndex:
                            current.effectQuantity == "probability_difference" ? 1 : 0];
                        if (entry.adjustmentSelector) [entry.adjustmentSelector selectItemAtIndex:
                            current.effectAdjustment == "reference_profile" ? 1 : 0];
                        if (entry.presentationSelector) [entry.presentationSelector selectItemAtIndex:
                            current.effectPresentation == "probability" ? 1 : 0];
                        if (entry.confidenceSelector) [entry.confidenceSelector selectItemAtIndex:
                            std::fabs(current.confidenceLevel - 0.90) < 0.001 ? 0 :
                            (std::fabs(current.confidenceLevel - 0.99) < 0.001 ? 2 : 1)];
                    }
                    for (const auto &plotEntry : g_plots) {
                        PlotModel *candidate = plotEntry.second;
                        if (!candidate || !candidate->isRegressionDerivedPlot ||
                            candidate->regressionDerivedSourceModelId != current.sourceModelId ||
                            candidate->regressionDerivedTerm != current.term) continue;
                        hasPlot = true;
                        plotFocal = candidate->xLabel;
                        break;
                    }
                }
                RefreshInteractionDerivedLinkFromSource(
                    current, true, hasPlot, plotFocal);
                return;
            }
            bool enabled = [sender indexOfSelectedItem] != 0;
            double reference = 0.0;
            if ([sender indexOfSelectedItem] == 2) {
                NSAlert *alert = [[NSAlert alloc] init];
                [alert setMessageText:@"Reference value"];
                [alert setInformativeText:@"Test H0: estimated marginal mean = reference value."];
                [alert addButtonWithTitle:@"Use reference"];
                [alert addButtonWithTitle:@"Cancel"];
                NSTextField *input = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 240, 24)];
                if (current.emmReferenceTestEnabled &&
                    std::isfinite(current.emmTestReference))
                    [input setStringValue:SafeNSStringFromUTF8(
                        FormatDouble(current.emmTestReference, 8))];
                [alert setAccessoryView:input];
                if ([alert runModal] != NSAlertFirstButtonReturn) {
                    ConfigureEMMReferenceSelector(sender, current);
                    return;
                }
                const std::string value = std::string([[input stringValue] UTF8String]);
                char *end = nullptr;
                reference = std::strtod(value.c_str(), &end);
                while (end && *end && std::isspace((unsigned char)*end)) ++end;
                if (end == value.c_str() || (end && *end) || !std::isfinite(reference)) {
                    NSBeep();
                    ConfigureEMMReferenceSelector(sender, current);
                    return;
                }
            }
            current.emmReferenceTestEnabled = enabled;
            current.emmTestReference = enabled
                ? reference : std::numeric_limits<double>::quiet_NaN();
            current.optionGeneration = ++g_nextInteractionReportOptionGeneration;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                for (GLMInteractionReportWindowEntry &entry : g_interactionReportWindows) {
                    if (entry.link.sourceModelId != current.sourceModelId ||
                        entry.link.term != current.term) continue;
                    entry.link.emmReferenceTestEnabled = current.emmReferenceTestEnabled;
                    entry.link.emmTestReference = current.emmTestReference;
                    entry.link.optionGeneration = current.optionGeneration;
                    ConfigureEMMReferenceSelector(entry.referenceSelector, entry.link);
                }
            }
            RefreshInteractionDerivedLinkFromSource(current, true, false);
        };
        [groupingSelector setTarget:referenceTarget];
        [groupingSelector setAction:@selector(referenceChanged:)];
        [comparisonSelector setTarget:referenceTarget];
        [comparisonSelector setAction:@selector(referenceChanged:)];
        [referenceSelector setTarget:referenceTarget];
        [referenceSelector setAction:@selector(referenceChanged:)];
        [adjustmentSelector setTarget:referenceTarget];
        [adjustmentSelector setAction:@selector(referenceChanged:)];
        [presentationSelector setTarget:referenceTarget];
        [presentationSelector setAction:@selector(referenceChanged:)];
        [confidenceSelector setTarget:referenceTarget];
        [confidenceSelector setAction:@selector(referenceChanged:)];
        if (!linkCopy.sourceModelId.empty()) {
            std::lock_guard<std::mutex> lock(g_mutex);
            GLMInteractionReportWindowEntry entry;
            entry.window = window;
            entry.scroll = scroll;
            entry.groupingSelector = groupingSelector;
            entry.comparisonSelector = comparisonSelector;
            entry.stratumLabel = stratumLabel;
            entry.referenceSelector = referenceSelector;
            entry.quantitySelector = quantitySelector;
            entry.adjustmentSelector = adjustmentSelector;
            entry.presentationSelector = presentationSelector;
            entry.confidenceSelector = confidenceSelector;
            entry.referenceTarget = referenceTarget;
            entry.link = linkCopy;
            g_interactionReportWindows.push_back(entry);
        }
        [[NSNotificationCenter defaultCenter] addObserverForName:NSWindowWillCloseNotification
                                                          object:window
                                                           queue:[NSOperationQueue mainQueue]
                                                      usingBlock:^(NSNotification *note) {
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                NSWindow *closingWindow = [note object];
                g_interactionReportWindows.erase(
                    std::remove_if(g_interactionReportWindows.begin(),
                                   g_interactionReportWindows.end(),
                                   [closingWindow](const GLMInteractionReportWindowEntry &entry) {
                                       return entry.window == closingWindow;
                                   }),
                    g_interactionReportWindows.end());
            }
            [retainedInteractionWindows removeObject:[note object]];
        }];
        [window center];
        EnableNotesForWindow(window, "", @"this interaction report", linkCopy.group);
        [window makeKeyAndOrderFront:nil];
    });
}

static bool GLMNumericValueForRow(PlotModel *model, const std::string &variable, int row, double &out)
{
    if (!model || row <= 0) return false;
    size_t index = (size_t)row - 1;
    if (NumericVariable *var = FindVariable(model, variable)) {
        if (index >= var->values.size()) return false;
        out = var->values[index];
        return std::isfinite(out);
    }
    if (const DataColumn *col = FindDataColumnForModel(model, variable)) {
        if (index >= col->values.size()) return false;
        return ParseDataCellDouble(col->values[index], out) && std::isfinite(out);
    }
    return false;
}

static std::string GLMFactorValueForRow(PlotModel *model, const std::string &variable, int row)
{
    if (!model || row <= 0) return "";
    size_t index = (size_t)row - 1;
    if (const DataColumn *col = FindDataColumnForModel(model, variable)) {
        if (index >= col->values.size() || DataCellIsMissing(col->values[index])) return "";
        return col->values[index];
    }
    if (NumericVariable *var = FindVariable(model, variable)) {
        if (index >= var->values.size() || !std::isfinite(var->values[index])) return "";
        return FormatFactorLabel(var->values[index]);
    }
    return "";
}

static void GLMAddObservedInteractionPoints(PlotModel *plot, PlotModel *seed,
                                            const GLMFitSummary &fit,
                                            const std::string &dependent,
                                            const std::string &x,
                                            const std::string &moderator,
                                            const std::string &xType,
                                            const std::string &moderatorType,
                                            const std::vector<std::string> &xLevels,
                                            const std::vector<std::string> &moderatorLevels)
{
    if (!plot || !seed) return;
    std::map<std::string, size_t> xIndex = GLMLevelIndex(xLevels);
    std::map<std::string, size_t> moderatorIndex = GLMLevelIndex(moderatorLevels);
    for (int row : fit.rowsUsed) {
        double y = NAN;
        if (!GLMNumericValueForRow(seed, dependent, row, y)) continue;
        double px = NAN;
        if (xType == "factor") {
            std::string level = GLMFactorValueForRow(seed, x, row);
            auto it = xIndex.find(level);
            if (it == xIndex.end()) continue;
            px = (double)it->second + 1.0;
            if (moderatorType == "factor" && !moderatorLevels.empty()) {
                std::string modLevel = GLMFactorValueForRow(seed, moderator, row);
                auto modIt = moderatorIndex.find(modLevel);
                if (modIt != moderatorIndex.end()) {
                    double centered = (double)modIt->second - ((double)moderatorLevels.size() - 1.0) / 2.0;
                    px += centered * 0.10;
                }
            }
        } else {
            if (!GLMNumericValueForRow(seed, x, row, px)) continue;
        }
        if (std::isfinite(px) && std::isfinite(y)) plot->points.push_back(DataPoint{px, y, row});
    }
}

static bool PopulateGLMInteractionPlotLegacy(PlotModel *plot,
                                             PlotModel *seed,
                                             const std::string &dependent,
                                             const std::string &term,
                                             const std::vector<std::string> &terms,
                                             const std::map<std::string, std::string> &termTypes,
                                             const GLMFitSummary &fit,
                                             std::string *message = nullptr)
{
    if (!plot || !seed) {
        if (message) *message = rlispstat::core::GLMNoActiveInteractionDataStatus();
        return false;
    }
    if (!fit.ok) {
        if (message) *message = fit.warning.empty() ? rlispstat::core::GLMInteractionModelNotFittedStatus() : fit.warning;
        return false;
    }
    std::vector<std::string> parts = SplitInteractionTerm(term);
    if (parts.size() != 2) {
        if (message) *message = rlispstat::core::GLMInteractionTwoWayOnlyStatus();
        return false;
    }
    std::string a = BaseVariableForTermComponent(parts[0]);
    std::string b = BaseVariableForTermComponent(parts[1]);
    std::string aType = rlispstat::core::GLMBaseVariableType(seed, a, termTypes);
    std::string bType = rlispstat::core::GLMBaseVariableType(seed, b, termTypes);

    std::string x = a;
    std::string moderator = b;
    std::string xType = aType;
    std::string moderatorType = bType;
    if (aType == "factor" && bType == "numeric") {
        x = b;
        moderator = a;
        xType = bType;
        moderatorType = aType;
    }
    if (aType == "factor" && bType == "factor") {
        x = a;
        moderator = b;
        xType = "factor";
        moderatorType = "factor";
    }

    plot->kind = "glm_interaction";
    plot->isDatasetSeed = false;
    plot->isGLMDiagnostic = false;
    plot->isGLMInteractionPlot = true;
    plot->glmModelId = "glm:" + seed->group;
    plot->glmInteractionTerm = term;
    plot->group = seed->group;
    plot->xLabel = x;
    plot->yLabel = "Predicted " + dependent;
    plot->title = "Effect: " + term;
    plot->points.clear();
    plot->interactionPlotLines.clear();
    plot->interactionXTicks.clear();
    plot->overlays.clear();

    const double confidenceLevel = 0.95;
    std::vector<std::string> xLevels;
    std::vector<std::string> moderatorLevels;
    if (xType == "factor") {
        xLevels = GLMFactorLevelsForVariable(seed, x, fit);
        for (size_t i = 0; i < xLevels.size(); ++i) {
            plot->interactionXTicks.push_back(std::make_pair((double)i + 1.0, xLevels[i]));
        }
    }
    if (moderatorType == "factor") {
        moderatorLevels = GLMFactorLevelsForVariable(seed, moderator, fit);
    }

    GLMAddObservedInteractionPoints(plot, seed, fit, dependent, x, moderator, xType, moderatorType, xLevels, moderatorLevels);

    if (xType == "numeric" && moderatorType == "factor") {
        GLMNumericSummary xSummary = GLMNumericSummaryForVariable(seed, x, fit);
        if (!xSummary.ok || moderatorLevels.empty()) {
            if (message) *message = rlispstat::core::GLMInteractionNoFittedValuesStatus();
            return false;
        }
        double left = xSummary.min;
        double right = xSummary.max;
        if (!(right > left)) {
            left = xSummary.mean - 1.0;
            right = xSummary.mean + 1.0;
        }
        for (size_t levelIndex = 0; levelIndex < moderatorLevels.size(); ++levelIndex) {
            InteractionPlotLine line;
            line.label = moderator + " = " + moderatorLevels[levelIndex];
            line.colorKey = PaletteColorNameAtIndex(levelIndex);
            for (int row : fit.rowsUsed) {
                if (GLMFactorValueForRow(seed, moderator, row) ==
                    moderatorLevels[levelIndex]) {
                    line.caseIds.push_back(row);
                }
            }
            for (int i = 0; i <= 40; ++i) {
                double value = left + (right - left) * (double)i / 40.0;
                GLMPostEstimate predicted = GLMPredictionEstimate(seed, terms, termTypes, fit,
                                                                  {{x, value}}, {{moderator, moderatorLevels[levelIndex]}},
                                                                  line.label, confidenceLevel);
                GLMAddInteractionLinePoint(plot, line, value, predicted.estimate);
            }
            plot->interactionPlotLines.push_back(line);
        }
    } else if (xType == "numeric" && moderatorType == "numeric") {
        GLMNumericSummary xSummary = GLMNumericSummaryForVariable(seed, x, fit);
        GLMNumericSummary modSummary = GLMNumericSummaryForVariable(seed, moderator, fit);
        if (!xSummary.ok || !modSummary.ok) {
            if (message) *message = rlispstat::core::GLMInteractionNoFittedValuesStatus();
            return false;
        }
        double left = xSummary.min;
        double right = xSummary.max;
        if (!(right > left)) {
            left = xSummary.mean - 1.0;
            right = xSummary.mean + 1.0;
        }
        std::vector<std::pair<std::string, double>> moderatorValues;
        if (std::isfinite(modSummary.sd) && modSummary.sd > 0.0) {
            moderatorValues.push_back(std::make_pair(moderator + " = M - SD", modSummary.mean - modSummary.sd));
            moderatorValues.push_back(std::make_pair(moderator + " = M", modSummary.mean));
            moderatorValues.push_back(std::make_pair(moderator + " = M + SD", modSummary.mean + modSummary.sd));
        } else {
            moderatorValues.push_back(std::make_pair(moderator + " = M", modSummary.mean));
        }
        for (size_t i = 0; i < moderatorValues.size(); ++i) {
            InteractionPlotLine line;
            line.label = moderatorValues[i].first;
            line.colorKey = PaletteColorNameAtIndex(i);
            for (int row : fit.rowsUsed) {
                double observedModerator = NAN;
                if (!GLMNumericValueForRow(seed, moderator, row,
                                           observedModerator)) continue;
                size_t nearest = 0;
                double nearestDistance = std::numeric_limits<double>::infinity();
                for (size_t candidate = 0;
                     candidate < moderatorValues.size(); ++candidate) {
                    const double distance = std::fabs(
                        observedModerator - moderatorValues[candidate].second);
                    if (distance < nearestDistance) {
                        nearestDistance = distance;
                        nearest = candidate;
                    }
                }
                if (nearest == i) line.caseIds.push_back(row);
            }
            for (int step = 0; step <= 40; ++step) {
                double value = left + (right - left) * (double)step / 40.0;
                GLMPostEstimate predicted = GLMPredictionEstimate(seed, terms, termTypes, fit,
                                                                  {{x, value}, {moderator, moderatorValues[i].second}},
                                                                  {}, line.label, confidenceLevel);
                GLMAddInteractionLinePoint(plot, line, value, predicted.estimate);
            }
            plot->interactionPlotLines.push_back(line);
        }
    } else if (xType == "factor" && moderatorType == "factor") {
        if (xLevels.empty() || moderatorLevels.empty()) {
            if (message) *message = rlispstat::core::GLMInteractionFactorNoLevelsStatus();
            return false;
        }
        for (size_t levelIndex = 0; levelIndex < moderatorLevels.size(); ++levelIndex) {
            InteractionPlotLine line;
            line.label = moderator + " = " + moderatorLevels[levelIndex];
            line.colorKey = PaletteColorNameAtIndex(levelIndex);
            for (int row : fit.rowsUsed) {
                if (GLMFactorValueForRow(seed, moderator, row) ==
                    moderatorLevels[levelIndex]) {
                    line.caseIds.push_back(row);
                }
            }
            for (size_t xIndex = 0; xIndex < xLevels.size(); ++xIndex) {
                GLMPostEstimate predicted = GLMPredictionEstimate(seed, terms, termTypes, fit,
                                                                  {}, {{x, xLevels[xIndex]}, {moderator, moderatorLevels[levelIndex]}},
                                                                  line.label, confidenceLevel);
                GLMAddInteractionLinePoint(plot, line, (double)xIndex + 1.0, predicted.estimate);
            }
            plot->interactionPlotLines.push_back(line);
        }
    } else {
        if (message) *message = rlispstat::core::GLMInteractionTypeNotAvailableStatus();
        return false;
    }

    if (plot->points.empty() || plot->interactionPlotLines.empty()) {
        if (message) *message = rlispstat::core::GLMInteractionNoFiniteValuesStatus();
        return false;
    }
    ComputeRanges(plot);
    return true;
}

static void StoreGLMFitForGroup(const std::string &group, const GLMFitSummary &fit);

static GLMFitSummary PendingLinearGLMFitSummary(const std::string &message)
{
    GLMFitSummary fit;
    fit.ok = false;
    fit.warning = message;
    return fit;
}

static void RefreshGeneralizedDiagnosticCodeReference(
    PlotModel *diagnostic,
    const GeneralizedGLMState &state)
{
    if (!diagnostic || !diagnostic->isGLMDiagnostic) return;
    diagnostic->rExportTheme = MacCommandDispatcher().plotTheme();
    diagnostic->diagnosticAvailableResidualTypes =
        rlispstat::core::AvailableGeneralizedResidualTypes(state);
    diagnostic->codeReference =
        rlispstat::core::GeneralizedDiagnosticPlotCodeReference(
            *diagnostic, state);
    if (!diagnostic->codeReference.provenance.verificationRCode.empty()) {
        MacCommandDispatcher().applicationState().registerOutputCodeReference(
            diagnostic->codeReference);
    }
}

static void StoreGLMFitForGroup(const std::string &group, const GLMFitSummary &fit)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    auto found = g_groupModels.find(group);
    if (found == g_groupModels.end()) return;
    GroupModelState &state = found->second;
    if (fit.ok) {
        if (state.isStale || state.fitVersion == 0) {
            state.fitVersion += 1;
            state.diagnosticsVersion += 1;
        }
        state.diagnostics = fit.diagnostics;
        state.rowsUsed = fit.rowsUsed;
        state.rowsExcluded = fit.rowsExcluded;
        state.isStale = false;
        state.rFitPending = false;
    }
}

static bool UpdateGLMDiagnosticPlot(PlotModel *diag)
{
    if (!diag || !diag->isGLMDiagnostic) {
        return false;
    }
    if (diag->glmDiagnosticKind == "partial_regression" &&
        diag->isRegressionDerivedPlot &&
        diag->regressionDerivedKind == "partial_regression_plot") {
        RegressionInteractionDerivedLink oldLink;
        oldLink.sourceModelKind = diag->regressionDerivedSourceKind;
        oldLink.sourceModelId = diag->regressionDerivedSourceModelId;
        oldLink.sourceModelRevision = diag->regressionDerivedSourceRevision;
        oldLink.sourceFitVersion = diag->regressionDerivedSourceFitVersion;
        oldLink.group = diag->group;
        oldLink.term = diag->regressionDerivedTerm;
        InteractionDerivedRefreshSnapshot snapshot;
        std::string message;
        if (!BuildInteractionDerivedRefreshSnapshot(
                oldLink, snapshot, message, false)) {
            return false;
        }
        const std::string requestedResidual = diag->displayedResidualType.empty()
            ? diag->regressionPartialResidualType : diag->displayedResidualType;
        const bool sourceIsCurrent =
            diag->regressionDerivedSourceRevision ==
                snapshot.link.sourceModelRevision &&
            diag->regressionDerivedSourceFitVersion ==
                snapshot.link.sourceFitVersion;
        const bool residualIsCurrent = requestedResidual.empty() ||
            requestedResidual == diag->regressionPartialResidualType;
        if (sourceIsCurrent && residualIsCurrent &&
            !diag->regressionPartialPointsByImputation.empty()) {
            return ApplyStoredPartialRegressionPlot(diag);
        }
        return RefreshPartialRegressionPlotFromSource(diag, &message);
    }
    RegressionComparisonState *comparison = nullptr;
    RegressionComparisonModel *comparisonModel = nullptr;
    if (FindRegressionComparisonModelById(diag->glmModelId, &comparison, &comparisonModel)) {
        if (comparison->rFitPending || comparisonModel->isStale ||
            comparisonModel->fitVersion == 0 || !comparisonModel->fit.ok) {
            return false;
        }
        return PopulateDiagnosticPlotFromFit(
            diag, comparisonModel->fit, comparisonModel->fitVersion,
            comparisonModel->fitVersion,
            ImputedModelInputRowsForMac(
                comparison->group, *comparisonModel));
    }
    GeneralizedComparisonState *generalizedComparison = nullptr;
    GeneralizedComparisonModel *generalizedComparisonModel = nullptr;
    if (FindGeneralizedComparisonModelById(diag->glmModelId, &generalizedComparison, &generalizedComparisonModel)) {
        if (generalizedComparison->rFitPending ||
            generalizedComparisonModel->isStale ||
            generalizedComparisonModel->fitVersion == 0 ||
            !generalizedComparisonModel->fit.ok) {
            return false;
        }
        std::string message;
        const bool populated = PopulateGeneralizedDiagnosticPlot(
            diag, generalizedComparisonModel->fit, &message,
            &generalizedComparisonModel->diagnosticOptions);
        if (populated) {
            RefreshGeneralizedDiagnosticCodeReference(
                diag, generalizedComparisonModel->fit);
        }
        return populated;
    }
    auto generalizedIt = g_generalizedGLMs.find(diag->glmModelId);
    if (generalizedIt != g_generalizedGLMs.end()) {
        GeneralizedGLMState &state = generalizedIt->second;
        // A diagnostic is a view of the accepted model fit.  It must not
        // launch the legacy synchronous fitter while the current R request
        // is pending, or quietly redraw the previous specification's rows.
        if (state.rFitPending || !state.ok ||
            state.fitVersion < state.modelVersion) return false;
        std::string message;
        const bool populated = PopulateGeneralizedDiagnosticPlot(
            diag, state, &message);
        if (populated) RefreshGeneralizedDiagnosticCodeReference(diag, state);
        return populated;
    }
    if (diag->glmModelId.rfind("glm:", 0) != 0) return false;
    const std::string linearModelId = diag->glmModelId.substr(4);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto stateIt = g_groupModels.find(linearModelId);
        auto fitIt = g_precomputedLinearModelFits.find(linearModelId);
        if (stateIt != g_groupModels.end() && fitIt != g_precomputedLinearModelFits.end() &&
            stateIt->second.group == diag->group &&
            !stateIt->second.isStale && fitIt->second.ok) {
            return PopulateDiagnosticPlotFromFit(
                diag, fitIt->second, stateIt->second.fitVersion,
                stateIt->second.diagnosticsVersion,
                ImputedModelInputRowsForMac(diag->group, stateIt->second));
        }
    }
    // Diagnostics only use an accepted R fit. The native fallback could show
    // provisional calculations from a different scope or imputation.
    return false;
}

static void RefreshGLMDiagnosticPlotsNow(const std::string &group, bool force = false)
{
    std::vector<PlotModel *> diagnostics;
    bool groupFitStale = false;
    int groupFitVersion = 0;
    int groupDiagnosticsVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto stateIt = g_groupModels.find(group);
        if (stateIt != g_groupModels.end()) {
            groupFitStale = stateIt->second.isStale;
            groupFitVersion = stateIt->second.fitVersion;
            groupDiagnosticsVersion = stateIt->second.diagnosticsVersion;
        }
        for (const auto &entry : g_plots) {
            PlotModel *plot = entry.second;
            if (plot && plot->group == group && plot->isGLMDiagnostic) {
                diagnostics.push_back(plot);
            }
        }
    }
    if (diagnostics.empty()) {
        return;
    }
    bool requestSmooth = false;
    for (PlotModel *diag : diagnostics) {
        // Each plot is linked to its own model id.  Comparing every plot to
        // the group's linear-model version misses changes to single-model
        // generalized fits and to individual comparison columns.
        int sourceFitVersion = groupFitVersion;
        int sourceDiagnosticsVersion = groupDiagnosticsVersion;
        int sourceOptionsVersion = 0;
        bool sourceStale = groupFitStale;
        bool sourceFrozen = false;
        GeneralizedComparisonState *comparison = nullptr;
        GeneralizedComparisonModel *comparisonModel = nullptr;
        if (FindGeneralizedComparisonModelById(diag->glmModelId,
                                               &comparison, &comparisonModel) &&
            comparisonModel) {
            sourceFitVersion = comparisonModel->fit.fitVersion;
            sourceDiagnosticsVersion = comparisonModel->fit.diagnosticsVersion;
            sourceOptionsVersion = comparisonModel->diagnosticOptions.version;
            sourceStale = comparison->rFitPending || comparisonModel->isStale;
            sourceFrozen = !comparison->autoRefit;
        } else {
            auto generalizedIt = g_generalizedGLMs.find(diag->glmModelId);
            if (generalizedIt != g_generalizedGLMs.end()) {
                const GeneralizedGLMState &source = generalizedIt->second;
                sourceFitVersion = source.fitVersion;
                sourceDiagnosticsVersion = source.diagnosticsVersion;
                sourceOptionsVersion = source.diagnosticOptions.version;
                sourceStale = source.rFitPending ||
                    source.fitVersion < source.modelVersion;
                sourceFrozen = !source.autoRefit;
            } else {
                RegressionComparisonState *linearComparison = nullptr;
                RegressionComparisonModel *linearModel = nullptr;
                if (FindRegressionComparisonModelById(diag->glmModelId,
                        &linearComparison, &linearModel) && linearModel) {
                    sourceFitVersion = linearModel->fitVersion;
                    sourceDiagnosticsVersion = linearModel->fitVersion;
                    sourceStale = linearComparison->rFitPending ||
                        linearModel->isStale;
                    sourceFrozen = !linearComparison->autoRefit;
                } else if (diag->glmModelId.rfind("glm:", 0) == 0) {
                    auto linear = g_groupModels.find(diag->glmModelId.substr(4));
                    if (linear != g_groupModels.end() && linear->second.group == group) {
                        sourceFitVersion = linear->second.fitVersion;
                        sourceDiagnosticsVersion = linear->second.diagnosticsVersion;
                        sourceStale = linear->second.isStale || linear->second.rFitPending;
                        sourceFrozen = !linear->second.autoRefit;
                    } else sourceStale = true;
                } else {
                    sourceStale = true;
                }
            }
        }
        if (sourceFrozen) {
            diag->analysisScopeFrozen = true;
            diag->frozenScopeNotice =
                "This diagnostic still belongs to the frozen source-model fit.";
            UpdateWindowTitleOnMain(diag);
            // A diagnostic option may still be changed against the accepted
            // frozen fit. Scope notifications use force=false and therefore
            // leave the existing diagnostic untouched.
            if (sourceStale || !force) continue;
        } else {
            diag->analysisScopeFrozen = false;
            diag->frozenScopeNotice.clear();
        }
        if (force || sourceStale || diag->displayedFitVersion == 0 ||
            diag->displayedFitVersion != sourceFitVersion ||
            diag->displayedDiagnosticsVersion != sourceDiagnosticsVersion ||
            diag->displayedDiagnosticOptionsVersion != sourceOptionsVersion) {
            if (!UpdateGLMDiagnosticPlot(diag)) InvalidateModelDiagnosticPlot(diag);
            else {
                std::lock_guard<std::mutex> lock(g_mutex);
                requestSmooth = RequestSmoothRecomputeForPlotUnlocked(diag) || requestSmooth;
            }
        }
    }
    if (requestSmooth) NotifyMainRTaskAvailable();
    std::lock_guard<std::mutex> lock(g_mutex);
	    for (ScatterView *view : g_views) {
	        if (view.model && view.model->group == group &&
                (view.model->isGLMDiagnostic || view.model->isGLMInteractionPlot)) {
	            [view setNeedsDisplay:YES];
	        }
	    }
	    for (HistogramView *view : g_histogramViews) {
	        if (view.model && view.model->group == group && view.model->isGLMDiagnostic) {
	            [view setNeedsDisplay:YES];
	        }
	    }
	}

static void RefreshGLMDiagnosticPlotsOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      RefreshGLMDiagnosticPlotsNow(groupCopy, false);
    });
}

static void RefreshGLMDiagnosticPlotsSynchronouslyOnMain(const std::string &group, bool force = true)
{
    if ([NSThread isMainThread]) {
        RefreshGLMDiagnosticPlotsNow(group, force);
        return;
    }
    dispatch_sync(dispatch_get_main_queue(), ^{
      RefreshGLMDiagnosticPlotsNow(group, force);
    });
}

static std::string GLMDiagnosticStateSummary(const std::string &group,
                                             const std::string &modelId = "")
{
    std::lock_guard<std::mutex> lock(g_mutex);
    PlotModel *seed = FirstPlotForGroupUnlocked(group);
    GroupModelState &state = EnsureGroupModelUnlocked(modelId.empty() ? group : modelId, seed);
    int validPredictors = 0;
    if (seed) {
        for (const std::string &term : state.terms) {
            if (FindVariable(seed, term)) ++validPredictors;
        }
    }
    return rlispstat::core::GLMDiagnosticStateSummaryText(
        group,
        state.response,
        state.terms,
        validPredictors,
        state.modelVersion,
        state.fitVersion,
        state.isStale,
        seed != nullptr,
        state.rowsUsed.size(),
        state.rowsExcluded.size());
}

static void InitializeDiagnosticImputationPresentation(
    PlotModel *diagnostic,
    const std::string &diagnosticKind)
{
    if (!diagnostic) return;
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *dataframe =
        FindDataFrameUnlockedConst(diagnostic->group);
    diagnostic->diagnosticShowImputationUncertainty = dataframe &&
        rlispstat::core::DiagnosticImputationUncertaintyShouldBeDefault(
            *dataframe, diagnosticKind);
    diagnostic->diagnosticImputationUncertaintyScope = "all";
}

static std::string OpenModelDiagnosticPlot(PlotModel *seed, const std::string &kind,
                                           bool reportErrors = true,
                                           const std::string &modelId = "")
{
    if (!seed) {
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMNoActiveDiagnosticStatus()));
        }
        return "";
    }
    std::string normalizedKind = NormalizeLinearDiagnosticKind(kind);
    if (!LinearDiagnosticKindIsImplemented(normalizedKind)) {
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMCurrentLinearDiagnosticUnavailableStatus(kind)));
        }
        return "";
    }
    PlotModel *diag = new PlotModel();
    static std::atomic<std::uint64_t> nextLinearDiagnosticId{0};
    diag->id = "diag_" + normalizedKind + "_" + seed->id + "_" +
        std::to_string((long long)time(nullptr)) + "_" +
        std::to_string(++nextLinearDiagnosticId);
    diag->group = seed->group;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = "glm:" + (modelId.empty() ? seed->group : modelId);
    diag->glmDiagnosticKind = normalizedKind;
    diag->interactionMode = "select";
    diag->selectionMode = "replace";
    InitializeDiagnosticImputationPresentation(diag, normalizedKind);
    if (!UpdateGLMDiagnosticPlot(diag)) {
        std::string group = diag->group;
        delete diag;
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMCurrentDiagnosticFitFailedStatus(GLMDiagnosticStateSummary(group, modelId))));
        }
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenRegressionComparisonDiagnosticPlot(const std::string &comparisonId, int modelIndex,
                                                          const std::string &kind, bool reportErrors)
{
    auto it = g_regressionComparisons.find(comparisonId);
    if (it == g_regressionComparisons.end()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMRegressionComparisonNotAvailableStatus()));
        return "";
    }
    RegressionComparisonState &state = it->second;
    if (modelIndex < 0 || (size_t)modelIndex >= state.models.size()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMChooseValidModelColumnStatus()));
        return "";
    }
    std::string normalizedKind = NormalizeLinearDiagnosticKind(kind);
    if (!LinearDiagnosticKindIsImplemented(normalizedKind)) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMSelectedLinearDiagnosticUnavailableStatus(kind)));
        return "";
    }
    RegressionComparisonModel &model = state.models[(size_t)modelIndex];
    if (model.isStale || model.fitVersion == 0) {
        RefitRegressionComparisonModel(state, model);
    }
    if (!model.fit.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMSelectedDiagnosticFitFailedStatus(model.fit.warning)));
        return "";
    }
    PlotModel *diag = new PlotModel();
    diag->id = "diag_" + normalizedKind + "_" + model.id + "_" + std::to_string((long long)time(nullptr));
    diag->group = state.group;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = model.id;
    diag->glmDiagnosticKind = normalizedKind;
    diag->interactionMode = "select";
    diag->selectionMode = "replace";
    diag->variables = state.seed.variables;
    diag->variableMeta = state.seed.variableMeta;
    InitializeDiagnosticImputationPresentation(diag, normalizedKind);
    if (!PopulateDiagnosticPlotFromFit(
            diag, model.fit, model.fitVersion, model.fitVersion,
            ImputedModelInputRowsForMac(state.group, model))) {
        delete diag;
        if (reportErrors) {
            ShowWorkbenchMessageOnMain(
                ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()),
                ToNSString(rlispstat::core::GLMNoDiagnosticRowsStatus()));
        }
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenGeneralizedGLMDiagnosticPlot(const std::string &modelId,
                                                     const std::string &kind,
                                                     bool reportErrors)
{
    auto it = g_generalizedGLMs.find(modelId);
    if (it == g_generalizedGLMs.end()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMGeneralizedLinearModelNotAvailableStatus()));
        return "";
    }
    GeneralizedGLMState &state = it->second;
    if (!state.ok || state.fitVersion < state.modelVersion) {
        RefitGeneralizedGLMState(state);
    }
    if (!state.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMCurrentGeneralizedDiagnosticFitFailedStatus(state.status)));
        return "";
    }

    std::string normalizedKind = NormalizeGeneralizedDiagnosticKind(kind);
    PlotModel *diag = new PlotModel(state.seed);
    diag->id = "diag_gglm_" + normalizedKind + "_" + state.id + "_" + std::to_string((long long)time(nullptr));
    diag->group = state.group;
    diag->isDatasetSeed = false;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = state.id;
    diag->glmDiagnosticKind = normalizedKind;
    diag->generalizedDiagnosticResiduals = true;
    diag->diagnosticAvailableResidualTypes =
        rlispstat::core::AvailableGeneralizedResidualTypes(state);
    diag->interactionMode = "select";
    diag->selectionMode = "replace";
    InitializeDiagnosticImputationPresentation(diag, normalizedKind);

    std::string message;
    if (!PopulateGeneralizedDiagnosticPlot(diag, state, &message)) {
        delete diag;
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(message));
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    RefreshGeneralizedDiagnosticCodeReference(diag, state);
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenGeneralizedComparisonDiagnosticPlot(const std::string &comparisonId, int modelIndex,
                                                           const std::string &kind, bool reportErrors)
{
    auto it = g_generalizedComparisons.find(comparisonId);
    if (it == g_generalizedComparisons.end()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMGeneralizedModelComparisonNotAvailableStatus()));
        return "";
    }
    GeneralizedComparisonState &state = it->second;
    if (modelIndex < 0 || (size_t)modelIndex >= state.models.size()) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMChooseValidModelColumnStatus()));
        return "";
    }
    GeneralizedComparisonModel &model = state.models[(size_t)modelIndex];
    if (model.isStale || model.fitVersion == 0) {
        RefitGeneralizedComparisonModels(state, false);
    }
    if (state.rFitPending ||
        model.fitState == rlispstat::core::RegressionComparisonFitState::Pending) {
        return "";
    }
    if (!model.fit.ok) {
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(rlispstat::core::GLMSelectedGeneralizedDiagnosticFitFailedStatus(model.fit.status)));
        return "";
    }

    std::string normalizedKind = NormalizeGeneralizedDiagnosticKind(kind);
    PlotModel *diag = new PlotModel(state.seed);
    diag->id = "diag_gglmcmp_" + normalizedKind + "_" + model.id + "_" + std::to_string((long long)time(nullptr));
    diag->group = state.group;
    diag->isDatasetSeed = false;
    diag->isGLMDiagnostic = true;
    diag->glmModelId = model.id;
    diag->glmDiagnosticKind = normalizedKind;
    diag->generalizedDiagnosticResiduals = true;
    diag->diagnosticAvailableResidualTypes =
        rlispstat::core::AvailableGeneralizedResidualTypes(model.fit);
    diag->interactionMode = "select";
    diag->selectionMode = "replace";
    InitializeDiagnosticImputationPresentation(diag, normalizedKind);

    std::string message;
    if (!PopulateGeneralizedDiagnosticPlot(diag, model.fit, &message, &model.diagnosticOptions)) {
        delete diag;
        if (reportErrors) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMDiagnosticPlotWindowTitle()), ToNSString(message));
        return "";
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        (void)AttachPlotModelUnlocked(diag);
    }
    RefreshGeneralizedDiagnosticCodeReference(diag, model.fit);
    PublishSpreadPlotMessage("DIAGNOSTIC_PLOT_OPENED", diag->group, diag->id, diag->glmModelId);
    AddPlotOnMain(diag);
    return diag->id;
}

static std::string OpenBinaryComparisonFitMeasurePlot(const std::string &comparisonId,
                                                      const std::string &measure,
                                                      bool reportErrors)
{
    auto it = g_generalizedComparisons.find(comparisonId);
    if (it == g_generalizedComparisons.end() || !it->second.binaryComparison) return "";
    GeneralizedComparisonState &state = it->second;
    PlotModel *plot = new PlotModel(state.seed);
    plot->id = "binary_comparison_" + measure + "_" + comparisonId + "_" + std::to_string((long long)time(nullptr));
    plot->group = state.group;
    plot->kind = "scatter";
    plot->isDatasetSeed = false;
    plot->title = (measure == "bic" ? "BIC" : "AIC") + std::string(" by binary model");
    plot->xLabel = "Model";
    plot->yLabel = measure == "bic" ? "BIC" : "AIC";
    plot->interactionMode = "inspect";
    plot->selectionMode = "replace";
    for (std::size_t index = 0; index < state.models.size(); ++index) {
        const GeneralizedComparisonModel &model = state.models[index];
        const double value = measure == "bic" ? model.fit.bic : model.fit.aic;
        if (!std::isfinite(value)) continue;
        plot->points.push_back(DataPoint{(double)index + 1.0, value, 0});
        plot->interactionXTicks.push_back(std::make_pair((double)index + 1.0, model.label));
    }
    if (plot->points.empty()) {
        delete plot;
        if (reportErrors) ShowWorkbenchMessageOnMain(@"Compare Binary Models", @"The selected fit measure is unavailable for these models.");
        return "";
    }
    ComputeRanges(plot);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(plot)) { delete plot; return ""; }
    }
    AddPlotOnMain(plot);
    return plot->id;
}

static std::string OpenBinaryComparisonROCPlot(const std::string &comparisonId, bool reportErrors)
{
    auto it = g_generalizedComparisons.find(comparisonId);
    if (it == g_generalizedComparisons.end() || !it->second.binaryComparison) return "";
    GeneralizedComparisonState &state = it->second;
    if (state.models.size() < 2) return "";
    const GeneralizedGLMState &base = state.models.front().fit;
    for (const GeneralizedComparisonModel &model : state.models) {
        if (model.fit.rowsUsed != base.rowsUsed || model.fit.response != base.response ||
            model.fit.responseCoding.eventValue != base.responseCoding.eventValue) {
            if (reportErrors) ShowWorkbenchMessageOnMain(@"Compare Binary Models", @"Comparative ROC curves require the same response, event, and analysis rows for every model.");
            return "";
        }
    }
    static const char *colors[] = {"#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#000000"};
    PlotModel *plot = new PlotModel(state.seed);
    plot->id = "binary_comparison_roc_" + comparisonId + "_" + std::to_string((long long)time(nullptr));
    plot->group = state.group;
    plot->kind = "glm_interaction";
    plot->isDatasetSeed = false;
    plot->title = "ROC curves — binary models";
    plot->xLabel = "False positive rate";
    plot->yLabel = "True positive rate";
    plot->interactionMode = "select";
    plot->selectionMode = "replace";
    for (std::size_t index = 0; index < state.models.size(); ++index) {
        const GeneralizedComparisonModel &model = state.models[index];
        rlispstat::core::DiagnosticPlotData roc = rlispstat::core::BuildGeneralizedDiagnosticPlotData(
            "roc_curve", model.diagnosticOptions, model.fit.diagnostics,
            model.fit.fitVersion, model.fit.diagnosticsVersion);
        if (!roc.ok) continue;
        InteractionPlotLine line;
        std::ostringstream label;
        label << model.label;
        if (std::isfinite(model.fit.auc)) label << " (AUC " << std::fixed << std::setprecision(3) << model.fit.auc << ")";
        line.label = label.str();
        line.colorKey = colors[index % (sizeof(colors) / sizeof(colors[0]))];
        line.points.push_back(DataPoint{0.0, 0.0, 0});
        for (const rlispstat::core::DiagnosticPlotPoint &point : roc.points) {
            DataPoint plotted{point.x, point.y, point.row};
            line.points.push_back(plotted);
            plot->points.push_back(plotted);
        }
        plot->interactionPlotLines.push_back(std::move(line));
    }
    InteractionPlotLine chance;
    chance.label = "Chance";
    chance.colorKey = "#777777";
    chance.points = {DataPoint{0.0, 0.0, 0}, DataPoint{1.0, 1.0, 0}};
    plot->interactionPlotLines.push_back(std::move(chance));
    if (plot->points.empty()) {
        delete plot;
        if (reportErrors) ShowWorkbenchMessageOnMain(@"Compare Binary Models", @"ROC curves are unavailable for the selected models.");
        return "";
    }
    ComputeRanges(plot);
    plot->dataXmin = plot->xmin = 0.0; plot->dataXmax = plot->xmax = 1.0;
    plot->dataYmin = plot->ymin = 0.0; plot->dataYmax = plot->ymax = 1.0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(plot)) { delete plot; return ""; }
    }
    AddPlotOnMain(plot);
    return plot->id;
}

static bool DispatchModelMutationOnMac(const std::vector<std::string> &command,
                                       const std::string &group)
{
    int before = -1;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto model = g_groupModels.find(group);
        if (model != g_groupModels.end()) before = model->second.modelVersion;
    }
    if (MacCommandDispatcher().dispatch(command) != "OK") return false;
    std::lock_guard<std::mutex> lock(g_mutex);
    auto model = g_groupModels.find(group);
    return model != g_groupModels.end() && model->second.modelVersion != before;
}

static void ApplyVariableAction(const std::string &group, const std::string &variable, const std::string &action)
{
    const std::string command = action == "dependent" ? "MODEL_SET_Y" : "MODEL_ADD_TERM";
    if (DispatchModelMutationOnMac({command, group, variable}, group)) {
        std::string datasetGroup = group;
        { std::lock_guard<std::mutex> lock(g_mutex);
          auto found = g_groupModels.find(group);
          if (found != g_groupModels.end()) datasetGroup = found->second.group; }
        PublishSpreadPlotMessage(action == "dependent" ? "GLM_DEPENDENT_CHANGED" : "GLM_PREDICTOR_ADDED",
                                 datasetGroup, "glm:" + group, "glm:" + group);
        RecordAPICommand({command, group, variable});
    }
}

static void RemoveModelTerm(const std::string &group, const std::string &term)
{
    if (DispatchModelMutationOnMac({"MODEL_REMOVE_TERM", group, term}, group)) {
        std::string datasetGroup = group;
        { std::lock_guard<std::mutex> lock(g_mutex);
          auto found = g_groupModels.find(group);
          if (found != g_groupModels.end()) datasetGroup = found->second.group; }
        PublishSpreadPlotMessage("GLM_PREDICTOR_REMOVED", datasetGroup, "glm:" + group, "glm:" + group);
        RefreshGLMDiagnosticPlotsSynchronouslyOnMain(datasetGroup, true);
        RecordAPICommand({"MODEL_REMOVE_TERM", group, term});
    }
}

static void ClearVariableModelRole(const std::string &group, const std::string &variable)
{
    if (DispatchModelMutationOnMac({"MODEL_CLEAR_ROLE", group, variable}, group)) {
        std::string datasetGroup = group;
        { std::lock_guard<std::mutex> lock(g_mutex);
          auto found = g_groupModels.find(group);
          if (found != g_groupModels.end()) datasetGroup = found->second.group; }
        PublishSpreadPlotMessage("GLM_ROLE_CLEARED", datasetGroup, "glm:" + group, "glm:" + group);
        RefreshGLMDiagnosticPlotsSynchronouslyOnMain(datasetGroup, true);
        RecordAPICommand({"MODEL_CLEAR_ROLE", group, variable});
    }
}

static DataColumn *FindDataColumnUnlocked(const std::string &group, const std::string &variable)
{
    DataFrameModel *df = FindDataFrameUnlocked(group);
    return df ? FindDataColumnInDataFrame(*df, variable) : nullptr;
}

static const DataColumn *FindDataColumnUnlockedConst(const std::string &group, const std::string &variable)
{
    const DataFrameModel *df = FindDataFrameUnlockedConst(group);
    return df ? FindDataColumnInDataFrame(*df, variable) : nullptr;
}

static void SyncDataColumnToGroupSeedsUnlocked(const std::string &group, const DataColumn &col)
{
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (plot && plot->group == group) {
            SyncPlotVariableFromColumn(plot, col);
        }
    }
    for (auto &entry : g_correlationMatrices) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_dendrograms) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_dimensionalityModels) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_regressionComparisons) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_generalizedComparisons) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
    for (auto &entry : g_generalizedGLMs) {
        if (entry.second.group == group) SyncPlotVariableFromColumn(&entry.second.seed, col);
    }
}

static bool RebuildPlotForDataFrame(PlotModel *plot, const DataFrameModel &df)
{
    if (!plot) return false;
    if (plot->isGLMDiagnostic || plot->kind == "pca_biplot" || plot->kind == "pca_scree" ||
        plot->kind == "interaction_plot") {
        return false;
    }
    SyncPlotVariablesFromDataFrame(plot, df);
    if (plot->isDatasetSeed) {
        rlispstat::core::RefreshDatasetSeedPlotAfterVariableSync(*plot);
        return true;
    }
    if (plot->kind == "scatter") {
        if (FindVariable(plot, plot->xLabel) && FindVariable(plot, plot->yLabel)) {
            RebuildPointsForCurrentVariables(plot);
        } else {
            plot->points.clear();
        }
        ComputeScatterRangesIncludingAllImputations(plot, df);
        return true;
    }
    if (plot->kind == "time_series") {
        std::string ignored;
        return rlispstat::core::RebuildTimeSeriesFromDataFrame(*plot, df, &ignored);
    }
    if (plot->kind == "trellis_scatterplot") {
        std::string ignored;
        return rlispstat::core::RebuildTrellisScatterplotFromDataFrame(*plot, df, &ignored);
    }
    if (plot->kind == "scatter_matrix") {
        RebuildScatterMatrixPoints(plot);
        ComputeRanges(plot);
        return true;
    }
    if (plot->kind == "boxplot") {
        if (BoxplotUsesVariableAxes(plot)) {
            std::string ignored;
            RebuildParallelBoxplotPoints(plot, &ignored);
        } else {
            RebuildGroupedBoxplotPointsFromDataFrame(plot, df);
        }
        return true;
    }
    if (plot->kind == "histogram") {
        RebuildHistogramPointsFromCurrentVariable(plot);
        return true;
    }
    if (plot->kind == "barplot") {
        return rlispstat::core::RefreshBarplotFromDataFrame(*plot, df);
    }
    return false;
}

static bool OpenEquivalentPlotWithScopeOnMain(
    PlotModel *source,
    const rlispstat::core::AnalysisScope &scope,
    std::string *message = nullptr)
{
    if (!source || source->isDatasetSeed || source->isGLMDiagnostic ||
        source->kind == "pca_biplot" || source->kind == "pca_scree" ||
        source->kind == "interaction_plot") {
        if (message) *message = "This view cannot yet be cloned with another analysis scope.";
        return false;
    }

    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(source->group);
        if (!found) {
            if (message) *message = "The source dataset is no longer available.";
            return false;
        }
        dataframe = *found;
    }

    PlotModel *created = new PlotModel(*source);
    created->id = source->kind + "_scope_" +
        std::to_string(static_cast<long long>(time(nullptr))) + "_" +
        std::to_string(std::rand() % 1000000);
    created->isDatasetSeed = false;
    created->dataScope = scope;
    created->dataScopeCaptured = true;
    const auto global = MacCommandDispatcher().applicationState()
        .activeAnalysisScope(source->group);
    const auto globalRows = rlispstat::core::ResolveAnalysisScopeRowIds(
        global, global.totalDatasetRows);
    created->analysisScopeFrozen =
        !rlispstat::core::AnalysisScopeMatchesRows(scope, globalRows);
    if (created->analysisScopeFrozen) {
        created->dataScope = rlispstat::core::ExplicitAnalysisScope(
            source->group,
            rlispstat::core::ResolveAnalysisScopeRowIds(
                scope, scope.totalDatasetRows),
            rlispstat::core::AnalysisScopeSourceKind::OtherExplicitSubset,
            scope.sourceDescription,
            scope.totalDatasetRows,
            scope.sourceViewId,
            scope.sourceElementId);
    }
    if (!RebuildPlotForDataFrame(created, dataframe)) {
        delete created;
        if (message) *message = "This plot specification cannot be rebuilt for another scope.";
        return false;
    }
    ApplyCapturedAnalysisScopeToPlotUnlocked(*created);

    bool requestSmooth = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!AttachPlotModelUnlocked(created)) {
            delete created;
            if (message) *message = "The equivalent plot could not be attached.";
            return false;
        }
        requestSmooth = RequestSmoothRecomputeForPlotUnlocked(created);
    }
    AddPlotOnMain(created);
    if (requestSmooth) NotifyMainRTaskAvailable();
    return true;
}

static void RefreshOpenPlotsForGlobalScopeOnMain(const std::string &group,
                                                 bool selectionChanged)
{
    auto &application = MacCommandDispatcher().applicationState();
    const AnalysisScope global = application.activeAnalysisScope(group);
    if (selectionChanged &&
        !rlispstat::core::AnalysisScopeTracksCurrentSelection(global) &&
        global.sourceKind != rlispstat::core::AnalysisScopeSourceKind::CurrentUnselection)
        return;

    std::vector<std::string> refreshed;
    bool requestSmooth = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *dataframe = FindDataFrameUnlockedConst(group);
        if (!dataframe) return;
        for (auto &[id, plot] : g_plots) {
            if (!plot || plot->group != group || plot->isDatasetSeed ||
                rlispstat::core::PlotIsDerivedAnalysisView(*plot)) continue;
            if (plot->analysisScopeFrozen) {
                plot->frozenScopeNotice = plot->dataScopeCaptured
                    ? rlispstat::core::FrozenAnalysisScopeNotice(plot->dataScope, global)
                    : std::string{};
                refreshed.push_back(id);
                continue;
            }
            if (!RebuildPlotForDataFrame(plot, *dataframe)) continue;
            rlispstat::core::ApplyAnalysisScopeToPlot(
                *plot, global,
                static_cast<std::size_t>(std::max(0, dataframe->rows)));
            if (plot->kind == "scatter")
                ComputeScatterRangesIncludingAllImputations(plot, *dataframe);
            plot->frozenScopeNotice.clear();
            rlispstat::core::RefreshBasicPlotCodeReference(application, *plot);
            if (plot->kind != "scatter_matrix")
                rlispstat::core::InvalidateSmoothCurvesForCoordinateChange(
                    plot->smoothCurves);
            requestSmooth = RequestSmoothRecomputeForPlotUnlocked(plot) || requestSmooth;
            refreshed.push_back(id);
        }
    }
    for (const std::string &id : refreshed) {
        UpdateWindowTitleForPlotOnMain(id);
        RedrawPlotOnMain(id);
    }
    if (requestSmooth) NotifyMainRTaskAvailable();
}

static std::vector<std::string> RebuildPlotsForDataFrameUnlocked(const std::string &group, const DataFrameModel &df,
                                                                  bool refitExistingAnalyses)
{
    std::vector<std::string> changed;
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (!plot || plot->group != group) continue;
        if (RebuildPlotForDataFrame(plot, df)) {
            // Live plots follow the current dataset-wide scope. Frozen plots
            // retain the explicit row snapshot captured when they were frozen.
            if (!plot->isDatasetSeed && !
                rlispstat::core::PlotIsDerivedAnalysisView(*plot) &&
                !plot->analysisScopeFrozen) {
                rlispstat::core::ApplyAnalysisScopeToPlot(
                    *plot,
                    MacCommandDispatcher().applicationState()
                        .activeAnalysisScope(group),
                    static_cast<std::size_t>(std::max(0, df.rows)));
            } else {
                ApplyCapturedAnalysisScopeToPlotUnlocked(*plot);
            }
            changed.push_back(plot->id);
        }
    }
    for (auto &entry : g_correlationMatrices) {
        CorrelationMatrixState &state = entry.second;
        if (state.group == group) {
            SyncPlotVariablesFromDataFrame(&state.seed, df);
        }
    }
    for (auto &entry : g_dendrograms) {
        DendrogramState &state = entry.second;
        if (state.group == group) {
            SyncPlotVariablesFromDataFrame(&state.seed, df);
            if (refitExistingAnalyses) RefitDendrogramState(state);
        }
    }
    for (auto &entry : g_dimensionalityModels) {
        DimensionalityState &state = entry.second;
        if (state.group == group) {
            SyncPlotVariablesFromDataFrame(&state.seed, df);
            if (refitExistingAnalyses && state.variables.size() >= 2) {
                RefitDimensionalityState(state);
            }
        }
    }
    for (auto &entry : g_regressionComparisons) {
        if (entry.second.group == group) {
            SyncPlotVariablesFromDataFrame(&entry.second.seed, df);
        }
    }
    for (auto &entry : g_generalizedComparisons) {
        if (entry.second.group == group) {
            SyncPlotVariablesFromDataFrame(&entry.second.seed, df);
        }
    }
    for (auto &entry : g_generalizedGLMs) {
        if (entry.second.group == group) {
            SyncPlotVariablesFromDataFrame(&entry.second.seed, df);
        }
    }
    return changed;
}

static void SynchronizeVariableTypeChangeOnMac(const std::string &group, const std::string &variable,
                                               const rlispstat::core::VariableTypeChangeEffects &effects)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataColumn *column = FindDataColumnUnlocked(group, variable);
        if (column) SyncDataColumnToGroupSeedsUnlocked(group, *column);
        const DataFrameModel *dataframe = FindDataFrameUnlockedConst(group);
        if (dataframe) {
            for (auto &entry : g_groupModels) {
                if (entry.second.group == group &&
                    rlispstat::core::SynchronizeGroupModelTermTypes(entry.second, *dataframe)) {
                    rlispstat::core::MarkGroupModelChanged(entry.second);
                }
            }
        }
    }
    rlispstat::core::DatasetValueChangeEffects linkedEffects;
    linkedEffects.correlationIds = effects.correlationIds;
    linkedEffects.dendrogramIds = effects.dendrogramIds;
    linkedEffects.dimensionalityIds = effects.dimensionalityIds;
    linkedEffects.scaleAnalysisIds = effects.scaleAnalysisIds;
    linkedEffects.generalizedGlmIds = effects.generalizedGlmIds;
    linkedEffects.generalizedGlmIdsToRefit = effects.generalizedGlmIdsToRefit;
    linkedEffects.mixedModelIds = effects.mixedModelIds;
    linkedEffects.regressionComparisonIds = effects.regressionComparisonIds;
    linkedEffects.generalizedComparisonIds = effects.generalizedComparisonIds;
    linkedEffects.modelTrellisIds = effects.modelTrellisIds;
    ApplyDatasetValueChangeEffectsOnMac(group, linkedEffects);
}

static bool PrepareNumericCategoryMappingOnMac(
    const std::string &group, const std::string &variable,
    rlispstat::core::VariableTypeConversionSpecification &specification,
    std::string *message)
{
    DataColumn snapshot;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataColumn *column = FindDataColumnUnlockedConst(group, variable);
        if (!column || !VariableTypeIsFactorLike(column->type) ||
            NormalizeVariableType(column->type) == "numeric") return true;
        snapshot = *column;
    }
    const std::vector<std::string> levels = rlispstat::core::DataColumnFactorLevels(snapshot);
    if (levels.empty()) return true;
    bool numericLabels = true;
    for (const std::string &level : levels) {
        double parsed = NAN;
        if (!rlispstat::core::ParseDataCellDouble(level, parsed)) {
            numericLabels = false;
            break;
        }
    }
    if (numericLabels) return true;

    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Convert categories to Numeric"];
    [alert setInformativeText:ToNSString(
        "Confirm or edit the numeric score for every category of `" + variable +
        "`. This mapping changes the statistical meaning of the variable and is saved in its provenance.")];
    [alert addButtonWithTitle:@"Apply Mapping"];
    if (levels.size() == 2) [alert addButtonWithTitle:@"Invert Mapping"];
    [alert addButtonWithTitle:@"Cancel"];

    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(0, 0, 430,
        std::min<CGFloat>(260.0, std::max<CGFloat>(90.0, 24.0 * levels.size() + 12.0)))];
    [scroll setHasVerticalScroller:YES];
    [scroll setBorderType:NSBezelBorder];
    NSTextView *editor = [[NSTextView alloc] initWithFrame:[[scroll contentView] bounds]];
    [editor setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    std::ostringstream proposed;
    for (std::size_t index = 0; index < levels.size(); ++index)
        proposed << (index ? "\n" : "") << (levels.size() == 2 ? index : index + 1)
                 << "\t" << levels[index];
    [editor setString:ToNSString(proposed.str())];
    [scroll setDocumentView:editor];
    [alert setAccessoryView:scroll];

    const NSModalResponse response = [alert runModal];
    const bool inverted = levels.size() == 2 && response == NSAlertSecondButtonReturn;
    const NSModalResponse cancelResponse = levels.size() == 2
        ? NSAlertThirdButtonReturn : NSAlertSecondButtonReturn;
    if (response == cancelResponse) {
        if (message) *message = "Variable type change cancelled.";
        return false;
    }
    if (inverted) {
        specification.invertBinary = true;
        return true;
    }

    const char *editorUTF8 = [[editor string] UTF8String];
    const std::string editorText = editorUTF8 ? editorUTF8 : "";
    std::istringstream input{editorText};
    std::string line;
    std::map<std::string, std::string> mapping;
    while (std::getline(input, line)) {
        const std::size_t tab = line.find('\t');
        if (tab == std::string::npos) continue;
        const std::string score = TrimCopy(line.substr(0, tab));
        const std::string label = TrimCopy(line.substr(tab + 1));
        double parsed = NAN;
        if (label.empty() || !rlispstat::core::ParseDataCellDouble(score, parsed)) {
            if (message) *message = "Each mapping row must contain a numeric score, a tab, and its category label.";
            return false;
        }
        mapping[label] = score;
    }
    if (mapping.size() != levels.size()) {
        if (message) *message = "The mapping must contain every category exactly once.";
        return false;
    }
    specification.numericMapping = std::move(mapping);
    return true;
}

static bool PrepareOrdinalCategoryOrderOnMac(
    const std::string &group, const std::string &variable,
    rlispstat::core::VariableTypeConversionSpecification &specification,
    std::string *message)
{
    DataColumn snapshot;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataColumn *column = FindDataColumnUnlockedConst(group, variable);
        if (!column) return true;
        snapshot = *column;
    }
    std::vector<std::string> levels = rlispstat::core::DataColumnFactorLevels(snapshot);
    if (NormalizeVariableType(snapshot.type) == "numeric") {
        std::stable_sort(levels.begin(), levels.end(), [](const std::string &left,
                                                         const std::string &right) {
            double a = NAN, b = NAN;
            return rlispstat::core::ParseDataCellDouble(left, a) &&
                rlispstat::core::ParseDataCellDouble(right, b) && a < b;
        });
    }
    if (levels.size() < 2) return true;

    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Set category order"];
    std::string explanation = "Put every category of `" + variable +
        "` on one line, from lowest to highest. The complete order is saved with the variable.";
    if (NormalizeVariableType(snapshot.type) == "numeric" && levels.size() > 20) {
        explanation += " This will create " + std::to_string(levels.size()) +
            " ordered categories from distinct numeric values.";
    }
    [alert setInformativeText:ToNSString(explanation)];
    [alert addButtonWithTitle:@"Apply Order"];
    [alert addButtonWithTitle:@"Cancel"];
    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(
        0, 0, 430, std::min<CGFloat>(320.0, std::max<CGFloat>(100.0, 22.0 * levels.size() + 12.0)))];
    [scroll setHasVerticalScroller:YES];
    [scroll setBorderType:NSBezelBorder];
    NSTextView *editor = [[NSTextView alloc] initWithFrame:[[scroll contentView] bounds]];
    [editor setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    std::ostringstream proposed;
    for (std::size_t index = 0; index < levels.size(); ++index)
        proposed << (index ? "\n" : "") << levels[index];
    [editor setString:ToNSString(proposed.str())];
    [scroll setDocumentView:editor];
    [alert setAccessoryView:scroll];
    if ([alert runModal] != NSAlertFirstButtonReturn) {
        if (message) *message = "Variable type change cancelled.";
        return false;
    }
    const char *editorUTF8 = [[editor string] UTF8String];
    std::istringstream input{editorUTF8 ? editorUTF8 : ""};
    std::vector<std::string> order;
    std::string line;
    while (std::getline(input, line)) {
        line = TrimCopy(line);
        if (!line.empty()) order.push_back(line);
    }
    const std::set<std::string> expected(levels.begin(), levels.end());
    const std::set<std::string> supplied(order.begin(), order.end());
    if (expected != supplied || supplied.size() != order.size()) {
        if (message) *message = "Category order must contain every category exactly once.";
        return false;
    }
    specification.categoryOrder = std::move(order);
    return true;
}

static bool PrepareNumericCategoricalLevelsOnMac(
    const std::string &group, const std::string &variable,
    rlispstat::core::VariableTypeConversionSpecification &specification,
    std::string *message)
{
    DataColumn snapshot;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataColumn *column = FindDataColumnUnlockedConst(group, variable);
        if (!column || NormalizeVariableType(column->type) != "numeric") return true;
        snapshot = *column;
    }
    std::vector<std::string> levels = rlispstat::core::DataColumnFactorLevels(snapshot);
    std::stable_sort(levels.begin(), levels.end(), [](const std::string &left,
                                                     const std::string &right) {
        double a = NAN, b = NAN;
        return rlispstat::core::ParseDataCellDouble(left, a) &&
            rlispstat::core::ParseDataCellDouble(right, b) && a < b;
    });
    if (levels.size() > 20) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Create many categories?"];
        [alert setInformativeText:ToNSString(
            "Changing `" + variable + "` to Categorical will create " +
            std::to_string(levels.size()) + " categories, one for each distinct value.")];
        [alert addButtonWithTitle:@"Create Categories"];
        [alert addButtonWithTitle:@"Cancel"];
        if ([alert runModal] != NSAlertFirstButtonReturn) {
            if (message) *message = "Variable type change cancelled.";
            return false;
        }
    }
    specification.categoryOrder = std::move(levels);
    return true;
}

static bool SetVariableAnalysisType(const std::string &group, const std::string &variable,
                                    const std::string &type, std::string *message)
{
    rlispstat::core::VariableTypeConversionSpecification conversion;
    const std::string normalizedType = NormalizeVariableType(type);
    if (normalizedType == "numeric" &&
        !PrepareNumericCategoryMappingOnMac(group, variable, conversion, message)) return false;
    if (normalizedType == "ordered" &&
        !PrepareOrdinalCategoryOrderOnMac(group, variable, conversion, message)) return false;
    if (normalizedType == "factor" &&
        !PrepareNumericCategoricalLevelsOnMac(group, variable, conversion, message)) return false;
    rlispstat::core::VariableTypeChangeEffects effects;
    DataFrameModel updatedDataFrame;
    bool haveUpdatedDataFrame = false;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        changed = MacCommandDispatcher().applicationState().setVariableType(
            group, variable, type, effects, message, &conversion);
        if (changed) {
            const DataFrameModel *updated = FindDataFrameUnlockedConst(group);
            if (updated) {
                updatedDataFrame = *updated;
                haveUpdatedDataFrame = true;
            }
        }
    }
    if (!changed) return false;
    // Native metadata and converted values are canonical.  Queue their R-side
    // synchronization before any affected model refits, matching the Windows
    // path and preventing a stale R registry from restoring the old type.
    if (haveUpdatedDataFrame && !QueueNativeDatasetSyncToR(updatedDataFrame) && message) {
        *message += " The native data were updated, but synchronization with R could not be queued.";
    }
    SynchronizeVariableTypeChangeOnMac(group, variable, effects);
    RecordAPICommand({"SET_VARIABLE_TYPE", group, variable, normalizedType});
    return true;
}

static std::string VariableInformationText(const std::string &group, const std::string &variable)
{
    std::lock_guard<std::mutex> lock(g_mutex);
    const DataFrameModel *df = FindDataFrameUnlockedConst(group);
    if (!df) return rlispstat::core::VariableNotFoundInDatasetStatus(variable, group);
    return rlispstat::core::VariableInformationText(*df, variable);
}

static bool AddDerivedDataColumnForGroup(const std::string &group, const std::string &source,
                                         const std::string &kind, std::string *message)
{
    if (group.empty()) {
        if (message) *message = rlispstat::core::NoActiveDatasetStatus();
        return false;
    }

    std::vector<std::string> plotsToRedraw;
    std::string createdName;
    DataFrameModel updatedDataFrame;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *registered = FindDataFrameUnlocked(group);
        if (!registered) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        if (MacCommandDispatcher().applicationState().datasetCalculationPending(group)) {
            if (message) *message = "Wait for the current R calculation before editing this sheet.";
            return false;
        }
        DataFrameModel &df = *registered;
        std::set<int> selectedRows;
        std::map<int, std::string> rowColors;
        auto selectionIt = g_groupSelections.find(group);
        if (selectionIt != g_groupSelections.end()) {
            selectedRows = selectionIt->second;
        }
        auto colorIt = g_groupPointColors.find(group);
        if (colorIt != g_groupPointColors.end()) {
            rowColors = colorIt->second;
        }
        if (!rlispstat::core::AddDerivedDataColumn(df,
                                                   source,
                                                   kind,
                                                   selectedRows,
                                                   rowColors,
                                                   &createdName,
                                                   message)) {
            return false;
        }
        updatedDataFrame = df;
    }
    // The new column is already visible in the native sheet.  Publish that
    // exact version to R before queuing any linked analysis refits; otherwise
    // compare-means and GLM cannot see it in their model specifications.
    const bool syncQueued = QueueNativeDatasetSyncToR(updatedDataFrame);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        // A newly appended selection/colour factor cannot change a tree or
        // dimensionality analysis built from the existing numeric variables.
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, updatedDataFrame, false);
    }
    for (const std::string &plotId : plotsToRedraw) {
        RedrawPlotOnMain(plotId);
    }
    RefreshDataDeskWindowsOnMain(group);
    RefreshDendrogramWindowsOnMain(group);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
    if (message) {
        *message = rlispstat::core::DerivedDataColumnAddedStatus(createdName, group);
        if (!syncQueued) *message += " R synchronization could not be queued; linked analyses need refitting.";
    }
    return true;
}

static bool AddDerivedDataColumnFromPlot(PlotModel *model, const std::string &kind, std::string *message)
{
    std::string group;
    std::string source = "dataset";
    if (model) {
        group = model->group;
        source = rlispstat::core::PlotDerivedColumnSourceLabel(model->title,
                                                               model->yLabel,
                                                               model->xLabel);
    } else {
        std::lock_guard<std::mutex> lock(g_mutex);
        group = ActiveDatasetGroupUnlocked();
    }
    return AddDerivedDataColumnForGroup(group, source, kind, message);
}

static rlispstat::core::DatasetValueChangeEffects RenameVariableReferencesUnlocked(
    const std::string &group, const std::string &oldName, const std::string &newName)
{
    for (auto &entry : g_plots) {
        PlotModel *plot = entry.second;
        if (!plot || plot->group != group) continue;
        if (plot->xLabel == oldName) plot->xLabel = newName;
        if (plot->yLabel == oldName) plot->yLabel = newName;
        RenameVariableInTermList(plot->scatterMatrixVariables, oldName, newName);
        RenameVariableInTermList(plot->boxplotVariables, oldName, newName);
        RenameVariableInTermList(plot->barplotXVariables, oldName, newName);
        if (plot->barplotSplitVariable == oldName) plot->barplotSplitVariable = newName;
        if (plot->glmInteractionTerm == oldName) plot->glmInteractionTerm = newName;
    }
    return MacCommandDispatcher().applicationState().applyVariableRename(
        group, oldName, newName);
}

static bool RenameDataColumn(const std::string &group, const std::string &oldName,
                             const std::string &newName, std::string *message)
{
    std::vector<std::string> plotsToRedraw;
    DataFrameModel updatedDataFrame;
    rlispstat::core::DatasetValueChangeEffects effects;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *registered = FindDataFrameUnlocked(group);
        if (!registered) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        if (MacCommandDispatcher().applicationState().datasetCalculationPending(group)) {
            if (message) *message = "Wait for the current R calculation before editing this sheet.";
            return false;
        }
        DataFrameModel &df = *registered;
        if (oldName == newName) {
            if (message) *message = rlispstat::core::DatasetVariableNameUnchangedStatus();
            return true;
        }
        if (!rlispstat::core::RenameDataFrameColumn(df, oldName, newName, message)) {
            return false;
        }
        effects = RenameVariableReferencesUnlocked(group, oldName, newName);
        updatedDataFrame = df;
    }
    const bool syncQueued = QueueNativeDatasetSyncToR(updatedDataFrame);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, updatedDataFrame);
    }
    ApplyDatasetValueChangeEffectsOnMac(
        group, effects, plotsToRedraw, syncQueued);
    if (message) {
        *message = rlispstat::core::VariableRenamedStatus(oldName, newName);
        if (!syncQueued) *message += " R synchronization could not be queued; linked analyses need refitting.";
    }
    return true;
}

static bool DatasetCalculationPendingUnlocked(const std::string &group)
{
    return MacCommandDispatcher().applicationState().datasetCalculationPending(group);
}

static void ApplyDatasetValueChangeEffectsOnMac(
    const std::string &group,
    const rlispstat::core::DatasetValueChangeEffects &effects,
    const std::vector<std::string> &plotsToRedraw,
    bool refitAffectedAnalyses)
{
    if (refitAffectedAnalyses) {
        for (const std::string &id : effects.correlationIds) {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto state = g_correlationMatrices.find(id);
            if (state != g_correlationMatrices.end() &&
                g_correlationMatrixControllers.count(id))
                RefitCorrelationMatrixState(state->second);
        }
        for (const std::string &id : effects.dendrogramIds) {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto state = g_dendrograms.find(id);
            if (state != g_dendrograms.end() && g_dendrogramControllers.count(id))
                RefitDendrogramState(state->second);
        }
        for (const std::string &id : effects.dimensionalityIds) {
            DimensionalityState *state = nullptr;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = g_dimensionalityModels.find(id);
                if (found != g_dimensionalityModels.end() &&
                    g_dimensionalityControllers.count(id))
                    state = &found->second;
            }
            if (!state) continue;
            if (state->autoFit) {
                RefitDimensionalityState(*state);
            } else {
                state->status =
                    "Auto-fit is off. Displaying the last completed result; "
                    "turn it on to analyse the changed data.";
            }
        }
        for (const std::string &id : effects.scaleAnalysisIds) {
            auto state = g_scaleAnalyses.find(id);
            if (state == g_scaleAnalyses.end() ||
                !g_scaleAnalysisControllers.count(id)) continue;
            if (state->second.autoFit && state->second.specification.items.size() >= 2)
                RequestScaleAnalysisFitInMainR(state->second);
        }
        for (const std::string &id : effects.generalizedGlmIdsToRefit) {
            auto state = g_generalizedGLMs.find(id);
            if (state != g_generalizedGLMs.end())
                RequestGeneralizedGLMFitInMainR(state->second);
        }
        for (const std::string &id : effects.regressionComparisonIds) {
            auto state = g_regressionComparisons.find(id);
            if (state == g_regressionComparisons.end()) continue;
            if (state->second.autoRefit) {
                RefitRegressionComparisonModels(state->second, false);
            } else {
                state->second.frozenScopeNotice =
                    "Auto-refit is off. Displaying the last completed result for the previous data.";
            }
        }
        for (const std::string &id : effects.generalizedComparisonIds) {
            auto state = g_generalizedComparisons.find(id);
            if (state == g_generalizedComparisons.end()) continue;
            if (state->second.autoRefit) {
                RefitGeneralizedComparisonModels(state->second, false);
            } else {
                state->second.frozenScopeNotice =
                    "Auto-refit is off. Displaying the last completed result for the previous data.";
            }
        }
        for (const std::string &id : effects.modelTrellisIds)
            RequestModelTrellisFit(id);

        for (const std::string &id : effects.mixedModelIds) {
            NativeMixedModelState state;
            bool shouldRefit = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto found = MacCommandDispatcher().applicationState().nativeMixedModels().find(id);
                shouldRefit = found != MacCommandDispatcher().applicationState().nativeMixedModels().end() &&
                    g_mixedModelControllers.count(id);
                if (shouldRefit) state = found->second;
            }
            if (shouldRefit) QueueMixedModelMainRTask(state);
        }

        // These result windows live in the native presentation layer rather
        // than ApplicationState, so they must join the same post-edit refit
        // path explicitly.  Keep their captured scope, but recompute against
        // the edited data.
        RefitOpenTable1WindowsOnMain(group, false);
        RefreshMeanComparisonSelectionScopesOnMain(group, true);
    }

    for (const std::string &plotId : plotsToRedraw) RedrawPlotOnMain(plotId);
    for (const std::string &id : effects.generalizedGlmIds)
        RefreshGeneralizedGLMOnMain(id);
    for (const std::string &id : effects.modelTrellisIds)
        RefreshModelTrellisOnMain(id);
    for (const std::string &id : effects.scaleAnalysisIds)
        ShowScaleAnalysisOnMain(id);
    RefreshDataDeskWindowsOnMain(group);
    RefreshDendrogramWindowsOnMain(group);
    RefreshGLMOnMain(group);
    RefreshRegressionComparisonWindowsOnMain(group, false);
    RefreshGeneralizedComparisonWindowsOnMain(group, false);
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(group, true);
    RedrawGroupViewsSynchronouslyOnMain(group, true);
    UpdatePanelOnMain();
}

static bool SetDataFrameCellValueForGroup(const std::string &group,
                                          const std::string &variable,
                                          std::size_t row,
                                          const std::string &value,
                                          std::string *message)
{
    std::vector<std::string> plotsToRedraw;
    DataFrameModel updatedDataFrame;
    rlispstat::core::DatasetValueChangeEffects effects;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (DatasetCalculationPendingUnlocked(group)) {
            if (message) *message = "Wait for the current R calculation before editing this sheet.";
            return false;
        }
        DataFrameModel *registered = FindDataFrameUnlocked(group);
        if (!registered) {
            if (message) *message = DatasetNotRegisteredStatus(group);
            return false;
        }
        if (!rlispstat::core::SetDataFrameCellValue(*registered, variable, row, value, message)) {
            return false;
        }
        effects = MacCommandDispatcher().applicationState().applyDatasetValueChange(group, variable);
        updatedDataFrame = *registered;
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, *registered);
    }
    const bool syncQueued = QueueNativeDatasetSyncToR(updatedDataFrame);
    if (!syncQueued && message)
        *message += " The cell changed, but synchronization with R could not be queued; affected analyses need refitting after synchronization.";
    ApplyDatasetValueChangeEffectsOnMac(
        group, effects, plotsToRedraw, syncQueued);
    return true;
}

static bool SetVariableDescription(const std::string &group, const std::string &variable,
                                   const std::string &description, std::string *message)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataColumn *col = FindDataColumnUnlocked(group, variable);
        if (!col) {
            if (message) *message = rlispstat::core::VariableNotFoundStatus(variable);
            return false;
        }
        rlispstat::core::SetDataColumnDescription(*col, description);
    }
    RefreshDataDeskWindowsOnMain(group);
    if (message) *message = rlispstat::core::VariableDescriptionChangedStatus(variable);
    return true;
}

static bool SetVariableDecimals(const std::string &group, const std::string &variable,
                                int decimals, std::string *message)
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataColumn *col = FindDataColumnUnlocked(group, variable);
        if (!col) {
            if (message) *message = rlispstat::core::VariableNotFoundStatus(variable);
            return false;
        }
        if (!rlispstat::core::SetDataColumnDecimals(*col, decimals, message)) {
            return false;
        }
    }
    RefreshDataDeskWindowsOnMain(group);
    if (message) *message = rlispstat::core::VariableDecimalsChangedStatus(variable, decimals);
    return true;
}

@interface VariablesWindowController : NSObject <NSTableViewDataSource, NSTableViewDelegate>
{
    std::string _group;
    NSWindow *_window;
    NSTableView *_table;
    NSTextField *_statusField;
    NSTextField *_decimalEditorField;
    NSStepper *_decimalEditorStepper;
    NSButton *_decimalAutomaticButton;
}
- (instancetype)initWithGroup:(const std::string &)group;
- (void)show;
- (void)refresh;
- (void)variableCellClicked:(id)sender;
- (void)makeDependent:(id)sender;
- (void)addPredictor:(id)sender;
- (void)removePredictor:(id)sender;
- (void)clearRole:(id)sender;
- (void)setVariableTypeFromMenu:(id)sender;
- (void)decimalStepperChanged:(id)sender;
- (void)decimalAutomaticChanged:(id)sender;
@end

@implementation VariablesWindowController
- (instancetype)initWithGroup:(const std::string &)group
{
    self = [super init];
    if (self) {
        _group = group;
        _window = [[NSWindow alloc]
            initWithContentRect:NSMakeRect(110, 190, 760, 520)
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                 NSWindowStyleMaskResizable | NSWindowStyleMaskMiniaturizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setTitle:ToNSString(VariableViewWindowTitle(group))];
        [_window setMinSize:NSMakeSize(620, 420)];
        NSView *content = [_window contentView];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];

        NSTextField *title = GLMLabel(ToNSString(VariableViewTitle()), NSMakeRect(18, 480, 220, 26), 18, NSFontWeightSemibold);
        [content addSubview:title];
        NSTextField *hint = GLMLabel(ToNSString(VariableViewInstructionText()), NSMakeRect(18, 456, 700, 22), 12, NSFontWeightRegular);
        [hint setTextColor:[NSColor colorWithCalibratedWhite:0.38 alpha:1.0]];
        [content addSubview:hint];

        NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(18, 54, 724, 394)];
        [scroll setBorderType:NSBezelBorder];
        [scroll setHasVerticalScroller:YES];
        [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        _table = [[NSTableView alloc] initWithFrame:[[scroll contentView] bounds]];
        [_table setDelegate:self];
        [_table setDataSource:self];
        [_table setUsesAlternatingRowBackgroundColors:NO];
        [_table setBackgroundColor:WorkbenchSurfaceColor()];
        [_table setRowHeight:28.0];
        [_table setTarget:self];
        [_table setAction:@selector(variableCellClicked:)];
        if (rlispstat::core::DefaultVariableRolesExperimentalFeatureEnabled()) {
            [_table setDoubleAction:@selector(doubleClickVariable:)];
        }

        NSTableColumn *nameColumn = [[NSTableColumn alloc] initWithIdentifier:@"name"];
        [[nameColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatNameColumnHeader())];
        [nameColumn setWidth:150];
        [nameColumn setEditable:YES];
        [_table addTableColumn:nameColumn];
        NSTableColumn *typeColumn = [[NSTableColumn alloc] initWithIdentifier:@"type"];
        [[typeColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatTypeColumnHeader())];
        [typeColumn setWidth:90];
        [typeColumn setEditable:NO];
        [_table addTableColumn:typeColumn];
        NSTableColumn *decimalsColumn = [[NSTableColumn alloc] initWithIdentifier:@"decimals"];
        [[decimalsColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatDecimalsColumnHeader())];
        [decimalsColumn setWidth:76];
        [decimalsColumn setEditable:NO];
        [_table addTableColumn:decimalsColumn];
        if (rlispstat::core::DefaultVariableRolesExperimentalFeatureEnabled()) {
            NSTableColumn *roleColumn = [[NSTableColumn alloc] initWithIdentifier:@"role"];
            [[roleColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatRoleColumnHeader())];
            [roleColumn setWidth:145];
            [roleColumn setEditable:NO];
            [_table addTableColumn:roleColumn];
        }
        NSTableColumn *descriptionColumn = [[NSTableColumn alloc] initWithIdentifier:@"description"];
        [[descriptionColumn headerCell] setStringValue:ToNSString(rlispstat::core::FormatDescriptionColumnHeader())];
        [descriptionColumn setWidth:280];
        [descriptionColumn setEditable:YES];
        [_table addTableColumn:descriptionColumn];
        [scroll setDocumentView:_table];
        [content addSubview:scroll];

        const rlispstat::core::VariableViewContextMenuTitles menuTitles = rlispstat::core::DefaultVariableViewContextMenuTitles();
        std::vector<rlispstat::core::LinkedPlotCommandOption> roleOptions = rlispstat::core::VariableViewRoleOptions();
        NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.root)];
        if (rlispstat::core::DefaultVariableRolesExperimentalFeatureEnabled()) {
            NSMenuItem *roleItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.role) action:nil keyEquivalent:@""];
            NSMenu *roleMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.role)];
            [roleMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[0].title) action:@selector(makeDependent:) keyEquivalent:@""]];
            [roleMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[1].title) action:@selector(addPredictor:) keyEquivalent:@""]];
            [roleMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[2].title) action:@selector(clearRole:) keyEquivalent:@""]];
            [menu setSubmenu:roleMenu forItem:roleItem];
            [menu addItem:roleItem];
        }
        NSMenuItem *typeItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.type) action:nil keyEquivalent:@""];
        NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.type)];
        for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::VariableViewTypeOptions()) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                          action:@selector(setVariableTypeFromMenu:)
                                                   keyEquivalent:@""];
            [item setRepresentedObject:ToNSString(option.value)];
            [typeMenu addItem:item];
        }
        [menu setSubmenu:typeMenu forItem:typeItem];
        [menu addItem:typeItem];
        [menu addItem:[NSMenuItem separatorItem]];
        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.editDescription) action:@selector(editSelectedVariableDescription:) keyEquivalent:@""]];
        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.showVariableInformation) action:@selector(showSelectedVariableInformation:) keyEquivalent:@""]];
        for (NSMenuItem *item in [menu itemArray]) {
            if ([item action]) {
                [item setTarget:self];
            }
            if ([item submenu]) {
                for (NSMenuItem *child in [[item submenu] itemArray]) {
                    if ([child action]) {
                        [child setTarget:self];
                    }
                }
            }
        }
        [_table setMenu:menu];

        _statusField = GLMLabel(@"", NSMakeRect(18, 18, 724, 22), 12, NSFontWeightRegular);
        [_statusField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
        [content addSubview:_statusField];
        [self refresh];
    }
    return self;
}

- (PlotModel *)plot
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return EnsureDatasetSeedPlotUnlocked(_group);
}

- (std::vector<VariableViewRow>)variables
{
    std::lock_guard<std::mutex> lock(g_mutex);
    std::vector<VariableViewRow> vars;
    const DataFrameModel *df = FindDataFrameUnlockedConst(_group);
    if (df) {
        return VariableViewRowsForDataFrame(*df);
    }
    PlotModel *plot = FirstPlotForGroupUnlocked(_group);
    if (!plot) return vars;
    if (!plot->variableMeta.empty()) {
        for (const VariableMeta &var : plot->variableMeta) {
            vars.push_back(VariableViewRow{var.name, var.type, "", -1});
        }
        return vars;
    }
    for (const NumericVariable &var : plot->variables) {
        vars.push_back(VariableViewRow{var.name, "numeric", "", -1});
    }
    return vars;
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    return (NSInteger)[self variables].size();
}

- (id)tableView:(NSTableView *)tableView objectValueForTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) {
        return @"";
    }
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"name"]) {
        return ToNSString(vars[(size_t)row].name);
    }
    if ([identifier isEqualToString:@"type"]) {
        return ToNSString(rlispstat::core::VariableTypeDisplayName(vars[(size_t)row].type));
    }
    if ([identifier isEqualToString:@"decimals"]) {
        if (vars[(size_t)row].type != "numeric") {
            return @"";
        }
        int decimals = vars[(size_t)row].decimals;
        return decimals < 0 ? ToNSString(rlispstat::core::FormatAutoLabel()) : [NSString stringWithFormat:@"%d", decimals];
    }
    if ([identifier isEqualToString:@"description"]) {
        return ToNSString(vars[(size_t)row].description);
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    return ToNSString(rlispstat::core::VariableRoleDisplayName(
        DefaultVariableRoleForGroupUnlocked(_group, vars[(size_t)row].name)));
}

- (void)tableView:(NSTableView *)tableView setObjectValue:(id)object forTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row
{
    (void)tableView;
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) return;
    std::string variable = vars[(size_t)row].name;
    std::string value = object ? [[object description] UTF8String] : "";
    value = TrimCopy(value);
    NSString *identifier = [tableColumn identifier];
    std::string message;
    if ([identifier isEqualToString:@"name"]) {
        if (RenameDataColumn(_group, variable, value, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    } else if ([identifier isEqualToString:@"type"]) {
        std::string normalized = NormalizeVariableType(value);
        if (SetVariableAnalysisType(_group, variable, normalized, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    } else if ([identifier isEqualToString:@"decimals"]) {
        int decimals = -1;
        std::string lowered = LowerCopy(value);
        if (!value.empty() && lowered != "auto" && lowered != "automatic") {
            char *end = nullptr;
            long parsed = std::strtol(value.c_str(), &end, 10);
            while (end && *end && std::isspace((unsigned char)*end)) ++end;
            if (!end || *end != '\0') {
                [_statusField setStringValue:ToNSString(rlispstat::core::VariableDecimalsInvalidStatus(false))];
                [self refresh];
                return;
            }
            decimals = (int)parsed;
        }
        if (SetVariableDecimals(_group, variable, decimals, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    } else if ([identifier isEqualToString:@"description"]) {
        if (SetVariableDescription(_group, variable, value, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
    }
    [self refresh];
}

- (std::string)selectedVariable
{
    NSInteger row = [_table selectedRow];
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) {
        return "";
    }
    return vars[(size_t)row].name;
}

- (std::string)variableAtRow:(NSInteger)row
{
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) {
        return "";
    }
    return vars[(size_t)row].name;
}

- (void)showRoleMenuForRow:(NSInteger)row column:(NSInteger)column
{
    std::string variable = [self variableAtRow:row];
    if (variable.empty()) return;
    [_table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];
    std::string role;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        role = DefaultVariableRoleForGroupUnlocked(_group, variable);
    }
    const rlispstat::core::VariableViewContextMenuTitles menuTitles = rlispstat::core::DefaultVariableViewContextMenuTitles();
    std::vector<rlispstat::core::LinkedPlotCommandOption> roleOptions = rlispstat::core::VariableViewRoleOptions();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.role)];
    NSMenuItem *dependent = [[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[0].title) action:@selector(makeDependent:) keyEquivalent:@""];
    [dependent setTarget:self];
    [dependent setState:role == "dependent" ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:dependent];
    NSMenuItem *predictor = [[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[1].title) action:@selector(addPredictor:) keyEquivalent:@""];
    [predictor setTarget:self];
    [predictor setState:role == "independent" ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:predictor];
    NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:ToNSString(roleOptions[2].title) action:@selector(clearRole:) keyEquivalent:@""];
    [none setTarget:self];
    [none setState:(role != "dependent" && role != "independent") ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:none];

    NSRect cellRect = NSIntersectionRect([_table rectOfRow:row], [_table rectOfColumn:column]);
    NSPoint point = NSMakePoint(NSMinX(cellRect) + 6.0, NSMaxY(cellRect));
    [menu popUpMenuPositioningItem:nil atLocation:point inView:_table];
}

- (void)showTypeMenuForRow:(NSInteger)row column:(NSInteger)column
{
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) return;
    std::string variable = vars[(size_t)row].name;
    std::string current = NormalizeVariableType(vars[(size_t)row].type);
    if (current == "logical") current = "factor";
    [_table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];

    const rlispstat::core::VariableViewContextMenuTitles menuTitles = rlispstat::core::DefaultVariableViewContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.type)];
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::VariableViewTypeOptions()) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:@selector(setVariableTypeFromMenu:)
                                               keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(option.value)];
        [item setState:current == option.value ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }

    NSRect cellRect = NSIntersectionRect([_table rectOfRow:row], [_table rectOfColumn:column]);
    NSPoint point = NSMakePoint(NSMinX(cellRect) + 6.0, NSMaxY(cellRect));
    NSString *editingStatus = ToNSString(rlispstat::core::VariableTypeEditingStatus(variable));
    [_statusField setStringValue:editingStatus];
    [menu popUpMenuPositioningItem:nil atLocation:point inView:_table];
    // popUpMenuPositioningItem is synchronous: a selected item has already
    // written the success/error status by the time it returns.  Only replace
    // the temporary prompt when the menu was dismissed without a choice.
    if ([[_statusField stringValue] isEqualToString:editingStatus]) {
        [_statusField setStringValue:@"Type unchanged."];
    }
}

- (void)showDecimalsEditorForRow:(NSInteger)row column:(NSInteger)column
{
    (void)column;
    std::vector<VariableViewRow> vars = [self variables];
    if (row < 0 || (size_t)row >= vars.size()) return;
    const VariableViewRow &var = vars[(size_t)row];
    [_table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row] byExtendingSelection:NO];
    if (var.type != "numeric") {
        [_statusField setStringValue:ToNSString(rlispstat::core::VariableDecimalsUnavailableStatus(var.name, var.type))];
        return;
    }

    int current = var.decimals;
    int editorValue = current >= 0 ? current : 2;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:ToNSString("Decimals for " + var.name)];
    [alert setInformativeText:ToNSString(rlispstat::core::VariableDecimalsInfoText())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertApplyButtonTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];

    NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 280, 72)];
    _decimalAutomaticButton = [[NSButton alloc] initWithFrame:NSMakeRect(0, 48, 220, 20)];
    [_decimalAutomaticButton setButtonType:NSButtonTypeSwitch];
    [_decimalAutomaticButton setTitle:ToNSString(rlispstat::core::VariableDecimalsAutoButtonTitle())];
    [_decimalAutomaticButton setState:current < 0 ? NSControlStateValueOn : NSControlStateValueOff];
    [_decimalAutomaticButton setTarget:self];
    [_decimalAutomaticButton setAction:@selector(decimalAutomaticChanged:)];
    [accessory addSubview:_decimalAutomaticButton];

    NSTextField *label = GLMLabel(ToNSString(rlispstat::core::FormatFixedDecimalsLabel()), NSMakeRect(0, 15, 100, 20), 12, NSFontWeightRegular);
    [accessory addSubview:label];
    _decimalEditorField = [[NSTextField alloc] initWithFrame:NSMakeRect(108, 11, 56, 24)];
    [_decimalEditorField setStringValue:[NSString stringWithFormat:@"%d", editorValue]];
    [_decimalEditorField setAlignment:NSTextAlignmentRight];
    [accessory addSubview:_decimalEditorField];
    _decimalEditorStepper = [[NSStepper alloc] initWithFrame:NSMakeRect(170, 8, 22, 28)];
    [_decimalEditorStepper setMinValue:0.0];
    [_decimalEditorStepper setMaxValue:12.0];
    [_decimalEditorStepper setIncrement:1.0];
    [_decimalEditorStepper setDoubleValue:(double)editorValue];
    [_decimalEditorStepper setTarget:self];
    [_decimalEditorStepper setAction:@selector(decimalStepperChanged:)];
    [accessory addSubview:_decimalEditorStepper];
    [self decimalAutomaticChanged:_decimalAutomaticButton];

    [alert setAccessoryView:accessory];
    if ([alert runModal] == NSAlertFirstButtonReturn) {
        std::string message;
        int decimals = -1;
        if ([_decimalAutomaticButton state] != NSControlStateValueOn) {
            std::string text = TrimCopy(std::string([[_decimalEditorField stringValue] UTF8String]));
            char *end = nullptr;
            long parsed = std::strtol(text.c_str(), &end, 10);
            while (end && *end && std::isspace((unsigned char)*end)) ++end;
            if (text.empty() || !end || *end != '\0' || parsed < 0 || parsed > 12) {
                [_statusField setStringValue:ToNSString(rlispstat::core::VariableDecimalsInvalidStatus(true))];
                [self refresh];
                return;
            }
            decimals = (int)parsed;
        }
        if (SetVariableDecimals(_group, var.name, decimals, &message)) {
            [_statusField setStringValue:ToNSString(message)];
        } else {
            [_statusField setStringValue:ToNSString(message)];
        }
        [self refresh];
    }
    _decimalEditorField = nil;
    _decimalEditorStepper = nil;
    _decimalAutomaticButton = nil;
}

- (void)variableCellClicked:(id)sender
{
    (void)sender;
    NSInteger row = [_table clickedRow];
    NSInteger column = [_table clickedColumn];
    if (row < 0 || column < 0) return;
    NSTableColumn *tableColumn = [[_table tableColumns] objectAtIndex:(NSUInteger)column];
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"role"]) {
        [self showRoleMenuForRow:row column:column];
        return;
    }
    if ([identifier isEqualToString:@"type"]) {
        [self showTypeMenuForRow:row column:column];
        return;
    }
    if ([identifier isEqualToString:@"decimals"]) {
        [self showDecimalsEditorForRow:row column:column];
        return;
    }
    if ([tableColumn isEditable]) {
        [_table editColumn:column row:row withEvent:nil select:YES];
    }
}

- (void)doubleClickVariable:(id)sender
{
    std::string variable = [self selectedVariable];
    if (variable.empty()) {
        return;
    }
    bool hasDependent = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto roles = MacCommandDispatcher().applicationState().variableRoles(_group);
        hasDependent = std::any_of(roles.begin(), roles.end(), [](const auto &entry) {
            return entry.second == "dependent";
        });
    }
    std::string message;
    SetDefaultVariableRoleOnMac(
        _group, variable, hasDependent ? "independent" : "dependent", &message);
    [self refresh];
    [_statusField setStringValue:ToNSString(message)];
}

- (void)makeDependent:(id)sender
{
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        std::string message;
        SetDefaultVariableRoleOnMac(_group, variable, "dependent", &message);
        [self refresh];
        [_statusField setStringValue:ToNSString(message)];
    }
}

- (void)addPredictor:(id)sender
{
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        std::string message;
        SetDefaultVariableRoleOnMac(_group, variable, "independent", &message);
        [self refresh];
        [_statusField setStringValue:ToNSString(message)];
    }
}

- (void)removePredictor:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        std::string message;
        SetDefaultVariableRoleOnMac(_group, variable, "none", &message);
        [self refresh];
        [_statusField setStringValue:ToNSString(message)];
    }
}

- (void)clearRole:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (!variable.empty()) {
        std::string message;
        SetDefaultVariableRoleOnMac(_group, variable, "none", &message);
        [self refresh];
        [_statusField setStringValue:ToNSString(message)];
    }
}

- (void)setSelectedVariableType:(const std::string &)type
{
    std::string variable = [self selectedVariable];
    if (variable.empty()) return;
    std::string message;
    if (!SetVariableAnalysisType(_group, variable, type, &message)) {
        [_statusField setStringValue:ToNSString(message)];
        [self refresh];
        ShowWorkbenchMessageOnMain(@"Change Variable Type", ToNSString(message));
        return;
    }
    [_statusField setStringValue:ToNSString(message)];
    [self refresh];
}

- (void)setVariableTypeFromMenu:(id)sender
{
    NSString *typeString = [sender representedObject];
    std::string type = typeString ? NormalizeVariableType(std::string([typeString UTF8String])) : "";
    [self setSelectedVariableType:type];
}

- (void)treatSelectedVariableAsNumeric:(id)sender
{
    (void)sender;
    [self setSelectedVariableType:"numeric"];
}

- (void)treatSelectedVariableAsFactor:(id)sender
{
    (void)sender;
    [self setSelectedVariableType:"factor"];
}

- (void)treatSelectedVariableAsText:(id)sender
{
    (void)sender;
    [self setSelectedVariableType:"character"];
