- (void)decimalStepperChanged:(id)sender
{
    (void)sender;
    if (!_decimalEditorStepper || !_decimalEditorField) return;
    long value = lrint([_decimalEditorStepper doubleValue]);
    [_decimalEditorField setStringValue:[NSString stringWithFormat:@"%ld", value]];
}

- (void)decimalAutomaticChanged:(id)sender
{
    (void)sender;
    BOOL automatic = _decimalAutomaticButton && [_decimalAutomaticButton state] == NSControlStateValueOn;
    [_decimalEditorField setEnabled:!automatic];
    [_decimalEditorStepper setEnabled:!automatic];
}

- (void)editSelectedVariableDescription:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (variable.empty()) return;
    std::string current;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataColumn *col = FindDataColumnUnlockedConst(_group, variable);
        if (col) current = col->description;
    }
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:ToNSString(VariableDescriptionDialogTitle(variable))];
    [alert setInformativeText:ToNSString(VariableDescriptionDialogInformationText())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertApplyButtonTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(0, 0, 420, 110)];
    NSTextView *textView = [[NSTextView alloc] initWithFrame:NSMakeRect(0, 0, 420, 110)];
    [textView setString:ToNSString(current)];
    [scroll setDocumentView:textView];
    [scroll setHasVerticalScroller:YES];
    [alert setAccessoryView:scroll];
    if ([alert runModal] == NSAlertFirstButtonReturn) {
        std::string message;
        SetVariableDescription(_group, variable, std::string([[textView string] UTF8String]), &message);
        [_statusField setStringValue:ToNSString(message)];
        [self refresh];
    }
}

- (void)showSelectedVariableInformation:(id)sender
{
    (void)sender;
    std::string variable = [self selectedVariable];
    if (variable.empty()) return;
    ShowWorkbenchMessageOnMain(ToNSString(VariableInformationDialogTitle()), ToNSString(VariableInformationText(_group, variable)));
}

- (void)show
{
    AssociateWindowWithDataset(_window, _group);
    [_window orderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)refresh
{
    [_table reloadData];
    if (!rlispstat::core::DefaultVariableRolesExperimentalFeatureEnabled()) {
        [_statusField setStringValue:ToNSString(
            std::to_string([self variables].size()) + " variables in " + _group)];
        return;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    const auto roles = MacCommandDispatcher().applicationState().variableRoles(_group);
    std::string dependent;
    std::size_t independents = 0;
    for (const auto &[variable, role] : roles) {
        if (role == "dependent") dependent = variable;
        else if (role == "independent") ++independents;
    }
    [_statusField setStringValue:ToNSString(
        rlispstat::core::VariableViewModelRoleSummary(dependent, independents))];
}
@end

