@implementation DataSheetRowView
- (void)drawBackgroundInRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    DataSheetRowStyle style = DataSheetStyleForRow(std::string([self.groupName UTF8String]), (int)self.originalRow, [self isSelected]);
    if (style.customBackground) {
        [style.background setFill];
        NSRectFill([self bounds]);
    } else {
