static void ConfigureSharedDataSheetTable(NSTableView *table, bool readOnly)
{
    if (!table) return;
    [table setUsesAlternatingRowBackgroundColors:NO];
    [table setBackgroundColor:WorkbenchSurfaceColor()];
    [table setAllowsMultipleSelection:YES];
    [table setAllowsColumnSelection:!readOnly];
    [table setSelectionHighlightStyle:NSTableViewSelectionHighlightStyleNone];
    [table setRowHeight:24.0];
    [table setIntercellSpacing:NSMakeSize(0.0, 0.0)];
    [table setAllowsColumnResizing:YES];
    [table setAllowsColumnReordering:!readOnly];
    [table setAllowsTypeSelect:YES];
}

@class TrellisPanelTableAdapter;

@interface TrellisPanelTableView : NSTableView
@property(nonatomic, assign) ScatterView *trellisOwner;
@property(nonatomic, copy) NSString *panelLevelId;
@property(nonatomic, assign) TrellisPanelTableAdapter *panelAdapter;
@end

@interface TrellisPanelTableAdapter : NSObject <NSTableViewDataSource, NSTableViewDelegate>
{
    std::string _group;
    DataFrameModel _dataFrame;
    std::vector<int> _rows;
    std::vector<std::string> _variables;
    BOOL _updatingSelection;
}
@property(nonatomic, assign) ScatterView *owner;
@property(nonatomic, assign) TrellisPanelTableView *tableView;
- (instancetype)initWithGroup:(const std::string &)group owner:(ScatterView *)owner;
- (void)updateDataFrame:(const DataFrameModel &)dataFrame
                   rows:(const std::vector<int> &)rows
              variables:(const std::vector<std::string> &)variables;
- (NSInteger)originalRowAtVisualRow:(NSInteger)row;
- (const std::vector<int> &)originalRows;
- (void)syncSelection:(const std::set<int> &)selection;
@end

@implementation TrellisPanelTableView
- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger visualRow = [self rowAtPoint:point];
    NSInteger visualColumn = [self columnAtPoint:point];
    NSInteger originalRow = self.panelAdapter
        ? [self.panelAdapter originalRowAtVisualRow:visualRow] : -1;
    NSString *variable = visualColumn >= 0 && visualColumn < (NSInteger)[[self tableColumns] count]
        ? [[[self tableColumns] objectAtIndex:(NSUInteger)visualColumn] identifier] : nil;
    return [self.trellisOwner trellisDataTableContextMenuForPanel:self.panelLevelId
                                                      originalRow:originalRow
                                                        variable:variable];
}
@end

@implementation TrellisPanelTableAdapter
- (instancetype)initWithGroup:(const std::string &)group owner:(ScatterView *)owner
{
    self = [super init];
    if (self) {
        _group = group;
        _owner = owner;
        _updatingSelection = NO;
    }
    return self;
}

- (void)updateDataFrame:(const DataFrameModel &)dataFrame
                   rows:(const std::vector<int> &)rows
              variables:(const std::vector<std::string> &)variables
{
    _dataFrame = dataFrame;
    _rows = rows;
    _variables = variables;
    [self.tableView reloadData];
}

- (NSInteger)originalRowAtVisualRow:(NSInteger)row
{
    return row >= 0 && (std::size_t)row < _rows.size() ? _rows[(std::size_t)row] : -1;
}

- (const std::vector<int> &)originalRows
{
    return _rows;
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    (void)tableView;
    return (NSInteger)_rows.size();
}

- (id)tableView:(NSTableView *)tableView
 objectValueForTableColumn:(NSTableColumn *)tableColumn
             row:(NSInteger)row
{
    (void)tableView;
    const NSInteger originalRow = [self originalRowAtVisualRow:row];
    if (originalRow <= 0) return @"";
    NSString *identifier = [tableColumn identifier];
    if ([identifier isEqualToString:@"_row"]) {
        return [NSString stringWithFormat:@"%ld", (long)originalRow];
    }
    const DataColumn *column = FindDataColumnInDataFrame(_dataFrame, [identifier UTF8String]);
    const std::size_t index = (std::size_t)originalRow - 1;
    return column && index < (std::size_t)std::max(0, _dataFrame.rows)
        ? ToNSString(DisplayValueForDataFrameCell(_dataFrame, *column, index)) : @"";
}

- (void)tableView:(NSTableView *)tableView
   willDisplayCell:(id)cell
    forTableColumn:(NSTableColumn *)tableColumn
               row:(NSInteger)row
{
    const NSInteger originalRow = [self originalRowAtVisualRow:row];
    if (originalRow <= 0) return;
    DataSheetRowStyle style = DataSheetStyleForRow(
        _group, (int)originalRow, [tableView isRowSelected:row]);
    bool imputed = false;
    NSString *identifier = [tableColumn identifier];
    if (![identifier isEqualToString:@"_row"]) {
        const DataColumn *column = FindDataColumnInDataFrame(_dataFrame, [identifier UTF8String]);
        imputed = column && DataFrameCellIsImputed(
            _dataFrame, *column, (std::size_t)originalRow - 1);
    }
    if (style.customBackground) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:style.background];
    } else if (imputed) {
        [cell setDrawsBackground:YES];
        [cell setBackgroundColor:[NSColor colorWithCalibratedRed:1.0 green:0.95 blue:0.72 alpha:1.0]];
    } else {
        [cell setDrawsBackground:NO];
    }
    if ([cell respondsToSelector:@selector(setTextColor:)]) {
        [cell setTextColor:style.textColor ? style.textColor : [NSColor blackColor]];
    }
}

- (NSTableRowView *)tableView:(NSTableView *)tableView rowViewForRow:(NSInteger)row
{
    (void)tableView;
    DataSheetRowView *rowView = [[DataSheetRowView alloc] init];
    rowView.groupName = ToNSString(_group);
    rowView.originalRow = [self originalRowAtVisualRow:row];
    return rowView;
}

- (NSString *)tableView:(NSTableView *)tableView
          toolTipForCell:(NSCell *)cell
                    rect:(NSRectPointer)rect
             tableColumn:(NSTableColumn *)tableColumn
                     row:(NSInteger)row
           mouseLocation:(NSPoint)mouseLocation
{
    (void)tableView; (void)cell; (void)rect; (void)mouseLocation;
    NSString *identifier = [tableColumn identifier];
    const NSInteger originalRow = [self originalRowAtVisualRow:row];
    if (originalRow <= 0 || [identifier isEqualToString:@"_row"]) return nil;
    const DataColumn *column = FindDataColumnInDataFrame(_dataFrame, [identifier UTF8String]);
    if (!column) return nil;
    const std::string tooltip = DataFrameImputationTooltipText(
        _dataFrame, *column, (std::size_t)originalRow - 1);
    return tooltip.empty() ? nil : ToNSString(tooltip);
}

- (void)tableViewSelectionDidChange:(NSNotification *)notification
{
    (void)notification;
    if (!_updatingSelection) [self.owner trellisDataTableSelectionChanged:self];
}

- (void)tableView:(NSTableView *)tableView
    sortDescriptorsDidChange:(NSArray<NSSortDescriptor *> *)oldDescriptors
{
    (void)oldDescriptors;
    if (self.owner.synchronizingTrellisTableScroll) return;
    NSSortDescriptor *descriptor = [[tableView sortDescriptors] firstObject];
    NSString *variable = [descriptor key];
    if (!descriptor || !variable || [variable isEqualToString:@"_row"]) return;
    [self.owner trellisDataTableSortVariable:variable ascending:[descriptor ascending]];
}

- (void)syncSelection:(const std::set<int> &)selection
{
    _updatingSelection = YES;
    NSMutableIndexSet *indexes = [NSMutableIndexSet indexSet];
    for (std::size_t index = 0; index < _rows.size(); ++index) {
        if (selection.find(_rows[index]) != selection.end()) [indexes addIndex:index];
    }
    [self.tableView selectRowIndexes:indexes byExtendingSelection:NO];
    _updatingSelection = NO;
}
@end

