// Activate before forwarding clicks, including clicks in an already-key sheet.
@interface DataSheetWindow : NSWindow
@end
@implementation DataSheetWindow
- (void)sendEvent:(NSEvent *)event
{
    if ([event type] == NSEventTypeLeftMouseDown || [event type] == NSEventTypeRightMouseDown ||
        [event type] == NSEventTypeOtherMouseDown) {
        [(DataSheetWindowController *)[self delegate] activateDatasetForCommands];
    }
    [super sendEvent:event];
