- (NSMenu *)dataSheetHeaderContextMenuForColumn:(NSInteger)column
{
    if (column < 0 || column >= (NSInteger)[[_table tableColumns] count]) return nil;
    NSTableColumn *tableColumn = [[_table tableColumns] objectAtIndex:(NSUInteger)column];
    NSString *identifier = [tableColumn identifier];
    if (!identifier || [identifier isEqualToString:@"_row"] ||
        [identifier isEqualToString:@"_scope"]) return nil;
    _headerContextVariable = std::string([identifier UTF8String]);
    [_table selectColumnIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)column] byExtendingSelection:NO];
    [_table setNeedsDisplay:YES];
    [[_table headerView] setNeedsDisplay:YES];

    const std::string variable = _headerContextVariable;
    std::string currentType;
    std::string currentRole;
    int decimals = -1;
    std::string currentLabelColumn;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataColumn *dataColumn = FindDataColumnUnlockedConst(_group, variable);
        if (dataColumn) {
            currentType = NormalizeVariableType(dataColumn->type);
            decimals = dataColumn->decimals;
        }
        currentRole = DefaultVariableRoleForGroupUnlocked(_group, variable);
        currentLabelColumn = CurrentLabelColumnForGroupUnlocked(_group);
    }

    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(variable)];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:@"Variable Information" action:@selector(showClickedColumnInformation:) keyEquivalent:@""]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:@"Rename Variable..." action:@selector(renameClickedColumn:) keyEquivalent:@""]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:@"Edit Description..." action:@selector(editClickedColumnDescription:) keyEquivalent:@""]];
    [menu addItem:[NSMenuItem separatorItem]];

    if (rlispstat::core::DefaultVariableRolesExperimentalFeatureEnabled()) {
        NSMenuItem *roleItem = [[NSMenuItem alloc]
            initWithTitle:ToNSString(rlispstat::core::FormatRoleColumnHeader())
                    action:nil keyEquivalent:@""];
        NSMenu *roleMenu = [[NSMenu alloc]
            initWithTitle:ToNSString(rlispstat::core::FormatRoleColumnHeader())];
        for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::VariableViewRoleOptions()) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                          action:@selector(setClickedColumnRole:)
                                                   keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(option.value)];
            const bool selected = (option.value == "dependent" && currentRole == "dependent") ||
                (option.value == "independent" && currentRole == "independent") ||
                (option.value == "none" && currentRole != "dependent" && currentRole != "independent");
            [item setState:selected ? NSControlStateValueOn : NSControlStateValueOff];
            [roleMenu addItem:item];
        }
        [menu setSubmenu:roleMenu forItem:roleItem];
        [menu addItem:roleItem];
    }

    NSMenuItem *typeItem = [[NSMenuItem alloc] initWithTitle:@"Type" action:nil keyEquivalent:@""];
    NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:@"Type"];
    for (const rlispstat::core::LinkedPlotCommandOption &option : rlispstat::core::VariableViewTypeOptions()) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                      action:@selector(setClickedColumnTypeFromMenu:)
                                               keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(option.value)];
        [item setState:currentType == option.value ? NSControlStateValueOn : NSControlStateValueOff];
        [typeMenu addItem:item];
    }
    [menu setSubmenu:typeMenu forItem:typeItem];
    [menu addItem:typeItem];

    NSMenuItem *decimalsItem = [[NSMenuItem alloc] initWithTitle:
        (decimals < 0 ? @"Decimals: Automatic..." : [NSString stringWithFormat:@"Decimals: %d...", decimals])
        action:@selector(editClickedColumnDecimals:) keyEquivalent:@""];
    [decimalsItem setEnabled:currentType == "numeric"];
    [menu addItem:decimalsItem];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *labelItem = [[NSMenuItem alloc] initWithTitle:@"Use as Point Label Column"
                                                       action:@selector(useClickedColumnAsPointLabel:) keyEquivalent:@""];
    [labelItem setState:currentLabelColumn == variable ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:labelItem];

    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddRCodeExportItems(exportMenu, "column", _group, false, variable);
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];

    for (NSMenuItem *item in [menu itemArray]) {
        if ([item action] && ![item target]) [item setTarget:self];
    }
    return menu;
}

- (void)setImputationDisplayMode:(id)sender
{
    NSString *mode = [sender representedObject];
    if (!mode) return;
    std::string value = [mode UTF8String];
    std::vector<std::string> plotsToRedraw;
    bool requestSmooth = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        DataFrameModel *found = FindDataFrameUnlocked(_group);
        if (!found || found->datasetType != "multiple_imputation") {
            return;
        }
        DataFrameModel &df = *found;
        if (value == "all" || value == "original") {
            df.imputationDisplayMode = value;
        } else if (value.rfind("version:", 0) == 0) {
            int version = std::atoi(value.substr(8).c_str());
            if (version >= 1 && version <= df.imputationCount) {
                df.activeImputationVersion = version;
                df.imputationDisplayMode = "version";
            }
        }
        ApplyImputationDisplayModeToStoredValues(df);
        plotsToRedraw = RebuildPlotsForDataFrameUnlocked(_group, df);
        for (const std::string &plotId : plotsToRedraw) {
            auto plot = g_plots.find(plotId);
            if (plot != g_plots.end())
                requestSmooth = RequestSmoothRecomputeForPlotUnlocked(plot->second) || requestSmooth;
        }
    }
    if (requestSmooth) NotifyMainRTaskAvailable();
    for (const std::string &plotId : plotsToRedraw) {
        RedrawPlotOnMain(plotId);
    }
    RedrawGroupViewsSynchronouslyOnMain(_group, true);
    RefreshDendrogramWindowsOnMain(_group);
    RefreshDataDeskWindowsOnMain(_group);
    RefreshRegressionComparisonWindowsOnMain(_group, false);
    [self refresh];
}

