- (BOOL)tableColumnsMatchDataFrame:(const DataFrameModel &)df
{
    NSArray<NSTableColumn *> *columns = [_table tableColumns];
    if ([columns count] != df.columns.size() + 2) {
        return NO;
    }
    if (![[[columns objectAtIndex:0] identifier] isEqualToString:@"_row"]) {
        return NO;
    }
    if (![[[columns objectAtIndex:1] identifier] isEqualToString:@"_scope"]) {
        return NO;
    }
    for (size_t i = 0; i < df.columns.size(); ++i) {
        NSString *identifier = [[columns objectAtIndex:(NSUInteger)i + 2] identifier];
        if (std::string([identifier UTF8String]) != df.columns[i].name) {
            return NO;
        }
    }
    return YES;
}

- (BOOL)tableView:(NSTableView *)tableView shouldSelectTableColumn:(NSTableColumn *)tableColumn
{
    (void)tableView;
    return ![[tableColumn identifier] isEqualToString:@"_row"] &&
           ![[tableColumn identifier] isEqualToString:@"_scope"];
}

// Brushing changes highlights only. Do not copy the dataset, rebuild columns,
// reload cells, or update model specifications for each pointer position.
- (void)refreshLinkedSelectionForGroup:(const std::string &)group
{
    if (group != _group || !_window.visible || _window.miniaturized ||
        _table.editedRow >= 0 || _table.editedColumn >= 0) return;
    std::set<int> selected;
    { std::lock_guard<std::mutex> lock(g_mutex); selected = g_groupSelections[_group]; }
    NSMutableIndexSet *indexes = [NSMutableIndexSet indexSet];
    if (_usesVisibleRows) {
        for (std::size_t i = 0; i < _visibleOriginalRows.size(); ++i)
            if (selected.count(_visibleOriginalRows[i])) [indexes addIndex:i];
    } else {
        const NSInteger count = _table.numberOfRows;
        for (int row : selected) if (row > 0 && row <= count) [indexes addIndex:row - 1];
    }
    _updatingSelection = true;
    [_table selectRowIndexes:indexes byExtendingSelection:NO];
    _updatingSelection = false;
    [_table displayIfNeeded];
}

- (void)refresh
{
    // A linked-selection notification can arrive while AppKit's field editor
    // is still committing a cell. Reloading at that point discards the typed
    // value before tableView:setObjectValue:... is called.
    if ([_table editedRow] >= 0 || [_table editedColumn] >= 0) {
        return;
    }
    DataFrameModel df = [self dataFrame];
    std::set<std::string> selectedColumnNames;
    for (NSUInteger index = [[_table selectedColumnIndexes] firstIndex];
         index != NSNotFound;
         index = [[_table selectedColumnIndexes] indexGreaterThanIndex:index]) {
        if (index >= (NSUInteger)[[_table tableColumns] count]) continue;
        NSString *identifier = [[[_table tableColumns] objectAtIndex:index] identifier];
        if (identifier && ![identifier isEqualToString:@"_row"] &&
            ![identifier isEqualToString:@"_scope"]) {
            selectedColumnNames.insert(std::string([identifier UTF8String]));
        }
    }
    NSMenu *menu = [_table menu];
    const rlispstat::core::DataSheetContextMenuTitles menuTitles = rlispstat::core::DefaultDataSheetContextMenuTitles();
    NSInteger existing = [menu indexOfItemWithTitle:ToNSString(menuTitles.imputedDataDisplay)];
    if (existing >= 0) {
        NSInteger previous = existing - 1;
        [menu removeItemAtIndex:existing];
        if (previous >= 0 && previous < [menu numberOfItems] && [[menu itemAtIndex:previous] isSeparatorItem]) {
            [menu removeItemAtIndex:previous];
        } else if (existing < [menu numberOfItems] && [[menu itemAtIndex:existing] isSeparatorItem]) {
            [menu removeItemAtIndex:existing];
        }
    }
    if (df.datasetType == "multiple_imputation" && df.imputationCount > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *displayItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.imputedDataDisplay) action:nil keyEquivalent:@""];
        NSMenu *displayMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuTitles.imputedDataDisplay)];
        for (int version = 1; version <= df.imputationCount; ++version) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::DataSheetImputationVersionTitle(version))
                                                          action:@selector(setImputationDisplayMode:)
                                                   keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString("version:" + std::to_string(version))];
            [item setState:(df.imputationDisplayMode == "version" && df.activeImputationVersion == version) ? NSControlStateValueOn : NSControlStateValueOff];
            [displayMenu addItem:item];
        }
        [displayMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *allItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.allImputedValuesDisplay)
                                                         action:@selector(setImputationDisplayMode:)
                                                  keyEquivalent:@""];
        [allItem setTarget:self];
        [allItem setRepresentedObject:@"all"];
        [allItem setState:(df.imputationDisplayMode == "all") ? NSControlStateValueOn : NSControlStateValueOff];
        [displayMenu addItem:allItem];
        NSMenuItem *originalItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuTitles.originalIncompleteDataDisplay)
                                                              action:@selector(setImputationDisplayMode:)
                                                       keyEquivalent:@""];
        [originalItem setTarget:self];
        [originalItem setRepresentedObject:@"original"];
        [originalItem setState:(df.imputationDisplayMode == "original") ? NSControlStateValueOn : NSControlStateValueOff];
        [displayMenu addItem:originalItem];
        [menu setSubmenu:displayMenu forItem:displayItem];
        [menu addItem:displayItem];
    }
    if (![self tableColumnsMatchDataFrame:df]) {
        while ([[_table tableColumns] count] > 0) {
            [_table removeTableColumn:[[_table tableColumns] objectAtIndex:0]];
        }
        NSTableColumn *rowColumn = [[NSTableColumn alloc] initWithIdentifier:@"_row"];
        [[rowColumn headerCell] setStringValue:ToNSString(rlispstat::core::HashColumnHeader())];
        [rowColumn setWidth:56];
        [rowColumn setEditable:NO];
        [_table addTableColumn:rowColumn];
        NSTableColumn *scopeColumn = [[NSTableColumn alloc] initWithIdentifier:@"_scope"];
        [[scopeColumn headerCell] setStringValue:@"S"];
        [scopeColumn setWidth:26];
        [scopeColumn setMinWidth:26];
        [scopeColumn setMaxWidth:26];
        [scopeColumn setEditable:NO];
        [_table addTableColumn:scopeColumn];
        for (const DataColumn &col : df.columns) {
            NSTableColumn *column = [[NSTableColumn alloc] initWithIdentifier:ToNSString(col.name)];
            [[column headerCell] setStringValue:ToNSString(col.name)];
            [column setWidth:std::max(90.0, std::min(180.0, 18.0 + (double)col.name.size() * 8.0))];
            [column setEditable:YES];
            [_table addTableColumn:column];
        }
    }
    [_table reloadData];

    _updatingSelection = true;
    NSMutableIndexSet *selectedColumns = [NSMutableIndexSet indexSet];
    for (NSUInteger index = 0; index < (NSUInteger)[[_table tableColumns] count]; ++index) {
        NSString *identifier = [[[_table tableColumns] objectAtIndex:index] identifier];
        if (identifier && selectedColumnNames.find(std::string([identifier UTF8String])) !=
                              selectedColumnNames.end()) {
            [selectedColumns addIndex:index];
        }
    }
    [_table deselectAll:nil];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(_group);
        if (it != g_groupSelections.end()) {
            NSMutableIndexSet *indexes = [NSMutableIndexSet indexSet];
            for (int row : it->second) {
                if (row <= 0 || row > df.rows) continue;
                if (_usesVisibleRows) {
                    const auto found = std::find(_visibleOriginalRows.begin(),
                                                 _visibleOriginalRows.end(), row);
                    if (found != _visibleOriginalRows.end()) {
                        [indexes addIndex:(NSUInteger)std::distance(_visibleOriginalRows.begin(), found)];
                    }
                } else {
                    [indexes addIndex:(NSUInteger)row - 1];
                }
            }
            [_table selectRowIndexes:indexes byExtendingSelection:NO];
        }
    }
    if ([selectedColumns count] > 0) {
        [_table selectColumnIndexes:selectedColumns byExtendingSelection:NO];
    }
    _updatingSelection = false;
    size_t selected = SelectionCount(_group);
    [_window setTitle:ToNSString(_customTitle.empty() ? DataFrameWindowTitle(_group) : _customTitle)];
    std::string status = _usesVisibleRows
        ? std::to_string(_visibleOriginalRows.size()) + " subgroup rows, " +
          std::to_string(selected) + " selected globally"
        : DataFrameStatusText(df, selected);
    rlispstat::core::AnalysisScope analysisScope;
    std::size_t excludedCount = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        analysisScope = MacCommandDispatcher().applicationState().activeAnalysisScope(_group);
        excludedCount = MacCommandDispatcher().applicationState().excludedRows(_group).size();
    }
    status += " · " + std::to_string(static_cast<std::size_t>(std::max(0, df.rows)) -
        excludedCount) + " included of " + std::to_string(std::max(0, df.rows));
    status += " · " + rlispstat::core::AnalysisScopeSummary(
        analysisScope, static_cast<std::size_t>(std::max(0, df.rows)));
    [_statusField setStringValue:ToNSString(status)];
}

- (void)revealOriginalRow:(NSInteger)row
{
    if (row <= 0 || row > [self dataFrameRowCount]) return;
    [self refresh];
    NSInteger visualRow = row - 1;
    if (_usesVisibleRows) {
        const auto found = std::find(_visibleOriginalRows.begin(), _visibleOriginalRows.end(), (int)row);
        if (found == _visibleOriginalRows.end()) return;
        visualRow = (NSInteger)std::distance(_visibleOriginalRows.begin(), found);
    }
    [_table scrollRowToVisible:visualRow];
    [[_window contentView] setNeedsDisplay:YES];
}
@end

@class CorrelationMatrixView;

@interface CorrelationMatrixWindowController : NSObject <NSWindowDelegate>
{
    std::string _correlationId;
    NSWindow *_window;
    NSTextField *_titleField;
    NSTextField *_badgeField;
    NSTextField *_scopeLabel;
    NSPopUpButton *_scopePopup;
    NSScrollView *_scrollView;
    CorrelationMatrixView *_matrixView;
    NSTextField *_statusField;
}
- (instancetype)initWithCorrelationId:(const std::string &)correlationId;
- (CorrelationMatrixState *)state;
- (void)show;
- (void)refresh;
- (void)showAddVariableMenuAtPoint:(NSPoint)point inView:(NSView *)view;
- (void)showSearchableAddVariableSelectorInView:(NSView *)view;
- (void)showVariableMenuForIndex:(NSInteger)index atPoint:(NSPoint)point inView:(NSView *)view;
- (void)showCellMenuForRow:(NSInteger)row column:(NSInteger)column atPoint:(NSPoint)point inView:(NSView *)view;
- (void)addResultActionsToMenu:(NSMenu *)menu;
- (void)correlationDisplayOption:(id)sender;
- (void)selectCellAtRow:(NSInteger)row column:(NSInteger)column;
- (void)openScatterAtRow:(NSInteger)row column:(NSInteger)column;
- (void)scopeChanged:(id)sender;
- (void)selectionDidChange;
- (void)explainCorrelationStatistic:(id)sender;
@end

@interface CorrelationMatrixView : NSView
@property(nonatomic, assign) CorrelationMatrixWindowController *controller;
- (instancetype)initWithController:(CorrelationMatrixWindowController *)controller;
- (CGFloat)matrixRowHeight;
- (NSSize)preferredContentSize;
- (NSRect)addVariableRect;
@end

@implementation CorrelationMatrixView

- (NSString *)snapshotTabDelimitedText
{
    CorrelationMatrixState *state = [_controller state];
    if (!state) return @"";
    std::ostringstream text;
    text << state->title;
    if (!state->method.empty()) text << " (" << state->method << ')';
    text << "\nVariable";
    for (const std::string &variable : state->variables) text << '\t' << variable;
    for (std::size_t row = 0; row < state->variables.size(); ++row) {
        text << '\n' << state->variables[row];
        for (std::size_t column = 0; column < state->variables.size(); ++column) {
            text << '\t' << rlispstat::core::CorrelationDisplayedCellText(*state,row,column);
        }
    }
    return ToNSString(text.str());
}

- (instancetype)initWithController:(CorrelationMatrixWindowController *)controller
{
    self = [super initWithFrame:NSMakeRect(0, 0, 720, 420)];
    if (self) {
        _controller = controller;
        [self setAutoresizingMask:NSViewNotSizable];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (CGFloat)matrixRowHeight
{
    CorrelationMatrixState *state = [_controller state];
    return (CGFloat)CorrelationMatrixRowHeight(state && state->showPValue,
                                               state && state->showN);
}

- (CorrelationMatrixLayout)matrixLayout
{
    CorrelationMatrixState *state = [_controller state];
    return BuildCorrelationMatrixLayout(state ? state->variables.size() : 0,
                                        state && state->showPValue,
                                        state && state->showN);
}

- (CGFloat)variableRowY:(NSInteger)index
{
    CorrelationMatrixLayout layout = [self matrixLayout];
    if (index < 0 || (size_t)index >= layout.rowHeaderRects.size()) return layout.top + layout.headerHeight;
    return (CGFloat)layout.rowHeaderRects[(size_t)index].y;
}

- (CGFloat)addVariableY
{
    return (CGFloat)[self matrixLayout].addVariableRect.y;
}

- (CGFloat)matrixTop
{
    return (CGFloat)[self matrixLayout].top;
}

- (NSSize)preferredContentSize
{
    CorrelationMatrixState *state = [_controller state];
    CorrelationSize size = CorrelationMatrixPreferredContentSize(state ? state->variables.size() : 0,
                                                                 state && state->showPValue,
                                                                 state && state->showN);
    return NSMakeSize(size.width, size.height);
}

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color align:(NSTextAlignment)align
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:align];
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    };
}

- (NSRect)variableRectAtIndex:(NSInteger)index
{
    CorrelationMatrixLayout layout = [self matrixLayout];
    if (index < 0 || (size_t)index >= layout.columnHeaderRects.size()) return NSZeroRect;
    return rlispstat::platform::macos::ToNSRect(layout.columnHeaderRects[(size_t)index]);
}

- (NSRect)addVariableRect
{
    return rlispstat::platform::macos::ToNSRect([self matrixLayout].addVariableRect);
}

- (NSRect)matrixCellRectForRow:(NSInteger)row column:(NSInteger)column
{
    return rlispstat::platform::macos::ToNSRect(
        CorrelationMatrixCellRect([self matrixLayout], (int)row, (int)column));
}

- (NSInteger)variableIndexAtPoint:(NSPoint)point
{
    CorrelationMatrixHit hit = HitTestCorrelationMatrix(
        [self matrixLayout],
        rlispstat::platform::macos::ToCorePoint(point),
        [_controller state] ? [_controller state]->displayPart : "full");
    return hit.kind == CorrelationMatrixHitKind::Variable ? hit.variableIndex : -1;
}

- (BOOL)pointInAddVariable:(NSPoint)point
{
    CorrelationMatrixHit hit = HitTestCorrelationMatrix(
        [self matrixLayout],
        rlispstat::platform::macos::ToCorePoint(point),
        [_controller state] ? [_controller state]->displayPart : "full");
    return hit.kind == CorrelationMatrixHitKind::AddVariable;
}

- (BOOL)matrixCellAtPoint:(NSPoint)point row:(NSInteger *)rowOut column:(NSInteger *)columnOut
{
    CorrelationMatrixHit hit = HitTestCorrelationMatrix(
        [self matrixLayout],
        rlispstat::platform::macos::ToCorePoint(point),
        [_controller state] ? [_controller state]->displayPart : "full");
    if (hit.kind != CorrelationMatrixHitKind::Cell) return NO;
    if (rowOut) *rowOut = hit.row;
    if (columnOut) *columnOut = hit.column;
    return YES;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);

    CorrelationMatrixState *state = [_controller state];
    NSDictionary *labelAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.18 alpha:1] align:NSTextAlignmentLeft];
    NSDictionary *mutedAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.45 alpha:1] align:NSTextAlignmentLeft];
    NSDictionary *centerAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.12 alpha:1] align:NSTextAlignmentCenter];
    NSDictionary *centerMutedAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.46 alpha:1] align:NSTextAlignmentCenter];
    NSDictionary *headerAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.18 alpha:1] align:NSTextAlignmentCenter];

    if (!state) return;

    CorrelationMatrixRenderPlan plan = BuildCorrelationMatrixRenderPlan(
        state->variables,
        state->cells,
        state->selectedRow,
        state->selectedCol,
        state->showP,
        state->showPValue,
        state->showN, state->displayPart);
    [[NSColor colorWithCalibratedWhite:0.86 alpha:1] setStroke];
    NSBezierPath *rule = [NSBezierPath bezierPath];
    [rule moveToPoint:NSMakePoint(plan.headerRuleRect.x, plan.headerRuleRect.y)];
    [rule lineToPoint:NSMakePoint(plan.headerRuleRect.x + plan.headerRuleRect.width, plan.headerRuleRect.y)];
    [rule stroke];

    for (const auto &header : plan.columnHeaders) {
        [ToNSString(header.text) drawInRect:rlispstat::platform::macos::ToNSRect(header.rect)
                             withAttributes:headerAttrs];
    }
    for (const auto &header : plan.rowHeaders) {
        [ToNSString(header.text) drawInRect:rlispstat::platform::macos::ToNSRect(header.rect)
                             withAttributes:labelAttrs];
    }
    for (const auto &cell : plan.cells) {
        NSRect cellRect = rlispstat::platform::macos::ToNSRect(cell.rect);
        if (cell.background == CorrelationCellBackground::Selected) {
            [[NSColor colorWithCalibratedRed:0.84 green:0.91 blue:0.98 alpha:1] setFill];
            NSRectFill(NSInsetRect(cellRect, 1, 1));
        } else if (cell.background == CorrelationCellBackground::Diagonal) {
            [[NSColor colorWithCalibratedWhite:0.975 alpha:1] setFill];
            NSRectFill(NSInsetRect(cellRect, 1, 1));
        }
        for (const auto &textItem : cell.textItems) {
            [ToNSString(textItem.text) drawInRect:rlispstat::platform::macos::ToNSRect(textItem.rect)
                                   withAttributes:(textItem.muted ? centerMutedAttrs : centerAttrs)];
        }
    }

    if (plan.showEmptyMessage) {
        [ToNSString(plan.emptyMessage) drawInRect:rlispstat::platform::macos::ToNSRect(plan.emptyMessageRect)
                                   withAttributes:mutedAttrs];
    }
    [ToNSString(plan.addVariableLabel) drawInRect:rlispstat::platform::macos::ToNSRect(plan.addVariableRect)
                                   withAttributes:mutedAttrs];
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    if ([self pointInAddVariable:p]) {
        [_controller showAddVariableMenuAtPoint:p inView:self];
        return;
    }
    NSInteger variableIndex = [self variableIndexAtPoint:p];
    if (variableIndex >= 0) {
        [_controller showVariableMenuForIndex:variableIndex atPoint:p inView:self];
        return;
    }
    NSInteger row = -1, col = -1;
    if ([self matrixCellAtPoint:p row:&row column:&col]) {
        [_controller selectCellAtRow:row column:col];
        if ([event clickCount] >= 2) {
            [_controller openScatterAtRow:row column:col];
        }
    }
}

- (void)rightMouseDown:(NSEvent *)event
{
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    if ([self pointInAddVariable:p]) {
        [_controller showSearchableAddVariableSelectorInView:self];
        return;
    }
    NSInteger variableIndex = [self variableIndexAtPoint:p];
    if (variableIndex >= 0) {
        [_controller showVariableMenuForIndex:variableIndex atPoint:p inView:self];
        return;
    }
    NSInteger row = -1, col = -1;
    if ([self matrixCellAtPoint:p row:&row column:&col]) {
        [_controller selectCellAtRow:row column:col];
        [_controller showCellMenuForRow:row column:col atPoint:p inView:self];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Correlation Matrix"];
    [_controller addResultActionsToMenu:menu];
    AddSnapshotAlbumContextItems(menu);
    [menu popUpMenuPositioningItem:nil atLocation:p inView:self];
}

@end

@implementation CorrelationMatrixWindowController

- (void)addResultActionsToMenu:(NSMenu *)menu
{
    CorrelationMatrixState *state = [self state];
    if (!state || !menu) return;
    NSMenu *sectionMenu=nil;
    std::string section;
    for (const auto &option:rlispstat::core::CorrelationContextOptions(*state)) {
        if (section!=option.section) {
            section=option.section;
            NSMenuItem *parent=[[NSMenuItem alloc] initWithTitle:ToNSString(section) action:nil keyEquivalent:@""];
            sectionMenu=[[NSMenu alloc] initWithTitle:ToNSString(section)];
            [sectionMenu setAutoenablesItems:NO];[parent setSubmenu:sectionMenu];[menu addItem:parent];
        }
        if (option.value=="show_p") [sectionMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *item=[[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:@selector(correlationDisplayOption:) keyEquivalent:@""];
        [item setTarget:self];[item setRepresentedObject:@[ToNSString(option.command),ToNSString(option.value)]];
        [item setState:option.checked?NSControlStateValueOn:NSControlStateValueOff];
        [item setEnabled:option.enabled];[sectionMenu addItem:item];
    }
    [menu addItem:[NSMenuItem separatorItem]];
    AddMissingInformationMenu(menu, state->id);
    AddStandardResultTableExportMenu(
        menu, _matrixView, ToNSString(state->title),
        ToNSString(state->id.empty() ? "correlation-matrix" : state->id),
        [_matrixView snapshotTabDelimitedText], _correlationId, true);
}

- (instancetype)initWithCorrelationId:(const std::string &)correlationId
{
    self = [super init];
    if (self) {
        _correlationId = correlationId;
        NSRect frame = NextWindowFrameOnMain(760, 560);
        _window = [[NSWindow alloc]
            initWithContentRect:frame
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setDelegate:self];
        [_window setTitle:ToNSString(rlispstat::core::CorrelationWindowTitle())];
        NSView *content = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 760, 560)];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];
        [_window setContentView:content];

        _titleField = GLMLabel(ToNSString(rlispstat::core::CorrelationWindowTitle()), NSMakeRect(16, 522, 280, 24), 17, NSFontWeightSemibold);
        [content addSubview:_titleField];
        _badgeField = GLMRightLabel(@"", NSMakeRect(590, 524, 150, 20), 12, NSFontWeightMedium);
        [content addSubview:_badgeField];

        _scopeLabel = GLMLabel(ToNSString(rlispstat::core::GLMScopeFieldLabel()),
                               NSMakeRect(570, 490, 46, 22), 12, NSFontWeightRegular);
        [content addSubview:_scopeLabel];
        _scopePopup = [[GlobalAnalysisScopeSummary alloc] initWithFrame:NSMakeRect(616, 486, 128, 28)];
        [_scopePopup setTarget:self];
        [_scopePopup setAction:@selector(scopeChanged:)];
        [content addSubview:_scopePopup];

        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 44, 736, 436)];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setAutohidesScrollers:YES];
        [_scrollView setBorderType:NSNoBorder];
        [_scrollView setDrawsBackground:NO];
        _matrixView = [[CorrelationMatrixView alloc] initWithController:self];
        [_scrollView setDocumentView:_matrixView];
        [content addSubview:_scrollView];

        _statusField = GLMLabel(@"", NSMakeRect(16, 14, 720, 20), 12, NSFontWeightRegular);
        [content addSubview:_statusField];
    }
    return self;
}

- (CorrelationMatrixState *)state
{
    auto it = g_correlationMatrices.find(_correlationId);
    if (it == g_correlationMatrices.end()) return nullptr;
    return &it->second;
}

- (void)show
{
    CorrelationMatrixState *state = [self state];
    EnableNotesForWindow(_window, _correlationId, @"this correlation matrix",
                         state ? state->group : std::string{});
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)refresh
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    CorrelationWindowControlState controls = BuildCorrelationWindowControlState(
        state->group,
        state->title,
        state->variables,
        state->missingMode,
        state->showP,
        state->showPValue,
        state->showN,
        state->precomputed,
        state->multipleImputation,
        state->imputationCount,
        state->note);
    [_window setTitle:ToNSString(controls.windowTitle)];
    [_titleField setStringValue:ToNSString(controls.title)];
    [_badgeField setStringValue:ToNSString(controls.badge)];
    PopulateAnalysisScopePopup(_scopePopup, state->group, "all",
                               state->dataScope, state->dataScopeCaptured, false);
    [_scopePopup setEnabled:!state->precomputed];

    NSSize matrixSize = [_matrixView preferredContentSize];
    NSScreen *screen = [_window screen] ?: [NSScreen mainScreen];
    NSRect visibleFrame = screen ? [screen visibleFrame] : NSMakeRect(0, 0, 1200, 800);
    CorrelationWindowLayout windowLayout = BuildCorrelationWindowLayout(matrixSize.width,
                                                                        matrixSize.height,
                                                                        visibleFrame.size.width,
                                                                        visibleFrame.size.height);

    NSSize currentSize = FitResultTableWindowToContent(
        _window,
        NSMakeSize(windowLayout.targetWidth, windowLayout.targetHeight),
        NSMakeSize(640.0, 420.0));
    windowLayout = BuildCorrelationWindowContentLayout(currentSize.width,
                                                       currentSize.height);

    [_titleField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.titleRect)];
    [_badgeField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.badgeRect)];
    [_scopeLabel setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scopeLabelRect)];
    [_scopePopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scopePopupRect)];
    [_scrollView setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scrollViewRect)];
    [_statusField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.statusRect)];

    NSSize visible = [_scrollView contentSize];
    rlispstat::core::Rect documentRect = CorrelationMatrixDocumentRect(matrixSize.width,
                                                                       matrixSize.height,
                                                                       visible.width,
                                                                       visible.height);
    [_matrixView setFrame:rlispstat::platform::macos::ToNSRect(documentRect)];
    [_matrixView setNeedsDisplay:YES];
    std::string status = controls.status;
    if (state->dataScopeCaptured) {
        status += " · " + rlispstat::core::AnalysisScopeWindowSummary(
            state->dataScope, state->dataScope.totalDatasetRows);
    }
    [_statusField setStringValue:ToNSString(status)];
}

- (void)correlationDisplayOption:(id)sender
{
    NSArray *option=[sender representedObject];
    if (![option isKindOfClass:[NSArray class]] || [option count]!=2) return;
    MacCommandDispatcher().dispatch({std::string([option[0] UTF8String]),_correlationId,std::string([option[1] UTF8String])});
    [self refresh];
}

- (void)scopeChanged:(id)sender
{
    (void)sender; // Scope is configured only through the global Analysis Scope menu.
}

- (void)selectionDidChange
{
    CorrelationMatrixState *state = [self state];
    if (!state || state->precomputed) { [self refresh]; return; }
    const auto global = MacCommandDispatcher().applicationState().activeAnalysisScope(state->group);
    if (rlispstat::core::AnalysisScopeTracksCurrentSelection(global) ||
        global.sourceKind == rlispstat::core::AnalysisScopeSourceKind::CurrentUnselection)
        RefitCorrelationMatrixState(*state);
    [self refresh];
}

- (void)showAddVariableMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::CorrelationAddVariableMenuTitle())];
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state->seed);
    CorrelationAddVariableMenuState menuState = BuildCorrelationAddVariableMenuState(
        state->variables, numeric, state->precomputed);
    if (menuState.locked) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.lockedTitle) action:nil keyEquivalent:@""];
        [item setEnabled:NO];
        [menu addItem:item];
        [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
        return;
    }
    for (const std::string &name : menuState.variables) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addVariableFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([[menu itemArray] count] == 0) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.emptyTitle) action:nil keyEquivalent:@""];
        [item setEnabled:NO];
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)showSearchableAddVariableSelectorInView:(NSView *)view
{
    CorrelationMatrixState *state = [self state];
    if (!state || state->precomputed) return;
    const auto numeric = rlispstat::core::NumericVariableNames(&state->seed);
    const auto menuState = BuildCorrelationAddVariableMenuState(
        state->variables, numeric, false);
    ShowSearchableAddSelector(_window, view, @"Add variables", menuState.variables,
        ^(NSArray<NSString *> *names) {
            CorrelationMatrixState *current = [self state];
            if (!current || current->precomputed) return;
            auto updated = current->variables;
            for (NSString *label in names) {
                std::string name = label.UTF8String;
                if (std::find(updated.begin(), updated.end(), name) == updated.end())
                    updated.push_back(name);
            }
            if (updated != current->variables) {
                current->variables = std::move(updated);
                RefitCorrelationMatrixState(*current);
                [self refresh];
            }
        });
}

- (void)addVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(rlispstat::core::CorrelationPooledAddVariableStatus())];
        [self refresh];
        return;
    }
    std::string name = std::string([title UTF8String]);
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state->seed);
    CorrelationVariableUpdateResult update = CorrelationVariablesAfterAdd(state->variables, name, numeric);
    if (!update.ok) {
        if (!update.status.empty()) [_statusField setStringValue:ToNSString(update.status)];
        return;
    }
    if (update.changed) {
        state->variables = update.variables;
        RefitCorrelationMatrixState(*state);
    }
    [self refresh];
}

- (void)showVariableMenuForIndex:(NSInteger)index atPoint:(NSPoint)point inView:(NSView *)view
{
    CorrelationMatrixState *state = [self state];
    if (!state || index < 0 || (size_t)index >= state->variables.size()) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::CorrelationVariableMenuTitle())];
    CorrelationVariableMenuState menuState = BuildCorrelationVariableMenuState(
        state->variables, static_cast<size_t>(index), state->precomputed);
    if (!menuState.valid) return;
    if (menuState.locked) {
        NSMenuItem *info = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.informationTitle) action:@selector(showCorrelationVariableInformation:) keyEquivalent:@""];
        [info setTarget:self];
        [info setRepresentedObject:@(index)];
        [menu addItem:info];
        NSMenuItem *locked = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.lockedTitle) action:nil keyEquivalent:@""];
        [locked setEnabled:NO];
        [menu addItem:locked];
        [self addResultActionsToMenu:menu];
        AddSnapshotAlbumContextItems(menu);
        [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
        return;
    }
    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.addVariableTitle) action:@selector(addVariableFromContextMenu:) keyEquivalent:@""];
    [add setTarget:self];
    [add setRepresentedObject:@(index)];
    [menu addItem:add];
    NSMenuItem *replace = [[NSMenuItem alloc]
        initWithTitle:ToNSString(menuState.replaceVariableTitle) action:nil keyEquivalent:@""];
    NSMenu *replaceMenu = [[NSMenu alloc]
        initWithTitle:ToNSString(menuState.replaceVariableTitle)];
    std::vector<std::string> numericVariables = rlispstat::core::NumericVariableNames(&state->seed);
    for (const std::string &name : CorrelationVariablesAvailableToAdd(
             state->variables, numericVariables)) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name)
            action:@selector(replaceCorrelationVariableFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ @(index), ToNSString(name) ]];
        [replaceMenu addItem:item];
    }
    if ([replaceMenu numberOfItems] == 0) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:@"No replacement variables"
            action:nil keyEquivalent:@""];
        [empty setEnabled:NO]; [replaceMenu addItem:empty];
    }
    [menu setSubmenu:replaceMenu forItem:replace];
    [menu addItem:replace];
    NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.removeVariableTitle)
                                                    action:@selector(removeVariableFromMenu:)
                                             keyEquivalent:@""];
    [remove setTarget:self];
    [remove setRepresentedObject:@(index)];
    [remove setEnabled:state->variables.size() > 2];
    [menu addItem:remove];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *numeric = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.treatAsNumericTitle) action:@selector(treatCorrelationVariableAsNumeric:) keyEquivalent:@""];
    [numeric setTarget:self];
    [numeric setRepresentedObject:@(index)];
    [menu addItem:numeric];
    NSMenuItem *factor = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.treatAsFactorTitle) action:@selector(treatCorrelationVariableAsFactor:) keyEquivalent:@""];
    [factor setTarget:self];
    [factor setRepresentedObject:@(index)];
    [factor setEnabled:state->variables.size() > 2];
    [menu addItem:factor];
    NSMenuItem *info = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.informationTitle) action:@selector(showCorrelationVariableInformation:) keyEquivalent:@""];
    [info setTarget:self];
    [info setRepresentedObject:@(index)];
    [menu addItem:info];
    [menu addItem:[NSMenuItem separatorItem]];
    [self addResultActionsToMenu:menu];
    AddSnapshotAlbumContextItems(menu);
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)addVariableFromContextMenu:(id)sender
{
    (void)sender;
    [_matrixView setNeedsDisplay:YES];
    NSRect rect = [_matrixView addVariableRect];
    [self showAddVariableMenuAtPoint:NSMakePoint(NSMinX(rect) + 8.0, NSMaxY(rect)) inView:_matrixView];
}

- (void)replaceCorrelationVariableFromMenu:(id)sender
{
    NSArray *represented = [sender representedObject];
    CorrelationMatrixState *state = [self state];
    if (!state || ![represented isKindOfClass:[NSArray class]] ||
        [represented count] < 2 || state->precomputed) return;
    NSInteger index = [[represented objectAtIndex:0] integerValue];
    NSString *nameString = [represented objectAtIndex:1];
    if (index < 0 || !nameString) return;
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state->seed);
    CorrelationVariableUpdateResult update = CorrelationVariablesAfterReplace(
        state->variables, static_cast<std::size_t>(index),
        std::string([nameString UTF8String]), numeric);
    if (!update.ok) {
        if (!update.status.empty()) [_statusField setStringValue:ToNSString(update.status)];
        return;
    }
    if (update.changed) {
        state->variables = update.variables;
        state->selectedRow = -1;
        state->selectedCol = -1;
        RefitCorrelationMatrixState(*state);
    }
    [self refresh];
}

- (void)removeVariableFromMenu:(id)sender
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(rlispstat::core::CorrelationPooledRemoveVariableStatus())];
        [self refresh];
        return;
    }
    NSInteger index = [[sender representedObject] integerValue];
    if (index >= 0) {
        CorrelationVariableUpdateResult update = CorrelationVariablesAfterRemove(
            state->variables,
            static_cast<size_t>(index));
        if (!update.ok) {
            if (!update.status.empty()) [_statusField setStringValue:ToNSString(update.status)];
            return;
        }
        state->variables = update.variables;
        state->selectedRow = -1;
        state->selectedCol = -1;
        RefitCorrelationMatrixState(*state);
    }
    [self refresh];
}

- (std::string)correlationVariableFromSender:(id)sender
{
    CorrelationMatrixState *state = [self state];
    if (!state) return "";
    NSInteger index = [[sender representedObject] integerValue];
    if (index < 0 || (size_t)index >= state->variables.size()) return "";
    return state->variables[(size_t)index];
}

- (void)setCorrelationVariableFromSender:(id)sender type:(const std::string &)type
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(rlispstat::core::CorrelationPooledVariableTypeStatus())];
        [self refresh];
        return;
    }
    std::string variable = [self correlationVariableFromSender:sender];
    if (variable.empty()) return;
    std::string message;
    if (!SetVariableAnalysisType(state->group, variable, type, &message)) {
        [_statusField setStringValue:ToNSString(message)];
        return;
    }
    state = [self state];
    if (state) {
        if (type != "numeric") {
            state->variables.erase(std::remove(state->variables.begin(), state->variables.end(), variable), state->variables.end());
        }
        RefitCorrelationMatrixState(*state);
    }
    [self refresh];
}

- (void)treatCorrelationVariableAsNumeric:(id)sender
{
    [self setCorrelationVariableFromSender:sender type:"numeric"];
}

- (void)treatCorrelationVariableAsFactor:(id)sender
{
    [self setCorrelationVariableFromSender:sender type:"factor"];
}

- (void)showCorrelationVariableInformation:(id)sender
{
    std::string variable = [self correlationVariableFromSender:sender];
    if (variable.empty()) return;
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    ShowWorkbenchMessageOnMain(ToNSString(VariableInformationDialogTitle()), ToNSString(VariableInformationText(state->group, variable)));
}

- (void)selectCellAtRow:(NSInteger)row column:(NSInteger)column
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    state->selectedRow = (int)row;
    state->selectedCol = (int)column;
    const CorrelationCellResult *cell = CorrelationCellAt(*state, (int)row, (int)column);
    std::string text = CorrelationCellStatusText(cell, (int)row, (int)column);
    if (!text.empty()) {
        [_statusField setStringValue:ToNSString(text)];
    }
    [_matrixView setNeedsDisplay:YES];
}

- (void)openScatterAtRow:(NSInteger)row column:(NSInteger)column
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    OpenCorrelationScatterplot(*state, (int)row, (int)column);
}

- (void)showCellMenuForRow:(NSInteger)row column:(NSInteger)column atPoint:(NSPoint)point inView:(NSView *)view
{
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    CorrelationCellMenuState menuState = BuildCorrelationCellMenuState((int)row, (int)column);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    NSMenuItem *open = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.openScatterplotTitle) action:@selector(openSelectedCellScatterplot:) keyEquivalent:@""];
    [open setTarget:self];
    [open setEnabled:menuState.canOpenScatterplot];
    [menu addItem:open];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copyR = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.copyRTitle) action:@selector(copySelectedCellR:) keyEquivalent:@""];
    [copyR setTarget:self];
    [menu addItem:copyR];
    NSMenuItem *copyDetail = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.copyDetailTitle) action:@selector(copySelectedCellDetail:) keyEquivalent:@""];
    [copyDetail setTarget:self];
    [menu addItem:copyDetail];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *explainRoot = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
        action:nil keyEquivalent:@""];
    NSMenu *explainMenu = [[NSMenu alloc] initWithTitle:[explainRoot title]];
    NSString *correlationTitle = @"Pearson r";
    if (state->method == "spearman") correlationTitle = @"Spearman rho";
    else if (state->method == "kendall") correlationTitle = @"Kendall tau";
    for (NSString *statistic in @[ correlationTitle, @"p", @"N" ]) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:statistic
            action:@selector(explainCorrelationStatistic:) keyEquivalent:@""];
        [item setTarget:self]; [item setRepresentedObject:statistic];
        [explainMenu addItem:item];
    }
    [explainRoot setSubmenu:explainMenu]; [menu addItem:explainRoot];
    [menu addItem:[NSMenuItem separatorItem]];
    [self addResultActionsToMenu:menu];
    AddSnapshotAlbumContextItems(menu);
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)explainCorrelationStatistic:(id)sender
{
    NSString *represented = [sender representedObject];
    CorrelationMatrixState *state = [self state];
    if (!state || ![represented isKindOfClass:[NSString class]]) return;
    ShowAnalysisStatisticExplanationOnMain(
        std::string([represented UTF8String]), "correlation", state->method,
        std::string(), state->multipleImputation, state->poolingMethod);
}

- (void)openSelectedCellScatterplot:(id)sender
{
    (void)sender;
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    OpenCorrelationScatterplot(*state, state->selectedRow, state->selectedCol);
}

- (void)copyStringToPasteboard:(NSString *)text
{
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
}

- (void)copySelectedCellR:(id)sender
{
    (void)sender;
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    const CorrelationCellResult *cell = CorrelationCellAt(*state, state->selectedRow, state->selectedCol);
    [self copyStringToPasteboard:ToNSString(CorrelationCellLabel(cell, false, false))];
}

- (void)copySelectedCellDetail:(id)sender
{
    (void)sender;
    CorrelationMatrixState *state = [self state];
    if (!state) return;
    const CorrelationCellResult *cell = CorrelationCellAt(*state, state->selectedRow, state->selectedCol);
    std::string text = CorrelationCellCopyDetailText(cell);
    if (text.empty()) return;
    [self copyStringToPasteboard:ToNSString(text)];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_correlationMatrixControllers.erase(_correlationId);
}

@end

