@implementation DimensionalityView

- (NSString *)snapshotTabDelimitedText
{
    DimensionalityState *state = [_controller state];
    if (!state) return @"";
    const DimensionalityReportState report = BuildDimensionalityReportState(
        state->variables, state->components, state->loadings,
        state->rowsUsed.size(), state->rowsExcluded.size(), state->method,
        state->componentCount, state->status, 0, "", 8,
        state->missingMode, state->rotation, state->scale,
        state->multipleImputation, state->displayedImputation,
        state->imputationCount, state->calculationMethod);
    std::ostringstream text;
    text << "Dimensionality analysis\t" << state->method
         << "\tRotation: " << state->rotation << "\n"
         << "Calculation\t" << report.calculationMethod << "\n";
    if (!report.calculationImputation.empty())
        text << "Multiple imputation\t" << report.calculationImputation << "\n";
    text << "\n"
         << "Component\tEigenvalue\tParallel eigenvalue\tVariance\tCumulative";
    for (const rlispstat::core::DimensionalityFitComponent &component : state->components) {
        text << '\n' << component.index << '\t' << component.eigenvalue << '\t'
             << component.parallelEigenvalue << '\t' << component.variance << '\t'
             << component.cumulative;
    }
    if (!state->loadings.empty()) {
        text << "\n\nVariable";
        for (int component = 1; component <= state->componentCount; ++component)
            text << "\tComponent " << component;
        text << "\tCommunality\tUniqueness";
        for (const rlispstat::core::DimensionalityFitLoading &loading : state->loadings) {
            text << '\n' << loading.variable;
            for (int component = 0; component < state->componentCount; ++component) {
                text << '\t';
                if (component < (int)loading.values.size()) text << loading.values[(std::size_t)component];
            }
            text << '\t' << loading.communality << '\t' << loading.uniqueness;
        }
    }
    return ToNSString(text.str());
}
- (instancetype)initWithController:(DimensionalityWindowController *)controller
{
    self = [super initWithFrame:NSMakeRect(0, 0, 740, 420)];
    if (self) {
        _controller = controller;
    }
    return self;
}

- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return YES; }

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color align:(NSTextAlignment)align
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:align];
    [style setLineBreakMode:NSLineBreakByTruncatingMiddle];
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    };
}

- (NSSize)preferredContentSize
{
    DimensionalityReportViewModel model = [self reportViewModel];
    return NSMakeSize(model.layout.preferredWidth, model.layout.preferredHeight);
}

- (DimensionalityReportViewModel)reportViewModel
{
    DimensionalityState *state = [_controller state];
    return state
        ? BuildDimensionalityReportViewModel(state->variables, state->components, state->loadings,
                                             state->rowsUsed.size(), state->rowsExcluded.size(),
                                             state->method, state->componentCount, state->status,
                                             state->focusedComponent, state->focusedVariable, 8,
                                             state->missingMode, state->rotation, state->scale,
                                             state->multipleImputation, state->displayedImputation,
                                             state->imputationCount, state->calculationMethod)
        : DimensionalityReportViewModel();
}

- (DimensionalityReportState)reportState
{
    return [self reportViewModel].report;
}

- (DimensionalityReportLayout)reportLayout
{
    return [self reportViewModel].layout;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    DimensionalityState *state = [_controller state];
    if (!state) return;
    DimensionalityReportViewModel model = [self reportViewModel];
    DimensionalityReportRenderPlan renderPlan = model.renderPlan;
    auto nsRect = [](const rlispstat::core::Rect &rect) {
        return rlispstat::platform::macos::ToNSRect(rect);
    };

    NSColor *text = [NSColor colorWithCalibratedWhite:0.15 alpha:1.0];
    NSColor *muted = [NSColor colorWithCalibratedWhite:0.45 alpha:1.0];
    NSColor *focusFill = [NSColor colorWithCalibratedRed:0.000 green:0.447 blue:0.698 alpha:0.10];
    NSColor *focusStrongFill = [NSColor colorWithCalibratedRed:0.902 green:0.624 blue:0.000 alpha:0.16];
    NSDictionary *sectionAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:text align:NSTextAlignmentLeft];
    NSDictionary *leftAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:text align:NSTextAlignmentLeft];
    NSDictionary *mutedAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:muted align:NSTextAlignmentLeft];
    NSDictionary *rightAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:text align:NSTextAlignmentRight];
    NSDictionary *rightHeaderAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:text align:NSTextAlignmentRight];

    for (const rlispstat::core::DimensionalityReportHighlightItem &highlight : renderPlan.highlights) {
        NSColor *fill = highlight.role == DimensionalityReportHighlightRole::Strong ? focusStrongFill : focusFill;
        [fill setFill];
        NSRectFillUsingOperation(nsRect(highlight.rect), NSCompositingOperationSourceOver);
    }

    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    for (const rlispstat::core::DimensionalityReportRuleItem &ruleItem : renderPlan.rules) {
        NSBezierPath *rule = [NSBezierPath bezierPath];
        [rule moveToPoint:NSMakePoint(ruleItem.start.x, ruleItem.start.y)];
        [rule lineToPoint:NSMakePoint(std::min([self bounds].size.width - 18.0, ruleItem.end.x),
                                      ruleItem.end.y)];
        [rule stroke];
    }

    auto attrsForRole = [&](DimensionalityReportTextRole role) -> NSDictionary * {
        switch (role) {
        case DimensionalityReportTextRole::Section:
            return sectionAttrs;
        case DimensionalityReportTextRole::Muted:
            return mutedAttrs;
        case DimensionalityReportTextRole::Right:
            return rightAttrs;
        case DimensionalityReportTextRole::RightHeader:
            return rightHeaderAttrs;
        case DimensionalityReportTextRole::Left:
        default:
            return leftAttrs;
        }
    };
    for (const rlispstat::core::DimensionalityReportTextItem &item : renderPlan.texts) {
        [ToNSString(item.text) drawInRect:nsRect(item.rect) withAttributes:attrsForRole(item.role)];
    }
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    DimensionalityState *state = [_controller state];
    if (!state) return;
    DimensionalityReportState report = [self reportState];
    DimensionalityReportLayout layout = rlispstat::core::BuildDimensionalityReportLayout(report);
    DimensionalityReportHit hit = rlispstat::core::HitTestDimensionalityReport(
        report, layout, rlispstat::platform::macos::ToCorePoint(p));
    DimensionalityReportAction action = DimensionalityReportPrimaryActionForHit(hit);
    switch (action.kind) {
    case DimensionalityReportActionKind::FocusComponent:
        SetDimensionalityFocusedComponentOnMain(state->id, action.component, false);
        return;
    case DimensionalityReportActionKind::FocusLoading:
        SetDimensionalityFocusOnMain(state->id, action.component, action.variable, false);
        return;
    case DimensionalityReportActionKind::OpenVariableMenu:
        if (action.focusVariable) {
            SetDimensionalityFocusedVariableOnMain(state->id, action.variable, false);
        }
        [_controller showVariableMenuForIndex:(NSInteger)action.variableIndex atPoint:p inView:self];
        return;
    case DimensionalityReportActionKind::OpenAddVariableMenu:
        [_controller showAddVariableMenuAtPoint:p inView:self];
        return;
    case DimensionalityReportActionKind::OpenAnalysisMenu:
        [_controller showAnalysisMenuAtPoint:p inView:self];
        return;
    case DimensionalityReportActionKind::ClearFocus:
    default:
        ClearDimensionalityFocusOnMain(state->id);
        return;
    }
}

- (void)rightMouseDown:(NSEvent *)event
{
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    DimensionalityState *state = [_controller state];
    if (state) {
        DimensionalityReportState report = [self reportState];
        DimensionalityReportLayout layout = rlispstat::core::BuildDimensionalityReportLayout(report);
        DimensionalityReportHit hit = rlispstat::core::HitTestDimensionalityReport(
            report, layout, rlispstat::platform::macos::ToCorePoint(p));
        DimensionalityReportAction action = DimensionalityReportContextActionForHit(hit);
        if (action.kind == DimensionalityReportActionKind::OpenVariableMenu) {
            [_controller showVariableMenuForIndex:(NSInteger)action.variableIndex atPoint:p inView:self];
            return;
        }
        if (action.kind == DimensionalityReportActionKind::OpenAddVariableMenu) {
            [_controller showSearchableAddVariableSelectorInView:self];
            return;
        }
    }
    [_controller showAnalysisMenuAtPoint:p inView:self];
}
@end

static NSInteger PromptForDimensionalityScoreCount(NSWindow *window,
                                                    NSInteger available,
                                                    bool factor)
{
    if (available < 1) return 0;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:factor ? @"Save factor scores" : @"Save component scores"];
    [alert setInformativeText:@"Choose how many retained dimensions to add to the data sheet."];
    NSPopUpButton *popup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0, 0, 240, 28)];
    for (NSInteger count = 1; count <= available; ++count) {
        [popup addItemWithTitle:[NSString stringWithFormat:
            factor
                ? (count == 1 ? @"1 factor" : @"%ld factors")
                : (count == 1 ? @"1 component" : @"%ld components"),
            (long)count]];
    }
    [popup selectItemAtIndex:available - 1];
    [alert setAccessoryView:popup];
    [alert addButtonWithTitle:@"Save"];
    [alert addButtonWithTitle:@"Cancel"];
    [NSApp activateIgnoringOtherApps:YES];
    const NSModalResponse response = [alert runModal];
    (void)window;
    return response == NSAlertFirstButtonReturn
        ? [popup indexOfSelectedItem] + 1 : 0;
}

@implementation DimensionalityWindowController

- (void)addExportMenuToMenu:(NSMenu *)menu
{
    DimensionalityState *state = [self state];
    if (!state || !menu) return;
    AddStandardResultTableExportMenu(
        menu, _reportView, ToNSString(rlispstat::core::DimensionalityWindowTitle()),
        ToNSString(state->id.empty() ? "dimensionality" : state->id),
        [_reportView snapshotTabDelimitedText], _modelId, true);
}
- (instancetype)initWithModelId:(const std::string &)modelId
{
    self = [super init];
    if (self) {
        _modelId = modelId;
        NSRect frame = NextWindowFrameOnMain(780, 560);
        _window = [[NSWindow alloc]
            initWithContentRect:frame
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setReleasedWhenClosed:NO];
        [_window setDelegate:self];
        [_window setTitle:ToNSString(rlispstat::core::DimensionalityWindowTitle())];
        [_window setContentMinSize:NSMakeSize(720, 430)];

        NSView *content = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 780, 560)];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];
        [_window setContentView:content];

        _titleField = GLMLabel(ToNSString(rlispstat::core::DimensionalityWindowTitle()), NSMakeRect(16, 522, 360, 24), 17, NSFontWeightSemibold);
        [content addSubview:_titleField];
        _badgeField = GLMRightLabel(@"", NSMakeRect(610, 524, 150, 20), 12, NSFontWeightMedium);
        [content addSubview:_badgeField];

        _methodPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(16, 488, 156, 26)];
        [_methodPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityPCAMethodTitle())];
        [_methodPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityFactorAnalysisMethodTitle())];
        [_methodPopup setTarget:self];
        [_methodPopup setAction:@selector(methodChanged:)];
        [content addSubview:_methodPopup];

        _missingPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(184, 488, 112, 26)];
        [_missingPopup addItemWithTitle:ToNSString(rlispstat::core::MissingDataListwiseMethodLabel())];
        [_missingPopup addItemWithTitle:ToNSString(rlispstat::core::MissingDataPairwiseMethodLabel())];
        [_missingPopup setTarget:self];
        [_missingPopup setAction:@selector(missingChanged:)];
        [content addSubview:_missingPopup];

        _componentsPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(308, 488, 116, 26)];
        [_componentsPopup setTarget:self];
        [_componentsPopup setAction:@selector(componentsChanged:)];
        [content addSubview:_componentsPopup];

        _rotationPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(438, 488, 118, 26)];
        [_rotationPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityNoRotationTitle())];
        [_rotationPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityVarimaxRotationTitle())];
        [_rotationPopup addItemWithTitle:ToNSString(rlispstat::core::DimensionalityQuartimaxRotationTitle())];
        [_rotationPopup setTarget:self];
        [_rotationPopup setAction:@selector(rotationChanged:)];
        [content addSubview:_rotationPopup];

        _scopeLabel = GLMLabel(ToNSString(rlispstat::core::GLMScopeFieldLabel()), NSMakeRect(570, 490, 46, 22), 12, NSFontWeightRegular);
        [content addSubview:_scopeLabel];
        _scopePopup = [[GlobalAnalysisScopeSummary alloc] initWithFrame:NSMakeRect(616, 486, 138, 28)];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeAllDataTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeSelectedRowsTitle())];
        [_scopePopup addItemWithTitle:ToNSString(rlispstat::core::ScopeUnselectedRowsTitle())];
        [_scopePopup setTarget:self];
        [_scopePopup setAction:@selector(scopeChanged:)];
        [content addSubview:_scopePopup];

        _scaleButton = [[NSButton alloc] initWithFrame:NSMakeRect(16, 456, 120, 22)];
        [_scaleButton setButtonType:NSButtonTypeSwitch];
        [_scaleButton setTitle:ToNSString(rlispstat::core::DimensionalityStandardizeButtonTitle())];
        [_scaleButton setTarget:self];
        [_scaleButton setAction:@selector(scaleChanged:)];
        [content addSubview:_scaleButton];

        _autoFitButton = [[NSButton alloc] initWithFrame:NSMakeRect(148, 456, 100, 22)];
        [_autoFitButton setButtonType:NSButtonTypeSwitch];
        [_autoFitButton setTitle:@"Auto-fit"];
        [_autoFitButton setTarget:self];
        [_autoFitButton setAction:@selector(autoFitChanged:)];
        [content addSubview:_autoFitButton];

        _imputationPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(260, 454, 220, 26)];
        [_imputationPopup setTarget:self];
        [_imputationPopup setAction:@selector(imputationChanged:)];
        [_imputationPopup setAccessibilityLabel:@"Imputation"];
        [content addSubview:_imputationPopup];

        _selectedRowsField = GLMRightLabel(@"", NSMakeRect(590, 458, 164, 20), 12, NSFontWeightRegular);
        [content addSubview:_selectedRowsField];

        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 44, 756, 404)];
        [_scrollView setBorderType:NSNoBorder];
        [_scrollView setDrawsBackground:NO];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setAutohidesScrollers:YES];
        _reportView = [[DimensionalityView alloc] initWithController:self];
        [_scrollView setDocumentView:_reportView];
