- (void)selectScaleAxis:(id)sender;
@end
@implementation ScaleNativePlotView
- (void)mouseDown:(NSEvent *)event
{
    const NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    if (self.model->kind == "pca_scree") {
        [self.scaleController focusDimensionComponent:[self screeComponentAtPoint:point] variable:@""];
        return;
    }
    if (self.model->kind == "pca_biplot") {
        if (NSPointInRect(point, [self xAxisLabelRect])) {
            [self showVariableMenuForAxis:@"x" atPoint:point]; return;
        }
        if (NSPointInRect(point, [self yAxisLabelHitRect])) {
            [self showVariableMenuForAxis:@"y" atPoint:point]; return;
        }
        const std::string variable = [self biplotLoadingVariableAtPoint:point];
        if (!variable.empty()) {
            [self.scaleController focusDimensionComponent:0 variable:ToNSString(variable)]; return;
        }
    }
    [super mouseDown:event];
}
- (void)selectScaleAxis:(id)sender
{
    NSArray *value = [sender representedObject];
    ScaleAnalysisState *state = [self.scaleController state];
    if (!state || ![value isKindOfClass:[NSArray class]] || value.count != 2) return;
    PlotModel updated = *self.model;
    if ([value[0] isEqualToString:@"x"]) updated.biplotXComponent = [value[1] intValue];
    else updated.biplotYComponent = [value[1] intValue];
    if (!rlispstat::core::BuildScaleNativePlotModel(*state,
        ScaleAnalysisChildKind::Biplot,
        (int)[self.scaleController dimensionImputation], updated)) return;
    *self.model = std::move(updated);
    [self setNeedsDisplay:YES];
    [self.superview setNeedsDisplay:YES];
}
- (void)rightMouseDown:(NSEvent *)event
{
    [self.scaleController showContextMenuAtPoint:[self convertPoint:event.locationInWindow fromView:nil] inView:self];
}
- (void)showVariableMenuForAxis:(NSString *)axis atPoint:(NSPoint)point
{
    if (self.model->kind == "pca_biplot") {
        const auto state = [self.scaleController state];
        if (!state) return;
        const auto p = BuildScaleDimensionalityPresentation(state->result, (int)[self.scaleController dimensionImputation]);
        const int availableComponents =
            rlispstat::core::DimensionalityBiplotAvailableComponentCount(
                p.components, p.scores);
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Dimension"];
        const bool isX = [axis isEqualToString:@"x"];
        for (const auto &component : p.components) {
            if (component.index > availableComponents) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(
                DimensionalityComponentMenuLabel(state->specification.dimensionalityMethod,
                    component.index, component.variance))
                action:@selector(selectScaleAxis:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:@[axis, @(component.index)]];
            [item setState:component.index == (isX ? self.model->biplotXComponent
                : self.model->biplotYComponent) ? NSControlStateValueOn : NSControlStateValueOff];
            [item setEnabled:component.index != (isX ? self.model->biplotYComponent
                : self.model->biplotXComponent)];
            [menu addItem:item];
        }
        [menu popUpMenuPositioningItem:nil atLocation:point inView:self]; return;
    }
    [self.scaleController showContextMenuAtPoint:point inView:self];
}
@end

