@implementation ScaleAnalysisDerivedView

- (instancetype)initWithController:(ScaleAnalysisDerivedWindowController *)controller
{
    if ((self = [super initWithFrame:NSMakeRect(0, 0, 840, 440)])) {
        _controller = controller;
        _selectedCorrelationRow = -1;
        _selectedCorrelationColumn = -1;
        _focusedDimensionComponent = 0;
    }
    return self;
}

- (void)focusComponent:(NSInteger)component variable:(NSString *)variable
{
    _focusedDimensionComponent = (int)component;
    _focusedDimensionVariable = std::string([variable UTF8String] ?: "");
