- (void)detachNativePlot
{
    g_views.erase(std::remove(g_views.begin(), g_views.end(), _nativePlotView), g_views.end());
}

- (BOOL)isFlipped { return YES; }

- (NSSize)preferredContentSize
{
    ScaleAnalysisState *state = [_controller state];
    const auto kind = [_controller kind];
    if (kind == ScaleAnalysisChildKind::ScreePlot || kind == ScaleAnalysisChildKind::Biplot ||
        kind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot) return NSMakeSize(780, 510);
    if (state && (kind == ScaleAnalysisChildKind::ItemRestPlot || kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot))
        return NSMakeSize(900, 230 + 36 * state->result.items.size());
    std::size_t rows = 8;
    if (state) {
        if (kind == ScaleAnalysisChildKind::Reliability)
            rows = std::max<std::size_t>(8, state->result.reliabilityByImputation.size() + 6);
        else if (kind == ScaleAnalysisChildKind::InterItemCorrelations) {
            const auto plan = rlispstat::core::BuildScaleCorrelationRenderPlan(
                state->result, (int)_selectedCorrelationRow,
                (int)_selectedCorrelationColumn,
                [_controller showCorrelationStars],
                [_controller showCorrelationPValues],
                [_controller showCorrelationN]);
            return NSMakeSize(std::max(900.0, plan.layout.width + 28.0),
                plan.layout.height + 168.0);
        } else if (kind == ScaleAnalysisChildKind::Dimensionality) {
            const auto model = rlispstat::core::BuildScaleDimensionalityReportViewModel(
                state->result, _focusedDimensionComponent,
                _focusedDimensionVariable, (int)[_controller dimensionImputation],
                state->specification.dimensionalityMethod);
            const CGFloat stabilityHeight = 70.0 +
                21.0 * ScaleFactorCountRows(state->result).size();
            // This is the document size, not the on-screen window size.  Keep
            // the complete loading table here and let
            // FitResultTableWindowToContent cap only the window to the visible
            // screen.  Capping both at 900 made the final loading rows
            // impossible to reach even though the view was inside a scroll
            // view.
            return NSMakeSize(std::max(900.0, model.layout.preferredWidth + 28.0),
                model.layout.preferredHeight + stabilityHeight + 130.0);
        }
        else if (kind == ScaleAnalysisChildKind::ItemDistributionsPlot) {
            double height = 130;
            for (const auto &series : state->result.plotSeries)
                if (series.kind == "item_distribution") height += 62 + 24 * series.labels.size();
            return NSMakeSize(800, height);
        }
        else if (kind == ScaleAnalysisChildKind::CorrelationHeatmap)
            rows = std::max<std::size_t>(18, state->specification.items.size() * 3 + 6);
        else if (kind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot ||
                 kind == ScaleAnalysisChildKind::ScreePlot ||
                 kind == ScaleAnalysisChildKind::Biplot)
            rows = 24;
        else if (kind == ScaleAnalysisChildKind::LoadingPlot) {
            const auto presentation =
                rlispstat::core::BuildScaleDimensionalityPresentation(
                    state->result, (int)[_controller dimensionImputation]);
            const std::size_t factorCount = presentation.loadings.empty()
                ? 1 : std::max<std::size_t>(
                    1, presentation.loadings.front().values.size());
            rows = std::max<std::size_t>(12,
                state->specification.items.size() * factorCount + 5);
        }
    }
    return NSMakeSize(900, 120 + 22 * rows);
}

- (NSString *)snapshotTabDelimitedText
{
    ScaleAnalysisState *state = [_controller state];
    // Export remains revision-bound even when an older result is kept visible
    // for comparison with Auto-fit off.
    if (!state || !ScaleAnalysisResultMatchesSpecification(
            state->specification, state->result)) return @"";
    std::ostringstream out;
    const auto kind = [_controller kind];
    out << ScaleAnalysisChildWindowTitle(kind,
        GroupIsMultipleImputation(state->group)) << '\n';
    if (kind == ScaleAnalysisChildKind::Reliability) {
        out << "Imputation\tAlpha\tStandardized alpha\tOmega total\n";
        for (const auto &row : state->result.reliabilityByImputation)
            out << row.imputation << '\t' << row.alpha << '\t'
                << row.standardizedAlpha << '\t' << row.omegaTotal << '\n';
    } else if (kind == ScaleAnalysisChildKind::InterItemCorrelations ||
               kind == ScaleAnalysisChildKind::CorrelationHeatmap) {
        const auto &value = state->result.correlations;
        out << "Item";
        for (const auto &name : value.variables) out << '\t' << name;
        out << '\n';
        const std::size_t n = value.variables.size();
        for (std::size_t row = 0; row < n; ++row) {
            out << value.variables[row];
            for (std::size_t column = 0; column < n; ++column)
                out << '\t' << value.values[row * n + column];
            out << '\n';
        }
    } else if (kind == ScaleAnalysisChildKind::Dimensionality ||
               kind == ScaleAnalysisChildKind::ScreePlot) {
        const auto presentation = BuildScaleDimensionalityPresentation(
            state->result, (int)[_controller dimensionImputation]);
        out << (state->specification.dimensionalityMethod == "pca"
            ? "Components" : "Factors") << "\tImputations\tProportion\n";
        for (const auto &row : ScaleFactorCountRows(state->result))
            out << row.factorCount << '\t' << row.imputations << '\t' << row.proportion << '\n';
        out << "Component\tObserved eigenvalue\tParallel reference\n";
        for (const auto &row : presentation.components)
            out << row.index << '\t' << row.eigenvalue << '\t' << row.parallelEigenvalue << '\n';
    } else if (kind == ScaleAnalysisChildKind::ScaleScores) {
        const auto &value = state->result.scores;
        out << "Method\t" << (state->result.imputationCount > 1
            ? "N per imputation" : "Valid N") << "\tMean\tSD\tMinimum\tMaximum\n"
            << value.method << '\t' << value.validN << '\t' << value.mean << '\t'
            << value.sd << '\t' << value.minimum << '\t' << value.maximum << '\n';
    } else if (kind == ScaleAnalysisChildKind::ItemRestPlot ||
               kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot) {
        out << "Item\t" << (kind == ScaleAnalysisChildKind::ItemRestPlot
            ? "Item-rest r" : "Alpha if deleted") << '\n';
        for (const auto &row : state->result.items)
            out << row.variable << '\t'
                << (kind == ScaleAnalysisChildKind::ItemRestPlot
                    ? row.itemRestCorrelation : row.alphaIfDeleted) << '\n';
    } else if (kind == ScaleAnalysisChildKind::LoadingPlot ||
               kind == ScaleAnalysisChildKind::Biplot) {
        const auto presentation = BuildScaleDimensionalityPresentation(
            state->result, (int)[_controller dimensionImputation]);
        out << "Imputation\tItem\tLoadings\tCommunality\tUniqueness\n";
        for (const auto &row : presentation.loadings) {
            out << presentation.imputation << '\t' << row.variable << '\t';
            for (std::size_t index = 0; index < row.values.size(); ++index) {
                if (index) out << "; ";
                out << row.values[index];
            }
            out << '\t' << row.communality << '\t' << row.uniqueness << '\n';
        }
    } else {
        out << "Series\tLabel\tValue\n";
        for (const auto &series : state->result.plotSeries) {
            const bool requested =
                (kind == ScaleAnalysisChildKind::ItemDistributionsPlot &&
                    series.kind == "item_distribution") ||
                (kind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot &&
                    series.kind == "score_distribution");
            if (!requested) continue;
            for (std::size_t index = 0; index < std::min(series.labels.size(), series.values.size()); ++index)
                out << series.name << '\t' << series.labels[index] << '\t' << series.values[index] << '\n';
        }
    }
    return ToNSString(out.str());
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor textBackgroundColor] setFill]; NSRectFill(self.bounds);
    ScaleAnalysisState *state = [_controller state];
    if (!state) return;
    _itemPlotHits.clear(); _heatmapRect = NSZeroRect;
    const auto nativeKind = [_controller kind];
    const bool nativeChart = nativeKind == ScaleAnalysisChildKind::ScreePlot ||
        nativeKind == ScaleAnalysisChildKind::Biplot || nativeKind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot;
    if (nativeChart) {
        const bool ready = rlispstat::core::BuildScaleNativePlotModel(*state, nativeKind,
            (int)[_controller dimensionImputation], _nativePlot);
        if (!_nativePlotView) {
            _nativePlotView = [[ScaleNativePlotView alloc] initWithModel:&_nativePlot];
            _nativePlotView.scaleController = _controller;
            g_views.push_back(_nativePlotView);
            [self addSubview:_nativePlotView];
        }
        [_nativePlotView setHidden:!ready];
        if (ready) {
            [_nativePlotView setFrame:self.bounds]; [_nativePlotView setNeedsDisplay:YES];
            return;
        }
    }
    NSDictionary *title = @{NSFontAttributeName:[NSFont systemFontOfSize:16 weight:NSFontWeightSemibold],
                            NSForegroundColorAttributeName:[NSColor labelColor]};
    NSDictionary *head = @{NSFontAttributeName:[NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
                           NSForegroundColorAttributeName:[NSColor labelColor]};
    NSDictionary *body = @{NSFontAttributeName:[NSFont systemFontOfSize:12],
                           NSForegroundColorAttributeName:[NSColor labelColor]};
    NSDictionary *muted = @{NSFontAttributeName:[NSFont systemFontOfSize:11],
                            NSForegroundColorAttributeName:[NSColor secondaryLabelColor]};
    auto value = [](const std::string &text) -> NSString * {
        return text.empty() ? @"—" : ToNSString(text);
    };
    auto rule = [&](CGFloat y) {
        [[NSColor separatorColor] setStroke];
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:NSMakePoint(14, y)];
        [line lineToPoint:NSMakePoint(self.bounds.size.width - 14, y)]; [line stroke];
    };
    auto drawLineSeries = [&](const std::vector<const rlispstat::core::ScalePlotSeriesResult *> &series,
                              CGFloat top, CGFloat height) {
        if (series.empty()) return;
        double minimum = std::numeric_limits<double>::infinity();
        double maximum = -std::numeric_limits<double>::infinity();
        std::size_t pointCount = 0;
        for (const auto *entry : series) {
            pointCount = std::max(pointCount, entry->values.size());
            for (const auto &raw : entry->values) {
                char *end = nullptr;
                const double number = std::strtod(raw.c_str(), &end);
                if (end != raw.c_str() && std::isfinite(number)) {
                    minimum = std::min(minimum, number); maximum = std::max(maximum, number);
                }
            }
        }
        if (!pointCount || !std::isfinite(minimum) || !std::isfinite(maximum)) return;
        if (!(maximum > minimum)) { minimum -= .5; maximum += .5; }
        const CGFloat left = 64, right = 190;
        const CGFloat width = std::max<CGFloat>(320, self.bounds.size.width - left - right - 20);
        [[NSColor separatorColor] setStroke];
        NSBezierPath *axes = [NSBezierPath bezierPath];
        [axes moveToPoint:NSMakePoint(left, top)];
        [axes lineToPoint:NSMakePoint(left, top + height)];
        [axes lineToPoint:NSMakePoint(left + width, top + height)]; [axes stroke];
        NSArray<NSColor *> *palette = @[
            [NSColor colorWithCalibratedRed:.10 green:.45 blue:.88 alpha:1],
            [NSColor colorWithCalibratedRed:.90 green:.25 blue:.30 alpha:1],
            [NSColor colorWithCalibratedRed:.16 green:.66 blue:.48 alpha:1],
            [NSColor colorWithCalibratedRed:.63 green:.37 blue:.82 alpha:1],
            [NSColor colorWithCalibratedRed:.92 green:.58 blue:.12 alpha:1]
        ];
        std::size_t legendIndex = 0;
        for (std::size_t seriesIndex = 0; seriesIndex < series.size(); ++seriesIndex) {
            const auto *entry = series[seriesIndex];
            const bool perImputation = entry->kind.find("_imputation") != std::string::npos ||
                (entry->kind == "score_distribution" && series.size() > 1);
            NSColor *base = [palette objectAtIndex:seriesIndex % [palette count]];
            NSColor *color = [base colorWithAlphaComponent:perImputation ? .26 : .95];
            NSBezierPath *path = [NSBezierPath bezierPath]; BOOL started = NO;
            for (std::size_t index = 0; index < entry->values.size(); ++index) {
                char *end = nullptr; const double number = std::strtod(entry->values[index].c_str(), &end);
                if (end == entry->values[index].c_str() || !std::isfinite(number)) continue;
                const CGFloat px = left + (pointCount <= 1 ? width / 2 :
                    width * static_cast<CGFloat>(index) / static_cast<CGFloat>(pointCount - 1));
                const CGFloat py = top + height - height * (number - minimum) / (maximum - minimum);
                if (!started) { [path moveToPoint:NSMakePoint(px, py)]; started = YES; }
                else [path lineToPoint:NSMakePoint(px, py)];
                if (!perImputation) {
                    [color setFill];
                    [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(px - 2.5, py - 2.5, 5, 5)] fill];
                }
            }
            [color setStroke]; [path setLineWidth:perImputation ? .8 : 2.2]; [path stroke];
            if (!perImputation || series.size() <= 6) {
                [ToNSString(entry->name) drawAtPoint:NSMakePoint(left + width + 12,
                    top + 18 * static_cast<CGFloat>(legendIndex++)) withAttributes:muted];
            }
        }
        if (series.size() > 6)
            [@"Faint lines: individual imputations" drawAtPoint:NSMakePoint(left + width + 12, top)
