        [ToNSString(FormatDouble(maximum, 2)) drawAtPoint:NSMakePoint(8, top - 7) withAttributes:muted];
        [ToNSString(FormatDouble(minimum, 2)) drawAtPoint:NSMakePoint(8, top + height - 7) withAttributes:muted];
    };
    CGFloat y = 14;
    const auto kind = [_controller kind];
    [ToNSString(ScaleAnalysisChildWindowTitle(kind,
