        y += 38;
    }
    NSString *identity = ToNSString(state->group);
    [identity drawAtPoint:NSMakePoint(16, y) withAttributes:muted]; y += 28; rule(y); y += 14;

    if (kind == ScaleAnalysisChildKind::Reliability) {
        const auto &summary = state->result.scaleSummary;
        [@"Reliability summary" drawAtPoint:NSMakePoint(16, y) withAttributes:head]; y += 24;
        NSString *line = [NSString stringWithFormat:@"Alpha: %@     Standardized alpha: %@     Omega total: %@     Mean inter-item r: %@",
            value(summary.alpha), value(summary.standardizedAlpha), value(summary.omegaTotal),
