        [line drawAtPoint:NSMakePoint(16, y) withAttributes:body]; y += 26;
        const CGFloat x[] = {16, 165, 310, 510};
        [@"Imputation" drawAtPoint:NSMakePoint(x[0], y) withAttributes:head];
        [@"Alpha" drawAtPoint:NSMakePoint(x[1], y) withAttributes:head];
        [@"Standardized alpha" drawAtPoint:NSMakePoint(x[2], y) withAttributes:head];
        [@"Omega total" drawAtPoint:NSMakePoint(x[3], y) withAttributes:head]; y += 23;
        for (const auto &row : state->result.reliabilityByImputation) {
            [value(row.imputation) drawAtPoint:NSMakePoint(x[0], y) withAttributes:body];
            [value(row.alpha) drawAtPoint:NSMakePoint(x[1], y) withAttributes:body];
            [value(row.standardizedAlpha) drawAtPoint:NSMakePoint(x[2], y) withAttributes:body];
            [value(row.omegaTotal) drawAtPoint:NSMakePoint(x[3], y) withAttributes:body]; y += 21;
        }
        y += 8;
        [@"For multiple imputation, reliability is computed separately by psych in every completed dataset. The displayed aggregate is descriptive (mean and range), not Rubin-pooled."
            drawInRect:NSMakeRect(16, y, self.bounds.size.width - 32, 38) withAttributes:muted];
    } else if (kind == ScaleAnalysisChildKind::InterItemCorrelations) {
        const auto &correlations = state->result.correlations;
        NSString *note = [NSString stringWithFormat:@"Basis: %@ · %@", value(correlations.basis), value(correlations.status)];
        [note drawAtPoint:NSMakePoint(16, y) withAttributes:muted]; y += 25;
        const auto plan = rlispstat::core::BuildScaleCorrelationRenderPlan(
            state->result, (int)_selectedCorrelationRow,
            (int)_selectedCorrelationColumn,
            [_controller showCorrelationStars],
            [_controller showCorrelationPValues],
            [_controller showCorrelationN]);
        const CGFloat offsetY = y - plan.layout.top;
        auto translated = [&](const rlispstat::core::Rect &rect) {
            return NSMakeRect(rect.x, rect.y + offsetY, rect.width, rect.height);
        };
        NSMutableParagraphStyle *centerStyle = [[NSMutableParagraphStyle alloc] init];
        [centerStyle setAlignment:NSTextAlignmentCenter];
        NSDictionary *center = @{NSFontAttributeName:[NSFont systemFontOfSize:12],
            NSForegroundColorAttributeName:[NSColor labelColor],
            NSParagraphStyleAttributeName:centerStyle};
        NSDictionary *centerMuted = @{NSFontAttributeName:[NSFont systemFontOfSize:11],
            NSForegroundColorAttributeName:[NSColor secondaryLabelColor],
            NSParagraphStyleAttributeName:centerStyle};
        NSDictionary *centerHead = @{NSFontAttributeName:[NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
            NSForegroundColorAttributeName:[NSColor labelColor],
            NSParagraphStyleAttributeName:centerStyle};
        [[NSColor separatorColor] setStroke];
        NSBezierPath *matrixRule = [NSBezierPath bezierPath];
        [matrixRule moveToPoint:NSMakePoint(plan.headerRuleRect.x,
            plan.headerRuleRect.y + offsetY)];
        [matrixRule lineToPoint:NSMakePoint(plan.headerRuleRect.x +
            plan.headerRuleRect.width, plan.headerRuleRect.y + offsetY)];
        [matrixRule stroke];
        for (const auto &header : plan.columnHeaders)
            [ToNSString(header.text) drawInRect:translated(header.rect) withAttributes:centerHead];
        for (const auto &header : plan.rowHeaders)
            [ToNSString(header.text) drawInRect:translated(header.rect) withAttributes:body];
        for (const auto &cell : plan.cells) {
            NSRect cellRect = translated(cell.rect);
            if (cell.background == rlispstat::core::CorrelationCellBackground::Selected) {
                [[NSColor selectedContentBackgroundColor] setFill];
                NSRectFillUsingOperation(NSInsetRect(cellRect, 1, 1),
                    NSCompositingOperationSourceOver);
            } else if (cell.background == rlispstat::core::CorrelationCellBackground::Diagonal) {
                [[NSColor controlBackgroundColor] setFill];
                NSRectFill(NSInsetRect(cellRect, 1, 1));
            }
            for (const auto &textItem : cell.textItems)
                [ToNSString(textItem.text) drawInRect:translated(textItem.rect)
                    withAttributes:(textItem.muted ? centerMuted : center)];
        }
        if (plan.showEmptyMessage)
            [ToNSString(plan.emptyMessage) drawInRect:translated(plan.emptyMessageRect)
                withAttributes:muted];
        y = offsetY + plan.layout.height + 8;
        [@"Pearson correlations use Fisher-z plus mice::pool.scalar. Polychoric and mixed matrices are descriptive element-wise means across imputations and are explicitly not pooled."
            drawInRect:NSMakeRect(16, y, self.bounds.size.width - 32, 42) withAttributes:muted];
    } else if (kind == ScaleAnalysisChildKind::Dimensionality) {
        const bool pca = state->specification.dimensionalityMethod == "pca";
