            drawAtPoint:NSMakePoint(16, y) withAttributes:head]; y += 24;
        const CGFloat x[] = {16, 150, 310};
        [(pca ? @"Components" : @"Factors")
            drawAtPoint:NSMakePoint(x[0], y) withAttributes:head];
        [@"Imputations" drawAtPoint:NSMakePoint(x[1], y) withAttributes:head];
        [@"Proportion" drawAtPoint:NSMakePoint(x[2], y) withAttributes:head]; y += 22;
        for (const auto &row : ScaleFactorCountRows(state->result)) {
            [ToNSString(std::to_string(row.factorCount)) drawAtPoint:NSMakePoint(x[0], y) withAttributes:body];
            [ToNSString(std::to_string(row.imputations)) drawAtPoint:NSMakePoint(x[1], y) withAttributes:body];
            [ToNSString(FormatDouble(100.0 * row.proportion, 1) + "%") drawAtPoint:NSMakePoint(x[2], y) withAttributes:body]; y += 21;
        }
        y += 13;
        }
        // Explain score availability before the selected imputation's loadings.
        // A table of loadings may be valid even when another imputation cannot
