            _focusedDimensionVariable,
            (int)[_controller dimensionImputation],
            state->specification.dimensionalityMethod);
        const CGFloat offsetY = y;
        auto translated = [&](const rlispstat::core::Rect &rect) {
            return NSMakeRect(rect.x, rect.y + offsetY, rect.width, rect.height);
        };
        NSMutableParagraphStyle *rightStyle = [[NSMutableParagraphStyle alloc] init];
        [rightStyle setAlignment:NSTextAlignmentRight];
        NSDictionary *rightBody = @{NSFontAttributeName:[NSFont systemFontOfSize:12],
            NSForegroundColorAttributeName:[NSColor labelColor],
            NSParagraphStyleAttributeName:rightStyle};
        NSDictionary *rightHead = @{NSFontAttributeName:[NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
            NSForegroundColorAttributeName:[NSColor labelColor],
            NSParagraphStyleAttributeName:rightStyle};
        for (const auto &highlight : model.renderPlan.highlights) {
            NSColor *fill = highlight.role == DimensionalityReportHighlightRole::Strong
