            [sharedRule moveToPoint:NSMakePoint(ruleItem.start.x,
                ruleItem.start.y + offsetY)];
            [sharedRule lineToPoint:NSMakePoint(ruleItem.end.x,
                ruleItem.end.y + offsetY)];
            [sharedRule stroke];
        }
        auto attrsForRole = [&](DimensionalityReportTextRole role) -> NSDictionary * {
            switch (role) {
            case DimensionalityReportTextRole::Section: return head;
            case DimensionalityReportTextRole::Muted: return muted;
            case DimensionalityReportTextRole::Right: return rightBody;
            case DimensionalityReportTextRole::RightHeader: return rightHead;
            case DimensionalityReportTextRole::Left:
            default: return body;
            }
        };
        for (const auto &item : model.renderPlan.texts)
            [ToNSString(item.text) drawInRect:translated(item.rect)
                withAttributes:attrsForRole(item.role)];
        y = offsetY + model.layout.preferredHeight + 8;
        [ToNSString(model.report.status) drawInRect:NSMakeRect(16, y, self.bounds.size.width - 32, 72)
            withAttributes:muted];
    } else if (kind == ScaleAnalysisChildKind::ScaleScores) {
        const auto &score = state->result.scores;
        const CGFloat x[] = {16, 145, 260, 365, 480, 600};
        NSString *sampleSizeLabel = state->result.imputationCount > 1
