        const NSString *labels[] = {@"Method", sampleSizeLabel, @"Mean", @"SD", @"Minimum", @"Maximum"};
        const std::string values[] = {score.method, score.validN, score.mean, score.sd, score.minimum, score.maximum};
        for (int index = 0; index < 6; ++index) {
