        _heatmapRect = NSMakeRect(180, y + 38, n * cell, n * cell);
        for (std::size_t index = 0; index < n; ++index) {
            [ToNSString(correlations.variables[index]) drawInRect:NSMakeRect(
                175 + cell * index, y, cell, 34) withAttributes:muted];
            [ToNSString(correlations.variables[index]) drawInRect:NSMakeRect(
                16, y + 38 + cell * index, 150, cell) withAttributes:muted];
        }
        for (std::size_t row = 0; row < n; ++row) for (std::size_t column = 0; column < n; ++column) {
            const std::size_t index = row * n + column;
            const double number = index < correlations.values.size()
                ? std::strtod(correlations.values[index].c_str(), nullptr) : 0;
            NSColor *color = number >= 0
                ? [NSColor colorWithCalibratedRed:.10 green:.45 blue:.88 alpha:.12 + .82 * std::min(1.0, std::fabs(number))]
                : [NSColor colorWithCalibratedRed:.90 green:.25 blue:.30 alpha:.12 + .82 * std::min(1.0, std::fabs(number))];
            const NSRect cellRect = NSMakeRect(180 + cell * column, y + 38 + cell * row, cell - 1, cell - 1);
            [color setFill]; NSRectFill(cellRect);
