        if (kind == ScaleAnalysisChildKind::ItemDistributionsPlot) {
            [@"Response frequencies (%) — missing responses excluded" drawAtPoint:NSMakePoint(16, y) withAttributes:muted]; y += 30;
            for (const auto &series : state->result.plotSeries) {
