            }
            [[NSColor separatorColor] setFill]; NSRectFill(NSMakeRect(zero, y, 1, 24));
            [value(entry.second) drawAtPoint:NSMakePoint(left + width + 16, y) withAttributes:body]; y += 36;
        }
        _barRowsCount = bars.size();
        if (kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot) {
            [[NSString stringWithFormat:@"Full-scale alpha: %@. Negative bars extend left of zero; exact values are printed at right.", value(state->result.scaleSummary.alpha)]
                drawInRect:NSMakeRect(16, y + 12, self.bounds.size.width - 32, 45) withAttributes:muted];
        }

    }
}

- (void)mouseDown:(NSEvent *)event
{
    ScaleAnalysisState *state = [_controller state];
    if (!state || !ScaleAnalysisResultMatchesSpecification(
            state->specification, state->result)) return;
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    const auto kind = [_controller kind];
    for (const auto &hit : _itemPlotHits) if (NSPointInRect(point, hit.first)) {
        [_controller showItemMenuForIndex:hit.second atPoint:point inView:self]; return;
    }
    if (kind == ScaleAnalysisChildKind::CorrelationHeatmap && NSPointInRect(point, _heatmapRect)) {
        const auto n = state->result.correlations.variables.size();
        const int row = (point.y - _heatmapRect.origin.y) / (_heatmapRect.size.height / n);
        const int col = (point.x - _heatmapRect.origin.x) / (_heatmapRect.size.width / n);
        [_controller showCorrelationCellMenuForRow:row column:col atPoint:point inView:self]; return;
    }
    if ((kind == ScaleAnalysisChildKind::ItemRestPlot || kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot) &&
        point.y >= _barRowsOrigin && point.y < _barRowsOrigin + 36 * _barRowsCount) {
        [_controller showItemMenuForIndex:(NSInteger)((point.y - _barRowsOrigin) / 36) atPoint:point inView:self];
        return;
    }

    if (kind == ScaleAnalysisChildKind::InterItemCorrelations) {
        const auto plan = rlispstat::core::BuildScaleCorrelationRenderPlan(
            state->result, (int)_selectedCorrelationRow,
            (int)_selectedCorrelationColumn,
            [_controller showCorrelationStars],
            [_controller showCorrelationPValues],
            [_controller showCorrelationN]);
        const CGFloat matrixTop = 115.0;
        const CGFloat offsetY = matrixTop - plan.layout.top;
        rlispstat::core::Point adjusted =
            rlispstat::platform::macos::ToCorePoint(point);
        adjusted.y -= offsetY;
        const auto hit = HitTestCorrelationMatrix(plan.layout, adjusted);
        if (hit.kind == rlispstat::core::CorrelationMatrixHitKind::Variable) {
            [_controller showItemMenuForIndex:hit.variableIndex
                atPoint:point inView:self];
            return;
        }
        if (hit.kind == rlispstat::core::CorrelationMatrixHitKind::Cell) {
            _selectedCorrelationRow = hit.row;
            _selectedCorrelationColumn = hit.column;
            [self setNeedsDisplay:YES];
            if ([event clickCount] >= 2)
                [_controller openCorrelationCellAtRow:hit.row column:hit.column];
            return;
        }
    } else if (kind == ScaleAnalysisChildKind::Dimensionality) {
        const auto factorRows = ScaleFactorCountRows(state->result);
        const CGFloat reportTop = 90.0 + 24.0 + 22.0 +
            21.0 * factorRows.size() + 13.0;
        const auto model = rlispstat::core::BuildScaleDimensionalityReportViewModel(
            state->result, _focusedDimensionComponent,
            _focusedDimensionVariable,
            (int)[_controller dimensionImputation],
            state->specification.dimensionalityMethod);
        rlispstat::core::Point adjusted =
            rlispstat::platform::macos::ToCorePoint(point);
        adjusted.y -= reportTop;
        const auto hit = rlispstat::core::HitTestDimensionalityReport(
            model.report, model.layout, adjusted);
        const auto action = DimensionalityReportPrimaryActionForHit(hit);
        if (action.kind == DimensionalityReportActionKind::OpenVariableMenu) {
            [_controller showItemMenuForIndex:(NSInteger)action.variableIndex
                atPoint:point inView:self];
            return;
        }
        if (action.kind == DimensionalityReportActionKind::FocusComponent) {
            _focusedDimensionComponent = action.component;
            _focusedDimensionVariable.clear();
            [self setNeedsDisplay:YES];
            return;
        }
        if (action.kind == DimensionalityReportActionKind::FocusLoading) {
            _focusedDimensionComponent = action.component;
            _focusedDimensionVariable = action.variable;
            [self setNeedsDisplay:YES];
            return;
        }
        if (action.kind == DimensionalityReportActionKind::ClearFocus) {
            _focusedDimensionComponent = 0;
            _focusedDimensionVariable.clear();
            [self setNeedsDisplay:YES];
            return;
        }
    }
    [super mouseDown:event];
}

- (void)rightMouseDown:(NSEvent *)event
{
    ScaleAnalysisState *state = [_controller state];
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    if (!state || !ScaleAnalysisResultMatchesSpecification(
            state->specification, state->result)) return;
    const auto kind = [_controller kind];
    for (const auto &hit : _itemPlotHits) if (NSPointInRect(point, hit.first)) {
        [_controller showItemMenuForIndex:hit.second atPoint:point inView:self]; return;
    }
    if (kind == ScaleAnalysisChildKind::CorrelationHeatmap && NSPointInRect(point, _heatmapRect)) {
        const auto n = state->result.correlations.variables.size();
        const int row = (point.y - _heatmapRect.origin.y) / (_heatmapRect.size.height / n);
        const int col = (point.x - _heatmapRect.origin.x) / (_heatmapRect.size.width / n);
        [_controller showCorrelationCellMenuForRow:row column:col atPoint:point inView:self]; return;
    }
    if (kind == ScaleAnalysisChildKind::InterItemCorrelations) {
        const auto plan = rlispstat::core::BuildScaleCorrelationRenderPlan(
            state->result, (int)_selectedCorrelationRow,
            (int)_selectedCorrelationColumn,
            [_controller showCorrelationStars],
            [_controller showCorrelationPValues],
            [_controller showCorrelationN]);
        rlispstat::core::Point adjusted =
            rlispstat::platform::macos::ToCorePoint(point);
        adjusted.y -= 115.0 - plan.layout.top;
        const auto hit = HitTestCorrelationMatrix(plan.layout, adjusted);
        if (hit.kind == rlispstat::core::CorrelationMatrixHitKind::Variable) {
            [_controller showItemMenuForIndex:hit.variableIndex
                atPoint:point inView:self];
            return;
        }
        if (hit.kind == rlispstat::core::CorrelationMatrixHitKind::Cell) {
            _selectedCorrelationRow = hit.row;
            _selectedCorrelationColumn = hit.column;
            [self setNeedsDisplay:YES];
            [_controller showCorrelationCellMenuForRow:hit.row column:hit.column
                atPoint:point inView:self];
            return;
        }
    } else if (kind == ScaleAnalysisChildKind::Dimensionality) {
        const auto factorRows = ScaleFactorCountRows(state->result);
        const CGFloat reportTop = 90.0 + 24.0 + 22.0 +
            21.0 * factorRows.size() + 13.0;
        const auto model = rlispstat::core::BuildScaleDimensionalityReportViewModel(
            state->result, _focusedDimensionComponent,
            _focusedDimensionVariable,
            (int)[_controller dimensionImputation],
            state->specification.dimensionalityMethod);
        rlispstat::core::Point adjusted =
            rlispstat::platform::macos::ToCorePoint(point);
        adjusted.y -= reportTop;
        const auto hit = rlispstat::core::HitTestDimensionalityReport(
            model.report, model.layout, adjusted);
        const auto action = DimensionalityReportContextActionForHit(hit);
        if (action.kind == DimensionalityReportActionKind::OpenVariableMenu) {
            [_controller showItemMenuForIndex:(NSInteger)action.variableIndex
                atPoint:point inView:self];
            return;
        }
    }
    [_controller showContextMenuAtPoint:point inView:self];
}

@end

@implementation ScaleAnalysisDerivedWindowController

- (instancetype)initWithAnalysisId:(const std::string &)analysisId
                               kind:(ScaleAnalysisChildKind)kind
{
    if ((self = [super init])) {
        _analysisId = analysisId; _kind = kind;
        _showCorrelationStars = NO;
        _showCorrelationPValues = NO;
        _showCorrelationN = NO;
        _dimensionImputation = 1;
        ScaleAnalysisState *state = [self state];
        if (state) _identity = BuildScaleAnalysisDerivedIdentity(*state, kind);
        const bool mi = state && GroupIsMultipleImputation(state->group);
        _window = [[NSWindow alloc] initWithContentRect:NextWindowFrameOnMain(920, 560)
            styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable)
            backing:NSBackingStoreBuffered defer:NO];
        [_window setTitle:ToNSString(ScaleAnalysisChildWindowTitle(kind, mi))];
        [_window setDelegate:self]; ConfigureResultWindowTabbing(_window);
        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(10, 42, 900, 508)];
        [_scrollView setHasVerticalScroller:YES]; [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setAutohidesScrollers:NO];
        [_scrollView setBorderType:NSNoBorder];
        _reportView = [[ScaleAnalysisDerivedView alloc] initWithController:self];
        [_scrollView setDocumentView:_reportView]; [[_window contentView] addSubview:_scrollView];
        if (_kind == ScaleAnalysisChildKind::Dimensionality) {
            NSView *content = [_window contentView];
            _dimensionMethodPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(10, 518, 140, 26)];
            [_dimensionMethodPopup addItemsWithTitles:@[@"Principal components", @"Factor analysis"]];
            [_dimensionMethodPopup setTarget:self];
            [_dimensionMethodPopup setAction:@selector(setDimensionMethodFromMenu:)];
            [_dimensionMethodPopup setToolTip:@"Method: principal components or exploratory factor analysis"];
            [content addSubview:_dimensionMethodPopup];

            _dimensionMissingPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(155, 518, 110, 26)];
            [_dimensionMissingPopup addItemsWithTitles:@[@"Listwise", @"Pairwise"]];
            [_dimensionMissingPopup setTarget:self];
            [_dimensionMissingPopup setAction:@selector(setDimensionMissingFromMenu:)];
            [_dimensionMissingPopup setToolTip:@"Missing-data handling for dimensionality"];
            [content addSubview:_dimensionMissingPopup];

            _dimensionCountPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(270, 518, 115, 26)];
            [_dimensionCountPopup setTarget:self];
            [_dimensionCountPopup setAction:@selector(setFactorCountFromMenu:)];
            [_dimensionCountPopup setToolTip:@"Number of retained factors or components"];
            [content addSubview:_dimensionCountPopup];

            _dimensionRotationPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(390, 518, 115, 26)];
            [_dimensionRotationPopup addItemsWithTitles:@[@"No rotation", @"Varimax", @"Quartimax", @"Oblimin", @"Promax"]];
            [_dimensionRotationPopup setTarget:self];
            [_dimensionRotationPopup setAction:@selector(setRotationFromMenu:)];
            [_dimensionRotationPopup setToolTip:@"Rotation"];
            [content addSubview:_dimensionRotationPopup];

            _dimensionExtractionPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(510, 518, 135, 26)];
            [_dimensionExtractionPopup addItemsWithTitles:@[@"Minimum residual", @"Maximum likelihood", @"Principal axis"]];
            [_dimensionExtractionPopup setTarget:self];
            [_dimensionExtractionPopup setAction:@selector(setExtractionFromMenu:)];
            [_dimensionExtractionPopup setToolTip:@"Factor extraction method"];
            [content addSubview:_dimensionExtractionPopup];

            _dimensionScaleButton = [[NSButton alloc] initWithFrame:NSMakeRect(650, 520, 130, 22)];
            [_dimensionScaleButton setButtonType:NSButtonTypeSwitch];
            [_dimensionScaleButton setTitle:@"Standardize"];
            [_dimensionScaleButton setTarget:self];
            [_dimensionScaleButton setAction:@selector(setDimensionScaleFromControl:)];
            [content addSubview:_dimensionScaleButton];
        }
        _statusField = GLMLabel(@"", NSMakeRect(14, 10, 890, 22), 11, NSFontWeightRegular);
        [_statusField setTextColor:[NSColor secondaryLabelColor]];
        [[_window contentView] addSubview:_statusField];
        EnableNotesForWindow(_window, analysisId,
            ToNSString(ScaleAnalysisChildWindowTitle(kind, mi)),
            state ? state->group : std::string{});
        [self refresh];
    }
    return self;
}

- (ScaleAnalysisState *)state
{
    auto found = g_scaleAnalyses.find(_analysisId);
    return found == g_scaleAnalyses.end() ? nullptr : &found->second;
}

- (ScaleAnalysisChildKind)kind { return _kind; }
- (BOOL)showCorrelationStars { return _showCorrelationStars; }
- (BOOL)showCorrelationPValues { return _showCorrelationPValues; }
- (BOOL)showCorrelationN { return _showCorrelationN; }
- (NSInteger)dimensionImputation { return _dimensionImputation; }
- (void)show { [self refresh]; [NSApp activateIgnoringOtherApps:YES]; [_window makeKeyAndOrderFront:nil]; }
- (void)close { [_window close]; }

- (void)refresh
{
    ScaleAnalysisState *state = [self state]; if (!state) return;
    if (_kind == ScaleAnalysisChildKind::LoadingPlot ||
        _kind == ScaleAnalysisChildKind::Biplot) {
        const bool pca = state->specification.dimensionalityMethod == "pca";
        NSString *base = _kind == ScaleAnalysisChildKind::LoadingPlot
            ? (pca ? @"Component Loadings" : @"Factor Loadings")
            : (pca ? @"Scale Component Biplot" : @"Scale Factor Biplot");
        [_window setTitle:GroupIsMultipleImputation(state->group)
            ? [base stringByAppendingString:@" - Multiple Imputation"] : base];
    }
    // A child presentation only advances to a new identity after the backend
    // result for that exact parent revision has been accepted.  While a refit
    // is pending it keeps its old identity and therefore cannot render a
    // mixture of the new specification and the previous result.
    if (ScaleAnalysisResultMatchesSpecification(
            state->specification, state->result)) {
        _identity = BuildScaleAnalysisDerivedIdentity(*state, _kind);
    }
    const CGFloat controlsHeight = _kind == ScaleAnalysisChildKind::Dimensionality
        ? 38.0 : 0.0;
    NSSize wanted = [_reportView preferredContentSize];
    NSSize content = FitResultTableWindowToContent(_window,
        NSMakeSize(wanted.width + 20, wanted.height + 52 + controlsHeight),
        NSMakeSize(720, 360));
    [_scrollView setFrame:NSMakeRect(10, 42, content.width - 20,
        content.height - 52 - controlsHeight)];
    [_statusField setFrame:NSMakeRect(14, 10, content.width - 28, 22)];
    if (_kind == ScaleAnalysisChildKind::Dimensionality) {
        const CGFloat y = content.height - 33.0;
        [_dimensionMethodPopup setFrameOrigin:NSMakePoint(10, y)];
        [_dimensionMissingPopup setFrameOrigin:NSMakePoint(155, y)];
        [_dimensionCountPopup setFrameOrigin:NSMakePoint(270, y)];
        [_dimensionRotationPopup setFrameOrigin:NSMakePoint(390, y)];
        [_dimensionExtractionPopup setFrameOrigin:NSMakePoint(510, y)];
        [_dimensionScaleButton setFrameOrigin:NSMakePoint(650, y + 2.0)];
        const bool pca = state->specification.dimensionalityMethod == "pca";
        [_dimensionMethodPopup selectItemAtIndex:pca ? 0 : 1];
        [_dimensionMissingPopup selectItemAtIndex:
            state->specification.dimensionalityMissingMode == "listwise" ? 0 : 1];
        [_dimensionCountPopup removeAllItems];
        [_dimensionCountPopup addItemWithTitle:@"Automatic"];
        const NSInteger maximum = std::max<NSInteger>(1,
            static_cast<NSInteger>(state->specification.items.size()) - (pca ? 0 : 1));
        for (NSInteger count = 1; count <= maximum; ++count) {
            [_dimensionCountPopup addItemWithTitle:[NSString stringWithFormat:
                count == 1 ? @"1 dimension" : @"%ld dimensions", (long)count]];
        }
        [_dimensionCountPopup selectItemAtIndex:std::max<NSInteger>(0,
            std::min<NSInteger>(state->specification.factorCount, maximum))];
        const std::map<std::string, NSInteger> rotations = {
            {"none", 0}, {"varimax", 1}, {"quartimax", 2},
            {"oblimin", 3}, {"promax", 4}
        };
        auto rotation = rotations.find(state->specification.rotation);
        [_dimensionRotationPopup selectItemAtIndex:
            rotation == rotations.end() ? 0 : rotation->second];
        const std::map<std::string, NSInteger> extractions = {
            {"minres", 0}, {"ml", 1}, {"pa", 2}
        };
        auto extraction = extractions.find(state->specification.extraction);
        [_dimensionExtractionPopup selectItemAtIndex:
            extraction == extractions.end() ? 0 : extraction->second];
        [_dimensionExtractionPopup setEnabled:!pca];
        const bool allNumeric = std::all_of(
            state->specification.items.begin(), state->specification.items.end(),
            [](const ScaleItemSpecification &item) {
                return item.type == ScaleItemType::Numeric;
            });
        const bool covarianceAvailable = allNumeric &&
            (state->specification.correlationBasis == "auto" ||
             state->specification.correlationBasis == "pearson");
        [_dimensionScaleButton setEnabled:covarianceAvailable];
        [_dimensionScaleButton setState:(state->specification.dimensionalityScale ||
            !covarianceAvailable) ? NSControlStateValueOn : NSControlStateValueOff];
    }
    NSSize visible = [_scrollView contentSize];
    [_reportView setFrameSize:NSMakeSize(std::max(wanted.width, visible.width),
        std::max(wanted.height, visible.height))];
    [_reportView setNeedsDisplay:YES];
    const bool current = ScaleAnalysisDerivedIdentityMatchesState(_identity, *state);
    [_statusField setStringValue:current
        ? @""
        : @"Waiting for the current Scale Analysis revision; stale results are not displayed."];
}

- (void)showContextMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    [[self contextMenuForView:view] popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (NSMenu *)contextMenuForView:(NSView *)view
{
    ScaleAnalysisState *state = [self state];
    if (!state) return nil;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Scale Analysis result"];
    if (_kind == ScaleAnalysisChildKind::Biplot && [view isKindOfClass:[ScatterView class]]) {
        ScatterView *plot = (ScatterView *)view;
        NSMenuItem *display = [[NSMenuItem alloc] initWithTitle:@"Display" action:nil keyEquivalent:@""];
        display.submenu = [plot biplotDisplayMenu]; [menu addItem:display];
        NSMenuItem *explore = [[NSMenuItem alloc] initWithTitle:@"Explore plot" action:nil keyEquivalent:@""];
        explore.submenu = [plot plotExploreMenu]; [menu addItem:explore];
    }
    if (_kind == ScaleAnalysisChildKind::ScreePlot || _kind == ScaleAnalysisChildKind::Biplot ||
        _kind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot || _kind == ScaleAnalysisChildKind::ItemDistributionsPlot ||
        _kind == ScaleAnalysisChildKind::ItemRestPlot || _kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot ||
        _kind == ScaleAnalysisChildKind::LoadingPlot || _kind == ScaleAnalysisChildKind::CorrelationHeatmap) {
        NSMenuItem *explain = [[NSMenuItem alloc] initWithTitle:@"Explain plot" action:@selector(explainScalePlot:) keyEquivalent:@""];
        [explain setTarget:self]; [menu addItem:explain]; [menu addItem:[NSMenuItem separatorItem]];
    }
    if (_kind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot && state->result.imputationCount > 1) {
        NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Imputation" action:nil keyEquivalent:@""];
        NSMenu *choices = [[NSMenu alloc] initWithTitle:@"Imputation"];
        for (int first = 1; first <= state->result.imputationCount; first += 5) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:[NSString stringWithFormat:@"Imputations %d–%d", first, std::min(first + 4, state->result.imputationCount)]
                action:@selector(setDimensionImputationFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:@(first)]; [choices addItem:item];
        }
        [root setSubmenu:choices]; [menu addItem:root];
    }
    if (_kind == ScaleAnalysisChildKind::ScaleScores) {
        NSMenuItem *hist = [[NSMenuItem alloc] initWithTitle:@"Histogram (save score to data)…"
            action:@selector(openScoreHistogram:) keyEquivalent:@""];
        [hist setTarget:self]; [menu addItem:hist];
    }
    if (_kind == ScaleAnalysisChildKind::Reliability || _kind == ScaleAnalysisChildKind::ScaleScores ||
        _kind == ScaleAnalysisChildKind::ItemRestPlot || _kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot) {
        NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Explain statistic" action:nil keyEquivalent:@""];
        NSMenu *choices = [[NSMenu alloc] initWithTitle:@"Explain statistic"];
        NSArray *names = _kind == ScaleAnalysisChildKind::ScaleScores
            ? @[@"Method", @"Valid N", @"Mean", @"SD", @"Minimum", @"Maximum"]
            : @[@"Alpha", @"Standardized alpha", @"Omega total", @"Mean inter-item r", @"Item-rest r", @"Alpha if deleted"];
        for (NSString *name in names) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:name action:@selector(explainScaleStatistic:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:name]; [choices addItem:item];
        }
        [root setSubmenu:choices]; [menu addItem:root];
    }
    const bool correlationResult = _kind == ScaleAnalysisChildKind::InterItemCorrelations ||
        _kind == ScaleAnalysisChildKind::CorrelationHeatmap;
    const bool dimensionalityResult = _kind == ScaleAnalysisChildKind::Dimensionality ||
        _kind == ScaleAnalysisChildKind::ScreePlot || _kind == ScaleAnalysisChildKind::LoadingPlot ||
        _kind == ScaleAnalysisChildKind::Biplot;
    if (correlationResult) {
        NSMenuItem *basis = [[NSMenuItem alloc] initWithTitle:@"Correlation basis" action:nil keyEquivalent:@""];
        NSMenu *submenu = [[NSMenu alloc] initWithTitle:@"Correlation basis"];
        NSArray<NSArray<NSString *> *> *values = @[@[@"Automatic", @"auto"], @[@"Pearson", @"pearson"],
            @[@"Polychoric", @"polychoric"], @[@"Mixed correlations", @"mixed"]];
        for (NSArray<NSString *> *entry in values) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:entry[0]
                action:@selector(setCorrelationBasisFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:entry[1]];
            [item setState:state->specification.correlationBasis == [entry[1] UTF8String]
                ? NSControlStateValueOn : NSControlStateValueOff];
            [submenu addItem:item];
        }
        [basis setSubmenu:submenu]; [menu addItem:basis];
        if (_kind == ScaleAnalysisChildKind::InterItemCorrelations) {
            const bool inferential = state->result.correlations.basis == "pearson" &&
                std::any_of(state->result.correlations.pValues.begin(),
                    state->result.correlations.pValues.end(), [](const std::string &text) {
                        char *end = nullptr;
                        const double value = std::strtod(text.c_str(), &end);
                        return end != text.c_str() && end && *end == '\0' &&
                            std::isfinite(value);
                    });
            const bool hasSampleSizes =
                state->result.correlations.sampleSizes.size() ==
                    state->result.correlations.values.size() ||
                !state->result.scaleSummary.nUsed.empty();
            NSMenuItem *display = [[NSMenuItem alloc] initWithTitle:@"Display"
                action:nil keyEquivalent:@""];
            NSMenu *displayMenu = [[NSMenu alloc] initWithTitle:@"Display"];
            NSMenuItem *stars = [[NSMenuItem alloc]
                initWithTitle:@"Significance stars"
                action:@selector(toggleCorrelationStars:) keyEquivalent:@""];
            [stars setTarget:self]; [stars setEnabled:inferential];
            [stars setState:_showCorrelationStars ? NSControlStateValueOn : NSControlStateValueOff];
            [displayMenu addItem:stars];
            NSMenuItem *pValues = [[NSMenuItem alloc]
                initWithTitle:ToNSString(rlispstat::core::CorrelationShowPValuesButtonTitle())
                action:@selector(toggleCorrelationPValues:) keyEquivalent:@""];
            [pValues setTarget:self]; [pValues setEnabled:inferential];
            [pValues setState:_showCorrelationPValues ? NSControlStateValueOn : NSControlStateValueOff];
            [displayMenu addItem:pValues];
            NSMenuItem *sampleSizes = [[NSMenuItem alloc]
                initWithTitle:@"Sample sizes"
                action:@selector(toggleCorrelationN:) keyEquivalent:@""];
            [sampleSizes setTarget:self]; [sampleSizes setEnabled:hasSampleSizes];
            [sampleSizes setState:_showCorrelationN ? NSControlStateValueOn : NSControlStateValueOff];
            [displayMenu addItem:sampleSizes];
            [display setSubmenu:displayMenu]; [menu addItem:display];
        }
        NSMenuItem *explain = [[NSMenuItem alloc]
            initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
            action:nil keyEquivalent:@""];
        NSMenu *explainMenu = [[NSMenu alloc] initWithTitle:[explain title]];
        NSString *statistic = state->result.correlations.basis == "polychoric"
            ? @"Polychoric correlation" : state->result.correlations.basis == "mixed"
            ? @"Mixed correlation" : @"Pearson r";
        NSMenuItem *entry = [[NSMenuItem alloc] initWithTitle:statistic
            action:@selector(explainCorrelationStatistic:) keyEquivalent:@""];
        [entry setTarget:self]; [entry setRepresentedObject:statistic];
        [explainMenu addItem:entry]; [explain setSubmenu:explainMenu];
        [menu addItem:explain];
    }
    if (dimensionalityResult) {
        NSMenu *parentMenu = menu;
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Dimensionality"];
        NSMenuItem *method = [[NSMenuItem alloc] initWithTitle:@"Method" action:nil keyEquivalent:@""];
        NSMenu *methodMenu = [[NSMenu alloc] initWithTitle:@"Method"];
        for (NSArray<NSString *> *entry in @[@[@"Principal components", @"pca"],
                                               @[@"Factor analysis", @"factor"]]) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:entry[0]
                action:@selector(setDimensionMethodFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:entry[1]];
            [item setState:state->specification.dimensionalityMethod == [entry[1] UTF8String]
                ? NSControlStateValueOn : NSControlStateValueOff];
            [methodMenu addItem:item];
        }
        [method setSubmenu:methodMenu]; [menu addItem:method];
        NSMenuItem *missing = [[NSMenuItem alloc] initWithTitle:@"Missing data" action:nil keyEquivalent:@""];
        NSMenu *missingMenu = [[NSMenu alloc] initWithTitle:@"Missing data"];
        for (NSArray<NSString *> *entry in @[@[@"Listwise", @"listwise"],
                                               @[@"Pairwise", @"pairwise"]]) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:entry[0]
                action:@selector(setDimensionMissingFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:entry[1]];
            [item setState:state->specification.dimensionalityMissingMode == [entry[1] UTF8String]
                ? NSControlStateValueOn : NSControlStateValueOff];
            [missingMenu addItem:item];
        }
        [missing setSubmenu:missingMenu]; [menu addItem:missing];
        NSMenuItem *factors = [[NSMenuItem alloc] initWithTitle:@"Number of factors" action:nil keyEquivalent:@""];
        NSMenu *factorMenu = [[NSMenu alloc] initWithTitle:@"Number of factors"];
        const NSInteger maximum = std::max<NSInteger>(1,
            std::min<NSInteger>(8, static_cast<NSInteger>(state->specification.items.size()) - 1));
        for (NSInteger count = 0; count <= maximum; ++count) {
            NSString *label = count == 0 ? @"Automatic (parallel analysis)" : [NSString stringWithFormat:@"%ld", (long)count];
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:label
                action:@selector(setFactorCountFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:@(count)];
            [item setState:state->specification.factorCount == count ? NSControlStateValueOn : NSControlStateValueOff];
            [factorMenu addItem:item];
        }
        [factors setSubmenu:factorMenu]; [menu addItem:factors];
        auto addStringSubmenu = [&](NSString *label, NSArray<NSArray<NSString *> *> *values,
                                    SEL action, const std::string &current) {
            NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:label action:nil keyEquivalent:@""];
            NSMenu *submenu = [[NSMenu alloc] initWithTitle:label];
            for (NSArray<NSString *> *entry in values) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:entry[0] action:action keyEquivalent:@""];
                [item setTarget:self]; [item setRepresentedObject:entry[1]];
                [item setState:current == [entry[1] UTF8String] ? NSControlStateValueOn : NSControlStateValueOff];
                [submenu addItem:item];
            }
            [root setSubmenu:submenu]; [menu addItem:root];
        };
        addStringSubmenu(@"Extraction", @[@[@"Minimum residual", @"minres"],
            @[@"Maximum likelihood", @"ml"], @[@"Principal axis", @"pa"]],
            @selector(setExtractionFromMenu:), state->specification.extraction);
        addStringSubmenu(@"Rotation", @[@[@"Oblimin", @"oblimin"], @[@"Varimax", @"varimax"],
            @[@"Quartimax", @"quartimax"], @[@"Promax", @"promax"], @[@"None", @"none"]],
            @selector(setRotationFromMenu:), state->specification.rotation);
        NSMenuItem *standardize = [[NSMenuItem alloc] initWithTitle:@"Standardize variables"
            action:@selector(setDimensionScaleFromControl:) keyEquivalent:@""];
        [standardize setTarget:self];
        [standardize setState:state->specification.dimensionalityScale
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:standardize];
        if (state->result.imputationCount > 1) {
            NSMenuItem *imputation = [[NSMenuItem alloc]
                initWithTitle:@"Imputation" action:nil keyEquivalent:@""];
            NSMenu *imputationMenu = [[NSMenu alloc] initWithTitle:@"Imputation"];
            for (NSInteger index = 1; index <= state->result.imputationCount; ++index) {
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:[NSString stringWithFormat:@"Imputation %ld of %d",
                        (long)index, state->result.imputationCount]
                    action:@selector(setDimensionImputationFromMenu:)
                    keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:@(index)];
                [item setState:_dimensionImputation == index
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [imputationMenu addItem:item];
            }
            [imputation setSubmenu:imputationMenu];
            [menu addItem:imputation];
        }
        NSMenuItem *plotsItem = [[NSMenuItem alloc]
            initWithTitle:@"Plots" action:nil keyEquivalent:@""];
        NSMenu *plotsMenu = [[NSMenu alloc] initWithTitle:@"Plots"];
        auto addPlot = [&](NSString *title, ScaleAnalysisChildKind kind) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title
                action:@selector(openDimensionalityPlotFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setTag:static_cast<NSInteger>(kind)];
            [plotsMenu addItem:item];
        };
        addPlot(@"Scree / parallel analysis", ScaleAnalysisChildKind::ScreePlot);
        addPlot(@"Factor loadings", ScaleAnalysisChildKind::LoadingPlot);
        addPlot(@"Factor biplot", ScaleAnalysisChildKind::Biplot);
        [plotsItem setSubmenu:plotsMenu];
        [menu addItem:plotsItem];
        NSMenuItem *saveScores = [[NSMenuItem alloc]
            initWithTitle:@"Save factor/component scores…"
            action:@selector(saveDimensionalityScores:) keyEquivalent:@""];
        [saveScores setTarget:self];
        const auto scorePresentation = BuildScaleDimensionalityPresentation(
            state->result, (int)_dimensionImputation);
        [saveScores setEnabled:!scorePresentation.scores.empty() &&
            !scorePresentation.scores.front().values.empty()];
        [menu addItem:saveScores];
        NSMenuItem *explain = [[NSMenuItem alloc]
            initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
            action:nil keyEquivalent:@""];
        NSMenu *explainMenu = [[NSMenu alloc] initWithTitle:[explain title]];
        for (NSString *statistic in @[ @"Eigenvalue", @"Parallel eigenvalue",
                @"Proportion of variance", @"Cumulative variance", @"Loading",
                @"Communality", @"Uniqueness" ]) {
            NSMenuItem *entry = [[NSMenuItem alloc] initWithTitle:statistic
                action:@selector(explainDimensionalityStatistic:) keyEquivalent:@""];
            [entry setTarget:self]; [entry setRepresentedObject:statistic];
            [explainMenu addItem:entry];
        }
        [explain setSubmenu:explainMenu]; [menu addItem:explain];
        if (_kind == ScaleAnalysisChildKind::Dimensionality) {
            for (NSMenuItem *item in [[menu itemArray] copy]) { [menu removeItem:item]; [parentMenu addItem:item]; }
        } else {
            NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Dimensionality" action:nil keyEquivalent:@""];
            root.submenu = menu; [parentMenu addItem:root];
        }
    }
    if (correlationResult || dimensionalityResult) [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *info = [[NSMenuItem alloc] initWithTitle:@"Analysis information…"
        action:@selector(showAnalysisInformation:) keyEquivalent:@""];
    [info setTarget:self]; [menu addItem:info];
    [menu addItem:[NSMenuItem separatorItem]];
    NSString *title = ToNSString(ScaleAnalysisChildWindowTitle(
        _kind, GroupIsMultipleImputation(state->group)));
    NSString *baseName = [[title lowercaseString]
        stringByReplacingOccurrencesOfString:@" " withString:@"-"];
    NSMenuItem *exports = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    const auto tables = rlispstat::core::ScaleAnalysisPublicationTables(*state, (int)_kind, (int)_dimensionImputation);
    const auto separateTables = _kind == ScaleAnalysisChildKind::Dimensionality
        ? rlispstat::core::ScaleAnalysisPublicationTables(*state, (int)_kind,
            (int)_dimensionImputation, rlispstat::core::ScaleAnalysisGlobalPresentation::CompactTable,
            rlispstat::core::ScaleAnalysisDimensionalityPresentation::SeparateTables)
        : std::vector<rlispstat::core::PublicationTableSpec>{};
    AddStandardTableVisualExportItems(exportMenu, _reportView, title, baseName,
        [_reportView snapshotTabDelimitedText], tables.empty() ? nullptr : &tables.front(),
        tables.empty() ? nullptr : &tables, true, true, nullptr,
        separateTables.size() == 2 ? &separateTables : nullptr);
    AddRCodeExportItems(exportMenu, "output", _analysisId, true);
    AddSnapshotAlbumContextItems(menu);
    [exports setSubmenu:exportMenu]; [menu addItem:exports];
    return menu;
}

- (void)showItemMenuForIndex:(NSInteger)index atPoint:(NSPoint)point inView:(NSView *)view
{
    auto parent = g_scaleAnalysisControllers.find(_analysisId);
    if (parent == g_scaleAnalysisControllers.end()) return;
    [parent->second showItemMenuForIndex:index atPoint:point inView:view];
}

- (CorrelationMatrixState)scaleCorrelationMatrixState
{
    CorrelationMatrixState correlation;
    ScaleAnalysisState *state = [self state];
    if (!state) return correlation;
    correlation.id = state->id + "_inter_item_correlations";
    correlation.group = state->group;
    correlation.title = ScaleAnalysisChildWindowTitle(
        ScaleAnalysisChildKind::InterItemCorrelations,
        state->result.imputationCount > 1);
    correlation.variables = state->result.correlations.variables;
    correlation.method = state->result.correlations.basis;
    correlation.missingMode = "pairwise";
    correlation.precomputed = true;
    correlation.multipleImputation = state->result.imputationCount > 1;
    correlation.imputationCount = state->result.imputationCount;
    if (correlation.multipleImputation && correlation.method == "pearson")
        correlation.poolingMethod = "mice::pool.scalar";
    correlation.note = state->result.correlations.status;
    correlation.cells = rlispstat::core::ScaleCorrelationCells(state->result);
    correlation.showP = _showCorrelationStars;
    correlation.showPValue = _showCorrelationPValues;
    correlation.showN = _showCorrelationN;
    correlation.seed = state->seed;
    correlation.hasSeed = state->hasSeed;
    return correlation;
}

- (void)toggleCorrelationStars:(id)sender
{
    (void)sender;
    _showCorrelationStars = !_showCorrelationStars;
    [self refresh];
}

- (void)toggleCorrelationPValues:(id)sender
{
    (void)sender;
    _showCorrelationPValues = !_showCorrelationPValues;
    [self refresh];
}

- (void)toggleCorrelationN:(id)sender
{
    (void)sender;
    _showCorrelationN = !_showCorrelationN;
    [self refresh];
}

- (NSArray<NSNumber *> *)scaleCorrelationCoordinatesFromSender:(id)sender
{
    id represented = [sender representedObject];
    if (![represented isKindOfClass:[NSArray class]] || [represented count] != 2)
        return nil;
    return represented;
}

- (void)openCorrelationCellAtRow:(NSInteger)row column:(NSInteger)column
{
    CorrelationMatrixState correlation = [self scaleCorrelationMatrixState];
    if (!correlation.hasSeed) return;
    OpenCorrelationScatterplot(correlation, (int)row, (int)column);
}

- (void)showCorrelationCellMenuForRow:(NSInteger)row column:(NSInteger)column
    atPoint:(NSPoint)point inView:(NSView *)view
{
    ScaleAnalysisState *state = [self state];
    if (!state) return;
    CorrelationCellMenuState menuState = BuildCorrelationCellMenuState(
        (int)row, (int)column);
    NSArray<NSNumber *> *coordinates = @[@(row), @(column)];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    NSMenuItem *open = [[NSMenuItem alloc]
        initWithTitle:ToNSString(menuState.openScatterplotTitle)
        action:@selector(openScaleCorrelationCellScatterplot:) keyEquivalent:@""];
    [open setTarget:self]; [open setRepresentedObject:coordinates];
    [open setEnabled:menuState.canOpenScatterplot && state->hasSeed];
    [menu addItem:open]; [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *copyValue = [[NSMenuItem alloc]
        initWithTitle:@"Copy correlation"
        action:@selector(copyScaleCorrelationCellValue:) keyEquivalent:@""];
    [copyValue setTarget:self]; [copyValue setRepresentedObject:coordinates];
    [menu addItem:copyValue];
    NSMenuItem *copyDetail = [[NSMenuItem alloc]
        initWithTitle:@"Copy correlation and details"
        action:@selector(copyScaleCorrelationCellDetail:) keyEquivalent:@""];
    [copyDetail setTarget:self]; [copyDetail setRepresentedObject:coordinates];
    [menu addItem:copyDetail]; [menu addItem:[NSMenuItem separatorItem]];

    NSString *statistic = state->result.correlations.basis == "polychoric"
        ? @"Polychoric correlation" : state->result.correlations.basis == "mixed"
        ? @"Mixed correlation" : @"Pearson r";
    NSMenuItem *explain = [[NSMenuItem alloc]
        initWithTitle:ToNSString(
            rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
        action:@selector(explainCorrelationStatistic:) keyEquivalent:@""];
    [explain setTarget:self]; [explain setRepresentedObject:statistic];
    [menu addItem:explain];
    AddSnapshotAlbumContextItems(menu);
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)openScaleCorrelationCellScatterplot:(id)sender
{
    NSArray<NSNumber *> *coordinates = [self scaleCorrelationCoordinatesFromSender:sender];
    if (!coordinates) return;
    [self openCorrelationCellAtRow:[coordinates[0] integerValue]
        column:[coordinates[1] integerValue]];
}

- (const CorrelationCellResult *)scaleCorrelationCellAtCoordinates:(NSArray<NSNumber *> *)coordinates
    storage:(std::vector<CorrelationCellResult> &)storage
{
    ScaleAnalysisState *state = [self state];
    if (!state || !coordinates) return nullptr;
    storage = rlispstat::core::ScaleCorrelationCells(state->result);
    return rlispstat::core::CorrelationCellAt(storage,
        state->result.correlations.variables.size(),
        (int)[coordinates[0] integerValue], (int)[coordinates[1] integerValue]);
}

- (void)copyScaleCorrelationCellValue:(id)sender
{
    NSArray<NSNumber *> *coordinates = [self scaleCorrelationCoordinatesFromSender:sender];
    std::vector<CorrelationCellResult> storage;
    const CorrelationCellResult *cell = [self scaleCorrelationCellAtCoordinates:coordinates
        storage:storage];
    if (!cell) return;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString(CorrelationCellLabel(cell, false, false))
        forType:NSPasteboardTypeString];
}

- (void)copyScaleCorrelationCellDetail:(id)sender
{
    ScaleAnalysisState *state = [self state];
    NSArray<NSNumber *> *coordinates = [self scaleCorrelationCoordinatesFromSender:sender];
    std::vector<CorrelationCellResult> storage;
    const CorrelationCellResult *cell = [self scaleCorrelationCellAtCoordinates:coordinates
        storage:storage];
    if (!state || !cell) return;
    std::ostringstream text;
    text << cell->yVariable << " x " << cell->xVariable << "\n"
         << state->result.correlations.basis << " = "
         << CorrelationCellLabel(cell, false, false);
    if (cell->n > 0) text << "; N per imputation = " << cell->n;
    if (!state->result.correlations.status.empty())
        text << "\n" << state->result.correlations.status;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString(text.str()) forType:NSPasteboardTypeString];
}

- (void)explainCorrelationStatistic:(id)sender
{
    ScaleAnalysisState *state = [self state];
    NSString *statistic = [sender representedObject];
    if (!state || ![statistic isKindOfClass:[NSString class]]) return;
    const bool mi = state->result.imputationCount > 1;
    const bool pooledPearson = mi && state->result.correlations.basis == "pearson";
    ShowAnalysisStatisticExplanationOnMain(
        std::string([statistic UTF8String]), "correlation",
        state->result.correlations.basis, std::string(), mi,
        pooledPearson ? "mice::pool.scalar" : std::string());
}

- (void)focusDimensionComponent:(NSInteger)component variable:(NSString *)variable
{
    auto children = g_scaleAnalysisDerivedControllers.find(_analysisId);
    if (children == g_scaleAnalysisDerivedControllers.end()) return;
    auto table = children->second.find((int)ScaleAnalysisChildKind::Dimensionality);
    if (table == children->second.end()) return;
    ScaleAnalysisDerivedView *view = [table->second valueForKey:@"reportView"];
    [view focusComponent:component variable:variable];
}

