{
    ShowWorkbenchMessageOnMain(@"Explain plot", ToNSString(rlispstat::core::ScaleAnalysisPlotExplanation(_kind)));
}

- (void)explainScaleStatistic:(id)sender
{
    ScaleAnalysisState *state = [self state]; if (!state) return;
    ShowAnalysisStatisticExplanationOnMain([[sender representedObject] UTF8String],
        _kind == ScaleAnalysisChildKind::ScaleScores ? "scale_scores" : "scale",
        state->specification.scoreMethod, "", state->result.imputationCount > 1);
}

- (void)openScoreHistogram:(id)sender
{
    ScaleAnalysisState *state = [self state];
    if (!state || !ScaleAnalysisResultMatchesSpecification(state->specification, state->result)) return;
    auto task = rlispstat::core::ScaleTotalScoreSaveTask(state->id, state->group,
        state->specification.scoreMethod, state->specification.revision, state->specification.fingerprint);
    task.secondary = "histogram";
    { std::lock_guard<std::mutex> lock(g_mutex); g_pendingMissingDataTasks.push_back(task); }
    NotifyMainRTaskAvailable();
}

- (void)explainDimensionalityStatistic:(id)sender
{
    ScaleAnalysisState *state = [self state];
    NSString *statistic = [sender representedObject];
    if (!state || ![statistic isKindOfClass:[NSString class]]) return;
    ShowAnalysisStatisticExplanationOnMain(
        std::string([statistic UTF8String]), "dimensionality",
        state->specification.extraction + " with " +
            state->specification.rotation + " rotation",
        std::string(), state->result.imputationCount > 1);
}

