- (void)setDimensionMethodFromMenu:(id)sender
{
    ScaleAnalysisState *state = [self state]; if (!state) return;
    ScaleAnalysisSpecification candidate = state->specification;
    candidate.dimensionalityMethod = sender == _dimensionMethodPopup
        ? ([_dimensionMethodPopup indexOfSelectedItem] == 0 ? "pca" : "factor")
        : [[[sender representedObject] description] UTF8String];
    const int maximum = std::max(1, static_cast<int>(candidate.items.size()) -
        (candidate.dimensionalityMethod == "pca" ? 0 : 1));
    candidate.factorCount = std::min(candidate.factorCount, maximum);
    auto found = g_scaleAnalysisControllers.find(_analysisId);
    if (found != g_scaleAnalysisControllers.end()) [found->second applyCandidate:std::move(candidate)];
}

