- (void)setDimensionImputationFromMenu:(id)sender
{
    ScaleAnalysisState *state = [self state]; if (!state) return;
    _dimensionImputation = std::max<NSInteger>(1,
        std::min<NSInteger>([[sender representedObject] integerValue],
            std::max(1, state->result.imputationCount)));
    [self refresh];
}

- (void)openDimensionalityPlotFromMenu:(id)sender
{
    auto parent = g_scaleAnalysisControllers.find(_analysisId);
    if (parent == g_scaleAnalysisControllers.end()) return;
    [parent->second openDerivedResult:sender];
    const auto kind = static_cast<ScaleAnalysisChildKind>([sender tag]);
    auto children = g_scaleAnalysisDerivedControllers.find(_analysisId);
    if (children == g_scaleAnalysisDerivedControllers.end()) return;
    auto child = children->second.find(static_cast<int>(kind));
    if (child == children->second.end()) return;
    child->second->_dimensionImputation = _dimensionImputation;
    [child->second refresh];
}

- (void)saveDimensionalityScores:(id)sender
{
    (void)sender;
    ScaleAnalysisState *state = [self state];
    if (!state || !ScaleAnalysisResultMatchesSpecification(
            state->specification, state->result)) return;
    const auto displayed = BuildScaleDimensionalityPresentation(
        state->result, (int)_dimensionImputation);
    const NSInteger available = displayed.scores.empty() ? 0 :
        static_cast<NSInteger>(displayed.scores.front().values.size());
    if (available < 1) {
        [_statusField setStringValue:@"No factor/component scores are available to save."];
        return;
    }
    const bool factor = state->specification.dimensionalityMethod != "pca";
    const NSInteger requested = PromptForDimensionalityScoreCount(
        _window, available, factor);
    if (requested < 1) return;
    MainRDimensionalityScoreSaveTask task;
    task.requestId = std::string([[[NSUUID UUID] UUIDString] UTF8String]);
    task.sourceKind = "scale_analysis";
    task.analysisId = state->id;
    task.group = state->group;
    task.componentCount = (int)requested;
    if (!QueueDimensionalityScoreSaveMainRTask(task)) {
        [_statusField setStringValue:@"Saving scores is already in progress…"];
        return;
    }
    [_statusField setStringValue:@"Saving scores across imputations and synchronizing the data sheet…"];
}

- (void)showScoreSaveStatus:(NSString *)status
{
    [_statusField setStringValue:status ?: @""];
}

- (void)showAnalysisInformation:(id)sender
{
    (void)sender; ScaleAnalysisState *state = [self state]; if (!state) return;
    std::ostringstream message;
    message << "Source Scale Analysis revision: " << state->specification.revision
            << "\nSpecification fingerprint: " << state->specification.fingerprint
            << "\nBackend: " << state->result.backend
            << "\nImputations: " << state->result.imputationCount
            << "\n\n" << state->result.provenance;
    ShowWorkbenchMessageOnMain(@"Scale Analysis information", ToNSString(message.str()));
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    [_reportView detachNativePlot];
    auto found = g_scaleAnalysisDerivedControllers.find(_analysisId);
    if (found != g_scaleAnalysisDerivedControllers.end()) {
        found->second.erase(static_cast<int>(_kind));
        if (found->second.empty()) g_scaleAnalysisDerivedControllers.erase(found);
    }
}

@end

@implementation ScaleItemSearchField

- (void)keyDown:(NSEvent *)event
{
    switch (event.keyCode) {
        case 36: // Return
        case 76: // Numeric keypad Enter
            [self.selectorController addSelectedItemFromSelector:self];
            return;
        case 53: // Escape
            [self.selectorController closeItemSelector:self];
            return;
        case 125: // Down arrow
            [self.selectorController moveItemSelectorSelection:1];
            return;
        case 126: // Up arrow
            [self.selectorController moveItemSelectorSelection:-1];
            return;
        default:
            [super keyDown:event];
            return;
    }
}

@end

@implementation ScaleItemSelectorTableView

- (void)keyDown:(NSEvent *)event
{
    switch (event.keyCode) {
        case 36: // Return
        case 76: // Numeric keypad Enter
            [self.selectorController addSelectedItemFromSelector:self];
            return;
        case 53: // Escape
            [self.selectorController closeItemSelector:self];
            return;
        default:
            [super keyDown:event];
            return;
    }
}

@end

@interface ScaleAnalysisView : NSView {
    CGFloat _itemRowsOrigin;
    CGFloat _summaryOrigin;
    BOOL _hasSummary;
}
@property(nonatomic, assign) ScaleAnalysisWindowController *controller;
- (instancetype)initWithController:(ScaleAnalysisWindowController *)controller;
- (NSSize)preferredContentSize;
- (NSString *)snapshotTabDelimitedText;
@end

@implementation ScaleAnalysisView

- (instancetype)initWithController:(ScaleAnalysisWindowController *)controller
{
    if ((self = [super initWithFrame:NSMakeRect(0, 0, 900, 340)])) {
        _controller = controller;
    }
    return self;
}

- (BOOL)isFlipped { return YES; }

- (NSSize)preferredContentSize
{
    ScaleAnalysisState *state = [_controller state];
    const std::size_t count = state ? state->specification.items.size() : 0U;
    const auto layout = rlispstat::core::BuildScaleAnalysisWindowLayout(count, 12);
    // This is the document size, not the window viewport.  The window is
    // capped separately by BuildScaleAnalysisWindowLayout().  Keeping the
    // complete item height here gives NSScrollView a real vertical range
    // instead of silently clipping the last items and the inline Add item row.
    const CGFloat overviewHeight = state && state->specification.showOverview &&
        !state->result.scaleSummary.numberOfItems.empty() ? 195.0 : 0.0;
    const CGFloat documentHeight = 147.0 + overviewHeight +
        24.0 * static_cast<CGFloat>(count) + 72.0;
    return NSMakeSize(layout.preferredWidth, std::max(250.0, documentHeight));
}

- (NSString *)snapshotTabDelimitedText
{
    ScaleAnalysisState *state = [_controller state];
    if (!state) return @"";
    std::ostringstream out;
    out << "Scale Analysis\n"
        << "Dataset\t" << state->group << '\n'
        << "Correlation basis\t" << state->specification.correlationBasis << '\n'
        << "Score method\t" << state->specification.scoreMethod << '\n';
    if (!state->status.empty()) out << "Status\t" << state->status << '\n';
    const auto &summary = state->result.scaleSummary;
    if (!summary.numberOfItems.empty()) {
        out << "\nScale summary\n"
            << "Items\tN used\tMissing in original (%)\tScale mean\tScale SD"
               "\tMean inter-item r\tAlpha\tStandardized alpha\tOmega total\n"
            << summary.numberOfItems << '\t' << summary.nUsed << '\t'
            << summary.missingPercent << '\t' << summary.scaleMean << '\t'
            << summary.scaleSd << '\t' << summary.meanInterItemCorrelation << '\t'
            << summary.alpha << '\t' << summary.standardizedAlpha << '\t'
            << summary.omegaTotal << '\n';
    }
    out << "\nScale items\n"
        << "Item\tType\tDirection\tTheoretical range\tMean\tSD\tMissing (%)"
           "\tItem-rest correlation\tAlpha if deleted\n";
    for (const auto &item : state->specification.items) {
        auto result = std::find_if(state->result.items.begin(), state->result.items.end(),
            [&](const rlispstat::core::ScaleItemResultRow &candidate) {
                return candidate.variable == item.variable;
            });
        std::string range = "—";
        if (item.hasScoringRange) {
            std::ostringstream value;
            value << item.scoringMinimum << "–" << item.scoringMaximum;
            range = value.str();
        }
        out << item.variable << '\t'
            << rlispstat::core::ScaleItemTypeDisplayName(item.type) << '\t'
            << (item.reversed ? "Reversed" : "Forward") << '\t' << range;
        if (result != state->result.items.end()) {
            out << '\t' << result->mean << '\t' << result->sd << '\t'
                << result->missingPercent << '\t' << result->itemRestCorrelation
                << '\t' << result->alphaIfDeleted;
        } else {
            out << "\t—\t—\t—\t—\t—";
        }
        out << '\n';
    }
    return ToNSString(out.str());
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor textBackgroundColor] setFill];
    NSRectFill(self.bounds);
    ScaleAnalysisState *state = [_controller state];
    if (!state) return;

    NSDictionary *head = @{NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
                           NSForegroundColorAttributeName: [NSColor labelColor]};
    NSDictionary *body = @{NSFontAttributeName: [NSFont systemFontOfSize:12],
                           NSForegroundColorAttributeName: [NSColor labelColor]};
    NSDictionary *muted = @{NSFontAttributeName: [NSFont systemFontOfSize:11],
                            NSForegroundColorAttributeName: [NSColor secondaryLabelColor]};
    NSDictionary *link = @{NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
                           NSForegroundColorAttributeName: [NSColor linkColor]};
    NSDictionary *section = @{NSFontAttributeName: [NSFont systemFontOfSize:14 weight:NSFontWeightSemibold],
                              NSForegroundColorAttributeName: [NSColor labelColor]};
    auto valueText = [](const std::string &value) -> NSString * {
        return value.empty() ? @"—" : ToNSString(value);
    };
    auto separator = [&](CGFloat y) {
        [[NSColor separatorColor] setStroke];
        NSBezierPath *rule = [NSBezierPath bezierPath];
        [rule moveToPoint:NSMakePoint(14, y)];
        [rule lineToPoint:NSMakePoint(self.bounds.size.width - 14, y)];
        [rule stroke];
    };
    auto sectionTitle = [&](NSString *title, CGFloat &y) {
        [title drawAtPoint:NSMakePoint(16, y) withAttributes:section]; y += 27;
    };
    CGFloat y = 8;

    _hasSummary = state->specification.showOverview &&
        !state->result.scaleSummary.numberOfItems.empty();
    if (_hasSummary) {
        sectionTitle(@"Scale summary", y);
        _summaryOrigin = y;
        const auto fields = rlispstat::core::ScaleAnalysisSummaryFields(state->result);
        const CGFloat cellWidth = (self.bounds.size.width - 32) / 3;
        for (std::size_t index = 0; index < fields.size(); ++index) {
            const CGFloat left = 16 + (index % 3) * cellWidth;
            const CGFloat top = y + (index / 3) * 52;
            [ToNSString(fields[index].first) drawAtPoint:NSMakePoint(left, top) withAttributes:head];
            [valueText(fields[index].second) drawAtPoint:NSMakePoint(left, top + 22) withAttributes:body];
        }
        y += 156;
        separator(y); y += 12;
    }

    sectionTitle(state->specification.showItemAnalysis ? @"Item analysis" : @"Scale items", y);
    const CGFloat x[] = {16, 184, 270, 360, 445, 515, 580, 670, 790};
    const NSString *labels[] = {@"Item", @"Type", @"Direction", @"Range", @"Mean", @"SD", @"Missing %", @"Item-rest r", @"Alpha if deleted"};
    const NSInteger visibleColumns = state->specification.showItemAnalysis ? 9 : 4;
    for (NSInteger index = 0; index < visibleColumns; ++index)
        [labels[index] drawAtPoint:NSMakePoint(x[index], y) withAttributes:head];
    separator(y + 21); y += 28; _itemRowsOrigin = y;
    const auto &specItems = state->specification.items;
    for (std::size_t index = 0; index < specItems.size(); ++index, y += 24) {
        const ScaleItemSpecification &item = specItems[index];
        if (index % 2U == 1U) {
            [[NSColor colorWithCalibratedWhite:0.5 alpha:0.055] setFill];
            NSRectFill(NSMakeRect(12, y - 3, self.bounds.size.width - 24, 23));
        }
        NSString *range = item.hasScoringRange
            ? [NSString stringWithFormat:@"%.3g–%.3g", item.scoringMinimum, item.scoringMaximum]
            : @"—";
        std::string mean = "—", sd = "—", missing = "—", itemRest = "—", alphaDeleted = "—";
        auto row = std::find_if(state->result.items.begin(), state->result.items.end(),
            [&](const rlispstat::core::ScaleItemResultRow &candidate) {
                return candidate.variable == item.variable;
            });
        if (row != state->result.items.end()) {
            mean = row->mean.empty() ? "—" : row->mean;
            sd = row->sd.empty() ? "—" : row->sd;
            missing = row->missingPercent.empty() ? "—" : row->missingPercent + "%";
            itemRest = row->itemRestCorrelation.empty() ? "—" : row->itemRestCorrelation;
            alphaDeleted = row->alphaIfDeleted.empty() ? "—" : row->alphaIfDeleted;
        }
        [ToNSString(item.variable) drawAtPoint:NSMakePoint(x[0], y) withAttributes:body];
        [ToNSString(rlispstat::core::ScaleItemTypeDisplayName(item.type)) drawAtPoint:NSMakePoint(x[1], y) withAttributes:body];
        [(item.reversed ? @"Reversed" : @"Forward") drawAtPoint:NSMakePoint(x[2], y) withAttributes:body];
        [range drawAtPoint:NSMakePoint(x[3], y) withAttributes:body];
        if (state->specification.showItemAnalysis) {
            [ToNSString(mean) drawAtPoint:NSMakePoint(x[4], y) withAttributes:body];
            [ToNSString(sd) drawAtPoint:NSMakePoint(x[5], y) withAttributes:body];
            [ToNSString(missing) drawAtPoint:NSMakePoint(x[6], y) withAttributes:body];
            [ToNSString(itemRest) drawAtPoint:NSMakePoint(x[7], y) withAttributes:body];
            [ToNSString(alphaDeleted) drawAtPoint:NSMakePoint(x[8], y) withAttributes:body];
        }
    }
    [@"+ Add item" drawAtPoint:NSMakePoint(16, y + 1) withAttributes:link];
    y += 31;
    separator(y);
    y += 11;
    if (specItems.empty()) {
        [@"No items selected. Add numeric or ordinal variables to define the scale."
            drawAtPoint:NSMakePoint(16, y) withAttributes:muted];
    } else if (state->rFitPending) {
        [@"Fitting the exact current scale specification in R…"
            drawAtPoint:NSMakePoint(16, y) withAttributes:muted];
    } else {
        if (!state->result.summary.empty()) {
            [ToNSString(state->result.summary) drawInRect:NSMakeRect(16, y,
                self.bounds.size.width - 32, 38) withAttributes:head]; y += 42;
        }
    }

    // Detailed reliability, correlation, dimensionality, score and plot
    // presentations live in revision-bound child windows.  Keeping the main
    // report compact also prevents it from becoming a vertically stacked
    // dashboard as analyses are requested.
    return;

    if (state->specification.showReliability &&
        !state->result.scaleSummary.alpha.empty()) {
        sectionTitle(@"Reliability", y);
        const auto &summary = state->result.scaleSummary;
        NSString *line = [NSString stringWithFormat:
            @"Alpha: %@     Standardized alpha: %@     Omega total: %@",
            valueText(summary.alpha), valueText(summary.standardizedAlpha),
            valueText(summary.omegaTotal)];
        [line drawAtPoint:NSMakePoint(16, y) withAttributes:body]; y += 22;
        [valueText(summary.reliabilityStatus) drawInRect:NSMakeRect(16, y,
            self.bounds.size.width - 32, 34) withAttributes:muted]; y += 36;
        if (!state->result.reliabilityByImputation.empty()) {
            const CGFloat columns[] = {16, 145, 275, 440};
            const NSString *heads[] = {@"Imputation", @"Alpha", @"Standardized alpha", @"Omega total"};
            for (NSInteger column = 0; column < 4; ++column)
                [heads[column] drawAtPoint:NSMakePoint(columns[column], y) withAttributes:head];
            y += 21;
            for (const auto &row : state->result.reliabilityByImputation) {
                [valueText(row.imputation) drawAtPoint:NSMakePoint(columns[0], y) withAttributes:body];
                [valueText(row.alpha) drawAtPoint:NSMakePoint(columns[1], y) withAttributes:body];
                [valueText(row.standardizedAlpha) drawAtPoint:NSMakePoint(columns[2], y) withAttributes:body];
                [valueText(row.omegaTotal) drawAtPoint:NSMakePoint(columns[3], y) withAttributes:body];
                y += 20;
            }
        }
        separator(y); y += 12;
    }

    if (state->specification.showCorrelations) {
        sectionTitle(@"Inter-item correlations", y);
        NSString *note = [NSString stringWithFormat:@"Correlation basis: %@ · %@",
            valueText(state->result.correlations.basis), valueText(state->result.correlations.status)];
        [note drawAtPoint:NSMakePoint(16, y) withAttributes:muted]; y += 24;
        const auto &correlations = state->result.correlations;
        const std::size_t count = correlations.variables.size();
        if (count && correlations.values.size() == count * count) {
            [@"Item" drawAtPoint:NSMakePoint(16, y) withAttributes:head];
            for (std::size_t column = 0; column < count; ++column)
                [ToNSString(correlations.variables[column]) drawAtPoint:
                    NSMakePoint(145 + 82 * column, y) withAttributes:head];
            y += 22;
            for (std::size_t row = 0; row < count; ++row) {
                [ToNSString(correlations.variables[row]) drawAtPoint:NSMakePoint(16, y) withAttributes:body];
                for (std::size_t column = 0; column < count; ++column)
                    [valueText(correlations.values[row * count + column]) drawAtPoint:
                        NSMakePoint(145 + 82 * column, y) withAttributes:body];
                y += 22;
            }
        }
        separator(y); y += 12;
    }

    if (state->specification.showDimensionality) {
        sectionTitle(state->specification.dimensionalityMethod == "pca"
            ? @"Dimensionality / principal components"
            : @"Dimensionality / exploratory factor analysis", y);
        NSString *note = [NSString stringWithFormat:@"Status: %@%@",
            valueText(state->result.dimensionality.status),
            state->result.dimensionality.suggestedFactors.empty() ? @"" :
                [NSString stringWithFormat:@" · Parallel analysis: %@",
                    valueText(state->result.dimensionality.suggestedFactors)]];
        [note drawInRect:NSMakeRect(16, y, self.bounds.size.width - 32, 36) withAttributes:muted]; y += 38;
        if (!state->result.dimensionality.loadings.empty()) {
            [@"Item" drawAtPoint:NSMakePoint(16, y) withAttributes:head];
            for (std::size_t factor = 0; factor < state->result.dimensionality.factorNames.size(); ++factor)
                [ToNSString(state->result.dimensionality.factorNames[factor]) drawAtPoint:
                    NSMakePoint(220 + 86 * factor, y) withAttributes:head];
            CGFloat tail = 220 + 86 * state->result.dimensionality.factorNames.size();
            [@"h²" drawAtPoint:NSMakePoint(tail, y) withAttributes:head];
            [@"u²" drawAtPoint:NSMakePoint(tail + 80, y) withAttributes:head]; y += 22;
            for (const auto &row : state->result.dimensionality.loadings) {
                [valueText(row.item) drawAtPoint:NSMakePoint(16, y) withAttributes:body];
                for (std::size_t factor = 0; factor < row.loadings.size(); ++factor)
                    [valueText(row.loadings[factor]) drawAtPoint:NSMakePoint(220 + 86 * factor, y) withAttributes:body];
                [valueText(row.communality) drawAtPoint:NSMakePoint(tail, y) withAttributes:body];
                [valueText(row.uniqueness) drawAtPoint:NSMakePoint(tail + 80, y) withAttributes:body]; y += 22;
            }
        }
        separator(y); y += 12;
    }

    if (state->specification.showScoreDistribution) {
        sectionTitle(@"Scale-score distribution", y);
        const auto &score = state->result.scores;
        NSString *line = [NSString stringWithFormat:
            state->result.imputationCount > 1
                ? @"Method: %@     N per imputation: %@     Mean: %@     SD: %@     Minimum: %@     Maximum: %@"
                : @"Method: %@     Valid N: %@     Mean: %@     SD: %@     Minimum: %@     Maximum: %@",
            valueText(score.method), valueText(score.validN), valueText(score.mean),
            valueText(score.sd), valueText(score.minimum), valueText(score.maximum)];
        [line drawAtPoint:NSMakePoint(16, y) withAttributes:body]; y += 23;
        [valueText(score.status) drawInRect:NSMakeRect(16, y, self.bounds.size.width - 32, 32)
            withAttributes:muted]; y += 38; separator(y); y += 12;
    }

    auto drawBars = [&](NSString *title, const std::vector<std::pair<std::string, std::string>> &values) {
        sectionTitle(title, y);
        double maximum = 0.0;
        for (const auto &entry : values) maximum = std::max(maximum, std::fabs(std::strtod(entry.second.c_str(), nullptr)));
        maximum = maximum > 0.0 ? maximum : 1.0;
        for (const auto &entry : values) {
            [valueText(entry.first) drawAtPoint:NSMakePoint(16, y) withAttributes:body];
            const double numeric = std::strtod(entry.second.c_str(), nullptr);
            const CGFloat width = std::min<CGFloat>(360.0, 360.0 * std::fabs(numeric) / maximum);
            [[NSColor colorWithCalibratedRed:0.10 green:0.45 blue:0.88 alpha:0.68] setFill];
            NSRectFill(NSMakeRect(220, y + 2, width, 12));
            [valueText(entry.second) drawAtPoint:NSMakePoint(590, y) withAttributes:body]; y += 20;
        }
        separator(y); y += 12;
    };
    auto seriesForKind = [&](const std::string &kind) {
        std::vector<const rlispstat::core::ScalePlotSeriesResult *> matches;
        for (const auto &series : state->result.plotSeries) {
            if (series.kind == kind && series.labels.size() == series.values.size())
                matches.push_back(&series);
        }
        return matches;
    };
    auto drawLineSeries = [&](NSString *title,
                              const std::vector<const rlispstat::core::ScalePlotSeriesResult *> &series) {
        if (series.empty()) return;
        double minimum = std::numeric_limits<double>::infinity();
        double maximum = -std::numeric_limits<double>::infinity();
        std::size_t pointCount = 0;
        for (const auto *entry : series) {
            pointCount = std::max(pointCount, entry->values.size());
            for (const auto &value : entry->values) {
                const double number = std::strtod(value.c_str(), nullptr);
                if (std::isfinite(number)) {
                    minimum = std::min(minimum, number);
                    maximum = std::max(maximum, number);
                }
            }
        }
        if (!std::isfinite(minimum) || !std::isfinite(maximum) || pointCount == 0) return;
        if (minimum == maximum) { minimum -= 0.5; maximum += 0.5; }
        sectionTitle(title, y);
        const CGFloat left = 52.0;
        const CGFloat width = std::max<CGFloat>(240.0, self.bounds.size.width - 280.0);
        const CGFloat height = 95.0;
        [[NSColor separatorColor] setStroke];
        NSBezierPath *axes = [NSBezierPath bezierPath];
        [axes moveToPoint:NSMakePoint(left, y)];
        [axes lineToPoint:NSMakePoint(left, y + height)];
        [axes lineToPoint:NSMakePoint(left + width, y + height)];
        [axes stroke];
        NSArray<NSColor *> *palette = @[
            [NSColor colorWithCalibratedRed:0.10 green:0.45 blue:0.88 alpha:0.9],
            [NSColor colorWithCalibratedRed:0.93 green:0.30 blue:0.25 alpha:0.9],
            [NSColor colorWithCalibratedRed:0.16 green:0.66 blue:0.48 alpha:0.9],
            [NSColor colorWithCalibratedRed:0.63 green:0.37 blue:0.82 alpha:0.9],
            [NSColor colorWithCalibratedRed:0.92 green:0.58 blue:0.12 alpha:0.9]
        ];
        for (std::size_t seriesIndex = 0; seriesIndex < series.size(); ++seriesIndex) {
            const auto *entry = series[seriesIndex];
            NSColor *color = [palette objectAtIndex:seriesIndex % [palette count]];
            NSBezierPath *path = [NSBezierPath bezierPath];
            BOOL started = NO;
            for (std::size_t index = 0; index < entry->values.size(); ++index) {
                const double number = std::strtod(entry->values[index].c_str(), nullptr);
                if (!std::isfinite(number)) continue;
                const CGFloat px = left + (pointCount <= 1 ? width / 2.0 :
                    width * static_cast<CGFloat>(index) / static_cast<CGFloat>(pointCount - 1));
                const CGFloat py = y + height - height * static_cast<CGFloat>(
                    (number - minimum) / (maximum - minimum));
                if (!started) { [path moveToPoint:NSMakePoint(px, py)]; started = YES; }
                else [path lineToPoint:NSMakePoint(px, py)];
                [color setFill];
                [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(px - 2.5, py - 2.5, 5, 5)] fill];
            }
            [color setStroke]; [path setLineWidth:1.6]; [path stroke];
            [ToNSString(entry->name) drawAtPoint:NSMakePoint(left + width + 12,
                y + 17 * static_cast<CGFloat>(seriesIndex)) withAttributes:muted];
        }
        y += height + 24; separator(y); y += 12;
    };
    if (state->specification.showItemPlots) {
        std::vector<std::pair<std::string, std::string>> values;
        for (const auto &row : state->result.items) values.emplace_back(row.variable, row.itemRestCorrelation);
        drawBars(@"Corrected item-rest correlations", values);
        values.clear();
        for (const auto &row : state->result.items) values.emplace_back(row.variable, row.alphaIfDeleted);
        drawBars(@"Reliability if item deleted", values);
    }
    if (state->specification.showItemDistributions) {
        for (const auto *series : seriesForKind("item_distribution")) {
            std::vector<std::pair<std::string, std::string>> values;
            for (std::size_t index = 0; index < series->labels.size(); ++index)
                values.emplace_back(series->labels[index], series->values[index]);
            drawBars([NSString stringWithFormat:@"Item distribution — %@",
                ToNSString(series->name)], values);
        }
    }
    if (state->specification.showLoadingPlot && !state->result.dimensionality.loadings.empty()) {
        std::vector<std::pair<std::string, std::string>> values;
        for (const auto &row : state->result.dimensionality.loadings)
            values.emplace_back(row.item, row.loadings.empty() ? "" : row.loadings.front());
        drawBars(@"Factor loadings", values);
    }
    if (state->specification.showCorrelationHeatmap) {
        sectionTitle(@"Correlation heatmap", y);
        const auto &correlations = state->result.correlations;
        const std::size_t count = correlations.variables.size();
        const CGFloat cell = count ? std::min<CGFloat>(30.0, 360.0 / count) : 24.0;
        for (std::size_t row = 0; row < count; ++row) for (std::size_t column = 0; column < count; ++column) {
            const double value = std::strtod(correlations.values[row * count + column].c_str(), nullptr);
            NSColor *color = value >= 0
                ? [NSColor colorWithCalibratedRed:0.12 green:0.43 blue:0.86 alpha:0.15 + 0.75 * std::min(1.0, std::fabs(value))]
                : [NSColor colorWithCalibratedRed:0.93 green:0.30 blue:0.25 alpha:0.15 + 0.75 * std::min(1.0, std::fabs(value))];
            [color setFill]; NSRectFill(NSMakeRect(180 + cell * column, y + cell * row, cell - 1, cell - 1));
        }
        y += cell * count + 18; separator(y); y += 12;
    }
    if (state->specification.showReliabilityStability) {
        std::vector<std::pair<std::string, std::string>> values;
        for (const auto &row : state->result.reliabilityByImputation)
            values.emplace_back("Imputation " + row.imputation, row.alpha);
        drawBars(@"Reliability stability across imputations", values);
    }
    if (state->specification.showScoreDistribution)
        drawLineSeries(@"Scale-score distribution", seriesForKind("score_distribution"));
    if (state->specification.showScreePlot) {
        auto series = seriesForKind("scree_observed");
        const auto references = seriesForKind("scree_reference");
        series.insert(series.end(), references.begin(), references.end());
        drawLineSeries(@"Scree / parallel analysis", series);
        const auto stability = seriesForKind("factor_stability");
        if (!stability.empty()) {
            std::vector<std::pair<std::string, std::string>> values;
            for (std::size_t index = 0; index < stability.front()->labels.size(); ++index)
                values.emplace_back(stability.front()->labels[index], stability.front()->values[index]);
            drawBars(state->specification.dimensionalityMethod == "pca"
                ? @"Suggested-component stability across imputations"
                : @"Suggested-factor stability across imputations", values);
        }
    }

    if (!state->result.provenance.empty()) {
        sectionTitle(@"Statistical provenance", y);
        [ToNSString(state->result.provenance) drawInRect:NSMakeRect(16, y,
            self.bounds.size.width - 32, 64) withAttributes:muted];
    }
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    ScaleAnalysisState *state = [_controller state];
    if (!state || point.y < _itemRowsOrigin) return;
    NSInteger index = (NSInteger)((point.y - _itemRowsOrigin) / 24.0);
    if (index >= 0 && index < (NSInteger)state->specification.items.size()) {
        [_controller showReplacementMenuForIndex:index atPoint:point inView:self];
    } else if (index == (NSInteger)state->specification.items.size()) {
        [_controller showAddItemMenuAtPoint:point inView:self];
    }
}

- (void)rightMouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    ScaleAnalysisState *state = [_controller state];
    if (!state) return;
    NSString *statistic = nil;
    if (_hasSummary && point.y >= _summaryOrigin && point.y < _summaryOrigin + 156 && point.x >= 16) {
        const NSInteger column = (point.x - 16) / ((self.bounds.size.width - 32) / 3);
        const NSInteger row = (point.y - _summaryOrigin) / 52;
        const auto fields = rlispstat::core::ScaleAnalysisSummaryFields(state->result);
        if (column < 3 && row * 3 + column < (NSInteger)fields.size())
            statistic = ToNSString(fields[row * 3 + column].first);
    } else if (state->specification.showItemAnalysis && point.y >= _itemRowsOrigin - 28 &&
               point.y < _itemRowsOrigin + 24 * state->specification.items.size() && point.x >= 445) {
        const CGFloat edges[] = {445, 515, 580, 670, 790};
        const char *names[] = {"Mean", "SD", "Missing %", "Item-rest r", "Alpha if deleted"};
        for (int i = 0; i < 5; ++i) if (point.x >= edges[i]) statistic = ToNSString(names[i]);
    }
    if (statistic) {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Statistic"];
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:@"Explain statistic"
            action:@selector(explainScaleStatistic:) keyEquivalent:@""];
        [item setTarget:_controller]; [item setRepresentedObject:statistic]; [menu addItem:item];
        [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
        return;
    }
    if (point.y < _itemRowsOrigin) {
        [_controller showScaleMenuAtPoint:point inView:self];
        return;
    }
    NSInteger index = (NSInteger)((point.y - _itemRowsOrigin) / 24.0);
    if (index >= 0 && index < (NSInteger)state->specification.items.size()) {
        [_controller showItemMenuForIndex:index atPoint:point inView:self];
    } else {
        [_controller showScaleMenuAtPoint:point inView:self];
    }
}

@end

@implementation ScaleAnalysisWindowController

- (instancetype)initWithAnalysisId:(const std::string &)analysisId
{
    if ((self = [super init])) {
        _analysisId = analysisId;
        ScaleAnalysisState *state = [self state];
        const bool mi = state && GroupIsMultipleImputation(state->group);
        const auto layout = rlispstat::core::BuildScaleAnalysisWindowLayout(
            state ? state->specification.items.size() : 0U, 12);
        _window = [[NSWindow alloc] initWithContentRect:NextWindowFrameOnMain(
            layout.preferredWidth, layout.preferredHeight)
            styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                       NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable)
            backing:NSBackingStoreBuffered defer:NO];
        [_window setTitle:ToNSString(rlispstat::core::ScaleAnalysisWindowTitle(mi))];
        [_window setDelegate:self];
        ConfigureResultWindowTabbing(_window);
        NSView *content = [_window contentView];
        _titleField = GLMLabel(ToNSString(rlispstat::core::ScaleAnalysisWindowTitle(mi)),
                               NSMakeRect(16, layout.preferredHeight - 50, 430, 26), 18,
                               NSFontWeightSemibold);
        [content addSubview:_titleField];
        _badgeField = GLMRightLabel(state ? ToNSString(state->group) : @"",
                                   NSMakeRect(layout.preferredWidth - 260,
                                              layout.preferredHeight - 48, 240, 22),
                                   12, NSFontWeightSemibold);
        [content addSubview:_badgeField];
        _correlationPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(16, layout.preferredHeight - 88, 170, 28) pullsDown:NO];
        [_correlationPopup addItemsWithTitles:@[@"Automatic correlations", @"Pearson", @"Polychoric", @"Mixed correlations"]];
        [_correlationPopup setTarget:self];
        [_correlationPopup setAction:@selector(optionsChanged:)];
        [content addSubview:_correlationPopup];
        _scorePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(194, layout.preferredHeight - 88, 125, 28) pullsDown:NO];
        [_scorePopup addItemsWithTitles:@[@"Mean score", @"Sum score"]];
        [_scorePopup setTarget:self];
        [_scorePopup setAction:@selector(optionsChanged:)];
        [content addSubview:_scorePopup];
        _autoFitButton = [[NSButton alloc] initWithFrame:NSMakeRect(327,
            layout.preferredHeight - 86, 100, 24)];
        [_autoFitButton setButtonType:NSButtonTypeSwitch];
        [_autoFitButton setTitle:@"Auto-fit"];
        [_autoFitButton setTarget:self];
        [_autoFitButton setAction:@selector(autoFitChanged:)];
        [content addSubview:_autoFitButton];
        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 48, layout.preferredWidth - 24, layout.preferredHeight - 150)];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setBorderType:NSNoBorder];
        _reportView = [[ScaleAnalysisView alloc] initWithController:self];
        [_scrollView setDocumentView:_reportView];
        [content addSubview:_scrollView];
        _statusField = GLMLabel(@"", NSMakeRect(16, 12, layout.preferredWidth - 32, 24), 11, NSFontWeightRegular);
        [_statusField setTextColor:[NSColor secondaryLabelColor]];
        [content addSubview:_statusField];
        EnableNotesForWindow(_window, analysisId, @"Scale Analysis",
                             state ? state->group : std::string{});
        [self refresh];
    }
    return self;
}

- (ScaleAnalysisState *)state
{
    auto found = g_scaleAnalyses.find(_analysisId);
    return found == g_scaleAnalyses.end() ? nullptr : &found->second;
}

- (void)show { [self refresh]; if (!_window.isVisible) { [NSApp activateIgnoringOtherApps:YES]; [_window makeKeyAndOrderFront:nil]; } }

- (void)refresh
{
    ScaleAnalysisState *state = [self state];
    if (!state) return;
    const auto layout = rlispstat::core::BuildScaleAnalysisWindowLayout(
        state->specification.items.size(), 12);
    NSSize wanted = [_reportView preferredContentSize];
    NSSize contentSize = FitResultTableWindowToContent(_window,
        NSMakeSize(wanted.width + 24, wanted.height + 150),
        NSMakeSize(760.0, 430.0));
    const CGFloat width = contentSize.width, height = contentSize.height;
    [_titleField setFrame:NSMakeRect(16, height - 50, 430, 26)];
    [_badgeField setFrame:NSMakeRect(width - 260, height - 48, 240, 22)];
    [_correlationPopup setFrame:NSMakeRect(16, height - 88, 170, 28)];
    [_scorePopup setFrame:NSMakeRect(194, height - 88, 125, 28)];
    [_autoFitButton setFrame:NSMakeRect(327, height - 86, 100, 24)];
    [_scrollView setFrame:NSMakeRect(12, 48, width - 24, height - 150)];
    [_statusField setFrame:NSMakeRect(16, 12, width - 32, 24)];
    NSSize visible = [_scrollView contentSize];
    [_reportView setFrameSize:NSMakeSize(std::max(wanted.width, visible.width),
        std::max(wanted.height, visible.height))];
    [_reportView setNeedsDisplay:YES];
    const bool multipleImputation = GroupIsMultipleImputation(state->group);
    int imputationCount = state->result.imputationCount;
    if (multipleImputation && imputationCount <= 1) {
        DataFrameModel dataframe;
        if (DataFrameSnapshotForGroup(state->group, dataframe)) {
            imputationCount = std::max(1, dataframe.imputationCount);
        }
    }
    [_titleField setStringValue:ToNSString(
        rlispstat::core::ScaleAnalysisWindowTitle(multipleImputation))];
    [_window setTitle:ToNSString(
        rlispstat::core::ScaleAnalysisWindowTitle(multipleImputation))];
    [_badgeField setStringValue:ToNSString(state->group +
        (multipleImputation ? " · m = " + std::to_string(imputationCount) : ""))];
    const std::string basis = state->specification.correlationBasis;
    [_correlationPopup selectItemAtIndex:basis == "pearson" ? 1 : basis == "polychoric" ? 2 : basis == "mixed" ? 3 : 0];
    [_scorePopup selectItemAtIndex:state->specification.scoreMethod == "sum" ? 1 : 0];
    [_autoFitButton setState:state->autoFit ? NSControlStateValueOn : NSControlStateValueOff];
    [_statusField setStringValue:ToNSString(state->status)];
    if (_itemSelectorPanel && _itemSelectorPanel.isVisible) {
        [self rebuildItemSelectorPreservingRow:_itemSelectorTable.selectedRow];
    }

    auto children = g_scaleAnalysisDerivedControllers.find(_analysisId);
    if (children != g_scaleAnalysisDerivedControllers.end()) {
        for (const auto &entry : children->second) [entry.second refresh];
    }
}

- (void)showAddItemMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    (void)point;
    (void)view;
    [self showPersistentItemSelector];
}

- (NSMenu *)buildAddItemMenu
{
    ScaleAnalysisState *state = [self state];
    DataFrameModel dataframe;
    if (!state || !DataFrameSnapshotForGroup(state->group, dataframe)) return nil;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Add item"];
    auto eligible = rlispstat::core::EligibleScaleVariables(dataframe, state->specification.items);
    if (eligible.empty()) {
        NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:@"No eligible numeric or ordinal variables" action:nil keyEquivalent:@""];
        [none setEnabled:NO];
        [menu addItem:none];
    }
    for (const std::string &name : eligible) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addItemFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    return menu;
}

- (void)saveTotalScore:(id)sender
{
    ScaleAnalysisState *state = [self state];
    if (!state || state->rFitPending || !ScaleAnalysisResultMatchesSpecification(
            state->specification, state->result)) return;
    const auto task = rlispstat::core::ScaleTotalScoreSaveTask(state->id, state->group,
        [sender tag] == 1 ? "sum" : "mean", state->specification.revision,
        state->specification.fingerprint);
    { std::lock_guard<std::mutex> lock(g_mutex); g_pendingMissingDataTasks.push_back(task); }
    NotifyMainRTaskAvailable();
}

- (void)explainScaleStatistic:(id)sender
{
    ScaleAnalysisState *state = [self state];
    if (!state) return;
    ShowAnalysisStatisticExplanationOnMain([[sender representedObject] UTF8String],
        "scale", state->specification.scoreMethod, "", state->result.imputationCount > 1);
}

- (void)showPersistentItemSelector
{
    if (!_itemSelectorPanel) {
        const CGFloat width = 360.0;
        const CGFloat height = 350.0;
        _itemSelectorPanel = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, width, height)
            styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                       NSWindowStyleMaskUtilityWindow)
            backing:NSBackingStoreBuffered defer:NO];
        [_itemSelectorPanel setTitle:@"Add scale items"];
        [_itemSelectorPanel setReleasedWhenClosed:NO];
        [_itemSelectorPanel setHidesOnDeactivate:NO];
        NSView *content = _itemSelectorPanel.contentView;

        _itemSearchField = [[ScaleItemSearchField alloc] initWithFrame:NSMakeRect(14, height - 46, width - 28, 28)];
        [(ScaleItemSearchField *)_itemSearchField setSelectorController:self];
        [_itemSearchField setPlaceholderString:@"Search items"];
        [_itemSearchField setSendsSearchStringImmediately:YES];
        [_itemSearchField setDelegate:self];
        [content addSubview:_itemSearchField];

        NSScrollView *listScroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(14, 42, width - 28, height - 98)];
        [listScroll setHasVerticalScroller:YES];
        [listScroll setBorderType:NSBezelBorder];
        _itemSelectorTable = [[ScaleItemSelectorTableView alloc] initWithFrame:listScroll.bounds];
        [(ScaleItemSelectorTableView *)_itemSelectorTable setSelectorController:self];
        NSTableColumn *column = [[NSTableColumn alloc] initWithIdentifier:@"ScaleItemName"];
        [column setWidth:width - 52];
        [_itemSelectorTable addTableColumn:column];
        [_itemSelectorTable setHeaderView:nil];
        [_itemSelectorTable setRowHeight:25.0];
        [_itemSelectorTable setAllowsEmptySelection:YES];
        [_itemSelectorTable setAllowsMultipleSelection:YES];
        [_itemSelectorTable setAllowsTypeSelect:YES];
        [_itemSelectorTable setDataSource:self];
        [_itemSelectorTable setDelegate:self];
        [_itemSelectorTable setTarget:self];
        [_itemSelectorTable setAction:nil];
        [_itemSelectorTable setDoubleAction:@selector(addSelectedItemFromSelector:)];
        [listScroll setDocumentView:_itemSelectorTable];
        [content addSubview:listScroll];

        _itemSelectorEmptyLabel = GLMLabel(@"Shift-click: range · Command-click: individual",
            NSMakeRect(18, 14, 205, 20), 11, NSFontWeightRegular);
        [_itemSelectorEmptyLabel setTextColor:NSColor.secondaryLabelColor];
        [content addSubview:_itemSelectorEmptyLabel];
        _addSelectedItemsButton = [[NSButton alloc]
            initWithFrame:NSMakeRect(width - 132, 8, 118, 28)];
        [_addSelectedItemsButton setTitle:@"Add selected"];
        [_addSelectedItemsButton setBezelStyle:NSBezelStyleRounded];
        [_addSelectedItemsButton setTarget:self];
        [_addSelectedItemsButton setAction:@selector(addSelectedItemFromSelector:)];
        [content addSubview:_addSelectedItemsButton];
        _filteredItemNames = [[NSMutableArray alloc] init];
    }

    const BOOL wasVisible = _itemSelectorPanel.isVisible;
    if (!wasVisible) [_itemSearchField setStringValue:@""];
    [self rebuildItemSelectorPreservingRow:0];

    NSRect buttonRect = [_scrollView convertRect:_scrollView.bounds toView:nil];
    NSRect buttonOnScreen = [_window convertRectToScreen:buttonRect];
    NSRect frame = _itemSelectorPanel.frame;
    frame.origin.x = NSMinX(buttonOnScreen);
    frame.origin.y = NSMinY(buttonOnScreen) - NSHeight(frame) - 6.0;
    NSScreen *screen = _window.screen ?: NSScreen.mainScreen;
    if (screen) {
        NSRect visible = screen.visibleFrame;
        frame.origin.x = std::clamp(frame.origin.x, NSMinX(visible),
                                    std::max(NSMinX(visible), NSMaxX(visible) - NSWidth(frame)));
        frame.origin.y = std::clamp(frame.origin.y, NSMinY(visible),
                                    std::max(NSMinY(visible), NSMaxY(visible) - NSHeight(frame)));
    }
    [_itemSelectorPanel setFrame:frame display:NO];
    if (_itemSelectorPanel.parentWindow != _window)
        [_window addChildWindow:_itemSelectorPanel ordered:NSWindowAbove];
    [_itemSelectorPanel makeKeyAndOrderFront:nil];
    [_itemSelectorPanel makeFirstResponder:_itemSearchField];
}

- (void)rebuildItemSelectorPreservingRow:(NSInteger)row
{
    if (!_itemSelectorTable || !_filteredItemNames) return;
    ScaleAnalysisState *state = [self state];
    DataFrameModel dataframe;
    [_filteredItemNames removeAllObjects];
    if (state && DataFrameSnapshotForGroup(state->group, dataframe)) {
        const auto eligible = rlispstat::core::EligibleScaleVariables(
            dataframe, state->specification.items);
        NSString *query = _itemSearchField.stringValue ?: @"";
        for (const std::string &name : eligible) {
            NSString *label = ToNSString(name);
            if (query.length == 0 ||
                [label rangeOfString:query options:NSCaseInsensitiveSearch].location != NSNotFound)
                [_filteredItemNames addObject:label];
        }
    }
    [_itemSelectorTable reloadData];
    const NSInteger count = (NSInteger)_filteredItemNames.count;
    [_itemSelectorEmptyLabel setStringValue:count == 0
        ? @"No eligible unused items"
        : @"Shift-click: range · Command-click: individual"];
    [_itemSelectorEmptyLabel setHidden:NO];
    [_addSelectedItemsButton setEnabled:count != 0];
    if (count > 0) {
        const NSInteger wanted = std::clamp(row < 0 ? 0 : row,
                                             (NSInteger)0, count - 1);
        [_itemSelectorTable selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)wanted]
                       byExtendingSelection:NO];
        [_itemSelectorTable scrollRowToVisible:wanted];
    }
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView
{
    (void)tableView;
    return (NSInteger)_filteredItemNames.count;
}

- (NSView *)tableView:(NSTableView *)tableView
    viewForTableColumn:(NSTableColumn *)tableColumn
                   row:(NSInteger)row
{
    (void)tableColumn;
    static NSString *identifier = @"ScaleItemSelectorCell";
    NSTableCellView *cell = [tableView makeViewWithIdentifier:identifier owner:self];
    if (!cell) {
        cell = [[NSTableCellView alloc] initWithFrame:NSMakeRect(0, 0, 300, 25)];
        cell.identifier = identifier;
        NSTextField *label = GLMLabel(@"", NSMakeRect(7, 3, 286, 19),
                                     12, NSFontWeightRegular);
        [label setAutoresizingMask:NSViewWidthSizable];
        cell.textField = label;
        [cell addSubview:label];
    }
    cell.textField.stringValue = row >= 0 && row < (NSInteger)_filteredItemNames.count
        ? _filteredItemNames[(NSUInteger)row] : @"";
    return cell;
}

- (void)tableViewSelectionDidChange:(NSNotification *)notification
{
    if (notification.object != _itemSelectorTable || !_addSelectedItemsButton) return;
    const NSUInteger count = _itemSelectorTable.selectedRowIndexes.count;
    [_addSelectedItemsButton setEnabled:count > 0];
    [_addSelectedItemsButton setTitle:count > 1
        ? [NSString stringWithFormat:@"Add %lu items", (unsigned long)count]
        : @"Add selected"];
}

- (void)controlTextDidChange:(NSNotification *)notification
{
    if (notification.object == _itemSearchField)
        [self rebuildItemSelectorPreservingRow:0];
}

- (void)moveItemSelectorSelection:(NSInteger)delta
{
    const NSInteger count = (NSInteger)_filteredItemNames.count;
    if (count <= 0) return;
    NSInteger row = _itemSelectorTable.selectedRow;
    if (row < 0) row = 0;
    else row = std::clamp(row + delta, (NSInteger)0, count - 1);
    [_itemSelectorTable selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)row]
                   byExtendingSelection:NO];
    [_itemSelectorTable scrollRowToVisible:row];
}

- (void)addSelectedItemFromSelector:(id)sender
{
    NSIndexSet *selectedRows = _itemSelectorTable.selectedRowIndexes;
    if (selectedRows.count == 0 && _filteredItemNames.count > 0) {
        selectedRows = [NSIndexSet indexSetWithIndex:0];
    }
    if (selectedRows.count == 0) return;
    const NSInteger firstRow = (NSInteger)selectedRows.firstIndex;
    NSMutableArray<NSString *> *names = [NSMutableArray array];
    NSUInteger row = selectedRows.firstIndex;
    while (row != NSNotFound) {
        if (row < _filteredItemNames.count)
            [names addObject:_filteredItemNames[row]];
        row = [selectedRows indexGreaterThanIndex:row];
    }
    if (![self addItemsNamed:names]) return;
    [self rebuildItemSelectorPreservingRow:firstRow];
    if (sender == _itemSearchField)
        [_itemSelectorPanel makeFirstResponder:_itemSearchField];
    else
        [_itemSelectorPanel makeFirstResponder:_itemSelectorTable];
}

- (void)closeItemSelector:(id)sender
{
    (void)sender;
    [_itemSelectorPanel orderOut:nil];
    [_window makeKeyAndOrderFront:nil];
}

- (void)showReplacementMenuForIndex:(NSInteger)index atPoint:(NSPoint)point inView:(NSView *)view
{
    ScaleAnalysisState *state = [self state];
    DataFrameModel dataframe;
    if (!state || index < 0 || index >= (NSInteger)state->specification.items.size() ||
        !DataFrameSnapshotForGroup(state->group, dataframe)) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Replace item"];
    for (const DataColumn &column : dataframe.columns) {
        if (!rlispstat::core::ScaleColumnIsEligible(column)) continue;
        bool usedElsewhere = false;
        for (NSInteger j = 0; j < (NSInteger)state->specification.items.size(); ++j)
            if (j != index && state->specification.items[j].variable == column.name) usedElsewhere = true;
        if (usedElsewhere) continue;
        NSMenuItem *entry = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name) action:@selector(replaceItemFromMenu:) keyEquivalent:@""];
        [entry setTarget:self];
        [entry setRepresentedObject:@[@(index), ToNSString(column.name)]];
        if (state->specification.items[index].variable == column.name) [entry setState:NSControlStateValueOn];
        [menu addItem:entry];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)showItemMenuForIndex:(NSInteger)index atPoint:(NSPoint)point inView:(NSView *)view
{
    ScaleAnalysisState *state = [self state];
    if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    const ScaleItemSpecification &spec = state->specification.items[index];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(spec.variable)];
    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:@"Add item\u2026"
        action:nil keyEquivalent:@""];
    NSMenu *addMenu = [self buildAddItemMenu];
    if (addMenu) [menu setSubmenu:addMenu forItem:add];
    else [add setEnabled:NO];
    [menu addItem:add];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *type = [[NSMenuItem alloc] initWithTitle:@"Treat as" action:nil keyEquivalent:@""];
    NSMenu *types = [[NSMenu alloc] initWithTitle:@"Treat as"];
    DataFrameModel itemData;
    const DataColumn *itemColumn = nullptr;
    if (DataFrameSnapshotForGroup(state->group, itemData))
        for (const auto &column : itemData.columns)
            if (column.name == spec.variable) { itemColumn = &column; break; }
    for (NSInteger value = 0; value < 2; ++value) {
        NSMenuItem *entry = [[NSMenuItem alloc] initWithTitle:ToNSString(ScaleItemTypeMenuLabel(value == 0 ? ScaleItemType::Numeric : ScaleItemType::Ordinal, itemColumn)) action:@selector(setItemTypeFromMenu:) keyEquivalent:@""];
        [entry setTarget:self];
        [entry setRepresentedObject:@[@(index), @(value)]];
        if ((value == 0) == (spec.type == ScaleItemType::Numeric)) [entry setState:NSControlStateValueOn];
        [types addItem:entry];
    }
    [menu setSubmenu:types forItem:type]; [menu addItem:type];
    NSMenuItem *direction = [[NSMenuItem alloc] initWithTitle:@"Direction" action:nil keyEquivalent:@""];
    NSMenu *directions = [[NSMenu alloc] initWithTitle:@"Direction"];
    for (NSInteger value = 0; value < 2; ++value) {
        NSMenuItem *entry = [[NSMenuItem alloc] initWithTitle:value == 0 ? @"Forward" : @"Reversed" action:@selector(setItemDirectionFromMenu:) keyEquivalent:@""];
        [entry setTarget:self]; [entry setRepresentedObject:@[@(index), @(value)]];
        if ((value == 1) == spec.reversed) [entry setState:NSControlStateValueOn];
        [directions addItem:entry];
    }
    [menu setSubmenu:directions forItem:direction]; [menu addItem:direction];
    NSMenuItem *range = [[NSMenuItem alloc] initWithTitle:@"Set theoretical scoring range…" action:@selector(setItemRangeFromMenu:) keyEquivalent:@""];
    [range setTarget:self]; [range setRepresentedObject:@(index)]; [menu addItem:range];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *info = [[NSMenuItem alloc] initWithTitle:@"Variable information" action:@selector(showItemInformation:) keyEquivalent:@""];
    [info setTarget:self]; [info setRepresentedObject:@(index)]; [menu addItem:info];
    NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:@"Remove item" action:@selector(removeItemFromMenu:) keyEquivalent:@""];
    [remove setTarget:self]; [remove setRepresentedObject:@(index)]; [menu addItem:remove];
    [menu addItem:[NSMenuItem separatorItem]];
    AddSnapshotAlbumContextItems(menu);
    [self addExportMenuToMenu:menu];
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (BOOL)applyCandidate:(ScaleAnalysisSpecification)candidate
{
    ScaleAnalysisState *state = [self state];
    if (!state) return NO;
    std::string error;
    if (!CommitScaleAnalysisSpecification(*state, std::move(candidate), error)) {
        [_statusField setStringValue:ToNSString(error)];
        return NO;
    }
    [self refresh];
    return YES;
}

- (void)addItemFromMenu:(id)sender
{
    [self addItemNamed:[sender representedObject]];
}

- (BOOL)addItemNamed:(NSString *)name
{
    if (name.length == 0) return NO;
    return [self addItemsNamed:@[name]];
}

- (BOOL)addItemsNamed:(NSArray<NSString *> *)names
{
    ScaleAnalysisState *state = [self state];
    if (!state || names.count == 0) return NO;
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return NO;
    ScaleAnalysisSpecification candidate = state->specification;
    BOOL changed = NO;
    for (NSString *name in names) {
        if (name.length == 0) continue;
        const std::string itemName = [name UTF8String];
        if (std::any_of(candidate.items.begin(), candidate.items.end(),
            [&](const ScaleItemSpecification &item) {
                return item.variable == itemName;
            })) continue;
        auto found = std::find_if(dataframe.columns.begin(), dataframe.columns.end(),
            [&](const DataColumn &column) { return column.name == itemName; });
        if (found == dataframe.columns.end() ||
            !rlispstat::core::ScaleColumnIsEligible(*found)) continue;
        ScaleItemSpecification item;
        item.variable = itemName;
        item.type = rlispstat::core::DefaultScaleItemType(*found);
        candidate.items.push_back(std::move(item));
        changed = YES;
    }
    if (!changed) return NO;
    return [self applyCandidate:std::move(candidate)];
}

- (void)replaceItemFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject]; NSInteger index = [payload[0] integerValue];
    ScaleAnalysisState *state = [self state]; if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    std::string name = [payload[1] UTF8String]; DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    auto column = std::find_if(dataframe.columns.begin(), dataframe.columns.end(), [&](const DataColumn &c){ return c.name == name; });
    if (column == dataframe.columns.end()) return;
    ScaleAnalysisSpecification candidate = state->specification;
    candidate.items[index] = {}; candidate.items[index].variable = name;
    candidate.items[index].type = rlispstat::core::DefaultScaleItemType(*column);
    [self applyCandidate:std::move(candidate)];
}

- (void)removeItemFromMenu:(id)sender
{
    NSInteger index = [[sender representedObject] integerValue]; ScaleAnalysisState *state = [self state];
    if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    ScaleAnalysisSpecification candidate = state->specification;
    candidate.items.erase(candidate.items.begin() + index); [self applyCandidate:std::move(candidate)];
}

- (void)setItemTypeFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject]; NSInteger index = [payload[0] integerValue]; NSInteger value = [payload[1] integerValue];
    ScaleAnalysisState *state = [self state]; if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    ScaleAnalysisSpecification candidate = state->specification;
    candidate.items[index].type = value == 1 ? ScaleItemType::Ordinal : ScaleItemType::Numeric;
    [self applyCandidate:std::move(candidate)];
}

- (BOOL)promptForRangeAtIndex:(NSInteger)index candidate:(ScaleAnalysisSpecification &)candidate
{
    NSAlert *alert = [[NSAlert alloc] init]; [alert setMessageText:@"Theoretical scoring range"];
    [alert setInformativeText:@"Numeric reverse scoring requires the scale's theoretical minimum and maximum. Observed minima and maxima are never used."];
    NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 260, 58)];
    NSTextField *minimum = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 30, 120, 24)];
    NSTextField *maximum = [[NSTextField alloc] initWithFrame:NSMakeRect(140, 30, 120, 24)];
    [minimum setPlaceholderString:@"Minimum"]; [maximum setPlaceholderString:@"Maximum"];
    const auto &item = candidate.items[index];
    if (item.hasScoringRange) { [minimum setDoubleValue:item.scoringMinimum]; [maximum setDoubleValue:item.scoringMaximum]; }
    [accessory addSubview:minimum]; [accessory addSubview:maximum]; [alert setAccessoryView:accessory];
    [alert addButtonWithTitle:@"Apply"]; [alert addButtonWithTitle:@"Cancel"];
    if ([alert runModal] != NSAlertFirstButtonReturn) return NO;
    double lo = minimum.doubleValue, hi = maximum.doubleValue;
    if (!std::isfinite(lo) || !std::isfinite(hi) || lo >= hi) {
        ShowWorkbenchMessageOnMain(@"Scoring range", @"Enter a finite minimum smaller than the maximum.");
        return NO;
    }
    candidate.items[index].hasScoringRange = true;
    candidate.items[index].scoringMinimum = lo; candidate.items[index].scoringMaximum = hi;
    return YES;
}

- (void)setItemDirectionFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject]; NSInteger index = [payload[0] integerValue]; BOOL reversed = [payload[1] integerValue] == 1;
    ScaleAnalysisState *state = [self state]; if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    ScaleAnalysisSpecification candidate = state->specification; candidate.items[index].reversed = reversed;
    if (reversed && candidate.items[index].type == ScaleItemType::Numeric && !candidate.items[index].hasScoringRange)
        if (![self promptForRangeAtIndex:index candidate:candidate]) return;
    [self applyCandidate:std::move(candidate)];
}

- (void)setItemRangeFromMenu:(id)sender
{
    NSInteger index = [[sender representedObject] integerValue]; ScaleAnalysisState *state = [self state];
    if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    ScaleAnalysisSpecification candidate = state->specification;
    if ([self promptForRangeAtIndex:index candidate:candidate]) [self applyCandidate:std::move(candidate)];
}

- (void)showItemInformation:(id)sender
{
    NSInteger index = [[sender representedObject] integerValue]; ScaleAnalysisState *state = [self state];
    if (!state || index < 0 || index >= (NSInteger)state->specification.items.size()) return;
    ShowWorkbenchMessageOnMain(@"Variable Information", ToNSString(VariableInformationText(state->group, state->specification.items[index].variable)));
}

- (void)showScaleMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Scale Analysis"];
    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:@"Add item\u2026"
        action:nil keyEquivalent:@""];
    NSMenu *addMenu = [self buildAddItemMenu];
    if (addMenu) [menu setSubmenu:addMenu forItem:add];
    else [add setEnabled:NO];
    [menu addItem:add];
    [menu addItem:[NSMenuItem separatorItem]];
    auto addCommand = [&](NSMenu *target, NSString *title,
                          ScaleAnalysisChildKind kind) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title
            action:@selector(openDerivedResult:) keyEquivalent:@""];
        [item setTarget:self];
        [item setTag:static_cast<NSInteger>(kind)];
        [target addItem:item];
    };
    addCommand(menu, @"Reliability…", ScaleAnalysisChildKind::Reliability);
    addCommand(menu, @"Inter-item correlations…",
        ScaleAnalysisChildKind::InterItemCorrelations);
    addCommand(menu, @"Dimensionality…", ScaleAnalysisChildKind::Dimensionality);
    addCommand(menu, @"Scale scores…", ScaleAnalysisChildKind::ScaleScores);
    NSMenuItem *save = [[NSMenuItem alloc] initWithTitle:@"Save total scores to data" action:nil keyEquivalent:@""];
    NSMenu *saveMenu = [[NSMenu alloc] initWithTitle:@"Save total scores to data"];
    ScaleAnalysisState *current = [self state];
    for (NSInteger index = 0; index < 2; ++index) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:index == 0 ? @"Mean of items" : @"Sum of items"
            action:@selector(saveTotalScore:) keyEquivalent:@""];
        [item setTag:index]; [item setTarget:self];
        [item setEnabled:current && !current->rFitPending &&
            ScaleAnalysisResultMatchesSpecification(current->specification, current->result)];
        [saveMenu addItem:item];
    }
    [saveMenu setAutoenablesItems:NO]; [save setSubmenu:saveMenu]; [menu addItem:save];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *plotsItem = [[NSMenuItem alloc] initWithTitle:@"Plots" action:nil
        keyEquivalent:@""];
    NSMenu *plots = [[NSMenu alloc] initWithTitle:@"Plots"];
    addCommand(plots, @"Item-rest correlations",
        ScaleAnalysisChildKind::ItemRestPlot);
    addCommand(plots, @"Reliability if item deleted",
        ScaleAnalysisChildKind::ReliabilityIfDeletedPlot);
    addCommand(plots, @"Item distributions",
        ScaleAnalysisChildKind::ItemDistributionsPlot);
    addCommand(plots, @"Scale-score distribution",
        ScaleAnalysisChildKind::ScaleScoreDistributionPlot);
    [plots addItem:[NSMenuItem separatorItem]];
    addCommand(plots, @"Correlation heatmap",
        ScaleAnalysisChildKind::CorrelationHeatmap);
    [menu setSubmenu:plots forItem:plotsItem];
    [menu addItem:plotsItem];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *information = [[NSMenuItem alloc]
        initWithTitle:@"Analysis information…"
        action:@selector(showAnalysisInformation:) keyEquivalent:@""];
    [information setTarget:self]; [menu addItem:information];
    [menu addItem:[NSMenuItem separatorItem]];
    AddSnapshotAlbumContextItems(menu);
    [self addExportMenuToMenu:menu];
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)addExportMenuToMenu:(NSMenu *)menu
{
    if (!menu || !_reportView) return;
    NSString *title = [_window title] ?: @"Scale Analysis";
    NSString *baseName = [[title lowercaseString]
        stringByReplacingOccurrencesOfString:@" " withString:@"-"];
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export"
        action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    const auto tables = rlispstat::core::ScaleAnalysisPublicationTables(*[self state]);
    const auto noteTables = rlispstat::core::ScaleAnalysisPublicationTables(
        *[self state], -1, 1, rlispstat::core::ScaleAnalysisGlobalPresentation::ItemTableNote);
    AddStandardTableVisualExportItems(exportMenu, _reportView, title, baseName,
        [_reportView snapshotTabDelimitedText], tables.empty() ? nullptr : &tables.front(),
        &tables, true, true, &noteTables);
    AddRCodeExportItems(exportMenu, "output", _analysisId, true);
    [root setSubmenu:exportMenu];
    [menu addItem:root];
}

- (void)openDerivedResult:(id)sender
{
    ScaleAnalysisState *state = [self state];
    if (!state) return;
    const auto kind = static_cast<ScaleAnalysisChildKind>([sender tag]);
    ScaleAnalysisSpecification candidate = state->specification;
    if (kind == ScaleAnalysisChildKind::Reliability) {
        candidate.showReliability = true;
        candidate.computeOmega = true;
        candidate.showReliabilityStability = true;
    } else if (kind == ScaleAnalysisChildKind::InterItemCorrelations ||
               kind == ScaleAnalysisChildKind::CorrelationHeatmap) {
        candidate.showCorrelations = true;
        candidate.showCorrelationHeatmap =
            kind == ScaleAnalysisChildKind::CorrelationHeatmap;
    } else if (kind == ScaleAnalysisChildKind::Dimensionality ||
               kind == ScaleAnalysisChildKind::ScreePlot ||
               kind == ScaleAnalysisChildKind::LoadingPlot ||
               kind == ScaleAnalysisChildKind::Biplot) {
        candidate.showDimensionality = true;
        candidate.showScreePlot = kind == ScaleAnalysisChildKind::ScreePlot;
        candidate.showLoadingPlot = kind == ScaleAnalysisChildKind::LoadingPlot;
    } else if (kind == ScaleAnalysisChildKind::ScaleScores ||
               kind == ScaleAnalysisChildKind::ScaleScoreDistributionPlot) {
        candidate.showScoreDistribution = true;
    } else if (kind == ScaleAnalysisChildKind::ItemDistributionsPlot) {
        candidate.showItemDistributions = true;
    } else if (kind == ScaleAnalysisChildKind::ItemRestPlot ||
               kind == ScaleAnalysisChildKind::ReliabilityIfDeletedPlot) {
        candidate.showItemPlots = true;
    }
    if (![self applyCandidate:std::move(candidate)]) return;

    auto &children = g_scaleAnalysisDerivedControllers[_analysisId];
    const int key = static_cast<int>(kind);
    auto existing = children.find(key);
    ScaleAnalysisDerivedWindowController *controller = nil;
    if (existing == children.end()) {
        controller = [[ScaleAnalysisDerivedWindowController alloc]
            initWithAnalysisId:_analysisId kind:kind];
        children[key] = controller;
    } else {
        controller = existing->second;
    }
    [controller show];
}

- (void)showAnalysisInformation:(id)sender
{
    (void)sender;
    ScaleAnalysisState *state = [self state];
    if (!state) return;
    std::ostringstream message;
    message << "Scale Analysis revision: " << state->specification.revision
            << "\nSpecification fingerprint: " << state->specification.fingerprint
            << "\nDataset: " << state->group
            << "\nItems: " << state->specification.items.size()
            << "\nCorrelation basis: " << state->specification.correlationBasis
            << "\nScore method: " << state->specification.scoreMethod
            << "\nBackend: " << state->result.backend
            << "\nImputations: " << state->result.imputationCount
            << "\n\n" << state->result.provenance;
    ShowWorkbenchMessageOnMain(@"Scale Analysis information",
        ToNSString(message.str()));
}

- (void)optionsChanged:(id)sender
{
    (void)sender; ScaleAnalysisState *state = [self state]; if (!state) return;
    ScaleAnalysisSpecification candidate = state->specification;
    NSInteger correlation = _correlationPopup.indexOfSelectedItem;
    candidate.correlationBasis = correlation == 1 ? "pearson" : correlation == 2 ? "polychoric" : correlation == 3 ? "mixed" : "auto";
    candidate.scoreMethod = _scorePopup.indexOfSelectedItem == 1 ? "sum" : "mean";
    [self applyCandidate:std::move(candidate)];
}

- (void)autoFitChanged:(id)sender
{
    (void)sender;
    ScaleAnalysisState *state = [self state];
    if (!state) return;
    const bool enabled = [_autoFitButton state] == NSControlStateValueOn;
    if (state->autoFit == enabled) return;
    state->autoFit = enabled;
    if (!enabled) {
        if (state->rFitPending && state->pendingRevision >= 0 &&
            !state->pendingFingerprint.empty()) {
            AcknowledgeScaleAnalysisMainRTask(
                state->id, state->pendingRevision, state->pendingFingerprint);
            state->rFitPending = false;
            state->pendingRevision = -1;
            state->pendingFingerprint.clear();
        }
        state->status = ScaleAnalysisHasCompletedResult(state->result)
            ? "Auto-fit is off. Displaying the last completed result; later changes are not fitted."
            : "Auto-fit is off. Changes will not be fitted until it is turned on.";
    } else if (rlispstat::core::ScaleAnalysisResultMatchesSpecification(
                   state->specification, state->result)) {
        state->status = state->result.summary;
    } else {
        RequestScaleAnalysisFitInMainR(*state);
    }
    [self refresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    if (_itemSelectorPanel) {
        if (_itemSelectorPanel.parentWindow == _window)
            [_window removeChildWindow:_itemSelectorPanel];
        [_itemSelectorPanel orderOut:nil];
    }
    auto children = g_scaleAnalysisDerivedControllers.find(_analysisId);
    if (children != g_scaleAnalysisDerivedControllers.end()) {
        std::vector<ScaleAnalysisDerivedWindowController *> open;
        for (const auto &entry : children->second) open.push_back(entry.second);
        for (ScaleAnalysisDerivedWindowController *controller : open) [controller close];
        g_scaleAnalysisDerivedControllers.erase(_analysisId);
    }
    g_scaleAnalysisControllers.erase(_analysisId);
}

