@implementation DendrogramView

- (NSString *)snapshotTabDelimitedText
{
    DendrogramState *state = [_controller state];
    if (!state) return @"";
    std::ostringstream text;
    text << "Dendrogram\nDistance\t" << state->distance
         << "\nLinkage\t" << state->linkage
         << "\nMissing-data handling\t" << state->missingMode
         << "\nVariables\t";
    for (std::size_t index = 0; index < state->variables.size(); ++index) {
        if (index) text << ", ";
        text << state->variables[index];
    }
    text << "\nCases\t" << state->caseRows.size();
    return ToNSString(text.str());
}

- (instancetype)initWithController:(DendrogramWindowController *)controller
{
    self = [super initWithFrame:NSMakeRect(0, 0, 760, 420)];
    if (self) {
        _controller = controller;
        [self setAutoresizingMask:NSViewNotSizable];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (BOOL)acceptsFirstResponder
{
    return YES;
}

- (NSSize)preferredContentSize
{
    DendrogramState *state = [_controller state];
    DendrogramSize size = DendrogramPreferredContentSize(state ? state->caseRows.size() : 0);
    if(state&&state->rotate270)std::swap(size.width,size.height);
    return NSMakeSize((CGFloat)size.width, (CGFloat)size.height);
}

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color align:(NSTextAlignment)align
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:align];
    [style setLineBreakMode:NSLineBreakByTruncatingTail];
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    };
}

- (void)publishSelection:(const std::set<int> &)rows mode:(const std::string &)mode
{
    DendrogramState *state = [_controller state];
    if (!state) return;
    int selectionVersion = 0;
    if (MergeSelection(state->group, rows, mode, &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    _geometry = DendrogramPlotGeometry();
    PlotThemeOverrideScope localTheme(PlotLocalThemeName(self));
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);

    DendrogramState *state = [_controller state];
    if (!state) return;

    NSDictionary *mutedAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:theme.mutedText align:NSTextAlignmentLeft];
    NSDictionary *leafAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:theme.text align:NSTextAlignmentCenter];

    const auto caption = rlispstat::core::DendrogramVariableCaptionLines(state->variables, NSWidth([self bounds]));
    for (std::size_t i=0;i<caption.size();++i)
        [ToNSString(caption[i]) drawInRect:NSMakeRect(20, 8+16*i, NSWidth([self bounds])-40, 16) withAttributes:mutedAttrs];
    const double captionHeight=caption.empty()?0.0:16.0*caption.size()+12.0;
    NSInteger n = (NSInteger)state->caseRows.size();
    if (n == 0) {
        [ToNSString((state->status.empty() ? rlispstat::core::DendrogramEmptyPlotStatus(state->variables.size()) : state->status)) drawInRect:NSMakeRect(20, 48+captionHeight, std::max(100.0, NSWidth([self bounds]) - 40.0), 120) withAttributes:mutedAttrs];
        return;
    }

    NSRect bounds = [self bounds];
    _geometry = BuildDendrogramPlotGeometry(
        state->caseRows,
        state->merges,
        state->leafOrder,
        bounds.size.width,
        bounds.size.height,
        state->verticalFlip,
        state->rowLabels,
        state->rotate270,
        state->rotateCaseLabels90, captionHeight);
    NSRect plotRect = rlispstat::platform::macos::ToNSRect(_geometry.plotRect);

    [theme.majorGrid setStroke];
    NSBezierPath *axes = [NSBezierPath bezierPath];
    [axes setLineWidth:1.0];
    [axes moveToPoint:NSMakePoint(plotRect.origin.x, plotRect.origin.y)];
    [axes lineToPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect))];
    [axes moveToPoint:NSMakePoint(plotRect.origin.x, NSMaxY(plotRect))];
    [axes lineToPoint:NSMakePoint(NSMaxX(plotRect), NSMaxY(plotRect))];
    [axes stroke];

    for (const DendrogramLeafGeometry &leaf : _geometry.leaves) {
        if (!leaf.showLabel) continue;
        NSRect rect=rlispstat::platform::macos::ToNSRect(leaf.labelRect);
        if(leaf.labelRotated90){[NSGraphicsContext saveGraphicsState];NSAffineTransform *transform=[NSAffineTransform transform];[transform translateXBy:NSMidX(rect) yBy:NSMidY(rect)];[transform rotateByDegrees:90];[transform concat];[ToNSString(leaf.label) drawInRect:NSMakeRect(-NSWidth(rect)*.5,-NSHeight(rect)*.5,NSWidth(rect),NSHeight(rect)) withAttributes:leafAttrs];[NSGraphicsContext restoreGraphicsState];}
        else [ToNSString(leaf.label) drawInRect:rect withAttributes:(state->rotate270?[self attrsWithSize:11 weight:NSFontWeightRegular color:theme.text align:NSTextAlignmentRight]:leafAttrs)];
    }

    std::set<int> selection;
    std::map<int, std::string> rowColors;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sit = g_groupSelections.find(state->group);
        if (sit != g_groupSelections.end()) selection = sit->second;
        rowColors = DisplayPointColorMap(state->group);
    }
    for (const DendrogramBranchSegment &segment : _geometry.branches) {
        const std::string color = DendrogramUniformBranchColor(
            segment, rowColors, {});
        const BOOL selected = DendrogramBranchIsFullySelected(segment, selection);
        NSColor *stroke = !color.empty() ? ColorForName(color, 1.0) :
            (selected ? theme.selectedMarkStroke : theme.axis);
        [stroke setStroke];
        NSBezierPath *branch = [NSBezierPath bezierPath];
        [branch setLineWidth:selected ? 3.0 : (!color.empty() ? 2.4 : 1.8)];
        [branch moveToPoint:NSMakePoint(segment.start.x, segment.start.y)];
        [branch lineToPoint:NSMakePoint(segment.end.x, segment.end.y)];
        [branch stroke];
    }
    BOOL hasSelection = !selection.empty();
    for (const DendrogramLeafGeometry &leaf : _geometry.leaves) {
        int row = leaf.rowId;
        NSPoint p = NSMakePoint(leaf.point.x, leaf.point.y);
        BOOL selected = selection.find(row) != selection.end();
        std::string rowColor;
        auto colorIt = rowColors.find(row);
        if (colorIt != rowColors.end()) rowColor = colorIt->second;
        if (rowColor.empty()) {
            auto grouped = state->colorByRowColors.find(row);
            if (grouped != state->colorByRowColors.end()) rowColor = grouped->second;
        }
        if (selected) {
            NSColor *selectedColor = theme.coordinatedMarks && rowColor.empty()
                ? theme.selectedMarkFill : ColorForName(rowColor.empty() ? "black" : rowColor, 1.0);
            [[selectedColor colorWithAlphaComponent:0.22] setFill];
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(p.x - 7.0, p.y - 7.0, 14.0, 14.0)] fill];
            [selectedColor setFill];
            const CGFloat radius = theme.coordinatedMarks ? 4.0 * (CGFloat)theme.selectedMarkScale : 4.0;
            NSBezierPath *dot = rowColor.empty()
                ? PlotThemeMarkPath(theme, p, radius, true)
                : [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(p.x - radius, p.y - radius,
                                                                    radius * 2.0, radius * 2.0)];
            [dot fill];
            [(theme.coordinatedMarks ? theme.selectedMarkStroke : [selectedColor colorWithAlphaComponent:0.90]) setStroke];
            [dot setLineWidth:theme.coordinatedMarks ? (CGFloat)theme.selectedMarkStrokeWidth : 0.9];
            [dot stroke];
        } else if (!rowColor.empty()) {
            [ColorForName(rowColor, hasSelection ? 0.36 : 0.78) setFill];
            NSBezierPath *dot = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(p.x - 3.4, p.y - 3.4, 6.8, 6.8)];
            [dot fill];
            [ColorForName(rowColor, hasSelection ? 0.26 : 0.58) setStroke];
            [dot setLineWidth:0.7];
            [dot stroke];
        } else {
            [(theme.coordinatedMarks
                ? (theme.hollowUnselectedMarks ? theme.panel : theme.markFill)
                : [NSColor colorWithCalibratedWhite:0.10 alpha:(hasSelection ? 0.24 : 0.74)]) setFill];
            NSBezierPath *dot = PlotThemeMarkPath(theme, p, 3.2, false);
            [dot fill];
            [(theme.coordinatedMarks ? theme.markStroke :
                [NSColor colorWithCalibratedWhite:0.02 alpha:(hasSelection ? 0.18 : 0.42)]) setStroke];
            [dot setLineWidth:theme.coordinatedMarks ? 1.0 : 0.6];
            [dot stroke];
        }
    }

    _legendRect = NSZeroRect;
    if (state->colorByLegendVisible && !state->colorByVariable.empty() &&
        rlispstat::core::DendrogramColorLegendMatchesLinkedRowColors(*state, rowColors) &&
        !state->colorByLegendItems.empty()) {
        std::size_t longest=state->colorByVariable.size();for(const auto& item:state->colorByLegendItems)longest=std::max(longest,item.first.size());const CGFloat legendWidth=std::max<CGFloat>(132.0,std::min<CGFloat>(260.0,72.0+7.2*longest));const CGFloat legendHeight=34.0+22.0*state->colorByLegendItems.size();CGFloat x=std::clamp<CGFloat>(state->colorByLegendX*NSWidth([self bounds]),4.0,std::max<CGFloat>(4.0,NSWidth([self bounds])-legendWidth-4.0));CGFloat y=std::clamp<CGFloat>(state->colorByLegendY*NSHeight([self bounds]),4.0,std::max<CGFloat>(4.0,NSHeight([self bounds])-legendHeight-4.0));_legendRect=NSMakeRect(x,y,legendWidth,legendHeight);
        [[theme.panel colorWithAlphaComponent:0.96] setFill];[theme.axis setStroke];NSBezierPath *legendBackground=[NSBezierPath bezierPathWithRoundedRect:_legendRect xRadius:4 yRadius:4];[legendBackground fill];[legendBackground setLineWidth:.8];[legendBackground stroke];[[theme.majorGrid colorWithAlphaComponent:.28] setFill];NSRectFill(NSMakeRect(x,y,legendWidth,30));
        NSDictionary *titleAttrs = [self attrsWithSize:11.5 weight:NSFontWeightSemibold color:theme.text align:NSTextAlignmentLeft];
        [ToNSString(state->colorByVariable) drawInRect:NSMakeRect(x+9,y+7,legendWidth-30,17) withAttributes:titleAttrs];
        [@"▾" drawInRect:NSMakeRect(NSMaxX(_legendRect)-20,y+7,14,17) withAttributes:titleAttrs];y+=34.0;
        NSDictionary *itemAttrs = [self attrsWithSize:10.5 weight:NSFontWeightRegular color:theme.text align:NSTextAlignmentLeft];
        for (const auto &entry : state->colorByLegendItems) {
            [ColorForName(entry.second, 0.90) setFill];
            [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(x+10,y+5,10,10)] fill];
            [ToNSString(entry.first) drawInRect:NSMakeRect(x+27,y+3,legendWidth-34,16) withAttributes:itemAttrs];y+=22.0;
        }
    }

    if (_dragging) {
        NSRect rr = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::RectBetweenPoints(
                rlispstat::platform::macos::ToCorePoint(_dragStart),
                rlispstat::platform::macos::ToCorePoint(_dragCurrent)));
        [[NSColor colorWithCalibratedRed:0.125 green:0.445 blue:0.705 alpha:0.16] setFill];
        NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        [[NSColor colorWithCalibratedRed:0.050 green:0.310 blue:0.520 alpha:0.95] setStroke];
        NSFrameRect(rr);
    }

    NSDictionary *axisAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:theme.mutedText align:NSTextAlignmentRight];
    if(state->rotate270){[ToNSString("0") drawInRect:NSMakeRect(NSMinX(plotRect)-8,NSMaxY(plotRect)+6,70,14) withAttributes:axisAttrs];[ToNSString(FormatDouble(_geometry.maxHeight,3)) drawInRect:NSMakeRect(NSMaxX(plotRect)-62,NSMaxY(plotRect)+6,70,14) withAttributes:axisAttrs];}
    else {const CGFloat zeroY=state->verticalFlip?plotRect.origin.y-7.0:NSMaxY(plotRect)-7.0;const CGFloat maxY=state->verticalFlip?NSMaxY(plotRect)-7.0:plotRect.origin.y-7.0;[ToNSString("0") drawInRect:NSMakeRect(8,zeroY,plotRect.origin.x-14.0,14.0) withAttributes:axisAttrs];[ToNSString(FormatDouble(_geometry.maxHeight,3)) drawInRect:NSMakeRect(8,maxY,plotRect.origin.x-14.0,14.0) withAttributes:axisAttrs];}
}

- (void)mouseDown:(NSEvent *)event
{
    [[self window] makeFirstResponder:self];
    NSPoint legendStart=[self convertPoint:[event locationInWindow] fromView:nil];
    if(!NSIsEmptyRect(_legendRect)&&NSPointInRect(legendStart,_legendRect)){
        DendrogramState *state=[_controller state];
        const CGFloat itemOffset = legendStart.y - NSMinY(_legendRect) - 34.0;
        if (state && itemOffset >= 0.0) {
            const NSInteger itemIndex = (NSInteger)std::floor(itemOffset / 22.0);
            if (itemIndex >= 0 &&
                (std::size_t)itemIndex < state->colorByLegendItems.size()) {
                const auto rows = DendrogramColorLegendRows(
                    *state, state->colorByLegendItems[(std::size_t)itemIndex].first);
                if (!rows.empty()) {
                    const NSEventModifierFlags flags = [event modifierFlags];
                    const std::string mode = rlispstat::core::EffectiveSelectionModeName(
                        (flags & NSEventModifierFlagOption) != 0,
                        (flags & NSEventModifierFlagCommand) != 0,
                        (flags & NSEventModifierFlagControl) != 0,
                        (flags & NSEventModifierFlagShift) != 0,
                        "replace");
                    [self publishSelection:rows mode:mode];
                }
                return;
            }
        }
        NSRect original=_legendRect;BOOL moved=NO;
        for(;;){NSEvent *next=[[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged|NSEventMaskLeftMouseUp) untilDate:[NSDate distantFuture] inMode:NSEventTrackingRunLoopMode dequeue:YES];if(!next||[next type]==NSEventTypeLeftMouseUp)break;NSPoint p=[self convertPoint:[next locationInWindow] fromView:nil];CGFloat dx=p.x-legendStart.x,dy=p.y-legendStart.y;if(std::hypot(dx,dy)>3)moved=YES;if(!moved)continue;CGFloat left=std::clamp<CGFloat>(NSMinX(original)+dx,4.0,std::max<CGFloat>(4.0,NSWidth([self bounds])-NSWidth(original)-4.0));CGFloat top=std::clamp<CGFloat>(NSMinY(original)+dy,4.0,std::max<CGFloat>(4.0,NSHeight([self bounds])-NSHeight(original)-4.0));state->colorByLegendX=left/std::max<CGFloat>(1,NSWidth([self bounds]));state->colorByLegendY=top/std::max<CGFloat>(1,NSHeight([self bounds]));[self setNeedsDisplay:YES];}
        if(!moved)[[self dendrogramLegendMenu] popUpMenuPositioningItem:nil atLocation:legendStart inView:self];return;
    }
    _dragging = YES;
    _dragStart = [self convertPoint:[event locationInWindow] fromView:nil];
    _dragCurrent = _dragStart;
    [self setNeedsDisplay:YES];

    while (_dragging) {
        NSEvent *trackingEvent = [[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                                                            untilDate:[NSDate distantFuture]
                                                               inMode:NSEventTrackingRunLoopMode
                                                              dequeue:YES];
        if (!trackingEvent) break;
        if ([trackingEvent type] == NSEventTypeLeftMouseDragged) {
            _dragCurrent = [self convertPoint:[trackingEvent locationInWindow] fromView:nil];
            [self setNeedsDisplay:YES];
        } else if ([trackingEvent type] == NSEventTypeLeftMouseUp) {
            [self finishSelectionWithEvent:trackingEvent];
            break;
        }
    }
}

- (void)mouseUp:(NSEvent *)event
{
    [self finishSelectionWithEvent:event];
}

- (void)finishSelectionWithEvent:(NSEvent *)event
{
    _dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!_dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    _dragging = NO;
    rlispstat::core::Rect brush = rlispstat::core::RectBetweenPoints(
        rlispstat::platform::macos::ToCorePoint(_dragStart),
        rlispstat::platform::macos::ToCorePoint(_dragCurrent));
    std::set<int> rows;
    DendrogramSelectionGestureResult hit = DendrogramSelectionRowsForGesture(
        _geometry,
        brush,
        rlispstat::platform::macos::ToCorePoint(_dragCurrent));
    for (int row : hit.rows) {
        rows.insert(row);
    }
    if (!rows.empty()) {
        const bool joinHit = !hit.usedBrush &&
            !DendrogramJoinRowsAtPoint(
                _geometry,
                rlispstat::platform::macos::ToCorePoint(_dragCurrent),
                9.0).empty();
        [self publishSelection:rows mode:(!hit.usedBrush && !joinHit) ? "toggle" : "replace"];
    } else {
        DendrogramState *state = [_controller state];
        if (state) {
            int version = 0;
            if (MergeSelection(state->group, std::set<int>(), "replace", &version)) {
                PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(), version);
            }
            [_controller refresh];
            UpdatePanelOnMain();
        } else {
            [self setNeedsDisplay:YES];
        }
    }
}

- (void)rightMouseDown:(NSEvent *)event
