        NSMenuItem *fitTree = [[NSMenuItem alloc] initWithTitle:@"Fit tree to window" action:@selector(toggleFitTreeToWindow:) keyEquivalent:@""];
        [fitTree setTarget:_controller];
        [fitTree setState:_controller.fitTreeToWindow ? NSControlStateValueOn : NSControlStateValueOff];
        [displayMenu addItem:fitTree];
        NSMenuItem *distanceRoot = [[NSMenuItem alloc] initWithTitle:@"Distance" action:nil keyEquivalent:@""];
        NSMenu *distanceMenu = [[NSMenu alloc] initWithTitle:@"Distance"];
