                                                          action:@selector(setDendrogramDistance:)
                                                   keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:metric];
            [item setState:state->distance == std::string([metric UTF8String])
                ? NSControlStateValueOn : NSControlStateValueOff];
            [distanceMenu addItem:item];
        }
        [distanceRoot setSubmenu:distanceMenu];
        [displayMenu addItem:distanceRoot];
        NSMenu *labelsMenu = [[NSMenu alloc] initWithTitle:@"Leaf labels"];
        NSMenuItem *rowNumbers = [[NSMenuItem alloc] initWithTitle:@"Row numbers" action:@selector(setDendrogramLabelVariable:) keyEquivalent:@""];
        [rowNumbers setTarget:self]; [rowNumbers setRepresentedObject:@"."];
        [rowNumbers setState:state->labelVariable.empty() ? NSControlStateValueOn : NSControlStateValueOff];
        [labelsMenu addItem:rowNumbers];
        if (dataframe) for (const DataColumn &column : dataframe->columns) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name) action:@selector(setDendrogramLabelVariable:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:ToNSString(column.name)];
            [item setState:state->labelVariable == column.name ? NSControlStateValueOn : NSControlStateValueOff];
            [labelsMenu addItem:item];
        }
        [displayMenu setSubmenu:labelsMenu forItem:labelsRoot]; [displayMenu addItem:labelsRoot];
        NSMenuItem *rotate = [[NSMenuItem alloc] initWithTitle:@"Rotate dendrogram 270°" action:@selector(rotateDendrogram270:) keyEquivalent:@""];
        [rotate setTarget:self]; [rotate setState:state->rotate270 ? NSControlStateValueOn : NSControlStateValueOff]; [displayMenu addItem:rotate];
        NSMenuItem *rotateLabels = [[NSMenuItem alloc] initWithTitle:@"Rotate case labels 90°" action:@selector(rotateDendrogramLabels90:) keyEquivalent:@""];
        [rotateLabels setTarget:self]; [rotateLabels setState:state->rotateCaseLabels90 ? NSControlStateValueOn : NSControlStateValueOff]; [displayMenu addItem:rotateLabels];
        NSMenuItem *legendRoot=[[NSMenuItem alloc] initWithTitle:@"Color legend" action:nil keyEquivalent:@""];[legendRoot setSubmenu:[self dendrogramLegendMenu]];[legendRoot setEnabled:!state->colorByVariable.empty()];[displayMenu addItem:legendRoot];
        [menu setSubmenu:displayMenu forItem:displayRoot]; [menu addItem:displayRoot];

        NSMenuItem *groupRoot = [[NSMenuItem alloc] initWithTitle:@"Group / Condition" action:nil keyEquivalent:@""];
        NSMenu *groupMenu = [[NSMenu alloc] initWithTitle:@"Group / Condition"];
        NSMenuItem *colorRoot = [[NSMenuItem alloc] initWithTitle:@"Override colors by" action:nil keyEquivalent:@""];
        NSMenu *colorMenu = [[NSMenu alloc] initWithTitle:@"Override colors by"];
        NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:@"Cancel color override" action:@selector(setDendrogramColorByVariable:) keyEquivalent:@""];
        [none setTarget:self]; [none setRepresentedObject:@"."]; [none setState:state->colorByVariable.empty() ? NSControlStateValueOn : NSControlStateValueOff]; [colorMenu addItem:none];
        if (dataframe) for (const DataColumn &column : dataframe->columns) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name) action:@selector(setDendrogramColorByVariable:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:ToNSString(column.name)];
            [item setState:state->colorByVariable == column.name ? NSControlStateValueOn : NSControlStateValueOff];
            [colorMenu addItem:item];
        }
        [groupMenu setSubmenu:colorMenu forItem:colorRoot]; [groupMenu addItem:colorRoot];
        [menu setSubmenu:groupMenu forItem:groupRoot]; [menu addItem:groupRoot];
        NSMenuItem *analyzeRoot = [[NSMenuItem alloc] initWithTitle:@"Analyze" action:nil keyEquivalent:@""];
        NSMenu *analyzeMenu = [[NSMenu alloc] initWithTitle:@"Analyze"];
        NSMenuItem *matrixItem = [[NSMenuItem alloc] initWithTitle:@"Distance matrix…"
            action:@selector(openDendrogramDistanceMatrix:) keyEquivalent:@""];
        [matrixItem setTarget:self];
        [matrixItem setEnabled:!state->rFitPending && state->caseRows.size() >= 2];
        [analyzeMenu addItem:matrixItem];
        [analyzeRoot setSubmenu:analyzeMenu]; [menu addItem:analyzeRoot];
        [menu addItem:[NSMenuItem separatorItem]];
    }

    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.exportTitle)
                                                        action:nil
                                                 keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.exportTitle)];
    WindowNotesContainer *notes = WindowNotesContainerForView(self);
    if (notes) {
        NSMenuItem *includeNotes = PlotCommandMenuItem(@"Include Notes", @"NOTES_INCLUDE_EXPORT");
        [includeNotes setEnabled:[notes hasNotes]];
        [includeNotes setState:[notes includeNotes] ? NSControlStateValueOn : NSControlStateValueOff];
        [exportMenu addItem:includeNotes];
        [exportMenu addItem:[NSMenuItem separatorItem]];
    }
    const auto exportActions = rlispstat::core::BuildExportMenuActions(
        rlispstat::core::StandardVisualExportCapabilities(rlispstat::core::ExportPlatform::MacOS),
        rlispstat::core::ExportPlatform::MacOS);
    for (const auto &action : exportActions) {
        if (action.separatorBefore) [exportMenu addItem:[NSMenuItem separatorItem]];
        SEL selector = nullptr;
        if (action.capability == rlispstat::core::ExportCapability::CopyPdf) selector = @selector(copyDendrogramPDF:);
        else if (action.capability == rlispstat::core::ExportCapability::CopySvg) selector = @selector(copyDendrogramSVG:);
        else if (action.capability == rlispstat::core::ExportCapability::CopyPng) selector = @selector(copyDendrogramPNG:);
        else if (action.capability == rlispstat::core::ExportCapability::SaveSvg) selector = @selector(saveDendrogramSVG:);
        else if (action.capability == rlispstat::core::ExportCapability::SavePdf) selector = @selector(saveDendrogramPDF:);
        else if (action.capability == rlispstat::core::ExportCapability::SavePng) selector = @selector(saveDendrogramPNG:);
        if (!selector) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(action.title) action:selector keyEquivalent:@""];
        [item setTarget:self];
        [exportMenu addItem:item];
    }
    if (state && !state->id.empty()) {
        AddRCodeExportItems(exportMenu, "output", state->id, false);
    }
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    AddPlotThemeSubmenu(menu, self);
    if (WindowNotesContainer *notes = WindowNotesContainerForView(self)) [menu addItem:[notes annotateContextMenuItem]];
    AddSnapshotAlbumContextItems(menu);
    return FinalizeGraphContextMenu(menu);
}

- (void)setDendrogramLabelVariable:(id)sender
{
    DendrogramState *state = [_controller state];
    const DataFrameModel *dataframe = state ? FindDataFrameUnlockedConst(state->group) : nullptr;
    NSString *value = [sender representedObject];
    if (!state || !dataframe || !value) return;
    std::string error;
    if (SetDendrogramLabelVariable(*state, *dataframe, std::string([value UTF8String]), &error)) {
        state->labelVariableConfigured = true;
        [_controller refresh];
    }
}

- (void)setDendrogramDistance:(id)sender
{
    DendrogramState *state = [_controller state];
    NSString *metric = [sender representedObject];
    if (!state || !metric) return;
    const std::string value([metric UTF8String]);
    if (!rlispstat::core::DendrogramDistanceIsValid(value) || state->distance == value) return;
    state->distance = value;
    RefitDendrogramState(*state);
    [_controller refresh];
}

- (void)openDendrogramDistanceMatrix:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state || state->rFitPending || state->caseRows.size() < 2) return;
    rlispstat::core::MainRDendrogramTask task;
    task.id = state->id; task.group = state->group;
    task.revision = state->requestRevision;
    task.dataVersion = state->sourceDataVersion;
    task.distanceMatrix = true;
    {
        std::lock_guard<std::mutex> lock(g_dendrogramTaskMutex);
        g_pendingDendrogramTasks.push_back(std::move(task));
    }
    NotifyMainRTaskAvailable();
}

- (void)setDendrogramColorByVariable:(id)sender
{
    DendrogramState *state = [_controller state];
    const DataFrameModel *dataframe = state ? FindDataFrameUnlockedConst(state->group) : nullptr;
    NSString *value = [sender representedObject];
    if (!state || !dataframe || !value) return;
    std::string error;
    const std::string variable([value UTF8String]);
    std::map<int, std::string> before;
    std::map<int, std::string> after;
    bool ok = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto &application = MacCommandDispatcher().applicationState();
        for (const auto &entry : application.displayPointColors(state->group)) before[entry.first] = entry.second;
        ok = application.setColorOverride(state->group, variable, &error);
        if (ok) {
            for (auto &[id, linked] : application.dendrograms()) {
                if (linked.group == state->group)
                    SetDendrogramColorByVariable(linked, *dataframe, variable, nullptr);
            }
            for (const auto &entry : application.displayPointColors(state->group)) after[entry.first] = entry.second;
        }
    }
    if (ok) {
        std::vector<int> changedRows;
        for (const auto &[row, color] : before)
            if (after.find(row) == after.end() || after[row] != color) changedRows.push_back(row);
        for (const auto &[row, color] : after)
            if (before.find(row) == before.end()) changedRows.push_back(row);
        std::sort(changedRows.begin(), changedRows.end());
        changedRows.erase(std::unique(changedRows.begin(), changedRows.end()), changedRows.end());
        [_controller refresh];
        PublishSpreadPlotMessage("ROW_COLORS_CHANGED", state->group,
            state->id, "", changedRows, 0);
        RedrawGroupViewsSynchronouslyOnMain(state->group, true);
        UpdatePanelOnMain();
    } else if (!error.empty()) {
        ShowWorkbenchMessageOnMain(@"Override Colors", ToNSString(error));
    }
}

