- (void)setDendrogramLegendPosition:(id)sender
{
    DendrogramState *state=[_controller state];NSString *position=[sender representedObject];if(!state||!position)return;
    if([position isEqualToString:@"top_left"]){state->colorByLegendX=.08;state->colorByLegendY=.10;}else if([position isEqualToString:@"top_right"]){state->colorByLegendX=.72;state->colorByLegendY=.10;}else if([position isEqualToString:@"bottom_left"]){state->colorByLegendX=.08;state->colorByLegendY=.68;}else{state->colorByLegendX=.72;state->colorByLegendY=.68;}[_controller refresh];
}

- (NSMenu *)dendrogramLegendMenu
{
    NSMenu *menu=[[NSMenu alloc] initWithTitle:@"Color legend"];NSMenuItem *hide=[[NSMenuItem alloc] initWithTitle:@"Hide legend" action:@selector(toggleDendrogramColorLegend:) keyEquivalent:@""];[hide setTarget:self];[menu addItem:hide];[menu addItem:[NSMenuItem separatorItem]];for(NSArray *entry in @[@[@"Top left",@"top_left"],@[@"Top right",@"top_right"],@[@"Bottom left",@"bottom_left"],@[@"Bottom right",@"bottom_right"]]){NSMenuItem *item=[[NSMenuItem alloc] initWithTitle:entry[0] action:@selector(setDendrogramLegendPosition:) keyEquivalent:@""];[item setTarget:self];[item setRepresentedObject:entry[1]];[menu addItem:item];}return menu;
}

- (void)showDendrogramSavePanelForFormat:(NSString *)format
{
    NSString *extension = [[format lowercaseString] copy];
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setTitle:ToNSString(DendrogramExportPanelTitle(std::string([format UTF8String])))];
    [panel setNameFieldStringValue:ToNSString(DendrogramDefaultExportFilename(std::string([format UTF8String])))];
    SetSavePanelExtensionCompat(panel, extension);
    if ([panel runModal] != NSModalResponseOK) return;
    BOOL ok = [format isEqualToString:@"SVG"] ? [self saveSVGToPath:[panel URL].path] :
        ([format isEqualToString:ToNSString(rlispstat::core::DendrogramPDFOptionIdentifier())]
            ? [self savePDFToPath:[panel URL].path]
            : [self savePNGToPath:[panel URL].path]);
    if (!ok) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DendrogramExportWindowTitle()), ToNSString(DendrogramExportFailedMessage()));
    }
}

- (BOOL)copyDendrogramFormat:(NSString *)format
{
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    if ([format isEqualToString:ToNSString(rlispstat::core::DendrogramPDFOptionIdentifier())]) {
        NSData *data = VisualExportDataForView(self, @"PDF");
        return [pasteboard setData:data forType:NSPasteboardTypePDF];
    }
    if ([format isEqualToString:@"SVG"]) {
        const std::string source = ComposeSvgExportForView(self, [self dendrogramSvgDocument]);
        NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
        BOOL ok = [pasteboard setData:data forType:@"public.svg-image"];
        [pasteboard setString:ToNSString(source) forType:NSPasteboardTypeString];
        return ok;
    }
    NSData *data = VisualExportDataForView(self, @"PNG");
    return data ? [pasteboard setData:data forType:NSPasteboardTypePNG] : NO;
}

- (void)saveDendrogramPNG:(id)sender
