- (BOOL)saveSVGToPath:(NSString *)path
{
    const std::string source = ComposeSvgExportForView(self, [self dendrogramSvgDocument]);
    NSData *data = [NSData dataWithBytes:source.data() length:source.size()];
    return [data writeToFile:path atomically:YES];
}

- (std::string)dendrogramSvgDocument
{
    DendrogramState *state = [_controller state];
    const NSRect bounds = [self bounds];
    rlispstat::core::SvgWriter svg({bounds.size.width, bounds.size.height, 2.0});
    const auto style = rlispstat::core::PlotThemeStyleForName(
        std::string([PlotEffectiveThemeName(self) UTF8String]));
    auto hex = [](const rlispstat::core::PlotRGBA &color) {
        char buffer[16];
        std::snprintf(buffer, sizeof(buffer), "#%02X%02X%02X",
            (int)std::llround(std::max(0.0, std::min(1.0, color.r)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.g)) * 255.0),
            (int)std::llround(std::max(0.0, std::min(1.0, color.b)) * 255.0));
        return std::string(buffer);
    };
    svg.rectangle(0, 0, bounds.size.width, bounds.size.height, {hex(style.background), "none", 0, 1, {}});
    if (!state) return svg.finish();
    const auto caption=rlispstat::core::DendrogramVariableCaptionLines(state->variables,bounds.size.width);
    rlispstat::core::SvgTextStyle captionStyle; captionStyle.fontSize=12; captionStyle.fill=hex(style.mutedText);
    for(std::size_t i=0;i<caption.size();++i) svg.text(20,20+16*i,caption[i],captionStyle);
    const double captionHeight=caption.empty()?0.0:16.0*caption.size()+12.0;
    if (state->caseRows.empty()) return svg.finish();
    const DendrogramPlotGeometry geometry = BuildDendrogramPlotGeometry(
        state->caseRows, state->merges, state->leafOrder, bounds.size.width, bounds.size.height,
        state->verticalFlip, state->rowLabels, state->rotate270, state->rotateCaseLabels90, captionHeight);
    const rlispstat::core::Rect &plot = geometry.plotRect;
    svg.line(plot.x, plot.y, plot.x, plot.y + plot.height, {"none", hex(style.majorGrid), 1, 1, {}});
    svg.line(plot.x, plot.y + plot.height, plot.x + plot.width, plot.y + plot.height,
             {"none", hex(style.majorGrid), 1, 1, {}});
    svg.beginClipRect(plot.x, plot.y, plot.width, plot.height);
    std::set<int> selection;
    std::map<int, std::string> rowColors;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto selected = g_groupSelections.find(state->group);
        if (selected != g_groupSelections.end()) selection = selected->second;
        rowColors = DisplayPointColorMap(state->group);
    }
    for (const DendrogramBranchSegment &segment : geometry.branches) {
        const std::string color = DendrogramUniformBranchColor(
            segment, rowColors, {});
        const bool selected = DendrogramBranchIsFullySelected(segment, selection);
        const std::string stroke = !color.empty()
            ? hex(rlispstat::core::PlotColorForNameOrHex(color))
            : hex(selected ? style.selectedMarkStroke : style.axis);
        svg.line(segment.start.x, segment.start.y, segment.end.x, segment.end.y,
                 {"none", stroke, selected ? 3.0 : (!color.empty() ? 2.4 : 1.8), 1, {}});
    }
    for (const DendrogramLeafGeometry &leaf : geometry.leaves) {
        std::string color;
        auto manual = rowColors.find(leaf.rowId);
        if (manual != rowColors.end()) color = manual->second;
        const auto fill = color.empty() ? style.geomFill : rlispstat::core::PlotColorForNameOrHex(color);
        const auto stroke = color.empty() ? style.geomStroke : rlispstat::core::PlotColorForNameOrHex(color, 0.75);
        svg.ellipse(leaf.point.x, leaf.point.y, 3.2, 3.2,
                    {hex(fill), hex(stroke), 0.8, 1, {}});
    }
    svg.endClip();
    rlispstat::core::SvgTextStyle label{hex(style.text), "Arial, Helvetica, sans-serif", 11, 400, false, "middle"};
    for (const DendrogramLeafGeometry &leaf : geometry.leaves) {
        if (!leaf.showLabel) continue;label.anchor=state->rotate270&&!leaf.labelRotated90?"end":"middle";const double tx=leaf.labelRotated90?leaf.labelRect.x+leaf.labelRect.width*.5:(state->rotate270?leaf.labelRect.x+leaf.labelRect.width:leaf.point.x);const double ty=leaf.labelRotated90?leaf.labelRect.y+leaf.labelRect.height*.5+3.5:leaf.labelRect.y+11.0;svg.text(tx,ty,leaf.label,label,leaf.labelRotated90?90.0:0.0);
    }
    if (state->colorByLegendVisible && !state->colorByVariable.empty() &&
        rlispstat::core::DendrogramColorLegendMatchesLinkedRowColors(*state, rowColors)) {
        std::size_t longest=state->colorByVariable.size();for(const auto& item:state->colorByLegendItems)longest=std::max(longest,item.first.size());const double legendWidth=std::max(132.0,std::min(260.0,72.0+7.2*longest));const double legendHeight=34.0+22.0*state->colorByLegendItems.size();double x=std::clamp(state->colorByLegendX*bounds.size.width,4.0,std::max(4.0,bounds.size.width-legendWidth-4.0)),y=std::clamp(state->colorByLegendY*bounds.size.height,4.0,std::max(4.0,bounds.size.height-legendHeight-4.0));svg.rectangle(x,y,legendWidth,legendHeight,{hex(style.panel),hex(style.axis),.8,1,{}});
        rlispstat::core::SvgTextStyle legendTitle{hex(style.text), "Arial, Helvetica, sans-serif", 11.5, 600, false, "start"};
        rlispstat::core::SvgTextStyle legendItem{hex(style.text), "Arial, Helvetica, sans-serif", 10.5, 400, false, "start"};
        svg.text(x+9, y + 20.0, state->colorByVariable, legendTitle); y += 34.0;
        for (const auto &entry : state->colorByLegendItems) {
            svg.ellipse(x + 15.0, y + 10.0, 5.0, 5.0,
                        {hex(rlispstat::core::PlotColorForNameOrHex(entry.second)), "none", 0, 1, {}});
            svg.text(x + 27.0, y + 14.0, entry.first, legendItem); y += 22.0;
        }
    }
    rlispstat::core::SvgTextStyle axis{hex(style.mutedText), "Arial, Helvetica, sans-serif", 11, 400, false, "end"};
    if(state->rotate270){svg.text(plot.x,plot.y+plot.height+18,"0",axis);svg.text(plot.x+plot.width,plot.y+plot.height+18,FormatDouble(geometry.maxHeight,3),axis);}else{svg.text(plot.x-8,state->verticalFlip?plot.y+4:plot.y+plot.height+4,"0",axis);svg.text(plot.x-8,state->verticalFlip?plot.y+plot.height+4:plot.y+4,FormatDouble(geometry.maxHeight,3),axis);}
    return svg.finish();
}

- (void)keyDown:(NSEvent *)event
{
    NSString *chars = [[event charactersIgnoringModifiers] lowercaseString];
    if ([chars isEqualToString:@"i"]) {
        [self invertDisplayedDendrogramSelection:nil];
        return;
    }
    [super keyDown:event];
}

- (void)openDendrogramPalette:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (state) {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
    ShowPaletteOnMain(true);
}

- (void)selectAllDisplayedCases:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::set<int> rows(state->caseRows.begin(), state->caseRows.end());
    int version = 0;
    if (MergeSelection(state->group, rows, "replace", &version)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(rows.begin(), rows.end()), version);
    }
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)invertDisplayedDendrogramSelection:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::set<int> current;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(state->group);
        if (it != g_groupSelections.end()) current = it->second;
    }
    std::set<int> inverted;
    for (int row : state->caseRows) {
        if (current.find(row) == current.end()) inverted.insert(row);
    }
    int version = 0;
    if (MergeSelection(state->group, inverted, "replace", &version)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(inverted.begin(), inverted.end()), version);
    }
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)clearDendrogramSelection:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::set<int> rows;
    int version = 0;
    if (MergeSelection(state->group, rows, "replace", &version)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", state->group, state->id, "", std::vector<int>(), version);
    }
    [_controller refresh];
    UpdatePanelOnMain();
}

- (void)colorSelectedDendrogramCases:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    std::vector<int> rows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(state->group);
        if (it != g_groupSelections.end()) rows.assign(it->second.begin(), it->second.end());
    }
    ApplyColorToRows(state->group, rows, SelectedColorForGroup(state->group));
}

- (void)resetSelectedDendrogramColors:(id)sender
{
    (void)sender;
    DendrogramState *state = [_controller state];
    if (!state) return;
    auto prepared = PreparePersistentColorsForManualEdit(state->group);
    if (!prepared) return;
    std::vector<int> rows = std::move(*prepared);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sit = g_groupSelections.find(state->group);
        std::vector<int> selected;
        if (sit != g_groupSelections.end()) selected.assign(sit->second.begin(), sit->second.end());
        auto cit = g_groupPointColors.find(state->group);
        if (cit != g_groupPointColors.end()) {
            for (int row : selected) cit->second.erase(row);
        }
        rows.insert(rows.end(), selected.begin(), selected.end());
        std::sort(rows.begin(), rows.end());
        rows.erase(std::unique(rows.begin(), rows.end()), rows.end());
        if (!selected.empty()) {
            RequestColorSmoothRecomputeForGroupUnlocked(state->group);
        }
    }
    PublishSpreadPlotMessage("ROW_COLORS_CHANGED", state->group, state->id, "", rows);
    [_controller refresh];
    UpdatePanelOnMain();
}

@end

@implementation DendrogramWindowController

- (instancetype)initWithDendrogramId:(const std::string &)dendrogramId
{
    self = [super init];
    if (self) {
        _dendrogramId = dendrogramId;
        _fitTreeToWindow = YES;
        NSRect frame = NextWindowFrameOnMain(820, 560);
        _window = [[NSWindow alloc]
            initWithContentRect:frame
                      styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                        backing:NSBackingStoreBuffered
                          defer:NO];
        [_window setDelegate:self];
        [_window setTitle:ToNSString(DendrogramWindowTitle())];
        NSView *content = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 820, 560)];
        [content setWantsLayer:YES];
        [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];
        [_window setContentView:content];

        _titleField = GLMLabel(ToNSString(DendrogramWindowTitle()), NSMakeRect(16, 522, 320, 24), 17, NSFontWeightSemibold);
        [content addSubview:_titleField];
        _badgeField = GLMRightLabel(@"", NSMakeRect(650, 524, 150, 20), 12, NSFontWeightMedium);
        [content addSubview:_badgeField];

        _linkageLabel = GLMLabel(ToNSString(DendrogramLinkageControlLabel()), NSMakeRect(16, 490, 66, 22), 12, NSFontWeightRegular);
        [content addSubview:_linkageLabel];
        _linkagePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(82, 490, 110, 24)];
        [_linkagePopup addItemWithTitle:ToNSString(rlispstat::core::DendrogramAverageLinkageTitle())];
        [_linkagePopup addItemWithTitle:ToNSString(rlispstat::core::DendrogramCompleteLinkageTitle())];
        [_linkagePopup addItemWithTitle:ToNSString(rlispstat::core::DendrogramSingleLinkageTitle())];
        [_linkagePopup setTarget:self];
        [_linkagePopup setAction:@selector(linkageChanged:)];
        [content addSubview:_linkagePopup];

        _missingLabel = GLMLabel(ToNSString(DendrogramMissingDataControlLabel()), NSMakeRect(212, 490, 86, 22), 12, NSFontWeightRegular);
        [content addSubview:_missingLabel];
        _missingPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(300, 490, 126, 24)];
        [_missingPopup addItemWithTitle:ToNSString(rlispstat::core::MissingDataPairwiseMethodLabel())];
        [_missingPopup addItemWithTitle:ToNSString(rlispstat::core::MissingDataListwiseMethodLabel())];
        [_missingPopup setTarget:self];
        [_missingPopup setAction:@selector(missingModeChanged:)];
        [content addSubview:_missingPopup];

        _distanceLabel = GLMLabel(ToNSString(DendrogramDistanceControlLabel("euclidean")), NSMakeRect(448, 490, 170, 22), 12, NSFontWeightRegular);
        [content addSubview:_distanceLabel];

        _variablesButton = [[LinkEDASecondaryActionButton alloc] initWithFrame:NSMakeRect(630, 490, 170, 24)];
        [_variablesButton setTitle:ToNSString(DendrogramVariablesButtonTitle(0))];
        [_variablesButton setBordered:NO];
        [_variablesButton setAlignment:NSTextAlignmentLeft];
        [_variablesButton setFont:[NSFont systemFontOfSize:11 weight:NSFontWeightSemibold]];
        [_variablesButton setContentTintColor:[NSColor colorWithCalibratedWhite:0.48 alpha:1.0]];
        [_variablesButton setTarget:self];
        [_variablesButton setAction:@selector(showVariablesMenu:)];
        __block DendrogramWindowController *blockSelf = self;
        [(LinkEDASecondaryActionButton *)_variablesButton setSecondaryAction:^{
            [blockSelf showSearchableVariablesSelector];
        }];
        [content addSubview:_variablesButton];

        _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 44, 796, 436)];
        [_scrollView setHasVerticalScroller:YES];
        [_scrollView setHasHorizontalScroller:YES];
        [_scrollView setAutohidesScrollers:YES];
        [_scrollView setScrollerStyle:NSScrollerStyleLegacy];
        [_scrollView setBorderType:NSNoBorder];
        [_scrollView setDrawsBackground:NO];
        _dendrogramView = [[DendrogramView alloc] initWithController:self];
        [_scrollView setDocumentView:_dendrogramView];
        [content addSubview:_scrollView];

        _statusField = GLMLabel(@"", NSMakeRect(16, 14, 790, 20), 12, NSFontWeightRegular);
        [content addSubview:_statusField];
    }
    return self;
