- (DendrogramState *)state
{
    auto it = g_dendrograms.find(_dendrogramId);
    if (it == g_dendrograms.end()) return nullptr;
    return &it->second;
}

- (void)show
{
    DendrogramState *state = [self state];
    EnableNotesForWindow(_window, _dendrogramId, @"this dendrogram",
                         state ? state->group : std::string{});
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)refresh
{
    DendrogramState *state = [self state];
    if (!state) return;
    if (!state->labelVariableConfigured) {
        const std::string label = MacCommandDispatcher().applicationState().labelColumn(state->group);
        const DataFrameModel *dataframe = FindDataFrameUnlockedConst(state->group);
        if (dataframe && !label.empty()) SetDendrogramLabelVariable(*state, *dataframe, label);
    }
    [_badgeField setStringValue:ToNSString(state->group)];
    [_linkagePopup selectItemWithTitle:ToNSString(state->linkage)];
    [_missingPopup selectItemWithTitle:ToNSString(state->missingMode)];
    [_distanceLabel setStringValue:ToNSString(DendrogramDistanceControlLabel(state->distance))];

    [_window setContentMinSize:NSMakeSize(700.0, 420.0)];
    NSSize currentSize = [[_window contentView] frame].size;
    // Lay out the current window; refits and selections must not resize it.
    DendrogramWindowLayout windowLayout = BuildDendrogramWindowLayout(
        currentSize.width - 24.0, currentSize.height - 124.0,
        currentSize.width / 0.94, currentSize.height / 0.88);

    [_titleField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.titleRect)];
    [_badgeField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.badgeRect)];
    [_linkageLabel setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.linkageLabelRect)];
    [_linkagePopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.linkagePopupRect)];
    [_missingLabel setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.missingLabelRect)];
    [_missingPopup setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.missingPopupRect)];
    [_distanceLabel setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.distanceLabelRect)];
    [_variablesButton setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.variablesButtonRect)];
    [_scrollView setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.scrollViewRect)];
    [_statusField setFrame:rlispstat::platform::macos::ToNSRect(windowLayout.statusRect)];

    NSSize visible = [_scrollView contentSize];
    [_scrollView setHasHorizontalScroller:!_fitTreeToWindow];
    [_scrollView setHasVerticalScroller:!_fitTreeToWindow];
    visible = [_scrollView contentSize];
    auto canvas = rlispstat::core::DendrogramViewportContentSize(
        state->caseRows.size(), visible.width, visible.height, _fitTreeToWindow, state->rotate270);
    const double captionMinimumHeight=260.0+16.0*rlispstat::core::DendrogramVariableCaptionLines(state->variables,canvas.width).size();
    [_scrollView setHasVerticalScroller:(!_fitTreeToWindow || captionMinimumHeight>visible.height)];
    [_dendrogramView setFrame:NSMakeRect(0, 0,
                                         canvas.width, std::max(canvas.height, 260.0 + 16.0 * rlispstat::core::DendrogramVariableCaptionLines(state->variables,canvas.width).size()))];
    [_dendrogramView setNeedsDisplay:YES];
    [_variablesButton setTitle:ToNSString(DendrogramVariablesButtonTitle(state->variables.size()))];
    std::string status = DendrogramWindowSummaryStatus(
        state->group, state->caseRows.size(), state->variables.size(),
        state->linkage, state->missingMode, SelectionCount(state->group));
    if (state->dataScopeCaptured) {
        status += " · " + rlispstat::core::AnalysisScopeWindowSummary(
            state->dataScope, state->dataScope.totalDatasetRows);
    }
    if (!state->status.empty()) status += " · " + state->status;
    [_statusField setStringValue:ToNSString(status)];
}

- (void)windowDidResize:(NSNotification *)notification
{
    (void)notification;
    [self refresh];
}

- (void)toggleFitTreeToWindow:(id)sender
{
    (void)sender;
    _fitTreeToWindow = !_fitTreeToWindow;
    [self refresh];
    [[_scrollView contentView] scrollToPoint:NSZeroPoint];
    [_scrollView reflectScrolledClipView:[_scrollView contentView]];
}

- (void)linkageChanged:(id)sender
{
    (void)sender;
    DendrogramState *state = [self state];
    if (!state) return;
    state->linkage = std::string([[[_linkagePopup selectedItem] title] UTF8String]);
    if (!rlispstat::core::DendrogramLinkageIsValid(state->linkage)) {
        state->linkage = "average";
    }
    RefitDendrogramState(*state);
    [self refresh];
}

- (void)missingModeChanged:(id)sender
{
    (void)sender;
    DendrogramState *state = [self state];
    if (!state) return;
    state->missingMode = std::string([[[_missingPopup selectedItem] title] UTF8String]);
    if (state->missingMode != "pairwise" && state->missingMode != "listwise") {
        state->missingMode = "pairwise";
    }
    RefitDendrogramState(*state);
    [self refresh];
}

- (void)showVariablesMenu:(id)sender
{
    (void)sender;
    DendrogramState *state = [self state];
    if (!state) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(DendrogramVariableMenuTitle())];
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state->seed);
    DendrogramVariableMenuState menuState = BuildDendrogramVariableMenuState(
        state->variables, numeric);
    NSMenu *removeMenu = [[NSMenu alloc] initWithTitle:@"Remove variable"];
    for (const DendrogramVariableMenuItem &entry : menuState.items) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(entry.variable)
                                                      action:@selector(toggleVariableFromMenu:)
                                               keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(entry.variable)];
        [item setEnabled:entry.enabled];
        [(entry.included ? removeMenu : menu) addItem:item];
    }
    if ([removeMenu numberOfItems] > 0) {
        if ([menu numberOfItems] > 0) [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:@"Remove variable" action:nil keyEquivalent:@""];
        [remove setSubmenu:removeMenu];[menu addItem:remove];
    }
    if ([[menu itemArray] count] == 0) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.emptyTitle)
                                                        action:nil
                                                 keyEquivalent:@""];
        [empty setEnabled:NO];
        [menu addItem:empty];
    }
    NSView *content = [_window contentView];
    NSRect frame = [_variablesButton frame];
    [menu popUpMenuPositioningItem:nil
                        atLocation:NSMakePoint(NSMinX(frame), NSMaxY(frame))
                            inView:content];
}

- (void)showSearchableVariablesSelector
{
    DendrogramState *state = [self state];
    if (!state) return;
    const auto numeric = rlispstat::core::NumericVariableNames(&state->seed);
    const auto menuState = BuildDendrogramVariableMenuState(state->variables, numeric);
    std::vector<std::string> choices;
    for (const auto &entry : menuState.items)
        if (!entry.included && entry.enabled) choices.push_back(entry.variable);
    ShowSearchableAddSelector(_window, _variablesButton, @"Add variables", choices,
        ^(NSArray<NSString *> *names) {
            DendrogramState *current = [self state];
            if (!current) return;
            auto updated = current->variables;
            for (NSString *label in names) {
                std::string name = label.UTF8String;
                if (std::find(updated.begin(), updated.end(), name) == updated.end())
                    updated.push_back(name);
            }
            if (updated != current->variables) {
                current->variables = std::move(updated);
                RefitDendrogramState(*current);
                [self refresh];
            }
        });
}

- (void)toggleVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    std::string variable = std::string([title UTF8String]);
    DendrogramState *state = [self state];
    if (!state) return;
    std::vector<std::string> numeric = rlispstat::core::NumericVariableNames(&state->seed);
    DendrogramVariableUpdateResult result = DendrogramVariablesAfterToggle(
        state->variables, variable, numeric);
    if (!result.ok) {
        if (!result.status.empty()) {
            [_statusField setStringValue:ToNSString(result.status)];
        }
        return;
    }
    state->variables = result.variables;
    RefitDendrogramState(*state);
    [self refresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_dendrogramControllers.erase(_dendrogramId);
}

@end

static void RefreshDendrogramWindowsOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::vector<DendrogramWindowController *> controllers;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          for (const auto &entry : g_dendrogramControllers) {
              DendrogramWindowController *controller = entry.second;
              DendrogramState *state = [controller state];
              if (state && state->group == groupCopy) {
                  controllers.push_back(controller);
              }
          }
      }
      for (DendrogramWindowController *controller : controllers) {
          [controller refresh];
      }
    });
}

