- (void)responseBoundsChanged:(id)sender;
- (void)trialsChanged:(id)sender;
- (void)inferenceChanged:(id)sender;
@end

struct GeneralizedGLMReportLayout {
    CGFloat width = 940.0;
    CGFloat margin = 14.0;
    CGFloat rowHeight = 22.0;
    CGFloat modelFitTitleY = 12.0;
    CGFloat modelFitRow1Y = 34.0;
    CGFloat modelFitRow2Y = 56.0;
    CGFloat ruleY = 84.0;
    CGFloat termsTitleY = 100.0;
    CGFloat headerY = 124.0;
    CGFloat coefRuleY = 146.0;
    CGFloat coefRowsY = 150.0;
    CGFloat bottomPadding = 18.0;
    CGFloat totalHeight = 220.0;
    NSInteger coefColumnCount = 6;
    NSInteger termTestCount = 0;
    NSInteger warningCount = 0;
    CGFloat specificationTitleY = 12.0;
    CGFloat specificationRowY = 34.0;
    CGFloat codingTitleY = 60.0;
    CGFloat codingRowY = 82.0;
    CGFloat pseudoTitleY = 180.0;
    CGFloat pseudoRowY = 202.0;
    CGFloat termTestsTitleY = 246.0;
    CGFloat termTestsHeaderY = 270.0;
    CGFloat termTestsRuleY = 292.0;
    CGFloat termTestsRowsY = 296.0;
    CGFloat warningsTitleY = 0.0;
    CGFloat diagnosticsTitleY = 0.0;
    CGFloat detailsTitleY = 0.0;
    CGFloat detailsRowsY = 0.0;
    CGFloat coefX[14] = { 2.0, 330.0, 416.0, 524.0, 632.0, 740.0 };
    CGFloat coefW[14] = { 320.0, 74.0, 92.0, 92.0, 92.0, 92.0 };

    NSInteger coefficientColumnAtX(CGFloat x) const
    {
        for (NSInteger col = 0; col < coefColumnCount; ++col) {
            if (x >= coefX[col] && x <= coefX[col] + coefW[col]) return col;
        }
        return -1;
    }

    NSRect coefficientCellRect(NSInteger row, NSInteger col) const
    {
        return NSMakeRect(margin + coefX[col], coefRowsY + row * rowHeight, coefW[col], rowHeight);
    }

    static GeneralizedGLMReportLayout Compute(NSInteger coefficientRows, CGFloat availableWidth,
                                              NSInteger coefficientColumns = 6,
                                              NSInteger termRows = 0,
                                              NSInteger warningRows = 0,
                                              bool showBinaryDetails = false,
                                              bool countModel = false,
                                              bool binaryModel = false, bool gammaModel = false)
    {
        GeneralizedGLMReportLayout layout;
        (void)termRows;
        layout.coefColumnCount = coefficientColumns;
        // Omnibus term tests are integrated into the coefficient table.  The
        // legacy termRows argument is retained for call-site compatibility,
        // but no second table is laid out below the coefficients.
        layout.termTestCount = 0;
        layout.warningCount = warningRows;
        std::vector<CGFloat> widths;
        if (binaryModel && coefficientColumns == 10) {
            widths = {270, 78, 76, 66, 62, 120, 55, 55, 64, 225};
        } else if (!binaryModel && coefficientColumns == 11) {
            widths = {245, 70, 72, 72, 58, 60, 120, 52, 52, 64, 220};
        } else if (!binaryModel && coefficientColumns == 10) {
            widths = {280, 75, 78, 78, 64, 66, 120, 52, 52, 64};
        } else if (binaryModel && coefficientColumns == 6) {
            widths = {260, 78, 78, 64, 64, 200};
        } else if (coefficientColumns == 7) {
            widths = countModel
                ? std::vector<CGFloat>{260, 72, 72, 72, 56, 60, 230}
                : std::vector<CGFloat>{290, 76, 76, 66, 62, 124, 168};
        } else {
            widths = {320, 90, 95, 90, 80, 80};
        }
        CGFloat used = 2.0;
        for (NSInteger col = 0; col < coefficientColumns; ++col) {
            const CGFloat width = col < (NSInteger)widths.size() ? widths[(size_t)col] : 72.0;
            layout.coefX[col] = used;
            layout.coefW[col] = width;
            used += width;
        }
        const CGFloat naturalWidth = used + 2.0 * layout.margin + 2.0;
        layout.width = std::max(std::max((CGFloat)940.0, naturalWidth), availableWidth);
        const CGFloat extra = layout.width - std::max((CGFloat)940.0, naturalWidth);
        if (extra > 0.0 && coefficientColumns > 0 && !binaryModel) {
            layout.coefW[0] += extra;
            for (NSInteger col = 1; col < coefficientColumns; ++col) layout.coefX[col] += extra;
        }
        if (countModel) {
            layout.modelFitRow2Y = 86.0;
            layout.ruleY = 190.0;
            layout.termsTitleY = 206.0;
            layout.headerY = 230.0;
            layout.coefRuleY = 252.0;
            layout.coefRowsY = 256.0;
        }
        if (!countModel) {
            if (binaryModel) {
                layout.modelFitTitleY = 60.0;
                layout.modelFitRow1Y = 82.0;
                layout.modelFitRow2Y = 82.0;
                layout.ruleY = 110.0;
                layout.detailsTitleY = 126.0;
                layout.detailsRowsY = 150.0;
                layout.termsTitleY = showBinaryDetails ? 250.0 : 126.0;
            } else {
                layout.modelFitRow2Y = layout.modelFitRow1Y;
                layout.ruleY = 62.0;
                layout.termsTitleY = 78.0;
            }
            layout.headerY = 102.0;
            if (binaryModel) layout.headerY = layout.termsTitleY + 24.0;
            layout.coefRuleY = layout.headerY + 22.0;
            layout.coefRowsY = layout.coefRuleY + 4.0;
        }
        if (gammaModel && !countModel && !binaryModel) {
            layout.ruleY += 22.0;
            layout.termsTitleY += 22.0;
            layout.headerY += 22.0;
            layout.coefRuleY += 22.0;
            layout.coefRowsY += 22.0;
        }
        const CGFloat afterCoefficients = layout.coefRowsY +
            std::max((CGFloat)1.0, (CGFloat)coefficientRows) * layout.rowHeight + 14.0;
        layout.warningsTitleY = afterCoefficients;
        layout.diagnosticsTitleY = layout.warningsTitleY;
        layout.totalHeight = layout.warningsTitleY +
            (warningRows > 0 ? 28.0 + 18.0 * warningRows : 0.0) + layout.bottomPadding;
        return layout;
    }
};

@interface GeneralizedGLMReportView : NSView
@property(nonatomic, assign) GeneralizedGLMWindowController *glmController;
@property(nonatomic) NSInteger selectedRow;
@property(nonatomic) NSInteger selectedColumn;
- (NSSize)preferredContentSize;
@end

@implementation GeneralizedGLMReportView

- (NSString *)snapshotTabDelimitedText
{
    GeneralizedGLMState *state = [_glmController state];
    return state ? [_glmController formattedOutputForState:state] : @"";
}

- (instancetype)initWithFrame:(NSRect)frame
{
    self = [super initWithFrame:frame];
    if (self) {
        _selectedRow = -1;
        _selectedColumn = -1;
        [self setWantsLayer:YES];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (NSSize)preferredContentSize
{
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute(
        [_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount],
        [_glmController binaryWarningCount], [_glmController showsModelDetails],
        [self glmController] && [[self glmController] state] &&
            [[self glmController] state]->countRegression,
        [self glmController] && [[self glmController] state] &&
            [[self glmController] state]->binaryRegression,
        [[self glmController] state] &&
            ([[self glmController] state]->family == "Gamma" ||
             [[self glmController] state]->family == "gamma_distance"));
    return NSMakeSize(layout.width, layout.totalHeight);
}

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color align:(NSTextAlignment)align
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:align];
    return @{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    };
}

- (void)drawFitField:(NSString *)label value:(NSString *)value rect:(NSRect)rect
{
    NSDictionary *labelAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.16 alpha:1.0] align:NSTextAlignmentLeft];
    NSDictionary *valueAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.16 alpha:1.0] align:NSTextAlignmentLeft];
    if (_glmController && [_glmController state]->countRegression) {
        [label drawInRect:NSMakeRect(rect.origin.x, rect.origin.y, rect.size.width - 8, 30)
            withAttributes:labelAttrs];
        [value drawInRect:NSMakeRect(rect.origin.x, rect.origin.y + 28, rect.size.width - 8, 18)
            withAttributes:valueAttrs];
        return;
    }
    CGFloat labelWidth = std::min((CGFloat)92.0, rect.size.width * 0.52);
    [label drawInRect:NSMakeRect(rect.origin.x, rect.origin.y, labelWidth, rect.size.height) withAttributes:labelAttrs];
    [value drawInRect:NSMakeRect(rect.origin.x + labelWidth, rect.origin.y, rect.size.width - labelWidth, rect.size.height) withAttributes:valueAttrs];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    if (!_glmController) return;
    GeneralizedGLMState *state = [_glmController state];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute(
        [_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount],
        [_glmController binaryWarningCount], [_glmController showsModelDetails],
        state && state->countRegression, state && state->binaryRegression,
            state && (state->family == "Gamma" || state->family == "gamma_distance"));

    NSColor *textColor = [NSColor colorWithCalibratedWhite:0.15 alpha:1.0];
    NSColor *mutedColor = [NSColor colorWithCalibratedWhite:0.48 alpha:1.0];
    NSDictionary *sectionAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:textColor align:NSTextAlignmentLeft];
    NSDictionary *leftAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:textColor align:NSTextAlignmentLeft];
    NSDictionary *mutedLeftAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:mutedColor align:NSTextAlignmentLeft];
    NSDictionary *headerLeftAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:textColor align:NSTextAlignmentLeft];
    NSDictionary *headerRightAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:textColor align:NSTextAlignmentRight];
    NSDictionary *rightAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:textColor align:NSTextAlignmentRight];
    NSDictionary *mutedRightAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:mutedColor align:NSTextAlignmentRight];
    const bool manualFitPending = state &&
        rlispstat::core::GeneralizedGLMHasPendingManualFit(*state);

    if (state && state->binaryRegression) {
        [ToNSString("Binary Model — " + state->response)
            drawInRect:NSMakeRect(layout.margin, layout.specificationTitleY,
                                  layout.width - 2.0 * layout.margin, 20)
            withAttributes:sectionAttrs];
        std::string coding = "Event: " + state->responseCoding.eventLabel + " · Reference: " +
            state->responseCoding.referenceLabel + " · " +
            rlispstat::core::BinaryLinkLabel(state->binaryLink) + " link";
        if (!manualFitPending) {
            coding += " · N = " + std::to_string(state->n);
            if (state->excluded > 0) {
                coding += " · " + std::to_string(state->excluded) + " excluded";
            }
        }
        [ToNSString(coding) drawInRect:NSMakeRect(layout.margin, layout.specificationRowY, layout.width - 2.0 * layout.margin, 18) withAttributes:leftAttrs];
    }
    NSString *fitTitle = state && state->binaryRegression ? @"Global fit" : ToNSString(rlispstat::core::GLMModelFitSectionTitle());
    [fitTitle drawInRect:NSMakeRect(layout.margin, layout.modelFitTitleY, 160, 18) withAttributes:sectionAttrs];
    if (state && state->rFitPending && !state->ok) {
        [ToNSString(state->status) drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y, layout.width - 2.0 * layout.margin, 38) withAttributes:mutedLeftAttrs];
        return;
    }
    if (manualFitPending) {
        [ToNSString(rlispstat::core::GeneralizedGLMPendingManualFitStatus())
            drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y,
                                  layout.width - 2.0 * layout.margin, 38)
            withAttributes:mutedLeftAttrs];
    } else if (state && state->ok) {
        CGFloat colW = (layout.width - 2.0 * layout.margin) / 4.0;
        if (state->binaryRegression) {
            std::string summary = "LR χ²(" + std::to_string(state->dfModel) + ") = " +
                FormatModelNumberOrDash(state->globalLR) + ", p " + FormatPValue(state->globalP) +
                " · Nagelkerke pseudo-R² = " + FormatModelNumberOrDash(state->nagelkerkeR2);
            [ToNSString(summary) drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y,
                layout.width - 2.0 * layout.margin, 18) withAttributes:leftAttrs];
        } else {
            const bool ceilingHurdle = state->countRegression &&
                state->countDistribution == rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling;
            const bool perfectScore = state->countRegression &&
                state->countDistribution == rlispstat::core::CountDistribution::PerfectScore;
            const bool boundedCount = state->countRegression &&
                rlispstat::core::CountDistributionUsesTrials(state->countDistribution);
            if (boundedCount) {
                const std::string trials = !state->trialsVariable.empty()
                    ? state->trialsVariable : FormatDoubleOrDash(state->trialsConstant, 0);
                [self drawFitField:@"N" value:ToNSString(std::to_string(state->n)) rect:NSMakeRect(layout.margin, layout.modelFitRow1Y, colW, 18)];
                [self drawFitField:@"Trials" value:ToNSString(trials) rect:NSMakeRect(layout.margin + colW, layout.modelFitRow1Y, colW, 18)];
                NSString *observedLabel = state->multipleImputation &&
                    !state->observedCeilingCountConstant
                    ? @"Mean observed at ceiling" : @"Observed at ceiling";
                [self drawFitField:observedLabel value:ToNSString(
                    FormatDoubleOrDash(state->perfectScoreCount, 1) + " (" +
                    FormatPercentOrDash(state->observedCeilingProportion, 1) + ")")
                    rect:NSMakeRect(layout.margin + colW * 2.0, layout.modelFitRow1Y, colW, 18)];
                [self drawFitField:state->multipleImputation ? @"Mean predicted at ceiling" : @"Predicted at ceiling" value:ToNSString(
                    FormatDoubleOrDash(std::isfinite(state->predictedCeilingCount)
                        ? state->predictedCeilingCount
                        : state->n * state->predictedCeilingProportion, 1) + " (" +
                    FormatPercentOrDash(state->predictedCeilingProportion, 1) + ")")
                    rect:NSMakeRect(layout.margin + colW * 3.0, layout.modelFitRow1Y, colW, 18)];
            } else {
                [self drawFitField:ToNSString(rlispstat::core::GLMFitNLabel()) value:ToNSString(std::to_string(state->n)) rect:NSMakeRect(layout.margin, layout.modelFitRow1Y, colW, 18)];
                [self drawFitField:ToNSString(rlispstat::core::GLMFitNullDevianceLabel()) value:ToNSString(FormatDoubleOrDash(state->nullDeviance, 3)) rect:NSMakeRect(layout.margin + colW, layout.modelFitRow1Y, colW, 18)];
                [self drawFitField:ToNSString(rlispstat::core::GLMFitResidualDevianceLabel()) value:ToNSString(FormatDoubleOrDash(state->residualDeviance, 3)) rect:NSMakeRect(layout.margin + colW * 2.0, layout.modelFitRow1Y, colW, 18)];
                [self drawFitField:ToNSString(rlispstat::core::GLMFitDfResidualLabel()) value:ToNSString(std::to_string(state->dfResidual)) rect:NSMakeRect(layout.margin + colW * 3.0, layout.modelFitRow1Y, colW, 18)];
            }
            if (ceilingHurdle) {
                [@"Perfect-score logistic component: fitted" drawInRect:
                    NSMakeRect(layout.margin, layout.modelFitRow2Y, colW * 1.5, 18)
                    withAttributes:mutedLeftAttrs];
                [@"Below-ceiling truncated beta-binomial: fitted" drawInRect:
                    NSMakeRect(layout.margin + colW * 1.5, layout.modelFitRow2Y, colW * 1.5, 18)
                    withAttributes:mutedLeftAttrs];
            } else if (state->countRegression ||
                rlispstat::core::GeneralizedModelHasExponentiatedEffect(*state)) {
                if (state->likelihoodAvailable) {
                    [ToNSString(std::string("log likelihood: ") + FormatModelNumberOrDash(state->logLik))
                        drawInRect:NSMakeRect(layout.margin, layout.modelFitRow2Y, colW, 18) withAttributes:leftAttrs];
                    [ToNSString(std::string("AIC: ") + FormatModelNumberOrDash(state->aic))
                        drawInRect:NSMakeRect(layout.margin + colW, layout.modelFitRow2Y, colW, 18) withAttributes:leftAttrs];
                    [ToNSString(std::string("BIC: ") + FormatModelNumberOrDash(state->bic))
                        drawInRect:NSMakeRect(layout.margin + colW * 2.0, layout.modelFitRow2Y, colW, 18) withAttributes:leftAttrs];
                } else {
                    NSString *likelihoodMessage = state->countDistribution == rlispstat::core::CountDistribution::QuasiPoisson
                        ? @"Quasi-Poisson has no likelihood, AIC, or BIC."
                        : state->multipleImputation
                            ? @"Likelihood statistics are not pooled across imputations."
                            : @"Likelihood statistics are unavailable.";
                    [likelihoodMessage
                        drawInRect:NSMakeRect(layout.margin, layout.modelFitRow2Y, colW * 3.0, 18)
                        withAttributes:mutedLeftAttrs];
                }
                if (!state->countRegression) {
                    [self drawFitField:state->family == "lognormal" ? @"Residual variance (log scale)" :
                        (state->family == "Gamma" || state->family == "gamma_distance") ? @"Dispersion φ" : @"Dispersion"
                        value:ToNSString(FormatModelNumberOrDash(state->dispersion))
                        rect:NSMakeRect(layout.margin + colW * 3.0, layout.modelFitRow2Y, colW, 18)];
                }
            }
        }
    } else if (state) {
        [ToNSString(state->status) drawInRect:NSMakeRect(layout.margin, layout.modelFitRow1Y, layout.width - 2.0 * layout.margin, 38) withAttributes:mutedLeftAttrs];
    }

    if (state && state->ok && state->countRegression && !manualFitPending) {
        NSString *summary = ToNSString(rlispstat::core::CountModelParameterSummary(*state));
        NSMutableAttributedString *parameter = [[NSMutableAttributedString alloc]
            initWithString:summary attributes:leftAttrs];
        NSRange colon = [summary rangeOfString:@":"];
        if (colon.location != NSNotFound)
            [parameter addAttribute:NSFontAttributeName
                value:[NSFont systemFontOfSize:12 weight:NSFontWeightSemibold]
                range:NSMakeRange(0, colon.location)];
        [parameter drawInRect:NSMakeRect(layout.margin, 110.0, layout.width - 2 * layout.margin, 34)];
        const auto diagnosticRows = rlispstat::core::GeneralizedFamilyDiagnosticRows(*state);
        for (std::size_t index = 0; index < diagnosticRows.size(); ++index) {
            [ToNSString(diagnosticRows[index].display) drawInRect:
                NSMakeRect(layout.margin, 132.0 + index * 20.0,
                           layout.width - 2 * layout.margin, 18.0)
                withAttributes:leftAttrs];
        }
    } else if (state && state->ok && !state->countRegression &&
               (state->family == "Gamma" || state->family == "gamma_distance")) {
        const auto diagnosticRows = rlispstat::core::GeneralizedFamilyDiagnosticRows(*state);
        if (!diagnosticRows.empty()) {
            [ToNSString(diagnosticRows.front().display) drawInRect:
                NSMakeRect(layout.margin, 56.0, layout.width - 2 * layout.margin, 18.0)
                withAttributes:leftAttrs];
        }
    }

    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *rule = [NSBezierPath bezierPath];
    [rule moveToPoint:NSMakePoint(layout.margin, layout.ruleY)];
    [rule lineToPoint:NSMakePoint(layout.width - layout.margin, layout.ruleY)];
    [rule stroke];

    if (state && state->binaryRegression && [_glmController showsModelDetails] &&
        state->ok && !manualFitPending) {
        [@"Model details" drawInRect:NSMakeRect(layout.margin, layout.detailsTitleY, 180, 18)
                         withAttributes:sectionAttrs];
        const CGFloat detailWidth = (layout.width - 2.0 * layout.margin) / 4.0;
        const CGFloat y1 = layout.detailsRowsY;
        const CGFloat y2 = y1 + 22.0;
        const CGFloat y3 = y2 + 22.0;
        [self drawFitField:@"Log likelihood" value:ToNSString(FormatModelNumberOrDash(state->logLik)) rect:NSMakeRect(layout.margin, y1, detailWidth, 18)];
        [self drawFitField:@"Residual dev." value:ToNSString(FormatModelNumberOrDash(state->residualDeviance)) rect:NSMakeRect(layout.margin + detailWidth, y1, detailWidth, 18)];
        [self drawFitField:@"Null dev." value:ToNSString(FormatModelNumberOrDash(state->nullDeviance)) rect:NSMakeRect(layout.margin + detailWidth * 2.0, y1, detailWidth, 18)];
        [self drawFitField:@"df residual" value:ToNSString(std::to_string(state->dfResidual)) rect:NSMakeRect(layout.margin + detailWidth * 3.0, y1, detailWidth, 18)];
        [self drawFitField:@"AIC" value:ToNSString(FormatModelNumberOrDash(state->aic)) rect:NSMakeRect(layout.margin, y2, detailWidth, 18)];
        [self drawFitField:@"BIC" value:ToNSString(FormatModelNumberOrDash(state->bic)) rect:NSMakeRect(layout.margin + detailWidth, y2, detailWidth, 18)];
        [self drawFitField:@"McFadden R²" value:ToNSString(FormatModelNumberOrDash(state->mcfaddenR2)) rect:NSMakeRect(layout.margin + detailWidth * 2.0, y2, detailWidth, 18)];
        [self drawFitField:@"Cox–Snell R²" value:ToNSString(FormatModelNumberOrDash(state->coxSnellR2)) rect:NSMakeRect(layout.margin + detailWidth * 3.0, y2, detailWidth, 18)];
        [self drawFitField:@"Apparent AUC¹" value:ToNSString(FormatModelNumberOrDash(state->auc)) rect:NSMakeRect(layout.margin, y3, detailWidth, 18)];
        [self drawFitField:@"Converged" value:(state->converged ? @"yes" : @"no") rect:NSMakeRect(layout.margin + detailWidth, y3, detailWidth, 18)];
        [self drawFitField:@"Iterations" value:ToNSString(std::to_string(state->iterations)) rect:NSMakeRect(layout.margin + detailWidth * 2.0, y3, detailWidth, 18)];
        [self drawFitField:@"Rank" value:ToNSString(std::to_string(state->rank) + "/" + std::to_string(state->parameterCount)) rect:NSMakeRect(layout.margin + detailWidth * 3.0, y3, detailWidth, 18)];
        [@"¹ Calculated on the observations used to fit the model; not out-of-sample validation."
            drawInRect:NSMakeRect(layout.margin, y3 + 20.0, layout.width - 2.0 * layout.margin, 16)
            withAttributes:mutedLeftAttrs];
        NSBezierPath *detailsRule = [NSBezierPath bezierPath];
        [detailsRule moveToPoint:NSMakePoint(layout.margin, layout.termsTitleY - 16.0)];
        [detailsRule lineToPoint:NSMakePoint(layout.width - layout.margin, layout.termsTitleY - 16.0)];
        [detailsRule stroke];
    }

    NSString *coefficientTitle = state && state->binaryRegression ? @"Terms and coefficients" : ToNSString(rlispstat::core::GLMTermsSectionTitle());
    [coefficientTitle drawInRect:NSMakeRect(layout.margin, layout.termsTitleY, 160, 18) withAttributes:sectionAttrs];
    NSMutableArray<NSString *> *headers = [NSMutableArray array];
    if (state && state->binaryRegression) {
        NSString *effectHeader = rlispstat::core::GeneralizedModelHasExponentiatedEffect(*state)
            ? ToNSString(rlispstat::core::GeneralizedExponentiatedEffectLabel(*state) + " / 95% CI")
            : @"95% CI";
        [headers addObjectsFromArray:@[@"Variable / category", @"B", @"SE", ToNSString(state->statisticName), @"p"]];
        [headers addObject:effectHeader];
    } else if (state && rlispstat::core::GeneralizedModelHasExponentiatedEffect(*state)) {
        [headers addObjectsFromArray:@[ToNSString(rlispstat::core::GLMCoefVariableHeader()), ToNSString(rlispstat::core::GLMCoefTypeHeader()), @"b", @"SE", ToNSString(state->statisticName), @"p"]];
        [headers addObject:ToNSString(rlispstat::core::GeneralizedExponentiatedEffectLabel(*state) + " / 95% CI")];
    } else {
        [headers addObjectsFromArray:@[ToNSString(rlispstat::core::GLMCoefVariableHeader()), ToNSString(rlispstat::core::GLMCoefTypeHeader()), ToNSString(rlispstat::core::GLMCoefBHeader()), ToNSString(rlispstat::core::GLMCoefSEHeader()), state ? ToNSString(state->statisticName) : ToNSString(rlispstat::core::GLMCoefStatisticHeader()), ToNSString(rlispstat::core::GLMCoefPHeader())]];
    }
    for (NSInteger col = 0; col < layout.coefColumnCount; ++col) {
        NSRect headerRect = NSMakeRect(layout.margin + layout.coefX[col], layout.headerY, layout.coefW[col], 18);
        const bool leftAligned = state && state->binaryRegression ? col == 0 : (col == 0 || col == 1);
        [headers[(NSUInteger)col] drawInRect:headerRect withAttributes:(leftAligned ? headerLeftAttrs : headerRightAttrs)];
    }
    NSBezierPath *coefRule = [NSBezierPath bezierPath];
    [coefRule moveToPoint:NSMakePoint(layout.margin, layout.coefRuleY)];
    [coefRule lineToPoint:NSMakePoint(layout.width - layout.margin, layout.coefRuleY)];
    [coefRule stroke];

    NSInteger rows = [_glmController coefficientRowCount];
    NSInteger addRow = rows - 1;
    for (NSInteger row = 0; row < rows; ++row) {
        const bool sectionRow = state && row >= 0 &&
            row < (NSInteger)state->rows.size() &&
            state->rows[(size_t)row].rowType == "section_header";
        if (row == _selectedRow) {
            [[NSColor colorWithCalibratedWhite:0.93 alpha:1.0] setFill];
            NSRectFill(NSMakeRect(layout.margin - 2.0, layout.coefRowsY + row * layout.rowHeight, layout.width - 2.0 * layout.margin + 4.0, layout.rowHeight));
        }
        for (NSInteger col = 0; col < layout.coefColumnCount; ++col) {
            NSString *value = [_glmController coefficientValueForRow:row column:col];
            if (!value || [value length] == 0) continue;
            NSRect cell = NSInsetRect(layout.coefficientCellRect(row, col), 2.0, 3.0);
            const bool leftAligned = state && state->binaryRegression ? col == 0 : (col == 0 || col == 1);
            NSDictionary *attrs = sectionRow
                ? sectionAttrs
                : (row == addRow || [value isEqualToString:@"\U00002014"])
                ? (leftAligned ? mutedLeftAttrs : mutedRightAttrs)
                : (leftAligned ? leftAttrs : rightAttrs);
            [value drawInRect:cell withAttributes:attrs];
        }
    }

	    if (state) {
	        CGFloat y = layout.warningsTitleY;
        if (!state->warnings.empty()) {
            [@"Warnings" drawInRect:NSMakeRect(layout.margin, y, 160, 18) withAttributes:sectionAttrs];
            y += 24.0;
            for (const std::string &warning : state->warnings) {
                [ToNSString("⚠ " + warning) drawInRect:NSMakeRect(layout.margin + 2.0, y, layout.width - 2.0 * layout.margin - 4.0, 18) withAttributes:mutedLeftAttrs];
                y += 18.0;
            }
        }
        const std::string pooledWaldFootnote =
            rlispstat::core::GeneralizedGlobalTermTestPooledWaldFootnote(*state);
        if (!pooledWaldFootnote.empty()) {
            [ToNSString(pooledWaldFootnote) drawInRect:
                NSMakeRect(layout.margin + 2.0, y,
                    layout.width - 2.0 * layout.margin - 4.0, 20.0)
                withAttributes:mutedLeftAttrs];
            y += 20.0;
        } else {
            const std::string methodNote =
                rlispstat::core::GeneralizedGlobalTermTestMethodNote(*state);
            if (!methodNote.empty()) {
                [ToNSString("Note: " + methodNote)
                    drawInRect:NSMakeRect(layout.margin + 2.0, y,
                        layout.width - 2.0 * layout.margin - 4.0, 24.0)
                    withAttributes:mutedLeftAttrs];
                y += 24.0;
            }
        }
        const std::string hierarchyNote =
            rlispstat::core::GeneralizedGlobalTermTestHierarchyNote(*state);
        if (!hierarchyNote.empty()) {
            [ToNSString("Note: " + hierarchyNote)
                drawInRect:NSMakeRect(layout.margin + 2.0, y,
                    layout.width - 2.0 * layout.margin - 4.0, 36.0)
                withAttributes:mutedLeftAttrs];
        }
    }
}

- (NSInteger)rowAtPoint:(NSPoint)point
{
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount], [_glmController binaryWarningCount], [_glmController showsModelDetails],
        [_glmController state] && [_glmController state]->countRegression,
        [_glmController state] && [_glmController state]->binaryRegression,
        [_glmController state] && ([_glmController state]->family == "Gamma" ||
                                   [_glmController state]->family == "gamma_distance"));
    if (point.y < layout.coefRowsY) return -1;
    NSInteger row = (NSInteger)floor((point.y - layout.coefRowsY) / layout.rowHeight);
    return (row >= 0 && row < [_glmController coefficientRowCount]) ? row : -1;
}

- (NSString *)fitStatisticAtPoint:(NSPoint)point
{
    const auto *state = [_glmController state];
    if (!state || !state->ok ||
        rlispstat::core::GeneralizedGLMHasPendingManualFit(*state)) return nil;
    const bool countModel = state->countRegression;
    const bool gammaModel = !countModel &&
        (state->family == "Gamma" || state->family == "gamma_distance");
    if (!countModel && !gammaModel) return nil;
    const auto layout = GeneralizedGLMReportLayout::Compute(
        [_glmController coefficientRowCount], self.bounds.size.width,
        [_glmController coefficientColumnCount], 0, 0, false, countModel, false, gammaModel);
    if (point.x < layout.margin || point.x >= layout.width-layout.margin) return nil;
    const CGFloat colW = (layout.width-2*layout.margin)/4;
    const int col = (int)((point.x-layout.margin)/colW);
    if (gammaModel) {
        if (point.y >= 34.0 && point.y < 53.0 && col == 3)
            return @"Gamma dispersion (phi)";
        if (point.y >= 56.0 && point.y < 76.0 &&
            !rlispstat::core::GeneralizedFamilyDiagnosticRows(*state).empty())
            return @"Implied coefficient of variation";
        return nil;
    }
    if (point.y >= layout.modelFitRow1Y && point.y < layout.modelFitRow1Y+48) {
        if (rlispstat::core::CountDistributionUsesTrials(state->countDistribution))
            return @[@"N", @"Trials", @"Observed at ceiling", @"Predicted at ceiling"][col];
        return @[@"N", @"Null deviance", @"Residual deviance", @"df residual"][col];
    }
    if (point.y >= layout.modelFitRow2Y && point.y < layout.modelFitRow2Y+20) {
        if (state->countDistribution == rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling)
            return point.x < layout.margin+1.5*colW ? @"Perfect-score logistic component" : @"Below-ceiling truncated beta-binomial";
        if (!state->likelihoodAvailable) return @"Likelihood statistics";
        return col < 3 ? @[@"Log likelihood", @"AIC", @"BIC"][col] : nil;
    }
    if (point.y >= 110 && point.y < 130) {
        const auto summary = rlispstat::core::CountModelParameterSummary(*state);
        if (summary.empty()) return nil;
        return ToNSString(summary.substr(0, summary.find(':')));
    }
    if (point.y >= 132 && point.y < 190) {
        const auto rows = rlispstat::core::GeneralizedFamilyDiagnosticRows(*state);
        const std::size_t index = static_cast<std::size_t>((point.y - 132) / 20);
        if (index < rows.size()) return ToNSString(rows[index].statistic);
    }
    return nil;
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount], [_glmController binaryWarningCount], [_glmController showsModelDetails],
        [_glmController state] && [_glmController state]->countRegression,
        [_glmController state] && [_glmController state]->binaryRegression,
        [_glmController state] && ([_glmController state]->family == "Gamma" ||
                                   [_glmController state]->family == "gamma_distance"));
    NSInteger row = [self rowAtPoint:point];
    NSInteger column = layout.coefficientColumnAtX(point.x - layout.margin);
    _selectedRow = row;
    _selectedColumn = column;
    [self setNeedsDisplay:YES];
    NSMenu *menu = [_glmController contextMenuForCoefficientRow:row column:column];
    NSString *statistic = [self fitStatisticAtPoint:point];
    if (!statistic && point.y >= layout.headerY && point.y < layout.coefRuleY && column >= 0)
        statistic = [_glmController coefficientColumnIdentifier:column];
    if (!statistic && row >= 0 && ![_glmController isAddTermRow:row] && column >= 0)
        statistic = [_glmController coefficientColumnIdentifier:column];
    if (statistic && ![menu itemWithTitle:@"Explain statistic"]) {
        NSMenuItem *explain = [[NSMenuItem alloc] initWithTitle:@"Explain statistic"
            action:@selector(explainGeneralizedStatistic:) keyEquivalent:@""];
        explain.target = _glmController;
        explain.representedObject = statistic;
        [menu insertItem:explain atIndex:0];
    }
    return SnapshotAlbumMenu(menu, @"Generalized Linear Model");
}

- (void)mouseDown:(NSEvent *)event
{
    if (PopContextMenuForMouseDownIfNeeded(self, event)) return;
    [[self window] makeFirstResponder:self];
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width,
        [_glmController coefficientColumnCount], [_glmController binaryTermTestCount], [_glmController binaryWarningCount], [_glmController showsModelDetails],
        [_glmController state] && [_glmController state]->countRegression,
        [_glmController state] && [_glmController state]->binaryRegression,
        [_glmController state] && ([_glmController state]->family == "Gamma" ||
                                   [_glmController state]->family == "gamma_distance"));
    NSInteger row = [self rowAtPoint:point];
    NSInteger column = layout.coefficientColumnAtX(point.x - layout.margin);
    _selectedRow = row;
    _selectedColumn = column;
    [self setNeedsDisplay:YES];
    [_glmController coefficientCellClickedAtRow:row column:column];
}

- (void)rightMouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    NSInteger row = [self rowAtPoint:point];
    if (row >= 0 && [_glmController isAddTermRow:row]) {
        [_glmController showSearchableAddTermSelectorInView:self];
        return;
    }
    PopContextMenuForMouseDownIfNeeded(self, event);
}
@end

