- (GeneralizedGLMState *)state
{
    auto it = g_generalizedGLMs.find(_modelId);
    if (it == g_generalizedGLMs.end()) return nullptr;
    return &it->second;
}

- (void)show
{
    [self activateDatasetForCommands];
    GeneralizedGLMState *state = [self state];
    EnableNotesForWindow(_window, _modelId, @"this model result",
                         state ? state->group : std::string{});
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
    // Do not acknowledge the R result while its report is still waiting for
    // the next AppKit paint cycle.
    [[_window contentView] displayIfNeeded];
}

- (void)showTaskProgress:(NSString *)message cancelPath:(NSString *)cancelPath terminal:(BOOL)terminal
{
    if (terminal && _applyingResultsTimer) {
        [_applyingResultsTimer invalidate];
        _applyingResultsTimer = nil;
        _applyingResultsStartedAt = 0;
    }
    if (terminal && [message hasPrefix:@"Results ready"]) {
        [_lastTaskTiming release];
        _lastTaskTiming = [(_applyingResultsPainted
            ? [message stringByAppendingFormat:@" · visible %.1fs", _applyingResultsSeconds]
            : message) copy];
        [_timingField setStringValue:_lastTaskTiming];
    } else if (!terminal && [message hasPrefix:@"Preparing"]) {
        [_applyingResultsTimer invalidate];
        _applyingResultsTimer = nil;
        _applyingResultsStartedAt = 0;
        _applyingResultsSeconds = 0;
        _applyingResultsPainted = NO;
        [_lastTaskTiming release];
        _lastTaskTiming = nil;
        [_timingField setStringValue:@""];
    }
    [_taskCancelPath release];
    _taskCancelPath = terminal ? nil : [cancelPath copy];
    BOOL cancellable = !terminal && [_taskCancelPath length] > 0;
    [_cancelTaskButton setHidden:!cancellable];
	    [_statusField setFrameSize:NSMakeSize(cancellable ?
	        MAX(200.0, [[_window contentView] bounds].size.width - 150.0) :
	        MAX(200.0, [[_window contentView] bounds].size.width - 32.0), 34.0)];
	    [_statusField setStringValue:(terminal && [message hasPrefix:@"Results ready"])
	        ? @"Status: results ready." : (message ?: @"")];
	    [_statusField setToolTip:[_statusField stringValue]];
}

- (void)beginApplyingResultsAt:(CFAbsoluteTime)startedAt
{
    if (_applyingResultsTimer) return;
    [self showTaskProgress:@"" cancelPath:@"" terminal:NO];
    _applyingResultsSeconds = 0;
    _applyingResultsPainted = NO;
    _applyingResultsStartedAt = startedAt;
    _applyingResultsTimer = [NSTimer timerWithTimeInterval:0.2
        target:self selector:@selector(updateApplyingResultsTime:)
        userInfo:nil repeats:YES];
    [[NSRunLoop mainRunLoop] addTimer:_applyingResultsTimer
        forMode:NSRunLoopCommonModes];
    [self updateApplyingResultsTime:_applyingResultsTimer];
}

- (void)resultsDidPaint
{
    if (!_applyingResultsTimer) return;
    _applyingResultsSeconds = MAX(0, CFAbsoluteTimeGetCurrent() - _applyingResultsStartedAt);
    _applyingResultsPainted = YES;
    [_applyingResultsTimer invalidate];
    _applyingResultsTimer = nil;
    _applyingResultsStartedAt = 0;
    [_statusField setStringValue:@"Status: results shown."];
    [_timingField setStringValue:[NSString stringWithFormat:
        @"Result transfer and rendering: %.1f s", _applyingResultsSeconds]];
}

- (void)updateApplyingResultsTime:(NSTimer *)timer
{
    if (timer != _applyingResultsTimer) return;
    [_statusField setStringValue:[NSString stringWithFormat:
        @"R calculations finished; applying results in this window · %.1f s",
        MAX(0, CFAbsoluteTimeGetCurrent() - _applyingResultsStartedAt)]];
}

- (void)cancelCurrentTask:(id)sender
{
    (void)sender;
    if (![_taskCancelPath length]) return;
    [@"cancel\n" writeToFile:_taskCancelPath atomically:YES
        encoding:NSUTF8StringEncoding error:nil];
    [_cancelTaskButton setEnabled:NO];
    [_statusField setStringValue:@"Cancelling R workers…"];
}

- (void)activateDatasetForCommands
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
        EnsureDatasetSeedPlotUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

- (void)windowDidBecomeKey:(NSNotification *)notification
{
    (void)notification;
    [self activateDatasetForCommands];
}

- (void)populateLinkPopupForFamily:(const std::string &)family selected:(const std::string &)selected
{
    [_linkPopup removeAllItems];
    GeneralizedGLMState *state = [self state];
    if (state && state->binaryRegression) {
        for (rlispstat::core::BinaryLink link : rlispstat::core::SupportedBinaryLinks()) {
            [_linkPopup addItemWithTitle:ToNSString(rlispstat::core::BinaryLinkLabel(link))];
        }
        [_linkPopup selectItemWithTitle:ToNSString(rlispstat::core::BinaryLinkLabel(state->binaryLink))];
        return;
    }
    std::string distribution = family;
    if (state && state->countRegression) {
        distribution = rlispstat::core::CountDistributionId(state->countDistribution);
    }
    std::vector<std::string> links = state
        ? rlispstat::core::LinksForModelDistribution(state->modelType, distribution)
        : std::vector<std::string>{};
    if (links.empty()) links = GeneralizedLinksForFamily(family);
    for (const std::string &link : links) {
        [_linkPopup addItemWithTitle:ToNSString(link)];
    }
    [_linkPopup selectItemWithTitle:ToNSString(selected)];
}

- (NSString *)formattedOutputForState:(GeneralizedGLMState *)state
{
    return state ? ToNSString(rlispstat::core::GeneralizedGLMFormattedOutputText(*state, _showModelDetails)) : @"";
}

- (NSInteger)coefficientRowCount
{
    GeneralizedGLMState *state = [self state];
    if (!state) return 1;
    if (state->rFitPending && !state->ok) return 0;
    if (state->ok && !rlispstat::core::GeneralizedGLMHasPendingManualFit(*state)) {
        return (NSInteger)state->rows.size() + 1;
    }
    return (NSInteger)state->terms.size() + 2;
}

- (NSInteger)coefficientColumnCount
{
    GeneralizedGLMState *state = [self state];
    if (!state) return 6;
    const NSInteger base = (state->binaryRegression ||
        !rlispstat::core::GeneralizedModelHasExponentiatedEffect(*state)) ? 6 : 7;
    return base;
}

- (NSInteger)binaryTermTestCount
{
    return 0;
}

- (NSInteger)binaryWarningCount
{
    GeneralizedGLMState *state = [self state];
    if (!state || rlispstat::core::GeneralizedGLMHasPendingManualFit(*state)) return 0;
    const bool hasPooledWaldFootnote =
        !rlispstat::core::GeneralizedGlobalTermTestPooledWaldFootnote(*state).empty();
    return (NSInteger)state->warnings.size() +
        (hasPooledWaldFootnote ||
         !rlispstat::core::GeneralizedGlobalTermTestMethodNote(*state).empty() ? 1 : 0) +
        (rlispstat::core::GeneralizedGlobalTermTestHierarchyNote(*state).empty() ? 0 : 1);
}

- (BOOL)showsModelDetails
{
    GeneralizedGLMState *state = [self state];
    return state && state->binaryRegression && _showModelDetails &&
        !rlispstat::core::GeneralizedGLMHasPendingManualFit(*state);
}

- (NSString *)coefficientColumnIdentifier:(NSInteger)column
{
    static NSString *ids[] = { @"term", @"type", @"estimate", @"stderr", @"stat", @"p" };
    GeneralizedGLMState *state = [self state];
    if (state && state->binaryRegression) {
        static NSString *binaryIds[] = { @"term", @"estimate", @"stderr", @"stat", @"p",
            @"effect_ci" };
        return (column >= 0 && column < [self coefficientColumnCount])
            ? binaryIds[column] : @"";
    }
    if (state && rlispstat::core::GeneralizedModelHasExponentiatedEffect(*state)) {
        static NSString *effectIds[] = { @"term", @"type", @"estimate", @"stderr", @"stat", @"p", @"exponentiated_effect" };
        return (column >= 0 && column < [self coefficientColumnCount])
            ? effectIds[column] : @"";
    }
    return (column >= 0 && column < 6) ? ids[column] : @"";
}

- (BOOL)isAddTermRow:(NSInteger)row
{
    return row == [self coefficientRowCount] - 1;
}

- (std::string)sourceTermForCoefficientRow:(NSInteger)row
{
    GeneralizedGLMState *state = [self state];
    if (!state || row <= 0 || [self isAddTermRow:row]) return "";
    if (state->ok && !rlispstat::core::GeneralizedGLMHasPendingManualFit(*state) &&
        row < (NSInteger)state->rows.size()) {
        const GeneralizedGLMRow &coef = state->rows[(size_t)row];
        if (!coef.sourceTerm.empty() && coef.sourceTerm != "NA" && coef.sourceTerm != "(Intercept)") {
            return coef.sourceTerm;
        }
        std::string candidate = coef.term;
        size_t eq = candidate.find('=');
        if (eq != std::string::npos) candidate = candidate.substr(0, eq);
        auto it = std::find(state->terms.begin(), state->terms.end(), candidate);
        if (it != state->terms.end()) return candidate;
        std::string label = coef.displayLabel;
        label.erase(label.begin(), std::find_if(label.begin(), label.end(), [](unsigned char ch) { return !std::isspace(ch); }));
        it = std::find(state->terms.begin(), state->terms.end(), label);
        if (it != state->terms.end()) return label;
        return "";
    }
    NSInteger termRow = row - 1;
    if (termRow >= 0 && (size_t)termRow < state->terms.size()) return state->terms[(size_t)termRow];
    return "";
}

- (NSString *)coefficientValueForRow:(NSInteger)row column:(NSInteger)column
{
    NSString *identifier = [self coefficientColumnIdentifier:column];
    GeneralizedGLMState *state = [self state];
    if (!state || row < 0) return @"";
    if ([self isAddTermRow:row]) {
        return [identifier isEqualToString:@"term"] ? @"+ Add term" : @"";
    }

    bool hasCoef = state->ok &&
        !rlispstat::core::GeneralizedGLMHasPendingManualFit(*state) &&
        row >= 0 && row < (NSInteger)state->rows.size();
    if (hasCoef) {
        const GeneralizedGLMRow &coef = state->rows[(size_t)row];
        bool sectionRow = coef.rowType == "section_header";
        bool parentRow = coef.rowType == "factor_parent" || coef.rowType == "term_parent";
        bool referenceRow = coef.rowType == "reference";
        const rlispstat::core::GlobalTermTestRow *termTest =
            rlispstat::core::GeneralizedGlobalTermTestForPresentationRow(*state, coef);
        if ([identifier isEqualToString:@"term"]) {
            std::string displayLabel = coef.displayLabel.empty() ? coef.term : coef.displayLabel;
            const std::string source = coef.sourceTerm.empty() ? coef.term : coef.sourceTerm;
            const bool nested = referenceRow || coef.rowType == "factor_level" ||
                (!coef.sourceTerm.empty() && coef.term != coef.sourceTerm);
            if (!nested && source.find(':') == std::string::npos &&
                state->centeredPredictors.count(source) != 0 &&
                displayLabel.find("(centered)") == std::string::npos) {
                displayLabel += " (centered)";
            }
            if (referenceRow && displayLabel.find("reference") == std::string::npos) displayLabel += " (reference)";
            return ToNSString(displayLabel);
        }
        if ([identifier isEqualToString:@"type"]) {
            if (sectionRow) return @"";
            if (coef.term == "(Intercept)" || coef.sourceTerm == "(Intercept)") return @"-";
            if (coef.rowType == "reference" || coef.rowType == "factor_level" ||
                (rlispstat::core::ModelTermTypeIsInteraction(coef.termType) && coef.rowType == "coefficient" &&
                 !coef.sourceTerm.empty() && coef.sourceTerm != coef.term)) return @"";
            return coef.termType.empty() ? @"-" : ToNSString(rlispstat::core::ModelTermTypeDisplayName(coef.termType));
        }
        if ([identifier isEqualToString:@"estimate"]) {
            if (sectionRow || parentRow) return @"";
            return (referenceRow) ? @"\U00002014" : ToNSString(state->binaryRegression
                ? FormatModelNumberOrDash(coef.estimate) : FormatDoubleOrDash(coef.estimate, 4));
        }
        if ([identifier isEqualToString:@"stderr"]) {
            if (sectionRow || parentRow) return @"";
            return (referenceRow) ? @"\U00002014" : ToNSString(state->binaryRegression
                ? FormatModelNumberOrDash(coef.stdError) : FormatDoubleOrDash(coef.stdError, 4));
        }
        if ([identifier isEqualToString:@"stat"]) {
            if (sectionRow) return @"";
            if (referenceRow) return @"\U00002014";
            if (parentRow) return termTest
                ? ToNSString(FormatDoubleOrDash(termTest->statistic, 3) +
                    (std::isfinite(termTest->statistic) &&
                     termTest->method == "Rubin Wald chi-square" ? "†" : ""))
                : @"\U00002014";
            return ToNSString(state->binaryRegression
                ? FormatModelNumberOrDash(coef.statistic) : FormatDoubleOrDash(coef.statistic, 3));
        }
        if ([identifier isEqualToString:@"p"]) {
            if (sectionRow) return @"";
            if (referenceRow) return @"\U00002014";
            if (parentRow) return termTest
                ? ToNSString(FormatPValue(termTest->pValue)) : @"\U00002014";
            return ToNSString(FormatPValue(coef.pValue));
        }
        if ([identifier isEqualToString:@"effect_ci"]) {
            if (sectionRow || parentRow) return @"";
            if (referenceRow) return @"\U00002014";
            if (rlispstat::core::GeneralizedModelHasExponentiatedEffect(*state)) {
                return ToNSString(FormatModelNumberOrDash(coef.exponentiatedEstimate) + " [" +
                    FormatModelNumberOrDash(coef.exponentiatedLower) + ", " +
                    FormatModelNumberOrDash(coef.exponentiatedUpper) + "]");
            }
            return ToNSString("[" + FormatModelNumberOrDash(coef.ciLower) + ", " +
                FormatModelNumberOrDash(coef.ciUpper) + "]");
        }
        if ([identifier isEqualToString:@"exponentiated_effect"]) {
            if (sectionRow || parentRow) return @"";
            if (referenceRow) return @"\U00002014";
            return ToNSString(FormatModelNumberOrDash(coef.exponentiatedEstimate) + " [" +
                FormatModelNumberOrDash(coef.exponentiatedLower) + ", " +
                FormatModelNumberOrDash(coef.exponentiatedUpper) + "]");
        }
        return @"";
    }

    if (row == 0) {
        if ([identifier isEqualToString:@"term"]) return @"(Intercept)";
        if ([identifier isEqualToString:@"type"]) return @"-";
        return @"\U00002014";
    }
    NSInteger termRow = row - 1;
    if (termRow >= 0 && (size_t)termRow < state->terms.size()) {
        const std::string &term = state->terms[(size_t)termRow];
        if ([identifier isEqualToString:@"term"]) {
            return ToNSString(state->centeredPredictors.count(term) != 0
                ? term + " (centered)" : term);
        }
        if ([identifier isEqualToString:@"type"]) {
            // Binary Regression uses the same model-local term specification as
            // the generalized model.  The worksheet type is only its default.
            const std::string type = rlispstat::core::ModelSpecificationTermType(*state, term);
            return ToNSString(rlispstat::core::ModelTermTypeDisplayName(type));
        }
        return @"\U00002014";
    }
    return @"";
}

- (void)refresh
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    _refreshing = YES;
    const std::string windowTitle = rlispstat::core::StatisticalModelWindowTitle(
        state->modelType, state->multipleImputation);
    [_window setTitle:ToNSString(windowTitle)];
    [_titleField setStringValue:ToNSString(windowTitle)];
    [_badgeField setStringValue:ToNSString(state->multipleImputation && state->imputationCount > 0
        ? "m = " + std::to_string(state->imputationCount)
        : state->group)];
    [_responsePopup removeAllItems];
    std::set<int> validationRows;
    if (state->dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
        validationRows.insert(state->dataScope.originalRowIds.begin(),
                              state->dataScope.originalRowIds.end());
    }
    if (state->binaryRegression) {
        for (const std::string &name : VariableNamesForModel(&state->seed)) {
            const DataColumn *column = FindDataColumnForModel(&state->seed, name);
            if (column && rlispstat::core::InspectBinaryResponse(*column, validationRows).ok) {
                [_responsePopup addItemWithTitle:ToNSString(name)];
            }
        }
    } else {
        for (const std::string &name : rlispstat::core::NumericVariableNames(&state->seed)) {
            const DataColumn *column = FindDataColumnForModel(&state->seed, name);
            bool valid = column != nullptr;
            if (valid && state->modelType == rlispstat::core::StatisticalModelType::Count) {
                valid = rlispstat::core::InspectCountResponse(*column, validationRows).ok;
            } else if (valid && state->modelType == rlispstat::core::StatisticalModelType::PositiveContinuous) {
                const auto *distribution =
                    rlispstat::core::FindDistributionSpecification(state->family);
                valid = rlispstat::core::InspectResponseDomain(
                    *column,
                    distribution ? distribution->responseDomain
                                 : rlispstat::core::ResponseDomain::Continuous,
                    validationRows).ok;
            } else if (valid && state->modelType == rlispstat::core::StatisticalModelType::Proportion) {
                const auto domain = state->family == "beta"
                    ? rlispstat::core::ResponseDomain::OpenUnitInterval
                    : rlispstat::core::ResponseDomain::OpenClosedUnitInterval;
                valid = rlispstat::core::InspectResponseDomain(
                    *column, domain, validationRows).ok;
            }
            if (valid) [_responsePopup addItemWithTitle:ToNSString(name)];
        }
    }
    [_responsePopup selectItemWithTitle:ToNSString(state->response)];
	    if (state->binaryRegression) {
	        [_familyLabel setStringValue:@"Distribution"];
	        [_linkLabel setStringValue:@"Link"];
	        [_familyPopup removeAllItems];
	        [_familyPopup addItemWithTitle:@"Binomial"];
	        [[_familyPopup lastItem] setRepresentedObject:@"binomial"];
	        [_familyPopup selectItemAtIndex:0];
	        [_familyLabel setFrame:NSMakeRect(236, NSMinY([_familyLabel frame]), 82, 22)];
	        [_familyPopup setFrame:NSMakeRect(318, NSMinY([_familyPopup frame]), 112, 24)];
	        [_eventPopup removeAllItems];
	        [_eventPopup addItemWithTitle:ToNSString(state->responseCoding.referenceLabel)];
	        [_eventPopup addItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
	        [_eventPopup selectItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
	        [_eventLabel setHidden:NO];
	        [_eventPopup setHidden:NO];
	        [_binaryReferenceField setStringValue:ToNSString("Reference category: " + state->responseCoding.referenceLabel)];
	        [_binaryReferenceField setHidden:NO];
	        [_linkLabel setFrame:NSMakeRect(440, NSMinY([_linkLabel frame]), 36, 22)];
	        [_linkPopup setFrame:NSMakeRect(476, NSMinY([_linkPopup frame]), 118, 24)];
	    } else {
	        [_eventLabel setHidden:YES];
	        [_eventPopup setHidden:YES];
	        [_familyLabel setStringValue:ToNSString(rlispstat::core::GLMFamilyFieldLabel())];
	        [_familyPopup removeAllItems];
	        for (const auto &distribution :
	             rlispstat::core::DistributionSpecificationsForModel(state->modelType)) {
	            [_familyPopup addItemWithTitle:ToNSString(distribution.visibleName)];
	            [[_familyPopup lastItem] setRepresentedObject:ToNSString(distribution.id)];
	        }
	        std::string selectedDistribution = state->countRegression
	            ? rlispstat::core::CountDistributionId(state->countDistribution)
	            : state->family;
	        if (state->countRegression &&
	            state->countDistribution == rlispstat::core::CountDistribution::QuasiPoisson) {
	            selectedDistribution = "poisson";
	        }
	        for (NSMenuItem *item in [_familyPopup itemArray]) {
	            if ([[[item representedObject] description]
	                    isEqualToString:ToNSString(selectedDistribution)]) {
	                [_familyPopup selectItem:item];
	                break;
	            }
	        }
	        [_binaryReferenceField setHidden:YES];
	        [_familyLabel setFrame:NSMakeRect(236, NSMinY([_familyLabel frame]), 82, 22)];
	        [_familyPopup setFrame:NSMakeRect(318, NSMinY([_familyPopup frame]), 146, 24)];
	        [_linkLabel setFrame:NSMakeRect(472, NSMinY([_linkLabel frame]), 36, 22)];
	        [_linkPopup setFrame:NSMakeRect(508, NSMinY([_linkPopup frame]), 86, 24)];
	    }
	    [self populateLinkPopupForFamily:state->family selected:state->link];
	    const bool boundedResponse = !state->binaryRegression &&
	        state->modelType != rlispstat::core::StatisticalModelType::Proportion &&
	        rlispstat::core::GeneralizedFamilyRequiresResponseBounds(state->family);
	    const bool boundedCount = state->countRegression &&
	        rlispstat::core::CountDistributionUsesTrials(state->countDistribution);
	    const bool countInference = state->modelType ==
	        rlispstat::core::StatisticalModelType::Count && !boundedCount;
	    [_inferenceLabel setHidden:!countInference];
	    [_inferencePopup setHidden:!countInference];
	    if (countInference) {
	        [_inferencePopup selectItemWithTitle:
	            state->countDistribution == rlispstat::core::CountDistribution::QuasiPoisson
	                ? @"Quasi-Poisson" : @"Standard likelihood"];
	    }
	    [_boundsLabel setHidden:!boundedResponse];
	    [_lowerBoundField setHidden:!boundedResponse];
	    [_boundsSeparatorLabel setHidden:!boundedResponse];
	    [_upperBoundField setHidden:!boundedResponse];
	    [_trialsLabel setHidden:!boundedCount];
	    [_trialsField setHidden:!boundedCount];
	    if (boundedCount) {
	        [_trialsField setStringValue:std::isfinite(state->trialsConstant)
	            ? ToNSString(FormatDoubleOrDash(state->trialsConstant, 0)) : @""];
	    }
	    if (boundedResponse) {
	        [_lowerBoundField setStringValue:state->responseBoundsConfigured
	            ? ToNSString(FormatDoubleOrDash(state->responseLower, 6)) : @""];
	        [_upperBoundField setStringValue:state->responseBoundsConfigured
	            ? ToNSString(FormatDoubleOrDash(state->responseUpper, 6)) : @""];
	    }
	    const bool supportsOffset = state->family != "beta_one_inflated" &&
	        (!state->countRegression ||
	         (state->countDistribution != rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling &&
	          state->countDistribution != rlispstat::core::CountDistribution::PerfectScore));
	    [_offsetLabel setHidden:!supportsOffset];
	    [_offsetPopup setHidden:!supportsOffset];
	    [_offsetPopup removeAllItems];
	    if (supportsOffset) {
	        [_offsetPopup addItemWithTitle:@"None"];
	        [[_offsetPopup lastItem] setRepresentedObject:@""];
	        for (const std::string &name : rlispstat::core::NumericVariableNames(&state->seed)) {
	            if (name == state->response || name == state->exposure) continue;
	            [_offsetPopup addItemWithTitle:ToNSString(name)];
	            [[_offsetPopup lastItem] setRepresentedObject:ToNSString(name)];
	        }
	        [_offsetPopup selectItemAtIndex:0];
	        for (NSMenuItem *item in [_offsetPopup itemArray]) {
	            if ([[[item representedObject] description]
	                    isEqualToString:ToNSString(state->offsetVariable)]) {
	                [_offsetPopup selectItem:item];
	                break;
	            }
	        }
	    }
	    PopulateAnalysisScopePopup(_scopePopup, state->group, state->scope,
	                               state->dataScope, state->dataScopeCaptured, true);
	    [_autoRefitButton setState:state->autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
	    [_residualPopup removeAllItems];
	    for (const std::string &type : rlispstat::core::AvailableGeneralizedResidualTypes(*state)) {
	        if (type == "dunn_smyth") [_residualPopup addItemWithTitle:ToNSString(rlispstat::core::GLMDunnSmythResidualTitle())];
	        else if (type == "raw") [_residualPopup addItemWithTitle:ToNSString(rlispstat::core::GLMRawResidualTitle())];
	        else if (type == "deviance") [_residualPopup addItemWithTitle:ToNSString(rlispstat::core::GLMDevianceResidualTitle())];
	        else if (type == "pearson") [_residualPopup addItemWithTitle:ToNSString(rlispstat::core::GLMPearsonResidualTitle())];
	        else if (type == "working") [_residualPopup addItemWithTitle:ToNSString(rlispstat::core::GLMWorkingResidualTitle())];
	    }
	    if (!rlispstat::core::IsGeneralizedResidualTypeAvailable(
	            *state, state->diagnosticOptions.residualType)) {
	        state->diagnosticOptions.residualType =
	            rlispstat::core::DefaultGeneralizedResidualType(*state);
	    }
	    NSString *selectedResidualTitle = state->diagnosticOptions.residualType == "dunn_smyth"
	        ? ToNSString(rlispstat::core::GLMDunnSmythResidualTitle())
	        : state->diagnosticOptions.residualType == "raw"
	            ? ToNSString(rlispstat::core::GLMRawResidualTitle())
	            : state->diagnosticOptions.residualType == "pearson"
	                ? ToNSString(rlispstat::core::GLMPearsonResidualTitle())
	                : state->diagnosticOptions.residualType == "working"
	                    ? ToNSString(rlispstat::core::GLMWorkingResidualTitle())
	                    : ToNSString(rlispstat::core::GLMDevianceResidualTitle());
	    [_residualPopup selectItemWithTitle:selectedResidualTitle];
    [_responsePopup setEnabled:(!state->precomputed || state->multipleImputation)];
    [_familyPopup setEnabled:!state->binaryRegression &&
        (!state->precomputed || state->multipleImputation)];
	    [_eventPopup setEnabled:(!state->precomputed || state->multipleImputation)];
    [_linkPopup setEnabled:(!state->precomputed || state->multipleImputation)];
	    [_inferencePopup setEnabled:(!state->precomputed || state->multipleImputation)];
	    [_lowerBoundField setEnabled:(!state->precomputed || state->multipleImputation)];
	    [_upperBoundField setEnabled:(!state->precomputed || state->multipleImputation)];
	    [_trialsField setEnabled:(!state->precomputed || state->multipleImputation)];
	    [_offsetPopup setEnabled:(!state->precomputed || state->multipleImputation)];
	    [_scopePopup setEnabled:(!state->precomputed || state->multipleImputation)];
    [_autoRefitButton setEnabled:(!state->precomputed || state->multipleImputation)];
	    const bool neverRequestedCurrentSpecification = state->lastRFitSignature.empty();
	    if ((!state->precomputed || state->multipleImputation) && state->autoRefit &&
	        (state->fitVersion < state->modelVersion ||
	         (!state->ok && neverRequestedCurrentSpecification))) {
	        RequestGeneralizedGLMFitInMainR(*state);
	    }
    bool keepCurrentReportWhilePending = state->rFitPending && state->ok;
    NSSize contentSize = [[_window contentView] frame].size;
    [_reportScrollView setFrame:NSMakeRect(14, 64, std::max((CGFloat)220.0, contentSize.width - 28.0),
                                             std::max((CGFloat)120.0, contentSize.height - 206.0))];
    if (!keepCurrentReportWhilePending) {
        NSSize wanted = [_reportView preferredContentSize];
        contentSize = FitResultTableWindowToContent(
            _window,
            NSMakeSize(wanted.width + 28.0, wanted.height + 206.0),
            NSMakeSize(780.0, 540.0));
        _hasSizedToContent = YES;
        [_reportScrollView setFrame:NSMakeRect(14, 64, std::max((CGFloat)220.0, contentSize.width - 28.0),
                                                 std::max((CGFloat)120.0, contentSize.height - 206.0))];
        [_reportView setFrame:NSMakeRect(0, 0, std::max(wanted.width, [_reportScrollView contentSize].width), wanted.height)];
        [_reportView setNeedsDisplay:YES];
    }
    size_t selected = SelectionCount(state->group);
    size_t total = state->seed.points.size();
    if (state->precomputed && !state->note.empty()) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(state->note))];
    } else {
        const bool manualFitPending =
            rlispstat::core::GeneralizedGLMHasPendingManualFit(*state);
        std::string status = manualFitPending
            ? "Status: " + rlispstat::core::GeneralizedGLMPendingManualFitStatus()
            : GeneralizedGLMWindowStatus(state->status, selected, total,
                                         state->family, state->link);
        if (state->binaryRegression && !manualFitPending) {
            status = state->ok
                ? "Status: fitted on " + std::to_string(state->n) + " rows; " + std::to_string(state->excluded) +
                    " excluded. Event: " + state->responseCoding.eventLabel + "; reference: " + state->responseCoding.referenceLabel + "."
                : "Status: " + state->status;
        }
        [_statusField setStringValue:ToNSString(status)];
    }
    if (state->dataScopeCaptured) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(rlispstat::core::AnalysisScopeWindowSummary(
                state->dataScope, state->dataScope.totalDatasetRows))]];
    }
    if (!state->frozenScopeNotice.empty()) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(state->frozenScopeNotice)]];
    }
	[_statusField setToolTip:[_statusField stringValue]];
    if (!state->rFitPending && [_taskCancelPath length]) {
        [_taskCancelPath release];
        _taskCancelPath = nil;
        [_cancelTaskButton setHidden:YES];
        [_cancelTaskButton setEnabled:YES];
        [_statusField setFrameSize:NSMakeSize(
            MAX(200.0, [[_window contentView] bounds].size.width - 32.0), 34.0)];
    }
    _refreshing = NO;
}

- (void)markChangedAndRefresh
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        [self refresh];
        return;
    }
    state->modelVersion += 1;
    // Any specification edit invalidates the in-flight request immediately.
    // Auto-refit below will create a new generation; with auto-refit off the
    // cleared pending flag still prevents the old result from being accepted.
    state->rFitPending = false;
    if (state->response.empty()) {
        state->ok = false;
        state->status = rlispstat::core::GLMChooseResponseVariableStatus();
    } else if (state->terms.empty() && !state->binaryRegression && !state->countRegression) {
        state->ok = false;
        state->status = rlispstat::core::GLMAddPredictorBeforeTableStatus();
    }
    if (state->autoRefit) {
        RequestGeneralizedGLMFitInMainR(*state);
    } else {
        state->status = rlispstat::core::GeneralizedGLMPendingManualFitStatus();
    }
    [self refresh];
}

- (void)responseChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    const std::string response = std::string([[[_responsePopup selectedItem] title] UTF8String]);
    const auto edit = rlispstat::core::SetModelSpecificationResponse(*state, response);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (!edit.changed) return;
    if (state->exposure == response) state->exposure.clear();
    if (state->offsetVariable == response) state->offsetVariable.clear();
    if (state->binaryRegression) {
        const DataColumn *column = FindDataColumnForModel(&state->seed, state->response);
        state->responseCoding = column ? rlispstat::core::InspectBinaryResponse(*column)
                                       : rlispstat::core::BinaryResponseCoding{};
        state->responseCodingExplicit = false;
    }
    [self markChangedAndRefresh];
}

- (void)familyChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    if (state->binaryRegression) return;
    NSMenuItem *selectedItem = [_familyPopup selectedItem];
    NSString *represented = [[selectedItem representedObject] description];
    std::string distribution = represented.length
        ? std::string([represented UTF8String])
        : std::string([[selectedItem title] UTF8String]);
    if (!rlispstat::core::DistributionIsAvailableForModel(state->modelType, distribution)) return;
    if (state->countRegression) {
        rlispstat::core::CountDistribution parsed;
        if (!rlispstat::core::ParseCountDistribution(distribution, parsed) ||
            parsed == rlispstat::core::CountDistribution::QuasiPoisson) return;
        state->countDistribution = parsed;
        const bool bounded = rlispstat::core::CountDistributionUsesTrials(parsed);
        state->family = parsed == rlispstat::core::CountDistribution::QuasiPoisson
            ? "quasipoisson" : bounded ? "binomial" : "poisson";
        state->link = bounded ? "logit" : "log";
        if (bounded) state->exposure.clear();
        if (parsed == rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling ||
            parsed == rlispstat::core::CountDistribution::PerfectScore)
            state->offsetVariable.clear();
    } else {
        state->family = distribution;
        if (distribution == "beta_one_inflated") state->offsetVariable.clear();
    }
    const std::string defaultLink = rlispstat::core::DefaultLinkForModelDistribution(
        state->modelType, distribution);
    const auto links = rlispstat::core::LinksForModelDistribution(
        state->modelType, distribution);
    if (std::find(links.begin(), links.end(), state->link) == links.end()) {
        state->link = defaultLink;
    }
    [self markChangedAndRefresh];
}

- (void)trialsChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->countRegression ||
        !rlispstat::core::CountDistributionUsesTrials(state->countDistribution)) return;
    const std::string text = std::string([[_trialsField stringValue] UTF8String]);
    char *end = nullptr;
    const double value = std::strtod(text.c_str(), &end);
    if (!end || end == text.c_str() || *end != '\0' || !std::isfinite(value) ||
        value <= 0.0 || std::floor(value) != value) {
        state->trialsVariable.clear();
        state->trialsConstant = NAN;
        state->rFitPending = false;
        state->ok = false;
        state->status = "Trials must be a fixed positive integer.";
        [_statusField setStringValue:ToNSString("Status: " + state->status)];
        return;
    }
    if (state->trialsVariable.empty() && state->trialsConstant == value) return;
    state->trialsVariable.clear();
    state->trialsConstant = value;
    [self markChangedAndRefresh];
}

- (void)eventChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    std::string selected = std::string([[[_eventPopup selectedItem] title] UTF8String]);
        if (selected == state->responseCoding.referenceLabel) {
            std::swap(state->responseCoding.eventValue, state->responseCoding.referenceValue);
            std::swap(state->responseCoding.eventLabel, state->responseCoding.referenceLabel);
            std::swap(state->responseCoding.eventCount, state->responseCoding.referenceCount);
        }
        state->responseCodingExplicit = true;
        [self markChangedAndRefresh];
}

- (void)inferenceChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->countRegression) return;
    const bool quasi = [[[_inferencePopup selectedItem] title]
        isEqualToString:@"Quasi-Poisson"];
    if (quasi) {
        state->countDistribution = rlispstat::core::CountDistribution::QuasiPoisson;
        state->family = "quasipoisson";
        state->link = "log";
    } else if (state->countDistribution == rlispstat::core::CountDistribution::QuasiPoisson) {
        state->countDistribution = rlispstat::core::CountDistribution::Poisson;
        state->family = "poisson";
        state->link = "log";
    }
    [self markChangedAndRefresh];
}

- (void)linkChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    std::string candidate = std::string([[[_linkPopup selectedItem] title] UTF8String]);
    if (state->binaryRegression) {
        rlispstat::core::BinaryLink parsed;
        if (rlispstat::core::ParseBinaryLink(candidate, parsed)) {
            state->binaryLink = parsed;
            state->link = rlispstat::core::BinaryLinkId(parsed);
            [self markChangedAndRefresh];
        }
        return;
    }
    const std::string distribution = state->countRegression
        ? rlispstat::core::CountDistributionId(state->countDistribution)
        : state->family;
    const auto links = rlispstat::core::LinksForModelDistribution(
        state->modelType, distribution);
    if ((!links.empty() && std::find(links.begin(), links.end(), candidate) != links.end()) ||
        (state->modelType == rlispstat::core::StatisticalModelType::LegacyGeneralized &&
         IsValidGeneralizedLink(state->family, candidate))) {
        state->link = candidate;
        [self markChangedAndRefresh];
    }
}

- (void)responseBoundsChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    const std::string lowerText = std::string([[_lowerBoundField stringValue] UTF8String]);
    const std::string upperText = std::string([[_upperBoundField stringValue] UTF8String]);
    char *lowerEnd = nullptr;
    char *upperEnd = nullptr;
    const double lower = std::strtod(lowerText.c_str(), &lowerEnd);
    const double upper = std::strtod(upperText.c_str(), &upperEnd);
    const bool valid = lowerEnd && upperEnd && lowerEnd != lowerText.c_str() &&
        upperEnd != upperText.c_str() && *lowerEnd == '\0' && *upperEnd == '\0' &&
        std::isfinite(lower) && std::isfinite(upper) && lower < upper;
    if (!valid) {
        state->responseBoundsConfigured = false;
        state->ok = false;
        state->status = "Enter finite response bounds with lower < upper.";
        [self refresh];
        return;
    }
    if (state->responseBoundsConfigured && state->responseLower == lower &&
        state->responseUpper == upper) return;
    state->responseBoundsConfigured = true;
    state->responseLower = lower;
    state->responseUpper = upper;
    [self markChangedAndRefresh];
}

- (void)scopeChanged:(id)sender
{
    (void)sender; // Scope is configured only through the global Analysis Scope menu.
}

- (void)autoRefitChanged:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    state->autoRefit = [_autoRefitButton state] == NSControlStateValueOn;
    if (state->autoRefit) [self markChangedAndRefresh];
    else [self refresh];
}

- (void)residualTypeChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    NSString *title = [[_residualPopup selectedItem] title];
    const std::string residualType =
        [title isEqualToString:ToNSString(rlispstat::core::GLMDunnSmythResidualTitle())]
            ? "dunn_smyth"
            : [title isEqualToString:ToNSString(rlispstat::core::GLMRawResidualTitle())]
                ? "raw"
                : [title isEqualToString:ToNSString(rlispstat::core::GLMPearsonResidualTitle())]
                    ? "pearson"
                    : [title isEqualToString:ToNSString(rlispstat::core::GLMWorkingResidualTitle())]
                        ? "working" : "deviance";
    if (!rlispstat::core::IsGeneralizedResidualTypeAvailable(*state, residualType)) return;
    if (state->diagnosticOptions.residualType != residualType) {
        state->diagnosticOptions.residualType = residualType;
        ++state->diagnosticOptions.version;
    }
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(state->group, true);
    [self refresh];
}

