- (void)selectModelOptionFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSString *kind = [payload objectAtIndex:0];
    NSString *title = [payload objectAtIndex:1];
    NSPopUpButton *popup = nil;
    SEL action = nil;
    if ([kind isEqualToString:@"response"]) { popup = _responsePopup; action = @selector(responseChanged:); }
    else if ([kind isEqualToString:@"family"]) { popup = _familyPopup; action = @selector(familyChanged:); }
    else if ([kind isEqualToString:@"event"]) { popup = _eventPopup; action = @selector(eventChanged:); }
    else if ([kind isEqualToString:@"link"]) { popup = _linkPopup; action = @selector(linkChanged:); }
    else if ([kind isEqualToString:@"scope"]) { popup = _scopePopup; action = @selector(scopeChanged:); }
    else if ([kind isEqualToString:@"residual"]) { popup = _residualPopup; action = @selector(residualTypeChanged:); }
    if (!popup || !action || ![popup itemWithTitle:title]) return;
    [popup selectItemWithTitle:title];
    [self performSelector:action withObject:popup];
}

- (void)setModelTermTypeFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    GeneralizedGLMState *state = [self state];
    if (!state || ![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    const std::string term = [[payload objectAtIndex:0] UTF8String];
    const std::string type = [[payload objectAtIndex:1] UTF8String];
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    const auto edit = rlispstat::core::SetModelSpecificationTermType(
        *state, term, type, metadata);
    if (!edit.ok) { [_statusField setStringValue:ToNSString(edit.message)]; return; }
    if (edit.changed) [self markChangedAndRefresh];
}

- (void)toggleModelTermCenteringFromMenu:(id)sender
{
    NSString *represented = [sender representedObject];
    GeneralizedGLMState *state = [self state];
    if (!state || ![represented isKindOfClass:[NSString class]]) return;
    const std::string term = [represented UTF8String];
    const bool centered = state->centeredPredictors.count(term) == 0;
    const auto edit = rlispstat::core::SetModelSpecificationPredictorCentered(
        *state, term, centered);
    if (!edit.ok) { [_statusField setStringValue:ToNSString(edit.message)]; return; }
    if (edit.changed) [self markChangedAndRefresh];
}

- (void)setModelReferenceFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
