- (NSMenuItem *)modelExportMenuItem
{
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    GeneralizedGLMState *state = [self state];
    if (state) {
        const std::string exportTitle = rlispstat::core::StatisticalModelWindowTitle(
            state->modelType, state->multipleImputation);
        const std::string exportBaseName = state->binaryRegression
            ? "binary-regression"
            : (state->countRegression
                ? "count-model"
                : rlispstat::core::StatisticalModelTypeId(state->modelType) + "-model");
        const auto reportTables = rlispstat::core::GeneralizedModelReportTables(*state);
        const auto publicationTable = rlispstat::core::GeneralizedModelPublicationTable(*state);
        AddStandardTableVisualExportItems(exportMenu, _reportView,
            ToNSString(exportTitle), ToNSString(exportBaseName),
            [self formattedOutputForState:state], &publicationTable, &reportTables);
        AddRCodeExportItems(exportMenu, "output", state->id, true);
    }
    if (state && state->binaryRegression) {
        [exportMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *csvRoot = [[NSMenuItem alloc] initWithTitle:@"CSV" action:nil keyEquivalent:@""];
        NSMenu *csvMenu = [[NSMenu alloc] initWithTitle:@"CSV"];
        [csvMenu addItem:[self modelMenuItem:@"Terms and coefficients…" action:@selector(exportBinaryCSV:) represented:@"coefficients"]];
        [csvMenu addItem:[self modelMenuItem:@"Model details…" action:@selector(exportBinaryCSV:) represented:@"model_fit"]];
        [exportMenu setSubmenu:csvMenu forItem:csvRoot];
        [exportMenu addItem:csvRoot];
    }

    OrganizeExportMenu(exportMenu);
    [root setSubmenu:exportMenu];
    return root;
}

- (void)copyMenuValue:(id)sender
{
    NSString *value = [sender representedObject];
    if (!value) value = @"";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:value forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(GLMValueCopiedStatus())];
}

- (void)explainGeneralizedStatistic:(id)sender
{
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    std::string statistic = [represented isKindOfClass:[NSString class]]
        ? [(NSString *)represented UTF8String] : "Model fit";
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    auto context = rlispstat::core::GeneralizedModelStatisticContext(
        *state, statistic, (int)_selectedCoefRow);
    statistic = context.statistic;
    if (state->multipleImputation) {
        DataFrameModel dataframe;
        if (DataFrameSnapshotForGroup(state->group, dataframe)) {
            context.rubinRulesApplied =
                !rlispstat::core::RowsWithImputedModelInputs(
                    dataframe, *state, {state->offsetVariable}).empty();
        }
    }
    ShowWorkbenchMessageOnMain(
        ToNSString("Explain statistic: " + statistic),
        ToNSString(rlispstat::core::ExplainModelStatistic(context)));
}

- (void)showCoefficientDetails:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || _selectedCoefRow < 0 || [self isAddTermRow:_selectedCoefRow]) return;
    if (!state->ok || _selectedCoefRow >= (NSInteger)state->rows.size()) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(state->status))];
        return;
    }
    const GeneralizedGLMRow &coef = state->rows[(size_t)_selectedCoefRow];
    [_statusField setStringValue:ToNSString(GeneralizedCoefficientDetailsStatus(coef, state->statisticName))];
}

- (void)showModelDetails:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    _showModelDetails = !_showModelDetails;
    [self refresh];
    [_statusField setStringValue:_showModelDetails
        ? @"Status: model details shown in the results table."
        : @"Status: model details hidden."];
}

- (NSMenu *)statisticContextMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    GeneralizedGLMState *state = [self state];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.statistic)];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.copyValue) action:@selector(copyMenuValue:) keyEquivalent:@""];
    [copy setTarget:self];
    [copy setRepresentedObject:[self coefficientValueForRow:row column:column]];
    [menu addItem:copy];
    NSMenuItem *details = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.showCoefficientDetails) action:@selector(showCoefficientDetails:) keyEquivalent:@""];
    [details setTarget:self];
    [menu addItem:details];
    NSMenuItem *explain = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.explainStatistic)
        action:@selector(explainGeneralizedStatistic:)
        keyEquivalent:@""];
    [explain setTarget:self];
    [explain setRepresentedObject:[self coefficientColumnIdentifier:column]];
    [menu addItem:explain];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), state && state->binaryRegression,
        state && state->countRegression &&
            rlispstat::core::CountDistributionSupportsScoreDistribution(
                state->countDistribution),
        state && state->countRegression)];
    [menu addItem:[NSMenuItem separatorItem]];
    if (!state) {
        [menu addItem:[self modelMenuItem:ToNSString(titles.copyModelTable) action:@selector(copyModelTable:) represented:nil]];
    }
    [menu addItem:[self modelMenuItem:ToNSString(titles.compareModels)
                                action:@selector(openModelComparison:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    if (state) [menu addItem:[self modelExportMenuItem]];
    return menu;
}

- (NSMenu *)predictorContextMenuForTableRow:(NSInteger)row
{
    GeneralizedGLMState *state = [self state];
    std::string baseTerm = [self sourceTermForCoefficientRow:row];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Predictor"];
    if (!state || baseTerm.empty()) return menu;
    const bool isMainEffect = !IsInteractionTerm(baseTerm);
    NSMenuItem *remove = [[NSMenuItem alloc]
        initWithTitle:(isMainEffect ? @"Remove predictor" : @"Remove interaction")
        action:@selector(removeSelectedTerm:) keyEquivalent:@""];
    [remove setTarget:self];
    [remove setRepresentedObject:ToNSString(baseTerm)];
    [menu addItem:remove];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *heading = [[NSMenuItem alloc] initWithTitle:ToNSString(baseTerm)
        action:nil keyEquivalent:@""];
    [heading setEnabled:NO]; [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];

    const std::string termType = rlispstat::core::ModelSpecificationTermType(
        *state, baseTerm, rlispstat::core::DefaultTermType(&state->seed, baseTerm));
    NSMenuItem *analyzeRoot = [[NSMenuItem alloc]
        initWithTitle:@"Analyze predictor" action:nil keyEquivalent:@""];
    NSMenu *analyzeMenu = [[NSMenu alloc] initWithTitle:@"Analyze predictor"];
    if (IsInteractionTerm(baseTerm)) {
        NSMenuItem *interpret = [[NSMenuItem alloc]
            initWithTitle:@"Interpret interaction…"
            action:@selector(openGeneralizedInteractionReport:)
            keyEquivalent:@""];
        [interpret setTarget:self];
        [interpret setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:interpret];
        NSMenuItem *plot = [[NSMenuItem alloc]
            initWithTitle:@"Effect plot…"
            action:@selector(openGeneralizedInteractionPlot:)
            keyEquivalent:@""];
        [plot setTarget:self];
        [plot setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:plot];
    } else {
        NSMenuItem *effect = [[NSMenuItem alloc]
            initWithTitle:@"Effect plot…"
            action:@selector(openGeneralizedInteractionPlot:)
            keyEquivalent:@""];
        [effect setTarget:self];
        [effect setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:effect];
        NSMenuItem *partial = [[NSMenuItem alloc]
            initWithTitle:@"Partial regression plot…"
            action:@selector(openGeneralizedPartialRegressionPlot:)
            keyEquivalent:@""];
        [partial setTarget:self];
        [partial setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:partial];
    }
    if (!IsInteractionTerm(baseTerm) &&
        (termType == "factor" || termType == "ordered")) {
        NSMenuItem *pairwise = [[NSMenuItem alloc]
            initWithTitle:@"Pairwise comparisons…"
            action:@selector(openGeneralizedPairwiseComparisons:)
            keyEquivalent:@""];
        [pairwise setTarget:self];
        [pairwise setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:pairwise];
    }
    if ([[analyzeMenu itemArray] count]) {
        [analyzeRoot setSubmenu:analyzeMenu];
        [menu addItem:analyzeRoot];
    }
    NSMenuItem *modelTermsRoot = [[NSMenuItem alloc]
        initWithTitle:@"Model terms" action:nil keyEquivalent:@""];
    NSMenu *modelTermsMenu = [[NSMenu alloc] initWithTitle:@"Model terms"];
    NSMenuItem *editRoot = [[NSMenuItem alloc]
        initWithTitle:@"Edit predictor" action:nil keyEquivalent:@""];
    NSMenu *editMenu = [[NSMenu alloc] initWithTitle:@"Edit predictor"];
    if (isMainEffect) {
        NSInteger termIndex = -1;
        for (size_t index = 0; index < state->terms.size(); ++index)
            if (state->terms[index] == baseTerm) { termIndex = (NSInteger)index; break; }
        NSMenuItem *changeRoot = [[NSMenuItem alloc] initWithTitle:@"Change variable"
            action:nil keyEquivalent:@""];
        NSMenu *changeMenu = [[NSMenu alloc] initWithTitle:@"Change variable"];
        for (const std::string &candidate : VariableNamesForModel(&state->seed)) {
            if (candidate == state->response || candidate == baseTerm ||
                std::find(state->terms.begin(), state->terms.end(), candidate) != state->terms.end()) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(candidate)
                action:@selector(replaceTermFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:@[@(termIndex), ToNSString(candidate)]];
            [changeMenu addItem:item];
        }
        [changeRoot setSubmenu:changeMenu]; [editMenu addItem:changeRoot];

        NSMenuItem *typeRoot = [[NSMenuItem alloc] initWithTitle:@"Change type"
            action:nil keyEquivalent:@""];
        NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:@"Change type"];
        AddModelTermTypeMenuItems(typeMenu, self, @selector(typeMenuSelected:), termType);
        [typeRoot setSubmenu:typeMenu]; [editMenu addItem:typeRoot];

        if (termType == "factor") {
            DataFrameModel dataframe;
            if (DataFrameSnapshotForGroup(state->group, dataframe)) {
                const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
                    state->seed, &dataframe, baseTerm);
                if (metadata.levels.size() > 1) {
                    NSMenuItem *referenceRoot = [[NSMenuItem alloc]
                        initWithTitle:@"Reference category" action:nil keyEquivalent:@""];
                    NSMenu *referenceMenu = [[NSMenu alloc] initWithTitle:@"Reference category"];
                    const auto configured = state->factorReferenceLevels.find(baseTerm);
                    const std::string selected = configured == state->factorReferenceLevels.end()
                        ? metadata.levels.front() : configured->second;
                    for (const std::string &level : metadata.levels) {
                        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(level)
                            action:@selector(referenceMenuSelected:) keyEquivalent:@""];
                        [item setTarget:self]; [item setRepresentedObject:ToNSString(level)];
                        [item setState:level == selected ? NSControlStateValueOn : NSControlStateValueOff];
                        [referenceMenu addItem:item];
                    }
                    [referenceRoot setSubmenu:referenceMenu]; [editMenu addItem:referenceRoot];
                }
            }
        } else {
            const bool centered = state->centeredPredictors.count(baseTerm) != 0;
            NSMenuItem *center = [[NSMenuItem alloc]
                initWithTitle:(centered ? @"Remove centering" : @"Center predictor")
                action:@selector(toggleCenterSelectedPredictor:) keyEquivalent:@""];
            [center setTarget:self]; [editMenu addItem:center];
        }
    }
    if (!AddModelTermMenuItems(modelTermsMenu, self, @selector(addTermFromMenu:),
                                 &state->seed, state->response, state->terms, baseTerm, rlispstat::core::EffectiveModelSpecificationTermTypes(*state))) {
        NSMenuItem *disabled = [[NSMenuItem alloc] initWithTitle:@"No available interactions" action:nil keyEquivalent:@""];
        [disabled setEnabled:NO];
        [modelTermsMenu addItem:disabled];
    }
    if ([[modelTermsMenu itemArray] count]) {
        [modelTermsRoot setSubmenu:modelTermsMenu]; [menu addItem:modelTermsRoot];
    }
    if ([[editMenu itemArray] count]) {
        [editRoot setSubmenu:editMenu]; [menu addItem:editRoot];
    }
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), state->binaryRegression,
        state->countRegression &&
            rlispstat::core::CountDistributionSupportsScoreDistribution(
                state->countDistribution),
        state->countRegression)];
    [menu addItem:[self modelMenuItem:ToNSString(
        rlispstat::core::DefaultModelContextMenuTitles().compareModels)
        action:@selector(openModelComparison:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self modelExportMenuItem]];
    return menu;
}

- (void)toggleCenterSelectedPredictor:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    const std::string sourceTerm = [self sourceTermForCoefficientRow:_selectedCoefRow];
    if (!state || sourceTerm.empty() || IsInteractionTerm(sourceTerm)) return;
    const std::string term = rlispstat::core::BaseVariableForTermComponent(sourceTerm);
    const bool centered = state->centeredPredictors.count(term) == 0;
    const auto edit = rlispstat::core::SetModelSpecificationPredictorCentered(*state, term, centered);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (edit.changed) [self markChangedAndRefresh];
}

- (void)showReferenceMenuForSelectedPredictor:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    const std::string sourceTerm = [self sourceTermForCoefficientRow:_selectedCoefRow];
    if (!state || sourceTerm.empty() || IsInteractionTerm(sourceTerm)) return;
    const std::string term = rlispstat::core::BaseVariableForTermComponent(sourceTerm);
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    if (metadata.levels.empty()) return;
    const auto found = state->factorReferenceLevels.find(term);
    const std::string current = found == state->factorReferenceLevels.end()
        ? metadata.levels.front() : found->second;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Reference category"];
    for (const std::string &level : metadata.levels) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(level)
            action:@selector(referenceMenuSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(level)];
        [item setState:level == current ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
        [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails],
        [self state] && [self state]->countRegression,
        [self state] && [self state]->binaryRegression,
        [self state] && ([self state]->family == "Gamma" ||
                         [self state]->family == "gamma_distance"));
    NSRect rowRect = NSMakeRect(0, layout.coefRowsY + _selectedCoefRow * layout.rowHeight,
                                [_reportView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(layout.margin + 20.0, NSMaxY(rowRect)) inView:_reportView];
}

- (void)referenceMenuSelected:(id)sender
{
    NSString *selected = [sender representedObject];
    GeneralizedGLMState *state = [self state];
    const std::string sourceTerm = [self sourceTermForCoefficientRow:_selectedCoefRow];
    if (!selected || !state || sourceTerm.empty() || IsInteractionTerm(sourceTerm)) return;
    const std::string term = rlispstat::core::BaseVariableForTermComponent(sourceTerm);
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    const auto edit = rlispstat::core::SetModelSpecificationReferenceLevel(
        *state, term, [selected UTF8String], metadata.levels);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (edit.changed) [self markChangedAndRefresh];
}

- (void)openBinaryPairwiseComparisons:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *represented = [sender representedObject];
    if (!state || !state->binaryRegression || !represented) return;
    const std::string term([represented UTF8String]);
    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(state->group);
        if (!current) {
            [_statusField setStringValue:@"Status: dataset is no longer available."];
            return;
        }
        dataframe = *current;
    }
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    const DataColumn *factor = FindDataColumnInDataFrame(dataframe, term);
    if (factor) {
        std::set<std::string> seen;
        for (int row : state->rowsUsed) {
            if (row <= 0 || static_cast<std::size_t>(row) > factor->values.size()) continue;
            const std::string &value = factor->values[static_cast<std::size_t>(row - 1)];
            if (!DataCellIsMissing(value) && seen.insert(value).second) result.levels.push_back(value);
        }
        rlispstat::core::SortFactorLevelsLikeR(result.levels);
    }
    std::string message;
    if (!RunRBackedBinaryPairwiseComparisons(dataframe, *state, term, &result, &message)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink link = BuildGLMPairwiseComparisonPlotLink(
        state->group, dataframe, state->response, term, state->rowsUsed, result);
    link.sourceModelKind = "generalized_single";
    link.sourceModelId = state->id;
    link.sourceModelRevision = state->modelVersion;
    link.sourceFitVersion = state->fitVersion;
    link.method = result.method;
    link.levels = result.levels;
    link.binaryRegression = true;
    link.binaryOddsRatio = state->binaryLink == rlispstat::core::BinaryLink::Logit;
    link.multipleImputation = state->multipleImputation;
    link.poolingMethod = state->multipleImputation ? result.method : std::string();
    link.rowsByComparison.assign(result.comparisons.size(), {});
    link.observations.clear();
    link.rowsByLevel.clear();
    const DataColumn *response = FindDataColumnInDataFrame(dataframe, state->response);
    if (factor && response) {
        for (int row : state->rowsUsed) {
            if (row <= 0) continue;
            std::size_t index = static_cast<std::size_t>(row - 1);
            if (index >= factor->values.size() || index >= response->values.size()) continue;
            const std::string &level = factor->values[index];
            const std::string &observed = response->values[index];
            if (DataCellIsMissing(level) || DataCellIsMissing(observed)) continue;
            double binary = observed == state->responseCoding.eventValue ? 1.0 : 0.0;
            link.rowsByLevel[level].insert(row);
            link.observations.push_back({row, level, binary});
        }
        for (std::size_t index = 0; index < result.comparisons.size(); ++index) {
            const auto &comparison = result.comparisons[index];
            for (const std::string &level : {comparison.firstLevel, comparison.secondLevel}) {
                auto found = link.rowsByLevel.find(level);
                if (found != link.rowsByLevel.end()) link.rowsByComparison[index].insert(found->second.begin(), found->second.end());
            }
        }
    }
    ShowGLMPairwiseResultsWindowOnMain(term, result, link);
    [_statusField setStringValue:ToNSString("Pairwise comparisons calculated in R for " + term + ".")];
}

- (void)openGeneralizedPairwiseComparisons:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || !represented) return;
    const std::string term([represented UTF8String]);
    const auto termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(*state);
    const auto type = termTypes.find(term);
    if (type == termTypes.end() ||
        (type->second != "factor" && type->second != "ordered") ||
        std::find(state->terms.begin(), state->terms.end(), term) == state->terms.end() ||
        IsInteractionTerm(term)) {
        [_statusField setStringValue:@"Status: pairwise comparisons require an included categorical term."];
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    const std::string scope = ScopeForCapturedAnalysisScope(
        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneGeneralizedMISpec(
        GeneralizedGLMTaskForState(*state, state->rFitGeneration));
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    std::string message;
    if (!RunRBackedMIPairwiseComparisons(
            dataframe, "gglm_pairwise", "gglm_pairwise_" + state->id,
            state->response, state->terms, scope, modelSpec, term,
            &result, &message)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink link = BuildGLMPairwiseComparisonPlotLink(
        state->group, dataframe, state->response, term, state->rowsUsed, result);
    link.sourceModelKind = "generalized_single";
    link.sourceModelId = state->id;
    link.sourceModelRevision = state->modelVersion;
    link.sourceFitVersion = state->fitVersion;
    link.method = result.method;
    link.levels = result.levels;
    link.multipleImputation = true;
    link.poolingMethod = result.method;
    ShowGLMPairwiseResultsWindowOnMain(term, result, link);
    [_statusField setStringValue:ToNSString(
        "Pairwise comparisons calculated in R across all fitted imputations for " + term + ".")];
}

- (void)openGeneralizedInteractionReport:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || !represented) return;
    const std::string term([represented UTF8String]);
    if (term.empty() ||
        std::find(state->terms.begin(), state->terms.end(), term) == state->terms.end()) {
        [_statusField setStringValue:@"Status: select an included model effect."];
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    const std::string scope = ScopeForCapturedAnalysisScope(
        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneGeneralizedMISpec(
        GeneralizedGLMTaskForState(*state, state->rFitGeneration));
    const std::string response = state->response;
    const std::vector<std::string> terms = state->terms;
    const bool multipleImputation = state->multipleImputation;
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = "generalized_single";
    link.sourceModelId = state->id;
    link.sourceModelRevision = state->modelVersion;
    link.sourceFitVersion = state->fitVersion;
    link.group = state->group;
    link.term = term;
    link.binaryEffect = state->binaryRegression;
    link.boundedCountEffect = state->countRegression &&
        rlispstat::core::CountDistributionUsesTrials(state->countDistribution);
    if (state->countDistribution == rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling)
        link.effectQuantity = "overall_expected_score";
    else if (state->countDistribution == rlispstat::core::CountDistribution::PerfectScore)
        link.effectQuantity = "predicted_probability";
    else if (link.boundedCountEffect) link.effectQuantity = "expected_count";
    link.title = "Effect: " + term;
    const std::string jobKey = link.sourceModelKind + "|" +
        link.sourceModelId + "|" + term + "|" +
        std::to_string(link.sourceModelRevision) + "|" +
        std::to_string(link.sourceFitVersion);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!g_pendingInteractionReportJobs.insert(jobKey).second) {
            [_statusField setStringValue:ToNSString(
                "The effect interpretation for " + term +
                " is already being calculated in R…")];
            return;
        }
    }
    [_statusField setStringValue:ToNSString(
        "Calculating the effect interpretation in R for " + term + "…")];
    NSTextField *statusField = [_statusField retain];
    std::thread worker([dataframe, response, terms, scope, modelSpec, term,
                        link, multipleImputation, statusField, jobKey]() mutable {
        std::string body;
        std::string message;
        const std::string analysisId = "gglm_interaction_" + link.sourceModelId;
        const bool ok = RunRBackedMIInteractionReport(
            dataframe, "gglm_interaction", analysisId,
            response, terms, scope, modelSpec, term, &body, &message,
            std::numeric_limits<double>::quiet_NaN(), link);
        dispatch_async(dispatch_get_main_queue(), ^{
            bool current = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pendingInteractionReportJobs.erase(jobKey);
                auto found = g_generalizedGLMs.find(link.sourceModelId);
                current = found != g_generalizedGLMs.end() &&
                    found->second.modelVersion == link.sourceModelRevision &&
                    found->second.fitVersion == link.sourceFitVersion;
            }
            std::string applyMessage = message;
            if (ok && current) {
                ShowGLMInteractionReportWindowOnMain(link.title, body, link);
                [statusField setStringValue:ToNSString(multipleImputation
                    ? "Effect interpreted across all fitted imputations in R for " + term + "."
                    : "Effect interpreted from the R fit for " + term + ".")];
            } else {
                if (ok && !current) {
                    applyMessage = "The model changed while the effect was being interpreted; request it again.";
                }
                [statusField setStringValue:ToNSString(GLMStatusMessage(applyMessage))];
            }
            [statusField release];
        });
    });
    worker.detach();
}

- (void)openGeneralizedInteractionPlot:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || !represented) return;
    const std::string term([represented UTF8String]);
    if (term.empty() ||
        std::find(state->terms.begin(), state->terms.end(), term) == state->terms.end()) {
        [_statusField setStringValue:@"Status: select an included model effect."];
        return;
    }
    const bool simpleEffect = !IsInteractionTerm(term);
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    const std::string scope = ScopeForCapturedAnalysisScope(
        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneGeneralizedMISpec(
        GeneralizedGLMTaskForState(*state, state->rFitGeneration));
    const std::string response = state->response;
    const std::vector<std::string> terms = state->terms;
    const bool multipleImputation = state->multipleImputation;
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = "generalized_single";
    link.sourceModelId = state->id;
    link.sourceModelRevision = state->modelVersion;
    link.sourceFitVersion = state->fitVersion;
    link.group = state->group;
    link.term = term;
    link.binaryEffect = state->binaryRegression;
    link.boundedCountEffect = state->countRegression &&
        rlispstat::core::CountDistributionUsesTrials(state->countDistribution);
    if (state->countDistribution == rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling)
        link.effectQuantity = "overall_expected_score";
    else if (state->countDistribution == rlispstat::core::CountDistribution::PerfectScore)
        link.effectQuantity = "predicted_probability";
    else if (link.boundedCountEffect) link.effectQuantity = "expected_count";
    link.title = "Effect: " + term;
    const std::string jobKey = link.sourceModelKind + "|" +
        link.sourceModelId + "|" + term + "|" +
        std::to_string(link.sourceModelRevision) + "|" +
        std::to_string(link.sourceFitVersion);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!g_pendingInteractionPlotJobs.insert(jobKey).second) {
            [_statusField setStringValue:ToNSString(
                "The effect plot for " + term +
                " is already being calculated in R…")];
            return;
        }
    }
    [_statusField setStringValue:ToNSString(
        "Calculating the effect plot in R for " + term + "…")];
    NSTextField *statusField = [_statusField retain];
    std::thread worker([dataframe, response, terms, scope, modelSpec, term,
                        link, multipleImputation, simpleEffect, statusField,
                        jobKey]() mutable {
        rlispstat::core::RegressionInteractionPlotResult result;
        std::string message;
        const std::string analysisId = "gglm_interaction_" + link.sourceModelId;
        const bool ok = RunRBackedInteractionPlot(
            dataframe, "gglm_interaction_plot", analysisId,
            response, terms, scope, modelSpec, term, &result, &message,
            std::string(), link);
        dispatch_async(dispatch_get_main_queue(), ^{
            bool current = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pendingInteractionPlotJobs.erase(jobKey);
                auto found = g_generalizedGLMs.find(link.sourceModelId);
                current = found != g_generalizedGLMs.end() &&
                    found->second.modelVersion == link.sourceModelRevision &&
                    found->second.fitVersion == link.sourceFitVersion;
            }
            std::string applyMessage = message;
            if (ok && !current) {
                applyMessage = "The model changed while the effect plot was being calculated; request it again.";
            }
            const std::string plotId = ok && current
                ? ApplyRBackedInteractionPlotResult(
                    dataframe, analysisId, response, term,
                    result, &applyMessage, link)
                : std::string();
            [statusField setStringValue:ToNSString(plotId.empty()
                ? GLMStatusMessage(applyMessage)
                : (multipleImputation
                    ? "Pooled effect plot opened across all imputations for " + term + "."
                    : (simpleEffect
                        ? "Effect plot opened from the R fit for " + term + "."
                        : "Interaction effect plot opened from the R fit for " + term + ".")))];
            [statusField release];
        });
    });
    worker.detach();
}

- (void)openGeneralizedPartialRegressionPlot:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || !represented) return;
    const std::string term([represented UTF8String]);
    if (term.empty() || IsInteractionTerm(term) ||
        std::find(state->terms.begin(), state->terms.end(), term) == state->terms.end()) {
        [_statusField setStringValue:@"Status: choose an included main-effect term."];
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    const std::string scope = ScopeForCapturedAnalysisScope(
        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneGeneralizedMISpec(
        GeneralizedGLMTaskForState(*state, state->rFitGeneration));
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = "generalized_single";
    link.sourceModelId = state->id;
    link.sourceModelRevision = state->modelVersion;
    link.sourceFitVersion = state->fitVersion;
    link.group = state->group;
