- (NSMenu *)addTermContextMenu
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addTerm)];
    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.addTermAction) action:@selector(addTermClicked:) keyEquivalent:@""];
    [add setTarget:self];
    [menu addItem:add];
    return menu;
}

- (NSMenu *)modelActionContextMenu
{
    GeneralizedGLMState *state = [self state];
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.model)];
    AddMissingInformationMenu(menu, state->id);
    if (!state) return menu;

    NSMenuItem *heading = [[NSMenuItem alloc] initWithTitle:
        (state->title.empty() ? @"Model" : ToNSString(state->title)) action:nil keyEquivalent:@""];
    [heading setEnabled:NO]; [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *responseRoot = [[NSMenuItem alloc] initWithTitle:@"Response" action:nil keyEquivalent:@""];
    NSMenu *responseMenu = [[NSMenu alloc] initWithTitle:@"Response"];
    for (NSMenuItem *available in [_responsePopup itemArray]) {
        NSString *title = [available title];
        [responseMenu addItem:[self modelChoiceItem:title kind:@"response"
            selected:[title isEqualToString:ToNSString(state->response)]]];
    }
    [responseRoot setSubmenu:responseMenu]; [menu addItem:responseRoot];

    const bool supportsOffset = state->family != "beta_one_inflated" &&
        (!state->countRegression ||
         (state->countDistribution != rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling &&
          state->countDistribution != rlispstat::core::CountDistribution::PerfectScore));
    if (supportsOffset) {
        NSMenuItem *offsetRoot = [[NSMenuItem alloc] initWithTitle:@"Link-scale offset (advanced)" action:nil keyEquivalent:@""];
        NSMenu *offsetMenu = [[NSMenu alloc] initWithTitle:@"Link-scale offset (advanced)"];
        NSMenuItem *none = [self modelMenuItem:@"None" action:@selector(setOffsetVariableFromMenu:) represented:@""];
        [none setState:state->offsetVariable.empty() ? NSControlStateValueOn : NSControlStateValueOff];
        [offsetMenu addItem:none];
        for (const std::string &name : rlispstat::core::NumericVariableNames(&state->seed)) {
            if (name == state->response || name == state->exposure) continue;
            NSMenuItem *item = [self modelMenuItem:ToNSString(name)
                action:@selector(setOffsetVariableFromMenu:) represented:ToNSString(name)];
            [item setState:name == state->offsetVariable ? NSControlStateValueOn : NSControlStateValueOff];
            [offsetMenu addItem:item];
        }
        [offsetRoot setSubmenu:offsetMenu]; [menu addItem:offsetRoot];
    }

    NSMenuItem *addRoot = [[NSMenuItem alloc] initWithTitle:@"Add independent variable" action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:@"Add independent variable"];
    for (const std::string &name : VariableNamesForModel(&state->seed)) {
        if (name == state->response ||
            std::find(state->terms.begin(), state->terms.end(), name) != state->terms.end()) continue;
        [addMenu addItem:[self modelMenuItem:ToNSString(name)
            action:@selector(addTermFromMenu:) represented:ToNSString(name)]];
    }
    AddModelTermMenuItems(addMenu, self, @selector(addTermFromMenu:),
                            &state->seed, state->response, state->terms, "", rlispstat::core::EffectiveModelSpecificationTermTypes(*state));
    if ([addMenu numberOfItems] == 0) {
        NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:@"No available variables" action:nil keyEquivalent:@""];
        [none setEnabled:NO]; [addMenu addItem:none];
    }
    [addRoot setSubmenu:addMenu]; [menu addItem:addRoot];

    NSMenuItem *removeRoot = [[NSMenuItem alloc] initWithTitle:@"Remove term" action:nil keyEquivalent:@""];
    NSMenu *removeMenu = [[NSMenu alloc] initWithTitle:@"Remove term"];
    for (const std::string &term : state->terms) {
        [removeMenu addItem:[self modelMenuItem:ToNSString(term)
            action:@selector(removeSelectedTerm:) represented:ToNSString(term)]];
    }
    [removeRoot setSubmenu:removeMenu]; [removeRoot setEnabled:!state->terms.empty()];
    [menu addItem:removeRoot];

    NSMenuItem *typesRoot = [[NSMenuItem alloc] initWithTitle:@"Predictor types" action:nil keyEquivalent:@""];
    NSMenu *typesMenu = [[NSMenu alloc] initWithTitle:@"Predictor types"];
    NSMenuItem *transformRoot = [[NSMenuItem alloc] initWithTitle:@"Transformations" action:nil keyEquivalent:@""];
    NSMenu *transformMenu = [[NSMenu alloc] initWithTitle:@"Transformations"];
    NSMenuItem *referencesRoot = [[NSMenuItem alloc] initWithTitle:@"Reference categories" action:nil keyEquivalent:@""];
    NSMenu *referencesMenu = [[NSMenu alloc] initWithTitle:@"Reference categories"];
    DataFrameModel dataframe;
    const bool hasDataframe = DataFrameSnapshotForGroup(state->group, dataframe);
    std::set<std::string> configuredVariables;
    for (const std::string &term : state->terms) {
        if (IsInteractionTerm(term)) continue;
        const std::string variable = rlispstat::core::BaseVariableForTermComponent(term);
        if (!configuredVariables.insert(variable).second) continue;
        const std::string type = rlispstat::core::ModelSpecificationTermType(
            *state, variable, rlispstat::core::DefaultTermType(&state->seed, variable));
        NSMenuItem *termTypesRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(variable) action:nil keyEquivalent:@""];
        NSMenu *termTypes = [[NSMenu alloc] initWithTitle:ToNSString(variable)];
        for (NSString *candidate in @[@"numeric", @"factor"]) {
            NSString *label = [candidate isEqualToString:@"factor"] ? @"Treat predictor as categorical" : @"Treat predictor as continuous";
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:label
                action:@selector(setModelTermTypeFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:@[ToNSString(variable), candidate]];
            [item setState:type == [candidate UTF8String] ? NSControlStateValueOn : NSControlStateValueOff];
            [termTypes addItem:item];
        }
        [termTypesRoot setSubmenu:termTypes]; [typesMenu addItem:termTypesRoot];

        if (type == "factor" && hasDataframe) {
            const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
                state->seed, &dataframe, variable);
            if (!metadata.levels.empty()) {
                NSMenuItem *termReferenceRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(variable) action:nil keyEquivalent:@""];
                NSMenu *termReferences = [[NSMenu alloc] initWithTitle:ToNSString(variable)];
                const auto found = state->factorReferenceLevels.find(variable);
                const std::string selected = found == state->factorReferenceLevels.end()
                    ? metadata.levels.front() : found->second;
                for (const std::string &level : metadata.levels) {
                    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(level)
                        action:@selector(setModelReferenceFromMenu:) keyEquivalent:@""];
                    [item setTarget:self];
                    [item setRepresentedObject:@[ToNSString(variable), ToNSString(level)]];
                    [item setState:level == selected ? NSControlStateValueOn : NSControlStateValueOff];
                    [termReferences addItem:item];
                }
                [termReferenceRoot setSubmenu:termReferences]; [referencesMenu addItem:termReferenceRoot];
            }
        } else if (type != "factor") {
            const bool centered = state->centeredPredictors.count(variable) != 0;
            [transformMenu addItem:[self modelMenuItem:
                (centered ? ToNSString("Remove centering: " + variable)
                          : ToNSString("Center: " + variable))
                action:@selector(toggleModelTermCenteringFromMenu:) represented:ToNSString(variable)]];
        }
    }
    [typesRoot setSubmenu:typesMenu]; [typesRoot setEnabled:[typesMenu numberOfItems] > 0];
    [transformRoot setSubmenu:transformMenu]; [transformRoot setEnabled:[transformMenu numberOfItems] > 0];
    [referencesRoot setSubmenu:referencesMenu]; [referencesRoot setEnabled:[referencesMenu numberOfItems] > 0];
    [menu addItem:typesRoot]; [menu addItem:transformRoot]; [menu addItem:referencesRoot];

    if (state->binaryRegression) {
        NSMenuItem *eventRoot = [[NSMenuItem alloc] initWithTitle:@"Modelled event" action:nil keyEquivalent:@""];
        NSMenu *eventMenu = [[NSMenu alloc] initWithTitle:@"Modelled event"];
        for (NSString *event in @[ToNSString(state->responseCoding.referenceLabel),
                                  ToNSString(state->responseCoding.eventLabel)]) {
            [eventMenu addItem:[self modelChoiceItem:event kind:@"event"
                selected:[event isEqualToString:ToNSString(state->responseCoding.eventLabel)]]];
        }
        [eventRoot setSubmenu:eventMenu]; [menu addItem:eventRoot];
    } else {
        NSMenuItem *familyRoot = [[NSMenuItem alloc] initWithTitle:@"Distribution" action:nil keyEquivalent:@""];
        NSMenu *familyMenu = [[NSMenu alloc] initWithTitle:@"Distribution"];
        for (NSMenuItem *available in [_familyPopup itemArray]) {
            NSString *family = [available title];
            NSString *distributionId = [[available representedObject] description];
            const std::string selectedDistribution = state->countRegression &&
                state->countDistribution == rlispstat::core::CountDistribution::QuasiPoisson
                    ? "poisson"
                    : (state->countRegression
                        ? rlispstat::core::CountDistributionId(state->countDistribution)
                        : state->family);
            [familyMenu addItem:[self modelChoiceItem:family kind:@"family"
                selected:[distributionId isEqualToString:ToNSString(selectedDistribution)]]];
        }
        [familyRoot setSubmenu:familyMenu]; [menu addItem:familyRoot];
    }

    NSMenuItem *linkRoot = [[NSMenuItem alloc] initWithTitle:@"Link" action:nil keyEquivalent:@""];
    NSMenu *linkMenu = [[NSMenu alloc] initWithTitle:@"Link"];
    for (NSMenuItem *available in [_linkPopup itemArray]) {
        NSString *linkTitle = [available title];
        BOOL selected = state->binaryRegression
            ? [linkTitle isEqualToString:ToNSString(rlispstat::core::BinaryLinkLabel(state->binaryLink))]
            : [linkTitle isEqualToString:ToNSString(state->link)];
        [linkMenu addItem:[self modelChoiceItem:linkTitle kind:@"link" selected:selected]];
    }
    [linkRoot setSubmenu:linkMenu]; [menu addItem:linkRoot];


    [menu addItem:[self modelMenuItem:ToNSString(titles.refitModel) action:@selector(refitModel:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *residualRoot = [[NSMenuItem alloc] initWithTitle:@"Diagnostic residuals" action:nil keyEquivalent:@""];
    NSMenu *residualMenu = [[NSMenu alloc] initWithTitle:@"Diagnostic residuals"];
    for (NSMenuItem *available in [_residualPopup itemArray]) {
        NSString *residualTitle = [available title];
        const std::string residual =
            [residualTitle isEqualToString:ToNSString(rlispstat::core::GLMDunnSmythResidualTitle())]
                ? "dunn_smyth"
                : [residualTitle isEqualToString:ToNSString(rlispstat::core::GLMRawResidualTitle())]
                    ? "raw"
                    : [residualTitle isEqualToString:ToNSString(rlispstat::core::GLMPearsonResidualTitle())]
                        ? "pearson"
                        : [residualTitle isEqualToString:ToNSString(rlispstat::core::GLMWorkingResidualTitle())]
                            ? "working" : "deviance";
        NSMenuItem *item = [self modelChoiceItem:residualTitle kind:@"residual"
            selected:residual == state->diagnosticOptions.residualType];
        [item setEnabled:rlispstat::core::IsGeneralizedResidualTypeAvailable(*state, residual)];
        [residualMenu addItem:item];
    }
    [residualRoot setSubmenu:residualMenu]; [menu addItem:residualRoot];
    [menu addItem:[self modelMenuItem:ToNSString(rlispstat::core::AutoRefitMenuTitle(state->autoRefit))
                                action:@selector(toggleAutoRefitFromMenu:) represented:nil]];
    [menu addItem:[self modelMenuItem:ToNSString(titles.compareModels)
                                action:@selector(openModelComparison:) represented:nil]];
    [menu addItem:ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), state->binaryRegression,
        state->countRegression &&
            rlispstat::core::CountDistributionSupportsScoreDistribution(
                state->countDistribution),
        state->countRegression)];
    if (state->binaryRegression) {
        [menu addItem:[self modelMenuItem:(_showModelDetails ? @"Hide model details" : @"Show model details")
                                    action:@selector(showModelDetails:) represented:nil]];
    }
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self modelMenuItem:ToNSString(titles.rowsUsedExcluded) action:@selector(showRowsUsedExcluded:) represented:nil]];
    [menu addItem:[self modelExportMenuItem]];
    return menu;
}

- (NSMenu *)contextMenuForCoefficientRow:(NSInteger)row column:(NSInteger)column
{
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    if (row < 0) return [self modelActionContextMenu];
    if ([self isAddTermRow:row]) return [self addTermContextMenu];
    if (column >= 0 && column < [self coefficientColumnCount]) {
        NSString *identifier = [self coefficientColumnIdentifier:column];
        if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
            return [self statisticContextMenuForTableRow:row column:column];
        }
    }
    if (row > 0) return [self predictorContextMenuForTableRow:row];
    return [self statisticContextMenuForTableRow:row column:column];
}

- (void)showStatisticMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    NSMenu *menu = [self statisticContextMenuForTableRow:row column:column];
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
        [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails],
        [self state] && [self state]->countRegression,
        [self state] && [self state]->binaryRegression,
        [self state] && ([self state]->family == "Gamma" ||
                         [self state]->family == "gamma_distance"));
    NSRect rowRect = NSMakeRect(0, layout.coefRowsY + row * layout.rowHeight, [_reportView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMidX(rowRect), NSMaxY(rowRect)) inView:_reportView];
}

- (void)coefficientCellClickedAtRow:(NSInteger)row column:(NSInteger)column
{
    if (row < 0) return;
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    GeneralizedGLMState *state = [self state];
    if (state && state->precomputed && !state->multipleImputation) {
        NSString *identifier = [self coefficientColumnIdentifier:column];
        if ([self isAddTermRow:row] ||
            [identifier isEqualToString:@"term"] ||
            [identifier isEqualToString:@"type"]) {
            [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
            return;
        }
    }
    if ([self isAddTermRow:row]) {
        GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
            [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails],
            state && state->countRegression, state && state->binaryRegression,
            state && (state->family == "Gamma" || state->family == "gamma_distance"));
        [self showAddTermMenuAtPoint:NSMakePoint(layout.margin + 10.0, layout.coefRowsY + row * layout.rowHeight + layout.rowHeight) inView:_reportView];
        return;
    }
    if (column < 0) return;
    NSString *identifier = [self coefficientColumnIdentifier:column];
    if ([identifier isEqualToString:@"term"] && row > 0) {
        [self replaceTermAtTableRow:row];
    } else if ([identifier isEqualToString:@"type"] && row > 0) {
        [self showTypeMenuForTableRow:row];
    } else if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
        [self showStatisticMenuForTableRow:row column:column];
    }
}

