- (void)setOffsetVariableFromMenu:(id)sender
{
    GeneralizedGLMState *state = [self state];
    NSString *selection = [sender representedObject];
    if (!state || ![selection isKindOfClass:[NSString class]]) return;
    const std::string value = [selection UTF8String];
    if (!value.empty()) {
        const auto numeric = rlispstat::core::NumericVariableNames(&state->seed);
        if (value == state->response || value == state->exposure ||
            std::find(numeric.begin(), numeric.end(), value) == numeric.end()) return;
    }
    if (state->offsetVariable == value) return;
    state->offsetVariable = value;
    [self markChangedAndRefresh];
}

- (void)offsetChanged:(id)sender
{
    (void)sender;
    if (_refreshing) return;
    GeneralizedGLMState *state = [self state];
    NSMenuItem *selected = [_offsetPopup selectedItem];
    if (!state || !selected) return;
    const std::string value = std::string([[[selected representedObject] description] UTF8String]);
    if (!value.empty()) {
        const auto numeric = rlispstat::core::NumericVariableNames(&state->seed);
        if (value == state->response || value == state->exposure ||
            std::find(numeric.begin(), numeric.end(), value) == numeric.end()) return;
    }
    if (state->offsetVariable == value) return;
    state->offsetVariable = value;
    [self markChangedAndRefresh];
}

