    state->response.clear();
    [self markChangedAndRefresh];
}

- (void)setResponseType:(const std::string &)type
{
    GeneralizedGLMState *state = [self state];
    if (!state || state->response.empty()) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        return;
    }
    std::string message;
    if (!SetVariableAnalysisType(state->group, state->response, type, &message)) {
        [_statusField setStringValue:ToNSString(message)];
    } else {
        [self refresh];
    }
}

