- (std::string)lastTerm
{
    GeneralizedGLMState *state = [self state];
    if (!state || state->terms.empty()) return "";
    std::string selected = [self sourceTermForCoefficientRow:_selectedCoefRow];
    if (!selected.empty()) return selected;
    return state->terms.back();
}

- (void)changeLastTermFromMenu:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || state->terms.empty()) {
        [self addTermClicked:nil];
        return;
    }
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        return;
    }
    NSInteger row = (_selectedCoefRow > 0 && ![self isAddTermRow:_selectedCoefRow]) ? _selectedCoefRow : [self coefficientRowCount] - 2;
    [self replaceTermAtTableRow:row];
}

- (void)replaceTermAtTableRow:(NSInteger)row
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        return;
    }
    std::string oldTerm = [self sourceTermForCoefficientRow:row];
    if (oldTerm.empty()) return;
    NSInteger termIndex = -1;
    for (size_t i = 0; i < state->terms.size(); ++i) {
        if (state->terms[i] == oldTerm) {
            termIndex = (NSInteger)i;
            break;
        }
    }
    if (termIndex < 0) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMChangeTermTitle())];
    for (const std::string &name : VariableNamesForModel(&state->seed)) {
        if (name == state->response) continue;
        bool duplicate = false;
        for (size_t i = 0; i < state->terms.size(); ++i) {
            if ((NSInteger)i != termIndex && state->terms[i] == name) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        const std::string displayType = rlispstat::core::ModelTermTypeDisplayName(
            rlispstat::core::DefaultTermType(&state->seed, name));
        std::string display = name + " (" + displayType + ")";
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(display) action:@selector(replaceTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ @(termIndex), ToNSString(name) ]];
        [menu addItem:item];
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(GLMNoAvailableReplacementStatus())];
        return;
    }
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
        [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails],
        state && state->countRegression, state && state->binaryRegression,
            state && (state->family == "Gamma" || state->family == "gamma_distance"));
    [menu popUpMenuPositioningItem:nil
                        atLocation:NSMakePoint(layout.margin + layout.coefX[0] + 10.0,
                                               layout.coefRowsY + row * layout.rowHeight + layout.rowHeight)
                            inView:_reportView];
}

- (void)replaceTermFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSInteger termIndex = [[payload objectAtIndex:0] integerValue];
    NSString *title = [payload objectAtIndex:1];
    if (!title) return;
    GeneralizedGLMState *state = [self state];
    if (!state || termIndex < 0 || (size_t)termIndex >= state->terms.size()) return;
    std::string oldTerm = state->terms[(size_t)termIndex];
    std::string name = std::string([title UTF8String]);
    if (name == state->response) return;
    const auto edit = rlispstat::core::ReplaceModelSpecificationTerm(
        *state, VariableNamesForModel(&state->seed), oldTerm, name);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (!edit.changed) return;
    [self markChangedAndRefresh];
}

- (void)changeSelectedModelRow:(id)sender
{
    (void)sender;
    NSInteger row = (_selectedCoefRow > 0 && ![self isAddTermRow:_selectedCoefRow]) ? _selectedCoefRow : [self coefficientRowCount] - 2;
    [self replaceTermAtTableRow:row];
}

- (void)showTypeMenuForTableRow:(NSInteger)row
{
    GeneralizedGLMState *state = [self state];
    std::string term = [self sourceTermForCoefficientRow:row];
    if (!state || term.empty()) return;
    std::string type = rlispstat::core::ModelSpecificationTermType(
        *state, term, rlispstat::core::DefaultTermType(&state->seed, term));
    if (rlispstat::core::ModelTermTypeIsInteraction(type)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::PredictorTypeMenuTitle())];
    AddModelTermTypeMenuItems(menu, self, @selector(typeMenuSelected:), type);
    GeneralizedGLMReportLayout layout = GeneralizedGLMReportLayout::Compute([self coefficientRowCount], [_reportView bounds].size.width,
        [self coefficientColumnCount], [self binaryTermTestCount], [self binaryWarningCount], [self showsModelDetails],
        state && state->countRegression, state && state->binaryRegression,
            state && (state->family == "Gamma" || state->family == "gamma_distance"));
    [menu popUpMenuPositioningItem:nil
                        atLocation:NSMakePoint(layout.margin + layout.coefX[1],
                                               layout.coefRowsY + row * layout.rowHeight + layout.rowHeight)
                            inView:_reportView];
}

