    [self showTypeMenuForTableRow:row];
}

- (void)setLastTermType:(const std::string &)type
{
    GeneralizedGLMState *state = [self state];
    std::string term = [self lastTerm];
    if (!state || term.empty()) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        return;
    }
    if (IsInteractionTerm(term)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(state->group);
        if (!current) {
            [_statusField setStringValue:@"Status: dataset is no longer available."];
            return;
        }
        dataframe = *current;
    }
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    const auto edit = rlispstat::core::SetModelSpecificationTermType(
        *state, term, type, metadata);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (edit.changed) [self markChangedAndRefresh];
    else [self refresh];
    [_statusField setStringValue:ToNSString(GLMTermTypeChangedStatus(term, type))];
}

