- (NSString *)binaryCSVForTable:(NSString *)table
{
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return @"";
    const bool termTests = table && [table isEqualToString:@"term_tests"];
    const bool modelFit = table && [table isEqualToString:@"model_fit"];
    return ToNSString(modelFit ? rlispstat::core::BinaryRegressionModelFitCSV(*state)
        : (termTests ? rlispstat::core::BinaryRegressionTermTestsCSV(*state)
                     : rlispstat::core::BinaryRegressionCoefficientCSV(*state)));
}

- (void)copyBinaryRSyntax:(id)sender
{
    (void)sender;
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    auto rString = [](const std::string &value) {
        std::string out = "\"";
        for (char ch : value) { if (ch == '\\' || ch == '"') out.push_back('\\'); out.push_back(ch); }
        return out + "\"";
    };
    std::string terms = "character()";
    if (!state->terms.empty()) {
        terms = "c(";
        for (std::size_t i = 0; i < state->terms.size(); ++i) { if (i) terms += ", "; terms += rString(state->terms[i]); }
        terms += ")";
    }
    std::string syntax = "LinkEDA::ls_new_binary_regression(data = " + rString(state->group) +
        ", response = " + rString(state->response) + ", terms = " + terms + ", link = " + rString(state->link) +
        ", event = " + rString(state->responseCoding.eventValue) + ", reference = " + rString(state->responseCoding.referenceValue) + ")";
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents]; [pasteboard setString:ToNSString(syntax) forType:NSPasteboardTypeString];
    [_statusField setStringValue:@"Status: R syntax copied."];
}

- (void)exportBinaryCSV:(id)sender
{
    GeneralizedGLMState *state = [self state];
    if (!state || !state->binaryRegression) return;
    NSString *table = [sender representedObject] ?: @"coefficients";
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, @"csv");
    [panel setNameFieldStringValue:ToNSString(state->id + "_" + std::string([table UTF8String]) + ".csv")];
    if ([panel runModal] != NSModalResponseOK) return;
    NSError *error = nil;
    if (![[self binaryCSVForTable:table] writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:&error]) {
        ShowWorkbenchMessageOnMain(@"Export table", error ? [error localizedDescription] : @"The CSV file could not be written.");
    }
}

- (void)copyModelTable:(id)sender
{
