- (void)showAddTermMenuAtPoint:(NSPoint)point inView:(NSView *)view
{
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMAddTermTitle())];
	    for (const std::string &name : VariableNamesForModel(&state->seed)) {
	        if (name == state->response) continue;
	        if (std::find(state->terms.begin(), state->terms.end(), name) != state->terms.end()) continue;
	        const std::string type = rlispstat::core::ModelSpecificationTermType(
	            *state, name, rlispstat::core::DefaultTermType(&state->seed, name));
	        std::string display = name + " (" + rlispstat::core::ModelTermTypeDisplayName(type) + ")";
	        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(display) action:@selector(addTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    if (!AddModelTermMenuItems(menu, self, @selector(addTermFromMenu:), &state->seed, state->response, state->terms, "", rlispstat::core::EffectiveModelSpecificationTermTypes(*state))) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelNoAvailablePredictorsLabel()) action:nil keyEquivalent:@""];
        [item setEnabled:NO];
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)showSearchableAddTermSelectorInView:(NSView *)view
{
    GeneralizedGLMState *state = [self state];
    if (!state || (state->precomputed && !state->multipleImputation)) return;
    const auto choices = SearchableModelTermChoices(&state->seed, state->response,
        state->terms, rlispstat::core::EffectiveModelSpecificationTermTypes(*state));
    ShowSearchableAddSelector(_window, view, @"Add terms", choices,
        ^(NSArray<NSString *> *names) {
            GeneralizedGLMState *current = [self state];
            if (!current) return;
            bool changed = false;
            const auto available = VariableNamesForModel(&current->seed);
            for (NSString *label in names) {
                const auto edit = rlispstat::core::AddModelSpecificationTerm(
                    *current, available, std::string(label.UTF8String));
                changed = changed || edit.changed;
                if (!edit.ok && !edit.message.empty())
                    [_statusField setStringValue:ToNSString(edit.message)];
            }
            if (changed) [self markChangedAndRefresh];
        }, ^NSMenu *(NSString *label) {
            GeneralizedGLMState *current = [self state];
            if (!current) return (NSMenu *)nil;
            return SearchableModelTermContextMenu(label, self,
                @selector(addTermFromMenu:), &current->seed, current->response,
                current->terms,
                rlispstat::core::EffectiveModelSpecificationTermTypes(*current));
        });
}

- (void)addTermFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    GeneralizedGLMState *state = [self state];
    if (!state) return;
    std::string name = std::string([title UTF8String]);
    if (name == state->response) return;
    const auto edit = rlispstat::core::AddModelSpecificationTerm(
        *state, VariableNamesForModel(&state->seed), name);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (edit.changed) [self markChangedAndRefresh];
}

- (void)removeLastTerm:(id)sender
{
    [self removeSelectedTerm:sender];
}

- (void)removeSelectedTerm:(id)sender
{
    GeneralizedGLMState *state = [self state];
    if (!state || state->terms.empty()) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
        return;
    }
    std::string term;
    if (sender && [sender respondsToSelector:@selector(representedObject)]) {
        id represented = [sender representedObject];
        if ([represented isKindOfClass:[NSString class]] && [(NSString *)represented length] > 0) {
            term = [(NSString *)represented UTF8String];
        }
    }
    if (term.empty()) term = [self lastTerm];
    if (term.empty()) return;
    const auto edit = rlispstat::core::RemoveModelSpecificationTerm(*state, term);
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (!edit.changed) return;
    _selectedCoefRow = -1;
    _selectedCoefColumn = -1;
    [self markChangedAndRefresh];
}

- (void)openModelComparison:(id)sender
{
    (void)sender;
    GeneralizedGLMState *source = [self state];
    if (!source) return;

    const std::string prefix = source->binaryRegression ? "binarycmp_" : "gglmcmp_";
    const std::string comparisonId = prefix + source->group + "_" +
        std::to_string((long long)time(nullptr)) + "_" +
        std::to_string((long long)g_generalizedComparisons.size() + 1);
    GeneralizedComparisonState comparison =
        rlispstat::core::CreateGeneralizedComparisonFromSingleModel(
            comparisonId, *source, "Model 1");
    const bool needsFit = comparison.models.empty() ||
        rlispstat::core::GeneralizedComparisonResolvedFitState(
            comparison, comparison.models.front()) !=
            rlispstat::core::RegressionComparisonFitState::Valid;
    g_generalizedComparisons[comparisonId] = std::move(comparison);
    GeneralizedComparisonState &stored = g_generalizedComparisons[comparisonId];
    if (needsFit) RequestGeneralizedComparisonFitInMainR(stored);
    ShowGeneralizedComparisonOnMain(comparisonId);
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    [_applyingResultsTimer invalidate];
    _applyingResultsTimer = nil;
    _applyingResultsStartedAt = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto state = g_generalizedGLMs.find(_modelId);
        if (state != g_generalizedGLMs.end() && state->second.rFitPending) {
            state->second.rFitPending = false;
            state->second.status = "Fit cancelled because the model window was closed.";
        }
    }
    [_lastTaskTiming release];
    _lastTaskTiming = nil;
    g_generalizedGLMControllers.erase(_modelId);
}

@end

