struct GLMReportLayout {
    CGFloat width = 1006.0;
    CGFloat marginX = 14.0;
    CGFloat topPadding = 12.0;
    CGFloat bottomPadding = 12.0;
    CGFloat titleY = 12.0;
    CGFloat controlsY = 44.0;
    CGFloat modelFitY = 76.0;
    CGFloat modelFitRuleY = 104.0;
    CGFloat anovaHeaderY = 112.0;
    CGFloat anovaRow1Y = 132.0;
    CGFloat anovaRow2Y = 150.0;
    CGFloat termsTitleY = 184.0;
    CGFloat coefHeaderY = 204.0;
    CGFloat coefRuleY = 226.0;
    CGFloat coefRowsY = 230.0;
    CGFloat statusY = 252.0;
    CGFloat totalHeight = 292.0;
    CGFloat rowHeight = 22.0;
    // Interaction coefficients carry both the contrasted level and its
    // reference combination (for example, "Treatment × Greece (vs Control
    // × Finland)").  The former 104-point stub silently reduced those
    // labels to "Treatment ×".  Give the semantic label its own usable
    // column and move every numeric column as one block.
    CGFloat coefX[9] = { 2.0, 326.0, 394.0, 468.0, 527.0, 601.0, 660.0, 724.0, 808.0 };
    CGFloat coefW[9] = { 320.0, 64.0, 70.0, 55.0, 70.0, 55.0, 60.0, 80.0, 80.0 };

    NSInteger coefficientColumnAtX(CGFloat x) const
    {
        for (NSInteger col = 0; col < 9; ++col) {
            if (x >= coefX[col] && x <= coefX[col] + coefW[col]) {
                return col;
            }
        }
        return -1;
    }

    NSRect coefficientCellRect(NSInteger row, NSInteger col) const
    {
        return NSMakeRect(coefX[col], row * rowHeight, coefW[col], rowHeight);
    }

    CGFloat bottomY(CGFloat topY, CGFloat height) const
    {
        return totalHeight - topY - height;
    }

    NSRect frameFromTop(CGFloat x, CGFloat topY, CGFloat w, CGFloat h) const
    {
        return NSMakeRect(x, bottomY(topY, h), w, h);
    }

    static GLMReportLayout Compute(NSInteger coefficientRows, CGFloat availableWidth,
                                   CGFloat availableHeight = 0.0)
    {
        GLMReportLayout layout;
        layout.width = std::max((CGFloat)1006.0, availableWidth);
        CGFloat extra = layout.width - 1006.0;
        if (extra > 0.0) {
            layout.coefX[2] += extra * 0.10;
            layout.coefX[3] += extra * 0.18;
            layout.coefX[4] += extra * 0.26;
            layout.coefX[5] += extra * 0.34;
            layout.coefX[6] += extra * 0.42;
            layout.coefX[7] += extra * 0.50;
            layout.coefX[8] += extra * 0.58;
        }
        CGFloat y = layout.topPadding;
        layout.titleY = y;
        y += 24.0;
        y += 8.0;
        layout.controlsY = y;
        y += 28.0;
        y += 20.0;
        y += 6.0;
        layout.modelFitY = y;
        y += 42.0;
        layout.modelFitRuleY = y;
        y += 1.0;
        y += 12.0;
        layout.anovaHeaderY = y;
        y += 20.0;
        layout.anovaRow1Y = y;
        y += 18.0;
        layout.anovaRow2Y = y;
        y += 20.0;
        y += 12.0;
        layout.termsTitleY = y;
        y += 20.0;
        layout.coefHeaderY = y;
        y += 20.0;
        layout.coefRuleY = y;
        y += 4.0;
        layout.coefRowsY = y;
        const CGFloat desiredRows = std::max((CGFloat)1.0,
                                             (CGFloat)coefficientRows);
        if (availableHeight > 0.0) {
            // Fit every semantic coefficient row whenever the monitor has
            // room.  If the report is taller than the work area, keep the
            // status line visible and give all remaining space to the table's
            // scroll view.  The previous hard ten-row limit silently clipped
            // later factor levels after terms were added.
            layout.totalHeight = availableHeight;
            layout.statusY = std::max(layout.coefRowsY + layout.rowHeight + 12.0,
                                      availableHeight - layout.bottomPadding - 18.0);
        } else {
            y += desiredRows * layout.rowHeight;
            y += 12.0;
            layout.statusY = y;
            y += 18.0;
            y += layout.bottomPadding;
            layout.totalHeight = y;
        }
        return layout;
    }
};

@interface GLMCoefficientsView : NSView
@property(nonatomic, assign) GLMWindowController *glmController;
@property(nonatomic) NSInteger selectedRow;
@property(nonatomic) NSInteger selectedColumn;
@end

@implementation GLMCoefficientsView
- (NSString *)snapshotTabDelimitedText
{
    return _glmController ? [_glmController snapshotTableText] : @"";
}
- (instancetype)initWithFrame:(NSRect)frame
{
    self = [super initWithFrame:frame];
    if (self) {
        _selectedRow = -1;
        _selectedColumn = -1;
        [self setWantsLayer:YES];
    }
    return self;
}

- (BOOL)isFlipped
{
    return YES;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);

    GLMReportLayout layout = GLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width);
    NSDictionary *leftAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]
    };
    NSMutableParagraphStyle *rightStyle = [[NSMutableParagraphStyle alloc] init];
    [rightStyle setAlignment:NSTextAlignmentRight];
    NSDictionary *rightAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0],
        NSParagraphStyleAttributeName: rightStyle
    };

    NSInteger rows = [_glmController coefficientRowCount];
    for (NSInteger row = 0; row < rows; ++row) {
        if (row == _selectedRow) {
            [[NSColor colorWithCalibratedWhite:0.93 alpha:1.0] setFill];
            NSRectFill(NSMakeRect(0, row * layout.rowHeight, [self bounds].size.width, layout.rowHeight));
        }
        for (NSInteger col = 0; col < 9; ++col) {
            NSString *value = [_glmController coefficientValueForRow:row column:col];
            if (!value || [value length] == 0) continue;
            NSRect cell = NSInsetRect(layout.coefficientCellRect(row, col), 2.0, 3.0);
            [value drawInRect:cell withAttributes:(col <= 1 ? leftAttrs : rightAttrs)];
        }
    }
}

- (NSInteger)rowAtPoint:(NSPoint)point
{
    GLMReportLayout layout = GLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width);
    NSInteger row = (NSInteger)floor(point.y / layout.rowHeight);
    return (row >= 0 && row < [_glmController coefficientRowCount]) ? row : -1;
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    GLMReportLayout layout = GLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width);
    NSInteger row = [self rowAtPoint:point];
    NSInteger column = layout.coefficientColumnAtX(point.x);
    _selectedRow = row;
    _selectedColumn = column;
    [self setNeedsDisplay:YES];
    return SnapshotAlbumMenu([_glmController contextMenuForCoefficientRow:row column:column],
                             @"General Linear Model");
}

- (void)mouseDown:(NSEvent *)event
{
    if (PopContextMenuForMouseDownIfNeeded(self, event)) return;
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    GLMReportLayout layout = GLMReportLayout::Compute([_glmController coefficientRowCount], [self bounds].size.width);
    NSInteger row = [self rowAtPoint:point];
    NSInteger column = layout.coefficientColumnAtX(point.x);
    _selectedRow = row;
    _selectedColumn = column;
    [self setNeedsDisplay:YES];
    [_glmController coefficientCellClickedAtRow:row column:column];
}

- (void)rightMouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:event.locationInWindow fromView:nil];
    if ([self rowAtPoint:point] == [_glmController coefficientRowCount] - 1) {
        [_glmController showSearchableAddTermSelectorInView:self];
        return;
    }
    PopContextMenuForMouseDownIfNeeded(self, event);
}
@end

