    NSString *visualTable = ToNSString(rlispstat::core::CsvReportToTabDelimited(
        rlispstat::core::ModelTrellisAllResultsCSV(s)));
    AddStandardTableVisualExportItems(ex, _contentView, @"Linear Model Trellis",
        @"linear-model-trellis", visualTable, nullptr, nullptr, false, false);
    AddRCodeExportItems(ex, "output", _modelTrellisId, true);
    [ex addItem:[NSMenuItem separatorItem]];
    NSArray*copyTitles=@[@"Copy panel table",@"Copy all panel tables"];
    for(NSInteger i=0;i<2;i++){NSMenuItem*x=[[NSMenuItem alloc]initWithTitle:copyTitles[i] action:@selector(copyCSV:) keyEquivalent:@""];[x setTarget:self];[x setTag:i?1:2];[ex addItem:x];}
    for(NSInteger i=0;i<2;i++){NSMenuItem*x=[[NSMenuItem alloc]initWithTitle:i?@"CSV \u2014 All panel results\u2026":@"CSV \u2014 Selected result\u2026" action:@selector(exportCSV:) keyEquivalent:@""];[x setTarget:self];[x setTag:i];[ex addItem:x];}
    for(NSInteger i=0;i<2;i++){NSMenuItem*x=[[NSMenuItem alloc]initWithTitle:i?@"PDF \u2014 APA 7 style\u2026":@"PDF \u2014 As displayed\u2026" action:@selector(exportPDF:) keyEquivalent:@""];[x setTarget:self];[x setTag:i];[ex addItem:x];}
    OrganizeExportMenu(ex);
    [m addItem:[self root:@"Export" submenu:ex]];AddSnapshotAlbumContextItems(m);return m;
}
@end

static NSTextField *GLMLabel(NSString *text, NSRect frame, CGFloat size, NSFontWeight weight)
{
    NSTextField *field = [[NSTextField alloc] initWithFrame:frame];
    [field setStringValue:text];
    [field setEditable:NO];
    [field setSelectable:NO];
    [field setBordered:NO];
    [field setDrawsBackground:NO];
    [field setFont:[NSFont systemFontOfSize:size weight:weight]];
    [field setTextColor:[NSColor colorWithCalibratedWhite:0.18 alpha:1.0]];
    return field;
}

static NSTextField *GLMRightLabel(NSString *text, NSRect frame, CGFloat size, NSFontWeight weight)
{
    NSTextField *field = GLMLabel(text, frame, size, weight);
    [field setAlignment:NSTextAlignmentRight];
    return field;
}

