static NSString *Table1DisplayLabel(const Table1DisplayRow &row)
{
    return ToNSString(rlispstat::core::Table1DisplayLabelText(row));
}

static NSMutableDictionary *Table1Attributes(CGFloat size, NSFontWeight weight, NSTextAlignment alignment, NSColor *color)
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:alignment];
    return [@{
        NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
        NSForegroundColorAttributeName: color,
        NSParagraphStyleAttributeName: style
    } mutableCopy];
}

static NSDictionary *Table1NoteAttributes(bool warning = false)
{
    auto attrs = Table1Attributes(11, warning ? NSFontWeightMedium : NSFontWeightRegular,
        NSTextAlignmentLeft, warning ? [NSColor colorWithCalibratedRed:0.55 green:0.18 blue:0.14 alpha:1.0]
                                    : [NSColor colorWithCalibratedWhite:0.38 alpha:1.0]);
    [(NSMutableParagraphStyle *)attrs[NSParagraphStyleAttributeName] setLineBreakMode:NSLineBreakByWordWrapping];
    return attrs;
}

static CGFloat Table1NoteHeight(NSString *text, CGFloat width, NSDictionary *attributes)
{
    return std::max<CGFloat>(16.0, std::ceil([text boundingRectWithSize:NSMakeSize(std::max<CGFloat>(1.0,width), CGFLOAT_MAX)
        options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
        attributes:attributes].size.height) + 2.0);
}

@implementation Table1ReportView

- (NSString *)snapshotTabDelimitedText
{
    return _controller ? ToNSString([_controller tableText]) : @"";
}

- (instancetype)initWithController:(Table1WindowController *)controller
{
    self = [super initWithFrame:NSMakeRect(0, 0, 720, 420)];
    if (!self) return nil;
    _controller = controller;
    [self setWantsLayer:YES];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_table1Views.push_back({self, ([controller state])->missingnessSource.empty()?([controller state])->datasetId:([controller state])->missingnessSource});
    }
    return self;
}

- (void)dealloc
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = std::find_if(g_table1Views.begin(), g_table1Views.end(),
            [self](const Table1ViewEntry &e) { return e.view == self; });
        if (it != g_table1Views.end()) g_table1Views.erase(it);
    }
    [super dealloc];
}

- (BOOL)isFlipped
{
    return YES;
}

- (CGFloat)preferredHeight
{
    return [self preferredHeightForWidth:NSWidth(self.bounds)];
}

- (CGFloat)preferredHeightForWidth:(CGFloat)width
{
    Table1DisplayState *state = [_controller state];
    const auto layout = rlispstat::core::BuildTable1ReportLayout(*state,width);
    CGFloat height = (CGFloat)rlispstat::core::Table1PreferredHeight(*state)
        - 18.0 * (state->footnotes.size() + state->warnings.size());
    for (const auto& note : state->footnotes)
        height += Table1NoteHeight(ToNSString(note),width-2*layout.margin,Table1NoteAttributes()) + 2.0;
    for (const auto& warning : state->warnings)
        height += Table1NoteHeight(ToNSString("Warning: "+warning),width-2*layout.margin,Table1NoteAttributes(true)) + 2.0;
    return height + (_includeExportHeading ? 48.0 : 0.0);
}

- (void)setExportHeadingWithNumber:(NSString *)number title:(NSString *)title
{
    _includeExportHeading = YES;
    _exportTableNumber = number;
    _exportTitle = title;
}

- (void)clearExportHeading
{
    _includeExportHeading = NO;
    _exportTableNumber = nil;
    _exportTitle = nil;
}

- (NSInteger)rowAtPoint:(NSPoint)point
{
    Table1DisplayState *state = [_controller state];
    rlispstat::core::Table1ReportLayout layout =
        rlispstat::core::BuildTable1ReportLayout(*state, [self bounds].size.width);
    return (NSInteger)rlispstat::core::Table1ReportRowAtPoint(
        *state,
        layout,
        rlispstat::platform::macos::ToCorePoint(point));
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);

    Table1DisplayState *state = [_controller state];
    CGFloat width = [self bounds].size.width;
    rlispstat::core::Table1ReportLayout reportLayout =
        rlispstat::core::BuildTable1ReportLayout(*state, width);
    BOOL hasGroup = reportLayout.hasGroup;
    BOOL allNumericColumns = state->tableType == "compare_means" || state->tableType == "nested_contingency" ||
        state->tableType == "mi_missing_information";
    BOOL hasSpanningHeader = reportLayout.hasSpanningHeader;
    CGFloat margin = (CGFloat)reportLayout.margin;
    CGFloat varW = (CGFloat)reportLayout.variableWidth;
    CGFloat pW = (CGFloat)reportLayout.pWidth;
    CGFloat testW = (CGFloat)reportLayout.testWidth;
    CGFloat rowH = (CGFloat)reportLayout.rowHeight;

    NSDictionary *headerAttrs = Table1Attributes(12, NSFontWeightSemibold, NSTextAlignmentRight, [NSColor colorWithCalibratedWhite:0.18 alpha:1.0]);
    NSDictionary *headerLeftAttrs = Table1Attributes(12, NSFontWeightSemibold, NSTextAlignmentLeft, [NSColor colorWithCalibratedWhite:0.18 alpha:1.0]);
    NSDictionary *leftAttrs = Table1Attributes(12, NSFontWeightRegular, NSTextAlignmentLeft, [NSColor colorWithCalibratedWhite:0.16 alpha:1.0]);
    NSDictionary *parentAttrs = Table1Attributes(12, NSFontWeightSemibold, NSTextAlignmentLeft, [NSColor colorWithCalibratedWhite:0.13 alpha:1.0]);
    NSDictionary *subVariableAttrs = Table1Attributes(11, NSFontWeightRegular, NSTextAlignmentLeft, [NSColor colorWithCalibratedWhite:0.40 alpha:1.0]);
    NSDictionary *mutedAttrs = Table1Attributes(11, NSFontWeightRegular, NSTextAlignmentLeft, [NSColor colorWithCalibratedWhite:0.38 alpha:1.0]);
    NSDictionary *rightAttrs = Table1Attributes(12, NSFontWeightRegular, NSTextAlignmentRight, [NSColor colorWithCalibratedWhite:0.16 alpha:1.0]);
    NSDictionary *rightSemiboldAttrs = Table1Attributes(12, NSFontWeightSemibold, NSTextAlignmentRight, [NSColor colorWithCalibratedWhite:0.13 alpha:1.0]);
    NSDictionary *mutedRightAttrs = Table1Attributes(11, NSFontWeightRegular, NSTextAlignmentRight, [NSColor colorWithCalibratedWhite:0.38 alpha:1.0]);

    BOOL hasStubs = reportLayout.hasStubs;
    int numStubs = reportLayout.stubColumnCount;
    CGFloat stubW = (CGFloat)reportLayout.stubWidth;
    CGFloat stubArea = (CGFloat)reportLayout.stubArea;
    int valueCols = reportLayout.valueColumnCount;
    auto columnWidth = [&](size_t column) -> CGFloat {
        return column < reportLayout.valueColumnWidths.size()
            ? (CGFloat)reportLayout.valueColumnWidths[column]
            : (CGFloat)reportLayout.columnWidth;
    };
    auto columnX = [&](size_t column) -> CGFloat {
        CGFloat result = margin + stubArea;
        for (size_t index = 0; index < column; ++index) result += columnWidth(index);
        return result;
    };

    CGFloat y = 14.0;
    if (_includeExportHeading) {
        NSDictionary *numberAttrs = Table1Attributes(12, NSFontWeightSemibold, NSTextAlignmentLeft,
                                                       [NSColor colorWithCalibratedWhite:0.10 alpha:1.0]);
        NSDictionary *titleAttrs = Table1Attributes(13, NSFontWeightRegular, NSTextAlignmentLeft,
                                                      [NSColor colorWithCalibratedWhite:0.10 alpha:1.0]);
        if ([_exportTableNumber length] > 0) {
            [[@"Table " stringByAppendingString:_exportTableNumber] drawInRect:NSMakeRect(margin, y, width - 2.0 * margin, 18)
                                                                  withAttributes:numberAttrs];
            y += 20.0;
        }
        [(_exportTitle ?: ToNSString(state->title)) drawInRect:NSMakeRect(margin, y, width - 2.0 * margin, 20)
                                                withAttributes:titleAttrs];
        y += 28.0;
    }
    NSString *subtitle = ToNSString(Table1Subtitle(*state, true));
    [subtitle drawInRect:NSMakeRect(margin, y, width - 2.0 * margin, 18) withAttributes:mutedAttrs];
    y += 24.0;

    if (hasSpanningHeader) {
        CGFloat spanWidth = 0.0;
        for (int index = 0; index < state->groupSpanningColumnCount; ++index)
            spanWidth += columnWidth((size_t)index);
        NSDictionary *spanAttrs = Table1Attributes(11, NSFontWeightSemibold, NSTextAlignmentCenter, [NSColor colorWithCalibratedWhite:0.22 alpha:1.0]);
        [ToNSString(state->groupSpanningHeader) drawInRect:NSMakeRect(margin + stubArea, y, spanWidth, 16) withAttributes:spanAttrs];
        if (state->groupSpanningColumnCount < (int)state->columns.size()) {
            CGFloat totalX = columnX((size_t)state->groupSpanningColumnCount);
            CGFloat totalW = 0.0;
            for (size_t index = (size_t)state->groupSpanningColumnCount; index < state->columns.size(); ++index)
                totalW += columnWidth(index);
            NSDictionary *totalSpanAttrs = Table1Attributes(11, NSFontWeightSemibold, NSTextAlignmentRight, [NSColor colorWithCalibratedWhite:0.22 alpha:1.0]);
            [ToNSString(state->columns.back()) drawInRect:NSMakeRect(totalX, y, totalW - 8.0, 16) withAttributes:totalSpanAttrs];
        }
        y += 14.0;
    }

    if (hasStubs) {
        CGFloat sx = margin;
        for (int s = 0; s < numStubs; ++s) {
            [ToNSString(state->stubHeaders[s]) drawInRect:NSMakeRect(sx, y, stubW - 4.0, 18) withAttributes:headerLeftAttrs];
            sx += stubW;
        }
    } else {
        [ToNSString(rlispstat::core::Table1ReportVariableHeader()) drawInRect:NSMakeRect(margin, y, varW, 18) withAttributes:headerLeftAttrs];
    }
    for (size_t c = 0; c < state->columns.size(); ++c) {
        NSDictionary *colHeaderAttrs = (allNumericColumns || hasGroup ||
            (c > 0 && state->tableType != "mi_diagnostics")) ? headerAttrs : headerLeftAttrs;
        if(!state->missingnessSource.empty())colHeaderAttrs=Table1Attributes(12, NSFontWeightSemibold, NSTextAlignmentCenter, [NSColor labelColor]);
        else if(state->tableType=="missing_data_test")colHeaderAttrs=state->columns[c]=="Status"?headerLeftAttrs:headerAttrs;
        if(state->tableType=="missing_data_overview" && state->missingnessSource.empty())colHeaderAttrs=state->columns[c]=="Missing variables"?headerLeftAttrs:headerAttrs;
        [ToNSString(state->columns[c]) drawInRect:NSMakeRect(columnX(c), y, columnWidth(c) - 8.0, 18) withAttributes:colHeaderAttrs];
    }
    CGFloat x = columnX((size_t)valueCols);
    if (state->showP) {
        [ToNSString(rlispstat::core::Table1ReportPHeader()) drawInRect:NSMakeRect(x, y, pW - 8.0, 18) withAttributes:headerAttrs];
        x += pW;
    }
    if (state->showTest) {
        [ToNSString(rlispstat::core::Table1ReportTestHeader()) drawInRect:NSMakeRect(x, y, testW - 8.0, 18) withAttributes:headerLeftAttrs];
    }
    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *rule = [NSBezierPath bezierPath];
    [rule moveToPoint:NSMakePoint(margin, y + 22.0)];
    [rule lineToPoint:NSMakePoint(width - margin, y + 22.0)];
    [rule stroke];
    y += 28.0;

    NSInteger selected = [_controller selectedRow];
    std::set<int> selection;
    bool isContingency = state->tableType == "nested_contingency";
    if (isContingency && !state->datasetId.empty()) {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sit = g_groupSelections.find(state->datasetId);
        if (sit != g_groupSelections.end()) selection = sit->second;
    }
    for (size_t r = 0; r < state->rows.size(); ++r) {
        const Table1DisplayRow &row = state->rows[r];

        BOOL isNestedLeaf = row.rowType == "nested_leaf_level" || row.rowType == "nested_total";
        BOOL isDataRow = rlispstat::core::Table1RowHasValues(row);

        if (row.rowType == "nested_total") {
            [[NSColor colorWithCalibratedWhite:0.72 alpha:1.0] setStroke];
            NSBezierPath *totalRule = [NSBezierPath bezierPath];
            [totalRule moveToPoint:NSMakePoint(margin, y - 5.0)];
            [totalRule lineToPoint:NSMakePoint(width - margin, y - 5.0)];
            [totalRule stroke];
        }

        // Detect change in first stub column for group separator
        if (hasStubs && r > 0 && !row.stubValues.empty() && !row.stubValues[0].empty()) {
            BOOL firstStubChanged = true;
            if (r > 0 && r - 1 < state->rows.size()) {
                const Table1DisplayRow &prevRow = state->rows[r - 1];
                firstStubChanged = prevRow.stubValues.empty() ||
                    prevRow.stubValues[0] != row.stubValues[0];
            }
            if (firstStubChanged) {
                [[NSColor colorWithCalibratedWhite:0.92 alpha:1.0] setStroke];
                NSBezierPath *sep = [NSBezierPath bezierPath];
                [sep moveToPoint:NSMakePoint(margin, y - 4.0)];
                [sep lineToPoint:NSMakePoint(width - margin, y - 4.0)];
                [sep stroke];
            }
        } else if (!hasStubs && rlispstat::core::Table1RowIsParent(row) && r > 0) {
            [[NSColor colorWithCalibratedWhite:0.94 alpha:1.0] setStroke];
            NSBezierPath *sep = [NSBezierPath bezierPath];
            [sep moveToPoint:NSMakePoint(margin, y - 4.0)];
            [sep lineToPoint:NSMakePoint(width - margin, y - 4.0)];
            [sep stroke];
        }

        bool hasSplitColumns = isContingency && state->groupSpanningColumnCount > 0;
        bool allRowRowsSelected = false;
        if (isContingency && !hasSplitColumns && isNestedLeaf && !selection.empty()) {
            allRowRowsSelected = rlispstat::core::ContingencyRowCoverage(*state, r, selection) ==
                rlispstat::core::AggregateCoverage::Full;
        }
        if (allRowRowsSelected) {
            [[NSColor colorWithCalibratedRed:0.85 green:0.91 blue:0.96 alpha:1.0] setFill];
            NSRectFill(NSMakeRect(margin - 4.0, y - 2.0, width - 2.0 * margin + 8.0, rowH));
        } else if ((NSInteger)r == selected) {
            NSColor *selectionFill = state->tableType == "compare_means"
                ? [NSColor colorWithCalibratedWhite:0.91 alpha:1.0]
                : [NSColor colorWithCalibratedRed:0.92 green:0.95 blue:0.98 alpha:1.0];
            [selectionFill setFill];
            NSRectFill(NSMakeRect(margin - 4.0, y - 2.0, width - 2.0 * margin + 8.0, rowH));
        }

        if (hasStubs) {
            CGFloat sx = margin;
            for (size_t s = 0; s < row.stubValues.size() && s < (size_t)numStubs; ++s) {
                NSDictionary *stubAttrs = (s == 0) ? parentAttrs : leftAttrs;
                [ToNSString(row.stubValues[s]) drawInRect:NSMakeRect(sx, y, stubW - 4.0, 18) withAttributes:stubAttrs];
                sx += stubW;
            }
        } else {
            BOOL indented = rlispstat::core::Table1RowIsIndented(row);
            NSDictionary *labelAttrs;
            if (rlispstat::core::Table1RowIsSubVariable(row)) {
                labelAttrs = subVariableAttrs;
            } else if (rlispstat::core::Table1RowIsParent(row)) {
                labelAttrs = parentAttrs;
            } else {
                labelAttrs = indented ? leftAttrs : parentAttrs;
            }
            CGFloat labelX = margin + (indented ? 18.0 : 0.0);
            [Table1DisplayLabel(row) drawInRect:NSMakeRect(labelX, y, varW - (labelX - margin), 18) withAttributes:labelAttrs];
        }

        if (isDataRow) {
            NSDictionary *valueAttrs = row.rowType == "nested_total"
                ? rightSemiboldAttrs
                : row.rowType == "missing"
                ? (hasGroup ? mutedRightAttrs : mutedAttrs)
                : ((allNumericColumns || hasGroup) ? rightAttrs : leftAttrs);
            for (size_t c = 0; c < state->columns.size(); ++c) {
                bool isSplitTotalColumn = hasSplitColumns && (int)c >= state->groupSpanningColumnCount;
                if (isContingency && isNestedLeaf && !isSplitTotalColumn && !selection.empty()) {
                    rlispstat::core::AggregateCoverage coverage =
                        rlispstat::core::ContingencyCellCoverage(*state, r, c, selection);
                    if (coverage == rlispstat::core::AggregateCoverage::Full) {
                        [[NSColor colorWithCalibratedRed:0.85 green:0.91 blue:0.96 alpha:1.0] setFill];
                        NSRectFill(NSMakeRect(columnX(c) - 4.0, y - 2.0, columnWidth(c) - 2.0, rowH));
                    } else if (coverage == rlispstat::core::AggregateCoverage::Partial) {
                        [[NSColor colorWithCalibratedRed:0.92 green:0.96 blue:0.99 alpha:1.0] setFill];
                        NSRectFill(NSMakeRect(columnX(c) - 4.0, y - 2.0, columnWidth(c) - 2.0, rowH));
                    }
                }
                std::string value = c < row.values.size() ? row.values[c] : "";
                NSDictionary* cellAttrs=state->tableType=="missing_data_overview"?(state->columns[c]=="Missing variables"?leftAttrs:rightAttrs):valueAttrs;
                if(!state->missingnessSource.empty()) {
                    cellAttrs=Table1Attributes(row.rowType=="nested_total"?12:17, row.rowType=="nested_total"?NSFontWeightSemibold:NSFontWeightRegular,
                        NSTextAlignmentCenter, value=="—"?[NSColor secondaryLabelColor]:[NSColor labelColor]);
                    const auto found=state->missingnessPatternRows.find(state->columns[c]);
                    if(found!=state->missingnessPatternRows.end()) {
                        std::lock_guard<std::mutex> lock(g_mutex);
                        const auto selected=g_groupSelections.find(state->missingnessSource);
                        if(selected!=g_groupSelections.end() && std::any_of(found->second.begin(),found->second.end(),[&](int id){return selected->second.count(id)>0;})) {
                            [[NSColor colorWithCalibratedRed:0.87 green:0.93 blue:0.99 alpha:1] setFill];
                            NSRectFill(NSMakeRect(columnX(c),y-2,columnWidth(c)-8,rowH));
                        }
                    }
                }
                if(state->tableType=="missing_data_test")cellAttrs=state->columns[c]=="Status"?leftAttrs:rightAttrs;
                [ToNSString(value) drawInRect:NSMakeRect(columnX(c), y, columnWidth(c) - 8.0, 18) withAttributes:cellAttrs];
            }
        }
        CGFloat tx = columnX((size_t)valueCols);
        if (state->showP) {
            [ToNSString(row.p) drawInRect:NSMakeRect(tx, y, pW - 8.0, 18) withAttributes:rightAttrs];
            tx += pW;
        }
        if (state->showTest) {
            [ToNSString(row.test) drawInRect:NSMakeRect(tx, y, testW - 8.0, 18) withAttributes:leftAttrs];
        }
        y += rowH;
    }

    y += 14.0;
    NSDictionary *noteAttrs = Table1NoteAttributes();
    for (const std::string &note : state->footnotes) {
        CGFloat height = Table1NoteHeight(ToNSString(note),width-2*margin,noteAttrs);
        [ToNSString(note) drawWithRect:NSMakeRect(margin, y, width - 2.0 * margin, height)
            options:NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading
            attributes:noteAttrs];
        y += height + 2.0;
    }
    NSDictionary *warningAttrs = Table1NoteAttributes(true);
    for (const std::string &warning : state->warnings) {
        CGFloat height = Table1NoteHeight(ToNSString("Warning: "+warning),width-2*margin,warningAttrs);
        [ToNSString("Warning: " + warning) drawInRect:NSMakeRect(margin, y, width - 2.0 * margin, height)
                                        withAttributes:warningAttrs];
        y += height + 2.0;
    }
}

- (NSInteger)columnAtPoint:(NSPoint)point
{
    Table1DisplayState *state = [_controller state];
    rlispstat::core::Table1ReportLayout layout =
        rlispstat::core::BuildTable1ReportLayout(*state, [self bounds].size.width);
    return (NSInteger)rlispstat::core::Table1ReportColumnAtPoint(
        *state,
        layout,
        rlispstat::platform::macos::ToCorePoint(point));
}

- (NSMenu *)diagnosticStatisticMenuAtPoint:(NSPoint)point
{
    Table1DisplayState *state = [_controller state];
    if (state->tableType != "mi_missing_information") return nil;
    const auto layout = rlispstat::core::BuildTable1ReportLayout(*state, self.bounds.size.width);
    if (point.y < layout.headerOffset - 28.0 ||
        point.y >= layout.headerOffset + layout.rowHeight * state->rows.size()) return nil;
    NSInteger column = [self columnAtPoint:point];
    if (column < 0 || (size_t)column >= state->columns.size()) return nil;
    NSMenu *menu = [_controller contextMenuForRow:[self rowAtPoint:point]];
    NSMenuItem *item = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
        action:@selector(explainTableStatistic:) keyEquivalent:@""];
    [item setTarget:_controller]; [item setRepresentedObject:ToNSString(state->columns[(size_t)column])];
    [menu insertItem:item atIndex:0];
    [menu insertItem:[NSMenuItem separatorItem] atIndex:1];
    return menu;
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSMenu *diagnosticMenu = [self diagnosticStatisticMenuAtPoint:point];
    if (diagnosticMenu) {
        [diagnosticMenu popUpMenuPositioningItem:nil atLocation:point inView:self];
        return;
    }
    NSInteger row = [self rowAtPoint:point];
    [_controller setSelectedRow:row];
    Table1DisplayState *state = [_controller state];
    if(!state->missingnessSource.empty()) {
        const auto layout=rlispstat::core::BuildTable1ReportLayout(*state,self.bounds.size.width);
        if(point.x>=layout.margin+layout.stubArea && point.y>=layout.headerOffset-28 &&
            point.y<layout.headerOffset+layout.rowHeight*state->rows.size()) {
            [_controller selectMissingPattern:[self columnAtPoint:point]];return;
        }
    }
    if (state->tableType != "nested_contingency" && state->tableType != "mi_contingency" && row >= 0 &&
        (size_t)row < state->rows.size()) {
        rlispstat::core::Table1ReportLayout layout =
            rlispstat::core::BuildTable1ReportLayout(*state, [self bounds].size.width);
        const Table1DisplayRow &displayRow = state->rows[(size_t)row];
        const bool clickedVariableName = state->tableType == "table1" &&
            !displayRow.variable.empty() &&
            rlispstat::core::Table1DisplayLabelText(displayRow) == displayRow.variable;
        if (clickedVariableName &&
            point.x >= layout.margin && point.x <= layout.margin + layout.stubArea) {
            NSMenu *menu = [_controller replacementMenuForRow:row];
            [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
            [self setNeedsDisplay:YES];
            return;
        }
    }
    if (state->tableType == "nested_contingency" || state->tableType == "mi_contingency") {
        rlispstat::core::Table1ReportLayout layout =
            rlispstat::core::BuildTable1ReportLayout(*state, [self bounds].size.width);
        rlispstat::core::Point corePoint = rlispstat::platform::macos::ToCorePoint(point);
        const bool inStubHeader = layout.hasStubs &&
            point.y >= layout.headerOffset - 28.0 && point.y < layout.headerOffset &&
            point.x >= layout.margin && point.x < layout.margin + layout.stubArea;
        if (inStubHeader) {
            const std::size_t index = std::min<std::size_t>(
                state->stubHeaders.size() - 1,
                (std::size_t)((point.x - layout.margin) / layout.stubWidth));
            NSMenu *menu = [_controller contextMenuForNestedRowVariable:
                state->stubHeaders[index]];
            [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
            [self setNeedsDisplay:YES];
            return;
        }
        const bool inSplitHeader = layout.hasSpanningHeader &&
            point.y >= layout.headerOffset - 42.0 &&
            point.y < layout.headerOffset - 28.0 &&
            point.x >= layout.margin + layout.stubArea;
        if (inSplitHeader) {
            NSMenu *menu = [_controller contextMenuForNestedSplitVariable];
            [menu popUpMenuPositioningItem:nil atLocation:point inView:self];
            [self setNeedsDisplay:YES];
            return;
        }
        if (state->tableType == "mi_contingency") return;
        auto publishContingencySelection = [&](const rlispstat::core::ContingencySelection &selection) -> bool {
            if (selection.kind == rlispstat::core::ContingencySelectionKind::None || state->datasetId.empty()) {
                return false;
            }
            std::set<int> targetRows = rlispstat::core::ContingencyRowsForSelection(*state, selection);
            std::string group = state->datasetId;
            int selectionVersion = 0;
            auto mode = rlispstat::core::SelectionMode::Replace;
            if ([event modifierFlags] & NSEventModifierFlagCommand) {
                mode = rlispstat::core::SelectionMode::Toggle;
            } else if ([event modifierFlags] & NSEventModifierFlagShift) {
                mode = rlispstat::core::SelectionMode::Add;
            }
            std::set<int> next;
            bool changed = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto it = g_groupSelections.find(group);
                std::set<int> current = (it != g_groupSelections.end()) ? it->second : std::set<int>();
                next = rlispstat::core::ApplySelectionOperation(current, targetRows, mode);
                changed = SetGroupSelectionUnlocked(group, next, &selectionVersion);
            }
            if (changed) {
                PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", group, "table:" + state->id, "", std::vector<int>(next.begin(), next.end()), selectionVersion);
            }
            return true;
        };

        rlispstat::core::ContingencySelection selection =
            rlispstat::core::Table1ContingencySelectionAtPoint(*state, layout, corePoint, (int)row);
        if (publishContingencySelection(selection)) {
            [self setNeedsDisplay:YES];
            return;
        }
        if (rlispstat::core::Table1ReportPointIsColumnHeader(layout, corePoint)) {
            [self setNeedsDisplay:YES];
            return;
        }
    }
    [self setNeedsDisplay:YES];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    if(!([_controller state])->missingnessSource.empty())[_controller setMissingPattern:[self columnAtPoint:point]];
    NSMenu *diagnosticMenu = [self diagnosticStatisticMenuAtPoint:point];
    if (diagnosticMenu) return diagnosticMenu;
    NSInteger row = [self rowAtPoint:point];
    [_controller setSelectedRow:row];
    [self setNeedsDisplay:YES];
    return [_controller contextMenuForRow:row];
}

@end

@implementation Table1WindowController

- (instancetype)initWithState:(const Table1DisplayState &)state
{
    self = [super init];
    if (!self) return nil;
    _state = state;
    _tableId = state.id;
    _group = state.datasetId;
    _selectedRow = -1;
    CGFloat initialWidth = _state.columns.size() > 6 ? 1180.0 : 760.0;
    if (_state.tableType == "mi_missing_information")
        initialWidth = std::max(760.0, rlispstat::core::BuildTable1ReportLayout(_state,0).width + 48.0);
    NSScreen *screen = [NSScreen mainScreen];
    if (screen) initialWidth = std::min(initialWidth, NSWidth([screen visibleFrame]) - 48.0);
    CGFloat preferredContentHeight = (CGFloat)rlispstat::core::Table1PreferredHeight(_state) + 130.0;
    CGFloat initialHeight = std::max<CGFloat>(330.0, std::min<CGFloat>(620.0, preferredContentHeight));
    NSRect frame = NextWindowFrameOnMain(initialWidth, initialHeight);
    _window = [[NSWindow alloc] initWithContentRect:frame
                                          styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                     NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable)
                                            backing:NSBackingStoreBuffered
                                              defer:NO];
    [_window setDelegate:self];
    NSString *nativeWindowTitle = (_state.tableType == "compare_means" || _state.tableType == "mi_contingency")
        ? ToNSString(_state.title)
        : (_state.tableType == "nested_contingency" ? @"Contingency Table"
                                                     : ToNSString(rlispstat::core::Table1WindowTitle()));
    [_window setTitle:nativeWindowTitle];
    NSView *content = [_window contentView];
    [content setWantsLayer:YES];
    [[content layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];

    _titleField = GLMLabel(ToNSString(_state.title), NSMakeRect(16, frame.size.height - 52, frame.size.width - 210, 24), 17, NSFontWeightSemibold);
    [_titleField setAutoresizingMask:NSViewMinYMargin | NSViewWidthSizable];
    [content addSubview:_titleField];
    _badgeField = GLMRightLabel(ToNSString(_state.datasetId), NSMakeRect(frame.size.width - 176, frame.size.height - 48, 150, 20), 12, NSFontWeightMedium);
    [_badgeField setAutoresizingMask:NSViewMinYMargin | NSViewMinXMargin];
    [content addSubview:_badgeField];

    _scrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 56, frame.size.width - 32, frame.size.height - 130)];
    [_scrollView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [_scrollView setHasVerticalScroller:YES];
    [_scrollView setHasHorizontalScroller:YES];
    if (_state.tableType == "mi_missing_information") {
        [_scrollView setScrollerStyle:NSScrollerStyleLegacy];
        [_scrollView setAutohidesScrollers:YES];
    }
    [_scrollView setBorderType:NSNoBorder];
    [_scrollView setDrawsBackground:NO];
    _reportView = [[Table1ReportView alloc] initWithController:self];
    [_scrollView setDocumentView:_reportView];
    [content addSubview:_scrollView];

    _linkCheckbox = [[NSButton alloc] initWithFrame:NSMakeRect(16, 12, 200, 22)];
    [_linkCheckbox setButtonType:NSButtonTypeSwitch];
    [_linkCheckbox setTitle:@"Link to Bar Chart"];
    [_linkCheckbox setTarget:self];
    [_linkCheckbox setAction:@selector(toggleLink:)];
    [_linkCheckbox setAutoresizingMask:NSViewMaxXMargin | NSViewMaxYMargin];
    [_linkCheckbox setFont:[NSFont systemFontOfSize:11]];
    [_linkCheckbox setHidden:!_state.linkEnabled && _state.sourcePlotId.empty()];
    [content addSubview:_linkCheckbox];

    _addVariableButton = [[LinkEDASecondaryActionButton alloc] initWithFrame:NSMakeRect(12, 8, 164, 26)];
    [_addVariableButton setTitle:@"+ Add variable…"];
    [_addVariableButton setBezelStyle:NSBezelStyleInline];
    [_addVariableButton setBordered:NO];
    [_addVariableButton setAlignment:NSTextAlignmentLeft];
    [_addVariableButton setFont:[NSFont systemFontOfSize:12 weight:NSFontWeightRegular]];
    [_addVariableButton setContentTintColor:[NSColor secondaryLabelColor]];
    [_addVariableButton setTarget:self];
    [_addVariableButton setAction:@selector(showLinkedModelVariables:)];
    __block Table1WindowController *blockSelf = self;
    [(LinkEDASecondaryActionButton *)_addVariableButton setSecondaryAction:^{
        [blockSelf showSearchableAddVariableSelector];
    }];
    [_addVariableButton setAutoresizingMask:NSViewMaxXMargin | NSViewMaxYMargin];
    [_addVariableButton setToolTip:@"Add a variable to Table 1."];
    [content addSubview:_addVariableButton];

    _statusField = GLMLabel(ToNSString(rlispstat::core::Table1StatusFieldHint()), NSMakeRect(16, 34, frame.size.width - 32, 20), 11, NSFontWeightRegular);
    [_statusField setTextColor:[NSColor colorWithCalibratedWhite:0.38 alpha:1.0]];
    [_statusField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
    [content addSubview:_statusField];
    [self updateState:_state];
    return self;
}

- (void)embedDescriptives:(Table1WindowController *)controller
{
    if(!controller || controller==self || _embeddedDescriptives)return;
    _embeddedDescriptives=controller;controller->_overviewOwner=self;
    [controller->_window orderOut:nil];
    [controller->_scrollView setDocumentView:nil];
    [_scrollView setDocumentView:nil];
    _combinedReport=[[NSView alloc] initWithFrame:NSZeroRect];
    [_combinedReport setWantsLayer:YES];[[_combinedReport layer] setBackgroundColor:[[NSColor whiteColor] CGColor]];
    [_combinedReport addSubview:_reportView];
    [_combinedReport addSubview:controller->_reportView];
    _descriptiveHeading=[NSTextField labelWithString:@"Descriptives by missingness pattern"];
    [_descriptiveHeading setFont:[NSFont boldSystemFontOfSize:14]];
    [_combinedReport addSubview:_descriptiveHeading];
    [_scrollView setDocumentView:_combinedReport];
    const NSRect screen=[[_window screen] visibleFrame];
    const CGFloat natural=std::max(rlispstat::core::Table1NaturalWidth(_state),rlispstat::core::Table1NaturalWidth(*[controller state]));
    FitResultTableWindowToContent(_window,NSMakeSize(std::min<CGFloat>(natural+48,NSWidth(screen)-48),std::min<CGFloat>(720,NSHeight(screen)-48)),NSMakeSize(760,330));
    [_statusField setStringValue:@"Right-click a table for export options."];
    [self layoutMissingDataReport];
    [_combinedReport scrollPoint:NSMakePoint(0,NSHeight([_combinedReport bounds]))];
    [self show];
}

- (void)layoutMissingDataReport
{
    if(!_embeddedDescriptives)return;
    const CGFloat width=std::max<CGFloat>([_scrollView contentSize].width,
        std::max(rlispstat::core::Table1NaturalWidth(_state),rlispstat::core::Table1NaturalWidth(*[_embeddedDescriptives state])));
    const CGFloat first=[_reportView preferredHeightForWidth:width];
    const CGFloat second=[_embeddedDescriptives->_reportView preferredHeightForWidth:width];
    [_combinedReport setFrame:NSMakeRect(0,0,width,first+second+50)];
    [_reportView setFrame:NSMakeRect(0,second+50,width,first)];
    [_descriptiveHeading setFrame:NSMakeRect(14,second+10,width-28,28)];
    [_embeddedDescriptives->_reportView setFrame:NSMakeRect(0,0,width,second)];
}

- (void)updateState:(const Table1DisplayState &)state
{
    _sourceState = state;
    if (_sourceState.needsRFit) {
        rlispstat::core::MainRTable1Task task;
        task.id = state.id; task.group = state.datasetId;
        task.analysisKind = state.tableType == "nested_contingency" ? "nested_contingency" : state.tableType == "frequency" ? "frequency" : "table1";
            task.contingencyDisplayMode = state.nestedDisplayMode;
            task.sourcePlotId = state.sourcePlotId; task.linkEnabled = state.linkEnabled;
        task.title = state.title; task.variables = state.variables;
        task.groupVariable = state.groupVariable; task.variableTypes = state.variableTypes;
        task.showP = state.showP; task.showTest = state.showTest;
        task.scope = state.dataScopeCaptured && state.dataScope.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds ? "selected" : "all";
        task.scopeDescription = state.dataScopeCaptured ? state.dataScope.sourceDescription : "All observations";
        if (task.scope == "selected") task.rows = state.dataScope.originalRowIds;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            MacCommandDispatcher().prepareTable1Task(task);
            g_pendingTable1Tasks.erase(std::remove_if(g_pendingTable1Tasks.begin(), g_pendingTable1Tasks.end(),
                [&](const auto &old) { return old.id == task.id; }), g_pendingTable1Tasks.end());
            g_pendingTable1Tasks.push_back(std::move(task));
        }
        _sourceState.needsRFit = false;
        NotifyMainRTaskAvailable();
    }
    _state = rlispstat::core::Table1ApplyDisplayPreferences(
        _sourceState, g_descriptivesTablePreferences);
    _tableId = state.id;
    _group = state.datasetId;
    [_titleField setStringValue:ToNSString(_state.title)];
    const bool isMIDiagnostic = _state.tableType == "missing_data_overview" || _state.tableType == "missing_data_test" || _state.tableType == "missingness_descriptives" || _state.tableType == "mi_diagnostics" || _state.tableType == "mi_missing_information";
    [_window setTitle:(isMIDiagnostic || _state.tableType == "compare_means" || _state.tableType == "mi_contingency") ? ToNSString(_state.title)
                      : (_state.tableType == "nested_contingency" ? @"Contingency Table"
                                                                   : ToNSString(rlispstat::core::Table1WindowTitle()))];
    [_badgeField setStringValue:ToNSString(_state.datasetId)];
    // The complete dataset name is already in the report subtitle. A narrow
    // duplicate badge can hide the identifying suffix of an imputed dataset.
    [_badgeField setHidden:isMIDiagnostic];
    [_titleField setToolTip:ToNSString(_state.title)];
    NSRect titleFrame = [_titleField frame];
    titleFrame.size.width = NSWidth([[_window contentView] bounds]) - (isMIDiagnostic ? 32.0 : 210.0);
    [_titleField setFrame:titleFrame];
    bool isContingency = _state.tableType == "nested_contingency";
    bool hasSource = !_state.sourcePlotId.empty();
    [_linkCheckbox setHidden:!isContingency || !hasSource];
    const bool showsAddVariable = _state.tableType == "table1" ||
        !_state.linkedModelOutputId.empty() || !_state.missingnessSource.empty();
    [_addVariableButton setHidden:!showsAddVariable];
    NSMenu *addVariableMenu = showsAddVariable ? [self addVariableMenu] : nil;
    BOOL hasAddVariable = NO;
    for (NSMenuItem *item in [addVariableMenu itemArray]) {
        if ([item isEnabled] && [item action] != nil) { hasAddVariable = YES; break; }
    }
    [_addVariableButton setEnabled:hasAddVariable];
    [_addVariableButton setToolTip:_state.tableType == "table1"
        ? @"Add a variable to Table 1."
        : @"Add a variable to this analysis."];
    [_linkCheckbox setState:_state.linkEnabled ? NSControlStateValueOn : NSControlStateValueOff];
    NSScreen *screen = [_window screen] ?: [NSScreen mainScreen];
    CGFloat logicalWidth = (CGFloat)rlispstat::core::Table1NaturalWidth(_state);
    CGFloat desiredWidth = _state.tableType == "mi_missing_information"
        ? std::max<CGFloat>(760.0, logicalWidth + 48.0)
        : std::max<CGFloat>(760.0, std::min<CGFloat>(1180.0, logicalWidth + 32.0));
    CGFloat desiredHeight = std::max<CGFloat>(330.0,
        std::min<CGFloat>(680.0, (CGFloat)rlispstat::core::Table1PreferredHeight(_state) + 130.0));
    if (screen) {
        desiredWidth = std::min(desiredWidth, NSWidth([screen visibleFrame]) - 48.0);
        desiredHeight = std::min(desiredHeight, NSHeight([screen visibleFrame]) - 48.0);
    }
    FitResultTableWindowToContent(
        _window, NSMakeSize(desiredWidth, desiredHeight), NSMakeSize(760.0, 330.0));
    CGFloat width = std::max<CGFloat>([_scrollView contentSize].width, logicalWidth);
    CGFloat height = [_reportView preferredHeightForWidth:width];
    [_reportView setFrame:NSMakeRect(0, 0, width, height)];
    [_reportView setNeedsDisplay:YES];
    [self layoutMissingDataReport];
    if(_overviewOwner)[_overviewOwner layoutMissingDataReport];
    [_statusField setStringValue:ToNSString(_state.statusText.empty() && _state.tableType!="mi_missing_information"
        ? rlispstat::core::Table1StatusFieldHint()
        : _state.statusText)];
}

- (void)windowDidResize:(NSNotification *)notification
{
    (void)notification;
    if (!_reportView || !_scrollView) return;
    if(_embeddedDescriptives){[self layoutMissingDataReport];return;}
    const CGFloat naturalWidth = (CGFloat)rlispstat::core::Table1NaturalWidth(_state);
    const CGFloat width = std::max<CGFloat>([_scrollView contentSize].width, naturalWidth);
    NSRect frame = [_reportView frame];
    const CGFloat height = [_reportView preferredHeightForWidth:width];
    if (std::fabs(NSWidth(frame) - width) > 0.5 || std::fabs(NSHeight(frame) - height) > 0.5) {
        frame.size.width = width;
        frame.size.height = height;
        [_reportView setFrame:frame];
        [_reportView setNeedsDisplay:YES];
    }
}

- (Table1DisplayState *)state
{
    return &_state;
}

- (NSInteger)selectedRow
{
    return _selectedRow;
}

- (void)setSelectedRow:(NSInteger)row
{
    _selectedRow = row;
}

- (std::string)tableText
{
    return rlispstat::core::Table1PlainText(_state);
}

- (void)copyTable:(id)sender
{
    (void)sender;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString([self tableText]) forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(rlispstat::core::Table1CopiedStatus())];
}

- (std::string)csvText
{
    return rlispstat::core::Table1CSVText(_state);
}

- (std::string)markdownText
{
    return rlispstat::core::Table1MarkdownText(_state);
}

- (void)writeString:(const std::string &)text defaultName:(NSString *)name title:(NSString *)title
{
    NSSavePanel *panel = [NSSavePanel savePanel];
    [panel setNameFieldStringValue:name];
    [panel setTitle:title];
    if ([panel runModal] == NSModalResponseOK) {
        NSError *error = nil;
        BOOL ok = [ToNSString(text) writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:&error];
        [_statusField setStringValue:ok ? ToNSString(rlispstat::core::Table1ExportedStatus()) : ToNSString(rlispstat::core::Table1ExportFailedStatus())];
    }
}

