- (void)rebuildNestedContingencyFromSelection
{
    MacCommandDispatcher().applicationState().captureAnalysisScope(_state.datasetId, _state.dataScope, _state.dataScopeCaptured);
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        [_statusField setStringValue:ToNSString(rlispstat::core::DatasetNotAvailableForRecomputeStatus())];
        return;
    }
    if (df.datasetType == "multiple_imputation") {
        const Table1DisplayState requested = _state;
        const Table1DisplayState previous = _sourceState;
        const auto generation = ++g_miContingencyRecomputeVersions[requested.id];
        const std::string scope = ScopeForCapturedAnalysisScope(requested.dataScope,requested.dataScopeCaptured,"all");
        const std::string specification = std::to_string(df.provenance.currentVersion.version) + "|" +
            OriginalRowsAnalysisModelSpec(requested.dataScope,requested.dataScopeCaptured) + "|" + requested.nestedDisplayMode;
        [_statusField setStringValue:@"Calculating in R…"];
        std::thread([df,requested,previous,generation,scope,specification]() {
            std::string message; std::vector<std::string> payload;
            const bool ok = RunRBackedMultipleImputationAnalysis(df,"contingency",requested.id,
                requested.variables,requested.groupVariable,"",{},scope,&message,specification,&payload);
            dispatch_async(dispatch_get_main_queue(), ^{
                auto found=g_table1Controllers.find(requested.id);
                if(found==g_table1Controllers.end() || g_miContingencyRecomputeVersions[requested.id]!=generation) return;
                const auto reply = ok ? HandleCommandLines(payload) : "ERR " + message;
                if(reply.rfind("ERR",0)==0) {
                    [found->second updateState:previous];
                    ShowWorkbenchMessageOnMain(@"Contingency Table",ToNSString(reply));
                }
            });
        }).detach();
        return;
    }
    Table1DisplayState rebuilt = rlispstat::core::NestedContingencyTableStateForDataFrame(
        df, _state.id, _state.variables, _state.groupVariable, _state.nestedDisplayMode,
        _state.dataScopeCaptured ? &_state.dataScope : nullptr);
    rebuilt.datasetId = _state.datasetId;
    rebuilt.linkEnabled = _state.linkEnabled;
    rebuilt.sourcePlotId = _state.sourcePlotId;
    [self updateState:rebuilt];
}

- (void)propagateNestedContingencyToBarplot
{
    std::string plotId;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTableSources.find(_tableId);
        if (it == g_linkedTableSources.end() || !_state.linkEnabled) return;
        plotId = it->second;
    }
    PlotModel *barplotModel = nil;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        BarplotView *view = BarplotViewForPlotUnlocked(plotId);
        if (view) barplotModel = view.model;
    }
    if (!barplotModel || barplotModel->kind != "barplot") {
        [self rebuildNestedContingencyFromSelection];
        return;
    }
    barplotModel->barplotXVariables = _state.variables;
    barplotModel->barplotSplitVariable = _state.groupVariable;
    std::string message;
    if (!RebuildBarplotFromModelVariables(barplotModel, &message)) {
        [_statusField setStringValue:ToNSString(message)];
        return;
    }
    UpdateWindowTitleOnMain(barplotModel);
    RedrawPlotOnMain(barplotModel->id);
    NotifyBarplotLinkedTablesChanged(plotId);
}

- (void)changeSplitVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    const std::string candidate([title UTF8String]);
    if (std::find(_state.variables.begin(), _state.variables.end(), candidate) != _state.variables.end()) {
        if (!rlispstat::core::MoveContingencyRowToColumn(
                _state.variables, _state.groupVariable, candidate)) {
            [_statusField setStringValue:@"Keep at least one row variable in the table."];
            return;
        }
    } else {
        _state.groupVariable = candidate;
    }
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        [self propagateNestedContingencyToBarplot];
    } else {
        [self rebuildNestedContingencyFromSelection];
    }
}

- (void)addRowVariableFromMenu:(id)sender
{
    NSString *title = [sender representedObject];
    if (!title) return;
    std::string variable = std::string([title UTF8String]);
    if (std::find(_state.variables.begin(), _state.variables.end(), variable) == _state.variables.end()) {
        if (variable == _state.groupVariable) _state.groupVariable.clear();
        _state.variables.push_back(variable);
        if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
            [self propagateNestedContingencyToBarplot];
        } else {
            [self rebuildNestedContingencyFromSelection];
        }
    }
}

- (void)replaceRowVariableFromMenu:(id)sender
{
    id represented = [sender representedObject];
    std::string oldVariable, newVariable;
    if ([represented isKindOfClass:[NSArray class]] && [(NSArray *)represented count] >= 2) {
        oldVariable = std::string([[(NSArray *)represented objectAtIndex:0] UTF8String]);
        newVariable = std::string([[(NSArray *)represented objectAtIndex:1] UTF8String]);
    } else {
        NSString *title = [represented isKindOfClass:[NSString class]] ? represented : nil;
        if (!title || _selectedRow < 0 || (size_t)_selectedRow >= _state.rows.size()) return;
        oldVariable = _state.rows[(size_t)_selectedRow].variable;
        newVariable = std::string([title UTF8String]);
    }
    if (oldVariable.empty() || newVariable.empty()) return;
    if (newVariable == _state.groupVariable) {
        if (!rlispstat::core::MoveContingencyRowToColumn(
                _state.variables, _state.groupVariable, oldVariable)) return;
    } else {
        for (std::string &variable : _state.variables) {
            if (variable == oldVariable) {
                variable = newVariable;
                break;
            }
        }
    }
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        [self propagateNestedContingencyToBarplot];
    } else {
        [self rebuildNestedContingencyFromSelection];
    }
}

- (void)removeRowVariableFromMenu:(id)sender
{
    if (_state.variables.size()<=1) return;
    std::string variable;
    NSString *representedVariable = [sender representedObject];
    if (representedVariable) {
        variable = std::string([representedVariable UTF8String]);
    } else if (_selectedRow >= 0 && (size_t)_selectedRow < _state.rows.size()) {
        variable = _state.rows[(size_t)_selectedRow].variable;
    }
    if (variable.empty() && !_state.variables.empty()) {
        variable = _state.variables.back();
    }
    if (variable.empty()) return;
    _state.variables.erase(std::remove(_state.variables.begin(), _state.variables.end(), variable), _state.variables.end());
    if (_state.variables.empty()) return;
    if (_state.linkEnabled && !_state.sourcePlotId.empty()) {
        [self propagateNestedContingencyToBarplot];
    } else {
        [self rebuildNestedContingencyFromSelection];
    }
}

