- (void)setMissingPattern:(NSInteger)column
{
    _selectedPattern=column>=0 && (size_t)column<_state.columns.size()?_state.columns[(size_t)column]:"";
}
- (void)selectMissingPattern:(NSInteger)column
{
    [self setMissingPattern:column];
    auto found=_state.missingnessPatternRows.find(_selectedPattern);if(found==_state.missingnessPatternRows.end())return;
    std::vector<std::string> command={"SET_SELECTED",_state.missingnessSource,std::to_string(found->second.size())};
    for(int row:found->second)command.push_back(std::to_string(row));
