- (void)missingPatternAction:(id)sender
{
    NSArray* args=[sender representedObject];if(args.count!=2)return;
    const auto task=rlispstat::core::MissingPatternActionTask(_state.missingnessSource,_state.id,
        std::string([args[0] UTF8String]),std::string([args[1] UTF8String]));
    {std::lock_guard<std::mutex> lock(g_mutex);g_pendingMissingDataTasks.push_back(task);}
    [_statusField setStringValue:@"Updating missingness results in R…"];NotifyMainRTaskAvailable();
}
- (NSMenu *)missingnessMenu
{
    NSMenu* menu=[[NSMenu alloc] initWithTitle:@"Missingness patterns"];
    auto item=[&](NSString* title,NSString* action,NSString* value,NSMenu* parent){
        NSMenuItem* i=[[NSMenuItem alloc] initWithTitle:title action:@selector(missingPatternAction:) keyEquivalent:@""];
        [i setTarget:self];[i setRepresentedObject:@[action,value]];[parent addItem:i];return i;
    };
    if(!_selectedPattern.empty()) item(ToNSString("Descriptives for "+_selectedPattern),@"descriptives",ToNSString(_selectedPattern),menu);
    item(@"Descriptives for all patterns",@"descriptives",@"all",menu);
    item(@"Little's MCAR test (continuous variables)",@"little",@"",menu);
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem* add=[[NSMenuItem alloc] initWithTitle:@"Add variable" action:nil keyEquivalent:@""];
    [add setSubmenu:[self linkedModelVariableMenu]];[menu addItem:add];
    if(_selectedRow>=0 && (size_t)_selectedRow<_state.rows.size() && !_state.rows[_selectedRow].variable.empty()) {
        const auto variable=_state.rows[_selectedRow].variable;
        auto remove=item(ToNSString("Remove "+variable),@"remove",ToNSString(variable),menu);
        [remove setEnabled:_state.variables.size()>1];
    }
    NSMenuItem* save=[[NSMenuItem alloc] initWithTitle:@"Save to data" action:nil keyEquivalent:@""];
    NSMenu* saves=[[NSMenu alloc] initWithTitle:@"Save to data"];
    for(const auto& option:std::vector<std::pair<std::string,std::string>>{{"pattern","Missingness pattern"},{"n_missing","Number missing"},{"pct_missing","Percent missing"},{"indicators","Variable indicators"}})
        item(ToNSString(option.second),@"save",ToNSString(option.first),saves);
    [save setSubmenu:saves];[menu addItem:save];
    NSMenuItem* exportItem=[[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu* exports=[[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(exports,_reportView,ToNSString(_state.title),ToNSString(_state.id),ToNSString([self tableText]));
    AddRCodeExportItems(exports,"output",_state.id,true);[exportItem setSubmenu:exports];[menu addItem:exportItem];
    return menu;
}

- (NSMenu *)linkedModelVariableMenu
{
    if(!_state.missingnessSource.empty()) {
        NSMenu *menu=[[NSMenu alloc] initWithTitle:@"Add variable"];
        for(const auto& v:_state.addVariableOptions) {
            NSMenuItem* item=[[NSMenuItem alloc] initWithTitle:ToNSString(v) action:@selector(missingPatternAction:) keyEquivalent:@""];
            [item setTarget:self];[item setRepresentedObject:@[@"add",ToNSString(v)]];[menu addItem:item];
        }
        return menu;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Add variable"];
    for (const auto &variable : _state.addVariableOptions)
        [menu addItem:PlotCommandMenuItem(ToNSString(variable),
            ToNSString("MI_ADD_VARIABLE|" + _state.linkedModelOutputId + "|" + variable))];
    return menu;
}

- (NSMenu *)addVariableMenu
{
    if (_state.tableType != "table1") return [self linkedModelVariableMenu];
    const auto titles = rlispstat::core::DefaultTable1ContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addVariable)];
    DataFrameModel data;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId)) {
            data = *current;
            found = true;
        }
    }
    if (found) for (const DataColumn &column : data.columns) {
        if (DataColumnLooksLikeId(column) || column.name == _state.groupVariable ||
            std::find(_state.variables.begin(), _state.variables.end(), column.name) !=
                _state.variables.end()) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name)
            action:@selector(addVariableFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(column.name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] == 0) {
        NSMenuItem *empty = [[NSMenuItem alloc]
            initWithTitle:ToNSString(titles.noAvailableVariables) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [menu addItem:empty];
    }
    return menu;
}

