        rlispstat::core::Table1ReplaceVariableTitle(variable))];
    DataFrameModel data;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId)) {
            data = *current;
            found = true;
        }
    }
    if (found) for (const DataColumn &column : data.columns) {
        if (DataColumnLooksLikeId(column) || column.name == variable ||
            column.name == _state.groupVariable ||
            std::find(_state.variables.begin(), _state.variables.end(), column.name) !=
                _state.variables.end()) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name)
            action:@selector(replaceVariableFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(column.name)];
