    }
    if ([menu numberOfItems] == 0) {
        NSMenuItem *empty = [[NSMenuItem alloc]
            initWithTitle:ToNSString(titles.noAvailableVariables) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [menu addItem:empty];
    }
    return menu;
}

