- (void)showSearchableAddVariableSelector
{
    std::vector<std::string> choices;
    if (_state.tableType == "table1") {
        DataFrameModel data; bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            if (const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId)) {
                data = *current; found = true;
            }
        }
        if (found) for (const DataColumn &column : data.columns) {
            if (DataColumnLooksLikeId(column) || column.name == _state.groupVariable ||
                std::find(_state.variables.begin(), _state.variables.end(), column.name) !=
                    _state.variables.end()) continue;
            choices.push_back(column.name);
        }
    } else choices = _state.addVariableOptions;
    ShowSearchableAddSelector(_window, _addVariableButton, @"Add variables", choices,
        ^(NSArray<NSString *> *names) {
            if (_state.tableType == "table1") {
                bool changed = false;
                for (NSString *label in names) {
                    std::string variable = label.UTF8String;
                    if (std::find(_state.variables.begin(), _state.variables.end(), variable) ==
                        _state.variables.end()) {
                        _state.variables.push_back(variable); changed = true;
                    }
                }
                if (changed) [self rebuildFromBackendData];
                return;
            }
            for (NSString *label in names) {
                const std::string variable = label.UTF8String;
                if (!_state.missingnessSource.empty())
                    HandleCommandLines({"MISSING_PATTERN_ACTION", _state.missingnessSource,
                                        _state.id, "add", variable});
                else HandleCommandLines({"MI_ADD_VARIABLE",
                                         _state.linkedModelOutputId, variable});
            }
        });
}

- (void)addStatisticExplanationMenuTo:(NSMenu *)menu
{
    if (!menu) return;
    NSMenuItem *root = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().explainStatistic)
        action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:[root title]];
    std::vector<std::string> statistics;
    if (_state.tableType == "table1") {
        statistics = {"N", "Mean", "SD", "Median", "Q1", "Q3",
                      "Observed count", "Percent"};
    } else if (_state.tableType == "nested_contingency" || _state.tableType == "mi_contingency") {
        statistics = {"Observed count", "Percent"};
    } else if (_state.tableType == "compare_means") {
        statistics = {"Mean", "Mean difference", "SE", "df", "t", "p",
                      "Lower 95%", "Upper 95%"};
    } else {
        statistics = _state.columns;
    }
    if (_state.showTest) statistics.push_back("Test");
    if (_state.showP) statistics.push_back("p");
    std::set<std::string> seen;
    for (const std::string &statistic : statistics) {
        if (statistic.empty() || !seen.insert(statistic).second) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(statistic)
            action:@selector(explainTableStatistic:) keyEquivalent:@""];
        [item setTarget:self]; [item setRepresentedObject:ToNSString(statistic)];
        [submenu addItem:item];
    }
    if ([submenu numberOfItems] == 0) return;
    [root setSubmenu:submenu]; [menu addItem:root];
    [menu addItem:[NSMenuItem separatorItem]];
}

- (void)frequencyVariableSelected:(id)sender
{
    _state.variables = {std::string([[sender representedObject] UTF8String])};
    [self rebuildFromBackendData];
}

- (rlispstat::core::PublicationTableSpec)clipboardTable
{
    // Preserve exactly the values already displayed. This is a clipboard
    // representation, not a second statistical calculation.
    rlispstat::core::PublicationTableSpec table;
    table.title = rlispstat::core::PublicationTitleWithoutTableLabel(_state.title);
    table.subtitle = rlispstat::core::Table1Subtitle(_state);
    table.footnotes = _state.footnotes;
    const auto textValue = [](const std::string &value) {
        rlispstat::core::PublicationValue cell;
        cell.kind = rlispstat::core::PublicationValueKind::Text;
        cell.text = value;
        return cell;
    };
    if (_state.stubHeaders.empty()) {
        table.columns.push_back({"variable", "Variable", "", -1, false});
        table.stubColumns.push_back(0);
    } else {
        for (const auto &header : _state.stubHeaders) {
            table.stubColumns.push_back(table.columns.size());
            table.columns.push_back({header, header, "", -1, false});
        }
    }
    for (const auto &column : _state.columns)
        table.columns.push_back({column, column, "", -1, column == "p"});
    if (_state.showP) table.columns.push_back({"p", "p", "", -1, true});
    if (_state.showTest) table.columns.push_back({"test", "Test", "", -1, false});
    for (const auto &row : _state.rows) {
        std::vector<rlispstat::core::PublicationValue> cells;
        if (_state.stubHeaders.empty()) cells.push_back(textValue(row.label));
        else for (std::size_t i = 0; i < _state.stubHeaders.size(); ++i)
            cells.push_back(textValue(i < row.stubValues.size() ? row.stubValues[i] : ""));
        for (const auto &value : row.values) cells.push_back(textValue(value));
        if (_state.showP) cells.push_back(textValue(row.p));
        if (_state.showTest) cells.push_back(textValue(row.test));
        cells.resize(table.columns.size());
        table.rows.push_back(std::move(cells));
    }
    return table;
}

- (NSMenu *)contextMenuForRow:(NSInteger)row
{
    if (_state.tableType == "frequency") {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Frequency table"];
        NSMenuItem *variable = [[NSMenuItem alloc] initWithTitle:@"Variable" action:nil keyEquivalent:@""];
        NSMenu *choices = [[NSMenu alloc] initWithTitle:@"Variable"];
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            if (const auto *df = FindDataFrameUnlockedConst(_state.datasetId)) for (const auto &column : df->columns) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name) action:@selector(frequencyVariableSelected:) keyEquivalent:@""];
                [item setTarget:self]; [item setRepresentedObject:ToNSString(column.name)];
                [item setState:(!_state.variables.empty() && column.name == _state.variables.front()) ? NSControlStateValueOn : NSControlStateValueOff];
                [choices addItem:item];
            }
        }
        [variable setSubmenu:choices]; [menu addItem:variable];
        [self addStatisticExplanationMenuTo:menu];
        NSMenuItem *exportItem=[[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
        NSMenu *exports=[[NSMenu alloc] initWithTitle:@"Export"];
        const auto clipboard = [self clipboardTable];
        AddStandardTableVisualExportItems(exports,_reportView,ToNSString(_state.title),ToNSString(_state.id),ToNSString([self tableText]),&clipboard,nullptr,false,false);
        AddRCodeExportItems(exports,"output",_state.id,true);
        [exports addItem:[NSMenuItem separatorItem]];
        for (auto entry : std::vector<std::pair<NSString *, SEL>>{{@"CSV…", @selector(exportCSV:)}, {@"PDF — APA 7 style…", @selector(exportPDFAPA:)},
            {@"PDF — As displayed…", @selector(exportPDF:)}}) {
            NSMenuItem *item=[[NSMenuItem alloc] initWithTitle:entry.first action:entry.second keyEquivalent:@""];
            [item setTarget:self]; [exports addItem:item];
        }
        OrganizeExportMenu(exports);
        [exportItem setSubmenu:exports];[menu addItem:exportItem];
        return menu;
    }
    if(!_state.missingnessSource.empty())return [self missingnessMenu];
    if (_state.tableType == "missing_data_overview" || _state.tableType == "missing_data_test" || _state.tableType == "missingness_descriptives" || _state.tableType == "mi_diagnostics" || _state.tableType == "mi_missing_information") {
        NSMenu *menu=[[NSMenu alloc] initWithTitle:ToNSString(_state.title)];
        if(_state.tableType=="mi_diagnostics") [menu addItem:ImputationDiagnosticsMenuItem(_state.datasetId)];
        NSMenuItem *exportItem=[[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
        NSMenu *exports=[[NSMenu alloc] initWithTitle:@"Export"];
        AddStandardTableVisualExportItems(exports,_reportView,ToNSString(_state.title),ToNSString(_state.id),ToNSString([self tableText]));
        AddRCodeExportItems(exports,"output",_state.id,true);[exportItem setSubmenu:exports];[menu addItem:exportItem];return menu;
    }

    if (_state.tableType == "compare_means") {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Test"];
        AddMissingInformationMenu(menu, _state.id);
        [self addStatisticExplanationMenuTo:menu];
        NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
        NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
        const auto clipboard = [self clipboardTable];
        AddStandardTableVisualExportItems(exportMenu, _reportView, ToNSString(_state.title),
            ToNSString(_state.id), ToNSString([self tableText]), &clipboard, nullptr, false, false);
        AddRCodeExportItems(exportMenu, "output", _state.id, true);
        [exportMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:@"CSV…" action:@selector(exportCSV:) keyEquivalent:@""];
        [csv setTarget:self]; [exportMenu addItem:csv];
        NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(exportPDFAPA:) keyEquivalent:@""];
        [apa setTarget:self]; [exportMenu addItem:apa];
        NSMenuItem *displayed = [[NSMenuItem alloc] initWithTitle:@"PDF — As displayed…" action:@selector(exportPDF:) keyEquivalent:@""];
        [displayed setTarget:self]; [exportMenu addItem:displayed];
        OrganizeExportMenu(exportMenu);
        [menu setSubmenu:exportMenu forItem:exportItem];
