        [menu addItem:exportItem];
        return menu;
    }
    if (_state.tableType == "nested_contingency" || _state.tableType == "mi_contingency") {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Nested Contingency Table"];
        AddMissingInformationMenu(menu, _state.id);
