        NSMenu *removeRowMenu = [[NSMenu alloc] initWithTitle:@"Remove Row Variable"];
        for (const std::string &variable : _state.variables) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(variable) action:@selector(removeRowVariableFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
