            }
            if (addNoneOption) {
                [changeColMenu addItem:[[NSMenuItem alloc] initWithTitle:@"(no available variables)" action:nil keyEquivalent:@""]];
            }
        }
        [colVarMenu setSubmenu:changeColMenu forItem:changeCol];
        [colVarMenu addItem:changeCol];

        if (!_state.groupVariable.empty()) {
            NSMenuItem *clearCol = [[NSMenuItem alloc] initWithTitle:@"No Column Split" action:@selector(changeSplitVariableFromMenu:) keyEquivalent:@""];
            [clearCol setTarget:self];
            [clearCol setRepresentedObject:ToNSString(std::string(""))];
            [colVarMenu addItem:clearCol];
        }

        [menu setSubmenu:colVarMenu forItem:colVarItem];
        [menu addItem:colVarItem];

        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *displayItem = [[NSMenuItem alloc] initWithTitle:@"Cell contents" action:nil keyEquivalent:@""];
        NSMenu *displayMenu = [[NSMenu alloc] initWithTitle:@"Cell contents"];
        {
            struct { NSString *title; NSString *mode; } modes[] = {
                {@"Counts and Percentages", @"count_percent"},
                {@"Counts Only", @"count"},
                {@"Percentages Only", @"percent"},
            };
            for (size_t mi = 0; mi < sizeof(modes) / sizeof(modes[0]); ++mi) {
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:modes[mi].title action:@selector(setNestedDisplayModeFromMenu:) keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:modes[mi].mode];
                if (_state.nestedDisplayMode == std::string([modes[mi].mode UTF8String])) {
                    [item setState:NSControlStateValueOn];
                }
