    const auto titles = rlispstat::core::DefaultTable1ContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.root)];
        AddMissingInformationMenu(menu, _state.id);
    [self addDescriptiveDisplayMenuTo:menu];
