    AddStandardTableVisualExportItems(exportMenu, _reportView, ToNSString(_state.title),
        ToNSString(_state.id), ToNSString([self tableText]), &clipboard, nullptr, false, false);
    AddRCodeExportItems(exportMenu, "output", _state.id, true);
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *csv = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.exportCSV) action:@selector(exportCSV:) keyEquivalent:@""];
    [csv setTarget:self];
    [exportMenu addItem:csv];
    NSMenuItem *markdown = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.exportMarkdown) action:@selector(exportMarkdown:) keyEquivalent:@""];
    [markdown setTarget:self];
    [exportMenu addItem:markdown];
    NSMenuItem *apa = [[NSMenuItem alloc] initWithTitle:@"PDF — APA 7 style…" action:@selector(exportPDFAPA:) keyEquivalent:@""];
    [apa setTarget:self]; [exportMenu addItem:apa];
    NSMenuItem *pdf = [[NSMenuItem alloc] initWithTitle:@"PDF — As displayed…" action:@selector(exportPDF:) keyEquivalent:@""];
    [pdf setTarget:self]; [exportMenu addItem:pdf];
    OrganizeExportMenu(exportMenu);
    [menu setSubmenu:exportMenu forItem:exportItem];

    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.addVariable) action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.addVariable)];
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (found) {
        for (const DataColumn &col : df.columns) {
            if (DataColumnLooksLikeId(col) || col.name == _state.groupVariable) continue;
            if (std::find(_state.variables.begin(), _state.variables.end(), col.name) != _state.variables.end()) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(addVariableFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(col.name)];
            [addMenu addItem:item];
        }
    }
    NSMenuItem *group = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.groupingVariable) action:nil keyEquivalent:@""];
    NSMenu *groupMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.groupingVariable)];
    NSMenuItem *clear = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.clearGroupingVariable) action:@selector(clearGroup:) keyEquivalent:@""];
    [clear setTarget:self];
    if (_state.groupVariable.empty()) [clear setState:NSControlStateValueOn];
    [groupMenu addItem:clear];
    [groupMenu addItem:[NSMenuItem separatorItem]];
    if (found) {
        for (const DataColumn &col : df.columns) {
            if (DataColumnLooksLikeId(col)) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(setGroupFromMenu:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(col.name)];
            if (col.name == _state.groupVariable) [item setState:NSControlStateValueOn];
            [groupMenu addItem:item];
        }
    }
    [menu setSubmenu:groupMenu forItem:group];
    [menu addItem:group];
    [menu addItem:[NSMenuItem separatorItem]];

    if ([addMenu numberOfItems] == 0) [addMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableVariables) action:nil keyEquivalent:@""]];
    [menu setSubmenu:addMenu forItem:add];
    [menu addItem:add];

    std::string variable;
    if (row >= 0 && (size_t)row < _state.rows.size()) variable = _state.rows[(size_t)row].variable;
    if (!variable.empty()) {
        NSString *replaceTitle = ToNSString(
            rlispstat::core::Table1ReplaceVariableTitle(variable));
        NSMenuItem *change = [[NSMenuItem alloc] initWithTitle:replaceTitle action:nil keyEquivalent:@""];
        NSMenu *changeMenu = [[NSMenu alloc] initWithTitle:replaceTitle];
        if (found) {
            for (const DataColumn &col : df.columns) {
                if (DataColumnLooksLikeId(col) || col.name == _state.groupVariable || col.name == variable) continue;
                if (std::find(_state.variables.begin(), _state.variables.end(), col.name) !=
                    _state.variables.end()) continue;
                NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(col.name) action:@selector(replaceVariableFromMenu:) keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(col.name)];
                [changeMenu addItem:item];
            }
        }
        if ([changeMenu numberOfItems] == 0) [changeMenu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableVariables) action:nil keyEquivalent:@""]];
        [menu setSubmenu:changeMenu forItem:change];
        [menu addItem:change];
        NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1RemoveVariableTitle(variable)) action:@selector(removeSelectedVariable:) keyEquivalent:@""];
        [remove setTarget:self];
        [menu addItem:remove];
        NSMenuItem *typeRoot = [[NSMenuItem alloc] initWithTitle:@"Type of variable" action:nil keyEquivalent:@""];
        NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:@"Type of variable"];
        const std::string currentType = rlispstat::core::Table1VariableAnalysisType(
            _state, variable);
        for (const char *type : {"numeric", "categorical", "ordinal"}) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::Table1TypeMenuTitle(type)) action:@selector(typeMenuSelected:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:@[ToNSString(variable), ToNSString(std::string(type))]];
            if (currentType == type) [item setState:NSControlStateValueOn];
            [typeMenu addItem:item];
        }
        [menu setSubmenu:typeMenu forItem:typeRoot];
        [menu addItem:typeRoot];
        [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.showVariableInformation) action:nil keyEquivalent:@""]];
        [menu addItem:[NSMenuItem separatorItem]];
        for (const auto &option : rlispstat::core::Table1PlotMenuOptions(
                 variable, currentType, _state.groupVariable)) {
            SEL action = option.command == "TABLE1_OPEN_BARPLOT"
                ? @selector(openBarplot:)
                : (option.command == "TABLE1_OPEN_BOXPLOT"
                    ? @selector(openBoxplot:)
                    : @selector(openHistogram:));
            NSMenuItem *plot = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title)
                                                          action:action keyEquivalent:@""];
            [plot setTarget:self];
            [menu addItem:plot];
        }
    }

    [menu addItem:[NSMenuItem separatorItem]];
    AddSnapshotAlbumContextItems(menu);
    [menu addItem:exportItem];
    return menu;
}

- (void)toggleDescriptiveDisplayOption:(id)sender
{
    NSString *key = [sender representedObject];
    if ([key isEqualToString:@"mean"]) g_descriptivesTablePreferences.showMean = !g_descriptivesTablePreferences.showMean;
    else if ([key isEqualToString:@"sd"]) g_descriptivesTablePreferences.showSD = !g_descriptivesTablePreferences.showSD;
    else if ([key isEqualToString:@"se"]) g_descriptivesTablePreferences.showSE = !g_descriptivesTablePreferences.showSE;
    else if ([key isEqualToString:@"ci95"]) g_descriptivesTablePreferences.showCI95 = !g_descriptivesTablePreferences.showCI95;
    else if ([key isEqualToString:@"median"]) g_descriptivesTablePreferences.showMedian = !g_descriptivesTablePreferences.showMedian;
    else if ([key isEqualToString:@"quartiles"]) g_descriptivesTablePreferences.showQuartiles = !g_descriptivesTablePreferences.showQuartiles;
    else if ([key isEqualToString:@"missing"]) g_descriptivesTablePreferences.showMissing = !g_descriptivesTablePreferences.showMissing;
    else if ([key isEqualToString:@"overall"]) g_descriptivesTablePreferences.showOverall = !g_descriptivesTablePreferences.showOverall;
    else if ([key isEqualToString:@"p"]) g_descriptivesTablePreferences.showP = !g_descriptivesTablePreferences.showP;
    else if ([key isEqualToString:@"test"]) g_descriptivesTablePreferences.showTest = !g_descriptivesTablePreferences.showTest;
    Table1DisplayState source = _sourceState;
    [self updateState:source];
}

- (void)addDescriptiveDisplayMenuTo:(NSMenu *)menu
{
    if (_state.tableType != "table1") return;
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Statistics and columns" action:nil keyEquivalent:@""];
    NSMenu *options = [[NSMenu alloc] initWithTitle:@"Statistics and columns"];
    auto addGroup = [&](NSString *title,
                        std::initializer_list<std::tuple<NSString *, NSString *, bool>> entries) {
        NSMenuItem *group = [[NSMenuItem alloc] initWithTitle:title action:nil keyEquivalent:@""];
        NSMenu *submenu = [[NSMenu alloc] initWithTitle:title];
        for (const auto &entry : entries) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:std::get<0>(entry)
                action:@selector(toggleDescriptiveDisplayOption:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:std::get<1>(entry)];
            [item setState:std::get<2>(entry) ? NSControlStateValueOn : NSControlStateValueOff];
            [submenu addItem:item];
        }
        [options setSubmenu:submenu forItem:group];
        [options addItem:group];
    };
    addGroup(@"Location", {
        {@"Mean", @"mean", g_descriptivesTablePreferences.showMean},
        {@"Median", @"median", g_descriptivesTablePreferences.showMedian}
    });
    addGroup(@"Dispersion", {
        {@"SD", @"sd", g_descriptivesTablePreferences.showSD},
        {@"Q1 and Q3", @"quartiles", g_descriptivesTablePreferences.showQuartiles}
    });
    addGroup(@"Uncertainty", {
        {@"SE", @"se", g_descriptivesTablePreferences.showSE},
        {@"95% CI", @"ci95", g_descriptivesTablePreferences.showCI95}
    });
    addGroup(@"Rows and columns", {
        {@"Missing in original", @"missing", g_descriptivesTablePreferences.showMissing},
        {@"Overall", @"overall", g_descriptivesTablePreferences.showOverall},
        {@"p", @"p", g_descriptivesTablePreferences.showP},
        {@"Test", @"test", g_descriptivesTablePreferences.showTest}
    });
    [menu setSubmenu:options forItem:root];
    [menu addItem:root];
    [menu addItem:[NSMenuItem separatorItem]];
}

- (void)show
{
    EnableNotesForWindow(_window, _tableId, @"this statistical table", _state.datasetId);
    [_window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

- (BOOL)isVisible
{
    return [_window isVisible];
}

- (NSWindow *)getWindow
{
    return _window;
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    if(_embeddedDescriptives){_embeddedDescriptives->_overviewOwner=nil;[[_embeddedDescriptives getWindow] close];}

    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MacCommandDispatcher().cancelTable1Task(_tableId);
        g_pendingTable1Tasks.erase(std::remove_if(g_pendingTable1Tasks.begin(), g_pendingTable1Tasks.end(),
            [&](const auto &task) { return task.id == _tableId; }), g_pendingTable1Tasks.end());
    }
    g_table1Controllers.erase(_tableId);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTableSources.find(_tableId);
        if (it != g_linkedTableSources.end()) {
            std::string plotId = it->second;
            g_linkedTables[plotId].erase(_tableId);
            if (g_linkedTables[plotId].empty()) g_linkedTables.erase(plotId);
            g_linkedTableSources.erase(it);
        }
    }
}

@end

static bool Table1WindowUsesDatasetAnalysis(const Table1DisplayState &state)
{
    if (!state.missingnessSource.empty() || !state.linkedModelOutputId.empty()) return false;
    return state.tableType == "table1" || state.tableType == "frequency" ||
        state.tableType == "nested_contingency";
}

static void RefitOpenTable1WindowsOnMain(const std::string &group,
                                         bool captureActiveScope)
{
    const std::string copy = group;
    void (^refitBlock)(void) = ^{
        std::vector<std::pair<Table1WindowController *, Table1DisplayState>> pending;
        const AnalysisScope active =
            MacCommandDispatcher().applicationState().activeAnalysisScope(copy);
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            for (const auto &entry : g_table1Controllers) {
                Table1WindowController *controller = entry.second;
                Table1DisplayState *current = controller ? [controller state] : nullptr;
                if (!current || current->datasetId != copy ||
                    !Table1WindowUsesDatasetAnalysis(*current)) continue;
                Table1DisplayState requested = *current;
                if (captureActiveScope) {
                    requested.dataScope = active;
                    requested.dataScopeCaptured = true;
                }
                requested.needsRFit = true;
                requested.statusText = "Data or analysis scope changed; recalculating in R...";
                pending.push_back({controller, std::move(requested)});
            }
        }
        for (auto &entry : pending) [entry.first updateState:entry.second];
    };
    if ([NSThread isMainThread]) refitBlock();
    else dispatch_async(dispatch_get_main_queue(), refitBlock);
}

static std::map<std::string, NativeMixedModelState> &g_nativeMixedModels =
    MacCommandDispatcher().applicationState().nativeMixedModels();

static bool RunNativeMixedModelReport(const NativeMixedModelState &state, std::string *report, std::string *message);

struct MixedModelHitRegion {
    NSRect rect;
    std::string action;
    std::string value;
};

@protocol MixedModelReportActionTarget <NSObject>
- (void)mixedModelAction:(NSString *)action value:(NSString *)value atPoint:(NSPoint)point inView:(NSView *)view;
- (NSMenu *)mixedModelContextMenuForAction:(NSString *)action value:(NSString *)value;
@end

@interface MixedModelReportView : NSView {
    MixedModelReportState _state;
    std::vector<MixedModelHitRegion> _hitRegions;
    id<MixedModelReportActionTarget> _controller;
    NSPopUpButton *_dependentPopup;
}
- (instancetype)initWithFrame:(NSRect)frameRect state:(const MixedModelReportState &)state;
- (void)updateState:(const MixedModelReportState &)state;
- (CGFloat)contentHeightForWidth:(CGFloat)width;
- (NSString *)rawText;
- (void)setController:(id<MixedModelReportActionTarget>)controller;
- (void)configureResponseCandidates:(const std::vector<std::string> &)candidates
                           selected:(const std::string &)selected
                             target:(id)target
                             action:(SEL)action;
@end

@implementation MixedModelReportView
- (NSString *)snapshotTabDelimitedText { return [self rawText]; }
- (BOOL)isFlipped { return YES; }

- (instancetype)initWithFrame:(NSRect)frameRect state:(const MixedModelReportState &)state
{
    self = [super initWithFrame:frameRect];
    if (self) {
        _state = state;
        [self setWantsLayer:YES];
        // Use the same native response selector as the General Linear Model.
        // Keeping this as a real control also gives us the standard keyboard,
        // accessibility and menu behaviour instead of imitating a popup in
        // drawRect:.
        _dependentPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(140.0, 35.0, 148.0, 28.0)];
        [self addSubview:_dependentPopup];
    }
    return self;
}

- (void)setController:(id<MixedModelReportActionTarget>)controller
{
    _controller = controller;
}

- (void)configureResponseCandidates:(const std::vector<std::string> &)candidates
                           selected:(const std::string &)selected
                             target:(id)target
                             action:(SEL)action
{
    [_dependentPopup removeAllItems];
    for (const std::string &candidate : candidates) {
        [_dependentPopup addItemWithTitle:ToNSString(candidate)];
    }
    if (!selected.empty()) [_dependentPopup selectItemWithTitle:ToNSString(selected)];
    [_dependentPopup setTarget:target];
    [_dependentPopup setAction:action];
    [_dependentPopup setEnabled:[_dependentPopup numberOfItems] > 0];
}

- (NSString *)rawText { return ToNSString(_state.rawText); }

- (NSDictionary *)attrsWithSize:(CGFloat)size weight:(NSFontWeight)weight color:(NSColor *)color
{
    return @{ NSFontAttributeName: [NSFont systemFontOfSize:size weight:weight],
              NSForegroundColorAttributeName: color };
}

- (CGFloat)contentHeightForWidth:(CGFloat)width
{
    CGFloat h = 12.0 + 24.0; // title
    h += 28.0;               // controls
    h += 24.0;               // formula and selected-row status

    const std::vector<std::pair<std::string, std::string>> fitItems = MixedModelFitSummaryItems(_state);
    const size_t fitColumns = width >= 700.0 ? 4 : (width >= 540.0 ? 3 : 2);
    const size_t fitRows = fitItems.empty() ? 1 : (fitItems.size() + fitColumns - 1) / fitColumns;
    h += 20.0 + (CGFloat)fitRows * 20.0 + 10.0;

    for (const char *title : {"Fixed effects", "Random effects", "Warnings"}) {
        const MixedModelReportSection *section = FindMixedModelReportSection(_state, title);
        if (!section) continue;
        h += 20.0 + (CGFloat)std::max<size_t>(1, section->rows.size()) * 20.0;
        if (section->title == "Fixed effects" || section->title == "Random effects") h += 20.0;
        h += 6.0;
    }
    h += 24.0; // status
    return std::max((CGFloat)380.0, h + 10.0);
}

- (void)updateState:(const MixedModelReportState &)state
{
    _state = state;
    CGFloat h = [self contentHeightForWidth:[self bounds].size.width];
    [self setFrameSize:NSMakeSize([self bounds].size.width, h)];
    [self setNeedsDisplay:YES];
}

- (void)drawText:(NSString *)text rect:(NSRect)rect attrs:(NSDictionary *)attrs right:(BOOL)right
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setAlignment:right ? NSTextAlignmentRight : NSTextAlignmentLeft];
    NSMutableDictionary *drawAttrs = [attrs mutableCopy];
    [drawAttrs setObject:style forKey:NSParagraphStyleAttributeName];
    [text drawInRect:rect withAttributes:drawAttrs];
}

- (void)addHitRect:(NSRect)rect action:(const std::string &)action value:(const std::string &)value
{
    MixedModelHitRegion hit;
    hit.rect = rect;
    hit.action = action;
    hit.value = value;
    _hitRegions.push_back(hit);
}

- (NSInteger)hitIndexAtPoint:(NSPoint)point
{
    for (NSInteger i = (NSInteger)_hitRegions.size() - 1; i >= 0; --i) {
        if (NSPointInRect(point, _hitRegions[(size_t)i].rect)) return i;
    }
    return -1;
}

- (BOOL)rowLooksLikeFixedEffect:(const std::string &)value
{
    if (value.empty() || value == "(Intercept)") return NO;
    auto it = g_nativeMixedModels.find(_state.id);
    if (it == g_nativeMixedModels.end()) return YES;
    for (const std::string &term : it->second.fixedEffects) {
        if (value == term || value.find(term) == 0 || value.find("factor(" + term + ")") == 0) return YES;
    }
    return NO;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    _hitRegions.clear();
    [WorkbenchSurfaceColor() setFill];
    NSRectFill([self bounds]);
    CGFloat width = [self bounds].size.width;
    CGFloat margin = 14.0;
    CGFloat avail = std::max((CGFloat)160.0, width - 2.0 * margin);
    CGFloat y = 12.0;
    NSDictionary *titleAttrs = [self attrsWithSize:16 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.12 alpha:1.0]];
    NSDictionary *labelAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.16 alpha:1.0]];
    NSDictionary *smallAttrs = [self attrsWithSize:11 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.34 alpha:1.0]];
    NSDictionary *sectionAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.18 alpha:1.0]];
    NSDictionary *headerAttrs = [self attrsWithSize:12 weight:NSFontWeightSemibold color:[NSColor colorWithCalibratedWhite:0.20 alpha:1.0]];
    NSDictionary *cellAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedWhite:0.14 alpha:1.0]];
    NSDictionary *warnAttrs = [self attrsWithSize:12 weight:NSFontWeightRegular color:[NSColor colorWithCalibratedRed:0.56 green:0.14 blue:0.10 alpha:1.0]];

    [self drawText:ToNSString(_state.title) rect:NSMakeRect(margin, y, avail * 0.62, 22) attrs:titleAttrs right:NO];
    const std::string badge = !_state.dataset.empty() ? _state.dataset : _state.group;
    [self drawText:ToNSString(badge) rect:NSMakeRect(margin + avail * 0.62, y + 2, avail * 0.38, 18) attrs:smallAttrs right:YES];
    y += 26.0;

    [self drawText:@"Response variable" rect:NSMakeRect(margin, y + 2.0, 126.0, 18.0) attrs:labelAttrs right:NO];
    [_dependentPopup setFrame:NSMakeRect(margin + 126.0, y - 3.0, 148.0, 28.0)];
    CGFloat controlX = margin + 290.0;

    std::string scopeValue = _state.scope.empty() ? "all" : _state.scope;
    std::string scopeDisplay = scopeValue == "all" ? "All data" : (scopeValue == "selected" ? "Selected rows" : scopeValue);
    [self drawText:@"Scope:" rect:NSMakeRect(controlX, y + 2.0, 43.0, 18.0) attrs:labelAttrs right:NO];
    controlX += 45.0;
    CGFloat scopeW = std::min((CGFloat)116.0, std::max((CGFloat)94.0, avail * 0.15));
    NSRect scopeRect = NSMakeRect(controlX, y, scopeW, 22.0);
    [[NSColor colorWithCalibratedWhite:0.975 alpha:1.0] setFill];
    [[NSBezierPath bezierPathWithRoundedRect:scopeRect xRadius:5.0 yRadius:5.0] fill];
    [[NSColor colorWithCalibratedWhite:0.86 alpha:1.0] setStroke];
    NSBezierPath *scopeBorder = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(scopeRect, 0.5, 0.5) xRadius:5.0 yRadius:5.0];
    [scopeBorder setLineWidth:0.7];
    [scopeBorder stroke];
    [self drawText:ToNSString(scopeDisplay) rect:NSInsetRect(scopeRect, 8.0, 3.0) attrs:smallAttrs right:NO];
    controlX = NSMaxX(scopeRect) + 20.0;
    if (!_state.estimation.empty()) {
        [self drawText:ToNSString("Estimation: " + _state.estimation) rect:NSMakeRect(controlX, y + 2.0, 150.0, 18.0) attrs:labelAttrs right:NO];
    } else if (!_state.family.empty()) {
        std::string familyText = "Distribution: " + _state.family;
        if (!_state.link.empty()) familyText += "/" + _state.link;
        [self drawText:ToNSString(familyText) rect:NSMakeRect(controlX, y + 2.0, 180.0, 18.0) attrs:labelAttrs right:NO];
    }
    y += 28.0;

    std::string formula = _state.formula;
    formula.erase(std::remove(formula.begin(), formula.end(), '`'), formula.end());
    if (!formula.empty()) {
        [self drawText:ToNSString("Formula: " + formula) rect:NSMakeRect(margin, y, avail * 0.68, 18.0) attrs:smallAttrs right:NO];
    }
    const size_t totalRows = RowCountForGroup(_state.group);
    if (totalRows > 0) {
        [self drawText:ToNSString(SelectedRowsStatus(SelectionCount(_state.group), totalRows))
                   rect:NSMakeRect(margin + avail * 0.68, y, avail * 0.32, 18.0)
                  attrs:smallAttrs
                  right:YES];
    }
    y += 24.0;

    [self drawText:@"Global fit" rect:NSMakeRect(margin, y, avail, 18.0) attrs:sectionAttrs right:NO];
    y += 20.0;
    const std::vector<std::pair<std::string, std::string>> fitItems = MixedModelFitSummaryItems(_state);
    const size_t fitColumns = width >= 700.0 ? 4 : (width >= 540.0 ? 3 : 2);
    CGFloat fitW = avail / (CGFloat)fitColumns;
    for (size_t i = 0; i < fitItems.size(); ++i) {
        const size_t row = i / fitColumns;
        const size_t col = i % fitColumns;
        NSString *label = ToNSString(fitItems[i].first + " ");
        CGFloat labelW = std::min(fitW * 0.62, [label sizeWithAttributes:sectionAttrs].width + 2.0);
        CGFloat itemX = margin + (CGFloat)col * fitW;
        CGFloat itemY = y + (CGFloat)row * 20.0;
        [self drawText:label rect:NSMakeRect(itemX, itemY, labelW, 18.0) attrs:sectionAttrs right:NO];
        [self drawText:ToNSString(fitItems[i].second) rect:NSMakeRect(itemX + labelW, itemY, fitW - labelW - 8.0, 18.0) attrs:labelAttrs right:NO];
    }
    const size_t fitRows = fitItems.empty() ? 1 : (fitItems.size() + fitColumns - 1) / fitColumns;
    y += (CGFloat)fitRows * 20.0 + 2.0;
    [[NSColor colorWithCalibratedWhite:0.88 alpha:1.0] setStroke];
    NSBezierPath *fitRule = [NSBezierPath bezierPath];
    [fitRule moveToPoint:NSMakePoint(margin, y)];
    [fitRule lineToPoint:NSMakePoint(margin + avail, y)];
    [fitRule setLineWidth:0.7];
    [fitRule stroke];
    y += 10.0;

    for (const char *sectionTitle : {"Fixed effects", "Random effects", "Warnings"}) {
        const MixedModelReportSection *sectionPtr = FindMixedModelReportSection(_state, sectionTitle);
        if (!sectionPtr) continue;
        const MixedModelReportSection &section = *sectionPtr;
        [self drawText:ToNSString(section.title) rect:NSMakeRect(margin, y, avail, 18) attrs:sectionAttrs right:NO];
        y += 20.0;
        size_t colCount = 1;
        for (const auto &row : section.rows) colCount = std::max(colCount, row.size());
        std::vector<CGFloat> colX(colCount, margin), colW(colCount, avail);
        BOOL twoColumnLayout = (colCount == 2);
        if (colCount > 1) {
            std::vector<CGFloat> fractions;
            if (section.title == "Fixed effects") {
                fractions = colCount == 7
                    ? std::vector<CGFloat>{0.29, 0.14, 0.12, 0.12, 0.10, 0.10, 0.13}
                    : std::vector<CGFloat>{0.32, 0.15, 0.13, 0.13, 0.12, 0.15};
            } else if (section.title == "Random effects" && colCount == 5) {
                fractions = {0.24, 0.24, 0.18, 0.18, 0.16};
            } else if (twoColumnLayout) {
                fractions = {0.50, 0.50};
            }
            if (fractions.size() == colCount) {
                CGFloat nextX = margin;
                for (size_t c = 0; c < colCount; ++c) {
                    colX[c] = nextX;
                    colW[c] = avail * fractions[c];
                    nextX += colW[c];
                }
            } else {
                CGFloat firstW = std::min((CGFloat)180.0, avail * 0.30);
                CGFloat restW = (avail - firstW) / (CGFloat)(colCount - 1);
                colX[0] = margin; colW[0] = firstW;
                for (size_t c = 1; c < colCount; ++c) {
                    colX[c] = margin + firstW + restW * (CGFloat)(c - 1);
                    colW[c] = restW;
                }
            }
        }
        for (size_t r = 0; r < section.rows.size(); ++r) {
            const std::vector<std::string> &row = section.rows[r];
            BOOL header = r == 0 && section.title != "Warnings";
            NSDictionary *attrs = section.title == "Warnings" ? warnAttrs : (header ? headerAttrs : cellAttrs);
            CGFloat rowY = y;
            for (size_t c = 0; c < row.size(); ++c) {
                [self drawText:ToNSString(row[c])
                           rect:NSMakeRect(colX[c], y, colW[c] - 8.0, 18)
                          attrs:attrs
                          right:((section.title == "Fixed effects" && c >= 2) ||
                                 (section.title == "Random effects" && c >= 2))];
            }
            if (!header && !row.empty()) {
                if (section.title == "Fixed effects" && [self rowLooksLikeFixedEffect:row[0]]) {
                    [self addHitRect:NSMakeRect(colX[0], rowY - 1.0, colW[0] - 4.0, 21.0) action:"fixed" value:row[0]];
                } else if (section.title == "Random effects" && row[0] != "Residual") {
                    [self addHitRect:NSMakeRect(colX[0], rowY - 1.0, colW[0] - 4.0, 21.0) action:"random" value:row[0]];
                }
            }
            y += 20.0;
            if (header) {
                [[NSColor colorWithCalibratedWhite:0.88 alpha:1.0] setStroke];
                NSBezierPath *rule = [NSBezierPath bezierPath];
                [rule moveToPoint:NSMakePoint(margin, y - 3.0)];
                [rule lineToPoint:NSMakePoint(margin + avail, y - 3.0)];
                [rule setLineWidth:0.7];
                [rule stroke];
            }
        }
        if (section.title == "Fixed effects") {
            NSRect addRect = NSMakeRect(margin, y, std::min((CGFloat)180.0, avail), 20.0);
            [self drawText:ToNSString(rlispstat::core::MixedModelAddFixedEffectDrawLabel()) rect:addRect attrs:labelAttrs right:NO];
            [self addHitRect:NSInsetRect(addRect, -3.0, -2.0) action:"add_fixed" value:""];
            y += 20.0;
        } else if (section.title == "Random effects") {
            NSRect addRect = NSMakeRect(margin, y, std::min((CGFloat)190.0, avail), 20.0);
            [self drawText:ToNSString(rlispstat::core::MixedModelAddRandomEffectDrawLabel()) rect:addRect attrs:labelAttrs right:NO];
            [self addHitRect:NSInsetRect(addRect, -3.0, -2.0) action:"add_random" value:""];
            y += 20.0;
        }
        y += 6.0;
    }

    [self drawText:ToNSString(MixedModelReportStatusLine(_state))
               rect:NSMakeRect(margin, y, avail, 22.0)
              attrs:smallAttrs
              right:NO];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger hit = [self hitIndexAtPoint:point];
    if (hit >= 0 && _controller && [_controller respondsToSelector:@selector(mixedModelContextMenuForAction:value:)]) {
        const MixedModelHitRegion &region = _hitRegions[(size_t)hit];
        NSMenu *menu = [_controller mixedModelContextMenuForAction:ToNSString(region.action) value:ToNSString(region.value)];
        if (menu) return SnapshotAlbumMenu(menu, @"Mixed Model");
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelWindowTitle())];
    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardTableVisualExportItems(exportMenu, self, ToNSString(_state.title),
        ToNSString(_state.id.empty() ? "mixed-model" : _state.id), [self rawText]);
    AddRCodeExportItems(exportMenu, "output", _state.id, true);
    [exportMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::MixedModelCopyTableTitle()) action:@selector(copyReport:) keyEquivalent:@""];
    [copy setTarget:self];
    [exportMenu addItem:copy];
    OrganizeExportMenu(exportMenu);
    [exportRoot setSubmenu:exportMenu];
    [menu addItem:exportRoot];
    AddSnapshotAlbumContextItems(menu);
    return menu;
}

- (void)copyReport:(id)sender
{
    (void)sender;
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:[self rawText] forType:NSPasteboardTypeString];
}

- (void)mouseDown:(NSEvent *)event
{
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger hit = [self hitIndexAtPoint:point];
    if (hit >= 0 && _controller && [_controller respondsToSelector:@selector(mixedModelAction:value:atPoint:inView:)]) {
        const MixedModelHitRegion &region = _hitRegions[(size_t)hit];
        [_controller mixedModelAction:ToNSString(region.action)
                                value:ToNSString(region.value)
                              atPoint:point
                               inView:self];
        return;
    }
    [super mouseDown:event];
}
@end

