static std::string HandleGeneralizedProgressCommand(const std::vector<std::string> &lines)
{
    if (lines.size() < 16) return "ERR malformed generalized progress event";
    const std::vector<std::string> event = lines;
    const CFAbsoluteTime receivedAt = CFAbsoluteTimeGetCurrent();
    dispatch_async(dispatch_get_main_queue(), ^{
        std::string modelId = event[1];
        GeneralizedGLMWindowController *controller = nil;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto found = g_generalizedGLMControllers.find(modelId);
            if (found == g_generalizedGLMControllers.end()) {
                for (const std::string &suffix : {std::string("-pairwise"), std::string("-interaction")}) {
                    if (modelId.size() > suffix.size() &&
                        modelId.compare(modelId.size() - suffix.size(), suffix.size(), suffix) == 0) {
                        modelId.resize(modelId.size() - suffix.size());
                        found = g_generalizedGLMControllers.find(modelId);
                        break;
                    }
                }
            }
            if (found != g_generalizedGLMControllers.end()) controller = found->second;
        }
        if (!controller) return; // Progress is only shown in an existing model window.
        NSString *phase = SafeNSStringFromUTF8(event[3]);
        NSString *status = SafeNSStringFromUTF8(event[4]);
        const NSInteger completed = std::atoi(event[5].c_str());
        const NSInteger total = std::atoi(event[6].c_str());
        const NSInteger running = std::atoi(event[7].c_str());
        const NSInteger workers = std::atoi(event[8].c_str());
        const NSInteger warnings = std::atoi(event[12].c_str());
        const NSInteger failures = std::atoi(event[13].c_str());
        const BOOL terminal = [status isEqualToString:@"completed"] ||
            [status isEqualToString:@"failed"] ||
            [status isEqualToString:@"cancelled"];
        if ([status isEqualToString:@"completed"]) {
            // The result command already refreshed and painted the report.
            // A second full refresh here delays the visible completion state.
            [controller showTaskProgress:SafeNSStringFromUTF8(event[15])
                cancelPath:@"" terminal:YES];
            return;
        }
        NSString *message = SafeNSStringFromUTF8(event[15]);
        if ([phase isEqualToString:@"fitting"] && total > 0 &&
            ![message hasPrefix:@"Could not start"] &&
            ![message hasPrefix:@"Parallel execution unavailable"] &&
            ![message hasPrefix:@"Worker failed"]) {
            message = [NSString stringWithFormat:
                @"Fitting in R: %ld/%ld · %ld active in %ld worker process%@ · %.0f s%@%@",
                (long)completed, (long)total, (long)running, (long)workers,
                workers == 1 ? @"" : @"es", std::atof(event[11].c_str()),
                warnings ? [NSString stringWithFormat:@" · %ld warning%@", (long)warnings,
                    warnings == 1 ? @"" : @"s"] : @"",
                failures ? [NSString stringWithFormat:@" · %ld failure%@", (long)failures,
                    failures == 1 ? @"" : @"s"] : @""];
        } else if ([phase isEqualToString:@"transferring"]) {
            [controller beginApplyingResultsAt:receivedAt];
            return;
        } else if (!message.length) {
            message = [phase stringByReplacingOccurrencesOfString:@"_" withString:@" "];
        }
        [controller showTaskProgress:message
            cancelPath:SafeNSStringFromUTF8(event[14]) terminal:terminal];
    });
    return "OK";
}

static void ShowTextReportOnMain(const std::string &reportId, const std::string &group,
                                 const std::string &title, const std::string &text)
{
    Table1DisplayState state;
    state.id = reportId;
    state.datasetId = group;
    state.title = title;
    state.columns.push_back("Report");
    std::vector<std::string> lines = SplitLines(text);
    for (const std::string &line : lines) {
        Table1DisplayRow row;
        row.rowType = "text";
        row.label = line;
        row.values.push_back("");
        state.rows.push_back(row);
