static void ShowMixedModelTextOnMain(const std::string &modelId, const std::string &group,
                                     const std::string &modelType, const std::string &text)
{
    MixedModelReportState state = ParseMixedModelReport(modelId, group, modelType, text);
    void (^showBlock)(void) = ^{
      MixedModelWindowController *controller = nil;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          auto it = g_mixedModelControllers.find(state.id);
          if (it != g_mixedModelControllers.end()) {
              controller = it->second;
          }
      }
      if (!controller) {
          controller = [[MixedModelWindowController alloc] initWithState:state];
          std::lock_guard<std::mutex> lock(g_mutex);
          g_mixedModelControllers[state.id] = controller;
      } else {
          [controller updateState:state];
      }
      [controller show];
    };
    if ([NSThread isMainThread]) {
        showBlock();
    } else {
        dispatch_sync(dispatch_get_main_queue(), showBlock);
    }
}

static void ShowCompareMeansOnMain(PlotModel *model, const std::string &testType, const std::string &var1,
                                   const std::string &var2, const std::string &groupVar)
{
    model = ActiveDatasetCommandModel(model);
    NSString *title = ToNSString(CompareMeansTitle(testType));
    if (!model) {
        ShowWorkbenchMessageOnMain(title, ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) {
            found = true;
        }
    }
    if (!found) {
        ShowWorkbenchMessageOnMain(title, ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_pendingCompareMeansTasks.push_back({model->group, testType, var1, var2, groupVar});
    }
    NotifyMainRTaskAvailable();
}

static void ShowEditableCompareMeansOnMain(PlotModel *model, const std::string &testType)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(CompareMeansTitle(testType)),
                                   ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel df;
    bool foundDataset = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) { df = *current; foundDataset = true; }
    }
    if (!foundDataset) {
        ShowWorkbenchMessageOnMain(ToNSString(CompareMeansTitle(testType)),
                                   ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }

    MeanComparisonState state;
    state.id = "cm_batch_" + std::to_string((long long)time(nullptr)) + "_" + std::to_string((long long)arc4random_uniform(1000000));
    state.datasetId = df.group; state.title = CompareMeansTitle(testType); state.confidenceLevel = 0.95;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.datasetId, state.dataScope, state.dataScopeCaptured);
    }
    state.alternative = "two.sided"; state.specification.confidenceLevel = 0.95;
    state.specification.pAdjustment = rlispstat::core::MultipleTestingAdjustment::Holm;
    const auto sharedKind = testType == "one_sample_t"
        ? rlispstat::core::SharedAnalysisKind::OneSampleComparison
        : testType == "paired_t"
            ? rlispstat::core::SharedAnalysisKind::PairedSamplesComparison
            : testType == "independent_t"
                ? rlispstat::core::SharedAnalysisKind::IndependentSamplesComparison
                : rlispstat::core::SharedAnalysisKind::OneWayComparison;
    const auto initial = ResolveInitialAnalysisForGroup(df, sharedKind);
    const auto initialResponses =
        rlispstat::core::InitialAnalysisVariables(initial, "responses");
    const auto initialFirst =
        rlispstat::core::InitialAnalysisVariable(initial, "first");
    const auto initialSecond =
        rlispstat::core::InitialAnalysisVariable(initial, "second");
    const auto initialGroup =
        rlispstat::core::InitialAnalysisVariable(initial, "group");
    if (testType == "one_sample_t") {
        state.analysisType = "one_sample_t_test"; state.specification.kind = rlispstat::core::MeanComparisonKind::OneSample;
        state.specification.method = rlispstat::core::MeanComparisonMethod::OneSampleT;
        state.specification.dependentVariableIds = initialResponses;
        state.subtitle = initialResponses.empty()
            ? "Choose a dependent variable."
            : "Test value: 0 · Alternative: two-sided · Confidence level: 95%";
    } else if (testType == "paired_t") {
        state.analysisType = "paired_samples_t_test"; state.specification.kind = rlispstat::core::MeanComparisonKind::PairedSamples;
        state.specification.method = rlispstat::core::MeanComparisonMethod::OneSampleT;
        if (!initialFirst.empty() && !initialSecond.empty() &&
            MeanComparisonPairedVariablesCompatible(df, initialFirst, initialSecond))
            state.specification.pairs.push_back({
                "pair:" + initialFirst + "\x1f" + initialSecond,
                initialFirst, initialSecond});
        state.subtitle = state.specification.pairs.empty()
            ? "Choose two compatible paired variables."
            : "Automatic by pair type · Differences: first variable − second variable · Confidence level: 95%";
    } else {
        const bool independent = testType == "independent_t";
        state.analysisType = independent ? "independent_samples_t_test" : "one_way_anova";
        state.specification.kind = independent ? rlispstat::core::MeanComparisonKind::IndependentSamples : rlispstat::core::MeanComparisonKind::OneWayAnova;
        state.specification.method = independent ? rlispstat::core::MeanComparisonMethod::WelchT : rlispstat::core::MeanComparisonMethod::WelchAnova;
        state.specification.dependentVariableIds = initialResponses;
        if (!initialGroup.empty()) {
            const DataColumn *column = FindDataColumnInDataFrame(df, initialGroup);
            if (column && MeanComparisonGroupingCandidate(*column, independent)) {
                state.specification.groupingVariableId = initialGroup;
                state.groupVariable = initialGroup;
                const std::vector<std::string> levels = MeanComparisonEffectiveLevels(*column);
                state.specification.groupOrderIds = independent
                    ? rlispstat::core::MeanComparisonDefaultIndependentGroupOrder(levels)
                    : levels;
            }
        }
        state.method = independent ? "Welch" : "Welch one-way ANOVA";
        if (initialResponses.empty()) {
            state.subtitle = "Choose a dependent variable.";
        } else if (state.groupVariable.empty()) {
            state.subtitle = "Choose a grouping variable from the context menu.";
        } else {
            state.subtitle = "Grouping variable: " + state.groupVariable + " · " + state.method;
        }
    }
    ShowMeanComparisonStateOnMain(state);
    const bool ready = (state.analysisType == "paired_samples_t_test" ? !state.specification.pairs.empty() : !state.specification.dependentVariableIds.empty()) &&
        ((state.analysisType != "independent_samples_t_test" && state.analysisType != "one_way_anova") || state.specification.groupingVariableId.has_value());
    if (ready) {
        MainRCompareMeansTask task = MeanComparisonTaskForState(state, df);
        {
            std::lock_guard<std::mutex> lock(g_mutex); g_pendingCompareMeansTasks.push_back(std::move(task));
        }
        NotifyMainRTaskAvailable();
    }
}

static void ShowNewTable1OnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1WindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1WindowTitle()), ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }
    const auto initial = ResolveInitialAnalysisForGroup(
        df, rlispstat::core::SharedAnalysisKind::DescriptiveTable);
    const auto initialVariables =
        rlispstat::core::InitialAnalysisVariables(initial, "variables");
