static void ShowContingencyTableResultOnMain(const DataFrameModel &df,
                                             const std::vector<std::string> &rowVariables,
                                             const std::string &columnVariable,
                                             const std::string &sourcePlotId)
{
    if (rowVariables.empty() || columnVariable.empty()) return;
    std::string id = "contingency_" + df.group + "_" + std::to_string((long long)time(nullptr));
    rlispstat::core::AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(df.group, dataScope, dataScopeCaptured);
    }
    if (df.datasetType == "multiple_imputation") {
        const std::string scope = ScopeForCapturedAnalysisScope(dataScope, dataScopeCaptured, "all");
        const std::string specification = std::to_string(df.provenance.currentVersion.version) +
            "|" + OriginalRowsAnalysisModelSpec(dataScope, dataScopeCaptured);
        std::thread worker([df, id, rowVariables, columnVariable, scope, specification]() {
            std::string message;
            if (!RunRBackedMultipleImputationAnalysis(df, "contingency", id,
                    rowVariables, columnVariable, "", {}, scope, &message, specification))
                ShowWorkbenchMessageOnMain(@"Contingency Table", ToNSString(message));
        });
        worker.detach();
        return;
    }
    Table1DisplayState state = rlispstat::core::NestedContingencyTableStateForDataFrame(
        df, id, rowVariables, columnVariable, "count_percent",
        dataScopeCaptured ? &dataScope : nullptr);
    state.datasetId = df.group;
    state.linkEnabled = true;
    state.sourcePlotId = sourcePlotId;
    std::string rowLabel;
    for (const std::string &variable : rowVariables) {
        if (!rowLabel.empty()) rowLabel += " \u00d7 ";
        rowLabel += variable;
    }
    state.title = "Contingency Table \u2014 " + rowLabel + " by " + columnVariable;
    const std::string tableId = state.id;
    ShowTable1StateOnMain(state);
    if (!sourcePlotId.empty()) {
        dispatch_async(dispatch_get_main_queue(), ^{
            std::lock_guard<std::mutex> lock(g_mutex);
            g_linkedTables[sourcePlotId].insert(tableId);
            g_linkedTableSources[tableId] = sourcePlotId;
        });
    }
}

