@implementation ContingencyTableSetupWindowController
- (instancetype)initWithId:(const std::string &)controllerId
                  dataframe:(const DataFrameModel &)dataframe
                    initial:(const rlispstat::core::InitialAnalysisSpecification &)initial
               sourcePlotId:(const std::string &)sourcePlotId
{
    self = [super init];
    if (!self) return nil;
    _controllerId = controllerId;
    _dataframe = dataframe;
    _sourcePlotId = sourcePlotId;
    _window = [[NSWindow alloc]
        initWithContentRect:NextWindowFrameOnMain(520, 250)
                  styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                             NSWindowStyleMaskMiniaturizable)
                    backing:NSBackingStoreBuffered defer:NO];
    [_window setTitle:@"Contingency Table"];
    [_window setDelegate:self];
    ConfigureResultWindowTabbing(_window);

    NSView *content = [_window contentView];
    [content addSubview:GLMLabel(@"Contingency Table", NSMakeRect(20, 198, 300, 28),
                                 18, NSFontWeightSemibold)];
    [content addSubview:GLMLabel(@"Row variable:", NSMakeRect(20, 145, 120, 24),
                                 12, NSFontWeightRegular)];
    [content addSubview:GLMLabel(@"Column variable:", NSMakeRect(20, 105, 120, 24),
                                 12, NSFontWeightRegular)];
    _rowPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(148, 141, 330, 30)];
    _columnPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(148, 101, 330, 30)];
    [_rowPopup addItemWithTitle:@"(not assigned)"];
    [_columnPopup addItemWithTitle:@"(not assigned)"];
    const auto definition = rlispstat::core::SharedAnalysisDefinition(
        rlispstat::core::SharedAnalysisKind::ContingencyTable);
    for (const DataColumn &column : _dataframe.columns) {
        if (rlispstat::core::AnalysisVariableIsCompatible(
                column, definition.slots.front().acceptedType)) {
            [_rowPopup addItemWithTitle:ToNSString(column.name)];
            [_columnPopup addItemWithTitle:ToNSString(column.name)];
        }
    }
    const std::string row = rlispstat::core::InitialAnalysisVariable(initial, "row");
    const std::string column = rlispstat::core::InitialAnalysisVariable(initial, "column");
    if (!row.empty()) [_rowPopup selectItemWithTitle:ToNSString(row)];
    if (!column.empty()) [_columnPopup selectItemWithTitle:ToNSString(column)];
    [_rowPopup setTarget:self]; [_rowPopup setAction:@selector(selectionChanged:)];
    [_columnPopup setTarget:self]; [_columnPopup setAction:@selector(selectionChanged:)];
    [content addSubview:_rowPopup]; [content addSubview:_columnPopup];

    _statusLabel = GLMLabel(@"", NSMakeRect(20, 63, 458, 24), 11, NSFontWeightRegular);
    [[_statusLabel cell] setWraps:NO];
    [content addSubview:_statusLabel];
    _runButton = [[NSButton alloc] initWithFrame:NSMakeRect(374, 18, 104, 32)];
    [_runButton setTitle:@"Run"];
    [_runButton setBezelStyle:NSBezelStyleRounded];
    [_runButton setTarget:self]; [_runButton setAction:@selector(runAnalysis:)];
    [content addSubview:_runButton];
    NSButton *cancel = [[NSButton alloc] initWithFrame:NSMakeRect(260, 18, 104, 32)];
    [cancel setTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    [cancel setBezelStyle:NSBezelStyleRounded];
    [cancel setTarget:self]; [cancel setAction:@selector(cancel:)];
    [content addSubview:cancel];
    [self selectionChanged:nil];
    return self;
}

- (void)selectionChanged:(id)sender
{
    NSString *rowSelection = [_rowPopup titleOfSelectedItem];
    NSString *columnSelection = [_columnPopup titleOfSelectedItem];
    if ([_rowPopup indexOfSelectedItem] > 0 &&
        [rowSelection isEqualToString:columnSelection]) {
        if (sender == _columnPopup && _previousColumn &&
            ![_previousColumn isEqualToString:rowSelection]) {
            [_rowPopup selectItemWithTitle:_previousColumn];
        } else if (sender == _rowPopup && _previousRow &&
                   ![_previousRow isEqualToString:columnSelection]) {
            [_columnPopup selectItemWithTitle:_previousRow];
        }
    }
    _previousRow = [_rowPopup titleOfSelectedItem];
    _previousColumn = [_columnPopup titleOfSelectedItem];
    const bool hasRow = [_rowPopup indexOfSelectedItem] > 0;
    const bool hasColumn = [_columnPopup indexOfSelectedItem] > 0;
    bool distinct = false;
    if (hasRow && hasColumn)
        distinct = ![[_rowPopup titleOfSelectedItem]
            isEqualToString:[_columnPopup titleOfSelectedItem]];
    [_runButton setEnabled:hasRow && hasColumn && distinct];
    if ([_rowPopup numberOfItems] <= 1)
        [_statusLabel setStringValue:@"No categorical variables. Set their type in Variable View."];
    else if (!hasRow && !hasColumn)
        [_statusLabel setStringValue:@"Choose row and column variables."];
    else if (!hasRow)
        [_statusLabel setStringValue:@"Choose a row variable."];
    else if (!hasColumn)
        [_statusLabel setStringValue:@"Choose a column variable."];
    else if (!distinct)
        [_statusLabel setStringValue:@"Row and column variables must be different."];
    else
        [_statusLabel setStringValue:@"Ready to compute the contingency table."];
}

- (void)runAnalysis:(id)sender
{
    (void)sender;
    if (![_runButton isEnabled]) return;
    const std::string row([[_rowPopup titleOfSelectedItem] UTF8String]);
    const std::string column([[_columnPopup titleOfSelectedItem] UTF8String]);
    ShowContingencyTableResultOnMain(_dataframe, {row}, column, _sourcePlotId);
    [_window close];
}

- (void)cancel:(id)sender { (void)sender; [_window close]; }
- (void)show {
    AssociateWindowWithDataset(_window, _dataframe.group);
    [_window makeKeyAndOrderFront:nil];
}
- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    std::lock_guard<std::mutex> lock(g_mutex);
    g_contingencySetupControllers.erase(_controllerId);
}
@end

static void ShowContingencyTableDialogOnMain(PlotModel *model,
                                             const std::string &preferredRow,
                                             const std::string &preferredColumn)
{
    model = ActiveDatasetCommandModel(model);
    DataFrameModel df;
    if (!DataFrameForContextModel(model, df)) {
        ShowWorkbenchMessageOnMain(@"Contingency Table", ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }
    rlispstat::core::AnalysisSpecification existing;
    const rlispstat::core::AnalysisSpecification *existingPointer = nullptr;
    if (!preferredRow.empty() || !preferredColumn.empty()) {
        existing["row"] = preferredRow.empty()
            ? std::vector<std::string>{} : std::vector<std::string>{preferredRow};
        existing["column"] = preferredColumn.empty()
            ? std::vector<std::string>{} : std::vector<std::string>{preferredColumn};
        existingPointer = &existing;
    }
    const auto initial = ResolveInitialAnalysisForGroup(
        df, rlispstat::core::SharedAnalysisKind::ContingencyTable, existingPointer);
    const std::string controllerId = "contingency_setup_" + df.group + "_" +
        std::to_string((long long)time(nullptr)) + "_" +
        std::to_string((long long)arc4random_uniform(1000000));
    const std::string sourcePlotId = model && !model->isDatasetSeed ? model->id : "";
    ContingencyTableSetupWindowController *controller =
        [[ContingencyTableSetupWindowController alloc]
            initWithId:controllerId dataframe:df initial:initial sourcePlotId:sourcePlotId];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_contingencySetupControllers[controllerId] = controller;
    }
    [controller show];
}

static void ShowNestedContingencyTableOnMain(PlotModel *model)
{
    DataFrameModel df;
    if (!DataFrameForContextModel(model, df)) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::FrequencyTableWindowTitle()), ToNSString(rlispstat::core::DatasetForPlotNotAvailableStatus()));
        return;
    }
    std::vector<std::string> xvars = BarplotXVariablesForModel(model);
    std::string splitVar = model->barplotSplitVariable;
    if (splitVar.empty() && xvars.size() > 1) {
        splitVar = xvars[1];
        xvars.erase(xvars.begin() + 1);
    }
    if (xvars.empty()) return;
    if (splitVar.empty()) {
        ShowContingencyTableDialogOnMain(model, xvars.front(), "");
        return;
    }
    ShowContingencyTableResultOnMain(df, xvars, splitVar, model ? model->id : "");
}

static void RebuildLinkedNestedTable(const std::string &tableId)
{
    std::string plotId;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTableSources.find(tableId);
        if (it == g_linkedTableSources.end()) return;
        plotId = it->second;
    }
    PlotModel *model = nullptr;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        BarplotView *view = BarplotViewForPlotUnlocked(plotId);
        if (view) model = view.model;
    }
    if (!model || model->kind != "barplot") return;
    Table1WindowController *controller = nil;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto cit = g_table1Controllers.find(tableId);
        if (cit != g_table1Controllers.end()) controller = cit->second;
    }
    if (!controller) return;
    dispatch_async(dispatch_get_main_queue(), ^{
        DataFrameModel df;
        if (!DataFrameForContextModel(model, df)) return;
        std::vector<std::string> xvars = BarplotXVariablesForModel(model);
        std::string splitVar = model->barplotSplitVariable;
        if (splitVar.empty() && xvars.size() > 1) {
            splitVar = xvars[1];
            xvars.erase(xvars.begin() + 1);
        }
        if (xvars.empty()) return;
        std::string displayMode = [controller state]->nestedDisplayMode;
        Table1DisplayState *oldState = [controller state];
        Table1DisplayState newState = rlispstat::core::NestedContingencyTableStateForDataFrame(
            df, tableId, xvars, splitVar, displayMode,
            oldState->dataScopeCaptured ? &oldState->dataScope : nullptr);
        newState.datasetId = df.group;
        newState.linkEnabled = true;
        newState.sourcePlotId = plotId;
        [controller updateState:newState];
    });
}

static void NotifyBarplotLinkedTablesChanged(const std::string &plotId)
{
    std::set<std::string> tableIds;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_linkedTables.find(plotId);
        if (it != g_linkedTables.end()) {
            tableIds = it->second;
        }
    }
    for (const std::string &tid : tableIds) {
        RebuildLinkedNestedTable(tid);
    }
}

static void OpenTable1HistogramOnMain(const std::string &group, const std::string &variable,
                                      const AnalysisScope *scope)
{
    DataFrameModel df;
    PlotModel seed;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    BuildSeedPlotForGroup(group, seed);
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::DatasetNotAvailableStatus()));
        return;
    }
    const DataColumn *col = Table1FindColumn(df, variable);
    if (!col) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::SelectedVariableNotAvailableStatus()));
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "histogram";
    created->id = "hist_" + group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    created->group = group;
    created->xLabel = variable;
    created->title = "Histogram of " + variable;
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    for (size_t i = 0; i < col->values.size(); ++i) {
        double x = NAN;
        if (ParseDataCellDouble(col->values[i], x)) {
            created->histogramPoints.push_back(HistogramPoint{x, (int)i + 1, 0});
        }
    }
    if (created->histogramPoints.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::Table1HistogramRequiresNumericStatus()));
        return;
    }
    RebinHistogramByRule(created, "sturges");
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (scope) rlispstat::core::ApplyAnalysisScopeToPlot(
            *created, *scope, static_cast<std::size_t>(std::max(0, df.rows)));
        if (!AttachPlotModelUnlocked(created)) { delete created; return; }
    }
    AddPlotOnMain(created);
}

static void OpenTable1BarplotOnMain(const std::string &group, const std::string &variable,
                                    const std::string &splitVariable,
                                    const AnalysisScope *scope)
{
    DataFrameModel df;
    PlotModel seed;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    BuildSeedPlotForGroup(group, seed);
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::DatasetNotAvailableStatus()));
        return;
    }
    const DataColumn *col = Table1FindColumn(df, variable);
    const DataColumn *splitCol = splitVariable.empty() || splitVariable == variable ? nullptr : Table1FindColumn(df, splitVariable);
    if (!col) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::SelectedVariableNotAvailableStatus()));
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "barplot";
    created->id = "barplot_" + group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    created->group = group;
    created->xLabel = variable;
    created->yLabel = "";
    created->title = splitCol ? ("Bar chart of " + variable + " by " + splitVariable) : ("Bar chart of " + variable);
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    created->barplotXVariables = std::vector<std::string>{variable};
    created->barplotRowColorDisplay = "hide";
    if (splitCol) {
        created->barplotSplitVariable = splitVariable;
        created->barplotShowConditionalPercent = true;
    }

    rlispstat::core::RebuildBarplotBinsForColumns(*created, std::vector<const DataColumn *>{col}, splitCol);
    NormalizeBarplotVisualState(created);
    if (created->barplotBins.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::Table1BarplotRequiresValueStatus()));
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (scope) rlispstat::core::ApplyAnalysisScopeToPlot(
            *created, *scope, static_cast<std::size_t>(std::max(0, df.rows)));
        if (!AttachPlotModelUnlocked(created)) { delete created; return; }
    }
    AddPlotOnMain(created);
}

static void OpenTable1BoxplotOnMain(const std::string &group, const std::string &variable,
                                    const std::string &groupVariable,
                                    const AnalysisScope *scope)
{
    DataFrameModel df;
    PlotModel seed;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    BuildSeedPlotForGroup(group, seed);
    if (!found) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::DatasetNotAvailableStatus()));
        return;
    }
    const DataColumn *yCol = Table1FindColumn(df, variable);
    const DataColumn *xCol = groupVariable.empty() ? nullptr : Table1FindColumn(df, groupVariable);
    if (!yCol) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::SelectedVariableNotAvailableStatus()));
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "boxplot";
    created->id = "boxplot_" + group + "_" + variable + "_" + std::to_string((long long)time(nullptr));
    created->group = group;
    created->xLabel = groupVariable;
    created->yLabel = variable;
    created->title = groupVariable.empty() ? ("Boxplot of " + variable) : (variable + " by " + groupVariable);
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    if (groupVariable.empty()) {
        created->boxplotVariables.push_back(variable);
    }
    for (size_t i = 0; i < yCol->values.size(); ++i) {
        double y = NAN;
        if (!ParseDataCellDouble(yCol->values[i], y)) continue;
        std::string category = xCol ? DisplayValueForCell(*xCol, i) : variable;
        if (DataCellIsMissing(category)) category = "NA";
        created->boxplotPoints.push_back(BoxplotPoint{y, category, (int)i + 1});
    }
    if (created->boxplotPoints.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::Table1PlotWindowTitle()), ToNSString(rlispstat::core::Table1BoxplotRequiresNumericStatus()));
        return;
    }
    EnsureParallelBoxplotState(created);
    if (created->boxplotCategories.empty()) {
        created->boxplotCategories = CategoriesForPlot(*created);
    }
    created->boxplotDefinedCategories = created->boxplotCategories;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (scope) rlispstat::core::ApplyAnalysisScopeToPlot(
            *created, *scope, static_cast<std::size_t>(std::max(0, df.rows)));
        if (!AttachPlotModelUnlocked(created)) { delete created; return; }
    }
    AddPlotOnMain(created);
}

static void OpenMeanComparisonPairedScatterplotOnMain(const std::string &group,
                                                      const std::string &firstVariable,
                                                      const std::string &secondVariable,
                                                      const AnalysisScope *scope)
{
    PlotModel seed;
    if (!BuildSeedPlotForGroup(group, seed) ||
        !rlispstat::core::FindNumericVariable(seed, firstVariable) ||
        !rlispstat::core::FindNumericVariable(seed, secondVariable)) {
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables are no longer available.");
        return;
    }
    PlotModel *created = new PlotModel(seed);
    created->kind = "scatter";
    created->isDatasetSeed = false;
    created->isGLMDiagnostic = false;
    created->id = "paired_scatter_" + group + "_" +
        std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
    created->xLabel = firstVariable;
    created->yLabel = secondVariable;
    created->title = ScatterplotDefaultTitle(firstVariable, secondVariable);
    created->overlays.clear();
    created->nextOverlayId = 1;
    created->interactionMode = "select";
    created->selectionMode = "replace";
    RebuildPointsForCurrentVariables(created);
    ComputeRanges(created);
    if (created->points.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables contain no complete numeric observations.");
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (scope) rlispstat::core::ApplyAnalysisScopeToPlot(
            *created, *scope, scope->totalDatasetRows);
        if (!AttachPlotModelUnlocked(created)) { delete created; return; }
        EnsureGroupModelUnlocked(created->group, created);
    }
    AddPlotOnMain(created);
}

static void OpenMeanComparisonDifferenceHistogramOnMain(const std::string &group,
                                                        const std::string &firstVariable,
                                                        const std::string &secondVariable,
                                                        const AnalysisScope *scope)
{
    DataFrameModel dataframe;
    PlotModel seed;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(group);
        if (found) dataframe = *found;
    }
    BuildSeedPlotForGroup(group, seed);
    const DataColumn *first = FindDataColumnInDataFrame(dataframe, firstVariable);
    const DataColumn *second = FindDataColumnInDataFrame(dataframe, secondVariable);
    if (!first || !second) {
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables are no longer available.");
        return;
    }
    PlotModel *created = new PlotModel();
    created->kind = "histogram";
    created->id = "paired_difference_hist_" + group + "_" +
        std::to_string((long long)time(nullptr)) + "_" + std::to_string(std::rand() % 1000000);
    created->group = group;
    created->xLabel = firstVariable + " \u2212 " + secondVariable;
    created->title = "Histogram of paired differences: " + created->xLabel;
    created->variables = seed.variables;
    created->variableMeta = seed.variableMeta;
    const std::size_t rowCount = std::min(first->values.size(), second->values.size());
    for (std::size_t row = 0; row < rowCount; ++row) {
        double firstValue = NAN;
        double secondValue = NAN;
        if (!ParseDataCellDouble(first->values[row], firstValue) ||
            !ParseDataCellDouble(second->values[row], secondValue)) continue;
        created->histogramPoints.push_back(HistogramPoint{
            firstValue - secondValue,
            static_cast<int>(row) + 1,
            0
        });
    }
    if (created->histogramPoints.empty()) {
        delete created;
        ShowWorkbenchMessageOnMain(@"Compare Means", @"The paired variables contain no complete numeric observations.");
        return;
    }
    RebinHistogramByRule(created, "sturges");
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (scope) rlispstat::core::ApplyAnalysisScopeToPlot(
            *created, *scope,
            static_cast<std::size_t>(std::max(0, dataframe.rows)));
        if (!AttachPlotModelUnlocked(created)) { delete created; return; }
    }
    AddPlotOnMain(created);
}

static void AppendGLMRun(NSMutableAttributedString *text, NSString *s, NSFontWeight weight)
{
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setLineSpacing:4.0];
    NSDictionary *attrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:weight],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0],
        NSParagraphStyleAttributeName: style
    };
    [text appendAttributedString:[[NSAttributedString alloc] initWithString:s attributes:attrs]];
}

static NSAttributedString *GLMFitAttributedSummary(const GLMFitSummary &fit)
{
    NSMutableAttributedString *out = [[NSMutableAttributedString alloc] init];
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitGlobalFitSectionTitle()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitRSquaredLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + FormatPercent(fit.r2, 1) + "     "), NSFontWeightRegular);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitAdjustedRSquaredLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + FormatPercent(fit.adjR2, 1) + "     "), NSFontWeightRegular);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitSValueLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + FormatDouble(fit.sigma, 3) + "     "), NSFontWeightRegular);
    AppendGLMRun(out, ToNSString(rlispstat::core::GLMFitDFLabel()), NSFontWeightSemibold);
    AppendGLMRun(out, ToNSString(" = " + std::to_string(fit.dfResidual)), NSFontWeightRegular);
    return out;
}

static void AppendRegressionDetailField(NSMutableAttributedString *text, NSString *label, NSString *value, BOOL separator)
{
    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]
    };
    NSDictionary *valueAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightRegular],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.15 alpha:1.0]
    };
    [text appendAttributedString:[[NSAttributedString alloc] initWithString:label attributes:labelAttrs]];
    [text appendAttributedString:[[NSAttributedString alloc] initWithString:value attributes:valueAttrs]];
    if (separator) {
        [text appendAttributedString:[[NSAttributedString alloc] initWithString:@"; " attributes:valueAttrs]];
    }
}

static NSString *RegressionDetailValue(double value, int digits)
{
    return ToNSString(FormatDoubleOrDash(value, digits));
}

static NSString *RegressionDetailPercent(double value)
{
    return ToNSString(FormatPercentOrDash(value, 1));
}

static NSString *RegressionDetailP(double p)
{
    std::string formatted = FormatPValue(p);
    if (formatted == "\u2014") return @" = \u2014";
    if (formatted.rfind("<", 0) == 0) return ToNSString(" " + formatted);
    return ToNSString(" = " + formatted);
}

static NSBox *GLMBox(NSRect frame)
{
    NSBox *box = [[NSBox alloc] initWithFrame:frame];
    [box setBoxType:NSBoxCustom];
    [box setBorderColor:[NSColor colorWithCalibratedWhite:0.84 alpha:1.0]];
    [box setFillColor:[NSColor colorWithCalibratedWhite:0.99 alpha:1.0]];
    [box setCornerRadius:8.0];
    return box;
}

struct GeneralizedComparisonLayout {
    CGFloat margin = 14.0;
    CGFloat termWidth = 340.0;
    CGFloat modelWidth = 140.0;
    CGFloat addModelWidth = 106.0;
    CGFloat headerHeight = 56.0;
    CGFloat rowHeight = 24.0;
    CGFloat gapAfterTerms = 10.0;
    CGFloat noteHeight = 28.0;
    int fitRows = 14;

    GeneralizedComparisonLayout(bool showInformationCriteria = false,
                                bool binaryComparison = false)
        : fitRows((int)rlispstat::core::GeneralizedComparisonVisibleFitRows(
              binaryComparison, showInformationCriteria).size()) {}

    CGFloat width(int modelCount) const
    {
        return margin * 2.0 + termWidth + modelWidth * (CGFloat)modelCount + addModelWidth;
    }

    CGFloat height(int termCount) const
    {
        return margin * 2.0 + headerHeight + rowHeight * ((CGFloat)termCount + 1.0) +
               gapAfterTerms + rowHeight * (CGFloat)fitRows + noteHeight;
    }

    NSRect termRect(int row) const
    {
        return NSMakeRect(margin, margin + headerHeight + rowHeight * (CGFloat)row, termWidth, rowHeight);
    }

    NSRect modelHeaderRect(int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex, margin, modelWidth, headerHeight);
    }

    NSRect addModelRect(int modelCount) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelCount, margin, addModelWidth, headerHeight);
    }

    NSRect coefficientRect(int row, int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex,
                          margin + headerHeight + rowHeight * (CGFloat)row,
                          modelWidth, rowHeight);
    }

    CGFloat fitStartY(int termCount) const
    {
        return margin + headerHeight + rowHeight * ((CGFloat)termCount + 1.0) + gapAfterTerms;
    }

    NSRect fitLabelRect(int fitRow, int termCount) const
    {
        return NSMakeRect(margin, fitStartY(termCount) + rowHeight * (CGFloat)fitRow, termWidth, rowHeight);
    }

    NSRect fitValueRect(int fitRow, int termCount, int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex,
                          fitStartY(termCount) + rowHeight * (CGFloat)fitRow,
                          modelWidth, rowHeight);
    }
};

// Inclusion is an explicit control within a comparison cell. Keep its
// geometry identical for both states so that `+` and `−` never inherit the
// hit area of the coefficient value (or of the whole cell).
static NSRect ComparisonTermInclusionControlRect(NSRect cellRect)
{
    return NSMakeRect(NSMinX(cellRect) + 4.0,
                      NSMinY(cellRect) + 3.0,
                      22.0,
                      NSHeight(cellRect) - 6.0);
}

static NSRect ComparisonTermValueRect(NSRect cellRect, bool hasInclusionControl)
{
    NSRect valueRect = NSInsetRect(cellRect, 4.0, 4.0);
    if (hasInclusionControl) {
        valueRect.origin.x += 24.0;
        valueRect.size.width = std::max((CGFloat)0.0, valueRect.size.width - 24.0);
    }
    return valueRect;
}

