- (GeneralizedComparisonState *)state
{
    auto it = g_generalizedComparisons.find(_comparisonId);
    return it == g_generalizedComparisons.end() ? nullptr : &it->second;
}

- (void)show
{
    // Existing comparison controllers are reused when Main R publishes an
    // asynchronous fit.  Refresh from the canonical state before presenting
    // the window; otherwise the state accepts the result while the visible
    // table and status remain frozen at "Fitting...".
    [self refresh];
    [self activateDatasetForCommands];
    GeneralizedComparisonState *state = [self state];
    EnableNotesForWindow(_window, _comparisonId, @"this model comparison",
                         state ? state->group : std::string{});
    [_window makeKeyAndOrderFront:nil];
    [_window orderFrontRegardless];
    [NSApp activateIgnoringOtherApps:YES];
}

- (void)activateDatasetForCommands
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(state->group);
        EnsureDatasetSeedPlotUnlocked(state->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

- (void)windowDidBecomeKey:(NSNotification *)notification
{
    (void)notification;
    [self activateDatasetForCommands];
}

- (BOOL)isVisible
{
    return [_window isVisible];
}

- (int)selectedTermRow { return _selectedTermRow; }
- (int)selectedModelColumn { return _selectedModelColumn; }

- (void)refresh
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    const bool ordinaryGeneralized = !state->binaryComparison && !state->countComparison;
    NSString *windowTitle = ToNSString(
        rlispstat::core::StatisticalModelComparisonTitle(
            state->modelType, state->multipleImputation));
    [_window setTitle:windowTitle];
    [_titleField setStringValue:windowTitle];
    if (state->autoRefit) {
        RefitGeneralizedComparisonModels(*state, false);
    }
    RefreshGeneralizedTermRowsFromFits(*state);
    [_badgeField setStringValue:ToNSString(state->multipleImputation
        ? state->group + " · m = " + std::to_string(std::max(1, state->imputationCount))
        : state->group)];
    [_responsePopup removeAllItems];
    for (const std::string &name : VariableNamesForModel(&state->seed)) {
        const DataColumn *column = FindDataColumnForModel(&state->seed, name);
        if (!column) continue;
        bool compatible = false;
        if (state->binaryComparison) {
            compatible = rlispstat::core::InspectBinaryResponse(*column).ok;
        } else if (state->countComparison) {
            compatible = rlispstat::core::InspectCountResponse(*column).ok;
        } else if (state->modelType ==
                   rlispstat::core::StatisticalModelType::PositiveContinuous) {
            const auto *distribution =
                rlispstat::core::FindDistributionSpecification(state->family);
            compatible = distribution && rlispstat::core::InspectResponseDomain(
                *column, distribution->responseDomain).ok;
        } else if (state->modelType ==
                   rlispstat::core::StatisticalModelType::Proportion) {
            const auto *distribution =
                rlispstat::core::FindDistributionSpecification(state->family);
            compatible = distribution && rlispstat::core::InspectResponseDomain(
                *column, distribution->responseDomain).ok;
        } else {
            compatible = column->type == "numeric" || column->type == "ordinal";
        }
        if (compatible) [_responsePopup addItemWithTitle:ToNSString(name)];
    }
    [_responsePopup selectItemWithTitle:ToNSString(state->response)];
    if (state->binaryComparison) {
        [_eventLabel setStringValue:@"Event category:"];
        [_eventPopup setTarget:self];
        [_eventPopup setAction:@selector(binaryEventChanged:)];
        [_eventPopup removeAllItems];
        if (state->responseCoding.ok) {
            [_eventPopup addItemWithTitle:ToNSString(state->responseCoding.referenceLabel)];
            [_eventPopup addItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
            [_eventPopup selectItemWithTitle:ToNSString(state->responseCoding.eventLabel)];
        }
        [_referenceField setStringValue:ToNSString("Reference category: " + (state->responseCoding.ok ? state->responseCoding.referenceLabel : std::string("—")))];
        [_linkPopup removeAllItems];
        [_linkPopup setTarget:self];
        [_linkPopup setAction:@selector(binaryLinkChanged:)];
        for (rlispstat::core::BinaryLink link : rlispstat::core::SupportedBinaryLinks()) {
            [_linkPopup addItemWithTitle:ToNSString(rlispstat::core::BinaryLinkLabel(link))];
        }
        [_linkPopup selectItemWithTitle:ToNSString(rlispstat::core::BinaryLinkLabel(state->binaryLink))];
        [_eventLabel setHidden:NO]; [_eventPopup setHidden:NO]; [_referenceField setHidden:NO];
        [_linkLabel setHidden:NO]; [_linkPopup setHidden:NO];
    } else if (ordinaryGeneralized) {
        [_eventLabel setStringValue:@"Distribution:"];
        [_eventPopup setTarget:self];
        [_eventPopup setAction:@selector(generalizedFamilyChanged:)];
        [_eventPopup removeAllItems];
        for (const auto &distribution :
             rlispstat::core::DistributionSpecificationsForModel(state->modelType)) {
            [_eventPopup addItemWithTitle:ToNSString(distribution.visibleName)];
            [[_eventPopup lastItem] setRepresentedObject:ToNSString(distribution.id)];
        }
        for (NSMenuItem *item in [_eventPopup itemArray]) {
            if ([[item representedObject] isEqualToString:ToNSString(state->family)]) {
                [_eventPopup selectItem:item];
                break;
            }
        }
        [_linkPopup setTarget:self];
        [_linkPopup setAction:@selector(generalizedLinkChanged:)];
        [_linkPopup removeAllItems];
        for (const std::string &link : rlispstat::core::LinksForModelDistribution(
                 state->modelType, state->family)) {
            [_linkPopup addItemWithTitle:ToNSString(link)];
        }
        [_linkPopup selectItemWithTitle:ToNSString(state->link)];
        [_eventLabel setHidden:NO]; [_eventPopup setHidden:NO]; [_referenceField setHidden:YES];
        [_linkLabel setHidden:NO]; [_linkPopup setHidden:NO];
    } else {
        [_eventLabel setHidden:YES]; [_eventPopup setHidden:YES]; [_referenceField setHidden:YES];
        [_linkLabel setHidden:YES]; [_linkPopup setHidden:YES];
    }
    [_scopeStaticLabel setStringValue:ToNSString(rlispstat::core::GLMScopeFieldLabel())];
	    PopulateAnalysisScopePopup(_scopePopup, state->group, state->scope,
	                               state->dataScope, state->dataScopeCaptured, true);
    [_autoRefitButton setHidden:NO];
    [_autoRefitButton setState:state->autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
    [_responsePopup setEnabled:YES];
	    [_scopePopup setEnabled:YES];
    [_eventPopup setEnabled:ordinaryGeneralized ||
        (state->binaryComparison && state->responseCoding.ok)];
    [_linkPopup setEnabled:ordinaryGeneralized || state->binaryComparison];
    [_autoRefitButton setEnabled:YES];
    size_t selected = SelectionCount(state->group);
    size_t n = state->seed.variables.empty() ? 0 : state->seed.variables.front().values.size();
    [_selectedRowsField setStringValue:ToNSString(rlispstat::core::SelectedRowsStatus(selected, n))];

    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    NSSize wanted = NSMakeSize(layout.width((int)state->models.size()), layout.height((int)state->termRows.size()));
    const bool twoRowControls = state->binaryComparison || ordinaryGeneralized;
    NSSize contentSize = FitResultTableWindowToContent(
        _window,
        NSMakeSize(std::max((CGFloat)790.0, wanted.width + 24.0),
                   std::max((CGFloat)540.0,
                            wanted.height + (twoRowControls ? 180.0 : 150.0))),
        NSMakeSize(700.0, 430.0));
    CGFloat h = contentSize.height;
    CGFloat w = contentSize.width;
    [_titleField setFrame:NSMakeRect(14, h - 48, 320, 24)];
    [_badgeField setFrame:NSMakeRect(w - 150, h - 46, 130, 20)];
    [_responseStaticLabel setFrame:NSMakeRect(14, h - 82, 70, 22)];
    [_responsePopup setFrame:NSMakeRect(86, h - 86, twoRowControls ? 112 : 150, 28)];
    if (state->binaryComparison) {
        [_eventLabel setFrame:NSMakeRect(208, h - 82, 42, 22)];
        [_eventPopup setFrame:NSMakeRect(250, h - 86, 92, 28)];
        [_referenceField setFrame:NSMakeRect(350, h - 82, 122, 22)];
        [_linkLabel setFrame:NSMakeRect(480, h - 82, 34, 22)];
        [_linkPopup setFrame:NSMakeRect(514, h - 86, 136, 28)];
        [_scopeStaticLabel setFrame:NSMakeRect(14, h - 112, 46, 22)];
        [_scopePopup setFrame:NSMakeRect(60, h - 116, 138, 28)];
        [_autoRefitButton setFrame:NSMakeRect(214, h - 112, 94, 22)];
        [_selectedRowsField setFrame:NSMakeRect(w - 170, h - 112, 150, 20)];
    } else if (ordinaryGeneralized) {
        [_eventLabel setFrame:NSMakeRect(208, h - 82, 48, 22)];
        [_eventPopup setFrame:NSMakeRect(256, h - 86, 142, 28)];
        [_linkLabel setFrame:NSMakeRect(410, h - 82, 34, 22)];
        [_linkPopup setFrame:NSMakeRect(444, h - 86, 136, 28)];
        [_scopeStaticLabel setFrame:NSMakeRect(14, h - 112, 46, 22)];
        [_scopePopup setFrame:NSMakeRect(60, h - 116, 138, 28)];
        [_autoRefitButton setFrame:NSMakeRect(214, h - 112, 94, 22)];
        [_selectedRowsField setFrame:NSMakeRect(w - 170, h - 112, 150, 20)];
    } else {
        [_scopeStaticLabel setFrame:NSMakeRect(254, h - 82, 46, 22)];
        [_scopePopup setFrame:NSMakeRect(300, h - 86, 138, 28)];
        [_autoRefitButton setFrame:NSMakeRect(456, h - 82, 94, 22)];
        [_selectedRowsField setFrame:NSMakeRect(w - 170, h - 82, 150, 20)];
    }
    CGFloat reportTopInset = twoRowControls ? 170.0 : 140.0;
    [_scrollView setFrame:NSMakeRect(12, 46, std::max((CGFloat)200.0, w - 24.0), std::max((CGFloat)140.0, h - reportTopInset))];
    [_statusField setFrame:NSMakeRect(14, 16, std::max((CGFloat)200.0, w - 28.0), 20)];
    [_reportView setFrame:NSMakeRect(0, 0, wanted.width, wanted.height)];
    [_reportView setNeedsDisplay:YES];
    if (state->binaryComparison) {
        std::string status = state->multipleImputation
            ? "Comparing " + std::to_string(state->models.size()) + " models across " +
                std::to_string(std::max(1, state->imputationCount)) +
                " imputations; common original rows: " + std::to_string(state->commonRows.size())
            : "Status: comparing " + std::to_string(state->models.size()) + " models on " +
                std::to_string(state->commonRows.size()) + " common rows";
        if (!state->responseCoding.ok) status = "Select a binary response variable before fitting the models.";
        else if (state->rFitPending) status = state->multipleImputation
            ? "Fitting " + std::to_string(state->models.size()) + " models across " +
                std::to_string(std::max(1, state->imputationCount)) + " imputations..."
            : "Fitting model comparison in the main R session...";
        else if (state->commonRows.empty()) status = state->multipleImputation
            ? "No common original rows are available across the completed imputations."
            : "No common complete rows are available for the model comparison.";
        else for (const GeneralizedComparisonModel &model : state->models) {
            if (!model.fit.ok && !model.fit.status.empty()) {
                status = "Status: " + model.label + ": " + model.fit.status;
                break;
            }
        }
        [_statusField setStringValue:ToNSString(status)];
    } else if (state->multipleImputation) {
        std::string status = state->rFitPending
            ? "Fitting " + std::to_string(state->models.size()) + " models across " +
                std::to_string(std::max(1, state->imputationCount)) + " imputations..."
            : "Comparing " + std::to_string(state->models.size()) + " models across " +
                std::to_string(std::max(1, state->imputationCount)) +
                " imputations; common original rows: " + std::to_string(state->commonRows.size());
        if (!state->rFitPending && state->commonRows.empty()) {
            status = "No common original rows are available across the completed imputations.";
        }
        for (const GeneralizedComparisonModel &model : state->models) {
            if (!model.fit.ok && !model.fit.status.empty() && !state->rFitPending) {
                status = "Status: " + model.label + ": " + model.fit.status;
                break;
            }
        }
        [_statusField setStringValue:ToNSString(status)];
    } else {
        [_statusField setStringValue:ToNSString(rlispstat::core::GeneralizedComparisonSummaryStatus(state->models.size(), state->termRows.size()))];
    }
    if (state->dataScopeCaptured) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(rlispstat::core::AnalysisScopeWindowSummary(
                state->dataScope, state->dataScope.totalDatasetRows))]];
    }
    if (!state->frozenScopeNotice.empty()) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(state->frozenScopeNotice)]];
    }
}

- (void)refitModelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    // A semantic edit may arrive while Main R is still fitting an older
    // request. Queue a fresh generation so the older reply is discarded.
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    else RefreshGeneralizedTermRowsFromFits(*state);
}

- (void)addTerm:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMAddTermTitle())];
    int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    GeneralizedComparisonModel *activeModel = state->models.empty() ? nullptr : &state->models[(size_t)active];
    std::string activeResponse = activeModel && !activeModel->response.empty() ? activeModel->response : state->response;
    for (const std::string &name : VariableNamesForModel(&state->seed)) {
        if (name == activeResponse || (activeModel && rlispstat::core::GeneralizedModelIncludesTerm(*activeModel, name))) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    std::vector<std::string> interactionBase = activeModel ? activeModel->terms : std::vector<std::string>();
    std::vector<std::vector<std::string>> comparisonTerms;
    for (const GeneralizedComparisonModel &model : state->models) {
        comparisonTerms.push_back(model.terms);
    }
    if (!AddComparisonModelTermMenuItems(menu, self, @selector(addTermFromMenu:), &state->seed,
                                           activeResponse, comparisonTerms, interactionBase)) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(rlispstat::core::ComparisonNoAvailableTermsStatus())];
        return;
    }
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(20, 20) inView:_reportView];
}

- (void)showSearchableAddTermSelectorInView:(NSView *)view
{
    GeneralizedComparisonState *state = [self state];
    if (!state || state->models.empty()) return;
    const int active = std::max(0, std::min(state->activeModel,
        (int)state->models.size() - 1));
    const auto &model = state->models[(size_t)active];
    const std::string response = model.response.empty() ? state->response : model.response;
    std::vector<std::vector<std::string>> comparisonTerms;
    for (const auto &candidate : state->models) comparisonTerms.push_back(candidate.terms);
    const auto choices = SearchableComparisonTermChoices(
        &state->seed, response, comparisonTerms, model.terms);
    ShowSearchableAddSelector(_window, view, @"Add terms", choices,
        ^(NSArray<NSString *> *names) {
            GeneralizedComparisonState *current = [self state];
            if (!current || active >= (int)current->models.size()) return;
            bool changed = false;
            const auto available = VariableNamesForModel(&current->seed);
            for (NSString *label in names)
                changed = rlispstat::core::IncludeGeneralizedComparisonTerm(
                    *current, active, std::string(label.UTF8String), available) || changed;
            if (changed) { [self refitModelColumn:active]; [self refresh]; }
        }, ^NSMenu *(NSString *label) {
            GeneralizedComparisonState *current = [self state];
            if (!current || active >= (int)current->models.size()) return (NSMenu *)nil;
            const auto &activeModel = current->models[(size_t)active];
            const std::string currentResponse = activeModel.response.empty()
                ? current->response : activeModel.response;
            std::vector<std::vector<std::string>> currentTerms;
            for (const auto &candidate : current->models)
                currentTerms.push_back(candidate.terms);
            return SearchableComparisonTermContextMenu(label, self,
                @selector(addTermFromMenu:), &current->seed, currentResponse,
                currentTerms, activeModel.terms, (std::size_t)active);
        });
}

- (void)addTermFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) return;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    std::string term = [name UTF8String];
    int active = std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    if (rlispstat::core::IncludeGeneralizedComparisonTerm(
            *state, active, term, VariableNamesForModel(&state->seed))) {
        [self refitModelColumn:active];
        [self refresh];
    }
}

- (void)addModelColumn:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    const int active = state->models.empty() ? -1
        : std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    const int added = rlispstat::core::AddGeneralizedComparisonModel(*state, active, false);
    if (added < 0) return;
    _selectedModelColumn = added;
    _selectedTermRow = -1;
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    else RefreshGeneralizedTermRowsFromFits(*state);
    [self refresh];
}

- (void)addEmptyModelColumn:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    const int active = state->models.empty() ? -1
        : std::max(0, std::min(state->activeModel, (int)state->models.size() - 1));
    const int added = rlispstat::core::AddGeneralizedComparisonModel(*state, active, true);
    if (added < 0) return;
    _selectedModelColumn = added;
    _selectedTermRow = -1;
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    else RefreshGeneralizedTermRowsFromFits(*state);
    [self refresh];
}

- (NSMenu *)contextMenuForAddModel
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMAddModelLabel())];
    NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:@"New empty model"
        action:@selector(addEmptyModelColumn:) keyEquivalent:@""];
    [empty setTarget:self];
    [menu addItem:empty];
    NSMenuItem *duplicate = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::GLMDuplicateModelTitle())
        action:@selector(addModelColumn:) keyEquivalent:@""];
    [duplicate setTarget:self];
    [menu addItem:duplicate];
    return menu;
}

- (void)modelHeaderClicked:(int)modelColumn event:(NSEvent *)event
{
    (void)event;
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedModelColumn = modelColumn;
    _selectedTermRow = -1;
}

- (void)cellClickedAtTermRow:(int)termRow modelColumn:(int)modelColumn event:(NSEvent *)event
{
    GeneralizedComparisonState *state = [self state];
    if (!state || termRow < 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    BOOL toggle = ([event clickCount] >= 2 || (([event modifierFlags] & NSEventModifierFlagOption) != 0));
    if (termRow > 0) {
        if (toggle) {
            [self toggleSelectedTerm:nil];
        }
    }
}

- (void)fitCellClickedAtRow:(int)fitRow modelColumn:(int)modelColumn event:(NSEvent *)event
{
    (void)event;
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedTermRow = -1;
    _selectedFitRow = fitRow;
    _selectedModelColumn = modelColumn;
    NSString *label = [self fitLabelForRow:fitRow] ?: @"Statistic";
    NSString *value = [self fitDisplayForRow:fitRow modelColumn:modelColumn] ?: @"—";
    [_statusField setStringValue:[NSString stringWithFormat:@"Status: %@ · %@ = %@",
        ToNSString(state->models[(size_t)modelColumn].label), label, value]];
}

- (void)toggleTermAtRow:(int)termRow modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || termRow <= 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    state->activeModel = modelColumn;
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    [self toggleSelectedTerm:nil];
}

- (void)showReplacementMenuForTermRow:(int)termRow modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || termRow <= 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    const std::string rawTerm = state->termRows[(size_t)termRow];
    const std::string source = GeneralizedComparisonSourceTerm(*state, rawTerm);
    if (rawTerm != source || IsInteractionTerm(source) ||
        source.find('=') != std::string::npos) return;

    state->activeModel = modelColumn;
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    const GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
    const std::string response = model.response.empty() ? state->response : model.response;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Replace predictor"];
    for (const std::string &candidate : VariableNamesForModel(&state->seed)) {
        if (candidate == response || candidate == source ||
            rlispstat::core::GeneralizedModelIncludesTerm(model, candidate) ||
            !ModelTermExistsForModel(&state->seed, candidate, response)) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(candidate)
            action:@selector(replaceSelectedTerm:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(source + "\x1f" + candidate)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] == 0) {
        NSMenuItem *empty = [[NSMenuItem alloc]
            initWithTitle:@"No replacement variables available" action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [menu addItem:empty];
    }
    GeneralizedComparisonLayout layout(state->showInformationCriteria,
                                       state->binaryComparison);
    const NSRect rect = layout.termRect(termRow);
    [menu popUpMenuPositioningItem:nil
        atLocation:NSMakePoint(NSMinX(rect) + 16.0, NSMaxY(rect)) inView:_reportView];
}

- (NSString *)displayForTerm:(const std::string &)term modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return @"";
    const auto cell = rlispstat::core::GeneralizedComparisonTermCell(
        *state, modelColumn, term);
    // AppKit draws the add control itself.  Keep the historical dash for an
    // excluded base term, but never read coefficient rows outside the core
    // identity-checked semantic cell.
    if (cell.inclusionControlAvailable && !cell.termIncluded) return @"\u2014";
    return ToNSString(cell.displayText);
}

- (NSString *)fitDisplayForRow:(int)fitRow modelColumn:(int)modelColumn
{
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return @"";
    const std::vector<int> visibleRows = rlispstat::core::GeneralizedComparisonVisibleFitRows(
        state->binaryComparison, state->showInformationCriteria);
    if (fitRow < 0 || (size_t)fitRow >= visibleRows.size()) return @"";
    const int rawFitRow = visibleRows[(size_t)fitRow];
    const GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
    // A specification edit (including a binary event/reference swap) makes
    // every statistic from the preceding revision ineligible immediately.
    // Do not combine a current header/term specification with an older fit
    // while its replacement request is pending.
    if (rlispstat::core::GeneralizedComparisonResolvedFitState(*state, model) !=
        rlispstat::core::RegressionComparisonFitState::Valid) return @"";
    const GeneralizedGLMState &fit = model.fit;
    if (rawFitRow == 14 || rawFitRow == 15) {
        const bool useAIC = rawFitRow == 14;
        double minimum = INFINITY;
        for (const GeneralizedComparisonModel &candidate : state->models) {
            const double value = useAIC ? candidate.fit.aic : candidate.fit.bic;
            if (candidate.fit.ok && std::isfinite(value)) minimum = std::min(minimum, value);
        }
        const double value = useAIC ? fit.aic : fit.bic;
        return fit.ok && std::isfinite(value) && std::isfinite(minimum)
            ? ToNSString(FormatDoubleOrDash(value - minimum, 2)) : @"—";
    }
    if (state->binaryComparison) {
        const NestedModelTestResult test = GeneralizedAdjacentModelTest(*state, modelColumn);
        switch (rawFitRow) {
            case 0: return fit.ok ? ToNSString(std::to_string(fit.n)) : @"—";
            case 1: return fit.ok ? ToNSString(std::to_string(fit.responseCoding.eventCount)) : @"—";
            case 2: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.residualDeviance, 3)) : @"—";
            case 3: return fit.ok ? ToNSString(std::to_string(fit.dfResidual)) : @"—";
            case 4: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.aic, 2)) : @"—";
            case 5: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.bic, 2)) : @"—";
            case 6: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.logLik, 3)) : @"—";
            case 7: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.nagelkerkeR2, 3)) : @"—";
            case 8: return fit.ok ? ToNSString(FormatDoubleOrDash(fit.auc, 3)) : @"—";
            case 9: return fit.ok ? ToNSString(std::to_string(fit.parameterCount)) : @"—";
            case 10: return test.ok ? ToNSString(
                test.statisticName.find("mice::D") != std::string::npos && std::isfinite(test.df2)
                    ? std::to_string(test.df) + " / " + FormatDoubleOrDash(test.df2, 1)
                    : std::to_string(test.df)) : @"—";
            case 11: return test.ok ? ToNSString(FormatDoubleOrDash(test.delta, 3)) : @"—";
            case 12: return test.ok ? ToNSString(
                FormatDoubleOrDash(test.statistic, 3) +
                (test.statisticName.find("mice::D3") != std::string::npos ? " [D3]" :
                 test.statisticName.find("mice::D1") != std::string::npos ? " [D1]" : "")) : @"—";
            case 13: return test.ok ? ToNSString(FormatPValue(test.p)) : @"—";
            default: return @"";
        }
    }
    rlispstat::core::GeneralizedComparisonFitDisplayData display;
    display.ok = fit.ok;
    display.family = model.family;
    display.link = model.link;
    display.n = fit.n;
    display.nullDeviance = fit.nullDeviance;
    display.residualDeviance = fit.residualDeviance;
    display.dfResidual = fit.dfResidual;
    display.aic = fit.aic;
    display.bic = fit.bic;
    display.dispersion = fit.dispersion;
    display.logLik = fit.logLik;
    return ToNSString(rlispstat::core::GeneralizedComparisonFitDisplay(
        display, GeneralizedAdjacentModelTest(*state, modelColumn), rawFitRow));
}

- (NSString *)fitLabelForRow:(int)fitRow
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return @"";
    const std::vector<int> visibleRows = rlispstat::core::GeneralizedComparisonVisibleFitRows(
        state->binaryComparison, state->showInformationCriteria);
    if (fitRow < 0 || (size_t)fitRow >= visibleRows.size()) return @"";
    const int rawFitRow = visibleRows[(size_t)fitRow];
    if (state && state->binaryComparison) {
        static NSString *labels[] = { @"N", @"Events", @"Residual dev.", @"df residual", @"AIC", @"BIC",
            @"logLik", @"Nagelkerke pseudo-R²", @"Apparent AUC", @"Parameters", @"Δdf vs prev",
            @"Δ deviance", @"LR χ² vs prev", @"p vs prev", @"ΔAIC", @"ΔBIC" };
        return rawFitRow >= 0 && rawFitRow < 16 ? labels[rawFitRow] : @"";
    }
    return ToNSString(rlispstat::core::GeneralizedComparisonFitLabel(rawFitRow));
}

- (NSMenu *)contextMenuForFitRow:(int)fitRow modelColumn:(int)modelColumn
{
    _selectedTermRow = -1;
    _selectedFitRow = fitRow;
    _selectedModelColumn = modelColumn;
    GeneralizedComparisonState *state = [self state];
    if (state && modelColumn >= 0 && (size_t)modelColumn < state->models.size()) {
        state->activeModel = modelColumn;
    }
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.statistic)];
    NSString *value = [self fitDisplayForRow:fitRow modelColumn:modelColumn] ?: @"";
    NSString *label = [self fitLabelForRow:fitRow] ?: @"Model fit";
    NSMenuItem *copy = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.copyValue)
        action:@selector(copyComparisonCellValue:) keyEquivalent:@""];
    [copy setTarget:self]; [copy setRepresentedObject:value]; [menu addItem:copy];
    NSMenuItem *explain = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.explainStatistic)
        action:@selector(explainGeneralizedComparisonStatistic:) keyEquivalent:@""];
    [explain setTarget:self]; [explain setRepresentedObject:label]; [menu addItem:explain];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *diagnostics = ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), state && state->binaryComparison,
        state && state->countComparison && modelColumn >= 0 &&
            (size_t)modelColumn < state->models.size() &&
            rlispstat::core::CountDistributionSupportsScoreDistribution(
                state->models[(size_t)modelColumn].countDistribution),
        state && state->countComparison);
    if (state && modelColumn >= 0 && (size_t)modelColumn < state->models.size()) {
        [diagnostics setEnabled:state->models[(size_t)modelColumn].fit.ok];
    }
    [menu addItem:diagnostics];
    return menu;
}

- (void)explainGeneralizedComparisonStatistic:(id)sender
{
    GeneralizedComparisonState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string statistic = [represented isKindOfClass:[NSString class]]
        ? [(NSString *)represented UTF8String] : "Model fit";
    rlispstat::core::ModelStatisticExplanationContext context;
    context.statistic = statistic;
    context.modelFamily = model.family;
    context.link = model.link;
    context.comparison = true;
    context.multipleImputation = state->multipleImputation;
    context.rubinRulesApplied = state->multipleImputation;
    context.likelihoodAvailable = model.fit.likelihoodAvailable;
    if (state->multipleImputation) {
        DataFrameModel dataframe;
        if (DataFrameSnapshotForGroup(state->group, dataframe)) {
            const rlispstat::core::ModelSpecification specification =
                rlispstat::core::EffectiveGeneralizedComparisonModelSpecification(*state, model);
            context.rubinRulesApplied =
                !rlispstat::core::RowsWithImputedModelInputs(
                    dataframe, specification, {model.offsetVariable}).empty();
        }
        const bool sequentialStatistic =
            statistic.find("vs prev") != std::string::npos ||
            statistic.find("D1") != std::string::npos ||
            statistic.find("D3") != std::string::npos ||
            statistic.find("Wald") != std::string::npos;
        if (sequentialStatistic) {
            const NestedModelTestResult test =
                GeneralizedAdjacentModelTest(*state, _selectedModelColumn);
            context.miMethod = test.ok && !test.statisticName.empty()
                ? test.statisticName : "mice::D1";
        } else {
            context.miMethod = "mice::pool";
        }
    }
    ShowWorkbenchMessageOnMain(
        ToNSString("Explain statistic: " + statistic),
        ToNSString(rlispstat::core::ExplainModelStatistic(context)));
}

- (NSString *)comparisonTableText
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return @"";
    rlispstat::core::ComparisonCopyTable table;
    table.title = rlispstat::core::StatisticalModelComparisonTitle(
        state->modelType, state->multipleImputation);
    table.response = state->response;
    for (const GeneralizedComparisonModel &model : state->models) table.modelLabels.push_back(model.label);
    for (const std::string &term : state->termRows) {
        table.termLabels.push_back(GeneralizedComparisonDisplayLabel(*state, term));
        std::vector<std::string> cells;
        for (size_t m = 0; m < state->models.size(); ++m) {
            cells.push_back([[self displayForTerm:term modelColumn:(int)m] UTF8String]);
        }
        table.termDisplaysByRow.push_back(cells);
    }
    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    for (int r = 0; r < layout.fitRows; ++r) {
        table.fitLabels.push_back([[self fitLabelForRow:r] UTF8String]);
        std::vector<std::string> cells;
        for (size_t m = 0; m < state->models.size(); ++m) {
            cells.push_back([[self fitDisplayForRow:r modelColumn:(int)m] UTF8String]);
        }
        table.fitDisplaysByRow.push_back(cells);
    }
    table.footnote = rlispstat::core::GeneralizedComparisonFootnote();
    return ToNSString(rlispstat::core::ComparisonCopyTableText(table));
}

