- (void)toggleSelectedTerm:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    if (rlispstat::core::ToggleGeneralizedComparisonTerm(
            *state, _selectedModelColumn, term, VariableNamesForModel(&state->seed))) {
        [self refitModelColumn:_selectedModelColumn];
        [self refresh];
    }
}

- (void)replaceSelectedTerm:(id)sender
{
    NSString *value = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!value || !state || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    const std::string encoded = [value UTF8String];
    const std::size_t separator = encoded.find('\x1f');
    if (separator == std::string::npos) return;
    const std::string term = encoded.substr(0, separator);
    const std::string replacement = encoded.substr(separator + 1);
    if (rlispstat::core::ReplaceGeneralizedComparisonTerm(
            *state, _selectedModelColumn, term, replacement,
            VariableNamesForModel(&state->seed))) {
        [self refitModelColumn:_selectedModelColumn];
        [self refresh];
    }
}

- (void)addSelectedTermToAllModels:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    const std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    if (rlispstat::core::IncludeGeneralizedComparisonTermInAllModels(
            *state, term, VariableNamesForModel(&state->seed))) {
        if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
        else RefreshGeneralizedTermRowsFromFits(*state);
        [self refresh];
    }
}

- (void)removeSelectedTermFromComparison:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 ||
        (size_t)_selectedTermRow >= state->termRows.size()) return;
    const std::string term = GeneralizedComparisonSourceTerm(
        *state, state->termRows[(size_t)_selectedTermRow]);
    if (!rlispstat::core::RemoveGeneralizedComparisonTermCompletely(*state, term)) return;
    _selectedTermRow = -1;
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    else RefreshGeneralizedTermRowsFromFits(*state);
    [self refresh];
}

- (void)toggleModelTermFromMenu:(id)sender
{
    NSString *represented = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!represented || !state) return;
    const std::string encoded = [represented UTF8String];
    const std::size_t separator = encoded.find('\x1f');
    if (separator == std::string::npos) return;
    const int modelColumn = std::atoi(encoded.substr(0, separator).c_str());
    const std::string term = encoded.substr(separator + 1);
    if (!rlispstat::core::ToggleGeneralizedComparisonTerm(
            *state, modelColumn, term, VariableNamesForModel(&state->seed))) return;
    _selectedModelColumn = modelColumn;
    state->activeModel = modelColumn;
    [self refitModelColumn:modelColumn];
    [self refresh];
}

