- (NSMenuItem *)diagnosticResidualsMenuItemForSelectedModel
{
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return nil;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Diagnostic residuals"
        action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:@"Diagnostic residuals"];
    for (const std::string &residualType :
         rlispstat::core::AvailableGeneralizedResidualTypes(model.fit)) {
        NSString *title = residualType == "dunn_smyth"
            ? ToNSString(rlispstat::core::GLMDunnSmythResidualTitle())
            : residualType == "raw"
                ? ToNSString(rlispstat::core::GLMRawResidualTitle())
                : residualType == "pearson"
            ? ToNSString(rlispstat::core::GLMPearsonResidualTitle())
            : residualType == "working"
                ? ToNSString(rlispstat::core::GLMWorkingResidualTitle())
                : ToNSString(rlispstat::core::GLMDevianceResidualTitle());
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title
            action:@selector(diagnosticResidualTypeSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setState:model.diagnosticOptions.residualType == residualType
            ? NSControlStateValueOn : NSControlStateValueOff];
        [item setRepresentedObject:@{
            @"modelId": ToNSString(model.id),
            @"residualType": ToNSString(residualType)
        }];
        [submenu addItem:item];
    }
    [root setSubmenu:submenu];
    return root;
}

- (void)diagnosticResidualTypeSelected:(id)sender
{
    NSDictionary *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSDictionary class]]) return;
    NSString *modelIdValue = payload[@"modelId"];
    NSString *residualTypeValue = payload[@"residualType"];
    if (!modelIdValue || !residualTypeValue) return;
    GeneralizedComparisonState *comparison = nullptr;
    GeneralizedComparisonModel *model = nullptr;
    if (!FindGeneralizedComparisonModelById([modelIdValue UTF8String],
                                            &comparison, &model) ||
        !comparison || !model) return;
    const std::string residualType = [residualTypeValue UTF8String];
    if (!rlispstat::core::IsGeneralizedResidualTypeAvailable(model->fit, residualType) ||
        model->diagnosticOptions.residualType == residualType) return;
    model->diagnosticOptions.residualType = residualType;
    ++model->diagnosticOptions.version;
    model->fit.diagnosticOptions = model->diagnosticOptions;
    RefreshGLMDiagnosticPlotsSynchronouslyOnMain(comparison->group, true);
    [self refresh];
}

