- (void)refitSelectedGeneralizedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
    // This is the explicit Refit command, so it must run even when the user
    // disabled Auto-refit while constructing the specification.
    state->activeModel = _selectedModelColumn;
    RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

