- (void)deleteSelectedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || state->models.size() <= 1 || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    if (!rlispstat::core::DeleteGeneralizedComparisonModel(*state, _selectedModelColumn)) return;
    _selectedModelColumn = state->activeModel;
    _selectedTermRow = -1;
    RefreshGeneralizedTermRowsFromFits(*state);
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)renameSelectedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:ToNSString(rlispstat::core::GLMRenameModelTitle())];
    NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 220, 24)];
    [field setStringValue:ToNSString(state->models[(size_t)_selectedModelColumn].label)];
    [alert setAccessoryView:field];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::GLMRenameModelTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    if ([alert runModal] == NSAlertFirstButtonReturn) {
        state->models[(size_t)_selectedModelColumn].label = [[field stringValue] UTF8String];
        [self refresh];
    }
}

- (void)openSelectedModelAsGeneralizedGLM:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string singleId =
        "gglm_" + model.id + "_" + std::to_string((long long)time(nullptr));
    GeneralizedGLMState single =
        rlispstat::core::CreateSingleModelFromGeneralizedComparison(
            *state, _selectedModelColumn, singleId);
    const bool needsFit = !single.ok;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedGLMs[single.id] = single;
    }
    if (needsFit) {
        GeneralizedGLMState &stored = g_generalizedGLMs[single.id];
        RequestGeneralizedGLMFitInMainR(stored);
    }
    ShowGeneralizedGLMOnMain(single.id);
}

- (void)showFamilyMenuForSelectedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMComparisonFamilyMenuTitle())];
    for (const std::string &family : std::vector<std::string>{"gaussian", "binomial", "poisson", "Gamma", "inverse.gaussian", "quasibinomial", "quasipoisson"}) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(family) action:@selector(familyMenuSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(family)];
        [item setState:state->models[(size_t)_selectedModelColumn].family == family ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    NSRect rect = layout.modelHeaderRect(_selectedModelColumn);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMidX(rect), NSMaxY(rect)) inView:_reportView];
