- (void)familyMenuSelected:(id)sender
{
    NSString *family = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!family || !state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string selectedFamily = [family UTF8String];
    if (model.family == selectedFamily) return;
    model.family = selectedFamily;
    if (!IsValidGeneralizedLink(model.family, model.link)) {
        model.link = DefaultGeneralizedLink(model.family);
    }
    rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
    [self refitModelColumn:_selectedModelColumn];
    [self refresh];
}

- (void)showLinkMenuForSelectedModel:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::GLMComparisonLinkMenuTitle())];
    std::vector<std::string> links;
    if (state->binaryComparison) {
        for (rlispstat::core::BinaryLink link : rlispstat::core::SupportedBinaryLinks()) {
            links.push_back(rlispstat::core::BinaryLinkId(link));
        }
    } else {
        links = GeneralizedLinksForFamily(model.family);
    }
    for (const std::string &link : links) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(link) action:@selector(linkMenuSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(link)];
        [item setState:model.link == link ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    NSRect rect = layout.modelHeaderRect(_selectedModelColumn);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMidX(rect), NSMaxY(rect)) inView:_reportView];
}

- (void)linkMenuSelected:(id)sender
{
    NSString *link = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!link || !state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string selectedLink = [link UTF8String];
    if (model.link == selectedLink) return;
    model.link = selectedLink;
    rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
    [self refitModelColumn:_selectedModelColumn];
    [self refresh];
}

- (NSMenu *)contextMenuForModelColumn:(int)modelColumn
{
    _selectedModelColumn = modelColumn;
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return nil;
    state->activeModel = modelColumn;
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.model)];
    AddMissingInformationMenu(menu, state->id);
    NSMenuItem *heading = [[NSMenuItem alloc]
        initWithTitle:ToNSString(state->models[(size_t)modelColumn].label)
        action:nil keyEquivalent:@""];
    [heading setEnabled:NO];
    [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *rename = [[NSMenuItem alloc]
        initWithTitle:@"Rename model\u2026" action:@selector(renameSelectedModel:) keyEquivalent:@""];
    [rename setTarget:self];
    [menu addItem:rename];

    NSMenuItem *termsRoot = [[NSMenuItem alloc] initWithTitle:@"Model terms" action:nil keyEquivalent:@""];
    NSMenu *termsMenu = [[NSMenu alloc] initWithTitle:@"Model terms"];
    std::set<std::string> listedTerms;
    for (const std::string &row : state->termRows) {
        const std::string term = GeneralizedComparisonSourceTerm(*state, row);
        if (term == "(Intercept)" || !listedTerms.insert(term).second) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(term)
            action:@selector(toggleModelTermFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setState:rlispstat::core::GeneralizedModelIncludesTerm(
            state->models[(size_t)modelColumn], term) ? NSControlStateValueOn : NSControlStateValueOff];
        [item setRepresentedObject:ToNSString(std::to_string(modelColumn) + "\x1f" + term)];
        [termsMenu addItem:item];
    }
    [termsRoot setSubmenu:termsMenu];
    [menu addItem:termsRoot];
    const GeneralizedComparisonModel &selectedModel = state->models[(size_t)modelColumn];
    const bool supportsOffset = selectedModel.family != "beta_one_inflated" &&
        (!state->countComparison ||
         (selectedModel.countDistribution != rlispstat::core::CountDistribution::HurdleBetaBinomialCeiling &&
          selectedModel.countDistribution != rlispstat::core::CountDistribution::PerfectScore));
    if (supportsOffset) {
        NSMenuItem *offsetRoot = [[NSMenuItem alloc]
            initWithTitle:@"Link-scale offset (advanced)" action:nil keyEquivalent:@""];
        NSMenu *offsetMenu = [[NSMenu alloc] initWithTitle:@"Link-scale offset (advanced)"];
        NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:@"None"
            action:@selector(comparisonOffsetSelected:) keyEquivalent:@""];
        [none setTarget:self];
        [none setRepresentedObject:ToNSString(std::to_string(modelColumn) + "\x1f")];
        [none setState:selectedModel.offsetVariable.empty() ? NSControlStateValueOn : NSControlStateValueOff];
        [offsetMenu addItem:none];
        for (const std::string &candidate : rlispstat::core::NumericVariableNames(&state->seed)) {
            if (candidate == selectedModel.response || candidate == selectedModel.exposure) continue;
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(candidate)
                action:@selector(comparisonOffsetSelected:) keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(std::to_string(modelColumn) + "\x1f" + candidate)];
            [item setState:selectedModel.offsetVariable == candidate ? NSControlStateValueOn : NSControlStateValueOff];
            [offsetMenu addItem:item];
        }
        [offsetRoot setSubmenu:offsetMenu];
        [menu addItem:offsetRoot];
    }
    if (state->countComparison) {
        NSMenuItem *distributionRoot = [[NSMenuItem alloc]
            initWithTitle:@"Distribution" action:nil keyEquivalent:@""];
        NSMenu *distributionMenu = [[NSMenu alloc] initWithTitle:@"Distribution"];
        for (const auto &specification : rlispstat::core::DistributionSpecificationsForModel(
                 rlispstat::core::StatisticalModelType::Count)) {
            rlispstat::core::CountDistribution distribution;
            if (!rlispstat::core::ParseCountDistribution(specification.id, distribution) ||
                distribution == rlispstat::core::CountDistribution::QuasiPoisson) continue;
            NSMenuItem *item = [[NSMenuItem alloc]
                initWithTitle:ToNSString(specification.visibleName)
                action:@selector(countComparisonDistributionSelected:)
                keyEquivalent:@""];
            [item setTarget:self];
            [item setRepresentedObject:ToNSString(
                std::to_string(modelColumn) + "\x1f" + specification.id)];
            const auto selected = state->models[(size_t)modelColumn].countDistribution;
            [item setState:(selected != rlispstat::core::CountDistribution::QuasiPoisson &&
                            selected == distribution)
                ? NSControlStateValueOn : NSControlStateValueOff];
            [distributionMenu addItem:item];
        }
        [distributionRoot setSubmenu:distributionMenu];
        [menu addItem:distributionRoot];

        const auto selectedDistribution =
            state->models[(size_t)modelColumn].countDistribution;
        if (rlispstat::core::CountDistributionUsesTrials(selectedDistribution)) {
            NSMenuItem *trials = [[NSMenuItem alloc]
                initWithTitle:@"Set trials\u2026"
                action:@selector(countComparisonTrialsSelected:)
                keyEquivalent:@""];
            [trials setTarget:self];
            [trials setRepresentedObject:ToNSString(std::to_string(modelColumn))];
            [menu addItem:trials];
        } else {
            NSMenuItem *inferenceRoot = [[NSMenuItem alloc]
                initWithTitle:@"Dispersion / inference" action:nil keyEquivalent:@""];
            NSMenu *inferenceMenu = [[NSMenu alloc] initWithTitle:@"Dispersion / inference"];
            const bool quasi = selectedDistribution ==
                rlispstat::core::CountDistribution::QuasiPoisson;
            for (const auto &entry : std::vector<std::pair<std::string, std::string>>{
                     {"standard", "Standard likelihood model"},
                     {"quasipoisson", "Quasi-Poisson"}}) {
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:ToNSString(entry.second)
                    action:@selector(countComparisonInferenceSelected:)
                    keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(
                    std::to_string(modelColumn) + "\x1f" + entry.first)];
                [item setState:((entry.first == "quasipoisson") == quasi)
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [inferenceMenu addItem:item];
            }
            [inferenceRoot setSubmenu:inferenceMenu];
            [menu addItem:inferenceRoot];

            NSMenuItem *exposureRoot = [[NSMenuItem alloc]
                initWithTitle:@"Exposure (log offset)" action:nil keyEquivalent:@""];
            NSMenu *exposureMenu = [[NSMenu alloc] initWithTitle:@"Exposure (log offset)"];
            NSMenuItem *none = [[NSMenuItem alloc]
                initWithTitle:@"None"
                action:@selector(countComparisonExposureSelected:)
                keyEquivalent:@""];
            [none setTarget:self];
            [none setRepresentedObject:ToNSString(std::to_string(modelColumn) + "\x1f")];
            [none setState:state->models[(size_t)modelColumn].exposure.empty()
                ? NSControlStateValueOn : NSControlStateValueOff];
            [exposureMenu addItem:none];
            for (const std::string &candidate : rlispstat::core::NumericVariableNames(&state->seed)) {
                if (candidate == state->response) continue;
                const DataColumn *column = FindDataColumnForModel(&state->seed, candidate);
                if (!column || !rlispstat::core::InspectCountExposure(*column).ok) continue;
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:ToNSString(candidate)
                    action:@selector(countComparisonExposureSelected:)
                    keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(
                    std::to_string(modelColumn) + "\x1f" + candidate)];
                [item setState:state->models[(size_t)modelColumn].exposure == candidate
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [exposureMenu addItem:item];
            }
            [exposureRoot setSubmenu:exposureMenu];
            [menu addItem:exposureRoot];
        }
    }
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *residuals = [self diagnosticResidualsMenuItemForSelectedModel];
    if (residuals) [menu addItem:residuals];
    NSMenuItem *diagnosticsRoot = ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), state->binaryComparison,
        state->countComparison &&
            rlispstat::core::CountDistributionSupportsScoreDistribution(
                state->models[(size_t)modelColumn].countDistribution),
        state->countComparison);
    [diagnosticsRoot setEnabled:state->models[(size_t)modelColumn].fit.ok];
    [menu addItem:diagnosticsRoot];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *open = [[NSMenuItem alloc]
        initWithTitle:(state->countComparison ? @"Open this model as single Count Model"
            : (state->binaryComparison ? @"Open this model as single Binary Model"
                : @"Open this model as single Generalized Linear Model"))
        action:@selector(openSelectedModelAsGeneralizedGLM:) keyEquivalent:@""];
    NSMenuItem *refit = [[NSMenuItem alloc] initWithTitle:@"Refit this model"
        action:@selector(refitSelectedGeneralizedModel:) keyEquivalent:@""];
    NSMenuItem *duplicate = [[NSMenuItem alloc] initWithTitle:@"Duplicate model"
        action:@selector(duplicateSelectedModel:) keyEquivalent:@""];
    NSMenuItem *remove = [[NSMenuItem alloc] initWithTitle:@"Delete model"
        action:@selector(deleteSelectedModel:) keyEquivalent:@""];
    for (NSMenuItem *item in @[open, refit, duplicate, remove]) [item setTarget:self];
    [remove setEnabled:state->models.size() > 1];
    [menu addItem:open]; [menu addItem:refit]; [menu addItem:duplicate]; [menu addItem:remove];

    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *informationCriteria = [[NSMenuItem alloc]
        initWithTitle:@"Information criteria" action:@selector(toggleInformationCriteria:)
        keyEquivalent:@""];
    [informationCriteria setTarget:self];
    [informationCriteria setState:state->showInformationCriteria
        ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:informationCriteria];
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

- (void)countComparisonDistributionSelected:(id)sender
{
    NSString *represented = [sender representedObject];
    if (!represented) return;
    const std::string value = [represented UTF8String];
    const std::size_t separator = value.find('\x1f');
    if (separator == std::string::npos) return;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    int modelColumn = -1;
    try { modelColumn = std::stoi(value.substr(0, separator)); } catch (...) { return; }
    rlispstat::core::CountDistribution distribution;
    if (!rlispstat::core::ParseCountDistribution(value.substr(separator + 1), distribution) ||
        distribution == rlispstat::core::CountDistribution::QuasiPoisson) return;
    if (rlispstat::core::SetGeneralizedComparisonCountDistribution(
            *state, modelColumn, distribution)) {
        [self refitModelColumn:modelColumn];
        [self refresh];
    }
}

- (void)comparisonOffsetSelected:(id)sender
{
    NSString *represented = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!represented || !state) return;
    const std::string encoded = [represented UTF8String];
    const std::size_t separator = encoded.find('\x1f');
    if (separator == std::string::npos) return;
    int modelColumn = -1;
    try { modelColumn = std::stoi(encoded.substr(0, separator)); } catch (...) { return; }
    if (rlispstat::core::SetGeneralizedComparisonOffset(
            *state, modelColumn, encoded.substr(separator + 1))) {
        [self refitModelColumn:modelColumn];
        [self refresh];
    }
}

- (void)countComparisonInferenceSelected:(id)sender
{
    NSString *represented = [sender representedObject];
    if (!represented) return;
    const std::string value = [represented UTF8String];
    const std::size_t separator = value.find('\x1f');
    if (separator == std::string::npos) return;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    int modelColumn = -1;
    try { modelColumn = std::stoi(value.substr(0, separator)); } catch (...) { return; }
    const bool requestQuasi = value.substr(separator + 1) == "quasipoisson";
    if (!requestQuasi && modelColumn >= 0 &&
        (size_t)modelColumn < state->models.size() &&
        state->models[(size_t)modelColumn].countDistribution !=
            rlispstat::core::CountDistribution::QuasiPoisson) return;
    const auto target = requestQuasi
        ? rlispstat::core::CountDistribution::QuasiPoisson
        : rlispstat::core::CountDistribution::Poisson;
    if (rlispstat::core::SetGeneralizedComparisonCountDistribution(
            *state, modelColumn, target)) {
        [self refitModelColumn:modelColumn];
        [self refresh];
    }
}

- (void)countComparisonTrialsSelected:(id)sender
{
    NSString *represented = [sender representedObject];
    if (!represented) return;
    int modelColumn = -1;
    try { modelColumn = std::stoi([represented UTF8String]); } catch (...) { return; }
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    auto &model = state->models[(size_t)modelColumn];
    if (!rlispstat::core::CountDistributionUsesTrials(model.countDistribution)) return;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Trials"];
    [alert setInformativeText:@"Enter a fixed positive integer."];
    NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 220, 24)];
    [field setStringValue:std::isfinite(model.trialsConstant)
        ? ToNSString(FormatDoubleOrDash(model.trialsConstant, 0)) : @""];
    [alert setAccessoryView:field];
    [alert addButtonWithTitle:@"Apply"];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
    if ([alert runModal] != NSAlertFirstButtonReturn) return;
    const std::string text = [[field stringValue] UTF8String];
    char *end = nullptr;
    const double value = std::strtod(text.c_str(), &end);
    if (!end || end == text.c_str() || *end != '\0' || !std::isfinite(value) ||
        value <= 0.0 || std::floor(value) != value) {
        ShowWorkbenchMessageOnMain(@"Trials", @"Trials must be a fixed positive integer.");
        return;
    }
    if (rlispstat::core::SetGeneralizedComparisonTrials(
            *state, modelColumn, "", value)) {
        [self refitModelColumn:modelColumn];
        [self refresh];
    }
}

- (void)countComparisonExposureSelected:(id)sender
{
    NSString *represented = [sender representedObject];
    if (!represented) return;
    const std::string encoded([represented UTF8String]);
    const std::size_t separator = encoded.find('\x1f');
    if (separator == std::string::npos) return;
    int modelColumn = -1;
    try { modelColumn = std::stoi(encoded.substr(0, separator)); } catch (...) { return; }
    GeneralizedComparisonState *state = [self state];
    if (!state || modelColumn < 0 || (size_t)modelColumn >= state->models.size()) return;
    auto &model = state->models[(size_t)modelColumn];
    if (rlispstat::core::CountDistributionUsesTrials(model.countDistribution)) return;
    const std::string exposure = encoded.substr(separator + 1);
    if (!exposure.empty()) {
        const DataColumn *column = FindDataColumnForModel(&state->seed, exposure);
        if (!column || !rlispstat::core::InspectCountExposure(*column).ok) return;
    }
    if (rlispstat::core::SetGeneralizedComparisonExposure(
            *state, modelColumn, exposure)) {
        [self refitModelColumn:modelColumn];
        [self refresh];
    }
}

- (void)modelHeaderClickedMenu:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (state && _selectedModelColumn >= 0 && (size_t)_selectedModelColumn < state->models.size()) {
        state->activeModel = _selectedModelColumn;
        [self refresh];
    }
}

- (void)toggleInformationCriteria:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    state->showInformationCriteria = !state->showInformationCriteria;
    [self refresh];
}

- (NSMenu *)contextMenuForTermRow:(int)termRow modelColumn:(int)modelColumn
{
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    GeneralizedComparisonState *state = [self state];
    if (state && modelColumn >= 0 && (size_t)modelColumn < state->models.size()) {
        state->activeModel = modelColumn;
    }
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.predictor)];
    if (!state || termRow <= 0 || (size_t)termRow >= state->termRows.size() ||
        modelColumn < 0 || (size_t)modelColumn >= state->models.size()) {
        NSMenuItem *details = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.showCoefficientDetails)
            action:@selector(showCoefficientDetails:) keyEquivalent:@""];
        [details setTarget:self]; [menu addItem:details];
        NSMenuItem *explain = [[NSMenuItem alloc]
            initWithTitle:ToNSString(titles.explainStatistic)
            action:@selector(explainGeneralizedComparisonStatistic:) keyEquivalent:@""];
        [explain setTarget:self]; [explain setRepresentedObject:@"b"];
        [menu addItem:explain];
        return menu;
    }

    const std::string baseTerm = GeneralizedComparisonSourceTerm(
        *state, state->termRows[(size_t)termRow]);
    const bool interaction = IsInteractionTerm(baseTerm);
    GeneralizedComparisonModel &model = state->models[(size_t)modelColumn];
    const bool included = rlispstat::core::GeneralizedModelIncludesTerm(model, baseTerm);
    const std::string termType = rlispstat::core::GeneralizedComparisonModelTermType(
        *state, modelColumn, baseTerm);
    NSMenuItem *remove = [[NSMenuItem alloc]
        initWithTitle:(interaction ? @"Remove interaction from comparison"
            : @"Remove predictor from comparison")
        action:@selector(removeSelectedTermFromComparison:) keyEquivalent:@""];
    [remove setTarget:self];
    [menu addItem:remove];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *heading = [[NSMenuItem alloc]
        initWithTitle:ToNSString(baseTerm + " \xC2\xB7 " + model.label)
        action:nil keyEquivalent:@""];
    [heading setEnabled:NO]; [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *analyzeRoot = [[NSMenuItem alloc]
        initWithTitle:@"Analyze predictor" action:nil keyEquivalent:@""];
    NSMenu *analyzeMenu = [[NSMenu alloc] initWithTitle:@"Analyze predictor"];
    NSMenuItem *details = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.showCoefficientDetails)
        action:@selector(showCoefficientDetails:) keyEquivalent:@""];
    [details setTarget:self]; [analyzeMenu addItem:details];
    NSMenuItem *explain = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.explainStatistic)
        action:@selector(explainGeneralizedComparisonStatistic:) keyEquivalent:@""];
    [explain setTarget:self]; [explain setRepresentedObject:@"b"];
    [analyzeMenu addItem:explain];
    if (interaction) {
        NSMenuItem *interpret = [[NSMenuItem alloc]
            initWithTitle:@"Interpret interaction…"
            action:@selector(openGeneralizedComparisonInteraction:)
            keyEquivalent:@""];
        [interpret setTarget:self];
        [interpret setRepresentedObject:ToNSString(baseTerm)];
        [interpret setEnabled:!included || model.fit.ok];
        [analyzeMenu addItem:interpret];
        NSMenuItem *plot = [[NSMenuItem alloc]
            initWithTitle:@"Effect plot…"
            action:@selector(openGeneralizedComparisonInteractionPlot:)
            keyEquivalent:@""];
        [plot setTarget:self];
        [plot setRepresentedObject:ToNSString(baseTerm)];
        [plot setEnabled:!included || model.fit.ok];
        [analyzeMenu addItem:plot];
    } else if (included) {
        NSMenuItem *effect = [[NSMenuItem alloc]
            initWithTitle:@"Effect plot…"
            action:@selector(openGeneralizedComparisonInteractionPlot:)
            keyEquivalent:@""];
        [effect setTarget:self];
        [effect setRepresentedObject:ToNSString(baseTerm)];
        [effect setEnabled:model.fit.ok];
        [analyzeMenu addItem:effect];
        NSMenuItem *partial = [[NSMenuItem alloc]
            initWithTitle:@"Partial regression plot…"
            action:@selector(openGeneralizedComparisonPartialRegressionPlot:)
            keyEquivalent:@""];
        [partial setTarget:self];
        [partial setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:partial];
    }
    if (included && !interaction &&
        (termType == "factor" || termType == "ordered")) {
        NSMenuItem *pairwise = [[NSMenuItem alloc]
            initWithTitle:@"Pairwise comparisons…"
            action:@selector(openGeneralizedComparisonPairwise:)
            keyEquivalent:@""];
        [pairwise setTarget:self];
        [pairwise setRepresentedObject:ToNSString(baseTerm)];
        [analyzeMenu addItem:pairwise];
    }
    [analyzeRoot setSubmenu:analyzeMenu]; [menu addItem:analyzeRoot];

    NSMenuItem *modelTermsRoot = [[NSMenuItem alloc] initWithTitle:@"Model terms"
        action:nil keyEquivalent:@""];
    NSMenu *modelTermsMenu = [[NSMenu alloc] initWithTitle:@"Model terms"];
    NSMenuItem *toggle = [[NSMenuItem alloc] initWithTitle:@"Include in this model"
        action:@selector(toggleSelectedTerm:) keyEquivalent:@""];
    [toggle setTarget:self];
    [toggle setState:included ? NSControlStateValueOn : NSControlStateValueOff];
    [modelTermsMenu addItem:toggle];
    NSMenuItem *addAll = [[NSMenuItem alloc] initWithTitle:@"Add to all models"
        action:@selector(addSelectedTermToAllModels:) keyEquivalent:@""];
    NSMenuItem *removeAll = [[NSMenuItem alloc] initWithTitle:@"Remove term from comparison"
        action:@selector(removeSelectedTermFromComparison:) keyEquivalent:@""];
    [addAll setTarget:self]; [removeAll setTarget:self];
    [modelTermsMenu addItem:addAll]; [modelTermsMenu addItem:removeAll];
    std::vector<std::vector<std::string>> comparisonTerms;
    for (const GeneralizedComparisonModel &candidate : state->models)
        comparisonTerms.push_back(candidate.terms);
    const std::string response = model.response.empty() ? state->response : model.response;
    AddComparisonModelTermMenuItems(modelTermsMenu, self, @selector(addTermFromMenu:),
        &state->seed, response, comparisonTerms, model.terms, baseTerm);
    [modelTermsRoot setSubmenu:modelTermsMenu]; [menu addItem:modelTermsRoot];

    NSMenuItem *editRoot = [[NSMenuItem alloc] initWithTitle:@"Edit predictor"
        action:nil keyEquivalent:@""];
    NSMenu *editMenu = [[NSMenu alloc] initWithTitle:@"Edit predictor"];
    if (!interaction && baseTerm.find('=') == std::string::npos) {
        NSMenuItem *typesRoot = [[NSMenuItem alloc] initWithTitle:@"Change type"
            action:nil keyEquivalent:@""];
        NSMenu *typesMenu = [[NSMenu alloc] initWithTitle:@"Change type"];
        AddModelTermTypeMenuItems(typesMenu, self, @selector(comparisonTypeMenuSelected:), termType);
        [typesRoot setSubmenu:typesMenu]; [editMenu addItem:typesRoot];
        const std::string predictor = rlispstat::core::BaseVariableForTermComponent(baseTerm);
        if (termType == "factor") {
            DataFrameModel dataframe;
            if (DataFrameSnapshotForGroup(state->group, dataframe)) {
                const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
                    state->seed, &dataframe, predictor);
                if (metadata.levels.size() > 1) {
                    NSMenuItem *referenceRoot = [[NSMenuItem alloc]
                        initWithTitle:@"Reference category" action:nil keyEquivalent:@""];
                    NSMenu *referenceMenu = [[NSMenu alloc] initWithTitle:@"Reference category"];
                    const auto configured = model.factorReferenceLevels.find(predictor);
                    const std::string selected = configured == model.factorReferenceLevels.end()
                        ? metadata.levels.front() : configured->second;
                    for (const std::string &level : metadata.levels) {
                        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(level)
                            action:@selector(comparisonReferenceMenuSelected:) keyEquivalent:@""];
                        [item setTarget:self]; [item setRepresentedObject:ToNSString(level)];
                        [item setState:level == selected ? NSControlStateValueOn : NSControlStateValueOff];
                        [referenceMenu addItem:item];
                    }
                    [referenceRoot setSubmenu:referenceMenu]; [editMenu addItem:referenceRoot];
                }
            }
        } else {
            const bool centered = model.centeredPredictors.count(predictor) != 0;
            NSMenuItem *center = [[NSMenuItem alloc]
                initWithTitle:(centered ? @"Remove centering" : @"Center predictor")
                action:@selector(toggleCenterSelectedPredictor:) keyEquivalent:@""];
            [center setTarget:self]; [center setEnabled:included]; [editMenu addItem:center];
        }
    }
    if ([editMenu numberOfItems] > 0) {
        [editRoot setSubmenu:editMenu];
        [menu addItem:editRoot];
    }

    NSMenuItem *diagnosticsRoot = ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), state->binaryComparison,
        state->countComparison &&
            rlispstat::core::CountDistributionSupportsScoreDistribution(
                model.countDistribution),
        state->countComparison);
    [diagnosticsRoot setEnabled:included && model.fit.ok];
    [menu addItem:diagnosticsRoot];

    NSMenuItem *copyRoot = [[NSMenuItem alloc] initWithTitle:@"Copy" action:nil keyEquivalent:@""];
    NSMenu *copyMenu = [[NSMenu alloc] initWithTitle:@"Copy"];
    NSString *value = [self displayForTerm:state->termRows[(size_t)termRow]
                              modelColumn:modelColumn] ?: @"";
    NSMenuItem *copyValue = [[NSMenuItem alloc] initWithTitle:@"Value"
        action:@selector(copyComparisonCellValue:) keyEquivalent:@""];
    [copyValue setTarget:self]; [copyValue setRepresentedObject:value];
    NSMenuItem *copyNamed = [[NSMenuItem alloc] initWithTitle:@"Predictor and value"
        action:@selector(copyComparisonCellValue:) keyEquivalent:@""];
    [copyNamed setTarget:self];
    [copyNamed setRepresentedObject:[NSString stringWithFormat:@"%@\t%@", ToNSString(baseTerm), value]];
    [copyMenu addItem:copyValue]; [copyMenu addItem:copyNamed];
    [copyRoot setSubmenu:copyMenu]; [menu addItem:copyRoot];
    return menu;
}

- (void)openGeneralizedComparisonPairwise:(id)sender
{
    GeneralizedComparisonState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || !represented || _selectedModelColumn < 0 ||
        static_cast<std::size_t>(_selectedModelColumn) >= state->models.size()) return;
    const std::string term([represented UTF8String]);
    const GeneralizedComparisonModel &model =
        state->models[static_cast<std::size_t>(_selectedModelColumn)];
    const MainRGeneralizedGLMTask task =
        GeneralizedGLMTaskForComparisonModel(*state, model);
    const auto type = task.termTypes.find(term);
    if (type == task.termTypes.end() ||
        (type->second != "factor" && type->second != "ordered") ||
        std::find(task.terms.begin(), task.terms.end(), term) == task.terms.end()) {
        [_statusField setStringValue:@"Status: pairwise comparisons require an included categorical term."];
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    std::string message;
    if (!RunRBackedMIPairwiseComparisons(
            dataframe, "gglm_pairwise", "gglm_pairwise_" + model.id,
            task.response, task.terms, task.scope,
            EncodeStandaloneGeneralizedMISpec(task), term, &result, &message)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink link = BuildGLMPairwiseComparisonPlotLink(
        state->group, dataframe, task.response, term, model.fit.rowsUsed, result);
    link.sourceModelKind = "generalized_comparison";
    link.sourceModelId = model.id;
    link.sourceModelRevision = model.modelVersion;
    link.sourceFitVersion = model.fitVersion;
    link.method = result.method;
    link.levels = result.levels;
    link.multipleImputation = true;
    link.poolingMethod = result.method;
    ShowGLMPairwiseResultsWindowOnMain(term, result, link);
    [_statusField setStringValue:ToNSString(
        "Pairwise comparisons calculated across all fitted imputations for " + model.label + ".")];
}

- (void)openGeneralizedComparisonInteraction:(id)sender
{
    GeneralizedComparisonState *state = [self state];
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (!state || !represented || _selectedModelColumn < 0 ||
        static_cast<std::size_t>(_selectedModelColumn) >= state->models.size()) return;
    const std::string term([represented UTF8String]);
    const GeneralizedComparisonModel &model =
        state->models[static_cast<std::size_t>(_selectedModelColumn)];
    const MainRGeneralizedGLMTask task =
        GeneralizedGLMTaskForComparisonModel(*state, model);
    if (!rlispstat::core::GeneralizedModelIncludesTerm(model, term)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(
            rlispstat::core::ComparisonInteractionNotIncludedMessage(term, model.label)))];
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = "generalized_comparison";
    link.sourceModelId = model.id;
    link.sourceModelRevision = model.modelVersion;
    link.sourceFitVersion = model.fitVersion;
    link.group = state->group;
    link.term = term;
    link.binaryEffect = task.binaryRegression;
    link.boundedCountEffect = task.countRegression &&
        (task.countDistribution == "binomial_trials" ||
         task.countDistribution == "beta_binomial" ||
         task.countDistribution == "hurdle_beta_binomial_ceiling" ||
         task.countDistribution == "perfect_score");
    if (task.countDistribution == "hurdle_beta_binomial_ceiling")
        link.effectQuantity = "overall_expected_score";
    else if (task.countDistribution == "perfect_score")
        link.effectQuantity = "predicted_probability";
    else if (link.boundedCountEffect) link.effectQuantity = "expected_count";
    link.title = "Effect: " + term + " (" + model.label + ")";
    std::string body;
    std::string message;
    if (!RunRBackedMIInteractionReport(
            dataframe, "gglm_interaction", "gglm_interaction_" + model.id,
            task.response, task.terms, task.scope,
            EncodeStandaloneGeneralizedMISpec(task), term, &body, &message,
            std::numeric_limits<double>::quiet_NaN(), link)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    ShowGLMInteractionReportWindowOnMain(link.title, body, link);
    [_statusField setStringValue:ToNSString(
        "Interaction interpreted across all fitted imputations for " + model.label + ".")];
}

