    link.sourceModelRevision = model.modelVersion;
    link.sourceFitVersion = model.fitVersion;
    link.group = state->group;
    link.term = term;
    link.title = "Partial regression plot: " + term + " (" + model.label + ")";
    std::string message;
    const std::string residualType = model.diagnosticOptions.residualType.empty()
        ? "working" : model.diagnosticOptions.residualType;
