- (void)showTypeMenuForSelectedTerm:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    std::string type = rlispstat::core::GeneralizedComparisonModelTermType(
        *state, _selectedModelColumn, term);
    if (rlispstat::core::ModelTermTypeIsInteraction(type)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::TermTypeMenuTitle())];
    AddModelTermTypeMenuItems(menu, self, @selector(comparisonTypeMenuSelected:), type);
    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    NSRect rowRect = layout.termRect(_selectedTermRow);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMinX(rowRect) + 20.0, NSMaxY(rowRect)) inView:_reportView];
}

- (void)comparisonTypeMenuSelected:(id)sender
{
    NSString *mode = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    std::string term = GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    if (IsInteractionTerm(term)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    std::string type = (mode && [mode isEqualToString:@"factor"]) ? "factor" : "numeric";
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    rlispstat::core::ModelSpecification preview = rlispstat::core::EffectiveGeneralizedComparisonModelSpecification(
        *state, state->models[(size_t)_selectedModelColumn]);
    const auto validation = rlispstat::core::SetModelSpecificationTermType(
        preview, term, type, metadata);
    if (!validation.ok) {
        [_statusField setStringValue:ToNSString(validation.message)];
        return;
    }
    if (rlispstat::core::ApplyGeneralizedComparisonTermType(
            *state, _selectedModelColumn, term, type, metadata)) {
        [self refitModelColumn:_selectedModelColumn];
        [self refresh];
        [_statusField setStringValue:ToNSString(GLMTermTypeChangedStatus(term, type))];
    }
}

- (void)toggleCenterSelectedPredictor:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const std::string sourceTerm = GeneralizedComparisonSourceTerm(
        *state, state->termRows[(size_t)_selectedTermRow]);
    const std::string term = rlispstat::core::BaseVariableForTermComponent(sourceTerm);
    if (IsInteractionTerm(sourceTerm) ||
        rlispstat::core::GeneralizedComparisonModelTermType(*state, _selectedModelColumn, term) == "factor") return;
    if (rlispstat::core::ToggleGeneralizedComparisonPredictorCentering(
            *state, _selectedModelColumn, term)) {
        [self refitModelColumn:_selectedModelColumn];
        [self refresh];
    }
}

- (void)showReferenceMenuForSelectedTerm:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    const std::string term = rlispstat::core::BaseVariableForTermComponent(
        GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]));
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    if (metadata.levels.empty()) return;
    const GeneralizedComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    auto found = model.factorReferenceLevels.find(term);
    const std::string current = found == model.factorReferenceLevels.end()
        ? metadata.levels.front() : found->second;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Reference category"];
    for (const std::string &level : metadata.levels) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(level)
            action:@selector(comparisonReferenceMenuSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(level)];
        [item setState:level == current ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    GeneralizedComparisonLayout layout(state->showInformationCriteria, state->binaryComparison);
    NSRect rowRect = layout.termRect(_selectedTermRow);
    [menu popUpMenuPositioningItem:nil
        atLocation:NSMakePoint(NSMinX(rowRect) + 20.0, NSMaxY(rowRect)) inView:_reportView];
}

- (void)comparisonReferenceMenuSelected:(id)sender
{
    NSString *selected = [sender representedObject];
    GeneralizedComparisonState *state = [self state];
    if (!selected || !state || _selectedTermRow <= 0 ||
        (size_t)_selectedTermRow >= state->termRows.size() || _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    const std::string term = rlispstat::core::BaseVariableForTermComponent(
        GeneralizedComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]));
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(state->group, dataframe)) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        state->seed, &dataframe, term);
    if (rlispstat::core::ApplyGeneralizedComparisonReferenceLevel(
            *state, _selectedModelColumn, term, [selected UTF8String], metadata.levels)) {
        [self refitModelColumn:_selectedModelColumn];
        [self refresh];
    }
}

- (void)responseChanged:(id)sender
{
    NSString *name = [_responsePopup titleOfSelectedItem];
    if (!name) return;
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    const std::string newResponse = [name UTF8String];
    state->response = newResponse;
    if (state->binaryComparison) {
        const DataColumn *column = FindDataColumnForModel(&state->seed, state->response);
        state->responseCoding = column ? rlispstat::core::InspectBinaryResponse(*column)
                                       : rlispstat::core::BinaryResponseCoding{};
        state->family = "binomial";
        state->link = rlispstat::core::BinaryLinkId(state->binaryLink);
    } else if (!state->countComparison && state->modelType ==
               rlispstat::core::StatisticalModelType::LegacyGeneralized) {
        state->family = DefaultGeneralizedFamilyForResponse(state->seed, state->response);
        state->link = DefaultGeneralizedLink(state->family);
    }
    for (GeneralizedComparisonModel &model : state->models) {
        rlispstat::core::SetModelSpecificationResponse(model, newResponse);
        if (model.exposure == newResponse) model.exposure.clear();
        if (model.offsetVariable == newResponse) model.offsetVariable.clear();
        model.family = state->family;
        model.link = state->link;
        model.candidateTerms.erase(std::remove_if(
            model.candidateTerms.begin(), model.candidateTerms.end(),
            [&](const std::string &term) {
                return rlispstat::core::ModelTermShouldBeRemoved(term, newResponse);
            }), model.candidateTerms.end());
        model.interactionImpliedTerms.clear();
        rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
    }
    RefreshGeneralizedTermRowsFromFits(*state);
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)generalizedFamilyChanged:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    NSString *selected = [[_eventPopup selectedItem] representedObject];
    if (!state || state->binaryComparison || state->countComparison || !selected) return;
    if (rlispstat::core::SetGeneralizedComparisonFamily(*state, [selected UTF8String])) {
        if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
        else RefreshGeneralizedTermRowsFromFits(*state);
    }
    [self refresh];
}

- (void)generalizedLinkChanged:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    NSString *selected = [_linkPopup titleOfSelectedItem];
    if (!state || state->binaryComparison || state->countComparison || !selected) return;
    if (rlispstat::core::SetGeneralizedComparisonLink(*state, [selected UTF8String])) {
        if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
        else RefreshGeneralizedTermRowsFromFits(*state);
    }
    [self refresh];
}

- (void)binaryEventChanged:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    NSString *selected = [_eventPopup titleOfSelectedItem];
    if (!state || !state->binaryComparison || !selected) return;
    if (std::string([selected UTF8String]) == state->responseCoding.referenceLabel) {
        std::swap(state->responseCoding.eventValue, state->responseCoding.referenceValue);
        std::swap(state->responseCoding.eventLabel, state->responseCoding.referenceLabel);
        std::swap(state->responseCoding.eventCount, state->responseCoding.referenceCount);
    }
    for (GeneralizedComparisonModel &model : state->models) {
        rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
    }
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)binaryLinkChanged:(id)sender
{
    (void)sender;
    GeneralizedComparisonState *state = [self state];
    NSString *selected = [_linkPopup titleOfSelectedItem];
    rlispstat::core::BinaryLink link;
    if (!state || !state->binaryComparison || !selected ||
        !rlispstat::core::ParseBinaryLink(std::string([selected UTF8String]), link)) return;
    state->binaryLink = link;
    state->link = rlispstat::core::BinaryLinkId(link);
    for (GeneralizedComparisonModel &model : state->models) {
        model.family = "binomial";
        model.link = state->link;
        rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
    }
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)scopeChanged:(id)sender
{
    (void)sender; // Scope is configured only through the global Analysis Scope menu.
}

- (void)autoRefitChanged:(id)sender
{
    GeneralizedComparisonState *state = [self state];
    if (!state) return;
    state->autoRefit = [_autoRefitButton state] == NSControlStateValueOn;
    // Re-enabling Auto-refit is also an explicit retry.  A previous fit error
    // may have a non-zero fitVersion, so the normal stale-only path is not
    // sufficient to restart it.
    if (state->autoRefit) RefitGeneralizedComparisonModels(*state, true);
    [self refresh];
}

- (void)windowDidResize:(NSNotification *)notification
{
    (void)notification;
    [self refresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    int pendingGeneration = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto found = g_generalizedComparisons.find(_comparisonId);
        if (found != g_generalizedComparisons.end() && found->second.rFitPending) {
            pendingGeneration = found->second.rFitGeneration;
            found->second.rFitPending = false;
        }
    }
    if (pendingGeneration > 0) {
        AcknowledgeGeneralizedComparisonMainRTask(
            _comparisonId, pendingGeneration);
    }
    g_generalizedComparisonControllers.erase(_comparisonId);
}
@end

struct RegressionComparisonLayout {
    CGFloat margin = 14.0;
    // Keep full factor-contrast interaction labels visible in comparisons.
    CGFloat termWidth = 340.0;
    CGFloat modelWidth = 140.0;
    CGFloat addModelWidth = 106.0;
    CGFloat headerHeight = 48.0;
    CGFloat rowHeight = 24.0;
    CGFloat gapAfterTerms = 10.0;
    CGFloat noteHeight = 28.0;
    int fitRows = 13;

    explicit RegressionComparisonLayout(bool showInformationCriteria = false)
        : fitRows((int)rlispstat::core::RegressionComparisonVisibleFitRows(
              showInformationCriteria).size()) {}

    CGFloat width(int modelCount) const
    {
        return margin * 2.0 + termWidth + modelWidth * (CGFloat)modelCount + addModelWidth;
    }

    CGFloat height(int termCount) const
    {
        return margin * 2.0 + headerHeight + rowHeight * ((CGFloat)termCount + 1.0) +
               gapAfterTerms + rowHeight * (CGFloat)fitRows + noteHeight;
    }

    NSRect termRect(int row) const
    {
        return NSMakeRect(margin, margin + headerHeight + rowHeight * (CGFloat)row, termWidth, rowHeight);
    }

    NSRect modelHeaderRect(int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex, margin, modelWidth, headerHeight);
    }

    NSRect addModelRect(int modelCount) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelCount, margin, addModelWidth, headerHeight);
    }

    NSRect coefficientRect(int row, int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex,
                          margin + headerHeight + rowHeight * (CGFloat)row,
                          modelWidth, rowHeight);
    }

    CGFloat fitStartY(int termCount) const
    {
        return margin + headerHeight + rowHeight * ((CGFloat)termCount + 1.0) + gapAfterTerms;
    }

    NSRect fitLabelRect(int fitRow, int termCount) const
    {
        return NSMakeRect(margin, fitStartY(termCount) + rowHeight * (CGFloat)fitRow, termWidth, rowHeight);
    }

    NSRect fitValueRect(int fitRow, int termCount, int modelIndex) const
    {
        return NSMakeRect(margin + termWidth + modelWidth * (CGFloat)modelIndex,
                          fitStartY(termCount) + rowHeight * (CGFloat)fitRow,
                          modelWidth, rowHeight);
    }
};

@interface RegressionComparisonWindowController : NSObject <NSWindowDelegate>
{
    std::string _comparisonId;
    NSWindow *_window;
    NSPopUpButton *_responsePopup;
    NSPopUpButton *_scopePopup;
    NSButton *_autoRefitButton;
    NSTextField *_titleField;
    NSTextField *_badgeField;
    NSTextField *_responseStaticLabel;
    NSTextField *_scopeStaticLabel;
    NSTextField *_selectedRowsField;
    NSTextField *_statusField;
    NSScrollView *_scrollView;
    NSView *_reportView;
    int _selectedTermRow;
    int _selectedModelColumn;
    int _selectedFitRow;
}
