- (void)removeSelectedTermFromComparison:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
        return;
    }
    const std::string term = RegressionComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    // A menu deletion removes the term from the comparison itself.  Only the
    // +/- cell control performs a column-local exclusion while retaining a
    // candidate row.
    if (!RemoveRegressionComparisonTermCompletely(*state, term)) return;
    _selectedTermRow = -1;
    if (state->precomputed && state->multipleImputation) {
        if (state->autoRefit) {
            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("after removing " + term + " from the comparison"))];
        } else {
            RefreshRegressionTermRowsFromFits(*state);
            [self refresh];
        }
    } else {
        for (size_t i = 0; i < state->models.size(); ++i) {
            if (state->models[i].isStale) [self refitModelColumn:(int)i];
        }
        [self refresh];
    }
}

- (void)showCoefficientDetails:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow < 0 || (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string displayTerm = state->termRows[(size_t)_selectedTermRow];
    const std::string term = RegressionComparisonSourceTerm(*state, displayTerm);
    const GLMCoefficientRow *coef = CoefficientForTerm(model.fit, displayTerm);
    if (!coef) {
        std::vector<GLMCoefficientRow> rows = CoefficientsForSourceTerm(model.fit, term);
        if (rows.empty()) {
            [_statusField setStringValue:ToNSString(ComparisonTermNotIncludedStatus())];
            return;
        }
        [_statusField setStringValue:ToNSString(RegressionCoefficientGroupDetailsStatus(rows))];
        return;
    }
    NSMutableAttributedString *detail = [[NSMutableAttributedString alloc] init];
    std::string structuralStatus = RegressionCoefficientStructuralDetailsStatus(*coef);
    if (!structuralStatus.empty()) {
        [_statusField setStringValue:ToNSString(structuralStatus)];
        return;
    }
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMCoefBHeader()), ToNSString(" = " + FormatDoubleOrDash(coef->estimate, 4)), YES);
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMRegressionBetaLabel()),
                                std::isfinite(coef->standardizedBeta)
                                    ? ToNSString(" = " + FormatDoubleOrDash(coef->standardizedBeta, 3))
                                    : @" = \u2014",
                                YES);
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMCoefSEHeader()), ToNSString(" = " + FormatDoubleOrDash(coef->stdError, 4)), YES);
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMCoefStatisticHeader()), ToNSString(" = " + FormatDoubleOrDash(coef->tValue, 3)), YES);
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMCoefPHeader()), RegressionDetailP(coef->pValue), YES);
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMRegressionPartialRLabel()),
                                ToNSString(" = " + FormatDoubleOrDash(coef->partialR, 3)), YES);
    AppendRegressionDetailField(detail, ToNSString(rlispstat::core::GLMRegressionDeltaRSquaredLabel()),
                                ToNSString(" = " + FormatDoubleOrDash(coef->deltaR2, 3)), NO);
    [_statusField setAttributedStringValue:detail];
}

- (void)toggleCenterSelectedPredictor:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 ||
        (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(
            rlispstat::core::PrecomputedComparisonChangeInRStatus("centering predictors"))];
        return;
    }
    const std::string term = RegressionComparisonSourceTerm(
        *state, state->termRows[(size_t)_selectedTermRow]);
    if (term.empty() || IsInteractionTerm(term) ||
        rlispstat::core::RegressionComparisonModelTermType(
            *state, _selectedModelColumn, term) == "factor") return;
    RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    if (std::find(model.terms.begin(), model.terms.end(), term) ==
        model.terms.end()) {
        [_statusField setStringValue:ToNSString(ComparisonTermNotIncludedStatus())];
        return;
    }
    if (!rlispstat::core::ToggleRegressionComparisonPredictorCentering(
            *state, _selectedModelColumn, term)) return;
    [self refitModelColumn:_selectedModelColumn];
    [self refresh];
    [_statusField setStringValue:ToNSString(
        (model.centeredPredictors.count(term) ? "Centered " : "Stopped centering ") +
        term + " in " + model.label + ".")];
}

- (void)openPairwiseComparisonsForSelectedTerm:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 ||
        (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string term = RegressionComparisonSourceTerm(
        *state, state->termRows[(size_t)_selectedTermRow]);
    const std::string response = model.response.empty() ? state->response : model.response;
    const rlispstat::core::ModelSpecification specification =
        rlispstat::core::EffectiveRegressionComparisonModelSpecification(*state, model);
    DataFrameModel dataframe;
    bool hasDataframe = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(state->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    rlispstat::core::GLMPairwiseComparisonRequest request;
    request.term = term;
    const auto termTypes = rlispstat::core::RegressionComparisonModelTermTypes(*state, model);
    rlispstat::core::GLMPairwiseComparisonEligibility eligibility =
        rlispstat::core::EvaluateGLMPairwiseComparisonEligibility(
            state->seed, hasDataframe ? &dataframe : nullptr, response,
            model.terms, termTypes, model.fit, request);
    const auto type = termTypes.find(term);
    const bool miFactorEligible = state->multipleImputation &&
        type != termTypes.end() &&
        (type->second == "factor" || type->second == "ordered") &&
        std::find(specification.terms.begin(), specification.terms.end(), term) !=
            specification.terms.end() && !IsInteractionTerm(term);
    if (!eligibility.eligible && !miFactorEligible) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(eligibility.message))];
        return;
    }
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    result.levels = eligibility.levels;
    std::string message;
    const std::string scope = ScopeForCapturedAnalysisScope(
        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneLinearMISpec(
        specification.termTypes, specification.centeredPredictors,
        specification.factorReferenceLevels,
        RowsForCapturedAnalysisScope(state->dataScope, state->dataScopeCaptured));
    const bool ok = state->multipleImputation
        ? RunRBackedMIPairwiseComparisons(
            dataframe, "glm_pairwise", "glm_pairwise_" + model.id,
            response, specification.terms, scope, modelSpec, term, &result, &message)
        : RunRBackedGLMPairwiseComparisons(
            dataframe, &state->seed, response, specification.terms,
            termTypes, model.fit, request, &result, &message);
    if (!ok) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink plotLink = BuildGLMPairwiseComparisonPlotLink(
        state->group, dataframe, response, term, model.fit.rowsUsed, result);
    plotLink.sourceModelKind = "linear_comparison";
    plotLink.sourceModelId = model.id;
    plotLink.sourceModelRevision = model.modelVersion;
    plotLink.sourceFitVersion = model.fitVersion;
    plotLink.multipleImputation = state->multipleImputation;
    plotLink.poolingMethod = state->multipleImputation ? result.method : std::string();
    ShowGLMPairwiseResultsWindowOnMain(term, result, plotLink);
    [_statusField setStringValue:ToNSString(
        "Pairwise comparisons calculated for " + term + " in " + model.label + ".")];
}

- (void)openInteractionReportForSelectedTerm:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 ||
        (size_t)_selectedTermRow >= state->termRows.size() ||
        _selectedModelColumn < 0 ||
        (size_t)_selectedModelColumn >= state->models.size()) return;
    RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    const std::string term = RegressionComparisonSourceTerm(
        *state, state->termRows[(size_t)_selectedTermRow]);
    const std::string response = model.response.empty() ? state->response : model.response;
    const rlispstat::core::ModelSpecification specification =
        rlispstat::core::EffectiveRegressionComparisonModelSpecification(*state, model);
    if (!rlispstat::core::ModelIncludesTerm(model, term)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(
            rlispstat::core::ComparisonInteractionNotIncludedMessage(term, model.label)))];
        return;
    }
    DataFrameModel dataframe;
    bool hasDataframe = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(state->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    RegressionInteractionDerivedLink derivedLink;
    derivedLink.sourceModelKind = "linear_comparison";
    derivedLink.sourceModelId = model.id;
    derivedLink.sourceModelRevision = model.modelVersion;
    derivedLink.sourceFitVersion = model.fitVersion;
    derivedLink.group = state->group;
    derivedLink.term = term;
    const bool simpleEffect = !IsInteractionTerm(term);
    derivedLink.title = "Effect: " + term + " (" + model.label + ")";
    const std::string scope = ScopeForCapturedAnalysisScope(
        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneLinearMISpec(
        specification.termTypes, specification.centeredPredictors,
        specification.factorReferenceLevels,
        RowsForCapturedAnalysisScope(state->dataScope, state->dataScopeCaptured));
    std::string body;
    std::string message;
    if (!hasDataframe || !RunRBackedMIInteractionReport(
            dataframe, "glm_interaction", "glm_interaction_" + model.id,
            response, specification.terms, scope, modelSpec, term,
            &body, &message)) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    ShowGLMInteractionReportWindowOnMain(derivedLink.title, body, derivedLink);
    [_statusField setStringValue:ToNSString(state->multipleImputation
        ? "Interaction interpreted across all imputations for " + model.label + "."
        : "Interaction interpreted in R for " + model.label + ".")];
}

