        state->dataScope, state->dataScopeCaptured, state->scope);
    const std::string modelSpec = EncodeStandaloneLinearMISpec(
        specification.termTypes, specification.centeredPredictors,
        specification.factorReferenceLevels,
        RowsForCapturedAnalysisScope(state->dataScope, state->dataScopeCaptured));
