- (void)duplicateSelectedModel:(id)sender
{
    (void)sender;
    [self addModelColumn:self];
}

- (void)deleteSelectedModel:(id)sender
{
    (void)sender;
	    RegressionComparisonState *state = [self state];
	    if (!state || state->models.size() <= 1 || _selectedModelColumn < 0 ||
	        (size_t)_selectedModelColumn >= state->models.size()) return;
	    if (state->precomputed && !state->multipleImputation) {
	        [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("comparison"))];
	        return;
	    }
	    if (!DeleteRegressionComparisonModel(*state, _selectedModelColumn)) return;
	    _selectedModelColumn = state->activeModel;
	    _selectedTermRow = -1;
	    _selectedFitRow = -1;
	    if (state->precomputed && state->multipleImputation) {
	        if (state->autoRefit) {
	            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("after deleting a model"))];
	        } else {
	            RefreshRegressionTermRowsFromFits(*state);
	            [self refresh];
	        }
	    } else {
	        [self refresh];
	    }
}

- (void)renameSelectedModel:(id)sender
{
	    (void)sender;
	    RegressionComparisonState *state = [self state];
	    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
	    NSAlert *alert = [[NSAlert alloc] init];
	    [alert setMessageText:ToNSString(rlispstat::core::GLMRenameModelTitle())];
    NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 220, 24)];
    [field setStringValue:ToNSString(state->models[(size_t)_selectedModelColumn].label)];
    [alert setAccessoryView:field];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::GLMRenameModelTitle())];
    [alert addButtonWithTitle:ToNSString(rlispstat::core::AlertCancelButtonTitle())];
	    if ([alert runModal] == NSAlertFirstButtonReturn) {
	        state->models[(size_t)_selectedModelColumn].label = [[field stringValue] UTF8String];
	        [self refresh];
	        [_statusField setStringValue:ToNSString(RegressionComparisonModelRenamedStatus())];
	    }
	}

- (void)openSelectedModelAsGLM:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedModelColumn < 0 || (size_t)_selectedModelColumn >= state->models.size()) return;
    RegressionComparisonModel &model = state->models[(size_t)_selectedModelColumn];
    if (state->precomputed && !model.fit.ok) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(model.fit.warning))];
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &glm = EnsureGroupModelUnlocked(state->group, &state->seed);
        static_cast<rlispstat::core::ModelSpecification &>(glm) =
            rlispstat::core::EffectiveRegressionComparisonModelSpecification(*state, model);
        if (state->precomputed) {
            glm.precomputed = true;
            glm.multipleImputation = state->multipleImputation;
            glm.imputationCount = state->imputationCount;
            glm.title = model.label.empty() ? "General Linear Model" : ("General Linear Model - " + model.label);
            glm.note = state->note.empty()
                ? "Pooled/precomputed linear model opened from model comparison."
                : state->note;
            glm.modelVersion += 1;
            glm.fitVersion += 1;
            glm.diagnosticsVersion += 1;
            glm.isStale = false;
            glm.diagnostics = model.fit.diagnostics;
            glm.rowsUsed = model.fit.rowsUsed;
            glm.rowsExcluded = model.fit.rowsExcluded;
            g_precomputedLinearModelFits[state->group] = model.fit;
        } else {
            rlispstat::core::MarkGroupModelChanged(glm);
        }
    }
    ShowGLMOnMain(&state->seed, true);
    [_statusField setStringValue:ToNSString(RegressionComparisonOpenedSingleModelStatus(model.label))];
}

- (NSMenu *)contextMenuForModelColumn:(int)modelColumn
{
    _selectedModelColumn = modelColumn;
    _selectedFitRow = -1;
    RegressionComparisonState *state = [self state];
    if (state) SetRegressionComparisonActiveModel(*state, modelColumn);
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    const BOOL canEdit = state && (!state->precomputed || state->multipleImputation);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.model)];
    if (state && modelColumn >= 0 && (size_t)modelColumn < state->models.size())
        AddMissingInformationMenu(menu, state->id);

    NSMenuItem *modelRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.model) action:nil keyEquivalent:@""];
    NSMenu *modelMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.model)];
    [modelMenu addItem:[self comparisonMenuItem:ToNSString(rlispstat::core::GLMRenameModelTitle()) action:@selector(renameSelectedModel:) represented:nil]];
    NSMenuItem *duplicate = [self comparisonMenuItem:ToNSString(rlispstat::core::GLMDuplicateModelTitle()) action:@selector(duplicateSelectedModel:) represented:nil];
    NSMenuItem *remove = [self comparisonMenuItem:ToNSString(rlispstat::core::GLMDeleteModelTitle()) action:@selector(deleteSelectedModel:) represented:nil];
    [duplicate setEnabled:canEdit];
    [remove setEnabled:canEdit && state && state->models.size() > 1];
    [modelMenu addItem:duplicate];
    [modelMenu addItem:remove];
    [modelRoot setSubmenu:modelMenu];
    [menu addItem:modelRoot];

    NSMenuItem *termsRoot = [[NSMenuItem alloc] initWithTitle:@"Model terms" action:nil keyEquivalent:@""];
    NSMenu *termsMenu = [[NSMenu alloc] initWithTitle:@"Model terms"];
    NSMenuItem *addPredictor = [self comparisonMenuItem:ToNSString(titles.addTermAction) action:@selector(addTerm:) represented:nil];
    [addPredictor setEnabled:canEdit];
    [termsMenu addItem:addPredictor];
    [termsRoot setSubmenu:termsMenu];
    [menu addItem:termsRoot];

    NSMenuItem *fitRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.modelFit) action:nil keyEquivalent:@""];
    NSMenu *fitMenu = [[NSMenu alloc] initWithTitle:ToNSString(titles.modelFit)];
    NSMenuItem *refit = [self comparisonMenuItem:ToNSString(titles.refitActiveModel) action:@selector(refitSelectedModel:) represented:nil];
    [refit setEnabled:canEdit];
    [fitMenu addItem:refit];
    NSMenuItem *autoRefit = [self comparisonMenuItem:ToNSString(rlispstat::core::AutoRefitMenuTitle(state && state->autoRefit)) action:@selector(toggleAutoRefitFromMenu:) represented:nil];
    [autoRefit setEnabled:state && (!state->precomputed || state->multipleImputation)];
    [autoRefit setState:state && state->autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
    [fitMenu addItem:autoRefit];
    NSMenuItem *informationCriteria = [self comparisonMenuItem:@"Information criteria" action:@selector(toggleInformationCriteria:) represented:nil];
    [informationCriteria setState:state && state->showInformationCriteria ? NSControlStateValueOn : NSControlStateValueOff];
    [fitMenu addItem:informationCriteria];
    [fitRoot setSubmenu:fitMenu];
    [menu addItem:fitRoot];

    NSMenuItem *diagnosticsItem = ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), false);
    NSMenu *diagMenu = [diagnosticsItem submenu];
    [diagMenu addItem:[NSMenuItem separatorItem]];
    [diagMenu addItem:[self comparisonMenuItem:ToNSString(titles.rowsUsedExcluded) action:@selector(showRowsUsedExcluded:) represented:nil]];
    [menu addItem:diagnosticsItem];
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.openAsSingleGLM) action:@selector(openSelectedModelAsGLM:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

- (void)modelHeaderClickedMenu:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (state && _selectedModelColumn >= 0 && (size_t)_selectedModelColumn < state->models.size()) {
        SetRegressionComparisonActiveModel(*state, _selectedModelColumn);
        [self refresh];
    }
}

- (void)toggleInformationCriteria:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state) return;
    state->showInformationCriteria = !state->showInformationCriteria;
    [self refresh];
}

- (NSMenu *)contextMenuForTermRow:(int)termRow modelColumn:(int)modelColumn
{
    _selectedTermRow = termRow;
    _selectedModelColumn = modelColumn;
    RegressionComparisonState *state = [self state];
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.coefficient)];
    if (state && termRow > 0 && (size_t)termRow < state->termRows.size()) {
        BOOL canEditTerms = (!state->precomputed || state->multipleImputation);
        const std::string baseTerm = RegressionComparisonSourceTerm(*state, state->termRows[(size_t)termRow]);
        const std::string termType = rlispstat::core::RegressionComparisonModelTermType(
            *state, modelColumn, baseTerm);
        const bool interaction = IsInteractionTerm(baseTerm);
        const bool inModel = modelColumn >= 0 && (size_t)modelColumn < state->models.size() &&
            std::find(state->models[(size_t)modelColumn].terms.begin(),
                      state->models[(size_t)modelColumn].terms.end(), baseTerm) !=
                state->models[(size_t)modelColumn].terms.end();

        NSMenuItem *remove = [[NSMenuItem alloc]
            initWithTitle:(interaction ? @"Remove interaction from comparison"
                : @"Remove predictor from comparison")
            action:@selector(removeSelectedTermFromComparison:) keyEquivalent:@""];
        [remove setTarget:self];
        [remove setEnabled:canEditTerms];
        [menu addItem:remove];
        [menu addItem:[NSMenuItem separatorItem]];

        NSMenuItem *analyzeRoot = [[NSMenuItem alloc] initWithTitle:@"Analyze predictor" action:nil keyEquivalent:@""];
        NSMenu *analyzeMenu = [[NSMenu alloc] initWithTitle:@"Analyze predictor"];
        NSMenuItem *details = [self comparisonMenuItem:ToNSString(titles.showCoefficientDetails) action:@selector(showCoefficientDetails:) represented:nil];
        [analyzeMenu addItem:details];
        [analyzeMenu addItem:[self comparisonMenuItem:ToNSString(titles.explainStatistic)
            action:@selector(explainComparisonStatistic:) represented:@"b"]];
        if (!interaction && termType == "factor") {
            NSMenuItem *pairwise = [self comparisonMenuItem:@"Pairwise comparisons…" action:@selector(openPairwiseComparisonsForSelectedTerm:) represented:nil];
            [pairwise setEnabled:inModel && state->models[(size_t)modelColumn].fit.ok];
            [analyzeMenu addItem:pairwise];
        }
        if (!interaction) {
            NSMenuItem *effect = [self comparisonMenuItem:@"Effect plot…"
                action:@selector(openInteractionPlotForSelectedTerm:)
                represented:nil];
            [effect setEnabled:inModel && state->models[(size_t)modelColumn].fit.ok];
            [analyzeMenu addItem:effect];
            NSMenuItem *partial = [self comparisonMenuItem:@"Partial regression plot…"
                action:@selector(openPartialRegressionPlotForSelectedTerm:)
                represented:nil];
            [partial setEnabled:inModel && state->models[(size_t)modelColumn].fit.ok];
            [analyzeMenu addItem:partial];
        }
        if (interaction) {
            NSMenuItem *interpret = [self comparisonMenuItem:@"Interpret interaction…" action:@selector(openInteractionReportForSelectedTerm:) represented:nil];
            [interpret setEnabled:!inModel || state->models[(size_t)modelColumn].fit.ok];
            [analyzeMenu addItem:interpret];
            NSMenuItem *plot = [self comparisonMenuItem:@"Effect plot…" action:@selector(openInteractionPlotForSelectedTerm:) represented:nil];
            [plot setEnabled:!inModel || state->models[(size_t)modelColumn].fit.ok];
            [analyzeMenu addItem:plot];
        }
        [analyzeRoot setSubmenu:analyzeMenu];
        [menu addItem:analyzeRoot];

        NSMenuItem *modelTermsRoot = [[NSMenuItem alloc] initWithTitle:@"Model terms" action:nil keyEquivalent:@""];
        NSMenu *modelTermsMenu = [[NSMenu alloc] initWithTitle:@"Model terms"];
        NSMenuItem *toggle = [[NSMenuItem alloc]
            initWithTitle:(inModel ? @"Remove term from this model" : @"Add term to this model")
            action:@selector(toggleSelectedTerm:) keyEquivalent:@""];
        [toggle setTarget:self];
        [toggle setEnabled:canEditTerms];
        [modelTermsMenu addItem:toggle];
        NSMenuItem *addAll = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.addTermToAllModels) action:@selector(addSelectedTermToAllModels:) keyEquivalent:@""];
        [addAll setTarget:self];
        [addAll setEnabled:canEditTerms];
        [modelTermsMenu addItem:addAll];
        std::vector<std::string> interactionBase;
        if (modelColumn >= 0 && (size_t)modelColumn < state->models.size()) {
            interactionBase = state->models[(size_t)modelColumn].terms;
        }
        std::string response = state->response;
        if (modelColumn >= 0 && (size_t)modelColumn < state->models.size() &&
            !state->models[(size_t)modelColumn].response.empty()) {
            response = state->models[(size_t)modelColumn].response;
        }
        std::vector<std::vector<std::string>> comparisonTerms;
        for (const RegressionComparisonModel &model : state->models) comparisonTerms.push_back(model.terms);
        if (canEditTerms) {
            AddComparisonModelTermMenuItems(modelTermsMenu, self, @selector(addTermFromMenu:),
                &state->seed, response, comparisonTerms, interactionBase, baseTerm);
        }
        [modelTermsRoot setSubmenu:modelTermsMenu];
        [menu addItem:modelTermsRoot];

        if (!interaction) {
            NSMenuItem *editRoot = [[NSMenuItem alloc] initWithTitle:@"Edit predictor" action:nil keyEquivalent:@""];
            NSMenu *editMenu = [[NSMenu alloc] initWithTitle:@"Edit predictor"];
        NSMenuItem *type = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeType) action:@selector(showTypeMenuForSelectedTerm:) keyEquivalent:@""];
        [type setTarget:self];
        [type setEnabled:!state->precomputed];
            [editMenu addItem:type];
            if (termType != "factor") {
                const bool centered = modelColumn >= 0 && (size_t)modelColumn < state->models.size() &&
                    state->models[(size_t)modelColumn].centeredPredictors.count(baseTerm);
                NSMenuItem *center = [self comparisonMenuItem:
                    (centered ? @"Remove centering" : @"Center predictor")
                    action:@selector(toggleCenterSelectedPredictor:) represented:nil];
                [center setEnabled:!state->precomputed && inModel];
                [editMenu addItem:center];
            }
            [editRoot setSubmenu:editMenu];
            [menu addItem:editRoot];
        }

        [menu addItem:ModelDiagnosticPlotsMenuItem(
            self, @selector(openDiagnosticFromMenu:), false)];
    } else {
        [menu addItem:[self comparisonMenuItem:ToNSString(titles.showCoefficientDetails) action:@selector(showCoefficientDetails:) represented:nil]];
        [menu addItem:[self comparisonMenuItem:ToNSString(titles.explainStatistic)
            action:@selector(explainComparisonStatistic:) represented:@"b"]];
    }
    [menu addItem:[self comparisonMenuItem:ToNSString(titles.openSingleGLM) action:@selector(openSelectedModelAsGLM:) represented:nil]];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self comparisonExportMenuItem]];
    return menu;
}

- (void)showTypeMenuForSelectedTerm:(id)sender
{
    (void)sender;
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PooledMITermTypesChangeInRStatus())];
        return;
    }
    std::string term = RegressionComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    std::string type = rlispstat::core::RegressionComparisonModelTermType(
        *state, _selectedModelColumn, term);
    if (rlispstat::core::ModelTermTypeIsInteraction(type)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::TermTypeMenuTitle())];
    AddModelTermTypeMenuItems(menu, self, @selector(comparisonTypeMenuSelected:), type);
    RegressionComparisonLayout layout(state->showInformationCriteria);
    NSRect rowRect = layout.termRect(_selectedTermRow);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMinX(rowRect) + 20.0, NSMaxY(rowRect)) inView:_reportView];
}

- (void)comparisonTypeMenuSelected:(id)sender
{
    NSString *mode = [sender representedObject];
    RegressionComparisonState *state = [self state];
    if (!state || _selectedTermRow <= 0 || (size_t)_selectedTermRow >= state->termRows.size()) return;
    if (state->precomputed) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PooledMITermTypesChangeInRStatus())];
        return;
    }
    std::string term = RegressionComparisonSourceTerm(*state, state->termRows[(size_t)_selectedTermRow]);
    if (IsInteractionTerm(term)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    std::string type = (mode && [mode isEqualToString:@"factor"]) ? "factor" : "numeric";
    std::string message;
    if (!rlispstat::core::ApplyRegressionComparisonTermType(
            *state, _selectedModelColumn, term, type, &message)) {
        if (!message.empty()) [_statusField setStringValue:ToNSString(message)];
        return;
    }
    [self refitModelColumn:_selectedModelColumn];
    [self refresh];
    [_statusField setStringValue:ToNSString(GLMTermTypeChangedStatus(term, type))];
}

- (void)responseChanged:(id)sender
{
    NSString *name = [_responsePopup titleOfSelectedItem];
    if (!name) return;
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (state->precomputed) {
        if (!state->multipleImputation) {
            [_statusField setStringValue:ToNSString(rlispstat::core::PrecomputedComparisonChangeInRStatus("response"))];
            [self refresh];
            return;
        }
        std::string newResponse = [name UTF8String];
        state->response = newResponse;
        state->termRows = FilterModelTermsForResponse(&state->seed, state->termRows, newResponse);
        state->termRows.insert(state->termRows.begin(), "(Intercept)");
        for (RegressionComparisonModel &model : state->models) {
            rlispstat::core::SetModelSpecificationResponse(model, newResponse);
            model.candidateTerms.erase(std::remove_if(
                model.candidateTerms.begin(), model.candidateTerms.end(),
                [&](const std::string &term) {
                    return rlispstat::core::ModelTermShouldBeRemoved(term, newResponse);
                }), model.candidateTerms.end());
        }
        if (state->autoRefit) {
            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus("with response " + newResponse))];
        } else {
            RefreshRegressionTermRowsFromFits(*state);
            [self refresh];
        }
        return;
    }
    state->response = [name UTF8String];
    state->termRows.erase(std::remove(state->termRows.begin(), state->termRows.end(), state->response), state->termRows.end());
    for (RegressionComparisonModel &model : state->models) {
        rlispstat::core::SetModelSpecificationResponse(model, state->response);
        model.candidateTerms.erase(std::remove_if(
            model.candidateTerms.begin(), model.candidateTerms.end(),
            [&](const std::string &term) {
                return rlispstat::core::ModelTermShouldBeRemoved(term, state->response);
            }), model.candidateTerms.end());
        rlispstat::core::InvalidateRegressionComparisonModel(*state, model);
    }
    if (state->autoRefit) RefitRegressionComparisonModels(*state, true);
    for (RegressionComparisonModel &model : state->models) RefreshModelDiagnosticsForModelNow(model.id);
    [self refresh];
}

- (void)scopeChanged:(id)sender
{
    (void)sender; // Scope is configured only through the global Analysis Scope menu.
}

- (void)autoRefitChanged:(id)sender
{
    RegressionComparisonState *state = [self state];
    if (!state) return;
    if (state->precomputed && !state->multipleImputation) {
        [_statusField setStringValue:ToNSString(rlispstat::core::PooledMIAutoRefitDisabledStatus())];
        [self refresh];
        return;
    }
    state->autoRefit = [_autoRefitButton state] == NSControlStateValueOn;
    if (state->autoRefit) {
        if (state->precomputed && state->multipleImputation) {
            [self refitPooledMIComparisonWithStatus:ToNSString(rlispstat::core::PooledMIComparisonRefitStatus())];
        } else {
            RefitRegressionComparisonModels(*state, false);
        }
    }
    [self refresh];
}

- (void)windowDidResize:(NSNotification *)notification
{
    (void)notification;
    [self refresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    g_regressionComparisonControllers.erase(_comparisonId);
}
@end

@implementation GLMWindowController
- (void)positionBesideModelWindow:(GLMWindowController *)other
{
    if (!other) return;
    NSRect frame = [other->_window frame];
    NSRect visible = [[other->_window screen] visibleFrame];
    if (NSIsEmptyRect(visible)) visible = [[NSScreen mainScreen] visibleFrame];
    NSPoint origin = NSMakePoint(NSMinX(frame) + 36.0, NSMinY(frame) - 36.0);
    if (NSMaxX(frame) + 36.0 > NSMaxX(visible)) origin.x = NSMinX(visible) + 36.0;
    if (origin.y < NSMinY(visible)) origin.y = NSMaxY(visible) - NSHeight(frame) - 36.0;
    [_window setFrameOrigin:origin];
}

