            GLMRightLabel(ToNSString(rlispstat::core::GLMGeneralLinearTHeader()), NSMakeRect(14 + layout.coefX[5], 172, layout.coefW[5], 18), 12, NSFontWeightSemibold),
            GLMRightLabel(ToNSString(rlispstat::core::GLMCoefPHeader()), NSMakeRect(14 + layout.coefX[6], 172, layout.coefW[6], 18), 12, NSFontWeightSemibold),
            GLMRightLabel(ToNSString(rlispstat::core::GLMRegressionPartialRLabel()), NSMakeRect(14 + layout.coefX[7], 172, layout.coefW[7], 18), 12, NSFontWeightSemibold),
            GLMRightLabel(ToNSString(rlispstat::core::GLMRegressionDeltaRSquaredLabel()), NSMakeRect(14 + layout.coefX[8], 172, layout.coefW[8], 18), 12, NSFontWeightSemibold),
            nil];
        for (NSTextField *field in _coefHeaderFields) [content addSubview:field];

        _coefRule = [[NSBox alloc] initWithFrame:NSMakeRect(14, 168, 582, 1)];
        [_coefRule setBoxType:NSBoxSeparator];
        [content addSubview:_coefRule];

        _coefScrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 42, 620, 124)];
        [_coefScrollView setBorderType:NSNoBorder];
        [_coefScrollView setDrawsBackground:NO];
        [_coefScrollView setHasVerticalScroller:YES];
        [_coefScrollView setHasHorizontalScroller:NO];
        [_coefScrollView setAutohidesScrollers:YES];
        [_coefScrollView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [content addSubview:_coefScrollView];

        _coefView = [[GLMCoefficientsView alloc] initWithFrame:NSMakeRect(0, 0, 620, 124)];
        [(GLMCoefficientsView *)_coefView setGlmController:self];
        [_coefView setAutoresizingMask:NSViewWidthSizable];
        [_coefScrollView setDocumentView:_coefView];

        _statusField = GLMLabel(ToNSString(rlispstat::core::GLMReadyStatus()), NSMakeRect(12, 16, 620, 18), 12, NSFontWeightRegular);
        [_statusField setAutoresizingMask:NSViewWidthSizable | NSViewMaxYMargin];
        [content addSubview:_statusField];
        [self refresh];
    }
    return self;
}

- (NSInteger)coefficientRowCount
{
    GLMFitSummary fit = [self currentFit];
    if (fit.ok) {
        return (NSInteger)fit.coefficients.size() + 1; // coefficients plus add-term row
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
    return (NSInteger)state.terms.size() + 2;
}

- (NSString *)coefficientColumnIdentifier:(NSInteger)column
{
    static NSString *ids[] = { @"term", @"type", @"estimate", @"beta", @"stderr", @"stat", @"p", @"partial", @"delta" };
    return (column >= 0 && column < 9) ? ids[column] : @"";
}

- (NSString *)coefficientValueForRow:(NSInteger)row column:(NSInteger)column
{
    NSString *identifier = [self coefficientColumnIdentifier:column];
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    std::map<std::string, std::string> termTypes;
    std::set<std::string> centeredPredictors;
    std::string scope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        centeredPredictors = state.centeredPredictors;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
    }
    GLMFitSummary fit = [self currentFit];
    bool fitRows = fit.ok;
    bool isAdd = fitRows ? row == (NSInteger)fit.coefficients.size() : row == (NSInteger)terms.size() + 1;
    bool isIntercept = row == 0 && !isAdd;
    GLMCoefficientRow coef;
    bool hasCoef = fitRows && row >= 0 && row < (NSInteger)fit.coefficients.size();
    if (hasCoef) {
        coef = fit.coefficients[(size_t)row];
        coef.displayLabel = rlispstat::core::GLMRegressionCoefficientDisplayLabel(
            coef, centeredPredictors);
    }
    bool parentRow = hasCoef && (coef.rowType == "factor_parent" || coef.rowType == "term_parent");
    bool referenceRow = hasCoef && coef.rowType == "reference";
    bool interactionChildRow = hasCoef &&
        rlispstat::core::ModelTermTypeIsInteraction(coef.termType) &&
        coef.rowType == "coefficient" &&
        !coef.sourceTerm.empty() &&
        coef.sourceTerm != coef.term;
    NSInteger termIndex = row - 1;
    std::string term = hasCoef ? (coef.displayLabel.empty() ? coef.term : coef.displayLabel) : (isIntercept ? "(Intercept)" : (isAdd ? "+ Add term" :
        ((termIndex >= 0 && (size_t)termIndex < terms.size()) ? terms[(size_t)termIndex] : "")));
    if (hasCoef && column >= 0 && column < 9) {
        const auto cell = rlispstat::core::GLMRegressionTableCell(
            coef, static_cast<rlispstat::core::GLMTableColumn>(column));
        return ToNSString(rlispstat::core::GLMRegressionTableCellText(cell));
    }
    if ([identifier isEqualToString:@"term"]) {
        return ToNSString(term);
    }
    if ([identifier isEqualToString:@"type"]) {
        if (isIntercept) return @"-";
        if (isAdd || term.empty()) return @"";
        if (hasCoef && (coef.rowType == "reference" || coef.rowType == "factor_level" || interactionChildRow)) return @"";
        return ToNSString(rlispstat::core::ModelTermTypeDisplayName(hasCoef ? coef.termType : rlispstat::core::ModelTermDisplayType(_model, term, termTypes)));
    }
    if ([identifier isEqualToString:@"estimate"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatDouble(coef.estimate, 4)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"beta"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow && std::isfinite(coef.standardizedBeta)) ? ToNSString(FormatDouble(coef.standardizedBeta, 3)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"stderr"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatDouble(coef.stdError, 4)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"stat"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatDouble(coef.tValue, 3)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"p"]) {
        if (parentRow) return @"";
        return (hasCoef && !referenceRow) ? ToNSString(FormatPValue(coef.pValue)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"partial"]) {
        if (parentRow) return @"\U00002014";
        return (hasCoef && !referenceRow && std::isfinite(coef.partialR)) ? ToNSString(FormatDouble(coef.partialR, 3)) : @"\U00002014";
    }
    if ([identifier isEqualToString:@"delta"]) {
        return (hasCoef && !referenceRow && std::isfinite(coef.deltaR2)) ? ToNSString(FormatDouble(coef.deltaR2, 3)) : @"\U00002014";
    }
    return @"";
}

- (GLMFitSummary)currentFit
{
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    std::map<std::string, std::string> termTypes;
    std::string scope;
    std::string group;
    std::string signature;
    bool shouldQueueRFit = false;
    bool shouldQueuePooledMIFit = false;
    bool hasCachedFit = false;
    GLMFitSummary cachedFit;
    MainRLinearGLMTask task;
    DataFrameModel pooledDataframe;
    std::string pooledScope;
    std::string pooledModelSpec;
    std::vector<std::string> centeredPredictors;
    std::vector<int> fitSelectionRows;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (state.precomputed && !state.multipleImputation) {
            auto fitIt = g_precomputedLinearModelFits.find(_modelId);
            if (fitIt != g_precomputedLinearModelFits.end()) {
                return fitIt->second;
            }
        }
        group = state.group.empty() ? _model->group : state.group;
        if (state.isStale && !state.rFitPending && state.autoRefit)
            MacCommandDispatcher().applicationState().captureAnalysisScope(group, state.dataScope, state.dataScopeCaptured, &state.scope);
        dependent = state.response;
        terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        centeredPredictors.assign(state.centeredPredictors.begin(),
                                  state.centeredPredictors.end());
        scope = ScopeForModelSpecification(state);
        fitSelectionRows = RowsForModelSpecificationUnlocked(group, state);
        if (dependent.empty()) {
            state.rFitPending = false;
            state.lastRFitSignature.clear();
            return PendingLinearGLMFitSummary("Choose a response variable before fitting.");
        }
        if (terms.empty()) {
            state.rFitPending = false;
            state.lastRFitSignature.clear();
            return PendingLinearGLMFitSummary("Add at least one independent variable before fitting.");
        }
        signature = rlispstat::core::LinearGLMFitSignature(
            dependent, terms, termTypes, scope, state.centeredPredictors,
            state.factorReferenceLevels);
        signature = rlispstat::core::LinearGLMFitIdentityWithSelection(
            signature, scope, fitSelectionRows);
        auto fitIt = g_precomputedLinearModelFits.find(_modelId);
        if (fitIt != g_precomputedLinearModelFits.end() && fitIt->second.ok) {
            cachedFit = fitIt->second;
            hasCachedFit = true;
        }
        // Auto-refit freezes the accepted fit as well as its captured rows.
        // Keep that result available while the current specification/data is
        // stale; the status line explains that it belongs to the previous fit.
        if (!state.autoRefit && hasCachedFit) {
            state.rFitPending = false;
            return cachedFit;
        }
        // A pooled MI table arrives from R with a valid fit but without the
        // native request signature used by later interactive refits.  Adopt
        // the signature once.  After any specification mutation `isStale` is
        // true, so the same window follows the normal main-R task path instead
        // of spawning a fresh Rscript process.
        if (state.precomputed && state.multipleImputation && !state.isStale &&
            hasCachedFit && state.lastRFitSignature.empty()) {
            state.lastRFitSignature = signature;
            return cachedFit;
        }
        if (rlispstat::core::LinearGLMFitMayBePresented(
                state, signature,
                fitIt != g_precomputedLinearModelFits.end() ? &fitIt->second : nullptr)) {
            return fitIt->second;
        }
        if (!state.isStale && !state.rFitPending &&
            fitIt != g_precomputedLinearModelFits.end() && !fitIt->second.ok)
            return fitIt->second;
        if (state.rFitPending && state.lastRFitSignature == signature) {
            return PendingLinearGLMFitSummary(
                "Fitting the current linear-model specification in the main R session...");
        }
        if (!state.autoRefit) {
            state.rFitPending = false;
            return PendingLinearGLMFitSummary(
                "Auto-refit is off. Turn it on to fit the current model specification.");
        }
        state.rFitPending = true;
        state.lastRFitSignature = signature;
        if (state.multipleImputation) {
            // Reuse the connected main R session whenever possible.  It owns
            // the canonical mids object and the same mice-based fitter used
            // by Windows and the generalized models.  The standalone path is
            // now only a recovery fallback when that session is unavailable.
            if (!g_mainRNotifyPath.empty()) {
                task.group = group;
                task.modelId = _modelId;
                task.dependent = dependent;
                task.scope = scope;
                task.terms = terms;
                task.termTypes = termTypes;
                task.centeredPredictors.assign(state.centeredPredictors.begin(),
                                               state.centeredPredictors.end());
                task.factorReferenceLevels = state.factorReferenceLevels;
                task.rows = fitSelectionRows;
                task.requestIdentity = signature;
                shouldQueueRFit = true;
            } else {
                if (_modelId != group) {
                    state.rFitPending = false;
                    return PendingLinearGLMFitSummary(
                        "The main R session is unavailable; reconnect it to fit this model.");
                }
                const DataFrameModel *found = FindDataFrameUnlockedConst(group);
                if (!found) {
                    state.rFitPending = false;
                    return PendingLinearGLMFitSummary(GLMImputedDatasetUnavailableStatus());
                }
                pooledDataframe = *found;
                pooledScope = scope;
                pooledModelSpec = EncodeStandaloneLinearMISpec(
                    termTypes, state.centeredPredictors, state.factorReferenceLevels,
                    fitSelectionRows);
                shouldQueuePooledMIFit = true;
            }
        } else {
            task.group = group;
            task.modelId = _modelId;
            task.dependent = dependent;
            task.scope = scope;
            task.terms = terms;
            task.termTypes = termTypes;
            task.centeredPredictors.assign(state.centeredPredictors.begin(),
                                           state.centeredPredictors.end());
            task.factorReferenceLevels = state.factorReferenceLevels;
            task.rows = fitSelectionRows;
            task.requestIdentity = signature;
            shouldQueueRFit = true;
        }
    }
    if (shouldQueuePooledMIFit) {
        std::thread worker([pooledDataframe, dependent, terms, pooledScope,
                            pooledModelSpec, group, signature]() {
            std::string message;
            bool ok = RunRBackedMultipleImputationAnalysis(
                pooledDataframe, "glm",
                "glm_" + pooledDataframe.group + "_" + std::to_string((long long)time(nullptr)),
                std::vector<std::string>(), "", dependent, terms, pooledScope,
                &message, pooledModelSpec);
            if (!ok) {
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    auto it = g_groupModels.find(group);
                    if (it != g_groupModels.end() && it->second.lastRFitSignature == signature) {
                        it->second.rFitPending = false;
                    }
                }
                ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralLinearModelTitle()), ToNSString(message));
            }
        });
        worker.detach();
    }
    if (shouldQueueRFit) {
        QueueLinearGLMMainRTask(task);
    }
    // The cache, when present here, belongs to a previous specification.  The
    // term table must therefore be rebuilt from the current canonical state
    // and show pending values instead of mixing those rows with the old fit.
    return PendingLinearGLMFitSummary(
        "Fitting the current linear-model specification in the main R session...");
}

- (BOOL)usesPooledGlobalWald
{
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
    return state.multipleImputation;
}

- (NSString *)globalModelStatisticLabel
{
    return [self usesPooledGlobalWald] ? ToNSString(rlispstat::core::GLMD1WaldLabel()) : ToNSString(rlispstat::core::GLMAnovaFRatioLabel());
}

- (void)openInteractionReportForTerm:(const std::string &)term
{
    if (term.empty()) return;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    std::map<std::string, std::string> termTypes;
    DataFrameModel dataframe;
    bool multipleImputation = false;
    std::string dependent;
    std::string scope;
    std::string modelSpec;
    int modelVersion = 0;
    int fitVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        dependent = state.response;
        scope = ScopeForModelSpecification(state);
        multipleImputation = state.multipleImputation;
        modelVersion = state.modelVersion;
        fitVersion = state.fitVersion;
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) dataframe = *found;
        modelSpec = EncodeStandaloneLinearMISpec(
            termTypes, state.centeredPredictors, state.factorReferenceLevels,
            RowsForModelSpecificationUnlocked(_model->group, state));
    }
    RegressionInteractionDerivedLink derivedLink;
    derivedLink.sourceModelKind = "linear_single";
    derivedLink.sourceModelId = _modelId;
    derivedLink.sourceModelRevision = modelVersion;
    derivedLink.sourceFitVersion = fitVersion;
    derivedLink.group = _model->group;
    derivedLink.term = term;
    derivedLink.title = "Effect: " + term;
    if (dataframe.group.empty()) {
        [_statusField setStringValue:ToNSString(
            GLMStatusMessage("The dataset for the interaction interpretation is unavailable."))];
        return;
    }
    const std::string jobKey = derivedLink.sourceModelKind + "|" +
        derivedLink.sourceModelId + "|" + term + "|" +
        std::to_string(modelVersion) + "|" + std::to_string(fitVersion);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!g_pendingInteractionReportJobs.insert(jobKey).second) {
            [_statusField setStringValue:ToNSString(
                "The interaction interpretation for " + term +
                " is already being calculated in R…")];
            return;
        }
    }

    // Post-estimation may take noticeably longer than the model fit for an
    // imputed dataset. Never block AppKit while R calculates the report.
    [_statusField setStringValue:ToNSString(
        "Calculating the interaction interpretation in R for " + term + "…")];
    NSTextField *statusField = [_statusField retain];
    std::thread worker([dataframe, dependent, terms, scope, modelSpec, term,
                        derivedLink, multipleImputation, statusField,
                        jobKey]() mutable {
        std::string body;
        std::string message;
        const std::string analysisId = "glm_interaction_" + derivedLink.sourceModelId + "_" +
            std::to_string(derivedLink.sourceModelRevision) + "_" +
            std::to_string(derivedLink.sourceFitVersion);
        const bool ok = RunRBackedMIInteractionReport(
            dataframe, "glm_interaction", analysisId,
            dependent, terms, scope, modelSpec, term, &body, &message);
        dispatch_async(dispatch_get_main_queue(), ^{
            bool current = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pendingInteractionReportJobs.erase(jobKey);
                auto state = g_groupModels.find(derivedLink.sourceModelId);
                current = state != g_groupModels.end() &&
                    state->second.modelVersion == derivedLink.sourceModelRevision &&
                    state->second.fitVersion == derivedLink.sourceFitVersion;
            }
            std::string applyMessage = message;
            if (ok && current) {
                ShowGLMInteractionReportWindowOnMain(
                    derivedLink.title, body, derivedLink);
                [statusField setStringValue:ToNSString(multipleImputation
                    ? "Interaction interpreted across all imputations in R for " + term + "."
                    : "Interaction interpreted in R for " + term + ".")];
            } else {
                if (ok && !current) {
                    applyMessage = "The model changed while the interaction was being interpreted; request it again.";
                }
                [statusField setStringValue:ToNSString(GLMStatusMessage(applyMessage))];
            }
            [statusField release];
        });
    });
    worker.detach();
}

- (void)openInteractionPlotForTerm:(const std::string &)term
{
    if (term.empty()) return;
    DataFrameModel dataframe;
    bool multipleImputation = false;
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    std::string scope;
    std::string modelSpec;
    int modelVersion = 0;
    int fitVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        multipleImputation = state.multipleImputation;
        dependent = state.response;
        terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        modelVersion = state.modelVersion;
        fitVersion = state.fitVersion;
        scope = ScopeForModelSpecification(state);
        modelSpec = EncodeStandaloneLinearMISpec(
            rlispstat::core::EffectiveModelSpecificationTermTypes(state),
            state.centeredPredictors, state.factorReferenceLevels,
            RowsForModelSpecificationUnlocked(_model->group, state));
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
        }
    }
    RegressionInteractionDerivedLink derivedLink;
    derivedLink.sourceModelKind = "linear_single";
    derivedLink.sourceModelId = _modelId;
    derivedLink.sourceModelRevision = modelVersion;
    derivedLink.sourceFitVersion = fitVersion;
    derivedLink.group = _model->group;
    derivedLink.term = term;
    const bool simpleEffect = !IsInteractionTerm(term);
    derivedLink.title = "Effect: " + term;
    if (dataframe.group.empty()) {
        [_statusField setStringValue:ToNSString(
            GLMStatusMessage("The dataset for the effect plot is unavailable."))];
        return;
    }

    const std::string jobKey = derivedLink.sourceModelKind + "|" +
        derivedLink.sourceModelId + "|" + term + "|" +
        std::to_string(modelVersion) + "|" + std::to_string(fitVersion);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!g_pendingInteractionPlotJobs.insert(jobKey).second) {
            [_statusField setStringValue:ToNSString(
                "The effect plot for " + term + " is already being calculated in R…")];
            return;
        }
    }

    // R-backed post-estimation can take several seconds for multiply-imputed
    // and three-way models. Keep it off AppKit's main thread so the model
    // window continues to redraw and the result window can be presented as
    // soon as R returns.
    [_statusField setStringValue:ToNSString(
        "Calculating the effect plot in R for " + term + "…")];
    NSTextField *statusField = [_statusField retain];
    std::thread worker([dataframe, dependent, terms, scope, modelSpec, term,
                        derivedLink, multipleImputation, simpleEffect, statusField,
                        jobKey]() mutable {
        rlispstat::core::RegressionInteractionPlotResult result;
        std::string message;
        const std::string analysisId = "glm_interaction_" + derivedLink.sourceModelId;
        const bool ok = RunRBackedInteractionPlot(
            dataframe, "glm_interaction_plot", analysisId,
            dependent, terms, scope, modelSpec, term, &result, &message);
        dispatch_async(dispatch_get_main_queue(), ^{
            bool current = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                g_pendingInteractionPlotJobs.erase(jobKey);
                auto state = g_groupModels.find(derivedLink.sourceModelId);
                current = state != g_groupModels.end() &&
                    state->second.modelVersion == derivedLink.sourceModelRevision &&
                    state->second.fitVersion == derivedLink.sourceFitVersion;
            }
            std::string applyMessage = message;
            if (ok && !current) {
                applyMessage = "The model changed while the effect plot was being calculated; request the plot again.";
            }
            const std::string plotId = ok && current
                ? ApplyRBackedInteractionPlotResult(
                    dataframe, analysisId, dependent, term,
                    result, &applyMessage, derivedLink)
                : std::string();
            [statusField setStringValue:ToNSString(plotId.empty()
                ? GLMStatusMessage(applyMessage)
                : (multipleImputation
                    ? "Pooled effect plot opened across all imputations for " + term + "."
                    : "Effect plot opened from the R fit for " + term + "."))];
            [statusField release];
        });
    });
    worker.detach();
}

- (void)showInteractionReport:(id)sender
{
    std::string term;
    NSString *represented = [sender respondsToSelector:@selector(representedObject)] ? [sender representedObject] : nil;
    if (represented) term = [represented UTF8String];
    if (term.empty()) term = [self selectedTerm];
    [self openInteractionReportForTerm:term];
}

- (void)showInteractionPlot:(id)sender
{
    std::string term;
    NSString *represented = [sender respondsToSelector:@selector(representedObject)] ? [sender representedObject] : nil;
    if (represented) term = [represented UTF8String];
    if (term.empty()) term = [self selectedTerm];
    [self openInteractionPlotForTerm:term];
}

- (void)showPartialRegressionPlot:(id)sender
{
    std::string term;
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (represented) term = [represented UTF8String];
    if (term.empty()) term = [self selectedTerm];
    if (term.empty() || IsInteractionTerm(term)) return;
    DataFrameModel dataframe;
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    std::string scope;
    std::string modelSpec;
    int modelVersion = 0;
    int fitVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (std::find(state.terms.begin(), state.terms.end(), term) == state.terms.end()) return;
        dependent = state.response;
        terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        scope = ScopeForModelSpecification(state);
        modelVersion = state.modelVersion;
        fitVersion = state.fitVersion;
        modelSpec = EncodeStandaloneLinearMISpec(
            rlispstat::core::EffectiveModelSpecificationTermTypes(state),
            state.centeredPredictors, state.factorReferenceLevels,
            RowsForModelSpecificationUnlocked(_model->group, state));
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group))
            dataframe = *found;
    }
    if (dataframe.group.empty()) {
        [_statusField setStringValue:@"Status: dataset is no longer available."];
        return;
    }
    RegressionInteractionDerivedLink link;
    link.sourceModelKind = "linear_single";
    link.sourceModelId = _modelId;
    link.sourceModelRevision = modelVersion;
    link.sourceFitVersion = fitVersion;
    link.group = _model->group;
    link.term = term;
    link.title = "Partial regression plot: " + term;
    std::string message;
    const std::string plotId = OpenRBackedPartialRegressionPlot(
        dataframe, "glm_partial_plot", "glm_partial_" + _modelId,
        dependent, terms, scope, modelSpec, term, "raw", &message, link);
    [_statusField setStringValue:ToNSString(plotId.empty()
        ? GLMStatusMessage(message)
        : "Partial regression plot opened for " + term + ".")];
}

- (std::string)sourceTermForCoefficientRow:(NSInteger)row
{
    GLMFitSummary fit = [self currentFit];
    if (fit.ok && row > 0 && row < (NSInteger)fit.coefficients.size()) {
        return fit.coefficients[(size_t)row].sourceTerm;
    }
    std::lock_guard<std::mutex> lock(g_mutex);
    GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
    NSInteger termRow = row - 1;
    if (termRow >= 0 && (size_t)termRow < state.terms.size()) {
        return state.terms[(size_t)termRow];
    }
    return "";
}

- (void)dependentChanged:(id)sender
{
    NSString *name = [_dependentPopup titleOfSelectedItem];
    if (!name) {
        return;
    }
    std::string newDependent = [name UTF8String];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (state.precomputed) {
            if (!state.multipleImputation) {
                [_statusField setStringValue:ToNSString(GLMPrecomputedTableRefitStatus("change the response"))];
                return;
            }
        }
    }
    ApplyVariableAction(_modelId, newDependent, "dependent");
    [self refresh];
}

- (void)addPredictor:(id)sender
{
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (state.precomputed && !state.multipleImputation) {
            [_statusField setStringValue:ToNSString(GLMPrecomputedTableRefitStatus("add predictors"))];
            return;
        }
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::ScatterplotAddIndependentVariableTitle())];
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
    }
    for (const std::string &name : VariableNamesForModel(_model)) {
        if (name == dependent || std::find(terms.begin(), terms.end(), name) != terms.end()) {
            continue;
        }
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(addPredictorFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(name)];
        [menu addItem:item];
    }
    if ([menu numberOfItems] > 0) {
        [menu addItem:[NSMenuItem separatorItem]];
    }
    if (!AddModelTermMenuItems(menu, self, @selector(addPredictorFromMenu:), _model, dependent, terms, "", effectiveTypes)) {
        NSInteger last = [menu numberOfItems] - 1;
        if (last >= 0 && [[menu itemAtIndex:last] isSeparatorItem]) {
            [menu removeItemAtIndex:last];
        }
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(GLMNoAvailablePredictorsStatus())];
        return;
    }
    NSView *view = [sender isKindOfClass:[NSView class]] ? (NSView *)sender : _coefView;
    NSPoint point = [view isEqual:_coefView] ? NSMakePoint(10, [_coefView bounds].size.height - 4) : [(NSButton *)sender frame].origin;
    if (![view isEqual:_coefView]) {
        point.y += [(NSButton *)sender frame].size.height;
        view = [(NSButton *)sender superview];
    }
    [menu popUpMenuPositioningItem:nil atLocation:point inView:view];
}

- (void)showSearchableAddTermSelectorInView:(NSView *)view
{
    std::string response;
    std::vector<std::string> terms;
    std::map<std::string, std::string> effectiveTypes;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (state.precomputed && !state.multipleImputation) return;
        response = state.response; terms = state.terms;
        effectiveTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
    }
    const auto choices = SearchableModelTermChoices(
        _model, response, terms, effectiveTypes);
    ShowSearchableAddSelector(_window, view, @"Add terms", choices,
        ^(NSArray<NSString *> *names) {
            for (NSString *label in names)
                ApplyVariableAction(_modelId, std::string(label.UTF8String), "predictor");
            [self refresh];
        }, ^NSMenu *(NSString *label) {
            std::string currentResponse;
            std::vector<std::string> currentTerms;
            std::map<std::string, std::string> currentTypes;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
                currentResponse = state.response;
                currentTerms = state.terms;
                currentTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
            }
            return SearchableModelTermContextMenu(label, self,
                @selector(addPredictorFromMenu:), _model, currentResponse,
                currentTerms, currentTypes);
        });
}

- (void)addPredictorFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) {
        return;
    }
    std::string term = [name UTF8String];
    // Pooled MI models are now edited in the same canonical native model as
    // ordinary linear models.  currentFit() sends the resulting immutable
    // specification to the already-connected R session, including the
    // dataset-derived factor type for terms such as `g`.
    ApplyVariableAction(_modelId, term, "predictor");
    [self refresh];
}

- (void)changeSelectedModelRow:(id)sender
{
    NSInteger row = _selectedCoefRow;
    if (row < 0) {
        return;
    }
    if (row == [self coefficientRowCount] - 1) {
        [self addPredictor:_coefView];
        return;
    }
    if (row == 0) {
        return;
    }
    [self replacePredictorAtTableRow:row];
}

- (void)dependentFromMenu:(id)sender
{
    NSString *name = [sender representedObject];
    if (!name) return;
    ApplyVariableAction(_modelId, [name UTF8String], "dependent");
    [self refresh];
}

- (void)replacePredictorAtTableRow:(NSInteger)row
{
    std::string oldTerm = [self sourceTermForCoefficientRow:row];
    if (oldTerm.empty()) return;
    NSInteger termIndex = -1;
    std::string dependent;
    std::vector<std::string> terms;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
    }
    for (size_t i = 0; i < terms.size(); ++i) {
        if (terms[i] == oldTerm) {
            termIndex = (NSInteger)i;
            break;
        }
    }
    if (termIndex < 0 || (size_t)termIndex >= terms.size()) return;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::ScatterplotReplacePredictorTitle())];
    for (const std::string &name : VariableNamesForModel(_model)) {
        if (name == dependent) continue;
        bool duplicate = false;
        for (size_t i = 0; i < terms.size(); ++i) {
            if ((NSInteger)i != termIndex && terms[i] == name) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(name) action:@selector(replacePredictorFromMenu:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ @(termIndex), ToNSString(name) ]];
        [menu addItem:item];
    }
    if ([[menu itemArray] count] == 0) {
        [_statusField setStringValue:ToNSString(GLMNoAvailableReplacementStatus())];
        return;
    }
    GLMReportLayout layout;
    NSRect rowRect = NSMakeRect(0, row * layout.rowHeight, [_coefView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMinX(rowRect) + 10, NSMaxY(rowRect)) inView:_coefView];
}

- (void)replacePredictorFromMenu:(id)sender
{
    NSArray *payload = [sender representedObject];
    if (![payload isKindOfClass:[NSArray class]] || [payload count] < 2) return;
    NSInteger termIndex = [[payload objectAtIndex:0] integerValue];
    NSString *name = [payload objectAtIndex:1];
    if (!name) return;
    const std::string replacement = [name UTF8String];
    std::string oldTerm;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (termIndex >= 0 && (size_t)termIndex < state.terms.size()) {
            oldTerm = state.terms[(size_t)termIndex];
        }
    }
    if (oldTerm.empty() || oldTerm == replacement) return;
    if (DispatchModelMutationOnMac(
            {"MODEL_REPLACE_TERM", _modelId, oldTerm, replacement},
            _modelId)) {
        PublishSpreadPlotMessage(
            "GLM_PREDICTOR_REPLACED", _model->group,
            "glm:" + _modelId, "glm:" + _modelId);
        RecordAPICommand({"MODEL_REPLACE_TERM", _modelId, oldTerm, replacement});
    }
    [self refresh];
}

- (void)showTypeMenuForTableRow:(NSInteger)row
{
    if (row <= 0 || row == [self coefficientRowCount] - 1) return;
    std::string term = [self sourceTermForCoefficientRow:row];
    if (term.empty()) return;
    std::string type;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        type = rlispstat::core::ModelSpecificationTermType(state, term);
    }
    if (rlispstat::core::ModelTermTypeIsInteraction(type)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::PredictorTypeMenuTitle())];
    AddModelTermTypeMenuItems(menu, self, @selector(typeMenuSelected:), type);
    GLMReportLayout layout;
    NSRect rowRect = NSMakeRect(0, row * layout.rowHeight, [_coefView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(layout.coefX[1], NSMaxY(rowRect)) inView:_coefView];
}

- (void)typeMenuSelected:(id)sender
{
    NSString *mode = [sender representedObject];
    std::string term = [self sourceTermForCoefficientRow:_selectedCoefRow];
    if (term.empty()) return;
    if (IsInteractionTerm(term)) {
        [_statusField setStringValue:ToNSString(GLMInteractionComponentTypeStatus(term))];
        return;
    }
    std::string type = (mode && [mode isEqualToString:@"factor"]) ? "factor" : "numeric";
    rlispstat::core::ModelSpecificationEditResult edit;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        const DataFrameModel *dataframe = FindDataFrameUnlockedConst(_model->group);
        edit = rlispstat::core::SetModelSpecificationTermType(
            state, term, type,
            rlispstat::core::PredictorMetadataForLinearModel(*_model, dataframe, term));
        if (edit.ok && edit.changed) rlispstat::core::MarkGroupModelChanged(state);
    }
    if (!edit.ok) {
        [_statusField setStringValue:ToNSString(edit.message)];
        return;
    }
    if (!edit.changed) return;
    PublishSpreadPlotMessage("GLM_TERM_TYPE_CHANGED", _model->group, "glm:" + _modelId, "glm:" + _modelId);
    [self refresh];
    [_statusField setStringValue:ToNSString(GLMTermTypeChangedStatus(term, type))];
}

- (void)changeSelectedType:(id)sender
{
    (void)sender;
    NSInteger row = _selectedCoefRow;
    if (row > 0) {
        [self showTypeMenuForTableRow:row];
    }
}

