- (NSString *)regressionTableText
{
    std::string dependent;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
    }
    GLMFitSummary fit = [self currentFit];
    if (!fit.ok) return @"";
    return ToNSString(rlispstat::core::GLMRegressionCopyTableText(fit, dependent, [self usesPooledGlobalWald]));
}

- (NSString *)snapshotTableText
{
    if (!_model) return @"";
    std::string dependent;
    std::string scope;
    std::string note;
    bool hasCapturedScope = false;
    std::string scopeSummary;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        scope = state.scope == "compare_selected_all" ? "all" : state.scope;
        note = state.note;
        hasCapturedScope = state.dataScopeCaptured;
        if (hasCapturedScope) {
            scopeSummary = rlispstat::core::AnalysisScopeWindowSummary(
                state.dataScope, state.dataScope.totalDatasetRows);
        }
    }
    GLMFitSummary fit = [self currentFit];
    if (!fit.ok) return ToNSString(fit.warning);

    std::ostringstream out;
    out << "Response variable\t" << dependent << "\n";
    out << "Scope\t" << (scopeSummary.empty() ? scope : scopeSummary) << "\n";
    out << "Selected rows\t" << SelectionCount(_model->group) << " / "
        << RowCountForGroup(_model->group) << "\n\n";
    out << "Global fit\n";
    out << "R²\t" << FormatPercent(fit.r2, 1)
        << "\tAdjusted R²\t" << FormatPercent(fit.adjR2, 1)
        << "\ts\t" << FormatDouble(fit.sigma, 3)
        << "\tdf\t" << fit.dfResidual << "\n\n";
    out << "Source\tSum of Squares\tdf\tMean Square\t"
        << ([[self globalModelStatisticLabel] UTF8String]) << "\tp\n";
    out << "Regression\t" << FormatDouble(fit.ssRegression, 4) << "\t"
        << fit.dfModel << "\t" << FormatDouble(fit.msRegression, 4) << "\t"
        << FormatDouble(fit.globalF, 3) << "\t" << FormatPValue(fit.globalP) << "\n";
    out << "Residual\t" << FormatDouble(fit.ssResidual, 4) << "\t"
        << fit.dfResidual << "\t" << FormatDouble(fit.msResidual, 4) << "\t\t\n\n";
    out << "Terms\n";
    out << "Variable\tType\tb\tβ\tSE\tt\tp\tPartial r\tΔR²\n";
    const NSInteger rowCount = [self coefficientRowCount] - 1;
    for (NSInteger row = 0; row < rowCount; ++row) {
        for (NSInteger column = 0; column < 9; ++column) {
            if (column) out << '\t';
            NSString *value = [self coefficientValueForRow:row column:column] ?: @"";
            out << [value UTF8String];
        }
        out << '\n';
    }
    out << "\nStatus\t";
    if (!note.empty()) out << note;
    else out << GLMFittedStatus(fit.n, fit.excluded, scope);
    if (!scopeSummary.empty()) out << " · " << scopeSummary;
    out << "\n\n* p < .05; ** p < .01; *** p < .001";
    return ToNSString(out.str());
}

- (NSMenuItem *)regressionExportMenuItem
{
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Export"];
    NSMenuItem *placeholder = [[NSMenuItem alloc] initWithTitle:@"Preparing export…" action:nil keyEquivalent:@""];
    [placeholder setEnabled:NO]; [menu addItem:placeholder];
    [menu setDelegate:self];
    [root setSubmenu:menu];
    return root;
}

- (void)menuNeedsUpdate:(NSMenu *)menu
{
    // Persistent fit menus are created before R has returned any results.
    // Freeze the current fit only when the export submenu is opened.
    [menu removeAllItems];
    const GLMFitSummary exportFit = [self currentFit];
    if (!_model || !exportFit.ok) {
        NSMenuItem *pending = [[NSMenuItem alloc] initWithTitle:@"Results are not ready for export" action:nil keyEquivalent:@""];
        [pending setEnabled:NO];
        [menu addItem:pending];
        return;
    }
    GroupModelState state;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        state = EnsureGroupModelUnlocked(_modelId, _model);
    }
    const auto publicationTable = rlispstat::core::LinearModelCodeReference(state, exportFit).publication.table;
    NSString *text = ToNSString(rlispstat::core::GLMRegressionCopyTableText(
        exportFit, state.response, state.multipleImputation));
    const auto reportTables = rlispstat::core::LinearModelReportTables(state,exportFit);
    AddStandardTableVisualExportItems(menu, nil, @"Linear Model",
        @"general-linear-model", text, publicationTable ? &*publicationTable : nullptr, &reportTables);
    AddRCodeExportItems(menu, "output", "glm:" + _modelId, true);
}

- (void)copyRegressionTable:(id)sender
{
    (void)sender;
    NSString *text = [self regressionTableText];
    if (![text length]) {
        GLMFitSummary fit = [self currentFit];
        [_statusField setStringValue:ToNSString(GLMStatusMessage(fit.warning))];
        return;
    }
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:text forType:NSPasteboardTypeString];
    [_statusField setStringValue:ToNSString(GLMRegressionTableCopiedStatus())];
}

- (NSMenu *)statisticContextMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.statistic)];
    NSMenuItem *copy = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.copyValue) action:@selector(copyMenuValue:) keyEquivalent:@""];
    [copy setTarget:self];
    [copy setRepresentedObject:[self valueForTableRow:row column:column]];
    [menu addItem:copy];
    NSMenuItem *explain = [[NSMenuItem alloc]
        initWithTitle:ToNSString(titles.explainStatistic)
        action:@selector(explainStatistic:)
        keyEquivalent:@""];
    [explain setTarget:self];
    [explain setRepresentedObject:[self coefficientColumnIdentifier:column]];
    [menu addItem:explain];
    [menu addItem:ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), false)];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.compareModels) action:@selector(openModelComparison:) keyEquivalent:@""]];
    [menu addItem:[self regressionExportMenuItem]];
    for (NSMenuItem *item in [menu itemArray]) {
        if ([item action] && ![item target]) [item setTarget:self];
    }
    return menu;
}

- (NSMenu *)predictorContextMenuForTableRow:(NSInteger)row
{
    const auto titles = rlispstat::core::DefaultModelContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.predictor)];
    std::string baseTerm = [self sourceTermForCoefficientRow:row];
    const bool interaction = IsInteractionTerm(baseTerm);
    if (!baseTerm.empty() && baseTerm != "(Intercept)") {
        NSMenuItem *remove = [[NSMenuItem alloc]
            initWithTitle:(interaction ? @"Remove interaction" : @"Remove predictor")
            action:@selector(removeSelectedTerm:) keyEquivalent:@""];
        [remove setRepresentedObject:ToNSString(baseTerm)];
        [remove setTarget:self];
        [menu addItem:remove];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    NSMenuItem *analyzeRoot = [[NSMenuItem alloc] initWithTitle:@"Analyze predictor" action:nil keyEquivalent:@""];
    NSMenu *analyze = [[NSMenu alloc] initWithTitle:@"Analyze predictor"];
    NSMenuItem *modelTermsRoot = [[NSMenuItem alloc] initWithTitle:@"Model terms" action:nil keyEquivalent:@""];
    NSMenu *modelTermsMenu = [[NSMenu alloc] initWithTitle:@"Model terms"];
    NSMenuItem *editRoot = [[NSMenuItem alloc] initWithTitle:@"Edit predictor" action:nil keyEquivalent:@""];
    NSMenu *edit = [[NSMenu alloc] initWithTitle:@"Edit predictor"];
    if (interaction) {
        NSMenuItem *interpret = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.interpretInteraction) action:@selector(showInteractionReport:) keyEquivalent:@""];
        [interpret setRepresentedObject:ToNSString(baseTerm)];
        [interpret setTarget:self];
        [analyze addItem:interpret];
        NSMenuItem *plot = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.interactionPlot) action:@selector(showInteractionPlot:) keyEquivalent:@""];
        [plot setRepresentedObject:ToNSString(baseTerm)];
        [plot setTarget:self];
        [analyze addItem:plot];
    }
    if (!interaction) {
        NSMenuItem *effect = [[NSMenuItem alloc] initWithTitle:@"Effect plot…" action:@selector(showInteractionPlot:) keyEquivalent:@""];
        [effect setTarget:self];
        [effect setRepresentedObject:ToNSString(baseTerm)];
        [analyze addItem:effect];
        NSMenuItem *partial = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.partialRegressionPlot) action:@selector(showPartialRegressionPlot:) keyEquivalent:@""];
        [partial setTarget:self];
        [partial setRepresentedObject:ToNSString(baseTerm)];
        [analyze addItem:partial];
    }

    // Pairwise comparisons are a domain operation.  AppKit only asks the
    // portable GLM model whether this exact row identifies a currently fitted
    // simple categorical main effect, and uses that answer to enable the menu.
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    DataFrameModel dataframe;
    bool hasDataframe = false;
    bool multipleImputation = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
        termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        multipleImputation = state.multipleImputation;
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    rlispstat::core::GLMPairwiseComparisonRequest pairwiseRequest;
    pairwiseRequest.term = baseTerm;
    rlispstat::core::GLMPairwiseComparisonEligibility pairwiseEligibility =
        rlispstat::core::EvaluateGLMPairwiseComparisonEligibility(
            *_model, hasDataframe ? &dataframe : nullptr, dependent, terms, termTypes,
            [self currentFit], pairwiseRequest);
    const auto baseType = termTypes.find(baseTerm);
    const bool miPairwiseEligible = multipleImputation && baseType != termTypes.end() &&
        (baseType->second == "factor" || baseType->second == "ordered") &&
        std::find(terms.begin(), terms.end(), baseTerm) != terms.end() &&
        !interaction;
    if (pairwiseEligibility.eligible ||
        (std::find(terms.begin(), terms.end(), baseTerm) != terms.end() &&
         !interaction && baseTerm != "(Intercept)")) {
        NSMenuItem *pairwise = [[NSMenuItem alloc] initWithTitle:@"Pairwise comparisons…"
                                                         action:@selector(openPairwiseComparisons:)
                                                  keyEquivalent:@""];
        [pairwise setRepresentedObject:ToNSString(baseTerm)];
        [pairwise setEnabled:pairwiseEligibility.eligible || miPairwiseEligible];
        [pairwise setTarget:self];
        [analyze addItem:pairwise];
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
    }
    if (!AddModelTermMenuItems(modelTermsMenu, self, @selector(addPredictorFromMenu:),
                                 _model, dependent, terms, baseTerm, termTypes)) {
        NSMenuItem *disabled = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.noAvailableInteractions) action:nil keyEquivalent:@""];
        [disabled setEnabled:NO];
        [modelTermsMenu addItem:disabled];
    }
    if (!interaction) {
        NSMenuItem *changeVariable = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeVariable) action:@selector(changeSelectedModelRow:) keyEquivalent:@""];
        [changeVariable setTarget:self]; [edit addItem:changeVariable];
        NSMenuItem *changeType = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.changeType) action:@selector(changeSelectedType:) keyEquivalent:@""];
        [changeType setTarget:self]; [edit addItem:changeType];
        const std::string type = rlispstat::core::ModelTermDisplayType(_model, baseTerm, termTypes);
        if (type == "factor") {
            NSMenuItem *reference = [[NSMenuItem alloc]
                initWithTitle:@"Reference category…" action:@selector(showReferenceLevelMenu:)
                keyEquivalent:@""];
            [reference setRepresentedObject:ToNSString(baseTerm)];
            [reference setTarget:self]; [edit addItem:reference];
        } else {
            bool isCentered = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
                isCentered = state.centeredPredictors.count(baseTerm) != 0;
            }
            NSMenuItem *center = [[NSMenuItem alloc]
                initWithTitle:(isCentered ? @"Remove centering" : @"Center predictor")
                action:@selector(toggleCenterPredictor:)
                keyEquivalent:@""];
            [center setRepresentedObject:ToNSString(baseTerm)];
            [center setTarget:self]; [edit addItem:center];
        }
    }
    if ([[analyze itemArray] count]) { [analyzeRoot setSubmenu:analyze]; [menu addItem:analyzeRoot]; }
    if ([[modelTermsMenu itemArray] count]) { [modelTermsRoot setSubmenu:modelTermsMenu]; [menu addItem:modelTermsRoot]; }
    if ([[edit itemArray] count]) { [editRoot setSubmenu:edit]; [menu addItem:editRoot]; }
    [menu addItem:ModelDiagnosticPlotsMenuItem(
        self, @selector(openDiagnosticFromMenu:), false)];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[[NSMenuItem alloc] initWithTitle:ToNSString(titles.compareModels)
                                             action:@selector(openModelComparison:)
                                      keyEquivalent:@""]];
    [[menu itemArray].lastObject setTarget:self];
    [menu addItem:[self regressionExportMenuItem]];
    (void)row;
    return menu;
}

- (void)openPairwiseComparisons:(id)sender
{
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    const std::string term = represented ? [represented UTF8String] : [self selectedTerm];
    if (term.empty()) return;
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    DataFrameModel dataframe;
    bool hasDataframe = false;
    bool multipleImputation = false;
    std::string scope;
    std::string modelSpec;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
        termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        multipleImputation = state.multipleImputation;
        scope = ScopeForModelSpecification(state);
        modelSpec = EncodeStandaloneLinearMISpec(
            termTypes, state.centeredPredictors, state.factorReferenceLevels,
            RowsForModelSpecificationUnlocked(_model->group, state));
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
            hasDataframe = true;
        }
    }
    rlispstat::core::GLMPairwiseComparisonRequest request;
    request.term = term;
    GLMFitSummary fit = [self currentFit];
    rlispstat::core::GLMPairwiseComparisonEligibility eligibility =
        rlispstat::core::EvaluateGLMPairwiseComparisonEligibility(
            *_model, hasDataframe ? &dataframe : nullptr, dependent, terms, termTypes, fit, request);
    const auto type = termTypes.find(term);
    const bool miFactorEligible = multipleImputation && type != termTypes.end() &&
        (type->second == "factor" || type->second == "ordered") &&
        std::find(terms.begin(), terms.end(), term) != terms.end() && !IsInteractionTerm(term);
    if (!eligibility.eligible && !miFactorEligible) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(eligibility.message))];
        return;
    }
    rlispstat::core::GLMPairwiseComparisonResult result;
    result.term = term;
    result.levels = eligibility.levels;
    std::string message;
    const bool ok = hasDataframe && (multipleImputation
        ? RunRBackedMIPairwiseComparisons(
            dataframe, "glm_pairwise", "glm_pairwise_" + dataframe.group,
            dependent, terms, scope, modelSpec, term, &result, &message)
        : RunRBackedGLMPairwiseComparisons(
            dataframe, _model, dependent, terms, termTypes, fit, request, &result, &message));
    if (!ok) {
        [_statusField setStringValue:ToNSString(GLMStatusMessage(message))];
        return;
    }
    GLMPairwiseComparisonPlotLink plotLink = BuildGLMPairwiseComparisonPlotLink(
        _model->group, dataframe, dependent, term, fit.rowsUsed, result);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto current = g_groupModels.find(_modelId);
        plotLink.sourceModelKind = "linear_single";
        plotLink.sourceModelId = _modelId;
        if (current != g_groupModels.end()) {
            plotLink.sourceModelRevision = current->second.modelVersion;
            plotLink.sourceFitVersion = current->second.fitVersion;
        }
    }
    plotLink.multipleImputation = multipleImputation;
    plotLink.poolingMethod = multipleImputation ? result.method : std::string();
    ShowGLMPairwiseResultsWindowOnMain(term, result, plotLink);
    [_statusField setStringValue:ToNSString("Pairwise comparisons calculated for " + term + ".")];
}

- (NSMenu *)contextMenuForCoefficientRow:(NSInteger)row column:(NSInteger)column
{
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    if (row < 0 || row == [self coefficientRowCount] - 1) {
        NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Linear Model"];
        [menu addItem:ModelDiagnosticPlotsMenuItem(
            self, @selector(openDiagnosticFromMenu:), false)];
        [menu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *compare = [[NSMenuItem alloc]
            initWithTitle:ToNSString(rlispstat::core::DefaultModelContextMenuTitles().compareModels)
                   action:@selector(openModelComparison:) keyEquivalent:@""];
        [compare setTarget:self];
        [menu addItem:compare];
        [menu addItem:[self regressionExportMenuItem]];
        return menu;
    }
    NSMenu *result = nil;
    if (column >= 0 && column < 9) {
        NSString *identifier = [self coefficientColumnIdentifier:column];
        if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
            result = [self statisticContextMenuForTableRow:row column:column];
        }
    }
    if (!result) result = row > 0 ? [self predictorContextMenuForTableRow:row]
                                  : [self statisticContextMenuForTableRow:row column:column];
    return result;
}

- (void)showStatisticMenuForTableRow:(NSInteger)row column:(NSInteger)column
{
    if (row == [self coefficientRowCount] - 1) return;
    NSMenu *menu = [self statisticContextMenuForTableRow:row column:column];
    GLMReportLayout layout;
    NSRect rowRect = NSMakeRect(0, row * layout.rowHeight, [_coefView bounds].size.width, layout.rowHeight);
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(NSMidX(rowRect), NSMaxY(rowRect)) inView:_coefView];
}

- (void)coefficientCellClickedAtRow:(NSInteger)row column:(NSInteger)column
{
    if (row < 0) return;
    _selectedCoefRow = row;
    _selectedCoefColumn = column;
    BOOL isAddRow = row == [self coefficientRowCount] - 1;
    NSString *identifier = [self coefficientColumnIdentifier:column];
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (state.precomputed && !state.multipleImputation) {
            if (!(state.multipleImputation && isAddRow) &&
                (isAddRow ||
                [identifier isEqualToString:@"term"] ||
                [identifier isEqualToString:@"type"])) {
                [_statusField setStringValue:ToNSString(GLMPooledTableChangeInRStatus())];
                return;
            }
        }
    }
    if (isAddRow) {
        [self addPredictor:_coefView];
        return;
    }
    if (column < 0) return;
    if ([identifier isEqualToString:@"term"] && row > 0) {
        std::string term = [self sourceTermForCoefficientRow:row];
        if (IsInteractionTerm(term)) {
            NSMenu *menu = [self contextMenuForCoefficientRow:row column:column];
            GLMReportLayout layout;
            NSRect rowRect = layout.coefficientCellRect(row, column);
            [menu popUpMenuPositioningItem:nil
                                atLocation:NSMakePoint(NSMinX(rowRect) + 12.0,
                                                       NSMaxY(rowRect))
                                    inView:_coefView];
        } else {
            [self replacePredictorAtTableRow:row];
        }
    } else if ([identifier isEqualToString:@"type"] && row > 0) {
        [self showTypeMenuForTableRow:row];
    } else if (![identifier isEqualToString:@"term"] && ![identifier isEqualToString:@"type"]) {
        [self showStatisticMenuForTableRow:row column:column];
    }
}

- (void)scopeChanged:(id)sender
{
    (void)sender; // Scope is configured only through the global Analysis Scope menu.
}

- (void)autoRefitChanged:(id)sender
{
    (void)sender;
    const bool enabled = [_autoRefitButton state] == NSControlStateValueOn;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        state.autoRefit = enabled;
        // Turning Auto-refit off cancels presentation of an in-flight result.
        // Turning it back on is an explicit retry of the current immutable
        // specification, including a specification whose previous fit failed.
        state.rFitPending = false;
        if (enabled) {
            state.isStale = true;
            state.frozenScopeNotice.clear();
        }
    }
    [self refresh];
}

- (std::string)selectedTerm
{
    return [self sourceTermForCoefficientRow:_selectedCoefRow];
}

- (void)removeSelectedTerm:(id)sender
{
    std::string term = [self selectedTerm];
    if (sender && [sender respondsToSelector:@selector(representedObject)]) {
        id represented = [sender representedObject];
        if ([represented isKindOfClass:[NSString class]] && [(NSString *)represented length] > 0) {
            term = [(NSString *)represented UTF8String];
        }
    }
    if (term.empty()) {
        [_statusField setStringValue:ToNSString(GLMSelectPredictorToRemoveStatus())];
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (state.precomputed && !state.multipleImputation) {
            [_statusField setStringValue:ToNSString(GLMPrecomputedTableRefitStatus("remove predictors"))];
            return;
        }
    }
    if (!term.empty()) {
        RemoveModelTerm(_modelId, term);
    }
}

- (void)openResidualsFitted:(id)sender
{
    (void)sender;
    OpenModelDiagnosticPlot(_model, "residuals_fitted", true, _modelId);
}

- (void)explainStatistic:(id)sender
{
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    std::string statistic = [represented isKindOfClass:[NSString class]]
        ? [(NSString *)represented UTF8String] : "Model fit";
    if (statistic == "estimate") statistic = "b";
    else if (statistic == "beta") statistic = "β";
    else if (statistic == "stderr") statistic = "SE";
    else if (statistic == "stat") statistic = "t";
    else if (statistic == "partial") statistic = "Partial r";
    else if (statistic == "delta") statistic = "ΔR²";

    rlispstat::core::ModelStatisticExplanationContext context;
    context.statistic = statistic;
    context.modelFamily = "gaussian";
    context.link = "identity";
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        context.multipleImputation = state.multipleImputation;
        context.rubinRulesApplied = state.multipleImputation;
        context.miMethod = state.multipleImputation ? "mice::pool" : "";
        if (state.multipleImputation) {
            if (const DataFrameModel *dataframe = FindDataFrameUnlockedConst(_model->group)) {
                context.rubinRulesApplied =
                    !rlispstat::core::RowsWithImputedModelInputs(*dataframe, state).empty();
            }
        }
    }
    ShowWorkbenchMessageOnMain(
        ToNSString("Explain statistic: " + statistic),
        ToNSString(rlispstat::core::ExplainModelStatistic(context)));
}

