- (void)show
{
    if (!_window) {
        return;
    }
    [self activateDatasetForCommands];
    EnableNotesForWindow(_window, _model ? _model->id : "", @"this model result",
                         _model ? _model->group : std::string{});
    [_window orderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self refresh];
}

- (void)activateDatasetForCommands
{
    if (!_model) {
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        MarkActiveDatasetGroupUnlocked(_model->group);
        EnsureDatasetSeedPlotUnlocked(_model->group);
    }
    UpdateActiveDatasetMenuOnMain();
}

- (void)windowDidBecomeKey:(NSNotification *)notification
{
    (void)notification;
    [self activateDatasetForCommands];
}

- (void)refresh
{
    if (_isRefreshingLayout) {
        return;
    }
    _isRefreshingLayout = YES;
    if (!_model) {
        _isRefreshingLayout = NO;
        return;
    }
    std::string dependent;
    std::vector<std::string> terms;
    std::map<std::string, std::string> termTypes;
    bool precomputed = false;
    bool multipleImputation = false;
    bool autoRefit = true;
    int imputationCount = 0;
    std::string title;
    std::string note;
	    std::string dataScopeSummary;
	    bool dataScopeCaptured = false;
	    rlispstat::core::AnalysisScope dataScope;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        dependent = state.response;
        terms = state.terms;
        termTypes = rlispstat::core::EffectiveModelSpecificationTermTypes(state);
        _scope = state.scope;
        precomputed = state.precomputed;
        multipleImputation = state.multipleImputation;
	        autoRefit = state.autoRefit;
	        imputationCount = state.imputationCount;
	        title = state.title;
	        note = state.note;
	        if (state.dataScopeCaptured) {
	            dataScopeCaptured = true;
	            dataScope = state.dataScope;
	            dataScopeSummary = rlispstat::core::AnalysisScopeWindowSummary(
	                state.dataScope, state.dataScope.totalDatasetRows);
	        }
	    }
	    if (precomputed && multipleImputation && note.empty()) {
	        note = "Pooled multiple-imputation linear model; coefficients use Rubin's rules.";
	    }
    [_titleField setStringValue:ToNSString(title.empty() ? "Linear Model" : title)];
    [_window setTitle:ToNSString(title.empty() ? "Linear Model" : title)];
    [_badgeField setStringValue:ToNSString(multipleImputation && imputationCount > 0
        ? "m = " + std::to_string(imputationCount)
        : _model->group)];
    [_dependentPopup setEnabled:(!precomputed || multipleImputation)];
	    [_scopePopup setEnabled:(!precomputed || multipleImputation)];
    [_autoRefitButton setEnabled:(!precomputed || multipleImputation)];
    [_autoRefitButton setState:autoRefit ? NSControlStateValueOn : NSControlStateValueOff];
	    if (_scope == "compare_selected_all") _scope = "all";
	    PopulateAnalysisScopePopup(_scopePopup, _model->group, _scope,
	                               dataScope, dataScopeCaptured, true);
    [_dependentPopup removeAllItems];
    for (const NumericVariable &var : _model->variables) {
        [_dependentPopup addItemWithTitle:ToNSString(var.name)];
    }
    if (dependent.empty()) {
        [_dependentPopup selectItem:nil];
    } else {
        [_dependentPopup selectItemWithTitle:ToNSString(dependent)];
    }

    NSInteger coefficientRows = [self coefficientRowCount];
    bool fitPending = false;
    {
        // coefficientRowCount asks for currentFit, which may have queued the
        // exact new specification.  Read the flag afterwards so a predictor
        // replacement does not resize once for its provisional rows and a
        // second time for the returned factor hierarchy.
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        fitPending = state.rFitPending;
    }
    // Derive the preferred size from the current semantic rows, never from a
    // width the user may previously have stretched.  This lets response and
    // predictor changes grow or shrink the result window deterministically.
    GLMReportLayout preferredLayout = GLMReportLayout::Compute(coefficientRows, 800.0);
    NSSize fittedSize;
    if (_hasSizedToContent && fitPending) {
        // Keep the last stable outer geometry while the table already shows
        // the new canonical term names with pending values.  The definitive
        // result performs at most one content-size adjustment.
        fittedSize = [[_window contentView] frame].size;
    } else {
        fittedSize = FitResultTableWindowToContent(
            _window,
            NSMakeSize(preferredLayout.width, preferredLayout.totalHeight),
            NSMakeSize(800.0, 340.0));
    }
    _hasSizedToContent = YES;
    GLMReportLayout layout = GLMReportLayout::Compute(
        coefficientRows, fittedSize.width, fittedSize.height);

    [_titleField setFrame:layout.frameFromTop(layout.marginX, layout.titleY, 240.0, 22.0)];
    AddMissingInformationMenu([_titleField menu], "glm:" + _modelId);
    [_badgeField setFrame:layout.frameFromTop(layout.width - layout.marginX - 128.0, layout.titleY + 2.0, 128.0, 20.0)];
    [_responseLabel setFrame:layout.frameFromTop(layout.marginX, layout.controlsY + 3.0, 126.0, 22.0)];
    [_dependentPopup setFrame:layout.frameFromTop(140.0, layout.controlsY, 148.0, 28.0)];
    [_scopeLabel setFrame:layout.frameFromTop(304.0, layout.controlsY + 3.0, 46.0, 22.0)];
    [_scopePopup setFrame:layout.frameFromTop(350.0, layout.controlsY, 138.0, 28.0)];
    [_autoRefitButton setFrame:layout.frameFromTop(layout.width - layout.marginX - 206.0, layout.controlsY + 3.0, 94.0, 22.0)];
    [_selectedRowsField setFrame:layout.frameFromTop(layout.width - layout.marginX - 150.0, layout.controlsY + 28.0, 150.0, 20.0)];
    [_fitSummaryField setFrame:layout.frameFromTop(layout.marginX, layout.modelFitY, layout.width - 2.0 * layout.marginX, 36.0)];
    [_fitSummaryRule setFrame:layout.frameFromTop(layout.marginX, layout.modelFitRuleY, layout.width - 2.0 * layout.marginX, 1.0)];

    CGFloat anovaX[] = { 14.0, 122.0, 262.0, 326.0, 454.0, 560.0 };
    CGFloat anovaW[] = { 90.0, 116.0, 38.0, 98.0, 76.0, 72.0 };
    if ([_anovaHeaderFields count] > 4) {
        NSTextField *statisticHeader = [_anovaHeaderFields objectAtIndex:4];
        [statisticHeader setStringValue:[self globalModelStatisticLabel]];
    }
    for (NSUInteger i = 0; i < [_anovaHeaderFields count]; ++i) {
        NSTextField *field = [_anovaHeaderFields objectAtIndex:i];
        [field setFrame:layout.frameFromTop(anovaX[i], layout.anovaHeaderY, anovaW[i], 18.0)];
    }
    [_anovaModelField setFrame:layout.frameFromTop(anovaX[0], layout.anovaRow1Y, anovaW[0], 20.0)];
    [_anovaModelSSField setFrame:layout.frameFromTop(anovaX[1], layout.anovaRow1Y, anovaW[1], 20.0)];
    [_anovaModelDFField setFrame:layout.frameFromTop(anovaX[2], layout.anovaRow1Y, anovaW[2], 20.0)];
    [_anovaModelMSField setFrame:layout.frameFromTop(anovaX[3], layout.anovaRow1Y, anovaW[3], 20.0)];
    [_anovaModelFField setFrame:layout.frameFromTop(anovaX[4], layout.anovaRow1Y, anovaW[4], 20.0)];
    [_anovaModelPField setFrame:layout.frameFromTop(anovaX[5], layout.anovaRow1Y, anovaW[5], 20.0)];
    [_anovaResidualField setFrame:layout.frameFromTop(anovaX[0], layout.anovaRow2Y, anovaW[0], 20.0)];
    [_anovaResidualSSField setFrame:layout.frameFromTop(anovaX[1], layout.anovaRow2Y, anovaW[1], 20.0)];
    [_anovaResidualDFField setFrame:layout.frameFromTop(anovaX[2], layout.anovaRow2Y, anovaW[2], 20.0)];
    [_anovaResidualMSField setFrame:layout.frameFromTop(anovaX[3], layout.anovaRow2Y, anovaW[3], 20.0)];

    [_termsLabel setFrame:layout.frameFromTop(layout.marginX, layout.termsTitleY, 160.0, 18.0)];
    for (NSUInteger i = 0; i < [_coefHeaderFields count]; ++i) {
        NSTextField *field = [_coefHeaderFields objectAtIndex:i];
        [field setFrame:layout.frameFromTop(layout.marginX + layout.coefX[i], layout.coefHeaderY, layout.coefW[i], 18.0)];
    }
    [_coefRule setFrame:layout.frameFromTop(layout.marginX, layout.coefRuleY, layout.width - 2.0 * layout.marginX, 1.0)];
    CGFloat coefContentHeight = std::max((CGFloat)1.0, (CGFloat)coefficientRows) * layout.rowHeight;
    CGFloat coefVisibleHeight = std::max(
        layout.rowHeight, layout.statusY - 12.0 - layout.coefRowsY);
    [_coefScrollView setFrame:layout.frameFromTop(layout.marginX - 2.0, layout.coefRowsY, layout.width - 2.0 * layout.marginX + 4.0, coefVisibleHeight)];
    [_coefView setFrame:NSMakeRect(0.0, 0.0, layout.width - 2.0 * layout.marginX + 4.0, coefContentHeight)];
    [(GLMCoefficientsView *)_coefView setNeedsDisplay:YES];
    [_statusField setFrame:layout.frameFromTop(layout.marginX - 2.0, layout.statusY, layout.width - 2.0 * layout.marginX, 18.0)];

    size_t selected = SelectionCount(_model->group);
    [_selectedRowsField setStringValue:ToNSString(
        rlispstat::core::SelectedRowsStatus(selected, RowCountForGroup(_model->group)))];

	std::string fitScope;
	{
	    std::lock_guard<std::mutex> lock(g_mutex);
	    GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
	    fitScope = ScopeForModelSpecification(state);
	}
	    GLMFitSummary fit = [self currentFit];
	    if (!fit.ok) {
	        if (precomputed && multipleImputation && !note.empty()) {
	            [_statusField setStringValue:ToNSString(GLMFitNoteWarningStatus(note, fit.warning))];
	        } else {
	            [_statusField setStringValue:ToNSString(GLMStatusMessage(fit.warning))];
	        }
	        [_fitSummaryField setStringValue:ToNSString(fit.warning)];
        [_anovaModelSSField setStringValue:@""];
        [_anovaModelDFField setStringValue:@""];
        [_anovaModelMSField setStringValue:@""];
        [_anovaModelFField setStringValue:@""];
        [_anovaModelPField setStringValue:@""];
        [_anovaResidualSSField setStringValue:@""];
        [_anovaResidualDFField setStringValue:@""];
        [_anovaResidualMSField setStringValue:@""];
    } else {
        [_fitSummaryField setAttributedStringValue:GLMFitAttributedSummary(fit)];
        if (!precomputed) {
            StoreGLMFitForGroup(_modelId, fit);
            RefreshGLMDiagnosticPlotsNow(_model->group, true);
            PublishSpreadPlotMessage("GLM_REFIT_COMPLETED", _model->group, "glm:" + _modelId, "glm:" + _modelId, fit.rowsUsed);
            PublishSpreadPlotMessage("GLM_DIAGNOSTICS_UPDATED", _model->group, "glm:" + _modelId, "glm:" + _modelId, fit.rowsUsed);
        }

        [_anovaModelSSField setStringValue:ToNSString(FormatDouble(fit.ssRegression, 4))];
        [_anovaModelDFField setStringValue:ToNSString(std::to_string(fit.dfModel))];
        [_anovaModelMSField setStringValue:ToNSString(FormatDouble(fit.msRegression, 4))];
        [_anovaModelFField setStringValue:ToNSString(FormatDouble(fit.globalF, 3))];
        [_anovaModelPField setStringValue:ToNSString(FormatPValue(fit.globalP))];
        [_anovaResidualSSField setStringValue:ToNSString(FormatDouble(fit.ssResidual, 4))];
        [_anovaResidualDFField setStringValue:ToNSString(std::to_string(fit.dfResidual))];
        [_anovaResidualMSField setStringValue:ToNSString(FormatDouble(fit.msResidual, 4))];

        if (precomputed && !note.empty()) {
            [_statusField setStringValue:ToNSString(GLMStatusMessage(note))];
        } else {
            [_statusField setStringValue:ToNSString(GLMFittedStatus(fit.n, fit.excluded, fitScope))];
        }
    }
    if (!dataScopeSummary.empty()) {
        NSString *status = [_statusField stringValue] ?: @"";
        [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
            ToNSString(dataScopeSummary)]];
    }
    if (fit.ok) {
        std::lock_guard<std::mutex> lock(g_mutex);
        const auto found = g_groupModels.find(_modelId);
        if (found != g_groupModels.end() && !found->second.frozenScopeNotice.empty()) {
            NSString *status = [_statusField stringValue] ?: @"";
            [_statusField setStringValue:[status stringByAppendingFormat:@" · %@",
                ToNSString(found->second.frozenScopeNotice)]];
        }
    }
    _isRefreshingLayout = NO;
}

- (void)openModelComparison:(id)sender
{
    (void)sender;
    if (!_model) return;

    GLMFitSummary fit = [self currentFit];
    GroupModelState source;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        source = EnsureGroupModelUnlocked(_modelId, _model);
    }
    const std::string comparisonId = "regcmp_" + source.group + "_" +
        std::to_string((long long)time(nullptr)) + "_" +
        std::to_string((long long)g_regressionComparisons.size() + 1);
    RegressionComparisonState comparison =
        rlispstat::core::CreateRegressionComparisonFromSingleModel(
            comparisonId, source, fit.ok ? &fit : nullptr, _model, "Model 1");
    const bool needsFit = comparison.models.empty() ||
        rlispstat::core::RegressionComparisonResolvedFitState(
            comparison, comparison.models.front()) !=
            rlispstat::core::RegressionComparisonFitState::Valid;
    g_regressionComparisons[comparisonId] = std::move(comparison);
    RegressionComparisonState &stored = g_regressionComparisons[comparisonId];
    // A multiple-imputation model is marked precomputed because its existing
    // table came from R.  The comparison itself is nevertheless editable and
    // has a supported main-R pooled refit path.  If the source fit cannot be
    // reused verbatim, queue that path instead of leaving a permanently blank
    // comparison.  Only immutable non-MI precomputed tables stay unrefitted.
    if (needsFit && (!stored.precomputed || stored.multipleImputation)) {
        RequestRegressionComparisonFitInMainR(stored);
    }
    ShowRegressionComparisonOnMain(comparisonId);
}

- (void)windowDidResize:(NSNotification *)notification
{
    (void)notification;
    [self refresh];
}

- (void)windowWillClose:(NSNotification *)notification
{
    (void)notification;
    std::lock_guard<std::mutex> lock(g_mutex);
    g_glmControllers.erase(_modelId);
    auto state = g_groupModels.find(_modelId);
    if (state != g_groupModels.end()) {
        g_groupModels.erase(state);
    }
    g_precomputedLinearModelFits.erase(_modelId);
    MacCommandDispatcher().applicationState().eraseOutputCodeReference("glm:" + _modelId);
}
@end

static void ShowGLMOnMain(PlotModel *model, bool copyLegacyState)
{
    if (!model) return;
    const std::string group = model->group;
    std::string modelId;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (!FindDataFrameUnlockedConst(group)) return;
        modelId = rlispstat::core::CreateLinearModelInstance(g_groupModels, group);
        GroupModelState &state = g_groupModels.at(modelId);
        auto legacy = g_groupModels.find(group);
        if (copyLegacyState && legacy != g_groupModels.end() &&
            (!legacy->second.response.empty() || legacy->second.precomputed)) {
            const std::string defaultTitle = state.title;
            state = legacy->second;
            state.modelId = modelId;
            state.group = group;
            if (state.title.empty()) state.title = defaultTitle;
            auto fit = g_precomputedLinearModelFits.find(group);
            if (fit != g_precomputedLinearModelFits.end())
                g_precomputedLinearModelFits[modelId] = fit->second;
        } else {
            const DataFrameModel *dataframe = FindDataFrameUnlockedConst(group);
            const auto initial = rlispstat::core::ResolveInitialAnalysisSpecification(
                *dataframe,
                rlispstat::core::SharedAnalysisDefinition(
                    rlispstat::core::SharedAnalysisKind::LinearModel),
                rlispstat::core::DefaultVariableRolesForAnalysisInitialization(
                    MacCommandDispatcher().applicationState().variableRoles(group)));
            state.response = rlispstat::core::InitialAnalysisVariable(initial, "response");
            state.terms = rlispstat::core::InitialAnalysisVariables(initial, "predictors");
            state.multipleImputation = GroupIsMultipleImputationUnlocked(group);
            state.imputationCount = state.multipleImputation
                ? std::max(1, dataframe->imputationCount) : 0;
        }
        if (!state.dataScopeCaptured) {
            CaptureActiveAnalysisScopeUnlocked(group, state.dataScope, state.dataScopeCaptured);
            if (state.dataScope.kind == rlispstat::core::AnalysisScopeKind::AllObservations)
                state.dataScopeCaptured = false;
            state.scope = ScopeForCapturedAnalysisScope(
                state.dataScope, state.dataScopeCaptured, "all");
        }
        if (!state.precomputed) rlispstat::core::MarkGroupModelChanged(state);
        auto fit = g_precomputedLinearModelFits.find(modelId);
        if (fit != g_precomputedLinearModelFits.end() &&
            !state.provenance.executedRCode.empty())
            MacCommandDispatcher().applicationState().registerOutputCodeReference(
                rlispstat::core::LinearModelCodeReference(state, fit->second));
    }
    dispatch_async(dispatch_get_main_queue(), ^{
        PlotModel *plot = nullptr;
        GLMWindowController *previous = nil;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            plot = FirstPlotForGroupUnlocked(group);
            for (const auto &entry : g_glmControllers) {
                auto state = g_groupModels.find(entry.first);
                if (state != g_groupModels.end() && state->second.group == group)
                    previous = entry.second;
            }
        }
        if (!plot) return;
        GLMWindowController *controller =
            [[GLMWindowController alloc] initWithModel:plot modelId:modelId];
        [controller positionBesideModelWindow:previous];
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            g_glmControllers[modelId] = controller;
        }
        [controller show];
    });
}

static void RefreshGLMOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::vector<GLMWindowController *> controllers;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          for (const auto &entry : g_glmControllers) {
              auto state = g_groupModels.find(entry.first);
              if (entry.first == groupCopy ||
                  (state != g_groupModels.end() && state->second.group == groupCopy))
                  controllers.push_back(entry.second);
      }
      }
      for (GLMWindowController *controller : controllers) [controller refresh];
    });
}

