static void ShowNewCorrelationMatrixOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    const auto initial = ResolveInitialAnalysisForGroup(
        dataframe, rlispstat::core::SharedAnalysisKind::CorrelationMatrix);
    bool multipleImputation = GroupIsMultipleImputation(model->group);
    CorrelationMatrixState state;
    state.id = "corr_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.title = multipleImputation ? "Pearson Correlation Matrix - Multiple Imputation"
                                     : "Pearson Correlation Matrix";
    state.method = "pearson";
    state.missingMode = "pairwise";
    state.showP = true;
    state.showPValue = false;
    state.showN = false;
    state.multipleImputation = multipleImputation;
    state.variables = rlispstat::core::InitialAnalysisVariables(initial, "variables");
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    if (initial.minimumValid) RefitCorrelationMatrixState(state);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_correlationMatrices[state.id] = state;
    }
    ShowCorrelationMatrixOnMain(state.id);
}

static void ShowCorrelationMatrixForVariablesOnMain(PlotModel *model,
                                                    const std::vector<std::string> &variables,
                                                    const std::string &title)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    bool multipleImputation = GroupIsMultipleImputation(model->group);
    CorrelationMatrixState state;
    state.id = "corr_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.title = !title.empty()
        ? title
        : (multipleImputation ? "Pearson Correlation Matrix - Multiple Imputation" : "Pearson Correlation Matrix");
    state.method = "pearson";
    state.missingMode = "pairwise";
    state.showP = true;
    state.showPValue = false;
    state.showN = true;
    state.multipleImputation = multipleImputation;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    for (const std::string &name : variables) {
        if (name.empty() || !FindVariable(model, name)) continue;
        if (std::find(state.variables.begin(), state.variables.end(), name) == state.variables.end()) {
            state.variables.push_back(name);
        }
    }
    if (state.variables.size() < 2) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::CorrelationWindowTitle()), ToNSString(rlispstat::core::CorrelationMatrixNeedsTwoNumericStatus()));
        return;
    }
    RefitCorrelationMatrixState(state);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_correlationMatrices[state.id] = state;
    }
    ShowCorrelationMatrixOnMain(state.id);
}

static void ShowNewDimensionalityOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::DimensionalityWindowTitle()), ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    const auto initial = ResolveInitialAnalysisForGroup(
        dataframe, rlispstat::core::SharedAnalysisKind::Dimensionality);
    DimensionalityState state;
    state.id = "dim_" + model->group + "_" + std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.method = "pca";
    state.missingMode = "listwise";
    state.scale = true;
    state.variables = rlispstat::core::InitialAnalysisVariables(initial, "variables");
    state.componentCount = std::min<int>(2, (int)state.variables.size());
    state.seed = *model;
    state.hasSeed = true;
    state.multipleImputation = dataframe.datasetType == "multiple_imputation" ||
        dataframe.imputationCount > 1;
    state.imputationCount = state.multipleImputation
        ? std::max(1, dataframe.imputationCount) : 1;
    state.displayedImputation = state.multipleImputation
        ? std::max(1, std::min(state.imputationCount, dataframe.activeImputationVersion)) : 1;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    if (initial.minimumValid) RefitDimensionalityState(state);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_dimensionalityModels[state.id] = state;
    }
    ShowDimensionalityOnMain(state.id);
}

static void ShowNewScaleAnalysisOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Scale Analysis",
            ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;

    ScaleAnalysisState state;
    state.id = "scale_" + model->group + "_" +
        std::to_string((long long)time(nullptr)) + "_" +
        std::to_string(g_scaleAnalyses.size() + 1U);
    state.group = model->group;
    state.specification.datasetId = model->group;
    state.specification.items = rlispstat::core::InitialScaleItems(dataframe, {});
    state.specification.revision = 1;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(
            state.group, state.dataScope, state.dataScopeCaptured);
    }
    std::string error;
    if (!rlispstat::core::ValidateScaleAnalysisSpecification(
            dataframe, state.specification, error)) {
        ShowWorkbenchMessageOnMain(@"Scale Analysis", ToNSString(error));
        return;
    }
    state.modelVersion = state.specification.revision;
    state.status = state.specification.items.size() < 2
        ? "Choose at least two numeric or ordinal items."
        : "Fitting Scale Analysis in the main R session...";
    const std::string analysisId = state.id;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_scaleAnalyses[analysisId] = std::move(state);
    }
    ShowScaleAnalysisOnMain(analysisId);
    auto found = g_scaleAnalyses.find(analysisId);
    if (found != g_scaleAnalyses.end() && found->second.specification.items.size() >= 2) {
        RequestScaleAnalysisFitInMainR(found->second);
    }
}

