static void ShowNewGeneralizedGLMOnMain(
    PlotModel *model,
    rlispstat::core::StatisticalModelType modelType)
{
    const bool countModel = modelType == rlispstat::core::StatisticalModelType::Count;
    const std::string modelTitle = rlispstat::core::StatisticalModelTypeLabel(modelType);
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(modelTitle),
                                   ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    const auto variableRoles = FreshRegressionVariableRolesSnapshot(model->group);
    const bool multipleImputation = GroupIsMultipleImputation(model->group);
    int imputationCount = 0;
    if (multipleImputation) {
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
            if (current) {
                found = true;
                imputationCount = std::max(1, current->imputationCount);
            }
        }
        if (!found) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMWindowTitle()), ToNSString(rlispstat::core::GLMImputedDatasetNotAvailableStatus()));
            return;
        }
    }
    AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(model->group, dataScope, dataScopeCaptured);
    }
    auto state = rlispstat::core::CreateIndependentGeneralizedGLMSession(
        "gglm_" + model->group + "_" + std::to_string((long long)time(nullptr)),
        model->group, *model, dataframe,
        modelType == rlispstat::core::StatisticalModelType::Count
            ? rlispstat::core::SharedAnalysisKind::CountRegression
        : modelType == rlispstat::core::StatisticalModelType::PositiveContinuous
            ? rlispstat::core::SharedAnalysisKind::PositiveContinuousModel
        : modelType == rlispstat::core::StatisticalModelType::Proportion
            ? rlispstat::core::SharedAnalysisKind::ProportionModel
            : rlispstat::core::SharedAnalysisKind::GeneralizedLinearModel,
        variableRoles, dataScope,
        ScopeForCapturedAnalysisScope(dataScope, dataScopeCaptured, "all"));
    state.dataScopeCaptured = dataScopeCaptured;
    state.multipleImputation = multipleImputation;
    state.imputationCount = imputationCount;
    state.status = state.response.empty()
        ? (countModel ? "Choose a valid count response variable."
                      : "Choose a response compatible with " + modelTitle + ".")
        : (state.terms.empty() && !countModel ? rlispstat::core::GLMAddPredictorBeforeTableStatus()
                                             : "Fitting " + modelTitle + " in the main R session...");
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedGLMs[state.id] = state;
    }
    if (!state.response.empty() && (!state.terms.empty() || state.countRegression)) {
        auto it = g_generalizedGLMs.find(state.id);
        if (it != g_generalizedGLMs.end()) RequestGeneralizedGLMFitInMainR(it->second);
    }
    ShowGeneralizedGLMOnMain(state.id);
}

static void ShowNewBinaryRegressionOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Binary Model", ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    const bool multipleImputation = GroupIsMultipleImputation(model->group);
    if (multipleImputation &&
        !rlispstat::core::SharedAnalysisSupportsMultipleImputation(
            rlispstat::core::SharedAnalysisKind::BinaryRegression)) {
        ShowWorkbenchMessageOnMain(@"Binary Model",
            @"Binary Model is unavailable for multiple-imputation datasets.");
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    const auto variableRoles = FreshRegressionVariableRolesSnapshot(model->group);
    AnalysisScope dataScope;
    bool dataScopeCaptured = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(model->group, dataScope, dataScopeCaptured);
    }
    auto state = rlispstat::core::CreateIndependentGeneralizedGLMSession(
        "binary_" + model->group + "_" + std::to_string((long long)time(nullptr)) +
            "_" + std::to_string((long long)g_generalizedGLMs.size() + 1),
        model->group, *model, dataframe,
        rlispstat::core::SharedAnalysisKind::BinaryRegression,
        variableRoles, dataScope,
        ScopeForCapturedAnalysisScope(dataScope, dataScopeCaptured, "all"));
    state.dataScopeCaptured = dataScopeCaptured;
    state.multipleImputation = multipleImputation;
    state.imputationCount = multipleImputation ? std::max(1, dataframe.imputationCount) : 0;
    state.status = state.response.empty() ? rlispstat::core::GLMChooseResponseVariableStatus()
        : (state.terms.empty() ? rlispstat::core::GLMAddPredictorBeforeTableStatus()
                               : "Fitting binary regression in the main R session...");
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedGLMs[state.id] = state;
    }
    ShowGeneralizedGLMOnMain(state.id);
    if (!state.response.empty()) {
        auto it = g_generalizedGLMs.find(state.id);
        if (it != g_generalizedGLMs.end()) RequestGeneralizedGLMFitInMainR(it->second);
    }
}

static void ShowNewGeneralizedComparisonOnMain(
    PlotModel *model, rlispstat::core::StatisticalModelType modelType)
{
    const bool countComparison =
        modelType == rlispstat::core::StatisticalModelType::Count;
    const std::string comparisonTitle =
        rlispstat::core::StatisticalModelComparisonTitle(modelType);
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(ToNSString(comparisonTitle),
                                   ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    const bool multipleImputation = GroupIsMultipleImputation(model->group);
    const auto comparisonKind = rlispstat::core::SharedAnalysisKind::GeneralizedComparison;
    if (multipleImputation &&
        !rlispstat::core::SharedAnalysisSupportsMultipleImputation(comparisonKind)) {
        ShowWorkbenchMessageOnMain(ToNSString(comparisonTitle),
                                   ToNSString(rlispstat::core::GLMComparisonRequiresPooledTestStatus()));
        return;
    }
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    const auto initial = rlispstat::core::ResolveInitialAnalysisSpecification(
        dataframe,
        rlispstat::core::SharedAnalysisDefinition(
            countComparison ? rlispstat::core::SharedAnalysisKind::CountRegression
            : modelType == rlispstat::core::StatisticalModelType::PositiveContinuous
                ? rlispstat::core::SharedAnalysisKind::PositiveContinuousModel
            : modelType == rlispstat::core::StatisticalModelType::Proportion
                ? rlispstat::core::SharedAnalysisKind::ProportionModel
                : rlispstat::core::SharedAnalysisKind::GeneralizedComparison),
        FreshRegressionVariableRolesSnapshot(model->group));
    GeneralizedComparisonState state;
    const std::string idPrefix = countComparison ? "countcmp_"
        : modelType == rlispstat::core::StatisticalModelType::PositiveContinuous
            ? "positivecmp_"
        : modelType == rlispstat::core::StatisticalModelType::Proportion
            ? "proportioncmp_" : "gglmcmp_";
    state.id = idPrefix + model->group + "_" +
        std::to_string((long long)time(nullptr));
    state.group = model->group;
    state.modelType = modelType;
    state.seed = *model;
    state.hasSeed = true;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    state.response = rlispstat::core::InitialAnalysisVariable(initial, "response");
    state.countComparison = countComparison;
    state.multipleImputation = multipleImputation;
    state.imputationCount = multipleImputation
        ? std::max(1, dataframe.imputationCount) : 0;
    rlispstat::core::SynchronizeGeneralizedComparisonDatasetIdentity(state, dataframe);
    const auto distributions =
        rlispstat::core::DistributionSpecificationsForModel(modelType);
    state.family = countComparison ? "poisson"
        : modelType == rlispstat::core::StatisticalModelType::LegacyGeneralized
            ? (state.response.empty() ? "gaussian"
                                      : DefaultGeneralizedFamilyForResponse(*model, state.response))
        : distributions.empty() ? "" : distributions.front().id;
    state.link = modelType == rlispstat::core::StatisticalModelType::LegacyGeneralized
        ? DefaultGeneralizedLink(state.family)
        : rlispstat::core::DefaultLinkForModelDistribution(modelType, state.family);
    if (!state.response.empty() &&
        modelType != rlispstat::core::StatisticalModelType::LegacyGeneralized &&
        !countComparison) {
        const DataColumn *responseColumn =
            FindDataColumnInDataFrame(dataframe, state.response);
        const auto *distribution =
            rlispstat::core::FindDistributionSpecification(state.family);
        if (!responseColumn || !distribution ||
            !rlispstat::core::InspectResponseDomain(
                *responseColumn, distribution->responseDomain).ok) {
            state.response.clear();
        }
    }
    GeneralizedComparisonModel modelOne;
    modelOne.id = state.id + ":model:1";
    modelOne.label = "Model 1";
    modelOne.response = state.response;
    modelOne.family = state.family;
    modelOne.link = state.link;
    if (modelType == rlispstat::core::StatisticalModelType::Proportion) {
        modelOne.responseBoundsConfigured = true;
        modelOne.responseLower = 0.0;
        modelOne.responseUpper = 1.0;
    }
    modelOne.countDistribution = rlispstat::core::CountDistribution::Poisson;
    // Materialize dataset defaults in the model instance.  state.termTypes is
    // presentation/default metadata, never the source of truth for a column.
    modelOne.modelVersion = 1;
    for (const std::string &term :
         rlispstat::core::InitialAnalysisVariables(initial, "predictors")) {
        if (term != state.response && ModelTermExistsForModel(model, term, state.response)) {
            modelOne.terms.push_back(term);
            AddGeneralizedComparisonTermRow(state, term);
        }
    }
    modelOne.candidateTerms = modelOne.terms;
    state.models.push_back(modelOne);
    RefreshGeneralizedTermRowsFromFits(state);
    state.activeModel = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedComparisons[state.id] = state;
    }
    GeneralizedComparisonState &stored = g_generalizedComparisons[state.id];
    if (!stored.response.empty())
        RefitGeneralizedComparisonModels(stored, true);
    ShowGeneralizedComparisonOnMain(state.id);
}

static void ShowNewBinaryRegressionComparisonOnMain(PlotModel *model)
{
    model = ActiveDatasetCommandModel(model);
    if (!model) {
        ShowWorkbenchMessageOnMain(@"Compare Binary Models", ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    const bool multipleImputation = GroupIsMultipleImputation(model->group);
    if (multipleImputation &&
        !rlispstat::core::SharedAnalysisSupportsMultipleImputation(
            rlispstat::core::SharedAnalysisKind::GeneralizedComparison)) {
        ShowWorkbenchMessageOnMain(@"Compare Binary Models",
            ToNSString(rlispstat::core::GLMComparisonRequiresPooledTestStatus()));
        return;
    }
    GeneralizedComparisonState state;
    state.id = "binarycmp_" + model->group + "_" + std::to_string((long long)time(nullptr)) +
        "_" + std::to_string((long long)g_generalizedComparisons.size() + 1);
    state.group = model->group;
    state.modelType = rlispstat::core::StatisticalModelType::Binary;
    state.family = "binomial";
    state.binaryLink = rlispstat::core::BinaryLink::Logit;
    state.link = rlispstat::core::BinaryLinkId(state.binaryLink);
    state.scope = "all";
    state.binaryComparison = true;
    state.autoRefit = true;
    state.seed = *model;
    state.hasSeed = true;
    DataFrameModel dataframe;
    if (!DataFrameSnapshotForGroup(model->group, dataframe)) return;
    state.multipleImputation = multipleImputation;
    state.imputationCount = multipleImputation
        ? std::max(1, dataframe.imputationCount) : 0;
    rlispstat::core::SynchronizeGeneralizedComparisonDatasetIdentity(state, dataframe);
    const auto initial = rlispstat::core::ResolveInitialAnalysisSpecification(
        dataframe,
        rlispstat::core::SharedAnalysisDefinition(
            rlispstat::core::SharedAnalysisKind::BinaryRegression),
        FreshRegressionVariableRolesSnapshot(model->group));
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }
    state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
    state.response = rlispstat::core::InitialAnalysisVariable(initial, "response");
    if (!state.response.empty()) {
        const DataColumn *column = FindDataColumnForModel(model, state.response);
        if (column) {
            rlispstat::core::BinaryResponseCoding coding = rlispstat::core::InspectBinaryResponse(*column);
            if (coding.ok) {
                state.responseCoding = coding;
            }
        }
    }
    GeneralizedComparisonModel modelOne;
    modelOne.id = state.id + ":model:1";
    modelOne.label = "Model 1";
    modelOne.response = state.response;
    modelOne.family = "binomial";
    modelOne.link = state.link;
    // Keep every comparison column semantically self-contained.  In
    // particular, a model-local factor interpretation must not depend on the
    // mutable comparison-wide default map.
    modelOne.modelVersion = 1;
    for (const std::string &term :
         rlispstat::core::InitialAnalysisVariables(initial, "predictors")) {
        if (term != state.response && ModelTermExistsForModel(model, term, state.response)) {
            modelOne.terms.push_back(term);
            AddGeneralizedComparisonTermRow(state, term);
        }
    }
    modelOne.candidateTerms = modelOne.terms;
    state.models.push_back(modelOne);
    RefreshGeneralizedTermRowsFromFits(state);
    state.activeModel = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_generalizedComparisons[state.id] = state;
    }
    GeneralizedComparisonState &stored = g_generalizedComparisons[state.id];
    if (!stored.response.empty() && stored.responseCoding.ok)
        RefitGeneralizedComparisonModels(stored, true);
    ShowGeneralizedComparisonOnMain(state.id);
}

static bool RunNativeMixedModelReport(const NativeMixedModelState &state, std::string *report, std::string *message)
{
    QueueMixedModelMainRTask(state);
    if (report) {
        *report = "Fitting mixed model in the main R session...";
    }
    if (message) {
        message->clear();
    }
    return true;
}

static void ShowNewNativeMixedModelOnMain(PlotModel *model, bool generalized)
{
    model = ActiveDatasetCommandModel(model);
    NSString *title = generalized ? ToNSString(rlispstat::core::MixedModelGeneralizedWindowTitle()) : ToNSString(rlispstat::core::MixedModelLinearWindowTitle());
    if (!model) {
        ShowWorkbenchMessageOnMain(title, ToNSString(NoActiveDatasetImportOrRegisterStatus()));
        return;
    }
    DataFrameModel df;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
        if (current) {
            df = *current;
            found = true;
        }
    }
    if (!found) {
        ShowWorkbenchMessageOnMain(title, ToNSString(ActiveDatasetUnavailableStatus()));
        return;
    }

    const auto initial = ResolveInitialAnalysisForGroup(
        df, generalized
            ? rlispstat::core::SharedAnalysisKind::GeneralizedMixedModel
            : rlispstat::core::SharedAnalysisKind::LinearMixedModel);
    NativeMixedModelState state;
    state.id = std::string(generalized ? "glmm_" : "lmm_") + model->group + "_" +
        std::to_string(static_cast<long long>(time(nullptr)));
    state.group = model->group;
    state.modelType = generalized ? "generalized_linear_mixed_model" : "linear_mixed_model";
    state.method = generalized ? "ML" : "REML";
    state.family = "binomial";
    state.link = "logit";
    state.response = rlispstat::core::InitialAnalysisVariable(initial, "response");
    state.fixedEffects = rlispstat::core::InitialAnalysisVariables(initial, "fixed_effects");
    const std::string randomGroup =
        rlispstat::core::InitialAnalysisVariable(initial, "group");
    if (!randomGroup.empty()) {
        NativeMixedRandomSpec random;
        random.group = randomGroup;
        random.terms.push_back("1");
        random.covariance = "|";
        state.randomEffects.push_back(std::move(random));
    }
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
    }

    std::string report;
    std::string message;
    if (!state.response.empty() && !state.randomEffects.empty()) {
        if (!RunNativeMixedModelReport(state, &report, &message)) {
            ShowWorkbenchMessageOnMain(title, ToNSString(message));
            return;
        }
    } else {
        report = generalized ? "Generalized Linear Mixed Model\n" : "Linear Mixed Model\n";
        report += "Dataset: " + model->group + "\n";
        report += "Response: " + state.response + "\nWarnings\n";
        report += state.response.empty()
            ? "Choose a response variable from the context menu.\n"
            : "Choose a grouping variable for the random effect from the context menu.\n";
    }
    state.reportText = report;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        g_nativeMixedModels[state.id] = state;
    }
    ShowMixedModelTextOnMain(state.id, state.group, state.modelType, report);
}

static void RefreshRegressionComparisonWindowsOnMain(const std::string &group, bool selectionChanged)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::vector<RegressionComparisonWindowController *> controllers;
      for (const auto &entry : g_regressionComparisonControllers) {
          RegressionComparisonWindowController *controller = entry.second;
          RegressionComparisonState *state = [controller state];
          if (state && state->group == groupCopy) {
              if (selectionChanged && state->autoRefit && state->scope != "all" && !state->dataScopeCaptured) {
                  for (RegressionComparisonModel &model : state->models) {
                      rlispstat::core::InvalidateRegressionComparisonModel(*state, model);
                  }
              }
              controllers.push_back(controller);
          }
      }
      for (RegressionComparisonWindowController *controller : controllers) {
          [controller refresh];
      }
    });
}

static void RefreshGeneralizedComparisonWindowsOnMain(const std::string &group, bool selectionChanged)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      std::vector<GeneralizedComparisonWindowController *> controllers;
      for (const auto &entry : g_generalizedComparisonControllers) {
          GeneralizedComparisonWindowController *controller = entry.second;
          GeneralizedComparisonState *state = [controller state];
          if (state && state->group == groupCopy) {
              if (selectionChanged && state->autoRefit && state->scope != "all" && !state->dataScopeCaptured) {
                  for (GeneralizedComparisonModel &model : state->models) {
                      rlispstat::core::InvalidateGeneralizedComparisonModel(*state, model);
                  }
              }
              controllers.push_back(controller);
          }
      }
      for (GeneralizedComparisonWindowController *controller : controllers) {
          [controller refresh];
      }
    });
}

static void ShowVariablesWindowOnMain(const std::string &group)
{
    std::string groupCopy = group;
    dispatch_async(dispatch_get_main_queue(), ^{
      VariablesWindowController *controller = nil;
      bool hasDataset = false;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          hasDataset = DatasetExistsUnlocked(groupCopy) || FirstPlotForGroupUnlocked(groupCopy) != nullptr;
          if (hasDataset) {
              EnsureDatasetSeedPlotUnlocked(groupCopy);
          }
          auto it = g_variableControllers.find(groupCopy);
          if (it != g_variableControllers.end()) {
              controller = it->second;
          }
      }
      if (!hasDataset) {
          ShowWorkbenchMessageOnMain(ToNSString(VariableViewTitle()), ToNSString(DatasetNotRegisteredStatus(groupCopy)));
          return;
      }
      if (!controller) {
          controller = [[VariablesWindowController alloc] initWithGroup:groupCopy];
          std::lock_guard<std::mutex> lock(g_mutex);
          g_variableControllers[groupCopy] = controller;
      }
      [controller show];
    });
}

