static std::optional<std::string> PromptForSubsetDatasetName(
    const std::string &suggestedName,
    std::size_t rowCount,
    std::size_t columnCount = 0)
{
    std::string previousValue = suggestedName;
    while (true) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Make Subset"];
        [alert setInformativeText:columnCount > 0
            ? [NSString stringWithFormat:
                @"Create a new dataset containing %lu observations and %lu variables.",
                (unsigned long)rowCount, (unsigned long)columnCount]
            : [NSString stringWithFormat:
                @"Create a new dataset containing %lu observations.",
                (unsigned long)rowCount]];
        [alert addButtonWithTitle:@"Create Subset"];
        [alert addButtonWithTitle:@"Cancel"];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 320, 24)];
        [field setStringValue:ToNSString(previousValue)];
        [field setPlaceholderString:@"Subset name"];
        [field setAccessibilityLabel:@"Subset dataset name"];
        [alert setAccessoryView:field];
        [[alert window] setInitialFirstResponder:field];
        const NSModalResponse response = [alert runModal];
        previousValue = rlispstat::core::NormalizeAnalysisScopeSelectionName(
            [[field stringValue] UTF8String]);
        [field release];
        [alert release];
        if (response != NSAlertFirstButtonReturn) return std::nullopt;
        std::string error;
        if (rlispstat::core::ValidateAnalysisScopeSelectionName(previousValue, &error)) {
            return previousValue;
        }
        NSAlert *errorAlert = [[NSAlert alloc] init];
        [errorAlert setMessageText:@"Name the subset"];
        [errorAlert setInformativeText:ToNSString(error)];
        [errorAlert addButtonWithTitle:@"OK"];
        [errorAlert runModal];
        [errorAlert release];
    }
}

static std::optional<std::vector<std::string>> PromptForSubsetVariables(
    const DataFrameModel &source)
{
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Select variables for the subset"];
    [alert setInformativeText:@"Choose the variables to keep. All observations will be retained."];
    [alert addButtonWithTitle:@"Continue"];
    [alert addButtonWithTitle:@"Cancel"];
    const CGFloat width = 440;
    const CGFloat rowHeight = 25;
    const CGFloat documentHeight = std::max<CGFloat>(300, rowHeight * source.columns.size());
    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(0, 0, width, 300)];
    [scroll setHasVerticalScroller:YES];
    [scroll setBorderType:NSBezelBorder];
    NSView *list = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, width - 20, documentHeight)];
    NSMutableArray<NSButton *> *checks = [[NSMutableArray alloc] init];
    for (std::size_t i = 0; i < source.columns.size(); ++i) {
        const DataColumn &column = source.columns[i];
        NSButton *check = [[NSButton alloc] initWithFrame:NSMakeRect(
            8, documentHeight - rowHeight * (i + 1), width - 40, rowHeight)];
        [check setButtonType:NSButtonTypeSwitch];
        [check setTitle:ToNSString(column.name)];
        [check setState:NSControlStateValueOff];
        [check setAccessibilityLabel:ToNSString("Keep variable " + column.name)];
        [list addSubview:check];
        [checks addObject:check];
        [check release];
    }
    [scroll setDocumentView:list];
    [[scroll contentView] scrollToPoint:NSMakePoint(0, documentHeight - 300)];
    [scroll reflectScrolledClipView:[scroll contentView]];
    [list release];
    [alert setAccessoryView:scroll];
    const NSModalResponse response = [alert runModal];
    std::optional<std::vector<std::string>> selected;
    if (response == NSAlertFirstButtonReturn) {
        selected = std::vector<std::string>{};
        for (std::size_t i = 0; i < source.columns.size(); ++i) {
            if ([[checks objectAtIndex:i] state] == NSControlStateValueOn)
                selected->push_back(source.columns[i].name);
        }
    }
    [checks release];
    [scroll release];
    [alert release];
    return selected;
}

static void MakeVariableSubsetOnMain(const std::string &group)
{
    DataFrameModel sourceSnapshot;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *source = FindDataFrameUnlockedConst(group);
        if (!source) return;
        sourceSnapshot = *source;
    }
    const auto variables = PromptForSubsetVariables(sourceSnapshot);
    if (!variables.has_value()) return;
    if (variables->empty()) {
        ShowWorkbenchMessageOnMain(@"Make Subset", @"Select at least one variable.");
        return;
    }
    const std::string proposal = UniqueNativeDatasetNameFromBase(group + " variables");
    const auto requestedName = PromptForSubsetDatasetName(
        proposal, static_cast<std::size_t>(sourceSnapshot.rows), variables->size());
    if (!requestedName.has_value()) return;
    DataFrameModel subset;
    std::string outputGroup;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *source = FindDataFrameUnlockedConst(group);
        if (!source) {
            ShowWorkbenchMessageOnMain(@"Make Subset", @"The source dataset is no longer available.");
            return;
        }
        outputGroup = MacCommandDispatcher().applicationState().datasets().uniqueDatasetName(
            *requestedName);
        subset = rlispstat::core::SubsetDataFrameColumns(*source, *variables, outputGroup);
        if (subset.columns.size() != variables->size()) {
            ShowWorkbenchMessageOnMain(@"Make Subset", @"A selected variable is no longer available.");
            return;
        }
        MacCommandDispatcher().applicationState().registerDataset(subset);
        EnsureDatasetSeedPlotUnlocked(outputGroup);
        MarkActiveDatasetGroupUnlocked(outputGroup);
    }
    if (!QueueNativeDatasetSyncToR(subset)) {
        ShowWorkbenchMessageOnMain(@"Make Subset",
            @"The subset was created in LinkEDA, but R synchronization failed.");
    }
    UpdateActiveDatasetMenuOnMain();
    UpdateAnalysisScopeStatusOnMain();
    ShowDataSheetOnMain(outputGroup);
    UpdatePanelOnMain();
}

static void MakeSubsetOnMain(const std::string &group,
                             const std::vector<int> &rows,
                             const std::string &sourceName)
{
    if (rows.empty()) {
        ShowWorkbenchMessageOnMain(@"Make Subset", @"The chosen selection contains no observations.");
        return;
    }
    const std::string proposal = UniqueNativeDatasetNameFromBase(
        group + " subset" + (sourceName.empty() ? "" : " - " + sourceName));
    const std::optional<std::string> requestedName =
        PromptForSubsetDatasetName(proposal, rows.size());
    if (!requestedName.has_value()) return;

    std::string outputGroup;
    DataFrameModel subset;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *source = FindDataFrameUnlockedConst(group);
        if (!source) {
            ShowWorkbenchMessageOnMain(@"Make Subset", @"The source dataset is no longer available.");
            return;
        }
        outputGroup = MacCommandDispatcher().applicationState().datasets().uniqueDatasetName(
            *requestedName);
        subset = rlispstat::core::SubsetDataFrame(*source, rows, outputGroup);
        if (subset.rows == 0) {
            ShowWorkbenchMessageOnMain(@"Make Subset", @"The chosen selection contains no valid observations.");
            return;
        }
        MacCommandDispatcher().applicationState().registerDataset(subset);
        EnsureDatasetSeedPlotUnlocked(outputGroup);
        MarkActiveDatasetGroupUnlocked(outputGroup);
    }
    if (!QueueNativeDatasetSyncToR(subset)) {
        ShowWorkbenchMessageOnMain(
            @"Make Subset",
            @"The subset was created in LinkEDA, but it could not be synchronized with the connected R session. R-backed analyses may be unavailable until the dataset is recreated.");
    }
    UpdateActiveDatasetMenuOnMain();
    UpdateAnalysisScopeStatusOnMain();
    ShowDataSheetOnMain(outputGroup);
    UpdatePanelOnMain();
}

static bool ToggleSmoothCurvesForScope(PlotModel *model, rlispstat::core::SmoothCurveScope scope)
{
    if (!model) return false;
    const bool wasPresent = rlispstat::core::SmoothCurveScopeIsPresent(model->smoothCurves, scope);
    bool changed = rlispstat::core::ToggleSmoothCurveScopePending(model->smoothCurves, scope);
    if (changed && wasPresent && model->kind == "trellis_scatterplot") {
        for (auto &panel : model->trellisPanelSmoothCurves) {
            panel.second.erase(std::remove_if(panel.second.begin(), panel.second.end(),
                [&](const rlispstat::core::SmoothCurveData &curve) {
                    return curve.scope == scope;
                }), panel.second.end());
        }
    }
    if (changed && !wasPresent) {
        NotifyMainRTaskAvailable();
    }
    return changed;
}

static void DispatchCommand(PlotModel *model, const std::string &command)
{
    if (HandleRecordingCommand(command)) {
        return;
    }
    CommandRequest request = ParseMenuCommand(command);
    RecordDispatchCommand(model, command);
    if (model && (request.action == CommandAction::HistogramSetBins ||
        request.action == CommandAction::SetTrellisHistogramBins) && request.args.empty()) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Number of bins"];
        [alert setInformativeText:@"Enter a whole number from 1 to 200."];
        [alert addButtonWithTitle:@"Apply"]; [alert addButtonWithTitle:@"Cancel"];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 180, 24)];
        [field setIntegerValue:model->kind == "histogram" ? model->histogramBins.size() : model->trellisSpecification.histogramBinCount];
        [alert setAccessoryView:field];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
        const std::string value = [[[field stringValue] stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]] UTF8String];
        if (!rlispstat::core::HistogramBinCountForChoice(*model, value)) {
            ShowWorkbenchMessageOnMain(@"Number of bins", @"Enter a whole number from 1 to 200.");
            return;
        }
        request.args.push_back(value);
    }

    auto rebuildBarplotAndRefresh = [&](NSString *title) {
        std::string message;
        if (!RebuildBarplotFromModelVariables(model, &message)) {
            ShowWorkbenchMessageOnMain(title, ToNSString(message));
            return;
        }
        UpdateWindowTitleOnMain(model);
        RedrawPlotOnMain(model->id);
        NotifyBarplotLinkedTablesChanged(model->id);
        UpdatePanelOnMain();
    };
    auto barplotPayload = [&]() {
        std::ostringstream payload;
        for (size_t i = 0; i < request.args.size(); ++i) {
            if (i > 0) payload << "|";
            payload << request.args[i];
        }
        return payload.str();
    };
    switch (request.action) {
    case CommandAction::MissingInformationAddVariable:
    case CommandAction::ShowMissingInformation:
    case CommandAction::ShowRCode:
    case CommandAction::ShowRPublicationCode: {
        // Export-menu commands are delivered through the same native target
        // as plot commands, including when the owning result is a table or a
        // model window and there is no active plot.  Forward them to the
        // central dispatcher so it can resolve the immutable output-code
        // reference and open the R-code viewer.  Previously these actions
        // fell through to the plot-only tail below and were silently ignored.
        std::vector<std::string> lines;
        lines.reserve(1 + request.args.size());
        lines.push_back(request.name);
        lines.insert(lines.end(), request.args.begin(), request.args.end());
        const std::string reply = MacCommandDispatcher().dispatch(lines);
        if (reply.rfind("ERR ", 0) == 0) {
            ShowWorkbenchMessageOnMain(
                request.action == CommandAction::ShowRPublicationCode
                    ? @"R Publication Code" : (request.action == CommandAction::MissingInformationAddVariable ? @"Add variable" : request.action == CommandAction::ShowMissingInformation
                        ? @"Missing-information diagnostics" : @"R Code"),
                ToNSString(reply.substr(4)));
        }
        return;
    }
    case CommandAction::PlotTheme: {
        if (request.args.empty()) break;
        MacCommandDispatcher().dispatch({"PLOT_THEME", request.args[0]});
        return;
    }
    case CommandAction::ExcludeSelectedCases:
    case CommandAction::IncludeSelectedCases:
    case CommandAction::IncludeAllCases:
    case CommandAction::ToggleCaseIncluded: {
        std::vector<std::string> command{request.name};
        command.insert(command.end(), request.args.begin(), request.args.end());
        const std::string reply = MacCommandDispatcher().dispatch(command);
        if (reply.rfind("ERR ", 0) == 0)
            ShowWorkbenchMessageOnMain(@"Cases", ToNSString(reply.substr(4)));
        return;
    }
    case CommandAction::GetAnalysisScope:
    case CommandAction::SetAnalysisScopeAll:
    case CommandAction::SetAnalysisScopeFromSelection:
    case CommandAction::SetAnalysisScopeFromRows: {
        std::string group;
        if (!request.args.empty()) group = request.args[0];
        if (group.empty()) {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
        }
        if (group.empty()) {
            ShowWorkbenchMessageOnMain(@"Analysis scope", @"Import or activate a dataset first.");
            return;
        }
        if (request.action == CommandAction::SetAnalysisScopeFromSelection && request.name != "SET_ANALYSIS_SCOPE_UNSELECTED") {
            std::size_t selectedCount = 0;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto selected = g_groupSelections.find(group);
                if (selected != g_groupSelections.end()) selectedCount = selected->second.size();
            }
            if (selectedCount == 0) {
                ShowWorkbenchMessageOnMain(@"Analysis scope",
                    @"Select one or more observations first.");
                return;
            }
        }
        std::string error;
        bool ok = true;
        rlispstat::core::AnalysisScopeChangeEvent changeEvent;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto &state = MacCommandDispatcher().applicationState();
            if (request.action == CommandAction::SetAnalysisScopeAll) {
                ok = state.resetActiveAnalysisScopeToAllObservations(group, &changeEvent, &error);
            } else if (request.name == "SET_ANALYSIS_SCOPE_UNSELECTED") {
                ok = state.setActiveAnalysisScopeFromUnselected(group, &changeEvent, &error);
            } else if (request.action == CommandAction::SetAnalysisScopeFromSelection) {
                const std::string description = request.args.size() > 1 && !request.args[1].empty()
                    ? request.args[1] : "Current selection";
                const std::optional<std::string> sourceView =
                    request.args.size() > 2 && !request.args[2].empty()
                    ? std::optional<std::string>(request.args[2]) : std::nullopt;
                ok = state.setActiveAnalysisScopeFromSelection(
                    group, rlispstat::core::AnalysisScopeSourceKind::CurrentSelection,
                    description, sourceView, &changeEvent, &error);
            } else if (request.action == CommandAction::SetAnalysisScopeFromRows) {
                if (request.args.size() < 4) {
                    ok = false;
                    error = "The requested row subset is incomplete.";
                } else {
                    char *end = nullptr;
                    const long count = std::strtol(request.args[1].c_str(), &end, 10);
                    if (!end || *end != '\0' || count < 0 ||
                        request.args.size() < static_cast<std::size_t>(4 + count)) {
                        ok = false;
                        error = "The requested row subset is invalid.";
                    } else {
                        std::vector<int> rows;
                        rows.reserve(static_cast<std::size_t>(count));
                        for (long index = 0; index < count; ++index) {
                            rows.push_back(std::atoi(request.args[static_cast<std::size_t>(2 + index)].c_str()));
                        }
                        const std::size_t metadata = static_cast<std::size_t>(2 + count);
                        const DataFrameModel *dataset = FindDataFrameUnlockedConst(group);
                        if (!dataset) {
                            ok = false;
                            error = "The analysis-scope dataset is no longer available.";
                        } else {
                            rlispstat::core::AnalysisScope scope = rlispstat::core::ExplicitAnalysisScope(
                                group, rows,
                                rlispstat::core::AnalysisScopeSourceKindFromId(request.args[metadata]),
                                request.args[metadata + 1],
                                static_cast<std::size_t>(std::max(0, dataset->rows)),
                                request.args.size() > metadata + 2 && !request.args[metadata + 2].empty()
                                    ? std::optional<std::string>(request.args[metadata + 2]) : std::nullopt,
                                request.args.size() > metadata + 3 && !request.args[metadata + 3].empty()
                                    ? std::optional<std::string>(request.args[metadata + 3]) : std::nullopt);
                            ok = state.setActiveAnalysisScope(scope, &changeEvent, &error);
                        }
                    }
                }
            }
        }
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Analysis scope", ToNSString(error));
            return;
        }
        // Every live window follows the one dataset-wide analytical scope.
        // Only an explicitly frozen view may retain an older row set.
        PublishSpreadPlotMessage(
            "ANALYSIS_SCOPE_CHANGED", group,
            changeEvent.currentScope.sourceViewId.value_or("analysis-scope"),
            changeEvent.currentScope.sourceDescription, {},
            static_cast<int>(changeEvent.version));
        RefreshDataDeskWindowsOnMain(group);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::SaveAnalysisScopeFromSelection: {
        if (request.args.empty()) return;
        const std::string group = request.args[0];
        std::size_t selectedCount = 0;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto selected = g_groupSelections.find(group);
            if (selected != g_groupSelections.end()) selectedCount = selected->second.size();
        }
        if (selectedCount == 0) {
            ShowWorkbenchMessageOnMain(@"Save Analysis Scope",
                @"Select one or more observations first.");
            return;
        }
        std::optional<std::string> name;
        if (request.args.size() > 1 && !request.args[1].empty()) {
            name = rlispstat::core::NormalizeAnalysisScopeSelectionName(request.args[1]);
        } else {
            name = PromptForSavedAnalysisScopeName(selectedCount);
        }
        if (!name.has_value()) return;
        std::string error;
        bool ok = false;
        rlispstat::core::AnalysisScopeChangeEvent changeEvent;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            ok = MacCommandDispatcher().applicationState().saveCurrentSelectionAsAnalysisScope(
                group, *name, rlispstat::core::AnalysisScopeSourceKind::CurrentSelection,
                request.args.size() > 2 && !request.args[2].empty()
                    ? std::optional<std::string>(request.args[2]) : std::nullopt,
                &changeEvent, &error);
        }
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Save Analysis Scope", ToNSString(error));
            return;
        }
        PublishSpreadPlotMessage(
            "ANALYSIS_SCOPE_CHANGED", group,
            changeEvent.currentScope.sourceViewId.value_or("analysis-scope"),
            changeEvent.currentScope.sourceDescription, {},
            static_cast<int>(changeEvent.version));
        UpdateAnalysisScopeStatusOnMain();
        RefreshDataDeskWindowsOnMain(group);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::UseSavedAnalysisScope:
    case CommandAction::AddSavedAnalysisScope: {
        if (request.args.size() < 2) return;
        const std::string group = request.args[0];
        const std::string savedName = request.args[1];
        std::optional<std::string> combinedName;
        if (request.action == CommandAction::AddSavedAnalysisScope) {
            std::size_t combinedCount = 0;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                auto &state = MacCommandDispatcher().applicationState();
                const auto saved = state.savedSelection(group, savedName);
                const auto active = state.activeAnalysisScope(group);
                if (saved.has_value() &&
                    active.kind == rlispstat::core::AnalysisScopeKind::ExplicitRowIds) {
                    std::set<int> rows(active.originalRowIds.begin(), active.originalRowIds.end());
                    rows.insert(saved->originalRowIds.begin(), saved->originalRowIds.end());
                    combinedCount = rows.size();
                }
            }
            if (combinedCount == 0) {
                ShowWorkbenchMessageOnMain(@"Analysis scope",
                    @"Choose a selected or saved scope before adding another selection.");
                return;
            }
            const std::optional<std::string> name =
                PromptForSavedAnalysisScopeName(combinedCount);
            if (!name.has_value()) return;
            combinedName = *name;
        }
        std::string error;
        rlispstat::core::AnalysisScopeChangeEvent changeEvent;
        bool ok = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto &state = MacCommandDispatcher().applicationState();
            ok = request.action == CommandAction::UseSavedAnalysisScope
                ? state.activateSavedSelection(group, savedName, &changeEvent, &error)
                : state.addSavedSelectionToActiveScope(
                    group, savedName, *combinedName, &changeEvent, &error);
        }
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Analysis scope", ToNSString(error));
            return;
        }
        PublishSpreadPlotMessage(
            "ANALYSIS_SCOPE_CHANGED", group,
            changeEvent.currentScope.sourceViewId.value_or("analysis-scope"),
            changeEvent.currentScope.sourceDescription, {},
            static_cast<int>(changeEvent.version));
        RefreshDataDeskWindowsOnMain(group);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::MakeSubsetFromVariables:
        if (!request.args.empty()) MakeVariableSubsetOnMain(request.args[0]);
        return;
    case CommandAction::MakeSubsetFromSelection:
    case CommandAction::MakeSubsetFromSavedSelection: {
        if (request.args.empty()) return;
        const std::string group = request.args[0];
        std::vector<int> rows;
        std::string sourceName = "current selection";
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto &state = MacCommandDispatcher().applicationState();
            if (request.action == CommandAction::MakeSubsetFromSelection) {
                std::set<int> selected;
                if (state.selectedRows(group, selected)) {
                    rows.assign(selected.begin(), selected.end());
                }
            } else if (request.args.size() >= 2) {
                const auto saved = state.savedSelection(group, request.args[1]);
                if (saved.has_value()) {
                    rows = saved->originalRowIds;
                    sourceName = saved->name;
                }
            }
        }
        MakeSubsetOnMain(group, rows, sourceName);
        return;
    }
    case CommandAction::TogglePlotScopeFreeze: {
        if (!model || model->isDatasetSeed ||
            rlispstat::core::PlotIsDerivedAnalysisView(*model)) return;
        const std::string group = model->group;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            model->analysisScopeFrozen = !model->analysisScopeFrozen;
            if (model->analysisScopeFrozen) {
                const auto global = MacCommandDispatcher().applicationState()
                    .activeAnalysisScope(group);
                const std::size_t total = model->dataScope.totalDatasetRows;
                const auto rows = rlispstat::core::ResolveAnalysisScopeRowIds(
                    model->dataScope, total);
                model->dataScope = rlispstat::core::ExplicitAnalysisScope(
                    group, rows,
                    rlispstat::core::AnalysisScopeSourceKind::OtherExplicitSubset,
                    model->dataScope.sourceDescription,
                    total,
                    model->dataScope.sourceViewId,
                    model->dataScope.sourceElementId);
                model->dataScopeCaptured = true;
                model->frozenScopeNotice = model->dataScopeCaptured
                    ? rlispstat::core::FrozenAnalysisScopeNotice(model->dataScope, global)
                    : std::string{};
            }
        }
        if (!model->analysisScopeFrozen)
            RefreshOpenPlotsForGlobalScopeOnMain(group, false);
        else {
            UpdateWindowTitleOnMain(model);
            RedrawPlotOnMain(model->id);
        }
        return;
    }
    case CommandAction::OpenEquivalentWithActiveScope:
    case CommandAction::OpenEquivalentWithAllRows: {
        if (!model) return;
        rlispstat::core::AnalysisScope targetScope;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *dataset = FindDataFrameUnlockedConst(model->group);
            if (!dataset) {
                ShowWorkbenchMessageOnMain(@"Data scope", @"The source dataset is no longer available.");
                return;
            }
            targetScope = request.action == CommandAction::OpenEquivalentWithAllRows
                ? rlispstat::core::AllObservationsAnalysisScope(
                    model->group, static_cast<std::size_t>(std::max(0, dataset->rows)))
                : MacCommandDispatcher().applicationState().activeAnalysisScope(model->group);
        }
        std::string message;
        if (!OpenEquivalentPlotWithScopeOnMain(model, targetScope, &message)) {
            ShowWorkbenchMessageOnMain(@"Open equivalent", ToNSString(message));
        }
        return;
    }
    case CommandAction::FileImportData:
        ShowImportChooserOnMain();
        return;
    case CommandAction::FileExportData:
        ShowExportDataChooserOnMain();
        return;
    case CommandAction::FileOpenDataFromR:
        if (g_mainRNotifyPath.empty()) {
            ShowWorkbenchMessageOnMain(@"Open data from R",
                @"No connected R session is available.");
            return;
        }
        QueueDataBrowseMainRTask({
            std::string([[[NSUUID UUID] UUIDString] UTF8String])
        });
        return;
    case CommandAction::FileReturnDataToR:
    case CommandAction::FileReturnSelectedRowsToR:
    case CommandAction::FileCancelDataReturn: {
        std::string group;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
        }
        std::string message;
        const std::string mode = request.action == CommandAction::FileReturnSelectedRowsToR
            ? "selected"
            : (request.action == CommandAction::FileCancelDataReturn ? "cancel" : "all");
        bool editSession = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            editSession = !group.empty() &&
                g_rEditSessionsByGroup.find(group) != g_rEditSessionsByGroup.end();
        }
        if (!group.empty() && !editSession && mode != "cancel") {
            ShowRDataAssignmentDialogOnMain(group, mode);
            return;
        }
        const bool ok = !group.empty() && editSession &&
            QueueRDataReturnForGroup(group, mode, &message);
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Return data to R",
                ToNSString(message.empty() ? "No R data-return session is active." : message));
        }
        return;
    }
    case CommandAction::OpenDataSheet: {
        if (!request.args.empty()) {
            ShowDataSheetOnMain(request.args[0]);
        } else if (model) {
            PlotModel *target = ActiveDatasetCommandModel(model);
            ShowDataSheetOnMain(target ? target->group : model->group);
        } else {
            std::string group;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                group = ActiveDatasetGroupUnlocked();
            }
            if (!group.empty()) {
                ShowDataSheetOnMain(group);
            } else {
                ShowWorkbenchMessageOnMain(ToNSString(DataSheetOpenTitle()), ToNSString(ImportOrRegisterDatasetStatus()));
            }
        }
        return;
    }
    case CommandAction::DataSetActiveDataset: {
        if (request.args.empty()) {
            ShowActiveDatasetOnMain();
            return;
        }
        std::string group = request.args[0];
        bool ok = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            ok = DatasetExistsUnlocked(group);
            if (ok) {
                SetActiveDatasetUnlocked(group);
            }
        }
        if (ok) {
            UpdateActiveDatasetMenuOnMain();
            ShowDataSheetOnMain(group);
            UpdatePanelOnMain();
        } else {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::ActiveDatasetWindowTitle()), ToNSString(DatasetNotRegisteredStatus(group)));
        }
        return;
    }
    case CommandAction::ShowActiveDataset:
        ShowActiveDatasetOnMain();
        return;
    case CommandAction::ChooseLabelColumn: {
        PlotModel *target = ActiveDatasetCommandModel(model);
        std::string group;
        if (target) {
            group = target->group;
        } else {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
        }
        ShowChooseLabelColumnDialogOnMain(group);
        return;
    }
    case CommandAction::VariableView: {
        std::string group;
        if (!request.args.empty()) {
            group = request.args[0];
        } else {
            PlotModel *target = ActiveDatasetCommandModel(model);
            if (target) {
                group = target->group;
            } else {
                std::lock_guard<std::mutex> lock(g_mutex);
                group = ActiveDatasetGroupUnlocked();
            }
        }
        if (group.empty()) {
            ShowWorkbenchMessageOnMain(ToNSString(VariableViewTitle()), ToNSString(ImportOrRegisterDatasetStatus()));
        } else {
            ShowVariablesWindowOnMain(group);
        }
        return;
    }
    case CommandAction::DataMissingDataPatterns: {
        PlotModel *target = ActiveDatasetCommandModel(model);
        std::string group;
        if (target) {
            group = target->group;
        } else {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
        }
        ShowMissingDataPatternsDialogOnMain(group, request.name=="DATA_MISSINGNESS_MODELS");
        return;
    }
    case CommandAction::AddSelectionColumn:
    case CommandAction::AddPointColorColumn: {
        std::string message;
        bool selectionColumn = request.action == CommandAction::AddSelectionColumn;
        if (!request.args.empty()) {
            AddDerivedDataColumnForGroup(request.args[0], "data_sheet", selectionColumn ? "selection" : "color", &message);
        } else {
            PlotModel *target = ActiveDatasetCommandModel(model);
            AddDerivedDataColumnFromPlot(target ? target : model, selectionColumn ? "selection" : "color", &message);
        }
        const rlispstat::core::PlotContextMenuTitles titles = rlispstat::core::DefaultPlotContextMenuTitles();
        ShowWorkbenchMessageOnMain(ToNSString(titles.addDataColumn), ToNSString(message));
        return;
    }
    case CommandAction::SetVariableTypeNumeric:
    case CommandAction::SetVariableTypeFactor:
    case CommandAction::ShowVariableInformation: {
        PlotModel *target = ActiveDatasetCommandModel(model);
        if (!target || target->xLabel.empty()) {
            ShowWorkbenchMessageOnMain(ToNSString(VariableTypeTitle()), ToNSString(NoActiveVariableForTypeStatus()));
            return;
        }
        if (request.action == CommandAction::ShowVariableInformation) {
            ShowWorkbenchMessageOnMain(ToNSString(VariableInformationDialogTitle()), ToNSString(VariableInformationText(target->group, target->xLabel)));
            return;
        }
        std::string message;
        std::string type = request.action == CommandAction::SetVariableTypeNumeric ? "numeric" : "factor";
        if (!SetVariableAnalysisType(target->group, target->xLabel, type, &message)) {
            ShowWorkbenchMessageOnMain(ToNSString(VariableTypeTitle()), ToNSString(message));
        }
        return;
    }
    case CommandAction::RefreshRDataFrames:
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RefreshRDataFramesWindowTitle()), ToNSString(rlispstat::core::NativeBackendCannotInspectRStatus()));
        return;
