        ShowPanelOnMain(true);
        return;
    case CommandAction::PanelHide:
        ShowPanelOnMain(false);
        return;
    case CommandAction::ResetWindowLayout:
        ResetWindowLayoutOnMain();
        return;
    case CommandAction::OpenColorPalette:
        if (model) {
            std::lock_guard<std::mutex> lock(g_mutex);
            MarkActiveDatasetGroupUnlocked(
            MacCommandDispatcher().applicationState().dataSheetGroupForPlotGroup(model->group));
        }
        ShowPaletteOnMain(true);
        return;
    case CommandAction::PaletteHide:
        ShowPaletteOnMain(false);
        return;
    case CommandAction::NewScatterplot:
        ShowNewLinkedScatterplotDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::NewTrellisScatterplot:
        ShowNewTrellisScatterplotDialogOnMain(
            ActiveDatasetCommandModel(model),
            request.args.empty() ? "scatter" : request.args[0]);
        return;
    case CommandAction::NewTimeSeries:
        ShowNewTimeSeriesDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::NewScatterMatrix:
        ShowNewLinkedScatterMatrixDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::NewParallelCoordinates:
        ShowNewParallelCoordinatesDialogOnMain(ActiveDatasetCommandModel(model));
        return;
    case CommandAction::ScatterMatrixAddVariable: {
        if (!model || model->kind != "scatter_matrix" || request.args.empty()) return;
        std::string variable = request.args[0];
        std::vector<std::string> updated = rlispstat::core::ScatterMatrixVariablesAfterAdd(
            model->scatterMatrixVariables, variable, rlispstat::core::NumericVariableNames(model));
        if (updated != model->scatterMatrixVariables) {
            model->scatterMatrixVariables = updated;
            RebuildScatterMatrixPoints(model);
            ComputeRanges(model);
            rlispstat::core::RefreshBasicPlotCodeReference(
                MacCommandDispatcher().applicationState(), *model);
            if (model->scatterMatrixFitsPending) NotifyMainRTaskAvailable();
            UpdateWindowTitleOnMain(model);
            RedrawPlotOnMain(model->id);
            UpdatePanelOnMain();
        }
        return;
    }
    case CommandAction::ScatterMatrixRemoveVariable: {
        if (!model || model->kind != "scatter_matrix" || request.args.empty()) return;
        std::string variable = request.args[0];
        NormalizeScatterMatrixVariables(model);
        std::vector<std::string> updated = rlispstat::core::ScatterMatrixVariablesAfterRemove(
            model->scatterMatrixVariables, variable);
        if (updated == model->scatterMatrixVariables) return;
        model->scatterMatrixVariables = updated;
        RebuildScatterMatrixPoints(model);
        ComputeRanges(model);
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        if (model->scatterMatrixFitsPending) NotifyMainRTaskAvailable();
        UpdateWindowTitleOnMain(model);
        RedrawPlotOnMain(model->id);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::ScatterMatrixReplaceVariable: {
        if (!model || model->kind != "scatter_matrix" || request.args.size() < 2) return;
        char *end = nullptr;
        long parsedIndex = std::strtol(request.args[0].c_str(), &end, 10);
        if (!end || *end != '\0' || parsedIndex < 0) return;
        std::vector<std::string> current = ScatterMatrixVariablesForModel(model);
        std::vector<std::string> updated =
            rlispstat::core::ScatterMatrixVariablesAfterReplacement(
                current,
                static_cast<std::size_t>(parsedIndex),
                request.args[1],
                rlispstat::core::NumericVariableNames(model));
        if (updated == current) return;
        model->scatterMatrixVariables = updated;
        RebuildScatterMatrixPoints(model);
        ComputeRanges(model);
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        if (model->scatterMatrixFitsPending) NotifyMainRTaskAvailable();
        UpdateWindowTitleOnMain(model);
        RedrawPlotOnMain(model->id);
        UpdatePanelOnMain();
        return;
    }
