        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            BarplotCoreSegmentReferenceForIndices(model, barIndex, segmentIndex);
        if (!reference.has_value()) return;
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
