        if (!model || model->kind != "barplot" || request.args.empty()) return;
        std::string level = DecodeCommandField(request.args[0]);
        rlispstat::core::BarplotVisualState state = BarplotVisualStateForModel(model);
        if (!rlispstat::core::ResetBarplotLevelColorOverride(state, level)) return;
        ApplyNormalizedBarplotVisualState(model, state);
