    case CommandAction::BarplotSegmentDetails: {
        if (!model || model->kind != "barplot") return;
        int barIndex = -1;
        int segmentIndex = -1;
        if (!ParseBarplotSegmentCommandPayload(barplotPayload(), &barIndex, &segmentIndex)) return;
        std::vector<rlispstat::core::BarplotBinSummary> bins = rlispstat::core::BarplotBinsForModel(model);
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            (barIndex >= 0 && segmentIndex >= 0)
                ? rlispstat::core::BarplotSegmentReferenceForIndices(
                    bins,
                    (std::size_t)barIndex,
                    (std::size_t)segmentIndex)
                : std::nullopt;
        if (!reference.has_value()) return;
        std::set<int> selection;
        std::map<int, std::string> rowColors;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto sit = g_groupSelections.find(model->group);
            if (sit != g_groupSelections.end()) selection = sit->second;
            rowColors = DisplayPointColorMap(model->group);
        }
        std::vector<std::string> splitLevels = BarplotSplitLevels(model);
        size_t levelIndex = rlispstat::core::BarplotLevelIndex(splitLevels, reference->segment.level);
        std::optional<BarplotSegmentVisualStyle> style = ResolveBarplotSegmentVisual(
            model,
            reference->category,
            reference->segment.level,
            levelIndex);
        std::string details = rlispstat::core::BarplotSegmentTooltipText(
            model->xLabel,
            model->barplotSplitVariable,
            model->barplotWidthMode,
            bins[reference->barIndex],
            model->barplotTotalN,
            reference->segment,
            style,
            rowColors,
            selection,
            BarplotPaletteOrder(),
            model->barplotRowColorDisplay != "hide");
        ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::BoxplotSegmentDetailsWindowTitle()), ToNSString(details));
        return;
    }
    case CommandAction::ContextCorrelationXY:
        if (model) {
            ShowCorrelationMatrixForVariablesOnMain(model, {model->xLabel, model->yLabel},
                                                    "Correlation: " + model->yLabel + " with " + model->xLabel);
        }
        return;
    case CommandAction::ContextDescriptivesXY:
        if (model) {
            ShowTable1ForVariablesOnMain(model, {model->xLabel, model->yLabel}, "",
                                         "Descriptive statistics: " + model->xLabel + " and " + model->yLabel);
        }
        return;
    case CommandAction::ContextLinearModelXY:
        if (model) {
            std::string group = model->group;
            std::string x = model->xLabel;
            std::string y = model->yLabel;
            bool changed = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                PlotModel *seed = FirstPlotForGroupUnlocked(group);
                if (seed && FindVariable(seed, x) && FindVariable(seed, y) && x != y) {
                    GroupModelState &state = EnsureGroupModelUnlocked(group, seed);
                    state.response = y;
                    state.terms.clear();
                    state.terms.push_back(x);
                    rlispstat::core::MarkGroupModelChanged(state);
                    changed = true;
                }
            }
            if (changed) {
                PublishSpreadPlotMessage("GLM_SPEC_CHANGED", group, "glm:" + group, "glm:" + group);
                ShowGLMOnMain(model, true);
            } else {
                ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::GLMGeneralLinearModelTitle()), ToNSString(rlispstat::core::ScatterplotNoValidXYStatus()));
            }
        }
        return;
    case CommandAction::PlotAnalyzeModel:
    case CommandAction::PlotAnalyzeCorrelations:
    case CommandAction::PlotAnalyzeContingency:
    case CommandAction::PlotAnalyzeDescriptives: {
        if (!model) return;
        DataFrameModel dataframe;
        if (!DataFrameForContextModel(model, dataframe)) return;
        const rlispstat::core::PlotAnalysisContext context =
            rlispstat::core::BuildPlotAnalysisContext(*model, dataframe);
        if (request.action == CommandAction::PlotAnalyzeCorrelations) {
            if (context.offersCorrelations)
                ShowCorrelationMatrixForVariablesOnMain(
                    model, context.numericVariables, "Correlations from plot");
            return;
        }
        if (request.action == CommandAction::PlotAnalyzeContingency) {
            if (!context.offersContingencyTables) return;
            std::string row;
            if (!context.dependentVariable.empty() &&
                std::find(context.categoricalVariables.begin(),
                          context.categoricalVariables.end(),
                          context.dependentVariable) != context.categoricalVariables.end())
                row = context.dependentVariable;
            std::string column;
            if (context.categoricalVariables.size() == 2) {
                if (row.empty()) row = context.categoricalVariables.front();
                const auto found = std::find_if(context.categoricalVariables.begin(),
                    context.categoricalVariables.end(),
                    [&](const std::string &variable) { return variable != row; });
                if (found != context.categoricalVariables.end()) column = *found;
            }
            ShowContingencyTableDialogOnMain(model, row, column);
            return;
        }
        if (request.action == CommandAction::PlotAnalyzeDescriptives) {
            if (!context.offersDescriptives) return;
            std::vector<std::string> variables = context.numericVariables.empty()
                ? context.categoricalVariables : context.numericVariables;
            std::vector<std::string> eligibleGrouping;
            for (const std::string &candidate : context.groupingVariables) {
                if (candidate != context.dependentVariable &&
                    std::find(variables.begin(), variables.end(), candidate) == variables.end()) {
                    eligibleGrouping.push_back(candidate);
                }
            }
            const std::string grouping = eligibleGrouping.size() == 1
                ? eligibleGrouping.front() : std::string{};
            ShowTable1ForVariablesOnMain(
                model, variables, grouping, "Descriptive statistics from plot");
            return;
        }
        if (!context.offersModel) return;
        if (context.modelKind == rlispstat::core::PlotAnalysisModelKind::Linear) {
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                PlotModel *seed = FirstPlotForGroupUnlocked(model->group);
                GroupModelState &state = EnsureGroupModelUnlocked(model->group, seed ? seed : model);
                state.response = context.dependentVariable;
                state.terms = context.predictors;
                state.termTypeOverrides =
                    rlispstat::core::PlotAnalysisTermTypes(context);
                state.termTypes = state.termTypeOverrides;
                CaptureActiveAnalysisScopeUnlocked(
                    model->group, state.dataScope, state.dataScopeCaptured);
                state.scope = ScopeForCapturedAnalysisScope(
                    state.dataScope, state.dataScopeCaptured, state.scope);
                rlispstat::core::MarkGroupModelChanged(state);
            }
            PublishSpreadPlotMessage("GLM_SPEC_CHANGED", model->group,
                                     "glm:" + model->group, "glm:" + model->group);
            ShowGLMOnMain(model, true);
            return;
        }
        const DataColumn *responseColumn = FindDataColumnInDataFrame(
            dataframe, context.dependentVariable);
        if (!responseColumn) return;
        const auto coding = rlispstat::core::InspectBinaryResponse(*responseColumn);
        if (!coding.ok) return;
        GeneralizedGLMState state;
        state.id = "binary_plot_" + model->group + "_" +
            std::to_string((long long)time(nullptr));
        state.group = model->group;
        state.seed = *model;
        state.hasSeed = true;
        state.response = context.dependentVariable;
        state.responseCoding = coding;
        state.responseCodingExplicit = true;
        state.terms = context.predictors;
        state.termTypes = rlispstat::core::PlotAnalysisTermTypes(context);
        state.title = "Binary Model";
        state.modelType = rlispstat::core::StatisticalModelType::Binary;
        state.binaryRegression = true;
        state.family = "binomial";
        state.binaryLink = rlispstat::core::BinaryLink::Logit;
        state.link = rlispstat::core::BinaryLinkId(state.binaryLink);
        state.modelVersion = 1;
        state.status = "Fitting Binary Model in the main R session...";
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            CaptureActiveAnalysisScopeUnlocked(
                state.group, state.dataScope, state.dataScopeCaptured);
            state.scope = ScopeForCapturedAnalysisScope(
                state.dataScope, state.dataScopeCaptured, state.scope);
            g_generalizedGLMs[state.id] = state;
        }
        ShowGeneralizedGLMOnMain(state.id);
        auto it = g_generalizedGLMs.find(state.id);
        if (it != g_generalizedGLMs.end()) RequestGeneralizedGLMFitInMainR(it->second);
        return;
    }
    case CommandAction::ContextHistogramFrequency:
