    case CommandAction::OpenRegressionComparison: {
        model = ActiveDatasetCommandModel(model);
        if (!model) return;
        const bool multipleImputation = GroupIsMultipleImputation(model->group);
        DataFrameModel df;
        if (!DataFrameSnapshotForGroup(model->group, df)) {
            ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RegressionModelComparisonTitle()), ToNSString(ActiveDatasetUnavailableStatus()));
            return;
        }
        const auto initial = rlispstat::core::ResolveInitialAnalysisSpecification(
            df,
            rlispstat::core::SharedAnalysisDefinition(
                rlispstat::core::SharedAnalysisKind::RegressionComparison),
            FreshRegressionVariableRolesSnapshot(model->group));
        RegressionComparisonState state;
        state.id = "regcmp_" + model->group + "_" + std::to_string((long long)time(nullptr));
        state.group = model->group;
        state.response = rlispstat::core::InitialAnalysisVariable(initial, "response");
        state.scope = "all";
        state.autoRefit = true;
        state.multipleImputation = multipleImputation;
        state.precomputed = multipleImputation;
        state.imputationCount = multipleImputation ? std::max(1, df.imputationCount) : 0;
        state.seed = *model;
        state.hasSeed = true;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            CaptureActiveAnalysisScopeUnlocked(state.group, state.dataScope, state.dataScopeCaptured);
        }
        state.scope = ScopeForCapturedAnalysisScope(state.dataScope, state.dataScopeCaptured, state.scope);
        state.termRows.push_back("(Intercept)");
        RegressionComparisonModel column;
        column.id = state.id + ":model:1";
        column.label = "Model 1";
        column.response = state.response;
        for (const std::string &term :
             rlispstat::core::InitialAnalysisVariables(initial, "predictors")) {
            if (term == state.response || !ModelTermExistsForModel(model, term, state.response)) continue;
            column.terms.push_back(term);
            rlispstat::core::AddRegressionTermRow(state, term);
        }
        column.candidateTerms = column.terms;
        state.models.push_back(column);
        if (!multipleImputation) {
            RefitRegressionComparisonModels(state, true);
        }
        g_regressionComparisons[state.id] = state;
        ShowRegressionComparisonOnMain(state.id);
        if (multipleImputation && !state.response.empty() && !column.terms.empty()) {
            if (!g_mainRNotifyPath.empty()) {
                RequestRegressionComparisonFitInMainR(g_regressionComparisons[state.id]);
                return;
            }
            const std::string comparisonId = state.id;
            const std::string response = state.response;
            const std::string scope = state.scope;
            const std::string modelSpec = rlispstat::core::EncodePooledRegressionComparisonModelSpec(state);
            std::thread worker([df, comparisonId, response, scope, modelSpec]() {
                std::string message;
                bool ok = RunRBackedMultipleImputationAnalysis(
                    df, "regcmp", comparisonId,
                    std::vector<std::string>(), "", response, std::vector<std::string>(), scope, &message, modelSpec);
                if (!ok) ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::RegressionModelComparisonTitle()), ToNSString(message));
            });
            worker.detach();
        }
        return;
    }
    case CommandAction::SetSelectedColor: {
        std::string color = request.args.empty() ? "" : request.args[0];
        if (color.empty()) return;
        PlotModel *target = ActiveDatasetCommandModel(model);
        if (target) {
            ApplyColorToGroupSelection(target->group, color);
        } else if (model) {
            ApplyColorToGroupSelection(model, color);
        } else {
            std::string group;
