        NSPopUpButton *altPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(96, 40, 140, 28)];
        [altPopup addItemWithTitle:ToNSString(rlispstat::core::BoxplotTwoSidedOptionLabel())];
