        NSTextField *drawsField = [[NSTextField alloc] initWithFrame:NSMakeRect(96, 10, 100, 24)];
        [drawsField setStringValue:[NSString stringWithFormat:@"%d", model->boxplotH0Draws]];
        [accessory addSubview:drawsField];
        [alert setAccessoryView:accessory];
        if ([alert runModal] == NSAlertFirstButtonReturn) {
            double h0 = std::strtod([[h0Field stringValue] UTF8String], nullptr);
            int draws = std::atoi([[drawsField stringValue] UTF8String]);
            if (!std::isfinite(h0)) h0 = 0.0;
            model->boxplotH0 = h0;
            model->boxplotH0Alternative = [[altPopup titleOfSelectedItem] UTF8String];
            model->boxplotH0Draws = std::max(100, std::min(200000, draws));
            std::string message;
            if (!RebuildBoxplotH0Simulation(model, &message)) {
                ClearBoxplotH0Simulation(model);
                ShowWorkbenchMessageOnMain(ToNSString(rlispstat::core::BoxplotH0SimulationWindowTitle()), ToNSString(message));
                return;
            }
        }
        break;
    }
