        HistogramDensityParameterDialogState dialogState =
            BuildHistogramDensityBandwidthDialogState(model->histogramDensityBw);
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:ToNSString(dialogState.title)];
        [alert setInformativeText:ToNSString(dialogState.informativeText)];
        [alert addButtonWithTitle:ToNSString(dialogState.setButtonTitle)];
        [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 180, 24)];
        [field setStringValue:ToNSString(dialogState.currentValueText)];
        [alert setAccessoryView:field];
        if ([alert runModal] == NSAlertFirstButtonReturn) {
            std::string text = [[field stringValue] UTF8String];
            std::optional<double> bandwidth =
                rlispstat::core::ParseHistogramDensityBandwidthCommandValue(text);
            if (!bandwidth.has_value()) return;
            model->histogramDensityBw = *bandwidth;
            model->histogramShowDensity = true;
        }
        break;
    }
    case CommandAction::HistogramSetDensityAdjust: {
        if (!model) return;
        HistogramDensityParameterDialogState dialogState =
            BuildHistogramDensityAdjustDialogState(model->histogramDensityAdjust);
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:ToNSString(dialogState.title)];
        [alert setInformativeText:ToNSString(dialogState.informativeText)];
        [alert addButtonWithTitle:ToNSString(dialogState.setButtonTitle)];
        [alert addButtonWithTitle:ToNSString(dialogState.cancelButtonTitle)];
        NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 180, 24)];
        [field setStringValue:ToNSString(dialogState.currentValueText)];
        [alert setAccessoryView:field];
        if ([alert runModal] == NSAlertFirstButtonReturn) {
            std::optional<double> adjust =
                rlispstat::core::ParseHistogramDensityAdjustCommandValue([[field stringValue] UTF8String]);
            if (!adjust.has_value()) return;
            model->histogramDensityAdjust = *adjust;
            model->histogramShowDensity = true;
        }
        break;
    }
    case CommandAction::BiplotSetX:
    case CommandAction::BiplotSetY: {
        if (!model || model->kind != "pca_biplot" || request.args.empty()) return;
        int component = std::max(1, std::atoi(request.args[0].c_str()));
        if (request.action == CommandAction::BiplotSetX) {
            model->biplotXComponent = component;
        } else {
            model->biplotYComponent = component;
        }
        if (RefreshDimensionalityBiplotPlot(model)) {
            UpdateWindowTitleOnMain(model);
            RedrawPlotOnMain(model->id);
            UpdatePanelOnMain();
        }
        return;
    }
    case CommandAction::SetImputationUncertainty: {
        if (!model || request.args.empty()) return;
        std::string mode = request.args[0];
        if (ScatterImputationUncertaintyModeIsValid(mode)) {
            model->scatterImputationUncertainty = mode;
            if (model->isGLMDiagnostic &&
                !model->diagnosticImputationValues.empty()) {
                std::vector<rlispstat::core::ScatterplotPointValue> points;
                points.reserve(model->points.size());
                for (const DataPoint &point : model->points)
                    points.push_back({point.row, point.x, point.y});
                const auto viewport =
                    rlispstat::core::ScatterplotViewportIncludingPointImputations(
                        points, model->diagnosticImputationValues, mode);
                if (viewport.has_value()) {
                    model->xmin = viewport->xmin; model->xmax = viewport->xmax;
                    model->ymin = viewport->ymin; model->ymax = viewport->ymax;
                }
                break;
            }
            DataFrameModel df;
            bool hasDataFrame = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
                if (current) {
                    df = *current;
                    hasDataFrame = true;
                }
            }
            if (hasDataFrame) {
                ComputeScatterRangesIncludingAllImputations(model, df);
            }
        }
        break;
    }
    case CommandAction::SetImputationDisplay: {
        if (!model || request.args.empty()) return;
        const std::string group = model->group;
        const std::string value = request.args[0];
        std::vector<std::string> plotsToRedraw;
        bool requestSmooth = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            DataFrameModel *found = FindDataFrameUnlocked(group);
            if (!found || found->datasetType != "multiple_imputation" ||
                found->imputationCount <= 0) return;
            if (value == "all" || value == "original") {
                found->imputationDisplayMode = value;
            } else if (value.rfind("version:", 0) == 0) {
                const int version = std::atoi(value.substr(8).c_str());
                if (version < 1 || version > found->imputationCount) return;
                found->activeImputationVersion = version;
                found->imputationDisplayMode = "version";
            } else {
                return;
            }
            ApplyImputationDisplayModeToStoredValues(*found);
            plotsToRedraw = RebuildPlotsForDataFrameUnlocked(group, *found);
            for (const std::string &plotId : plotsToRedraw) {
                auto plot = g_plots.find(plotId);
                if (plot != g_plots.end())
                    requestSmooth = RequestSmoothRecomputeForPlotUnlocked(plot->second) || requestSmooth;
            }
        }
        if (requestSmooth) NotifyMainRTaskAvailable();
        for (const std::string &plotId : plotsToRedraw) RedrawPlotOnMain(plotId);
        RedrawGroupViewsSynchronouslyOnMain(group, true);
        RefreshDendrogramWindowsOnMain(group);
        RefreshDataDeskWindowsOnMain(group);
        RefreshRegressionComparisonWindowsOnMain(group, false);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::ChangeXVariable:
    case CommandAction::ChangeYVariable: {
        if (!model || request.args.empty()) return;
        bool changeX = request.action == CommandAction::ChangeXVariable;
        if (model->kind == "glm_interaction") {
            ShowWorkbenchMessageOnMain(@"Effect Plot", changeX
                ? @"The horizontal axis can only be exchanged with another variable in the displayed interaction."
                : @"The response axis of an effect plot is fixed by its fitted model.");
            return;
        }
        std::string varName = request.args[0];
        if (model->kind == "trellis_scatterplot" &&
            ((changeX && varName == model->yLabel) || (!changeX && varName == model->xLabel))) {
            ShowWorkbenchMessageOnMain(@"Trellis Scatterplot", @"X and Y must be different variables.");
            return;
        }
        if (FindVariable(model, varName)) {
            if (model->kind == "trellis_scatterplot") {
                rlispstat::core::InitializeTrellisSpecificationFromLegacy(*model);
                DataFrameModel dataframe;
                bool found = false;
                {
                    std::lock_guard<std::mutex> lock(g_mutex);
                    const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
                    if (current) { dataframe = *current; found = true; }
                }
                PlotModel candidate = *model;
                if (changeX) candidate.trellisSpecification.xVariableId = varName;
                else candidate.trellisSpecification.yVariableId = varName;
                std::string error;
                if (!found || !rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error)) {
                    ShowWorkbenchMessageOnMain(@"Trellis Plot", ToNSString(error.empty() ? "Dataset unavailable." : error));
                    return;
                }
                *model = std::move(candidate);
                const bool smoothRequested =
                    rlispstat::core::InvalidateTrellisSmoothCurvesForDataChange(*model) &&
                    model->trellisSpecification.plotType == TrellisPlotType::Scatter;
                rlispstat::core::RefreshBasicPlotCodeReference(
                    MacCommandDispatcher().applicationState(), *model);
                UpdateWindowTitleOnMain(model);
                RedrawPlotOnMain(model->id);
                UpdatePanelOnMain();
                if (smoothRequested) NotifyMainRTaskAvailable();
                return;
            }
            const std::string oldX = model->xLabel;
            const std::string oldY = model->yLabel;
            const std::string previousHistogramDefaultTitle = model->kind == "histogram"
                ? HistogramDefaultTitle(oldX) : "";
            if (changeX) {
                model->xLabel = varName;
            } else {
                model->yLabel = varName;
            }
            DataFrameModel df;
            bool hasDataFrame = false;
            {
                std::lock_guard<std::mutex> lock(g_mutex);
                const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
                if (current) {
                    df = *current;
                    hasDataFrame = true;
                }
            }
            if (model->kind == "trellis_scatterplot" && hasDataFrame) {
                std::string error;
                if (!rlispstat::core::RebuildTrellisScatterplotFromDataFrame(*model, df, &error)) {
                    model->xLabel = oldX;
                    model->yLabel = oldY;
                    std::string ignored;
                    rlispstat::core::RebuildTrellisScatterplotFromDataFrame(*model, df, &ignored);
                    ShowWorkbenchMessageOnMain(@"Trellis Scatterplot", ToNSString(error));
                    return;
                }
            } else if (model->kind == "time_series" && hasDataFrame) {
                if (changeX) {
                    model->timeSeriesTimeType = "numeric";
                    const DataColumn *timeColumn = FindDataColumnInDataFrame(df, varName);
                    if (timeColumn) {
                        model->timeSeriesTimeType =
                            rlispstat::core::InferTimeSeriesTimeType(*timeColumn);
                    }
                }
                std::string ignored;
                rlispstat::core::RebuildTimeSeriesFromDataFrame(*model, df, &ignored);
            } else if (model->kind == "histogram") {
                RebuildHistogramPointsFromCurrentVariable(model);
                if (model->title.empty() || model->title == previousHistogramDefaultTitle)
                    model->title = HistogramDefaultTitle(model->xLabel);
            } else {
                RebuildPointsForCurrentVariables(model);
            }
            if (hasDataFrame && model->kind != "time_series" && model->kind != "trellis_scatterplot") {
                ComputeScatterRangesIncludingAllImputations(model, df);
            } else if (model->kind != "time_series" && model->kind != "trellis_scatterplot") {
                ComputeRanges(model);
            }
            if (RequestSmoothRecomputeForPlotUnlocked(model)) {
                NotifyMainRTaskAvailable();
            }
            rlispstat::core::RefreshBasicPlotCodeReference(
                MacCommandDispatcher().applicationState(), *model);
            UpdateWindowTitleOnMain(model);
            RedrawPlotOnMain(model->id);
            UpdatePanelOnMain();
        }
        return;
    }
    case CommandAction::SetTimeSeriesGroup: {
        if (!model || model->kind != "time_series" || request.args.empty()) return;
        model->timeSeriesGroupVariable = request.args[0] == "." ? "" : request.args[0];
        DataFrameModel dataframe;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
            if (current) { dataframe = *current; found = true; }
        }
        std::string error;
        if (!found || !rlispstat::core::RebuildTimeSeriesFromDataFrame(*model, dataframe, &error)) {
            ShowWorkbenchMessageOnMain(@"Time Series", ToNSString(error.empty() ? "Dataset unavailable." : error));
            return;
        }
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        UpdateWindowTitleOnMain(model);
        RedrawPlotOnMain(model->id);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::SetTimeSeriesIdentification: {
        if (!model || request.args.empty()) return;
        const bool trellisTimeSeries = model->kind == "trellis_scatterplot" &&
            model->trellisSpecificationInitialized &&
            model->trellisSpecification.plotType == TrellisPlotType::TimeSeries;
        if (model->kind != "time_series" && !trellisTimeSeries) return;
        const std::string mode = request.args[0];
        if (mode != "legend" && mode != "start_labels" && mode != "none") return;
        model->timeSeriesIdentification = mode;
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetTimeSeriesLegendPosition: {
        if (!model || request.args.empty()) return;
        const bool trellisTimeSeries = model->kind == "trellis_scatterplot" &&
            model->trellisSpecificationInitialized &&
            model->trellisSpecification.plotType == TrellisPlotType::TimeSeries;
        if (model->kind != "time_series" && !trellisTimeSeries) return;
        const std::string position = request.args[0];
        if (!rlispstat::core::SetTimeSeriesLegendPosition(*model, position)) return;
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetInteractionLegendPosition: {
        if (!model || request.args.empty() || model->kind != "glm_interaction") return;
        if (!rlispstat::core::SetInteractionLegendPosition(*model, request.args[0])) return;
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::ToggleRegressionConnectingLine: {
        if (!model || model->kind != "glm_interaction") return;
        model->regressionConnectEstimates = !model->regressionConnectEstimates;
        rlispstat::core::SynchronizeRegressionPlotCodeReferenceDisplay(*model);
        MacCommandDispatcher().applicationState().registerOutputCodeReference(
            model->codeReference);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::ToggleRegressionConfidenceIntervals: {
        if (!model) return;
        if (model->kind == "scatter" || model->kind == "trellis_scatterplot") {
            model->scatterFitConfidenceIntervalsVisible =
                !model->scatterFitConfidenceIntervalsVisible;
            rlispstat::core::RefreshBasicPlotCodeReference(
                MacCommandDispatcher().applicationState(), *model);
            MacCommandDispatcher().applicationState().registerOutputCodeReference(
                model->codeReference);
            RedrawPlotOnMain(model->id);
            return;
        }
        if (model->kind != "glm_interaction") return;
        model->regressionConfidenceIntervalsVisible =
            !model->regressionConfidenceIntervalsVisible;
        ComputeRanges(model);
        rlispstat::core::ApplyRegressionInteractionAxisRange(*model);
        rlispstat::core::SynchronizeRegressionPlotCodeReferenceDisplay(*model);
        MacCommandDispatcher().applicationState().registerOutputCodeReference(
            model->codeReference);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::ToggleSmoothConfidenceIntervals: {
        if (!model || (model->kind != "scatter" &&
                       model->kind != "trellis_scatterplot")) return;
        model->scatterSmoothConfidenceIntervalsVisible =
            !model->scatterSmoothConfidenceIntervalsVisible;
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        MacCommandDispatcher().applicationState().registerOutputCodeReference(
            model->codeReference);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::ToggleRegressionConfidenceLevel: {
        if (!model || model->kind != "glm_interaction") return;
        model->regressionConfidenceLevelVisible =
            !model->regressionConfidenceLevelVisible;
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetRegressionEffectXAxis: {
        if (!model || model->kind != "glm_interaction" || request.args.empty()) return;
        SetRegressionEffectXAxisOnMain(model, request.args[0]);
        return;
    }
    case CommandAction::SetRegressionEffectQuantity:
    case CommandAction::SetRegressionEffectAdjustment:
    case CommandAction::SetRegressionEffectPresentation:
    case CommandAction::SetRegressionEffectConfidence: {
        if (!model || request.args.empty()) return;
        SetRegressionEffectOptionOnMain(model, request.action, request.args[0]);
        return;
    }
    case CommandAction::ConditionPlotCategorical:
    case CommandAction::ConditionPlotOrdered:
    case CommandAction::ConditionPlotEqualWidth:
    case CommandAction::ConditionPlotEqualCount: {
        if (!model || request.args.empty()) return;
        DataFrameModel dataframe;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
            if (current) { dataframe = *current; found = true; }
        }
        const bool categorical = request.action == CommandAction::ConditionPlotCategorical ||
            request.action == CommandAction::ConditionPlotOrdered;
        const auto kind = categorical
            ? TrellisConditioningVariableKind::Categorical
            : TrellisConditioningVariableKind::ContinuousBinned;
        const auto method = request.action == CommandAction::ConditionPlotEqualCount
            ? TrellisContinuousBinningMethod::EqualCount
            : TrellisContinuousBinningMethod::EqualWidth;
        std::string error;
        if (!found || !rlispstat::core::ConvertPlotToTrellisWithCondition(
                *model, dataframe, request.args[0], kind, method,
                request.action == CommandAction::ConditionPlotOrdered, &error)) {
            ShowWorkbenchMessageOnMain(@"Conditioning variables",
                ToNSString(error.empty() ? "Dataset unavailable." : error));
            return;
        }
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        ReplacePlotViewWithTrellisOnMain(model);
        return;
    }
    case CommandAction::SetPlotColorBy: {
        if (!model || request.args.empty()) return;
        std::map<int, std::string> before;
        std::map<int, std::string> after;
        std::string error;
        bool ok = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto &application = MacCommandDispatcher().applicationState();
            for (const auto &entry : application.displayPointColors(model->group))
                before[entry.first] = entry.second;
            ok = application.setColorOverride(model->group, request.args[0], &error);
            if (ok) {
                for (const auto &entry : application.displayPointColors(model->group))
                    after[entry.first] = entry.second;
                for (auto &[id, linkedPlot] : g_plots) {
                    if (!linkedPlot || linkedPlot->group != model->group) continue;
                    if (linkedPlot->kind == "barplot")
                        linkedPlot->barplotRowColorDisplay =
                            application.colorOverride(model->group)
                                ? (linkedPlot->barplotSplitVariable.empty()
                                    ? "bar_fill" : "composition_strip")
                                : "hide";
                    rlispstat::core::RefreshBasicPlotCodeReference(application, *linkedPlot);
                }
            }
        }
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Override Colors",
                ToNSString(error.empty() ? "Dataset unavailable." : error));
            return;
        }
        std::vector<int> changedRows;
        for (const auto &[row, color] : before)
            if (after.find(row) == after.end() || after[row] != color) changedRows.push_back(row);
        for (const auto &[row, color] : after)
            if (before.find(row) == before.end()) changedRows.push_back(row);
        std::sort(changedRows.begin(), changedRows.end());
        changedRows.erase(std::unique(changedRows.begin(), changedRows.end()), changedRows.end());
        PublishSpreadPlotMessage("ROW_COLORS_CHANGED", model->group,
            model->id, "", changedRows, 0);
        RedrawGroupViewsSynchronouslyOnMain(model->group, true);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::SaveColorScheme: {
        if (!model) return;
        std::size_t count = 0;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            count = MacCommandDispatcher().applicationState()
                .resolveActiveAnalysisRowIds(model->group).size();
        }
        const auto name = PromptForColorSchemeName(count);
        if (!name) return;
        std::string error;
        bool ok = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            ok = MacCommandDispatcher().applicationState()
                .saveCurrentColorsAsScheme(model->group, *name, &error);
        }
        if (!ok) ShowWorkbenchMessageOnMain(@"Save Color Scheme", ToNSString(error));
        return;
    }
    case CommandAction::ApplyColorScheme: {
        if (!model || request.args.empty()) return;
        const std::string name = request.args[0];
        rlispstat::core::ColorSchemeCompatibility compatibility;
        std::string error;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            compatibility = MacCommandDispatcher().applicationState()
                .colorSchemeCompatibility(model->group, name, &error);
        }
        if (!error.empty()) {
            ShowWorkbenchMessageOnMain(@"Apply Color Scheme", ToNSString(error));
            return;
        }
        enum class Choice { Matching, SwitchScope, Cancel };
        Choice choice = Choice::Matching;
        if (!compatibility.exactScope) {
            NSAlert *alert = [[NSAlert alloc] init];
            [alert setMessageText:@"This color scheme was created for a different scope"];
            NSString *versionNote = compatibility.sameDataVersion
                ? @"" : @" The dataset version has also changed.";
            [alert setInformativeText:[NSString stringWithFormat:
                @"\"%s\" contains colors for %lu observations. The current scope contains %lu observations; %lu observations match.%@",
                name.c_str(), (unsigned long)compatibility.schemeScopeCount,
                (unsigned long)compatibility.currentScopeCount,
                (unsigned long)compatibility.matchingObservationCount, versionNote]];
            [alert addButtonWithTitle:@"Apply to Matching Observations Only"];
            [alert addButtonWithTitle:@"Switch to Scheme Scope and Apply"];
            [alert addButtonWithTitle:@"Cancel"];
            const NSModalResponse response = [alert runModal];
            [alert release];
            if (response == NSAlertSecondButtonReturn) choice = Choice::SwitchScope;
            else if (response != NSAlertFirstButtonReturn) choice = Choice::Cancel;
        }
        if (choice == Choice::Cancel) return;
        std::vector<int> changedRows;
        rlispstat::core::AnalysisScopeChangeEvent scopeEvent;
        bool ok = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            auto &application = MacCommandDispatcher().applicationState();
            ok = choice == Choice::SwitchScope
                ? application.switchToColorSchemeScopeAndApply(
                    model->group, name, &scopeEvent, &changedRows, &error)
                : application.applyColorSchemeToMatchingObservations(
                    model->group, name, &changedRows, &error);
        }
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Apply Color Scheme", ToNSString(error));
            return;
        }
        if (choice == Choice::SwitchScope) {
            PublishSpreadPlotMessage("ANALYSIS_SCOPE_CHANGED", model->group,
                "color-scheme", scopeEvent.currentScope.sourceDescription, {},
                static_cast<int>(scopeEvent.version));
            RefreshDataDeskWindowsOnMain(model->group);
        }
        PublishSpreadPlotMessage("ROW_COLORS_CHANGED", model->group,
            model->id, "", changedRows, 0);
        RedrawGroupViewsSynchronouslyOnMain(model->group, true);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::SetPlotColorLegendVisible: {
        if (!model || request.args.empty()) return;
        model->colorByLegendVisible = request.args[0] != "0";
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetPlotColorLegendPosition: {
        if (!model || request.args.empty() ||
            !rlispstat::core::SetPlotColorLegendPosition(*model, request.args[0])) return;
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetTrellisScatterplotX:
    case CommandAction::SetTrellisScatterplotY:
    case CommandAction::SetTrellisScatterplotCondition: {
        if (!model || model->kind != "trellis_scatterplot" || request.args.empty()) return;
        DataFrameModel dataframe;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
            if (current) { dataframe = *current; found = true; }
        }
        rlispstat::core::InitializeTrellisSpecificationFromLegacy(*model);
        PlotModel candidate = *model;
        if (request.action == CommandAction::SetTrellisScatterplotX) {
            candidate.trellisSpecification.xVariableId = request.args[0];
        } else if (request.action == CommandAction::SetTrellisScatterplotY) {
            candidate.trellisSpecification.yVariableId = request.args[0];
        } else {
            const std::string current = request.args.size() >= 2
                ? request.args[0]
                : candidate.trellisSpecification.conditioningVariables.front().variableId;
            const std::string replacement = request.args.size() >= 2
                ? request.args[1] : request.args[0];
            std::string error;
            if (!found || !rlispstat::core::ReplaceTrellisConditioningVariable(
                    candidate, dataframe, current, replacement, &error)) {
                ShowWorkbenchMessageOnMain(@"Trellis Scatterplot",
                    ToNSString(error.empty() ? "Dataset unavailable." : error));
                return;
            }
        }
        std::string error;
        if (request.action != CommandAction::SetTrellisScatterplotCondition &&
            (!found || !rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error))) {
            ShowWorkbenchMessageOnMain(@"Trellis Scatterplot", ToNSString(error.empty() ? "Dataset unavailable." : error));
            return;
        }
        *model = std::move(candidate);
        const bool smoothRequested =
            rlispstat::core::InvalidateTrellisSmoothCurvesForDataChange(*model) &&
            model->trellisSpecification.plotType == TrellisPlotType::Scatter;
        UpdateWindowTitleOnMain(model);
        RedrawPlotOnMain(model->id);
        UpdatePanelOnMain();
        if (smoothRequested) NotifyMainRTaskAvailable();
        return;
    }
    case CommandAction::SetTrellisScatterplotLayout: {
        if (!model || model->kind != "trellis_scatterplot" || request.args.empty()) return;
        const std::string mode = request.args[0];
        if (mode != "automatic" && mode != "one_row" && mode != "one_column" && mode != "grid" &&
            mode != "two_columns" && mode != "three_columns") return;
        model->trellisLayoutMode = mode;
        rlispstat::core::InitializeTrellisSpecificationFromLegacy(*model);
        model->trellisSpecification.layoutMode = mode;
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetTrellisScatterplotOrder: {
        if (!model || model->kind != "trellis_scatterplot" || request.args.empty()) return;
        const std::string order = request.args[0];
        if (order != "defined" && order != "ascending" && order != "descending") return;
        model->trellisPanelOrder = order;
        rlispstat::core::InitializeTrellisSpecificationFromLegacy(*model);
        model->trellisSpecification.panelOrder = order;
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        RedrawPlotOnMain(model->id);
        return;
    }
    case CommandAction::SetTrellisPlotType:
    case CommandAction::SetTrellisPlotTypeWithX:
    case CommandAction::AddTrellisConditionCategorical:
    case CommandAction::AddTrellisConditionOrdered:
    case CommandAction::AddTrellisConditionEqualWidth:
    case CommandAction::AddTrellisConditionEqualCount:
    case CommandAction::SetTrellisConditionFactor:
    case CommandAction::SetTrellisConditionOrdered:
    case CommandAction::SetTrellisConditionEqualWidth:
    case CommandAction::SetTrellisConditionEqualCount:
    case CommandAction::RemoveTrellisCondition:
    case CommandAction::MoveTrellisConditionEarlier:
    case CommandAction::MoveTrellisConditionLater:
    case CommandAction::ConfigureTrellisConditionEqualWidth:
    case CommandAction::ConfigureTrellisConditionEqualCount:
    case CommandAction::ConfigureTrellisConditionBins:
    case CommandAction::SetTrellisConditionDimensionRows:
    case CommandAction::SetTrellisConditionDimensionColumns:
    case CommandAction::SetTrellisConditionDimensionNested:
    case CommandAction::SwapTrellisRowsAndColumns:
    case CommandAction::SetTrellisSplitVariable:
    case CommandAction::SetTrellisScaleMode:
    case CommandAction::SetTrellisBarMeasure:
    case CommandAction::SetTrellisHistogramMeasure:
    case CommandAction::SetTrellisHistogramBins:
    case CommandAction::ToggleTrellisConnectObservations: {
        if (!model || model->kind != "trellis_scatterplot") return;
        rlispstat::core::InitializeTrellisSpecificationFromLegacy(*model);
        DataFrameModel dataframe;
        bool found = false;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *current = FindDataFrameUnlockedConst(model->group);
            if (current) { dataframe = *current; found = true; }
        }
        if (!found) return;
        PlotModel candidate = *model;
        std::string error;
        bool ok = true;
        if ((request.action == CommandAction::SetTrellisPlotType ||
             request.action == CommandAction::SetTrellisPlotTypeWithX) && !request.args.empty()) {
            const std::optional<TrellisPlotType> type = rlispstat::core::ParseTrellisPlotType(request.args[0]);
            if (!type) return;
            candidate.trellisSpecification.plotType = *type;
            if (request.action == CommandAction::SetTrellisPlotTypeWithX && request.args.size() >= 2) {
                candidate.trellisSpecification.xVariableId = request.args[1];
            }
            if (*type == TrellisPlotType::DataTable) {
                rlispstat::core::InitializeTrellisDataTableSpecification(candidate, dataframe);
            }
            ok = rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error);
        } else if ((request.action == CommandAction::AddTrellisConditionCategorical ||
                    request.action == CommandAction::AddTrellisConditionOrdered ||
                    request.action == CommandAction::AddTrellisConditionEqualWidth ||
                    request.action == CommandAction::AddTrellisConditionEqualCount) && !request.args.empty()) {
            const bool categorical = request.action == CommandAction::AddTrellisConditionCategorical ||
                request.action == CommandAction::AddTrellisConditionOrdered;
            ok = rlispstat::core::AddTrellisConditioningVariable(candidate, dataframe, request.args[0],
                categorical ? TrellisConditioningVariableKind::Categorical :
                              TrellisConditioningVariableKind::ContinuousBinned,
                request.action == CommandAction::AddTrellisConditionEqualCount
                    ? TrellisContinuousBinningMethod::EqualCount
                    : TrellisContinuousBinningMethod::EqualWidth, &error,
                request.action == CommandAction::AddTrellisConditionOrdered);
        } else if ((request.action == CommandAction::SetTrellisConditionFactor ||
                    request.action == CommandAction::SetTrellisConditionOrdered ||
                    request.action == CommandAction::SetTrellisConditionEqualWidth ||
                    request.action == CommandAction::SetTrellisConditionEqualCount) && !request.args.empty()) {
            const bool categorical = request.action == CommandAction::SetTrellisConditionFactor ||
                request.action == CommandAction::SetTrellisConditionOrdered;
            ok = rlispstat::core::SetTrellisConditioningInterpretation(
                candidate, dataframe, request.args[0],
                categorical ? TrellisConditioningVariableKind::Categorical
                            : TrellisConditioningVariableKind::ContinuousBinned,
                request.action == CommandAction::SetTrellisConditionEqualCount
                    ? TrellisContinuousBinningMethod::EqualCount
                    : TrellisContinuousBinningMethod::EqualWidth,
                request.action == CommandAction::SetTrellisConditionOrdered, &error);
        } else if (request.action == CommandAction::RemoveTrellisCondition && !request.args.empty()) {
            ok = rlispstat::core::RemoveTrellisConditioningVariable(candidate, dataframe, request.args[0], &error);
        } else if ((request.action == CommandAction::MoveTrellisConditionEarlier ||
                    request.action == CommandAction::MoveTrellisConditionLater) && !request.args.empty()) {
            ok = rlispstat::core::MoveTrellisConditioningVariable(candidate, dataframe, request.args[0],
                request.action == CommandAction::MoveTrellisConditionEarlier ? -1 : 1, &error);
        } else if ((request.action == CommandAction::ConfigureTrellisConditionEqualWidth ||
                    request.action == CommandAction::ConfigureTrellisConditionEqualCount) && !request.args.empty()) {
            std::size_t bins = 4;
            for (const TrellisConditioningVariable &condition : candidate.trellisSpecification.conditioningVariables) {
                if (condition.variableId == request.args[0] && condition.binning) bins = condition.binning->binCount;
            }
            ok = rlispstat::core::ConfigureTrellisContinuousCondition(candidate, dataframe, request.args[0],
                request.action == CommandAction::ConfigureTrellisConditionEqualCount
                    ? TrellisContinuousBinningMethod::EqualCount
                    : TrellisContinuousBinningMethod::EqualWidth, bins, &error);
        } else if (request.action == CommandAction::ConfigureTrellisConditionBins && request.args.size() >= 2) {
            const std::size_t bins = static_cast<std::size_t>(std::max(2L, std::min(6L,
                std::strtol(request.args[1].c_str(), nullptr, 10))));
            TrellisContinuousBinningMethod method = TrellisContinuousBinningMethod::EqualWidth;
            for (const TrellisConditioningVariable &condition : candidate.trellisSpecification.conditioningVariables) {
                if (condition.variableId == request.args[0] && condition.binning) method = condition.binning->method;
            }
            ok = rlispstat::core::ConfigureTrellisContinuousCondition(candidate, dataframe,
                request.args[0], method, bins, &error);
        } else if ((request.action == CommandAction::SetTrellisConditionDimensionRows ||
                    request.action == CommandAction::SetTrellisConditionDimensionColumns ||
                    request.action == CommandAction::SetTrellisConditionDimensionNested) && !request.args.empty()) {
            const TrellisDimension dimension = request.action == CommandAction::SetTrellisConditionDimensionRows
                ? TrellisDimension::Rows
                : (request.action == CommandAction::SetTrellisConditionDimensionColumns
                    ? TrellisDimension::Columns : TrellisDimension::Nested);
            ok = rlispstat::core::SetTrellisConditioningDimension(
                candidate, dataframe, request.args[0], dimension, &error);
        } else if (request.action == CommandAction::SwapTrellisRowsAndColumns) {
            ok = rlispstat::core::SwapTrellisRowsAndColumns(candidate, dataframe, &error);
        } else if (request.action == CommandAction::SetTrellisSplitVariable && !request.args.empty()) {
            const std::string variable = request.args[0] == "." ? "" : request.args[0];
            if (candidate.trellisSpecification.plotType == TrellisPlotType::TimeSeries) {
                candidate.trellisSpecification.groupingVariableId = variable;
            } else {
                candidate.trellisSpecification.splitVariableId = variable;
            }
            ok = rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error);
            if (ok && (candidate.trellisSpecification.plotType == TrellisPlotType::Scatter ||
                       candidate.trellisSpecification.plotType == TrellisPlotType::Histogram))
                ok = rlispstat::core::SetPlotColorByVariable(
                    candidate, dataframe, variable, &error);
        } else if (request.action == CommandAction::SetTrellisScaleMode && !request.args.empty()) {
            const std::string mode = request.args[0];
            if (mode != "common_xy" && mode != "free_x" && mode != "free_y" && mode != "free_xy") return;
            candidate.trellisSpecification.scaleMode = mode;
        } else if (request.action == CommandAction::SetTrellisBarMeasure && !request.args.empty()) {
            if (request.args[0] != "count" && request.args[0] != "percent" &&
                request.args[0] != "conditional_percent") return;
            candidate.trellisSpecification.barMeasure = request.args[0];
            ok = rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error);
        } else if (request.action == CommandAction::SetTrellisHistogramMeasure && !request.args.empty()) {
            if (request.args[0] != "count" && request.args[0] != "density" && request.args[0] != "percent") return;
            candidate.trellisSpecification.histogramMeasure = request.args[0];
            ok = rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error);
        } else if (request.action == CommandAction::SetTrellisHistogramBins && !request.args.empty()) {
            const auto count = rlispstat::core::HistogramBinCountForChoice(candidate, request.args[0]);
            if (!count) return;
            candidate.trellisSpecification.histogramBinCount = static_cast<std::size_t>(*count);
            ok = rlispstat::core::RebuildTrellisPlotFromDataFrame(candidate, dataframe, &error);
        } else if (request.action == CommandAction::ToggleTrellisConnectObservations) {
            candidate.trellisSpecification.connectObservations =
                !candidate.trellisSpecification.connectObservations;
        } else {
            return;
        }
        if (!ok) {
            ShowWorkbenchMessageOnMain(@"Trellis Plot", ToNSString(error));
            return;
        }
        *model = std::move(candidate);
        const bool smoothInputsChanged = request.action == CommandAction::SetTrellisPlotType ||
            request.action == CommandAction::SetTrellisPlotTypeWithX ||
            request.action == CommandAction::AddTrellisConditionCategorical ||
            request.action == CommandAction::AddTrellisConditionOrdered ||
            request.action == CommandAction::AddTrellisConditionEqualWidth ||
            request.action == CommandAction::AddTrellisConditionEqualCount ||
            request.action == CommandAction::SetTrellisConditionFactor ||
            request.action == CommandAction::SetTrellisConditionOrdered ||
            request.action == CommandAction::SetTrellisConditionEqualWidth ||
            request.action == CommandAction::SetTrellisConditionEqualCount ||
            request.action == CommandAction::RemoveTrellisCondition ||
            request.action == CommandAction::MoveTrellisConditionEarlier ||
            request.action == CommandAction::MoveTrellisConditionLater ||
            request.action == CommandAction::ConfigureTrellisConditionEqualWidth ||
            request.action == CommandAction::ConfigureTrellisConditionEqualCount ||
            request.action == CommandAction::ConfigureTrellisConditionBins ||
            request.action == CommandAction::SetTrellisSplitVariable;
        const bool smoothRequested = smoothInputsChanged &&
            model->trellisSpecification.plotType == TrellisPlotType::Scatter &&
            rlispstat::core::InvalidateTrellisSmoothCurvesForDataChange(*model);
        if (smoothRequested) {
            NotifyMainRTaskAvailable();
        }
        rlispstat::core::RefreshBasicPlotCodeReference(
            MacCommandDispatcher().applicationState(), *model);
        UpdateWindowTitleOnMain(model);
        RedrawPlotOnMain(model->id);
        UpdatePanelOnMain();
        return;
    }
    case CommandAction::SetModeNone:
        if (!model) return;
        model->interactionMode = "none";
        break;
    case CommandAction::SetModeSelect:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        model->interactionMode = "select";
        break;
    case CommandAction::SetModeBrush:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        model->interactionMode = "brush";
        break;
    case CommandAction::SetModeIdentify:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        model->interactionMode = "identify";
        break;
    case CommandAction::SetModeLabel:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        model->interactionMode = "label";
        break;
    case CommandAction::SetModePan:
        if (!model) return;
        model->interactionMode = "pan";
        break;
    case CommandAction::SetModeZoom:
        if (!model) return;
        model->interactionMode = "zoom";
        break;
    case CommandAction::SetSelectionReplace:
        if (!model) return;
        model->selectionMode = "replace";
        break;
    case CommandAction::SetSelectionAdd:
        if (!model) return;
        model->selectionMode = "add";
        break;
    case CommandAction::SetSelectionSubtract:
        if (!model) return;
        model->selectionMode = "subtract";
        break;
    case CommandAction::SetSelectionToggle:
        if (!model) return;
        model->selectionMode = "toggle";
        break;
    case CommandAction::ClearSelection: {
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        bool changed = false;
        int selectionVersion = 0;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            changed = ClearGroupSelectionUnlocked(model->group, &selectionVersion);
        }
        if (changed) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", model->group, model->id, "", std::vector<int>(), selectionVersion);
        }
        break;
    }
    case CommandAction::InvertSelection: {
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        int selectionVersion = 0;
        if (InvertSelection(model, &selectionVersion)) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", model->group, model->id, "", std::vector<int>(), selectionVersion);
        }
        break;
    }
    case CommandAction::SelectAllVisible: {
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        int selectionVersion = 0;
        if (SelectAllVisible(model, &selectionVersion)) {
            std::set<int> rows = VisibleRowsForModel(model);
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", model->group, model->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
        }
        break;
    }
    case CommandAction::ResetZoom:
        if (!model) return;
        model->xmin = model->dataXmin;
        model->xmax = model->dataXmax;
        model->ymin = model->dataYmin;
        model->ymax = model->dataYmax;
        break;
    case CommandAction::BrushLarger:
        if (!model) return;
        model->brushWidth = std::min(400.0, model->brushWidth * 1.25);
        model->brushHeight = std::min(300.0, model->brushHeight * 1.25);
        break;
    case CommandAction::BrushSmaller:
        if (!model) return;
        model->brushWidth = std::max(12.0, model->brushWidth / 1.25);
        model->brushHeight = std::max(12.0, model->brushHeight / 1.25);
        break;
    case CommandAction::CopySelected:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        CopySelectedRowsToClipboard(model);
        break;
    case CommandAction::ToggleLmAll:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        ToggleOverlaySource(model, "all");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::ToggleLmSelected:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        ToggleOverlaySource(model, "selected");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::ToggleLmColor:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        ToggleOverlaySource(model, "color");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::ToggleLmBoth: {
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        bool hasAll = HasOverlaySource(model, "all");
        bool hasSelected = HasOverlaySource(model, "selected");
        if (hasAll && hasSelected) {
            RemoveOverlaySource(model, "all");
            RemoveOverlaySource(model, "selected");
        } else {
            AddOverlaySource(model, "all");
            AddOverlaySource(model, "selected");
        }
        NotifyMainRTaskAvailable();
        break;
    }
    case CommandAction::AddLmAll:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        AddOverlaySource(model, "all");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::AddLmSelected:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        AddOverlaySource(model, "selected");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::AddLmBoth:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        AddOverlaySource(model, "all");
        AddOverlaySource(model, "selected");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::AddLmColor:
        if (!model) return;
        if (!(model && rlispstat::core::PlotLinksToDataRows(*model))) return;
        AddOverlaySource(model, "color");
        NotifyMainRTaskAvailable();
        break;
    case CommandAction::ClearOverlays:
        if (!model) return;
        model->overlays.clear();
        rlispstat::core::InvalidateScatterMatrixFits(*model);
        break;
    case CommandAction::ToggleSmoothOverall: {
        if (!model) return;
        ToggleSmoothCurvesForScope(model, rlispstat::core::SmoothCurveScope::Overall);
        break;
    }
    case CommandAction::ToggleSmoothSelected: {
        if (!model) return;
        ToggleSmoothCurvesForScope(model, rlispstat::core::SmoothCurveScope::Selection);
        break;
    }
    case CommandAction::ToggleSmoothColor: {
        if (!model) return;
        ToggleSmoothCurvesForScope(model, rlispstat::core::SmoothCurveScope::ColorGroup);
        break;
    }
    case CommandAction::SaveSvg:
        if (!model) return;
        ShowPlotExportSavePanelOnMain(model->id, "SVG");
        return;
    case CommandAction::SavePng:
        if (!model) return;
        ShowPlotExportSavePanelOnMain(model->id, "PNG");
        return;
    case CommandAction::SavePdf:
        if (!model) return;
        ShowPlotExportSavePanelOnMain(model->id, "PDF");
        return;
    case CommandAction::CopySvg:
        if (!model) return;
        if (!QueuePlotSvgCopyOnMain(model->id)) {
            ShowWorkbenchMessageOnMain(ToNSString(PlotCopyFailedTitle()),
                                       @"The SVG could not be generated from the current plot.");
        }
        return;
    case CommandAction::CopyEmf:
        return;
    case CommandAction::CopyPng:
        if (!model) return;
        if (!CopyPlotViewToPasteboardOnMain(model->id, "PNG")) {
            ShowWorkbenchMessageOnMain(ToNSString(PlotCopyFailedTitle()),
                                       ToNSString(PlotCopyFailedStatus()));
        }
        return;
    case CommandAction::CopyPdf:
        if (!model) return;
        if (!CopyPlotViewToPasteboardOnMain(model->id, "PDF")) {
            ShowWorkbenchMessageOnMain(ToNSString(PlotCopyFailedTitle()),
                                       ToNSString(PlotCopyFailedStatus()));
        }
        return;
    case CommandAction::ClosePlot: {
        if (!model) return;
        std::string plotId = model->id;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            DetachPlotModelUnlocked(plotId);
        }
        ClosePlotOnMain(plotId);
        UpdatePanelOnMain();
        return;
    }
    default:
        break;
    }
    if (command == "EDIT_CLEAR_SELECTION") {
        DispatchCommand(model, "CLEAR_SELECTION");
        return;
    }
    if (command == "EDIT_COPY" || command == "EDIT_COPY_SELECTION") {
        DispatchCommand(model, "COPY_SELECTED");
        return;
    }
    if (command == "FILE_CLOSE_WORKBENCH") {
        (void)MacCommandDispatcher().dispatch({"CLOSE_ALL"});
        return;
    }
    if (command == "FILE_CLOSE_DATASET") {
        std::string group;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
        }
        CloseDatasetAndAnalysesOnMain(group);
        return;
    }
    if (command.rfind("VARIABLE_MAKE_DEPENDENT|", 0) == 0 ||
        command.rfind("VARIABLE_ADD_PREDICTOR|", 0) == 0) {
        size_t sep = command.find('|');
        size_t sep2 = command.find('|', sep + 1);
        if (sep2 != std::string::npos) {
            std::string action = command.substr(0, sep);
            std::string group = command.substr(sep + 1, sep2 - sep - 1);
            std::string variable = command.substr(sep2 + 1);
            ApplyVariableAction(group, variable, action == "VARIABLE_MAKE_DEPENDENT" ? "dependent" : "predictor");
        }
        return;
    }
    if (!model) {
        return;
    }

    rlispstat::core::RefreshBasicPlotCodeReference(
        MacCommandDispatcher().applicationState(), *model);
    UpdateWindowTitleOnMain(model);
    RedrawPlotOnMain(model->id);
    UpdatePanelOnMain();
}

static NSRect ColorLegendFrame(PlotModel *model, NSRect bounds)
{
    if (!model || model->colorByVariable.empty() || model->colorByLegendItems.empty()) return NSZeroRect;
    std::map<int, std::string> linkedRowColors;
    if (model->frozenAppearanceCaptured) {
        linkedRowColors = model->frozenRowColors;
    } else {
        std::lock_guard<std::mutex> lock(g_mutex);
        linkedRowColors = DisplayPointColorMap(model->group);
    }
    if (!rlispstat::core::PlotColorLegendMatchesLinkedRowColors(
            *model, linkedRowColors)) return NSZeroRect;
    std::size_t longest = model->colorByVariable.size();
    for (const auto &item : model->colorByLegendItems) longest = std::max(longest, item.first.size());
    const CGFloat width = std::max<CGFloat>(108.0,
        std::min<CGFloat>(260.0, 48.0 + 7.2 * (CGFloat)longest));
    const CGFloat height = 24.0 + 22.0 * (CGFloat)model->colorByLegendItems.size();
    const CGFloat x = std::clamp<CGFloat>(model->colorByLegendX * NSWidth(bounds),
        4.0, std::max<CGFloat>(4.0, NSWidth(bounds) - width - 4.0));
    const CGFloat top = std::clamp<CGFloat>(model->colorByLegendY * NSHeight(bounds),
        4.0, std::max<CGFloat>(4.0, NSHeight(bounds) - height - 4.0));
    // ScatterView is flipped, so the stored normalized Y coordinate is already
    // measured from the top.  Converting it as an AppKit bottom coordinate
    // inverted the Top/Bottom menu choices and put the title below the items.
    return NSMakeRect(x, top, width, height);
}

static void DrawColorLegend(PlotModel *model, NSRect bounds, const PlotThemeStyle &theme)
{
    if (!model || !model->colorByLegendVisible) return;
    const NSRect frame = ColorLegendFrame(model, bounds);
    if (NSIsEmptyRect(frame)) return;
    // Use the same quiet legend treatment as effect plots: a light rounded
    // panel, a small bold title and compact point keys.  The title area still
    // acts as the drag handle and opens the legend menu when clicked.
    [[theme.panel colorWithAlphaComponent:0.96] setFill];
    [[theme.majorGrid colorWithAlphaComponent:0.75] setStroke];
    NSBezierPath *background = [NSBezierPath bezierPathWithRoundedRect:frame xRadius:4 yRadius:4];
    [background fill]; [background setLineWidth:0.6]; [background stroke];
    NSDictionary *titleAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10.0 weight:NSFontWeightBold],
        NSForegroundColorAttributeName: theme.text
    };
    [ToNSString(model->colorByVariable) drawAtPoint:NSMakePoint(NSMinX(frame) + 6.0,
        NSMinY(frame) + 5.0) withAttributes:titleAttributes];
    NSDictionary *labelAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10.0 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    CGFloat centerY = NSMinY(frame) + 35.0;
    for (const auto &item : model->colorByLegendItems) {
        [ColorForNameOrHex(item.second, 1.0) setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(
            NSMinX(frame) + 13.0, centerY - 3.0, 6.0, 6.0)] fill];
        [ToNSString(item.first) drawAtPoint:NSMakePoint(NSMinX(frame) + 27.0, centerY - 7.0)
            withAttributes:labelAttributes];
        centerY += 22.0;
    }
}

@implementation Table1WindowController (NestedContextMenus)

- (NSMenu *)contextMenuForNestedRowVariable:(const std::string &)variable
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(variable)];
    NSMenuItem *heading = [[NSMenuItem alloc] initWithTitle:ToNSString(variable)
        action:nil keyEquivalent:@""];
    [heading setEnabled:NO]; [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];

    DataFrameModel dataframe;
    bool found = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *current = FindDataFrameUnlockedConst(_state.datasetId);
        if (current) { dataframe = *current; found = true; }
    }
    NSMenuItem *replaceRoot = [[NSMenuItem alloc] initWithTitle:@"Replace with" action:nil keyEquivalent:@""];
    NSMenu *replaceMenu = [[NSMenu alloc] initWithTitle:@"Replace with"];
    NSMenuItem *addRoot = [[NSMenuItem alloc] initWithTitle:@"Add row variable" action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:@"Add row variable"];
    if (found) {
        for (const DataColumn &column : dataframe.columns) {
            if (!rlispstat::core::AnalysisVariableIsCompatible(
                    column, rlispstat::core::AnalysisVariableType::Categorical) ||
                std::find(_state.variables.begin(), _state.variables.end(), column.name) !=
                    _state.variables.end()) continue;
            NSMenuItem *replace = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name)
                action:@selector(replaceRowVariableFromMenu:) keyEquivalent:@""];
            [replace setTarget:self];
            [replace setRepresentedObject:@[ToNSString(variable), ToNSString(column.name)]];
            [replaceMenu addItem:replace];
            NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:ToNSString(column.name)
                action:@selector(addRowVariableFromMenu:) keyEquivalent:@""];
            [add setTarget:self]; [add setRepresentedObject:ToNSString(column.name)];
            [addMenu addItem:add];
        }
    }
    [replaceRoot setSubmenu:replaceMenu];
    [replaceRoot setEnabled:[replaceMenu numberOfItems] > 0]; [menu addItem:replaceRoot];
    [addRoot setSubmenu:addMenu]; [addRoot setEnabled:[addMenu numberOfItems] > 0];
    [menu addItem:addRoot];
    NSMenuItem *moveToColumn = [[NSMenuItem alloc] initWithTitle:@"Move to columns"
        action:@selector(changeSplitVariableFromMenu:) keyEquivalent:@""];
    [moveToColumn setTarget:self];
    [moveToColumn setRepresentedObject:ToNSString(variable)];
    [moveToColumn setEnabled:!_state.groupVariable.empty() || _state.variables.size() > 1];
    [menu addItem:moveToColumn];

    NSMenuItem *typeRoot = [[NSMenuItem alloc] initWithTitle:@"Type of variable" action:nil keyEquivalent:@""];
    NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:@"Type of variable"];
    const std::string currentType = rlispstat::core::Table1VariableAnalysisType(_state, variable);
    for (const char *type : {"numeric", "categorical", "ordinal"}) {
        NSMenuItem *item = [[NSMenuItem alloc]
            initWithTitle:ToNSString(rlispstat::core::Table1TypeMenuTitle(type))
            action:@selector(typeMenuSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ToNSString(variable), ToNSString(std::string(type))]];
        [item setState:currentType == type ? NSControlStateValueOn : NSControlStateValueOff];
        [typeMenu addItem:item];
    }
    [typeRoot setSubmenu:typeMenu]; [menu addItem:typeRoot];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *remove = [[NSMenuItem alloc]
        initWithTitle:ToNSString(rlispstat::core::Table1RemoveVariableTitle(variable))
        action:@selector(removeRowVariableFromMenu:) keyEquivalent:@""];
    [remove setTarget:self]; [remove setRepresentedObject:ToNSString(variable)];
    [remove setEnabled:_state.variables.size() > 1]; [menu addItem:remove];
    [menu addItem:[NSMenuItem separatorItem]];
    AddStandardResultTableExportMenu(
        menu, _reportView, ToNSString(_state.title), ToNSString(_state.id),
        ToNSString([self tableText]), _state.id, true);
    return menu;
}

@end

@implementation GLMWindowController (PredictorCentering)

- (void)showReferenceLevelMenu:(id)sender
{
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    const std::string term = represented ? [represented UTF8String] : [self selectedTerm];
    if (term.empty() || IsInteractionTerm(term)) return;
    DataFrameModel dataframe;
    std::string current;
    bool available = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
            available = true;
        }
        const auto found = state.factorReferenceLevels.find(term);
        if (found != state.factorReferenceLevels.end()) current = found->second;
    }
    if (!available) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        *_model, &dataframe, term);
    if (metadata.levels.empty()) return;
    if (current.empty()) current = metadata.levels.front();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Reference category"];
    for (const std::string &level : metadata.levels) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:ToNSString(level)
            action:@selector(referenceLevelSelected:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@[ToNSString(term), ToNSString(level)]];
        [item setState:level == current ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(18, 18) inView:_coefView];
}

- (void)referenceLevelSelected:(id)sender
{
    NSArray *payload = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    if (![payload isKindOfClass:[NSArray class]] || [payload count] != 2) return;
    NSString *termValue = payload[0];
    NSString *levelValue = payload[1];
    if (!termValue || !levelValue) return;
    const std::string term = [termValue UTF8String];
    const std::string level = [levelValue UTF8String];
    DataFrameModel dataframe;
    bool available = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (const DataFrameModel *found = FindDataFrameUnlockedConst(_model->group)) {
            dataframe = *found;
            available = true;
        }
    }
    if (!available) return;
    const auto metadata = rlispstat::core::PredictorMetadataForModelSpecification(
        *_model, &dataframe, term);
    std::string message;
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        const auto edit = rlispstat::core::SetModelSpecificationReferenceLevel(
            state, term, level, metadata.levels);
        if (!edit.ok) message = edit.message;
        else if (edit.changed) {
            rlispstat::core::MarkGroupModelChanged(state);
            changed = true;
        }
    }
    if (!message.empty()) {
        [_statusField setStringValue:ToNSString(message)];
        return;
    }
    if (changed) [self refresh];
}

- (void)toggleCenterPredictor:(id)sender
{
    NSString *represented = [sender respondsToSelector:@selector(representedObject)]
        ? [sender representedObject] : nil;
    const std::string requested = represented ? [represented UTF8String] : [self selectedTerm];
    if (requested.empty()) return;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        GroupModelState &state = EnsureGroupModelUnlocked(_modelId, _model);
        bool changed = false;
        if (requested == "__none__") {
            const std::set<std::string> currentlyCentered = state.centeredPredictors;
            for (const std::string &term : currentlyCentered) {
                const auto edit = rlispstat::core::SetModelSpecificationPredictorCentered(
                    state, term, false);
                changed = changed || (edit.ok && edit.changed);
            }
        }
        else if (requested == "__all__") {
            for (const std::string &term : state.terms) {
                if (IsInteractionTerm(term)) continue;
                const auto edit = rlispstat::core::SetModelSpecificationPredictorCentered(
                    state, term, true);
                changed = changed || (edit.ok && edit.changed);
            }
        } else {
            const bool center = state.centeredPredictors.count(requested) == 0;
            const auto edit = rlispstat::core::SetModelSpecificationPredictorCentered(
                state, requested, center);
            if (!edit.ok) return;
            changed = edit.changed;
        }
        if (changed) rlispstat::core::MarkGroupModelChanged(state);
    }
    [self refresh];
}

@end

@implementation Table1WindowController (NestedSplitContextMenu)

- (NSMenu *)contextMenuForNestedSplitVariable
{
    const std::string variable = _state.groupVariable;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Column split variable"];
