- (void)changeBiplotDisplay:(id)sender
{
    if (!self.model) return;
    NSString *choice = [sender representedObject];
    if ([choice isEqualToString:@"shading"]) self.model->scatterShadeOverlap = !self.model->scatterShadeOverlap;
    else if ([choice isEqualToString:@"overlap"]) self.model->scatterSizeByOverlap = !self.model->scatterSizeByOverlap;
    else if ([choice isEqualToString:@"label-column"]) ShowChooseLabelColumnDialogOnMain(self.model->group);
    else self.model->labelDisplayMode = std::string([choice UTF8String]);
    [self setNeedsDisplay:YES];
}

- (NSMenu *)biplotDisplayMenu
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Display"];
    auto add = [&](NSMenu *parent, NSString *title, NSString *value, bool checked) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(changeBiplotDisplay:) keyEquivalent:@""];
        item.target = self; item.representedObject = value;
        item.state = checked ? NSControlStateValueOn : NSControlStateValueOff;
        [parent addItem:item];
    };
    add(menu, @"Transparent points (shade overlaps)", @"shading", self.model->scatterShadeOverlap);
    add(menu, @"Size points by overlap", @"overlap", self.model->scatterSizeByOverlap);
    if (NSMenuItem *pointSize = [self pointSizeMenuItem]) {
        [menu addItem:pointSize];
    }
    NSMenuItem *labels = [[NSMenuItem alloc] initWithTitle:@"Case labels" action:nil keyEquivalent:@""];
    NSMenu *choices = [[NSMenu alloc] initWithTitle:@"Case labels"];
    add(choices, @"Choose label variable…", @"label-column", false);
    [choices addItem:[NSMenuItem separatorItem]];
    for (const auto &option : rlispstat::core::ScatterplotLabelDisplayMenuOptions(self.model->labelDisplayMode))
        add(choices, ToNSString(option.title), ToNSString(option.value), option.checked);
    labels.submenu = choices; [menu addItem:labels];
    return menu;
}

- (void)explorePlot:(id)sender
{
    if (!self.model) return;
    NSString *value = [sender representedObject];
    if ([value hasPrefix:@"mode:"]) self.model->interactionMode = std::string([[value substringFromIndex:5] UTF8String]);
    else if ([value hasPrefix:@"selection:"]) self.model->selectionMode = std::string([[value substringFromIndex:10] UTF8String]);
    else if ([value isEqualToString:@"reset"]) {
        self.model->xmin = self.model->dataXmin; self.model->xmax = self.model->dataXmax;
        self.model->ymin = self.model->dataYmin; self.model->ymax = self.model->dataYmax;
    } else {
        int version = 0; bool changed = false;
        if ([value isEqualToString:@"clear"]) {
            std::lock_guard<std::mutex> lock(g_mutex);
            changed = ClearGroupSelectionUnlocked(self.model->group, &version);
        } else if ([value isEqualToString:@"all"]) changed = SelectAllVisible(self.model, &version);
        else if ([value isEqualToString:@"invert"]) changed = InvertSelection(self.model, &version);
        if (changed) PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", {}, version);
        RedrawGroupViewsSynchronouslyOnMain(self.model->group, true);
    }
    [self setNeedsDisplay:YES];
}

- (NSMenu *)plotExploreMenu
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Explore plot"];
    auto add = [&](NSString *title, NSString *value, bool checked) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(explorePlot:) keyEquivalent:@""];
        item.target = self; item.representedObject = value;
        item.state = checked ? NSControlStateValueOn : NSControlStateValueOff; [menu addItem:item];
    };
    const bool navigation = self.model->kind != "scatter_matrix" && self.model->kind != "trellis_scatterplot";
    for (NSArray *entry in @[@[@"Select cases", @"select"], @[@"Brush cases", @"brush"], @[@"Pan", @"pan"], @[@"Zoom", @"zoom"]]) {
        if (!navigation && ([entry[1] isEqualToString:@"pan"] || [entry[1] isEqualToString:@"zoom"])) continue;
        add(entry[0], [@"mode:" stringByAppendingString:entry[1]], self.model->interactionMode == [entry[1] UTF8String]);
    }
    [menu addItem:[NSMenuItem separatorItem]];
    for (const auto &option : rlispstat::core::ScatterplotSelectionModeMenuOptions())
        add(ToNSString(option.title), [@"selection:" stringByAppendingString:ToNSString(option.value)], self.model->selectionMode == option.value);
    [menu addItem:[NSMenuItem separatorItem]];
    add(@"Select all visible cases", @"all", false);
    add(@"Clear selection", @"clear", false);
    add(@"Invert selection", @"invert", false);
    if (navigation) add(@"Reset zoom", @"reset", false);
    return menu;
}

- (NSMenu *)biplotMenuForEvent:(NSEvent *)event
{
    (void)event;
    if (!g_commandTarget) g_commandTarget = [[CommandTarget alloc] init];
    const rlispstat::core::PlotContextMenuTitles titles =
        rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Biplot"];

    NSMenuItem *displayRoot = [[NSMenuItem alloc] initWithTitle:@"Display" action:nil keyEquivalent:@""];
    NSMenu *display = [self biplotDisplayMenu];
    auto stateIt = g_dimensionalityModels.find(self.model->dimensionalityModelId);
    if (stateIt != g_dimensionalityModels.end()) {
        const DimensionalityState &state = stateIt->second;
        for (NSNumber *axis in @[@YES, @NO]) {
            const BOOL isX = [axis boolValue];
            NSString *axisTitle = isX ? @"Horizontal component" : @"Vertical component";
            NSMenuItem *axisRoot = [[NSMenuItem alloc] initWithTitle:axisTitle action:nil keyEquivalent:@""];
            NSMenu *axisMenu = [[NSMenu alloc] initWithTitle:axisTitle];
            for (const DimensionalityComponent &component : state.components) {
                std::string label = DimensionalityComponentMenuLabel(
                    state.method, component.index, component.variance);
                NSString *command = [NSString stringWithFormat:@"%@|%d",
                    isX ? @"PCA_BIPLOT_SET_X" : @"PCA_BIPLOT_SET_Y", component.index];
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:ToNSString(label) action:@selector(runCommand:) keyEquivalent:@""];
                [item setTarget:g_commandTarget]; [item setRepresentedObject:command];
                [item setState:((isX && component.index == self.model->biplotXComponent) ||
                    (!isX && component.index == self.model->biplotYComponent))
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [item setEnabled:(isX ? component.index != self.model->biplotYComponent
                                     : component.index != self.model->biplotXComponent)];
                [axisMenu addItem:item];
            }
            [display setSubmenu:axisMenu forItem:axisRoot]; [display addItem:axisRoot];
        }
        [display addItem:[NSMenuItem separatorItem]];
    }
    AddPlotThemeSubmenu(display, self);
    [menu setSubmenu:display forItem:displayRoot]; [menu addItem:displayRoot];

    NSMenuItem *explore = [[NSMenuItem alloc] initWithTitle:@"Explore plot" action:nil keyEquivalent:@""];
    explore.submenu = [self plotExploreMenu]; [menu addItem:explore];
    [menu addItem:AnalysisScopeSubmenuItemForPlot(self.model)];

    NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:@"Export" action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:@"Export"];
    AddStandardPlotExportItems(exportMenu, YES);
    [menu setSubmenu:exportMenu forItem:exportRoot]; [menu addItem:exportRoot];
    AddSnapshotAlbumContextItems(menu);
    return FinalizeGraphContextMenu(menu);
}

- (NSMenu *)trellisConditionVariableMenuForIndices:(const std::vector<std::size_t> &)indices
{
    if (!self.model || indices.empty()) return nil;
    rlispstat::core::InitializeTrellisSpecificationFromLegacy(*self.model);
    const auto &conditions = self.model->trellisSpecification.conditioningVariables;
    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group);
        if (!found) return nil;
        dataframe = *found;
    }
    auto replacementMenu = [&](std::size_t conditionIndex) -> NSMenu * {
        if (conditionIndex >= conditions.size()) return nil;
        const TrellisConditioningVariable &current = conditions[conditionIndex];
        NSMenu *choices = [[NSMenu alloc] initWithTitle:@"Conditioning variable"];
        std::set<std::string> used;
        for (std::size_t index = 0; index < conditions.size(); ++index) {
            if (index != conditionIndex) used.insert(conditions[index].variableId);
        }
        for (const DataColumn &column : dataframe.columns) {
            if (column.name == self.model->trellisSpecification.xVariableId ||
                column.name == self.model->trellisSpecification.yVariableId ||
                used.find(column.name) != used.end()) continue;
            const bool compatible = current.kind == TrellisConditioningVariableKind::ContinuousBinned
                ? (NormalizeVariableType(column.type) == "numeric" && DataColumnAllowsNumeric(column))
                : rlispstat::core::TrellisConditionColumnIsValid(column, dataframe.rows);
            if (!compatible) continue;
            NSMenuItem *item = [self menuItem:ToNSString(column.name)
                command:ToNSString("TRELLIS_SCATTERPLOT_SET_CONDITION|" +
                    current.variableId + "|" + column.name)];
            [item setState:column.name == current.variableId
                ? NSControlStateValueOn : NSControlStateValueOff];
            [choices addItem:item];
        }
        if ([choices numberOfItems] == 0) {
            NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:@"No compatible variables"
                                                           action:nil keyEquivalent:@""];
            [empty setEnabled:NO];
            [choices addItem:empty];
        }
        return choices;
    };

    if (indices.size() == 1) return replacementMenu(indices.front());
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Conditioning variables"];
    for (std::size_t index : indices) {
        if (index >= conditions.size()) continue;
        NSMenuItem *root = [[NSMenuItem alloc]
            initWithTitle:ToNSString(conditions[index].variableLabel)
                   action:nil keyEquivalent:@""];
        [menu setSubmenu:replacementMenu(index) forItem:root];
        [menu addItem:root];
    }
    return [menu numberOfItems] > 0 ? menu : nil;
}

- (NSMenu *)trellisDataTableContextMenuForPanel:(NSString *)panelId
                                    originalRow:(NSInteger)originalRow
                                      variable:(NSString *)variable
{
    NSMenu *menu = [self trellisScatterplotMenuForEvent:[NSApp currentEvent]];
    if (originalRow > 0) {
        [menu insertItem:[NSMenuItem separatorItem] atIndex:0];
        if (variable && ![variable isEqualToString:@"_row"]) {
            NSMenuItem *copyCell = [[NSMenuItem alloc] initWithTitle:@"Copy cell"
                action:@selector(trellisDataTableCopy:) keyEquivalent:@""];
            [copyCell setTarget:self];
            [copyCell setRepresentedObject:ToNSString("cell|" +
                std::to_string((long long)originalRow) + "|" + std::string([variable UTF8String]))];
            [menu insertItem:copyCell atIndex:0];
        }
        NSMenuItem *copyRow = [[NSMenuItem alloc] initWithTitle:
            [NSString stringWithFormat:@"Copy row %ld", (long)originalRow]
            action:@selector(trellisDataTableCopy:) keyEquivalent:@""];
        [copyRow setTarget:self];
        [copyRow setRepresentedObject:ToNSString("row|" + std::to_string((long long)originalRow))];
        [menu insertItem:copyRow atIndex:0];
        NSMenuItem *reveal = [[NSMenuItem alloc] initWithTitle:
            [NSString stringWithFormat:@"Reveal row %ld in data sheet", (long)originalRow]
            action:@selector(trellisDataTableRevealRow:) keyEquivalent:@""];
        [reveal setTarget:self];
        [reveal setRepresentedObject:@(originalRow)];
        [menu insertItem:reveal atIndex:0];
    }
    (void)panelId;
    return menu;
}

