    [self setNeedsDisplay:YES];
}

- (void)trellisDataTableToggleVariable:(id)sender
{
    if (!self.model) return;
    NSString *name = [sender representedObject];
    if (!name) return;
    auto &variables = self.model->trellisSpecification.dataTable.displayedVariableIds;
    const std::string variable([name UTF8String]);
    auto found = std::find(variables.begin(), variables.end(), variable);
    if (found == variables.end()) variables.push_back(variable);
    else if (variables.size() > 1) variables.erase(found);
    self.trellisTableSignature = @"";
    [self syncTrellisDataTableViews];
    [self setNeedsDisplay:YES];
}

- (void)trellisDataTableReplaceVariable:(id)sender
{
    NSArray *represented = [sender representedObject];
    if (!self.model || ![represented isKindOfClass:[NSArray class]] ||
        [represented count] < 2) return;
    NSString *oldName = [represented objectAtIndex:0];
    NSString *newName = [represented objectAtIndex:1];
    if (!oldName || !newName) return;
    const std::string oldVariable([oldName UTF8String]);
    const std::string newVariable([newName UTF8String]);
    auto &variables = self.model->trellisSpecification.dataTable.displayedVariableIds;
    if (std::find(variables.begin(), variables.end(), newVariable) != variables.end()) return;
    auto current = std::find(variables.begin(), variables.end(), oldVariable);
    if (current == variables.end()) return;
    *current = newVariable;
    if (self.model->trellisSpecification.dataTable.sort.variableId &&
        *self.model->trellisSpecification.dataTable.sort.variableId == oldVariable) {
        self.model->trellisSpecification.dataTable.sort.variableId = newVariable;
    }
    self.trellisTableSignature = @"";
    [self syncTrellisDataTableViews];
    [self setNeedsDisplay:YES];
}

- (void)trellisDataTableMoveVariable:(id)sender
{
    NSString *value = [sender representedObject];
    if (!self.model || !value) return;
    const std::string encoded([value UTF8String]);
    const std::size_t separator = encoded.find('|');
    if (separator == std::string::npos) return;
    const std::string variable = encoded.substr(0, separator);
    const bool left = encoded.substr(separator + 1) == "left";
    auto &variables = self.model->trellisSpecification.dataTable.displayedVariableIds;
    auto found = std::find(variables.begin(), variables.end(), variable);
    if (found == variables.end()) return;
    const std::size_t index = (std::size_t)std::distance(variables.begin(), found);
    if ((left && index == 0) || (!left && index + 1 >= variables.size())) return;
    std::iter_swap(variables.begin() + index, variables.begin() + (left ? index - 1 : index + 1));
    self.trellisTableSignature = @"";
    [self syncTrellisDataTableViews];
}

- (void)trellisDataTableSort:(id)sender
{
    NSString *value = [sender representedObject];
    if (!self.model || !value) return;
    const std::string encoded([value UTF8String]);
    TrellisDataTableSortSpecification &sort = self.model->trellisSpecification.dataTable.sort;
    sort.variableId.reset();
    if (encoded == "original") sort.order = TrellisDataTableRowOrder::OriginalDatasetOrder;
    else if (encoded == "selected") sort.order = TrellisDataTableRowOrder::SelectedFirst;
    else {
        const std::size_t separator = encoded.find('|');
        if (separator == std::string::npos) return;
        sort.order = encoded.substr(0, separator) == "asc"
            ? TrellisDataTableRowOrder::VariableAscending
            : TrellisDataTableRowOrder::VariableDescending;
        sort.variableId = encoded.substr(separator + 1);
    }
    [self syncTrellisDataTableViews];
}

- (void)trellisDataTableSortVariable:(NSString *)variable ascending:(BOOL)ascending
{
    if (!self.model || !variable || [variable length] == 0) return;
    TrellisDataTableSortSpecification &sort =
        self.model->trellisSpecification.dataTable.sort;
    sort.order = ascending ? TrellisDataTableRowOrder::VariableAscending
                           : TrellisDataTableRowOrder::VariableDescending;
    sort.variableId = std::string([variable UTF8String]);
    [self syncTrellisDataTableViews];
}

- (void)trellisDataTableFitColumns:(id)sender
{
    if (!self.model) return;
    NSString *commandObject = [sender representedObject];
    const std::string command = commandObject ? std::string([commandObject UTF8String]) : "fit";
    TrellisDataTableSpecification &spec = self.model->trellisSpecification.dataTable;
    if (command == "toggle_rows") spec.showOriginalRowIds = !spec.showOriginalRowIds;
    else if (command == "toggle_counts") spec.showSelectionCounts = !spec.showSelectionCounts;
    else if (command == "shared") spec.verticalScrollMode = TrellisDataTableVerticalScrollMode::Shared;
    else if (command == "independent") spec.verticalScrollMode = TrellisDataTableVerticalScrollMode::Independent;
    else if (command == "show_all" || command == "restore_variables") {
        DataFrameModel df;
        { std::lock_guard<std::mutex> lock(g_mutex); const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group); if (found) df = *found; }
        if (command == "show_all") {
            spec.displayedVariableIds.clear();
            for (const DataColumn &column : df.columns) {
                spec.displayedVariableIds.push_back(column.name);
            }
            spec.initialized = true;
        } else {
            rlispstat::core::InitializeTrellisDataTableSpecification(*self.model, df, true);
        }
    }
    else if (command == "default_widths") {
        spec.columnWidths.clear();
    }
    else if (command == "fit_window") {
        const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
        CGFloat available = layout.panels.empty() ? 420.0 :
            (CGFloat)layout.panels.front().plotRect.width - 8.0;
        if (spec.showOriginalRowIds) {
            spec.columnWidths["_row"] = 56.0;
            available -= 56.0;
        }
        const CGFloat width = spec.displayedVariableIds.empty() ? available :
            std::max<CGFloat>(54.0, available / (CGFloat)spec.displayedVariableIds.size());
        for (const std::string &variable : spec.displayedVariableIds) spec.columnWidths[variable] = width;
    }
    else if (command == "restore") {
        DataFrameModel df;
        { std::lock_guard<std::mutex> lock(g_mutex); const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group); if (found) df = *found; }
        spec = TrellisDataTableSpecification();
        rlispstat::core::InitializeTrellisDataTableSpecification(*self.model, df, true);
    } else {
        DataFrameModel df;
        { std::lock_guard<std::mutex> lock(g_mutex); const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group); if (found) df = *found; }
        NSDictionary *attrs = @{NSFontAttributeName: [NSFont systemFontOfSize:12]};
        spec.columnWidths["_row"] = 56.0;
        for (const std::string &variable : spec.displayedVariableIds) {
            CGFloat width = [ToNSString(variable) sizeWithAttributes:attrs].width + 24.0;
            const DataColumn *column = FindDataColumnInDataFrame(df, variable);
            if (column) {
                for (std::size_t row = 0; row < column->values.size(); ++row) {
                    width = std::max(width, [ToNSString(DisplayValueForDataFrameCell(df, *column, row))
                        sizeWithAttributes:attrs].width + 20.0);
                }
            }
            spec.columnWidths[variable] = std::max<CGFloat>(54.0, std::min<CGFloat>(240.0, width));
        }
    }
    self.trellisTableSignature = @"";
    [self syncTrellisDataTableViews];
    [self setNeedsDisplay:YES];
}

- (void)trellisDataTableSelectPanel:(id)sender
{
    if (!self.model) return;
    NSString *panel = [sender representedObject];
    if (!panel) return;
    std::string encoded([panel UTF8String]);
    std::string operation = "replace";
    const std::size_t separator = encoded.find('|');
    if (separator != std::string::npos) {
        operation = encoded.substr(0, separator);
        encoded = encoded.substr(separator + 1);
    }
    const std::vector<int> panelRows = rlispstat::core::TrellisPanelOriginalRows(*self.model, encoded);
    if ([sender tag] == 1) {
        std::string panelLabel(encoded);
        const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
        for (const auto &entry : layout.panels) {
            if (entry.levelId == panelLabel && !entry.label.empty()) panelLabel = entry.label;
        }
        DataSheetWindowController *controller = [[DataSheetWindowController alloc]
            initWithGroup:self.model->group visibleRows:panelRows
            title:("Data Sheet — " + self.model->group + " — " + panelLabel)];
        g_detailDataSheetControllers.push_back(controller);
        [controller show];
        return;
    }
    std::set<int> rows(panelRows.begin(), panelRows.end());
    int version = 0; bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        if (operation == "add" || operation == "remove") {
            std::set<int> next;
            auto found = g_groupSelections.find(self.model->group);
            if (found != g_groupSelections.end()) next = found->second;
            if (operation == "add") next.insert(rows.begin(), rows.end());
            else for (int row : rows) next.erase(row);
            rows = std::move(next);
        }
        changed = SetGroupSelectionUnlocked(self.model->group, rows, &version);
    }
    if (changed) NotifyPortableSelectionChanged(self.model->group, rows, version, true);
    [self syncTrellisDataTableViews];
}

- (void)trellisDataTableRevealRow:(id)sender
{
    if (!self.model) return;
    const NSInteger row = [[sender representedObject] integerValue];
    if (row <= 0) return;
    const std::set<int> rows{(int)row};
    int version = 0; bool changed = false;
    { std::lock_guard<std::mutex> lock(g_mutex); changed = SetGroupSelectionUnlocked(self.model->group, rows, &version); }
    if (changed) NotifyPortableSelectionChanged(self.model->group, rows, version, true);
    RevealDataSheetRowOnMain(self.model->group, (int)row);
}

- (void)trellisDataTableCopy:(id)sender
{
    if (!self.model) return;
    NSString *modeObject = [sender representedObject];
    const std::string mode = modeObject ? std::string([modeObject UTF8String]) : "all";
    DataFrameModel df; std::set<int> selection;
    { std::lock_guard<std::mutex> lock(g_mutex); const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group); if (!found) return; df = *found; auto selected = g_groupSelections.find(self.model->group); if (selected != g_groupSelections.end()) selection = selected->second; }
    if (mode.rfind("cell|", 0) == 0) {
        const std::size_t separator = mode.find('|', 5);
        if (separator == std::string::npos) return;
        const int row = std::atoi(mode.substr(5, separator - 5).c_str());
        const DataColumn *column = FindDataColumnInDataFrame(df, mode.substr(separator + 1));
        if (!column || row <= 0 || row > df.rows) return;
        NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
        [pasteboard clearContents];
        [pasteboard setString:ToNSString(DisplayValueForDataFrameCell(
            df, *column, (std::size_t)row - 1)) forType:NSPasteboardTypeString];
        return;
    }
    std::vector<int> rows; std::string panelId;
    if (mode == "selected") {
        std::set<int> visible;
        for (const DataPoint &point : self.model->points) visible.insert(point.row);
        for (int row : selection) if (visible.find(row) != visible.end()) rows.push_back(row);
    }
    else if (mode.rfind("row|", 0) == 0) rows.push_back(std::atoi(mode.substr(4).c_str()));
    else if (mode.rfind("panel|", 0) == 0) { panelId = mode.substr(6); rows = rlispstat::core::TrellisPanelOriginalRows(*self.model, panelId); }
    else { for (const DataPoint &point : self.model->points) rows.push_back(point.row); std::sort(rows.begin(), rows.end()); rows.erase(std::unique(rows.begin(), rows.end()), rows.end()); }
    const std::string text = rlispstat::core::TrellisDataTableTSV(*self.model, df, rows, !panelId.empty(), panelId);
    NSPasteboard *pasteboard = [NSPasteboard generalPasteboard];
    [pasteboard clearContents];
    [pasteboard setString:ToNSString(text) forType:NSPasteboardTypeString];
}

- (void)trellisDataTableExportCSV:(id)sender
{
    if (!self.model) return;
    NSString *modeObject = [sender representedObject];
    const std::string mode = modeObject ? std::string([modeObject UTF8String]) : "all";
    DataFrameModel df; std::set<int> selection;
    { std::lock_guard<std::mutex> lock(g_mutex); const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group); if (!found) return; df = *found; auto selected = g_groupSelections.find(self.model->group); if (selected != g_groupSelections.end()) selection = selected->second; }
    const std::string csv = mode.rfind("panel|", 0) == 0
        ? rlispstat::core::TrellisDataTablePanelCSV(*self.model, df, mode.substr(6), selection)
        : rlispstat::core::TrellisDataTableAllPanelsCSV(*self.model, df, selection);
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, @"csv");
    [panel setNameFieldStringValue:mode.rfind("panel|", 0) == 0 ? @"trellis_panel.csv" : @"trellis_all_panels.csv"];
    if ([panel runModal] != NSModalResponseOK) return;
    [ToNSString(csv) writeToURL:[panel URL] atomically:YES encoding:NSUTF8StringEncoding error:nil];
}

- (void)trellisDataTableExportPDF:(id)sender
{
    (void)sender;
    NSSavePanel *panel = [NSSavePanel savePanel];
    SetSavePanelExtensionCompat(panel, @"pdf");
    [panel setNameFieldStringValue:@"trellis_data_tables.pdf"];
    if ([panel runModal] != NSModalResponseOK) return;
    const BOOL horizontalHidden = [self.trellisTableHorizontalScroller isHidden];
    const BOOL verticalHidden = [self.trellisTableVerticalScroller isHidden];
    [self.trellisTableHorizontalScroller setHidden:YES];
    [self.trellisTableVerticalScroller setHidden:YES];
    [[self window] makeFirstResponder:self];
    NSData *pdf = [self dataWithPDFInsideRect:[self bounds]];
    [self.trellisTableHorizontalScroller setHidden:horizontalHidden];
    [self.trellisTableVerticalScroller setHidden:verticalHidden];
    [pdf writeToURL:[panel URL] atomically:YES];
}

- (NSMenu *)trellisScatterplotMenuForEvent:(NSEvent *)event
{
    rlispstat::core::InitializeTrellisSpecificationFromLegacy(*self.model);
    const TrellisPlotSpecification &specification = self.model->trellisSpecification;
    const rlispstat::core::PlotContextMenuTitles titles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(titles.root)];

    NSPoint click = [self convertPoint:[event locationInWindow] fromView:nil];
    const rlispstat::core::TrellisScatterplotLayout clickedLayout = [self trellisScatterplotLayout];
    const std::optional<std::size_t> clickedPanel = rlispstat::core::TrellisPanelIndexAtPoint(
        clickedLayout, rlispstat::platform::macos::ToCorePoint(click));
    NSMenuItem *analysis = [[NSMenuItem alloc] initWithTitle:@"Analyze this panel once"
                                                      action:@selector(runTrellisPanelAnalysis:)
                                               keyEquivalent:@""];
    [analysis setTarget:self];
    [analysis setEnabled:clickedPanel.has_value() &&
        specification.plotType != TrellisPlotType::DataTable];
    if (clickedPanel) [analysis setRepresentedObject:@((NSInteger)*clickedPanel)];
    [menu addItem:analysis];
    const std::string analysisPanelId = clickedPanel
        ? clickedLayout.panels[*clickedPanel].levelId : "";
    const std::string analysisPanelDescription = clickedPanel
        ? "Trellis panel — " + clickedLayout.panels[*clickedPanel].label
        : "Trellis panel";
    const std::vector<int> analysisPanelRows = clickedPanel
        ? rlispstat::core::TrellisPanelOriginalRows(*self.model, analysisPanelId)
        : std::vector<int>{};
    [menu addItem:AnalysisScopeSubmenuItemForPlot(
        self.model, analysisPanelRows, "trellis_panel", analysisPanelDescription, analysisPanelId)];
    [menu addItem:[NSMenuItem separatorItem]];
    auto menuItemForSharedOption = [&](const auto &option) {
        NSMenuItem *item = option.command.empty()
            ? [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""]
            : [self menuItem:ToNSString(option.title) command:ToNSString(option.command)];
        [item setEnabled:option.enabled];
        [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
        return item;
    };

    DataFrameModel dataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group);
        if (found) dataframe = DataFrameMenuSnapshot(*found);
    }
    const rlispstat::core::PlotAnalysisContext plotAnalysis =
        rlispstat::core::BuildPlotAnalysisContext(*self.model, dataframe);
    const auto plotAnalysisOptions =
        rlispstat::core::PlotAnalysisMenuOptions(plotAnalysis);
    if (!plotAnalysisOptions.empty()) {
        NSMenuItem *analysisRoot = [[NSMenuItem alloc]
            initWithTitle:@"Analyze This Plot" action:nil keyEquivalent:@""];
        NSMenu *analysisMenu = [[NSMenu alloc] initWithTitle:@"Analyze This Plot"];
        for (const auto &option : plotAnalysisOptions) {
            [analysisMenu addItem:[self menuItem:ToNSString(option.title)
                command:ToNSString(option.command)]];
        }
        [menu setSubmenu:analysisMenu forItem:analysisRoot];
        [menu insertItem:analysisRoot atIndex:1];
    }
    auto numericColumn = [&](const std::string &name) {
        const DataColumn *column = FindDataColumnInDataFrame(dataframe, name);
        return column && NormalizeVariableType(column->type) == "numeric" && DataColumnAllowsNumeric(*column);
    };
    auto timeColumn = [&](const std::string &name) {
        const DataColumn *column = FindDataColumnInDataFrame(dataframe, name);
        if (!column) return false;
        const std::string type = NormalizeVariableType(column->type);
        return (type == "numeric" && DataColumnAllowsNumeric(*column)) || type == "datetime";
    };
    auto categoricalColumn = [&](const std::string &name) {
        const DataColumn *column = FindDataColumnInDataFrame(dataframe, name);
        return column && rlispstat::core::TrellisConditionColumnIsValid(*column, dataframe.rows);
    };

    NSMenuItem *typeRoot = [[NSMenuItem alloc] initWithTitle:@"Panel content" action:nil keyEquivalent:@""];
    NSMenu *typeMenu = [[NSMenu alloc] initWithTitle:@"Panel content"];
    for (const auto &entry : std::vector<std::pair<TrellisPlotType, NSString *>>{
             {TrellisPlotType::Scatter, @"Scatterplot"},
             {TrellisPlotType::TimeSeries, @"Time series"},
             {TrellisPlotType::Boxplot, @"Boxplot"},
             {TrellisPlotType::Bar, @"Bar chart"},
             {TrellisPlotType::Histogram, @"Histogram"},
             {TrellisPlotType::DataTable, @"Data table"}}) {
        NSMenuItem *item = [self menuItem:entry.second command:ToNSString(
            "TRELLIS_SCATTERPLOT_SET_TYPE|" + rlispstat::core::TrellisPlotTypeName(entry.first))];
        bool compatible = false;
        if (entry.first == TrellisPlotType::Scatter) {
            compatible = numericColumn(specification.xVariableId) &&
                         numericColumn(specification.yVariableId) &&
                         specification.xVariableId != specification.yVariableId;
        } else if (entry.first == TrellisPlotType::TimeSeries) {
            compatible = timeColumn(specification.xVariableId) &&
                         numericColumn(specification.yVariableId) &&
                         specification.xVariableId != specification.yVariableId;
        } else if (entry.first == TrellisPlotType::Boxplot) {
            compatible = categoricalColumn(specification.xVariableId) && numericColumn(specification.yVariableId);
        } else if (entry.first == TrellisPlotType::Bar) {
            compatible = categoricalColumn(specification.xVariableId);
        } else if (entry.first == TrellisPlotType::Histogram) {
            compatible = numericColumn(specification.xVariableId);
        } else {
            compatible = true;
        }
        if (!compatible && (entry.first == TrellisPlotType::Boxplot ||
                            entry.first == TrellisPlotType::Bar)) {
            NSMenu *choices = [[NSMenu alloc] initWithTitle:entry.second];
            for (const DataColumn &column : dataframe.columns) {
                bool alreadyConditioning = false;
                for (const TrellisConditioningVariable &condition : specification.conditioningVariables) {
                    if (condition.variableId == column.name) alreadyConditioning = true;
                }
                if (alreadyConditioning || !categoricalColumn(column.name)) continue;
                if (entry.first == TrellisPlotType::Boxplot && !numericColumn(specification.yVariableId)) continue;
                [choices addItem:[self menuItem:ToNSString("Use " + column.name + " as X")
                    command:ToNSString("TRELLIS_SCATTERPLOT_SET_TYPE_WITH_X|" +
                        rlispstat::core::TrellisPlotTypeName(entry.first) + "|" + column.name)]];
            }
            if ([choices numberOfItems] > 0) {
                [item setSubmenu:choices];
                compatible = true;
            }
        }
        if (!compatible && (entry.first == TrellisPlotType::Scatter ||
                            entry.first == TrellisPlotType::TimeSeries ||
                            entry.first == TrellisPlotType::Histogram)) {
            NSMenu *choices = [[NSMenu alloc] initWithTitle:entry.second];
            for (const DataColumn &column : dataframe.columns) {
                if (entry.first == TrellisPlotType::TimeSeries
                        ? !timeColumn(column.name) : !numericColumn(column.name)) continue;
                if ((entry.first == TrellisPlotType::Scatter ||
                     entry.first == TrellisPlotType::TimeSeries) &&
                    (!numericColumn(specification.yVariableId) || column.name == specification.yVariableId)) continue;
                [choices addItem:[self menuItem:ToNSString("Use " + column.name + " as X")
                    command:ToNSString("TRELLIS_SCATTERPLOT_SET_TYPE_WITH_X|" +
                        rlispstat::core::TrellisPlotTypeName(entry.first) + "|" + column.name)]];
            }
            if ([choices numberOfItems] > 0) {
                [item setSubmenu:choices];
                compatible = true;
            }
        }
        [item setEnabled:compatible];
        [item setState:entry.first == specification.plotType ? NSControlStateValueOn : NSControlStateValueOff];
        [typeMenu addItem:item];
    }
    [menu setSubmenu:typeMenu forItem:typeRoot];
    [menu addItem:typeRoot];

    if (specification.plotType != TrellisPlotType::DataTable) {
    NSMenuItem *variablesRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(titles.variables) action:nil keyEquivalent:@""];
    NSMenu *variables = [[NSMenu alloc] initWithTitle:ToNSString(titles.variables)];
    for (const std::pair<NSString *, bool> &axis :
         std::vector<std::pair<NSString *, bool>>{{@"X variable", true}, {@"Y variable", false}}) {
        NSMenuItem *axisRoot = [[NSMenuItem alloc] initWithTitle:axis.first action:nil keyEquivalent:@""];
        NSMenu *axisMenu = [[NSMenu alloc] initWithTitle:axis.first];
        if (!axis.second && specification.plotType == TrellisPlotType::Bar) {
            NSMenuItem *none = [self menuItem:@"None"
                                      command:@"TRELLIS_SCATTERPLOT_SET_SPLIT|."];
            [none setState:specification.splitVariableId.empty()
                ? NSControlStateValueOn : NSControlStateValueOff];
            [axisMenu addItem:none];
            [axisMenu addItem:[NSMenuItem separatorItem]];
        }
        for (const DataColumn &column : dataframe.columns) {
            bool compatible = false;
            if (axis.second) {
                compatible = specification.plotType == TrellisPlotType::TimeSeries
                    ? timeColumn(column.name)
                    : ((specification.plotType == TrellisPlotType::Scatter ||
                        specification.plotType == TrellisPlotType::Histogram)
                        ? numericColumn(column.name) : categoricalColumn(column.name));
            } else {
                compatible = specification.plotType == TrellisPlotType::Bar
                    ? (categoricalColumn(column.name) &&
                       column.name != specification.xVariableId &&
                       std::none_of(specification.conditioningVariables.begin(),
                                    specification.conditioningVariables.end(),
                                    [&](const TrellisConditioningVariable &condition) {
                                        return condition.variableId == column.name;
                                    }))
                    : ((specification.plotType == TrellisPlotType::Scatter ||
                        specification.plotType == TrellisPlotType::TimeSeries ||
                        specification.plotType == TrellisPlotType::Boxplot) &&
                       numericColumn(column.name));
            }
            if (!compatible) continue;
            const std::string command = axis.second
                ? "TRELLIS_SCATTERPLOT_SET_X|"
                : (specification.plotType == TrellisPlotType::Bar
                    ? "TRELLIS_SCATTERPLOT_SET_SPLIT|"
                    : "TRELLIS_SCATTERPLOT_SET_Y|");
            NSMenuItem *item = [self menuItem:ToNSString(column.name)
                                      command:ToNSString(command + column.name)];
            const bool current = column.name == (axis.second
                ? specification.xVariableId
                : (specification.plotType == TrellisPlotType::Bar
                    ? specification.splitVariableId : specification.yVariableId));
            const bool conflicts = (specification.plotType == TrellisPlotType::Scatter ||
                specification.plotType == TrellisPlotType::TimeSeries) &&
                column.name == (axis.second ? specification.yVariableId : specification.xVariableId);
            [item setState:current ? NSControlStateValueOn : NSControlStateValueOff];
            [item setEnabled:!conflicts];
            [axisMenu addItem:item];
        }
        [axisRoot setEnabled:axis.second || specification.plotType == TrellisPlotType::Bar ||
                                      specification.plotType == TrellisPlotType::Scatter ||
                                      specification.plotType == TrellisPlotType::TimeSeries ||
                                      specification.plotType == TrellisPlotType::Boxplot];
        [variables setSubmenu:axisMenu forItem:axisRoot];
        [variables addItem:axisRoot];
    }
    [variables addItem:[NSMenuItem separatorItem]];
    [variables addItem:[self menuItem:@"Open variables window"
                                 command:ToNSString("OPEN_VARIABLES_WINDOW|" + self.model->group)]];
    [menu setSubmenu:variables forItem:variablesRoot];
    [menu addItem:variablesRoot];
    }

    NSMenuItem *conditionRoot = [[NSMenuItem alloc] initWithTitle:@"Conditioning variables" action:nil keyEquivalent:@""];
    NSMenu *conditions = [[NSMenu alloc] initWithTitle:@"Conditioning variables"];
