    for (std::size_t index = 0; index < specification.conditioningVariables.size(); ++index) {
        const TrellisConditioningVariable &condition = specification.conditioningVariables[index];
        const std::string placement = condition.dimension == TrellisDimension::Rows
            ? "Rows" : condition.dimension == TrellisDimension::Columns ? "Columns" : "Nested";
        NSMenuItem *variableRoot = [[NSMenuItem alloc]
            initWithTitle:ToNSString(condition.variableLabel + " \xE2\x80\x94 " + placement)
                   action:nil keyEquivalent:@""];
        NSMenu *variableMenu = [[NSMenu alloc] initWithTitle:ToNSString(condition.variableLabel)];

        NSMenuItem *replaceRoot = [[NSMenuItem alloc] initWithTitle:@"Replace with" action:nil keyEquivalent:@""];
        NSMenu *replaceMenu = [[NSMenu alloc] initWithTitle:@"Replace with"];
        for (const DataColumn &column : dataframe.columns) {
            if (column.name == condition.variableId) continue;
            bool usedElsewhere = false;
            for (std::size_t other = 0; other < specification.conditioningVariables.size(); ++other) {
                if (other != index && specification.conditioningVariables[other].variableId == column.name) {
                    usedElsewhere = true; break;
                }
            }
            const bool axisVariable = specification.plotType != TrellisPlotType::DataTable &&
                (column.name == specification.xVariableId || column.name == specification.yVariableId);
            const bool compatible = condition.kind == TrellisConditioningVariableKind::ContinuousBinned
                ? (NormalizeVariableType(column.type) == "numeric" && DataColumnAllowsNumeric(column))
                : rlispstat::core::TrellisConditionColumnIsValid(column, dataframe.rows);
            if (!usedElsewhere && !axisVariable && compatible) {
                [replaceMenu addItem:[self menuItem:ToNSString(column.name)
                    command:ToNSString("TRELLIS_SCATTERPLOT_SET_CONDITION|" +
                        condition.variableId + "|" + column.name)]];
            }
        }
        [replaceRoot setEnabled:[replaceMenu numberOfItems] > 0];
        [variableMenu setSubmenu:replaceMenu forItem:replaceRoot]; [variableMenu addItem:replaceRoot];

        NSMenuItem *placeRoot = [[NSMenuItem alloc] initWithTitle:@"Place in" action:nil keyEquivalent:@""];
        NSMenu *placeMenu = [[NSMenu alloc] initWithTitle:@"Place in"];
        for (const auto &entry : std::vector<std::tuple<NSString *, std::string, TrellisDimension>>{
                 {@"Rows", "TRELLIS_SCATTERPLOT_DIMENSION_ROWS|", TrellisDimension::Rows},
                 {@"Columns", "TRELLIS_SCATTERPLOT_DIMENSION_COLUMNS|", TrellisDimension::Columns},
                 {@"Nested", "TRELLIS_SCATTERPLOT_DIMENSION_NESTED|", TrellisDimension::Nested}}) {
            NSMenuItem *item = [self menuItem:std::get<0>(entry)
                command:ToNSString(std::get<1>(entry) + condition.variableId)];
            [item setState:condition.dimension == std::get<2>(entry)
                ? NSControlStateValueOn : NSControlStateValueOff];
            [placeMenu addItem:item];
        }
        [variableMenu setSubmenu:placeMenu forItem:placeRoot]; [variableMenu addItem:placeRoot];

        if (numericColumn(condition.variableId)) {
            NSMenuItem *interpretRoot = [[NSMenuItem alloc] initWithTitle:@"Interpret as" action:nil keyEquivalent:@""];
            NSMenu *interpretMenu = [[NSMenu alloc] initWithTitle:@"Interpret as"];
            const TrellisContinuousBinningSpecification binning = condition.binning.value_or(
                TrellisContinuousBinningSpecification{});
            for (const auto &entry : std::vector<std::tuple<NSString *, std::string, bool>>{
                     {@"Categorical", "TRELLIS_SCATTERPLOT_SET_CONDITION_FACTOR|",
                        condition.kind == TrellisConditioningVariableKind::Categorical && !condition.orderedCategories},
                     {@"Ordinal", "TRELLIS_SCATTERPLOT_SET_CONDITION_ORDERED|",
                        condition.kind == TrellisConditioningVariableKind::Categorical && condition.orderedCategories},
                     {@"Equal-width intervals", "TRELLIS_SCATTERPLOT_SET_CONDITION_EQUAL_WIDTH|",
                        condition.kind == TrellisConditioningVariableKind::ContinuousBinned &&
                            binning.method == TrellisContinuousBinningMethod::EqualWidth},
                     {@"Equal-count intervals", "TRELLIS_SCATTERPLOT_SET_CONDITION_EQUAL_COUNT|",
                        condition.kind == TrellisConditioningVariableKind::ContinuousBinned &&
                            binning.method == TrellisContinuousBinningMethod::EqualCount}}) {
                NSMenuItem *item = [self menuItem:std::get<0>(entry)
                    command:ToNSString(std::get<1>(entry) + condition.variableId)];
                [item setState:std::get<2>(entry) ? NSControlStateValueOn : NSControlStateValueOff];
                [interpretMenu addItem:item];
            }
            [variableMenu setSubmenu:interpretMenu forItem:interpretRoot]; [variableMenu addItem:interpretRoot];

            NSMenuItem *binsRoot = [[NSMenuItem alloc] initWithTitle:@"Number of intervals" action:nil keyEquivalent:@""];
            NSMenu *binsMenu = [[NSMenu alloc] initWithTitle:@"Number of intervals"];
            for (int bins = 2; bins <= 6; ++bins) {
                NSMenuItem *item = [self menuItem:[NSString stringWithFormat:@"%d", bins]
                    command:ToNSString("TRELLIS_SCATTERPLOT_CONDITION_BINS|" + condition.variableId +
                        "|" + std::to_string(bins))];
                [item setState:binning.binCount == static_cast<std::size_t>(bins)
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [binsMenu addItem:item];
            }
            [binsRoot setEnabled:condition.kind == TrellisConditioningVariableKind::ContinuousBinned];
            [variableMenu setSubmenu:binsMenu forItem:binsRoot]; [variableMenu addItem:binsRoot];
        }

        [variableMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *earlier = [self menuItem:@"Move earlier" command:ToNSString(
