- (void)runTrellisPanelAnalysis:(id)sender
{
    if (!self.model || self.model->kind != "trellis_scatterplot") return;
    const NSInteger requestedIndex = [[sender representedObject] integerValue];
    const rlispstat::core::TrellisScatterplotLayout layout = [self trellisScatterplotLayout];
    if (requestedIndex < 0 || (std::size_t)requestedIndex >= layout.panels.size()) return;
    const rlispstat::core::TrellisPanelLayout &panel = layout.panels[(std::size_t)requestedIndex];
    std::vector<int> rows;
    for (std::size_t index = 0; index < self.model->points.size(); ++index) {
        if (index < self.model->trellisPointPanels.size() &&
            self.model->trellisPointPanels[index] == panel.panelId) {
            rows.push_back(self.model->points[index].row);
        }
    }
    std::sort(rows.begin(), rows.end());
    rows.erase(std::unique(rows.begin(), rows.end()), rows.end());
    if (rows.empty()) return;
    const TrellisPlotSpecification &specification = self.model->trellisSpecification;
    const std::string panelLabel = (std::size_t)requestedIndex < self.model->trellisPanelLabels.size()
        ? self.model->trellisPanelLabels[(std::size_t)requestedIndex]
        : panel.panelId;
    const std::string grouping = specification.plotType == TrellisPlotType::TimeSeries
        ? specification.groupingVariableId : specification.splitVariableId;
    QueueTrellisPanelAnalysisMainRTask({
        "trellis_panel_" + std::to_string((long long)time(nullptr)) + "_" +
            std::to_string(std::rand() % 1000000),
        self.model->id,
        self.model->group,
        panel.panelId,
        panelLabel,
        rlispstat::core::TrellisPlotTypeName(specification.plotType),
        specification.xVariableId,
        specification.yVariableId,
        grouping,
        rows
    });
}

- (void)editInteractionLegendTitle:(id)sender
{
    (void)sender;
    if (!self.model || self.model->kind != "glm_interaction") return;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Legend title"];
    [alert setInformativeText:@"Leave empty to use the variable label."];
    [alert addButtonWithTitle:@"Apply"];
    [alert addButtonWithTitle:@"Cancel"];
    NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 280, 24)];
    [field setStringValue:ToNSString(self.model->interactionLegendTitleOverride)];
    [alert setAccessoryView:field];
    if ([alert runModal] != NSAlertFirstButtonReturn) return;
    self.model->interactionLegendTitleOverride = [[field stringValue] UTF8String];
    self.model->interactionLegendTitle = self.model->interactionLegendTitleOverride.empty()
        ? self.model->interactionLegendDefaultTitle
        : self.model->interactionLegendTitleOverride;
    rlispstat::core::SynchronizeRegressionPlotCodeReferenceDisplay(*self.model);
    [self setNeedsDisplay:YES];
}

- (void)toggleInteractionLegendTitle:(id)sender
{
    (void)sender;
    if (!self.model || self.model->kind != "glm_interaction") return;
    self.model->interactionLegendTitleVisible = !self.model->interactionLegendTitleVisible;
    rlispstat::core::SynchronizeRegressionPlotCodeReferenceDisplay(*self.model);
    [self setNeedsDisplay:YES];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    if (event && self.model && self.model->isGLMDiagnostic) {
        const NSPoint click = [self convertPoint:[event locationInWindow] fromView:nil];
        if (NSPointInRect(click, [self xAxisLabelRect]))
            if (NSMenu *menu = [self diagnosticAxisMenuForX:YES]) return menu;
        if (NSPointInRect(click, [self yAxisLabelHitRect]))
            if (NSMenu *menu = [self diagnosticAxisMenuForX:NO]) return menu;
    }

    SetActivePlotOnMain(self.model);
    if (!g_commandTarget) {
        g_commandTarget = [[CommandTarget alloc] init];
    }
    if (self.model->kind == "scatter_matrix") {
        return [self scatterMatrixMenuForEvent:event];
    }
    if (self.model->kind == "pca_scree") {
        return [self screeMenuForEvent:event];
    }
    if (self.model->kind == "pca_biplot") {
        return [self biplotMenuForEvent:event];
    }
    if (self.model->kind == "trellis_scatterplot") {
        return [self trellisScatterplotMenuForEvent:event];
    }
    if (self.model->kind == "time_series") return [self timeSeriesContextMenu];
    const rlispstat::core::PlotContextMenuTitles contextTitles = rlispstat::core::DefaultPlotContextMenuTitles();
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.root)];
    if (rlispstat::core::PlotIsAggregateDiagnostic(*self.model)) {
        NSMenuItem *viewRoot = [[NSMenuItem alloc]
            initWithTitle:ToNSString(contextTitles.view) action:nil keyEquivalent:@""];
        NSMenu *viewMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.view)];
        if (NSMenuItem *imputation = [self diagnosticImputationMenuItem])
            [viewMenu addItem:imputation];
        NSMenuItem *legend = [[NSMenuItem alloc]
            initWithTitle:@"Legend position" action:nil keyEquivalent:@""];
        NSMenu *positions = [[NSMenu alloc] initWithTitle:@"Legend position"];
        for (const auto &position : std::vector<std::pair<std::string, NSString *>>{
                 {"right", @"Right"}, {"left", @"Left"},
                 {"top", @"Top"}, {"bottom", @"Bottom"}}) {
            NSMenuItem *item = [self menuItem:position.second command:ToNSString(
                "PLOT_INTERACTION_SET_LEGEND_POSITION|" + position.first)];
            [item setState:!self.model->interactionLegendUsesCustomPosition &&
                self.model->interactionLegendPosition == position.first
                    ? NSControlStateValueOn : NSControlStateValueOff];
            [positions addItem:item];
        }
        [legend setSubmenu:positions];
        [viewMenu addItem:legend];
        if (NSMenuItem *pointSize = [self pointSizeMenuItem]) {
            [viewMenu addItem:[NSMenuItem separatorItem]];
            [viewMenu addItem:pointSize];
        }
        AddPlotThemeSubmenu(viewMenu, self);
        [viewRoot setSubmenu:viewMenu];
        [menu addItem:viewRoot];
        NSMenuItem *exportRoot = [[NSMenuItem alloc]
            initWithTitle:ToNSString(contextTitles.exportMenu) action:nil keyEquivalent:@""];
        NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.exportMenu)];
        AddStandardPlotExportItems(exportMenu, NO);
        if (!self.model->codeReference.provenance.verificationRCode.empty())
            AddRCodeExportItems(exportMenu, "output", self.model->id,
                !self.model->codeReference.publication.availableBackends.empty());
        [exportRoot setSubmenu:exportMenu];
        [menu addItem:exportRoot];
        AddSnapshotAlbumContextItems(menu);
        return FinalizeGraphContextMenu(menu);
    }
    if (self.model->glmDiagnosticKind == "roc_curve") {
        NSPoint click = [self convertPoint:[event locationInWindow] fromView:nil];
        self.rocContextThresholdIndex = [self rocThresholdIndexAtPoint:click maximumDistance:10.0];
        const BOOL hasThreshold = self.rocContextThresholdIndex >= 0;
        NSMenuItem *selectionRoot = [[NSMenuItem alloc]
            initWithTitle:ToNSString(contextTitles.selection) action:nil keyEquivalent:@""];
        NSMenu *selectionMenu = [[NSMenu alloc]
            initWithTitle:ToNSString(contextTitles.selection)];
        NSMenuItem *thresholdRoot = [[NSMenuItem alloc]
            initWithTitle:@"ROC threshold" action:nil keyEquivalent:@""];
        NSMenu *thresholdMenu = [[NSMenu alloc] initWithTitle:@"ROC threshold"];
        for (NSArray<NSString *> *spec in @[
            @[@"Select observations crossing this threshold", @"crossing"],
            @[@"Select false positives", @"false_positive"],
            @[@"Select false negatives", @"false_negative"],
            @[@"Select all misclassified observations", @"misclassified"]]) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:spec[0] action:@selector(selectROCRowsFromMenu:) keyEquivalent:@""];
            [item setTarget:self]; [item setRepresentedObject:spec[1]]; [item setEnabled:hasThreshold];
            [thresholdMenu addItem:item];
        }
        [selectionMenu setSubmenu:thresholdMenu forItem:thresholdRoot];
        [selectionMenu addItem:thresholdRoot];
        [selectionMenu addItem:[NSMenuItem separatorItem]];
        [selectionMenu addItem:[self menuItem:@"Clear selection" command:@"CLEAR_SELECTION"]];
        [selectionMenu addItem:ColorSelectedPointsSubmenuItem(ToNSString(contextTitles.colorSelectedPoints))];
        [selectionMenu addItem:[self menuItem:ToNSString(contextTitles.openColorPalette) command:@"OPEN_COLOR_PALETTE"]];
        [menu setSubmenu:selectionMenu forItem:selectionRoot]; [menu addItem:selectionRoot];
        NSMenuItem *viewRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.view) action:nil keyEquivalent:@""];
        NSMenu *viewMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.view)];
        if (NSMenuItem *pointSize = [self pointSizeMenuItem]) {
            [viewMenu addItem:pointSize];
            [viewMenu addItem:[NSMenuItem separatorItem]];
        }
        AddPlotThemeSubmenu(viewMenu, self);
        [menu setSubmenu:viewMenu forItem:viewRoot]; [menu addItem:viewRoot];
        NSMenuItem *exportRoot = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.exportMenu) action:nil keyEquivalent:@""];
        NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.exportMenu)];
        AddStandardPlotExportItems(exportMenu, YES);
        [menu setSubmenu:exportMenu forItem:exportRoot]; [menu addItem:exportRoot];
        AddSnapshotAlbumContextItems(menu);
        return FinalizeGraphContextMenu(menu);
    }
    std::vector<std::string> numericVariables;
    numericVariables.reserve(self.model->variables.size());
    for (const NumericVariable &var : self.model->variables) {
        numericVariables.push_back(var.name);
    }
    std::vector<rlispstat::core::ScatterplotOverlaySpec> overlaySpecs;
    overlaySpecs.reserve(self.model->overlays.size());
    for (const Overlay &overlay : self.model->overlays) {
        overlaySpecs.push_back(rlispstat::core::ScatterplotOverlaySpec{
            overlay.type,
            overlay.source,
            overlay.visible
        });
    }
    DataFrameModel scatterImputationData;
    bool hasScatterImputationData = false;
    if (!self.model->isGLMDiagnostic &&
        self.model->kind != "glm_interaction") {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group);
        if (found && found->datasetType == "multiple_imputation" &&
            found->imputationCount > 0) {
            scatterImputationData = *found;
            hasScatterImputationData = true;
        }
    }
    rlispstat::core::ScatterplotMenuState menuState =
        rlispstat::core::BuildScatterplotMenuState(
            numericVariables,
            self.model->xLabel,
            self.model->yLabel,
            self.model->group,
            LabelColumnForGroup(self.model->group),
            self.model->labelDisplayMode,
            overlaySpecs,
            hasScatterImputationData ? scatterImputationData.imputationCount : 0,
            hasScatterImputationData ? scatterImputationData.activeImputationVersion : 1,
            hasScatterImputationData ? scatterImputationData.imputationDisplayMode : "version",
            self.model->scatterImputationUncertainty,
            self.model->smoothCurves);
    if (self.model->kind != "scatter") {
        menuState.showImputationUncertaintyOptions = false;
        menuState.imputationUncertaintyOptions.clear();
    }

    NSMenuItem *variables = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.variables) action:nil keyEquivalent:@""];
    NSMenu *variablesMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.variables)];
    NSMenuItem *xMenuItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.changeXVariable) action:nil keyEquivalent:@""];
    NSMenu *xMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.changeXVariable)];
    NSMenuItem *yMenuItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.changeYVariable) action:nil keyEquivalent:@""];
    NSMenu *yMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.changeYVariable)];
    for (const rlispstat::core::ScatterplotMenuOption &option : menuState.variables.xOptions) {
        [xMenu addItem:[self menuItemForOption:option]];
    }
    if (self.model->kind == "time_series") {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *dataframe = FindDataFrameUnlockedConst(self.model->group);
        if (dataframe) {
            for (const DataColumn &column : dataframe->columns) {
                if (column.type != "datetime") continue;
                NSMenuItem *item = [self menuItem:ToNSString(column.name)
                                           command:ToNSString("CHANGE_X_VARIABLE|" + column.name)];
                [item setState:column.name == self.model->xLabel
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [xMenu addItem:item];
            }
        }
    }
    for (const rlispstat::core::ScatterplotMenuOption &option : menuState.variables.yOptions) {
        [yMenu addItem:[self menuItemForOption:option]];
    }
    [variablesMenu setSubmenu:xMenu forItem:xMenuItem];
    [variablesMenu addItem:xMenuItem];
    [variablesMenu setSubmenu:yMenu forItem:yMenuItem];
    [variablesMenu addItem:yMenuItem];
    if (self.model->kind != "time_series") {
        if (NSMenuItem *splitItem = ColorByVariableMenuItem(self.model))
            [variablesMenu addItem:splitItem];
        if (NSMenuItem *legendItem = ColorLegendMenuItem(self.model))
            [variablesMenu addItem:legendItem];
    }
    if (NSMenuItem *conditionItem = ConditioningVariablesMenuItem(self.model))
        [variablesMenu addItem:conditionItem];
    if (self.model->kind == "time_series") {
        NSMenuItem *seriesItem = [[NSMenuItem alloc] initWithTitle:@"Change series variable" action:nil keyEquivalent:@""];
        NSMenu *seriesMenu = [[NSMenu alloc] initWithTitle:@"Change series variable"];
        NSMenuItem *none = [self menuItem:@"(none)" command:@"TIME_SERIES_SET_GROUP|."];
        [none setState:self.model->timeSeriesGroupVariable.empty() ? NSControlStateValueOn : NSControlStateValueOff];
        [seriesMenu addItem:none];
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            const DataFrameModel *dataframe = FindDataFrameUnlockedConst(self.model->group);
            if (dataframe) {
                for (const DataColumn &column : dataframe->columns) {
                    NSMenuItem *item = [self menuItem:ToNSString(column.name)
                                               command:ToNSString("TIME_SERIES_SET_GROUP|" + column.name)];
                    [item setState:column.name == self.model->timeSeriesGroupVariable
                        ? NSControlStateValueOn : NSControlStateValueOff];
                    [seriesMenu addItem:item];
                }
            }
        }
        [variablesMenu setSubmenu:seriesMenu forItem:seriesItem];
        [variablesMenu addItem:seriesItem];
    }
    [variablesMenu addItem:[NSMenuItem separatorItem]];
    [variablesMenu addItem:[self menuItemForOption:menuState.variables.openVariablesWindow]];
    // Regression effect plots are derived from a fitted model.  Do not expose
    // the generic scatterplot X/Y replacement menu: Y is the fitted response,
    // and the permitted X choices are added below from the interaction term.
    if (self.model->kind != "glm_interaction" && !self.model->isGLMDiagnostic) {
        [menu setSubmenu:variablesMenu forItem:variables];
        [menu addItem:variables];
    }

    if (self.model->isGLMDiagnostic) {
        if (NSMenuItem *color = ColorByVariableMenuItem(self.model)) [menu addItem:color];
        if (NSMenuItem *legend = ColorLegendMenuItem(self.model)) [menu addItem:legend];
        if (NSMenu *predictors = [self diagnosticAxisMenuForX:YES];
            self.model->glmDiagnosticKind == "partial_regression" && predictors) {
            NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:@"Predictor" action:nil keyEquivalent:@""];
            [item setSubmenu:predictors]; [menu addItem:item];
        }
    }

    if (self.model->kind == "time_series" && !self.model->timeSeriesGroupVariable.empty()) {
        NSMenuItem *identificationItem = [[NSMenuItem alloc] initWithTitle:@"Series identification" action:nil keyEquivalent:@""];
        NSMenu *identificationMenu = [[NSMenu alloc] initWithTitle:@"Series identification"];
        const std::vector<std::pair<std::string, NSString *>> identificationModes = {
            {"legend", @"Legend"},
            {"start_labels", @"Labels at series starts"},
            {"none", @"None"}
        };
        for (const auto &mode : identificationModes) {
            NSMenuItem *item = [self menuItem:mode.second
                                       command:ToNSString("TIME_SERIES_SET_IDENTIFICATION|" + mode.first)];
            [item setState:self.model->timeSeriesIdentification == mode.first
                ? NSControlStateValueOn : NSControlStateValueOff];
            [identificationMenu addItem:item];
        }
        [identificationMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *positionItem = [[NSMenuItem alloc] initWithTitle:@"Legend position" action:nil keyEquivalent:@""];
        NSMenu *positionMenu = [[NSMenu alloc] initWithTitle:@"Legend position"];
        const std::vector<std::pair<std::string, NSString *>> positions = {
            {"top_left", @"Top left"},
            {"top_right", @"Top right"},
            {"bottom_left", @"Bottom left"},
            {"bottom_right", @"Bottom right"}
        };
        for (const auto &position : positions) {
            NSMenuItem *item = [self menuItem:position.second
                                       command:ToNSString("TIME_SERIES_SET_LEGEND_POSITION|" + position.first)];
            [item setState:self.model->timeSeriesLegendPosition == position.first
                ? NSControlStateValueOn : NSControlStateValueOff];
            [positionMenu addItem:item];
        }
        [positionItem setEnabled:self.model->timeSeriesIdentification == "legend"];
        [identificationMenu setSubmenu:positionMenu forItem:positionItem];
        [identificationMenu addItem:positionItem];
        [menu setSubmenu:identificationMenu forItem:identificationItem];
        [menu addItem:identificationItem];
    }
    if (self.model->kind == "glm_interaction" &&
        !self.model->interactionPlotLines.empty()) {
        const std::vector<std::string> effectVariables =
            SplitInteractionTerm(self.model->glmInteractionTerm);
        if (effectVariables.size() >= 2) {
            NSMenuItem *axisItem = [[NSMenuItem alloc] initWithTitle:@"Horizontal-axis variable"
                                                              action:nil
                                                       keyEquivalent:@""];
            NSMenu *axisMenu = [[NSMenu alloc] initWithTitle:@"Horizontal-axis variable"];
            for (const std::string &variable : effectVariables) {
                NSMenuItem *item = [self menuItem:ToNSString(variable)
                    command:ToNSString("PLOT_REGRESSION_SET_EFFECT_X|" + variable)];
                [item setState:self.model->interactionFocalVariable == variable
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [axisMenu addItem:item];
            }
            [menu setSubmenu:axisMenu forItem:axisItem];
            [menu addItem:axisItem];
        }
        if (self.model->regressionBinaryProbability ||
            self.model->regressionBoundedCount) {
            NSMenuItem *quantityItem = [[NSMenuItem alloc]
                initWithTitle:@"Quantity" action:nil keyEquivalent:@""];
            NSMenu *quantityMenu = [[NSMenu alloc] initWithTitle:@"Quantity"];
            const std::vector<std::pair<std::string, NSString *>> quantityChoices =
                self.model->regressionCeilingHurdle
                ? std::vector<std::pair<std::string, NSString *>>{
                    {"overall_expected_score", @"Overall expected score"},
                    {"perfect_score_probability", @"Perfect score probability"},
                    {"conditional_expected_score", @"Expected score below ceiling"}}
                : self.model->regressionBoundedCount
                ? std::vector<std::pair<std::string, NSString *>>{
                    {"expected_count", @"Expected count"},
                    {"predicted_probability", @"Predicted probability"}}
                : std::vector<std::pair<std::string, NSString *>>{
                    {"predicted_probability", @"Predicted probability"},
                    {"probability_difference", @"Probability difference"}};
            for (const auto &choice : quantityChoices) {
                NSMenuItem *item = [self menuItem:choice.second command:ToNSString(
                    "PLOT_REGRESSION_SET_EFFECT_QUANTITY|" + choice.first)];
                [item setState:self.model->regressionEffectQuantity == choice.first
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [quantityMenu addItem:item];
            }
            [quantityItem setSubmenu:quantityMenu];
            [menu addItem:quantityItem];

            if (self.model->regressionBoundedCount) {
                // Bounded-count effects use ordinary marginal means. Only the
                // response-scale quantity changes; binary counterfactual and
                // percentage-display controls do not apply.
            } else {

            NSMenuItem *adjustmentItem = [[NSMenuItem alloc]
                initWithTitle:@"Adjustment" action:nil keyEquivalent:@""];
            NSMenu *adjustmentMenu = [[NSMenu alloc] initWithTitle:@"Adjustment"];
            for (const auto &choice : std::vector<std::pair<std::string, NSString *>>{
                    {"average_sample", @"Average over analysis sample"},
                    {"reference_profile", @"Reference profile"}}) {
                NSMenuItem *item = [self menuItem:choice.second command:ToNSString(
                    "PLOT_REGRESSION_SET_EFFECT_ADJUSTMENT|" + choice.first)];
                [item setState:self.model->regressionEffectAdjustment == choice.first
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [adjustmentMenu addItem:item];
            }
            [adjustmentItem setSubmenu:adjustmentMenu];
            [menu addItem:adjustmentItem];

            NSMenuItem *displayItem = [[NSMenuItem alloc]
                initWithTitle:@"Probability display" action:nil keyEquivalent:@""];
            NSMenu *displayMenu = [[NSMenu alloc] initWithTitle:@"Probability display"];
            for (const auto &choice : std::vector<std::pair<std::string, NSString *>>{
                    {"percentage", @"Percentage / percentage points"},
                    {"probability", @"Probability (0–1)"}}) {
                NSMenuItem *item = [self menuItem:choice.second command:ToNSString(
                    "PLOT_REGRESSION_SET_EFFECT_PRESENTATION|" + choice.first)];
                [item setState:self.model->regressionEffectPresentation == choice.first
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [displayMenu addItem:item];
            }
            [displayItem setSubmenu:displayMenu];
            [menu addItem:displayItem];

            NSMenuItem *confidenceItem = [[NSMenuItem alloc]
                initWithTitle:@"Confidence level" action:nil keyEquivalent:@""];
            NSMenu *confidenceMenu = [[NSMenu alloc] initWithTitle:@"Confidence level"];
            for (const auto &choice : std::vector<std::pair<std::string, NSString *>>{
                    {"0.90", @"90%"}, {"0.95", @"95%"}, {"0.99", @"99%"}}) {
                NSMenuItem *item = [self menuItem:choice.second command:ToNSString(
                    "PLOT_REGRESSION_SET_EFFECT_CONFIDENCE|" + choice.first)];
                const double level = std::strtod(choice.first.c_str(), nullptr);
                [item setState:std::fabs(self.model->regressionConfidenceLevel - level) < 0.001
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [confidenceMenu addItem:item];
            }
            [confidenceItem setSubmenu:confidenceMenu];
            [menu addItem:confidenceItem];
            }
        }
        NSMenuItem *connectingLine = [self menuItem:
            (self.model->regressionConnectEstimates
                ? @"Hide connecting line" : @"Show connecting line")
            command:@"PLOT_REGRESSION_TOGGLE_CONNECTING_LINE"];
        [connectingLine setState:self.model->regressionConnectEstimates
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:connectingLine];
        NSMenuItem *intervals = [self menuItem:
            (self.model->regressionConfidenceIntervalsVisible
                ? @"Hide confidence intervals" : @"Show confidence intervals")
            command:@"PLOT_REGRESSION_TOGGLE_CONFIDENCE_INTERVALS"];
        [intervals setState:self.model->regressionConfidenceIntervalsVisible
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:intervals];
        NSMenuItem *level = [self menuItem:
            (self.model->regressionConfidenceLevelVisible
                ? @"Hide confidence-level label" : @"Show confidence-level label")
            command:@"PLOT_REGRESSION_TOGGLE_CONFIDENCE_LEVEL"];
        [level setState:self.model->regressionConfidenceLevelVisible
            ? NSControlStateValueOn : NSControlStateValueOff];
        [level setEnabled:self.model->regressionConfidenceIntervalsVisible];
        [menu addItem:level];
        NSMenuItem *positionItem = [[NSMenuItem alloc] initWithTitle:@"Legend position"
                                                              action:nil
                                                       keyEquivalent:@""];
        NSMenu *positionMenu = [[NSMenu alloc] initWithTitle:@"Legend position"];
        const std::vector<std::pair<std::string, NSString *>> positions = {
            {"right", @"Right"},
            {"left", @"Left"},
            {"top", @"Top"},
            {"bottom", @"Bottom"},
            {"outside_right", @"Outside right"},
            {"outside_left", @"Outside left"},
            {"outside_top", @"Outside top"},
            {"outside_bottom", @"Outside bottom"},
            {"manual", @"Manual"}
        };
        for (const auto &position : positions) {
            NSMenuItem *item = [self menuItem:position.second
                                       command:ToNSString(
                                           "PLOT_INTERACTION_SET_LEGEND_POSITION|" +
                                           position.first)];
            [item setState:(position.first == "manual"
                ? self.model->interactionLegendUsesCustomPosition
                : !self.model->interactionLegendUsesCustomPosition &&
                    self.model->interactionLegendPosition == position.first)
                ? NSControlStateValueOn : NSControlStateValueOff];
            [positionMenu addItem:item];
        }
        [positionItem setSubmenu:positionMenu];
        [menu addItem:positionItem];
        NSMenuItem *renameLegend = [[NSMenuItem alloc]
            initWithTitle:@"Rename legend title…"
            action:@selector(editInteractionLegendTitle:) keyEquivalent:@""];
        [renameLegend setTarget:self];
        [menu addItem:renameLegend];
        NSMenuItem *showLegendTitle = [[NSMenuItem alloc]
            initWithTitle:@"Show legend title"
            action:@selector(toggleInteractionLegendTitle:) keyEquivalent:@""];
        [showLegendTitle setTarget:self];
        [showLegendTitle setState:self.model->interactionLegendTitleVisible
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:showLegendTitle];
    }



    NSMenuItem *selection = [[NSMenuItem alloc] initWithTitle:@"Explore plot" action:nil keyEquivalent:@""];
    NSMenu *selectionMenu = [self plotExploreMenu];
    [selectionMenu addItem:[NSMenuItem separatorItem]];
    [selectionMenu addItem:ColorSelectedPointsSubmenuItem(ToNSString(contextTitles.colorSelectedPoints))];
    [selectionMenu addItem:[self menuItem:ToNSString(contextTitles.openColorPalette) command:@"OPEN_COLOR_PALETTE"]];
    [selectionMenu addItem:[NSMenuItem separatorItem]];
    [selectionMenu addItem:AddDataColumnSubmenuItem()];
    [menu setSubmenu:selectionMenu forItem:selection];
    [menu addItem:selection];
    [menu addItem:AnalysisScopeSubmenuItemForPlot(self.model)];



    NSMenuItem *view = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.view) action:nil keyEquivalent:@""];
    NSMenu *viewMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.view)];
    if (self.model->kind == "scatter" && !rlispstat::core::PlotIsAggregateDiagnostic(*self.model)) {
        NSMenuItem *overlap = [self menuItem:@"Shade overlapping points" command:@"SCATTER_TOGGLE_OVERLAP_SHADING"];
        [overlap setState:self.model->scatterShadeOverlap ? NSControlStateValueOn : NSControlStateValueOff];
        [viewMenu addItem:overlap];
        NSMenuItem *overlapSize = [self menuItem:@"Size points by overlap" command:@"SCATTER_TOGGLE_OVERLAP_SIZE"];
        [overlapSize setState:self.model->scatterSizeByOverlap ? NSControlStateValueOn : NSControlStateValueOff];
        [viewMenu addItem:overlapSize];
    }
    if (NSMenuItem *imputation = [self diagnosticImputationMenuItem]) {
        [viewMenu addItem:imputation];
        if (self.model->diagnosticShowImputationUncertainty) {
            NSMenuItem *uncertainty = [[NSMenuItem alloc]
                initWithTitle:@"Imputation uncertainty" action:nil keyEquivalent:@""];
            NSMenu *uncertaintyMenu = [[NSMenu alloc]
                initWithTitle:@"Imputation uncertainty"];
            const std::vector<std::pair<std::string, NSString *>> scopes = {
                {"direct", @"Directly imputed cases"},
                {"all", @"All fitted values (model propagation)"}
            };
            for (const auto &scope : scopes) {
                NSMenuItem *item = [[NSMenuItem alloc]
                    initWithTitle:scope.second
                    action:@selector(selectDiagnosticUncertaintyScope:)
                    keyEquivalent:@""];
                [item setTarget:self];
                [item setRepresentedObject:ToNSString(scope.first)];
                [item setState:self.model->diagnosticImputationUncertaintyScope ==
                        scope.first
                    ? NSControlStateValueOn : NSControlStateValueOff];
                [uncertaintyMenu addItem:item];
            }
            [uncertaintyMenu addItem:[NSMenuItem separatorItem]];
            for (const auto &option :
                 rlispstat::core::ScatterplotImputationUncertaintyMenuOptions(
                     self.model->scatterImputationUncertainty)) {
                [uncertaintyMenu addItem:[self menuItemForOption:option]];
            }
            [viewMenu setSubmenu:uncertaintyMenu forItem:uncertainty];
            [viewMenu addItem:uncertainty];
        }
        [viewMenu addItem:[NSMenuItem separatorItem]];
    }
    if (NSMenuItem *residuals = [self diagnosticResidualMenuItem]) {
        [menu addItem:residuals];
    }
    if (menuState.showImputationDisplayOptions &&
        !self.model->isGLMDiagnostic &&
        self.model->kind != "glm_interaction") {
        NSMenuItem *imputationDisplay = [[NSMenuItem alloc]
            initWithTitle:ToNSString(menuState.imputationDisplayTitle)
                   action:nil keyEquivalent:@""];
        NSMenu *imputationDisplayMenu = [[NSMenu alloc]
            initWithTitle:ToNSString(menuState.imputationDisplayTitle)];
        for (std::size_t index = 0; index < menuState.imputationDisplayOptions.size(); ++index) {
            if (index == static_cast<std::size_t>(scatterImputationData.imputationCount)) {
                [imputationDisplayMenu addItem:[NSMenuItem separatorItem]];
            }
            [imputationDisplayMenu addItem:
                [self menuItemForOption:menuState.imputationDisplayOptions[index]]];
        }
        [viewMenu setSubmenu:imputationDisplayMenu forItem:imputationDisplay];
        [viewMenu addItem:imputationDisplay];
    }
    if (menuState.showImputationUncertaintyOptions && !self.model->isGLMDiagnostic) {
        NSMenuItem *imputationUncertainty = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.imputationUncertainty) action:nil keyEquivalent:@""];
        NSMenu *imputationUncertaintyMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.imputationUncertainty)];
        for (const rlispstat::core::ScatterplotMenuOption &option : menuState.imputationUncertaintyOptions) {
            [imputationUncertaintyMenu addItem:[self menuItemForOption:option]];
        }
        [viewMenu setSubmenu:imputationUncertaintyMenu forItem:imputationUncertainty];
        [viewMenu addItem:imputationUncertainty];
        [viewMenu addItem:[NSMenuItem separatorItem]];
    }
    if (NSMenuItem *pointSize = [self pointSizeMenuItem]) {
        [viewMenu addItem:pointSize];
        [viewMenu addItem:[NSMenuItem separatorItem]];
    }
    AddPlotThemeSubmenu(viewMenu, self);
    [menu setSubmenu:viewMenu forItem:view];
    [menu addItem:view];

    if (rlispstat::core::PlotSupportsObservationLabels(*self.model)) {
    NSMenuItem *labels = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.labels) action:nil keyEquivalent:@""];
    NSMenu *labelsMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.labels)];
    [labelsMenu addItem:[self menuItemForOption:menuState.chooseLabelColumn]];
    [labelsMenu addItem:[NSMenuItem separatorItem]];
    for (const rlispstat::core::ScatterplotMenuOption &option : menuState.labelDisplayOptions) {
        [labelsMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:labelsMenu forItem:labels];
    [menu addItem:labels];
    }

    const bool supportsAddedLines = self.model->kind == "scatter" &&
        (!self.model->isGLMDiagnostic ||
         rlispstat::core::RegressionDiagnosticSupportsAddedLines(*self.model));
    if (supportsAddedLines) {
        NSString *straightTitle = @"Regression lines";
        NSMenuItem *overlays = [[NSMenuItem alloc] initWithTitle:straightTitle action:nil keyEquivalent:@""];
        NSMenu *overlayMenu = [[NSMenu alloc] initWithTitle:straightTitle];
        for (const rlispstat::core::ScatterplotMenuOption &option : menuState.overlayOptions) {
            [overlayMenu addItem:[self menuItemForOption:option]];
        }
        if (self.model->kind == "scatter") {
            NSMenuItem *intervals = [self menuItem:
                (self.model->scatterFitConfidenceIntervalsVisible
                    ? @"Hide confidence intervals" : @"Show confidence intervals")
                command:@"PLOT_REGRESSION_TOGGLE_CONFIDENCE_INTERVALS"];
            [intervals setState:self.model->scatterFitConfidenceIntervalsVisible
                ? NSControlStateValueOn : NSControlStateValueOff];
            [overlayMenu addItem:intervals];
        }
        [overlayMenu addItem:[NSMenuItem separatorItem]];
        [overlayMenu addItem:[self menuItemForOption:menuState.clearOverlays]];
        [menu setSubmenu:overlayMenu forItem:overlays];
        [menu addItem:overlays];
    }

    if (supportsAddedLines && !menuState.smoothOptions.empty()) {
        NSString *smoothTitle = self.model->isGLMDiagnostic
            ? @"Smooth lines" : @"Smooth curves";
        NSMenuItem *smoothItem = [[NSMenuItem alloc] initWithTitle:smoothTitle action:nil keyEquivalent:@""];
        NSMenu *smoothMenu = [[NSMenu alloc] initWithTitle:smoothTitle];
        for (const rlispstat::core::ScatterplotMenuOption &option : menuState.smoothOptions) {
            [smoothMenu addItem:[self menuItemForOption:option]];
        }
        [smoothMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *smoothIntervals = [self menuItem:
            (self.model->scatterSmoothConfidenceIntervalsVisible
                ? @"Hide confidence intervals" : @"Show confidence intervals")
            command:@"PLOT_SMOOTH_TOGGLE_CONFIDENCE_INTERVALS"];
        [smoothIntervals setState:self.model->scatterSmoothConfidenceIntervalsVisible
            ? NSControlStateValueOn : NSControlStateValueOff];
        [smoothMenu addItem:smoothIntervals];
        [smoothMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *spanSlider = [[NSMenuItem alloc]
            initWithTitle:(self.model->smoothShowSpanSlider ? @"Hide Smoothing Slider" : @"Show Smoothing Slider")
                   action:@selector(toggleSmoothSpanControl:)
            keyEquivalent:@""];
        [spanSlider setTarget:self];
        [smoothMenu addItem:spanSlider];
        [menu setSubmenu:smoothMenu forItem:smoothItem];
        [menu addItem:smoothItem];
    }

    DataFrameModel analysisDataframe;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        const DataFrameModel *found = FindDataFrameUnlockedConst(self.model->group);
        if (found) analysisDataframe = *found;
    }
    const auto analysisContext =
        rlispstat::core::BuildPlotAnalysisContext(*self.model, analysisDataframe);
    const auto analysisOptions =
        rlispstat::core::PlotAnalysisMenuOptions(analysisContext);
    if (!analysisOptions.empty()) {
        NSMenuItem *analysisItem = [[NSMenuItem alloc]
            initWithTitle:ToNSString(contextTitles.analyzeThisPlot) action:nil keyEquivalent:@""];
        NSMenu *analysisMenu = [[NSMenu alloc]
            initWithTitle:ToNSString(contextTitles.analyzeThisPlot)];
        for (const auto &option : analysisOptions) {
            [analysisMenu addItem:[self menuItem:ToNSString(option.title)
                command:ToNSString(option.command)]];
        }
        [menu setSubmenu:analysisMenu forItem:analysisItem];
        [menu addItem:analysisItem];
    }

    NSMenuItem *plotItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.plot) action:nil keyEquivalent:@""];
    NSMenu *plotMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.plot)];
    for (const rlispstat::core::ScatterplotMenuOption &option : menuState.plotOptions) {
        [plotMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:plotMenu forItem:plotItem];
    [menu addItem:plotItem];

    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.exportMenu) action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.exportMenu)];
    AddStandardPlotExportItems(exportMenu, YES);
    if (self.model && !self.model->codeReference.provenance.verificationRCode.empty())
        AddRCodeExportItems(exportMenu, "output", self.model->id,
            !self.model->codeReference.publication.availableBackends.empty());
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    AddSnapshotAlbumContextItems(menu);
    return FinalizeGraphContextMenu(menu);
}

- (void)keyDown:(NSEvent *)event
{
    NSString *chars = [event charactersIgnoringModifiers];
    if ([chars length] == 0) {
        [super keyDown:event];
        return;
    }
    unichar ch = [chars characterAtIndex:0];
    NSEventModifierFlags flags = [event modifierFlags];
    if ((flags & NSEventModifierFlagCommand) != 0 && (ch == 's' || ch == 'S')) {
        DispatchCommand(self.model, "SAVE_SVG");
        return;
    }
    if ((flags & NSEventModifierFlagControl) != 0 && (ch == 's' || ch == 'S')) {
        DispatchCommand(self.model, "SAVE_SVG");
        return;
    }
    if (!(self.model && rlispstat::core::PlotLinksToDataRows(*self.model))) {
        [super keyDown:event];
        return;
    }

    switch (ch) {
        case 'c': case 'C': DispatchCommand(self.model, "CLEAR_SELECTION"); break;
        case 'a': case 'A': DispatchCommand(self.model, "SELECT_ALL_VISIBLE"); break;
        case 'v': case 'V': DispatchCommand(self.model, "INVERT_SELECTION"); break;
        case 'l': DispatchCommand(self.model, "ADD_LM_ALL"); break;
        case 'L': DispatchCommand(self.model, "ADD_LM_SELECTED"); break;
        case 'g': case 'G': DispatchCommand(self.model, "OPEN_GLM"); break;
        case 'k': case 'K': DispatchCommand(self.model, "CLEAR_OVERLAYS"); break;
        case 'x': case 'X': [self showVariableMenuForAxis:@"x" atPoint:NSMakePoint(NSMidX([self xAxisLabelRect]), NSMidY([self xAxisLabelRect]))]; break;
        case 'y': case 'Y': [self showVariableMenuForAxis:@"y" atPoint:NSMakePoint(NSMidX([self yAxisLabelHitRect]), NSMidY([self yAxisLabelHitRect]))]; break;
        default: [super keyDown:event]; break;
    }
}

- (void)savePNGToDesktop
{
    NSString *file = [NSHomeDirectory() stringByAppendingPathComponent:
        ToNSString("Desktop/" + rlispstat::core::PlotExportFilename(self.model->id, "PNG"))];
    [self savePNGToPath:file];
}

- (void)savePDFToDesktop
{
    NSString *file = [NSHomeDirectory() stringByAppendingPathComponent:
        ToNSString("Desktop/" + rlispstat::core::PlotExportFilename(self.model->id, "PDF"))];
    [self savePDFToPath:file];
}

- (BOOL)savePNGToPath:(NSString *)path
{
    const bool wasShown = self.model && self.model->smoothShowSpanSlider;
    const bool pointSizeWasShown = self.model && self.model->pointSizeSliderVisible;
    if (self.model) self.model->smoothShowSpanSlider = false;
    if (self.model) self.model->pointSizeSliderVisible = false;
    [self syncSmoothSpanControl];
    [self syncPointSizeControl];
    NSBitmapImageRep *rep = [self bitmapImageRepForCachingDisplayInRect:[self bounds]];
    [self cacheDisplayInRect:[self bounds] toBitmapImageRep:rep];
    NSData *data = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    const BOOL written = [data writeToFile:path atomically:YES];
    if (self.model) self.model->smoothShowSpanSlider = wasShown;
    if (self.model) self.model->pointSizeSliderVisible = pointSizeWasShown;
    [self syncSmoothSpanControl];
    [self syncPointSizeControl];
    return written;
}

- (BOOL)savePDFToPath:(NSString *)path
{
    const bool wasShown = self.model && self.model->smoothShowSpanSlider;
    const bool pointSizeWasShown = self.model && self.model->pointSizeSliderVisible;
    if (self.model) self.model->smoothShowSpanSlider = false;
    if (self.model) self.model->pointSizeSliderVisible = false;
    [self syncSmoothSpanControl];
    [self syncPointSizeControl];
    NSData *data = [self dataWithPDFInsideRect:[self bounds]];
    const BOOL written = [data writeToFile:path atomically:YES];
    if (self.model) self.model->smoothShowSpanSlider = wasShown;
    if (self.model) self.model->pointSizeSliderVisible = pointSizeWasShown;
    [self syncSmoothSpanControl];
    [self syncPointSizeControl];
    return written;
}
@end

@implementation BarplotView
- (instancetype)initWithModel:(PlotModel *)model
{
    rlispstat::core::BarplotViewSize preferred = rlispstat::core::BarplotPreferredViewSize(
        model ? model->barplotBins.size() : 0,
        model && !model->barplotSplitVariable.empty(),
        model ? BarplotXVariablesForModel(model).size() : 1);
    self = [super initWithFrame:NSMakeRect(0, 0, preferred.width, preferred.height)];
    if (self) {
        self.model = model;
        self.dragging = NO;
        self.toolTipTag = 0;
        [self setWantsLayer:YES];
    }
    return self;
}

- (BOOL)acceptsFirstResponder { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)event
{
    (void)event;
    return YES;
}
- (BOOL)isFlipped { return YES; }

- (NSRect)plotRect
{
    NSRect b = [self bounds];
    bool hasSplit = self.model && !self.model->barplotSplitVariable.empty();
    bool showCompositionStrip = hasSplit && self.model->barplotRowColorDisplay == "composition_strip";
    size_t xCount = self.model ? BarplotXVariablesForModel(self.model).size() : 1;
    return rlispstat::platform::macos::ToNSRect(
        rlispstat::core::BarplotPlotRect(
            rlispstat::platform::macos::ToCoreRect(b),
            hasSplit,
            showCompositionStrip,
            xCount));
}

- (NSRect)xAxisLabelRect
{
    NSRect b = [self bounds];
    return rlispstat::platform::macos::ToNSRect(
        rlispstat::core::BarplotXAxisLabelRect(
            rlispstat::platform::macos::ToCoreRect(b),
            rlispstat::platform::macos::ToCoreRect([self plotRect])));
}

- (NSInteger)xCategoryLabelIndexAtPoint:(NSPoint)point
{
    if (!self.model) {
        return -1;
    }
    double verticalOffset = rlispstat::core::BarplotCategoryLabelVerticalOffset(
        self.model->barplotRowColorDisplay == "composition_strip");
    auto hit = rlispstat::core::BarplotCategoryComponentAtPoint(
        [self barplotLayout],
        rlispstat::core::BarplotBinsForModel(self.model),
        BarplotXVariablesForModel(self.model),
        rlispstat::platform::macos::ToCorePoint(point),
        verticalOffset);
    if (hit.has_value()) {
        return (NSInteger)hit->barIndex;
    }
    return -1;
}

- (BOOL)xCategoryComponentAtPoint:(NSPoint)point
                          barIndex:(NSInteger *)barIndexOut
                     variableIndex:(size_t *)variableIndexOut
                              value:(std::string *)valueOut
{
    if (!self.model) {
        return NO;
    }
    double verticalOffset = rlispstat::core::BarplotCategoryLabelVerticalOffset(
        self.model->barplotRowColorDisplay == "composition_strip");
    auto hit = rlispstat::core::BarplotCategoryComponentAtPoint(
        [self barplotLayout],
        rlispstat::core::BarplotBinsForModel(self.model),
        BarplotXVariablesForModel(self.model),
        rlispstat::platform::macos::ToCorePoint(point),
        verticalOffset);
    if (!hit.has_value()) {
        return NO;
    }
    if (barIndexOut) *barIndexOut = (NSInteger)hit->barIndex;
    if (variableIndexOut) *variableIndexOut = hit->variableIndex;
    if (valueOut) *valueOut = hit->value;
    return YES;
}

- (std::vector<int>)rowsForXVariableIndex:(size_t)variableIndex value:(const std::string &)value
{
    if (!self.model) {
        return {};
    }
    return rlispstat::core::BarplotRowsForXVariableValue(
        rlispstat::core::BarplotBinsForModel(self.model),
        BarplotXVariablesForModel(self.model),
        variableIndex,
        value);
}

- (rlispstat::core::BarplotLayout)barplotLayout
{
    if (!self.model) {
        rlispstat::core::BarplotLayout layout;
        layout.plotRect = rlispstat::platform::macos::ToCoreRect([self plotRect]);
        return layout;
    }
    rlispstat::core::BarplotLayoutInput input;
    input.viewRect = rlispstat::platform::macos::ToCoreRect([self bounds]);
    input.xVariables = BarplotXVariablesForModel(self.model);
    input.bins = rlispstat::core::BarplotBinsForModel(self.model);
    input.mode = self.model->barplotMode;
    input.widthMode = self.model->barplotWidthMode;
    input.hasSplit = !self.model->barplotSplitVariable.empty();
    input.showCompositionStrip = self.model->barplotRowColorDisplay == "composition_strip";
    return rlispstat::core::BuildBarplotLayout(input);
}

- (NSRect)rectForBar:(NSInteger)bar
{
    if (bar < 0) {
        return NSZeroRect;
    }
    return rlispstat::platform::macos::ToNSRect(
        rlispstat::core::BarplotBarRect([self barplotLayout], (size_t)bar)
    );
}

- (NSInteger)barIndexAtPoint:(NSPoint)point
{
    std::optional<size_t> index = rlispstat::core::BarplotBarIndexAtPoint(
        [self barplotLayout],
        rlispstat::platform::macos::ToCorePoint(point)
    );
    if (!index.has_value()) {
        return -1;
    }
    return (NSInteger)*index;
}

- (NSRect)rectForSegment:(const BarplotSegment &)segment inBar:(NSRect)barRect barN:(int)barN cursor:(double *)cursor
{
    return rlispstat::platform::macos::ToNSRect(
        rlispstat::core::BarplotSegmentRect(
            rlispstat::platform::macos::ToCoreRect(barRect),
            segment.count,
            barN,
            cursor
        )
    );
}

- (std::vector<std::string>)splitLevelsForDisplay
{
    return rlispstat::core::BarplotSplitLevelsForBins(
        rlispstat::core::BarplotBinsForModel(self.model),
        self.model && !self.model->barplotSplitVariable.empty());
}

- (std::map<std::string, int>)splitLevelTotalsForLevels:(const std::vector<std::string> &)levels
{
    return rlispstat::core::BarplotSplitLevelTotalsForBins(
        rlispstat::core::BarplotBinsForModel(self.model),
        levels);
}

- (NSInteger)splitLevelLabelIndexAtPoint:(NSPoint)point
                                  levels:(std::vector<std::string> *)levelsOut
{
    std::vector<std::string> levels = [self splitLevelsForDisplay];
    if (levelsOut) {
        *levelsOut = levels;
    }
    if (levels.empty()) {
        return -1;
    }
    std::map<std::string, int> totals = [self splitLevelTotalsForLevels:levels];
    auto hit = rlispstat::core::BarplotSplitLevelLabelIndexAtPoint(
        rlispstat::platform::macos::ToCoreRect([self plotRect]),
        levels,
        totals,
        rlispstat::platform::macos::ToCorePoint(point));
    if (hit.has_value()) {
        return (NSInteger)*hit;
    }
    return -1;
}

- (std::vector<int>)rowsForSplitLevel:(const std::string &)level
{
    if (!self.model) {
        return {};
    }
    return rlispstat::core::BarplotRowsForSplitLevel(
        rlispstat::core::BarplotBinsForModel(self.model),
        level);
}

- (BOOL)segmentHitAtPoint:(NSPoint)point
                 barIndex:(NSInteger *)barIndexOut
             segmentIndex:(NSInteger *)segmentIndexOut
              segmentRect:(NSRect *)segmentRectOut
{
    if (!self.model || self.model->barplotSplitVariable.empty()) return NO;
    std::optional<rlispstat::core::BarplotSegmentHit> hit =
        rlispstat::core::BarplotSegmentAtPoint(
            [self barplotLayout],
            rlispstat::core::BarplotBinsForModel(self.model),
            [self splitLevelsForDisplay],
            true,
            rlispstat::platform::macos::ToCorePoint(point));
    if (!hit.has_value()) {
        return NO;
    }
    if (barIndexOut) *barIndexOut = (NSInteger)hit->barIndex;
    if (segmentIndexOut) *segmentIndexOut = (NSInteger)hit->segmentIndex;
    if (segmentRectOut) *segmentRectOut = rlispstat::platform::macos::ToNSRect(hit->rect);
    return YES;
}

- (NSMenu *)segmentMenuForBarIndex:(NSInteger)barIndex segmentIndex:(NSInteger)segmentIndex
{
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::BarplotSegmentMenuTitle())];
    std::optional<rlispstat::core::BarplotSegmentReference> reference =
        BarplotCoreSegmentReferenceForIndices(self.model, (int)barIndex, (int)segmentIndex);
    if (!reference.has_value()) {
        return menu;
    }

    NormalizeBarplotVisualState(self.model);

    std::vector<std::string> levels = BarplotSplitLevels(self.model);
    size_t levelIndex = rlispstat::core::BarplotLevelIndex(levels, reference->segment.level);
    BarplotSegmentVisualStyle style = ResolveBarplotSegmentVisual(
        self.model,
        reference->category,
        reference->segment.level,
        levelIndex);

    auto levelColorIt = self.model->barplotYLevelColors.find(reference->segment.level);
    std::string levelColor = levelColorIt == self.model->barplotYLevelColors.end() ? "" : levelColorIt->second;
    auto levelPatternIt = self.model->barplotYLevelPatterns.find(reference->segment.level);
    std::string levelPattern = levelPatternIt == self.model->barplotYLevelPatterns.end() ? "" : levelPatternIt->second;
    rlispstat::core::BarplotSegmentMenuState menuState =
        rlispstat::core::BuildBarplotSegmentMenuState(
            self.model->xLabel,
            self.model->barplotSplitVariable,
            *reference,
            style,
            BarplotPaletteOrder(),
            levelColor,
            levelPattern);

    [menu addItem:[self menuItem:ToNSString(menuState.selectRows.title)
                         command:ToNSString(menuState.selectRows.command)]];
    [menu addItem:[self menuItem:ToNSString(menuState.applyCurrentColorToRows.title)
                         command:ToNSString(menuState.applyCurrentColorToRows.command)]];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *segmentColorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::BarplotSetSegmentColorMenuItemTitle()) action:nil keyEquivalent:@""];
    NSMenu *segmentColorMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::BarplotSetSegmentColorMenuItemTitle())];
    for (const rlispstat::core::BarplotMenuOption &option : menuState.segmentColorOptions) {
        [segmentColorMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:segmentColorMenu forItem:segmentColorItem];
    [menu addItem:segmentColorItem];

    NSMenuItem *levelColorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.levelColorTitle)
                                                            action:nil
                                                     keyEquivalent:@""];
    NSMenu *levelColorMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.levelColorTitle)];
    for (const rlispstat::core::BarplotMenuOption &option : menuState.levelColorOptions) {
        [levelColorMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:levelColorMenu forItem:levelColorItem];
    [menu addItem:levelColorItem];

    NSMenuItem *segmentOpacityItem = [[NSMenuItem alloc] initWithTitle:ToNSString(rlispstat::core::BarplotSetSegmentOpacityMenuItemTitle()) action:nil keyEquivalent:@""];
    NSMenu *segmentOpacityMenu = [[NSMenu alloc] initWithTitle:ToNSString(rlispstat::core::BarplotSetSegmentOpacityMenuItemTitle())];
    for (const rlispstat::core::BarplotMenuOption &option : menuState.segmentOpacityOptions) {
        [segmentOpacityMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:segmentOpacityMenu forItem:segmentOpacityItem];
    [menu addItem:segmentOpacityItem];

    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self menuItem:ToNSString(menuState.resetSegmentColor.title)
                         command:ToNSString(menuState.resetSegmentColor.command)]];
    [menu addItem:[self menuItem:ToNSString(menuState.resetLevelColor.title)
                         command:ToNSString(menuState.resetLevelColor.command)]];
    [menu addItem:[self menuItem:ToNSString(menuState.details.title)
                         command:ToNSString(menuState.details.command)]];
    return menu;
}

- (std::vector<int>)rowsForPoint:(NSPoint)point
{
    if (!self.model) {
        return {};
    }
    return rlispstat::core::BarplotRowsAtPoint(
        [self barplotLayout],
        rlispstat::core::BarplotBinsForModel(self.model),
        [self splitLevelsForDisplay],
        !self.model->barplotSplitVariable.empty(),
        rlispstat::platform::macos::ToCorePoint(point));
}

- (NSString *)tooltipTextForPoint:(NSPoint)point
{
    if (!self.model) {
        return nil;
    }
    std::map<int, std::string> rowColors = RowColorsForPlot(self.model);
    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto sit = g_groupSelections.find(self.model->group);
        if (sit != g_groupSelections.end()) selection = sit->second;
    }

    NSInteger categoryIndex = -1;
    size_t variableIndex = 0;
    std::string categoryValue;
    if ([self xCategoryComponentAtPoint:point barIndex:&categoryIndex variableIndex:&variableIndex value:&categoryValue]) {
        std::vector<std::string> xVariables = BarplotXVariablesForModel(self.model);
        std::string variableName = variableIndex < xVariables.size() ? xVariables[variableIndex] : self.model->xLabel;
        std::vector<int> categoryRows = [self rowsForXVariableIndex:variableIndex value:categoryValue];
        return ToNSString(rlispstat::core::BarplotCategoryTooltipText(
            variableName,
            categoryValue,
            categoryRows,
            selection));
    }

    std::vector<std::string> labelLevels;
    NSInteger labelIndex = [self splitLevelLabelIndexAtPoint:point levels:&labelLevels];
    if (labelIndex >= 0 && (size_t)labelIndex < labelLevels.size()) {
        std::string level = labelLevels[(size_t)labelIndex];
        std::vector<int> levelRows = [self rowsForSplitLevel:level];
        return ToNSString(rlispstat::core::BarplotSplitLevelTooltipText(
            self.model->barplotSplitVariable,
            level,
            levelRows,
            selection));
    }

    NSInteger bar = [self barIndexAtPoint:point];
    std::vector<rlispstat::core::BarplotBinSummary> bins = rlispstat::core::BarplotBinsForModel(self.model);
    if (bar < 0 || (size_t)bar >= bins.size()) return nil;
    NSInteger hitBar = -1;
    NSInteger hitSegmentIndex = -1;
    std::optional<rlispstat::core::BarplotSegmentReference> reference;
    if ([self segmentHitAtPoint:point
                       barIndex:&hitBar
                   segmentIndex:&hitSegmentIndex
                    segmentRect:nullptr] &&
        hitBar == bar &&
        hitSegmentIndex >= 0) {
        reference = rlispstat::core::BarplotSegmentReferenceForIndices(
            bins,
            (std::size_t)hitBar,
            (std::size_t)hitSegmentIndex);
    }

    std::optional<rlispstat::core::BarplotSegmentSummary> segmentSummary;
    std::optional<rlispstat::core::BarplotSegmentVisualStyle> visualStyle;
    if (reference.has_value()) {
        segmentSummary = reference->segment;
        if (!self.model->barplotSplitVariable.empty()) {
            std::vector<std::string> splitLevels = BarplotSplitLevels(self.model);
            size_t levelIndex = rlispstat::core::BarplotLevelIndex(splitLevels, reference->segment.level);
            visualStyle = ResolveBarplotSegmentVisual(
                self.model,
                reference->category,
                reference->segment.level,
                levelIndex);
        }
    }

    return ToNSString(rlispstat::core::BarplotSegmentTooltipText(
        self.model->xLabel,
        self.model->barplotSplitVariable,
        self.model->barplotWidthMode,
        bins[(std::size_t)bar],
        self.model->barplotTotalN,
        segmentSummary,
        visualStyle,
        rowColors,
        selection,
        BarplotPaletteOrder(),
        self.model->barplotRowColorDisplay != "hide"));
}

- (void)updateTrackingAreas
{
    [super updateTrackingAreas];
    if (self.toolTipTag != 0) {
        [self removeToolTip:self.toolTipTag];
        self.toolTipTag = 0;
    }
    self.toolTipTag = [self addToolTipRect:[self bounds] owner:self userData:NULL];
}

- (NSString *)view:(NSView *)view stringForToolTip:(NSToolTipTag)tag point:(NSPoint)point userData:(void *)data
{
    (void)view;
    (void)tag;
    (void)data;
    return [self tooltipTextForPoint:point];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeOverrideScope snapshotTheme(self.snapshotThemeName ?: PlotLocalThemeName(self));
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);
    rlispstat::core::BarplotLayout layout = [self barplotLayout];
    NSRect pr = rlispstat::platform::macos::ToNSRect(layout.plotRect);
    [theme.panel setFill];
    NSRectFill(pr);

    std::set<int> selection;
    std::map<int, std::string> rowColors = RowColorsForPlot(self.model);
    int selectionVersion = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(self.model->group);
        if (it != g_groupSelections.end()) selection = it->second;
        auto vit = g_groupSelectionVersions.find(self.model->group);
        if (vit != g_groupSelectionVersions.end()) selectionVersion = vit->second;
    }
    self.model->barplotSelectionVersionDisplayed = selectionVersion;
    NormalizeBarplotVisualState(self.model);
    BOOL hasSplit = !self.model->barplotSplitVariable.empty();
    std::vector<std::string> splitLevels = hasSplit ? [self splitLevelsForDisplay] : std::vector<std::string>();
    if (hasSplit && splitLevels.empty()) {
        hasSplit = NO;
    }
    rlispstat::core::BarplotVisualState barplotVisualState = BarplotVisualStateForModel(self.model);

    NSDictionary *titleAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *smallAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10],
        NSForegroundColorAttributeName: theme.mutedText
    };
    NSMutableParagraphStyle *centerStyle = [[NSMutableParagraphStyle alloc] init];
    [centerStyle setAlignment:NSTextAlignmentCenter];
    [centerStyle setLineBreakMode:NSLineBreakByTruncatingMiddle];
    NSDictionary *centerAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10],
        NSForegroundColorAttributeName: theme.mutedText,
        NSParagraphStyleAttributeName: centerStyle
    };

    if (!self.model->title.empty()) {
        NSMutableParagraphStyle *titleStyle = [[NSMutableParagraphStyle alloc] init];
        [titleStyle setAlignment:NSTextAlignmentCenter];
        [titleStyle setLineBreakMode:NSLineBreakByTruncatingTail];
        NSMutableDictionary *centeredTitleAttrs = [titleAttrs mutableCopy];
        [centeredTitleAttrs setObject:titleStyle forKey:NSParagraphStyleAttributeName];
        [ToNSString(self.model->title) drawInRect:NSMakeRect(pr.origin.x, 10, pr.size.width, 20)
                                   withAttributes:centeredTitleAttrs];
    }
    DrawPlotImputationDisplayStatus(self.model, false, pr, 30.0);
    // Subtitle removed per user request
    if (hasSplit) {
        NSDictionary *legendAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10],
            NSForegroundColorAttributeName: theme.mutedText
        };
        NSMutableParagraphStyle *rightStyle = [[NSMutableParagraphStyle alloc] init];
        [rightStyle setAlignment:NSTextAlignmentRight];
        [rightStyle setLineBreakMode:NSLineBreakByTruncatingMiddle];
        NSMutableDictionary *splitLabelAttrs = [legendAttrs mutableCopy];
        [splitLabelAttrs setObject:rightStyle forKey:NSParagraphStyleAttributeName];
        NSDictionary *splitTitleAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text
        };
        std::map<std::string, int> splitTotals = [self splitLevelTotalsForLevels:splitLevels];
        rlispstat::core::BarplotSideLabelDrawPlan sideLabels =
            rlispstat::core::BuildBarplotSideLabelDrawPlan(
                layout.plotRect,
                self.model->barplotSplitVariable,
                splitLevels,
                splitTotals,
                self.model->barplotRowColorDisplay == "composition_strip");
        [ToNSString(sideLabels.splitTitle)
            drawInRect:rlispstat::platform::macos::ToNSRect(sideLabels.splitTitleRect)
        withAttributes:splitTitleAttrs];
        for (const rlispstat::core::BarplotCategoryLabelDrawItem &label : sideLabels.splitLabels) {
            [ToNSString(label.label)
                drawInRect:rlispstat::platform::macos::ToNSRect(label.rect)
            withAttributes:splitLabelAttrs];
        }
        if (sideLabels.showRowStripLabel) {
            [ToNSString(sideLabels.rowStripLabel)
                drawInRect:rlispstat::platform::macos::ToNSRect(sideLabels.rowStripLabelRect)
            withAttributes:splitLabelAttrs];
        }
    }

    double yMax = layout.yMaximum;
    for (const rlispstat::core::BarplotAxisTick &tick : rlispstat::core::BarplotYAxisTicks(yMax, self.model->barplotMode)) {
        double y = rlispstat::core::ZeroBaselineY(layout.plotRect,
            tick.value / std::max(1.0, yMax));
        [theme.majorGrid setStroke];
        NSBezierPath *grid = [NSBezierPath bezierPath];
        [grid moveToPoint:NSMakePoint(pr.origin.x, y)];
        [grid lineToPoint:NSMakePoint(pr.origin.x + pr.size.width, y)];
        [grid stroke];
        NSString *label = ToNSString(tick.label);
        NSSize labelSize = [label sizeWithAttributes:smallAttrs];
        [label drawAtPoint:NSMakePoint(pr.origin.x - labelSize.width - 7.0, y - labelSize.height / 2.0)
            withAttributes:smallAttrs];
    }

    [theme.axis setStroke];
    NSBezierPath *axis = [NSBezierPath bezierPath];
    [axis moveToPoint:NSMakePoint(pr.origin.x, pr.origin.y)];
    [axis lineToPoint:NSMakePoint(pr.origin.x, pr.origin.y + pr.size.height)];
    [axis moveToPoint:NSMakePoint(pr.origin.x,
        rlispstat::core::ZeroBaselineY(layout.plotRect, 0.0))];
    [axis lineToPoint:NSMakePoint(pr.origin.x + pr.size.width,
        rlispstat::core::ZeroBaselineY(layout.plotRect, 0.0))];
    [axis stroke];

    for (NSInteger i = 0; i < (NSInteger)self.model->barplotBins.size(); ++i) {
        const BarplotBin &bin = self.model->barplotBins[(size_t)i];
        NSRect r = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::BarplotBarRect(layout, (size_t)i));
        [(hasSplit
            ? (theme.coordinatedMarks ? theme.geomFill : [NSColor colorWithCalibratedWhite:1.0 alpha:1.0])
            : theme.panel) setFill];
        NSRectFillUsingOperation(r, NSCompositingOperationSourceOver);
        if (hasSplit) {
            NSDictionary *pctBaseAttrs = @{
                NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightSemibold],
                NSParagraphStyleAttributeName: centerStyle
            };
            std::vector<rlispstat::core::BarplotSegmentDrawItem> segmentPlan =
                rlispstat::core::BuildBarplotSegmentDrawPlan(
                    rlispstat::platform::macos::ToCoreRect(r),
                     rlispstat::core::ToBarplotBinSummary(bin),
                    splitLevels,
                    barplotVisualState,
                    rowColors);
            for (const rlispstat::core::BarplotSegmentDrawItem &item : segmentPlan) {
                NSRect segmentRect = rlispstat::platform::macos::ToNSRect(item.rect);
                DrawBarplotSegmentLayers(segmentRect,
                                         self.model,
                                         item.style,
                                         item.levelIndex,
                                         false,
                                         true,
                                         item.drawBottomEdge);

                if (item.useRowColorIdentityLayer) {
                    DrawBarplotRowColorIdentityLayer(segmentRect, item.rows, rowColors, 1.0);
                }

                const std::map<int, std::string> *selectionRowColors = &rowColors;
                std::map<int, std::string> overrideRowColors;
                if (!item.useRowColorIdentityLayer && !item.style.colorKey.empty()) {
                    for (int row : item.rows) {
                        overrideRowColors[row] = item.style.colorKey;
                    }
                    selectionRowColors = &overrideRowColors;
                }
                DrawBarplotSelectionLayer(segmentRect,
                                          item.rows,
                                          selection,
                                          *selectionRowColors,
                                          self.model);

                DrawBarplotSegmentBorder(segmentRect, self.model, true, item.drawBottomEdge);

                if (self.model->barplotShowConditionalPercent && segmentRect.size.height >= 16.0 && r.size.width >= 34.0) {
                    NSString *pct = ToNSString(FormatPercent(item.conditionalPercent / 100.0, 0));
                    NSMutableDictionary *pctAttrs = [pctBaseAttrs mutableCopy];
                    const auto selectionPlan = rlispstat::core::BuildBarplotSelectionSlicePlan(
                        item.rect, item.rows, selection, *selectionRowColors,
                        BarplotPaletteOrder(), SelectedColorForGroup(self.model->group));
                    [pctAttrs setObject:BarplotValueTextColor(selectionPlan,
                        item.rect.y + item.rect.height / 2.0,
                        rlispstat::core::BarplotSelectionDisplayShowsOverlay(
                            self.model->barplotSelectionDisplay))
                                 forKey:NSForegroundColorAttributeName];
                    [pct drawInRect:NSInsetRect(segmentRect, 1.0, std::max(0.0, (segmentRect.size.height - 12.0) / 2.0))
                       withAttributes:pctAttrs];
                }
            }
        } else {
            if (self.model->barplotRowColorDisplay == "bar_fill") {
                std::vector<rlispstat::core::BarplotCompositionSlice> slices =
                    rlispstat::core::BarplotVerticalRowColorCompositionSlices(
                        rlispstat::platform::macos::ToCoreRect(r),
                        bin.rows,
                        rowColors,
                        BarplotPaletteOrder());
                for (const rlispstat::core::BarplotCompositionSlice &slice : slices) {
                    CGFloat sliceAlpha = slice.colorKey == "__default__" ? 1.0 : 0.82;
                    [BarplotSegmentFillColor(slice.colorKey, 0, sliceAlpha) setFill];
                    NSRectFillUsingOperation(rlispstat::platform::macos::ToNSRect(slice.rect),
                                             NSCompositingOperationSourceOver);
                }
            }
            DrawBarplotSelectionLayer(r,
                                      bin.rows,
                                      selection,
                                      rowColors,
                                      self.model);
        }

        DrawBarplotSegmentBorder(r, self.model, true, true);

        if (!hasSplit && r.size.height > 14.0) {
            NSString *count = [NSString stringWithFormat:@"%lu", (unsigned long)bin.rows.size()];
            NSSize sz = [count sizeWithAttributes:smallAttrs];
            const auto selectionPlan = rlispstat::core::BuildBarplotSelectionSlicePlan(
                rlispstat::platform::macos::ToCoreRect(r), bin.rows, selection,
                rowColors, BarplotPaletteOrder(),
                SelectedColorForGroup(self.model->group));
            NSMutableDictionary *countAttrs = [smallAttrs mutableCopy];
            [countAttrs setObject:BarplotValueTextColor(selectionPlan,
                r.origin.y + 3.0 + sz.height / 2.0,
                rlispstat::core::BarplotSelectionDisplayShowsOverlay(
                    self.model->barplotSelectionDisplay))
                          forKey:NSForegroundColorAttributeName];
            [count drawAtPoint:NSMakePoint(r.origin.x + (r.size.width - sz.width) / 2.0, r.origin.y + 3.0)
                withAttributes:countAttrs];
        }

        if (self.model->barplotRowColorDisplay == "composition_strip") {
            NSRect stripRect = NSMakeRect(r.origin.x,
                                          pr.origin.y + pr.size.height + 2.0,
                                          r.size.width,
                                          4.0);
            std::vector<rlispstat::core::BarplotCompositionSlice> slices =
                rlispstat::core::BarplotHorizontalRowColorCompositionSlices(
                    rlispstat::platform::macos::ToCoreRect(stripRect),
                    bin.rows,
                    rowColors,
                    BarplotPaletteOrder());
            for (const rlispstat::core::BarplotCompositionSlice &slice : slices) {
                [RowColorCompositionColor(slice.colorKey, slice.colorKey == "__default__" ? 0.92 : 0.78) setFill];
                NSRectFillUsingOperation(rlispstat::platform::macos::ToNSRect(slice.rect),
                                         NSCompositingOperationSourceOver);
            }
            [(theme.coordinatedMarks ? theme.geomStroke : [NSColor colorWithCalibratedWhite:0.55 alpha:0.55]) setStroke];
            NSFrameRect(stripRect);
        }

    }

    double xLabelVerticalOffset = rlispstat::core::BarplotCategoryLabelVerticalOffset(
        self.model->barplotRowColorDisplay == "composition_strip");
    for (const rlispstat::core::BarplotCategoryLabelDrawItem &item :
         rlispstat::core::BuildBarplotCategoryLabelDrawPlan(
             layout,
             rlispstat::core::BarplotBinsForModel(self.model),
             BarplotXVariablesForModel(self.model),
             xLabelVerticalOffset)) {
        [ToNSString(item.label)
            drawInRect:rlispstat::platform::macos::ToNSRect(item.rect)
        withAttributes:centerAttrs];
    }

    if (!self.model->xLabel.empty()) {
        NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
        [style setAlignment:NSTextAlignmentCenter];
        NSDictionary *axisAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text,
            NSParagraphStyleAttributeName: style
        };
        [ToNSString(self.model->xLabel) drawInRect:[self xAxisLabelRect]
                                    withAttributes:axisAttrs];
    }
    if (!self.model->yLabel.empty()) {
        CGFloat yLabelX = hasSplit ? pr.origin.x - 30.0 : 12.0;
        [ToNSString(self.model->yLabel) drawAtPoint:NSMakePoint(yLabelX, pr.origin.y - 2.0) withAttributes:smallAttrs];
    }

    if (self.dragging) {
        std::optional<rlispstat::core::Rect> highlightRect = BarplotDragHighlightRect(
            layout,
            rlispstat::platform::macos::ToCorePoint(self.dragStart),
            rlispstat::platform::macos::ToCorePoint(self.dragCurrent));
        if (highlightRect.has_value()) {
            NSRect rr = rlispstat::platform::macos::ToNSRect(*highlightRect);
            [[theme.accent colorWithAlphaComponent:0.12] setFill];
            NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        }
    }

    if (theme.showPanelBorder) {
        NSBezierPath *border = [NSBezierPath bezierPathWithRect:NSInsetRect(pr, 0.5, 0.5)];
        [border setLineWidth:1.0];
        [theme.axis setStroke];
        [border stroke];
    }

    DrawColorLegend(self.model, [self bounds], theme);

}

- (void)mouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    if (HandleColorLegendMouseDown(self, self.model, event)) return;
    // The category-label hit areas intentionally have generous vertical
    // padding.  Test the axis title first so that a click on the displayed
    // variable name opens its chooser instead of selecting a category.
    if (NSPointInRect(point, [self xAxisLabelRect])) {
        [self showXVariableMenuAtPoint:point];
        return;
    }
    NSInteger categoryIndex = -1;
    size_t variableIndex = 0;
    std::string categoryValue;
    if ([self xCategoryComponentAtPoint:point barIndex:&categoryIndex variableIndex:&variableIndex value:&categoryValue]) {
        std::vector<int> matchingRows = [self rowsForXVariableIndex:variableIndex value:categoryValue];
        std::set<int> rows(matchingRows.begin(), matchingRows.end());
        int selectionVersion = 0;
        if (MergeSelection(self.model->group, rows, EffectiveSelectionMode(self.model, [event modifierFlags]), &selectionVersion)) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
        }
        [self setNeedsDisplay:YES];
        UpdatePanelOnMain();
        return;
    }
    if (NSPointInRect(point, [self splitVariableLabelRect])) {
        [self showSplitVariableMenuAtPoint:point];
        return;
    }
    std::vector<std::string> splitLevels;
    NSInteger splitLabelIndex = [self splitLevelLabelIndexAtPoint:point levels:&splitLevels];
    if (splitLabelIndex >= 0 && (size_t)splitLabelIndex < splitLevels.size()) {
        std::vector<int> levelRows = [self rowsForSplitLevel:splitLevels[(size_t)splitLabelIndex]];
        std::set<int> rows(levelRows.begin(), levelRows.end());
        int selectionVersion = 0;
        if (MergeSelection(self.model->group, rows, EffectiveSelectionMode(self.model, [event modifierFlags]), &selectionVersion)) {
            PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
        }
        [self setNeedsDisplay:YES];
        UpdatePanelOnMain();
        return;
    }
    self.dragging = YES;
    self.dragStart = point;
    self.dragCurrent = self.dragStart;
    [self setNeedsDisplay:YES];

    while (self.dragging) {
        NSEvent *trackingEvent = [[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                                                            untilDate:[NSDate distantFuture]
                                                               inMode:NSEventTrackingRunLoopMode
                                                              dequeue:YES];
        if (!trackingEvent) break;
        if ([trackingEvent type] == NSEventTypeLeftMouseDragged) {
            [self mouseDragged:trackingEvent];
        } else if ([trackingEvent type] == NSEventTypeLeftMouseUp) {
            [self finishDragWithEvent:trackingEvent];
            break;
        }
    }
}

- (void)mouseDragged:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    [self setNeedsDisplay:YES];
}

- (void)mouseUp:(NSEvent *)event
{
    [self finishDragWithEvent:event];
}

- (void)finishDragWithEvent:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!self.dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragging = NO;
    rlispstat::core::BarplotLayout layout = [self barplotLayout];
    std::optional<std::pair<size_t, size_t>> range = BarplotBarRangeForGesture(
        layout,
        rlispstat::platform::macos::ToCorePoint(self.dragStart),
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent));
    if (!range.has_value()) {
        if (self.model && NSPointInRect(self.dragCurrent, [self plotRect])) {
            std::set<int> rows;
            int selectionVersion = 0;
            if (MergeSelection(self.model->group, rows, EffectiveSelectionMode(self.model, [event modifierFlags]), &selectionVersion)) {
                PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(), selectionVersion);
                UpdatePanelOnMain();
            }
        }
        [self setNeedsDisplay:YES];
        return;
    }
    std::set<int> rows = rlispstat::core::BarplotRowsForGesture(
        layout,
        rlispstat::core::BarplotBinsForModel(self.model),
        [self splitLevelsForDisplay],
        !self.model->barplotSplitVariable.empty(),
        rlispstat::platform::macos::ToCorePoint(self.dragStart),
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent));
    int selectionVersion = 0;
    if (MergeSelection(self.model->group, rows, EffectiveSelectionMode(self.model, [event modifierFlags]), &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    UpdatePanelOnMain();
}

- (NSMenuItem *)menuItem:(NSString *)title command:(NSString *)command
{
    if (!g_commandTarget) g_commandTarget = [[CommandTarget alloc] init];
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:@""];
    [item setTarget:g_commandTarget];
    [item setRepresentedObject:command];
    return item;
}

- (NSMenuItem *)menuItemForOption:(const rlispstat::core::BarplotMenuOption &)option
{
    NSMenuItem *item = nil;
    if (option.command.empty()) {
        item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""];
    } else {
        item = [self menuItem:ToNSString(option.title) command:ToNSString(option.command)];
    }
    [item setEnabled:option.enabled];
    [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
    return item;
}

- (NSMenu *)xAxisMenu
{
    std::vector<std::string> availableVariables = BarplotAvailableVariablesForModel(self.model);

    std::vector<std::string> currentX = BarplotXVariablesForModel(self.model);
    rlispstat::core::BarplotXMenuState menuState = rlispstat::core::BuildBarplotXMenuState(
        availableVariables,
        currentX,
        self.model->barplotSplitVariable);
    NSMenu *xMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    for (const rlispstat::core::BarplotMenuOption &option : menuState.setOptions) {
        [xMenu addItem:[self menuItemForOption:option]];
    }
    if (menuState.setOptions.empty()) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.emptyTitle) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [xMenu addItem:empty];
    }

    [xMenu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *addItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.addXVariableTitle) action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.addXVariableTitle)];
    for (const rlispstat::core::BarplotMenuOption &option : menuState.addOptions) {
        [addMenu addItem:[self menuItemForOption:option]];
    }
    if (menuState.addOptions.empty()) {
        NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.emptyTitle) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [addMenu addItem:empty];
    }
    [xMenu setSubmenu:addMenu forItem:addItem];
    [xMenu addItem:addItem];

    if (!menuState.replaceSections.empty()) {
        NSMenuItem *replaceOneItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.replaceOneXVariableTitle) action:nil keyEquivalent:@""];
        NSMenu *replaceOneMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.replaceOneXVariableTitle)];
        for (const rlispstat::core::BarplotReplaceXMenuSection &section : menuState.replaceSections) {
            NSMenuItem *oldItem = [[NSMenuItem alloc] initWithTitle:ToNSString(section.variable) action:nil keyEquivalent:@""];
            NSMenu *oldMenu = [[NSMenu alloc] initWithTitle:ToNSString(section.variable)];
            for (const rlispstat::core::BarplotMenuOption &option : section.options) {
                [oldMenu addItem:[self menuItemForOption:option]];
            }
            if (section.options.empty()) {
                NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.emptyTitle) action:nil keyEquivalent:@""];
                [empty setEnabled:NO];
                [oldMenu addItem:empty];
            }
            [replaceOneMenu setSubmenu:oldMenu forItem:oldItem];
            [replaceOneMenu addItem:oldItem];
        }
        [xMenu setSubmenu:replaceOneMenu forItem:replaceOneItem];
        [xMenu addItem:replaceOneItem];
    }

    if (!menuState.removeOptions.empty()) {
        NSMenuItem *removeItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.removeXVariableTitle) action:nil keyEquivalent:@""];
        NSMenu *removeMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.removeXVariableTitle)];
        for (const rlispstat::core::BarplotMenuOption &option : menuState.removeOptions) {
            [removeMenu addItem:[self menuItemForOption:option]];
        }
        [xMenu setSubmenu:removeMenu forItem:removeItem];
        [xMenu addItem:removeItem];
    }
    return xMenu;
}

- (NSMenu *)splitVariableMenu
{
    const rlispstat::core::BarplotSplitMenuState menuState =
        rlispstat::core::BuildBarplotSplitMenuState(
            BarplotAvailableVariablesForModel(self.model),
            BarplotXVariablesForModel(self.model),
            self.model ? self.model->barplotSplitVariable : std::string{});
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    [menu addItem:[self menuItemForOption:menuState.noneOption]];
    [menu addItem:[NSMenuItem separatorItem]];
    for (const rlispstat::core::BarplotMenuOption &option : menuState.splitOptions)
        [menu addItem:[self menuItemForOption:option]];
    if (menuState.splitOptions.empty()) {
        NSMenuItem *empty = [[NSMenuItem alloc]
            initWithTitle:ToNSString(menuState.emptyTitle) action:nil keyEquivalent:@""];
        [empty setEnabled:NO];
        [menu addItem:empty];
    }
    return menu;
}

- (NSRect)splitVariableLabelRect
{
    if (!self.model || self.model->barplotSplitVariable.empty()) return NSZeroRect;
    const std::vector<std::string> levels = [self splitLevelsForDisplay];
    const auto plan = rlispstat::core::BuildBarplotSideLabelDrawPlan(
        rlispstat::platform::macos::ToCoreRect([self plotRect]),
        self.model->barplotSplitVariable,
        levels,
        [self splitLevelTotalsForLevels:levels],
        self.model->barplotRowColorDisplay == "composition_strip");
    return rlispstat::platform::macos::ToNSRect(plan.splitTitleRect);
}

- (void)showSplitVariableMenuAtPoint:(NSPoint)point
{
    [[self splitVariableMenu] popUpMenuPositioningItem:nil atLocation:point inView:self];
}

- (void)showXVariableMenuAtPoint:(NSPoint)point
{
    [[self xAxisMenu] popUpMenuPositioningItem:nil atLocation:point inView:self];
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    const rlispstat::core::PlotContextMenuTitles contextTitles = rlispstat::core::DefaultPlotContextMenuTitles();
    std::vector<std::string> currentXVariables = BarplotXVariablesForModel(self.model);
    rlispstat::core::BarplotDisplayMenuState displayMenuState =
        rlispstat::core::BuildBarplotDisplayMenuState(
            self.model->barplotMode,
            self.model->barplotWidthMode,
            self.model->barplotSplitVariable,
            self.model->barplotRowColorDisplay,
            self.model->barplotShowConditionalPercent,
            self.model->barplotSplitStrokeWidth,
            self.model->barplotSegmentEncodingMode,
            self.model->barplotShowPatterns,
            self.model->barplotSelectionDisplay,
            currentXVariables);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(displayMenuState.title)];

    NSPoint point = [self convertPoint:[event locationInWindow] fromView:nil];
    NSInteger hitBar = -1;
    NSInteger hitSegment = -1;
    const bool hasHitSegment = [self segmentHitAtPoint:point
                                              barIndex:&hitBar
                                          segmentIndex:&hitSegment
                                           segmentRect:nullptr];

    if (kShowExperimentalFeatures) {
      // Experimental submenu
      NSMenuItem *experimentalItem = [[NSMenuItem alloc] initWithTitle:@"Experimental" action:nil keyEquivalent:@""];
      NSMenu *experimentalMenu = [[NSMenu alloc] initWithTitle:@"Experimental"];

    if (hasHitSegment) {
        std::string title = "Segment";
        std::optional<rlispstat::core::BarplotSegmentReference> reference =
            BarplotCoreSegmentReferenceForIndices(self.model, (int)hitBar, (int)hitSegment);
        if (reference.has_value()) {
            title = rlispstat::core::BarplotSegmentMenuTitle(
                self.model->xLabel,
                self.model->barplotSplitVariable,
                *reference);
        }
        NSMenuItem *segmentItem = [[NSMenuItem alloc] initWithTitle:ToNSString(title) action:nil keyEquivalent:@""];
        [experimentalMenu setSubmenu:[self segmentMenuForBarIndex:hitBar segmentIndex:hitSegment] forItem:segmentItem];
        [experimentalMenu addItem:segmentItem];
        [experimentalMenu addItem:[NSMenuItem separatorItem]];
    }

    // Row Colors
    NSMenuItem *rowColorItem = [[NSMenuItem alloc] initWithTitle:ToNSString(displayMenuState.rowColorsTitle) action:nil keyEquivalent:@""];
    NSMenu *rowColorMenu = [[NSMenu alloc] initWithTitle:ToNSString(displayMenuState.rowColorsTitle)];
    for (const rlispstat::core::BarplotMenuOption &option : displayMenuState.rowColorOptions) {
        [rowColorMenu addItem:[self menuItemForOption:option]];
    }
    [experimentalMenu setSubmenu:rowColorMenu forItem:rowColorItem];
    [experimentalMenu addItem:rowColorItem];

    // Selection Display
    NSMenuItem *selectionDisplayItem = [[NSMenuItem alloc] initWithTitle:ToNSString(displayMenuState.selectionDisplayTitle) action:nil keyEquivalent:@""];
    NSMenu *selectionDisplayMenu = [[NSMenu alloc] initWithTitle:ToNSString(displayMenuState.selectionDisplayTitle)];
    for (const rlispstat::core::BarplotMenuOption &option : displayMenuState.selectionDisplayOptions) {
        [selectionDisplayMenu addItem:[self menuItemForOption:option]];
    }
    [experimentalMenu setSubmenu:selectionDisplayMenu forItem:selectionDisplayItem];
    [experimentalMenu addItem:selectionDisplayItem];

    // Split Style
    [experimentalMenu addItem:[self menuItemForOption:displayMenuState.splitStyle]];

    // Color Selected Rows
    [experimentalMenu addItem:ColorSelectedPointsSubmenuItem(ToNSString(contextTitles.colorSelectedRows))];

    // Open Color Palette
    [experimentalMenu addItem:[self menuItem:ToNSString(contextTitles.openColorPalette) command:@"OPEN_COLOR_PALETTE"]];

      [menu setSubmenu:experimentalMenu forItem:experimentalItem];
      [menu addItem:experimentalItem];
    }

    // Bar Chart submenu
    NSMenuItem *barChart = [[NSMenuItem alloc] initWithTitle:ToNSString(displayMenuState.title) action:nil keyEquivalent:@""];
    NSMenu *barMenu = [[NSMenu alloc] initWithTitle:ToNSString(displayMenuState.title)];
    NSMenu *xAxisMenu = [self xAxisMenu];
    NSMenuItem *xAxisItem = [[NSMenuItem alloc] initWithTitle:[xAxisMenu title] action:nil keyEquivalent:@""];
    [barMenu setSubmenu:xAxisMenu forItem:xAxisItem];
    [barMenu addItem:xAxisItem];
    NSMenu *splitMenu = [self splitVariableMenu];
    NSMenuItem *splitItem = [[NSMenuItem alloc]
        initWithTitle:[splitMenu title] action:nil keyEquivalent:@""];
    [barMenu setSubmenu:splitMenu forItem:splitItem];
    [barMenu addItem:splitItem];
    if (NSMenuItem *colorItem = ColorByVariableMenuItem(self.model))
        [barMenu addItem:colorItem];
    if (NSMenuItem *legendItem = ColorLegendMenuItem(self.model))
        [barMenu addItem:legendItem];
    if (NSMenuItem *conditionItem = ConditioningVariablesMenuItem(self.model))
        [barMenu addItem:conditionItem];
    NSMenuItem *scaleItem = [[NSMenuItem alloc] initWithTitle:ToNSString(displayMenuState.yAxisTitle) action:nil keyEquivalent:@""];
    NSMenu *scaleMenu = [[NSMenu alloc] initWithTitle:ToNSString(displayMenuState.yAxisTitle)];
    for (const rlispstat::core::BarplotMenuOption &option : displayMenuState.modeOptions) {
        [scaleMenu addItem:[self menuItemForOption:option]];
    }
    [barMenu setSubmenu:scaleMenu forItem:scaleItem];
    [barMenu addItem:scaleItem];
    NSMenuItem *widthItem = [[NSMenuItem alloc] initWithTitle:ToNSString(displayMenuState.barWidthTitle) action:nil keyEquivalent:@""];
    NSMenu *widthMenu = [[NSMenu alloc] initWithTitle:ToNSString(displayMenuState.barWidthTitle)];
    for (const rlispstat::core::BarplotMenuOption &option : displayMenuState.widthOptions) {
        [widthMenu addItem:[self menuItemForOption:option]];
    }
    [barMenu setSubmenu:widthMenu forItem:widthItem];
    [barMenu addItem:widthItem];
    NSMenuItem *percentages = [self menuItemForOption:displayMenuState.conditionalPercent];
    [barMenu addItem:percentages];
    NSMenuItem *splitBorderWidth = [self menuItemForOption:displayMenuState.splitStrokeWidth];
    [barMenu addItem:splitBorderWidth];

    [menu setSubmenu:barMenu forItem:barChart];
    [menu addItem:barChart];

    NSMenuItem *analysis = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.analyzeThisBarChart) action:nil keyEquivalent:@""];
    NSMenu *analysisMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.analyzeThisBarChart)];
    [analysisMenu addItem:[self menuItemForOption:displayMenuState.analysis]];
    [analysisMenu addItem:[NSMenuItem separatorItem]];
    [analysisMenu addItem:[self menuItemForOption:displayMenuState.nestedAnalysis]];
    [menu setSubmenu:analysisMenu forItem:analysis];
    [menu addItem:analysis];

    NSMenuItem *selection = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.selection) action:nil keyEquivalent:@""];
    NSMenu *selectionMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.selection)];
    for (const rlispstat::core::BarplotMenuOption &option : displayMenuState.selectionOptions) {
        [selectionMenu addItem:[self menuItemForOption:option]];
    }
    [selectionMenu addItem:ColorSelectedPointsSubmenuItem(ToNSString(contextTitles.colorSelectedRows))];
    [selectionMenu addItem:[self menuItem:ToNSString(contextTitles.openColorPalette) command:@"OPEN_COLOR_PALETTE"]];
    [selectionMenu addItem:[NSMenuItem separatorItem]];
    [selectionMenu addItem:AddDataColumnSubmenuItem()];
    [menu setSubmenu:selectionMenu forItem:selection];
    [menu addItem:selection];
    std::vector<int> clickedRows;
    std::string clickedDescription;
    std::string clickedElement;
    if (hitBar >= 0 && static_cast<std::size_t>(hitBar) < self.model->barplotBins.size()) {
        const BarplotBin &bin = self.model->barplotBins[static_cast<std::size_t>(hitBar)];
        clickedRows = bin.rows;
        clickedDescription = "Bar " + bin.category;
        clickedElement = bin.category;
        if (hitSegment >= 0 && static_cast<std::size_t>(hitSegment) < bin.segments.size()) {
            const BarplotSegment &segment = bin.segments[static_cast<std::size_t>(hitSegment)];
            clickedRows = segment.rows;
            clickedDescription = "Bar segment " + bin.category + " / " + segment.level;
            clickedElement += "/" + segment.level;
        }
    }
    [menu addItem:AnalysisScopeSubmenuItemForPlot(
        self.model, clickedRows, "bar_segment", clickedDescription, clickedElement)];

    // Export submenu
    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.exportMenu) action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.exportMenu)];
    AddStandardPlotExportItems(exportMenu, NO);
    if (self.model && !self.model->codeReference.provenance.verificationRCode.empty())
        AddRCodeExportItems(exportMenu, "output", self.model->id, false);
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    AddSnapshotAlbumContextItems(menu);

    // View submenu
    NSMenuItem *viewItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.view) action:nil keyEquivalent:@""];
    NSMenu *viewMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.view)];
    if (NSMenuItem *imputation = ImputationDisplaySubmenuItemForPlot(self.model)) {
        [viewMenu addItem:imputation];
        [viewMenu addItem:[NSMenuItem separatorItem]];
    }
    AddPlotThemeSubmenu(viewMenu, self);
    [menu setSubmenu:viewMenu forItem:viewItem];
    [menu addItem:viewItem];

    // Plot submenu (new plot creation only)
    NSMenuItem *plot = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.plot) action:nil keyEquivalent:@""];
    NSMenu *plotMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.plot)];
    for (const rlispstat::core::BarplotMenuOption &option : displayMenuState.plotOptions) {
        [plotMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:plotMenu forItem:plot];
    [menu addItem:plot];

    return FinalizeGraphContextMenu(menu);
}

- (void)rightMouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    [NSMenu popUpContextMenu:[self menuForEvent:event] withEvent:event forView:self];
}

- (BOOL)savePNGToPath:(NSString *)path
{
    NSBitmapImageRep *rep = [self bitmapImageRepForCachingDisplayInRect:[self bounds]];
    [self cacheDisplayInRect:[self bounds] toBitmapImageRep:rep];
    NSData *data = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    return [data writeToFile:path atomically:YES];
}

- (BOOL)savePDFToPath:(NSString *)path
{
    NSData *data = [self dataWithPDFInsideRect:[self bounds]];
    return [data writeToFile:path atomically:YES];
}
@end

static NSBezierPath *PathForCorePoints(const std::vector<rlispstat::core::Point> &points, BOOL closePath)
{
    NSBezierPath *path = [NSBezierPath bezierPath];
    bool started = false;
    for (const rlispstat::core::Point &point : points) {
        if (!std::isfinite(point.x) || !std::isfinite(point.y)) {
            continue;
        }
        NSPoint p = rlispstat::platform::macos::ToNSPoint(point);
        if (!started) {
            [path moveToPoint:p];
            started = true;
        } else {
            [path lineToPoint:p];
        }
    }
    if (started && closePath) {
        [path closePath];
    }
    return path;
}

