static NSRect WindowStickyReferenceRect(NSView *primaryView)
{
    if (!primaryView) return NSZeroRect;
    if ([primaryView conformsToProtocol:@protocol(WindowStickyReferenceProvider)]) {
        NSValue *value = [(id<WindowStickyReferenceProvider>)primaryView
            stickyReferenceRectValue];
        if (value) return [value rectValue];
    }
    if ([primaryView isKindOfClass:[ScatterView class]]) {
        ScatterView *scatter = (ScatterView *)primaryView;
        const std::string kind = scatter.model ? scatter.model->kind : std::string{};
        if (kind != "trellis_scatterplot" && kind != "scatter_matrix" &&
            kind != "pca_scree" && kind != "pca_biplot") {
            return [scatter plotRect];
        }
    }
    if ([primaryView isKindOfClass:[HistogramView class]])
        return [(HistogramView *)primaryView plotRect];
    if ([primaryView isKindOfClass:[BoxplotView class]])
        return [(BoxplotView *)primaryView plotRect];
    if ([primaryView isKindOfClass:[BarplotView class]])
        return [(BarplotView *)primaryView plotRect];
    return [primaryView bounds];
}

@implementation WindowNoteExportView {
    NSImage *_primaryImage;
    NSString *_noteText;
    CGFloat _primaryHeight;
}

- (instancetype)initWithPrimaryImage:(NSImage *)image noteText:(NSString *)noteText
{
    if (!image || !noteText) return nil;
    const CGFloat width = std::max((CGFloat)320.0, [image size].width);
    NSDictionary *attributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12.0],
        NSForegroundColorAttributeName: [NSColor blackColor]
    };
    NSRect measured = [noteText boundingRectWithSize:NSMakeSize(width - 48.0, CGFLOAT_MAX)
        options:(NSStringDrawingUsesLineFragmentOrigin | NSStringDrawingUsesFontLeading)
        attributes:attributes];
    const CGFloat noteHeight = std::max((CGFloat)84.0, std::ceil(measured.size.height) + 62.0);
    self = [super initWithFrame:NSMakeRect(0, 0, width, [image size].height + noteHeight)];
    if (!self) return nil;
    _primaryImage = image;
    _noteText = [noteText copy];
    _primaryHeight = [image size].height;
    return self;
}

- (BOOL)isFlipped { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor whiteColor] setFill];
    NSRectFill([self bounds]);
    [_primaryImage drawInRect:NSMakeRect(0, 0, NSWidth([self bounds]), _primaryHeight)
                     fromRect:NSZeroRect
                    operation:NSCompositingOperationSourceOver
                     fraction:1.0
               respectFlipped:YES
                        hints:nil];
    const CGFloat top = _primaryHeight + 20.0;
    [@"Notes" drawAtPoint:NSMakePoint(24.0, top)
            withAttributes:@{
                NSFontAttributeName: [NSFont systemFontOfSize:13.0 weight:NSFontWeightSemibold],
                NSForegroundColorAttributeName: [NSColor blackColor]
            }];
    [_noteText drawInRect:NSMakeRect(24.0, top + 26.0, NSWidth([self bounds]) - 48.0,
                                     NSHeight([self bounds]) - top - 34.0)
              withAttributes:@{
                  NSFontAttributeName: [NSFont systemFontOfSize:12.0],
                  NSForegroundColorAttributeName: [NSColor blackColor]
              }];
}
@end

static NSColor *StickyNoteColor(rlispstat::core::StickyNoteColor color)
{
    using rlispstat::core::StickyNoteColor;
    switch (color) {
    case StickyNoteColor::Pink:   return [NSColor colorWithSRGBRed:1.00 green:0.72 blue:0.84 alpha:1.0];
    case StickyNoteColor::Blue:   return [NSColor colorWithSRGBRed:0.72 green:0.87 blue:0.98 alpha:1.0];
    case StickyNoteColor::Green:  return [NSColor colorWithSRGBRed:0.78 green:0.94 blue:0.70 alpha:1.0];
    case StickyNoteColor::Orange: return [NSColor colorWithSRGBRed:1.00 green:0.81 blue:0.60 alpha:1.0];
    case StickyNoteColor::Yellow: return [NSColor colorWithSRGBRed:1.00 green:0.94 blue:0.56 alpha:1.0];
    }
    return [NSColor yellowColor];
}

static NSString *StickyNoteColorName(rlispstat::core::StickyNoteColor color)
{
    using rlispstat::core::StickyNoteColor;
    switch (color) {
    case StickyNoteColor::Pink: return @"Pink";
    case StickyNoteColor::Blue: return @"Blue";
    case StickyNoteColor::Green: return @"Green";
    case StickyNoteColor::Orange: return @"Orange";
    case StickyNoteColor::Yellow: return @"Yellow";
    }
    return @"Yellow";
}

