- (instancetype)initWithStickyNote:(WindowStickyNoteView *)sticky
                              canvas:(WindowStickyCanvasView *)canvas
{
    self = [super initWithFrame:NSMakeRect(0, 0, 16.0, 16.0)];
    if (!self) return nil;
    _sticky = sticky;
    _canvas = canvas;
    [self setAccessibilityLabel:@"Sticker pointer target"];
    [self setToolTip:@"Drag to point at an item in the window"];
    return self;
}

- (BOOL)isFlipped { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor colorWithCalibratedWhite:0.20 alpha:0.90] setFill];
    [[NSBezierPath bezierPathWithOvalInRect:NSInsetRect([self bounds], 3.0, 3.0)] fill];
    [[NSColor whiteColor] setStroke];
    NSBezierPath *ring = [NSBezierPath bezierPathWithOvalInRect:NSInsetRect([self bounds], 5.0, 5.0)];
    [ring setLineWidth:1.0];
    [ring stroke];
}

- (void)mouseDragged:(NSEvent *)event
{
    if (!_canvas || !_sticky) return;
    NSPoint point = [_canvas convertPoint:[event locationInWindow] fromView:nil];
    point.x = std::max((CGFloat)8.0, std::min(point.x, NSWidth([_canvas bounds]) - 8.0));
    point.y = std::max((CGFloat)8.0, std::min(point.y, NSHeight([_canvas bounds]) - 8.0));
    [_sticky moveAnchorToCanvasPoint:point];
}
@end

@implementation WindowStickyResizeHandleView {
    WindowStickyNoteView *_sticky;
    WindowStickyCanvasView *_canvas;
}

- (instancetype)initWithStickyNote:(WindowStickyNoteView *)sticky
                              canvas:(WindowStickyCanvasView *)canvas
{
    self = [super initWithFrame:NSMakeRect(0, 0, 18.0, 18.0)];
    if (!self) return nil;
    _sticky = sticky;
    _canvas = canvas;
    [self setAccessibilityLabel:@"Resize Sticker"];
    [self setToolTip:@"Drag to resize the Sticker"];
    return self;
}

- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)event { (void)event; return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor colorWithCalibratedWhite:0.22 alpha:0.55] setStroke];
    for (CGFloat offset : {4.0, 8.0, 12.0}) {
        NSBezierPath *grip = [NSBezierPath bezierPath];
        [grip moveToPoint:NSMakePoint(NSWidth([self bounds]) - offset, NSHeight([self bounds]) - 2.0)];
        [grip lineToPoint:NSMakePoint(NSWidth([self bounds]) - 2.0, NSHeight([self bounds]) - offset)];
        [grip setLineWidth:1.2];
        [grip stroke];
    }
}

- (void)mouseDown:(NSEvent *)event
{
    (void)event;
    [_canvas activateStickyForHitView:self];
    [_sticky setActive:YES];
}

- (void)mouseDragged:(NSEvent *)event
{
    NSPoint point = [_canvas convertPoint:[event locationInWindow] fromView:nil];
    [_sticky resizeToCanvasPoint:point];
}
@end

@implementation WindowStickyNoteView {
    rlispstat::core::WindowStickyNote _state;
    WindowStickyCanvasView *_canvas;
    NSScrollView *_scroll;
    NSTextView *_textView;
    NSButton *_colorButton;
    NSButton *_collapseButton;
    NSButton *_closeButton;
    WindowStickyAnchorView *_anchorView;
    WindowStickyResizeHandleView *_resizeHandle;
    BOOL _dragging;
    NSPoint _dragStart;
    NSPoint _frameStart;
}

- (instancetype)initWithState:(const rlispstat::core::WindowStickyNote &)state
                        canvas:(WindowStickyCanvasView *)canvas
{
    self = [super initWithFrame:NSMakeRect(state.x, state.y, state.width, state.height)];
    if (!self) return nil;
    _state = state;
    _canvas = canvas;
    [self setWantsLayer:YES];
    self.layer.cornerRadius = 5.0;
    self.layer.shadowColor = [[NSColor blackColor] CGColor];
    self.layer.shadowOpacity = 0.22;
    self.layer.shadowRadius = 4.0;
    self.layer.shadowOffset = CGSizeMake(0.0, -2.0);
    [self setAccessibilityLabel:@"Sticker note"];

    _scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(8.0, 26.0,
        state.width - 16.0, state.height - 34.0)];
    [_scroll setBorderType:NSNoBorder];
    [_scroll setHasVerticalScroller:YES];
    [_scroll setAutohidesScrollers:YES];
    [_scroll setDrawsBackground:NO];
    [_scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    const NSSize editorSize = [_scroll contentSize];
    _textView = [[NSTextView alloc] initWithFrame:NSMakeRect(
        0.0, 0.0, editorSize.width, editorSize.height)];
    [_textView setRichText:NO];
    [_textView setAllowsUndo:YES];
    [_textView setHorizontallyResizable:NO];
    [_textView setVerticallyResizable:YES];
    [_textView setMinSize:NSMakeSize(0.0, editorSize.height)];
    [_textView setMaxSize:NSMakeSize(CGFLOAT_MAX, CGFLOAT_MAX)];
    [_textView setAutoresizingMask:NSViewWidthSizable];
    [_textView setTextContainerInset:NSMakeSize(6.0, 5.0)];
    [_textView setFont:[NSFont systemFontOfSize:13.0]];
    [_textView setTextColor:[NSColor colorWithCalibratedWhite:0.10 alpha:1.0]];
    [_textView setDrawsBackground:YES];
    [_textView setString:ToNSString(state.plain_text)];
    [_textView setDelegate:self];
    [_textView setAccessibilityLabel:@"Sticker text"];
    [[_textView textContainer] setContainerSize:NSMakeSize(editorSize.width, CGFLOAT_MAX)];
    [[_textView textContainer] setWidthTracksTextView:YES];
    [[_textView textContainer] setLineFragmentPadding:0.0];
    [_scroll setDocumentView:_textView];
    [self addSubview:_scroll];

    _colorButton = [NSButton buttonWithTitle:@"●" target:self action:@selector(showColorMenu:)];
    [_colorButton setFrame:NSMakeRect(state.width - 49.0, 2.0, 21.0, 20.0)];
    [_colorButton setBezelStyle:NSBezelStyleInline];
    [_colorButton setAutoresizingMask:NSViewMinXMargin | NSViewMaxYMargin];
    [_colorButton setAccessibilityLabel:@"Sticker color"];
    [self addSubview:_colorButton];

    _collapseButton = [NSButton buttonWithTitle:@"−" target:self action:@selector(toggleCollapsed:)];
    [_collapseButton setFrame:NSMakeRect(state.width - 73.0, 2.0, 21.0, 20.0)];
    [_collapseButton setBezelStyle:NSBezelStyleInline];
    [_collapseButton setAutoresizingMask:NSViewMinXMargin | NSViewMaxYMargin];
    [_collapseButton setAccessibilityLabel:@"Collapse Sticker"];
    [_collapseButton setToolTip:@"Collapse this note to a marker"];
    [self addSubview:_collapseButton];

    _closeButton = [NSButton buttonWithTitle:@"×" target:self action:@selector(closeSticky:)];
    [_closeButton setFrame:NSMakeRect(state.width - 25.0, 2.0, 21.0, 20.0)];
    [_closeButton setBezelStyle:NSBezelStyleInline];
    [_closeButton setAutoresizingMask:NSViewMinXMargin | NSViewMaxYMargin];
    [_closeButton setAccessibilityLabel:@"Delete Sticker"];
    [self addSubview:_closeButton];
    _resizeHandle = [[WindowStickyResizeHandleView alloc] initWithStickyNote:self canvas:canvas];
    [_resizeHandle setFrameOrigin:NSMakePoint(state.width - 18.0, state.height - 18.0)];
    [_resizeHandle setAutoresizingMask:NSViewMinXMargin | NSViewMinYMargin];
    [self addSubview:_resizeHandle];
    [self applyColor];
    [self setActive:NO];
    [self applyCollapsedState];
    return self;
}

- (BOOL)isFlipped { return YES; }

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    NSColor *color = StickyNoteColor(_state.color);
    [color setFill];
    [[NSBezierPath bezierPathWithRoundedRect:[self bounds] xRadius:5.0 yRadius:5.0] fill];
    if (_state.collapsed) {
        [[NSColor colorWithCalibratedWhite:0.15 alpha:0.72] setStroke];
        NSBezierPath *border = [NSBezierPath bezierPathWithRoundedRect:
            NSInsetRect([self bounds], 0.75, 0.75) xRadius:6.0 yRadius:6.0];
        [border setLineWidth:1.5];
        [border stroke];
        NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
        [style setAlignment:NSTextAlignmentCenter];
        [@"…" drawInRect:NSInsetRect([self bounds], 4.0, 2.0) withAttributes:@{
            NSFontAttributeName: [NSFont systemFontOfSize:17.0 weight:NSFontWeightBold],
            NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.16 alpha:0.90],
            NSParagraphStyleAttributeName: style
        }];
        [style release];
        return;
    }
    [[[NSColor blackColor] colorWithAlphaComponent:0.07] setFill];
    NSRectFill(NSMakeRect(0.0, 0.0, NSWidth([self bounds]), 24.0));
    [[NSColor colorWithCalibratedWhite:0.25 alpha:0.30] setStroke];
    NSBezierPath *border = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect([self bounds], 0.5, 0.5)
                                                           xRadius:5.0 yRadius:5.0];
    [border setLineWidth:1.0];
    [border stroke];
}

- (void)applyCollapsedState
{
    const BOOL collapsed = _state.collapsed;
    [_scroll setHidden:collapsed];
    [_colorButton setHidden:collapsed];
    [_collapseButton setHidden:collapsed];
    [_closeButton setHidden:collapsed];
    [_resizeHandle setHidden:collapsed];
    [self setFrameSize:collapsed ? NSMakeSize(32.0, 28.0)
                                 : NSMakeSize(_state.width, _state.height)];
    [self setAccessibilityLabel:collapsed ? @"Collapsed Sticker; click to expand"
                                          : @"Sticker note"];
    [self setToolTip:collapsed ? @"Click to expand this note" : nil];
    [self setNeedsDisplay:YES];
    [_canvas setNeedsDisplay:YES];
}

- (void)toggleCollapsed:(id)sender
{
    (void)sender;
    rlispstat::core::SetWindowStickyNoteCollapsed(_state, !_state.collapsed);
    [self applyCollapsedState];
    [_canvas stickyNoteDidChange:self];
}

- (void)applyColor
{
    NSColor *color = StickyNoteColor(_state.color);
    [_textView setBackgroundColor:color];
    NSMutableAttributedString *dot = [[NSMutableAttributedString alloc] initWithString:@"●"];
    [dot addAttribute:NSForegroundColorAttributeName value:color range:NSMakeRange(0, 1)];
    [_colorButton setAttributedTitle:dot];
    [_colorButton setToolTip:[NSString stringWithFormat:@"Sticker color: %@", StickyNoteColorName(_state.color)]];
    [self setNeedsDisplay:YES];
}

- (void)showColorMenu:(id)sender
{
    (void)sender;
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Sticker color"];
    const std::array<rlispstat::core::StickyNoteColor, 5> colors = {
        rlispstat::core::StickyNoteColor::Yellow, rlispstat::core::StickyNoteColor::Pink,
        rlispstat::core::StickyNoteColor::Blue, rlispstat::core::StickyNoteColor::Green,
        rlispstat::core::StickyNoteColor::Orange
    };
    for (auto color : colors) {
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:StickyNoteColorName(color)
                                                     action:@selector(colorSelected:)
                                              keyEquivalent:@""];
        [item setTarget:self];
        [item setTag:(NSInteger)color];
        [item setState:color == _state.color ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    [menu popUpMenuPositioningItem:nil atLocation:NSMakePoint(0.0, NSHeight([_colorButton bounds]))
                            inView:_colorButton];
}

- (void)colorSelected:(id)sender
{
    [_canvas activateStickyForHitView:self];
    auto color = (rlispstat::core::StickyNoteColor)[sender tag];
    rlispstat::core::SetWindowStickyNoteColor(_state, color);
    [self applyColor];
    [_canvas stickyNoteDidChange:self];
}

- (void)closeSticky:(id)sender
{
    (void)sender;
    [_canvas removeStickyNote:self];
}

- (void)mouseDown:(NSEvent *)event
{
    if (_state.collapsed) {
        [self toggleCollapsed:nil];
        [_canvas activateStickyForHitView:self];
        return;
    }
    NSPoint local = [self convertPoint:[event locationInWindow] fromView:nil];
    _dragging = local.y <= 28.0;
    if (_dragging) {
        [_canvas activateStickyForHitView:self];
        _dragStart = [_canvas convertPoint:[event locationInWindow] fromView:nil];
        _frameStart = [self frame].origin;
        [_canvas addSubview:self positioned:NSWindowAbove relativeTo:nil];
    } else {
        [super mouseDown:event];
    }
}

- (void)mouseDragged:(NSEvent *)event
{
    if (!_dragging || !_canvas) return;
    NSPoint current = [_canvas convertPoint:[event locationInWindow] fromView:nil];
    NSPoint origin = NSMakePoint(_frameStart.x + current.x - _dragStart.x,
                                _frameStart.y + current.y - _dragStart.y);
    origin.x = std::max((CGFloat)0.0, std::min(origin.x, NSWidth([_canvas bounds]) - NSWidth([self frame])));
    origin.y = std::max((CGFloat)0.0, std::min(origin.y, NSHeight([_canvas bounds]) - NSHeight([self frame])));
    [self setFrameOrigin:origin];
    rlispstat::core::MoveWindowStickyNote(_state, origin.x, origin.y);
    [_canvas setNeedsDisplay:YES];
    [_canvas stickyNoteDidChange:self];
}

- (void)mouseUp:(NSEvent *)event
{
    (void)event;
    _dragging = NO;
}

- (void)textDidChange:(NSNotification *)notification
{
    (void)notification;
    rlispstat::core::SetWindowStickyNoteText(
        _state, std::string([[[_textView textStorage] string] UTF8String]));
    [_canvas stickyNoteDidChange:self];
}

- (void)textDidBeginEditing:(NSNotification *)notification
{
    (void)notification;
    [_canvas activateStickyForHitView:self];
}

- (rlispstat::core::WindowStickyNote)stateSnapshot { return _state; }
- (void)setAnchorView:(WindowStickyAnchorView *)anchorView { _anchorView = anchorView; }
- (WindowStickyAnchorView *)anchorView { return _anchorView; }

- (void)moveAnchorToCanvasPoint:(NSPoint)point
{
    rlispstat::core::MoveWindowStickyNoteAnchor(_state, point.x, point.y);
    [_anchorView setFrameOrigin:NSMakePoint(point.x - 8.0, point.y - 8.0)];
    [_canvas setNeedsDisplay:YES];
    [_canvas stickyNoteDidChange:self];
}

- (void)resizeToCanvasPoint:(NSPoint)point
{
    if (!_canvas || _state.collapsed) return;
    const NSPoint origin = [self frame].origin;
    const CGFloat width = std::max((CGFloat)160.0,
        std::min(point.x - origin.x, NSWidth([_canvas bounds]) - origin.x));
    const CGFloat height = std::max((CGFloat)110.0,
        std::min(point.y - origin.y, NSHeight([_canvas bounds]) - origin.y));
    [self setFrameSize:NSMakeSize(width, height)];
    [_resizeHandle setFrameOrigin:NSMakePoint(width - 18.0, height - 18.0)];
    rlispstat::core::ResizeWindowStickyNote(_state, width, height);
    [_canvas setNeedsDisplay:YES];
    [_canvas stickyNoteDidChange:self];
}

- (void)relayoutFromCanvasSize:(NSSize)oldSize
                  toCanvasSize:(NSSize)newSize
              oldReferenceRect:(NSRect)oldReferenceRect
              newReferenceRect:(NSRect)newReferenceRect
{
    const NSPoint oldAnchor = NSMakePoint(_state.anchor_x, _state.anchor_y);
    const BOOL anchorUsesReferenceRect =
        NSWidth(oldReferenceRect) > 0.0 && NSHeight(oldReferenceRect) > 0.0 &&
        NSWidth(newReferenceRect) > 0.0 && NSHeight(newReferenceRect) > 0.0 &&
        NSPointInRect(oldAnchor, NSInsetRect(oldReferenceRect, -1.0, -1.0));

    rlispstat::core::RelayoutWindowStickyNoteForCanvasResize(
        _state, oldSize.width, oldSize.height, newSize.width, newSize.height);
    if (anchorUsesReferenceRect) {
        const CGFloat relativeX = (oldAnchor.x - NSMinX(oldReferenceRect)) /
            NSWidth(oldReferenceRect);
        const CGFloat relativeY = (oldAnchor.y - NSMinY(oldReferenceRect)) /
            NSHeight(oldReferenceRect);
        _state.anchor_x = NSMinX(newReferenceRect) + relativeX * NSWidth(newReferenceRect);
        _state.anchor_y = NSMinY(newReferenceRect) + relativeY * NSHeight(newReferenceRect);
    }
    _state.anchor_x = std::max(8.0, std::min(_state.anchor_x, newSize.width - 8.0));
    _state.anchor_y = std::max(8.0, std::min(_state.anchor_y, newSize.height - 8.0));
    [self setFrameOrigin:NSMakePoint(_state.x, _state.y)];
    [self setFrameSize:_state.collapsed ? NSMakeSize(32.0, 28.0)
                                          : NSMakeSize(_state.width, _state.height)];
    [_anchorView setFrameOrigin:NSMakePoint(_state.anchor_x - 8.0,
                                            _state.anchor_y - 8.0)];
    if (NSWidth(newReferenceRect) > 0.0 && NSHeight(newReferenceRect) > 0.0) {
        rlispstat::core::SetWindowStickyNoteAnchorReferenceRect(
            _state, NSMinX(newReferenceRect), NSMinY(newReferenceRect),
            NSWidth(newReferenceRect), NSHeight(newReferenceRect));
    }
}

- (void)setActive:(BOOL)active
{
    self.layer.opacity = active ? 1.0f : 0.64f;
    [_anchorView setAlphaValue:active ? 1.0 : 0.55];
    [_resizeHandle setAlphaValue:active ? 1.0 : 0.55];
}

- (void)focusEditor
{
    [_canvas activateStickyForHitView:self];
    [[self window] makeFirstResponder:_textView];
}
@end

@implementation WindowStickyCanvasView {
    id<WindowStickyCanvasOwner> _owner;
    NSMutableArray<WindowStickyNoteView *> *_stickyNotes;
    NSRect _lastReferenceRect;
}

- (instancetype)initWithFrame:(NSRect)frame owner:(id<WindowStickyCanvasOwner>)owner
{
    self = [super initWithFrame:frame];
    if (!self) return nil;
    _owner = owner;
    _stickyNotes = [[NSMutableArray alloc] init];
    [self setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [self setAccessibilityLabel:@"Stickers"];
    return self;
}

- (void)viewDidMoveToSuperview
{
    [super viewDidMoveToSuperview];
    _lastReferenceRect = WindowStickyReferenceRect([self superview]);
}

- (void)setFrameSize:(NSSize)newSize
{
    const NSSize oldSize = [self frame].size;
    const NSRect oldReferenceRect = _lastReferenceRect;
    [super setFrameSize:newSize];
    const NSRect newReferenceRect = WindowStickyReferenceRect([self superview]);
    const BOOL changed = oldSize.width > 0.0 && oldSize.height > 0.0 &&
        (std::abs(oldSize.width - newSize.width) > 0.01 ||
         std::abs(oldSize.height - newSize.height) > 0.01);
    if (changed) {
        for (WindowStickyNoteView *sticky in _stickyNotes) {
            [sticky relayoutFromCanvasSize:oldSize
                              toCanvasSize:newSize
                          oldReferenceRect:oldReferenceRect
                          newReferenceRect:newReferenceRect];
        }
        [self setNeedsDisplay:YES];
        if ([_stickyNotes count]) [_owner stickyCanvasDidChange];
    }
    _lastReferenceRect = newReferenceRect;
}

- (void)addStickyWithState:(const rlispstat::core::WindowStickyNote &)state focus:(BOOL)focus
{
    const NSRect referenceRect = WindowStickyReferenceRect([self superview]);
    const auto fitted = rlispstat::core::WindowStickyNoteForCanvas(
        state, NSWidth([self bounds]), NSHeight([self bounds]),
        NSMinX(referenceRect), NSMinY(referenceRect),
        NSWidth(referenceRect), NSHeight(referenceRect));
    WindowStickyNoteView *sticky = [[WindowStickyNoteView alloc]
        initWithState:fitted canvas:self];
    WindowStickyAnchorView *anchor = [[WindowStickyAnchorView alloc]
        initWithStickyNote:sticky canvas:self];
    [anchor setFrameOrigin:NSMakePoint(fitted.anchor_x - 8.0, fitted.anchor_y - 8.0)];
    [sticky setAnchorView:anchor];
    [_stickyNotes addObject:sticky];
    [self addSubview:anchor];
    [self addSubview:sticky positioned:NSWindowAbove relativeTo:anchor];
    [self setNeedsDisplay:YES];
    if (focus) {
        [self activateStickyForHitView:sticky];
        [sticky focusEditor];
    }
}

- (void)loadStickyNotes:(const std::vector<rlispstat::core::WindowStickyNote> &)states
{
    NSArray<WindowStickyNoteView *> *existing = [_stickyNotes copy];
    for (WindowStickyNoteView *sticky in existing) {
        [[sticky anchorView] removeFromSuperview];
        [sticky removeFromSuperview];
    }
    [existing release];
    [_stickyNotes removeAllObjects];
    for (const rlispstat::core::WindowStickyNote &state : states)
        [self addStickyWithState:state focus:NO];
}

- (BOOL)isFlipped { return YES; }
- (BOOL)isOpaque { return NO; }

- (NSView *)hitTest:(NSPoint)point
{
    NSView *hit = [super hitTest:point];
    if (hit != self) return hit;
    auto distanceToSegment = [](NSPoint p, NSPoint a, NSPoint b) {
        const CGFloat dx = b.x - a.x;
        const CGFloat dy = b.y - a.y;
        const CGFloat lengthSquared = dx * dx + dy * dy;
        if (lengthSquared <= 0.01) return std::hypot(p.x - a.x, p.y - a.y);
        const CGFloat t = std::max((CGFloat)0.0, std::min((CGFloat)1.0,
            ((p.x - a.x) * dx + (p.y - a.y) * dy) / lengthSquared));
        return std::hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
    };
    for (WindowStickyNoteView *sticky in [_stickyNotes reverseObjectEnumerator]) {
        const auto state = [sticky stateSnapshot];
        const NSPoint start = NSMakePoint(NSMidX([sticky frame]), NSMidY([sticky frame]));
        const NSPoint end = NSMakePoint(state.anchor_x, state.anchor_y);
        if (distanceToSegment(point, start, end) <= 7.0) return [sticky anchorView];
    }
    return nil;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor colorWithCalibratedWhite:0.22 alpha:0.72] setStroke];
    for (WindowStickyNoteView *sticky in _stickyNotes) {
        rlispstat::core::WindowStickyNote state = [sticky stateSnapshot];
        NSPoint start = NSMakePoint(NSMidX([sticky frame]), NSMidY([sticky frame]));
        NSPoint end = NSMakePoint(state.anchor_x, state.anchor_y);
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:start];
        [line lineToPoint:end];
        [line setLineWidth:1.5];
        [line stroke];
    }
}

- (void)addStickyNote
{
    const NSUInteger index = [_stickyNotes count];
    const CGFloat width = 220.0;
    const CGFloat height = 160.0;
    const CGFloat x = std::max((CGFloat)10.0, NSWidth([self bounds]) - width - 18.0 - 22.0 * (index % 5));
    const CGFloat y = 18.0 + 22.0 * (index % 5);
    rlispstat::core::WindowStickyNote state = rlispstat::core::MakeWindowStickyNote(
        rlispstat::core::GenerateWindowStickyNoteId());
    rlispstat::core::MoveWindowStickyNote(state, x, y);
    rlispstat::core::MoveWindowStickyNoteAnchor(state,
        std::max((CGFloat)10.0, x - 54.0), std::min(NSHeight([self bounds]) - 10.0, y + height + 48.0));
    [self addStickyWithState:state focus:YES];
    [_owner stickyCanvasDidChange];
}

- (BOOL)hasContent
{
    for (WindowStickyNoteView *sticky in _stickyNotes)
        if ([sticky stateSnapshot].has_content) return YES;
    return NO;
}

- (NSUInteger)stickyNoteCount { return [_stickyNotes count]; }

- (std::vector<rlispstat::core::WindowStickyNote>)stateSnapshots
{
    std::vector<rlispstat::core::WindowStickyNote> states;
    states.reserve([_stickyNotes count]);
    for (WindowStickyNoteView *sticky in _stickyNotes) {
        auto state = [sticky stateSnapshot];
        rlispstat::core::SetWindowStickyNoteReferenceSize(
            state, NSWidth([self bounds]), NSHeight([self bounds]));
        const NSRect referenceRect = WindowStickyReferenceRect([self superview]);
        rlispstat::core::SetWindowStickyNoteAnchorReferenceRect(
            state, NSMinX(referenceRect), NSMinY(referenceRect),
            NSWidth(referenceRect), NSHeight(referenceRect));
        states.push_back(std::move(state));
    }
    return states;
}

- (void)stickyNoteDidChange:(WindowStickyNoteView *)sticky
{
    (void)sticky;
    [_owner stickyCanvasDidChange];
}

- (void)removeStickyNote:(WindowStickyNoteView *)sticky
{
    if (!sticky) return;
    if ([sticky stateSnapshot].has_content) {
        NSAlert *alert = [[NSAlert alloc] init];
        [alert setMessageText:@"Delete Sticker?"];
        [alert setInformativeText:@"This removes the text and pointer attached to this window."];
        [alert addButtonWithTitle:@"Delete"];
        [alert addButtonWithTitle:@"Cancel"];
        if ([alert runModal] != NSAlertFirstButtonReturn) return;
    }
    [[sticky anchorView] removeFromSuperview];
    [sticky removeFromSuperview];
    [_stickyNotes removeObject:sticky];
    [self setNeedsDisplay:YES];
    [_owner stickyCanvasDidChange];
}

- (void)activateStickyForHitView:(NSView *)hitView
{
    WindowStickyNoteView *active = nil;
    for (WindowStickyNoteView *sticky in _stickyNotes) {
        if (hitView == [sticky anchorView]) {
            active = sticky;
            break;
        }
        for (NSView *candidate = hitView; candidate && candidate != self;
             candidate = [candidate superview]) {
            if (candidate == sticky) {
                active = sticky;
                break;
            }
        }
        if (active) break;
    }
    for (WindowStickyNoteView *sticky in _stickyNotes) [sticky setActive:sticky == active];
}

- (void)deactivateAllStickyNotes
{
    for (WindowStickyNoteView *sticky in _stickyNotes) [sticky setActive:NO];
}
@end

@implementation WindowNotesContainer {
    rlispstat::core::WindowNote _note;
    NSView *_primaryView;
    NSString *_contextName;
    NSView *_notesPanel;
    NSTextView *_textView;
    WindowStickyCanvasView *_stickyCanvas;
    NSWindow *_observedWindow;
    BOOL _includeNotesInExport;
    CGFloat _rememberedWidth;
    CGFloat _windowShiftForNotes;
}

- (instancetype)initWithContentView:(NSView *)contentView
                             viewId:(const std::string &)viewId
                        contextName:(NSString *)contextName
{
    self = [super initWithFrame:[contentView frame]];
    if (!self) return nil;
    _primaryView = contentView;
    _contextName = [contextName length] ? [contextName copy] : @"this window";
    const std::string stableViewId = viewId.empty()
        ? rlispstat::core::GenerateWindowNoteViewId() : viewId;
    _note = rlispstat::core::MakeWindowNote(stableViewId);
    _rememberedWidth = 260.0;
    _windowShiftForNotes = 0.0;
    _includeNotesInExport = NO;
    [self setVertical:YES];
    [self setDividerStyle:NSSplitViewDividerStyleThin];
    [self setDelegate:self];
    [self setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [_primaryView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [self addSubview:_primaryView];
    _stickyCanvas = [[WindowStickyCanvasView alloc] initWithFrame:[_primaryView bounds] owner:self];
    [_primaryView addSubview:_stickyCanvas positioned:NSWindowAbove relativeTo:nil];

    _notesPanel = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, _rememberedWidth, NSHeight([self bounds]))];
    [_notesPanel setWantsLayer:YES];
    [_notesPanel setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    _notesPanel.layer.backgroundColor = [[NSColor controlBackgroundColor] CGColor];
    [_notesPanel setAccessibilityLabel:@"Notes"];

    NSTextField *heading = [NSTextField labelWithString:@"Notes"];
    [heading setFrame:NSMakeRect(12.0, NSHeight([_notesPanel bounds]) - 34.0, 170.0, 22.0)];
    [heading setFont:[NSFont systemFontOfSize:13.0 weight:NSFontWeightSemibold]];
    [heading setAutoresizingMask:NSViewMinYMargin | NSViewWidthSizable];
    [heading setAccessibilityLabel:@"Notes"];
    [_notesPanel addSubview:heading];

    NSButton *hideButton = [NSButton buttonWithTitle:@"Hide" target:self action:@selector(toggleNotes)];
    [hideButton setFrame:NSMakeRect(_rememberedWidth - 62.0, NSHeight([_notesPanel bounds]) - 37.0, 52.0, 26.0)];
    [hideButton setBezelStyle:NSBezelStyleInline];
    [hideButton setAutoresizingMask:NSViewMinXMargin | NSViewMinYMargin];
    [hideButton setAccessibilityLabel:@"Hide Notes"];
    [_notesPanel addSubview:hideButton];

    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(10.0, 10.0,
        _rememberedWidth - 20.0, NSHeight([_notesPanel bounds]) - 52.0)];
    [scroll setHasVerticalScroller:YES];
    [scroll setBorderType:NSBezelBorder];
    [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [scroll setAccessibilityLabel:@"Notes editor"];
    const NSSize notesEditorSize = [scroll contentSize];
    _textView = [[NSTextView alloc] initWithFrame:NSMakeRect(
        0.0, 0.0, notesEditorSize.width, notesEditorSize.height)];
    [_textView setRichText:NO];
    [_textView setAllowsUndo:YES];
    [_textView setUsesFindPanel:YES];
    [_textView setHorizontallyResizable:NO];
    [_textView setVerticallyResizable:YES];
    [_textView setMinSize:NSMakeSize(0.0, notesEditorSize.height)];
    [_textView setMaxSize:NSMakeSize(CGFLOAT_MAX, CGFLOAT_MAX)];
    [_textView setAutoresizingMask:NSViewWidthSizable];
    [_textView setTextContainerInset:NSMakeSize(6.0, 5.0)];
    [_textView setFont:[NSFont systemFontOfSize:13.0]];
    [_textView setDelegate:self];
    [_textView setAccessibilityLabel:@"Notes"];
    [[_textView textContainer] setContainerSize:NSMakeSize(notesEditorSize.width, CGFLOAT_MAX)];
    [[_textView textContainer] setWidthTracksTextView:YES];
    [[_textView textContainer] setLineFragmentPadding:0.0];
    [scroll setDocumentView:_textView];
    [_notesPanel addSubview:scroll];
    [_notesPanel setHidden:YES];
    return self;
}

- (CGFloat)dividerThickness
{
    return _note.visible ? [super dividerThickness] : 0.0;
}

- (NSColor *)dividerColor
{
    return _note.visible ? [super dividerColor] : [NSColor clearColor];
}

- (void)viewDidMoveToWindow
{
    [super viewDidMoveToWindow];
    NSWindow *window = [self window];
    if (!window || _observedWindow == window) return;
    if (_observedWindow) {
        [[NSNotificationCenter defaultCenter] removeObserver:self
                                                        name:NSWindowDidResignKeyNotification
                                                      object:_observedWindow];
    }
    _observedWindow = window;
    ConfigureResultWindowTabbing(window);
    [[NSNotificationCenter defaultCenter] addObserver:self
                                             selector:@selector(notesWindowDidResignKey:)
                                                 name:NSWindowDidResignKeyNotification
                                               object:window];
    [self updateNotesControls];
}

- (NSView *)hitTest:(NSPoint)point
{
    NSView *hit = [super hitTest:point];
    NSEventType type = [[NSApp currentEvent] type];
    if (type == NSEventTypeLeftMouseDown || type == NSEventTypeRightMouseDown)
        [_stickyCanvas activateStickyForHitView:hit];
    return hit;
}

- (void)notesWindowDidResignKey:(NSNotification *)notification
{
    (void)notification;
    [_stickyCanvas deactivateAllStickyNotes];
}

- (void)dealloc
{
    [[NSNotificationCenter defaultCenter] removeObserver:self];
    [super dealloc];
}

- (BOOL)notesVisible { return _note.visible; }
- (BOOL)hasNotes { return _note.has_content || [_stickyCanvas hasContent]; }
- (BOOL)hasPanelNote { return _note.has_content; }
- (BOOL)includeNotes { return _includeNotesInExport; }
- (NSUInteger)stickyNoteCount { return [_stickyCanvas stickyNoteCount]; }
- (std::vector<rlispstat::core::WindowStickyNote>)stickyNotesSnapshot
{
    return [_stickyCanvas stateSnapshots];
}
- (NSString *)noteText { return ToNSString(_note.plain_text); }
- (NSString *)viewId { return ToNSString(_note.view_id); }
- (NSView *)primaryContentView { return _primaryView; }
- (void)replacePrimaryContentView:(NSView *)contentView
{
    if (!contentView || contentView == _primaryView) return;
    NSRect frame = [_primaryView frame];
    [_stickyCanvas removeFromSuperview];
    [_primaryView removeFromSuperview];
    _primaryView = contentView;
    [_primaryView setFrame:frame];
    [_primaryView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    if (_note.visible && [_notesPanel superview] == self)
        [self addSubview:_primaryView positioned:NSWindowBelow relativeTo:_notesPanel];
    else [self addSubview:_primaryView];
    [_stickyCanvas setFrame:[_primaryView bounds]];
    [_primaryView addSubview:_stickyCanvas positioned:NSWindowAbove relativeTo:nil];
    [self adjustSubviews];
}
- (rlispstat::core::WindowNote)noteSnapshot
{
    rlispstat::core::WindowNote snapshot = _note;
    snapshot.include_in_export = _includeNotesInExport && snapshot.has_content;
    return snapshot;
}

- (void)updateNotesControls
{
    if (![self hasNotes]) _includeNotesInExport = NO;
    [[NSApp mainMenu] update];
}

- (void)stickyCanvasDidChange
{
    [self updateNotesControls];
}

- (void)showNotes
{
    if (_note.visible) return;
    NSWindow *window = [self window];
    const CGFloat primaryWidth = NSWidth([self bounds]);
    const CGFloat contentHeight = NSHeight([self bounds]);
    rlispstat::core::SetWindowNoteVisible(_note, true);
    if (window) {
        const CGFloat expandedWidth = primaryWidth + _rememberedWidth + [self dividerThickness];
        [window setContentSize:NSMakeSize(expandedWidth, contentHeight)];
        NSRect frame = [window frame];
        NSScreen *screen = [window screen] ?: [NSScreen mainScreen];
        _windowShiftForNotes = 0.0;
        if (screen) {
            const NSRect visible = [screen visibleFrame];
            const CGFloat overflow = NSMaxX(frame) - NSMaxX(visible);
            if (overflow > 0.0) {
                const CGFloat availableShift = std::max((CGFloat)0.0, NSMinX(frame) - NSMinX(visible));
                _windowShiftForNotes = std::min(overflow, availableShift);
                frame.origin.x -= _windowShiftForNotes;
                [window setFrame:frame display:YES];
            }
        }
    }
    if ([_notesPanel superview] != self) {
        [_notesPanel setFrame:NSMakeRect(
            std::max((CGFloat)0.0, NSWidth([self bounds]) - _rememberedWidth),
            0.0, _rememberedWidth, NSHeight([self bounds]))];
        [self addSubview:_notesPanel];
    }
    [_notesPanel setHidden:NO];
    [self adjustSubviews];
    [self setPosition:primaryWidth ofDividerAtIndex:0];
    [[self window] makeFirstResponder:_textView];
    [self updateNotesControls];
    [self setNeedsDisplay:YES];
    [_primaryView setNeedsDisplay:YES];
    [[self window] displayIfNeeded];
}

- (void)hideNotes
{
    if (!_note.visible) return;
    NSWindow *window = [self window];
    const CGFloat primaryWidth = NSWidth([_primaryView frame]);
    const CGFloat contentHeight = NSHeight([self bounds]);
    if (NSWidth([_notesPanel frame]) >= 160.0) _rememberedWidth = NSWidth([_notesPanel frame]);
    [window makeFirstResponder:_primaryView];
    rlispstat::core::SetWindowNoteVisible(_note, false);
    [_notesPanel setHidden:YES];
    [_notesPanel removeFromSuperview];
    if (window && primaryWidth > 0.0) {
        [window setContentSize:NSMakeSize(primaryWidth, contentHeight)];
        if (_windowShiftForNotes > 0.0) {
            NSRect frame = [window frame];
            frame.origin.x += _windowShiftForNotes;
            [window setFrame:frame display:YES];
        }
    }
    _windowShiftForNotes = 0.0;
    [self adjustSubviews];
    [_primaryView setFrame:[self bounds]];
    [self setNeedsLayout:YES];
    [self layoutSubtreeIfNeeded];
    [self updateNotesControls];
    [self setNeedsDisplay:YES];
    [_primaryView setNeedsDisplay:YES];
    [[[self window] contentView] setNeedsDisplay:YES];
    [[self window] displayIfNeeded];
}

- (void)toggleNotes
{
    _note.visible ? [self hideNotes] : [self showNotes];
}

- (void)textDidChange:(NSNotification *)notification
{
    (void)notification;
    const bool hadContent = _note.has_content;
    rlispstat::core::SetWindowNoteText(_note, std::string([[[_textView textStorage] string] UTF8String]));
    if (hadContent != _note.has_content) [self updateNotesControls];
}

- (void)clearNotesWithConfirmation
{
    if (!_note.has_content) return;
    NSAlert *alert = [[NSAlert alloc] init];
    [alert setMessageText:@"Clear Notes?"];
    [alert setInformativeText:[NSString stringWithFormat:@"This removes the note attached to %@.", _contextName]];
    [alert addButtonWithTitle:@"Clear Notes"];
    [alert addButtonWithTitle:@"Cancel"];
    if ([alert runModal] != NSAlertFirstButtonReturn) return;
    rlispstat::core::ClearWindowNote(_note);
    [_textView setString:@""];
    [self updateNotesControls];
}

- (void)toggleIncludeNotes
{
    if (![self hasNotes]) return;
    _includeNotesInExport = !_includeNotesInExport;
    [self updateNotesControls];
}

- (void)addStickyNote
{
    [_stickyCanvas addStickyNote];
}

- (void)setStickyNotesHiddenForExport:(BOOL)hidden
{
    [_stickyCanvas setHidden:hidden];
}

- (BOOL)stickyNotesHidden
{
    return [_stickyCanvas isHidden];
}

- (NSMenuItem *)annotateContextMenuItem
{
    NSString *title = [self hasNotes] ? @"Annotate •" : @"Annotate";
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:title action:nil keyEquivalent:@""];
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Annotate"];
    NSString *toggleTitle = _note.visible ? @"Hide Notes" :
        (_note.has_content ? @"Show Notes •" : @"Show Notes");
    NSMenuItem *toggle = PlotCommandMenuItem(toggleTitle, @"NOTES_TOGGLE");
    [toggle setState:_note.visible ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:toggle];
    [menu addItem:PlotCommandMenuItem(@"New Sticker", @"NOTES_ADD_STICKY")];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *clear = PlotCommandMenuItem(@"Clear Notes", @"NOTES_CLEAR");
    [clear setEnabled:_note.has_content];
    [menu addItem:clear];
    [root setSubmenu:menu];
    return root;
}

- (void)splitViewDidResizeSubviews:(NSNotification *)notification
{
    (void)notification;
    if (_note.visible && NSWidth([_notesPanel frame]) >= 160.0) {
        _rememberedWidth = NSWidth([_notesPanel frame]);
    }
}

- (CGFloat)splitView:(NSSplitView *)splitView constrainMinCoordinate:(CGFloat)proposedMinimumPosition ofSubviewAt:(NSInteger)dividerIndex
{
    (void)splitView; (void)proposedMinimumPosition; (void)dividerIndex;
    return 260.0;
}

- (CGFloat)splitView:(NSSplitView *)splitView constrainMaxCoordinate:(CGFloat)proposedMaximumPosition ofSubviewAt:(NSInteger)dividerIndex
{
    (void)dividerIndex;
    return std::max((CGFloat)260.0, std::min(proposedMaximumPosition, NSWidth([splitView bounds]) - 180.0));
}
@end

static void ReplacePlotViewWithTrellisOnMain(PlotModel *model)
{
    if (!model) return;
    for (ScatterView *view : g_views) {
        if (view.model == model) { [view setNeedsDisplay:YES]; return; }
    }
    NSView *oldView = nil;
    auto eraseView = [model](auto &views) {
        auto found = std::find_if(views.begin(), views.end(), [model](auto *view) {
            return view && [(id)view model] == model;
        });
        if (found == views.end()) return (NSView *)nil;
        NSView *result = *found;
        views.erase(found);
        return result;
    };
    if (!oldView) oldView = eraseView(g_boxplotViews);
    if (!oldView) oldView = eraseView(g_histogramViews);
    if (!oldView) oldView = eraseView(g_barplotViews);
    if (!oldView) return;
    WindowNotesContainer *container = [oldView.superview isKindOfClass:[WindowNotesContainer class]]
        ? (WindowNotesContainer *)oldView.superview : nil;
    if (!container) return;
    ScatterView *replacement = [[ScatterView alloc] initWithModel:model];
    [replacement setFrame:[oldView frame]];
    [container replacePrimaryContentView:replacement];
    g_views.push_back(replacement);
    [[container window] makeFirstResponder:replacement];
    [[container window] setTitle:ToNSString(PlotWindowTitleWithAnalysisScope(*model))];
    [replacement setNeedsDisplay:YES];
}

static WindowNotesContainer *ActiveWindowNotesContainer()
{
    NSArray *candidates = @[[NSApp keyWindow] ?: [NSNull null],
                            [NSApp mainWindow] ?: [NSNull null]];
    for (id candidate in candidates) {
        if (![candidate isKindOfClass:[NSWindow class]]) continue;
        NSView *content = [(NSWindow *)candidate contentView];
        if ([content isKindOfClass:[WindowNotesContainer class]]) {
            return (WindowNotesContainer *)content;
        }
    }
    return nil;
}

static WindowNotesContainer *WindowNotesContainerForView(NSView *view)
{
    for (NSView *candidate = view; candidate; candidate = [candidate superview]) {
        if ([candidate isKindOfClass:[WindowNotesContainer class]])
            return (WindowNotesContainer *)candidate;
    }
    NSView *content = [[view window] contentView];
    return [content isKindOfClass:[WindowNotesContainer class]]
        ? (WindowNotesContainer *)content : nil;
}

static void ConfigureResultWindowTabbing(NSWindow *window)
{
    if (!window) return;
    [window setTabbingIdentifier:@"LinkEDA.Results"];
    // Prevent AppKit from creating a visible one-tab bar while the window is
    // being attached. Enable tabbing after presentation so a hidden window can
    // still accept a native tab drag and reveal its bar on drop.
    [window setTabbingMode:NSWindowTabbingModeDisallowed];
    dispatch_async(dispatch_get_main_queue(), ^{
        [window setTabbingMode:NSWindowTabbingModeAutomatic];
        dispatch_async(dispatch_get_main_queue(), ^{
            NSArray<NSWindow *> *tabs = [window tabbedWindows];
            if ([tabs count] == 1) [window toggleTabBar:nil];
        });
    });
}

static WindowNotesContainer *EnableNotesForWindow(NSWindow *window,
                                                   const std::string &viewId,
                                                   NSString *contextName,
                                                   const std::string &dataSheetGroup)
{
    if (!window) return nil;
    SetWindowDataSheetGroupOnMac(window, dataSheetGroup);
    NSView *content = [window contentView];
    if ([content isKindOfClass:[WindowNotesContainer class]])
        return (WindowNotesContainer *)content;
    ConfigureResultWindowTabbing(window);
    WindowNotesContainer *container = [[WindowNotesContainer alloc]
        initWithContentView:content viewId:viewId contextName:contextName];
    [window setContentView:container];
    return container;
}

static NSData *VisualExportDataForView(NSView *view, NSString *format)
{
    return VisualExportDataForViewWithNotes(view, format, WindowNotesContainerForView(view));
}

static NSData *VisualExportDataForViewWithNotes(NSView *view, NSString *format,
                                                 WindowNotesContainer *notes)
{
    if (!view) return nil;
    const BOOL isPDF = [format caseInsensitiveCompare:@"PDF"] == NSOrderedSame;
    const BOOL stickyNotesWereHidden = notes ? [notes stickyNotesHidden] : YES;
    if (notes) [notes setStickyNotesHiddenForExport:![notes includeNotes]];
    NSMutableArray<NSView *> *transientControls = [NSMutableArray array];
    NSMutableArray<NSView *> *pending = [NSMutableArray arrayWithObject:view];
    while ([pending count] > 0) {
        NSView *candidate = [pending lastObject];
        [pending removeLastObject];
        if ([[candidate identifier] isEqualToString:@"LinkEDA.TransientPlotControl"] &&
            ![candidate isHidden]) {
            [transientControls addObject:candidate];
            [candidate setHidden:YES];
        }
        [pending addObjectsFromArray:[candidate subviews]];
    }
    NSData *primaryData = isPDF
        ? [view dataWithPDFInsideRect:[view bounds]]
        : HighResolutionPNGDataForView(view);
    for (NSView *control in transientControls) [control setHidden:NO];
    if (notes) [notes setStickyNotesHiddenForExport:stickyNotesWereHidden];
    if (!notes || !primaryData) return primaryData;
    const auto composition =
        rlispstat::core::BuildWindowExportComposition([notes noteSnapshot]);
    if (!composition.note.has_value()) return primaryData;

    NSImage *primaryImage = [[NSImage alloc] initWithData:primaryData];
    if (!primaryImage) return primaryData;
    [primaryImage setSize:[view bounds].size];
    WindowNoteExportView *exportView = [[WindowNoteExportView alloc]
        initWithPrimaryImage:primaryImage noteText:ToNSString(composition.note->plain_text)];
    if (!exportView) return primaryData;
    return isPDF
        ? [exportView dataWithPDFInsideRect:[exportView bounds]]
        : HighResolutionPNGDataForView(exportView);
}

static std::string ComposeSvgExportForView(NSView *view, const std::string &svg)
{
    WindowNotesContainer *notes = WindowNotesContainerForView(view);
    if (!notes) return svg;
    const auto composition = rlispstat::core::BuildWindowExportComposition([notes noteSnapshot]);
    return composition.note.has_value()
        ? rlispstat::core::ComposeSvgDocumentWithWindowNote(svg, *composition.note)
        : svg;
}

@implementation HistogramView
- (instancetype)initWithModel:(PlotModel *)model
{
    self = [super initWithFrame:NSMakeRect(0, 0, 720, 520)];
    if (self) {
        self.model = model;
        self.dragging = NO;
        self.renderingForExport = NO;
        [self setWantsLayer:YES];
        self.densityAdjustControl = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 292, 32)];
        [self.densityAdjustControl setWantsLayer:YES];
        self.densityAdjustControl.layer.cornerRadius = 6;
        self.densityAdjustControl.layer.backgroundColor = [[NSColor controlBackgroundColor] colorWithAlphaComponent:.92].CGColor;
        self.densityAdjustLabel = GLMLabel(@"Smoothing ×1.00", NSMakeRect(8, 7, 112, 18), 10, NSFontWeightMedium);
        self.densityAdjustSlider = [[NSSlider alloc] initWithFrame:NSMakeRect(120, 4, 160, 24)];
        [self.densityAdjustSlider setMinValue:.1]; [self.densityAdjustSlider setMaxValue:3];
        [self.densityAdjustSlider setContinuous:YES];
        [self.densityAdjustSlider setTarget:self];
        [self.densityAdjustSlider setAction:@selector(densityAdjustChanged:)];
        [self.densityAdjustControl addSubview:self.densityAdjustLabel];
        [self.densityAdjustControl addSubview:self.densityAdjustSlider];
        [self addSubview:self.densityAdjustControl];
        [self syncDensityAdjustControl];
    }
    return self;
}

- (void)syncDensityAdjustControl
{
    if (!self.model || !self.densityAdjustControl) return;
    const double value = self.model->histogramDensityAdjust;
    [self.densityAdjustSlider setMaxValue:std::max(3.0, value)];
    [self.densityAdjustSlider setMinValue:std::min(.1, value)];
    [self.densityAdjustSlider setDoubleValue:value];
    [self.densityAdjustLabel setStringValue:[NSString stringWithFormat:@"Smoothing ×%.2f", value]];
    const NSRect plot = [self plotRect];
    [self.densityAdjustControl setFrameOrigin:NSMakePoint(std::max<CGFloat>(8, NSMaxX(plot)-292), NSMinY(plot)+8)];
    [self.densityAdjustControl setHidden:self.renderingForExport || !self.model->histogramShowDensity || self.model->histogramDensityMode == "none"];
}

- (void)densityAdjustChanged:(id)sender
{
    if (!self.model) return;
    MacCommandDispatcher().dispatch({"HIST_SET_DENSITY_ADJUST", self.model->id,
        std::to_string([(NSSlider *)sender doubleValue])});
    [self syncDensityAdjustControl]; [self setNeedsDisplay:YES];
}

- (BOOL)acceptsFirstResponder { return YES; }
- (BOOL)isFlipped { return YES; }

- (NSRect)plotRect
{
    NSRect b = [self bounds];
    return NSMakeRect(64, 42, std::max(10.0, b.size.width - 96), std::max(10.0, b.size.height - 104));
}

- (int)maxBinCount
{
    std::vector<std::vector<rlispstat::core::CaseId>> binRows;
    if (!self.model) {
        return rlispstat::core::HistogramMaximumBinCount(binRows);
    }
    binRows.reserve(self.model->histogramBins.size());
    for (const HistogramBin &bin : self.model->histogramBins) {
        binRows.push_back(bin.rows);
    }
    return rlispstat::core::HistogramMaximumBinCount(binRows);
}

- (rlispstat::core::HistogramLayout)histogramLayoutWithMaxCount:(int)maxCount
{
    rlispstat::core::HistogramLayout layout;
    layout.plotRect = rlispstat::platform::macos::ToCoreRect([self plotRect]);
    layout.maxCount = std::max(1, maxCount);
    layout.gap = 2.0;
    if (!self.model) {
        return layout;
    }
    layout.counts.reserve(self.model->histogramBins.size());
    for (const HistogramBin &bin : self.model->histogramBins) {
        layout.counts.push_back((int)bin.rows.size());
    }
    return layout;
}

- (NSRect)rectForBin:(NSInteger)bin maxCount:(int)maxCount
{
    if (bin < 0) {
        return NSZeroRect;
    }
    return rlispstat::platform::macos::ToNSRect(
        rlispstat::core::HistogramBinRect([self histogramLayoutWithMaxCount:maxCount], (size_t)bin)
    );
}

- (NSInteger)binIndexAtPoint:(NSPoint)point
{
    std::optional<size_t> index = rlispstat::core::HistogramBinIndexAtPoint(
        [self histogramLayoutWithMaxCount:[self maxBinCount]],
        rlispstat::platform::macos::ToCorePoint(point)
    );
    if (!index.has_value()) {
        return -1;
    }
    return (NSInteger)*index;
}

- (NSRect)variableLabelRect
{
    if (!self.model || self.model->xLabel.empty()) return NSZeroRect;
    const NSRect plot = [self plotRect];
    NSDictionary *attributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium]
    };
    const NSSize labelSize = [ToNSString(self.model->xLabel) sizeWithAttributes:attributes];
    return NSMakeRect(
        NSMidX(plot) - labelSize.width / 2.0 - 8.0,
        NSMaxY(plot) + 25.0,
        labelSize.width + 16.0,
        std::max<CGFloat>(28.0, labelSize.height + 10.0));
}

- (NSRect)histogramAxisRect
{
    const NSRect plot = [self plotRect];
    return NSMakeRect(NSMinX(plot) - 8, NSMaxY(plot) - 3, NSWidth(plot) + 16, 59);
}

- (NSMenu *)variableMenu
{
    if (!self.model) return nil;
    if (NSMenuItem *residuals = [self diagnosticResidualMenuItem]) {
        return [residuals submenu];
    }
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Variable"];
    NSMenuItem *heading = [[NSMenuItem alloc]
        initWithTitle:@"Change variable" action:nil keyEquivalent:@""];
    [heading setEnabled:NO];
    [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];
    for (const NumericVariable &variable : self.model->variables) {
        NSMenuItem *item = [self menuItem:ToNSString(variable.name)
            command:ToNSString("CHANGE_X_VARIABLE|" + variable.name)];
        [item setState:variable.name == self.model->xLabel
            ? NSControlStateValueOn : NSControlStateValueOff];
        [menu addItem:item];
    }
    return menu;
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [self syncDensityAdjustControl];
    PlotThemeOverrideScope snapshotTheme(self.snapshotThemeName ?: PlotLocalThemeName(self));
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);
    NSRect pr = [self plotRect];
    [theme.panel setFill];
    NSRectFill(pr);

    std::set<int> selection;
    std::map<int, std::string> rowColors = RowColorsForPlot(self.model);
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(self.model->group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    std::vector<HistogramDensityCurve> densityCurves = DensityCurvesForHistogram(self.model, selection, rowColors);
    bool densityDisplayActive = rlispstat::core::HistogramDensityDisplayActive(
        self.model->histogramShowDensity,
        self.model->histogramDensityMode);
    int maxCount = [self maxBinCount];
    rlispstat::core::HistogramLayout histogramLayout = [self histogramLayoutWithMaxCount:maxCount];
    std::vector<std::vector<rlispstat::core::CaseId>> binRows;
    binRows.reserve(self.model->histogramBins.size());
    for (const HistogramBin &bin : self.model->histogramBins) {
        binRows.push_back(bin.rows);
    }
    std::vector<rlispstat::core::HistogramRugCase> rugCases;
    if (self.model->histogramShowRug) {
        rugCases.reserve(self.model->histogramPoints.size());
        for (const HistogramPoint &p : self.model->histogramPoints) {
            NSInteger b = (NSInteger)p.bin - 1;
            if (b < 0) continue;
            rugCases.push_back({p.row, (std::size_t)b});
        }
    }
    rlispstat::core::HistogramRenderInput renderInput;
    renderInput.layout = histogramLayout;
    renderInput.binRows = binRows;
    renderInput.selection = selection;
    renderInput.rowColors = rowColors;
    renderInput.showCounts = self.model->histogramShowCounts;
    renderInput.showColorSegments = !self.model->colorByVariable.empty() ||
        rlispstat::core::HistogramColorSegmentsVisible(
            self.model->histogramShowDensity,
            self.model->histogramDensityMode);
    renderInput.showRug = self.model->histogramShowRug;
    renderInput.rugCases = rugCases;
    renderInput.densityCurves = densityCurves;
    if (!self.model->histogramBins.empty()) {
        renderInput.densityXMinimum = self.model->histogramBins.front().lower;
        renderInput.densityXMaximum = self.model->histogramBins.back().upper;
    }
    rlispstat::core::HistogramRenderPlan renderPlan =
        rlispstat::core::BuildHistogramRenderPlan(renderInput);
    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    if (self.renderingForExport && !self.model->title.empty()) {
        NSMutableParagraphStyle *titleStyle = [[NSMutableParagraphStyle alloc] init];
        [titleStyle setAlignment:NSTextAlignmentCenter];
        [titleStyle setLineBreakMode:NSLineBreakByTruncatingTail];
        NSMutableDictionary *centeredTitleAttrs = [labelAttrs mutableCopy];
        [centeredTitleAttrs setObject:titleStyle forKey:NSParagraphStyleAttributeName];
        [ToNSString(self.model->title) drawInRect:NSMakeRect(pr.origin.x, 10, pr.size.width, 20)
                                   withAttributes:centeredTitleAttrs];
    }
    DrawPlotImputationDisplayStatus(
        self.model, false, pr, self.renderingForExport ? 30.0 : 10.0);

    DrawHistogramRenderPlanInPanel(renderPlan, pr, theme, self.model->group, selection);

    // Histogram graduations are controlled independently from their numeric
    // labels.  Keeping these as separate options lets a clean publication
    // retain scale values without requiring visible tick strokes (and vice
    // versa).
    NSDictionary *tickAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10],
        NSForegroundColorAttributeName: theme.mutedText
    };
    const int tickIntervals = 4;
    for (int tick = 0; tick <= tickIntervals; ++tick) {
        const CGFloat fraction = (CGFloat)tick / (CGFloat)tickIntervals;
        const CGFloat y = rlispstat::core::ZeroBaselineY(histogramLayout.plotRect, fraction);
        if (self.model->histogramShowTickMarks) {
            NSBezierPath *mark = [NSBezierPath bezierPath];
            [mark moveToPoint:NSMakePoint(NSMinX(pr) - 4.0, y)];
            [mark lineToPoint:NSMakePoint(NSMinX(pr), y)];
            [mark setLineWidth:1.0];
            [theme.axis setStroke];
            [mark stroke];
        }
        if (self.model->histogramShowTickLabels) {
            const double value = (double)maxCount * (double)tick / (double)tickIntervals;
            NSString *label = ToNSString(FormatDouble(value, 1));
            NSSize size = [label sizeWithAttributes:tickAttrs];
            [label drawAtPoint:NSMakePoint(NSMinX(pr) - size.width - 7.0,
                                           y - size.height / 2.0)
                 withAttributes:tickAttrs];
        }
    }
    if (!self.model->histogramBins.empty()) {
        const double minimum = self.model->histogramBins.front().lower;
        const double maximum = self.model->histogramBins.back().upper;
        const rlispstat::core::Rect contentRect =
            rlispstat::core::ZeroBaselineContentRect(histogramLayout.plotRect);
        for (int tick = 0; tick <= tickIntervals; ++tick) {
            const CGFloat fraction = (CGFloat)tick / (CGFloat)tickIntervals;
            const CGFloat x = contentRect.x + fraction * contentRect.width;
            if (self.model->histogramShowTickMarks) {
                NSBezierPath *mark = [NSBezierPath bezierPath];
                const CGFloat baseline = rlispstat::core::ZeroBaselineY(
                    histogramLayout.plotRect, 0.0);
                [mark moveToPoint:NSMakePoint(x, baseline)];
                [mark lineToPoint:NSMakePoint(x, baseline + 4.0)];
                [mark setLineWidth:1.0];
                [theme.axis setStroke];
                [mark stroke];
            }
            if (self.model->histogramShowTickLabels) {
                const double value = minimum + (maximum - minimum) *
                    (double)tick / (double)tickIntervals;
                NSString *label = ToNSString(FormatDouble(value, 3));
                NSSize size = [label sizeWithAttributes:tickAttrs];
                [label drawAtPoint:NSMakePoint(x - size.width / 2.0,
                                               NSMaxY(pr) + 7.0)
                     withAttributes:tickAttrs];
            }
        }
    }

    if (!self.model->xLabel.empty()) {
        NSMutableParagraphStyle *axisStyle = [[NSMutableParagraphStyle alloc] init];
        [axisStyle setAlignment:NSTextAlignmentCenter];
        [axisStyle setLineBreakMode:NSLineBreakByTruncatingTail];
        NSDictionary *axisAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text,
            NSParagraphStyleAttributeName: axisStyle
        };
        [ToNSString(self.model->xLabel)
            drawInRect:NSMakeRect(pr.origin.x, NSMaxY(pr) + 30.0, pr.size.width, 20.0)
        withAttributes:axisAttrs];
    }

    if ((self.model->labelDisplayMode == "all" ||
         self.model->labelDisplayMode == "selected") &&
        !self.model->histogramBins.empty()) {
        const std::map<int, std::string> rowLabels = RowLabelsForPlot(self.model);
        const double minimum = self.model->histogramBins.front().lower;
        const double maximum = self.model->histogramBins.back().upper;
        const double span = maximum - minimum;
        std::map<int, int> labelSlots;
        NSDictionary *pointLabelAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:9 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text
        };
        if (span > 0.0) for (const HistogramPoint &point : self.model->histogramPoints) {
            if (self.model->labelDisplayMode == "selected" &&
                selection.find(point.row) == selection.end()) continue;
            auto text = rowLabels.find(point.row);
            if (text == rowLabels.end() || text->second.empty() || point.bin <= 0 ||
                (std::size_t)point.bin > renderPlan.bars.size() || !std::isfinite(point.x)) continue;
            const CGFloat x = pr.origin.x + std::clamp(
                (point.x - minimum) / span, 0.0, 1.0) * pr.size.width;
            const rlispstat::core::Rect &bar = renderPlan.bars[(std::size_t)point.bin - 1].rect;
            const int slot = labelSlots[point.bin]++ % 4;
            const CGFloat y = std::max<CGFloat>(pr.origin.y + 2.0,
                bar.y - 14.0 - slot * 12.0);
            [ToNSString(text->second) drawInRect:NSMakeRect(x + 3.0, y, 120.0, 12.0)
                                  withAttributes:pointLabelAttrs];
        }
    }

    if (self.dragging) {
        std::optional<rlispstat::core::Rect> highlightRect =
            rlispstat::core::HistogramDragHighlightRect(
                histogramLayout,
                rlispstat::platform::macos::ToCorePoint(self.dragStart),
                rlispstat::platform::macos::ToCorePoint(self.dragCurrent));
        if (highlightRect.has_value()) {
            NSRect rr = rlispstat::platform::macos::ToNSRect(*highlightRect);
            [[theme.accent colorWithAlphaComponent:0.12] setFill];
            NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        }
    }
    if (theme.showPanelBorder) {
        NSBezierPath *border = [NSBezierPath bezierPathWithRect:NSInsetRect(pr, 0.5, 0.5)];
        [border setLineWidth:1.0];
        [theme.axis setStroke];
        [border stroke];
    }
    DrawColorLegend(self.model, [self bounds], theme);
}

- (void)mouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    const NSPoint initialPoint = [self convertPoint:[event locationInWindow] fromView:nil];
    if (NSPointInRect(initialPoint, [self histogramAxisRect])) {
        NSMenu *menu = [self variableMenu];
        if (menu) [NSMenu popUpContextMenu:menu withEvent:event forView:self];
        return;
    }
    if (HandleColorLegendMouseDown(self, self.model, event)) return;
    self.dragging = YES;
    self.dragStart = initialPoint;
    self.dragCurrent = self.dragStart;
    [self setNeedsDisplay:YES];

    while (self.dragging) {
        NSEvent *trackingEvent = [[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                                                            untilDate:[NSDate distantFuture]
                                                               inMode:NSEventTrackingRunLoopMode
                                                              dequeue:YES];
        if (!trackingEvent) {
            break;
        }
        if ([trackingEvent type] == NSEventTypeLeftMouseDragged) {
            [self mouseDragged:trackingEvent];
        } else if ([trackingEvent type] == NSEventTypeLeftMouseUp) {
            [self finishDragWithEvent:trackingEvent];
            break;
        }
    }
}

- (void)mouseDragged:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    [self setNeedsDisplay:YES];
}

- (void)mouseUp:(NSEvent *)event
{
    [self finishDragWithEvent:event];
}

- (void)finishDragWithEvent:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!self.dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragging = NO;
    std::vector<std::vector<rlispstat::core::CaseId>> binRows;
    binRows.reserve(self.model->histogramBins.size());
    for (const HistogramBin &bin : self.model->histogramBins) {
        binRows.push_back(bin.rows);
    }
    rlispstat::core::HistogramLayout layout = [self histogramLayoutWithMaxCount:[self maxBinCount]];
    rlispstat::core::Point dragStart = rlispstat::platform::macos::ToCorePoint(self.dragStart);
    rlispstat::core::Point dragCurrent = rlispstat::platform::macos::ToCorePoint(self.dragCurrent);
    if (!rlispstat::core::HistogramBinRangeForGesture(layout, dragStart, dragCurrent).has_value()) {
        [self setNeedsDisplay:YES];
        return;
    }
    std::set<int> rows = rlispstat::core::SelectHistogramCasesForGesture(
        binRows,
        layout,
        dragStart,
        dragCurrent
    );
    int selectionVersion = 0;
    if (MergeSelection(self.model->group, rows, EffectiveSelectionMode(self.model, [event modifierFlags]), &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(rows.begin(), rows.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    UpdatePanelOnMain();
}

- (void)refreshSelection
{
    [self setNeedsDisplay:YES];
}

- (void)selectDiagnosticImputation:(id)sender
{
    if (!self.model || !self.model->isGLMDiagnostic) return;
    const NSInteger selected = [[sender representedObject] integerValue];
    if (selected < 1 || selected > self.model->diagnosticImputationCount) return;
    self.model->diagnosticImputationIndex = static_cast<int>(selected);
    if (UpdateGLMDiagnosticPlot(self.model)) {
        UpdateWindowTitleOnMain(self.model);
        [self setNeedsDisplay:YES];
    }
}

- (void)selectDiagnosticResidualType:(id)sender
{
    id represented = [sender representedObject];
    if (![represented isKindOfClass:[NSString class]]) return;
    if (SelectDiagnosticResidualType(self.model, (NSString *)represented)) {
        UpdateWindowTitleOnMain(self.model);
        [self setNeedsDisplay:YES];
    }
}

- (NSMenuItem *)diagnosticResidualMenuItem
{
    if (!DiagnosticKindUsesResidualChoice(self.model)) return nil;
    NSMenuItem *root = [[NSMenuItem alloc]
        initWithTitle:@"Residuals" action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:@"Residuals"];
    for (const auto &choice : DiagnosticResidualChoices(self.model)) {
        NSMenuItem *item = [[NSMenuItem alloc]
            initWithTitle:choice.second
            action:@selector(selectDiagnosticResidualType:)
            keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:ToNSString(choice.first)];
        [item setState:self.model->displayedResidualType == choice.first
            ? NSControlStateValueOn : NSControlStateValueOff];
        [submenu addItem:item];
    }
    [root setSubmenu:submenu];
    return root;
}

- (NSMenuItem *)diagnosticImputationMenuItem
{
    if (!self.model || !self.model->isGLMDiagnostic ||
        self.model->diagnosticImputationCount <= 1) return nil;
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:@"Imputation" action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:@"Imputation"];
    for (int index = 1; index <= self.model->diagnosticImputationCount; ++index) {
        NSString *title = [NSString stringWithFormat:@"Imputation %d of %d",
            index, self.model->diagnosticImputationCount];
        NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title
            action:@selector(selectDiagnosticImputation:) keyEquivalent:@""];
        [item setTarget:self];
        [item setRepresentedObject:@(index)];
        [item setState:index == self.model->diagnosticImputationIndex
            ? NSControlStateValueOn : NSControlStateValueOff];
        [submenu addItem:item];
    }
    [root setSubmenu:submenu];
    return root;
}

- (NSMenuItem *)menuItem:(NSString *)title command:(NSString *)command
{
    if (!g_commandTarget) g_commandTarget = [[CommandTarget alloc] init];
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:@""];
    [item setTarget:g_commandTarget];
    [item setRepresentedObject:command];
    return item;
}

- (NSMenuItem *)menuItemForOption:(const rlispstat::core::HistogramMenuOption &)option
{
    NSMenuItem *item = nil;
    if (option.command.empty()) {
        item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""];
    } else {
        item = [self menuItem:ToNSString(option.title) command:ToNSString(option.command)];
    }
    [item setEnabled:option.enabled];
    [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
    return item;
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    const rlispstat::core::PlotContextMenuTitles contextTitles = rlispstat::core::DefaultPlotContextMenuTitles();
    rlispstat::core::HistogramMenuState menuState = rlispstat::core::BuildHistogramMenuState(
        self.model ? self.model->xLabel : "",
        self.model ? self.model->histogramShowCounts : true,
        self.model ? self.model->histogramShowTickMarks : true,
        self.model ? self.model->histogramShowTickLabels : true,
        self.model ? self.model->histogramShowRug : false,
        self.model ? self.model->histogramShowDensity : false,
        self.model ? self.model->histogramDensityMode : "all");
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    if (NSMenuItem *imputation = [self diagnosticImputationMenuItem]) {
        [menu addItem:imputation];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    if (NSMenuItem *residuals = [self diagnosticResidualMenuItem]) {
        [menu addItem:residuals];
        [menu addItem:[NSMenuItem separatorItem]];
    }
    NSMenuItem *variablesRoot = [[NSMenuItem alloc] initWithTitle:@"Variables" action:nil keyEquivalent:@""];
    NSMenu *variablesMenu = [[NSMenu alloc] initWithTitle:@"Variables"];
    if (NSMenuItem *splitItem = ColorByVariableMenuItem(self.model))
        [variablesMenu addItem:splitItem];
    if (NSMenuItem *legendItem = ColorLegendMenuItem(self.model))
        [variablesMenu addItem:legendItem];
    if (NSMenuItem *conditionItem = ConditioningVariablesMenuItem(self.model))
        [variablesMenu addItem:conditionItem];
    if (!self.model->isGLMDiagnostic) {
        [menu setSubmenu:variablesMenu forItem:variablesRoot];
        [menu addItem:variablesRoot];
    }

    NSMenuItem *hist = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.title) action:nil keyEquivalent:@""];
    NSMenu *histMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    AddHistogramBinningMenuItems(histMenu, self.model);
    [histMenu addItem:[NSMenuItem separatorItem]];
    [histMenu addItem:[self menuItemForOption:menuState.counts]];
    [histMenu addItem:[self menuItemForOption:menuState.tickMarks]];
    [histMenu addItem:[self menuItemForOption:menuState.tickLabels]];
    [histMenu addItem:[self menuItemForOption:menuState.rug]];
    [menu setSubmenu:histMenu forItem:hist];
    [menu addItem:hist];

    NSMenuItem *density = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.densityCurvesTitle) action:nil keyEquivalent:@""];
    NSMenu *densityMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.densityCurvesTitle)];
    [densityMenu addItem:[self menuItemForOption:menuState.densityToggle]];
    NSMenuItem *modeItem = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.densityModeTitle) action:nil keyEquivalent:@""];
    NSMenu *modeMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.densityModeTitle)];
    for (const rlispstat::core::HistogramMenuOption &option : menuState.densityModes) {
        [modeMenu addItem:[self menuItemForOption:option]];
    }
    [densityMenu setSubmenu:modeMenu forItem:modeItem];
    [densityMenu addItem:modeItem];
    [densityMenu addItem:[self menuItemForOption:menuState.densityBandwidth]];
    [densityMenu addItem:[self menuItemForOption:menuState.densityAdjust]];
    [menu setSubmenu:densityMenu forItem:density];
    [menu addItem:density];

    NSMenuItem *analysis = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.analyzeThisHistogram) action:nil keyEquivalent:@""];
    NSMenu *analysisMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.analyzeThisHistogram)];
    [analysisMenu addItem:[self menuItemForOption:menuState.frequencyTable]];
    [analysisMenu addItem:[self menuItemForOption:menuState.descriptives]];
    [menu setSubmenu:analysisMenu forItem:analysis];
    [menu addItem:analysis];

    NSMenuItem *selection = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.selection) action:nil keyEquivalent:@""];
    NSMenu *selectionMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.selection)];
    for (const rlispstat::core::HistogramMenuOption &option : menuState.selectionOptions) {
        [selectionMenu addItem:[self menuItemForOption:option]];
    }
    [selectionMenu addItem:ColorSelectedPointsSubmenuItem(ToNSString(contextTitles.colorSelectedRows))];
    [selectionMenu addItem:[self menuItem:ToNSString(contextTitles.openColorPalette) command:@"OPEN_COLOR_PALETTE"]];
    [selectionMenu addItem:[NSMenuItem separatorItem]];
    [selectionMenu addItem:AddDataColumnSubmenuItem()];
    [menu setSubmenu:selectionMenu forItem:selection];
    [menu addItem:selection];
    if (rlispstat::core::PlotSupportsObservationLabels(*self.model)) {
    NSMenuItem *labels = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.labels) action:nil keyEquivalent:@""];
    NSMenu *labelsMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.labels)];
    const auto chooseLabel = rlispstat::core::ScatterplotChooseLabelColumnOption(
        LabelColumnForGroup(self.model ? self.model->group : std::string()));
    NSMenuItem *chooseLabelItem = [self menuItem:ToNSString(chooseLabel.title)
        command:ToNSString(chooseLabel.command)];
    [chooseLabelItem setEnabled:chooseLabel.enabled];
    [chooseLabelItem setState:chooseLabel.checked ? NSControlStateValueOn : NSControlStateValueOff];
    [labelsMenu addItem:chooseLabelItem];
    [labelsMenu addItem:[NSMenuItem separatorItem]];
    for (const rlispstat::core::ScatterplotMenuOption &option :
         rlispstat::core::ScatterplotLabelDisplayMenuOptions(
             self.model ? self.model->labelDisplayMode : "none")) {
        NSMenuItem *item = [self menuItem:ToNSString(option.title) command:ToNSString(option.command)];
        [item setEnabled:option.enabled];
        [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
        [labelsMenu addItem:item];
    }
    [menu setSubmenu:labelsMenu forItem:labels];
    [menu addItem:labels];
    }
    std::vector<int> clickedRows;
    std::string clickedDescription;
    std::string clickedElement;
    if (event && self.model) {
        NSPoint click = [self convertPoint:[event locationInWindow] fromView:nil];
        const auto index = rlispstat::core::HistogramBinIndexAtPoint(
            [self histogramLayoutWithMaxCount:[self maxBinCount]],
            rlispstat::platform::macos::ToCorePoint(click));
        if (index.has_value() && *index < self.model->histogramBins.size()) {
            const HistogramBin &bin = self.model->histogramBins[*index];
            clickedRows = bin.rows;
            clickedDescription = "Histogram bin " + std::to_string(*index + 1);
            clickedElement = std::to_string(*index + 1);
        }
    }
    [menu addItem:AnalysisScopeSubmenuItemForPlot(
        self.model, clickedRows, "histogram_bin", clickedDescription, clickedElement)];

    NSMenuItem *plot = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.plot) action:nil keyEquivalent:@""];
    NSMenu *plotMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.plot)];
    for (const rlispstat::core::HistogramMenuOption &option : menuState.plotOptions) {
        [plotMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:plotMenu forItem:plot];
    [menu addItem:plot];
    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.exportMenu) action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.exportMenu)];
    AddStandardPlotExportItems(exportMenu, NO);
    if (self.model && !self.model->codeReference.provenance.verificationRCode.empty())
        AddRCodeExportItems(exportMenu, "output", self.model->id, false);
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    AddSnapshotAlbumContextItems(menu);
    NSMenuItem *viewItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.view) action:nil keyEquivalent:@""];
    NSMenu *viewMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.view)];
    if (NSMenuItem *imputation = ImputationDisplaySubmenuItemForPlot(self.model)) {
        [viewMenu addItem:imputation];
        [viewMenu addItem:[NSMenuItem separatorItem]];
    }
    AddPlotThemeSubmenu(viewMenu, self);
    [menu setSubmenu:viewMenu forItem:viewItem];
    [menu addItem:viewItem];
    return FinalizeGraphContextMenu(menu);
}

- (void)rightMouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    [NSMenu popUpContextMenu:[self menuForEvent:event] withEvent:event forView:self];
}

- (BOOL)savePNGToPath:(NSString *)path
{
    NSData *data = [self visualExportDataForFormat:@"PNG"];
    return [data writeToFile:path atomically:YES];
}

- (BOOL)savePDFToPath:(NSString *)path
{
    NSData *data = [self visualExportDataForFormat:@"PDF"];
    return [data writeToFile:path atomically:YES];
}

- (NSData *)visualExportDataForFormat:(NSString *)format
{
    self.renderingForExport = YES;
    [self syncDensityAdjustControl];
    NSData *data = VisualExportDataForView(self, format);
    self.renderingForExport = NO;
    [self syncDensityAdjustControl];
    [self setNeedsDisplay:YES];
    return data;
}
@end

@implementation BoxplotView
- (instancetype)initWithModel:(PlotModel *)model
{
    self = [super initWithFrame:NSMakeRect(0, 0, 720, 520)];
    if (self) {
        self.model = model;
        self.dragging = NO;
        self.toolTipTag = 0;
        [self setWantsLayer:YES];
        self.connectionWidthControl = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 226, 32)];
        [self.connectionWidthControl setWantsLayer:YES];
        self.connectionWidthControl.layer.cornerRadius = 6.0;
        self.connectionWidthControl.layer.backgroundColor =
            [[NSColor controlBackgroundColor] colorWithAlphaComponent:0.92].CGColor;
        NSTextField *widthLabel = GLMLabel(@"Line width", NSMakeRect(8, 7, 64, 18), 10, NSFontWeightMedium);
        [self.connectionWidthControl addSubview:widthLabel];
        self.connectionWidthSlider = [[NSSlider alloc] initWithFrame:NSMakeRect(72, 4, 142, 24)];
        [self.connectionWidthSlider setMinValue:0.5];
        [self.connectionWidthSlider setMaxValue:8.0];
        [self.connectionWidthSlider setNumberOfTickMarks:16];
        [self.connectionWidthSlider setAllowsTickMarkValuesOnly:NO];
        [self.connectionWidthSlider setContinuous:YES];
        [self.connectionWidthSlider setTarget:self];
        [self.connectionWidthSlider setAction:@selector(connectionWidthChanged:)];
        [self.connectionWidthControl addSubview:self.connectionWidthSlider];
        [self addSubview:self.connectionWidthControl];
        PlotGestureOverlayView *gestureOverlay =
            [[PlotGestureOverlayView alloc] initWithFrame:[self bounds]];
        self.gestureOverlay = gestureOverlay;
        [self.gestureOverlay setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
        [self.gestureOverlay setWantsLayer:YES];
        [self.gestureOverlay setHidden:YES];
        [self addSubview:self.gestureOverlay];
        [gestureOverlay release];
        [self syncConnectionWidthControl];
    }
    return self;
}

- (void)layout
{
    [super layout];
    [self.gestureOverlay setFrame:[self bounds]];
    if (self.connectionWidthControl) {
        const NSRect bounds = [self bounds];
        [self.connectionWidthControl setFrameOrigin:NSMakePoint(
            std::max<CGFloat>(8.0, NSMaxX(bounds) - NSWidth(self.connectionWidthControl.frame) - 10.0), 8.0)];
    }
}

- (void)updateGestureOverlay
{
    if (!self.gestureOverlay) return;
    if (!self.dragging) {
        [self.gestureOverlay setHidden:YES];
        return;
    }
    const NSRect rect = rlispstat::platform::macos::ToNSRect(
        rlispstat::core::RectBetweenPoints(
            rlispstat::platform::macos::ToCorePoint(self.dragStart),
            rlispstat::platform::macos::ToCorePoint(self.dragCurrent)));
    self.gestureOverlay.gestureRect = rect;
    [self.gestureOverlay setHidden:NSIsEmptyRect(rect)];
    [self.gestureOverlay setNeedsDisplay:YES];
    [self.gestureOverlay displayIfNeeded];
}

- (void)syncConnectionWidthControl
{
    if (!self.connectionWidthControl || !self.model) return;
    [self.connectionWidthSlider setDoubleValue:std::max(0.5, std::min(8.0, self.model->boxplotConnectionLineWidth))];
    [self.connectionWidthControl setHidden:!self.model->boxplotShowConnectionWidthSlider ||
        !BoxplotUsesVariableAxes(self.model) || !self.model->boxplotConnectRows];
}

- (void)connectionWidthChanged:(id)sender
{
    if (!self.model) return;
    self.model->boxplotConnectionLineWidth =
        std::max(0.5, std::min(8.0, [(NSSlider *)sender doubleValue]));
    [self setNeedsDisplay:YES];
}

- (void)toggleConnectionWidthControl:(id)sender
{
    (void)sender;
    if (!self.model) return;
    self.model->boxplotShowConnectionWidthSlider = !self.model->boxplotShowConnectionWidthSlider;
    [self syncConnectionWidthControl];
    [self setNeedsDisplay:YES];
}

- (NSInteger)variableLabelIndexAtPoint:(NSPoint)point
{
    if (!self.model || !BoxplotUsesVariableAxes(self.model)) return -1;
    NSRect pr = [self plotRect];
    if (point.y < NSMaxY(pr) + 2.0 || point.y > NSMaxY(pr) + 32.0) return -1;
    NSDictionary *attrs = @{NSFontAttributeName: [NSFont systemFontOfSize:10]};
    for (size_t i = 0; i < self.model->boxplotCategories.size(); ++i) {
        const std::string &name = self.model->boxplotCategories[i];
        const CGFloat center = [self categoryX:name];
        const CGFloat half = std::max<CGFloat>(24.0,
            [ToNSString(name) sizeWithAttributes:attrs].width / 2.0 + 8.0);
        if (std::fabs(point.x - center) <= half) return (NSInteger)i;
    }
    return -1;
}

- (NSMenu *)variableMenuForIndex:(NSInteger)index
{
    if (!self.model || index < 0 || (size_t)index >= self.model->boxplotCategories.size()) return nil;
    if (!g_commandTarget) g_commandTarget = [[CommandTarget alloc] init];
    const std::string variable = self.model->boxplotCategories[(size_t)index];
    const std::vector<std::string> available = rlispstat::core::NumericVariableNames(self.model);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(variable)];
    NSMenuItem *heading = [[NSMenuItem alloc] initWithTitle:ToNSString(variable) action:nil keyEquivalent:@""];
    [heading setEnabled:NO];
    [menu addItem:heading];
    [menu addItem:[NSMenuItem separatorItem]];

    NSMenuItem *replaceRoot = [[NSMenuItem alloc] initWithTitle:@"Replace Variable" action:nil keyEquivalent:@""];
    NSMenu *replaceMenu = [[NSMenu alloc] initWithTitle:@"Replace Variable"];
    for (const std::string &candidate : available) {
        if (candidate == variable ||
            std::find(self.model->boxplotVariables.begin(), self.model->boxplotVariables.end(), candidate) !=
                self.model->boxplotVariables.end()) continue;
        [replaceMenu addItem:[self menuItem:ToNSString(candidate)
            command:ToNSString("BOXPLOT_REPLACE_VARIABLE|" + variable + "|" + candidate)]];
    }
    if ([replaceMenu numberOfItems] == 0) {
        NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:@"No available replacement" action:nil keyEquivalent:@""];
        [none setEnabled:NO];
        [replaceMenu addItem:none];
    }
    [replaceRoot setSubmenu:replaceMenu];
    [menu addItem:replaceRoot];

    NSMenuItem *remove = [self menuItem:[@"Remove " stringByAppendingString:ToNSString(variable)]
                                command:ToNSString("BOXPLOT_REMOVE_VARIABLE|" + variable)];
    [remove setEnabled:self.model->boxplotVariables.size() > 1];
    [menu addItem:remove];

    NSMenuItem *addRoot = [[NSMenuItem alloc] initWithTitle:@"Add Variable" action:nil keyEquivalent:@""];
    NSMenu *addMenu = [[NSMenu alloc] initWithTitle:@"Add Variable"];
    for (const std::string &candidate : available) {
        if (std::find(self.model->boxplotVariables.begin(), self.model->boxplotVariables.end(), candidate) !=
            self.model->boxplotVariables.end()) continue;
        [addMenu addItem:[self menuItem:ToNSString(candidate)
            command:ToNSString("BOXPLOT_ADD_VARIABLE|" + candidate)]];
    }
    if ([addMenu numberOfItems] == 0) {
        NSMenuItem *none = [[NSMenuItem alloc] initWithTitle:@"No more numeric variables" action:nil keyEquivalent:@""];
        [none setEnabled:NO];
        [addMenu addItem:none];
    }
    [addRoot setSubmenu:addMenu];
    [menu addItem:addRoot];
    return menu;
}

- (void)updateTrackingAreas
{
    [super updateTrackingAreas];
    if (self.toolTipTag != 0) [self removeToolTip:self.toolTipTag];
    self.toolTipTag = [self addToolTipRect:[self bounds] owner:self userData:NULL];
}

- (NSString *)view:(NSView *)view stringForToolTip:(NSToolTipTag)tag point:(NSPoint)point userData:(void *)data
{
    (void)view; (void)tag; (void)data;
    std::vector<rlispstat::core::BoxplotCaseGeometry> geometry =
        rlispstat::core::BoxplotCaseGeometryForLayout([self boxplotLayout], [self boxplotCasesForCore]);
    std::optional<rlispstat::core::CaseId> nearest = rlispstat::core::NearestBoxplotCaseToPoint(
        geometry, rlispstat::platform::macos::ToCorePoint(point), 7.0);
    if (nearest.has_value()) {
        for (const auto &item : geometry) {
            if (item.caseId == *nearest) {
                return ToNSString("Row: " + std::to_string(item.caseId) + "\nGroup: " + item.category +
                                  "\nValue: " + FormatModelNumberOrDash(item.value));
            }
        }
    }
    std::vector<BoxplotStats> stats = BoxplotStatsForModel(*self.model);
    std::vector<BoxplotStatsRenderItem> plan = BuildBoxplotStatsRenderPlan([self boxplotLayout], stats);
    for (const BoxplotStatsRenderItem &item : plan) {
        NSRect hit = NSInsetRect(rlispstat::platform::macos::ToNSRect(item.boxRect), -6.0, -6.0);
        if (!NSPointInRect(point, hit)) continue;
        auto stat = std::find_if(stats.begin(), stats.end(), [&](const BoxplotStats &candidate) {
            return candidate.category == item.category;
        });
        if (stat == stats.end()) continue;
        return ToNSString("Group: " + stat->category + "\nN: " + std::to_string(stat->n) +
                          "\nMedian: " + FormatModelNumberOrDash(stat->median) +
                          "\nQ1: " + FormatModelNumberOrDash(stat->q1) +
                          "\nQ3: " + FormatModelNumberOrDash(stat->q3));
    }
    return nil;
}

- (BOOL)acceptsFirstResponder { return YES; }
- (BOOL)isFlipped { return YES; }

- (NSRect)plotRect
{
    NSRect b = [self bounds];
    return NSMakeRect(72, 42, std::max(10.0, b.size.width - 112), std::max(10.0, b.size.height - 112));
}

- (rlispstat::core::BoxplotLayout)boxplotLayout
{
    rlispstat::core::BoxplotLayout layout;
    layout.plotRect = rlispstat::platform::macos::ToCoreRect([self plotRect]);
    layout.categories = self.model->boxplotCategories;
    std::vector<rlispstat::core::BoxplotCase> cases = [self boxplotCasesForCore];
    BoxplotDisplayRange range = BoxplotDisplayRangeForCases(
        cases,
        self.model->boxplotShowH0Simulation,
        self.model->boxplotH0Values,
        self.model->boxplotH0ReferenceLines,
        self.model->boxplotH0Lower,
        self.model->boxplotH0Upper);
    layout.yMinimum = range.minimum;
    layout.yMaximum = range.maximum;
    layout.variableAxes = BoxplotUsesVariableAxes(self.model);
    layout.connectRows = self.model->boxplotConnectRows;
    return layout;
}

- (std::vector<rlispstat::core::BoxplotCase>)boxplotCasesForCore
{
    return BoxplotCasesForModel(*self.model);
}

- (double)screenY:(double)y
{
    rlispstat::core::BoxplotLayout layout = [self boxplotLayout];
    rlispstat::core::Point screen = rlispstat::core::DataToScreen(
        {0.5, y},
        rlispstat::core::BoxplotViewport(layout),
        layout.plotRect,
        true);
    return screen.y;
}

- (double)categoryX:(const std::string &)category
{
    return rlispstat::core::BoxplotCategoryCenter([self boxplotLayout], category);
}

- (void)drawH0SimulationLayerInRect:(NSRect)pr slotCount:(size_t)boxplotSlotCount smallAttrs:(NSDictionary *)smallAttrs
{
    (void)smallAttrs;
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    if (!self.model->boxplotShowH0Simulation || self.model->boxplotH0Values.size() < 2) return;
    std::vector<double> values = self.model->boxplotH0Values;
    double ymin = *std::min_element(values.begin(), values.end());
    double ymax = *std::max_element(values.begin(), values.end());
    if (ymin == ymax) {
        ymin -= 0.5;
        ymax += 0.5;
    }
    HistogramDensityCurve curve = DensityCurveForValues(values, "h0", "", self.model->boxplotH0Label, ymin, ymax, 0.0, 1.0);
    if (curve.x.size() < 2 || curve.y.size() != curve.x.size()) return;
    double maxDensity = *std::max_element(curve.y.begin(), curve.y.end());
    if (!(maxDensity > 0.0) || !std::isfinite(maxDensity)) return;

    double cx = BoxplotH0SimulationCenterX([self boxplotLayout]);
    double slotWidth = pr.size.width / std::max<size_t>(1, boxplotSlotCount);
    double boxWidth = std::max(32.0, std::min(74.0, slotWidth * 0.45));
    double maxWidth = std::max(12.0, std::min(30.0, boxWidth * 0.34));

    auto drawH0Interval = [&](double lower, double upper, NSColor *fill, NSColor *stroke, CGFloat lineWidth) {
        std::vector<size_t> indices;
        for (size_t i = 0; i < curve.x.size(); ++i) {
            if (curve.x[i] >= lower && curve.x[i] <= upper && std::isfinite(curve.y[i])) {
                indices.push_back(i);
            }
        }
        if (indices.size() < 2) return;
        NSBezierPath *path = [NSBezierPath bezierPath];
        bool started = false;
        for (size_t idx : indices) {
            double halfWidth = maxWidth * (curve.y[idx] / maxDensity);
            NSPoint pt = NSMakePoint(cx - halfWidth, [self screenY:curve.x[idx]]);
            if (!started) {
                [path moveToPoint:pt];
                started = true;
            } else {
                [path lineToPoint:pt];
            }
        }
        for (auto it = indices.rbegin(); it != indices.rend(); ++it) {
            size_t idx = *it;
            double halfWidth = maxWidth * (curve.y[idx] / maxDensity);
            [path lineToPoint:NSMakePoint(cx + halfWidth, [self screenY:curve.x[idx]])];
        }
        [path closePath];
        [fill setFill];
        [path fill];
        if (stroke) {
            [path setLineWidth:lineWidth];
            [stroke setStroke];
            [path stroke];
        }
    };

    NSColor *mainFill = theme.coordinatedMarks ? [theme.markFill colorWithAlphaComponent:0.42] : [NSColor colorWithCalibratedWhite:0.0 alpha:0.42];
    NSColor *mainStroke = theme.coordinatedMarks ? [theme.markStroke colorWithAlphaComponent:0.64] : [NSColor colorWithCalibratedWhite:0.0 alpha:0.64];
    NSColor *tailFill = theme.coordinatedMarks ? [theme.geomFill colorWithAlphaComponent:0.82] : [NSColor colorWithCalibratedRed:1.0 green:1.0 blue:0.0 alpha:0.82];
    NSColor *tailStroke = theme.coordinatedMarks ? theme.reference : [NSColor colorWithCalibratedRed:0.78 green:0.68 blue:0.0 alpha:0.90];
    drawH0Interval(ymin, ymax, mainFill, mainStroke, 1.0);
    std::string alternative = self.model->boxplotH0Alternative;
    for (const BoxplotValueInterval &interval : BoxplotTailIntervalsForAlternative(
             ymin,
             ymax,
             self.model->boxplotH0Lower,
             self.model->boxplotH0Upper,
             alternative)) {
        drawH0Interval(interval.lower, interval.upper, tailFill, tailStroke, 1.1);
    }

    BOOL twoGroups = self.model->boxplotCategories.size() == 2 && !BoxplotUsesVariableAxes(self.model);
    NSArray *lineColors = theme.coordinatedMarks ? @[theme.geomStroke, theme.auxiliary] : (twoGroups ? @[
        [NSColor colorWithCalibratedRed:0.973 green:0.463 blue:0.427 alpha:0.96],
        [NSColor colorWithCalibratedRed:0.000 green:0.737 blue:0.769 alpha:0.96]
    ] : @[
        [NSColor colorWithCalibratedRed:0.00 green:0.22 blue:0.88 alpha:0.96],
        [NSColor colorWithCalibratedRed:1.00 green:0.50 blue:0.00 alpha:0.96]
    ]);
    for (size_t i = 0; i < self.model->boxplotH0ReferenceLines.size(); ++i) {
        double y = self.model->boxplotH0ReferenceLines[i];
        if (!std::isfinite(y)) continue;
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line setLineWidth:1.8];
        [line moveToPoint:NSMakePoint(cx - maxWidth * 0.80, [self screenY:y])];
        [line lineToPoint:NSMakePoint(cx + maxWidth * 0.80, [self screenY:y])];
        [(NSColor *)lineColors[MIN((NSUInteger)i, (NSUInteger)[lineColors count] - 1)] setStroke];
        [line stroke];
    }

    NSDictionary *pAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: (theme.coordinatedMarks ? theme.text : [NSColor colorWithCalibratedRed:0.00 green:0.18 blue:0.75 alpha:1.0])
    };
    NSColor *pTopColor = theme.coordinatedMarks ? theme.reference : [NSColor colorWithCalibratedRed:1.00 green:0.88 blue:0.00 alpha:0.96];
    NSColor *pBottomColor = theme.coordinatedMarks ? theme.reference : [NSColor colorWithCalibratedRed:0.86 green:0.00 blue:0.00 alpha:0.96];
    NSColor *pStemColor = theme.coordinatedMarks ? theme.reference : [NSColor colorWithCalibratedRed:0.00 green:0.56 blue:0.00 alpha:0.96];
    auto drawPBracket = [&](double lower, double upper, NSString *label) {
        if (!std::isfinite(lower) || !std::isfinite(upper) || lower == upper) return;
        double yTop = std::min([self screenY:lower], [self screenY:upper]);
        double yBottom = std::max([self screenY:lower], [self screenY:upper]);
        double x = std::max(pr.origin.x + 4.0, cx - maxWidth - 18.0);
        double cap = 7.0;
        NSBezierPath *top = [NSBezierPath bezierPath];
        [top setLineWidth:1.25];
        [top moveToPoint:NSMakePoint(x, yTop)];
        [top lineToPoint:NSMakePoint(x + cap, yTop)];
        [pTopColor setStroke];
        [top stroke];
        NSBezierPath *stem = [NSBezierPath bezierPath];
        [stem setLineWidth:1.25];
        [stem moveToPoint:NSMakePoint(x, yTop)];
        [stem lineToPoint:NSMakePoint(x, yBottom)];
        [pStemColor setStroke];
        [stem stroke];
        NSBezierPath *bottom = [NSBezierPath bezierPath];
        [bottom setLineWidth:1.25];
        [bottom moveToPoint:NSMakePoint(x, yBottom)];
        [bottom lineToPoint:NSMakePoint(x + cap, yBottom)];
        [pBottomColor setStroke];
        [bottom stroke];
        NSSize labelSize = [label sizeWithAttributes:pAttrs];
        double yMid = (yTop + yBottom - labelSize.height) / 2.0;
        yMid = std::max(pr.origin.y + 2.0, std::min(pr.origin.y + pr.size.height - labelSize.height - 2.0, yMid));
        [label drawAtPoint:NSMakePoint(std::max(pr.origin.x + 2.0, x - labelSize.width - 4.0), yMid)
            withAttributes:pAttrs];
    };
    NSString *pLabel = ToNSString("p = " + FormatPValue(self.model->boxplotH0PValue));
    if (alternative == "two.sided") {
        if (std::isfinite(self.model->boxplotH0Lower)) drawPBracket(ymin, std::min(self.model->boxplotH0Lower, ymax), ToNSString(rlispstat::core::BoxplotPBracketLabel()));
        if (std::isfinite(self.model->boxplotH0Upper)) drawPBracket(std::max(self.model->boxplotH0Upper, ymin), ymax, ToNSString(rlispstat::core::BoxplotPBracketLabel()));
    } else if (alternative == "greater") {
        if (std::isfinite(self.model->boxplotH0Lower)) drawPBracket(std::max(self.model->boxplotH0Lower, ymin), ymax, pLabel);
    } else {
        if (std::isfinite(self.model->boxplotH0Lower)) drawPBracket(ymin, std::min(self.model->boxplotH0Lower, ymax), pLabel);
    }

    std::vector<double> markerLabelYs;
    auto drawRightMarker = [&](double y, NSString *label, NSColor *color, BOOL dashed) {
        if (!std::isfinite(y)) return;
        double sy = [self screenY:y];
        sy = std::max(pr.origin.y + 3.0, std::min(pr.origin.y + pr.size.height - 3.0, sy));
        NSDictionary *markerAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightSemibold],
            NSForegroundColorAttributeName: color
        };
        NSSize labelSize = [label sizeWithAttributes:markerAttrs];
        double pointerX = cx + maxWidth * 0.95;
        double labelX = cx + maxWidth + 28.0;
        double maxLabelX = [self bounds].size.width - labelSize.width - 4.0;
        if (labelX > maxLabelX) {
            labelX = maxLabelX;
        }
        double labelY = sy - labelSize.height / 2.0;
        for (double usedY : markerLabelYs) {
            if (std::fabs(labelY - usedY) < labelSize.height + 2.0) {
                labelY = usedY + labelSize.height + 2.0;
            }
        }
        labelY = std::max(pr.origin.y + 2.0, std::min(pr.origin.y + pr.size.height - labelSize.height - 2.0, labelY));
        markerLabelYs.push_back(labelY);
        double labelMidY = labelY + labelSize.height / 2.0;
        double lineEndX = std::max(pointerX + 4.0, labelX - 5.0);
        NSBezierPath *pointer = [NSBezierPath bezierPath];
        [pointer setLineWidth:1.6];
        if (dashed) {
            CGFloat pattern[] = { 3.0, 2.0 };
            [pointer setLineDash:pattern count:2 phase:0.0];
        }
        [pointer moveToPoint:NSMakePoint(pointerX, sy)];
        [pointer lineToPoint:NSMakePoint(lineEndX, labelMidY)];
        [color setStroke];
        [pointer stroke];
        [color setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(pointerX - 2.2, sy - 2.2, 4.4, 4.4)] fill];
        [label drawAtPoint:NSMakePoint(labelX, labelY) withAttributes:markerAttrs];
    };
    NSColor *meanMarkerColor = theme.coordinatedMarks ? theme.auxiliary : [NSColor colorWithCalibratedRed:0.00 green:0.22 blue:0.88 alpha:0.98];
    NSColor *h0MarkerColor = theme.coordinatedMarks ? theme.reference : [NSColor colorWithCalibratedRed:1.00 green:0.50 blue:0.00 alpha:0.98];
    if (!twoGroups && self.model->boxplotH0ReferenceLines.size() >= 2) {
        double observedMean = self.model->boxplotH0ReferenceLines[0];
        double h0Value = self.model->boxplotH0ReferenceLines[1];
        drawRightMarker(observedMean, ToNSString("x̄ = " + FormatDoubleOrDash(observedMean, 2)), meanMarkerColor, NO);
        drawRightMarker(h0Value, ToNSString("μ₀ = " + FormatDoubleOrDash(h0Value, 2)), h0MarkerColor, YES);
    } else if (twoGroups && self.model->boxplotH0ReferenceLines.size() >= 2) {
        double mean1 = self.model->boxplotH0ReferenceLines[0];
        double mean2 = self.model->boxplotH0ReferenceLines[1];
        drawRightMarker(mean1, ToNSString("x̄₁ = " + FormatDoubleOrDash(mean1, 2)), (NSColor *)lineColors[0], NO);
        drawRightMarker(mean2, ToNSString("x̄₂ = " + FormatDoubleOrDash(mean2, 2)), (NSColor *)lineColors[1], NO);
    }

    NSDictionary *leafAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: (theme.coordinatedMarks ? theme.text : [NSColor colorWithCalibratedWhite:0.18 alpha:1.0])
    };
    NSString *leaf = ToNSString(rlispstat::core::BoxplotLeafLabel());
    NSSize leafSize = [leaf sizeWithAttributes:leafAttrs];
    [leaf drawAtPoint:NSMakePoint(cx - leafSize.width / 2.0, pr.origin.y + 23.0) withAttributes:leafAttrs];

    std::string pText = FormatPValue(self.model->boxplotH0PValue);
    NSString *summary = ToNSString(self.model->boxplotH0Label + "  p = " + pText);
    NSDictionary *h0Attrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: (theme.coordinatedMarks ? theme.text : [NSColor colorWithCalibratedWhite:0.18 alpha:1.0])
    };
    NSSize summarySize = [summary sizeWithAttributes:h0Attrs];
    [summary drawAtPoint:NSMakePoint(cx - summarySize.width / 2.0, pr.origin.y + 8.0) withAttributes:h0Attrs];

    std::string parameter = twoGroups ? "μ₁ − μ₂" : "μ";
    std::string nullParameter = twoGroups ? "Δ₀" : "μ₀";
    std::string h0 = FormatDoubleOrDash(self.model->boxplotH0, 3);
    std::string hypothesis;
    if (alternative == "two.sided") {
        hypothesis = "H₀: " + parameter + " = " + nullParameter + "; H₁: " + parameter + " ≠ " + nullParameter;
    } else if (alternative == "greater") {
        hypothesis = "H₀: " + parameter + " ≤ " + nullParameter + "; H₁: " + parameter + " > " + nullParameter;
    } else {
        hypothesis = "H₀: " + parameter + " ≥ " + nullParameter + "; H₁: " + parameter + " < " + nullParameter;
    }
    hypothesis += "  (" + nullParameter + " = " + h0 + ")";
    NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
    [style setLineBreakMode:NSLineBreakByTruncatingTail];
    NSDictionary *hypAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10],
        NSForegroundColorAttributeName: (theme.coordinatedMarks ? theme.mutedText : [NSColor colorWithCalibratedWhite:0.24 alpha:1.0]),
        NSParagraphStyleAttributeName: style
    };
    [ToNSString(hypothesis) drawInRect:NSMakeRect(pr.origin.x, pr.origin.y + pr.size.height + 27.0, pr.size.width, 14.0)
                        withAttributes:hypAttrs];
}

- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    PlotThemeOverrideScope snapshotTheme(self.snapshotThemeName ?: PlotLocalThemeName(self));
    [self syncConnectionWidthControl];
    PlotThemeStyle theme = CurrentPlotThemeStyle();
    [theme.background setFill];
    NSRectFill([self bounds]);
    NSRect pr = [self plotRect];
    [theme.panel setFill];
    NSRectFill(pr);

    NSDictionary *labelAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:12 weight:NSFontWeightMedium],
        NSForegroundColorAttributeName: theme.text
    };
    NSDictionary *smallAttrs = @{
        NSFontAttributeName: [NSFont systemFontOfSize:10],
        NSForegroundColorAttributeName: theme.mutedText
    };
    rlispstat::core::BoxplotLayout axisLayout = [self boxplotLayout];
    rlispstat::core::DataViewport axisViewport = rlispstat::core::BoxplotViewport(axisLayout);
    for (const rlispstat::core::BoxplotAxisTick &tick :
         rlispstat::core::BoxplotYAxisTicks(axisViewport.ymin, axisViewport.ymax, 5)) {
        double y = [self screenY:tick.value];
        [theme.majorGrid setStroke];
        NSBezierPath *grid = [NSBezierPath bezierPath];
        [grid moveToPoint:NSMakePoint(pr.origin.x, y)];
        [grid lineToPoint:NSMakePoint(NSMaxX(pr), y)];
        [grid stroke];
        NSString *label = ToNSString(tick.label);
        NSSize size = [label sizeWithAttributes:smallAttrs];
        [label drawAtPoint:NSMakePoint(pr.origin.x - size.width - 7.0, y - size.height / 2.0)
            withAttributes:smallAttrs];
        [theme.axis setStroke];
        NSBezierPath *mark = [NSBezierPath bezierPath];
        [mark moveToPoint:NSMakePoint(pr.origin.x - 4.0, y)];
        [mark lineToPoint:NSMakePoint(pr.origin.x, y)];
        [mark stroke];
    }
    [theme.axis setStroke];
    NSBezierPath *axes = [NSBezierPath bezierPath];
    [axes moveToPoint:NSMakePoint(pr.origin.x, pr.origin.y)];
    [axes lineToPoint:NSMakePoint(pr.origin.x, NSMaxY(pr))];
    [axes lineToPoint:NSMakePoint(NSMaxX(pr), NSMaxY(pr))];
    [axes stroke];
    if (!self.model->yLabel.empty()) {
        NSString *yTitle = ToNSString(self.model->yLabel);
        NSDictionary *axisTitleAttrs = @{
            NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightMedium],
            NSForegroundColorAttributeName: theme.text
        };
        NSSize titleSize = [yTitle sizeWithAttributes:axisTitleAttrs];
        [NSGraphicsContext saveGraphicsState];
        NSAffineTransform *transform = [NSAffineTransform transform];
        [transform translateXBy:18.0 yBy:NSMidY(pr) + titleSize.width / 2.0];
        [transform rotateByDegrees:-90.0];
        [transform concat];
        [yTitle drawAtPoint:NSZeroPoint withAttributes:axisTitleAttrs];
        [NSGraphicsContext restoreGraphicsState];
    }
    if (!self.model->title.empty()) {
        NSMutableParagraphStyle *titleStyle = [[NSMutableParagraphStyle alloc] init];
        [titleStyle setAlignment:NSTextAlignmentCenter];
        [titleStyle setLineBreakMode:NSLineBreakByTruncatingTail];
        NSMutableDictionary *centeredTitleAttrs = [labelAttrs mutableCopy];
        [centeredTitleAttrs setObject:titleStyle forKey:NSParagraphStyleAttributeName];
        [ToNSString(self.model->title) drawInRect:NSMakeRect(pr.origin.x, 10, pr.size.width, 20)
                                   withAttributes:centeredTitleAttrs];
    }
    DrawPlotImputationDisplayStatus(self.model, false, pr, 30.0);
    size_t boxplotSlotCount = self.model->boxplotCategories.size();

    if (self.model->boxplotShowViolin || self.model->boxplotSplitViolin) {
        double violinMaxWidth = std::max(28.0, std::min(92.0, pr.size.width / std::max<size_t>(1, boxplotSlotCount) * 0.34));
        for (const std::string &category : self.model->boxplotCategories) {
            std::vector<double> values;
            for (const BoxplotPoint &p : self.model->boxplotPoints) {
                if (p.category == category && std::isfinite(p.y)) {
                    values.push_back(p.y);
                }
            }
            if (values.size() < 2) continue;
            double ymin = *std::min_element(values.begin(), values.end());
            double ymax = *std::max_element(values.begin(), values.end());
            if (ymin == ymax) {
                ymin -= 0.5;
                ymax += 0.5;
            }
            HistogramDensityCurve curve = DensityCurveForValues(values, "boxplot", "", category, ymin, ymax, 0.0, 1.0);
            if (curve.x.size() < 2 || curve.y.size() != curve.x.size()) continue;
            double maxDensity = *std::max_element(curve.y.begin(), curve.y.end());
            if (!(maxDensity > 0.0) || !std::isfinite(maxDensity)) continue;
            double cx = [self categoryX:category];

            auto drawInterval = [&](double lower, double upper, NSColor *fill, NSColor *stroke, CGFloat lineWidth) {
                NSBezierPath *path = [NSBezierPath bezierPath];
                bool started = false;
                std::vector<size_t> indices;
                for (size_t i = 0; i < curve.x.size(); ++i) {
                    if (curve.x[i] >= lower && curve.x[i] <= upper && std::isfinite(curve.y[i])) {
                        indices.push_back(i);
                    }
                }
                if (indices.size() < 2) return;
                for (size_t idx : indices) {
                    double halfWidth = violinMaxWidth * (curve.y[idx] / maxDensity);
                    NSPoint pt = NSMakePoint(cx - halfWidth, [self screenY:curve.x[idx]]);
                    if (!started) {
                        [path moveToPoint:pt];
                        started = true;
                    } else {
                        [path lineToPoint:pt];
                    }
                }
                for (auto it = indices.rbegin(); it != indices.rend(); ++it) {
                    size_t idx = *it;
                    double halfWidth = violinMaxWidth * (curve.y[idx] / maxDensity);
                    [path lineToPoint:NSMakePoint(cx + halfWidth, [self screenY:curve.x[idx]])];
                }
                [path closePath];
                [fill setFill];
                [path fill];
                if (stroke) {
                    [path setLineWidth:lineWidth];
                    [stroke setStroke];
                    [path stroke];
                }
            };

            NSColor *baseFill = [theme.geomFill colorWithAlphaComponent:0.36];
            NSColor *baseStroke = [theme.geomStroke colorWithAlphaComponent:0.42];
            drawInterval(ymin, ymax, baseFill, baseStroke, 0.8);
            if (self.model->boxplotSplitViolin) {
                NSColor *tailFill = [theme.accent2 colorWithAlphaComponent:0.62];
                NSColor *tailStroke = [theme.accent colorWithAlphaComponent:0.72];
                for (const BoxplotValueInterval &interval : BoxplotTailIntervalsForAlternative(
                         ymin,
                         ymax,
                         self.model->boxplotSplitLower,
                         self.model->boxplotSplitUpper,
                         self.model->boxplotSplitAlternative)) {
                    drawInterval(interval.lower, interval.upper, tailFill, tailStroke, 1.0);
                }
            }
        }
    }

    std::vector<BoxplotStats> stats = BoxplotStatsForModel(*self.model);
    std::vector<BoxplotStatsRenderItem> statsRenderPlan =
        BuildBoxplotStatsRenderPlan([self boxplotLayout], stats);
    for (const BoxplotStatsRenderItem &s : statsRenderPlan) {
        if (self.model->boxplotShowWhiskers) {
            NSBezierPath *whiskers = [NSBezierPath bezierPath];
            [whiskers setLineWidth:1.3];
            [whiskers moveToPoint:rlispstat::platform::macos::ToNSPoint(s.upperWhiskerStart)];
            [whiskers lineToPoint:rlispstat::platform::macos::ToNSPoint(s.upperWhiskerEnd)];
            [whiskers moveToPoint:rlispstat::platform::macos::ToNSPoint(s.lowerWhiskerStart)];
            [whiskers lineToPoint:rlispstat::platform::macos::ToNSPoint(s.lowerWhiskerEnd)];
            [whiskers moveToPoint:rlispstat::platform::macos::ToNSPoint(s.upperCapStart)];
            [whiskers lineToPoint:rlispstat::platform::macos::ToNSPoint(s.upperCapEnd)];
            [whiskers moveToPoint:rlispstat::platform::macos::ToNSPoint(s.lowerCapStart)];
            [whiskers lineToPoint:rlispstat::platform::macos::ToNSPoint(s.lowerCapEnd)];
            [theme.geomStroke setStroke];
            [whiskers stroke];
        }
        if (self.model->boxplotShowBox) {
            NSRect box = rlispstat::platform::macos::ToNSRect(s.boxRect);
            [theme.geomFill setFill];
            NSRectFillUsingOperation(box, NSCompositingOperationSourceOver);
            [theme.geomStroke setStroke];
            NSFrameRectWithWidth(box, 1.4);
            NSBezierPath *median = [NSBezierPath bezierPath];
            [median setLineWidth:2.0];
            [median moveToPoint:rlispstat::platform::macos::ToNSPoint(s.medianStart)];
            [median lineToPoint:rlispstat::platform::macos::ToNSPoint(s.medianEnd)];
            [theme.accent setStroke];
            [median stroke];
        }
        NSString *cat = ToNSString(s.category);
        NSSize size = [cat sizeWithAttributes:smallAttrs];
        [cat drawAtPoint:NSMakePoint(s.centerX - size.width / 2.0, pr.origin.y + pr.size.height + 8) withAttributes:smallAttrs];
    }

    [self drawH0SimulationLayerInRect:pr slotCount:boxplotSlotCount smallAttrs:smallAttrs];

    std::set<int> selection;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        auto it = g_groupSelections.find(self.model->group);
        if (it != g_groupSelections.end()) selection = it->second;
    }
    std::vector<rlispstat::core::BoxplotCaseGeometry> pointGeometry =
        rlispstat::core::BoxplotCaseGeometryForLayout([self boxplotLayout], [self boxplotCasesForCore]);
    std::vector<BoxplotConnectionLine> connectionPlan = BuildBoxplotConnectionLinePlan(
        pointGeometry,
        self.model->boxplotCategories,
        selection,
        BoxplotUsesVariableAxes(self.model),
        self.model->boxplotConnectRows);
    auto drawConnection = [&](const BoxplotConnectionLine &connection) {
        const std::string rowColor = RowColorForPlot(self.model, connection.caseId);
        const CGFloat lineWidth = (CGFloat)BoxplotConnectionStrokeWidth(
            self.model->boxplotConnectionLineWidth, connection.selected);
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line setLineWidth:lineWidth];
        [line setLineCapStyle:NSLineCapStyleRound];
        [line setLineJoinStyle:NSLineJoinStyleRound];
        bool started = false;
        for (const rlispstat::core::Point &point : connection.points) {
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(point);
            if (!started) {
                [line moveToPoint:sp];
                started = true;
            } else {
                [line lineToPoint:sp];
            }
        }
        NSColor *connectionColor = nil;
        if (!rowColor.empty()) {
            // Use exactly the same light/intense pair as the data sheet.
            connectionColor = BarplotDataSheetToneColor(rowColor, connection.selected, 0.96);
        } else {
            connectionColor = connection.selected
                ? [theme.selectedMarkFill colorWithAlphaComponent:0.96]
                : [theme.markStroke colorWithAlphaComponent:connection.dimmed ? 0.18 : 0.42];
        }
        [connectionColor setStroke];
        [line stroke];
    };
    // Selected rows are drawn last, but keep the same line width as unselected rows.
    for (const BoxplotConnectionLine &connection : connectionPlan) {
        if (!connection.selected) drawConnection(connection);
    }
    for (const BoxplotConnectionLine &connection : connectionPlan) {
        if (connection.selected) drawConnection(connection);
    }
    if (self.model->boxplotShowPoints) {
        std::vector<BoxplotPointDrawItem> pointPlan = BuildBoxplotPointDrawPlan(pointGeometry, selection);
        for (const BoxplotPointDrawItem &pointItem : pointPlan) {
            NSPoint sp = rlispstat::platform::macos::ToNSPoint(pointItem.point);
            std::string rowColor = RowColorForPlot(self.model, pointItem.caseId);
            const CGFloat radius = 3.2;
            if (pointItem.selected) DrawPointSelectionRing(theme, sp, radius,
                !rowColor.empty() ? ColorForName(rowColor, 1.0) : theme.selectedMarkFill);
            NSBezierPath *dot = PlotThemeMarkPath(theme, sp, radius, pointItem.selected);
            if (pointItem.selected) {
                [(!rowColor.empty() ? ColorForName(rowColor, 1.0) :
                    (theme.coordinatedMarks ? theme.selectedMarkFill : ColorForName(DisplayColorForPoint(self.model->group, pointItem.caseId), 1.0))) setFill];
                [dot fill];
                [(theme.coordinatedMarks ? theme.selectedMarkStroke : [NSColor colorWithCalibratedWhite:0.58 alpha:0.96]) setStroke];
                [dot setLineWidth:theme.coordinatedMarks ? (CGFloat)theme.selectedMarkStrokeWidth : 1.5];
                [dot stroke];
            } else {
                NSColor *fill = !theme.coordinatedMarks || !rowColor.empty()
                    ? ColorForName(rowColor.empty() ? "black" : rowColor, pointItem.dimmed ? 0.24 : 0.72)
                    : (theme.hollowUnselectedMarks ? theme.panel : theme.markFill);
                [fill setFill];
                [dot fill];
                if (theme.coordinatedMarks) {
                    [(!rowColor.empty() ? ColorForName(rowColor, 0.90) : theme.markStroke) setStroke];
                    [dot setLineWidth:1.0];
                    [dot stroke];
                }
            }
        }
    }
    if (self.dragging && !self.gestureOverlay) {
        NSRect rr = rlispstat::platform::macos::ToNSRect(
            rlispstat::core::RectBetweenPoints(
                rlispstat::platform::macos::ToCorePoint(self.dragStart),
                rlispstat::platform::macos::ToCorePoint(self.dragCurrent)));
        [[theme.accent colorWithAlphaComponent:0.16] setFill];
        NSRectFillUsingOperation(rr, NSCompositingOperationSourceOver);
        [[theme.accent colorWithAlphaComponent:0.95] setStroke];
        NSFrameRect(rr);
    }
    if (theme.showPanelBorder) {
        NSBezierPath *border = [NSBezierPath bezierPathWithRect:NSInsetRect(pr, 0.5, 0.5)];
        [border setLineWidth:1.0];
        [theme.axis setStroke];
        [border stroke];
    }
    DrawColorLegend(self.model, [self bounds], theme);
}

- (void)mouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    NSPoint initialPoint = [self convertPoint:[event locationInWindow] fromView:nil];
    if (HandleColorLegendMouseDown(self, self.model, event)) return;
    const NSInteger variableIndex = [self variableLabelIndexAtPoint:initialPoint];
    if (variableIndex >= 0) {
        NSMenu *variableMenu = [self variableMenuForIndex:variableIndex];
        if (variableMenu) [NSMenu popUpContextMenu:variableMenu withEvent:event forView:self];
        return;
    }
    self.dragging = YES;
    self.dragStart = initialPoint;
    self.dragCurrent = self.dragStart;
    [self updateGestureOverlay];

    while (self.dragging) {
        NSEvent *trackingEvent = [[self window] nextEventMatchingMask:(NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                                                            untilDate:[NSDate distantFuture]
                                                               inMode:NSEventTrackingRunLoopMode
                                                              dequeue:YES];
        if (!trackingEvent) {
            break;
        }
        if ([trackingEvent type] == NSEventTypeLeftMouseDragged) {
            // Keep the newest position, but never consume the mouse-up event.
            for (;;) {
                NSEvent *pending = [[self window] nextEventMatchingMask:
                    (NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                    untilDate:[NSDate distantPast]
                       inMode:NSEventTrackingRunLoopMode dequeue:NO];
                if (!pending || pending.type != NSEventTypeLeftMouseDragged) break;
                trackingEvent = [[self window] nextEventMatchingMask:
                    (NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp)
                    untilDate:[NSDate distantPast]
                       inMode:NSEventTrackingRunLoopMode dequeue:YES];
            }
            [self mouseDragged:trackingEvent];
        } else if ([trackingEvent type] == NSEventTypeLeftMouseUp) {
            [self finishDragWithEvent:trackingEvent];
            break;
        }
    }
    if (self.dragging) {
        self.dragging = NO;
        [self.gestureOverlay setHidden:YES];
        self.gestureOverlay.gestureRect = NSZeroRect;
    }
}

- (void)mouseDragged:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    [self updateGestureOverlay];
}

- (void)mouseUp:(NSEvent *)event
{
    [self finishDragWithEvent:event];
}

- (void)finishDragWithEvent:(NSEvent *)event
{
    self.dragCurrent = [self convertPoint:[event locationInWindow] fromView:nil];
    if (!self.dragging) {
        [self setNeedsDisplay:YES];
        return;
    }
    self.dragging = NO;
    [self.gestureOverlay setHidden:YES];
    self.gestureOverlay.gestureRect = NSZeroRect;
    std::string mode = EffectiveSelectionMode(self.model, [event modifierFlags]);
    rlispstat::core::Rect brush = rlispstat::core::RectBetweenPoints(
        rlispstat::platform::macos::ToCorePoint(self.dragStart),
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent));
    bool dragBrush = rlispstat::core::RectMeetsMinimumSize(brush, 3.0, 3.0);
    std::vector<rlispstat::core::BoxplotCaseGeometry> geometry =
        rlispstat::core::BoxplotCaseGeometryForLayout([self boxplotLayout], [self boxplotCasesForCore]);
    std::set<int> selected = rlispstat::core::SelectBoxplotCasesForGesture(
        geometry,
        brush,
        rlispstat::platform::macos::ToCorePoint(self.dragCurrent),
        dragBrush);
    if (!dragBrush && selected.empty()) {
        std::vector<BoxplotStats> stats = BoxplotStatsForModel(*self.model);
        std::vector<BoxplotStatsRenderItem> statsPlan = BuildBoxplotStatsRenderPlan([self boxplotLayout], stats);
        for (const BoxplotStatsRenderItem &item : statsPlan) {
            NSRect hit = NSInsetRect(rlispstat::platform::macos::ToNSRect(item.boxRect), -6.0, -6.0);
            if (!NSPointInRect(self.dragCurrent, hit)) continue;
            for (const BoxplotPoint &point : self.model->boxplotPoints) {
                if (point.category == item.category && point.row > 0) selected.insert(point.row);
            }
            break;
        }
    }
    int selectionVersion = 0;
    if (MergeSelection(self.model->group, selected, mode, &selectionVersion)) {
        PublishSpreadPlotMessage("ROW_SELECTION_CHANGED", self.model->group, self.model->id, "", std::vector<int>(selected.begin(), selected.end()), selectionVersion);
    }
    [self setNeedsDisplay:YES];
    UpdatePanelOnMain();
}

- (void)rightMouseDown:(NSEvent *)event
{
    SetActivePlotOnMain(self.model);
    [[self window] makeFirstResponder:self];
    [NSMenu popUpContextMenu:[self menuForEvent:event] withEvent:event forView:self];
}

- (NSMenuItem *)menuItem:(NSString *)title command:(NSString *)command
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:@selector(runCommand:) keyEquivalent:@""];
    [item setTarget:g_commandTarget];
    [item setRepresentedObject:command];
    return item;
}

- (NSMenuItem *)menuItemForOption:(const rlispstat::core::BoxplotMenuOption &)option
{
    NSMenuItem *item = nil;
    if (option.command.empty()) {
        item = [[NSMenuItem alloc] initWithTitle:ToNSString(option.title) action:nil keyEquivalent:@""];
    } else {
        item = [self menuItem:ToNSString(option.title) command:ToNSString(option.command)];
    }
    [item setEnabled:option.enabled];
    [item setState:option.checked ? NSControlStateValueOn : NSControlStateValueOff];
    return item;
}

- (NSMenu *)menuForEvent:(NSEvent *)event
{
    if (!g_commandTarget) g_commandTarget = [[CommandTarget alloc] init];
    NSPoint clickPoint = [self convertPoint:[event locationInWindow] fromView:nil];
    const NSInteger variableIndex = [self variableLabelIndexAtPoint:clickPoint];
    if (variableIndex >= 0) {
        return SnapshotAlbumMenu([self variableMenuForIndex:variableIndex], @"Boxplot");
    }
    [self syncConnectionWidthControl];
    const rlispstat::core::PlotContextMenuTitles contextTitles = rlispstat::core::DefaultPlotContextMenuTitles();
    rlispstat::core::BoxplotMenuState menuState =
        rlispstat::core::BuildBoxplotMenuState(
            self.model->boxplotShowPoints,
            self.model->boxplotShowBox,
            self.model->boxplotShowWhiskers,
            self.model->boxplotShowViolin,
            self.model->boxplotSplitViolin,
            self.model->boxplotShowH0Simulation,
            BoxplotUsesVariableAxes(self.model),
            self.model->boxplotConnectRows,
            self.model->boxplotStandardizeVariables,
            self.model->boxplotVariables,
            rlispstat::core::NumericVariableNames(self.model));

    NSMenu *menu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    NSMenuItem *boxplot = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.title) action:nil keyEquivalent:@""];
    NSMenu *boxMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.title)];
    [boxMenu addItem:[self menuItemForOption:menuState.togglePoints]];
    [boxMenu addItem:[self menuItemForOption:menuState.toggleBox]];
    [boxMenu addItem:[self menuItemForOption:menuState.toggleWhiskers]];
    [boxMenu addItem:[self menuItemForOption:menuState.toggleViolin]];
    [boxMenu addItem:[self menuItemForOption:menuState.configureSplitViolin]];
    if (menuState.showClearSplitViolin) {
        [boxMenu addItem:[self menuItemForOption:menuState.clearSplitViolin]];
    }
    [boxMenu addItem:[self menuItemForOption:menuState.configureH0]];
    if (menuState.showClearH0) {
        [boxMenu addItem:[self menuItemForOption:menuState.clearH0]];
    }
    if (menuState.showVariableAxisOptions) {
        [boxMenu addItem:[NSMenuItem separatorItem]];
        NSMenuItem *addVariable = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.addVariableTitle) action:nil keyEquivalent:@""];
        NSMenu *addMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.addVariableTitle)];
        for (const rlispstat::core::BoxplotMenuOption &option : menuState.addVariableOptions) {
            [addMenu addItem:[self menuItemForOption:option]];
        }
        if (menuState.addVariableOptions.empty()) {
            NSMenuItem *empty = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.noMoreNumericVariablesTitle) action:nil keyEquivalent:@""];
            [empty setEnabled:NO];
            [addMenu addItem:empty];
        }
        [boxMenu setSubmenu:addMenu forItem:addVariable];
        [boxMenu addItem:addVariable];
        if (menuState.showRemoveVariableMenu) {
            NSMenuItem *removeVariable = [[NSMenuItem alloc] initWithTitle:ToNSString(menuState.removeVariableTitle) action:nil keyEquivalent:@""];
            NSMenu *removeMenu = [[NSMenu alloc] initWithTitle:ToNSString(menuState.removeVariableTitle)];
            for (const rlispstat::core::BoxplotMenuOption &option : menuState.removeVariableOptions) {
                [removeMenu addItem:[self menuItemForOption:option]];
            }
            [boxMenu setSubmenu:removeMenu forItem:removeVariable];
            [boxMenu addItem:removeVariable];
        }
        [boxMenu addItem:[self menuItemForOption:menuState.connectRows]];
        [boxMenu addItem:[self menuItemForOption:menuState.standardizeVariables]];
        NSMenuItem *lineWidthControl = [[NSMenuItem alloc]
            initWithTitle:(self.model->boxplotShowConnectionWidthSlider
                ? @"Hide Line-Width Slider" : @"Show Line-Width Slider")
                   action:@selector(toggleConnectionWidthControl:)
            keyEquivalent:@""];
        [lineWidthControl setTarget:self];
        [lineWidthControl setEnabled:self.model->boxplotConnectRows];
        [boxMenu addItem:lineWidthControl];
    }
    [menu setSubmenu:boxMenu forItem:boxplot];
    [menu addItem:boxplot];
    if (BoxplotUsesVariableAxes(self.model)) {
        if (NSMenuItem *colorItem = ColorByVariableMenuItem(self.model))
            [menu addItem:colorItem];
        if (NSMenuItem *legendItem = ColorLegendMenuItem(self.model))
            [menu addItem:legendItem];
    }

    NSMenuItem *groupOrder = [[NSMenuItem alloc] initWithTitle:@"Group order" action:nil keyEquivalent:@""];
    NSMenu *groupOrderMenu = [[NSMenu alloc] initWithTitle:@"Group order"];
    for (const rlispstat::core::BoxplotMenuOption &option :
         rlispstat::core::BoxplotGroupOrderMenuOptions(self.model->boxplotGroupOrder)) {
        [groupOrderMenu addItem:[self menuItemForOption:option]];
    }
    [groupOrder setSubmenu:groupOrderMenu];
    [groupOrder setEnabled:self.model->boxplotCategories.size() > 1];
    [menu addItem:groupOrder];
    if (NSMenuItem *conditionItem = ConditioningVariablesMenuItem(self.model))
        [menu addItem:conditionItem];

    NSMenuItem *analysis = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.analyzeThisBoxplot) action:nil keyEquivalent:@""];
    NSMenu *analysisMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.analyzeThisBoxplot)];
    [analysisMenu addItem:[self menuItemForOption:menuState.descriptives]];
    [menu setSubmenu:analysisMenu forItem:analysis];
    [menu addItem:analysis];

    NSMenuItem *selection = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.selection) action:nil keyEquivalent:@""];
    NSMenu *selectionMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.selection)];
    for (const rlispstat::core::BoxplotMenuOption &option : menuState.selectionOptions) {
        [selectionMenu addItem:[self menuItemForOption:option]];
    }
    [selectionMenu addItem:ColorSelectedPointsSubmenuItem(ToNSString(contextTitles.colorSelectedPoints))];
    [selectionMenu addItem:[self menuItem:ToNSString(contextTitles.openColorPalette) command:@"OPEN_COLOR_PALETTE"]];
    [selectionMenu addItem:[NSMenuItem separatorItem]];
    [selectionMenu addItem:AddDataColumnSubmenuItem()];
    [menu setSubmenu:selectionMenu forItem:selection];
    [menu addItem:selection];
    std::vector<int> clickedRows;
    std::string clickedCategory;
    const std::vector<BoxplotStats> clickedStats = BoxplotStatsForModel(*self.model);
    const std::vector<BoxplotStatsRenderItem> clickedPlan =
        BuildBoxplotStatsRenderPlan([self boxplotLayout], clickedStats);
    for (const BoxplotStatsRenderItem &item : clickedPlan) {
        if (!NSPointInRect(clickPoint,
                NSInsetRect(rlispstat::platform::macos::ToNSRect(item.boxRect), -8.0, -8.0))) continue;
        clickedCategory = item.category;
        for (const BoxplotPoint &point : self.model->boxplotPoints) {
            if (point.row > 0 && point.category == clickedCategory) clickedRows.push_back(point.row);
        }
        break;
    }
    [menu addItem:AnalysisScopeSubmenuItemForPlot(
        self.model, clickedRows, "boxplot_group",
        clickedCategory.empty() ? "" : "Boxplot group " + clickedCategory,
        clickedCategory)];

    NSMenuItem *exportItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.exportMenu) action:nil keyEquivalent:@""];
    NSMenu *exportMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.exportMenu)];
    AddStandardPlotExportItems(exportMenu, NO);
    if (self.model && !self.model->codeReference.provenance.verificationRCode.empty())
        AddRCodeExportItems(exportMenu, "output", self.model->id, false);
    [menu setSubmenu:exportMenu forItem:exportItem];
    [menu addItem:exportItem];
    AddSnapshotAlbumContextItems(menu);

    NSMenuItem *viewItem = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.view) action:nil keyEquivalent:@""];
    NSMenu *viewMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.view)];
    if (NSMenuItem *imputation = ImputationDisplaySubmenuItemForPlot(self.model)) {
        [viewMenu addItem:imputation];
        [viewMenu addItem:[NSMenuItem separatorItem]];
    }
    AddPlotThemeSubmenu(viewMenu, self);
    [menu setSubmenu:viewMenu forItem:viewItem];
    [menu addItem:viewItem];

    NSMenuItem *plot = [[NSMenuItem alloc] initWithTitle:ToNSString(contextTitles.plot) action:nil keyEquivalent:@""];
    NSMenu *plotMenu = [[NSMenu alloc] initWithTitle:ToNSString(contextTitles.plot)];
    for (const rlispstat::core::BoxplotMenuOption &option : menuState.plotOptions) {
        [plotMenu addItem:[self menuItemForOption:option]];
    }
    [menu setSubmenu:plotMenu forItem:plot];
    [menu addItem:plot];
    return FinalizeGraphContextMenu(menu);
}

- (BOOL)savePNGToPath:(NSString *)path
{
    const BOOL controlWasHidden = [self.connectionWidthControl isHidden];
    [self.connectionWidthControl setHidden:YES];
    NSBitmapImageRep *rep = [self bitmapImageRepForCachingDisplayInRect:[self bounds]];
    [self cacheDisplayInRect:[self bounds] toBitmapImageRep:rep];
    NSData *data = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    const BOOL saved = [data writeToFile:path atomically:YES];
    [self.connectionWidthControl setHidden:controlWasHidden];
    return saved;
}

- (BOOL)savePDFToPath:(NSString *)path
{
    const BOOL controlWasHidden = [self.connectionWidthControl isHidden];
    [self.connectionWidthControl setHidden:YES];
    NSData *data = [self dataWithPDFInsideRect:[self bounds]];
    const BOOL saved = [data writeToFile:path atomically:YES];
    [self.connectionWidthControl setHidden:controlWasHidden];
    return saved;
}
@end

static NSString *const kSnapshotAlbumRowPasteboardType = @"org.linkeda.snapshot-album-row";

@protocol SnapshotStructuredSource <NSObject>
- (NSString *)snapshotTabDelimitedText;
@end

static std::string SnapshotCSVToTabDelimited(const std::string &csv)
{
    std::string result;
    result.reserve(csv.size());
    bool quoted = false;
    for (std::size_t index = 0; index < csv.size(); ++index) {
        const char ch = csv[index];
        if (ch == '"') {
            if (quoted && index + 1 < csv.size() && csv[index + 1] == '"') {
                result.push_back('"'); ++index;
            } else quoted = !quoted;
        } else if (ch == ',' && !quoted) result.push_back('\t');
        else result.push_back(ch);
    }
    return result;
}

@interface SnapshotPlotHostView : NSView <WindowStickyReferenceProvider>
- (instancetype)initWithSnapshot:(const rlispstat::core::SnapshotItem &)snapshot;
@end

@implementation SnapshotPlotHostView {
    std::unique_ptr<PlotModel> _ownedModel;
    NSView *_plotView;
}
- (instancetype)initWithSnapshot:(const rlispstat::core::SnapshotItem &)snapshot
{
    const auto *frozen = std::get_if<rlispstat::core::FrozenPlotContent>(
        &snapshot.renderable_content);
    NSRect frame = NSMakeRect(0, 0,
        frozen ? frozen->preferred_width : 720.0,
        frozen ? frozen->preferred_height : 520.0);
    self = [super initWithFrame:frame];
    if (!self || !frozen) return self;
    _ownedModel = std::make_unique<PlotModel>(frozen->model);
    // A snapshot must not participate in global linking or temporary
    // selection highlighting.  Dataset/scope identity remains in metadata.
    _ownedModel->group = "snapshot:" + snapshot.metadata.snapshot_id;
    _ownedModel->smoothShowSpanSlider = false;
    _ownedModel->pointSizeSliderVisible = false;
    _ownedModel->boxplotShowConnectionWidthSlider = false;
    if (_ownedModel->kind == "boxplot")
        _plotView = [[BoxplotView alloc] initWithModel:_ownedModel.get()];
    else if (_ownedModel->kind == "histogram")
        _plotView = [[HistogramView alloc] initWithModel:_ownedModel.get()];
    else if (_ownedModel->kind == "barplot")
        _plotView = [[BarplotView alloc] initWithModel:_ownedModel.get()];
    else
        _plotView = [[ScatterView alloc] initWithModel:_ownedModel.get()];
    [_plotView setValue:ToNSString(snapshot.metadata.theme_name)
              forKey:@"snapshotThemeName"];
    [_plotView setFrame:[self bounds]];
    [_plotView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [self addSubview:_plotView];
    [self setAccessibilityLabel:@"Static snapshot preview"];
    return self;
}
- (BOOL)isFlipped { return YES; }
- (NSValue *)stickyReferenceRectValue
{
    if (!_plotView) return [NSValue valueWithRect:[self bounds]];
    NSRect rect = WindowStickyReferenceRect(_plotView);
    rect = [self convertRect:rect fromView:_plotView];
    return [NSValue valueWithRect:rect];
}
- (NSView *)hitTest:(NSPoint)point
{
    // The captured plot itself is deliberately inert, but a snapshot may carry
    // an editable sticker canvas above it.  Returning nil for the host used to
    // discard that canvas before AppKit could reach its notes and handles.
    for (NSView *subview in [[self subviews] reverseObjectEnumerator]) {
        if (![subview isKindOfClass:[WindowStickyCanvasView class]]) continue;
        const NSPoint local = [subview convertPoint:point fromView:self];
        NSView *hit = [subview hitTest:local];
        if (hit) return hit;
    }
    return nil;
}
@end

@interface SnapshotImageHostView : NSView
- (instancetype)initWithSnapshot:(const rlispstat::core::SnapshotItem &)snapshot;
@end

@implementation SnapshotImageHostView {
    NSImage *_image;
}
- (instancetype)initWithSnapshot:(const rlispstat::core::SnapshotItem &)snapshot
{
    const auto *frozen = std::get_if<rlispstat::core::FrozenImageContent>(
        &snapshot.renderable_content);
    NSRect frame = NSMakeRect(0, 0,
        frozen ? frozen->preferred_width : 720.0,
        frozen ? frozen->preferred_height : 520.0);
    self = [super initWithFrame:frame];
    if (!self || !frozen || frozen->png_data.empty()) return self;
    NSData *png = [NSData dataWithBytes:frozen->png_data.data()
                                  length:frozen->png_data.size()];
    _image = [[NSImage alloc] initWithData:png];
    [self setAccessibilityLabel:@"Static visual snapshot preview"];
    return self;
}
- (BOOL)isFlipped { return YES; }
- (NSView *)hitTest:(NSPoint)point
{
    // Keep the frozen image non-interactive while allowing its editable
    // snapshot-sticker canvas to receive pointer events.
    for (NSView *subview in [[self subviews] reverseObjectEnumerator]) {
        if (![subview isKindOfClass:[WindowStickyCanvasView class]]) continue;
        const NSPoint local = [subview convertPoint:point fromView:self];
        NSView *hit = [subview hitTest:local];
        if (hit) return hit;
    }
    return nil;
}
- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor whiteColor] setFill];
    NSRectFill([self bounds]);
    if (_image) {
        [_image drawInRect:[self bounds] fromRect:NSZeroRect
                  operation:NSCompositingOperationSourceOver fraction:1.0
            respectFlipped:YES hints:nil];
    }
}
@end

@interface SnapshotStickerOverlayView : NSView
- (instancetype)initWithFrame:(NSRect)frame
                     stickers:(const std::vector<rlispstat::core::WindowStickyNote> &)stickers;
@end

@implementation SnapshotStickerOverlayView {
    std::vector<rlispstat::core::WindowStickyNote> _stickers;
}
- (instancetype)initWithFrame:(NSRect)frame
                     stickers:(const std::vector<rlispstat::core::WindowStickyNote> &)stickers
{
    self = [super initWithFrame:frame];
    if (!self) return nil;
    _stickers = stickers;
    [self setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [self setAccessibilityLabel:@"Snapshot Stickers"];
    return self;
}
- (BOOL)isFlipped { return YES; }
- (BOOL)isOpaque { return NO; }
- (NSView *)hitTest:(NSPoint)point { (void)point; return nil; }
- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    NSDictionary *textAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:13.0],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.10 alpha:1.0]
    };
    const NSRect referenceRect = WindowStickyReferenceRect([self superview]);
    for (const rlispstat::core::WindowStickyNote &stored : _stickers) {
        const auto sticker = rlispstat::core::WindowStickyNoteForCanvas(
            stored, NSWidth([self bounds]), NSHeight([self bounds]),
            NSMinX(referenceRect), NSMinY(referenceRect),
            NSWidth(referenceRect), NSHeight(referenceRect));
        NSRect frame = sticker.collapsed
            ? NSMakeRect(sticker.x, sticker.y, 32.0, 28.0)
            : NSMakeRect(sticker.x, sticker.y, sticker.width, sticker.height);
        const NSPoint start = NSMakePoint(NSMidX(frame), NSMidY(frame));
        const NSPoint end = NSMakePoint(sticker.anchor_x, sticker.anchor_y);
        [[NSColor colorWithCalibratedWhite:0.22 alpha:0.72] setStroke];
        NSBezierPath *line = [NSBezierPath bezierPath];
        [line moveToPoint:start]; [line lineToPoint:end]; [line setLineWidth:1.5]; [line stroke];
        [[NSColor colorWithCalibratedWhite:0.20 alpha:0.90] setFill];
        [[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(end.x - 5.0, end.y - 5.0, 10.0, 10.0)] fill];

        NSColor *color = StickyNoteColor(sticker.color);
        [color setFill];
        [[NSBezierPath bezierPathWithRoundedRect:frame xRadius:5.0 yRadius:5.0] fill];
        if (sticker.collapsed) {
            [[NSColor colorWithCalibratedWhite:0.15 alpha:0.72] setStroke];
            NSBezierPath *markerBorder = [NSBezierPath bezierPathWithRoundedRect:
                NSInsetRect(frame, 0.75, 0.75) xRadius:6.0 yRadius:6.0];
            [markerBorder setLineWidth:1.5]; [markerBorder stroke];
            NSMutableParagraphStyle *style = [[NSMutableParagraphStyle alloc] init];
            [style setAlignment:NSTextAlignmentCenter];
            [@"…" drawInRect:NSInsetRect(frame, 4.0, 2.0) withAttributes:@{
                NSFontAttributeName: [NSFont systemFontOfSize:17.0 weight:NSFontWeightBold],
                NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.16 alpha:0.90],
                NSParagraphStyleAttributeName: style
            }];
            [style release];
            continue;
        }
        [[NSColor colorWithCalibratedWhite:0.25 alpha:0.30] setStroke];
        NSBezierPath *border = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(frame, 0.5, 0.5)
                                                               xRadius:5.0 yRadius:5.0];
        [border setLineWidth:1.0]; [border stroke];
        [ToNSString(sticker.plain_text) drawInRect:NSMakeRect(
            NSMinX(frame) + 12.0, NSMinY(frame) + 10.0,
            std::max((CGFloat)1.0, NSWidth(frame) - 24.0),
            std::max((CGFloat)1.0, NSHeight(frame) - 20.0))
            withAttributes:textAttributes];
    }
}
@end

static NSView *SnapshotFrozenContentView(const rlispstat::core::SnapshotItem &snapshot,
                                         bool includeStickers = true)
{
    NSView *content = nil;
    if (std::holds_alternative<rlispstat::core::FrozenPlotContent>(
            snapshot.renderable_content)) {
        content = [[SnapshotPlotHostView alloc] initWithSnapshot:snapshot];
    } else if (std::holds_alternative<rlispstat::core::FrozenImageContent>(
                   snapshot.renderable_content)) {
        content = [[SnapshotImageHostView alloc] initWithSnapshot:snapshot];
    } else if (std::holds_alternative<rlispstat::core::FrozenTableContent>(
                   snapshot.renderable_content)) {
        const auto &table = std::get<rlispstat::core::FrozenTableContent>(
            snapshot.renderable_content);
        content = [[MacTabularExportView alloc]
            initWithTitle:ToNSString(snapshot.metadata.title)
            tabDelimited:ToNSString(rlispstat::core::FrozenTableToTabDelimited(table))];
    } else {
        const auto &text = std::get<rlispstat::core::FrozenTextContent>(
            snapshot.renderable_content);
        NSTextView *textView = [[NSTextView alloc]
            initWithFrame:NSMakeRect(0, 0, 720, 520)];
        [textView setEditable:NO];
        [textView setSelectable:YES];
        [textView setFont:[NSFont monospacedSystemFontOfSize:12 weight:NSFontWeightRegular]];
        [textView setString:ToNSString(text.plain_text)];
        content = textView;
    }
    if (content && includeStickers && !snapshot.stickers.empty()) {
        SnapshotStickerOverlayView *overlay = [[SnapshotStickerOverlayView alloc]
            initWithFrame:[content bounds] stickers:snapshot.stickers];
        [content addSubview:overlay positioned:NSWindowAbove relativeTo:nil];
    }
    return content;
}

@interface SnapshotExportPageView : NSView
- (instancetype)initWithSnapshot:(const rlispstat::core::SnapshotItem &)snapshot;
@end

@implementation SnapshotExportPageView {
    rlispstat::core::SnapshotItem _snapshot;
    NSView *_content;
}
- (instancetype)initWithSnapshot:(const rlispstat::core::SnapshotItem &)snapshot
{
    self = [super initWithFrame:NSMakeRect(0, 0, 1, 1)];
    if (!self) return nil;
    _snapshot = snapshot;
    _content = SnapshotFrozenContentView(_snapshot, _snapshot.metadata.include_notes);
    CGFloat noteHeight = (_snapshot.metadata.include_notes && _snapshot.note &&
                          _snapshot.note->has_content) ? 90.0 : 0.0;
    const NSSize nativeSize = [_content frame].size;
    const CGFloat width = std::max((CGFloat)360.0, nativeSize.width + 68.0);
    const CGFloat height = std::max((CGFloat)260.0, nativeSize.height + 66.0 + noteHeight + 24.0);
    [self setFrame:NSMakeRect(0, 0, width, height)];
    [_content setFrame:NSMakeRect(34.0, 66.0, nativeSize.width, nativeSize.height)];
    [self addSubview:_content];
    return self;
}
- (BOOL)isFlipped { return YES; }
- (void)drawRect:(NSRect)dirtyRect
{
    (void)dirtyRect;
    [[NSColor whiteColor] setFill]; NSRectFill([self bounds]);
    NSDictionary *titleAttributes = @{
        NSFontAttributeName: [NSFont systemFontOfSize:17 weight:NSFontWeightSemibold],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.08 alpha:1.0]
    };
    const CGFloat textWidth = std::max((CGFloat)1.0, NSWidth([self bounds]) - 68.0);
    [ToNSString(_snapshot.metadata.title) drawInRect:NSMakeRect(34, 18, textWidth, 24)
                                      withAttributes:titleAttributes];
    NSString *detail = [NSString stringWithFormat:@"%@  ·  %@  ·  Theme: %@",
        ToNSString(rlispstat::core::SnapshotContentKindName(_snapshot.content_kind)),
        ToNSString(rlispstat::core::SnapshotScopeSummary(_snapshot)),
        ToNSString(rlispstat::core::PlotThemeDisplayName(_snapshot.metadata.theme_name))];
    [detail drawInRect:NSMakeRect(34, 43, textWidth, 18) withAttributes:@{
        NSFontAttributeName: [NSFont systemFontOfSize:10.5],
        NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.38 alpha:1.0]
    }];
    if (_snapshot.metadata.include_notes && _snapshot.note && _snapshot.note->has_content) {
        const CGFloat y = NSHeight([self bounds]) - 82.0;
        [@"Notes" drawAtPoint:NSMakePoint(34, y) withAttributes:@{
            NSFontAttributeName: [NSFont systemFontOfSize:11 weight:NSFontWeightSemibold],
            NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.14 alpha:1.0]
        }];
        [ToNSString(_snapshot.note->plain_text) drawInRect:NSMakeRect(34, y + 18, textWidth, 54)
            withAttributes:@{NSFontAttributeName: [NSFont systemFontOfSize:10.5],
                             NSForegroundColorAttributeName: [NSColor colorWithCalibratedWhite:0.14 alpha:1.0]}];
    }
}
@end

static NSView *SnapshotDescendantOfClasses(NSView *view, NSArray<Class> *classes)
{
    if (!view) return nil;
    for (Class candidate in classes)
        if ([view isKindOfClass:candidate]) return view;
    for (NSView *child in [view subviews]) {
        NSView *found = SnapshotDescendantOfClasses(child, classes);
        if (found) return found;
    }
    return nil;
}

static NSView<SnapshotStructuredSource> *SnapshotStructuredSourceDescendant(NSView *view)
{
    if (!view) return nil;
    if ([view respondsToSelector:@selector(snapshotTabDelimitedText)])
        return (NSView<SnapshotStructuredSource> *)view;
    for (NSView *child in [view subviews]) {
        NSView<SnapshotStructuredSource> *found = SnapshotStructuredSourceDescendant(child);
        if (found) return found;
    }
    return nil;
}

static std::string SnapshotStringForObject(id object)
{
    if (!object || object == [NSNull null]) return std::string();
    if ([object isKindOfClass:[NSString class]]) return std::string([(NSString *)object UTF8String]);
    if ([object respondsToSelector:@selector(stringValue)])
        return std::string([[object stringValue] UTF8String]);
    return std::string([[object description] UTF8String]);
}

static std::optional<rlispstat::core::FrozenTableContent>
SnapshotVisibleTableContent(NSTableView *table)
{
    if (!table) return std::nullopt;
    NSArray<NSTableColumn *> *columns = [table tableColumns];
    std::vector<NSTableColumn *> visibleColumns;
    for (NSTableColumn *column in columns)
        if (![column isHidden]) visibleColumns.push_back(column);
    if (visibleColumns.empty()) return std::nullopt;
    const NSInteger total = [table numberOfRows];
    NSRange visible = [table rowsInRect:[table visibleRect]];
    if (visible.location == NSNotFound || visible.length == 0) {
        visible.location = 0;
        visible.length = static_cast<NSUInteger>(std::min<NSInteger>(total, 100));
    }
    if (visible.location > static_cast<NSUInteger>(total)) visible.location = 0;
    visible.length = std::min<NSUInteger>(visible.length,
        static_cast<NSUInteger>(std::max<NSInteger>(0, total - (NSInteger)visible.location)));
    std::ostringstream text;
    for (std::size_t columnIndex = 0; columnIndex < visibleColumns.size(); ++columnIndex) {
        if (columnIndex) text << '\t';
        text << SnapshotStringForObject([[visibleColumns[columnIndex] headerCell] stringValue]);
    }
    id<NSTableViewDataSource> dataSource = [table dataSource];
    for (NSUInteger offset = 0; offset < visible.length; ++offset) {
        const NSInteger row = static_cast<NSInteger>(visible.location + offset);
        text << '\n';
        for (std::size_t columnIndex = 0; columnIndex < visibleColumns.size(); ++columnIndex) {
            if (columnIndex) text << '\t';
            NSTableColumn *column = visibleColumns[columnIndex];
            id value = nil;
            if ([dataSource respondsToSelector:@selector(tableView:objectValueForTableColumn:row:)])
                value = [dataSource tableView:table objectValueForTableColumn:column row:row];
            if (!value) {
                const NSInteger nativeColumn = [table columnWithIdentifier:[column identifier]];
                NSView *cell = nativeColumn >= 0 ? [table viewAtColumn:nativeColumn row:row
                                                       makeIfNecessary:NO] : nil;
                if ([cell respondsToSelector:@selector(stringValue)]) value = [(id)cell stringValue];
                else if ([cell isKindOfClass:[NSTableCellView class]])
                    value = [[(NSTableCellView *)cell textField] stringValue];
            }
            text << SnapshotStringForObject(value);
        }
    }
    rlispstat::core::FrozenTableContent result;
    result.tab_delimited_text = text.str();
    result.first_source_row = visible.location;
    result.source_row_count = visible.length;
    result.total_source_row_count = static_cast<std::size_t>(std::max<NSInteger>(0, total));
    result.contains_all_source_rows = visible.location == 0 &&
        visible.length == static_cast<NSUInteger>(total);
    for (NSTableColumn *column : visibleColumns) result.column_widths.push_back([column width]);
    return result;
}

static std::optional<rlispstat::core::FrozenTableContent>
SnapshotStructuredTextContent(NSView *view)
{
    NSView<SnapshotStructuredSource> *structured = SnapshotStructuredSourceDescendant(view);
    if (structured) {
        NSString *value = [structured snapshotTabDelimitedText];
        if ([value length]) {
            rlispstat::core::FrozenTableContent result;
            result.tab_delimited_text = std::string([value UTF8String]);
            result.source_row_count = [[value componentsSeparatedByString:@"\n"] count];
            return result;
        }
    }
    return std::nullopt;
}

static BOOL SnapshotWindowSupportsCapture(NSWindow *window)
{
    if (!window) return NO;
    NSView *root = [window contentView];
    // All note-enabled LinkEDA result windows are valid drag sources.  The
    // capture step below still determines the exact structured representation
    // and reports a clear error for a result type that is not supported yet.
    return [root isKindOfClass:[WindowNotesContainer class]];
}

static std::optional<rlispstat::core::SnapshotItem>
CaptureSnapshotFromWindow(NSWindow *window)
{
    if (!window) return std::nullopt;
    NSView *root = [window contentView];
    if (![root isKindOfClass:[WindowNotesContainer class]]) return std::nullopt;
    WindowNotesContainer *notes = (WindowNotesContainer *)root;
    NSView *primary = [notes primaryContentView];
    rlispstat::core::SnapshotItem item;
    item.metadata.source_view_id = std::string([[notes viewId] UTF8String]);
    item.metadata.created_at = std::chrono::system_clock::now();
    item.metadata.theme_name = MacCommandDispatcher().plotTheme();
    item.metadata.title = std::string([[window title] UTF8String]);
    item.metadata.default_title = item.metadata.title;
    item.metadata.source_description = item.metadata.title;
    DendrogramView *dendrogram = (DendrogramView *)SnapshotDescendantOfClasses(primary,
        @[[DendrogramView class]]);
    NSView *plotView = dendrogram ? nil : SnapshotDescendantOfClasses(primary,
        @[[ScatterView class], [BoxplotView class], [HistogramView class], [BarplotView class]]);
    if (NSView *themedView = dendrogram ? (NSView *)dendrogram : plotView)
        item.metadata.theme_name = std::string([PlotEffectiveThemeName(themedView) UTF8String]);
    if (dendrogram) {
        NSData *png = HighResolutionPNGDataForView(dendrogram);
        DendrogramState *state = [dendrogram.controller state];
        if (![png length] || !state) return std::nullopt;
        rlispstat::core::FrozenImageContent frozen;
        const unsigned char *bytes = static_cast<const unsigned char *>([png bytes]);
        frozen.png_data.assign(bytes, bytes + [png length]);
        frozen.preferred_width = std::max(320.0, NSWidth([dendrogram bounds]));
        frozen.preferred_height = std::max(240.0, NSHeight([dendrogram bounds]));
        item.metadata.dataset_id = state->group;
        item.metadata.title = "Dendrogram";
        item.metadata.default_title = item.metadata.title;
        item.metadata.source_description = item.metadata.title;
        item.metadata.source_scope = state->dataScopeCaptured
            ? state->dataScope
            : rlispstat::core::AllObservationsAnalysisScope(
                  state->group, RowCountForGroup(state->group));
        item.content_kind = rlispstat::core::SnapshotContentKind::Plot;
        item.view_specification.view_type = "dendrogram";
        item.view_specification.variables = {{"variables", rlispstat::core::JoinStrings(state->variables, ", ")}};
        item.renderable_content = std::move(frozen);
    } else if (plotView) {
        PlotModel *source = [(id)plotView model];
        if (!source) return std::nullopt;
        rlispstat::core::FrozenPlotContent frozen;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            frozen.model = *source;
            frozen.model.pointSizeSliderVisible = false;
            frozen.model.frozenAppearanceCaptured = true;
            frozen.model.frozenRowColors = DisplayPointColorMap(source->group);
            const std::string labelColumn = CurrentLabelColumnForGroupUnlocked(source->group);
            const DataColumn *labels = labelColumn.empty()
                ? nullptr : FindDataColumnUnlockedConst(source->group, labelColumn);
            if (labels) frozen.model.frozenRowLabels =
                rlispstat::core::RowLabelMapForColumn(*labels);
        }
        frozen.preferred_width = std::max(320.0, NSWidth([plotView bounds]));
        frozen.preferred_height = std::max(240.0, NSHeight([plotView bounds]));
        item.metadata.dataset_id = frozen.model.group;
        item.metadata.title = rlispstat::core::TitleForPlot(frozen.model);
        item.metadata.default_title = item.metadata.title;
        item.metadata.source_description = item.metadata.title;
        item.metadata.source_scope = frozen.model.dataScopeCaptured
            ? frozen.model.dataScope
            : rlispstat::core::AllObservationsAnalysisScope(
                  frozen.model.group, RowCountForGroup(frozen.model.group));
        item.content_kind = frozen.model.kind == "trellis_scatterplot"
            ? rlispstat::core::SnapshotContentKind::Trellis
            : rlispstat::core::SnapshotContentKind::Plot;
        item.view_specification.view_type = frozen.model.kind;
        item.view_specification.variables = {{"x", frozen.model.xLabel}, {"y", frozen.model.yLabel}};
        item.renderable_content = std::move(frozen);
    } else {
        // Prefer an analysis view's own complete report over an incidental
        // NSTableView.  Native tables often expose only their visible rows,
        // whereas the structured source represents the entire result.
        std::optional<rlispstat::core::FrozenTableContent> frozen =
            SnapshotStructuredTextContent(primary);
        NSTableView *table = nil;
        if (!frozen) {
            table = (NSTableView *)SnapshotDescendantOfClasses(primary,
                @[[NSTableView class]]);
            if (table) frozen = SnapshotVisibleTableContent(table);
        }
        if (!frozen) return std::nullopt;
        std::string group;
        {
            std::lock_guard<std::mutex> lock(g_mutex);
            group = ActiveDatasetGroupUnlocked();
            const DataFrameModel *dataset = FindDataFrameUnlockedConst(group);
            item.metadata.source_scope = group.empty()
                ? rlispstat::core::AnalysisScope{}
                : MacCommandDispatcher().applicationState().activeAnalysisScope(group);
            if (dataset && item.metadata.source_scope.totalDatasetRows == 0)
                item.metadata.source_scope.totalDatasetRows = (std::size_t)std::max(0, dataset->rows);
        }
        item.metadata.dataset_id = group;
        item.content_kind = table ? rlispstat::core::SnapshotContentKind::DataTable
                                  : rlispstat::core::SnapshotContentKind::ModelResult;
        item.view_specification.view_type = table ? "visible_data_table" : "structured_result";
        if (table) {
            item.view_specification.options.push_back({"row_policy", "visible_rows"});
            if (!frozen->contains_all_source_rows) {
                std::ostringstream description;
                description << item.metadata.source_description << " — visible rows "
                    << (frozen->first_source_row + 1) << "–"
                    << (frozen->first_source_row + frozen->source_row_count)
                    << " of " << frozen->total_source_row_count;
                item.metadata.source_description = description.str();
            }
        }
        item.renderable_content = std::move(*frozen);
    }
    rlispstat::core::WindowNote sourceNote = [notes noteSnapshot];
    if (sourceNote.has_content) {
        sourceNote.include_in_export = true;
        item.note = std::move(sourceNote);
    }
    item.stickers = [notes stickyNotesSnapshot];
    return item;
}

@interface SnapshotAlbumDropView : NSView
@end

@implementation SnapshotAlbumDropView
- (instancetype)initWithFrame:(NSRect)frame
{
    self = [super initWithFrame:frame];
    if (!self) return nil;
    [self setWantsLayer:YES];
    [[self layer] setBackgroundColor:[WorkbenchBackgroundColor() CGColor]];
    [self setAccessibilityLabel:@"Snapshot Album content"];
    return self;
}
@end

@interface SnapshotAlbumWindowController : NSObject <NSWindowDelegate>
- (void)show;
- (void)refreshSelectingId:(NSString *)snapshotId;
- (BOOL)isVisible;
@end

static rlispstat::core::SnapshotAlbum g_snapshotAlbum;
static SnapshotAlbumWindowController *g_snapshotAlbumController = nil;
static NSInteger g_snapshotAlbumLastSourceWindowNumber = 0;

@interface SnapshotAlbumContextActionTarget : NSObject
- (void)addSnapshotFromContext:(id)sender;
@end

static SnapshotAlbumContextActionTarget *g_snapshotAlbumContextActionTarget = nil;

@implementation SnapshotAlbumContextActionTarget
- (void)addSnapshotFromContext:(id)sender
{
    NSValue *sourceValue = [sender representedObject];
    NSWindow *source = [sourceValue isKindOfClass:[NSValue class]]
        ? [sourceValue nonretainedObjectValue] : nil;
    if (SnapshotWindowSupportsCapture(source)) {
        AddWindowToSnapshotAlbumOnMain(source, YES);
    } else {
        AddActiveWindowToSnapshotAlbumOnMain();
    }
}
@end

static NSWindow *SnapshotAlbumSourceWindow()
{
    // During native menu tracking AppKit can temporarily clear keyWindow;
    // mainWindow remains the user's active result window.
    for (NSWindow *candidate in @[[NSApp keyWindow] ?: [NSNull null],
                                  [NSApp mainWindow] ?: [NSNull null]]) {
        if (![candidate isKindOfClass:[NSWindow class]]) continue;
        if (SnapshotWindowSupportsCapture(candidate)) {
            g_snapshotAlbumLastSourceWindowNumber = [candidate windowNumber];
            return candidate;
        }
    }
    // Do not silently reuse a stale result window when a Snapshot Album tab
    // (or another unsupported window) owns the focus. That produced duplicate
    // snapshots after the user had switched to a different result window.
    if ([NSApp keyWindow] || [NSApp mainWindow]) return nil;
    for (NSWindow *window in [NSApp windows]) {
        if ([window windowNumber] == g_snapshotAlbumLastSourceWindowNumber && [window isVisible] &&
            SnapshotWindowSupportsCapture(window)) return window;
    }
    return nil;
}

@interface SnapshotNotesEditorView : NSSplitView <NSTextViewDelegate, NSSplitViewDelegate, WindowStickyCanvasOwner>
- (instancetype)initWithFrame:(NSRect)frame
                      snapshot:(const rlispstat::core::SnapshotItem &)snapshot;
- (BOOL)notesVisible;
- (BOOL)hasNoteText;
- (void)showNotes;
- (void)hideNotes;
- (void)toggleNotes;
- (void)addStickyNote;
- (BOOL)hasStickers;
@end

@implementation SnapshotNotesEditorView {
    NSString *_snapshotId;
    NSView *_primaryView;
    NSView *_notesPanel;
    NSTextView *_textView;
    WindowStickyCanvasView *_stickyCanvas;
    BOOL _notesVisible;
    CGFloat _rememberedNotesWidth;
    CGFloat _windowShiftForNotes;
}
- (instancetype)initWithFrame:(NSRect)frame
                      snapshot:(const rlispstat::core::SnapshotItem &)snapshot
{
    self = [super initWithFrame:frame];
    if (!self) return nil;
    _snapshotId = [ToNSString(snapshot.metadata.snapshot_id) copy];
    _rememberedNotesWidth = 270.0;
    _windowShiftForNotes = 0.0;
    [self setVertical:YES];
    [self setDividerStyle:NSSplitViewDividerStyleThin];
    [self setDelegate:self];
    [self setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];

    // Stickers are made live in the editable canvas below; the frozen overlay
    // is reserved for preview/export-only content.
    _primaryView = SnapshotFrozenContentView(snapshot, false);
    [_primaryView setFrame:[self bounds]];
    [_primaryView setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [self addSubview:_primaryView];
    _stickyCanvas = [[WindowStickyCanvasView alloc]
        initWithFrame:[_primaryView bounds] owner:self];
    [_primaryView addSubview:_stickyCanvas positioned:NSWindowAbove relativeTo:nil];
    [_stickyCanvas loadStickyNotes:snapshot.stickers];

    _notesPanel = [[NSView alloc] initWithFrame:NSMakeRect(
        0.0, 0.0, _rememberedNotesWidth, NSHeight([self bounds]))];
    [_notesPanel setWantsLayer:YES];
    [_notesPanel setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    _notesPanel.layer.backgroundColor = [[NSColor controlBackgroundColor] CGColor];
    [_notesPanel setAccessibilityLabel:@"Snapshot Notes"];
    NSTextField *heading = [NSTextField labelWithString:@"Notes"];
    [heading setFrame:NSMakeRect(12.0, NSHeight([_notesPanel bounds]) - 34.0, 220.0, 22.0)];
    [heading setFont:[NSFont systemFontOfSize:13.0 weight:NSFontWeightSemibold]];
    [heading setAutoresizingMask:NSViewMinYMargin | NSViewWidthSizable];
    [_notesPanel addSubview:heading];

    NSScrollView *scroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(
        10.0, 10.0, _rememberedNotesWidth - 20.0, NSHeight([_notesPanel bounds]) - 52.0)];
    [scroll setHasVerticalScroller:YES];
    [scroll setBorderType:NSBezelBorder];
    [scroll setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    const NSSize editorSize = [scroll contentSize];
    _textView = [[NSTextView alloc] initWithFrame:NSMakeRect(
        0.0, 0.0, editorSize.width, editorSize.height)];
    [_textView setRichText:NO];
    [_textView setAllowsUndo:YES];
    [_textView setUsesFindPanel:YES];
    [_textView setHorizontallyResizable:NO];
    [_textView setVerticallyResizable:YES];
    [_textView setMinSize:NSMakeSize(0.0, editorSize.height)];
    [_textView setMaxSize:NSMakeSize(CGFLOAT_MAX, CGFLOAT_MAX)];
    [_textView setAutoresizingMask:NSViewWidthSizable];
    [_textView setTextContainerInset:NSMakeSize(6.0, 5.0)];
    [_textView setFont:[NSFont systemFontOfSize:13.0]];
    [_textView setString:snapshot.note ? ToNSString(snapshot.note->plain_text) : @""];
    [_textView setDelegate:self];
    [_textView setAccessibilityLabel:@"Editable Snapshot Notes"];
    [[_textView textContainer] setContainerSize:NSMakeSize(editorSize.width, CGFLOAT_MAX)];
    [[_textView textContainer] setWidthTracksTextView:YES];
    [[_textView textContainer] setLineFragmentPadding:0.0];
    [scroll setDocumentView:_textView];
    [_notesPanel addSubview:scroll];

    // installSnapshot restores the source window's visible/hidden state after
    // this view has entered its window, so opening the panel can enlarge the
    // window without changing the graph/table geometry.
    _notesVisible = NO;
    return self;
}
- (BOOL)notesVisible { return _notesVisible; }
- (BOOL)hasNoteText
{
    return rlispstat::core::WindowNoteTextHasContent(
        std::string([[[_textView textStorage] string] UTF8String]));
}
- (void)showNotes
{
    if (_notesVisible) return;
    NSWindow *window = [self window];
    const CGFloat primaryWidth = NSWidth([self bounds]);
    const CGFloat contentHeight = NSHeight([self bounds]);
    _notesVisible = YES;
    if (window) {
        [window setContentSize:NSMakeSize(
            primaryWidth + _rememberedNotesWidth + [self dividerThickness], contentHeight)];
        NSRect frame = [window frame];
        NSScreen *screen = [window screen] ?: [NSScreen mainScreen];
        _windowShiftForNotes = 0.0;
        if (screen) {
            const NSRect visible = [screen visibleFrame];
            const CGFloat overflow = NSMaxX(frame) - NSMaxX(visible);
            if (overflow > 0.0) {
                const CGFloat availableShift = std::max((CGFloat)0.0,
                    NSMinX(frame) - NSMinX(visible));
                _windowShiftForNotes = std::min(overflow, availableShift);
                frame.origin.x -= _windowShiftForNotes;
                [window setFrame:frame display:YES];
            }
        }
    }
    [_notesPanel setFrame:NSMakeRect(
        std::max((CGFloat)0.0, NSWidth([self bounds]) - _rememberedNotesWidth),
        0.0, _rememberedNotesWidth, NSHeight([self bounds]))];
    [self addSubview:_notesPanel];
    [self adjustSubviews];
    [self setPosition:primaryWidth ofDividerAtIndex:0];
    [[self window] makeFirstResponder:_textView];
    if ([_snapshotId length])
        g_snapshotAlbum.setNoteVisible(std::string([_snapshotId UTF8String]), true);
}
- (void)hideNotes
{
    if (!_notesVisible) return;
    NSWindow *window = [self window];
    const CGFloat primaryWidth = NSWidth([_primaryView frame]);
    const CGFloat contentHeight = NSHeight([self bounds]);
    if (NSWidth([_notesPanel frame]) >= 180.0)
        _rememberedNotesWidth = NSWidth([_notesPanel frame]);
    [[self window] makeFirstResponder:_primaryView];
    [_notesPanel removeFromSuperview];
    _notesVisible = NO;
    if (window && primaryWidth > 0.0) {
        [window setContentSize:NSMakeSize(primaryWidth, contentHeight)];
        if (_windowShiftForNotes > 0.0) {
            NSRect frame = [window frame];
            frame.origin.x += _windowShiftForNotes;
            [window setFrame:frame display:YES];
        }
    }
    _windowShiftForNotes = 0.0;
    [_primaryView setFrame:[self bounds]];
    [self adjustSubviews];
    if ([_snapshotId length])
        g_snapshotAlbum.setNoteVisible(std::string([_snapshotId UTF8String]), false);
}
- (void)toggleNotes { _notesVisible ? [self hideNotes] : [self showNotes]; }

- (BOOL)hasStickers
{
    return [_stickyCanvas stickyNoteCount] > 0;
}

- (void)addStickyNote
{
    [_stickyCanvas addStickyNote];
}

- (void)stickyCanvasDidChange
{
    if (![_snapshotId length]) return;
    rlispstat::core::SnapshotItem *item =
        g_snapshotAlbum.find(std::string([_snapshotId UTF8String]));
    if (!item) return;
    item->stickers = [_stickyCanvas stateSnapshots];
    NSMenu *menu = [self menu];
    for (NSMenuItem *menuItem in [menu itemArray]) {
        if ([[menuItem title] hasPrefix:@"Annotate"]) {
            [menuItem setTitle:([self hasNoteText] || [self hasStickers])
                ? @"Annotate •" : @"Annotate"];
            break;
        }
    }
}

- (void)adjustSubviews
{
    [super adjustSubviews];
    // NSSplitView preserves the initial document frame when it has a single
    // pane.  Snapshots without visible notes must instead fill the current
    // tab/window so their frozen content can adapt to resizing.
    if (!_notesVisible && _primaryView) [_primaryView setFrame:[self bounds]];
}

- (void)textDidChange:(NSNotification *)notification
{
    (void)notification;
    if (![_snapshotId length]) return;
    g_snapshotAlbum.setNoteText(std::string([_snapshotId UTF8String]),
        std::string([[[_textView textStorage] string] UTF8String]));
    g_snapshotAlbum.setNoteVisible(std::string([_snapshotId UTF8String]), _notesVisible);
    const BOOL hasText = [self hasNoteText];
    NSMenu *menu = [self menu];
    for (NSMenuItem *item in [menu itemArray]) {
        if ([[item title] hasPrefix:@"Annotate"]) {
            [item setTitle:(hasText || [self hasStickers]) ? @"Annotate •" : @"Annotate"];
            break;
        }
    }
}
- (void)splitViewDidResizeSubviews:(NSNotification *)notification
{
    (void)notification;
    if (_notesVisible && NSWidth([_notesPanel frame]) >= 180.0)
        _rememberedNotesWidth = NSWidth([_notesPanel frame]);
}
- (CGFloat)splitView:(NSSplitView *)splitView
    constrainMinCoordinate:(CGFloat)proposedMinimumPosition
           ofSubviewAt:(NSInteger)dividerIndex
{
    (void)splitView; (void)proposedMinimumPosition; (void)dividerIndex;
    return 320.0;
}
- (CGFloat)splitView:(NSSplitView *)splitView
    constrainMaxCoordinate:(CGFloat)proposedMaximumPosition
           ofSubviewAt:(NSInteger)dividerIndex
{
    (void)dividerIndex;
    return std::max((CGFloat)320.0,
        std::min(proposedMaximumPosition, NSWidth([splitView bounds]) - 180.0));
}
@end

@implementation SnapshotAlbumWindowController {
    NSWindow *_window;
    NSMutableDictionary<NSString *, NSWindow *> *_windowsById;
    NSWindow *_removingWindow;
}
- (instancetype)init
{
    self = [super init];
    if (!self) return nil;
    NSRect frame = NextWindowFrameOnMain(1080, 700);
    _window = [[NSWindow alloc] initWithContentRect:frame
        styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                  NSWindowStyleMaskResizable | NSWindowStyleMaskMiniaturizable
        backing:NSBackingStoreBuffered defer:NO];
    [_window setTitle:@"LinkEDA Snapshot Album"];
    [_window setMinSize:NSMakeSize(360, 260)];
    [_window setTabbingIdentifier:@"LinkEDA.SnapshotAlbum"];
    [_window setTabbingMode:NSWindowTabbingModePreferred];
    [_window setReleasedWhenClosed:NO];
    [_window setDelegate:self];
    // This backend is built with manual Objective-C lifetime management.
    // The controller lives for the whole session, so its tab registry must
    // not be an autoreleased convenience object: AppKit can deliver key-window
    // notifications much later while a native tab drag animation is running.
    _windowsById = [[NSMutableDictionary alloc] init];
    [self installEmptyContentInWindow:_window];
    return self;
}
- (BOOL)isVisible
{
    if ([_window isVisible]) return YES;
    for (NSWindow *window in [_windowsById allValues])
        if ([window isVisible]) return YES;
    return NO;
}
- (void)show
{
    NSWindow *front = [NSApp keyWindow];
    if (![[_windowsById allValues] containsObject:front]) front = _window;
    [front makeKeyAndOrderFront:nil];
    for (NSWindow *window in [_windowsById allValues])
        if (![window tabGroup]) [window orderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}
- (void)installMenu:(NSMenu *)menu recursivelyInView:(NSView *)view
{
    if ([view isKindOfClass:[NSTextView class]]) return;
    [view setMenu:menu];
    for (NSView *child in [view subviews]) [self installMenu:menu recursivelyInView:child];
}
- (NSMenuItem *)menuItem:(NSString *)title action:(SEL)action snapshotId:(NSString *)snapshotId
{
    NSMenuItem *item = [[NSMenuItem alloc] initWithTitle:title action:action keyEquivalent:@""];
    [item setTarget:self]; [item setRepresentedObject:snapshotId]; return item;
}
- (NSMenu *)contextMenuForItem:(const rlispstat::core::SnapshotItem &)item
{
    NSString *identifier = ToNSString(item.metadata.snapshot_id);
    NSMenu *menu = [[NSMenu alloc] initWithTitle:@"Snapshot"];
    [menu addItem:[self menuItem:@"Rename Snapshot…" action:@selector(renameSnapshot:) snapshotId:identifier]];
    NSMenuItem *annotate = [[NSMenuItem alloc] initWithTitle:
        ((item.note && item.note->has_content) || !item.stickers.empty()) ? @"Annotate •" : @"Annotate"
        action:nil keyEquivalent:@""];
    NSMenu *annotateMenu = [[NSMenu alloc] initWithTitle:@"Annotate"];
    NSWindow *snapshotWindow = _windowsById[identifier];
    SnapshotNotesEditorView *editor = [snapshotWindow.contentView
        isKindOfClass:[SnapshotNotesEditorView class]]
        ? (SnapshotNotesEditorView *)snapshotWindow.contentView : nil;
    const BOOL notesVisible = editor ? [editor notesVisible] : NO;
    NSMenuItem *toggleNotes = [self menuItem:(notesVisible ? @"Hide Notes" :
        ((item.note && item.note->has_content) ? @"Show Notes •" : @"Show Notes"))
        action:@selector(toggleSnapshotNotes:) snapshotId:identifier];
    [toggleNotes setState:notesVisible ? NSControlStateValueOn : NSControlStateValueOff];
    [annotateMenu addItem:toggleNotes];
    [annotateMenu addItem:[self menuItem:@"New Sticker"
                                  action:@selector(addSnapshotSticker:)
                              snapshotId:identifier]];
    [annotate setSubmenu:annotateMenu];
    [menu addItem:annotate];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *include = [self menuItem:@"Include in Album Export"
        action:@selector(toggleSnapshotIncluded:) snapshotId:identifier];
    [include setState:item.metadata.include_in_export ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:include];
    NSMenuItem *notes = [self menuItem:@"Include Notes in Export"
        action:@selector(toggleSnapshotNotesIncluded:) snapshotId:identifier];
    // A snapshot can acquire notes after capture, so this remains available
    // even when the copied note initially has no text.
    [notes setEnabled:YES];
    [notes setState:item.metadata.include_notes ? NSControlStateValueOn : NSControlStateValueOff];
    [menu addItem:notes];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self menuItem:@"Export Snapshot Album…" action:@selector(exportAlbum:) snapshotId:identifier]];
    [menu addItem:[NSMenuItem separatorItem]];
    [menu addItem:[self menuItem:@"Remove Snapshot" action:@selector(removeSnapshot:) snapshotId:identifier]];
    return menu;
}
- (void)installEmptyContentInWindow:(NSWindow *)window
{
    [window setTitle:@"LinkEDA Snapshot Album"];
    [window setTitleVisibility:NSWindowTitleVisible];
    SnapshotAlbumDropView *root = [[SnapshotAlbumDropView alloc]
        initWithFrame:[[window contentView] bounds]];
    [root setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    NSTextField *message = [NSTextField wrappingLabelWithString:
        @"Snapshot Album\n\nAdd the active graph or analysis from Window → Snapshot Album."];
    [message setAlignment:NSTextAlignmentCenter];
    [message setFont:[NSFont systemFontOfSize:15.0]];
    [message setTextColor:[NSColor secondaryLabelColor]];
    [message setFrame:NSInsetRect([root bounds], 80.0, 80.0)];
    [message setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [root addSubview:message]; [window setContentView:root];
}
- (void)setTabBarVisible:(BOOL)visible forWindow:(NSWindow *)window
{
    NSWindowTabGroup *group = [window tabGroup];
    if (!group) {
        if (visible) [window toggleTabBar:nil];
        return;
    }
    if (group && [group isTabBarVisible] != visible) [window toggleTabBar:nil];
}
- (void)installSnapshot:(const rlispstat::core::SnapshotItem &)item inWindow:(NSWindow *)window
{
    const BOOL shouldShowNotes = item.note && item.note->has_content && item.note->visible;
    SnapshotNotesEditorView *oldEditor = [window.contentView
        isKindOfClass:[SnapshotNotesEditorView class]]
        ? (SnapshotNotesEditorView *)window.contentView : nil;
    if ([oldEditor notesVisible]) [oldEditor hideNotes];
    [window setTitle:ToNSString(item.metadata.title)];
    [window setTitleVisibility:NSWindowTitleHidden];
    [window setTabbingIdentifier:@"LinkEDA.SnapshotAlbum"];
    [window setTabbingMode:NSWindowTabbingModePreferred];
    SnapshotNotesEditorView *root = [[SnapshotNotesEditorView alloc]
        initWithFrame:[[window contentView] bounds] snapshot:item];
    [root setAutoresizingMask:NSViewWidthSizable | NSViewHeightSizable];
    [window setContentView:root];
    if (shouldShowNotes) [root showNotes];
    NSMenu *menu = [self contextMenuForItem:item];
    [self installMenu:menu recursivelyInView:root];
    [root setAccessibilityLabel:[NSString stringWithFormat:@"Snapshot: %@. Right-click for actions.",
        ToNSString(item.metadata.title)]];
}
- (NSWindow *)newWindowForSnapshot:(const rlispstat::core::SnapshotItem &)item
{
    (void)item;
    NSWindow *window = [[NSWindow alloc] initWithContentRect:[_window frame]
        styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                  NSWindowStyleMaskResizable | NSWindowStyleMaskMiniaturizable
        backing:NSBackingStoreBuffered defer:NO];
    [window setMinSize:NSMakeSize(360, 260)]; [window setReleasedWhenClosed:NO];
    [window setDelegate:self]; return window;
}
- (NSString *)identifierForWindow:(NSWindow *)window
{
    for (NSString *identifier in _windowsById)
        if (_windowsById[identifier] == window) return identifier;
    return nil;
}
- (void)refreshSelectingId:(NSString *)snapshotId
{
    const BOOL wasVisible = [self isVisible];
    for (const auto &item : g_snapshotAlbum.items()) {
        NSString *identifier = ToNSString(item.metadata.snapshot_id);
        NSWindow *window = _windowsById[identifier];
        if (!window) {
            if ([_windowsById count] == 0) window = _window;
            else {
                window = [self newWindowForSnapshot:item];
                NSWindow *anchor = _window ?: [[_windowsById allValues] firstObject];
                [anchor addTabbedWindow:window ordered:NSWindowAbove];
            }
        }
        _windowsById[identifier] = window;
        [self installSnapshot:item inWindow:window];
    }
    if (snapshotId && wasVisible) [_windowsById[snapshotId] makeKeyAndOrderFront:nil];
    NSWindow *single = [_windowsById count] == 1 ? [[_windowsById allValues] firstObject] : nil;
    if (single && [[single tabbedWindows] count] == 1) [self setTabBarVisible:YES forWindow:single];
}
- (const rlispstat::core::SnapshotItem *)itemForSender:(id)sender
{
    NSString *identifier = [sender representedObject];
    return identifier ? g_snapshotAlbum.find(std::string([identifier UTF8String])) : nullptr;
}
- (void)renameSnapshot:(id)sender
{
    const auto *item = [self itemForSender:sender]; if (!item) return;
    const std::string identifier = item->metadata.snapshot_id;
    NSAlert *alert = [[NSAlert alloc] init]; [alert setMessageText:@"Rename Snapshot"];
    NSTextField *field = [[NSTextField alloc] initWithFrame:NSMakeRect(0, 0, 360, 26)];
    [field setStringValue:ToNSString(item->metadata.title)]; [alert setAccessoryView:field];
    [alert addButtonWithTitle:@"Rename"]; [alert addButtonWithTitle:@"Cancel"];
    if ([alert runModal] != NSAlertFirstButtonReturn) return;
    g_snapshotAlbum.rename(identifier, std::string([[field stringValue] UTF8String]));
    [self refreshSelectingId:ToNSString(identifier)];
}
- (void)toggleSnapshotNotes:(id)sender
{
    const auto *item = [self itemForSender:sender]; if (!item) return;
    NSString *identifier = ToNSString(item->metadata.snapshot_id);
    NSWindow *window = _windowsById[identifier];
    SnapshotNotesEditorView *editor = [window.contentView
        isKindOfClass:[SnapshotNotesEditorView class]]
        ? (SnapshotNotesEditorView *)window.contentView : nil;
    if (!editor) return;
    [editor toggleNotes];
    [(NSMenuItem *)sender setTitle:[editor notesVisible] ? @"Hide Notes" :
        ([editor hasNoteText] ? @"Show Notes •" : @"Show Notes")];
    [(NSMenuItem *)sender setState:[editor notesVisible]
        ? NSControlStateValueOn : NSControlStateValueOff];
}
- (void)addSnapshotSticker:(id)sender
{
    const auto *item = [self itemForSender:sender]; if (!item) return;
    NSString *identifier = ToNSString(item->metadata.snapshot_id);
    NSWindow *window = _windowsById[identifier];
    SnapshotNotesEditorView *editor = [window.contentView
        isKindOfClass:[SnapshotNotesEditorView class]]
        ? (SnapshotNotesEditorView *)window.contentView : nil;
    if (!editor) return;
    [editor addStickyNote];
    [window makeKeyAndOrderFront:nil];
}
- (void)toggleSnapshotIncluded:(id)sender
{
    const auto *item = [self itemForSender:sender]; if (!item) return;
    const BOOL included = !item->metadata.include_in_export;
    g_snapshotAlbum.setIncludedInExport(item->metadata.snapshot_id, included);
    [(NSMenuItem *)sender setState:included ? NSControlStateValueOn : NSControlStateValueOff];
}
- (void)toggleSnapshotNotesIncluded:(id)sender
{
    const auto *item = [self itemForSender:sender]; if (!item) return;
    const BOOL included = !item->metadata.include_notes;
    g_snapshotAlbum.setNotesIncluded(item->metadata.snapshot_id, included);
    [(NSMenuItem *)sender setState:included ? NSControlStateValueOn : NSControlStateValueOff];
}
- (BOOL)confirmRemovalOfItem:(const rlispstat::core::SnapshotItem &)item
{
    if (!(item.note && item.note->has_content) && item.stickers.empty()) return YES;
    NSAlert *alert = [[NSAlert alloc] init]; [alert setMessageText:@"Remove Snapshot?"];
    [alert setInformativeText:@"This snapshot has notes. The original LinkEDA window is not affected."];
    [alert addButtonWithTitle:@"Remove Snapshot"]; [alert addButtonWithTitle:@"Cancel"];
    return [alert runModal] == NSAlertFirstButtonReturn;
}
- (void)removeIdentifier:(NSString *)identifier confirm:(BOOL)confirm
{
    const auto *item = identifier
        ? g_snapshotAlbum.find(std::string([identifier UTF8String])) : nullptr;
    if (!item || (confirm && ![self confirmRemovalOfItem:*item])) return;
    NSWindow *window = _windowsById[identifier];
    g_snapshotAlbum.remove(std::string([identifier UTF8String]));
    [_windowsById removeObjectForKey:identifier];
    if ([_windowsById count] == 0) {
        _window = window ?: _window; [self installEmptyContentInWindow:_window];
        if ([[_window tabbedWindows] count] == 1) [self setTabBarVisible:NO forWindow:_window];
        return;
    }
    NSWindow *replacement = [[_windowsById allValues] firstObject];
    if (_window == window) _window = replacement;
    _removingWindow = window; [window close]; _removingWindow = nil;
    [replacement makeKeyAndOrderFront:nil];
}
- (void)removeSnapshot:(id)sender
{ [self removeIdentifier:[sender representedObject] confirm:YES]; }
- (BOOL)windowShouldClose:(NSWindow *)sender
{
    if (sender == _removingWindow) return YES;
    NSString *identifier = [self identifierForWindow:sender];
    if (identifier && [[sender tabbedWindows] count] > 1) {
        [self removeIdentifier:identifier confirm:YES]; return NO;
    }
    for (NSWindow *window in [_windowsById allValues]) [window orderOut:nil];
    [_window orderOut:nil]; return NO;
}
- (void)windowDidBecomeKey:(NSNotification *)notification
{
    NSWindow *window = [notification object];
    if (!window || !_windowsById) return;
    for (NSWindow *albumWindow in [_windowsById objectEnumerator]) {
        if (albumWindow == window) { _window = window; break; }
    }
}
- (void)synchronizeAlbumOrderFromTabs
{
    NSArray<NSWindow *> *windows = [_window tabbedWindows];
    if ([windows count] < 2) return;
    std::size_t position = 0;
    for (NSWindow *window in windows) {
        NSString *identifier = [self identifierForWindow:window];
        if (identifier) g_snapshotAlbum.move(std::string([identifier UTF8String]), position++);
    }
}
- (NSData *)albumPDFData
{
    [self synchronizeAlbumOrderFromTabs];
    const auto items = g_snapshotAlbum.exportItems(); if (items.empty()) return nil;
    NSMutableData *data = [NSMutableData data];
    CGDataConsumerRef consumer = CGDataConsumerCreateWithCFData((CFMutableDataRef)data);
    CGRect mediaBox = CGRectMake(0, 0, 842, 595);
    CGContextRef context = CGPDFContextCreate(consumer, &mediaBox, nullptr);
    for (const auto *item : items) {
        SnapshotExportPageView *page = [[SnapshotExportPageView alloc] initWithSnapshot:*item];
        const CGRect pageBox = CGRectMake(0, 0, NSWidth([page bounds]), NSHeight([page bounds]));
        CFDataRef pageBoxData = CFDataCreate(kCFAllocatorDefault,
            reinterpret_cast<const UInt8 *>(&pageBox), sizeof(pageBox));
        const void *keys[] = { kCGPDFContextMediaBox };
        const void *values[] = { pageBoxData };
        CFDictionaryRef pageInfo = CFDictionaryCreate(kCFAllocatorDefault, keys, values, 1,
            &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
        CGPDFContextBeginPage(context, pageInfo);
        CFRelease(pageInfo); CFRelease(pageBoxData);
        CGContextSaveGState(context); CGContextTranslateCTM(context, 0, NSHeight([page bounds])); CGContextScaleCTM(context, 1, -1);
        NSGraphicsContext *graphics = [NSGraphicsContext graphicsContextWithCGContext:context flipped:YES];
        [NSGraphicsContext saveGraphicsState]; [NSGraphicsContext setCurrentContext:graphics];
        [page displayRectIgnoringOpacity:[page bounds] inContext:graphics];
        [NSGraphicsContext restoreGraphicsState]; CGContextRestoreGState(context);
        CGPDFContextEndPage(context);
    }
    CGPDFContextClose(context); CGContextRelease(context); CGDataConsumerRelease(consumer);
    return data;
}
- (BOOL)writeManifestToFolder:(NSURL *)folder error:(NSError **)error
{
    NSData *data = [ToNSString(rlispstat::core::SnapshotAlbumManifestCSV(g_snapshotAlbum))
        dataUsingEncoding:NSUTF8StringEncoding];
    return [data writeToURL:[folder URLByAppendingPathComponent:@"manifest.csv"]
                    options:NSDataWritingAtomic error:error];
}
- (void)exportPDF
{
    NSSavePanel *panel = [NSSavePanel savePanel]; SetSavePanelExtensionCompat(panel, @"pdf");
    [panel setNameFieldStringValue:@"LinkEDA-Snapshot-Album.pdf"];
    if ([panel runModal] != NSModalResponseOK) return;
    NSError *error = nil; NSData *data = [self albumPDFData];
    if (!data || ![data writeToURL:[panel URL] options:NSDataWritingAtomic error:&error])
        ShowWorkbenchMessageOnMain(@"Export Snapshot Album", error ? [error localizedDescription] : @"No snapshots are included in export.");
}
- (NSURL *)chooseExportFolder:(NSString *)title
{
    NSOpenPanel *panel = [NSOpenPanel openPanel]; [panel setTitle:title];
    [panel setCanChooseDirectories:YES]; [panel setCanChooseFiles:NO];
    [panel setCanCreateDirectories:YES]; [panel setAllowsMultipleSelection:NO];
    return [panel runModal] == NSModalResponseOK ? [panel URL] : nil;
}
- (void)exportSVGFiles
{
    NSURL *folder = [self chooseExportFolder:@"Export Snapshot Album as SVG Files"]; if (!folder) return;
    NSError *error = nil; std::size_t order = 0;
    for (const auto *item : g_snapshotAlbum.exportItems()) {
        ++order; std::string svg;
        if (const auto *plot = std::get_if<rlispstat::core::FrozenPlotContent>(&item->renderable_content)) {
            const std::string &kind = plot->model.kind;
            const bool hasPortableVectorRenderer =
                kind == "scatter" || kind == "time_series" || kind == "histogram" ||
                kind == "barplot" || kind == "boxplot" || kind == "trellis_scatterplot" ||
                kind == "glm_interaction" || kind == "interaction_plot";
            if (hasPortableVectorRenderer) {
                svg = rlispstat::core::BuildSvgPlotSnapshotDocument(
                    plot->model, item->metadata.theme_name, item->metadata.title,
                    plot->preferred_width, plot->preferred_height).svg;
            } else {
                // Preserve the existing high-fidelity image export for plot types whose
                // portable vector renderer has not been implemented yet.
                SnapshotExportPageView *page = [[SnapshotExportPageView alloc] initWithSnapshot:*item];
                NSData *png = HighResolutionPNGDataForView(page);
                if (!png) {
                    error = [NSError errorWithDomain:@"LinkEDA.SnapshotAlbum" code:1
                        userInfo:@{NSLocalizedDescriptionKey:
                            @"LinkEDA could not render a snapshot for SVG export."}];
                    break;
                }
                NSString *encoded = [png base64EncodedStringWithOptions:0];
                std::ostringstream out;
                out << "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"" << plot->preferred_width
                    << "\" height=\"" << plot->preferred_height << "\" viewBox=\"0 0 "
                    << plot->preferred_width << " " << plot->preferred_height << "\">"
                    << "<image width=\"100%\" height=\"100%\" href=\"data:image/png;base64,"
                    << [encoded UTF8String] << "\"/></svg>";
                svg = out.str();
            }
        } else if (const auto *image = std::get_if<rlispstat::core::FrozenImageContent>(&item->renderable_content)) {
            NSData *png = [NSData dataWithBytes:image->png_data.data() length:image->png_data.size()];
            NSString *encoded = [png base64EncodedStringWithOptions:0];
            std::ostringstream out;
            out << "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"" << image->preferred_width
                << "\" height=\"" << image->preferred_height << "\" viewBox=\"0 0 "
                << image->preferred_width << " " << image->preferred_height << "\">"
                << "<image width=\"100%\" height=\"100%\" href=\"data:image/png;base64,"
                << [encoded UTF8String] << "\"/></svg>";
            svg = out.str();
        } else if (const auto *table = std::get_if<rlispstat::core::FrozenTableContent>(
                       &item->renderable_content)) {
            svg = rlispstat::core::BuildSvgTableDocument(item->metadata.title,
                rlispstat::core::FrozenTableToTabDelimited(*table)).svg;
        } else {
            const auto &text = std::get<rlispstat::core::FrozenTextContent>(
                item->renderable_content);
            svg = rlispstat::core::BuildSvgTableDocument(item->metadata.title,
                std::string("Output\n") + text.plain_text).svg;
        }
        if (item->metadata.include_notes) {
            svg = rlispstat::core::ComposeSvgDocumentWithWindowStickyNotes(svg, item->stickers);
            if (item->note && item->note->has_content)
                svg = rlispstat::core::ComposeSvgDocumentWithWindowNote(svg,
                    {"Notes", item->note->plain_text});
        }
        NSString *name = [NSString stringWithFormat:@"%03lu-%@.svg", (unsigned long)order,
            ToNSString(rlispstat::core::SafeExportBaseName(item->metadata.title, "snapshot"))];
        NSData *data = [ToNSString(svg) dataUsingEncoding:NSUTF8StringEncoding];
        if (![data writeToURL:[folder URLByAppendingPathComponent:name]
                      options:NSDataWritingAtomic error:&error]) break;
    }
    if (!error) [self writeManifestToFolder:folder error:&error];
    if (error) ShowWorkbenchMessageOnMain(@"Export Snapshot Album", [error localizedDescription]);
}
- (void)exportPNGFiles
{
    NSURL *folder = [self chooseExportFolder:@"Export Snapshot Album as PNG Files"]; if (!folder) return;
    NSError *error = nil; std::size_t order = 0;
    for (const auto *item : g_snapshotAlbum.exportItems()) {
        ++order; SnapshotExportPageView *page = [[SnapshotExportPageView alloc] initWithSnapshot:*item];
        NSData *data = HighResolutionPNGDataForView(page);
        NSString *name = [NSString stringWithFormat:@"%03lu-%@.png", (unsigned long)order,
            ToNSString(rlispstat::core::SafeExportBaseName(item->metadata.title, "snapshot"))];
        if (!data) {
            error = [NSError errorWithDomain:@"LinkEDA.SnapshotAlbum" code:1
                userInfo:@{NSLocalizedDescriptionKey:
                    @"LinkEDA could not render a snapshot as a high-resolution PNG."}];
            break;
        }
        if (![data writeToURL:[folder URLByAppendingPathComponent:name]
                       options:NSDataWritingAtomic error:&error]) break;
    }
    if (!error) [self writeManifestToFolder:folder error:&error];
    if (error) ShowWorkbenchMessageOnMain(@"Export Snapshot Album", [error localizedDescription]);
}
- (void)exportAlbum:(id)sender
{
    (void)sender; [self synchronizeAlbumOrderFromTabs];
    if (g_snapshotAlbum.exportItems().empty()) {
        ShowWorkbenchMessageOnMain(@"Export Snapshot Album", @"No snapshots are included in export."); return;
    }
    NSAlert *alert = [[NSAlert alloc] init]; [alert setMessageText:@"Export Snapshot Album"];
    [alert setInformativeText:@"Choose an export format. PDF is one multipage document; SVG and PNG create numbered files plus manifest.csv."];
    [alert addButtonWithTitle:@"PDF…"]; [alert addButtonWithTitle:@"SVG Files…"];
    [alert addButtonWithTitle:@"PNG Files…"]; [alert addButtonWithTitle:@"Cancel"];
    NSModalResponse response = [alert runModal];
    if (response != NSAlertFirstButtonReturn &&
        response != NSAlertSecondButtonReturn &&
        response != NSAlertThirdButtonReturn) return;
    // Let AppKit completely tear down the format-selection alert before
    // presenting the save/open panel.  Presenting two application-modal
    // dialogs back-to-back from a context-menu action can otherwise cause
    // macOS to silently discard the second panel.
    dispatch_async(dispatch_get_main_queue(), ^{
        [NSApp activateIgnoringOtherApps:YES];
        if (response == NSAlertFirstButtonReturn) [self exportPDF];
        else if (response == NSAlertSecondButtonReturn) [self exportSVGFiles];
        else [self exportPNGFiles];
    });
}
@end

static BOOL ActiveWindowSupportsSnapshotAlbum()
{
    return SnapshotAlbumSourceWindow() != nil;
}

static BOOL SnapshotAlbumIsVisible()
{
    return g_snapshotAlbumController && [g_snapshotAlbumController isVisible];
}

static void ShowSnapshotAlbumOnMain()
{
    (void)SnapshotAlbumSourceWindow();
    if (!g_snapshotAlbumController) g_snapshotAlbumController = [[SnapshotAlbumWindowController alloc] init];
    [g_snapshotAlbumController show];
}

static void AddWindowToSnapshotAlbumOnMain(NSWindow *sourceWindow, BOOL showWhenFirst)
{
    auto captured = CaptureSnapshotFromWindow(sourceWindow);
    if (!captured) {
        ShowWorkbenchMessageOnMain(@"Snapshot Album",
            @"This window cannot yet be frozen as a structured snapshot.");
        return;
    }
    const BOOL first = g_snapshotAlbum.empty();
    auto &added = g_snapshotAlbum.add(std::move(*captured));
    std::fprintf(stderr, "LinkEDA Snapshot Album: added %s (%zu bytes estimated)\n",
        added.metadata.snapshot_id.c_str(), rlispstat::core::EstimateSnapshotMemoryBytes(added));
    if (!g_snapshotAlbumController) g_snapshotAlbumController = [[SnapshotAlbumWindowController alloc] init];
    [g_snapshotAlbumController refreshSelectingId:ToNSString(added.metadata.snapshot_id)];
    if (first && showWhenFirst) [g_snapshotAlbumController show];
}

static void AddActiveWindowToSnapshotAlbumOnMain()
{
    AddWindowToSnapshotAlbumOnMain(SnapshotAlbumSourceWindow(), YES);
}

static void AddSnapshotAlbumContextItems(NSMenu *menu)
{
    if (!menu) return;
    WindowNotesContainer *notes = ActiveWindowNotesContainer();
    NSWindow *sourceWindow = notes ? [notes window] : [NSApp keyWindow];
    NSMenuItem *annotateRoot = nil;
    for (NSMenuItem *item in [menu itemArray]) {
        if ([[item title] hasPrefix:@"Annotate"]) {
            annotateRoot = item;
            break;
        }
    }
    if (!annotateRoot) {
        annotateRoot = [[NSMenuItem alloc] initWithTitle:@"Annotate" action:nil keyEquivalent:@""];
        [annotateRoot setSubmenu:[[NSMenu alloc] initWithTitle:@"Annotate"]];
        const NSInteger exportIndex = [menu indexOfItemWithTitle:@"Export"];
        if (exportIndex >= 0) [menu insertItem:annotateRoot atIndex:exportIndex];
        else [menu addItem:annotateRoot];
    }
    NSMenu *annotateMenu = [annotateRoot submenu];
    if (notes) {
        NSMenuItem *notesRoot = [notes annotateContextMenuItem];
        NSMenu *notesMenu = [notesRoot submenu];
        if (notesMenu) {
            NSArray<NSMenuItem *> *noteItems = [[notesMenu itemArray] copy];
            for (NSMenuItem *item in noteItems) {
                [notesMenu removeItem:item];
                [annotateMenu addItem:item];
            }
        } else {
            [annotateMenu addItem:notesRoot];
        }
    }
    if ([annotateMenu numberOfItems] > 0 && ![[annotateMenu itemAtIndex:[annotateMenu numberOfItems] - 1] isSeparatorItem])
        [annotateMenu addItem:[NSMenuItem separatorItem]];
    if (!g_snapshotAlbumContextActionTarget)
        g_snapshotAlbumContextActionTarget = [[SnapshotAlbumContextActionTarget alloc] init];
    NSMenuItem *add = [[NSMenuItem alloc] initWithTitle:@"Add Snapshot to Snapshot Album"
                                                  action:@selector(addSnapshotFromContext:)
                                           keyEquivalent:@""];
    [add setTarget:g_snapshotAlbumContextActionTarget];
    [add setRepresentedObject:[NSValue valueWithNonretainedObject:sourceWindow]];
    [add setEnabled:SnapshotWindowSupportsCapture(sourceWindow)];
    [annotateMenu addItem:add];
    [annotateMenu addItem:PlotCommandMenuItem(@"Show Snapshot Album", @"SNAPSHOT_ALBUM_SHOW")];
}

static void AddMenuItemWithoutDuplicateSeparators(NSMenu *menu, NSMenuItem *item)
{
    if (!menu || !item) return;
    if ([item isSeparatorItem]) {
        if ([menu numberOfItems] == 0 || [[menu itemAtIndex:[menu numberOfItems] - 1] isSeparatorItem]) return;
    }
    [menu addItem:item];
}

static void MoveSubmenuContents(NSMenu *destination, NSMenu *source)
{
    if (!destination || !source) return;
    NSArray<NSMenuItem *> *items = [[source itemArray] copy];
    for (NSMenuItem *item in items) {
        [source removeItem:item];
        AddMenuItemWithoutDuplicateSeparators(destination, item);
    }
}

static NSMenuItem *GraphMenuRoot(NSString *title, NSMenu **submenuOut)
{
    NSMenuItem *root = [[NSMenuItem alloc] initWithTitle:title action:nil keyEquivalent:@""];
    NSMenu *submenu = [[NSMenu alloc] initWithTitle:title];
    [root setSubmenu:submenu];
    if (submenuOut) *submenuOut = submenu;
    return root;
}

static BOOL GraphMenuTitleIsOneOf(NSString *title, NSArray<NSString *> *choices)
{
    for (NSString *choice in choices) if ([title caseInsensitiveCompare:choice] == NSOrderedSame) return YES;
    return NO;
}

static void NormalizeGraphSubmenuSeparators(NSMenu *menu)
{
    if (!menu) return;
    for (NSInteger index = [menu numberOfItems] - 1; index >= 0; --index) {
        NSMenuItem *item = [menu itemAtIndex:index];
        const BOOL leading = index == 0;
        const BOOL trailing = index == [menu numberOfItems] - 1;
        const BOOL duplicate = index > 0 && [[menu itemAtIndex:index - 1] isSeparatorItem];
        if ([item isSeparatorItem] && (leading || trailing || duplicate))
            [menu removeItemAtIndex:index];
    }
}

static NSMenuItem *GraphColorsRoot(NSMenu *selectionMenu)
{
    if (!selectionMenu) return nil;
    NSMenuItem *root = [selectionMenu itemWithTitle:@"Colors"];
    if (!root) {
        root = [[NSMenuItem alloc] initWithTitle:@"Colors" action:nil keyEquivalent:@""];
        [root setSubmenu:[[NSMenu alloc] initWithTitle:@"Colors"]];
        AddMenuItemWithoutDuplicateSeparators(selectionMenu, root);
    }
    return root;
}

static void RouteGraphColorMenuItem(NSMenuItem *item, NSMenu *selectionMenu)
{
    if (!item || !selectionMenu) return;
    NSMenuItem *colorsRoot = GraphColorsRoot(selectionMenu);
    NSMenu *colors = [colorsRoot submenu];
    if ([[item title] caseInsensitiveCompare:@"Colors"] == NSOrderedSame && [item submenu]) {
        if (item == colorsRoot) return;
        MoveSubmenuContents(colors, [item submenu]);
    } else {
        AddMenuItemWithoutDuplicateSeparators(colors, item);
    }
    NormalizeGraphSubmenuSeparators(colors);
}

static void RouteGraphConditioningMenuItem(NSMenuItem *item,
                                           NSMenu *conditioningMenu,
                                           NSMenu *selectionMenu)
{
    if (!item || !conditioningMenu) return;
    NSString *title = [item title] ?: @"";
    const BOOL isContainer = GraphMenuTitleIsOneOf(title,
        @[@"Conditioning variables", @"Conditioning variable", @"Group / Condition"]);
    if (!isContainer || ![item submenu]) {
        AddMenuItemWithoutDuplicateSeparators(conditioningMenu, item);
        return;
    }
    NSArray<NSMenuItem *> *children = [[[item submenu] itemArray] copy];
    for (NSMenuItem *child in children) {
        [[item submenu] removeItem:child];
        NSString *childTitle = [child title] ?: @"";
        if (GraphMenuTitleIsOneOf(childTitle, @[@"Colors", @"Override colors by", @"Color by"]))
            RouteGraphColorMenuItem(child, selectionMenu);
        else if (GraphMenuTitleIsOneOf(childTitle,
                     @[@"Conditioning variables", @"Conditioning variable", @"Group / Condition"]))
            RouteGraphConditioningMenuItem(child, conditioningMenu, selectionMenu);
        else AddMenuItemWithoutDuplicateSeparators(conditioningMenu, child);
    }
    NormalizeGraphSubmenuSeparators(conditioningMenu);
}

static BOOL GraphMenuItemIsCaseColorControl(NSMenuItem *item)
{
    if (!item || [item isSeparatorItem]) return NO;
    NSString *lower = [[item title] lowercaseString] ?: @"";
    NSString *command = [[item representedObject] isKindOfClass:[NSString class]]
        ? (NSString *)[item representedObject] : @"";
    NSString *actionName = [item action]
        ? [NSStringFromSelector([item action]) lowercaseString] : @"";
    return [lower hasPrefix:@"color selected"] ||
        [lower hasPrefix:@"colour selected"] ||
        [lower hasPrefix:@"open color palette"] ||
        [lower hasPrefix:@"data points color"] ||
        ([lower hasPrefix:@"reset selected"] && [lower containsString:@"color"]) ||
        [command hasPrefix:@"OPEN_COLOR_PALETTE"] ||
        [actionName containsString:@"colordendrogram"] ||
        [actionName containsString:@"colorselected"] ||
        [actionName containsString:@"resetselected"] ||
        [actionName containsString:@"open"] && [actionName containsString:@"palette"];
}

static void ConsolidateGraphColorControls(NSMenu *selectionMenu)
{
    if (!selectionMenu) return;
    NSMenuItem *colorsRoot = [selectionMenu itemWithTitle:@"Colors"];
    NSMutableArray<NSMenuItem *> *controls = [NSMutableArray array];
    NSInteger firstControlIndex = NSNotFound;
    NSArray<NSMenuItem *> *selectionItems = [[selectionMenu itemArray] copy];
    for (NSMenuItem *item in selectionItems) {
        if (item == colorsRoot || !GraphMenuItemIsCaseColorControl(item)) continue;
        if (firstControlIndex == NSNotFound)
            firstControlIndex = [selectionMenu indexOfItem:item];
        [item retain];
        [selectionMenu removeItem:item];
        [controls addObject:item];
        [item release];
    }
    if ([controls count] == 0) return;

    if (!colorsRoot) {
        colorsRoot = [[NSMenuItem alloc] initWithTitle:@"Colors" action:nil keyEquivalent:@""];
        [colorsRoot setSubmenu:[[NSMenu alloc] initWithTitle:@"Colors"]];
        const NSInteger insertion = firstControlIndex == NSNotFound
            ? [selectionMenu numberOfItems]
            : std::min(firstControlIndex, [selectionMenu numberOfItems]);
        [selectionMenu insertItem:colorsRoot atIndex:insertion];
    }

    NSMenu *colors = [colorsRoot submenu];
    NSArray<NSMenuItem *> *existing = [[colors itemArray] copy];
    [colors removeAllItems];
    NSMutableArray<NSMenuItem *> *statusItems = [NSMutableArray array];
    NSMutableArray<NSMenuItem *> *persistentItems = [NSMutableArray array];
    for (NSMenuItem *item in existing) {
        if ([item isSeparatorItem]) continue;
        if ([[item title] hasPrefix:@"Colors:"]) [statusItems addObject:item];
        else [persistentItems addObject:item];
    }
    for (NSMenuItem *item in statusItems) [colors addItem:item];
    if ([statusItems count] > 0) [colors addItem:[NSMenuItem separatorItem]];
    for (NSMenuItem *item in controls) [colors addItem:item];
    if ([persistentItems count] > 0) [colors addItem:[NSMenuItem separatorItem]];
    for (NSMenuItem *item in persistentItems) [colors addItem:item];
    NormalizeGraphSubmenuSeparators(colors);
    NormalizeGraphSubmenuSeparators(selectionMenu);
}

static NSMenu *FinalizeGraphContextMenu(NSMenu *menu)
{
    if (!menu) return menu;
    NSMenu *variablesMenu = nil, *conditioningMenu = nil, *displayMenu = nil, *selectionMenu = nil;
    NSMenu *analyzeMenu = nil, *annotateMenu = nil, *exportMenu = nil;
    NSMenuItem *variablesRoot = GraphMenuRoot(@"Variables", &variablesMenu);
    NSMenuItem *conditioningRoot = GraphMenuRoot(@"Conditioning variables", &conditioningMenu);
    NSMenuItem *displayRoot = GraphMenuRoot(@"Display", &displayMenu);
    NSMenuItem *selectionRoot = GraphMenuRoot(@"Explore plot", &selectionMenu);
    NSMenuItem *analyzeRoot = GraphMenuRoot(@"Analyze", &analyzeMenu);
    NSMenuItem *annotateRoot = GraphMenuRoot(@"Annotate", &annotateMenu);
    NSMenuItem *exportRoot = GraphMenuRoot(@"Export", &exportMenu);

    NSArray<NSMenuItem *> *items = [[menu itemArray] copy];
    [menu removeAllItems];
    for (NSMenuItem *item in items) {
        if ([item isSeparatorItem]) continue;
        NSString *title = [item title] ?: @"";
        NSString *lower = [title lowercaseString];
        NSString *representedCommand = [[item representedObject] isKindOfClass:[NSString class]]
            ? (NSString *)[item representedObject] : @"";
        if ([lower isEqualToString:@"close plot"] || [lower isEqualToString:@"show data sheet"] ||
            [representedCommand isEqualToString:@"CLOSE_PLOT"] ||
            [representedCommand hasPrefix:@"SHOW_DATA_SHEET"]) continue;
        if ([lower isEqualToString:@"plot"]) continue;

        if ([title caseInsensitiveCompare:@"Variables"] == NSOrderedSame) {
            NSMenu *source = [item submenu];
            NSArray<NSMenuItem *> *variableItems = [[source itemArray] copy];
            for (NSMenuItem *variableItem in variableItems) {
                [source removeItem:variableItem];
                NSString *variableTitle = [variableItem title] ?: @"";
                if (GraphMenuTitleIsOneOf(variableTitle,
                        @[@"Colors", @"Override colors by", @"Color by"]))
                    RouteGraphColorMenuItem(variableItem, selectionMenu);
                else if (GraphMenuTitleIsOneOf(variableTitle,
                             @[@"Conditioning variables", @"Conditioning variable", @"Group / Condition"]))
                    RouteGraphConditioningMenuItem(variableItem, conditioningMenu, selectionMenu);
                else if ([variableTitle caseInsensitiveCompare:@"Color legend"] == NSOrderedSame)
                    AddMenuItemWithoutDuplicateSeparators(displayMenu, variableItem);
                else AddMenuItemWithoutDuplicateSeparators(variablesMenu, variableItem);
            }
        } else if ([title caseInsensitiveCompare:@"Boxplot"] == NSOrderedSame) {
            NSMenu *boxplotMenu = [item submenu];
            NSArray<NSMenuItem *> *boxplotItems = [[boxplotMenu itemArray] copy];
            for (NSMenuItem *boxplotItem in boxplotItems) {
                [boxplotMenu removeItem:boxplotItem];
                NSString *boxplotTitle = [[boxplotItem title] lowercaseString];
                if ([boxplotTitle hasPrefix:@"add variable"] ||
                    [boxplotTitle hasPrefix:@"remove variable"] ||
                    [boxplotTitle hasPrefix:@"grouping variable"]) {
                    AddMenuItemWithoutDuplicateSeparators(variablesMenu, boxplotItem);
                } else {
                    AddMenuItemWithoutDuplicateSeparators(displayMenu, boxplotItem);
                }
            }
        } else if ([title caseInsensitiveCompare:@"Bar chart"] == NSOrderedSame) {
            NSMenu *barMenu = [item submenu];
            NSArray<NSMenuItem *> *barItems = [[barMenu itemArray] copy];
            for (NSMenuItem *barItem in barItems) {
                [barMenu removeItem:barItem];
                NSString *barTitle = [[barItem title] lowercaseString];
                if ([barTitle isEqualToString:@"colors"] ||
                    [barTitle hasPrefix:@"color by"]) {
                    RouteGraphColorMenuItem(barItem, selectionMenu);
                } else if ([barTitle hasPrefix:@"conditioning variable"]) {
                    RouteGraphConditioningMenuItem(barItem, conditioningMenu, selectionMenu);
                } else if ([barTitle containsString:@"categor"] || [barTitle hasPrefix:@"split variable"] ||
                    [barTitle hasPrefix:@"x variable"] || [barTitle isEqualToString:@"x axis"]) {
                    AddMenuItemWithoutDuplicateSeparators(variablesMenu, barItem);
                } else {
                    AddMenuItemWithoutDuplicateSeparators(displayMenu, barItem);
                }
            }
        } else if (GraphMenuTitleIsOneOf(title, @[@"Split variable",
                                                  @"Series variable", @"Displayed variables",
                                                  @"Grouping variables", @"X variable", @"Y variable",
                                                  @"Change X Variable", @"Change Y Variable", @"Variable"])) {
            AddMenuItemWithoutDuplicateSeparators(variablesMenu, item);
        } else if (GraphMenuTitleIsOneOf(title, @[@"Selection", @"Explore plot"])) {
            MoveSubmenuContents(selectionMenu, [item submenu]);
        } else if ([lower hasPrefix:@"global analysis scope"]) {
            // Case inclusion is an exploration action as well as a scope
            // control.  Keep the complete scope menu and surface its case
            // actions directly in Explore plot, matching the Windows layout.
            NSMenu *scopeMenu = [item submenu];
            BOOL addedCaseActions = NO;
            for (NSString *caseTitle in @[@"Exclude selected cases from all analyses",
                                           @"Include selected cases again",
                                           @"Include all cases again"]) {
                NSMenuItem *source = [scopeMenu itemWithTitle:caseTitle];
                NSString *command = [source representedObject];
                if (!source || ![command isKindOfClass:[NSString class]]) continue;
                if (!addedCaseActions && [selectionMenu numberOfItems] > 0)
                    [selectionMenu addItem:[NSMenuItem separatorItem]];
                NSMenuItem *direct = PlotCommandMenuItem([source title], command);
                [direct setEnabled:[source isEnabled]];
                AddMenuItemWithoutDuplicateSeparators(selectionMenu, direct);
                addedCaseActions = YES;
            }
            AddMenuItemWithoutDuplicateSeparators(analyzeMenu, item);
        } else if (GraphMenuTitleIsOneOf(title, @[@"Mouse Mode", @"Brush"])) {
            AddMenuItemWithoutDuplicateSeparators(selectionMenu, item);
        } else if ([title caseInsensitiveCompare:@"Analyze"] == NSOrderedSame) {
            MoveSubmenuContents(analyzeMenu, [item submenu]);
        } else if ([lower hasPrefix:@"analyze"] || [lower hasPrefix:@"analysis scope"] ||
                   [lower hasPrefix:@"set scope for future analyses"]) {
            AddMenuItemWithoutDuplicateSeparators(analyzeMenu, item);
        } else if ([lower hasPrefix:@"annotate"]) {
            MoveSubmenuContents(annotateMenu, [item submenu]);
            if ([title hasSuffix:@"•"]) [annotateRoot setTitle:@"Annotate •"];
        } else if ([title caseInsensitiveCompare:@"Export"] == NSOrderedSame) {
            MoveSubmenuContents(exportMenu, [item submenu]);
        } else if ([title caseInsensitiveCompare:@"View"] == NSOrderedSame ||
                   [title caseInsensitiveCompare:@"Display"] == NSOrderedSame) {
            MoveSubmenuContents(displayMenu, [item submenu]);
        } else if (GraphMenuTitleIsOneOf(title, @[@"Colors", @"Override colors by", @"Color by"])) {
            RouteGraphColorMenuItem(item, selectionMenu);
        } else if (GraphMenuTitleIsOneOf(title,
                       @[@"Conditioning variables", @"Conditioning variable", @"Group / Condition"])) {
            RouteGraphConditioningMenuItem(item, conditioningMenu, selectionMenu);
        } else if (GraphMenuTitleIsOneOf(title, @[@"Labels", @"Regression lines", @"Overlays", @"Smooth curves",
                                                  @"Series identification", @"Panel content",
                                                  @"Conditioning dimensions", @"Panel arrangement",
                                                  @"Panel order", @"Scales", @"Bar measure",
                                                  @"Histogram", @"Histogram scale", @"Bins",
                                                  @"Legend position", @"Color legend", @"Group order",
                                                  @"Lines and overlays", @"Column widths", @"Scrolling",
                                                  @"Density curves", @"Experimental"])) {
            AddMenuItemWithoutDuplicateSeparators(displayMenu, item);
        } else if (GraphMenuTitleIsOneOf(title, @[@"Copy"])) {
            AddMenuItemWithoutDuplicateSeparators(exportMenu, item);
        } else {
            NSString *command = representedCommand;
            NSString *actionName = [item action] ? [NSStringFromSelector([item action]) lowercaseString] : @"";
            if ([command hasPrefix:@"SELECT_"] || [command isEqualToString:@"CLEAR_SELECTION"]) {
                AddMenuItemWithoutDuplicateSeparators(selectionMenu, item);
            } else if ([actionName containsString:@"select"] || [actionName containsString:@"palette"] ||
                       [actionName containsString:@"colorselected"] || [actionName containsString:@"resetselected"]) {
                AddMenuItemWithoutDuplicateSeparators(selectionMenu, item);
            } else {
                // Plot-specific presentation controls remain available without
                // creating extra root categories.
                AddMenuItemWithoutDuplicateSeparators(displayMenu, item);
            }
        }
    }

    ConsolidateGraphColorControls(selectionMenu);
    for (NSMenu *submenu in @[variablesMenu, conditioningMenu, displayMenu, selectionMenu, analyzeMenu, annotateMenu, exportMenu]) {
        while ([submenu numberOfItems] > 0 && [[submenu itemAtIndex:[submenu numberOfItems] - 1] isSeparatorItem])
            [submenu removeItemAtIndex:[submenu numberOfItems] - 1];
    }
    if ([variablesMenu numberOfItems] > 0) [menu addItem:variablesRoot];
    if ([conditioningMenu numberOfItems] > 0) [menu addItem:conditioningRoot];
    if ([displayMenu numberOfItems] > 0) [menu addItem:displayRoot];
    if ([selectionMenu numberOfItems] > 0) [menu addItem:selectionRoot];
    if ([analyzeMenu numberOfItems] > 0) [menu addItem:analyzeRoot];
    if ([annotateMenu numberOfItems] > 0) [menu addItem:annotateRoot];
    OrganizeExportMenu(exportMenu);
    if ([exportMenu numberOfItems] > 0) [menu addItem:exportRoot];
    return menu;
}

static NSMenu *SnapshotAlbumMenu(NSMenu *menu, NSString *fallbackTitle)
{
    if (!menu) menu = [[NSMenu alloc] initWithTitle:fallbackTitle ?: @"Snapshot Album"];
    AddSnapshotAlbumContextItems(menu);
    return menu;
}

using rlispstat::platform::macos::ReadLine;
using rlispstat::platform::macos::WriteReply;

static void AddPlotOnMain(PlotModel *model)
{
    dispatch_async(dispatch_get_main_queue(), ^{
      InstallApplicationMenuBar();
      NSView *contentView = nil;
      NSView *plotView = nil;
      if (model->kind == "boxplot") {
          plotView = [[BoxplotView alloc] initWithModel:model];
      } else if (model->kind == "histogram") {
          HistogramView *histogramView = [[HistogramView alloc] initWithModel:model];
          plotView = histogramView;
      } else if (model->kind == "barplot") {
          plotView = [[BarplotView alloc] initWithModel:model];
      } else {
          plotView = [[ScatterView alloc] initWithModel:model];
      }
      contentView = [[WindowNotesContainer alloc]
          initWithContentView:plotView viewId:model->id contextName:@"this graph"];
      CGFloat windowWidth = 720.0;
      CGFloat windowHeight = 520.0;
      if (model->kind == "barplot") {
          rlispstat::core::BarplotViewSize preferred = rlispstat::core::BarplotPreferredViewSize(
              model->barplotBins.size(),
              !model->barplotSplitVariable.empty(),
              BarplotXVariablesForModel(model).size());
          windowWidth = (CGFloat)preferred.width;
          windowHeight = (CGFloat)preferred.height;
      } else if (model->kind == "trellis_scatterplot") {
          rlispstat::core::TrellisViewSize preferred =
              rlispstat::core::TrellisScatterplotPreferredViewSize(model->trellisPanelLevels.size());
          windowWidth = (CGFloat)preferred.width;
          windowHeight = (CGFloat)preferred.height;
      }
      NSRect frame = NextWindowFrameOnMain(windowWidth, windowHeight);
      NSWindow *window = [[NSWindow alloc]
          initWithContentRect:frame
                    styleMask:(NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable)
                      backing:NSBackingStoreBuffered
                        defer:NO];
      [window setTitle:ToNSString(PlotWindowTitleWithAnalysisScope(*model))];
      if (model->kind == "glm_interaction" || model->kind == "interaction_plot")
          [window setContentMinSize:NSMakeSize(520.0, 440.0)];
      [window setContentView:contentView];
      std::string dataSheetGroup;
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          dataSheetGroup = MacCommandDispatcher().applicationState()
              .dataSheetGroupForPlotGroup(model->group);
      }
      SetWindowDataSheetGroupOnMac(window, dataSheetGroup);
      [window makeKeyAndOrderFront:nil];
      [window makeFirstResponder:plotView];
      [NSApp activateIgnoringOtherApps:YES];
      [NSApp setMainMenu:[NSApp mainMenu]];
      {
          std::lock_guard<std::mutex> lock(g_mutex);
          if (model->kind == "boxplot") {
              g_boxplotViews.push_back((BoxplotView *)plotView);
          } else if (model->kind == "histogram") {
              g_histogramViews.push_back((HistogramView *)plotView);
          } else if (model->kind == "barplot") {
              g_barplotViews.push_back((BarplotView *)plotView);
          } else {
              g_views.push_back((ScatterView *)plotView);
          }
          (void)MacPlotCoordinator().activatePlot(model->id);
          MarkActiveDatasetGroupUnlocked(
            MacCommandDispatcher().applicationState().dataSheetGroupForPlotGroup(model->group));
      }
      if (rlispstat::core::PlotIsImputationDiagnostic(*model) ||
          (model->isRegressionDerivedPlot && rlispstat::core::IsPooledRegressionEffectPlot(*model))) {
          const std::string plotId = model->id;
          PlotModel *closedModel = model;
          NSView *closedPlotView = plotView;
          [[NSNotificationCenter defaultCenter]
              addObserverForName:NSWindowWillCloseNotification
                          object:window
                           queue:[NSOperationQueue mainQueue]
                      usingBlock:^(NSNotification *note) {
              // The native close button used to dispose only the NSWindow.
              // That left the derived plot in g_plots, so a later request
              // refreshed an invisible model and never opened a new window.
              dispatch_async(dispatch_get_main_queue(), ^{
                  std::lock_guard<std::mutex> lock(g_mutex);
                  g_views.erase(
                      std::remove_if(g_views.begin(), g_views.end(),
                          [&](ScatterView *view) {
                              return view == (ScatterView *)closedPlotView;
                          }),
                      g_views.end());
                  auto found = g_plots.find(plotId);
                  if (found != g_plots.end() && found->second == closedModel) {
                      (void)DetachPlotModelUnlocked(plotId);
                  }
              });
              (void)note;
          }];
      }
      UpdateActiveDatasetMenuOnMain();
      UpdatePanelOnMain();
    });
}

static bool DetachPlotModelUnlocked(const std::string &plotId, std::string *groupOut, PlotModel **modelOut)
{
    auto it = g_plots.find(plotId);
    if (it == g_plots.end()) {
        return false;
    }
    PlotModel *model = it->second;
    std::string group = model ? model->group : "";
    if (groupOut) *groupOut = group;
    if (modelOut) *modelOut = model;
    const auto coordination = MacPlotCoordinator().detachPlot(plotId);
    if (!coordination.accepted) return false;
    if (coordination.event.groupHasPlots) {
        return true;
    }

    rlispstat::core::RemovedGroupDomainState removed =
        MacCommandDispatcher().applicationState().removeGroupDomainState(group);
    g_variableControllers.erase(group);
    for (const std::string &id : removed.correlationIds) {
        g_correlationMatrixControllers.erase(id);
    }
    for (const std::string &id : removed.dimensionalityIds) {
        g_dimensionalityControllers.erase(id);
    }
    for (const std::string &id : removed.scaleAnalysisIds) {
        g_scaleAnalysisControllers.erase(id);
        g_scaleAnalysisDerivedControllers.erase(id);
    }
    for (const std::string &id : removed.dendrogramIds) {
        g_dendrogramControllers.erase(id);
    }
    for (const std::string &id : removed.generalizedGlmIds) {
        g_generalizedGLMControllers.erase(id);
    }
    for (const std::string &id : removed.generalizedComparisonIds) {
        g_generalizedComparisonControllers.erase(id);
    }
    for (const std::string &id : removed.mixedModelIds) {
        g_mixedModelControllers.erase(id);
    }
    for (const std::string &id : removed.regressionComparisonIds) {
        g_regressionComparisonControllers.erase(id);
    }
    for (const std::string &id : removed.modelTrellisIds) {
        g_modelTrellisControllers.erase(id);
    }
    return true;
}

static void ClearWorkbenchStateUnlocked()
{
    MacPlotCoordinator().resetPlots();
    MacCommandDispatcher().applicationState().clearWorkbenchModels();
    g_variableControllers.clear();
    g_modelTrellisControllers.clear();
    g_glmControllers.clear();
    g_correlationMatrixControllers.clear();
    g_dimensionalityControllers.clear();
    g_scaleAnalysisControllers.clear();
    g_scaleAnalysisDerivedControllers.clear();
    g_dendrogramControllers.clear();
    g_generalizedGLMControllers.clear();
    g_table1Controllers.clear();
    g_generalizedComparisonControllers.clear();
    g_mixedModelControllers.clear();
    g_regressionComparisonControllers.clear();
    g_interactionReportWindows.clear();
    g_pendingInteractionReportJobs.clear();
    g_pendingInteractionPlotJobs.clear();
    g_pendingDimensionalityScoreSaveTasks.clear();
    g_pendingDimensionalityScoreSaveRequests.clear();
    g_pendingDimensionalityScoreSaveSources.clear();
}

